    [11] = {
        ["T"] = "갈퀴발 놀 현상금",
        ["O"] = "채색된 놀 완장 8개를 병영에 있는 부관 레이너에게 가져가십시오.",
        ["D"] =
        "이 땅에서 제대로 된 일을 할 리 없는 야만적인 생물인 놀들이 엘윈 숲 경계 주변에서 목격되었습니다. 우리만으로는 감당하기 벅찬 거대한 놀 무리가 저기 경비탑 남쪽 숲에 들끓고 있습니다. 또 다른 무리는 동쪽의 돌무덤 호수 근처 지역에 자리 잡았습니다.\n\n스톰윈드 군대는 이들을 처치하는 데 도움을 주는 자를 포상할 것입니다. 그들을 처치했다는 증거로 채색된 놀 완장을 가져오십시오.",
    },
