        ["D"] =
        "당신 덕분에 우리는 석영 광산에 코볼트가 들끓고 있다는 사실을 알게 되었습니다. 이제 더 멀리 있는 석영 광산을 조사할 정찰병이 필요합니다.\n\n석영 광산을 탐험하고 코볼트가 있는지 확인해 주십시오. 그곳에서 코볼트를 보게 되면 모두 처치하십시오. 광산에 가려면 아조라의 탑에 도달할 때까지 길을 따라 동쪽으로 이동하십시오. 탑에서 북쪽으로 향하면 산기슭에서 광산을 찾을 수 있습니다.",
