        ["D"] =
        "당신이 용아귀와 싸우는 동안 우리는 그들의 계획을 더 알아냈습니다.\n구제크가 투석기를 만들었고 메네실 항구를 포위하려 합니다! 게다가 던 알가즈에서의 전투 때문에 우리는 증원군과 완전히 차단되었습니다!\n당신이 그 투석기들을 파괴해야 합니다. 투석기들은 용아귀 야영지에 있습니다.\n자, 이 부시깃을 받으십시오. 투석기가 있는 곳까지 싸우며 나아가 이 부시깃으로 불을 붙이십시오.\n그 일을 마치면 구제크를 찾아 처치하십시오. 이 용아귀 짐승의 목을 쳐야 합니다.",
