        ["D"] =
        "다르나서스로 가는 길은 안전하게 유지되어야 합니다. 돌라나르에서 다르나서스로 향하는 여행자들이 타락한 펄볼그인 나무구렁 부족에게 무자비한 공격을 받고 있다고 보고했습니다.\n\n중요한 소식과 상거래가 매일 이 길을 통해 다르나서스를 오갑니다. 이단자 무리가 사람들을 위협하게 내버려 둘 수는 없습니다.\n\n신성한 숲의 이름으로 무기를 드십시오, 도적. 그들의 소굴은 이 고지대 아래 어딘가에 있습니다. 그들의 신성한 아뮬렛을 가져와 제게 보고하십시오.",
