        ["D"] =
        "당신이 제게 가져온 편지는 비밀결사대와 동맹을 맺은 아르거스 결사단 소속의 나가즈라는 자가 쓴 것입니다. 이 아르거스 결사단이 무엇인지는 모르겠지만, 그들이 비밀결사대와 동맹이라면 분명 위협이 될 것입니다.\n\n그 편지에 언급된 아르거스재림회 어둠마법사들을 찾아주셨으면 합니다. 그들을 찾아 처치해 주십시오. 이 나가즈라는 자의 정체나 이 결사단에 대해 알 수 있는 단서가 될 만한 물건이 있다면 제게 가져오십시오.\n\n스트란브래드와 그 북쪽의 고원지대를 수색해 보십시오. 운이 좋다면 아르거스 결사단의 사절들을 그곳에서 찾을 수 있을 것입니다.",
