        ["D"] =
        "$N, 제 오랜 친구 역시 이곳 잿빛 골짜기에서 파수꾼들을 돕고 있는데, 아직 돌아오지 않고 있습니다.\n그는 우리 동족에 대한 펄볼그의 공격을 늦출 수 있다고 생각하는 물건, 즉 지금은 죽은 사악한 마법사가 만든 막대를 찾을 단서를 쥐고 있었습니다.\n이곳을 떠나기 전, 그는 그 막대에 사용할 보석을 찾고 있다고 말했습니다.\n그는 서쪽 산기슭의 팔라딤 호수에 있는 성소에 그 보석이 숨겨져 있을 가능성이 있다고 언급했습니다. 그 성소가 점령당하기 전까지 보석이 보관되어 있던 곳이죠.\n제 친구를 찾아주십시오, $N.",
