        ["D"] =
        "오, 다시 바다로 나가고 싶군요! 바람의 입맞춤을 느끼고, 아주 오래전 축복받은 내 어머니처럼 파도가 나를 흔들어 주었으면!\n오, 당신의 행운이 제게도 있었으면 좋겠군요, 훌륭한 $c, 당신의 미래에서 바다가 보이니까요!\n제 일은 기회의 땅, 칼림도어에 대해 열정적인 영혼들에게 말해주는 것입니다! 바다 건너편에서 당신의 운을 시험해 볼 의향이 있다면, 여기서 배를 타고 아름다운 테라모어 항구로 가십시오. 그곳에서 제 파트너인 엘프 피오라 롱이어즈와 대화하십시오.\n그녀가 당신의 칼림도어 모험을 시작하게 해줄 것입니다!",
