        ["O"] = "타나리스의 가젯잔 안에 있는 먹스 마나스크램블러에게 봉인된 혈액 용기를 가져가십시오.",
        ["D"] =
        "그런 일을 겪고도 남아서 돕겠다니, 꽤 용기가 있으시군요. 아니면 제가 준 방어구 때문에 호기심이 생겼을 수도 있고요. 저를 계속 도울 의향이 있다면 그런 아이템은 더 있습니다.\n\n당신이 수집한 혈액 샘플은 제 지인인 초자연적인 현상에 관심이 많은 기계공학자, 먹스 마나스크램블러를 위한 것입니다. 그의 최신 프로젝트는 죽은 자와 대화할 수 있게 해주는 장치로 이루어져 있습니다! 제 마지막 희망은 안시온에게 연락하여 제 상황에 대해 더 알아보는 것입니다.",
    },
    [8924] = {
        ["T"] = "심령체 사냥",
        ["O"] =
        "실체가 없는 언데드 근처에서 심령체 추출기를 사용하여 아즈샤라에서 범람한 심령체 12개, 여명의 설원에서 얼어붙은 심령체 12개, 동부 역병지대에서 안정된 심령체 12개를 수집하십시오. 추출기와 함께 그것들을 가젯잔의 먹스 마나스크램블러에게 다시 가져가십시오.",
        ["D"] =
        "훌륭한 기계공학의 산물이군요, 제가 직접 말씀드리자면요! 우리가 필요로 하는 실체가 없는 언데드를 찾기 위해선 여행을 좀 하셔야 할 것 같습니다.\n\n아시겠지만, 다른 기후는 망자의 영적 직물에 다른 농도를 부여합니다. 익사한 지 오래된 아즈샤라의 나이트 엘프, 여명의 설원의 명가 영혼들, 그리고 동부 역병지대의 유령과 밴시들은 우리가 필요로 하는 다양한 종류의 심령체를 제공할 것입니다. 그것들을 수확하기 전에 추출기를 근처에 두는 것을 잊지 마십시오!",
    },
    [8925] = {
        ["T"] = "휴대용 동력원",
        ["O"] =
        "불타는 평원에서 용암 군주 보크를 찾아 용암 핵을 구한 다음, 가젯잔의 먹스 마나스크램블러에게 가져가십시오.",
        ["D"] =
        "다음으로 심령체를 활성 상태로 유지하기 위한 안정적이고 휴대 가능한 에너지를 찾아야 합니다. 강력한 용암 핵을 심장으로 가진 용암 군주 보크라는 강력한 정령에 대한 소문을 들었습니다 - 끝없는 열 공급원이죠!\n\n그는 검은바위 산 남쪽, 불타는 평원에서 찾을 수 있다고 합니다. 그 용암 핵을 내게 가져오면, 초차원 유령 탐지기에 동력을 공급할 충분한 에너지를 갖게 될 겁니다!",
    },
    [8926] = {
        ["T"] = "정당한 보상",
        ["O"] = "아이언포지의 델리아나에게 자연의정수 허리띠를 가져가십시오.",
        ["D"] =
        "당신은 약속을 지켰고 먹스가 만든 장치를 가져왔습니다. 제 목숨을 구하는 데 계속 흥미를 느끼게 하려면 보상이 필요할 거라 생각합니다. 업그레이드하고 싶은 허리띠와 장갑 세트를 제게 가져오십시오. 허리띠부터 시작하겠습니다. 보답으로 드리는 물건은 훨씬 더 뛰어날 것이라고 약속합니다.",
    },
    [8927] = {
        ["T"] = "정당한 보상",
        ["O"] = "오그리마의 모크바르에게 자연의정수 허리띠를 가져가십시오.",
        ["D"] =
        "당신은 매우 믿음직한 분임을 증명하셨습니다, $N. 당신이 이 곤경을 헤쳐나가도록 도와줄 것이라 믿는 만큼, 당신의 성과에 따라 보상하는 것이 현명한 처사일 것입니다.\n\n일단 당신의 허리띠와 장갑을 교환해 드리겠습니다. 허리띠부터 시작하죠. 우리 둘 다 이 일을 끝까지 해낸다면, 나머지 방어구들도 구할 수 있게 해 드리겠습니다.",
    },
    [8928] = {
        ["T"] = "교활한 상인",
        ["O"] =
        "여명의 설원 남쪽 검은속삭임 협곡 입구 동굴 안에서 임프를 찾아 악령의 제어봉을 구매한 후 가젯잔의 먹스 마나스크램블러에게 돌아가십시오.",
        ["D"] =
        "핵이 우리 장치에 동력을 공급할 충분한 에너지를 제공할 것입니다; 이제 그 에너지가 녹지 않고 흐르도록 막대를 만들어야 합니다.\n\n여명의 설원에서 온갖 희귀한 물건을 파는 임프를 만난 적이 있습니다. 완벽하게 작동할 정령 막대를 그가 가지고 있었죠. 그걸 사지 않은 걸 지금 머리를 쥐어박고 후회하고 있습니다.\n\n그는 검은속삭임 협곡 입구 동굴 안에 살고 있습니다. 거기로 몰래 숨어 들어가서 그를 찾아보십시오.\n\n그가 40골드만 청구하도록 단단히 확인하세요; 그게 나한테 말했던 가격이니까요!",
