        "당신은 매우 믿음직한 분임을 증명하셨습니다, $N. 당신이 이 곤경을 헤쳐나가도록 도와줄 것이라 믿는 만큼, 당신의 성과에 따라 보상하는 것이 현명한 처사일 것입니다.\n\n일단 당신의 허리띠와 장갑을 교환해 드리겠습니다. 우리 둘 다 이 일을 끝까지 해낸다면, 나머지 방어구들도 구할 수 있게 해 드리겠습니다.",
    },
    [8944] = {
        ["T"] = "정당한 보상",
        ["O"] = "오그리마의 모크바르에게 용맹의 허리띠를 가져가십시오.",
        ["D"] =
        "당신은 매우 믿음직한 분임을 증명하셨습니다, $N. 당신이 이 곤경을 헤쳐나가도록 도와줄 것이라 믿는 만큼, 당신의 성과에 따라 보상하는 것이 현명한 처사일 것입니다.\n\n일단 당신의 허리띠와 장갑을 교환해 드리겠습니다. 허리띠부터 시작하죠. 우리 둘 다 이 일을 끝까지 해낸다면, 나머지 방어구들도 구할 수 있게 해 드리겠습니다.",
    },
    [8945] = {
        ["T"] = "망자의 간청",
        ["O"] = "스트라솔름으로 들어가 남작 리븐데어로부터 이시다 하몬을 구출하십시오.",
        ["D"] =
        "당신이 요구하는 정보는 주겠소, $N. 하지만 지금 더 다급한 문제가 있소.\n\n사랑하는 내 아내가 리븐데어의 언데드 찌꺼기들에게 포로로 잡혀 있소.\n\n아내가 은빛 여명회 멍청이들의 성전에 동참하는 걸 극구 반대했건만, 이젠 그게 중요한 게 아니오. 내가 하려다 못한 일을 당신이 끝내야만 하오. 반드시 남작의 마수에서 이시자를 구출해야 하오!",
    },
    [8946] = {
        ["T"] = "생존의 증거",
        ["O"] = "동부 역병지대의 안시온 하몬에게 이시다의 로켓을 가져가십시오.",
        ["D"] =
        "저를 구하려다 사랑하는 남편이 죽었다니 가장 잔인한 운명이군요. 하지만, 당신은 남편과 대화할 능력이 있다고 하셨죠.\n\n이 로켓을 가져가서 제가 무사하다는 증거로 전해주세요. 그가 이 세상에 더 머물러선 안 됩니다. 제 심장이 견디지 못할 테니까요.\n\n안녕히, $N. 당신에게 평생 빚을 졌습니다.",
    },
    [8947] = {
        ["T"] = "안시온의 기이한 부탁",
        ["O"] =
        "검은무쇠 주괴 3개, 마력 깃든 가죽 20개, 달빛 옷감 3개, 거친 경화 가죽 4개를 동부 역병지대의 안시온 하몬에게 가져가십시오.",
        ["D"] =
        "우리는 발타라크의 메달의 중요성을 몰랐기 때문에, 다른 전리품들과 함께 그것도 나누어 가졌소. 첫 번째 조각은 텔드렌이라는 드워프가 가져갔지. 그에게서 조각을 되찾으려 했지만 녀석은 나를 반쯤 죽여놓았소. 아마 무력으로 그 파편을 빼앗아야 할 거요.\n\n마지막으로 들은 바로는 그가 검은무쇠 드워프들의 검투사가 되었다고 하더군. 그를 싸움에 끌어들이는 건 약간의 도전이 되겠지만 말이오.\n\n나를 위해 다음 재료들을 모아주시오. 그것들이 필요할 거요.",
    },
    [8948] = {
        ["T"] = "안시온의 옛 친구",
        ["O"] = "톨 바라드 감옥 안에 있는 팔린 트리셰이퍼에게 미완성된 도전의 깃발을 가져가십시오.",
        ["D"] =
        "텔드렌은 공정한 싸움에 자발적으로 참여할 위인이 아니오. 그래서 그의 가문 색상을 본떠 이 깃발을 만들었소.\n\n약간의 마법만 추가하면 이 깃발은 그가 저항할 수 없는 방식으로 그를 도발할 거요.\n\n팔린이라는 제 옛 지인이 그 정확한 방법을 알고 있소. 그는 사람의 화를 돋우는... 특이한 재주가 있지. 마지막으로 들었을 때 톨 바라드에 갇혀 있다고 했는데, 그게 문제가 되지 않길 바라오.",
    },
    [8949] = {
        ["T"] = "도발자의 마법부여 <미구현>",
        ["O"] = "톨 바라드에서 해적들의 매복 공격으로부터 팔린 트리셰이퍼를 방어한 후, 그와 다시 대화하십시오.",
        ["D"] =
        "그래, 네가 필요로 하는 마법에 익숙한 건 사실이야, $c. 안타깝게도 지금 내가 감방에 갇혀 있는 신세라 재료가 없거든. 네가 좀 가져다준다면 --\n\n조심해, 해적이다!",
    },
    [8950] = {
        ["T"] = "도발자의 마법부여",
        ["O"] =
        "톨 바라드의 바라딘 요새 안에 있는 팔린 트리셰이퍼에게 다음 물품들을 가져가십시오: 엘드레스 영혼의 정수 1개, 어둠의 룬 4개, 눈부신 큰 결정 8개.",
        ["D"] =
        "아까 하던 말을 계속하자면... 유감스럽게도 내겐 필요한 재료가 없어, 이런 종류의 부적을 찾는 사람은 드물거든.\n\n인간들이 여기에 가뒀던 언데드 중 하나의 정수, 스칼로맨스 어둠의 룬 몇 개, 눈부신 큰 결정들이 필요해. 이 재료들을 가져오면 네 부탁을 들어주지.",
    },
