        ["D"] =
        "그럼 메달의 나머지 부분을 찾아야겠군? 보들리를 찾는 건 좀 골치 아픈 일이 될 거요. 그는 검은바위 첨탑에 다시 들어가기 위해 검은바위 산으로 돌아간 뒤 영영 돌아오지 않았으니까.\n\n최악의 상황이 벌어졌을까 두려우니, 고블린의 초차원 유령 탐지기를 챙겨가는 걸 추천하겠소.",
