    [8961] = {
        ["T"] = "두 불꽃의 군주",
        ["O"] =
        "성스러운 화로와 함께 인센디우스의 발연석, 엠버시어의 불씨를 모아 검은바위 산 안에 있는 보들리에게 가져가십시오.",
        ["D"] =
        "군주 발타라크를 소환하려면 아뮬렛의 남은 두 조각을 모아야 합니다. 그러기 위해선 화로와 그 안에서 태울 특별한 석탄이 필요하죠.\n\n두 명의 불의 귀족이 있습니다. 검은바위 나락의 불의군주 인센디우스와 검은바위 첨탑의 불의수호자 엠버시어입니다. 우리가 필요한 건 그들이 가지고 있습니다. 두 명에게서 흔적을 하나씩 모은 다음, 성스러운 화로와 함께 제게 돌아오십시오. 화로는 은빛 여명회와 약간의 우호적 관계가 있다면 그들에게서 구입할 수 있습니다.",
    },
    [8962] = {
        ["T"] = "중요한 재료",
        ["O"] = "드루이드의 유골을 구해서 검은바위 산 안에 있는 보들리에게 가져가십시오.",
        ["D"] =
        "$C, 잘 들으십시오. 화로와 그것에 불을 붙일 수단은 구했지만, 그걸 채울 다른 구성 요소가 아직 필요합니다. 죽은 옛 동료의 영혼을 유혹할 만큼 강력한 초점이 될 무언가 말입니다.\n\n우리 중 가장 뛰어난 드루이드였던 모르 그레이후프는 세나리온 의회에 친한 친구가 많았습니다. 그는 그곳의 바위 거인들을 연구하기 위해 아즈샤라로 가는 원정대의 일원이었지만, 거인들이 너무 공격적이라 원정대 대부분이 목숨을 잃었죠. 아즈샤라 북동쪽에 있는 거인들에게서 드루이드의 유골을 가져다주셔야 합니다.",
    },
    [8963] = {
