        ["D"] =
        "$C, 잘 들으십시오. 화로와 그것에 불을 붙일 수단은 구했지만, 그걸 채울 다른 구성 요소가 아직 필요합니다. 죽은 옛 동료의 영혼을 유혹할 만큼 강력한 초점이 될 무언가 말입니다.\n\n우리 사제였던 이살리엔은 여명의 설원의 별바람 마을에서 자랐습니다. 당신이 여명의 설원 남쪽 서리속삭임 골짜기에 있는 서리망치 거인들에게서 별바람 마을 유물을 구해다 주셨으면 합니다. 그들은 종종 북쪽으로 약탈을 가는 것으로 알려져 있죠.",
