        ["D"] =
        "$C, 잘 들으십시오. 화로와 그것에 불을 붙일 수단은 구했지만, 그걸 채울 다른 구성 요소가 아직 필요합니다. 죽은 옛 동료의 영혼을 유혹할 만큼 강력한 초점이 될 무언가 말입니다.\n\n우리와 함께 다녔던 오우거 강령술사, 코르모크는 언덕마루 구릉지 남쪽 해안에 있는 속죄의 섬에서 추방된 자들의 영혼을 소환하는 걸 즐겼습니다. 그곳으로 가서 그들의 시체에서 추방자의 영혼 재를 좀 가져다주십시오.",
