        ["D"] =
        "내 친구 모르 그레이후프는 군주 발타라크의 아뮬렛의 한 조각과 그 안에 담긴 타락한 영혼 파편을 소유한 첫 번째 희생자였습니다. 발타라크의 주문서와 아뮬렛을 훔친 후, 우리는 검은바위 첨탑 상층에서 목숨을 걸고 도망쳤습니다. 도중에 모르는 첨탑 하층으로 떨어졌습니다.\n\n나중에 우리는 그가 추락에서 살아남았지만 대장군 부네에게 붙잡혀 고문당했다는 것을 알게 되었습니다. 몇 명의 유령 암살자가 몰래 잠입하여 부네 앞에서 바로 그를 죽여버렸죠.",
