        "이봐, 불량 연금술사의 소행은 내 알 바 아니야. 그가 우리의 계획을 방해하고 있다면 내가 먼저 올바른 방향을 알려주지.\n\n그가 결백하다면 숨길 게 없을 테니까, 그렇지?\n\n나는 연금술사 스태프론 리런트에게서 물건을 구입했어. 그는 언덕마루 너머 구릉지의 라벤홀트 장원을 지난 한적한 곳에서 일하고 있지. 솔직히 말해서 좀 이상한 사람이라고 생각했어.",
