    [8985] = {
        ["T"] = "더욱 중요한 재료",
        ["O"] = "별바람 마을 유물을 구해서 검은바위 산 안에 있는 보들리에게 가져가십시오.",
        ["D"] =
        "$C, 잘 들으십시오. 아뮬렛 마지막 조각의 위치는 알았지만, 여전히 화로를 채울 다른 구성 요소가 필요합니다. 죽은 옛 동료의 영혼을 유혹할 만큼 강력한 초점이 될 무언가 말입니다.\n\n우리 사제였던 이살리엔은 여명의 설원의 별바람 마을에서 자랐습니다. 당신이 여명의 설원 남쪽 서리속삭임 골짜기에 있는 서리망치 거인들에게서 별바람 마을 유물을 구해다 주셨으면 합니다. 그들은 종종 북쪽으로 약탈을 가는 것으로 알려져 있죠.",
    },
    [8986] = {
        ["T"] = "더욱 중요한 재료",
        ["O"] = "드루이드의 유골을 구해서 검은바위 산 안에 있는 보들리에게 가져가십시오.",
        ["D"] =
        "$C, 잘 들으십시오. 아뮬렛 마지막 조각의 위치는 알았지만, 여전히 화로를 채울 다른 구성 요소가 필요합니다. 죽은 옛 동료의 영혼을 유혹할 만큼 강력한 초점이 될 무언가 말입니다.\n\n우리 중 가장 뛰어난 드루이드였던 모르 그레이후프는 세나리온 의회에 친한 친구가 많았습니다. 그는 그곳의 바위 거인들을 연구하기 위해 아즈샤라로 가는 원정대의 일원이었지만, 거인들이 너무 공격적이라 원정대 대부분이 목숨을 잃었죠. 아즈샤라 북동쪽에 있는 거인들에게서 드루이드의 유골을 가져다주셔야 합니다.",
    },
    [8987] = {
        ["T"] = "더욱 중요한 재료",
        ["O"] = "번쩍이는 열광의 검을 되찾아 검은바위 산 안에 있는 보들리에게 가져가십시오.",
        ["D"] =
        "$C, 잘 들으십시오. 아뮬렛 마지막 조각의 위치는 알았지만, 여전히 화로를 채울 다른 구성 요소가 필요합니다. 죽은 옛 동료의 잔해를 소환할 만큼 강력한 초점이 될 무언가 말입니다.\n\n자리엔과 소도스 남매는 붉은십자군의 길을 신봉했습니다. 그 사악한 조직 안에서 기사 작위를 얻고자 했죠. 동부 역병지대에 있는 티르의 손 수도원으로 가서 그곳의 근위병들에게서 번쩍이는 열광의 검을 되찾아 오십시오.\n",
    },
    [8988] = {
        ["T"] = "더욱 중요한 재료",
        ["O"] = "추방자의 영혼 재를 구해서 검은바위 산 안에 있는 보들리에게 가져가십시오.",
        ["D"] =
        "$C, 잘 들으십시오. 아뮬렛 마지막 조각의 위치는 알았지만, 여전히 화로를 채울 다른 구성 요소가 필요합니다. 죽은 옛 동료의 영혼을 유혹할 만큼 강력한 초점이 될 무언가 말입니다.\n\n우리와 함께 다녔던 오우거 강령술사, 코르모크는 언덕마루 구릉지 남쪽 해안에 있는 속죄의 섬에서 추방된 자들의 영혼을 소환하는 걸 즐겼습니다. 그곳으로 가서 그들의 시체에서 추방자의 영혼 재를 좀 가져다주십시오.",
