        "부름의 화로를 사용하여 이살리엔의 영혼을 불러내어 그녀를 처치하십시오. 합쳐진 군주 발타라크의 아뮬렛과 부름의 화로를 들고 검은바위 산 안에 있는 보들리에게 돌아가십시오.",
        ["D"] =
        "나중에, 우리가 살기 위해 할 수 있는 일을 하던 시절, 우리 일행의 나이트 엘프 사제인 이살리엔이 수감된 친구 팔린 트리셰이퍼를 방문하기 위해 인간의 감옥인 톨 바라드에 갔다는 사실이 알려졌습니다.\n\n하지만 그녀는 목표를 달성하지 못했습니다. 소문에 따르면 그녀는 의심할 여지 없이 군주 발타라크가 보낸 유령 암살자들에게 대기실에서 매복을 당했다고 합니다. 그 대기실은 지금 강력한 마법사를 가두는 데 사용되고 있습니다.",
