        "부름의 화로를 사용하여 자리엔과 소도스를 불러내어 그들을 처치하십시오. 합쳐진 군주 발타라크의 아뮬렛과 부름의 화로를 들고 검은바위 산 안에 있는 보들리에게 돌아가십시오.",
        ["D"] =
        "자리엔과 소도스 남매는 용병단이 해체되자 붉은십자군에 합류하기로 결정했습니다. 그들은 군주 발타라크의 아뮬렛 오른쪽 조각을 가져갔습니다. 속이 다 시원하지만, 우린 그 조각을 되찾아야 합니다.\n\n우리가 알아낸 바로는 붉은십자군 요새의 방에서 열린 입단 의식에서 실패하여 십자군 사령관 다스로한에게 죽임을 당했다고 합니다.\n\n어쨌든, 우리는... 그러니까 당신은 여전히 아뮬렛의 그 조각을 되찾아야 합니다.",
