        ["O"] =
        "부름의 화로를 사용하여 코르모크의 영혼을 불러내어 그를 처치하십시오. 합쳐진 군주 발타라크의 아뮬렛과 부름의 화로를 들고 검은바위 산 안에 있는 보들리에게 돌아가십시오.",
        ["D"] =
        "이제 필요한 걸 다 갖췄으니, 다음으로 누굴 소환할지 이야기해 볼 차례입니다.\n\n코르모크는 강령술에 손을 대기 전까지는 괜찮은 오우거였습니다. 그 후에는 조직의 거의 모든 사람에게 섬뜩한 존재가 되었죠. 그래서 그가 아뮬렛 조각을 챙겨 새 고향인 스칼로맨스로 돌아갔을 때 별로 놀랍지 않았습니다.\n\n하지만 그곳에서조차, 아니 그곳이기에 더욱 유령 암살자들로부터 안전하지 못했습니다. 그들은 코르모크의 주인인 라스 프로스트위스퍼가 보는 앞에서 그를 살해했습니다.",
