        ["D"] =
        "이제 모든 준비가 끝났습니다, $N.\n\n생전에 군주 발타라크는 지금의 괴수의 방에 살았습니다. 그곳으로 가서 부름의 화로를 사용해 군주 발타라크를 불러내십시오. 그가 육신을 갖게 될 테니, 다시 한 번 죽여야 할 겁니다. 나라면 괴수를 먼저 처리하고, 검은바위 첨탑 상층에서 살아남을 수 있도록 동료를 충분히 데려갈 것입니다.\n\n발타라크를 처치하면 그의 시체에 아뮬렛을 사용하십시오. 영혼이 다시 하나로 뭉쳐지면 그 역시 자신의 아뮬렛을 돌려받고 싶어 할 겁니다.\n\n행운을 빕니다!",
