        ["D"] =
        "이번에는 네 무례함을 눈감아주마, $c. 네가 오늘 도둑맞은 내 영혼의 나머지를 내게 돌려주는 고귀한 일을 했기 때문이다. 네 명백히 나약한 본성에도 불구하고, $r, 넌 나에게서 물건을 훔친 자들이 보이지 못했고 앞으로도 보여주지 못할 용기를 보여주었다!\n\n내가 마음을 바꿔 널 당장 죽여버리기 전에 돌아가라. 돌아가서 당분간은... 안전하다고 전해라.",
