    [9609] = {
        ["T"] = "감시자 빅스 돕기",
        ["O"] = "슬픔의 늪에서 감시자 빅스를 찾으십시오.",
        ["D"] =
        "막투르가 근처에 좌초된 감시자가 있다고 내게 알려주었네. 듣자 하니 다크샤이어에서 그가 호위하던 마차가 드레노어 난민들의 공격을 받았다는군. 그가 유일한 생존자인 것 같아.\n그는 남쪽 어딘가에 있네. 부탁이네, $c, 그를 좀 도와주게.",
    },
    [9610] = {
        ["T"] = "눈물의 연못",
        ["O"] = "아탈아이 유물 10개를 얻어 슬픔의 늪의 피난처에 있는 핀미르에게 돌아가십시오.",
        ["D"] =
        "나는 아제로스의 과거를 연구하는 데 관심이 있는데 당신이 나를 기꺼이 도와줄 의향이 있는지 궁금하군요.\n이 늪지대에는 역사적으로 중요한 의미가 있는 장소가 근처에 있어 당신이 그곳으로 탐험을 떠나주었으면 합니다. 눈물의 연못이 남동쪽에 있습니다. 그곳의 해안과 깊은 물속에는 아탈아이 트롤 문명의 유물들이 묻혀 있다고 전해집니다.\n하지만 조심하십시오, 그곳은 고대 녹색용 솜누스와 그의 용혈족, 그리고 연못 자체에 사는 육식성 물고기들이 지키고 있습니다!",
    },
    [11160] = {
        ["T"] = "돌망치의 깃발",
        ["O"] = "돌망치일족 깃발을 회수하여 브록의 굴에 있는 브록에게 가져가십시오.",
        ["D"] =
        "용들이 쳐들어와 브록의 옛 고향을 빼앗았을 때, 돌망치 오우거들은 도망치며 부족의 깃발을 포함한 모든 것을 버려두고 왔어.\n브록은 깃발이 돌망치 오우거 소굴 깊은 곳에 보관되어 있었다는 걸 알지만, 요즘 그곳은 불꽃의 둥지라고 불려. 브록은 그의 친구들을 죽인 용들에게 복수하기 위해 반드시 부족 깃발을 가져야 해.\n브록의 부족의 옛 소굴, 불꽃의 둥지는 내 소굴 북쪽에 있고 용혈족이 들끓고 있어. 깃발은 동굴 깊숙한 곳에 있을 거야. 조심해, $N.",
    },
    [14087] = {
        ["T"] = "멀고어에서 타기 배우기",
        ["O"] = "안내서를 멀고어의 블러드후프 마을에 있는 카르 스톰싱어에게 돌려주십시오.",
        ["D"] =
        "타기 훈련과 탈것 판매를 홍보하는 이 안내서는 카르 스톰싱어가 보낸 것입니다.\n\n카르는 멀고어의 블러드후프 마을에서 찾을 수 있습니다.",
    },
    [26100] = {
        ["T"] = "도시의 악어들",
        ["O"] = "오그리마 안에서 새끼 악어를 모아 아즈샤라의 검은아귀 마을에 있는 노인 발로에게 돌아가십시오.",
        ["D"] =
        "안녕하신가 $C. 이 늙은이와 이야기하러 들러줘서 기뻐 -- 고향에 문제가 생겼거든.\n\n최근 지나가던 상인이 속기 쉬운 아이들에게 새끼 악어 한 무리를 팔았어. 악어는 야생의 짐승이라, 다수가 탈출해서 지금은 도시 수로에 숨어 있지.\n\n가장 튼튼한 낚싯대를 챙겨서 아무 대도시나 낚시줄을 던진 다음, 그 꼬마 악마들 중 하나를 내게 가져다주게. 난 그놈들 중 하나가 몹시 보고 싶어.",
    },
    [26101] = {
        ["T"] = "달숲의 달빛물고기",
        ["O"] = "달숲 안에서 달빛물고기 10마리를 모아 아즈샤라의 검은아귀 마을에 있는 위플라에게 돌아가십시오.",
        ["D"] =
        "편안하게 낚시할 곳을 찾는다면 달숲만 한 곳이 없지. 칼림도어에서 그곳보다 고요한 물은 찾을 수 없을 거야.\n\n내가 진 내기 때문에 내 친구 위플라에게 물고기를 좀 줘야 하는데, 달숲으로 올라갈 시간이 없군. 어쩌면 네가 나 대신 그 물고기들을 낚아주는 데 관심이 있을까? 이 늙은이에게 큰 은혜를 베푸는 걸 텐데.",
    },
    [26102] = {
        ["T"] = "강물 속의 유령들",
        ["O"] = "저승바람 고개 안에서 유령 환영물고기를 모아 아즈샤라의 검은아귀 마을에 있는 오르수하에게 돌아가십시오.",
        ["D"] =
        "왕년에 오래된 카라잔 주변에서의 낚시는 풍성하고 훌륭했지. 그러다 군단과 악마들, 그리고 메디브가 사라지는 등 모든 불쾌한 일들이 벌어졌어. 그곳은 이 늙은 뼈마디를 떨리게 만들어.\n\n내 친구 오르수하는 네가 아직 그곳에서 낚시를 할 수 있는지 궁금해했어. 난 무서웠다고 솔직히 말하기엔 너무 부끄러워서, 한번 해보겠다고 동의했지. 하지만 도저히 그쪽으로 발길이 떨어지지가 않아 -- 대부분의 낚시꾼이 그렇듯 미신을 믿거든.\n\n아무래도 네가 그곳을 확인하고 그를 위해 뭐라도 낚이는 걸 가져와 줄 수 있을까?",
    },
    [26103] = {
        ["T"] = "얼어붙은 보급품",
        ["O"] = "여명의 설원 안에서 얼어붙은 방울 10개를 모아 아즈샤라의 검은아귀 마을에 있는 위플라에게 돌아가십시오.",
        ["D"] =
        "있지, 낚시는 단순히 다음 끼니를 잡는 것보다 훨씬 많은 일에 도움이 돼. 무더운 여름날에도 네게 도움이 될 수 있지.\n\n여명의 설원의 바다를 예로 들어보지 -- 며칠 동안이나 녹지 않을 정도로 아주 꽁꽁 얼어붙은 커다란 얼음 덩어리들을 낚을 수 있어. 생선을 보관해서 운반하거나, 널 이상하게 쳐다보는 놈한테 던지기에 아주 좋지.\n\n사실, 내 얼음이 거의 다 떨어졌어. 우리 보급품을 다시 채워줄 의향이 있나? 다 끝나면 위플라에게 가져가게.",
    },
    [26104] = {
        ["T"] = "순수 미술 낚시",
        ["O"] = "동부 역병지대 안에서 훌륭한 풍경화 한 폭을 모아 아즈샤라의 검은아귀 마을에 있는 오르수하에게 돌아가십시오.",
        ["D"] =
        "있지, 세상에는 강이나 호수, 바다로 흘러 들어가는 물건들이 많아. 그중 일부는 심지어 가치가 있기도 하지!\n\n예를 들어, 지금은 동부 역병지대인 곳의 브라우만 제분소에서 나왔던 공예품과 예술 작품들 말이야. 오르수하가 좋아할 만한 화려한 풍경화나 고급 목조 조각상 같은 정말 사랑스러운 작품들이 있었어. 어쩌면 그 호수들의 잔해 속에 그런 게 떠내려왔을지도 모르지. 한 번 찾아볼 만한 가치가 있지 않아?",
    },
    [26105] = {
        ["T"] = "끈질긴 텀프피시",
        ["O"] = "서부 역병지대 안에서 텀프피시 10마리를 모아 아즈샤라의 검은아귀 마을에 있는 위플라에게 돌아가십시오.",
        ["D"] =
        "지금의 서부 역병지대에 있는 다로우미어 호수로 흘러 들어가는 토리달 강은 항상 낚시하기 힘든 곳이었어. 지금은 이 늙은 뼈다귀가 감당하기엔 너무 험난하지, 그건 확실해.\n\n만약 도전을 찾고 있다면, 그 물에서 텀프피시를 한 마리 낚을 수 있을 거야. 난 위플라가 아주 감명받을 거라 확신해. 단지, 호수에 있는 그 트레샤돈들을 조심해. 난 그놈들이 지금 전부 역병에 걸렸다고 들었거든.",
    },
    [26106] = {
        ["T"] = "용암 내성 바닷가재",
        ["O"] = "불타는 평원 안에서 용암 내성 바닷가재 10마리를 모아 아즈샤라의 검은아귀 마을에 있는 오르수하에게 돌아가십시오.",
        ["D"] =
        "아아 불타는 평원... 유황과 맥주 냄새. 낚싯대와 릴을 챙겨 떠나고 싶어지는 최고의 기분을 선사하지. 그곳엔 오직 용암뿐이지만, 여전히 진수성찬을 낚을 수 있어. 난 지금 저 유명한 용암 내성 바닷가재에 대해 말하는 거야. 껍질은 못만큼 단단하고 불에 대한 저항력이 있지만, 그걸 제거하고 나면, 오! 그 안의 맵고 스모키한 풍미는 비할 데가 없지.\n\n오르수하에게는 그놈들 껍질을 깔 집게발이 있으니까, 함께 나눌 만큼 충분히 잡았다면 그에게 가져가게.",
    },
    [26107] = {
        ["T"] = "오 드 파르피시",
        ["O"] = "악령숲 안에서 향기로운 지옥물고기를 모아 아즈샤라의 검은아귀 마을에 있는 위플라에게 돌아가십시오.",
        ["D"] =
        "난 절대 유행을 이해하지 못할 거야, $N. 특히 펄볼그 유행은 더욱. 위플라가 말하길 검은아귀 부족은 예전에 악령숲에서 구했던 물고기로 향수를 만든다더군. 냄새나는군!\n\n하지만 우리 털복숭이 친구들에게 그것이 중요하다면, 내게도 중요해. 수로가 지옥 마법에 타락한 이후에도 이 향기로운 짐승을 여전히 구할 수 있는지 확인해 보고 싶어. 한번 해 볼 텐가?",
    },
    [26108] = {
        ["T"] = "길들여지지 않은 운고로",
        ["O"] = "운고로 분화구 안에서 척추이빨 화염물고기 10마리를 모아 아즈샤라의 검은아귀 마을에 있는 오르수하에게 돌아가십시오.",
        ["D"] =
        "내가 낚시를 안 해본 곳은 세상에 몇 군데 없지만 그중 하나가 바로 야생의 운고로 분화구야. 이 늙은 뼈다귀가 아래로 내려갈 수만 있었다면, 난 기꺼이 길들여지지 않은 분화구의 물에서 내 릴을 감았을 텐데. 슬프게도, 너 같은 젊은이들에게 의지할 수밖에 없구나.\n\n오르수하는 이국적인 생선 요리에 아주 뛰어나지. 어쩌면 네가 열 마리만 가져와 주면 우리 모두 너를 통해 대리 만족하며 포식할 수 있지 않을까?",
