    [26109] = {
        ["T"] = "오크와 남획",
        ["O"] = "저주받은 땅 안에서 오렌지 러피 10마리를 모아 아즈샤라의 검은아귀 마을에 있는 위플라에게 돌아가십시오.",
        ["D"] =
        "저주받은 땅의 펠스톤 요새에 들끓는 군단 충성파 오크들이 만족을 모르는 악마 군대를 먹여 살리려고 인근 해안의 씨가 마르도록 낚시를 하고 있어. 우리는 그 해안에 서식하는 사랑스러운 오렌지 러피를 보호하기 위해 행동해야만 해!\n\n열 마리를 낚아서 위플라에게 다시 가져가게. 그녀는 여기서 놈들이 평화롭게 살 수 있도록 보장할 테니까, 언젠가 저 오크놈들이 소탕되고 나면 더 많은 개체 수를 자연으로 돌려보낼 수 있을 거야.",
    },
    [26110] = {
        ["T"] = "그중 가장 희귀한 것",
        ["O"] = "아즈샤라 안에서 사파이어 다터를 모아 아즈샤라의 검은아귀 마을에 있는 오르수하에게 돌아가십시오.",
        ["D"] =
        "아아, 아즈샤라. 내게는 제2의 고향이자, 내 친구들에게는 고향 그 자체지. 여기엔 낚시할 곳이 아주 많아서 언제나 새로운 낚시 명소를 찾을 수 있어.\n\n난 다른 어떤 곳보다 아즈샤라에서 낚시를 하며 많은 시간을 보냈지만 여전히 내게 잡히지 않는 물고기가 하나 있지. 바로 사파이어 다터야. 펄볼그들이 이 물고기를 잡으면 스튜 냄비가 아니라 트로피 벽에 장식할 정도라니까! 네가 직접 한 마리 잡아보는 게 어때. 어디에든 있을 수 있어...!",
    },
    [26111] = {
