        ["D"] =
        "오 맙소사 $C, 내가 지금 제정신이 아니야. 이글거리는 협곡의 용암 웅덩이로 여행을 갔다가 방금 막 돌아왔는데 내 행운의 회중시계를 찾을 수가 없어!\n\n이 늙은 뼈다귀는 다시 길을 나서기 전에 잠깐 쉬어야 하지만, 너무 오래 기다리면 마법이 다 풀려서 용암이 내 시계를 녹여 액체 반죽으로 만들어버릴 거야. 어쩌면 네가 그곳으로 훌쩍 넘어가서 날 위해 그걸 낚아줄 수 있지 않을까? 네가 그걸 되가져올 수 있다면 위플라가 깨끗하게 닦아줄 텐데.",
