        ["D"] =
        "안제와타의 트롤들은 민물 숭어와 바다 농어를 교배시켜 공용어로 '긴 숭어'라 불리는 새로운 어종의 '랑과'를 만들어냈어. 우리가 그걸 맛본 지도 꽤 시간이 지났군. 타나리스로 내려가서 네가 뭘 낚을 수 있는지 한 번 보지 그래?",
