        ["D"] =
        "앉아봐 $C, 내가 이야기 하나 해줄게.\n\n옛날 옛적에 동부 내륙지에 낚시할 줄 모르는 하이 엘프들이 살고 있었어. 음, 난 그곳의 마른나무껍질 트롤들과 약간의 마찰이 있었지만 자세한 이야기는 하지 않을게. 하지만 날 구해준 대가로 난 그들에게 낚시하는 법을 가르쳐주었고 그들은 그걸 아주 좋아했지! 적어도 나한테는 그렇게 말했어.\n\n나중에 알고 보니 그들은 내 비위를 맞추고 있었던 거야. 그 후로는 그곳에 발길을 끊었지만, 네가 그곳으로 향하는 걸 개의치 않는다면 위플라가 황금비늘농어 무리를 갈망하고 있어.",
