        ["D"] =
        "이봐, $C! 내 늙은 뼈마디가 지나간 낚시의 나날들에 대한 이야기로 삐걱대고 있어, 그리고 네게 제안할 게 하나 있지. 슬픔의 늪의 탁한 물에는 위플라가 좋아하는 온갖 미끈거리는 생물들이 우글거려. 난 지금이야말로 우리가 낚싯줄을 던지고 뭘 낚아 올릴 수 있을지 볼 때라고 생각해. 하지만 조심해, 늪은 그저 물고기들의 집이기만 한 게 아니니까. 저 탁한 심연 아래엔 위험이 도사리고 있으니, 항상 정신을 똑바로 차려.",
