        ["D"] =
        "넌 필시 황야의 땅이라는 이름 때문에 낚시하기에 안 좋을 거라고 생각하겠지. 그리고 고블린놈들이 스프링소켓에 자리를 잡기 전이라면 네 생각이 맞았을 거야. 알고 보니 사막 아래에 물이 있었고, 그 안에 물고기가 살고 있었어!\n\n그곳에 방문해보지 않았다면 넌 아주 훌륭한 낚시 기회를 놓치고 있는 거야! 그래, 어때? 낚싯줄을 던지고 무엇이 미끼를 무는지 확인할 준비가 되었나?",
