        ["D"] =
        "들어봐 $C, 내 생각에 너라면 낚시꾼이 노릴 수 있는 가장 힘든 과제 중 하나인 상어 낚시를 해낼 만한 배짱과 기개가 있는 것 같아.\n\n맞아, 먼지진흙 습지대의 탁한 심연에는 낚이기를 기다리는 상어들이 널려 있지. 놈들은 크고, 사납고, 네가 금방 잊지 못할 싸움을 선사할 거야. 심연의 턱과 씨름할 준비가 되어 있다고 생각하나?",
