        ["D"] =
        "안녕하신가, $R! 줄무늬물구나무서기에 대해 들어본 적 있나? 그 화려한 지느러미로 다른 물고기들의 질투를 사는 물고기지. 자, 난 예전만큼 날렵하지 못하고, 내 태클 박스도 휴식이 필요해서 이 임무를 자네에게 넘기려고 하네. 가시덤불 골짜기로 가서 이 미끌거리는 악마 10마리를 낚아 올려. 녀석들은 정글의 수중 패션쇼나 다름없다니까!\n\n하지만 여기서 중요한 게 있어. 잡고 나면 위플라를 찾아가게. 그녀에게 이 화려한 물고기들을 보여주고, 녀석들이 아제로스 수중 무리의 최고봉이라고 말해. 누가 알아, 어쩌면 우리가 펄볼그들에게 낚시에 대해 한 수 가르쳐줄지도 모르고, 그걸 하면서 멋진 시간을 보낼 수 있을지도! 자, 어서 가서 사탕 가게에 간 노움만큼이나 줄무늬물구나무서기들이 잘 협조해 주기를 바라게!",
