        ["D"] =
        "있지, $N, 자네는 훌륭한 $g어부:어부;의 자질을 갖추고 있어. 게다가 최고의 안목까지 겸비하고 있지!\n\n최고의 해산물을 찾고 있다면 잊혀진 땅의 해안만한 곳이 없지. 농어만큼이나 쉽게 조개를 잡을 수 있거든. 그 고독한 조개들은 정말 이상한 생물이야. 위플라가 정말 고마워할 테니 조개를 좀 갖다주지 않겠나?",
