        ["D"] =
        "만나서 반갑네 $C. 만약 자네가 평화롭고 조용한 곳을 갈망한다면, 아라시 고원을 확인해 보는 게 좋을 거야. 두 대양에서 불과 조금 떨어진 곳에서 낚시를 할 수 있는 몇 안 되는 장소 중 하나니까!\n\n그 고요한 풍경에 속지 말게나. 이곳의 낚시는 말 그대로 자네를 물어뜯을 테니까! 날카로운이빨 스트롬피시를 조심하게. 녀석들이 있는 웅덩이에 서 있으면 다리를 물어뜯길 거야. 다행히도 녀석들은 혼자 다니기 때문에, 그런 일은 드물게 일어나지. 오르수하에게 그 표본을 하나 가져다줄 수 있겠나?",
