        ["D"] =
        "버섯구름 봉우리에서는 물을 많이 찾을 수 없을 거야 $C. 사실, 내가 아는 유일한 장소인 그림토템 초소 밑의 증기 웅덩이에선 아예 낚싯줄을 드리울 생각도 안 해봤지.\n\n네가 그곳에서 무엇을 찾을지 호기심이 생기는군. 어떤 친구를 놓치게 만들었던 희끗희끗한 장어에 대한 허풍을 들은 적이 있거든. 아마 존재하지 않겠지만, 알아보고 싶지 않나? 네가 뭘 가지고 돌아오든 위플라가 박제로 만들어 줄 거야.",
