        ["D"] =
        "난 예전에 저습지에서 많은 시간을 보냈어. 그곳에는 모든 종류의 낚싯감이 풍부했거든. 연못, 호수, 강, 늪, 바다, 네가 이름만 대면 낚시할 수 있는 곳이었지. 그곳에서 하도 오랜 시간을 보내서 내가 가장 좋아하던 미끼까지 두고 왔을 정도야.\n\n이봐, 언젠가 그곳에 가게 된다면 내 미끼를 한 번 찾아봐 주지 않겠어? 오르수하는 미끼를 수리하는 데 아주 능숙해서, 네가 그걸 발견하기만 한다면 그가 수리하는 걸 도와줄 거야.",
