        ["D"] =
        "언덕마루 구릉지의 남쪽 해안을 따라 정말 많은 멀록들이 있어. 남녘해안에서 낚시를 하다가 멀록들이 남긴 고기 부스러기를 훔쳐먹길 기대하며 녀석들 주위를 맴도는 특정한 머드킵이 있다는 걸 눈치챘지. 그 머드킵들은 꽤 맛이 좋은데, 지금 이곳의 우리 식량은 몹시 부족해 보여.\n\n물론 언덕마루 어디에서나 머드킵을 찾을 수 있지만, 내가 아는 건 여기까지야. 어떻게 생각해, 네 낚싯대와 릴을 드리워 우리에게 진수성찬을 가져다주지 않겠나?",
