        ["O"] = "잿빛 골짜기 안에서 날개꼬리 다터 10마리를 모아 아즈샤라의 검은아귀 마을에 있는 오르수하에게 돌아가십시오.",
        ["D"] =
        "신록이 우거진 아름다운 잿빛 골짜기는 세상의 혼돈으로부터 위안을 찾는 이들에게 완벽한 고요한 휴식처지. 이 고요함 속에는 잡히기를 기다리는 풍부한 물고기들이 있어. 잿빛 골짜기의 강과 호수에는 생명이 넘쳐나니, 이제 낚싯줄을 던지고 자연이 주는 풍요로움을 누릴 때야.\n\n내가 말하는 건 나이트 엘프들의 자랑거리이자, 오르수하가 가장 좋아하는 물고기인 날개꼬리 달다터야! 보름달이 가장 밝게 떴을 때 네가 자리잡은 횃대 밑으로 재빠르게 지나가는 달다터 떼에 비할 것은 아무것도 없어, 정말이야. 우릴 위해 좀 낚아다 준다면 고맙겠어!",
    },
    [26125] = {
        ["T"] = "돌고기 수프",
        ["O"] = "돌발톱 산맥 안에서 돌가죽 피라미 10마리를 모아 아즈샤라의 검은아귀 마을에 있는 위플라에게 돌아가십시오.",
        ["D"] =
        "안녕하신가 $C, 만약 돌발톱 산맥의 험준한 봉우리와 구불구불한 협곡 속에서 평화를 찾고 있다면, 내게 딱 맞는 해결책이 있지. 위플라가 새로 시도해보고 싶어하는 돌고기 수프 조리법이 있는데, 주재료가 필요하거든. 돌발톱 산맥에서만 발견되는 돌가죽 피라미 말이야. 비늘이 못만큼 단단할지는 몰라도, 채찍뿌리와 독특한 양념을 넣고 끓이면 아주 훌륭한 요리가 되지.\n\n그곳으로 향해서 쓸만한 물고기들을 많이 가져와 주겠나?",
    },
    [26126] = {
        ["T"] = "스프링소켓 장어",
