        ["D"] =
        "믿거나 말거나, 스프링소켓에는 아주 꽤 활발한 낚시 문화가 존재한답니다! 비록 이 스포츠에 실제로 참여하는 사람은 저뿐이지만, 조만간 다른 사람들도 관심을 갖게 될 거라고 믿어 의심치 않아요. 어쨌든, 당신이 기꺼이 나설 의향이 있다면 당신에게 도전 과제를 드리죠.\n\n이 연못은 깊은 지하의 자연 동굴 시스템에서 물을 끌어올려요. 그곳의 물고기들은 눈이 멀어 있고, 가끔 위로 헤엄쳐 올라와 수면으로 길을 찾기도 하죠. 저도 여기저기서 몇 마리 잡아본 게 다지만, 그건 제가 지금까지 먹어본 물고기 중 가장 맛있는 물고기였어요!\n\n당신도 낚시에 한번 도전해 보고, 몇 마리 잡을 수 있는지 보세요. 운이 좋아서 잡게 되면 제게 가져오세요. 요리하는 법을 가르쳐 드릴게요.",
