        "당신에게 줄 인양 작업이 하나 있는데, 나처럼 훌륭한 리플 애호가라면 이 일이 무척 마음에 들 거요.\n\n리플! 마실 것 말이오, 이 바보야.\n\n이곳에 무슨 물건이 있든 상관없이 젊은이들은 그저 조금... 다른 걸 원한단 말이오. 문화가 있는 무언가를 말이오. 버려진 호드 전초기지에는 녀석들이 한창 영업하던 시절에 남겨둔 동부내륙지 벌꿀 리플이 숨겨져 있소. 그런 고급 리플은 이제 구할 수조차 없다고! 굼벵이 바위굴 근처에서 발견되는 상자들에서 그 리플을 인양할 수 있소.\n\n이 폐허에는 더러운 점액과 수액 괴물들이 가득해서 고된 일이 될 거요. 소문에 따르면 어떤 우두머리 수액 괴물이 이들을 이끌고 있다고 하더군. 어쨌든, 리플을 구해서 여기 있는 내게 돌아오시오.",
    },
    [26168] = {
        ["T"] = "오믈렛을 만들려면...",
        ["O"] = "샤드라알로르에서 샤드라의 후예 알 10개를 모아 맹금의 봉우리의 케르 아이언사이트에게 돌아가십시오.",
        ["D"] =
        "남동쪽에 있는 마른나무껍질 트롤 놈들이 샤드라의 새끼 알들을 돌보고 있어. 우리가 마른나무껍질을 모조리 죽여버린다 해도, 그 알들은 부화하기만을 기다리며 야생에 그 끔찍한 생물들을 풀어놓을 준비를 하고 있을 거란 말이지.\n\n우린 이 위협을 확실하게 처리해야만 해. 알주머니에서 알이 보이면 찢어발기고 몽땅 내게 가져오도록. 혼자서 파괴하려 들진 마; 그러다간 작은 놈들이 튀어나올 수도 있으니까.\n\n알들을 여기로 가져오면 내가 확실하게 처리하도록 하지!",
    },
    [26169] = {
        ["T"] = "오믈렛을 만들려면...",
        ["O"] = "샤드라알로르에서 샤드라의 후예 알 12개를 모아 깨진엄니 마을의 주술사 쏜터스크에게 돌아가십시오.",
        ["D"] =
        "서쪽에 있는 마른나무껍질 놈들이 샤드라의 후예 알을 돌보고 있어. 우리가 마른나무껍질을 죽인다 하더라도 알은 부화해서 야생에 끔찍한 괴물들을 풀어놓기 위해 기다리고 있을 거야.\n\n이걸 제대로 처리해야만 해. 알주머니에서 알을 찢어내 내게 가져와. 혼자서 부수려고 하지 마. 작은 놈들이 빠져나올 수도 있으니까. 네가 알을 이곳으로 가져오면 내가 잘 처리해 주겠어!",
