    [26170] = {
        ["T"] = "해안 청소",
        ["O"] = "동부 내륙지의 해안을 따라 짠물 해안 물고기 10마리를 처치하십시오.",
        ["D"] =
        "이봐 친구, 마을 주변 낚시터 물고기들이 점점 씨가 마르고 있는데, 난 그 이유를 알고 있어. 바로 저주받은 짠물 해안 물고기 놈들 때문이지. 나를 위해 아주 간단한 일을 하나 해줄 용감한 모험가가 필요해... 가능한 한 많은 놈들을 처치해 달라고. 해낼 수 있겠어?",
    },
    [26171] = {
        ["T"] = "떨어지면 감사",
        ["O"] = "샤드라알로르 내의 마른나무껍질에게서 마른나무껍질 숄 조각 8개와 완벽한 무리수호자 거미줄 8개를 수집하십시오.",
        ["D"] =
        "얼라이언스와 와일드해머 부족 간의 관계를 증진시키기 위해 땜장이 왕께서 절 이곳에 보내셨죠. 제 역할은 간단해요, 그리핀 타기를 더 안전하게 만드는 거랍니다.\n\n저는 탑승자가 추락하는 걸 감지하고 자동으로 펴지는 낙하산을 만들 계획이에요. 아주 멋지지 않나요?\n\n하지만 이걸 만들려면 와일드해머 부족에게는 없는 재료가 필요해요. 제일 먼저 낙하산 천을 구해야 하죠. 근처의 마른나무껍질 트롤 놈들은 고품질의 재봉 기술을 가지고 있고 놈들의 거미는, 좀 징그럽긴 하지만 훌륭한 실을 만들어내거든요. 그걸 좀 가져다주시면 제가 이 낙하산 작업을 시작할 수 있을 거예요.",
    },
    [26172] = {
        ["T"] = "떨어지면 감사",
        ["O"] = "동부 내륙지의 산속에서 루포 지프코일을 찾으십시오.",
        ["D"] =
        "이 계획의 다음 부품은 알토미터예요! 간단히 말해서, 뭔가가 떨어진다? 그럼 알토미터가 작동하는 거죠. 참 쉽죠.\n\n안타깝게도 저한테는 지금 그게 없어요. 우리 노움들은 여기 동부 내륙지에 작은 전초기지를 가지고 있는데 제 동료 중 하나가 그 물건을 가지고 있을지도 몰라요. 가서 그와 이야기해 보시겠어요?\n\n이곳에서 동쪽에 있는 산맥, 쿠엘다닐 오두막 북쪽의 비밀 전초기지 안에 그가 숨어 있을 거예요.",
    },
    [26173] = {
        ["T"] = "떨어지면 감사",
        ["O"] = "아골와타 호수 바닥에서 알토미터를 회수하십시오.",
        ["D"] =
        "아, 티지가 알토미터를 찾고 있다고요? 우리한테 하나 있었죠. '있었다'는 게 문제지만. 얼마 전에 아골와타 옆 호수에서 실험을 하다가 사고가 나서 우리 보급품 일부가 호수로 바로 빠져버렸거든요. 아래로 내려가서 보급품들을 건져 오시면 당신이 찾는 알토미터도 그곳에 있을 거라고 확신해요.",
    },
    [26174] = {
        ["T"] = "떨어지면 감사",
        ["O"] = "맹금의 봉우리로 돌아가 스파크크래프트 양에게 온전한 알토미터를 가져가십시오.",
        ["D"] =
        "자, 스파크크래프트 양을 위한 온전한 알토미터가 여기 있어요. 도대체 그녀가 이걸 어디에 쓰려는 거죠? 자동으로 펴지는 낙하산이라... 흥미롭군요... 완성된 기계의 적절한 시연을 마련해야겠어요.",
    },
    [26175] = {
        ["T"] = "떨어지면 감사",
        ["O"] = "티지의 제트팩을 사용하여 공중 높이 날아오른 후 자동으로 펼쳐지는 낙하산을 테스트하십시오.",
        ["D"] =
        "이제... 쇼타임이에요! 폴스타트가 직접 액션을 자세히 볼 수 있도록 이걸 폴스타트에게 가져가고, 이 제트팩의 끈을 당기세요.\n\n어느새 당신은 하늘 높이 솟아올라 있을 거고, 추락하는 순간 낙하산이 펴질 거예요. 제 생각엔... 뭐, 확인해 볼 방법은 하나뿐이죠!",
    },
    [26176] = {
        ["T"] = "떨어지면 감사",
        ["O"] = "폴스타트 와일드해머에게 자동 낙하산 키트를 전달하십시오.",
        ["D"] =
        "이걸로 와일드해머 부족의 환심을 사지 못한다면, 대체 뭐가 통할지 모르겠네요. 절 대신해서 이걸 폴스타트에게 건네주시는 영광을 누려보실래요?",
    },
    [26177] = {
        ["T"] = "날카로운부리 친구들",
        ["O"] = "그리핀 간식을 만들 농어 스테이크 8개와 왕의 한입 갈대 줄기 12개를 모으십시오.",
        ["D"] =
        "우리 부족은 그리핀을 신성한 동물로 숭배해. 하늘의 웅장한 피조물이며, 멍청한 짐승 그 이상이지. 지능적이고 교활하거든. 어떤 이들은 우리가 그리핀을 말처럼 기른다고 하지만, 그건 우정에 더 가까워.\n\n이곳의 와일드해머와 친구가 되고 싶다면, 먼저 우리 그리핀들과 친구가 되게! 녀석들이 가장 좋아하는 간식은 좀 흔치 않은데, 바로 바삭바삭한 갈대와 신선한 생선 스테이크를 섞은 거지. 녀석들은 이 간식에 환장한다네.\n\n그리핀 간식을 좀 만들려면 재료를 좀 모아와야 해. 이곳에서 동쪽으로 가면 해안을 따라 흐르는 강으로 이어지는 커다란 개울을 발견할 수 있을 거야. 아골와타 근처에서 시작되지. 거기서 통통한 농어와 왕의 한입 갈대를 찾을 수 있어. 그걸 구해 내게 오면, 신선하게 한 바구니 만들어 주지.",
    },
    [26178] = {
        ["T"] = "날카로운부리 친구들",
        ["O"] = "맹금의 봉우리 남동쪽에서 발견되는 훈련된 날카로운부리들에게 그리핀 간식을 주십시오.",
        ["D"] =
        "이 먹이 가방을 가져가게. 아주 신선하지. 훈련받은 날카로운부리 그리핀들이 새장 남동쪽 숲을 떠돌고 있어. 가서 날 대신해 몇 마리에게 먹이를 주겠나?",
    },
    [26179] = {
        ["T"] = "동부내륙지의 은둔자",
        ["O"] =
        "깨진엄니 마을의 식량으로 거북 고기를 사용하는 것에 불만을 품고 떠난 전 깨진엄니 마을 경비병, 은둔자 우보를 찾으십시오.",
        ["D"] =
        "문제가 좀 생겼어. 너처럼 강한 친구가 해결해 줘야 해.\n\n우리 경비병 중 한 명인 은둔자 우보가 거북 고기를 싫어해서 마을을 떠났어. 지금은 여기서 북쪽에서 혼자 살고 있지.\n\n우보와 녀석의 경비 기술이 그리워. 녀석이 마을로 돌아왔으면 좋겠어. 네가 녀석을 찾아 마을로 데려와 주면 짭짤하게 보상해 주지. 우리 대신 이 일을 해주겠어, 친구?",
    },
    [26180] = {
        ["T"] = "무쇠턱거북 간식",
        ["O"] = "무쇠턱거북 간식을 만들 농어 스테이크 8개와 왕의 한입 갈대 줄기 12개를 모으십시오.",
        ["D"] =
        "만약 로아가 거북이의 형상을 취할 수 있다면, 그들은 분명 아주 특별한 존재일 거야. 난 잔달라 트롤도 아니고 우리 엄마도 아니었지만, 모든 트롤이 숭배하는 로아들에 대한 그녀의 이야기를 듣는 걸 좋아했지.\n\n레반터스크 부족은 엄청난 양의 거북 고기를 먹어 치워. 심지어 때로는 그냥 재미로 거북이를 죽이기도 하지. 정말 구역질이 나.\n\n난 이 거북이들에게 토르가조차 기뻐할 만한 제물을 바치고 싶어. 거북이들이 특별한 종류의 갈대와 이 위쪽 강에서 가끔 이 해안으로 떠내려오는 물고기를 먹는 걸 본 적이 있지. 그 물고기의 스테이크와 갈대를 좀 모아다 줄 수 있겠어? 그럼 거북이들에게 맛있는 간식을 만들어 줄 수 있을 거야.",
    },
    [26181] = {
        ["T"] = "간식 배급",
        ["O"] = "동부내륙지 해안을 따라 무쇠턱거북들에게 간식을 먹이십시오.",
        ["D"] =
        "네가 가져다준 재료로 무쇠턱거북들을 위한 특별한 간식을 만들었어. 나 대신 해안을 따라 있는 무쇠턱거북들에게 이 간식을 나눠주겠어?",
    },
    [26182] = {
        ["T"] = "평화의 징표",
        ["O"] = "동부 내륙지의 해안을 따라 거북이 \"배설물\" 8개를 수집하십시오.",
        ["D"] =
        "이제 내가 왜 이 거북이들을 그토록 사랑하고 마을로 돌아가지 않는지 알겠어? 레반터스크 부족이 나를 설득하라고 너 같은 모험가들을 자꾸 보내는 것도 지긋지긋해. 이 문제를 끝낼 완벽한 메시지를 하나 보낼까 해.\n\n네가 나눠준 간식에는 부작용이 하나 있는데, 거북이들의 소화관을 아주 빠르게 통과한다는 거야. 즉, 우리가 레반터스크 부족을 위해 예쁘게 포장할 수 있는 \"배설물\"이 아주 많다는 뜻이지.\n\n날 위해 좀 주워다 줘. 그리고 그게 아직 신선할 때 최대한 빨리 돌아와.",
    },
    [26183] = {
        ["T"] = "평화의 징표",
        ["O"] = "그의 오두막 북쪽 섬에서 우보의 화려한 궤짝을 수집하십시오.",
        ["D"] =
        "다음 단계는 멋진 상자를 구해서 진짜 좋은 선물인 것처럼 보이게 하는 거야. 지금 생각해 보니 네 손에 똥을 묻히지 않게 하려면 네가 먼저 상자를 구해오게 했어야 했는데... 뭐 어때!\n\n여기서 북쪽에 있는 작은 섬은 우리 어머니가 돌아가신 후에 화려한 상자에 어머니의 유골을 모셔둔 곳이야. 그건 정말 훌륭한 수공예품이라서 이번 계획에 완벽하게 들어맞을 거야. 그리고 무엇보다도 우리 어머니라면 이 전체 상황을 정말 재밌어하셨을 테니까.",
    },
    [26184] = {
        ["T"] = "평화의 징표",
        ["O"] = "동부 내륙지 깨진엄니 마을의 감시자 오웨이에게 우보의 평화의 징표를 가져가십시오.",
        ["D"] =
        "이 \"평화의 징표\"를 마을로 돌아가서 감시자 오웨이에게 전해 줘. 그러면 더 이상 나한테 말을 걸어보라고 너 같은 모험가들을 보내는 일은 그만둘 거라고 생각해.\n\n가봐 - 그리고 네가 나를 찾아오는 마지막 사람이길 바라.",
    },
    [26185] = {
        ["T"] = "라드의 잃어버린 구슬",
        ["O"] = "동부내륙지 해안을 순찰하는 상어 재버죠에게서 라드의 구슬을 모으십시오.",
        ["D"] =
        "가끔 라드는 부두로 가서 바다에 돌을 던지는 걸 좋아해. 라드는 심지어 세 번이나 물수제비를 떴어!\n\n라드는 너무 흥분한 나머지 돌 대신 구슬을 바다에 던져버렸지... 그리고 다음 순간, 크고 못된 상어 재버죠가 헤엄쳐 와서는 구슬을 삼켜버린 거야! 재버죠의 뱃속에서 라드 대신 구슬을 좀 꺼내줄래?",
    },
    [26186] = {
        ["T"] = "멀리서 온 부품",
        ["O"] = "아이언포지의 미올로 선더퓨리에게 간식 바구니를 가져가 공성 전차 부품으로 교환하십시오.",
        ["D"] =
        "아이언포지에서 이렇게나 멀리 떨어진 곳에서 공성 전차를 유지보수하는 건 정말 지옥이야. 우린 공식적으로 얼라이언스의 일원이 아니기 때문에 최신 최고의 부품에 접근할 수가 없거든.\n\n밖에 있는 저 외교관에게 공식적인 지원을 요청할 수도 있겠지만, 그가 수락한다 해도 우린 형식주의와 온갖 말도 안 되는 일에 휩쓸리게 될 거야. 내 아내가 우리에게 직접 보급품을 배달받을 수 있는 더 간단한 방법을 생각해 냈어. 바로 음식이지! 모든 드워프는 음식에 약하니까.\n\n이 간식 바구니를 아이언포지의 미올로 선더퓨리에게 가져다주고 그 대가로 부품을 좀 받아와 줘.",
    },
    [26187] = {
        ["T"] = "멀리서 온 부품",
        ["O"] = "맹금의 봉우리의 수석 기술자 우룰에게 공성 전차 부품 상자를 가져가십시오.",
        ["D"] =
        "보통은 어떤 부품이라도 아이언포지의 방어망을 벗어나게 내버려두지 않지만, 네가 내게 가져온 것을 고려하면... 음... 한 번쯤은 눈감아 줄 수도 있지 않겠어? 얼른 먹어 치우고 싶어서 견딜 수가 없군. 이 부품들을 와일드해머 부족에게 가져가면 이번 일은 해결된 걸로 치지.\n\n다음엔 에일 맥주도 좀 같이 넣어달라고 전해줘!",
    },
    [26188] = {
        ["T"] = "추적자 추적하기",
        ["O"] =
        "동부 내륙지 맹금의 봉우리에 있는 그리핀 조련사 탈론액스가 당신에게 긴발톱 은빛갈기늑대 15마리와 은빛갈기 늑대 15마리를 죽여 달라고 부탁했습니다. 임무를 마치면 그에게 돌아가십시오. 탈론액스는 늑대들이 동부 내륙지의 야생에 숨어 있다고 말했습니다.",
        ["D"] =
        "수많은 용감한 드워프들이 동부 내륙지의 혹독한 야생에서 목숨을 잃었네, $r. 은빛갈기늑대들은 우리 사냥꾼들에게 가장 큰 위협 중 하나지. 놈들은 수풀과 풍경 속에 숨어서 기다리다가, 기회가 오면 공격한다네.\n\n이런 종류의 흉포함을 견제하지 않은 채로 둘 수는 없네!\n\n은빛갈기를 찾으려면 은빛갈기처럼 생각해야지. 늑대와 추적자들을 쫓게! 모조리 베어버리게!",
    },
    [26189] = {
        ["T"] = "프라임 슬라임",
        ["O"] = "다이어글롭에게서 다이어글롭 샘플을 구하십시오.",
        ["D"] =
        "아는 드워프가 많지는 않겠지만, 내 맥주에 진짜 '짜릿한 맛'을 더하려면 이곳 주변에 있는 수액 괴물을 아주 조금 넣는다네. 맞아, 드워프를 잡아먹는 거대한 초록색 수액 괴물 말이야.\n\n이 맥주가 엄청난 짜릿함을 가지려면 거대한 수액 괴물이 필요해! 굼벵이 바위굴 아래에 놈들의 어미뻘인 놈이 도사리고 있는데, 정말 엄청나게 크지... 우린 그놈을 다이어글롭이라고 불러.\n\n자네가 그만한 실력이 있다면 그곳으로 내려가서 날 위해 다이어글롭 덩어리를 떼어와 주게나!",
    },
    [26190] = {
        ["T"] = "프라임 슬라임",
        ["O"] = "다이어글롭에게서 다이어글롭 샘플을 구하십시오.",
        ["D"] =
        "끈적거리는 수액 괴물 연구에 관심이 있나? 굼벵이 바위굴 수액 괴물들은 웃어넘길 상대가 아니야. 우리가 아무리 놈들을 쓸어버려도, 트롤들처럼 계속 재생해서 돌아오는 것 같거든... 아니면 뭔가 다른 이유가 있거나.\n\n내 생각이 뭔지 알아? 난 그 아래에 수액 괴물들을 끊임없이 만들어내는 어떤 근원지가 있을 거라고 생각해. 난 그게 뭔지 알아내고 싶어! 그러니 가보게 모험가여, 굼벵이 바위굴로 내려가서 수액 괴물을 만드는 원흉의 샘플을 가져다주게. 내게 정말 흥미로운 연구 대상이 될 거야!",
    },
    [26191] = {
        ["T"] = "사악한 직업",
        ["O"] = "맹금의 봉우리 동쪽에서 흉포한 달빛야수 10마리를 처치하십시오.",
        ["D"] =
        "이 지역의 트롤들과 벌이는 우리의 끝없는 불화는 종종 평화로운 교착 상태로 사그라들곤 하지만, 평화는 결코 영원하지 않지.\n\n동부 내륙지 바깥에서는 올빼미야수들이 계획을 망쳐놓고 있어. 녀석들은 때때로 트롤 무리를 습격하거나 와일드해머 보급 마차를 약탈하지. 그러면 우리는 서로를 탓하며 전투를 벌이게 된다네.\n\n만약 우리가 어떤 형태로든 평화를 향해 나아가고자 한다면, 저 올빼미야수들을 막아야 해. 동쪽으로 가서 날 위해 녀석들의 수를 좀 줄여주게. 그러면 흥분도 좀 가라앉겠지.",
    },
    [26192] = {
        ["T"] = "원시적인 구타",
        ["O"] = "동부 내륙지의 중앙 지역에서 원시 올빼미야수 10마리를 찾아 처치하십시오.",
        ["D"] =
        "동쪽으로 멀리 갈수록, 올빼미야수들은 더 원시적이고 억세지지. 그놈들의 수를 줄이는 건 여기서부터 점점 더 힘든 도전이 될 테지만, 우린 와일드해머를 위해 이 일을 해야만 해.\n\n동부 내륙지의 중앙으로 가서 올빼미야수들의 수를 줄이게나. 자네가 괴수 한 마리를 처치할 때마다, 동부 내륙지는 한결 더 평화로워질 테니.",
    },
    [26193] = {
        ["T"] = "야만적인 일격",
        ["O"] = "동쪽으로 멀리 산마루 절벽 근처에서 야만적인 올빼미야수를 찾아 10마리를 처치하십시오.",
        ["D"] =
        "해안가 깨진엄니 마을에 가장 가까운 올빼미야수들이 가장 큰 피해를 주고 있어. 최근에 레반터스크 정찰대를 죽였다고 들었는데, 트롤들이 자기네 동료 시체를 찾았을 때는 우리가 비난을 받았지. 이런 부탁을 하게 되어 가슴이 아프지만, 그 올빼미야수들이 드워프와 트롤 사이의 긴장감을 폭발적으로 악화시키도록 내버려둘 수는 없어.\n\n야만적인 올빼미야수들은 더 강하고 더 다혈질인 것 같으니 조심하게 -- 하지만 우리는 반드시 그놈들을 쓰러뜨려야 해.",
    },
    [26194] = {
        ["T"] = "달빛야수의 지도력",
        ["O"] = "리렉의 허수아비를 찾아 태워 그를 자극하십시오. 그가 나타나면 그를 죽이십시오.",
        ["D"] =
        "이제 이 지역에서 녀석들의 수가 줄었으니, 그들의 \"지도자\"를 제거해야 할 때야. 녀석들의 족장은 그저 이 지역에서 가장 크고 성질이 더러운 달빛야수일 뿐이지. 나머지 녀석들은 그를 두려워하거나 존경하는데... 둘 중 어느 쪽인지는 잘 모르겠군.\n\n놈의 이름은 리렉이고 여기서 멀리 동쪽, 진타알로르의 북쪽에서 찾을 수 있어. 우리 정찰병들의 말에 따르면 녀석은 매우 은밀한 짐승이지만, 나머지 녀석들보다는 똑똑해. 녀석은 자신이 사는 곳에 허수아비를 세우는 게 목격되었어. 녀석을 꾀어내려면 허수아비 하나를 불태워. 틀림없이 은신처에서 나올 거야.",
    },
    [26195] = {
        ["T"] = "달빛야수의 지도력",
        ["O"] = "리렉의 허수아비를 찾아 태워 그를 자극하십시오. 그가 나타나면 그를 죽이십시오.",
        ["D"] =
        "이제 이 지역에서 녀석들의 수가 줄었으니, 그들의 \"지도자\"를 제거해야 할 때야. 녀석들의 족장은 그저 이 지역에서 가장 크고 성질이 더러운 달빛야수일 뿐이지. 나머지 녀석들은 그를 두려워하거나 존경하는데... 둘 중 어느 쪽인지는 잘 모르겠군.\n\n놈의 이름은 리렉이고 여기서 멀리 동쪽, 진타알로르의 북쪽에서 찾을 수 있어. 우리 정찰병들의 말에 따르면 녀석은 매우 은밀한 짐승이지만, 나머지 녀석들보다는 똑똑해. 녀석은 자신이 사는 곳에 허수아비를 세우는 게 목격되었어. 녀석을 꾀어내려면 허수아비 하나를 불태워. 틀림없이 은신처에서 나올 거야.",
    },
    [26196] = {
        ["T"] = "거북 파워",
        ["O"] = "산마루 절벽을 따라 늘어선 동부 내륙지의 동쪽 해안에 있는 거북이들에게서 연한 거북 옆구리살 10개를 모으십시오.",
        ["D"] =
        "건장한 와일드해머 드워프가 긴 하루를 보낸 후 가장 먼저 찾는 건 시원한 에일 한 잔과 요깃거리지. 이 근방에서 가장 맛있는 요리는 바로 끝내주는 거북이 스튜라네.\n\n안타깝게도 맹금의 봉우리는 동부 내륙지에서 거대 거북이들과 가장 멀리 떨어진 곳이지. 산마루 절벽으로 가서 날 위해 거북이들을 좀 사냥해 주게, 그래야 내가 요리를 시작할 수 있을 테니 말이야 -- 거북이들의 연한 옆구리살을 가져다주게!",
    },
    [26197] = {
        ["T"] = "거북 파워",
        ["O"] = "",
        ["D"] = "",
    },
    [26198] = {
        ["T"] = "현상 수배: 오염된 볏",
        ["O"] = "돌개바람 호수 주변을 순찰하는 파울크레스트를 찾아 놈의 고통을 덜어주십시오.",
        ["D"] =
        "몇 달 전, 하늘을 통상 순찰하던 중, 용감한 와일드해머 드워프 한 명이 트롤 창의 일제 사격에 맞아 추락했습니다. 그의 충실한 그리핀 동반자 파울크레스트는 이 일을 심각하게 받아들였습니다. 그 이후로 파울크레스트는 마주치는 모든 것, 즉 야생 동물, 트롤, 드워프를 가리지 않고 살해하며 자신의 분노를 표출하고 있습니다. 이 가여운 짐승은 안락사시켜야 합니다. 맹금의 봉우리의 그리핀 조련사들에게 파울크레스트의 죽음을 증명할 물건을 가져가십시오.",
    },
    [26199] = {
        ["T"] = "현상 수배: 오염된 볏",
        ["O"] = "돌개바람 호수 주변을 순찰하는 파울크레스트를 찾아 그를 죽이십시오.",
        ["D"] =
        "몇 달 전, 와일드해머 놈 중 한 명이 우리가 쏜 창에 맞고 하늘에서 떨어졌다. 녀석의 그리핀인 파울크레스트는 이 일을 심각하게 받아들였지. 그 이후로 녀석은 피의 분노에 휩싸여 야생 동물, 트롤, 드워프를 가리지 않고 학살하고 있다. 깨진엄니 마을의 감시자 오웨이에게 녀석의 죽음을 증명할 물건을 가져가라.",
    },
    [26200] = {
        ["T"] = "숲의 균형 찾기",
        ["O"] = "어린 달빛야수 5마리와 달빛야수 10마리를 처치하고 아우버다인의 파수꾼 글린다 날셰에게 돌아가십시오.",
        ["D"] =
        "이시누 알라, $N. 삶의 모든 것은 균형을 이루며, 엘룬께서는 숲이 그러한 상태를 유지하도록 돌보십니다. 최근에 균형이 무너지고 있으며, 무언가 조치를 취하지 않는다면 아제로스의 근간을 흔들 수 있다는 두려움이 들기 시작했습니다. 저희는 엘룬께 우리를 도울 자를 보내 달라고 기도했고, 그 결과 당신이 오셨군요.\n\n지금 이 불균형의 주요 원인은 동쪽에 있는 달빛야수 무리입니다. 평화롭던 달빛야수 군락이 통제 불능의 혼돈으로 변했던 텔드랏실의 사례와 비슷한 일이 일어났다는 보고를 받았습니다. 달빛야수들은 눈에 보이는 모든 것을 공격하고 자연의 흐름을 방해하고 있습니다. 부디 그 군락을 처리하여 숲의 균형을 되찾아주십시오.",
    },
    [26201] = {
        ["T"] = "숲의 균형 찾기",
        ["O"] = "달빛야수 점쟁이 3마리와 사나운 달빛야수 10마리를 처치한 후, 아우버다인의 파수꾼 글린다 날셰에게 돌아가십시오.",
        ["D"] =
        "유감스럽게도, 우리가 정화한 지역은 군락의 작은 일부에 불과했던 모양입니다. 나이 든 달빛야수들은 숲의 더 동쪽에 살고 있습니다. 이 야생의 피조물들을 파괴해야 한다는 것이 슬프지만, 해야 할 일은 해야만 합니다.\n\n달빛야수 군락으로 돌아가서 숲 안쪽을 더 수색해 주십시오. 아우버다인의 안전을 지키고 균형을 되찾기 위해서는 이 위협을 완전히 제거해야 합니다.",
    },
    [26202] = {
        ["T"] = "황혼의 망치단",
        ["O"] = "황혼의 폭력배 8명과 황혼의 제자 8명을 처치하고 아우버다인의 알란다리안 나이트송에게 돌아가십시오.",
        ["D"] =
        "아우버다인에 심각한 위협이 도사리고 있습니다, $N. 그들은 자신들을 황혼의 망치단이라고 부릅니다. 이들은 혼돈과 불안을 퍼뜨리며 숲의 균형을 무너뜨리는 이교도 집단입니다. 놈들은 고대 신들을 숭배하고 그들을 다시 깨워 아제로스에 파멸을 가져오기를 갈망합니다.\n\n이들을 막아야 합니다! 놈들은 남쪽 멀리, 잿빛 골짜기 경계 근처에 있는 지배자의 고대검이라는 전초기지에 주둔하고 있습니다. 가십시오, $N. 어둠해안에 남겨진 이교도의 흔적을 정화해 주십시오.",
    },
    [26203] = {
        ["T"] = "아우버다인에 오신 것을 환영합니다",
        ["O"] = "아우버다인에 있는 병참장교 냐나에게 보고하십시오.",
        ["D"] =
        "아우버다인에 오신 것을 환영합니다, 여행이 평탄했길 바랍니다. 이곳엔 해야 할 일이 아주 많으며, 당신이 도와주신다면 정말 감사하겠습니다. 달빛야수, 펄볼그, 멀록, 이교도, 나가... 골칫거리 목록이 정말 길답니다!\n\n먼저 병참장교 냐나와 인사를 나누는 것이 좋을 것 같습니다. 그녀는 마을회관에 머물며 보고서를 읽고 현재 진행 중인 여러 상황을 주시하고 있습니다. 다음에 다시 만날 수 있기를 바랍니다. 엘룬의 축복이 당신과 함께하길.",
    },
    [26204] = {
        ["T"] = "잿빛안개의 위협",
        ["O"] = "아우버다인 남쪽에서 빌 휠랜드를 위해 잿빛안개 멀록을 처치하십시오.",
        ["D"] =
        "저는 서부 몰락지대에 살았었지만, 인근 해안에 멀록들이 들끓기 시작했을 때 황금해안 채석장 근처에 있던 제 땅을 버려야만 했습니다. 그 비늘 덮인 똥개들의 기억을 지워보려고 머나먼 어둠해안까지 왔지요. 하지만 소용이 없군요, $C! 이곳 마을 바로 남쪽 해안에도 멀록들이 사방에 깔려 있습니다!\n\n당신에게 일말의 동정심이라도 있다면, 제발 놈들이 우리를 압도할 만큼 큰 위협으로 자라나기 전에 놈들을 쓰러뜨려 주십시오. 전 악몽 속에서도 놈들의 비명소리를 듣습니다....",
    },
    [26205] = {
        ["T"] = "잿빛안개의 위협",
        ["O"] = "아우버다인에 있는 빌 휠랜드를 위해 어둠해안 남부 해안을 따라 잿빛안개 멀록들을 처치하십시오.",
        ["D"] =
        "이 위협이 우리를 조여오는데 도저히 잠을 잘 수가 없소, $C. 그래서 해안을 따라 남쪽으로 더 멀리 걸어보았지. 어둠해안의 먼 남쪽 해안에 더 강력한 멀록들이 있다는 걸 믿을 수 있겠소?\n\n놈들은 분명 어디선가 오고 있을 거요. 당신이 놈들의 위협을 끝장내는 동안 나는 좀 조사를 해봐야겠소.\n\n나를 위해 이 일을 처리해 줄 수 있겠소, 그렇지?",
    },
    [26206] = {
        ["T"] = "숄비어드",
        ["O"] = "숄비어드를 처치한 후 아우버다인의 빌 휠랜드에게 돌아가십시오.",
        ["D"] =
        "서부 몰락지대의 멀록들에게는 지도자가 있었을지도 모릅니다. 전 그걸 알아낼 만큼 그곳에 오래 머물지 않았지만요. 어둠해안의 멀록들에게 지도자가 있다는 건 확실합니다.\n\n해안을 따라 잿빛 골짜기에 거의 다다를 때까지 남쪽으로 계속 가다 보면, 미성숙한 바다 거인을 발견할 수 있을 거요. 그 괴물이 이 멀록 침략의 배후에 있는 존재요! 놈을 쓰러뜨리지 않으면 우린 놈의 끈적이는 군대에게 짓밟히고 말 거요!",
    },
    [26207] = {
        ["T"] = "현상 수배: 미스트핀",
        ["O"] = "아메스아란 폐허 동쪽 깊은 바다에 있는 \"미스트핀\"이라는 트레샤돈을 찾아 처치하십시오. 아우버다인에 있는 파수꾼 글린다 날셰에게 현상금을 청구하십시오.",
        ["D"] =
        "주목!\n\n\"미스트핀\"으로 알려진 트레샤돈의 죽음에 대해 포상금을 지급합니다. 이 괴물은 지역 내 어선들을 공격했고 최소 두 명의 어부를 사망케 했습니다.\n\n미스트핀은 아메스아란 폐허 동쪽의 깊은 바다 경계를 배회하는 것으로 알려져 있습니다. 이 현상금 청구는 아우버다인에 있는 파수꾼 글린다 날셰에게 해야 합니다.\n\n아우버다인 마을 의회.",
    },
    [26208] = {
        ["T"] = "현상 수배: 그리즐투스",
        ["O"] = "\"그리즐투스\"로 알려진 곰을 찾아 처치하십시오. 아우버다인에 있는 파수꾼 글린다 날셰에게 현상금을 청구하십시오.",
        ["D"] =
        "주목!\n\n\"그리즐투스\"로 알려진 곰의 죽음에 대해 포상금을 지급합니다. 검은나무 펄볼그들이 잿빛 골짜기의 곰 한 마리를 남쪽의 잿빛 골짜기 경계 근처에 있는 검은나무 소굴로 유인했습니다. 이 어린 곰이 검은나무 펄볼그의 통제를 받는 괴물로 자라기 전에 놈을 처치해야 합니다.\n\n이 현상금에 대한 보상 청구는 아우버다인에 있는 파수꾼 글린다 날셰에게 제출해야 합니다.\n\n아우버다인 마을 의회.",
    },
    [26209] = {
        ["T"] = "와일드해머 유골",
        ["O"] = "진타알로르에서 와일드해머 뼈 10개를 회수하십시오. 이 임무를 완수하면 맹금의 봉우리의 폴스타트 와일드해머에게 돌아가십시오.",
        ["D"] =
        "진타알로르의 썩은가지 트롤들은 오랫동안 우리 묘지에서 훔친 드워프의 뼈를 사용하여 사악한 의식을 행해 왔다. 그들은 타락한 여사제 헥스의 요청으로 뼈를 훔친다.\n\n진타알로르로 가서 숭고한 우리 조상들의 뼈를 회수해라. 도시 안 트롤들의 힘의 근원지에서 그것들을 찾을 수 있을 것이다.",
    },
    [26210] = {
        ["T"] = "구인: 맹금의 봉우리 경비대장",
        ["O"] =
        "진타알로르로 이동하여 썩은가지 전사 20명, 썩은가지 어둠마법사 20명, 썩은가지 가죽무두장이 20명, 아마자시 경비병 20명을 처치하십시오. 이 임무를 완수하면 동부 내륙지의 맹금의 봉우리에 있는 칼라 해머플라이트와 대화하십시오.",
        ["D"] =
        "와일드해머 부족은 트롤 도시인 진타알로르로 군대를 이끄는 데 관심이 있는 강력한 전사들을 모집하고 있다. 관심 있는 지원자는 다음 임무를 완수해야 한다:\n\n썩은가지 전사 근절\n\n썩은가지 어둠마법사 근절\n\n썩은가지 가죽무두장이 근절\n\n썩은가지 아마자시 경비병 근절",
    },
    [26211] = {
        ["T"] = "전술적 타격",
        ["O"] = "진타알로르에 들어가 타락한 여사제 헥스와 수호자 히타야를 처치하십시오.",
        ["D"] =
        "오랫동안 와일드해머 부족은 동부 내륙지에 살아왔고 오랫동안 썩은가지 트롤들과 충돌해 왔다. 트롤들은 이곳 남동쪽에 진타알로르라는 거대한 도시를 세웠다. 우리가 이 힘의 요새에서 그들을 모조리 없앨 희망은 없지만 그들에게 치명타를 입혀 혼란에 빠뜨려 우리를 공격하지 못하게 할 수는 있다.\n\n진타알로르에 잠입하여 그들의 지도자인 타락한 여사제 헥스와 수호자 히타야를 처치하라! 놈들은 도시의 가장 높은 곳에 있을 것이다.",
    },
    [26212] = {
        ["T"] = "그들이 하는 부두 마법",
        ["O"] = "진타알로르의 트롤들에게서 부두 플럭스 8개를 수집하여 동부 내륙지 맹금의 봉우리의 칼라 해머플라이트에게 가져가십시오.",
        ["D"] =
        "마을의 많은 이들처럼, 나도 썩은가지 트롤들과 싸워왔고 그들 무기의 품질에 감탄했다. 난 썩은가지 트롤들이 나무와 강철을 강화하기 위해 마법을 사용한다고 믿는다. 하지만 그 마법은 그들이 무기를 단조하고 만들 때 사용하는 특별한 플럭스의 형태일 것이다.\n\n네가 진타알로르로 가서 그 플럭스를 좀 가져다줄 의향이 있다면 내게 그 표본이 몇 개 필요하다.",
    },
    [26213] = {
        ["T"] = "호윈이 제일 좋아하는 낚시터",
        ["O"] = "맹금의 봉우리 극동쪽, 산마루 절벽을 따라 있는 폭포 꼭대기의 그가 가장 좋아하는 낚시터에서 호윈의 애장품 미끼를 회수하십시오.",
        ["D"] =
        "$R, 자네 유능해 보이는군. 부탁 하나만 해도 되겠나?\n\n먼 동쪽, 산마루 폭포 꼭대기에 있는 내가 가장 좋아하는 장소에서 낚시를 하고 있었는데, 썩은가지 트롤 무리가 배회하다가 날 공격했다네. 난 살기 위해 도망쳤고, 낚시 도구는 전부 내버려 두었지.\n\n산마루 폭포로 돌아가서 내 물건들을 좀 주워다 주겠나? 전부 다 찾지 못해도 괜찮네 -- 난 정말 내가 가장 아끼는 미끼만 되찾으면 되거든.",
    },
    [26214] = {
        ["T"] = "호윈이 제일 좋아하는 낚시터",
        ["O"] = "산마루 폭포의 기슭에서 호윈의 애장품 미끼를 회수하십시오.",
        ["D"] =
        "낚시 의자 주변을 샅샅이 수색했지만 호윈의 미끼나 다른 낚시 도구의 흔적은 찾을 수 없습니다. 다른 물건들은 폭포 위로 휩쓸려 내려갔을지도 모릅니다. 운이 좋다면 폭포 아래의 진흙 속에 있을 수도 있습니다.",
    },
    [26215] = {
        ["T"] = "호윈이 제일 좋아하는 낚시터",
        ["O"] = "금단의 바다에서 호윈의 애장품 미끼를 회수하십시오.",
        ["D"] =
        "강한 해류가 폭포에서 멀어져 동쪽의 금단의 바다로 흐릅니다.\n\n호윈의 태클 박스에 있던 물건들이 해류에 휩쓸렸다면 이곳 동쪽의 대륙붕으로 떠내려갔을지도 모릅니다.\n\n호윈에게 미끼를 잃어버렸다고 말하러 가기 전에 한 번 찾아볼 가치가 있습니다.",
    },
    [26216] = {
        ["T"] = "호윈이 제일 좋아하는 낚시터",
        ["O"] = "호윈의 애장품 미끼를 가지고 맹금의 봉우리로 돌아가십시오.",
        ["D"] = "기적 같은 일이군요! 유목 한 조각에 낚시 미끼가 걸려 있습니다. 당신은 미끼를 조심스럽게 빼내며 호윈이 찾던 바로 그 미끼이기를 바랍니다.",
    },
    [26217] = {
        ["T"] = "호수에서 길을 잃다",
        ["O"] = "로다미어 호수 바닥에서 얀스가의 가보를 회수하십시오.",
        ["D"] =
        "아서스가 로데론에서 배신한 후 도시에 큰 공황이 일어났소. 우리 가족과 나는 로다미어 호수를 가로질러 배를 타고 탈출한 많은 사람들 중 하나였지.\n\n난 내 가족의 다른 사람들보다 운이 나빴어 -- 물이 새는 배를 탔다가 공동묘지 동쪽 부두에서 얼마 떨어지지 않은 곳에서 전복되고 말았지. 내가 인간으로서 마지막으로 기억하는 건 물보다 차가운 손이 날 해안으로 끌어올렸다는 거야....\n\n어쨌든, 우리 가족의 가보는 호수 바닥으로 가라앉았고, 지금도 거기에 있소. 당신이 그 물건들을 회수해 준다면 그 대가를 기꺼이 지불하겠소.",
    },
    [26218] = {
        ["T"] = "케스트렐호의 잔해",
        ["O"] = "공동묘지 북쪽의 북부 해안가에 있는 케스트렐호의 잔해를 뒤져 굴뚝나무 목장조합 운송 상자를 찾으십시오.",
        ["D"] =
        "몇 달 전에 굴뚝나무 목장조합에 수공예 재료를 대량으로 주문했소. 그 보급품들은 케스트렐이라는 배를 타고 칼림도어에서 배송 중이었지. 안타깝게도 배가 짙은 안개 속에서 공동묘지 북쪽 해안을 따라 좌초되고 말았소.\n\n배가 난파된 북부 해안가 근처 숲에는 적대적인 늑대인간들이 살고 있어서, 난 아직 잔해를 조사하러 가지 못했소. 당신이 케스트렐호의 화물칸에서 내 운송 상자를 찾아준다면 기꺼이 그 안의 보급품 일부를 나누어 주겠소.",
    },
    [26219] = {
        ["T"] = "정당한 보상",
        ["O"] = "자연의정수 장갑 세트를 아이언포지의 델리아나에게 가져가십시오.",
        ["D"] =
        "당신은 약속을 지켰고 먹스가 만든 장치를 가져왔습니다. 제 목숨을 구하는 데 계속 흥미를 느끼게 하려면 보상이 필요할 거라 생각합니다. 업그레이드하고 싶은 허리띠와 장갑 세트를 제게 가져오십시오. 보답으로 드리는 물건은 훨씬 더 뛰어날 것이라고 약속합니다.",
    },
    [26220] = {
        ["T"] = "정당한 보상",
        ["O"] = "자연의정수 장갑 세트를 오그리마의 모크바르에게 가져가십시오.",
        ["D"] =
        "당신은 매우 믿음직한 분임을 증명하셨습니다, $N. 당신이 이 곤경을 헤쳐나가도록 도와줄 것이라 믿는 만큼, 당신의 성과에 따라 보상하는 것이 현명한 처사일 것입니다.\n\n일단 당신의 허리띠와 장갑을 교환해 드리겠습니다. 우리 둘 다 이 일을 끝까지 해낸다면, 나머지 방어구들도 구할 수 있게 해 드리겠습니다.",
