        "정말 놀라운 이야기군요, $N! 제 감사는 물론이고, 관련된 모든 이들의 진심 어린 감사를 전합니다. 이제 밤에 두 눈 다 감고 잘 수 있겠어요.\n\n당신의 보상에 대해 말하자면, 정말 마음에 쏙 들 만한 물건을 몇 가지 준비해 두었습니다.",
    },
    [26240] = {
        ["T"] = "가장 좋은 것은 마지막을 위해",
        ["O"] = "모크바르에게 당신의 기원의 로브를 주십시오.",
        ["D"] =
        "정말 놀라운 이야기군요, $N! 제 감사는 물론이고, 관련된 모든 이들의 진심 어린 감사를 전합니다. 당신의 노력 덕분에 우린 과거의 실수에서 해방되었습니다.\n\n당신의 보상에 대해 말하자면, 당신이 분명히 획득했고 진정으로 즐길 만한 물건을 몇 가지 준비해 두었습니다.",
    },
    [26241] = {
        ["T"] = "안시온의 작별 인사",
        ["O"] = "기원의 스커트를 아이언포지의 델리아나에게 가져가십시오.",
        ["D"] =
        "발타라크의 영혼이 이 아뮬렛에 저장되어 있었소. 우린 탐욕에 눈이 멀어 어리석게도 그것을 세 조각으로 나누었고, 우리를 기다리는 저주가 무엇인지 전혀 몰랐소.\n\n발타라크의 주문을 막는 유일한 방법은 메달을 다시 하나로 맞추는 것뿐이오. 델리아나에게 돌아가서 남은 조각을 찾을 희망은 보들리뿐이라고 전하시오. 당신이 받기로 한 보상에 대해서도 그녀와 얘기해 보시오.\n\n나로선 마침내 평화롭게 쉴 수 있겠군. 행운을 비오. 행운이 아주 많이 필요할 거요!",
    },
    [26242] = {
        ["T"] = "안시온의 작별 인사",
        ["O"] = "성령의 다리갑옷 한 쌍을 오그리마의 모크바르에게 가져가십시오.",
        ["D"] =
        "발타라크의 영혼이 이 아뮬렛에 저장되어 있었소. 우린 탐욕에 눈이 멀어 어리석게도 그것을 세 조각으로 나누었고, 우리를 기다리는 저주가 무엇인지 전혀 몰랐소.\n\n발타라크의 주문을 막는 유일한 방법은 아뮬렛을 다시 하나로 맞추는 것뿐이오. 모크바르에게 돌아가서 남은 조각을 찾을 희망은 보들리뿐이라고 전하시오. 당신이 받기로 한 보상에 대해서도 그와 얘기해 보시오.\n\n나로선 마침내 평화롭게 쉴 수 있겠군. 행운을 비오. 행운이 아주 많이 필요할 거요!",
    },
    [26243] = {
        ["T"] = "이글거리는 보석",
        ["O"] = "이글거리는 보석을 감정할 누군가를 찾으십시오.",
        ["D"] =
        "이 보석은 뚜렷한 붉은 광택이 있다는 것만 제외하면 평원 주변에 널려 있는 다른 흑요석 파편과 거의 똑같아 보입니다. 밝은 빛 앞에서 파편을 보면 소용돌이치는 연기 웅덩이가 그 안에서 춤을 추고 있으며, 수정을 너무 오래 쥐고 있으면 엄청난 열기가 뿜어져 나오는 것을 알 수 있습니다.\n\n불타는 평원에 있는 누군가라면 이 아이템을 보고 흥미를 가질지도 모릅니다.",
    },
    [26244] = {
        ["T"] = "흑요석 획득",
        ["O"] = "불타는 평원 주변의 흑요석 정령과 전투절단기로부터 흑요석 파편 24개를 수집하십시오.",
        ["D"] =
        "어둠괴철로 도시 녀석들이 이런 걸로 흑요석 합금을 만들어서 마법 무기 같은 걸로 바꾼다는 얘기를 들었지. 항상 나도 한번 해보고 싶었다네...\n\n어때? 자네한테 뭔가 좋은 걸 만들어주겠다고 약속하지. 일단 시작하려면 평원 주변에 있는 정령과 전투절단기에게서 흑요석이 좀 필요해. 그러고 나서 더 흥미로운 시약으로 넘어가자고...",
    },
    [26245] = {
        ["T"] = "악마의 불꽃",
        ["O"] = "불타는 평원 주변의 불꽃동족에게서 연기나는 심장 8개를 수집하십시오.",
        ["D"] =
        "좋아, 여기 용암 속에서 춤추는 저 임프들 본 적 있나? 징그러운 벌레 같은 놈들이지...\n\n놈들 중 하나를 죽이고 그 속을 본 적 있어? 심장이 있어야 할 자리에 이글거리는 돌덩이가 있더군.\n\n뭐, 자네 무기에 악마의 손길이 약간 닿는 걸... 두려워하지 않는다면 합금에 그걸 쓸 수 있지!",
    },
    [26246] = {
        ["T"] = "용의 불꽃",
        ["O"] = "불타는 평원 주변의 용, 용혈족, 또는 새끼용에게서 섬광 불꽃 샘 분비선 12개를 수집하십시오.",
        ["D"] =
        "용들이 어떻게 불을 뿜는지 궁금해한 적 있나? 대부분의 사람들은 마법이라고 하지만... 용의 내장은 연금술사들의 꿈이나 다름없지.\n\n화학 물질들이 계속 섞이고, 그 혼합물을 용이 입 밖으로 내뿜으면 공기에 닿아 점화되는 거야. 내가 이걸 말하는 데는 다 이유가 있지...\n\n그 기초 화학 물질 중 하나가 우리 무기를 위한 훌륭한 융제 역할을 해서, 흑요석 합금이 좀 더 잘 결합되게 만들어 줄 거야.\n\n자네가 찾아야 할 분비선은 붉은색에 깊은 색조를 띠고 거의 빛나는 듯한... 아, 그리고 심장 근처에 있어. 폐 옆에 있는 거 말고...\n\n이 근방의 불을 뿜는 놈들은 대부분 위험하니까, 도움이 좀 필요할지도 몰라. 놈들이 성숙할수록 분비선을 얻을 확률이 높아질 거야.",
    },
    [26247] = {
        ["T"] = "이글거리는 무장",
        ["O"] = "검은바위 나락으로 들어가 어둠괴철로 도시 중심부에 있는 검은 모루를 사용하여 무기의 기초를 단조하십시오.",
        ["D"] =
        "좋아... 내가 작고, 사소하고, 아주 쬐끔, 미세한 세부 사항 하나를 빼먹었을지도 모르겠군...\n\n합금은 만들어졌지만, 여기서 자네 무기를 실제로 단조할 수는 없어! 검은바위 나락에 있는 어둠괴철로 도시 중심부의 검은 모루에서 형태를 잡아야 하거든.\n\n알아, 나도 안다고! 난 그저 우리가 재료를 다 모으고 나면 자네가 좀 더 동기부여가 될 거라고 생각했을 뿐이야.\n\n그래서... 할 텐가? 도면 몇 장을 줄 테니 가지고 들어가게. 너무 쉬워서 아기도 따라 할 수 있을 거야! 가는 길에 뭘 원하는지 결정하고, 최선을 다해 형태를 잡은 다음 다시 이리로 가져오면 내가 과정을 마무리해 주지. 가는 길에 친구들도 좀 데려가라고.",
    },
    [26248] = {
        ["T"] = "정당한 보상",
        ["O"] = "정령의 건틀릿 세트를 아이언포지의 델리아나에게 가져가십시오.",
        ["D"] =
        "당신은 약속을 지켰고 먹스가 만든 장치를 가져왔습니다. 제 목숨을 구하는 데 계속 흥미를 느끼게 하려면 보상이 필요할 거라 생각합니다. 업그레이드하고 싶은 허리띠와 장갑 세트를 제게 가져오십시오. 보답으로 드리는 물건은 훨씬 더 뛰어날 것이라고 약속합니다.",
