        "발타라크의 영혼이 이 아뮬렛에 저장되어 있었소. 우린 탐욕에 눈이 멀어 어리석게도 그것을 세 조각으로 나누었고, 우리를 기다리는 저주가 무엇인지 전혀 몰랐소.\n\n발타라크의 주문을 막는 유일한 방법은 메달을 다시 하나로 맞추는 것뿐이오. 델리아나에게 돌아가서 남은 조각을 찾을 희망은 보들리뿐이라고 전하시오. 당신이 받기로 한 보상에 대해서도 그녀와 얘기해 보시오.\n\n나로선 마침내 평화롭게 쉴 수 있겠군. 행운을 비오. 행운이 아주 많이 필요할 거요!",
