    [26264] = {
        ["T"] = "계약 #1010: 마법 잔여물",
        ["O"] = "바라딘 요새에서 마법 잔여물이 담긴 병 4개를 수집하십시오.",
        ["D"] =
        "팀을 구성할 의향이 있는 계약자들을 위한 일거리가 있습니다. 축일의 마법을 부릴 시간입니다! 축일 장식 부서에서 온 일거리입니다.\n\n계약 #1010: 바라딘 요새 내에서 마법 잔여물 획득\n\n수량: 샘플 4개",
    },
    [26265] = {
        ["T"] = "비전의 원기 회복",
        ["O"] =
        "바라딘 요새에 있는 누군가에게 창조된 결정수를 만드는 법을 배운 다음, 실리더스의 용사의 안식처에 있는 날라에스 루나브랜치에게 창조된 결정수 20개를 가져가십시오.",
        ["D"] =
        "안녕하신가 $C! 자네의 도움이 필요하네.\n\n건조한 사막의 열기 때문에 사람도 짐승도 모두 목이 말라 있네. 톨 바라드의 키린 토가 가장 상쾌한 결정수를 창조하는 특별한 방법을 알고 있을지도 모른다는 소문을 들었지. 그곳으로 가서 어떻게 하는지 배워와 우리 식수를 다시 채워줄 수 있겠나?",
    },
    [26266] = {
        ["T"] = "어둠의 문학",
        ["O"] = "저주받은 땅의 황무지에 있는 이교도들에게서 어둠의 맹세단 고서 8권을 수집하십시오.",
        ["D"] =
        "당신은 호드 소속이시죠? 저도 진영에 합류하려고 생각 중인데, 모든 걸 고려해 볼 때 호드가 명백한 선택인 것 같습니다...\n\n모르그리아와 그녀의 상단이 여기 제 야영지에서 저와 마주쳤어요. 우리가 각자 왜 이곳에 있는지 설명했을 때, 글쎄요... 뒤틀린 황천이 맺어준 인연이랄까요 -- 우리의 목표가 완전히 일치한다는 걸 믿으시겠어요? 그래서 우린 잠정적으로 합의했습니다: 저는 호드 시민권을 대가로 펠스톤 요새에 대한 정보와 돌아다니는 저주에 대한 치료법을 제공하기로 말이죠.\n\n저주와 관련해서는, 성공할지 안 할지 모르는 계획이 하나 있습니다. 영구적인 해결책은 아니지만, 호드에게 잠시나마 휴식을 줄 수 있도록 노력해 보겠습니다. 단, $C만이 줄 수 있는 도움이 있다면 말이죠.\n\n근처에 있는 이교도들에게서 고서가 필요합니다. 특히 마법이나 의식을 행하는 자들의 것이어야 해요. 폭력배나 집행자는 안 됩니다. 고서가 두꺼울수록 더 좋습니다. 고서를 가져오시면 더 자세히 설명해 드리겠습니다.",
    },
    [26267] = {
        ["T"] = "역 고통",
        ["O"] = "펠스톤 요새 안의 흑마법사들에게서 고통의 문양을 얻으십시오.",
        ["D"] =
        "<이잘니르는 구부정하게 앉아 오랫동안 탁한 눈으로 흑마법서를 훑어봅니다. 마침내, 그가 당신을 올려다봅니다.>\n\n혹시 이렇게 생긴 걸 본 적 있으십니까? 두루마리나 돌에 적힌 것 말입니다.\n\n<이잘니르가 사악해 보이는 룬 주위를 둘러싸고 있는 혼돈의 문자로 가득 찬 페이지를 보여줍니다.>\n\n흑마법사들은 이걸 이용해 제가 생각지도 못한 방식으로 저주, 즉 지옥불을 가지고 장난을 치고 있습니다. 하, 저 멍청이들은 심지어 이걸 연금술에도 쓰고 있어요.\n\n계속 진행하려면 이 문양 중 하나가 필요합니다. 펠스톤의 흑마법사들 말고는 이런 걸 가지고 있을 사람이 없겠죠. 요새는 혼자 가기엔 너무 위험하니 친구들을 데려가세요. 당신이 돌아올 때까지 전 계속 읽고 있겠습니다.",
    },
    [26268] = {
        ["T"] = "저주 다시 쓰기",
        ["O"] = "펠스톤 요새 주변에서 쿠지르 흑잉크 병 5개를 수집하십시오.",
        ["D"] =
        "여기 문양의 비문이 보이십니까? 쿠지르 흑잉크로 쓴 겁니다. 흑마법사조차도 구하기 힘들 정도로 아주 강력하죠. 악마의 피가 이 잉크의 주성분이라, 빛을 집어삼키는 검은 광택을 띱니다.\n\n흠... 녀석들이 사용하는 어휘는 아르거스 결사단 조직에서 유래한 것이군요. 제 입맛에 맞게 조정할 수 있을 정도로 읽을 수는 있지만, 제게는 흑잉크가 없습니다.\n\n<이잘니르가 기대에 찬 미소로 당신을 바라봅니다.>\n\n이것 좀 구해주시겠습니까? 흑마법사와 그들의 조수들이 가지고 있을 겁니다. 장담하건대 요새 주변의 흑마법사 막사에서 찾을 수 있을 겁니다. 오두막에도 몇 개 있을 수 있고요.",
    },
    [26269] = {
        ["T"] = "영혼 연료",
        ["O"] = "펠스톤 요새 안에 있는 이교도들의 시체에서 이잘니르를 위해 그롬볼라 영혼석 1개를 찾으십시오.",
        ["D"] =
        "이 문양을 쥐었을 때 어떤 느낌이 드셨습니까? 메스꺼움? 긁을 수 없는 가려움?\n\n<이잘니르가 룬에 손을 얹고 눈을 감습니다.>\n\n제게는 머리를 두드리는 듯한 느낌이 듭니다. 마치... 누군가 감방 창살을 흔드는 것 같군요. 펠스톤 뒤편의 어떤 동굴에서 강력한 영혼석을 몰래 빼내왔다는 소문을 들었습니다... 이 문양이 어떻게 충전되었는지 짐작하는 건 그리 비약적인 추론이 아니죠.\n\n그 안의 오크들은 다른 누구와도 어울리지 않고 완전히 다른 차원에 있습니다. 하지만 가끔 도둑질이나 거래, 또는 단순한 실수로 인해 그들이 탐내는 돌이 엉뚱한 곳에 떨어지기도 하죠.\n\n어쩌면 이미 몇 개 보셨을지도 모르겠군요? 제 계획이 결실을 맺으려면 적어도 하나는 필요합니다. 펠스톤 주변의 흑마법사들이 가지고 있을 겁니다.\n\n만약 무모할 정도로 용기가 있다면 동굴 자체를 시도해 볼 수도 있습니다. 펠스톤 중심부 서쪽에 있고, 입구가 거대한 뼈로 둘러싸여 있죠. 전 안에는 들어가 본 적이 없지만, 이야기는 들었습니다...",
    },
    [26270] = {
        ["T"] = "먼 붕괴",
        ["O"] = "남쪽 멀리 펠스톤의 맨 위층 테라스에 있는 높은 제단의 소환진에서 변형된 고통의 문양을 사용하십시오.",
        ["D"] =
        "마지막 행동을 할 시간입니다. 이제 당신 일행은 펠스톤의 위험에 익숙해졌으니, 이것도 그리 어렵지 않을 겁니다.\n\n계획은 이렇습니다: 수정된 문양을 펠스톤 남부의 가장 높은 테라스에 있는 제단으로 가져가서 소환진에 사용하십시오. 그것은 어둠의 마법을 뿜어내는 보라색 룬입니다. 이론상으로는, 이 문양이 대상들에게 걸린 저주를 찢어내 소환진으로 되돌려 보낼 것입니다 -- 말씀드렸듯이 영구적인 해결책은 아닙니다만.\n\n이 일을 했을 때 어떤 결과가 초래될지 저도 모르니, 모든 상황에 대비하십시오. 행운을 빕니다, $N.",
    },
    [26271] = {
        ["T"] = "고대 보석 연마술",
        ["O"] = "별똥별 마을의 엘레노어 문글로우가 여명의 설원에 있는 커다란 명가 폐허 중 한 곳에서 명가 장인 도구함을 회수해 달라고 합니다.",
        ["D"] =
        "안녕하세요, 여명의 설원이 마음에 드시길 바라요! 어둠해안의 우울함에서 벗어나 이렇게 건조한 공기를 쐬니 정말 좋아요. 모험가이시죠?\n\n저는 수습 보석세공사인데, 이 지역 주변에 널려 있는 예쁜 수정들 때문에 여기 왔어요. 소문에 따르면 하늘에서 떨어진대요 -- 아마 마을 이름도 거기서 유래했을 거예요! 하지만 제가 가져온 도구로는 수정들을 깎을 수가 없어요. 진짜예요, 해봤다니까요! 제가 가진 가장 좋은 연마기가 부러져버렸어요...!\n\n이 수정들이 최근에 생긴 건 아닐 테니, 분명 고대 명가 사람들도 수정 깎는 방법을 알고 있었겠죠? 당신이 찾을 수 있는 건 무엇이든 다 살게요! 켈테릴은 남쪽에 있고... 텔레스아란은 여기서 북동쪽인데, 그곳으로 가는 길에 무서운 할머니가 한 분 계세요.",
    },
    [26272] = {
        ["T"] = "수리가 필요해요!",
        ["O"] = "명가 장인 도구함을 눈망루 마을의 펠노크 스틸스프링에게 전달하십시오.",
        ["D"] =
        "흠... 이 도구함은 정말 오래됐네요... 아직은 사용하기가 좀 꺼림칙해요.\n\n<엘레노어가 이마를 긁적이며 놀랍도록 날카로운 눈으로 장인 도구함을 유심히 살펴봅니다.>\n\n아, 알겠어요! 눈망루 마을에서 만난 고블린에게 보급품을 좀 빌려준 적이 있어요. 그 사람은 기계공학자이고 저한테 빚을 졌죠! 마침 그쪽으로 가시는 길인가요? 이걸 그 사람한테 좀 가져다주실 수 있나요? 제가 보냈다고 하고, 복원해 주면 정말 고맙겠다고 전해주세요.",
    },
    [26273] = {
        ["T"] = "별똥별",
        ["O"] = "별똥별 마을의 엘레노어 문글로우가 여명의 설원 주변에서 별똥별 수정 10개를 모아 달라고 합니다.",
        ["D"] =
        "정말 기대되네요, $N! 빨리 보석을 만들고 싶어 죽겠어요. 펠노크가 훌륭한 기계공학자이긴 하겠지만, 그렇게 오래된 유물을 복원하는 건 누구에게나 힘든 일일 거예요.\n\n그동안 우리가 찾을 수 있는 한 많은 수정을 모아보는 건 어때요? 모든 일이 다 끝나면 제가 보석을 만들어 드릴게요! 공평하죠?",
    },
    [26274] = {
        ["T"] = "펠노크의 솜씨",
        ["O"] =
        "눈망루 마을의 펠노크 스틸스프링에게서 복원된 장인 도구함을 받아 여명의 설원의 별똥별 마을에 있는 엘레노어 문글로우에게 돌아가십시오.",
        ["D"] =
        "좋아요, $N. 도구함을 가지러 당신과 함께 가고 싶지만, 이 많은 보석들을 두고 가려니 영 마음이 안 놓여서요... 누가 훔쳐가기라도 하면 어떡해요?\n\n당신에게 너무 의지해서 죄송해요. 꼭 보답할게요, 약속해요! 아니, 제가 게을러서 그런 게 아니라니까요!",
    },
    [26275] = {
        ["T"] = "당신을 위한 선물!",
        ["O"] = "엘레노어 뒤에 있는 집 안의 상자에서 보석 세팅 꾸러미를 엘레노어에게 가져다주십시오.",
        ["D"] =
        "<엘레노어가 조심스럽게 수정 중 하나를 연마하려 시도합니다.>\n\n허... 펠노크를 불러서 이 자질구레한 것들이 어디에 쓰는 건지 설명 좀 해달라고 해야 할까 봐요. 다행히 도구들은 잘 작동하니까 이제 당신의 보석을 깎아 드릴게요!\n\n오래 안 걸릴 거예요! 제 뒤에 있는 집 안 상자에 세팅 꾸러미가 있어요. 마지막으로 그 꾸러미 좀 가져다주실래요? 제발요?!",
    },
    [26276] = {
        ["T"] = "방진 작전",
        ["O"] = "검은바위 나락의 방진에게서 흑요석 핵을 회수하여 스톰윈드의 침묵의 쇼니에게 가져가십시오.",
        ["D"] =
        "우린 아직도 놈리건으로 뚫고 들어가 도시의 피해를 복구할 효율적인 방법을 찾고 있어요. 우리에게 필요한 건 더 많은 동력이에요!\n\n제 사촌이 검은바위 나락에 있는 어느 연구실에서 일자리를 구했대요. 거기서 흑요석 핵을 동력으로 하는 골렘들을 만들고 있다더군요. 제가 그 핵 중 하나를 조사해서 우리 일에 쓸 수 있을지 알아보고 싶어요.\n\n사촌 말로는 흑요석 핵을 사용하는 방진이라는 오래된 골렘이 있다고 하더라고요. 곧 폐기될 예정이니까 -- 당신이 그 핵을 훔쳐오더라도 아무도 눈치채지 못할 거예요!",
    },
    [26277] = {
        ["T"] = "불꽃의 주술사",
        ["O"] = "검은바위 나락에서 화염술사 로어그레인을 처치한 후, 운고로 분화구의 마샬의 야영지에 있는 야루니 플레임워처에게 돌아가십시오.",
        ["D"] =
        "대지고리회에서 제가 맡은 책임 중에는 주술사들의 불꽃 에너지 사용 -- 그리고 오용 -- 을 감시하는 일도 포함됩니다. 최근 아주 먼 곳인 검은바위 산에서 거친 불꽃의 기운이 당겨지는 것을 느꼈습니다.\n\n대지고리회의 전 회원이 산 깊숙한 곳에 사는 검은무쇠 드워프들과 어울리며 주술사들이 사용하는 불의 원소 에너지와 마법사들이 사용하는 비전 화염 마법을 섞는 실험을 하고 있는 것 같습니다.\n\n이러한 원소의 타락은 반드시 막아야 합니다. 저는 원시 마법에 대한 연구를 계속하기 위해 이곳에 남아야 하지만 -- 아마 당신과 몇몇 동료들이라면 이 이단 주술사를 처치할 수 있을지도 모릅니다.\n\n그의 이름은 토나카 로어그레인입니다.",
    },
    [26278] = {
        ["T"] = "불의 군주의 부관들",
        ["O"] = "검은바위 나락에서 불의군주 록코르와 사자 화염채찍을 처치한 후, 아즈샤라의 군주 히드락시스에게 돌아가십시오.",
        ["D"] =
        "당신은 우리 적을 무찌르고 물의 군주들의 대의를 발전시키기 위한 임무를 수행할 수 있음을 제게 증명했습니다. 하지만 지금까지 당신은 하급 적들만 상대해 왔죠... 이제 더 큰 기술과 위험이 따르는 임무를 맡을 때가 되었습니다.\n\n검은바위 산 깊은 곳에서 검은무쇠 드워프들이 불의 군주의 하수인들과 음모를 꾸미고 있습니다. 불의 군주의 수석 사절 두 명을 처치하십시오: 바로 불의군주 록코르와 사자 화염채찍입니다.\n\n이 임무를 완수하여 우리의 대의에 대한 당신의 헌신을 제게 증명하십시오.",
    },
    [26279] = {
        ["T"] = "더 좋은 물건",
        ["O"] = "검은바위 나락 깊은 곳에서 마그무스를 처치한 후, 불타는 평원의 모건의 망루에 있는 랄리우스에게 돌아가십시오.",
        ["D"] =
        "윙키 대장은 지는 걸 못 참아. 아주 화가 났다고 내가 말했지!\n\n윙키는 검은무쇠 드워프들이 좋은 물건을 가지고 있다고 했지만 난 아니라고 했어! 틀림없이 더 좋은 게 있을 거라고.\n\n그리고 그렇다더군.\n\n그리고 그 이름은 마그. 무스. 라고 해.\n\n마그. 무스.\n\n마그. 무스. 마그무스! 죽여버려! 불로는 죽이지 마.",
    },
    [26280] = {
        ["T"] = "비뚤어진 제자",
        ["O"] = "사냥개조련사 그렙마르를 처치하고 그의 사냥꾼 학교 졸업장을 회수하여 스톰윈드의 울피르 아이언비어드에게 가져가십시오.",
        ["D"] =
        "내가 이런 말을 하게 될 줄이야! $N, 미안하지만 자네 같은 모험가의 도움이 필요하네.\n\n방금 내 옛 제자 중 한 명이 검은바위 나락에서 악마의 사냥개들을 조련하고 있다는 소식을 들었네. 녀석은 악마를 처치해야지, 놈들과 어울리면 안 된다고!\n\n내가 수여한 졸업장을 취소하고 싶네 -- 녀석의 이름은 그렙마르야 -- 하지만 우리 아이언포지 드워프들은 검은무쇠 도시에 환영받지 못하네. 자네가 이 나쁜 소식을 전하고 졸업장을 회수해 올 수 있겠나?",
    },
    [26281] = {
        ["T"] = "영원의 불꽃",
        ["O"] = "영원의 불씨를 스톰윈드의 가킨 다크바인더에게 가져가십시오.",
        ["D"] =
        "불씨를 살펴보니 마치 살아있는 것처럼 당신의 손안에서 박동치는 것이 느껴집니다. 가킨 다크바인더가 이런 기이한 물건을 다뤄본 경험이 있어서 더 자세히 조사할 수 있을지도 모른다는 이야기가 떠오릅니다.\n\n그는 스톰윈드의 마법 지구에 있는 어둠의 희생양 선술집에서 찾을 수 있습니다.",
    },
    [26282] = {
        ["T"] = "오래된 빚",
        ["O"] = "은여울 광산 안에서 현장감독 그림개쉬를 찾아 처치하십시오.",
        ["D"] =
        "질문을 너무 많이 하지 않고 일자리를 맡을 수 있는 진취적인 사람처럼 보이시네요. 딱 제가 찾던 타입이에요.\n\n여기 스프링소켓에 정착하기 전에 전 한 장소에서 다른 장소로 물건을 나르는 사업을 했었죠. 그때는 세관이나 서류 작업의 까다로운 부분들을 원활하게 처리해주는 \"파트너\"가 있었거든요. 그러다 투자개발회사가 끼어들어 그들을 제 밑에서 빼갔고, 전체 조직이 무너져버렸어요. 전 이 사막에 발이 묶이고 말았죠!\n\n일이 잘 풀리긴 했지만, 고블린은 그런 원한을 쉽게 잊지 않는답니다. 저는 제 사업을 돌보기 위해 이곳에 머물러야 하지만, 당신이 은여울 광산에 있는 현장감독 그림개쉬를 기꺼이 손봐주신다면 아주 기쁘게 보상해 드리겠습니다.",
    },
    [26283] = {
        ["T"] = "아조타 유물",
        ["O"] = "아이언포지 내에서 지식이 풍부한 역사학자를 찾으십시오.",
        ["D"] =
        "당신 앞에는 헤아릴 수 없이 오래된 고대 인간의 형태를 띤 낡고 풍화된 우상이 있습니다. 지식이 풍부한 역사학자라면 이 물건에 흥미를 느낄지도 모릅니다. 가장 유명한 역사학자는 아이언포지 탐험가의 전당에서 찾을 수 있습니다.",
    },
    [26284] = {
        ["T"] = "아조타 유물",
        ["O"] = "은여울 광산 내에서 아조타 유물을 수집하십시오.",
        ["D"] =
        "수천 년 전 트롤들이 아조타라는 이름으로만 알려진 집단과 전쟁을 벌였다고 합니다. 그들에 대해 알려진 것은 거의 없지만, 저를 포함한 몇몇 괴짜 큐레이터들은 눈에 보이는 것 이상의 많은 것이 있다고 믿고 있습니다.\n\n당신이 한 말이 사실이고 투자개발회사가 그들의 유물 은닉처를 우연히 발견한 것이라면, 그걸 제게 가져오셔야만 합니다. 그것들은 박물관에 있어야 해요! 그들의 광산으로 파고들어가서 가능한 한 많이 모아주시겠습니까?",
    },
    [26285] = {
        ["T"] = "디그의 잃어버린 파이프",
        ["O"] = "은여울 광산 내에서 머클러크에게서 디그의 잃어버린 파이프를 회수하여 무법항에 있는 그에게 가져가십시오.",
        ["D"] =
        "몇 가지 나쁜 버릇도 없는 인생이 무슨 인생이겠수, 안 그래 $C?\n\n슬프게도, 마을 동쪽 해변에 나갔다가 내가 제일 좋아하는 파이프를 잃어버린 후로는 한 모금도 못 피웠어. 내가 좀 심하게 취해 있었지, 무슨 말인지 알 거요. 그리고 정신을 차렸을 때, 웬 커다란 멀록 한 놈이 파이프를 가지고 도망치는 걸 봤다니까!\n\n그 멀록 놈이 은여울 광산에 집을 마련한 것 같더군. 혹시 그쪽으로 갈 일이 있으면 내 파이프 좀 가져다주슈, 정말 고맙게 생각할 테니까.",
    },
    [26286] = {
        ["T"] = "현장감독 처치",
        ["O"] = "은여울 광산 내에서 투자개발회사 현장감독을 처치하십시오.",
        ["D"] =
        "투자개발회사는 그곳에 거대한 광산 시설을 가지고 있어요! 그러니 제가 노랫소리 수정을 구하려고 고군분투하는 것도 무리가 아니죠. 그 정도 규모의 작전이라면 정글의 근간을 무너뜨릴 가능성이 큽니다. 상황이 통제 불능이 되기 전에 누군가 처리해야 해요!\n\n제 부탁 좀 들어주세요. 가서 경쟁자들을 제거하고 은여울 광산 현장감독의 머리를 제게 가져오세요. 그가 사라지면, 제가 여기서 짭짤한 이익을 얻기 시작할 수 있을 뿐만 아니라, 그 과정에서 정글이 파괴되는 것도 막을 수 있을 테니까요!",
    },
    [26287] = {
        ["T"] = "오색 비늘",
        ["O"] = "은여울 광산 안의 바실리스크에게서 오색 비늘을 수집하여 무법항의 드리즐릭에게 가져가십시오.",
        ["D"] =
        "제가 엑셀시어 부츠 라인 주문을 처리하는 데 당신이 아주 큰 도움을 주셨으니, 제 실험적인 새 디자인을 도와주셔야겠습니다.\n\n악어 가죽을 넘어 바실리스크 가죽으로 영역을 확장하려고 합니다. 그냥 평범한 바실리스크가 아니라 최고 중의 최고를 원합니다. 투자개발회사가 은여울 광산에서 크고 빛나는 특별한 바실리스크를 찾아냈다는 소문을 들었습니다. 바로 제가 필요로 하는 녀석입니다. 그곳으로 가서 그 비늘을 제게 가져오십시오!",
    },
    [26288] = {
        ["T"] = "도구 되찾기",
        ["O"] = "은여울 광산 내의 투자개발회사에게서 도구 20개를 회수하십시오.",
        ["D"] =
        "그러니까 상황은 이렇습니다, $N. 몇 달 전에 가시덤불 골짜기에서 진행되는 어떤 작전을 위해 고품질의 도구들을 만들어 달라는 의뢰를 받았죠. 현장감독은 그걸 은여울... 은여울 광산이라고 불렀어요!\n\n그들이 뭘 파내고 있었는지는 모르겠지만, 광산에 인력을 쏟아붓고 광부들에게 도구를 공급하는 데 금화를 아끼지 않았죠.\n\n그 이후로 전 이곳 타나리스에서 훨씬, 훨씬 더 수익성 높은 의뢰를 받았고, 그 주문을 맞추려면 제가 예전에 만든 모든 도구를 되찾아야 합니다.\n\n이 일을 우리 둘만의 비밀로 해주신다면, 은여울 광산 광부들에게서 제가 만든 도구들을 \"회수\"해 올 수 있을 거라고 생각합니다. 그러면 우리 모두가 행복해지겠죠. 음, 은여울 얼간이들만 빼고, 하하. 어떻습니까?",
    },
    [26289] = {
        ["T"] = "이탈자 나가",
        ["O"] = "은여울 광산 안에서 조수결속사 점쟁이 5명, 조수결속사 전사 5명, 그리고 그나시를 처치하십시오.",
        ["D"] =
        "여왕님의 오랜 하수인으로서 나는 불충을 혐오한다네. 하지만 타락한 심연의 하수인들이 길을 잘못 이끌면 빗나간 나가들은 길을 잃고 말지.\n\n작은 심부름을 좋아하는군, 그렇지 않은가, 필멸자여? 이건 어떤가: 고블린들이 굴을 파고 있는 바다 건너편으로 여행하게나. 그곳은 우리가 직접 가기엔 너무 건조한 내륙 깊숙한 곳이라네. 고블린들은 그나시라는 자가 이끄는 제멋대로인 나가 무리의 소굴에 우연히 발을 들여놓게 되었지. 그나시의 하수인들을 처치하고 그의 존재를 끝내주게.\n\n여왕에게 도전하는 자는 그 누구도 살려둘 수 없으니까.",
    },
    [26290] = {
        ["T"] = "트롤 유물",
        ["O"] = "오그리마 내에서 지식이 풍부한 전승지기를 찾으십시오.",
        ["D"] =
        "당신 앞에는 헤아릴 수 없이 오래된 고대 인간의 형태를 띤 낡고 풍화된 우상이 있습니다. 지식이 풍부한 트롤 전승지기라면 이 물건에 흥미를 느낄지도 모릅니다. 가장 유명한 전승지기는 오그리마 정기의 골짜기에서 찾을 수 있습니다.",
    },
    [26291] = {
        ["T"] = "트롤 유물",
        ["O"] = "은여울 광산 내에서 트롤 유물을 수집하십시오.",
        ["D"] =
        "전설에 따르면 수천 년 전에 우리 트롤들이 아조타라는 이름으로만 알려진 집단과 전쟁을 치렀다고 해. 전투에서의 집요함을 빼면 놈들에 대해 알려진 건 거의 없지. 난 여기에 눈에 보이는 것 이상으로 많은 것이 숨겨져 있다고 믿어.\n\n네가 한 말이 사실이고 투자개발회사가 그들의 유물 은닉처를 우연히 발견한 것이라면, 그걸 제게 가져와야 해. 놈들의 광산으로 파고들어가서 가능한 한 많이 모아주겠어?",
    },
    [26292] = {
        ["T"] = "터널 괴물",
        ["O"] = "은여울 광산에서 알리스 타이드시커가 묘사한 괴물을 찾아 파괴하십시오.",
        ["D"] =
        "엘프치고는 특이하다는 건 알지만, 전 바다를 아주 좋아해요. 무법항 동쪽 얕은 물에 떠다니며 물고기나 새들과 친구가 되어 수많은 시간을 보냈죠. 단 한 번도 두려움을 느낀 적이 없었는데... 최근에 말이에요.\n\n평소보다 북쪽으로 더 멀리 헤엄쳐 가고 있었는데, 해저에서 거대한 미지의 촉수가 솟아오르더니 제 다리를 움켜쥐지 뭐예요! 그 괴물이 저를 수중 터널로 끌어들이려 했지만, 전 필사적으로 저항했죠. 마침내 괴물은 저를 놔주고 터널 속으로 사라졌고... 터널은 괴물 뒤에서 무너져 내렸어요.\n\n제 생각엔 그 괴물이 마을 북쪽 언덕에 투자개발회사가 세운 발굴 현장에 살고 있는 것 같아요. 그들에게 경고하려고 했지만 제 말을 무시하더군요. 제발, 그 광산에 들어가시거든 괴물을 조심하세요! 다른 사람이 무방비 상태로 괴물과 마주치는 건 생각만 해도 끔찍해요.",
    },
    [26293] = {
        ["T"] = "왕에게 어울리는",
        ["O"] = "페랄라스 전역을 돌아다니는 방황하는 숲 걸음꾼들에게서 걸음꾼 나뭇가지를 모으십시오.",
        ["D"] =
        "그리 바빠 보이지는 않는데... 작은 부탁 하나 할까? 스팀휘들 무역회사에서 나를 여기로 보내 작은 내기를 하나 걸게 했거든. 글룩은 예전의 아버지처럼 자신이 왕 고르독이 될 거라고 생각하지만, 현재 왕은 글룩을 배신자로 낙인찍고 혈투의 전장에서 쫓아냈어. 우리는 글룩이 친구들의 약간의 도움만 있다면 왕이 될 자질이 있다고 생각해.\n\n나는 다가올 전투에서 글룩이 쓸 수 있는 강력한 무기를 만들어 줄 계획이야. 넌 내게 필요한 부품들을 전부 구해다 줘야 해. 어때, 할래?\n\n가장 먼저 필요한 건 근처의 숲 걸음꾼들에게서 구할 수 있는 특별한 종류의 마법 목재야. 금속만큼이나 단단하면서도 가벼워서 손잡이로 아주 훌륭하지.",
    },
    [26294] = {
        ["T"] = "왕에게 어울리는",
        ["O"] = "글룩의 소굴에 있는 비고를 위해 저습지 대마 8다발을 수집하십시오.",
        ["D"] =
        "이 지역 주변에는 매우 튼튼한 밧줄을 만드는 데 사용할 수 있는 특별한 대마가 자라지. 이 밧줄이 있으면 왕이 손아귀의 힘이 빠지더라도 무기를 놓치는 일이 없을 거야!\n\n오우거들은 참 이상해. 소문에 따르면 이전 왕이었던 글룩의 아버지가 이 대마를 한 다발 피우더니 왕좌에서 어슬렁어슬렁 떠나버렸다고 하더라고. 그가 오우거들의 시야에서 사라지자마자, 그들은 그냥 새로운 왕을 선포해 버렸고, 그렇게 글룩의 왕위 계승권은 끝나버렸지.\n\n어쨌든, 이 대마는 페랄라스의 강 근처에서 자라고 숲 전역에서 발견할 수 있어.",
    },
    [26295] = {
        ["T"] = "왕에게 어울리는",
        ["O"] = "페랄라스의 약해진 야수들에게서 야수 피 담긴 유리병 20개를 수집하십시오.",
        ["D"] =
        "내 계획의 중요한 부분은 정제된 철과 나중에 네가 수집해 올 특수 합금을 섞는 거야. 하지만 이 지역에서 철을 구하기란 아주 힘들지!\n\n그래도 해결책이 있어. 철이 많이 필요한 건 아니니까, 페랄라스에 있는 야수들에게서 추출하면 되거든.\n\n이건 헤모백 맥스라고 부르는 작은 장치야. 야수를 약하게 만든 다음 그 피 속에 있는 철분을 빨아들이는 거지! 유리병이 충분히 모이면 가공할 철이 생길 거야. 슬프게도 유리병 하나당 철분 양이 너무 적어서 구식 방법으로 야생 동물들을 마구잡이로 학살할 수밖에 없겠어.",
    },
    [26296] = {
        ["T"] = "왕을 위한 무기",
        ["O"] = "페랄라스의 꿈틀거리는 심연에서 실리시드 합금 덩어리 12개를 수집하십시오.",
        ["D"] =
        "이제... 덜 유쾌한 일에 대해 이야기해보죠. 당신이 이 일에 헌신한다고 느낄 때까지 이 부탁을 미룬 이유가 있습니다. 이곳에서 남동쪽으로 가면 꿈틀거리는 심연을 찾을 수 있습니다. 그곳은 실리시드라고 불리는 잽싼 야수들의 서식지입니다.\n\n가끔 녀석들이 광석을 먹이로 착각하고 끈적끈적한 진흙으로 덮는다는 건 잘 알려진 사실입니다. 녀석들이 그것을 완전히 소화하고... 배설하면... 어떻게 되는지 아십니까?\n\n글쎄요, 우리가 얻게 되는 건 어찌 된 일인지 새로운 합금을 형성하는 어울리지 않는 광석들의 조합입니다. 어떻게 그런 일이 일어나는지는 묻지 마십시오. 저도 그 속을 들여다보고 싶진 않으니까요. 제가 바라는 건 글루크의 새 무기를 만들 합금을 당신이 구해오는 것뿐입니다.",
    },
    [26297] = {
        ["T"] = "왕을 위한 무기",
        ["O"] =
        "이글거리는 협곡의 대지 및 불의 정령에게서 소용돌이치는 녹은 바위와 맹렬한 불꽃의 정수를 수집하십시오.",
        ["D"] =
        "마침내 이 왕의 무기를 제작할 수 있는 날이 멀지 않았소. 이제 문제는 간단하오. 열을 만들고 유지하는 것이지. 이곳의 가열로는 오우거들이 흔히 사용하는 품질이 낮은 무기를 대량으로 찍어내는 데는 적합하지만, 이 합금들을 녹여 철과 결합할 만큼 충분히 뜨겁지는 않소.\n\n불행히도 이는 우리가 직접 열을 구해야 한다는 뜻이오. 동부 왕국의 동쪽 멀리에 이글거리는 협곡이 있소.\n\n그곳은 용암이 흐르고 바위가 녹으며 정령들이 날뛰는 곳이지. 그곳의 불타는 정수들을 모아 내게 가져다주시오.\n\n그 정수들이 있으면 우리의 요구를 감당할 수 있도록 이 가열로를 강화할 수 있을 거요.",
    },
    [26298] = {
        ["T"] = "왕을 위한 무기",
        ["O"] = "페랄라스의 해안에 있는 물의 정령에게서 소금기 있는 냉각의 정수를 수집하십시오.",
        ["D"] =
        "열은 이 과정의 절반에 불과하오, $c. 우리는 불길을 진정시키고 열을 관리하여 합금이 천천히 녹고 융합되어 완전히 새로운 것으로 변하도록 해야 하오. 다행히도 필요한 것을 구하러 멀리 보낼 필요는 없소.\n\n페랄라스 해안에 가면 바다 자체의 냉각 정수를 흠뻑 머금은 물의 정령들을 찾을 수 있을 거요. 가서 가능한 한 많이 모아 오시오. 주둔지 전체를 태워 먹지 않으려면 단조 과정에서 그것을 사용해야 하니까!",
    },
    [26299] = {
        ["T"] = "왕을 위한 무기",
        ["O"] = "마라우돈에 입장하여 녹시온을 처치하십시오. 그의 정수를 수집하여 페랄라스에 있는 비고에게 가져가십시오.",
        ["D"] =
        "좋소, 편하게 하루를 보낼 생각은 버리시오. 우리가 필요한 것을 얻을 수 있다고 들은 곳은 단 한 곳뿐이오. 켄타우로스의 발상지인 마라우돈이지.\n\n주황색 동굴 깊은 곳에서 \"녹시온\"이라 불리는 매우 강력한 물의 정령을 찾을 수 있을 거요. 그의 정수는 이렇게 강력한 무기를 위한 훨씬 더 가치 있는 시약이 될 것이오.\n\n나를 위해 그 정수를 구하다가 목숨을 잃거나 팔다리를 잃을 위험을 감수하겠소? 장담하건대, 글루크가 혈투의 전장을 지배하게 되면 이 모든 것이 보상받을 것이오!",
    },
    [26300] = {
        ["T"] = "왕을 위한 무기",
        ["O"] = "디와 덤이 글루크의 새 무기를 단조하는 동안 그들을 식혀주십시오.",
        ["D"] =
        "내 뒤에 있는 이 굼뜬 멍청이들이 디와 덤이오. 똑똑한 것과는 거리가 멀지만, 커다란 망치로 모루를 내리치는 데는 소질이 있지. 내 생각에 이 녀석들은 평균적인 대장장이만큼은 똑똑한 것 같소.\n\n이 녀석들이 무기를 단조하고 열기에 고통받는 동안, 자네가 녹시온의 정수를 사용해 불길을 진정시키고 이들을 식혀주어야 하오. 오우거들이 과열되게 놔두지 마시오. 그렇지 않으면 이 모든 수고가 헛수고가 될 테니까.",
    },
    [26301] = {
        ["T"] = "왕을 위한 무기",
        ["O"] = "글루크의 새 무기를 전달하십시오.",
        ["D"] =
        "이제 이 용사의 무기를 글루크에게 바칠 시간이오. 나를 대신해 영광을 누리겠소?\n\n그는 근처 동굴에 있소.",
    },
    [26302] = {
        ["T"] = "타락의 근원",
        ["O"] = "마라우돈 안에 있는 공주 테라드라스의 샘플을 수집하여 스퀴글코드 전초기지에 있는 셀라이 듀라이트에게 가져가십시오.",
        ["D"] =
        "구전에 따르면 이 땅은 한때 울창했다고 합니다. 하지만 마라우돈 내에서 공주 테라드라스가 켄타우로스를 풀어놓은 탓에 우리가 사방에서 보는 이 땅을 만든 재앙이 발생했죠. 제 목표는 여기 있는 디비와 켈리의 도움을 받아 이 땅을 복원하는 것입니다.\n\n우리가 더 조사해야 할 한 가지 핵심 요소는 공주 자신의 샘플입니다. 그녀를 처치하면 더 이상의 타락을 끝낼 수 있을 뿐만 아니라, 그녀를 면밀히 연구함으로써 타락을 되돌릴 수도 있을 것입니다.\n\n저를 대신해 마라우돈으로 들어가 샘플을 회수해 주십시오. 후하게 보상해 드리겠습니다.",
    },
    [26303] = {
        ["T"] = "핵에 대한 조율",
        ["O"] = "아즈샤라 해안가의 섬에 있는 군주 히드락시스를 찾아가십시오.",
        ["D"] =
        "오 이런, $N 아니오. 전에 당신이 나를 지나쳐 가는 것을 본 적이 있지. 이곳의 독특함을 전혀 눈치채지 못한 채 말이야. 내가 서 있는 곳에서 두 걸음도 채 떨어지지 않은 곳에 검은바위 산 깊은 곳, 화산 심장부라고 알려진 곳으로 이어지는 안정적인 차원의 균열이 있소. 이곳은 거대한 악의 장소이기도 하지만 당신 같은 모험심 강한 이들에게는 큰 영광의 장소이기도 하지. 한번 보시겠소?\n\n당연히 그러고 싶겠지. 하지만 당신 같은 필멸자가 도움 없이 그곳에 모험을 떠나는 것은 너무 위험하오. 다행히도 내가 올바른 방향으로 등을 밀어주기 위해 여기 있소.\n\n아즈샤라 해안을 따라 거주하는 히드락시안 물의 군주들을 찾아보시오. 그들은 당신의 성공에 큰 관심이 있소.",
    },
    [26304] = {
        ["T"] = "핵에 대한 조율",
        ["O"] =
        "화염초 꽃잎 5개, 겨울서리풀 5개, 불의 원소 1개, 물의 원소 1개를 아즈샤라 해안가의 섬에 있는 군주 히드락시스에게 가져가십시오.",
        ["D"] =
        "화산 심장부는 우리의 철천지원수인 불의 정령들의 둥지라네. 이대로 방치하면 녀석들은 힘을 키워 아제로스 전체를 불태울 거요.\n\n산의 맹렬한 중심부는 불의 군주와 동맹을 맺은 검은무쇠 드워프들에게조차 너무 뜨겁소. 하지만 당신이 내 지시에 따른다면 화산 중심부의 강렬한 열기를 견딜 수 있는 축복을 내리겠소.\n\n먼저 의식에 소모할 원소 재료가 필요하오. 불의 원소 1개와 물의 원소 1개, 화염초 꽃잎 몇 개, 그리고 겨울서리풀 몇 개를 모아오시오. 직접 이 세계에서 구할 수 없다면, 필멸자들이 어떤 상업 중심지에서 이것들을 판다고 하더군.",
    },
    [26305] = {
        ["T"] = "핵에 대한 조율",
        ["O"] =
        "토라이드의 불타는 핵과 키나이스의 얼어붙은 핵을 아즈샤라 해안가의 섬에 있는 군주 히드락시스에게 가져가십시오.",
        ["D"] =
        "다음으로 우리는 불과 얼음에 조율된 강력한 존재들의 주입된 정수가 필요하오.\n\n불타는 평원의 폭풍의 제단 근처 용암 폭포에서 토라이드를 찾을 수 있을 거요. 그를 처치하고 불타는 핵을 회수하는 것은 세상에 큰 축복이 될 것이오.\n\n냉기와 관련해서는, 여명의 설원에 있는 내 사촌 키나이스를 처치해야만 하오. 그는 켈테릴 호수 남쪽의 얼어붙은 폭포를 따라 살고 있지.\n\n이것은 불행하지만 필수적인 희생이라네.",
    },
    [26306] = {
        ["T"] = "핵에 대한 조율",
        ["O"] =
        "검은바위 나락의 화산 심장부 입구 근처에 흐르는 용암으로 단열된 유리병을 채우고, 근처 벽에서 핵 조각을 수집하십시오.",
        ["D"] =
        "이제 산의 열기에 조율할 시약을 모아야 하오. 화산 심장부 자체의 열기와 공명 샘플이 필요하지. 아니면 최대한 안전하게 구할 수 있는 것이라도 말이오.\n\n검은무쇠 드워프들의 요새인 검은바위 나락으로 들어가시오. 맨 밑바닥까지 내려가면 그들의 제련소가 보일 거요. 근처의 맹렬한 용암으로 이 단열된 유리병을 채우시오.\n\n그런 다음 다리를 건너 핵을 향해 나아가 근처 벽에서 조각을 수집하시오.\n\n명심하시오 필멸자여. 이것은 위험한 임무이며 결코 혼자서 끝내고 싶지 않을 거요. 살아남는다면 나중에 다시 돌아오시오.",
    },
    [26307] = {
        ["T"] = "핵에 대한 조율",
        ["O"] =
        "군주 히드락시스가 화산 심장부에 안전하게 들어갈 수 있도록 보호의 부적을 불어넣는 동안 가만히 계십시오.",
        ["D"] =
        "당신이 수집한 재료를 사용하여 내 축복의 힘을 불어넣겠소. 이것은 산의 독특한 공명에 맞춰져 있으므로 화산 심장부에서만 당신을 보호할 거요.\n\n단단히 버티시오 필멸자여! 약간 따가울 수 있지만, 검은바위 산의 가장 깊은 곳을 파고들면서 살아남으려면 어쩔 수 없는 일이라네.",
    },
    [26308] = {
        ["T"] = "의지의 시험",
        ["O"] = "언더시티에 있는 타락한 기사와 대화하십시오.",
        ["D"] =
        "반갑소, $C $N. 난 최근 언더시티로 여행을 떠나 타락한 기사(Fallen Knight)와 대화할 기회가 있었지.\n\n<성기사가 낄낄거립니다.>\n\n언젠가 그녀의 진짜 이름을 알고 싶군. 그렇게 부르는 건 너무 비전문적으로 느껴지거든. 어쨌든, 그녀는 자네의 잠재력을 높이 평가했고 자네가 몇 가지 시험을 치르도록 자신에게 보내주기를 원했다네. 언더시티로 가서 그녀를 찾아보게.",
    },
    [26309] = {
        ["T"] = "의지의 시험",
        ["O"] = "시험을 치르고 싶다면 언더시티에 있는 타락한 기사와 대화하십시오.",
        ["D"] =
        "난 예전의 내가 아니야, $C $N. 은빛 성기사단의 기사, 위대한 미덕을 지닌 성기사, 진실과 정의의 수호자. 이제 난 여기 언더시티의 시궁창에 앉아, 이 진흙탕 속에서 병든 생물들이나 낚고 있지.\n\n하지만 너는 자신의 영혼에 안식처를 틀고 있는 어둠에도 불구하고 그 어둠과 싸우려는 의지를 보여주었어. 네가 수락한다면 널 시험해 보고 싶다.",
    },
    [26310] = {
        ["T"] = "의지의 시험",
        ["O"] =
        "붉은십자군 수도원 동쪽의 묘지에 있는 세 명의 전직 성기사 유령을 처치하십시오. 영혼들을 안식에 들게 한 후 언더시티의 타락한 기사에게 돌아가십시오.",
        ["D"] =
        "첫 번째 시험을 위해 티리스팔 숲의 북동쪽 멀리 여행해야 한다. 붉은십자군 수도원의 동쪽인데, 넌 아직 그곳에 갈 만큼 강하지 않으니 수도원에 너무 가까이 가지 않도록 주의해라. 묘지로 이어지는 작은 돌길을 찾을 수 있을 거다.\n\n그 묘지에서 세 명의 성기사 유령을 찾을 수 있다. 살아서 그들은 팀으로 함께 일했고, 죽어서는 자신들의 안식처에 묻혔지. 그들이 아직 이 세상에 미련을 두고 있는 것이 느껴진다. 가서 그들을 풀어주어, 마침내 안식에 들게 해라.",
    },
    [26311] = {
        ["T"] = "빛의 재료",
        ["O"] = "오그리마의 명예의 골짜기에 있는 모루 아투르크(Aturk the Anvil)에게 편지와 보수를 전달하십시오.",
        ["D"] =
        "이제 성기사에게 어울리는 망치를 만들 때다. 오그리마에 실력 좋은 대장장이가 한 명 있지. 그의 이름은 모루 아투르크다. 이 세부 사항이 적힌 편지와 보수를 그에게 가져가면, 네가 구해야 할 재료 목록을 줄 것이다. 명예의 골짜기에 있는 대장기술 전문가들 옆에서 그를 찾을 수 있다.\n\n내가 살아있던 시절이라면 아이언포지에 제작을 의뢰했겠지만, 요새는 그들이 요청을 받아주지 않을 것 같은 느낌이 드는군.",
    },
    [26312] = {
        ["T"] = "빛의 재료",
        ["O"] =
        "아투르크의 재료 목록을 사용하여 축복받은 주괴, 젤레마의 망치, 은빛 성기사단 메달, 코르의 보석을 찾으십시오. 이것들을 오그리마의 모루 아투르크에게 가져가십시오.",
        ["D"] =
        "나는 기술을 연마하고 내가 다룰 수 있는 재료에 대해 배우며 시간을 보낸다. 여행을 하면서 네 철퇴에 유용할 자원 몇 가지를 알게 되었지.\n\n<아투르크가 황소를 향해 핑거 스냅을 하며 요청 사항을 적으라고 말합니다.>\n\n이 편지를 받아서 물건들을 가져와!",
    },
    [26313] = {
        ["T"] = "빛의 무기",
        ["O"] = "",
        ["D"] =
        "아투르크 스스로도 감탄했어. 이건 정말 훌륭한 무기야. 강력한 호드 구성원에게 딱 어울리지! 우리를 잘 모셔라, $N. 너는 재능이 있으니까.\n\n널 의심했던 걸 미안하게 생각하진 않는다. 그런 의심이 네가 스스로를 증명하려는 원동력이 되었을 테니까! 아카마고쉬(Aka\'Magosh)!",
    },
    [26314] = {
        ["T"] = "원기 회복의 의식",
        ["O"] = "스칼로맨스에서 잔다이스 바로브를 처치하고, 고위마술사 안드로매스의 신비한 원기 회복에 관한 노트를 회수하십시오.",
        ["D"] =
        "만나서 반갑네 $N. 내 개인적인 부탁 하나 해도 되겠나?\n\n제3차 대전쟁이 일어나기 오래 전, 나는 제법 실력 있는 창조술사인 잔다이스 바로브와 매우 가까운 사이였다네. 스컬지 군대가 로데론을 덮쳤을 때 내 소지품 중 일부가 잔다이스에게 남겨졌지. 우리가 헤어지게 된 정황을 고려할 때, 그녀의 분노를 다시 마주하고 싶지는 않네.\n\n하지만 비전 마법에 대한 자네의 숙련도는 나와 맞먹을 정도이니, 그녀와 정면으로 맞설 수 있을 거라 믿네. 그녀에게서 내 신비한 원기 회복에 관한 노트를 되찾아준다면, 기꺼이 그 노트의 내용을 자네와 공유하겠네. 원기 회복의 의식이 꽤 시간을 절약해 준다는 것을 알게 될 거야!\n\n자네와 자네의 동료들은 서부 역병지대의 스칼로맨스 지하에서 잔다이스 바로브를 찾을 수 있을 걸세.",
    },
    [26315] = {
        ["T"] = "원기 회복의 의식",
        ["O"] = "스톰윈드의 마법 지구에 있는 고위마술사 안드로매스와 대화하십시오",
        ["D"] =
        "반갑네, $N. 자네는 훈련을 통해 강력해졌고 이제 내가 가르칠 수 있는 것은 거의 남지 않은 것 같군. 동료들을 위해 음식과 음료를 창조하는 데 지쳤겠지? 내 예상이 맞다면 스톰윈드의 고위마술사 안드로매스와 대화해 보는 게 좋을 것 같네. 그가 더 나은 방법을 알고 있을 거야.",
    },
    [26316] = {
        ["T"] = "로데론의 법적 유산",
        ["O"] =
        "언더시티에 있는 현자 이본로크를 위해 스칼로맨스와 스트라솔름에서 로데론의 법적 관행에 관한 책을 찾으십시오.",
        ["D"] =
        "생전에 나는 법학자였고, 죽어서도 훨씬 폭넓은 주제를 탐구하는 동시에 이 연구를 계속하고 싶다네. 로데론의 폐허로 직접 나가 책을 구해올 시간은 없지만, 자네라면 할 수 있을 거라고 믿네.\n\n스트라솔름의 폐허와 스칼로맨스 학교에서 특정 고서들을 가져다주면 현자로서의 내 임무와 개인적인 관심사 사이에서 균형을 맞출 수 있을 걸세.",
    },
    [26317] = {
        ["T"] = "아탈아이 서판",
        ["O"] = "아탈학카르 신전에서 알라니의 서판과 자카리의 서판을 수집하십시오.",
        ["D"] =
        "슬픔의 늪에 가라앉은 사원인 아탈학카르 신전에 거주하는 아탈아이 트롤들이 내가 연구하고 싶은 두 개의 고대 서판을 가지고 있다고 하더군.\n\n내가 물어보기도 전에 그들이 날 죽일 테니, 그곳으로 내려가 그것들을 회수해 줄 모험심 강한 자가 필요하네. 이 일에 관심 있나?",
    },
    [26318] = {
        ["T"] = "혈신(Blood God)의 기원",
        ["O"] =
        "아탈학카르 신전의 아탈아이 의술사와 아탈아이 고위 사제에게서 아탈아이 두루마리 4개를 수집하십시오.",
        ["D"] =
        "일거리를 찾고 있나? 남쪽의 늪으로 여행할 용감한 영혼이 필요하네.\n\n가라앉은 사원 안에서 고위 사제와 의술사들을 찾을 수 있을 거야. 이 트롤들은 혈신 학카르 자신의 광기 어린 예언이 쓰인 두루마리를 가지고 다니지. 나는 녀석의 추종자들을 예의주시하고 있는데, 이 두루마리들이 큰 도움이 될 거야. 어떻게 생각하나?",
    },
    [26319] = {
        ["T"] = "지식의 유산",
        ["O"] =
        "톨 바라드 섬의 바라딘 요새로 이동하여 칼레드라 돈브리즈가 회수하고자 하는 책들을 찾으십시오.",
        ["D"] =
        "여행자여, 방해해서 미안하지만 귀하의 이름은 귀족 가문들 사이에서 널리 알려져 있었기에, 나는 명성 있는 영웅이 요새를 방문하기를 기다리고 있었습니다.\n\n쿠엘탈라스와 달라란이 모두 함락되면서 우리 종족의 지식 중 상당수가 소실되었습니다. 그러나 키린 토는 톨 바라드 섬의 감옥 요새인 바라딘 요새에 도서관을 유지하고 있었죠. 그 감옥에 보관되어 있을지도 모르는 여러 권의 고서들을 꼭 보존하고 싶습니다.\n\n이 노력에 당신의 도움을 요청해도 될까요? 두둑하게 보상해 드리겠습니다.",
    },
    [26320] = {
        ["T"] = "지식의 유산",
        ["O"] =
        "톨 바라드 섬의 바라딘 요새로 이동하여 현자 애쉬메인이 회수하고자 하는 책들을 찾으십시오.",
        ["D"] =
        "여행자여, 방해해서 미안하지만 귀하의 이름은 장로들 사이에서 널리 알려져 있었기에, 나는 명성 있는 영웅이 정기의 봉우리를 방문하기를 기다리고 있었습니다.\n\n쿠엘탈라스와 달라란이 모두 함락되면서 하이 엘프 종족의 지식 중 상당수가 소실되었습니다. 그러나 키린 토는 톨 바라드 섬의 감옥 요새인 바라딘 요새에 도서관을 유지하고 있었죠. 그 감옥에 보관되어 있을지도 모르는 여러 권의 고서들을 꼭 보존하고 싶습니다.\n\n이 노력에 당신의 도움을 요청해도 될까요? 두둑하게 보상해 드리겠습니다.",
    },
    [26321] = {
        ["T"] = "끝나지 않은 임무",
        ["O"] = "톨 바라드 섬에서 레베카 마틴이 잃어버린 가보를 회수하십시오.",
        ["D"] =
        "거기- 그래, 당신! 모험가여! 제 말을 좀 들어주시겠어요!\n\n스톰윈드 왕궁의 권력자들에게 몇 주 동안이나 청원했지만 아무도 제 요청에 귀를 기울이지 않아요. 제 가족은 제2차 대전쟁 이전에 톨 바라드 섬에 살았습니다. 대부분 그곳에서 죽었지만, 제 삼촌 한 분은 탈출하셨죠. 그분은 돌아가시기 전에 소중한 가보가 섬의 안전한 곳에 숨겨져 있다고 말씀하셨습니다. 그런데 지금 톨 바라드에 해적들이 나타났다는 소문이 돌고 있어요! 그들은 분명 그 보물을 노리고 있을 겁니다.\n\n이봐요 $C, 저는 섬으로 가서 그 보물을 되찾아줄 누군가가 절실히 필요합니다. 이 열쇠를 가져가세요! 보물이 숨겨진 칸을 열 수 있을 겁니다. 제발, 제 가족의 유산을 되찾아 주세요!",
    },
    [26322] = {
        ["T"] = "끝나지 않은 임무",
        ["O"] = "잃어버린 가보를 스톰윈드에 있는 레베카 마틴에게 돌려주십시오.",
        ["D"] =
        "받은 열쇠로는 숨겨진 칸 안의 작은 금고가 열리지 않는 것 같습니다. 할 수 있는 일은 금고를 레베카 마틴에게 가져가 그녀가 찾던 보물이 들어 있기를 바라는 것뿐입니다.",
    },
    [26323] = {
        ["T"] = "끝나지 않은 임무",
        ["O"] = "톨 바라드 섬에서 조지아나 마틴이 잃어버린 가보를 회수하십시오.",
        ["D"] =
        "거기- 그래, 당신! 모험가여! 제 말을 좀 들어주시겠어요!\n\n언더시티의 권력자들에게 몇 주 동안이나 청원했지만 아무도 제 요청에 귀를 기울이지 않아요. 제 가족은 제2차 대전쟁 이전에 톨 바라드 섬에 살았습니다. 대부분 그곳에서 죽었지만, 제 삼촌 한 분은 탈출하셨죠. 그분은 돌아가시기 전에 소중한 가보가 섬의 안전한 곳에 숨겨져 있다고 말씀하셨습니다. 그런데 지금 톨 바라드에 해적들이 나타났다는 소문이 돌고 있어요! 그들은 분명 그 보물을 노리고 있을 겁니다.\n\n이봐요 $C, 저는 섬으로 가서 그 보물을 되찾아줄 누군가가 절실히 필요합니다. 이 열쇠를 가져가세요! 보물이 숨겨진 칸을 열 수 있을 겁니다. 제발, 제 가족의 유산을 되찾아 주세요!",
