    [26324] = {
        ["T"] = "끝나지 않은 임무",
        ["O"] = "잃어버린 가보를 언더시티에 있는 조지아나 마틴에게 돌려주십시오.",
        ["D"] =
        "받은 열쇠로는 숨겨진 칸 안의 작은 금고가 열리지 않는 것 같습니다. 할 수 있는 일은 금고를 조지아나 마틴에게 가져가 그녀가 찾던 보물이 들어 있기를 바라는 것뿐입니다.",
