    [26325] = {
        ["T"] = "묻힌 보물",
        ["O"] = "발견한 흙더미를 파낼 알맞은 도구를 찾으십시오.",
        ["D"] =
        "이 평범해 보이는 흙더미에는 어떤 보물도 숨겨져 있지 않은 것 같습니다. 느슨한 흙을 헤집어보면 상자의 가장자리 같은 것이 만져지다가 이내 감각이 사라집니다.\n\n아마도 상자를 파내려면 특별한 장비가 필요한 것 같습니다?",
    },
    [26326] = {
        ["T"] = "속죄를 향하여",
        ["O"] = "불길한 흰색 보주에 대해 더 자세히 알려줄 수 있는 사람과 대화하십시오.",
        ["D"] =
        "블랙스톤 선장의 상자 속 보물들 사이에는 불길한 붉은빛으로 맥동하는 기묘한 젖빛 보주가 있습니다. 매끄러운 표면을 만져보면 보주는 기묘하게도 안도감을 줍니다. 이 물건이 무엇인지 자세히 알아보는 것이 좋을 듯합니다.",
    },
    [26327] = {
        ["T"] = "속죄를 향하여",
        ["O"] =
        "블랙스톤 선장의 옛 선원들을 찾아 팔레스의 눈(Eye of Paleth)의 기원에 대해 그들이 말하는 내용을 알아보십시오.",
        ["D"] =
        "$C, 당신은 이제 이 섬의 주민들을 연옥에 가둔 것보다 더 강력한 마법으로 저주받은 팔레스의 눈에 얽매이게 되었습니다. 우리는 사우스쇼어의 포로수용소에서 사람들을 학대한 죄로 빛에 얽매였었죠.\n\n블랙스톤 선장이 자신의 보물을 숨기기 위해 이 섬을 선택한 것은 우연이 아닙니다. 그는 사우스쇼어의 사략 함대에 징집되기 전까지 수년간 고통받았습니다. 우리가 속죄의 일환으로 그의 보물을 지키는 것은 마땅한 임무였죠. 이 이야기는 당신과 아무런 관련이 없었어야 하지만, 이제 당신은 그 속 깊이 빠져들고 말았습니다. 블랙스톤의 실수가 당신의 삶을 지배하는 것을 원치 않는다면, 블랙스톤이 실패했던 것처럼 저주를 풀어야 할 겁니다.\n\n팔레스의 눈이 어떻게 블랙스톤의 손에 들어갔는지 자세한 내막은 모르지만, 당신에게 얽힌 저주를 깨려면 그 근원까지 거슬러 올라가야 할 겁니다. 블랙스톤은 세 명의 선원과 함께 이 섬에 왔습니다. 블랙스톤처럼 광기에 굴복하고 싶지 않다면 그들을 찾으십시오.",
    },
    [26328] = {
        ["T"] = "속죄를 향하여",
        ["O"] = "수집한 정보를 사용하여 블랙스톤의 보물 더미를 찾으십시오.",
        ["D"] =
        "그럼 세 명의 선원이 보물이 나가들이 거주하는 페랄라스의 한 동굴에 있다고 했단 말입니까?\n\n저는 칼림도어에 대해 아는 바가 없어 더 이상 조언해 드릴 수는 없지만, 그 땅의 해변 동굴들을 뒤져본다면 틀림없이 원하는 것을 찾을 수 있을 것입니다.\n\n그리고 여기서 상자를 파낼 때 썼던 삽을 하나 더 구하십시오. 분명 필요할 테니까요.\n\n안녕히 가십시오, $C. 우리가 다시 만날 일이 없기를 기도하겠습니다.",
    },
    [26329] = {
        ["T"] = "또 다른 삶의 꿈",
        ["O"] =
        "블랙스톤과 그의 연인의 공통된 친구를 찾으십시오. 블랙스톤의 일지에 그가 친구를 사귀었던 장소에 대한 단서가 있을지도 모릅니다.",
        ["D"] =
        "보물과 \"장막의 엮는 자\"의 저주의 기원 대신, 블랙스톤이 자신의 선원들을 보호하기 위해 보물을 다른 곳에 숨겼다는 내용의 쪽지를 발견합니다. 이 고결한 행동 때문에 당신은 저주받은 팔레스의 눈을 계속 지니고 다녀야 하는 운명에 처하게 되었습니다.\n\n오직 블랙스톤의 연인만이 보물의 진짜 위치를 알고 있습니다. 그녀를 찾는 것만이 저주에서 벗어날 유일한 희망입니다.",
    },
    [26330] = {
        ["T"] = "또 다른 삶의 꿈",
        ["O"] = "파라 그림토템이 보물 더미로 안내하는 동안 그녀를 보호하십시오.",
        ["D"] =
        "이 농장은 우리의 꿈이었어요. 그가 실제로 이곳으로 돌아오지 못할 거라는 건 항상 알고 있었던 것 같아요. 사략선원은 위험한 일이고, 그가 아예 해적으로 돌아서고 나서는...\n\n블랙스톤이 어떻게 그 보물을 이곳으로 옮겼는지는 모르겠지만, 근처 동굴에 숨겨두었어요. 아마도 그것이 그가 제게 준 마지막 선물이겠지만, 저는 거기에 접근할 수가 없었어요. 장막 너머의 영혼들이 출몰하거든요. 그들은 우리를 쫓아내려 할 거예요. 하지만 당신이 전투에서 내 사랑을 물리칠 만큼 강했고, 저주에서 살아남아 여기까지 왔다면, 어쩌면 그들을 물리칠 수 있을지도 몰라요.\n\n출발할 준비가 되면 알려주세요.",
    },
    [26331] = {
        ["T"] = "약탈하는 해적들",
        ["O"] = "비행조련사 호킨스에게서 그리핀을 타고 톨 바라드에서 발생한 해적의 습격을 조사하십시오.",
        ["D"] =
        "세 달 전 우리 감시원이 수평선에서 돛과 배들을 발견했습니다. 그는 전에 그들의 깃발을 본 적이 있다고 주장했지만, 어디서 누구와 함께 봤는지는 너무 겁이 나서 말하지 못하는 것 같았습니다. 그들이 목격된 직후 수면 위로 대포 소리가 울려 퍼졌죠.\n\n그 방향에는 섬이 딱 하나 있습니다. 옛 키린 토 감옥이 있는 톨 바라드. 그곳에서 무엇을 원할 수 있을까요? 습격일까요? 탈옥일까요?\n\n저는 호기심이 생기지만 제 미신적인 선원들은 두려워하고 있습니다. 당신이 도와줄 수 있어요! 비행조련사 호킨스에게 가서 톨 바라드로 가는 비행을 요청하십시오. 섬을 살펴보고 무슨 일이 일어나고 있는지 알려줄 정찰병이 필요합니다.",
    },
    [26332] = {
        ["T"] = "약탈하는 해적들",
        ["O"] = "아라시 고원의 팔디르의 만에 있는 스틸구트 선장을 찾으십시오.",
        ["D"] =
        "잘 들으십시오! 한... 글쎄, 그냥 동맹이라고 해두죠, 그 동맹으로부터 톨 바라드에서 해군 공격이 일어나고 있는 것 같다는 소식을 들었습니다.\n\n그 섬은 가치가 없는 곳이므로, 이런 보고를 받는 것은 꽤 의심스럽습니다.\n\n팔디르의 만으로 향하여 스틸구트 선장에게 말하고 제가 당신을 보냈다고 하십시오. 그들은 그것이 무엇인지 알 것입니다.",
    },
    [26333] = {
        ["T"] = "배를 위한 나의 왕국",
        ["O"] = "윙키가 배를 건조하기 위해 요청한 물자를 구하여 타나리스에 있는 그녀의 섬으로 가져가십시오.",
        ["D"] =
        "난 수영을 못 하고 지금 와서 시간 낭비하며 배울 생각은 추호도 없어요! 내 배를 조립할 부품이 필요할 뿐이죠 - 아주 작은 거니까, 많은 걸 요구하는 건 아니에요.\n\n여기 부품 목록이 있어요. 방수 갑옷 입고 빨리 가서 이 물건들 좀 가져와 줘요. 빨리 다녀올수록, 당신은 더 빨리 저주를 풀 수 있고, 난 제대로 된 침대에서 잠을 잘 수 있다고요.\n\n아 - 그 물건들은 어디서 구하냐고요? 서부 역병지대에 제재소가 있다고 들었어요. 거기서 좀 구할 수 있을 거예요. 룬무늬 옷감은 아무나 주울 수 있게 널려 있죠, 안 그래요? 실타래는 상인들이 팔고, 끈적이는 타르 주전자는 다른 해적들한테서 구하면 돼요.",
    },
    [26334] = {
        ["T"] = "배를 위한 나의 왕국",
        ["O"] = "윙키가 배를 건조하는 데 필요한 도구를 구하십시오.",
        ["D"] =
        "맨손으로 배를 만들 순 없잖아요! 이 부품들을 조립할 제대로 된 도구가 필요하다고요. 당신이 그걸 구해와 줘야 해요. 왜냐하면 당신이 저번에 다녀간 이후로 난 백일몽이나 꾸며 치즈 먹고 선탠이나 하느라 수영을 배우지 않았으니까요. 꿈을 갖는 건 중요해요! 계속 나아갈 원동력이 되니까. 그리고 태닝한 노움을 몇 명이나 본 적 있어요? 내 황금빛 피부는 꽤 센세이션을 일으킬 거예요.\n\n어쨌든, 대장장이 망치 하나, 만능 스패너 하나, 구리 나사 50줌, 그리고 노움 크기 톱이 필요해요. 숙련된 기계공학자라면 일부를 도와줄 수 있겠지만, 톱은 딱 한 군데, 놈리건에서만 구할 수 있어요!",
    },
    [26335] = {
        ["T"] = "스튜얼의 복수",
        ["O"] = "로린 렘카가 살았는지 죽었는지 확인하십시오.",
        ["D"] =
        "말씀드렸다시피, 제 아버지는 블랙스톤과 나머지 오크 선원들을 감옥에서 구하기 위해 목숨을 바쳤습니다. 제 아버지 밑에서 항해했던 오크들은 포로수용소에서 징집되었고, 사우스쇼어 사략 함대가 파괴된 후 그 수용소로 다시 송환되었죠. 아버지는 그들의 자유를 청원했지만, 텔그램 판사와 로린 렘카 감독관에게 거절당했습니다.\n\n텔그램은 이미 오래전에 죽었지만, 렘카는 아직 살아있을 거라 믿습니다. 그녀가 이성에 귀를 기울였다면, 아버지는 굳이 수용소에서 오크들을 빼내려 하지 않았을 테고 그 일로 죽지도 않았을 겁니다. 그녀가 아버지의 죽음에 대한 대가를 치를 때까지 제 양심이 편치 않을 테지만, 지금 그녀가 어디 있는지 전혀 모릅니다.\n\n렘카는 암컷 오크를 개인 노예로 데리고 있었죠. 이름은 그리킥이었습니다. 렘카는 수용소에 와릭이라는 수행원도 데리고 있었어요. 두 사람 다 살아있는지 모르겠지만, 어느 한 사람이라도 찾는다면 렘카의 행방을 아는 단서가 될 겁니다.",
    },
    [26336] = {
        ["T"] = "스튜얼의 복수",
        ["O"] = "로린 렘카를 처치하십시오.",
        ["D"] =
        "사법 체계가 적절한 처벌을 내려주길 바랐지만, 스톰윈드의 지도자들이 수년 전 로데론에서 일어난 범죄에 신경을 쓸 거란 희망은 거의 없습니다.\n\n아버지는 제 복수심을 인정하지 않으실 겁니다. 심지어 작전이 잘못되더라도 그 바보들에게 손을 대지 않겠다고 약속하게 하셨죠. 하지만 그 약속의 글귀를 지키면서도 양심을 맑게 유지할 방법이 있습니다. 당신이 제 복수의 손길이 되어주셔야 합니다. 그렇게 해주신다면, 원하시는 걸 알려드리죠.\n\n로린 렘카는 죽어야 합니다. 피는 피로 갚아야 합니다.",
    },
    [26337] = {
        ["T"] = "강령술사와 후예",
        ["O"] = "톨 바라드 섬의 바라딘 요새로 들어가 공허한 아스틸로스와 나즈라사쉬를 처치하십시오.",
        ["D"] =
        "반갑소, $C. 은밀한 일거리를 찾으러 왔다면 제대로 찾아온 게 맞소.\n\n섬 감옥인 바라딘 요새에서 소규모 탈옥이 있었다고 들었소. 그곳에 수감되어 있는 죄수들 중에 절대 탈출해서는 안 되는 두 놈이 있소. 둘 다 언더시티에 파멸을 몰고 올 수 있는 강력한 마법 사용자요. 그리고 우린 돌아다니는 강령술사가 더 늘어나는 걸 결코 원치 않소.\n\n수고스럽겠지만 아라시 고원의 팔디르의 만으로 가서 톨 바라드로 가는 비행편을 타 주시오. 아스틸로스와 나즈라사쉬가 절대 섬을 빠져나오지 못하게 처리해 준다면 수고비는 두둑하게 챙겨드리겠소.",
    },
    [26338] = {
        ["T"] = "바라딘 요새의 몰락 가능성",
        ["O"] = "SI:7에서 바라딘 요새의 현재 상황에 대해 더 많은 정보를 줄 수 있는 사람을 찾으십시오.",
        ["D"] =
        "스톰윈드 해군의 대제독으로서 저는 공해상에서 일어나는 온갖 종류의 사건과 사기 행위에 대한 보고를 받습니다. 최근 톨 바라드의 섬 요새에서 불안한 보고가 들어왔습니다. 해적들이 옛 키린 토 감옥을 장악했을지도 모른다는 내용이었죠.\n\n현재로선 이 소문은 근거가 없습니다. 누군가 톨 바라드로 가서 상황을 파악해야 합니다. 당신은 능력 있어 보이는군요 -- 얼라이언스는 당신을 필요로 합니다, 모험가여.\n\n출발하기 전에 SI:7에 들러보십시오. 그들이 더 많은 정보를 가지고 있을지도 모릅니다.",
    },
    [26339] = {
        ["T"] = "바라딘 요새의 몰락 가능성",
        ["O"] = "톨 바라드 섬의 바라딘 요새 상황을 조사하여 해적 습격 소문이 사실인지 확인하십시오.",
        ["D"] =
        "톨 바라드 섬에는 바라딘 요새 감옥이 있습니다 -- 하지만 바라딘은 그저 그런 감옥이 아닙니다. 세상에서 가장 흉악한 생물들이 그곳에 수감되어 있죠. 케잔조차 통제하지 못했던 놈도 있다니까요!\n\n그러니까, 해적들이 감옥을 장악했는지 확인해야 합니다 -- 만약 그렇다면, 우리도 뭔가 조치를 취해야 하죠. 현장에 도착해서 최선의 행동 방침을 결정하는 건 당신에게 맡기겠습니다.\n\n말이 나왔으니 말인데, 그곳에 가는 방법을 모른다면 아라시 고원의 팔디르의 만으로 가야 할 겁니다. 그곳의 비행조련사가 기꺼이 도와줄 겁니다.",
    },
    [26340] = {
        ["T"] = "바라딘 요새의 몰락 가능성",
        ["O"] = "바라딘 요새를 공격한 해적들인 글라구트, 칼립소, 해적 군주 블랙스톤을 처치하십시오.",
        ["D"] =
        "렌직이 소문이 사실로 밝혀질 경우 당신 재량껏 처리하라고 지시했었죠.\n\n상황을 해결하는 가장 간단한 방법은 현재 바라딘 요새를 통제하고 있는 해적들을 제거하는 겁니다.\n\n감옥을 돌파하여 질서가 회복되도록 해야 합니다.",
    },
    [26341] = {
        ["T"] = "바라딘 요새의 몰락 가능성",
        ["O"] = "톨 바라드 섬의 바라딘 요새 상황을 조사하여 해적 습격 소문이 사실인지 확인하십시오.",
        ["D"] =
        "호드의 영웅이여, 부족장들이 당신의 도움을 필요로 하고 있소!\n\n톨 바라드 섬은 바라딘 요새 감옥이 있는 곳이오 -- 그곳엔 세상에서 가장 흉악한 짐승들이 수감되어 있지. 케잔조차 가둬두지 못한 놈도 있다오!\n\n해적들이 그 감옥을 장악했다는 소문이 돌고 있소. 조사가 필요하오. 그곳에 도착해서 어떻게 대처할지는 당신에게 맡기겠소.\n\n그곳에 가는 방법을 모른다면, 아라시 고원의 팔디르의 만으로 가보시오. 그곳의 비행조련사가 비행편을 마련해 줄 거요.",
    },
    [26342] = {
        ["T"] = "바라딘 요새의 몰락 가능성",
        ["O"] = "바라딘 요새를 공격한 해적들인 글루크, 칼립소, 해적 군주 블랙스톤을 처치하십시오.",
        ["D"] =
        "볼진은 소문이 사실로 확인될 경우 직접 문제를 해결하라고 지시했습니다.\n\n상황을 해결하는 가장 간단한 방법은 현재 바라딘 요새를 장악하고 있는 해적들을 제거하는 것입니다.\n\n감옥을 돌파하여 질서를 회복해야 합니다.",
