        ["D"] =
        "반갑소, $C. 은밀한 일거리를 찾으러 왔다면 제대로 찾아온 게 맞소.\n\n섬 감옥인 바라딘 요새에서 소규모 탈옥이 있었다고 들었소. 그곳에 수감되어 있는 죄수들 중에 절대 탈출해서는 안 되는 두 놈이 있소. 놈들이 나를 찾으러 올 가능성이 농후한데, 난 스톰윈드에 그런 종류의 혼란이 일어나는 걸 원치 않소.\n\n수고스럽겠지만 아라시 고원의 팔디르의 만으로 가서 톨 바라드로 가는 비행편을 타 주시오. 모루무스와 다크말이 절대 섬을 빠져나오지 못하게 처리해 준다면 수고비는 두둑하게 챙겨드리겠소.",
    },
    [26344] = {
        ["T"] = "네가 내 등을 긁어주면...",
        ["O"] = "가시덤불 골짜기에서 우두머리 오글소프를 찾아 제거하십시오.",
        ["D"] =
        "아마 당신은 그 보주가 나왔던 나머지 보물을 찾고 있는 것 같군요. 좋은 소식이 있습니다. 우리가 배를 나포했던 곳 근처에 통째로 묻혔거든요. 나쁜 소식은 제가 좌표의 일부만 알고 있다는 겁니다. 블랙스톤이 저와 윙크스, 주니어에게 좌표를 나누어 주었죠. 그러니 나머지 정보를 얻으려면 그들과 대화해야 할 겁니다.\n\n하지만 먼저... 경쟁 카르텔 멤버와 약간의 문제가 있었습니다. 블랙스톤 선원들을 떠난 이후로 블랙워터 해적단을 위해 프리랜서로 일하고 있는데 벤처 투자회사의 우두머리 오글소프와 여러 번 마찰을 빚었거든요. 무법항 밖으로 나갈 때마다 뒤를 조심해야 하는 건 이제 지긋지긋합니다. 그녀를 처리해 주면 당신이 알고 싶은 걸 알려드리죠.\n\n그녀는 가시덤불 골짜기 어딘가에 작은 기지를 가지고 있는데 어딘지는 모릅니다.",
    },
    [26345] = {
        ["T"] = "좋은 소식",
        ["O"] = "톱니항에서 칼레타카 윈터블러프를 만나 노르간논의 원반에 대해 논의하십시오.",
        ["D"] =
        "좋은 소식이 있습니다, $N! 탐험가 연맹에서 노르간논의 원반에 새겨진 룬 문자를 일부 해독했습니다. 이상하게도, 고대 타우라헤어에서 쓰이는 룬 문자와 비슷하더군요.\n\n우리는 룬 문자 해독을 돕기로 한 타우렌 연락책을 찾았고, 당신이 그녀와 함께 일했으면 합니다. 그녀는 당신을 만나기 위해 썬더 블러프에서 톱니항까지 여행하기로 동의했습니다. 그곳의 여관에서 칼레타카 윈터블러프를 만나면 우울둠을 여는 데 한 걸음 더 다가갈 수 있을 것입니다!",
    },
    [26346] = {
        ["T"] = "흥미로운 발견",
        ["O"] = "톱니항에서 칼레타카 윈터블러프를 만나 노르간논의 원반에 대해 논의하십시오.",
        ["D"] =
        "얼마 전 탐험가 연맹이 노르간논의 원반이라는 유물을 얻었습니다. 우리는 그 원반에서 정보를 얻어내려 하고 있고, 계속 진행하려면 타우라헤어 전문가가 필요합니다.\n\n우리는 기꺼이 우리와 함께 일할 타우렌 연락책을 찾았고, 그녀와 만날 전령이 필요합니다. 마을에서 당신을 추천하는 소리를 들었으니, 톱니항의 부러진 돛대 선술집에서 칼레타카 윈터블러프를 만나주셨으면 합니다. 우리가 맞다면, 이 원반들이 울둠의 고대 시설을 여는 열쇠가 될 수 있습니다!",
    },
    [26347] = {
        ["T"] = "좋은 소식",
        ["O"] = "톱니항과 악령숲 사이의 길 어딘가에서 칼레타카 윈터블러프를 찾으십시오.",
        ["D"] =
        "솔직히 말해서 $R를 대면하는 건 조금 긴장되는 일입니다만, 저희 어머니는 지식을 추구하는 데 진영 간의 불만을 방해물로 두실 분이 아니셨죠.\n\n하지만 어머니는 이리로 오시는 길에 걱정이 많으셨습니다. 수상한 누군가가 우리를 미행하고 있다고 생각하셨거든요. 여기서 기다리지 않기로 하셨고, 악령숲으로 향하고 있다고 전해달라고 하셨습니다. 걸어서 가셨으니 충분히 따라잡으실 수 있을 겁니다.\n\n어머니가 걱정되지만, $R, 스스로 몸을 지키실 수 있을 거라고 믿습니다.",
    },
    [26348] = {
        ["T"] = "나쁜 소식",
        ["O"] = "톱니항에 있는 물린 윈터블러프에게 나쁜 소식을 전하십시오.",
        ["D"] =
        "칼레타카 윈터블러프의 시신은 모든 귀중품을 약탈당했습니다. 손에 방어 흔적이 없는 것으로 보아 기습을 당한 것 같습니다. 목이 단칼에 베인 자국은 살인자가 매우 노련함을 보여줍니다.\n\n당신이 떠나려 할 때 근처 진흙에서 기묘한 발자국 하나를 발견합니다. 미행당하고 있다는 어머니의 의심이 사실이었으며 그 결과가 모두에게 비극적이었음을 톱니항의 물린 윈터블러프에게 알려야 한다는 것을 알기에, 당신은 그 발자국의 특징을 기억해 둡니다.",
    },
    [26349] = {
        ["T"] = "나쁜 소식",
        ["O"] = "칼레타카의 암호화된 쪽지를 아이언포지에 있는 선임탐험가 마겔라스에게 가져가십시오.",
        ["D"] =
        "<물린이 진정하려고 애쓰는 동안, 당신은 진흙에서 본 발자국에 대해 설명합니다.>\n\n당신을 돕고 싶지만 지금은 집중할 수가 없군요. 하지만 당신이 떠나기 전에 어머니가 제게 주신 것이 하나 있는데, 당신이 가져가야 할 것 같습니다, $R.\n\n어머니는 당신에게 무슨 일이 생기면 이 쪽지를 전해주라고 하셨습니다. 어머니를 필요로 했던 일이 무엇이든 이 쪽지가 도움이 되길 바랍니다.\n\n이제 두 번 다시 $R를 보고 싶지 않다고 말해도 용서하십시오.",
    },
    [26350] = {
        ["T"] = "또다시 좋은 소식",
        ["O"] = "아이언포지의 탐험가의 전당에 있는 역사학자 카르닉과 대화하십시오.",
        ["D"] =
        "제가 칼레타카의 메시지를 해독하는 동안, 탐험가 연맹의 다른 단원들이 울둠의 서판 위치를 해독하는 데 돌파구를 마련했습니다.\n\n자세한 내용을 알고 싶다면 역사학자 카르닉과 대화해 보십시오.",
    },
    [26351] = {
        ["T"] = "또다시 좋은 소식",
        ["O"] = "여명의 설원에 있는 검은속삭임 협곡을 수색하여 울둠의 서판 위치에 대한 단서를 찾으십시오.",
        ["D"] =
        "탐험가 연맹은 울둠의 서판이 연기가 끊이지 않는 곳에 보관되어 있음을 나타내는 두어 가지 정보를 해독했습니다. 또한, \"협곡\"과 \"동굴\"이라는 단어가 자주 등장하는 것 같습니다.\n\n이글거리는 협곡을 가리키는 것이 분명해 보이지만, 기억하십시오. 이 원반들은 라그나로스가 소환되기 훨씬 전에 만들어졌습니다. 이글거리는 협곡은 그때 존재하지 않았죠.\n\n하지만 여명의 설원에 있는 검은속삭임 협곡은 존재했습니다.\n\n당신의 뛰어난 능력을 발휘해 검은속삭임 협곡에서 울둠의 서판에 대한 단서를 찾아주셨으면 합니다. 찾은 것이 있으면 보고해 주십시오.",
    },
    [26352] = {
        ["T"] = "또다시 나쁜 소식",
        ["O"] = "어스콜러의 메시지를 가지고 아이언포지의 역사학자 카르닉에게 돌아가십시오.",
        ["D"] =
        "당신이 무엇을 찾고 있는지 알고 있으며, 그것을 찾는 당신의 용맹함을 보았습니다. 저는 이것을 가볍게 말하는 것이 아닙니다. 필멸자들이 지식 추구를 위해 얼마나 많은 희생을 치르는지 보아왔기 때문입니다.\n\n경고하건대, 당신은 울둠의 서판을 맞이할 준비가 되어 있지 않습니다. 그 문 뒤에 기다리고 있는 것을 감당할 준비가 되어 있지 않습니다. 티탄들조차 그들이 발견한 것에 대해 준비되지 않았고, 그것이 바로 서판과 원반이 분리되어 바람에 흩어진 이유입니다.\n\n당신이 이 흔적을 계속 쫓는다면 말할 수 없는 파멸이 풀려날 것입니다. 이제 가십시오, $R. 이 퀘스트는 끝났습니다. 새 임무를 찾기를 권합니다.",
    },
    [26353] = {
        ["T"] = "좋은 소식",
        ["O"] = "무법항에서 헤드릭 아이언스톤을 만나 노르간논의 원반에 대해 논의하십시오.",
        ["D"] =
        "좋은 소식이 있습니다, $N! 현자들이 노르간논의 원반에 새겨진 룬 문자를 일부 해독했습니다. 고대 드워프어로 쓰여 있더군요.\n\n우리는 룬 문자 해독을 돕기로 한 드워프 연락책을 찾았고, 당신이 그와 만났으면 합니다. 그는 당신과 만나기 위해 아이언포지에서 톱니항까지 여행하기로 동의했습니다. 그곳 여관에서 헤드릭 아이언스톤을 만나면 울둠을 여는 데 한 걸음 더 다가갈 수 있을 것입니다!",
    },
    [26354] = {
        ["T"] = "흥미로운 발견",
        ["O"] = "톱니항에서 헤드릭 아이언스톤을 만나 노르간논의 원반에 대해 논의하십시오.",
        ["D"] =
        "얼마 전 현자들이 노르간논의 원반이라는 유물을 얻었습니다. 우리는 그 원반에서 정보를 얻어내려 하고 있고, 계속 진행하려면 드워프어 전문가가 필요합니다.\n\n우리는 기꺼이 우리와 함께 일할 드워프 연락책을 찾았고, 그와 만날 전령이 필요합니다. 마을에서 당신을 추천하는 소리를 들었으니, 톱니항의 부러진 돛대 선술집에서 헤드릭 아이언스톤을 만나주셨으면 합니다. 우리가 맞다면, 이 원반들이 울둠의 고대 시설을 여는 열쇠가 될 수 있습니다!",
    },
    [26355] = {
        ["T"] = "좋은 소식",
        ["O"] = "톱니항과 악령숲 사이의 길 어딘가에서 헤드릭 아이언스톤을 찾으십시오.",
        ["D"] =
        "솔직히 말해서 $R를 대면하는 건 조금 긴장되는 일입니다만, 저희 아버지는 지식을 추구하는 데 진영 간의 불만을 방해물로 두실 분이 아니셨죠.\n\n하지만 아버지는 이리로 오시는 길에 걱정이 많으셨습니다. 누군가 우리를 지켜보고 미행하고 있다고 생각하셔서 혼자 출발하셨거든요. 악령숲으로 향하고 있다고 전해달라고 하셨습니다. 걸어서 가셨으니 충분히 따라잡으실 수 있을 겁니다.\n\n아버지가 걱정되지만, $R, 제 아버지라면 스스로 몸을 지키실 수 있을 거라고 믿습니다.",
    },
    [26356] = {
        ["T"] = "나쁜 소식",
        ["O"] = "톱니항에 있는 넬리 아이언스톤에게 나쁜 소식을 전하십시오.",
        ["D"] =
        "헤드릭 아이언스톤의 시신은 모든 귀중품을 약탈당했습니다. 손에 방어 흔적이 없는 것으로 보아 기습을 당한 것 같습니다. 목이 단칼에 베인 자국은 살인자가 매우 노련함을 보여줍니다.\n\n당신이 떠나려 할 때 근처 진흙에서 기묘한 발자국 하나를 발견합니다. 미행당하고 있다는 아버지의 의심이 사실이었으며 그 결과가 모두에게 비극적이었음을 톱니항의 넬리 아이언스톤에게 알려야 한다는 것을 알기에, 당신은 그 발자국의 특징을 기억해 둡니다.",
    },
    [26357] = {
        ["T"] = "나쁜 소식",
        ["O"] = "헤드릭의 암호화된 쪽지를 썬더 블러프에 있는 현자 트루스시커에게 가져가십시오.",
        ["D"] =
        "<넬리가 진정하려고 애쓰는 동안, 당신은 진흙에서 본 발자국에 대해 설명합니다.>\n\n당신을 돕고 싶지만 그 기묘한 신발 자국은 제게 익숙하지 않군요. 하지만 다른 게 있습니다, $R.\n\n아버지는 당신에게 무슨 일이 생기면 이 쪽지를 전해주라고 하셨습니다. 아버지를 필요로 했던 일이 무엇이든 이 쪽지가 도움이 되길 바랍니다.\n\n이제 두 번 다시 $R를 보고 싶지 않다고 말해도 용서하십시오.",
    },
    [26358] = {
        ["T"] = "또다시 좋은 소식",
        ["O"] = "썬더 블러프의 정기의 봉우리에 있는 현자 나샤와 대화하십시오.",
        ["D"] =
        "제가 헤드릭의 메시지를 해독하는 동안, 다른 현자들 중 일부가 울둠의 서판 위치를 해독하는 데 돌파구를 마련했다고 믿고 있습니다.\n\n자세한 내용을 알고 싶다면 정기의 봉우리에 있는 현자 나샤와 대화해 보십시오.",
    },
    [26359] = {
        ["T"] = "또다시 좋은 소식",
        ["O"] = "여명의 설원에 있는 검은속삭임 협곡을 수색하여 울둠의 서판 위치에 대한 단서를 찾으십시오.",
        ["D"] =
        "현자들은 울둠의 서판이 연기가 끊이지 않는 곳에 보관되어 있음을 나타내는 두어 가지 정보를 해독했습니다. 또한, \"협곡\"과 \"동굴\"이라는 단어가 자주 등장하는 것 같습니다.\n\n이글거리는 협곡을 가리키는 것이 분명해 보이지만, 기억하십시오. 이 원반들은 라그나로스가 소환되기 훨씬 전에 만들어졌습니다. 이글거리는 협곡은 그때 존재하지 않았죠.\n\n하지만 여명의 설원에 있는 검은속삭임 협곡은 존재했습니다.\n\n당신의 뛰어난 능력을 발휘해 검은속삭임 협곡에서 울둠의 서판에 대한 단서를 찾아주셨으면 합니다. 찾은 것이 있으면 보고해 주십시오.",
    },
