    [26409] = {
        ["T"] = "사냥꾼의 길",
        ["O"] = "골드샤이어에 있는 제임스 할로란과 대화하십시오.",
        ["D"] =
        "반갑네, 젊은 사냥꾼이여. 자네는 야수를 다루고 동료로 훈련시킬 수 있을 만큼 충분히 숙련된 것 같군.\n\n골드샤이어에 있는 제임스 할로란을 만나보게. 그가 자네만의 야수를 얻는 길로 안내해 줄 걸세.",
    },
    [26410] = {
        ["T"] = "야수 길들이기",
        ["O"] =
        "조련용 막대를 사용하여 돌가죽멧돼지를 길들이십시오. 기술을 연습한 후 조련용 막대를 골드샤이어에 있는 제임스 할로란에게 돌려주십시오.",
        ["D"] =
        "만나서 반갑네! 자, 어떻게 하면 자네만의 야수를 얻을 수 있는지 알고 싶나?\n\n좋아, 자네가 꽤 관심을 가질 만한 것에 집중해 보지: 바로 야수 말일세!\n\n가장 좋은 학습 방법은 여러 생물을 동료로 삼아보고 어떤 녀석이 마음에 드는지 확인하는 거야. 그러니 돌가죽멧돼지를 찾은 다음, 조련용 막대를 사용하여 길들여 보게.",
    },
    [26411] = {
        ["T"] = "야수 길들이기",
        ["O"] =
        "조련용 막대를 사용하여 굶주린 늑대를 길들이십시오. 기술을 연습한 후 조련용 막대를 골드샤이어에 있는 제임스 할로란에게 돌려주십시오.",
        ["D"] =
        "돌가죽멧돼지는 꽤 건장하지. 좀 더 섬세한 녀석을 원하나? 좋아, 딱 맞는 녀석이 있지. 여기서 동쪽으로 가면 굶주린 늑대라고 불리는 큰 늑대들을 찾을 수 있을 거야. 우아하게 조각된 활처럼, 그들의 아름다운 외모 뒤에는 극심한 피해를 입힐 수 있는 강력한 투사가 숨어 있지. 자네가 길들인 멧돼지보다 훨씬 더 민첩하고 날쌘 것을 알게 될 걸세.\n\n이 조련용 막대를 가져가서 굶주린 늑대가 마음에 드는지 확인해 보게.",
    },
    [26412] = {
        ["T"] = "야수 길들이기",
        ["O"] =
        "조련용 막대를 사용하여 새끼곰을 길들이십시오. 기술을 연습한 후 조련용 막대를 골드샤이어에 있는 제임스 할로란에게 돌려주십시오.",
        ["D"] =
        "아마 자네는 엄청난 힘을 지닌 생물을 원할지도 모르겠군. 새끼곰은 자네 같은 풋내기 사냥꾼에게 훌륭한 동반자이며, 골드샤이어 동쪽에서 찾을 수 있다네. 여기 조련용 막대가 있네. 이 동물을 야수로 삼아보고 마음에 드는지 확인해 보게!\n\n돌아오면, 자네가 선택한 동물을 길들이는 데 필요한 기술을 알려주겠네. 이 생물은 자네가 직면하는 도전에 맞서고 자네와 함께 경험을 쌓을 걸세. 또한, 녀석을 자유롭게 부르고 해제하는 방법도 보여주지.",
    },
    [26413] = {
        ["T"] = "야수 훈련",
        ["O"] = "스톰윈드에 있는 호위 하위(Howie Hill)와 대화하십시오.",
        ["D"] =
        "$N, 자네는 이제 야수를 길들일 수 있는 힘을 얻었지만 녀석을 훈련시킬 수 있는 기술도 얻어야 하네.\n\n스톰윈드로 가서 드워프 지구를 찾게. 그곳에서 우리의 가장 존경받는 동물 조련사 중 한 명인 호위 하위와 대화해야 하네. 그가 새로운 야수를 훈련시킬 수 있는 힘을 줄 테니, 어서 가게!\n\n호위는 다정한 사람이니 그의 승인을 얻는 데는 아무런 문제가 없을 걸세. 행운을 비네, $N.",
    },
    [26414] = {
        ["T"] = "너덜너덜한 편지",
        ["O"] = "너덜너덜한 편지를 읽고 노스샤이어 수도원에 있는 시시(Cece Herbert)와 대화하십시오.",
        ["D"] =
        "코볼트 야영지에서 돌아오자마자 이것을 자네에게 전해 달라는 부탁을 받았네, $N. 우리 지역의 사냥꾼 전문가인 시시가 보낸 편지 같군. 수도원에서 다른 일을 하기 전에 주저하지 말고 읽어보게나.",
    },
    [26415] = {
        ["T"] = "문양 룬",
        ["O"] = "앤빌마 안에 있는 마렉 스트롬누르(Marrek Stromnur)와 대화하십시오.",
        ["D"] =
        "자네가 날 돕는 동안 이걸 자네에게 전해달라고 받았어. 시간 날 때 한번 읽어보게. 마법사 전문가 마렉이 보낸 것 같군. 한번 살펴보고 시간 날 때 앤빌마 안에 있는 그를 찾아가 보게.",
    },
    [26416] = {
        ["T"] = "테라모어 섬으로 가는 문",
        ["O"] =
        "저주받은 땅의 새로운 어둠의 문 근처에서 첫 번째 어둠의 문 파편 3개를 수집한 다음 테라모어 섬에 있는 여군주 제이나 프라우드무어에게 돌아가십시오.",
        ["D"] =
        "다시 만나서 반갑군요, $N. 제가 있는 도시로 순간이동하는 것이 꽤 유용했기를 바랍니다. 그렇다면, 동료들을 위해 차원문을 열어보는 건 어떨까요? 이번에 당신에게 줄 임무는 훨씬 더 어렵지만, 주문 너머에 또 다른 보상을 준비해 두었습니다.\n\n먼저 저주받은 땅에 있는 어둠의 문으로 가셔야 합니다. 그 저주받은 문은 오크의 고향인 드레노어로 들어가는 입구이지만, 사실은 두 번째 어둠의 문입니다. 첫 번째 문은 제2차 대전쟁 당시 침략하는 오크들을 막으려는 대마법사 카드가의 시도로 파괴되었죠. 새 문 근처에서 아직 그 문 파편을 찾을 수 있습니다. 저를 위해 작은 파편 세 개를 수집해 오시면 계속 진행할 수 있습니다.",
    },
    [26417] = {
        ["T"] = "테라모어 섬으로 가는 문",
        ["O"] = "운고로 분화구 주변에서 녹색 마력의 결정 5개를 수집한 후, 테라모어 섬에 있는 여군주 제이나 프라우드무어에게 돌아가십시오.",
        ["D"] =
        "잘하셨습니다. 이 파편들은 당신의 완--\n\n<여군주 제이나가 기침을 합니다.>\n\n깜빡하고 놀라움을 망칠 뻔했군요! 다음으로, 운고로 분화구에서 녹색 마력의 결정 5개가 필요합니다. 분화구 주변에 흩어져 있죠. 한 번도 가본 적이 없다면 타나리스 남서쪽에서 내려가는 길을 찾을 수 있습니다. 하지만 분화구 안으로 천천히 떨어지기 주문을 시전하고 뛰어내리는 것이 더 재미있을지도 모르겠군요!",
    },
    [26418] = {
        ["T"] = "테라모어 섬으로 가는 문",
        ["O"] =
        "검은바위 나락으로 들어가 7인의 제왕을 쓰러뜨리고 세스렐(Seeth\'rel)의 고서를 얻은 후, 테라모어 섬에 있는 여군주 제이나 프라우드무어에게 돌아가십시오.",
        ["D"] =
        "자, 이 여행들의 목적을 밝힐 때가 되었군요! 테라모어 섬으로 통하는 차원문을 생성하는 방법을 가르쳐주는 것 외에도, 당신에게 쓸 머리 장비를 하나 선물할까 합니다. 일종의 관이죠. 음, 당신이 재료의 대부분을 모아야 했으니 대단한 선물은 아닐지도 모르겠지만, 제게는 이것들이 없었거든요! 이 관에 대한 아이디어는 얼마 전에 떠올렸습니다. 황천의 기운이 닿은 돌을 사용하고 부서진 마력의 결정으로 힘을 불어넣는 것이죠. 잘 만들어졌으면 좋겠군요!\n\n하지만 구성 요소가 하나 더 필요합니다. 이런 돌들을 하나로 묶는 것은 흔한 지식이 아니지만, 한때 어둠괴철로 도시에 살았던 세스렐이라는 강력한 마술사가 쓴 책에 자세한 설명이 있다는 것을 읽었습니다. 그곳은 검은바위 나락입니다. 그곳에 가서 그 고서를 되찾아온다면 이 관을 완성할 수 있을 것입니다.",
    },
    [26419] = {
        ["T"] = "스토나드로 가는 문",
        ["O"] =
        "저주받은 땅의 새로운 어둠의 문 근처에서 첫 번째 어둠의 문 파편 3개를 수집한 다음 스토나드에 있는 로린 폭스파이어에게 돌아가십시오.",
        ["D"] =
        "아, $C! 만나서 반갑습니다. 당신에게 제안할 것이 있습니다. 그저 스토나드로 순간이동하는 대신, 아군을 위한 차원문을 여는 것은 어떨까요? 제 발명품 하나를 도와주시기만 하면 됩니다. 제 이론대로라면, 그 물건을 당신이 가질 수 있도록 허락해 드리죠.\n\n가치 있는 일이라 생각하신다면, 이곳에서 남쪽으로 여행하여 저주받은 땅으로 가십시오. 그리고 현재의 어둠의 문 근처 땅에 흩어져 있는 원래의 어둠의 문 파편들을 좀 주워오십시오. 죽고 싶지 않다면 문에 너무 가까이 가지 마십시오.",
    },
    [26420] = {
        ["T"] = "스토나드로 가는 문",
        ["O"] = "운고로 분화구 주변에서 녹색 마력의 결정 5개를 수집한 후, 스토나드에 있는 로린 폭스파이어에게 돌아가십시오.",
        ["D"] =
        "다음 임무는 조금 더 멀리 떨어진 칼림도어에서 수행해야 합니다. 운고로 분화구로 여행하여 녹색 마력의 결정 5개를 수집하십시오. 분화구 전체에 마력의 결정이 흩어져 있으니 어디서든 찾을 수 있을 겁니다. 이것들은 잘 알려져 있지 않은데, 그것이 제가 당신에게 이 일을 시키는 주된 이유입니다. 한 번도 가본 적이 없다면 타나리스 남서쪽에서 분화구로 내려가는 길을 찾을 수 있습니다. 무모한 기분이 든다면 천천히 떨어지기를 시전하고 분화구 안으로 뛰어내려도 되고요.\n\n잡아먹히지 않도록 조심하십시오.",
    },
    [26421] = {
        ["T"] = "스토나드로 가는 문",
        ["O"] =
        "검은바위 나락으로 들어가 7인의 제왕을 쓰러뜨리고 세스렐의 고서를 얻은 후, 스토나드에 있는 로린 폭스파이어에게 돌아가십시오.",
        ["D"] =
