        "아케이나이트 마갑을 티리스팔 숲의 평온의 정원에 있는 붉은십자군 성기사에게 가져가십시오. 그들을 보려면 정기의 토템이 필요합니다.",
        ["D"] =
        "<아투르크가 자부심에 찬 미소를 지으며 이마의 땀을 닦습니다.>\n\n내가 드레노어에서 수습 생활을 시작했을 때, 성스러운 전사를 위해 말의 갑옷을 만들게 될 줄은 꿈에도 몰랐지. 하지만 나의 포세이큰 친구여, 이건 내 최고의 작품 중 하나야. 내게 최고의 품질을 제공할 수 있다고 믿어줘서 고맙다.\n\n분명 네 안내자가 직접 이 작품의 솜씨를 판단하고 싶어 할 거다. 네 마갑을 그들에게 가져가 보고, 문제가 있으면 다시 돌아와라.",
    },
    [26437] = {
        ["T"] = "말의 영혼",
        ["O"] =
        "안돌할의 폐허로 이동하여 그곳의 헛간에 있는 말의 영혼을 풀어주십시오. 말의 영혼과 대화하여 아케이나이트 마갑을 축복받으십시오. 그런 다음 티리스팔 숲의 평온의 정원에 있는 붉은십자군 성기사에게 돌아가십시오. 그들을 보려면 정기의 토템이 필요합니다.",
        ["D"] =
        "네 마갑은 특별한 형태의 축복, 즉 합당한 영혼의 축복을 받아야 한다. 멀지 않은 안돌할의 폐허에 도시가 함락될 때 갇힌 말들의 영혼이 느껴진다. 그들을 풀어주면 그들이 보상으로 네 마갑에 축복을 내려줄 것이다.\n\n모두 풀어주어야 한다, $N. 그렇지 않으면 축복은 실패할 것이다. 너 같은 흉측한 괴물에겐 당연히 실패할 거라고 예상하고 있다만.",
    },
    [26438] = {
        ["T"] = "예언의 탐지기",
        ["O"] =
        "아제로스 다이아몬드 1개와 온전한 검은 다이아몬드 1개를 티리스팔 숲의 평온의 정원에 있는 붉은십자군 성기사에게 가져가십시오. 그들을 보려면 정기의 토템이 필요합니다.",
        ["D"] =
        "정말로 이걸 끝낼 생각이라면, 쓰러진 군마를 되살릴 방법이 필요하다. 네가 나와 대화하기 위해 사용하는 정기의 토템이 이 장치의 기본 바탕이 될 것이다.\n\n나머지 필요한 구성 요소는 두 개의 다이아몬드다. 빛으로 장막을 꿰뚫으려면 두 다이아몬드가 나란히 찬란하게 빛을 발해야 한다. 따라서 아제로스 다이아몬드와 온전한 검은 다이아몬드가 필요하다. 이 두 개를 집중제로 사용하면 정기의 토템이 네 신성한 의지의 등대 역할을 할 수 있게 될 것이다.\n\n<붉은십자군 성기사가 몸서리칩니다.>\n\n내 꼴을 보라지, 마치 네가 가치 있는 존재라도 되는 것처럼 말을 섞고 있다니.",
    },
    [26439] = {
        ["T"] = "심판과 구원",
        ["O"] =
        "스칼로맨스에 있는 대납골당의 지하실 심장부에서 예언의 탐지기를 사용하십시오. 그렇게 하면 심판해야 할 영혼들이 나타납니다. 이 영혼들을 무찌르면 죽음의 기사 다크리버가 소환됩니다. 그를 무찌르고 잃어버린 쓰러진 군마의 영혼을 되찾으십시오.\n\n군마의 구원받은 영혼과 축복받은 마력 깃든 마갑을 다크리버 군마의 영혼에게 주십시오.",
        ["D"] =
        "이 가방을 가져가라 -- 안에는 네 임무에 필요한 물건들이 들어 있다.\n\n대납골당의 지하실 심장부에서 예언의 탐지기를 사용하여 심판해야 할 저주받은 영혼들을 불러내라. 이 시험 동안 네 심판을 지혜롭게 사용해라 -- 그것들은 네가 생각하는 것보다 더 강력한 효력을 발휘할 것이다. 영혼들 다음에는 죽음의 기사가 나타날 것이다. 그를 무찌르고 잃어버린 군마의 영혼을 되찾아라. 그래야만, $N, 네가 그것을 구원하고 새 군마에 마갑을 씌울 수 있을 것이다!",
    },
    [26440] = {
        ["T"] = "타락한 기사",
        ["O"] = "언더시티 깊은 곳에 있는 타락한 기사와 대화하십시오.",
        ["D"] =
        "때가 왔다, $N. 네가 여행 중에 의심할 여지 없이 생각했을 것... 바로 군마를 얻기 위해 무엇이 필요한지 배울 시간이다.\n\n언더시티에 있는 타락한 기사와 대화하라. 그녀가 필요한 임무를 안내해 줄 것이다.\n\n이 시험에서 좋은 결과가 있기를 바란다. 빛을 위하여, 고귀한 $g형제여:자매여;!",
