    [26441] = {
        ["T"] = "고귀한 군마",
        ["O"] = "언더시티에 있는 타락한 기사와 대화하십시오.",
        ["D"] =
        "다시 만나서 반갑군, $N. 자네를 $g 형제:자매;라고 부를 수 있어서 그 어느 때보다 자랑스럽네. 자네의 헌신은 우리 모두에게 귀감이 되니까.\n\n이제 자네에게 큰 선물을 내릴 때가 되었네. 하지만 명심하게, 지금은 이것을 대가 없이 주지만, 나중에 시간이 허락한다면 내 퀘스트를 수행하려는 모든 성기사들에게 훨씬 더 큰 도전이 될 것이라는 걸.\n\n다시 내게 말을 걸면 큰 축복을 내려주지.",
