    [26442] = {
        ["T"] = "고귀한 군마",
        ["O"] = "언더시티에 있는 타락한 기사와 대화하십시오.",
        ["D"] =
        "안녕, $N. 자네의 신앙만큼이나 헌신적인 모습이 여전히 강하군.\n\n언더시티에 있는 타락한 기사와 이야기를 나눌 때가 된 것 같네. 자네가 배워야 할 교훈이 더 남아 있고, 난 자네가 준비되었다고 느끼거든.\n\n바깥쪽 고리를 따라 그녀를 찾아보게나. 그리고 $N, 이 가르침을 진지하게 받아들이게. 겸손과 노력으로 지금의 지위에 올랐으니, 오만해져서 우리를 실망시키는 일이 없도록 해.\n\n무사하길.",
