        ["D"] =
        "반갑습니다, $G형제여:자매여;. 우리의 가장 영향력 있는 태양길잡이 중 하나인 시시카 어스혼 님께서 최근에 당신에 대해 말씀하셨습니다. 이제 당신이 시험을 받을 때가 되었다는 말씀과 함께... 당신이 지금까지 얼마나 잘 해왔는지에 대해 아주 칭찬을 아끼지 않으시더군요.\n\n제가 당신이라면 시간이 날 때 썬더 블러프로 가서 그녀와 대화하겠습니다. 그녀는 필시 정기의 봉우리에 계실 겁니다 -- 그곳이 그녀가 대부분의 시간을 보내는 곳이니까요.",
