        ["O"] = "썬더 블러프에 있는 시시카 어스혼과 대화하십시오.",
        ["D"] =
        "무엇보다도, 태양길잡이는 우리의 힘을 보완하는 따뜻함을 반영해야 합니다. 우리 같은 자가 신성해지기 위해 노력한다는 것은 신이 되기 위해 애쓴다는 뜻이 아닙니다 -- 모든 행동에서 선해지기 위해 노력한다는 뜻이죠.\n\n이 가혹한 시대에서 어둠을 쳐부수라는 부름을 받긴 했지만, 다른 사람을 돕는 것이야말로 아제로스의 시민들 사이에서 당신을 진정으로 차별화하는 것임을 항상 기억해야 합니다. 동정심, 인내, 용기 -- 이런 것들은 전투에서의 힘만큼이나 태양길잡이에게 의미 있는 것들입니다.\n\n이것을 잘 알고 절대 잊지 마십시오.",
    },
    [26446] = {
        ["T"] = "신앙의 두루마리",
        ["O"] = "썬더 블러프의 주 봉우리에서 테야 스위프트토템을 찾으십시오.",
        ["D"] =
        "그렇다면 당신의 임무는, $n, 여기 썬더 블러프에서 도움이 필요한 사람을 찾는 것입니다. 마음과 동기가 순수한 사람 말입니다. 어쩌면 다른 사람을 돕고 있는 사람일 수도 있고. 길잡이가 필요한 사람일 수도 있죠. 여하튼, 그 사람은 고귀한 의도를 가지고 당신의 친절에 의지하고 있어야 합니다.\n\n그 일을 마친 후 제게 돌아오십시오. 그런 다음, 우리는 당신의 길과 태양 속을 걷는다는 것이 무엇을 의미하는지에 대해 더 깊이 논의할 것입니다.",
