        ["O"] = "리넨 옷감 10개를 썬더 블러프에 있는 테야 스위프트토템에게 가져가십시오.",
        ["D"] =
        "가엾은 아이들, 켄타우로스의 공격과 호드의 땅 곳곳으로 우리 종족이 흩어진 탓에 대부분 가족이 없어요.\n\n보통 옷이나 가죽을 구해서 만들지만 점점 구하기 어려워지고, 제가 온통 신경 쓸 수 있는 건 아이들을 따뜻하고 안전하게 지키고 머리 위에 지붕을 씌워주는 것뿐이에요.\n\n아이들을 위한 옷을 지을 수 있게 리넨 옷감을 좀 가져다주시면 큰 도움이 될 거예요.",
