    [26448] = {
        ["T"] = "신앙의 두루마리",
        ["O"] = "썬더 블러프에 있는 시시카 어스혼과 대화하십시오.",
        ["D"] =
        "오늘 안으로 이 옷감들이 꼭 아이들에게 전달되도록 하겠습니다. 부디 무사하십시오, 친절한 $c 님. 당신 같은 성품을 가진 $g분이:분이; 도시에 얼굴을 내미는 일은 흔치 않지만, 당신은 이곳 썬더 블러프에서 태양을 따르는 자들이 결코 다른 이들을 어둠 속으로 이끌지 않는다는 것을 증명해 보이셨습니다.\n\n안녕히 가십시오.",
