        ["O"] = "생명의 십자가를 썬더 블러프에 있는 송가 클라우드라이더에게 가져가십시오.",
        ["D"] =
        "이것을 받으십시오, $n. 이것은 생명의 십자가라고 불립니다.\n\n당신은 자애롭고 인내심이 강하다는 것을 증명하셨으니, 이제 당신이 태양의 가장 위대한 선물 중 하나를 집중할 만큼 충분히 강력한지 확인할 차례입니다.\n\n제 친구 송가가 최근 블러드후프 마을 근처에서 벤처 투자회사 녀석들과 마주쳤다가 가까스로 목숨만 건져 돌아왔습니다.\n\n십자가를 가지고 그에게 가서 대화하십시오. 만약 당신이 그를 도울 수 있다면, 우리는 곧 다시 이야기하게 될 것입니다. 태양의 따스함이 함께하길.",
    },
    [26450] = {
        ["T"] = "신앙의 두루마리",
        ["O"] = "생명의 십자가를 사용하여 멀고어에 있는 다코다 프리로어(Dakoda Freeroar)를 부활시키십시오.",
        ["D"] =
        "다코다와 나는 블러드후프 마을 바로 북동쪽에 있는 벤처 투자회사 광산까지 갔었지. 그놈들이 우리 평원에 침투했다는 소식을 듣고 대부족장님께 가져갈 증거를 원했거든.\n\n서류를 살펴보고 있는 쓰레기 두 놈을 발견하고 우리는 공격했어. 불행히도 우리는 감당할 수 있는 것보다 더 많은 수의 녀석들에게 금세 압도당하고 말았지.\n\n내가 도망칠 수 있도록 다코다가 녀석들을 막아냈어... 그 멍청한 바보, 주제넘게 용감한 척하긴.\n\n호수 해안가 쓰러지는 걸 분명히 봤지만 난 돌아갈 수가 없었어. 다코다는 지금 거기 있어, 우릴 도와줄 수 있겠나, $n?",
