        ["D"] =
        "나중에 십자가에 대해 더 자세히 이야기할 시간이 있을 거요. 지금 중요한 건 벤처 투자회사 녀석들에게서 그 서류를 얻는 거니까. 우리가 그걸 손에 넣으면, 그들이 멀고어에 침투했다는 것과 배후에 누가 있을지 모른다는 증거를 확보할 수 있을 테지.\n\n난 지금 전투를 치를 몸 상태가 아니야, $n. 광산에 있는 감독관들에게서 서류를 빼앗아 올 만큼 자네가 강하다고 생각하나? 만약 서류를 구하게 되면, 송가에게 가져다주고 내가 무사하다고 전해줘.",
