        ["O"] = "썬더 블러프에 있는 시시카 어스혼과 대화하십시오.",
        ["D"] =
        "시시카가 살펴본 후에 문서를 부족장님께 가져가겠소. 끝에 적힌 그 이니셜들... 영 찜찜하군. 그동안 자네는 시시카에게 가서 직접 이야기해보게나. 그녀가 자네 등을 두드려 주고 싶어 할 테니까.\n\n다시 한 번 고마워, $n. 다시 만나길 바라. 자네는 내가 친구라고 부르기 자랑스러운 동맹이야.",
