        "첫 번째 진짜 수업을 받을 준비가 되었군, $C $N. 하지만 난 네가 읽을 수 있는 신앙의 고서 사본을 가지고 있지 않으니, 살아있는 성기사가 하는 방식과는 상당히 다를 것이다.\n\n\"동정심, 인내, 용기--이러한 것들은 전투에서의 힘만큼이나 성기사에게 의미가 있습니다.\" 이는 그 고서에 있는 많은 구절 중 하나이며, 네가 배워야 할 내용이다. 우리는 죽은 자, 불경한 존재인데, 왜 빛이 우리에게 응답하는지 나도 이해할 수 없다. 우리 자신의 영혼조차 우리가 쟁취해야 할 이상에 맞서 싸우고 있으니까.\n\n쏟아지는 말을 받아들일 준비를 하고 다시 내게 말을 걸어라.",
