        ["D"] =
        "잘 왔네, $g 형제:자매;여. 타락한 기사를 만나보았나? 그녀는 막강한 성기사지만 살아생전의 정체에 대해서는 비밀로 하고 있어서 우리가 그렇게 부르고 있지. 난 자네가 그녀에게서 배울 준비가 되었다고 믿네. 내가 가르칠 수 없는 교훈들이 있거든.\n\n언더시티 군사 지구에서 그녀가 끔찍한 진흙탕에서 낚시를 하고 있는 걸 찾을 수 있을 거야. 난 그게 뭔지 모르고 살았으면 좋겠군. 빛이 자네와 함께하길.",
