        ["D"] =
        "이제 시작할 수 있겠다, $N. 원래대로라면 마음과 동기가 순수한 사람을 찾아 보내고 싶지만, 우리 모두 심장이 더 이상 뛰지 않는 상황에서는 지나친 요구라는 걸 인정할 수밖에 없군. 그러니 올바른 방향으로 등을 밀어주겠다.\n\n운하 건너편에서 훈련 중인 알리사 블레예를 찾아봐라 -- 사실 여기서도 볼 수 있지. 그녀는 스컬지가 덮치기 전 로데론의 고아원 원장이었다. 지금 그녀는 그런 비극이 다시는 일어나지 않도록 막는 데 모든 훈련 시간을 쏟고 있지.\n\n아이들에 대해서는 묻지 마라, $N.",
