        ["D"] =
        "자네 여행의 다음 단계로 나아가, 수많은 $C를 죽음에서 구해낸 기술을 배울 때가 왔네. 언덕마루 구릉지의 라벤홀트 장원에서 소식이 왔어.\n\n장원의 거주민들은 아주 비밀스러운 조직이라 이건 꽤 이례적인 일이라네. 어둠 속 인물들에게 인상이라도 남긴 겐가? 촛불에 비춰 이 편지를 읽어보고 지시대로 그곳으로 향하게나.",
