        "칼림도어의 바람이 당신을 맞이하러 몰아치고 있으며, 당신은 우리의 가장 강력한 $G 형제들:자매들; 중 한 명으로 꼽힐 것입니다. 당신이 여기까지 왔고 그토록 촉망받는 미래를 가진 것을 보니 자랑스럽습니다.\n\n바람의 정령을 조종하는 것은 어려운 일이지만, 당신의 기술이 눈앞에 놓인 어떤 장애물이든 극복해낼 것이라 믿어 의심치 않습니다.\n\n임시 주둔지 서쪽에 있는 아라시 고원의 맨 북쪽으로 향하여 텐린 와일드해머를 찾으십시오. 그녀가 당신을 가르칠 것입니다.",
