        "때가 왔다, 젊은 $c. 너는 강해졌고 네 영혼은 대지처럼 인내한다. 주술사의 길을 걷는다는 것은 네 자신을 증명하기 전부터 지혜를 갖추었다는 것을 보여준다.\n\n대지의 정령이 네 운명을 인도하여, 네가 준비되었다면 너의 일부가 될 것이다. 하지만 넌 대지 그 자체의 앞에 서야 한다. 준비가 되었다면 주술사만이 아는 것들을 보게 될 것이다.\n\n남서쪽에 있는 서리갈기트롤 새끼들을 찾아가 그들의 모조 그릇 두 개를 빼앗아라. 그런 다음 내게 돌아오면 네 미래에 대해 더 이야기 나누도록 하지.",
