        "이 천연 석영을 받아서 우리가 만났다는 증표로 울파른 볼드브레이드에게 가져가라. 그가 널 위해 토템을 만들어 줄 것이고, 이 조약돌은 그 토템의 심장이 될 것이다. 작아 보일지 몰라도 크기는 중요하지 않으며, 아무리 작은 것이라도 산보다 오래 지속될 수 있다는 것을 알게 될 것이다.\n\n인내심을 가져라, $N. 강인함을 유지하라. 그리고 지혜를 구하라. 이것이 대지가 네게 요구하는 것이다. 결국, 너는 대지와 하나가 될 것이다 -- 네가 대지를 존중하면 대지도 널 존중할 것이다.",
