        ["D"] =
        "당신은 불의 토템을 휘두를 만큼 강력하지만, 그렇다고 해서 당신이 준비되었다는 뜻은 아닙니다.\n\n모단 호수의 텔사마 남쪽에서 가장 높은 봉우리 중 하나로 향하는 숨겨진 오솔길을 찾을 수 있을 겁니다. 길에는 주술사 돌이 표시되어 있습니다. 꼭대기까지 올라가면 쥴두그 파이어테일이 지키고 있는 성스러운 제단 중 하나인 땅에 갇힌 불꽃의 제단을 발견할 수 있습니다.\n\n이 횃불을 그에게 가져가십시오 -- 이것은 당신이 불을 길들이려 한다는 것을 의미합니다. 제단의 화로에 불을 붙여 내게 돌아오면 불의 토템을 주겠습니다.",
