        ["D"] =
        "하지만 당신은 역사 수업을 들으러 온 것이 아니지요? 영원의 불꽃과 불의 토템을 구하러 온 것이 분명합니다.\n\n첫 번째 단계는 정기를 만들어 당신을 불꽃과 결속시키는 것입니다.\n\n두 가지 물건을 가져다주면 불의 정기를 만들어 줄 수 있습니다. 첫 번째는 돌부스러기 정찰병들이 주로 지니고 다니는 불붙인 타르로, 이곳 남쪽과 북서쪽에서 찾을 수 있는 단순한 물건입니다.\n\n두 번째 물건은 더 위험할 것입니다. 검은무쇠 일족 중 한 명의 시약 주머니입니다. 던 모로 남동쪽 아이언밴드 야영지에서 그들을 찾을 수 있습니다.",
