        ["D"] =
        "불의 정기가 완성되었습니다. 이제 당신이 불꽃을 마주할 때입니다. 제단에서 정기를 사용하고 산꼭대기로 향하여 그곳에 있는 현신과 마주하십시오. 당신이 준비될 때까지 그는 공격하지 않겠지만, 당신이 그를 볼 수 있다는 것을 알아차릴 것입니다.\n\n재빨리 그를 쓰러뜨리십시오, $n. 당신이 그를 쓰러뜨리는 데 오랜 시간이 걸릴수록 그의 힘은 더 강해질 것입니다. 그를 물리치면 화로 안에 그의 타오르는 불꽃을 넣고 횃불에 불을 붙이십시오.",
