        ["O"] = "저습지에서 기르나 블레스드브루를 찾으십시오.",
        ["D"] =
        "부정할 수 없군요, 당신의 미래에는 물이 기다리고 있습니다. 당신이 이미 불의 방식에 강하다는 것을 알고 있으니, 이제 기르나와 대화할 준비가 된 것 같군요.\n\n기르나는 메네실 항구 남서쪽 저습지 해안을 따라 살고 있습니다. 놓칠 리 없을 겁니다. 그녀의 위엄 있는 그리핀이 당신의 머리 위를 날아다니는 집과 부두를 찾으십시오.\n\n그녀는 정령의 방식에 강하고 당신에게 물의 방식을 가르칠 수 있습니다... 만약 당신이 준비되었다고 생각한다면 말입니다. 근처를 배회하는 멀록들을 조심하십시오. 그들은 물을 받아들이고 물을 자신의 것이라 주장하니까요.",
    },
    [26489] = {
        ["T"] = "물의 부름",
        ["O"] = "기르나의 부두 아래에 있는 균열에서 빈 갈색 물주머니를 채운 후 저습지에 있는 그녀에게 가져가십시오.",
        ["D"] =
        "깨달음을 얻고 내게서 정기를 얻으려면, 가장 순수한 형태의 물만 찾아야 합니다. 나를 위해 샘플을 가져오는 동안 주변 환경에 주의를 기울이십시오. 물에 의지하고 물을 보호하는 생명체들을 인식하십시오. 물이 숲과 사막에 어떤 영향을 미치는지 확인하십시오. 생명을 지탱하는 바로 그 물질이 어떻게 생명체가 생명을 앗아가도록 강요하는지 목격하십시오.\n\n우리는 간단한 일부터 시작할 것입니다: 여기서 북서쪽으로 조금 떨어진 물 아래에는 귀중한 천연 샘물을 바다로 흘려보내는 균열이 있습니다. 이 물주머니를 그 샘물로 채워서 내게 돌아오십시오.",
    },
    [26490] = {
        ["T"] = "물의 부름",
        ["O"] = "돌발톱 산맥의 바위웅덩이 호수에서 빈 빨간색 물주머니를 채우십시오.",
        ["D"] =
        "칼림도어의 돌발톱 산맥 깊은 곳에는 현지인들이 바위웅덩이라고 부르는 오염된 호수가 있습니다. 벤처 투자회사가 그 지역에 헤아릴 수 없는 피해를 입혔죠. 나도 한때 이 문제를 바로잡으려 했지만 헛수고였습니다.\n\n남쪽 산맥을 따라 잿빛 골짜기 깊숙이 들어가 발톱동굴 샛길(Talondeep Path)에 도달하십시오. 거기서부터 돌발톱에 도착하게 됩니다. 바위웅덩이 호수 안의 샘물 균열에서 샘플을 가져오면 정기에 한 걸음 더 다가갈 수 있을 것입니다.",
    },
    [26491] = {
        ["T"] = "물의 부름",
        ["O"] = "까마귀 언덕에 있는 우물에서 빈 파란색 물주머니를 채우고 저습지에 있는 기르나에게 돌아가십시오.",
        ["D"] =
        "오래 전 나는 동료들을 따라 그늘숲 깊은 곳으로 들어갔습니다. 그곳을 배회하는 끈질긴 좀비들로부터 몸을 방어하다가 좀비들이 장악하지 못한 작은 정착지에 도착하게 되었죠. 그곳이 까마귀 언덕이었습니다.\n\n그곳에서 나는 가장 기이한 것을 발견했습니다. 정착지 중앙에 천연 샘물이 솟아나는 작은 우물이 있었던 것이죠. 근처 마을 주민들이 그 가치를 제대로 알고 있는지 의문입니다 -- 그것은 부정한 바다 한가운데 있는 작은 성스러운 흔적이었습니다.\n\n그 물의 샘플을 이 물주머니에 담아오십시오.",
    },
    [26492] = {
        ["T"] = "물의 부름",
        ["O"] =
        "타락한 물의 현신을 처치하고 타락한 현신의 팔보호구와 얼마 남지 않은 순수한 물을 어둠해안에 있는 샘물의 화로에 놓으십시오.",
        ["D"] =
        "아우버다인에서 북동쪽으로 멀리 떨어진 어둠해안 앞바다의 섬에는 지옥 마법의 타락으로 오염된 제단이 있습니다. 그곳의 영혼들은 더 이상 우리 사람들에게 말하지 않으니 현신을 처치하고 연못을 정화하는 것은 당신에게 달려 있습니다.\n\n북쪽으로 난 길을 따라 연못까지 쭉 가십시오. 정령과 싸우고 녀석의 팔보호구를 가져다가 기르나의 물약 남은 방울과 함께 화로 위에 놓으십시오. 이 의식은 당신이 대화할 순수한 영혼을 소환하기에 충분할 것입니다.\n\n임무를 완수했다는 증거를 가져오면 보상으로 토템을 주겠습니다.",
    },
    [26493] = {
        ["T"] = "물의 부름",
