        "결정을 가져가라. 결정을 가져가고 생명을 주어라.\n\n생명을 주고 이해하라. 물이 곧 생명임을 이해하라... 타락은 생명을 멈춘다.\n\n너는 물의 힘으로 보호하고 생명을 준다.",
