    [26495] = {
        ["T"] = "공포마",
        ["O"] = "",
        ["D"] = "<출시일 스포일러를 방지하기 위해 전체 퀘스트가 비활성화되었습니다.>",
    },
    [26496] = {
        ["T"] = "의식의 지식",
        ["O"] =
        "검은바위 첨탑 하층으로 들어가 붉은방패부대 흑마법사, 횃불부대 공포술사, 핏빛도끼부대 소환사에게서 인쿨라의 노트를 수집하십시오. 불타는 평원에 있는 주나리에게 노트를 가져가십시오.",
        ["D"] =
        "검은바위 첨탑 하층으로 밀고 들어온 오크 부족들의 대열에는 여러 유형의 흑마법사들이 있다. 붉은방패부대는 다방면의 능력을 뽐내고, 횃불부대는 공포에 특화되어 있으며, 핏빛도끼부대는 악마를 부리는 데 능숙하지.\n\n그들의 공통점은 모든 흑마법사들이 인쿨라 여군주에게 보고했다는 거다. 아니, 그녀가 나를 만나기 전까지는 그랬지.\n\n인쿨라는 흑마법사가 생명석의 마나 샘을 생성할 수 있는 의식을 고안한 영리한 오크였다. 누구도 자신의 권력에 도전하지 못하도록 그녀는 자신의 지식을 세 부족 모두에 흩어놓았지.\n\n그런 의식이 있다면 꽤 유용하지 않겠나, $N? 첨탑에서 노트를 회수하면, 내가 그 노트를 해석하는 것을 도와주겠다.",
    },
    [26497] = {
        ["T"] = "오래된 양피지",
        ["O"] = "오래된 양피지를 읽고 시험의 골짜기에 있는 동굴 안의 나르톡과 대화하십시오.",
        ["D"] =
        "아, 자네가 없는 동안 양피지가 하나 도착했네, $N.\n\n나는 흑마법사와 엮이는 건 가급적 피하려 하지만, 시간이 날 때 읽어보는 게 좋을 것 같군. 내 짐작이 맞다면 자네가 새로 임명된 훈련 교관인 나르톡이 보낸 것일 거네. 자네가 준비되면 자네와 할 이야기가 있다는군.",
    },
    [26498] = {
        ["T"] = "앨리슨을 위한 꽃",
        ["O"] =
        "알터랙 산맥에서 서리 엉겅퀴 8개를 수집하여 남녘해안 묘지에 있는 앨리슨 몽클레어(Allison Mont Claire)의 무덤에 놓으십시오.",
        ["D"] =
        "안녕하시오, 낯선 이여. 남녘해안으로 가는 길이시오? 만약 그렇다면 부탁 하나만 들어주시겠소?\n\n전쟁 전에 나는 앨리슨 몽클레어라는 소녀를 사랑했었소. 그 후 나는 바다로 나갔고, 스컬지가 닥쳤지. 집에 돌아왔을 때, 나는 앨리슨을 발견했소. 그녀는 남녘해안의 묘지에 묻혀 있소.\n\n도저히 그녀의 무덤을 다시 찾아갈 엄두가 나지 않지만, 그녀에 대한 기억은 기리고 싶소. 당신이 알터랙 산맥에서 서리 엉겅퀴를 몇 개 꺾어다 그녀의 무덤에 놓아준다면 정말 고맙겠소.",
    },
    [26499] = {
        ["T"] = "마법 물자",
        ["O"] =
        "달라란 소환사들과 대화하여 개방의 룬을 얻은 다음, 이를 사용하여 달라란 주변에 마법으로 봉인된 금고를 열고 그 안에 있는 마법 물자를 수집하십시오. 알터랙 산맥의 달라란 근처에 있는 대마법사 앤자이럼 룬위버에게 마법 물자 30개를 가져가십시오.",
        ["D"] =
        "그러니까 우리를 돕고 싶단 말이지? 자네에게 딱 맞는 일이 있네!\n\n보다시피 달라란 주위에 세운 마법 돔 외부에는 폐허가 된 구조물들이 있네. 폐허 속 몇몇 장소에서 마법으로 봉인된 금고를 찾을 수 있을 거야. 금고의 비전 자물쇠는 개방의 룬으로 열 수 있다네.\n\n해당 지역의 달라란 소환사들과 대화하여 개방의 룬을 빌려달라고 요청하게. 그런 다음 상자를 수색하고 안에 있는 마법 물자를 수집해 주게. 조심해야 하네 - 일부 상자에는 수호자를 소환하는 주문이 걸려 있을 수도 있으니까.",
    },
    [26500] = {
        ["T"] = "기묘한 고서",
        ["O"] = "강령술 고서를 스톰윈드의 스톰윈드 항구에 있는 웬델 스파크브라이트(Wendel Sparkbright)에게 가져가십시오.",
        ["D"] =
        "자네가 모아온 잡동사니 더미에서 신경 쓰이는 물건을 발견했네. 이것은 강령술의 고서로, 금지된 마법을 수행하여 결국 우리 도시와 로데론을 몰락으로 이끈 장본인이지. 자네가 이 책을 어느 집에서 가져왔는지 기억하지 못할 거라 생각하는데...?\n\n다행히도 우리에게는 이 고서에 독자의 결계가 새겨져 있다네. 자네가 결계나 마법 방어에 대한 이야기를 듣는 것에 지쳤다는 건 알지만, 한 번만 더 내 설명을 들어주게. 이 결계는 의도된 독자를 제외한 모든 사람에게 고서 안의 글자들을 뒤섞어버린다네. 우리는 이 결계를 건 사람이 누구인지, 즉 이 고서의 주인이 누구였는지 알아낼 수 있네.\n\n이 고서를 스톰윈드의 웬델 스파크브라이트에게 가져가게. 그는 항구, 가장 남쪽 부두 근처에 서성이는 걸 좋아하지.",
    },
    [26501] = {
        ["T"] = "기묘한 고서",
        ["O"] = "강령술 고서를 알터랙 산맥의 달라란 근처에 있는 대마법사 앤자이럼 룬위버에게 돌려주십시오.",
        ["D"] =
        "쿵 쾅 펑! 이렇게 쉬운 일이라니! 멀록 겨드랑이에서나 간혹 발견되는 마법 시약 같은 게 필요할 줄 알았나요? 아니에요! 아주 간단한 주문이랍니다. 정말로요! 이 고서는 그다지 철저하게 봉인되어 있지 않았거든요.\n\n어쨌든, 이 고서는 아만 넨스톡(Arman Nenstock)이란 사람의 소유였습니다! 전 그게 누군지 전혀 몰라요. 대마법사님은 아시길 바라야죠. 그 책을 다시 그분께 가져가서 안부 전해주세요.",
    },
    [26502] = {
        ["T"] = "희귀한 책",
        ["O"] = "알터랙 폐허에서 타르그와 글롬무스를 처치하고 그들이 가진 책을 회수하십시오. 그런 다음 남녘해안에 있는 현자 딥스에게 돌아가십시오.",
        ["D"] =
        "알터랙 왕국은 학문적 연구로 유명하지 않았지만, 알터랙 도시의 도서관에는 희귀한 고서들이 몇 권 있었습니다. 이제 오우거들이 도시의 폐허를 장악했으니, 그 고서들을 회수할 수 있지 않을까 싶군요...\n\n오우거들은 스스로 글을 읽지 못하면서도 귀해 보이는 책들을 수집하는 것을 좋아합니다. 오우거 우두머리들은 금박이 입혀진 고서들 - 특히 예쁜 그림들로 장식된 책들을 수집하곤 했죠. 그들을 처치하면 잃어버린 보물 몇 가지를 되찾을 수 있을지도 모릅니다.",
    },
    [26503] = {
        ["T"] = "희귀한 책",
        ["O"] = "알터랙 폐허에서 머그톨(Mug'thol)을 처치하고 그에게서 \"알터랙의 여명기\"를 회수하십시오. 그런 다음 남녘해안에 있는 현자 딥스에게 돌아가십시오.",
        ["D"] =
        "당신이 꼭 회수해 주기를 바랐던 고서가 한 권 있는데, 폐허 어딘가에 아직 있을 거라 확신합니다. 그 책의 이름은 \"알터랙의 여명기\"이며, 알터랙 부족이 왕국을 세우고 얼라이언스에 가입하기 전의 유일하게 알려진 역사서입니다. 금실이 박힌 표지로 묶여 있었으니, 분명 오우거들이 보물로 여겼을 겁니다.\n\n어쩌면 그들의 우두머리인 머그톨이라는 야수가 그걸 가지고 있지 않을까요? 그 녀석을 설득해서 책을 넘겨받을 수 있겠습니까?",
    },
    [26504] = {
        ["T"] = "비밀결사대 문서",
        ["O"] = "소페라 절벽과 코란의 비수에 있는 비밀결사대 야영지를 수색하여 그들이 무엇을 계획하고 있는지 보여주는 문서를 찾으십시오.",
        ["D"] =
        "비밀결사대가 이전 남녘해안 집정관을 암살한 것은 언덕마루를 불안정하게 만들어 자신들의 영향력을 뻗치기 위한 대담한 행동이었습니다. 내 자신의 안전뿐만 아니라 남녘해안의 다른 시민들의 안전을 위해 그들의 계획을 더 자세히 알아야 합니다.\n\n어차피 비밀결사대 단원들을 처치하러 가신다면, 그들의 야영지를 뒤져 그들이 어떤 음모를 꾸미고 있는지 단서를 줄 만한 문서가 있는지 찾아보십시오!",
    },
    [26505] = {
        ["T"] = "라벤홀트 장원으로 보내는 편지",
        ["O"] = "집정관 헨리 말레브의 편지를 알터랙 산맥의 라벤홀트 장원에 있는 조라크 라벤홀트 경에게 가져가십시오.",
        ["D"] =
        "비밀결사대의 여러 귀족 지도자들을 제거했다는 것은 알고 있지만, 누가 이 조직을 운영하고 있는지는 아직 수수께끼입니다. 비밀결사대의 우두머리를 제거하기 전까지 남녘해안은 안전하지 않을 것입니다.\n\n지원을 요청할 때가 왔습니다. 이 편지를 던홀드 요새 북쪽 구릉지에 있는 장원의 조라크 라벤홀트 경에게 가져가십시오. 그는 한때 알터랙 왕국의 귀족이었으니 이 불한당들을 쓰러뜨리는 데 우리만큼이나 관심이 있을 겁니다.",
    },
    [26506] = {
        ["T"] = "스트란브래드 특사",
        ["O"] = "던홀드 요새와 스트란브래드를 오가는 비밀결사대 전령을 찾아 요격하십시오.",
        ["D"] =
        "<라벤홀트 경이 한숨을 쉽니다.>\n\n결국 비밀결사대가 언덕마루까지 손을 뻗었군요. 놈들의 세력이 더 확장되기 전에 그들의 기원에 대한 제 독자적인 조사가 마무리되기를 바랐지만, 저의 자원도 턱없이 부족합니다. 자네가 그 일을 도와준다면 남녘해안에 있는 자네 주인이나 나 모두에게 도움이 될 걸세.\n\n현장에서 받은 마지막 보고서에 따르면 전령이 정기적으로 던홀드 요새에서 스트란브래드로 이동한다고 합니다. 이 전령은 도로가 아닌 강을 따라 움직이죠.\n\n그 전령을 가로채고 그가 지닌 메시지를 내게 가져오십시오.",
    },
    [26507] = {
        ["T"] = "고원지대의 수상한 활동",
        ["O"] = "고원지대와 단드레드 장원 근처 언덕에서 정보 교환 지점을 찾으십시오.",
        ["D"] =
        "비밀결사대에 대한 의심을 품고 고원지대에 있는 그들의 야영지를 파악하기 위해 요원을 파견했습니다. 하지만 아직 보고가 들어오지 않았고, 영영 들어오지 않을 것 같군요.\n\n고원지대 산기슭과 단드레드 장원 근처에 작은 표식을 남기고 정보를 남겨두라고 지시했소. 자네가 그 표식을 찾아서 그가 수집했을지도 모를 정보를 회수해 주겠나? 스트란브래드 북쪽 구릉지를 따라가 산사태 오우거 소굴 동쪽, 그리고 살육의 동굴 북쪽을 지나면 그 표식들을 발견할 수 있을 거요. 찾은 내용을 빨리 보고해 주시오. 난... 요원의 유족을 위한 준비를 해야겠소.",
    },
    [26508] = {
        ["T"] = "고원지대의 수상한 활동",
        ["O"] = "라벤홀트 경의 이야기를 들으십시오.",
        ["D"] =
        "계속 진행하기 전에, 우리가 지금 상대하고 있는 비밀결사대의 배후가 누구이며 그들의 정체가 무엇일지에 대한 제 의심을 말해두어야 할 것 같습니다. 이것은 배신과 배반의 긴 이야기입니다. 편히 앉으시죠.",
    },
    [26509] = {
        ["T"] = "고원지대의 수상한 활동",
        ["O"] = "고원지대에서 비밀결사대 단원들을 처치하고 앨리덴 페레놀드 경이 살아 있다는 증거를 찾으십시오.",
        ["D"] =
        "앨리덴 페레놀드가 진정 비밀결사대의 배후인지 확인해야 합니다.\n\n자네는 능력 있다는 걸 보여주었소. 고원지대로 가서 비밀결사대 단원들을 처치하시오. 그들의 우두머리가 누구인지 증거를 찾아보게나. 편지의 밀랍 인장이 될 수도 있고, 왕실 문장이 새겨진 인장 반지, 문서의 서명일 수도 있소.\n\n무엇을 찾든 신속하게 이곳으로 가져오시오.",
    },
    [26510] = {
        ["T"] = "앨리덴 페레놀드 경",
        ["O"] = "단드레드 장원에서 앨리덴 페레놀드 경을 찾아 그를 처치하십시오.",
        ["D"] =
        "<라벤홀트 경이 고개를 가로젓습니다.>\n\n한때 위대했던 페레놀드 가문이 어찌 이렇게 몰락했단 말인가. 고작 좀도둑질과 암살이나 하는 신세로 전락하다니!\n\n물론, 적절한 이유가 있다면 좀도둑질과 암살이 잘못된 건 아니오. 하지만 그런 일에는 예술과 장인정신이 뒤따라야 하는 법이지. 내 말이 좀 샜군.\n\n비밀결사대는 무너뜨려야 하오. 나는 알터랙의 왕좌를 차지하는 데는 관심이 없으니, 그의 죽음에 라벤홀트 가문이 직접 연루되지 않는 것이 정치적 상황에 더 나을 것이오. 그러니 자네에게 부탁하겠소. 앨리덴 페레놀드를 찾아 그를 죽이시오.",
    },
    [26511] = {
        ["T"] = "페레놀드의 유산",
        ["O"] =
        "앨리덴 페레놀드의 죽음과 해스 장군을 찾아달라는 엘리사의 부탁을 알터랙 산맥의 라벤홀트 장원에 있는 라벤홀트 경에게 보고하십시오.",
        ["D"] =
        "저를 페레놀드 경의 집안에서 풀어주셔서 감사합니다. 제 걱정은 마세요, 저 혼자서도 집에 갈 수 있으니까요.\n\n하지만 부탁 하나만 들어주시겠어요? 앨리덴은 항상 자신에게 무슨 일이 생기면 해스 장군이라는 분께 알리라고 제게 말했거든요. 이 \"해스 장군\"이 어디 있는지는 모르겠지만 양심의 짐을 덜고 이 소박한 부탁을 들어주고 싶어요. 그분이 누구인지 찾아내서 앨리덴이 죽었다는 소식을 전해줄 수 있나요?",
    },
    [26512] = {
        ["T"] = "페레놀드의 유산",
        ["O"] = "남녘해안의 마을 역사학자인 쿤드릭 잔덴에게 해스라는 사람에 대한 정보가 있는지 물어 해스 장군을 찾으십시오.",
        ["D"] =
        "해스 장군은 알터랙 군대의 지도자였습니다. 그는 아이덴 왕이 호드와 어울리는 것을 처음부터 반대했죠. 좋은 사람이었고 훌륭한 군인이었습니다.\n\n만약 그가 아직 살아있다면 현지 주민들 사이에 자연스럽게 스며들어 살고 있을 겁니다. 남녘해안으로 가보십시오. 그곳에 도움을 줄 수 있는 마을 역사학자가 있을 겁니다.",
    },
    [26513] = {
        ["T"] = "페레놀드의 유산",
        ["O"] = "스톰윈드 시청에 있는 왕실조사원 바스릴로와 대화하고 그가 해스 장군의 행방을 아는지 물어보십시오.",
        ["D"] =
        "해스라는 이름은 들어본 적이 없는 것 같지만, 그래도 기록은 남겨뒀죠! 잠시만 기다려주세요.\n\n<쿤드릭 잔덴이 두꺼운 장부를 훑어봅니다.>\n\n아- 해스가 있네요. 하지만 딸과 함께 여관에 딱 이틀만 묵었군요. 배를 타고 남쪽, 스톰윈드로 갔습니다. 그곳에서 찾아보세요. 시청에 있는 누군가가 도와줄 수 있을 겁니다.",
    },
    [26514] = {
        ["T"] = "페레놀드의 유산",
        ["O"] = "스톰윈드의 공원에 있는 시트린 이글(Citrine Eagle) 여관에서 해스 장군을 찾으십시오.",
        ["D"] =
        "저는 이 도시의 모든 장교와 경비병을 잘 알고 있습니다. 그들 모두의 신원 조회를 해야 하니까요. 스톰윈드 왕국의 군대에서 복무하는 해스라는 이름의 사람은 없습니다.\n\n하지만 그의 사촌을 소개해드릴 수는 있을 것 같군요. 엘리아스 해스(Elias Hath)는 공원에서 여관을 운영하고 있습니다. 시트린 이글이라는 곳인 것 같아요. 어쩌면 그가 당신을 더 나은 방향으로 이끌어 줄 수 있지 않을까요?",
    },
    [26515] = {
        ["T"] = "페레놀드의 유산",
        ["O"] = "해스 장군의 인장 반지를 서리바람 야영지 근처의 묘지로 가져가 아이덴 페레놀드와 함께 묻어주십시오.",
        ["D"] =
        "그래서 앨리덴 페레놀드가 죽었고 그 사실을 내게 알리고 싶어 했다고? 궁금하군. 왜 그랬을까?\n\n당신이 찾는 사람이 바로 나요, $C.\n\n난 페레놀드 가문과 좋지 않게 헤어졌고, 그 감정은 한 번도 사라진 적이 없소. 난 내 남은 인생을 그저 평화롭게 살고 싶을 뿐이오. 트롤베인이 언젠가 말했듯이 배신은 결코 용서받을 수 없으니까.\n\n당신이 남의 잔심부름 하는 걸 좋아하는 것 같으니, 마지막 부탁 하나 하겠소. 그 시절의 내 마지막 유물인 이 인장 반지를 가져가서, 알터랙 국경 바로 너머 서리바람 야영지 묘지에 있는 아이덴 왕의 무덤에 묻어 주시오. 그런 다음, 다신 페레놀드 가문에 대해 입에 올리지 맙시다.",
    },
    [26516] = {
        ["T"] = "암흑 의회",
        ["O"] = "아르거스의 주문서를 알터랙 산맥의 라벤홀트 장원에 있는 조라크 라벤홀트 경에게 가져가십시오.",
        ["D"] =
        "이 아르거스의 각성(Argus Wake)이라는 조직은 내가 이전에 의심했던 것보다 훨씬 더 위험한 어둠의 세력과 결탁했을 가능성이 있는 비밀 단체라고 믿소. 이 주문서를 조라크 라벤홀트 경에게 가져가시오. 그는 던홀드 요새 북쪽 구릉지에 있는 장원에서 찾을 수 있소.\n\n어쩌면 그가 이 조직에 대해 들어본 적이 있을지도 모르오.",
    },
    [26517] = {
        ["T"] = "암흑 의회",
        ["O"] = "나가즈를 처치하고 그를 수색하여 아르거스의 각성과 관련된 정보를 찾으십시오.",
        ["D"] =
        "비밀결사대를 조사한 바에 따르면, 아르거스의 각성의 편지에서 언급된 나가즈가 앨리덴 페레놀드 경과 같은 장소에 있을 가능성이 높소.\n\n단드레드 장원을 공격하고 나가즈를 처치하시오. 나가즈의 시신과 그의 방을 수색하여 이 아르거스의 각성이 누구에게 보고하는지와 관련된 다른 문서를 찾으시오. 행운을 비오, $C.",
    },
    [26518] = {
        ["T"] = "마법의 양피지",
        ["O"] = "마법의 양피지를 알터랙 산맥의 라벤홀트 장원에 있는 조라크 라벤홀트 경에게 가져가십시오.",
        ["D"] =
        "이 양피지에는 해독할 수 없게 만드는 마법이 걸려 있습니다. 하지만 종이 맨 위에서 한 단어는 읽을 수 있습니다. 바로 '아르거스'입니다. 라벤홀트 경이 이것에 관심을 가질 것입니다.",
    },
    [26519] = {
        ["T"] = "펠리시티의 해독",
        ["O"] = "펠리시티 페레놀드가 마법의 양피지를 해독할 때까지 기다리십시오.",
        ["D"] =
        "아래층에 가보면 전 아이덴 페레놀드 왕의 조카이자 이시덴 페레놀드의 누이인 펠리시티 페레놀드가 있을 거요. 그녀는 거의 20년 동안 나의 피후견인이었고, 내가 가르칠 수 있는 모든 기술과 그 이상을 훈련받았지.\n\n자네의 행동 덕분에 그녀는 장원을 떠날 자유를 얻었소. 이제 그녀의 사촌이 처리되었으니, 비밀결사대 암살자들이 그녀를 공격할까 두려워하지 않고 드러내놓고 살 수 있게 되었군.\n\n펠리시티는 특히 비전 분야에서 뛰어난 마법사요. 그녀에게 이 문서를 해석하게 해보시오.",
    },
    [26520] = {
        ["T"] = "혈석 장치",
        ["O"] =
        "알터랙 산맥의 달라란 근처에 있는 로다미어 포로수용소에 수감된 포세이큰 죄수들에게서 혈석 장치 4개를 수집하십시오.",
        ["D"] =
        "이 아르거스의 각성이라는 조직은 혈마법, 특히 혈석으로 수행할 수 있는 종류의 마법에 관심을 가지고 있소. 비밀결사대가 일부 포세이큰을 매수하여 언더시티의 금고에서 혈석 장치를 훔친 다음 달라란으로 피신한 것 같군. 이번 달 말에 죄수들이 이송될 때 혈석 거래가 있을 예정이라고 하더군.\n\n달라란 경비병들도 분명 뇌물을 받았을 거요.\n\n눈에는 눈, 이에는 이지! 자네가 포세이큰 도둑들을 소탕하고 혈석 장치를 회수하는 동안 모른 척하도록 우리가 그들 손에 금화를 쥐여주겠소.",
    },
    [26521] = {
        ["T"] = "아르거스의 각성",
        ["O"] = "아르거스재림회 어둠마법사 4명을 죽이고 아르거스의 각성에 대한 정보를 타렌 제분소에 있는 크루스크에게 가져가십시오.",
        ["D"] =
        "앨리덴 페레놀드가 나에게 말했을 때, 그는 비밀결사대가 그들의 대의를 위해 강력한 동맹을 영입했다고 언급했다. 내가 전혀 들어본 적 없는 아르거스의 각성(Argus Wake)이라는 조직이 어둠 마법사들과 나가즈라는 오크를 보내 그를 도왔다지 뭔가. 나는 나가즈가 어디 있는지는 모르지만, 어둠 마법사들이 스트란브래드와 고원지대를 배회하고 있다. 그들 중 몇 명을 죽인 다음 이 정보를 크루스크에게 가져가라.",
    },
    [26522] = {
        ["T"] = "아르거스의 각성",
        ["O"] = "알터랙 산맥의 단드레드 장원에 있는 나가즈를 죽이고 언덕마루 구릉지의 타렌 제분소에 있는 크루스크에게 그의 머리를 가져가십시오.",
        ["D"] =
        "비밀결사대가 불타는 군단과 동맹을 맺었다면, 이 상황은 내가 의심했던 것보다 더 심각하다. 대족장님께서 우리가 행동하기를 원하실 것이다.\n\n이 나가즈는 분명 앨리덴 페레놀드 경과 가까운 곳에 있을 것이다. 우리 정보 보고에 따르면 페레놀드는 호수 위 장원인 단드레드 장원에 있다. 그곳에서 나가즈를 찾아 그의 머리를 가져와라.",
    },
    [26523] = {
        ["T"] = "마법의 양피지",
        ["O"] = "마법의 양피지를 언덕마루 구릉지의 타렌 제분소에 있는 크루스크에게 가져가십시오.",
        ["D"] =
        "나가즈의 시체에서 당신은 텍스트를 왜곡하여 읽을 수 없게 만드는 비전 룬이 반짝이는 양피지를 발견합니다. 타렌 제분소의 크루스크가 이것에 대해 아는 것에 관심이 있을 것입니다.",
    },
    [26524] = {
        ["T"] = "라벤홀트 장원으로",
        ["O"] = "마법의 양피지를 알터랙 산맥의 라벤홀트 장원에 있는 조라크 라벤홀트 경에게 가져가십시오.",
        ["D"] =
        "윽! 이게 뭔가? 비전 마법! 나는 이것을 어찌할 도리가 없다.\n\n나가즈가 이 양피지를 가지고 있었다면 우리는 그것이 무엇을 말하는지 이해해야 한다. 여기서 멀지 않은 곳에 라벤홀트 장원이 있다. 라벤홀트 경이 완전히 우리의 동맹은 아니지만, 인간치고는 공정한 마음을 가진 것으로 알려져 있지. 그가 이 양피지에 있는 암호를 풀 수 있는지 확인해 봐라.\n\n라벤홀트 장원은 던홀드 요새 뒤 구릉지에 있다.",
    },
    [26525] = {
        ["T"] = "펠리시티의 해독",
        ["O"] = "펠리시티 페레놀드가 마법의 양피지를 해독할 때까지 기다리십시오.",
        ["D"] =
        "펠리시티 페레놀드를 소개하지. 전 아이덴 페레놀드 왕의 조카이자 이시덴 페레놀드의 여동생이라네. 그녀의 가문은 한때 알터랙 산맥을 다스렸고, 그녀는 타락시키고 찬탈하려는 모든 자들로부터 이 땅을 안전하게 지키는 데 기득권을 가지고 있지.\n\n그녀는 또한 매우 재능 있는 마법사라네. 그녀에게 양피지를 주면 답을 얻을 수 있을 거야.",
    },
    [26526] = {
        ["T"] = "혈석 장치",
        ["O"] = "스트란브래드와 고원지대에 있는 비밀결사대 단원들에게서 혈석 목걸이 4개를 수집하십시오.",
        ["D"] =
        "불타는 군단의 분파인 아르거스의 각성에 대해 최근 알게 되었지. 이 불타는 칼날단, 타오르는 목걸이 따위가 어둠의 의회에 보고한다더군. 적어도 그들은 더 창의적인 이름을 생각해냈군.\n\n혈마법은 혈석을 매개체로 사용하며, 이 양피지는 그들이 알터랙 산맥의 비밀결사대 단원들에게 혈석 목걸이를 배포해왔음을 나타낸다. 고원지대로 돌아가 목걸이 4개를 얻을 때까지 비밀결사대 단원들을 처치해라. 네가 없는 동안 나는 그들을 위한 의식을 준비하겠다.",
    },
    [26527] = {
        ["T"] = "혈석 장치",
        ["O"] = "펠리시티 페레놀드가 라벤홀트 장원에서 혈석 점술 의식을 수행하는 동안 그녀를 보호하십시오.",
        ["D"] =
        "혈석은 불타는 군단의 흑마법사와 어둠의 마법사들이 주로 사용하는 불쾌한 광물입니다. 혈석이 충분히 강력하다면 점을 칠 수 있는 마법의 오라를 남깁니다.\n\n아르거스의 각성이 혈석을 사용하고 있고, 이것이 비교적 희귀한 물건이라고 추정할 수 있으니, 운이 좋다면 혈석 기운이 가장 강력한 곳이 어디인지 점을 칠 수 있을 것입니다.\n\n이 의식을 수행할 수 있지만 온전히 집중해야 합니다. 점을 치는 동안 어둠의 마법에 이끌린 불쾌한 생명체들이 황천에서 나타날 수 있습니다. 저를 보호해 주세요, 그렇지 않으면 의식은 실패할 겁니다!",
    },
    [26528] = {
        ["T"] = "모든 징후가 잊혀진 땅을 가리킨다",
        ["O"] = "만노로크 소굴 근처의 전망이 좋은 어딘가인 잊혀진 땅에서 펠리시티 페레놀드를 만나십시오.",
        ["D"] =
        "$C, 잘 들으세요. 점술 속에서 전 바다 건너 칼림도어라 불리는 땅으로 이끌려갔어요. 그 서쪽 해안에 잊혀진 땅이라는 황량한 불모지가 있죠. 흑마법사 집단이 소환 차원문을 세우는 걸 보았어요. 그곳에서 아르거스의 각성에 대한 해답을 찾을 수 있을 겁니다.\n\n의식의 여파에서 회복되고 나면 칼림도어로 스스로를 순간이동시킬 수 있어요. 전 지금... 조금 피곤하거든요. 하지만 먼저 가서 시작하세요. 이 흑마법사들이 자리 잡은 곳 근처에서 절 찾으세요. 경치 좋은 곳에 있을게요!",
    },
    [26529] = {
        ["T"] = "잊혀진 땅의 아르거스의 각성",
        ["O"] = "변이의 부적(Periapt of Polymorph)을 사용하여 잘라트리아(Zala'thria)를 제압한 후, 잊혀진 땅의 펠리시티 페레놀드에게 돌아가십시오.",
        ["D"] =
        "한동안 이 흑마법사들을 지켜보았는데, 이들은 아르거스의 각성이 아니라 불타는 칼날단과 동맹을 맺고 있습니다. 하지만 군단 내부에는 많은 조직이 있고, 그들은 자신들의 자매 그룹이 잊혀진 땅 어디에서 작전을 수행 중인지 알고 있을 것입니다.\n\n어떤 큰 악마가 지도자 행세를 하고 있지만, 현명한 스파이는 겉모습 너머를 보는 법이죠 (라벤홀트 경이 제게 그렇게 말했습니다). 그 악마가 큰 칼을 들고 있긴 하지만, 이 집단의 진짜 실세는 잘라트리아라는 흑마법사입니다. 그녀는 바로 우리 아래, 저 사원 폐허에 있습니다.\n\n그녀에게 가는 길에 방해되는 자들이 몇 명 있으니, 당신의 힘을 빌려 그들을 처리해 주세요. 우리는 그녀를 산 채로 잡아야 하니까 라벤홀트 경이 준 이 작은 부적을 사용하세요. 이걸 쓰면 그녀를 다루기 훨씬 쉬워질 겁니다. 당신이 끝내면 제가 가서 그녀를 데려올게요.\n\n<펠리시티가 키득거립니다.>",
    },
    [26530] = {
        ["T"] = "잊혀진 땅의 아르거스의 각성",
        ["O"] =
        "잊혀진 땅에 있는 펠리시티 페레놀드를 위해 언데드 파괴자에게서 뼛가루 4줌, 공포의 갈퀴발톱에게서 독수리 피 2병, 불타는 칼날단 흑마법사에게서 혈석 가루 1포대를 수집하십시오.",
        ["D"] =
        "잘라트리아에게서 진실을 알아내려면 특별한 자백제가 필요해요. 장원을 떠나기 전에 약병을 챙겼어야 했는데, 필요한 재료들은 이곳 잊혀진 땅에서 구할 수 있을 것 같아요.\n\n뼛가루 4줌이 필요해요 - 근처 협곡에 있는 해골들에게서 쉽게 구할 수 있죠. 피도 2병 필요해요 - 독수리 피면 충분해요. 마지막으로 저기 아래에 있는 소환사 중 한 명에게서 혈석 가루 한 포대를 가져오세요.\n\n제가 혈석이 강력한 나쁜 마법에 쓰인다고 했던 거 알아요 - 걱정 마세요, 절 위해 쓰는 건 아니니까요. 뭐, 개인적인 용도는 아니라는 거죠.",
    },
    [26531] = {
        ["T"] = "잊혀진 땅의 아르거스의 각성",
        ["O"] = "잘라트리아를 심문하십시오.",
        ["D"] =
        "여기 있어요. 잠시 변이를 풀고 약을 주입할 테니, 당신은 핵심적인 질문을 던지세요. 준비됐나요?\n\n들이켜라 잘라트리아! 비행선 들어간다! 입 벌려! 안 그러면 평생 풀만 뜯어 먹게 될 테니까!",
    },
    [26532] = {
        ["T"] = "잊혀진 땅의 아르거스의 각성",
        ["O"] = "아르거스의 각성의 동굴 은신처를 찾아내고 그곳을 돌파하여 순간이동진에 도달하십시오. 그런 다음 순간이동기를 사용하여 스로진을 찾으십시오.",
        ["D"] =
        "이제 우리의 목표가 정해졌어요: 스로진(Thro'jin). 그를 처리하면 아르거스의 각성은 스스로 무너질지도 몰라요. 아니면 군단 내의 다른 분파들에 의해 갈가리 찢기거나요. 어느 쪽이든, 당면한 문제를 해결할 수 있죠.\n\n당신과 합류하기 전에 잘라트리아를 처리해야 해요. 아르거스의 각성 은신처를 뚫고 들어가 이 순간이동진을 찾으세요. 제가 그녀의 처리를 끝내는 대로, 어디로 연결되든 점술을 통해 당신과 합류할게요. 이 임무에 부를 만한 믿을 수 있는 사람이 있다면 부르는 것도 좋을 거예요. 저 없이 스로진을 죽이지 말아 달라는 부탁만 들어주세요!",
    },
    [26533] = {
        ["T"] = "아르거스의 각성의 최후",
        ["O"] = "스로진을 처치한 후 펠리시티 페레놀드를 찾아 탈출하십시오!",
        ["D"] =
        "우리 여기 있어요! 큰 악당을 끝장낼 준비가 되었어요! 이제 장난은 끝이에요 - 이 일대를 점술로 확인했는데 스로진은 멀지 않은 옛 폐허에 숨어 있어요.\n\n하지만 아주 작고 사소한 문제가 하나 있어요. 임무를 마치면 재빨리 탈출해야 하는데, 우리 둘 다 라벤홀트 장원으로 순간이동하려면 막대한 마법 에너지가 필요할 거예요. 그래서 당신이 혼자 그를 처리해 주셔야 해요. 일이 끝나면 만나요 - 전 반대편 근처에서 기다리고 있을게요.",
    },
    [26534] = {
        ["T"] = "아르거스의 각성의 최후",
        ["O"] = "알터랙 산맥의 라벤홀트 장원에 있는 조라크 라벤홀트 경에게 임무 성공을 보고하십시오.",
        ["D"] =
        "준비가 되었다면, 이제 우린 떠날 겁니다. 도착할 때쯤이면 제 기운이 꽤 많이 소진되어 있을 테니, 라벤홀트 경에게 임무 성공 보고는 당신이 해주세요. 다시 만날 수 있을 때 뵙죠. 엉덩이 꽉 잡으세요!",
    },
    [26535] = {
        ["T"] = "스트롬가드로 보내는 편지",
        ["O"] = "망치 주둔지에 있는 드럼 펠에게 스트롬가드에 있는 비밀결사대 요원들에 대해 경고하십시오.",
        ["D"] =
        "스로진이 보낸 이 편지는 마레즈 코울(Marez Cowl)에게 작성되었으며, 아라시 고원의 스트롬가드로 수신지가 적혀 있습니다. 아르거스의 각성이 아라시 고원에서도 비밀결사대와 함께 일하고 있을지도 모릅니다. 망치 주둔지에 있는 누군가가 이 정보에 관심을 가질 것입니다.",
    },
    [26536] = {
        ["T"] = "스트롬가드로 보내는 편지",
        ["O"] = "임시 주둔지에 있는 니알스 대장에게 스트롬가드에 있는 비밀결사대 요원들에 대해 경고하십시오.",
        ["D"] =
        "스로진이 보낸 이 편지는 마레즈 코울에게 작성되었으며, 아라시 고원의 스트롬가드로 수신지가 적혀 있습니다. 아르거스의 각성이 아라시 고원에서도 비밀결사대와 함께 일하고 있을지도 모릅니다. 임시 주둔지에 있는 누군가가 이 정보에 관심을 가질 것입니다.",
    },
    [26537] = {
        ["T"] = "모르디스의 열쇠",
        ["O"] = "모르디스의 열쇠를 사용할 곳을 찾으십시오.",
        ["D"] =
        "이 열쇠는 발리마르 모르디스 남작의 시체에서 발견되었습니다. 과연 어디에 쓰이는 걸까요?\n\n알터랙 폐허 북동쪽에 남작의 장원이 있었던 것이 기억납니다. 그곳을 확인해 보는 게 어떨까요?",
    },
    [26538] = {
        ["T"] = "모르디스 남작령",
        ["O"] = "발리마르 모르디스 남작을 찾고 그가 언데드인지 확인하십시오. 만약 그렇다면 그를 처치하십시오.",
        ["D"] =
        "알터랙의 귀족 가문 중 하나는 발리마르 모르디스 남작이 이끌고 있었습니다. 모르디스 가문은 알터랙 도시 북동쪽에 장원을 가지고 있었으며 이 지역에서 매우 존경받았습니다.\n\n모르디스 남작은 스컬지가 달라란으로 향하던 중 알터랙 왕국을 지나갈 때 그들에 의해 살해당한 것으로 여겨졌습니다. 그러나 최근 몇 년 동안 죽은 남작이 자기 가문의 영지를 순찰하는 것을 보았다는 목격담이 있습니다. 그가 스컬지의 꼭두각시가 되었다는 소문이 돌고 있죠.\n\n그가 마지막으로 목격된 장소를 수색하여 그 소문이 사실인지 확인하십시오, $N. 만약 그가 스컬지로 타락했다면 당신이 그를 파괴해야 합니다.",
