        ["D"] =
        "지난 전쟁에서 달라란과 안돌할이 파괴되었지만 생존자들은 식량과 물품을 조달받기 위해 우리에게 의존하고 있습니다. 이 귀중한 무역로가 위협받아서는 안 됩니다.\n\n멀록들이 로다미어 호수 남쪽 해안과 서리바람 거점을 지나 흐르는 다로우미어 강을 따라 마을을 세웠다는 보고를 받았습니다. 옛날 같았으면 이런 야수들을 처리하는 건 알터랙 왕국의 일이었겠죠. 이제는 우리가 방어에 나서야 할 때입니다.\n\n우리가 무역로를 안전하게 지킬 수 있도록 놈들의 숫자를 줄여주십시오.",
    },
    [26541] = {
        ["T"] = "해외로부터의 위협",
