        ["D"] =
        "알터랙 폐허로 이주한 오우거들은 토착민인 산악 설인들과 조화롭게 사는 것 같습니다. 저는 이것이 우려스럽습니다. 이런 생물들이 서로 협력한 역사가 없기 때문입니다.\n\n오우거들이 설인들을 부추기면 그들이 우리 상단도 공격하기 시작할 수 있습니다. 따라서 얼라이언스의 공포를 놈들에게 심어주기 위해 선제 공격을 하는 것이 현명한 처사일 겁니다.\n\n알터랙 산맥의 침묵의 동굴 근처에서 설인 무리의 본진을 찾을 수 있을 테지만, 알터랙 폐허 전역에 퍼져 산다고 들었습니다.",
    },
    [26542] = {
        ["T"] = "희귀한 품종",
