        ["D"] =
        "반갑습니다 여행자여! 언덕마루의 농부들은 사과로 유명합니다. 반짝이는 붉은 사과, 황금껍질 사과, 달라란 달콤사과 등이 모두 우리 지역 밭에서 자라죠. 지난 전쟁 이전에는 알터랙 산맥에서 자라는 또 다른 품종의 사과가 있었는데, 바로 겨울바삭사과입니다.\n\n스트란브래드의 사과밭은 스컬지 군대가 달라란으로 향하던 중 그곳을 지나면서 파괴되었습니다. 하지만 혹시라도 씨앗이 남아있다면 새로운 겨울바삭사과 나무를 심을 수 있을 겁니다. 스트란브래드의 과수원으로 여행을 떠나 씨앗을 찾을 수 있는지 알아봐 주시겠습니까?\n\n조심하십시오 - 스트란브래드는 이제 비밀결사대가 통제하고 있습니다.",
    },
    [26543] = {
        ["T"] = "수박 펀치",
        ["O"] = "남녘해안에 있는 니마를 위해 알터랙 산맥의 단드레드 장원에서 즙이 많은 수박 4개를 수집하십시오.",
        ["D"] =
        "저희 여관에서 제공하는 음식은 현지에서 조달한 농산물로 만듭니다. 매년 이맘때면 언덕마루에서 수박을 들여오곤 했는데, 방금 수박 농사를 망쳐서 올해는 수박이 없을 거라는 소식을 들었어요. 이건 재앙이나 다름없어요, $N. 수박이 없으면 제 특제 수박 펀치를 만들 수가 없거든요!\n\n요전 밤 여관에 온 어떤 수상한 사람이 수박씨를 뱉고 있더라고요. 어디서 났냐고 물었더니 북쪽 단드레드 장원이라는 곳에서 수박이 자라고 있다고 했어요. 그곳으로 가서 수박을 좀 구해다 주시겠어요? 즙이 가장 많은 수박이어야 해요!",
    },
    [26544] = {
        ["T"] = "누가 사과를 좋아할까?",
