        ["D"] =
        "오, 타렌 제분소를 방문한 또 다른 $R군요. 저도 압니다, 버섯이 모두가 좋아하는 전채 요리가 아니라는 걸요. 전 다른 음식으로 선택의 폭을 넓힐 생각이었습니다. 당신이 날 도와줄 수 있을까요?\n\n스트란브래드의 사과밭은 스컬지 군대가 달라란으로 가기 위해 거쳐가면서 초토화되었지만 씨앗이라도 남아있다면 겨울바삭사과 나무를 새로 심을 수 있을 겁니다. 스트란브래드의 과수원으로 여행하여 씨앗을 찾아봐 주시겠습니까?\n\n조심하십시오 - 스트란브래드는 지금 비밀결사대가 통제하고 있습니다.",
    },
    [26545] = {
        ["T"] = "누가 수박을 좋아할까?",
        ["O"] = "타렌 제분소에 있는 제이슨 레미욱스를 위해 알터랙 산맥의 단드레드 장원에서 즙이 많은 수박 4개를 수집하십시오.",
        ["D"] =
        "모든 분들이 사과를 좋아하는 건 아닐 겁니다. 호드 분들이 좋아하실 만한 걸 여기서 재배할 수 있지 않을까요?\n\n알아요 - 단드레드 장원 근처에 수박이 크게 열린 곳이 있습니다. $R 여러분 수박 좋아하시죠, 그렇죠? 그럼, 가서 좀 구해다 주세요!",
