        ["O"] = "불타는 언덕을 정찰하여 연기의 근원지를 찾아내십시오.",
        ["D"] =
        "망치 주둔지 동쪽에 있는 불타는 언덕(Blazin\' Hills)에서 엄청난 연기가 솟아오르는 걸 보았네. 그곳을 집으로 삼고 있는 정령들은 보통 평화롭기 때문에 내 마음이 영 편치 않네.\n\n자네가 그곳에 가서 무슨 일이 이렇게 소란을 피우고 있는지 조사해 주었으면 하네. 위험이 도사리고 있으니 방심하지 말고 정신을 바짝 차리도록 하게.",
    },
    [26547] = {
        ["T"] = "언덕으로",
        ["O"] = "불타는 언덕을 정찰하여 연기의 근원지를 찾아내십시오.",
        ["D"] =
        "망치 주둔지 동쪽 불타는 언덕에서 심상치 않은 연기가 솟아오르는 것을 보았다네, $g젊은이:젊은이;. 그 지역에 서식하는 정령들은 대체로 평화롭기 때문에 이 상황은 내게 큰 걱정거리지. 자네가 그곳으로 향해 무엇이 이 소란을 야기하고 있는지 조사하는 임무를 맡아주었으면 하네. 위험이 도사리고 있으니 긴장을 늦추지 말고 정신 똑바로 차려야 할 거야.",
