        ["D"] =
        "당신도 알다시피 균형은 자연의 조화에 있어 매우 중요합니다. 이 균형을 회복하기 위해 내 동족을 해쳐야 한다는 사실이 가슴 아픕니다.\n\n필멸자여, 이것은 나의 가장 깊은 슬픔이지만 당신에게 근처의 물의 정령들을 죽여달라고 부탁해야만 합니다. 그들은 내 형제들에게 영향을 미치는 분노를 가라앉히는 데 사용할 수 있는 식힌 아쿠알 정수를 포함하고 있습니다. 산의 북쪽, 땅에 물이 고인 곳에서 그들을 찾을 수 있을 것입니다.",
    },
    [26549] = {
        ["T"] = "고통스러운 물 끼얹기",
        ["O"] = "약해진 맹렬한 잉걸불(Raging Cinder)에게 진정의 물이 든 병을 사용하여 그들의 맹렬한 손목띠(Raging Bindings)를 수집하십시오.",
        ["D"] =
        "당신이 가져온 식힌 아쿠알 정수로 진정의 물이 든 병을 만들었습니다. 이것은 당신이 불타는 언덕에 있는 맹렬한 잉걸불 불의 정령들을 약화시켜 당신이 손목 결속구를 수집할 수 있을 만큼 시원하게 만드는 데 도움이 될 것입니다.\n\n이 손목띠들을 내게 가져오면 우리는 이 언덕에 평화의 새로운 시대를 여는 데 사용할 것입니다.",
    },
    [26550] = {
        ["T"] = "물과의 만남",
        ["O"] = "불타는 언덕 내에 있는 아쿠아멘투스를 찾으십시오.",
        ["D"] =
        "아쿠아멘투스는 이곳 물의 정령들의 지도자이며 그들 중 가장 강합니다. 그는 지혜롭고 강력하며, 그의 영향력은 불타는 언덕의 경계를 넘어섭니다.\n\n비록 의견이 다를 때가 많지만 저는 아쿠아멘투스를 매우 존경합니다. 그는 이 땅에서 균형과 조화의 중요성을 이해하고 그것을 유지하기 위해 노력합니다.\n\n최근 물의 정령들이 불안해하고 있는데, 저는 이 불안이 여기 불타는 언덕의 교란과 관련이 있을까 두렵습니다. 우리는 존경심과 겸손한 태도로 아쿠아멘투스에게 접근하여 우리의 보금자리에 균형을 회복할 수 있도록 도움을 요청해야 합니다.\n\n그는 물이 자유롭게 흐르는 북쪽에서 찾을 수 있습니다. 가서 그와의 접견을 청하십시오.",
    },
    [26551] = {
        ["T"] = "분출구 닫기",
        ["O"] = "불타는 언덕 내에 있는 아쿠아멘투스를 위해 증기 분출구 8개를 붕괴시키십시오.",
        ["D"] =
        "내 물에 불안을 야기한 근원을 찾은 것 같다. 땅에 열수 분출구가 열려 물을 증기로 증발시키고 우리가 애써 유지해 온 균형을 교란하고 있구나.\n\n너에게 거센 물결의 힘을 불어넣어 줄 테니 그것으로 저 분출구들을 무너뜨리고 영원히 닫아버려라. 서둘러라. 내 동족들이 자신이나 다른 이들에게 입힐 피해가 우려되는구나.",
    },
    [26552] = {
        ["T"] = "깃털의 공물",
        ["O"] = "불타는 언덕 내에 있는 아쿠아멘투스를 위해 온전한 타조 깃털 6개를 수집하십시오.",
        ["D"] =
        "분출구를 닫는 것만으로는 내 동족의 완전한 분노를 잠재울 수 없다. 우리 힘만으로는 불가능하다. 우리를 돕게 하려면 그의 자존심을 달래주어야 할 자의 도움이 필요하다.\n\n공기는 균형의 핵심이며 산불을 광란으로 몰아넣거나 필멸자의 이마에 흐르는 땀을 식혀준다. 하지만 공기는 오만하고 스스로의 호언장담으로 가득 찬 원소다.\n\n내 계획에 대해 더 자세히 설명할 때가 올 테지만, 지금 네가 알아야 할 것은 이 언덕에서 가장 가벼운 깃털을 공물로 바쳐야 한다는 것이다. 이것들은 이 지역 전역의 타조들에게서 찾을 수 있다. 이 임무를 수행하라, 필멸자여.",
    },
    [26553] = {
        ["T"] = "바람과의 만남",
        ["O"] = "아쿠아멘투스와 대화하여 에어로미르의 제단으로 가는 길을 안내받으십시오.",
        ["D"] =
        "분출구가 정리되었으니 더 이상 내 친족들이 분노에 굴복하지 않으리라 확신할 수 있다. 하지만 우리는 이미 분노에 사로잡힌 자들을 도와야 한다.\n\n준비가 되면 나에게 말하라, 너와 공물을 에어로미르에게 데려다주겠다. 네가 나의 목소리가 되어 내 형제들을 식혀달라고 그에게 부탁해주어야 한다. 할 수 있겠느냐?",
    },
    [26554] = {
        ["T"] = "바람의 도움",
        ["O"] = "에어로미르와 대화하여 그의 축복과 함께 아쿠아멘투스에게 돌아가십시오.",
        ["D"] =
        "그래서, 정령 형제들이 말다툼을 벌이고 있단 말이지? 놀랍지도 않군.\n\n아니, 이 소동을 일으킨 것은 내가 아니지만 네가 이렇게 훌륭한 공물을 가져왔으니 내가 할 수 있는 한 널 돕겠다.\n\n너에게 공기의 축복을 내려 아쿠아멘투스의 일족을 달래줄 매개체로 삼아주마. 나와 대화하면, 바람의 힘이 너를 하늘로 이끌어 아쿠아멘투스에게 돌려보내 줄 것이다.",
    },
    [26555] = {
        ["T"] = "분노 가라앉히기",
        ["O"] = "에어로미르가 내린 평온의 공기를 사용하여 불타는 언덕 내의 끓어오르는 방랑자(Boiling Wanderers)들을 약화시키고 진정시키십시오.",
        ["D"] =
        "아르타시스가 자기 형제들을 억제하기 위해 네가 그들을 학살하도록 시켰을 거라는 건 의심의 여지가 없지만, 난 그러지 않겠다. 물은 불처럼 경솔하지 않다. 끓어오름은 진정될 수 있는 법.\n\n에어로미르가 네게 내려준 진정의 공기로 내 일족들을 분노에서 해방시켜 다오. 이성이 자리 잡으려면 넌 그들을 약화시켜야 할 것이다.",
    },
    [26556] = {
        ["T"] = "불에게로 귀환",
        ["O"] = "불타는 언덕 내에 있는 아트라시스에게 돌아가십시오.",
        ["D"] =
        "자네가 내 형제들을 진정시켜 주었지만, 불타는 언덕 내부의 문제는 뿌리가 깊다. 이제 아트라시스와 만나야 할 때다. 그에게 돌아가 우리가 만날 의향이 있다고 전해주게.",
    },
    [26557] = {
        ["T"] = "의회 소집",
        ["O"] = "아트라시스와 대화하여 정령 의회를 목격하십시오.",
        ["D"] =
        "불타는 언덕에서 무슨 일이 일어나고 있는지 최종적으로 결정할 때가 왔습니다. 우리 정령 지도자들은 지난 수천 년 동안 거의 모이지 않았지만 지금은 절박한 시기입니다. 에어로미르, 아쿠아멘투스, 지오마르, 그리고 저. 공기, 물, 대지, 불. 우리는 의회를 소집할 것입니다. 함께라면 어떤 적의 폭풍도 이겨낼 수 있습니다. 다시 저와 대화하여 이 만남을 지켜보십시오.",
    },
    [26558] = {
        ["T"] = "울리는 들판",
        ["O"] = "알스톤 영지 밭을 교란하는 광분한 대지(Frantic Earth) 7마리와 배회하는 대지(Rambling Earth) 7마리를 처치하십시오.",
        ["D"] =
        "제기랄, 이 빌어먹을 대지의 정령들이 내 밭을 엉망으로 만들고 내 동물들을 겁주고 있어! 이제 참을 만큼 참았어!\n\n누군가 광분한 대지와 배회하는 대지 정령들을 완전히 처리해 주었으면 좋겠군. 그놈들이 온갖 말썽을 일으키는 최악의 부류야. 나를 위해 그 일을 해주겠소? 보수는 두둑이 쳐줄 테고, 내 감사도 받을 거요.\n\n단언컨대 쉬운 일은 아닐 거요. 이 정령들은 끈질긴 놈들이니까.",
    },
    [26559] = {
        ["T"] = "동물을 구하라",
        ["O"] = "알스톤 영지에서 겁먹은 동물 6마리에게 올가미를 던져 파울라 알스톤에게 데려오십시오.",
        ["D"] =
        "우리 동물들이 너무 걱정돼요! 대지의 정령들이 땅에서 솟아나자 우리 동물들이 들판으로 도망쳤는데 지금은 너무 겁이 나서 돌아오지 못하고 있어요. 저 애들을 밖에 홀로 둘 수 없어요. 부디 저 애들을 안전한 곳으로 데려오는 걸 도와주시겠어요?\n\n여기, 이 밧줄을 받으세요. 이걸로 올가미를 씌워서 제게 데려올 수 있을 거예요. 제발 조심하세요, 아무도 다치지 않았으면 좋겠어요.",
    },
    [26560] = {
        ["T"] = "인생이 네게... 딸기를 준다면?",
        ["O"] = "알스톤 영지에 있는 랜달 알스톤을 위해 어둠딸기 8부셸을 수집하십시오.",
        ["D"] =
        "저 너머에 있는 밭이 보이나? 나는 그곳에서 수년 동안 어둠딸기를 키워왔지. 이 지역에서 최고로 치는 딸기인데 정령들이 그것들을 짓이겨 곤죽으로 만들까 봐 두렵소. 누군가 저곳에 가서 눈에 띄는 대로 어둠딸기 부셸을 모두 수집해 줬으면 좋겠소. 하지만 그곳은 조심해야 하오, 정령들은 위험한 무리이니까.\n\n나를 위해 그 일을 해주겠소?",
    },
    [26561] = {
        ["T"] = "파이어플룸 찾기",
        ["O"] = "불타는 언덕 위로 솟아오르는 파이어플룸을 찾으십시오.",
        ["D"] =
        "당신은 우리 가족에게 능력 있고 마음씨 따뜻한 사람이라는 것을 증명해 보였어요. 저에게 개인적으로 매우 중요한 일을 도와주시겠어요?\n\n와일드해머 가문으로서 저의 그리핀 파이어플룸과 나누는 유대감은 끝이 없습니다. 파이어플룸은 항상 정령들과 독특한 유대감을 가지고 있었어요. 그것이 제가 파이어플룸을 선택하고, 그가 저를 선택한 이유 중 하나이기도 하죠.\n\n정령들이 땅에서 솟아올랐을 때, 파이어플룸은 도망쳐서 불타는 언덕 위 하늘로 날아올랐어요. 그 아이의 안전이 너무 걱정됩니다. 녀석을 추적해서 그가 무사한지 제게 알려주실 수 있나요? 그냥 눈으로만 확인해 주시면 됩니다.",
    },
    [26562] = {
        ["T"] = "약간의 달콤함",
        ["O"] = "불타는 언덕에서 거대한 어둠딸기 8부셸을 수집하십시오.",
        ["D"] =
        "파이어플룸이 가장 좋아하는 간식 중 하나는 어둠딸기인데, 가장 큰 딸기만 좋아해요. 제 남편은 자신이 근방에서 최고로 딸기를 잘 키운다고 생각하지만... 글쎄요, 사실이 아니라고만 해둘게요. 불타는 언덕 위에는 정령들의 존재가 가장 비옥한 토양을 만드는 데 도움을 주고 있어요. 가장 좋은 어둠딸기는 그곳에서 찾을 수 있죠.\n\n파이어플룸을 돌아오게 할 미끼를 만들 수 있게 저를 위해 그것들을 좀 구해 주시겠어요?",
    },
    [26563] = {
        ["T"] = "약간의 고기",
        ["O"] = "불타는 언덕 내의 불타는 바위거미(Blazing Creeper)들에게서 바위거미 고기 덩어리 10개를 수집하십시오.",
        ["D"] =
        "파이어플룸이 좋아하는 또 다른 간식은 구운 바위거미 고기 덩어리예요. 가장 좋은 덩어리는 다리와 몸통이 만나는 관절에서 나오죠.\n\n불타는 바위거미들은 불타는 언덕 내에서 찾을 수 있어요. 제게 그 고기를 좀 구해 주시면, 어둠딸기와 섞어서 파이어플룸이 거부할 수 없는 간식을 만들게요.",
    },
    [26564] = {
        ["T"] = "파이어플룸 꾀어내기",
        ["O"] = "알스톤 부두의 파이어플룸의 둥지 근처에 냄새가 강한 미끼를 놓으십시오.",
        ["D"] =
        "당신이 가져온 바위거미 고기 덩어리와 어둠딸기로 파이어플룸이 가장 좋아하는 간식 두 가지를 모두 준비했어요. 이 두 가지를 합치면 파이어플룸은 거부하지 못하고 다시 우리에게 날아올 거예요. 냄새가 조금 강해서 멀리까지 퍼질 거라고 확신해요. 부두에 있는 파이어플룸의 둥지에 이걸 놔주시겠어요?",
    },
    [26565] = {
        ["T"] = "긴급한 간청",
        ["O"] = "파이어플룸을 그의 둥지에서 부르고 아만다 알스톤이 폴스타트에게 보내는 메시지를 맹금의 봉우리로 가져가십시오.",
        ["D"] =
        "이 영지가 더 이상 안전하지 않다는 건 이미 눈치채셨겠죠. 정령들이 고통에 울부짖는 소리가 느껴지는데 상황은 더욱 악화될 뿐일 겁니다. 저희 가족의 고집 때문에 시간이 지체되어서 내 집안을 안전하게 대피시킬 시기를 놓쳤고, 이 도로는 더 이상 선택지가 아닙니다.\n\n맹금의 봉우리로 가서 우리가 떠날 수 있도록 폴스타트에게 도움을 요청해 주세요. 그동안 저는 우리 가족에게 떠나야 한다고 설득할게요.\n\n이 호루라기를 가져가세요. 파이어플룸은 이제 당신을 믿고 둥지에서 부르면 다가올 겁니다. 그가 당신을 맹금의 봉우리로 데려가서 폴스타트와 대화할 수 있게 해줄 거예요.",
    },
    [26566] = {
        ["T"] = "긴급한 간청",
        ["O"] = "맹금의 봉우리 내에서 파이어플룸을 소환하여 그의 등에 타고 알스톤 영지로 돌아가십시오.",
        ["D"] =
        "그대의 말이 사실이라면, 알스톤 일가는 한시라도 빨리 대피해야 하네! 아만다에게 돌아가 와일드해머는 결코 동족을 버리지 않는다고 전하게. 해가 질 때까지 도착할 테니 단단히 준비해 두라고 하게나. 이 간청을 우리에게 전해줘서 고맙네, $N.",
    },
    [26567] = {
        ["T"] = "영지 포기하기",
        ["O"] = "파울라 알스톤에게 와일드해머 일족이 다가오고 있음을 알리십시오.",
        ["D"] =
        "부탁이에요, 파울라에게 우리가 떠난다고 전해주시겠어요? 마지막으로 짐을 좀 싸고 남편을 데려와야 해요. 영지를 탈출하기 위해 곧 당신 뒤를 따를게요. 우리 가족을 위해 해주신 모든 일에 감사드립니다, $N.",
    },
    [26568] = {
        ["T"] = "어둠딸기 파이",
        ["O"] = "망치 주둔지 남동쪽 불타는 언덕에서 거대한 어둠딸기 8부셸을 수집하십시오.",
        ["D"] =
        "불타는 언덕 위에는 어둠딸기라고 불리는 특별한 딸기가 있는데, 짙은 보라색을 띤 맛있는 과일입니다.\n\n희귀성 때문에 암시장에서 비싼 값에 팔린다는 건 알지만 병사들을 먹여야 하는데 이익을 챙길 시간은 없습니다. 당신이 제게 그것을 조금 구해준다면 병사들을 위해 따뜻한 파이를 구울 수 있습니다.",
    },
    [26569] = {
        ["T"] = "특이한 전투식량",
        ["O"] = "불타는 언덕 내의 불타는 바위거미에게서 바위거미 고기 덩어리 10개를 수집하십시오.",
        ["D"] =
        "아라시 내에서는 질 좋은 고기를 구하기 어렵고, 맛있는 건 더욱 찾기 힘듭니다. 우리 \"고기\" 만두에 제가 슬쩍 넣는 비밀 재료가 있는데... 바로 바위거미 고기죠.\n\n네, 네. 당신이 짓는 표정이 보입니다. 망치 주둔지에 6개월 동안 주둔해 보기 전까지는 절 판단하지 마십시오.\n\n재고가 바닥나고 있어서, 충분한 식사가 제공되지 않으면 폭동이 일어날 판입니다. 내가 필요한 고기는 이 근방 남동쪽에 있는 불타는 언덕의 불타는 바위거미에게서 구할 수 있습니다. 조금 가져다주시면 두둑하게 보상해 드리겠습니다.",
    },
    [26570] = {
        ["T"] = "물에 젖은 일지",
        ["O"] = "아라시 고원의 불타는 언덕 해안에서 물에 젖은 일지의 주인을 찾으십시오.",
        ["D"] =
        "당신 손에 쥐어진 두꺼운 일지에는 \"파울라 알스톤 소유\"라는 라벨이 붙어 있습니다. 누군가 그 안의 내용을 아주 자랑스럽게 써 내려간 모양입니다. 가장 최근 항목을 훑어보고 주인을 찾아 그들에게 돌려주는 건 어떨까요?",
    },
    [26571] = {
        ["T"] = "남쪽 언덕",
        ["O"] = "대지의 정령들의 운명을 조사하기 위해 불타는 언덕의 남부 지역으로 여행하십시오.",
        ["D"] =
        "이 땅의 남쪽 지역은 대지의 영역이자 그들의 지도자인 지오마르의 영역입니다. 그가 의회에 오지 않은 것이 몹시 걱정되는군요. 당신이 그의 영토로 가서 그곳에서 무엇을 발견했는지 제게 알려주기를 원합니다.\n\n아주 오래 전 마른나무껍질 트롤들은 정령들을 신으로 여기며 숭배했습니다. 그들의 낡은 제단들이 여전히 이 땅 곳곳에 흩어져 있죠. 남쪽 언덕에 가면 그런 제단 중 하나를 찾을 수 있을 것이고, 나는 그것을 통해 당신과 소통할 수 있습니다. 임무가 끝나면 그곳을 사용해 내게 신호를 보내십시오.",
    },
    [26572] = {
        ["T"] = "격노한 채찍질",
        ["O"] = "불타는 언덕 내의 마른나무껍질 무두장이 8마리를 처치한 후, 침수된 주술사 제단(Sunken Shaman Shrine)으로 돌아가 아트라시스와 대화하십시오.",
        ["D"] =
        "마른나무껍질 부족의 무두장이들은 그들 중에서도 가장 잔인한 무리다. 적의 가죽을 산 채로 벗긴다는 그들의 소문은 아라시 전역, 심지어 정령 의회에 있는 우리에게까지 퍼졌지. 그들이 여기서 무얼 하고 있는지, 왜 우리의 평화로운 공존을 깨뜨리려 했는지는 알 수 없으나 그들의 공포 정치는 끝장내야 한다. 거침없는 불의 진노로 그들을 모두 베어 넘겨라!",
    },
    [26573] = {
        ["T"] = "불타는 언덕의 광전사",
