        ["O"] = "황야의 땅에 있는 고통의 요새에서 인듀리움 광석 상자 8개를 수집하십시오.",
        ["D"] =
        "은여울 광산에서 이걸 얻었다고? 흥미롭네요! 하지만 순수한 인듀리움 광석을 발견하는 것만큼 흥미롭진 않죠. 우리가 아는 한, 이 광석은 울다만에서만 나옵니다. 그리고 울다만 주변 광산은 어둠괴철로 놈들이 점령하고 있죠.\n\n하지만... 어둠괴철로 녀석들은 동쪽의 고통의 요새에도 기지를 두고 있어요. 그곳을 공격하는 게 울다만 본진을 치는 것보다 수월할 겁니다. 돕고 싶다면, $C, 고통의 요새로 가서 놈들의 인듀리움 비축물자를 빼앗아 오세요!",
    },
    [26593] = {
        ["T"] = "인듀리움 매트릭스",
        ["O"] = "울다만 안에서 인듀리움 매트릭스를 찾아 역사학자 레베카 켈러에게 가져오십시오.",
        ["D"] =
        "티탄들은 까마득한 옛날 아제로스를 거닐었던 고대 종족입니다. 오랜 세월 동안 울다만의 티탄 시설은 여러 사람들에 의해 발굴되고 주거지로 쓰여왔죠. 시설의 많은 비밀이 약탈당했지만, 깊은 곳에는 아직 옛 티탄의 방어 시설이 지키고 있는 방들이 남아 있습니다.\n\n당신은 지금까지 유능함을 증명했습니다. 어쩌면 그 방어 시설을 상대할 수 있지 않을까요? 그것들을 시험해 볼 생각이 있다면 임무를 하나 주겠습니다. 울다만 가장 깊은 곳의 방 어딘가에 인듀리움 매트릭스라는 티탄 기계가 있을 겁니다. 그것을 회수해 제게 가져오시면 후하게 보상해 드리겠습니다.",
    },
    [26594] = {
        ["T"] = "현상 수배: 스코치마우",
        ["O"] = "스코치마우를 처치하고 그의 머리를 용수철소켓의 더크 윈드래틀(Dirk Windrattle)에게 가져가십시오.",
        ["D"] =
        "용수철소켓 동쪽에 위치한 레슬로 협곡을 배회하는 위험한 비룡, 스코치마우가 있습니다. 수십 명의 목숨을 앗아간 스코치마우는 가는 곳마다 큰 피해를 주고 있습니다.\n\n용수철소켓의 뜻 있는 시민이 이 야수의 머리에 현상금을 내걸었습니다. 스코치마우는 공격자에게 자비를 베풀지 않을 것이므로 모험가 여러분은 친구와 함께 가는 것이 좋습니다. 성공한다면, 그의 머리를 용수철소켓 여관에 있는 더크 윈드래틀에게 가져가십시오.",
    },
    [26595] = {
        ["T"] = "마법의 메달리온",
        ["O"] = "마법의 메달리온에 대해 더 많은 것을 알려줄 수 있는 사람을 찾으십시오.",
        ["D"] =
        "강력한 마법이 불어넣어진 것이 틀림없는 메달리온을 발견했습니다. 검은바위 산에 흐르는 끓는 용암의 열기에 완전히 저항하는 것 같으니까요. 메달리온에는 조각난 둥근 원 혹은 고리 같은 단순한 디자인이 새겨져 있습니다.\n\n당신은 이 상징에 익숙하지 않지만, 세상 어딘가에는 이것을 아는 사람이 분명 있을 것입니다...",
    },
    [26596] = {
        ["T"] = "마법의 메달리온",
        ["O"] = "마법의 메달리온을 타나라신? 텐케리스? 타네라니사니? 아무튼 그 비슷한 곳에 있는 마본 리벳시커에게 가져가십시오!",
        ["D"] =
        "언젠가는 제가 현장에 나가 여러 발견을 하는 날이 오겠지만, 지금은 여기 톱니항에 있는 마본의 작업장을 지키고 있어요. 하지만 마본이 당신이 가진 이 아뮬렛을 본다면 무척 좋아할 거예요. 그는 이상한 문양이 있는 오래된 물건들을 아주 좋아하거든요. 뭐, 그게 그의 전문 분야이기도 하고요.\n\n그는 남쪽에서 찾을 수 있을 텐데, 거기까지 가려면 비행선을 타야 할 정도로 아주 먼 곳이죠. 타나라신? 텐케리스? 타네라니사니? 뭐 그런 비슷한 이름이었는데!",
    },
    [26597] = {
        ["T"] = "마법의 메달리온",
        ["O"] = "마법의 메달리온을 운고로 분화구에 있는 야루니 플레임워처(Yaluni Flamewatcher)에게 가져가십시오.",
        ["D"] =
        "아뇨? 검은바위 산의 용암에 떠다니는 걸 주웠다고요? 글쎄요, 적어도 재밌는 이야기거리네요. 그렇게 말하면 대지 고리회를 자극하는 건 피할 수 있을지도 몰라요.\n\n네, 이 아뮬렛에는 대지 고리회의 상징이 있습니다. 알다시피 그들은 좀 신비롭고 고대의 주술사 같은 무리죠. 아마 자기들끼리만 아는 엄청난 힘을 부리고 그럴 겁니다.\n\n당신이 이 작은 발견을 돌려주고 싶어 하는 선량한 타입이라면, 그들의 일원 중 한 명이 원시 정령들을 연구하러 운고로 주변을 서성이고 있다고 들었어요. 하지만 여기요...\n<마본이 메달리온을 만지작거립니다.>\n이걸 간직하고 싶다면 새것처럼 쓸 수 있을 겁니다. 예전에 소유했던 사람이 누구든 확실히 이젠 필요 없을 테니까요...",
    },
    [26598] = {
        ["T"] = "빚 수금",
        ["O"] = "펠스톤 요새 안의 존 테일러, 조엘 테일러, 조슈아 테일러에게서 그록스의 상품을 약탈하십시오.",
        ["D"] =
        "힘 좀 써야 할 문제가 하나 생겼어.\n\n여기 요새에 나한테 큰 빚을 진 불량배들이 있거든 -- 언데드 형제 삼 인방이지. 저번에 우리가 여기 부두에 정박했을 때, 녀석들은 내가 파는 물건을 각자 하나씩 원했지만 당장 가진 돈이 없었지. 다음에 내가 올 때 돈을 지불한다는 조건으로 물건을 내줬어.\n\n그런데 이게 웬걸? 난 아직도 그 돈을 기다리고 있다고! 고블린은 절대 잊지 않아, $R. 명심해!\n\n한 놈은 내 지팡이를, 다른 놈은 시계를, 마지막 놈은 마법의 북을 갖고 있지. 뼈를 몇 개 부러뜨려서라도 내 물건을 되찾아와 줘, 무슨 말인지 알지?",
    },
    [26599] = {
        ["T"] = "병사들 먹이기",
        ["O"] = "재갈기멧돼지에게서 유황 고기(Sulfurous Meat) 10개를 모으십시오.",
        ["D"] =
        "이런 곳에선 긍정적인 태도를 유지하는 게 중요해. 근데 여기 사람들이 널 좀 차갑게 대하는 것 같지? 너무 마음에 두진 마. 황량한 풍경, 끊임없는 번개, 어둠의 문이 깨어날지도 모른다는 위협... 이런 것들이 이곳에 주둔한 대부분의 사람들을 지치게 하니까.\n\n여긴 스트레스가 심한 초소일 뿐만 아니라, 배고픔은 사람을 끔찍하게 변하게 만들지. 우린 다음 대규모 보급품이 도착할 때까지 비상 식량을 축내고 있어... 다음 보급품이 언제 올지는 아무도 모른다니까!\n\n이곳 동물들은 식용으로 적합하지 않지만, 내게 계획이 하나 있어. 좀 도와줄래?\n\n이 지역 주변의 재갈기멧돼지 고기가 필요해. 들 수 있는 만큼 많이 가져다줘. 다만 너무 질긴 부분은 피하고.",
    },
    [26600] = {
        ["T"] = "해답은 연금술",
        ["O"] = "네더가드 요새의 마법사 탑 안에 있는 니나 라이트브루와 대화하십시오.",
        ["D"] =
        "탑 위에 있는 니나를 만난 적 있나? 그녀는 이곳과 그늘숲을 오가며 연금술 용품을 팔고 있지.\n\n그녀가 연금술 자체에 진짜 열정을 가지고 있다고 말하긴 했는데, 자신의 결과물에는 자신감이 없더군. 실용적인 문제를 해결하기 위해 그녀를 끌어들일 완벽한 기회야.\n\n어때, $N? 이 물건들을 먹을 수 있게 만들도록 그녀에게 도움을 요청해 줄 수 있겠어? 그리고 내가 안부 전한다고 말해줘!\n\n<룬겔츠가 상냥한 미소를 지어 보입니다.>",
    },
    [26601] = {
        ["T"] = "진흙 정화",
        ["O"] = "저주받은 땅 해안 근처의 퇴적물에서 붉은 진흙 7개를 수집하십시오.",
        ["D"] =
        "그러니까... 계획은 연금술을 사용해서 이 악마 같은 고기를 먹을 수 있는 무언가로 바꾸겠다는 거군요? 음... 잘 모르겠지만, 시도해 봐서 나쁠 건 없겠죠.\n\n<니나가 턱을 문지르며 한참을 깊은 생각에 잠깁니다.>\n\n이게 말도 안 되는 소리처럼 들릴 수 있지만, 우리가 타는 말들은 늪을 지나고 나면 병에 걸리곤 해요. 그런데 도착하고 나면 말들이 항상 땅에 있는 진흙 덩어리를 파먹는 걸 봐요. 다음 날이면 언제 그랬냐는 듯 멀쩡해지죠.\n\n아마도... 진흙에 어떤 정화 효과가 있는 게 아닐까요? 소량이라면 어디서든 찾을 수 있지만, 조수간만의 차이가 있으니 해안가에서 더 쉽게 찾을 수 있을 거예요.",
    },
    [26602] = {
        ["T"] = "배급 준비 완료",
        ["O"] = "네더가드 요새 안에 있는 병참장교 룬겔츠에게 이 소식을 전하십시오.",
        ["D"] =
        "좋아요, 한번 시험해 봅시다. 물을 끓이고, 으깬 숯, 생채기풀, 그롬의 피를 넣고... 이제 진흙을 넣는 거죠.\n\n<니나가 진흙을 냄새나는 용액에 섞어 점성 있게 만듭니다.>\n\n이제 갑니다...\n\n<혼합물이 고기와 닿으면서 맹렬하게 지글거립니다. 잠잠해지자, 뭔가가 제대로 되었다는 것이 분명해집니다.>\n\n오, 세상에... 냄새가 사라졌어요! 더 이상 끈적이는 것도 없고, 색깔도 밝아졌고, 요리까지 된 것 같네요!\n\n<니나가 고기를 조심스럽게 살피더니 맛을 봅니다.>\n\n흠... 나쁘지 않네요! 운이 좋았나 봐요, $N. 룬겔츠에게 이 좋은 소식을 전해주는 게 어때요? 남은 걸 다 요리해서 나중에 가져다줄게요. 정말 고마워요!",
    },
    [26603] = {
        ["T"] = "정찰병 모그리아",
        ["O"] = "저주받은 땅의 해안 어딘가에서 정찰병 모그리아(Scout Morgria)를 찾으십시오.",
        ["D"] =
        "제가 찾던 바로 그 $R로군요, $N.\n\n아마 보지 못하셨겠지만, 저주받은 땅에서 돌아온 우리 정찰병과 그런트 일부가 저주에 걸린 채 돌아오고 있습니다. 이건 사라지지도 않고, 우리 흑마법사들도 이런 건 처음 본다고 하더군요.\n\n남은 정찰병 중 한 명을 상황을 파악하기 위해 남쪽 정찰 임무에 파견했습니다. 당신이라면 그녀와 함께 훌륭하게 일을 해낼 수 있을 거라 생각합니다. 그녀가 약간 다혈질이니 균형을 잘 맞춰주십시오. 저 아래 황무지의 위험을 과소평가해서도 안 됩니다.\n\n마지막으로 본 보고서에 따르면 그녀와 그녀의 짐마차는 저주받은 땅 해안가에 있습니다. 힘과 명예를, $N.",
    },
    [26604] = {
        ["T"] = "약골 처치",
        ["O"] = "저주받은 땅에서 어둠의 서약 이교도들을 처치하십시오.",
        ["D"] =
        "파견사령관님이 정보를 수집하라고 날 이곳에 보냈지. 필요한 정보는 다 모았다! 이교도들은 우리 옆구리의 곪은 상처와 같아서, 멀리서 우리를 겁주고 저주를 퍼뜨리고 있다.\n\n<모그리아가 근처의 언데드를 매서운 눈초리로 쏘아봅니다. 언데드는 과묵하게 그녀의 시선을 마주합니다.>\n\n전부 죽여라, $N. 여기서 남서쪽에 있는 요새 외곽을 배회하는 찌꺼기들부터 시작해라. 놈들의 피로 이 땅을 더 붉게 물들여주지. 호드를 위하여!",
    },
    [26605] = {
        ["T"] = "얼라이언스 처치",
        ["O"] = "네더가드 요새 주변의 얼라이언스 병사들에게서 네더가드 휘장 16개를 수집하십시오.",
        ["D"] =
        "이교도들도 문제지만, 얼라이언스 놈들을 보는 것만큼 내 피를 끓게 하는 건 없다! 우리는 이 야영지의 손님이니 예의를 갖춰야 하지만... 저 쓰레기들이 지나가는 걸 볼 때마다 참기가 힘들다! 내게 권한이 있었다면 네더가드 요새에 총공격을 감행했을 거다!\n\n상관은 늪으로 향하는 악마들을 막을 방패막이로 그들이 필요하다고 하지만... 내 생각엔 개소리다! 넌 나와 같은 명령을 받고 있지 않으니 가라, $N. 요새 주변의 병사들에게서 얼라이언스 휘장을 가져오면 두둑하게 보상해주지.",
    },
    [26606] = {
        ["T"] = "수확의 시간",
        ["O"] = "저주받은 땅의 요새 무기고에서 네더가드 광석 보급품 10개를 훔치십시오.",
        ["D"] =
        "<토르스라크가 고개를 돌려 오른쪽 눈으로 당신을 쳐다봅니다.>\n\n나쁜 눈을 가졌다고, $C.... 좋은 기회를 못 본다는 뜻은 아니지.\n\n스토나드로 돌아가면, 무기, 건물 유지보수, 수리 등 온갖 곳에 쓰일 금속이 필요하다. 여기서 북서쪽 언덕 위에 네더가드 놈들의 고품질 광석이 가득한 광산이 있지. 분명 스톰윈드의 나약한 대장장이들에게 보낼 광석 상자들이 어딘가에 쌓여 있을 거다.\n\n그 광석이 좀 필요하다, $C.",
    },
    [26607] = {
        ["T"] = "새로운 미각",
        ["O"] = "저주받은 땅의 붉은돌 수정가죽도마뱀에게서 붉은돌 옆구리살 10개를 수집하십시오.",
        ["D"] =
        "보급품이 떨어져 가는데, 이 땅은 한여름의 듀로타보다도 가혹하군! 해부학을 알지 못하면 이곳의 모든 건 먹기에 독이 되지.\n\n이곳을 배회하는 붉은 바실리스크가 해체해서 식용으로 만들기에 가장 쉽다. 몸통에서 머리를 잘라낸 다음, 목구멍에 손을 넣어 독이 퍼지기 전에 주황색 분비샘을 꺼내야 한다. 충분히 빠르지 않으면 고기를 못 쓰게 되거든.\n\n내게 옆구리살을 가져오면 요리를 시작하지! 네 몫도 챙겨줄 테니 걱정 마라.",
    },
    [26608] = {
        ["T"] = "펠스톤 정벌",
        ["O"] = "펠스톤 요새의 거주민들에게서 누더기 귀 50개를 수집하십시오.",
        ["D"] =
        "그 요새는 이 땅에서도 재앙 같은 곳이다. 우리가 \"지켜보며 기다리는\" 시간이 길어질수록, 그곳은 더 위험해진다.\n\n스토나드를 떠나기 전, 우리는 오그리마에 지원을 요청했다. 편지가 세상 반대편에 닿을 때까지 손가락만 빨고 앉아있는 걸 참을 수 있겠나... 그 편지를 어떤 멍청이가 다른 편지 더미 속에 던져넣을지도 모르는 일인데!\n\n난 참을 만큼 참았다! 전사들을 모아라! 전리품을 가져와라, $N. 귀를 말이다. 네가 일으킨 피바람의 증거를 원한다! 그 요새에 들어가서 놈들의 대가리를 박살내라. 호드를 위해 봉사하는 데 허락 따윈 필요 없다!",
    },
    [26609] = {
        ["T"] = "펠스톤 광산",
        ["O"] = "펠스톤 요새 내부의 광산에서 펠스톤 금 광석 30개를 수집하십시오.",
        ["D"] =
        "저쪽에 있는 언데드가 펠스톤 아래에 있는 광산에 대해 말해줬다. 마지막으로 들었을 때 광맥이 아주 튼튼하고, 이 지역에서 가장 크다고 하더군.\n\n그 파이 한 조각을 우리가 차지하자고, $C. 이대로 가면 그 요새에 살아남는 놈은 아무도 없을 거다. 쥐새끼들이 광석을 들고 도망치기 전에 챙기는 게 좋을 거다.",
    },
    [26610] = {
        ["T"] = "스토나드에 보고",
        ["O"] = "슬픔의 늪의 스토나드에 있는 파견사령관 루아그에게 보고하십시오.",
        ["D"] =
        "<모그리아가 당신에게 경례하며, 윤기 나는 붉은 인장이 찍힌 찢어진 두루마리를 건넵니다.>\n\n임무는 성공적이다, 전부 네 덕분이지. 칭찬할 것밖에 없구나, $N. 넌 이 장소를 최대한 멀리하고 싶을 테니, 슬픔의 늪의 스토나드에 있는 파견사령관님께 이 보고서를 가져가라.\n\n호드의 적들을 처치한 영광만으로 부족하다면, 그분이 확실히 보상해 주실 거다.\n\n록타르 오가르!",
    },
    [26611] = {
        ["T"] = "사악한 자들을 위한 안식",
        ["O"] = "밤의 추적자 로스를 펠스톤 요새 밖으로 호위하십시오.",
        ["D"] =
        "<그 언데드를 쿡 찌르자 입술 사이로 희미한 쉿 소리가 새어 나오며 눈을 뜹니다.>\n\n당신은 이교도가 아니군? 도와줘, $C! 놈들이 내게 군단 마법을 쓰고 있었어. 더 이상은 견딜 수가 없어...\n\n우린 이곳을 떠나야 해... 당장 떠나야 한다고! 고문관은 처-처리했나?\n\n우리가 여-여기서 무사히 빠져나가면, 언더시티의 도-도적 지구에 있는 그레고리 찰스를 찾아가.",
    },
    [26612] = {
        ["T"] = "응답받은 기도",
        ["O"] = "성기사 셔먼을 펠스톤 요새 밖으로 호위하십시오.",
        ["D"] =
        "<인간의 눈이 번쩍 뜨이고 당신의 존재를 눈치챕니다.>\n\n당신... 이교도가 아니군요? 오늘이 며칠이죠? 여기서 나가야 해요!\n\n내 분대의 절반이 선발대에게 학살당했어요... 그-그들이 남은 우리를 이곳으로 데려왔고, 이제 남은 건 나 하나뿐이에요.\n\n제발, 떠나야 합니다! 빛의 은총으로 우리가 탈출한다면 -- 스톰윈드의 빛의 대성당에 계시는 그레이슨 섀도브레이커 경에게 당신이 한 일을 전해주세요.",
    },
    [26613] = {
        ["T"] = "네더가드를 위한 원조",
        ["O"] = "네더가드 요새 내부의 감시자 마할 바에게 원조 요청서를 반환하십시오.",
        ["D"] =
        "<시체는 비교적 신선합니다. 드워프의 가슴에 난 너덜너덜한 상처에서 피가 웅덩이처럼 땅에 새어 나왔습니다.>\n\n<드워프의 장비는 손대지 않은 것처럼 보이며, 낡은 배낭 안에서 네더가드 요새의 공식 통신문으로 보이는 편지를 발견합니다.>",
    },
    [26614] = {
        ["T"] = "정보 수집",
        ["O"] = "저주받은 땅 전역의 어둠의 서약 이교도들에게서 이교도 기록 묶음 12개를 수집하십시오.",
        ["D"] =
        "어둠의 서약은 우리가 어둠의 문을 감시하는 데 있어 항상 골칫거리였습니다. 우리는 보통 고립된 사건이나 실랑이에서 그들을 만나곤 했지만, 그들은 점점 더 대담해지고 조직적으로 변했습니다. 파견 나간 정찰병 대부분이 돌아오지 않기 때문에 그들의 성장을 감시할 수조차 없습니다. 게다가, 적은 우리가 치유할 수 없는 기묘하고 새로운 마법 저주를 사용하고 있습니다.\n\n여기서 무슨 일이 일어나고 있는지 궁금하군요. 우리 요원으로 활동해 주시겠습니까? 하급 어둠의 서약 단원들은 최고의 정보원은 아니지만, 우리가 유일하게 만날 수 있는 자들입니다. 여기서 남쪽 계곡에 있는 그들부터 시작하여 그들이 가지고 있을지 모르는 메모나 편지를 가져와 주십시오.\n\n바깥은 위험하니 조심하십시오, $C.",
    },
    [26615] = {
        ["T"] = "큰 그림",
        ["O"] = "펠스톤의 정예 거주민들에게서 펠스톤 서신 20개를 전리품으로 획득하십시오.",
        ["D"] =
        "오크들이 처음 아제로스를 침공했을 때, 이 땅은 자원이 풍부했습니다. 그들은 우리 세계로 쏟아져 들어오면서 펠스톤을 거점과 교두보로 건설했죠. 펠스톤은 2차 대전쟁 때 어둠의 문과 함께 파괴되었습니다. 그 이후로 요새 폐허에 가까이 가는 이는 거의 없었습니다.\n\n하지만, 당신이 회수한 메모에는 그곳을 도시처럼 묘사하고 있습니다. 그 모든 재건 작업이 하룻밤 사이에 일어날 리 없고, 누군가의 감독 없이는 절대로 불가능한 일입니다. 펠스톤에 주둔하는 병력은 어둠의 의회의 여러 분파에서 온 것으로 보이며, 누가 이곳을 지휘하고 있는지 저는 도무지 알 수가 없군요. 그들은 좀처럼 협력하지 않으니까요.\n\n스톰윈드에 있는 동료에게 보낼 보고서를 준비 중인데, 당신이 더 양질의 정보를 수집해 주었으면 합니다. 유능한 동맹의 도움을 구하는 것이 좋을 것입니다. 요새에 잠입하여 장비가 좋은 자가 가진 서신을 찾아보십시오.\n\n명심하십시오 -- 이것은 무엇보다 정찰 임무입니다. 적을 과소평가하지 마십시오. 이 메모들은 펠스톤 내에 매우 강력한 자들이 거주하고 있음을 증명하니, 조심해야 합니다.",
    },
    [26616] = {
        ["T"] = "우리만의 눈",
        ["O"] = "펠스톤 요새 내부의 저주하는 눈 12개에 감시자의 홍채를 사용하십시오.",
        ["D"] =
        "이 기록 중 일부는 흑마법사들이 요새 내에서 거의 전지전능한 존재로 군림하고 있다고 언급합니다. 분명 그들은 형체 없는 눈을 소환해 길거리를 떠다니게 하며 무리를 끊임없이 감시하고 있을 겁니다...\n\n아주 복잡한 마법처럼 들리지는 않으니, 우리가 이 눈을 해킹해서 여기서 그들의 시야를 감시할 수 있다면 큰 가능성이 있을 겁니다. 어쩌면 전염되는 이 저주에 대해 더 알아낼 수 있을지도 모르죠.\n\n요새에 가져갈 수 있는 장신구를 하나 준비했습니다. 이 눈 중 하나를 마주치면 홍채를 통해 쳐다보십시오. 그러면 마법이 걸릴 겁니다. 눈은 많을수록 좋으니, 더 이상 사용할 수 없을 때까지 계속 사용하십시오.",
    },
    [26617] = {
        ["T"] = "펠스톤 광산",
        ["O"] = "펠스톤 요새 내부의 광산에서 펠스톤 금 광석 30개를 수집하십시오.",
        ["D"] =
        "어떻게 지내나, $C. 감시자 영감을 도와준 사람이 당신이라 들었소. 우리 모두를 대표해서 고맙다고 전하지.\n\n또한 남쪽 요새의 광산에 대한 이야기도 들었소. 이 땅의 역사에 대해 아는 게 있나? 오크들이 말라 비틀어지게 만들기 전에는 이 지역에 금이 아주 많았다오. 그놈들이 광산을 작업 중이라면, 아직 좀 남아있을지도 모르지!\n\n펠스톤으로 향하는 거요? 기왕 가는 김에 그놈들이 아래에서 캐는 광석을 좀 가져다주겠소? 네더가드는 손에 넣을 수 있는 모든 자원이 필요하거든!",
    },
    [26618] = {
        ["T"] = "말라붙은 보급품",
        ["O"] = "펠스톤 요새가 어떻게 깨끗한 물을 구하는지 알아내십시오.",
        ["D"] =
        "형편없는 짓거리야, 저 펠스톤은. 이 저주받은 땅도 형편없고... 게다가 예전엔 경치도 그리 좋지 않았지.\n\n저기, 펠스톤 놈들은 어디서 물을 구하는 걸까? 우린 우리만의 음료수를 알지만...\n\n<힐다르가 그녀의 자매 근처에 있는 맥주가 가득 담긴 큰 마차를 향해 고개를 끄덕입니다.>\n\n...이 지역의 모든 우물이 말라버렸다는 것도 알지. 여긴 비도 안 와. 설마 마법으로 창조한 물만 마시는 건 아니겠지..? 그건 건강에 나쁘다고!\n\n누구나 물은 필요해, $N. 만약 그쪽으로 간다면, 조사 좀 해보는 게 어때? 어쩌면 우리가 생각한 것보다 훨씬 많은 걸 알아낼 수 있을지도 몰라... 우리만의 깨끗한 물을 구하는 방법까지도 말이야! 마지막으로 들었을 때 우린 물이 꽤나 부족했거든.",
    },
    [26619] = {
        ["T"] = "최악은 아니군",
        ["O"] = "그록스 머크스웨거에게 펠스톤 그로그주 24병을 가져가십시오.",
        ["D"] =
        "그래서, 네더가드도 물에 관심이 있다고? 뭐야... 스톰윈드 거물들이 지원을 끊기라도 한 건가? 걱정 마라, 걱정 마...\n\n흠... 물물교환은 어때? 난 펠스톤 녀석들한테 애정 따윈 없어 -- 음침하고, 표리부동하고, 가끔은 대놓고 역겹지! 하지만 그로그주는 꽤 기막히게 만들거든.\n\n오... 그 물건 두 다스만 가져와. 그렇게 해주면, 내 물을 좀 나눠주고 우리가 여기서 출항한 후에 나머지를 네더가드로 배달해주지.",
    },
    [26620] = {
        ["T"] = "지친 자들을 위한 물",
        ["O"] = "네더가드 요새에 있는 힐다르 선더브루에게 물통을 배달하고 소식을 전하십시오.",
        ["D"] =
        "여기 있다.\n\n<그록스가 날카로운 휘파람을 붑니다. 갑판원 한 명이 재빨리 통을 끌고 와 당신 앞에 내려놓습니다.>\n\n내가 말했듯이 -- 네가 찾을 수 있는 가장 신선한 물이다! 그 힐다르라는 아가씨한테 내가 곧 네더가드에 들러 나머지를 배달하고 앞으로의 선적에 대해 논의할 거라고 전해라. 방법은 걱정하지 마, 그냥 우리한테 맡겨. 당신과 거래해서 즐거웠다.",
    },
    [26621] = {
        ["T"] = "부활하는 악",
        ["O"] = "스톰윈드의 마법 지구 마법사 탑에 있는 고위마술사 안드로매스와 대화하십시오.",
        ["D"] =
        "우리가 알아낸 모든 것을 보고서로 정리했습니다, $N. 스톰윈드에 있는 제 동료는 헤아릴 수 없는 힘을 지닌 현자인 고위마술사 안드로매스입니다. 이 보고서를 그에게 서둘러 가져가십시오. 그가 이 글을 읽고 나면, 틀림없이 이 위협을 박멸하기 위해 그의 막대한 영향력을 빌려줄 것입니다.\n\n저는 당신의 행동에 대해 적었고, 당신이 여기서 준 모든 도움을 자세히 설명했습니다. 고위마술사님은 당신이 도착하면 무언가를 주실 것입니다.\n\n빛이 항상 당신과 함께하길, $N. 이것이 우리가 하는 마지막 일이라 해도, 우리는 이 어둠의 세력을 막아낼 것입니다.",
    },
    [26622] = {
        ["T"] = "가라앉은 보물",
        ["O"] = "저주받은 땅 해안의 난파선 중 한 곳에서 가라앉은 보물을 찾으십시오.",
        ["D"] =
        "이봐! 수영 잘하게 생겼는데, 나 수영 잘하는 사람이 필요하거든.\n\n저기 저 난파선들 보여? 항구로 들어올 때마다 저게 보이는데, 이런 생각이 들더라고: 가라앉은 보물!\n\n나 대신 확인해주면 보수도 줄게. 난 저 아래 난파선이 네 척인 걸 셌어. 뭐라도 찾으면 가져와, 전리품을 나눠 갖자고...\n\n아, 그리고 저 아래에서 무시무시한 해골들이 수영하는 걸 본 것 같아. 조심해, $R!",
    },
    [26623] = {
        ["T"] = "뼈다귀 파티",
        ["O"] = "그롬볼라 안에서 튼튼한 뼈 30개를 모아 로코와 테디에게 가져가십시오.",
        ["D"] =
        "<로코가 입에 양말을 문 채 안절부절못하며 꿀꿀거립니다. 우리 곳곳에 흩어져 있는 뼈다귀들이 눈에 띄는데, 모두 거의 흔적도 없이 갉아먹혔습니다.>",
    },
    [26624] = {
        ["T"] = "현상 수배: 영혼의 약탈자 그루조크",
        ["O"] = "펠스톤 요새 안의 그롬볼라에 들어가 영혼의 약탈자 그루조크의 머리를 취하십시오.",
        ["D"] =
        "영혼의 약탈자 그루조크로 알려진 자를 찾아 처치하기 위해 어둠의 서약 영토 깊숙이 모험을 떠날 용감한 자들이 필요합니다.\n\n그는 극도로 위험한 인물로 간주됩니다. 신뢰할 수 있는 정보에 따르면 그는 네더가드 남쪽 펠스톤 요새 깊숙한 곳, 뼈로 둘러싸인 동굴 안에 있습니다.\n\n현상금을 받으려면 그루조크의 머리를 병참장교 룬겔츠에게 가져가십시오.",
    },
    [26625] = {
        ["T"] = "현상 수배: 영혼의 약탈자 그루조크",
        ["O"] = "펠스톤 요새 안의 그롬볼라에 들어가 영혼의 약탈자 그루조크의 머리를 취하십시오.",
        ["D"] =
        "호드의 일원들이여, 이것은 무기를 들라는 부름이다! 굴단의 옛 추종자들이 펠스톤 요새 안에 둥지를 틀고, 죽은 자를 일으키며 사악한 강령술을 부활시켰다.\n\n이 집단의 우두머리는 영혼의 약탈자 그루조크로 알려져 있으며, 그를 처치하기 위해 노련한 파티가 필요하다. 남쪽 펠스톤 요새 내의 뼈로 둘러싸인 동굴 안에서 그를 찾아라.\n\n현상금을 완료하려면 그의 머리를 정찰병 모그리아에게 가져가라.",
    },
    [26626] = {
        ["T"] = "뜻밖의 동맹",
        ["O"] = "저주받은 땅의 해안 어딘가에서 이살니르를 찾아 대화하십시오.",
        ["D"] =
        "대부분은 인정하지 않겠지만, 우리는 끔찍한 궁지에 처했습니다. 네더가드는 한동안 병력을 지원받지 못했고, 사람들은 전에 본 적 없는 저주로 고통받고 있으며, 우리 주변의 땅은 날이 갈수록 더 위험해지고 있습니다.\n\n2주 전 시약을 채집하다가, 남쪽에 있는 요새의 폐허에서 도망쳐 나온 언데드와 마주쳤습니다. 저는 싸울 준비를 했지만, 그는 두 팔을 들어 올리며 자신의 상황을 설명했습니다.\n\n그는 한때 이교도의 고위 단원이었고, 탈출하려다 거의 죽을 뻔했다고 합니다. 이제 그는 호드나 얼라이언스에 피난처를 찾고 있지만, 언데드인 그가... 글쎄요, 우리와 함께할 곳이 마땅치 않지 않습니까?\n\n감시자 영감님은 그게 함정의 일종이라고 생각하지만, 솔직히 우리에겐 돌파구가 필요합니다. 그런 자라면 틀림없이 유용한 정보를 가지고 있을 겁니다.\n\n그를 찾아봐 주시지 않겠습니까, $C? 마지막으로 봤을 때 그는 해안으로 향하고 있었습니다.",
    },
    [26627] = {
        ["T"] = "최악 중의 최고",
        ["O"] = "모그리아의 야영지 남서쪽에 있는 펠스톤 전초기지에서 리디아 카트라이트를 처치하십시오.",
        ["D"] =
        "숨기지 않고 말하지 -- 난 아직 어느 진영에도 속하지 않았지만, 예전 동료들에 대한 미련 따윈 없어. 난 그 바보들에게 절대 잊지 못할 교훈을 가르쳐주기 위해서라면 누구와도 일할 거요!\n\n내가 요새에 있었던 기간은 짧았지만, 요새의 모든 비밀을 알고 있지... 더 중요한 건, 그 모든 걸 멈추게 하는 방법을 안다는 거요. 뭐, 잠시 동안이겠지만...\n\n당신이 이 일을 맡을 능력이 되는지 확인해야겠소. 근처 전초기지에 은밀한 자가 이교도 무리를 지휘하고 있소. \'리디아 카트라이트\'라는 자지.\n\n친구들을 데려와서... 그녀를 죽이고 오면, 그 다음으로 넘어가겠소.",
    },
    [26628] = {
        ["T"] = "기반이 무너지다",
        ["O"] = "펠스톤 요새 안에서 펠스톤 상인 15명, 펠스톤 광부 15명, 펠스톤 인부 15명을 처치하십시오.",
        ["D"] =
        "펠스톤의 사회적 기반은 일꾼들로 이루어져 있소. 그들의 개입 없이는 아무것도 작동하지 않지. 장군 나로크는 공포와 고통을 통해 그들에 대한 통제력을 조이는 데 엄청난 시간을 보냈소.\n\n요새는 이 지역에서 가장 큰 금맥 위에 자리 잡고 있고, 일꾼들이 그것을 수확하지. 펠스톤의 오래된 구조물들은 폐허가 되었지만, 일꾼들이 그것들을 수리하고 있소. 부두에는 운송이 필요한 물건들이 있고 -- 수확한 금으로 사들인 것들이지, 기타 등등...\n\n뭘 해야 할지 알겠지, $N.",
    },
    [26629] = {
        ["T"] = "진정한 신도들",
        ["O"] = "펠스톤 요새 내에서 야수조련사 진라, 요리사 데빈, 부두관리인 리암을 처치하십시오.",
        ["D"] =
        "펠스톤의 병력 중에는 필수 불가결한 단원 몇 명이 생각나는군. 그들을 죽이면 지휘 계통에 깊은 불화를 심을 수 있을 거요.\n\n늑대들을 돌보는 거친 여자인 야수조련사 진라는 요새 내의 기마 순찰대와 중요한 물자 배달을 감독하지. 짐승들은 오직 그녀만 따른다오. 그녀는 마구간 근처 가장 서쪽 높은 곳의 큰 오두막에 살고 있소.\n\n요리사 데빈은 진짜배기 악당이지 -- 낮에는 요리사, 밤에는 고문관인데, 감히 요리된 고기가 어디서 나오는지 의문을 제기하는 자가 없소. 그는 요새에 공포를 생생하게 유지하며, 남쪽 중간 계단의 벽으로 둘러싸인 구역을 배회한다오.\n\n마지막으로 부두관리인 리암은 펠스톤의 물류와 해상 무역의 배후에 있는 천재요. 그는 외톨이지... 아마 항구 사무실에 틀어박혀 책에 파묻혀 있을 거요.",
    },
    [26630] = {
        ["T"] = "배신의 상처",
        ["O"] = "이살니르의 소지품을 찾고 펠스톤 요새 안의 에델드린에게서 이살니르의 문양을 전리품으로 획득하십시오.",
        ["D"] =
        "펠스톤 안에서 나는 살아있는 자들이 소위 친구라고 부를 만한 자를 가졌지, 믿거나 말거나.\n\n하이 엘프인 \'에델드린\'과 나는 많은 관심사를 공유했소. 그것은 몹시 매혹적이었지. 함께 협력하면서 나는 경계를 풀었고... 그의 행동은 교묘해서 내 주변 사람들에 대한 그의 영향력이 잡초처럼 자라나는 것을 눈치채지 못했소. 내가 도망쳤을 때, 그는 내가 가진 모든 것을 물려받았지.\n\n그중 일부를 되찾고 싶소. 부두 근처 언덕에 있는 내 옛 텐트에 내 소지품이 든 배낭이 있소. 에델드린은 내 문양을 가지고 있지: 저주에 대한 일종의 \'열쇠\'이자 저주를 멈추려면 꼭 필요한 물건이오.",
    },
    [26631] = {
        ["T"] = "눈엣가시",
        ["O"] = "펠스톤 요새 안의 세이아나 브라이트글렌에게서 세이아나의 문양을 전리품으로 획득하십시오.",
        ["D"] =
        "나의 상대는 세이아나 브라이트글렌이었는데, 불행히도 완벽에 대한 기호를 가진 뛰어난 흑마법사였소. 사소한 결점 하나하나가 그녀의 비아냥을 샀고, 나는 여전히 꿈속에서 내가 총애를 잃은 후 그녀가 지었던 악마 같은 웃음을 보오.\n\n인정하지, 지금 퍼지고 있는 이 저주... 그 지옥불은 우리 두 사람 두뇌의 산물이오. 그녀가 해로운 측면을 다루었고, 나는 위력과 지속력을 다루었소.\n\n<이살니르가 두 손을 들고 반쯤 미안한 듯 고개를 숙입니다.>\n\n쉬운 싸움을 기대하진 마시오. 그녀는 우리가 저주에 맞서 싸우기 위해 필요한 또 다른 문양을 가지고 있소. 펠스톤의 중심에서 서쪽으로 향하면, 주도로 오른편의 언덕에서 그녀를 찾을 수 있을 거요.",
    },
    [26632] = {
        ["T"] = "장군의 문양",
        ["O"] = "펠스톤 요새 안의 장군 나로크에게서 나로크의 문양을 전리품으로 획득하십시오.",
        ["D"] =
        "마침내 때가 왔소, $N. 이제 뱀의 머리를 노리러 갈 때요. 우린 아주 가까이 왔소...\n\n충성의 표시와 더 큰 보안을 위해, 세이아나와 나는 장군 나로크에게 그만의 문양을 주어야 했소. 세 개의 문양을 결합하면 저주에 대한 약간의 통제권을 얻을 수 있소. 세상에서 저주를 영원히 없앨 만큼은 아니지만... 시작은 할 수 있지. 사례별로 당신에게 걸린 저주를 해제해 줄 수 있을 거요.\n\n나로크는 남쪽 맨 끝의 가장 높은 계단에 있는 자신의 탑에 거주하오. 다른 자들이 죽은 후 그는 당신이 자신을 노리러 온다는 걸 알게 될 거요. 내게 그의 문양을 가져오면, 내가 돕고 퍼뜨린 저주를 통제하기 시작할 수 있소.",
    },
    [26633] = {
        ["T"] = "애쉬폴 무장하기",
        ["O"] = "타우릿산의 폐허에 있는 타우릿산의 첩자와 타우릿산의 요원에게서 검은무쇠 단검 10개와 검은무쇠 총 5개를 회수하십시오.",
        ["D"] =
        "시간 좀 있나? 싸움을 두려워하지 않는 사람처럼 보이는군.\n\n어둠괴철로 도시로 돌아가면, 나는 장교였지... 어느 정도... 내 지휘 아래 많은 드워프가 있었으니까. 다른 일을 하는 건 쓸모없을 테니 토륨 대장합회에 없어서는 안 될 존재가 될 생각이야. 네 도움이 필요해.\n\n이 작은 촌락이 안전할 거라 생각하겠지만, 몇 달마다 오크 습격대가 지나가지. 저기 모건이란 친구가 모두의 무기를 좋은 상태로 유지하려고 최선을 다하지만, 습격이 너무 자주 와.\n\n타우릿산의 잔해 속에 가면 무기로 무장한 고약한 첩자와 요원들이 득실대지. 여기 경비병들을 위해 그 무기들을 좀 조달해 주겠나? 보수는 주지.",
    },
    [26634] = {
        ["T"] = "오크 놈들은 지긋지긋해!",
        ["O"] = "애쉬폴 초소 서쪽의 검은바위 오크 30명을 처치하십시오.",
        ["D"] =
        "그래, 바로 여기 서쪽엔 상대해야 할 검은 호드 꼬맹이들이 있어. 군대 전체를 상대하라는 건 아니지만, 네가 죽이는 오크 한 명 한 명이 이곳의 생명을 구하는 일이 될지도 몰라.\n\n가서 이 호드 무리를 좀 줄여볼 텐가? 놈들을 이끄는 우두머리를 눈여겨보고 있지만, 정찰을 좀 더 해봐야 해.",
    },
    [26635] = {
        ["T"] = "불타는 히드라",
        ["O"] = "애쉬폴 초소 서쪽에서 부대장 그루마, 마술사 말타르그, 대장장이 트랄락을 처치하십시오.",
        ["D"] =
        "저 밖에서 지휘하는 오크들을 한동안 주시해 왔는데, 자네만 괜찮다면 처리하고 싶은 놈들을 몇 명 찾았지.\n\n부대장 그루마는 여기서 서쪽에 있는 큰 탑의 병력들에게 순찰 명령을 내린다. 마술사 말타르그는 탑에서 남서쪽으로 그리 멀지 않은 곳에서 뭔가 의식을 치르고 있지... 틀림없이 나쁜 짓을 꾸미고 있을 거야. 대장장이 트랄락은, 짐작했겠지만--가열로에 있다... 이놈들에 대해선 더 할 말이 없군.\n\n뒤를 조심해, $C. 네가 없는 동안 난 계속 정찰하마.",
    },
    [26636] = {
        ["T"] = "가장 아픈 곳을 찔러라",
        ["O"] = "애쉬폴 초소의 북서쪽, 검은바위 요새 안에 있는 나르고쉬 레이지블레이드를 처치하십시오.",
        ["D"] =
        "좋아, 그래서... 이 지역의 우두머리 오크인지 뭔지 하는 놈에 대해 알아냈지... 내가 보기에 놈은 약간 벼락출세한 놈이야 -- 최근에야 그 자리에 올랐지.\n\n이름은 나르고쉬 레이지블레이드. 검은바위 산 동쪽의 큰 요새에서 그를 찾을 수 있다... 그러니까 여기서 북서쪽이지. 근육이 장난 아니니까 조심해... 아마 그 우스꽝스러운 이름값을 할 거야.\n\n좋은 사냥이 되길, $C.",
    },
    [26637] = {
        ["T"] = "부재중인 담화",
        ["O"] = "모건 블랙아이에게 그룰 스톤크릭의 도면을 배달하십시오.",
        ["D"] =
        "반갑군, $C. 대지 고리회에서 이 땅의 상태를 평가하라고 날 이곳에 보냈다네.\n\n불은 내가 이곳에서 말하는 것을 들을 수 있는 유일한 원소지. 정령들의 태도부터 그들이 쓰는 방언까지 화신 그 자체다. 다른 모든 목소리를 압도하는 하나의 목소리--땅을 전율케 하는 쇳소리가 들린다... 내가 침묵시킬 목소리지. 나를 도와주겠나?\n\n우린 이 목소리 뒤에 숨겨진 힘을 정령에 묶어 취약하게 만들 수 있다. 하지만 준비가 필요하지. 이 도면을 저기 있는 드워프에게 가져다주게... 모건이라고 불렸던 것 같은데.\n\n그가 내가 그린 것을 제작할 수 있는지 보게. 그동안 나는 목표를 위한 시약을 모으고 때가 되면 널 찾겠다.",
    },
    [26638] = {
        ["T"] = "구속하는 팔보호구",
        ["O"] = "불타는 평원 전역의 다양한 적들에게서 검은무쇠 조각 30개를 전리품으로 획득하십시오.",
        ["D"] =
        "흠... 팔보호구? 흥미로운 도면이군. 내 둥그런 배뚱땡이보다 두껍잖아! 그 덩치 큰 녀석에게 정말 이 팔보호구에 맞는 손목이 있단 말인가?!\n\n<모건은 당신이 불의 정령을 결속하여 파괴하고 땅을 진정시키려는 계획에 대해 설명하는 것을 듣습니다.>\n\n하, 전적으로 찬성할 만한 계획이로군! 기꺼이 돕겠지만, 내게 이런 프로젝트에 당장 쓸 금속이 있다고 생각하진 마! 하지만 검은무쇠 조각이라면 쓸 수 있겠는데...\n\n방어구, 무기, 장신구--뭐든지 검은무쇠를 쓰는 사람들은 많아! 내게 조각들을 좀 가져다주면 무료로 그 팔보호구를 만들기 시작하마 -- 그 고약한 불의군주 놈을 한 방 먹이고 싶거든!",
    },
    [26639] = {
        ["T"] = "필요한 도움",
        ["O"] = "그룰 스톤크릭과 그의 어려움에 대해 대화하십시오.",
        ["D"] =
        "좋아, 제련을 시작하지. 그... 타우렌과 얘기해 봤어. 내가 제대로 말했나?\n\n널 보자고 하더군. 원대한 계획을 위한 몇 가지 물건을 구하는 데 어려움을 겪고 있다고 말이야.",
    },
    [26640] = {
        ["T"] = "불지옥의 룬",
        ["O"] = "불타는 평원 주변의 마법을 쓰는 인간형 적들에게서 불지옥의 룬 15개를 수집하십시오.",
        ["D"] =
        "필요한 구성 요소는 거의 다 모았다... 딱 하나만 빼고.\n\n고위 드워프들은 타우릿산이 다스리던 시절, 우레망치 바위굴 꼭대기의 제단이 화염 소환의 초기 시도가 있던 장소라고 말하지. 그 시대의 유물로 우리가 의식에 사용할 수 있는 룬이 남아 있다네.\n\n이 룬들은 힘을 품고 있어서, 불나방처럼 평원 전역의 마법 사용자들이 룬을 찾으러 오지.\n\n<그룰이 가슴에 난 새로운 화상 흉터를 당신에게 보여줍니다.>\n\n난 한물갔어 -- 내 몸은 예전처럼 움직이지 않고, 전투에서 거의 쓰러질 뻔했지. 제발, 나를 대신해 네가 찾을 수 있는 모든 룬을 가져다주게.",
    },
    [26641] = {
        ["T"] = "부름을 받다",
        ["O"] = "우레망치 바위굴 정상의 제단에 불의 현신을 소환하여 처치하십시오.",
        ["D"] =
        "<그룰이 중얼거리며 룬 위로 손을 젓자, 룬이 덜그럭거리며 빛납니다.>\n\n흠... 이거로군. 목소리가 외칠 때 이 룬이 내게 속삭인다. 구속할 수 있게 준비하지.\n\n<몇 분이 지나고, 그룰은 모은 모든 구성 요소를 사용하여 작업을 마칩니다.>\n\n됐다. 의식은 간단하다 -- 우레망치 바위굴 꼭대기 제단에서 이 룬을 사용해라. 땅의 끓어오르는 에너지가 팔보호구로 솟구쳐, 정령의 형태로 구속될 것이다. 그것을 처치하면 구속에 쓰인 모든 에너지가 소멸할 것이다.\n\n앞서 말했듯, 불은 폭력적인 원소다. 앞으로의 전투를 위해 동맹을 구해야 할지도 모른다.",
    },
    [26642] = {
        ["T"] = "미란의 실종",
        ["O"] = "미란의 행방에 대한 단서를 찾기 위해 애쉬폴 초소 바로 밖의 구역을 조사하십시오.",
        ["D"] =
        "오, 모험가님! 선술집 입구 곁에 있는 제 표지판을 보셨나요?\n\n제 다정한 남편, 미란이... 며칠째 실종됐어요! 남편은 약초채집사인데 -- 동전을 좀 벌려고 장벽 밖으로 나가 약초를 캐러 가겠다고 했었죠.\n\n<밀디스가 눈물을 글썽이기 시작합니다.>\n\n그 후로 그이를 보지 못했어요! 우린... 우린 이런 곳에 올 준비가 되어 있지 않았어요!\n\n제발... 남편을 좀 찾아주시겠어요?! 분명 당신이 할 수 있는 일이 있을 거예요!",
    },
    [26643] = {
        ["T"] = "오우거의 짓인가?",
        ["O"] = "우레망치 바위굴 북쪽 어딘가에서 미란의 흔적을 찾으십시오.",
        ["D"] =
        "<몸싸움의 흔적과 버려진 주머니는 미란이 이 자리에서 살해당한 것이 아니라 납치되었음을 나타냅니다.>\n\n<큰 발자국과 우레망치 바위굴이 가까운 것으로 보아 습격자는 오우거들일 가능성이 높습니다. 발자국은 북쪽으로 향하고 있습니다. 미란은 아직 살아있을지도 모릅니다.>",
    },
    [26644] = {
        ["T"] = "동굴",
        ["O"] = "근처 동굴로 들어가 미란을 찾으십시오.",
        ["D"] =
        "<셔츠 주변 지역을 조사해 보니 오우거들이 미란을 근처 동굴로 데려갔음을 암시하는 모든 증거가 있습니다. 질질 끌려간 흔적이 동굴 입구로 이어집니다.>",
    },
    [26645] = {
        ["T"] = "미란의 탈출",
        ["O"] = "미란을 우레망치 바위굴 밖으로 호위하십시오.",
        ["D"] =
        "으아아아! 저리 가 이 짐승아! 너-\n\n<미란은 당신이 오우거가 아님을 알아챕니다.>\n\n다-당신은 누구죠?! 당신은... 우호적인가요? 제 아내가 당신을 보냈나요? 오, 밀디스...\n\n번거롭지 않으시다면, 저도... 함께 가도 될까요? 오우거들이 절 장난감처럼 다루고 있어요... 뼈가 몇 군데 부러졌고, 당신이 날 두고 가면 난 얼마 못 버틸 거예요.",
    },
    [26646] = {
        ["T"] = "우리 중의 첩자",
        ["O"] = "타우릿산의 폐허를 배회하는 드워프들을 수색하여 추적의 증거를 찾으십시오.",
        ["D"] =
        "$C. 당신에게 제안할 것이 있소. 어둠괴철로 도시의 상황이 형과 내게 너무 험악해져서, 우리는 토륨 대장합회와 함께 새 삶을 시작하기 위해 이곳으로 여행을 왔소.\n\n<페린이 다가와 목소리를 속삭임으로 낮춥니다.>\n\n사실을 말하자면, 누군가 우릴 미행하는 것 같소. 원로원은 아직 우리와 끝난 게 아니오 -- 과거의 불만 때문에 우리를 다시 법의 심판대(Ring of Law)로 끌고 가고 싶어 하지...\n\n첩자들이 저기 북쪽 폐허를 쥐새끼처럼 숨어다니고 있소. 몇 명 죽여보시오... 나머지가 어떻게 나락으로 도망치는지 확인해 보게. 가장 중요한 건, 형과 나에 관련된 눈에 띄는 무언가를 찾을 수 있는지 알아보는 거요.",
    },
    [26647] = {
        ["T"] = "무법자의 법칙",
        ["O"] = "타우릿산의 갈증(Thaurissan's Thirst) 아래층 방에 있는 손님들의 소지품을 샅샅이 뒤지십시오.",
        ["D"] =
        "도시에 흐르는 끊임없는 피해망상은 항상 혐오스러웠소. 카룸이 앤빌레이지 장교였음에도 불구하고, 우리는 사람들의 심기를 거스르지 않도록 조심해야 했소. 여기 바깥에서는 약간의 숨 쉴 틈이 있지...\n\n당신이 해낼 수 있다면, 아래층 손님들의 숙소를 샅샅이 뒤져서 누구를 찾거나 무엇을 발견하는지 알아보는 게 어떻겠소? 내가 알기로 우리가 여기에 가장 오래 있었으니, 요원은 누구든 될 수 있소.\n\n그 요원을 죽이시오. 물론 보수는 지급하겠소. 공짜는 없는 법이지.",
    },
    [26648] = {
        ["T"] = "문제의 근원",
        ["O"] = "검은바위 나락 안의 숙소로 들어가 이그비르 말리스터를 죽이고 그의 목걸이를 취하십시오.",
        ["D"] =
        "나에게 혈육은 두 명 더 있소. 카룸이 여기 있고, 다른 한 명은 어둠괴철로 안에 있는 이그비르요 -- 콧대가 어찌나 높은지 검은무쇠 부족이라고는 전혀 알아볼 수 없지. 그는 해결사이고, 많은 원로원 의원들이 사악한 짓을 위해 그의 서비스를 이용하오.\n\n우리가 탈출에 대해 말했을 때 그는 우리를 경멸하며 뛰쳐나갔고, 경비병들과 함께 돌아왔소. 카룸이 그들을 처리했고 이그비르는 도망쳤지, 그리고 우리는 여기에 있소. 그 꼬맹이가 우리 뒤를 쫓아 독살자를 보내 자신의 본색을 드러냈군.\n\n혼란을 일으키기 위해 도시로 들어가는 약탈대 이야기를 들었소. 그들의 무리에 합류해서, 그를 죽이고 그가 걸고 있는 목걸이를 가져오시오. 틀림없이 숙소에서 수다를 떨고 있을 거요.",
    },
    [26649] = {
        ["T"] = "골렘 사냥",
        ["O"] = "타우릿산의 폐허 북쪽 구릉지에서 골렘술사 루가르를 찾아 그의 제어봉을 빼앗으십시오.",
        ["D"] =
        "당신 같은 모험가 타입을 찾고 있었지! 나 좀 도와줄 수 있겠나?\n\n이곳의 경비병들을 도울 골렘을 원해. 어릴 적 배운 골렘술에 자부심을 가지고 있긴 하지만, 여긴 공장이 아니야. 그런 파괴자 중 하나를 밑바닥부터 만드는 건 힘든 일이지.\n\n북쪽 폐허 너머 구릉지에 루가르라는 골렘술사가 이 지역의 낡은 전쟁 파괴자들을 수리하고 있다는 소문을 들었지 -- 내가 관심 있는 개인 프로젝트를 진행 중이라더군...\n\n그놈은 지팡이를 하나 가지고 있는데, 자신의 골렘을 조종할 수 있게 해주는 물건이야. 그 지팡이를 구해오면 우리가 사업을 시작할 수 있을 거야!",
    },
    [26650] = {
        ["T"] = "거인의 토대",
        ["O"] = "불타는 평원의 전쟁 파괴자들에게서 온전한 공명기 수정을 얻고, 헬가의 룬문자 병을 사용하여 근처 웅덩이에서 용암을 조금 빼내십시오.",
        ["D"] =
        "<헬가가 잠시 후 눈을 뜹니다.>\n\n허... 녀석이 작업을 다 끝내지 못했다는 건 알겠지만, 적어도 기본은 다 돼 있군.\n\n내가 골렘을 이쪽으로 가져오는 작업을 할게. 우리가 개선할 수 있는 아이디어가 몇 가지 있지!\n\n공명기 수정이 금가서 제어봉을 쓸 때 보기가 힘들어. 이 지역의 전쟁 파괴자들에게서 쓸만한 수정을 구해봐.\n\n오, 그리고 룬문자도 좀 닳았어 -- 용암으로 좀 다듬어야 하는데, 이걸 쓰면 될 거야.\n\n<헬가가 룬문자가 새겨진 유리 같은 병을 건넵니다.>\n\n길을 따라 서쪽으로 올라가면 웅덩이가 있을 텐데... 빠지지 않게 조심해! 이 병은 수년간 끄떡없었으니 다루는 건 걱정하지 말고.",
    },
    [26651] = {
        ["T"] = "핵 충전",
        ["O"] = "검은바위 산 서쪽에 있는 폭풍의 제단으로 동력 없는 골렘 핵을 가져가서 충전하십시오.",
        ["D"] =
        "루가르는 골렘의 핵을 완전히 충전하지 않았지만, 난 어차피 검은바위에서 가져온 내가 직접 만든 핵을 쓰고 싶어. 내 핵은 용량도 더 커서, 아이디어가 하나 있는데...\n\n산 서쪽에 폭풍의 제단이라는 곳이 있어. 오크 마법의 장소라고 하더군...\n\n이 폭풍의 제단이 이름값만 한다면, 이 예쁜이에게 에너지를 공급하기엔 딱 좋은 곳일 거야!\n\n어때, $N? 크게 어렵진 않을 거야. 어, 내 생각엔... 어쨌든...",
    },
    [26652] = {
        ["T"] = "적절한 기름",
        ["O"] = "불타는 평원 전역의 맹독혓바닥, 죽음채찍, 화염꼬리전갈 시체에서 전갈 점액이 든 유리병 16개를 수집하십시오.",
        ["D"] =
        "좋은 골렘의 비밀이 거기에 칠해진 기름이라는 건 누구나 다 알지. 우리가 마법을 쓴다고 돌이 깨지지 않는 것 같아? 아니지!\n\n바로 요전 날, 어떤 상인이 죽은 전갈이 가득 실린 마차를 몰고 오는 걸 봤지. 그 녀석들한테서 나오는 점액 -- 끈적끈적한 강물 같았어! 새 골렘에 쓰기엔 엄청난 잠재력이 있다고 생각해.\n\n우릴 위해 점액을 좀 모아줄래? 평원 전역에서 그 전갈들을 찾을 수 있을 거야. 빈 유리병을 줄 테니 -- 그냥 가득 채워 와!",
    },
    [26653] = {
        ["T"] = "골렘술의 예술",
        ["O"] = "스튜어트를 제어하는 동안 조종을 멈추거나 그가 죽지 않게 하면서 불타는 평원에서 적 20명을 처치하십시오.",
        ["D"] =
        "좋아, $N. 원하는 걸 모두 얻었고 약간 수리도 했어. 녀석이 제대로 작동하고 있지...\n\n재밌게 놀아볼래?!\n\n한번 조종해 봐! 네가 원하는 건 뭐든 맘껏 싸워도 좋아, 하지만 이 테스트가 공정한지 확인하고 싶어 -- 즉 집중을 방해받아선 안 된다는 뜻이야! 준비가 되면 알려줘.\n\n오... 녀석의 이름은 스튜어트야.",
    },
    [26654] = {
        ["T"] = "불의 창자",
        ["O"] = "우레망치 바위굴에 있는 불창자 오우거들에게서 불의 창자 30개를 수집하십시오.",
        ["D"] =
        "안녕... 마법에 대해 아는 거 있어?\n\n안개석을 좀 만들려고 해 -- 아이들이 좋아하거든. 하지만 먼저 동쪽의 오우거들에게서 시약을 좀 구해야 해.\n\n녀석들을 본 지 꽤 오래됐지만, 오우거의 내장이 많이 변했을 것 같진 않군. 당연하겠지만 놈들의 내장이 필요해.",
    },
    [26655] = {
        ["T"] = "영원한 고요는 없다",
        ["O"] = "밤이 되면 붉은마루 산맥의 영원고요 호수 바닥에서 영원고요 호수 잠복꾼(Everstill Lurker)을 처치하고 흐릿한 핵을 수집하십시오.",
        ["D"] =
        "붉은마루에 가본 적 있어? 좋은 곳이지. 내 약혼녀와 내가 한때 거기 살았거든.\n\n어쨌든... 밤이 되면 호수가 요동치지. 거대하고 육중한 짐승이 호수 바닥을 뒤집어 놓아 -- 외래종이라고 해두지. 내 잘못이야. 공격적이진 않지만, 헤집고 다니는 걸 정말 좋아하거든.\n\n이 안개석을 만들려면 놈이 가진 물건이 필요해. 네가 놈을 죽이고 그 핵을 가져다주는 게 어때.",
    },
    [26656] = {
        ["T"] = "날씨를 견뎌내다",
        ["O"] = "불타는 평원에서 불씨 검은늑대 가죽 8개를 수집하십시오.",
        ["D"] =
        "네가 무슨 생각 하는지 알아... \"이 녀석 분명히 다음엔 빌어먹을 돌멩이를 가져오라고 하겠지?\" 맞지?\n\n헤헤... 돌멩이는 벌써 구했으니 걱정 마. 이 내장들이 다 마를 때까지 기다려야 해, 그런 다음 갈아버릴 거거든.\n\n<제이슨 틴링이 몸을 떱니다.>\n\n이봐... 공기에 스민 이 한기가 느껴져? 뼛속까지 시리네...\n\n이렇게 하자: 여기를 배회하는 검은늑대들에게서 가죽을 좀 가져와 주면, 안개석을 좀 나눠주지.",
    },
    [26657] = {
        ["T"] = "관리인의 부탁",
        ["O"] =
        "저승바람 오우거들을 처치하고 그들의 야영지를 수색하여 그들이 카라잔의 폐허를 약탈했는지 확인하십시오. 그 후 저승바람 고개의 아리덴의 야영지에 있는 아리덴 엘리스에게 조사 결과를 보고하십시오.",
        ["D"] =
        "안녕하십니까 여행자여! 평소라면 저승바람 고개를 지나는 자들에게 서둘러 지나가라고 조언하겠지만, 당신은 더 강인한 분 같군요.\n\n저는 늙은 메디브의 장원, 카라잔의 관리인이었습니다. 마법이 폭주했을 때 저는 스톰윈드에 있었는데, 이제 상황이 진정되었으니 그곳이 어떤지 확인해봐야겠다는 의무감을 느낍니다. 하지만 전 어리석은 노인이 아닙니다. 먼저 그곳을 정찰해 줄 용감한 분의 도움이 필요합니다.\n\n그곳에 대한 온갖 끔찍한 이야기를 들으셨을 테니, 무작정 뛰어드는 것은 원치 않습니다. 남쪽 도로변 동굴에 오우거 부족이 이주해 왔습니다. 당신 같은 젊고 진취적인 $g신사:숙녀;분께서 오우거 야영지를 확인하여 그들이 카라잔에서 귀중품을 약탈했는지 확인해 주신다면, 장원을 조사해도 안전할지 알 수 있을 것입니다.",
    },
    [26658] = {
        ["T"] = "관리인의 부탁",
        ["O"] = "카라잔 예배당을 수색하여 숨겨진 관리인의 열쇠를 찾은 다음, 저승바람 고개의 아리덴의 야영지에 있는 아리덴 엘리스에게 열쇠를 가져가십시오.",
        ["D"] =
        "오우거들이 약탈해도 안전할 정도라면, 카라잔 주변도 당신같이 용감한 모험가가 조사하기에 충분히 안전할 것이라 생각합니다.\n\n그들의 전리품에 장원의 물건이 없다는 것은 그곳이 단단히 잠겨 있다는 뜻입니다 - 바라건대 아직 마법으로 봉인되어 있기를 바랍니다.\n\n다행히도 저는 항상 카라잔 예배당에 열쇠 하나를 숨겨 두었습니다. 남쪽 길을 따라 장원으로 간 다음, 장원을 지나 서쪽으로 계속 가면 예배당을 찾을 수 있습니다. 열쇠를 찾을 수 있는지 확인해 보십시오!",
    },
    [26659] = {
        ["T"] = "관리인의 부탁",
        ["O"] = "관리인의 열쇠를 사용하여 카라잔의 정문을 연 다음, 저승바람 고개의 아리덴의 야영지에 있는 아리덴 엘리스에게 돌아가십시오.",
        ["D"] =
        "전 마법사는 아니지만 물건의 마력 강도를 평가하는 안목은 있습니다 - 메디브가 수집한 다양한 장신구의 먼지를 털어야 할 때 아주 유용하죠.\n\n이 열쇠에는 카라잔 정문 주변에 주로 설치된 마법 결계를 통과할 수 있는 마법이 아직 남아 있습니다. 열쇠를 사용하려 할 때 위험이 없다고는 장담할 수 없지만, 성공한다면 장원이 실제로 어떤 상태인지 볼 수 있을 것입니다.",
    },
    [26660] = {
        ["T"] = "관리인의 부탁",
        ["O"] = "관리인의 열쇠를 사용하여 카라잔의 뒷문을 연 다음, 저승바람 고개의 아리덴의 야영지에 있는 아리덴 엘리스에게 돌아가십시오.",
        ["D"] =
        "정문은 당연히 침입자에 대비해 강력한 결계가 쳐져 있습니다. 하지만 강둑으로 내려가 강을 건너 장원 북동쪽 반대편에 있는 탑을 오르면 뒷문에 도달할 수 있습니다.\n\n뒷문에는 자체적인 방어막이 있지만, 이 열쇠에 남은 마력이라면 간신히 통과할 수 있을 거라 생각합니다. 다시 말하지만 제 생각이 틀렸을 수도 있습니다. 하지만 시도해 볼 의향이 있다면, 열쇠를 가져가서 뒷문을 열어보십시오. 부디 좋은 소식과 함께 곧 돌아오시기를 바랍니다.",
    },
    [26661] = {
        ["T"] = "비행장 공격 계획",
        ["O"] = "던 모로의 아이언포지 비행장 남쪽에 있는 켈시 스틸스파크에게 편지를 배달하십시오.",
        ["D"] =
        "이 트롤 양피지는 거친 그림으로 미루어 보아 아이언포지 비행장에 대한 일종의 공격 계획을 묘사한 것으로 보입니다. 공성 전차가 따라갈 수 없는 얼음 위로 산악경비대를 유인하는 계획 같지만, 잔달라어를 읽을 수 없어 확신할 수 없습니다. 이것을 켈시 스틸스파크에게 보여주는 것이 좋을 것입니다.",
    },
    [26662] = {
        ["T"] = "아이언포지 비행장",
        ["O"] = "비행편을 타고 아이언포지 비행장으로 간 다음, 동쪽 벙커 근처에 있는 기르다 선더브루와 대화하십시오.",
        ["D"] =
        "아이언포지 비행장에 대해 들어보셨나요, $R? 전 개인적으로 그리핀을 더 좋아하지만, 우리 드워프들은 비행 기계로도 유명하죠. 2차와 3차 대전쟁 이후 우리는 대부분의 비행 기계를 잃었지만, 마그니 국왕님께서 기계들을 다시 만들기 위해 거대한 비행장 건설을 명령하셨습니다.\n\n좀 길게 돌려 말했지만, 비행장까지 무료 비행을 원하십니까? 당신 같은 모험가라면 큰 도움이 될 거라 기대합니다!",
    },
    [26663] = {
        ["T"] = "아이언포지 비행장",
        ["O"] = "비행편을 타고 아이언포지 비행장으로 간 다음, 동쪽 벙커 근처에 있는 기르다 선더브루와 대화하십시오.",
        ["D"] =
        "아이언포지 비행장에 대해 들어보셨나요, $R? 전 개인적으로 그리핀을 더 좋아하지만, 우리 드워프들은 비행 기계로도 유명하죠. 2차와 3차 대전쟁 이후 우리는 대부분의 비행 기계를 잃었지만, 마그니 국왕님께서 기계들을 다시 만들기 위해 거대한 비행장 건설을 명령하셨습니다.\n\n좀 길게 돌려 말했지만, 비행장까지 무료 비행을 원하십니까? 당신 같은 모험가라면 큰 도움이 될 거라 기대합니다!",
    },
    [26664] = {
        ["T"] = "노니르 돕기",
        ["O"] = "비행장 남쪽에서 발견되는 던 모로 독수리에게서 두툼한 독수리 가슴살 8개를 수집하십시오.",
        ["D"] =
        "어이! 길 잃은 새 얼굴 같군, 모험을 즐기는 부류가 분명해. 일자리 찾고 있나?\n\n좋아! 식량 재고가 부족해지고 있는데 여기 친구들이 곧 밥 먹을 걸 기대하고 있거든. 괜찮은 $g신사:숙녀;라면 근처에 있는 새들 좀 잡아다 주겠나? 내 말은 독수리야. 두툼한 가슴살 몇 개면 충분해!",
    },
    [26665] = {
        ["T"] = "노니르 돕기",
        ["O"] = "비행장 남동쪽, 얼어붙은 호수 동쪽에 있는 늙은 얼음발톱 곰에게서 가죽 5장을 수집하십시오.",
        ["D"] =
        "자자, 달려가기 전에 자네에게 맡길 두 번째 임무가 있네. 걱정 마, 보수는 줄 테니. 자네 일생동안 곰 한두 마리쯤은 잡아본 $R처럼 보이는데, 내 말이 맞나? 여기 남동쪽에 그 짐승들 굴이 아주 크게 하나 있지. 내가 물건을 만들게 가죽 몇 장 좀 구해다 주겠나?",
    },
    [26666] = {
        ["T"] = "탑시 돕기",
        ["O"] = "비행장에 있는 스톰파이크 산악경비대 또는 던 모로 산악경비대원 6명에게 청소 키트를 사용하십시오.",
        ["D"] =
        "안녕하세요! 임무가 많이 밀렸는데 -- 좀 도와주실 수 있나요? 돌아다니면서 산악경비대의 총을 닦아야 하는데, 이 빌어먹을 추출기를 고치느라 바빠서요. 항상 고장 나 있는 것 같아요....\n\n총을 닦는 건 쉬워요, $N. 이 키트를 들고 돌아다니면서 서비스를 제공하기만 하면 돼요. 총을 여섯 자루만 닦아주셔도 제 시간을 엄청 절약할 수 있을 거예요!",
    },
    [26667] = {
        ["T"] = "탑시 돕기",
        ["O"] = "얼음 호수로 가서 중심핵 추출기를 설치하고 지키십시오. 중심핵 추출기는 허블 바디윙클과 대화하여 얻으십시오.",
        ["D"] =
        "당신이 자리를 비운 사이에 다행히도 이 기계를 고쳤어요. 저기, 한 번만 더 도와주실 수 있나요? 이번엔 돈을 드릴게요!\n\n이 기계는 얼음 중심핵 추출기라고 불러요. 남쪽 얼음 호수를 뚫고 들어가 얼음의 내용물을 연구하는 데 쓰죠. 기후에 관한 유용한 정보를 주기도 하고, 공성 전차가 얼음 위를 달릴 수 있을지 없을지 판단하게 해 줘요.\n\n그냥 아주 작은 섬 남쪽, 호수의 가장 깊은 곳으로 가져가서 사용하기만 하면 돼요. 야생동물들로부터 기계를 지켜야 할지도 몰라요!",
    },
    [26668] = {
        ["T"] = "위즐 돕기",
        ["O"] = "비행장 주변에 흩어진 쓰레기 12개를 수집하십시오.",
        ["D"] =
        "그래, 그래, 뭐야? 나 아주 바빠.\n\n아, 그냥 할 일 찾는 중이라고? 그렇게까지 심심한가 보군, 뭐 그렇다면 일거리를 한두 개 줄 수는 있지.\n\n알다시피, 이 비행장은 꽤 새것이라, 주변에 쓰레기가 많은 걸 볼 수 있을 거야. 쓰레기를 좀 주워오면 그중에 쓸만한 게 있는지 한 번 보자고.",
    },
    [26669] = {
        ["T"] = "위즐 돕기",
        ["O"] = "비행기 수리를 도우십시오.",
        ["D"] =
        "너의 다음 지루한 임무는 비행기가 활주로에 서 있는 이유를 알아내는 거야. 기계공학자 코발트가 같이 있는 걸 보니 뭔가 문제가 있는 게 틀림없어. 분명 도움이 필요할 텐데 난 스스로 시간을 낼 수가 없어. 나한테 돈을 주고 고치라는 이 비행기가 더 걱정이거든. 가서 코발트를 확인해 보고, 네 도움이 필요한지 알아보라고.\n\n재미있을 수도, 아닐 수도 있겠지. 난 신경 안 써.",
