    [26670] = {
        ["T"] = "아이언포지 비행장",
        ["O"] = "비행장을 둘러보고, 문제를 겪고 있는 3명을 도우십시오.",
        ["D"] =
        "훌륭해, 확실히 자네가 필요할 걸세. 이 비행장은 얼라이언스를 위해 공중 우위를 창출하려는 드워프와 노움이 함께 일하는 아름다운 결합의 산물이지.\n\n지금은 보시다시피 활주로에 비행기 한 대가 서 있어서 약간 지연되고 있어. 이곳저곳 돌아다니면 분명 자네를 필요로 하는 사람들을 찾을 수 있을 거야!",
