        ["D"] =
        "자네가 비행장에서 해준 훌륭한 일 덕분에 친구들의 기분이 아주 좋아졌어. 하지만 나한테 마지막 임무가 하나 더 있는데... 켈시 스틸스파크라는 노움에게 이 음식을 가져다줄 수 있겠나? 남서쪽에 있는 서리갈기트롤 마을을 감시하는 정찰병이야.\n\n그녀를 찾는 가장 좋은 방법은 얼음 호수의 서쪽을 끼고 도는 걸세.",
