        ["D"] =
        "나는 저 트롤들을 감시하면서 그들이 수상한 짓을 꾸미지 않는지 확인하러 이곳에 파견됐어요. 그런데, $C, 저들이 수상한 짓을 꾸미고 있어요.\n\n그들의 고위 사제인 리카리라는 트롤이 나를 발견하고 경비병들을 불러 날 공격했을 땐 정말 놀랐죠. 가까스로 탈출했지만, 놈들이 내 무릎을 심하게 쳤어요. 당신이 그곳에 가서 놈들의 숫자를 좀 쳐내야 하지만, 고위 사제와는 교전하지 마세요!",
