        ["D"] =
        "리크와타의 서리갈기트롤들이 비행장 공격을 준비하고 있어요. 그들은 마을 주변에 무기 은닉처를 저장해 두었는데, 전 그저 음식인 줄만 알았죠. 아니었어요 -- 상자엔 무기가 가득해요!\n\n여기, 임시 횃불을 하나 만들었어요. 그들의 화톳불이든, 아무 불이든 가져가서 저 무기들에 불을 지르세요!",
