    [26674] = {
        ["T"] = "고위 사제 리카리",
        ["O"] = "고위 사제 리카리를 처치하십시오.",
        ["D"] =
        "지금까지의 당신의 행동은 내 영혼을 고취시켰어요, $N. 우리가 쉽게 패배하지 않는다는 것을 트롤들에게 보여줘야 해요. 이를 달성하기 위한 우리의 최선의 기회는 고위 사제 리카리를 처치하는 거예요. 그러면 다음 지도자는 우리를 공격하는 데 관심이 줄어들기를 바랄 수 있죠.\n\n고위 사제를 과소평가하지 마세요. 그는 어둠의 힘을 다루거든요. 도움을 청할 수 있는 친구가 있기를 바라요.\n\n성공하면 비행장에 있는 함대사령관 스톤플린트에게 보고하세요. 그는 벙커 안에 있어요.",
    },
    [26675] = {
        ["T"] = "얼음 깨기",
        ["O"] = "그림나르 스롬윈이 서리갈기 소굴을 탈출하도록 도우십시오. 성공하면 카라노스의 그론 스롬윈에게 알리십시오.",
        ["D"] =
