        ["D"] =
        "우린 여기 카라노스에서 무기와 방어구를 많이 만들어 아제로스 곳곳에 배달해야 합니다. 내 형제, 그림나르가 그 배달 중 하나를 나갔는데 며칠 전에 돌아왔어야 했어요.\n\n누군가 형이 서리갈기 소굴을 지나가는 걸 봤다는데, 그 후로 아무도 형을 보지 못했습니다. 트롤들이 형을 붙잡았을까요? 제발 아니길 바라지만... 날 위해 확인해 주시겠소?",
