        ["D"] =
        "$N, 자네에게 긴급한 임무가 있네. 최근 우리 시민 몇 명이 감쪽같이 사라졌다네. 처음엔 대수롭지 않게 여겼지만 벌써 몇 주가 지났는데 아무도 돌아오지 않고 있어.\n\n실종이 시작된 이후로, 서리갈기트롤들이 여기서 정서쪽에 야영지를 몇 개 지었지. 그곳을 확인해서 우리 시민들을 찾을 수 있는지 알아보게.",
