        ["D"] =
        "우리는 이곳 놈리건 아래에서 고군분투하고 있지만, 빛의 치료적 사용에 관한 제 연구는 매우 성공적이었어요. 제가 조만간 이곳을 빠져나갈 가능성은 희박하니, 제 노트를 아이언포지의 수석 의료 책임자에게 가져다주시겠어요? 그녀의 이름은 밍크시 스프링치크이고 땜장이 마을에서 찾을 수 있어요.\n\n제발, $C, 서둘러 주세요.",
