    [26679] = {
        ["T"] = "우리를 따뜻하게",
        ["O"] = "겨울늑대 가죽 8장을 모아 카라노스의 여관주인 벨름에게 가져가십시오.",
        ["D"] =
        "공기 중의 한기가 느껴지십니까? 불 곁에 서 있는데도 수염이 얼어붙을 것 같은 기분이에요! 이 겨울은 해가 갈수록 추워지고 있다니까요.\n\n저기, 내게 필요한 건 망토를 지어 입을 짐승의 질 좋은 가죽이에요. 도와주실 수 있겠어요? 서쪽으로 가서 얼음 호수로 향한 다음 늑대 가죽을 좀 가져다주세요.",
