        ["D"] =
        "며칠 전 심한 눈보라가 쳐서 문이 부서졌어! 우리의 귀중한 산양들이 많이 도망쳤지! 산양들이 여기서 남쪽으로 도망치는 걸 봤지만 막을 수가 없었어. 팔 산양이 없는데 내가 어떻게 돈을 벌겠어?\n\n여기서 바로 남쪽에 있는 툰드리드 언덕으로 가서 내 산양들을 찾을 수 있는지 알아봐 줘. 산양들에게 다가가서 내 올가미를 사용해 목장까지 타고 돌아와! 영원히 감사할 거야!",
