        ["D"] =
        "다시 오셨군요. 숙련 타기를 배우러 오신 거 맞죠? 이전과 마찬가지로 해골 군마의 값은 지불되었지만, 훈련 비용은 직접 지불하셔야 합니다. 신속한 승마는 유감스럽게도 비용이 많이 듭니다.\n\n훈련을 마친 후 제 바로 뒤에 있는 자카리아 포스트와 대화하십시오. 그는 우리 군마의 판매를 관리합니다. 아직 자금이 없다면 언제든지 다시 오셔도 좋습니다.",
