        ["D"] =
        "다시 온 걸 환영하네! 더 빨리 타는 법을 배우러 왔군, 그렇지? 전과 마찬가지로 산양 값은 지불되었지만, 훈련 비용은 자네가 지불해야 해. 고급 훈련은 비싸거든, 미안하네.\n\n훈련을 마친 후 우리 바로 밖에 있는 베론 앰버스틸과 대화하게. 그는 이 목장을 운영하고 산양을 팔지. 아직 돈이 없다면 언제든지 다시 와도 되네.",
