        ["D"] =
        "그래서 해골 군마를 얻으러 오셨군요? 마침 당신을 기다리고 있었습니다! 어떤 신비한 후원자가 일반 군마 값을 지불하고 당신의 이름, $N(으)로 편지를 남겼습니다. 하지만 훈련 비용은 지불하지 않으셨으므로, 안타깝게도 그 비용은 부담하셔야 합니다.\n\n훈련을 받으신 후 제 바로 뒤에 있는 자카리아 포스트와 대화하십시오. 그는 우리 군마의 판매를 관리합니다. 아직 자금이 없으시다면 나중에 다시 오셔도 됩니다.",
