        ["D"] =
        "그래서 산양 타는 법을 배우러 왔나 보군? 마침 자네를 기다리고 있었다네! 어떤 신비한 후원자가 일반 산양 값을 지불하고 자네의 이름, $N(으)로 편지를 남겼지. 하지만 훈련 비용은 지불하지 않았으므로, 안타깝게도 그 비용은 자네에게 청구해야겠어.\n\n훈련을 받은 후 우리 바로 밖에 있는 베론 앰버스틸과 대화하게. 그는 이 목장을 운영하고 산양을 팔지. 아직 돈이 없다면 나중에 다시 와도 좋네.",
    },
    [26685] = {
