        ["O"] = "빈지 페더휘슬에게서 숙련 타기를 배운 다음, 던 모로에 있는 밀리 페더휘슬과 대화하여 기계타조를 얻으십시오.",
        ["D"] =
        "다시 온 걸 환영해요. 더 빨리 조종하는 법을 배우러 오신 거 맞죠? 이전과 마찬가지로 기계타조의 비용은 지불되었지만, 훈련 비용은 직접 지불하셔야 해요. 고급 조종술은 안타깝게도 비용이 많이 든답니다.\n\n훈련을 마친 후 제 바로 옆에 있는 여동생 밀리와 대화하세요. 그녀가 기계타조를 제작하고 판매한답니다. 아직 자금이 없으시다면 언제든지 다시 오셔도 좋아요.",
    },
    [26686] = {
        ["T"] = "기계타조 조종",
        ["O"] = "빈지 페더휘슬에게서 수습 타기를 배운 다음, 던 모로에 있는 밀리 페더휘슬과 대화하여 기계타조를 얻으십시오.",
        ["D"] =
        "그래서 기계타조 조종법을 배우러 오셨군요? 마침 당신을 기다리고 있었어요! 어떤 신비한 후원자가 수습생용 기계타조 값을 지불하고 당신의 이름, $N(으)로 편지를 남겼답니다. 하지만 훈련 비용은 지불하지 않았기 때문에, 안타깝게도 그 비용은 청구해야 해요.\n\n훈련을 받으신 후 제 바로 옆에 있는 여동생 밀리와 대화하세요. 그녀가 기계타조를 제작하고 판매한답니다. 아직 자금이 없으시다면 나중에 다시 오셔도 돼요.",
    },
    [26687] = {
        ["T"] = "그룸날을 위한 광석",
        ["O"] = "황금해안 채석장 광산에서 역학 광석 10개를 채광하여 광부 그룸날에게 돌아가십시오.",
        ["D"] =
        "저 아래 빌어먹을 트로그 놈들이 우리가 엄청난 발견을 눈앞에 두고 있을 때 채광 작업을 중단시켰어!\n\n트로그가 공격하는 동안 광산을 대피시키는데, 내 광부 중 한 명이 내게 급히 달려왔지. 광산 깊은 곳에서 특이한 금속의 새로운 광맥을 발견했다고 하더군. 안타깝게도 이 발견에 대한 후속 조치를 할 수가 없었어.\n\n넌 싸움에 꽤 소질이 있어 보이는군. 만약 광석을 찾아내는 감각과 트로그를 죽이고 싶은 욕망이 있다면, 그 안에서 찾은 특이한 광석을 내게 가져오는 대가로 후하게 보상하겠어.",
    },
    [26688] = {
        ["T"] = "역사 복원",
        ["O"] = "서리갈기 동굴에서 잃어버린 서판 8개를 회수하여 수습생 소렌에게 돌아가십시오.",
        ["D"] =
        "과거의 역사에 대해 뭔가를 파내려고 이곳에 왔는데, 빌어먹을 트롤 놈들이 내 발굴 장소인 바로 그 동굴을 점령해버렸어요!\n\n전 싸움꾼은 아니지만, 당신은 그 임무를 감당할 수 있어 보여요. 동굴에 들어가 흥미로울 만한 유물을 좀 가져다주시겠어요? 항아리, 뼈단지, 서판, 뭐 그런 것들 말이에요.\n\n후하게 보상해 드릴게요. 이곳을 발굴하라는 명령은 아이언포지에서 직접 내려온 거니까요!",
    },
    [26689] = {
        ["T"] = "선술집 대난투",
        ["O"] = "골드샤이어 남서쪽 길을 따라 마르디간을 찾으십시오.",
        ["D"] =
        "불과 몇 시간 전에 사자무리 여관에서 싸움을 말려야 했습니다. 사랑? 명예? 돈 때문이었을까요? 아닙니다. 물약 때문이었습니다. 단 하나의 빌어먹을 분노의 물약 말입니다.\n\n서로 떼어놓고 보니, 싸우던 사람 중 한 명이 동쪽에 있는 아조라의 탑 주인이자 대마법사 칼라인의 아들인 마르디간이었습니다.\n\n마르디간은 서쪽 시내 주둔지를 향해 마을 남서쪽 길을 따라 비틀거리며 걸어갔습니다. 저 대신 그를 확인해 주시겠습니까? 그가 크게 다치기라도 했다면, 그의 아버지가 이 지역 경비대에게 엄청난 압박을 가할 것입니다.",
    },
    [26690] = {
        ["T"] = "선술집 대난투",
        ["O"] = "엘윈 숲에서 붉은꽃잎풀 잎사귀 6개를 모아 사자무리 여관에 있는 윌리엄 페슬에게 가져가십시오.",
        ["D"] =
        "아버지께서 사자무리 여관의 윌리엄 페슬에게 분노의 물약을 만들어 달라고 요청하러 저를 보내셨어요. 물약을 받고 나서 생각했죠, 에일 한 잔 하는 게 어때서? 하지만 머그잔을 다 비우기도 전에 한 번도 본 적 없는 불한당의 습격을 받았어요!\n\n상황은 순식간에 험악해졌고, 우리가 칼을 뽑으려는 순간 치안대장 더그한이 끼어들었죠. 그 소란 속에서 그 불한당이 물약을 훔쳐갔어요!\n\n과거에도 아버지의 부탁을 몇 번 망친 적이 있다는 건 인정해요. 만약 그 물약이 없다면, 아버지는 저와 제 개를 쫓아내실 게 분명해요.\n\n치안대장 더그한이 저를 도우라고 당신을 보냈다면, 제발 붉은꽃잎풀 잎사귀를 모아서 윌리엄 페슬에게 가져다주세요. 그래야 그가 제게 새 물약을 만들어 줄 수 있으니까요.",
    },
    [26691] = {
        ["T"] = "선술집 대난투",
        ["O"] = "골드샤이어 남서쪽의 마르디간에게 돌아가십시오.",
        ["D"] =
        "마르디간이 저렇게 소란을 피운다면 더 이상 그와 거래하고 싶지 않습니다. 사자무리 여관은 아늑하고 훌륭한 장소인데, 그가 올 때마다 또 다른 싸움이 벌어진다니까요!\n\n물약과 영약이 필요하다면 이제부터 스톰윈드로 가라고 하세요. 이제 그는 루미어 양의 문제라고 전해주세요!",
    },
    [26692] = {
        ["T"] = "선술집 대난투",
        ["O"] = "거울 호수 위 천둥 폭포에 있는 마르디간의 집 근처에서 그와 만나십시오.",
        ["D"] =
        "이건 내가 필요한 게 아닌--\n\n<마르디간이 먼 곳에서 무언가를 발견하고 갑자기 말을 멈춥니다.>\n\n저거 연기야? 언덕에서? 그럴 리가... 집으로 귀환해야 해! 제발 천둥 폭포에 있는 내 집에서 만나줘요!",
    },
    [26693] = {
        ["T"] = "선술집 대난투",
        ["O"] = "마르디간의 집에서 단서를 확인하십시오.",
        ["D"] =
        "<프리츠의 시체에서 마르디간의 집 안으로 핏자국이 길게 이어져 있습니다. 어쩌면 안에서 단서를 찾을 수 있을지도 모릅니다.>",
    },
    [26694] = {
        ["T"] = "선술집 대난투",
        ["O"] = "사자무리 여관 뒤에 있는 남자와 마르디간의 집 화재에 대해 대적하십시오.",
        ["D"] =
        "<쪽지를 손에 쥔 마르디간이 욕을 퍼부으며 얼굴이 붉어진 채 사자무리 여관 쪽으로 전력 질주하는 것을 봅니다.>\n\n<마르디간의 집을 파괴하고 그의 개를 죽인 남자를 대적하기 위해 그를 따라가야 할 것 같습니다.>",
    },
    [26695] = {
        ["T"] = "선술집 대난투",
        ["O"] = "아조라의 탑에 있는 테오크리투스에게 마르디간의 상황을 알리십시오.",
        ["D"] =
        "정말로 마르디간을 돕고 싶다면, 당장 나를 도와라. 마르디간의 아버지에게 아들의 범죄를 알려야 하지만, 그와 연락할 수 있는 사람은 골드샤이어 동쪽 길에 있는 아조라의 탑의 테오크리투스뿐이다. 조심해라; 그 탑은 비전 마력의 강력한 중심지이고 그곳에는 무언가 이상한 점이 있다....",
    },
    [26696] = {
        ["T"] = "아조라의 손",
        ["O"] = "서부 몰락지대 중앙의 감시의 언덕에서 칼라인을 찾으십시오.",
        ["D"] =
        "마르디간의 아버지는 나의 동료인 대마법사 칼라인일세. 나는 칼라인을 서부 몰락지대로 보내 매우 중요한 유물인 아조라의 손을 회수하기를 바랐지.\n\n아조라의 손은 매우 강력한 무기로, 아주, 아주 우려스러운 집단의 관심을 끌었어. 나는 타노스라는 강력한 마법사에게 그것을 숨기라고 주었지만, 타노스는 서부 몰락지대로 떠난 후 실종되었네.\n\n칼라인을 찾고 싶다면 감시의 언덕으로 가보게. 부디 그가 타노스의 흔적을 쫓고 있기를 바라. 그가 자네의 일을 도울 수 있도록 그의 임무를 도와주게.",
    },
    [26697] = {
        ["T"] = "아조라의 손",
        ["O"] = "해당 지역의 데피아즈단 노상강도와 데피아즈단 밀수업자에게서 타노스의 위치에 대한 단서 3개를 찾으십시오.",
        ["D"] =
        "테오크리투스가 말했듯이, 난 타노스라는 사람을 찾으러 이곳에 파견되었지만, 찾은 거라곤 바람에 떠도는 소문뿐이네.\n\n그가 이곳을 방문했다는 건 알지만, 실종되기 전에 자신의 일에 대해 누구에게도 말하지 않았더군.\n\n스타우트맨틀은 그가 이 지역 데피아즈단에 대해 묻고 다녔다고 말해줬네. 그들이 그를 찾는 열쇠일지도 몰라. 마르디간의 일에 내 도움이 필요하다면, 내가 여기서 조사를 계속하는 동안 자네가 데피아즈단을 샅샅이 조사해 주어야 하네.",
    },
    [26698] = {
        ["T"] = "아조라의 손",
        ["O"] = "감시의 언덕 여관에 있는 레빌 코스트와 대화하십시오.",
        ["D"] =
        "자네가 외출한 동안 민병대원들과 꽤 친해졌네. 그들이 마음을 열고 자신들이 가진 적은 정보를 제공해 주었어.\n\n스타우트맨틀은 타노스가 데피아즈단에 대해 더 알고 싶어 했고, 그 시간의 대부분을 레빌 코스트라는 남자와 이야기하는 데 보냈다고 알려주더군. 레빌 코스트는 교회에서 일하는 덩치인데, 우리가 과거에 거래한 적이 있지.\n\n우린 썩 좋게 헤어지진 않았어. 코스트는 여관에 틀어박혀 있는데, 나를 알아보면 마을을 뜰 거라고 생각하네. 자네가 가서 그가 무슨 말을 하는지 들어보는 게 어때?",
    },
    [26699] = {
        ["T"] = "아조라의 손",
        ["O"] = "해당 지역의 데피아즈단 약탈자와 데피아즈단 덫사냥꾼에게서 타노스의 위치에 대한 단서를 3개 더 찾으십시오.",
        ["D"] =
        "타노스? 머리가 희끗희끗한 친구? 네, 여기 있었죠. 데피아즈단에 대해 횡설수설하며 그들의 작전 기지 중 한 곳을 찾고 있었어요.\n\n그 당시 그는 몹시 흥분해 보였어요. 저와 악수조차 하지 않으려 했죠.\n\n그가 어디로 갔는지는 전혀 모르지만, 붉은 복면을 쓴 벼락부자들과 싸우고 싶어 했어요. 그들이 그를 사냥하고 있었다고요? 그들에게서 무엇을 알아냈나요?\n\n당신의 노트를 보니 절반의 편지가 빠져 있군요. 사다리 위쪽에 있고 더 강한 놈들을 노려보세요; 당신이 필요한 걸 틀림없이 찾을 수 있을 겁니다.",
    },
    [26700] = {
        ["T"] = "아조라의 손",
        ["O"] = "데피아즈단 단서를 사용하여 서부 몰락지대에서 타노스를 찾으십시오.",
        ["D"] =
        "나는 흑기사라고 알려진 집단이 소유하고 있다고 여겨지는 위대한 유물을 찾기 위해 서부 몰락지대로 오라는 명령을 받았다네.\n\n기사단은 전설적인 존재야 -- 악하고 더러운 존재들로, 카라잔에 있는 그들의 어둠의 주인을 위해 위대한 힘을 지닌 물건을 찾아 땅을 배회하지.\n\n타노스가 가진 물건은 내가 찾는 유물과 같거나 그 이상의 힘을 지녔다고 믿네.\n\n기사단이 그가 그것을 가지고 있다는 것을 눈치챈다면 그는 큰 위험에 처하게 돼. 빨리 그를 찾아야 해! 칼라인에게 이 상황을 알리겠네.",
    },
    [26701] = {
        ["T"] = "아조라의 손",
        ["O"] = "타노스가 황금해안 채석장을 소탕하여 은신처를 만들도록 도우십시오.",
        ["D"] =
        "조심해! 난 이걸 제어할 수 없어! 테오크리투스가 나에게 이 저주받은 장갑을 주면서 서부 몰락지대인 이곳에 숨기라고 했어.\n\n아조라의 탑에서 멀어지자, 난 이 장갑을 껴야만 할 것 같은 충동을 느꼈어. 장갑은 마치 두 번째 피부처럼 내 손에 달라붙었고 다시는 뺄 수가 없었지! 이제 내가 두려움을 느낄 때마다 장갑에서 날것의 비전 마력이 뿜어져 나와.\n\n난 숨어야 해, $C! 아무도 내가 어디 있는지 알아선 안 돼.\n\n앞에 있는 광산이 나의 새 보금자리가 될 거야. 이 땅을 공포에 떨게 하는 데피아즈단이 광산을 점령했기 때문에 마을 사람들은 가까이 오지 않지. 장갑을 이용하면, 난 놈들을 쉽게 소탕할 수 있어. 데피아즈단이 사라진 걸 꽤 오랫동안 아무도 눈치채지 못할 거야.",
    },
    [26702] = {
        ["T"] = "아조라의 손",
        ["O"] = "엘윈 숲의 아조라의 탑에 있는 테오크리투스에게 돌아가십시오.",
        ["D"] =
        "우린 임무에 실패했네... 그 기사들이 지금 가진 힘은 나를 두렵게 하는군.\n\n우리는 테오크리투스에게 돌아가서 무슨 일이 있었는지 말해야 해.\n\n이 혼란을 바로잡기 위해 우리가 무엇을 할 수 있을지 전혀 모르겠네.",
    },
    [26703] = {
        ["T"] = "아조라의 손",
        ["O"] = "칼라인에게 마르디간에게 무슨 일이 있었는지 알리십시오.",
        ["D"] =
        "칼라인은 곧 도착할 거야. 그를 아는데, 짐을 챙기자마자 순간이동 주문을 시전할 게 뻔해.\n\n그가 도착하면 그의 아들에게 일어난 끔찍한 일의 심각성을 이해시키고, 자네와 그를 마르디간이 간 곳으로 보내야 해.\n\n아조라의 손은 당분간 잃어버렸지만, 적어도 우리는 마르디간을 도우려 노력할 수 있네.",
    },
    [26704] = {
        ["T"] = "밤의 기수들",
        ["O"] = "다크샤이어 경비병들에게 미스터리한 듀오에 대한 정보를 물어보십시오.",
        ["D"] =
        "네 얼굴 표정의 의미를 안다. 아무리 냉혹한 $g남자:여자;라도... 기사단에 대해 알게 되면 그런 표정을 짓지. 그래, 불과 두 시간 전만 해도 그들이 이 근처에서 목격됐었지.\n\n최근 사제와 동행한 불안정한 마법사 한 명이 바로 그 표정을 하고 마을을 전력 질주했어. 그들은 누군가를 찾고 있었고, 몇몇 마을 사람들에게 정보를 요구하더니, 다시 떠나버렸지.\n\n난 그들이 어느 방향으로 떠났는지 보지 못했어. 내 감시자들에게 가서 그 두 사람이 어느 쪽으로 갔는지 보았는지 물어봐.",
    },
    [26705] = {
        ["T"] = "밤의 기수들",
        ["O"] = "다크샤이어 남쪽에서 레빌의 야영지를 찾으십시오.",
        ["D"] =
        "글쎄요, 적어도 이름 하나는 얻었군요: 레빌. 그게 당신에게 무슨 의미가 있나요?\n\n만난 적이 있다고요? 그 두 광인이 당신을 찾고 있었단 말인가요? 이제 왜 당신들 세 명 모두 그런 귀신에 홀린 듯한 표정을 짓고 있는지 설명이 되네요....\n\n마을 남쪽으로 가서 그들을 따라잡아 보세요. 하루가 넘게 지났으니 -- 틀림없이 가까운 곳에 야영을 했을 겁니다.",
    },
    [26706] = {
        ["T"] = "밤의 기수들",
        ["O"] = "다크샤이어 북쪽의 미스트맨틀 장원을 조사하십시오.",
        ["D"] =
        "레빌의 일지: 247일차 - 파트 2\n\n칼라인은 흑기사단이 최근 미스트맨틀 장원에서 목격되었다고 말했다, 우리 둘 다 이유는 모르지만. 중요한 것은 그 장원은 보통 언데드가 득실거리는데, 근처에서 늑대인간이 새롭게 목격되었다는 점이다.\n\n우리는 곧 떠날 것이다. 그가 절실히 필요로 하는 안식을 찾아줄 수 있기를 바란다.",
    },
    [26707] = {
        ["T"] = "밤의 기수들",
        ["O"] = "빛의 대성당에 있는 수사 대로우에게 주입된 은괴를 구하고, 스톰윈드 항구에 있는 로버트 다비에게 고품질 참나무를 구하십시오.",
        ["D"] =
        "이 완고한 늑대인간을 통과하려면 우리는 어둠으로 향해야 하네 - 거의 논의되지 않는 빛의 반대편 말이야.\n\n나는 이런 순간을 준비해 왔고, 그 계획을 정의로운 대의를 위해 사용할 때가 왔어. 칼라인은 좋은 사람이야. 그는 아들이 어디에 있는지 알 권리가 있네.\n\n먼저, 스톰윈드의 항구 구역으로 가서 항만관리인 아가일과 대화하게. 그는 어떤... 친구에게서 온 특별한 은이 든 궤짝을 가지고 있을 걸세. 그곳에 있는 동안 조선소의 조선공 로버트 다비에게 연락하게. 약간의 참나무가 필요한데 그는 내가 목숨을 구해준 술집 난투극 이후로 내게 빚을 지고 있거든.\n\n은을 얻게 되면 그것을 지인인 수사 대로우에게 가져가야 하네. 그는 대성당 도서관에서 빛의 대성당의 가장 귀중한 책들을 지키는 임무를 맡고 있지.\n\n도서관은 대성당 바로 아래에 있을 걸세. 그에게 은을 주면 그가 축복을 내려줄 거야.\n\n주입된 은괴와 고품질 참나무를 모두 내게 가져오게.",
    },
    [26708] = {
        ["T"] = "밤의 기수들",
        ["O"] = "포획한 늑대인간을 심문하십시오.",
        ["D"] =
        "레빌이 내게 계획을 말해주었고, 우리가 필요한 정보를 얻을 수 있는 도구도 주었네. 하지만 막상 여기에 오니, 난... 난 이걸 할 수 없을 것 같아. 자네에게 나를 대신해 주기를 간청하네, $N. 제발! 난 마르디간이 어디로 갔는지, 그가 무사한지 알아야 해.",
    },
    [26709] = {
        ["T"] = "밤의 기수들",
        ["O"] = "다크샤이어 남쪽으로 여행하여 롤랜드 광산에 도착하십시오. 늑대인간들을 뚫고 길을 만들며 안에서 칼라인과 레빌을 기다리십시오.",
        ["D"] =
        "내 아들이 롤랜드 광산에 있다면 너무 늦기 전에 거기로 가야 하네. 레빌과 내가 이 늑대인간의 시체를 처리하고 그곳에서 만나지. 이 지역을 방어하는 늑대인간들을 뚫고 길을 확보해 놓게, 그러면 우리가 자네를 찾으러 가겠네.\n\n마르디간이 무사히 거기에 있기를 바라야 하지만, 최악의 사태가 두렵네. 제발 서둘러 주게, $n.",
    },
    [26710] = {
        ["T"] = "밤의 기수들",
        ["O"] = "칼라인과 레빌이 도착할 때까지 롤랜드 광산 안에서 마르디간을 방어하십시오.",
        ["D"] =
        "이 무리의 우두머리가 곧 돌아올 거야. 놈은 사악하게 생긴 낫 같은 걸로 날 자신들과 같은 존재로 만들려 했어. 놈이 내게 그걸 사용했을 때, 그것은 불타고 내 마음을 지졌지만, 난 저항했어. 놈은 우리가 \"그 장소\"로 가야 한다며 그 일을 끝내려고 날 여기로 데려왔지.\n\n난 힘을 모아야 해, 그래야 여기서 나가서 아버지를 찾을 수 있어, 그 우두머리가 돌아와 우리 모두를 변화시키기 전에!",
    },
    [26711] = {
        ["T"] = "죽음 속의 삶",
        ["O"] = "그늘숲 주변에서 밝은숲 꽃(Brightwood Blooms) 8개를 수집하십시오.",
        ["D"] =
        "이 유령이 나오는 땅은 메디브의 타락이 휩쓸기 전에는 밝은숲으로 알려졌었고, 그 타락은 이곳을 우리가 지금 아는 그늘숲으로 바꾸어 놓았습니다.\n\n이 땅은 너무 더럽혀져서 많은 이들이 어떤 생명체도 이곳에서 자랄 수 없다고 믿습니다. 밖에 있는 호박들이 보이십니까? 속까지 썩어버렸죠.\n\n하지만 저는 엘룬의 도움과 자연의 치유력이 살짝 더해진다면 희망이 있다고 생각합니다.\n\n이 땅을 치유하기 위해 제게는 우선 과거의 잔재가 필요합니다. 그늘숲 곳곳에는 아직 밝은숲 꽃이라는 고대 약초가 자라고 있습니다. 그것을 8개 수집해 주시면 제 다음 단계의 실험에 사용할 수 있습니다.",
    },
    [26712] = {
        ["T"] = "죽음 속의 삶",
        ["O"] = "그늘숲 전역의 언데드에게서 신선한 뼛가루를 모으십시오.",
        ["D"] =
        "제 실험의 다음 핵심 재료는 가장 끔찍한 것을 요구합니다. 건강과 생명의 반대는 죽음과 부패이며, 이 숲은 그 묘사에 맞는 많은 것들의 본거지입니다.\n\n묘지로 가서 그곳을 배회하는 언데드 생명체들로부터 갓 갈아낸 뼛가루를 모아오십시오. 5개만 가져다주십시오, $n.",
    },
    [26713] = {
        ["T"] = "죽음 속의 삶",
        ["O"] = "황혼의 숲을 찾아 달샘에서 유리병을 채우십시오.",
        ["D"] =
        "그늘숲 심장부 깊은 곳에는 이 타락 속에서도 생명이 번성하는 무척 아름다운 곳이 있습니다. 황혼의 숲이라고 불리는 곳이죠. 그곳에서 제 조상들이 남긴 달샘을 찾을 수 있을 겁니다. 저는 이것이 그늘숲을 구할 마지막 열쇠라고 믿습니다.\n\n다크샤이어에서 남쪽으로 나가 가시덤불 골짜기로 이어지는 갈림길 직전까지 가십시오. 거기서 북쪽으로 향하면 숲으로 들어가는 길을 찾을 수 있을 것입니다. 수집한 재료들을 챙겨가서 달샘의 물로 이 유리병을 채운 다음, 제게 가져오십시오.",
    },
    [26714] = {
        ["T"] = "시녀의 몰락",
        ["O"] = "다크샤이어 안에서 넬의 옛 연인 패린을 찾으십시오.",
        ["D"] =
        "내 사랑, 패린을 못 본 지 몇 주가 지났어요. 그의 얼굴을 다시 본다면 더할 나위 없이 기쁘겠지만, 그는 한 달째 찾아오지 않았고, 이제 미스트맨틀 장원은 언데드의 손에 넘어갔어요.\n\n전 스탈반 영주님을 모시기 위해 이곳에 남았지만, 그분은 변하고 있어요. 영주님은 숨기려 하시지만, 그분의 뼈에서 살점이 떨어져 나가는 걸 똑똑히 봤어요.\n\n스탈반 영주님은 바깥 세상이 혼돈에 빠졌고 내 패린도 그 혼돈 속에 쓰러졌음이 틀림없다고 하셔요. 그렇지 않고서야 그가 돌아오지 않을 이유가 없다는 거죠?\n\n그가 없이는 살 수 없어요. 안녕, 내 사랑. 빛이여, 제발, 절 용서하소서.",
    },
    [26715] = {
        ["T"] = "시녀의 몰락",
        ["O"] = "진홍 까마귀 선술집에서 남은 빵 약간과 밝은숲 백포도주 한 통을 훔치십시오.",
        ["D"] =
        "그녀의 슬픔이 그녀를 밴시로 만들었다니 믿을 수 없어요. 그녀의 영혼을 자유롭게 해줘야 해요! 생각 좀 해볼게요...\n\n좋은 생각이 났어요! 그녀를 유인해서 안식에 들게 해야 해요. 우리가 가장 좋아하던 일은 건초밭에서 소풍을 즐기는 거였으니, 다시 소풍을 제안하면 그녀를 유혹할 수 있지 않을까요?\n\n전 부자가 아니지만 절박한 상황에는 절박한 조치가 필요하죠. 진홍 까마귀 선술집에서 남은 빵 약간과 그녀가 가장 좋아하던 와인인 밝은숲 백포도주 한 통을 훔쳐 주실 수 있나요?",
    },
    [26716] = {
        ["T"] = "시녀의 몰락",
        ["O"] = "다크샤이어 서쪽의 새끼 검은 랩터(Young Black Ravager)에게서 부드러운 늑대 털 6개를 수집하십시오.",
        ["D"] =
        "우리가 소풍을 갈 때 가끔 담요 가져가는 걸 잊어버리곤 했는데, 그러면 그녀가 절 꾸짖었죠. 이제 그런 일이 다시는 일어나지 않을 텐데도 그녀의 꾸지람이 그리워요.\n\n<패린이 애틋한 미소를 지으며 미소 짓습니다.>\n\n이 계획이 성공하려면 모든 세부 사항이 완벽해야 하지만, 지금 제겐 사용할 담요가 없어요. 빨리 새로 하나 만들어야 해요.\n\n다크샤이어 외곽의 새끼 검은 랩터를 찾아 그들의 털을 가져다주세요; 그걸로 멋진 담요를 만들 수 있을 거예요.",
    },
    [26717] = {
        ["T"] = "시녀의 몰락",
        ["O"] = "다크샤이어 서쪽의 건초밭에 준비된 소풍 세트를 놓고, 넬 옥스본의 영혼이 도착하면 그녀를 안식에 들게 하십시오.",
        ["D"] =
        "드디어 내 넬의 영혼을 안식에 들게 할 수 있어요. 이 저주받은 삶 이후에 무엇이 오든 그녀가 평안하기를 기도합니다.\n\n당신이 쓸 수 있도록 담요와 소풍 세트를 준비해 두었어요. 우리가 만나곤 했던 건초밭으로 가져가서 그걸로 그녀의 영혼을 유인해 낸 다음 처치하세요. 해야만 하는 일이지만, 내 눈으로 직접 볼 수는 없어요.",
    },
    [26718] = {
        ["T"] = "죽음이 우리를 갈라놓을 때까지",
        ["O"] = "피그미 맹독그물거미(Pygmy Venom Web Spiders)에게서 반짝이는 거미줄 10개와 그늘숲 북쪽 강에서 온전한 진주 7개를 모으십시오.",
        ["D"] =
        "잠깐! 무기를 거두세요! 제발! 당신의 도움이 필요해요.\n\n금발 머리 얼간이 아서스 왕자가 로데론을 파괴하기 전, 저와 페이 언더힐(Faye Underhill) 양은 더할 나위 없는 행복 속에 단둘이 살고 있었죠. 스컬지가 도착했을 때 난 그녀를 멀리 보냈고 글쎄요... 제가 어떻게 변했는지 보이시죠.\n\n그녀가 다크샤이어로 돌아왔고, 전 정말 절실하게 그녀와 이야기하고 우리의 사랑을 이어나가고 싶어요. 하지만 이런 모습으론 안 돼요. 그녀가 절 알아보기나 할까요?\n\n하지만 제게 계획이 있어요! 그녀가 좋아할 만한 선물을 만들고 제 자신을 최대한 단정하게 꾸밀 거예요. 그녀가 날 알아보면 내 품에 뛰어들 거란 걸 알아요.\n\n다크샤이어 북동쪽 피그미 맹독그물거미의 최고급 거미줄이 필요하지만, 이런 모습으론 헛간을 떠날 수가 없어요. 제가 필요한 걸 구해주실 수 있나요?\n\n그곳에 계신 동안 그늘숲과 엘윈 숲 사이의 강 깊은 곳으로 잠수해 보세요. 가장 완벽한 진주를 품고 있는 조개를 찾을 수 있을 거예요. 이 재료들을 합치면 놀랍도록 아름다운 목걸이를 만들 수 있어요.",
    },
    [26719] = {
        ["T"] = "죽음이 우리를 갈라놓을 때까지",
        ["O"] = "스톰윈드 운하 향기로운 화원에서 붉은 장미를 구하십시오.",
        ["D"] =
        "이 목걸이는 내 페이에게 완벽해요. 그녀는 항상 진주에 끌렸고, 당신이 짝이 잘 맞는 진주를 가져다주었군요! 하지만, 안타깝게도 그녀가 내 썩어가는 살점 냄새를 멀리서부터 맡는다면 진주는 아무 소용이 없을 거예요.\n\n로데론에서는 재미 삼아 우리만의 향수를 만들곤 했죠. 그녀는 우리가 만든 장미 향수가 저에게 가장 잘 어울린다고 항상 말했어요. 그 향을 재현할 수 있다면, 그녀는 날 단번에 알아볼 거예요.\n\n이 근처에서 제가 아는 유일한 꽃집은 스톰윈드 운하 지구에 있는 검프 부부의 화원뿐이에요. 그들에게 가서 죽음의 냄새를 없애는 데 쓸 수 있는 싱싱한 붉은 장미를 가져다주세요.",
    },
    [26720] = {
        ["T"] = "죽음이 우리를 갈라놓을 때까지",
        ["O"] = "다크샤이어 외곽, 버려진 헛간 뒤에 있는 페이의 집 안에 페이에게 쓰는 잭의 편지를 두십시오.",
        ["D"] =
        "그녀의 애정을 얻기 위한 제 계획의 마지막 단계는 바로 이것입니다: 우리만의 비밀 애칭을 사용하여 그녀에게 쓴 편지. 틀림없이 이 편지가 그녀를 내게로 이끌 거예요. 이걸 가져가서 그녀의 집에 놔주실 수 있나요? 감시자에게 들킬 위험을 감수할 순 없어요. 이 헛간 바로 뒤에서 그녀의 집을 찾을 수 있을 거예요.",
    },
    [26721] = {
        ["T"] = "죽음이 우리를 갈라놓을 때까지",
        ["O"] = "다크샤이어 외곽의 헛간에서 페이 언더힐이 도착하기를 기다리십시오.",
        ["D"] =
        "편지를 두셨군요? 정말 흥분되네요. 그녀가 당장이라도 여기에 올 거라 확신해요. 향수도 뿌렸고, 이 선물이 그녀의 마음을 얻는 데 도움이 될 거란 걸 알아요. 당신이 우리를 어떻게 만나게 해주었는지 설명하면, 그녀도 당신을 알게 되어 기뻐할 거예요.",
    },
    [26722] = {
        ["T"] = "죽음이 우리를 갈라놓을 때까지",
        ["O"] = "잭 아처를 고통에서 해방시켜 주고 그를 처치하십시오.",
        ["D"] =
        "이대로는 살 수 없어요. 더 이상은. 그녀 없이는. 그녀는 내 죽은 삶에 목적을 주었는데, 이제 내겐 아무것도 없어요.\n\n제발, $n. 포세이큰이란 이유로 광장의 경비병들에게 사지가 찢기기 전에, 날 신속히 끝내주세요.",
    },
    [26723] = {
        ["T"] = "현상 수배: 역병 걸린 비틀걸음",
        ["O"] = "다크샤이어 북쪽 강을 따라 잠복해 있는 역병 걸린 비틀걸음(Plagued Shambler)을 처치하십시오.",
        ["D"] =
        "다크샤이어 북쪽 강을 따라 오직 밤에만 순찰하며, 지나는 곳마다 죽음과 파괴의 흔적을 남기는 역병 걸린 사악한 야수가 목격되었습니다.\n\n용감한 마음과 굳건한 실력을 갖춘 모험가라면, 놈이 다크샤이어와 무역로에 너무 가까이 다가오기 전에 제거해 주십시오.",
    },
    [26724] = {
        ["T"] = "검은 마력",
        ["O"] = "동부 역병지대에서 어둠의 이교도(Dark Adept)와 어둠마법사에게서 검은 마력 고서 3권을 모은 다음, 아이언포지의 버려진 동굴에 있는 주발 콥스시커에게 돌아가십시오.",
        ["D"] =
        "저주받은 자들의 교단은 다양한 금지된 마법과 온갖 종류의 어둠의 마술을 마법사들에게 훈련시킨다. 비록 그들의 전문 분야가 강령술이긴 하지만, 우리 흑마법사들도 그들의 연구에서 한두 가지 배울 점이 있지.\n\n동부 역병지대로 가서 교단의 어둠의 이교도와 어둠마법사를 처치해라. 그들의 요새인 맹독의 둥지와 곰팡이 계곡에서 놈들을 찾을 수 있을 것이다. 내가 그들의 기술을 연구할 수 있도록 그들의 주문서 세 권을 모아라.",
    },
    [26725] = {
        ["T"] = "검은 마력",
        ["O"] = "동부 역병지대에서 어둠의 이교도와 어둠마법사에게서 검은 마력 고서 3권을 모은 다음, 오그리마의 어둠의 틈에 있는 쿠르굴에게 돌아가십시오.",
        ["D"] =
        "저주받은 자들의 교단은 다양한 금지된 마법과 온갖 종류의 어둠의 마술을 마법사들에게 훈련시킨다. 비록 그들의 전문 분야가 강령술이긴 하지만, 우리 흑마법사들도 그들의 연구에서 한두 가지 배울 점이 있지.\n\n동부 역병지대로 가서 교단의 어둠의 이교도와 어둠마법사를 처치해라. 그들의 요새인 맹독의 둥지와 곰팡이 계곡에서 놈들을 찾을 수 있을 것이다. 내가 그들의 기술을 연구할 수 있도록 그들의 주문서 세 권을 모아라.",
    },
    [26726] = {
        ["T"] = "헌신의 메아리",
        ["O"] = "역병숲을 수색하여 길 잃은 엘리드린을 찾고 그를 안식에 들게 하십시오.",
        ["D"] =
        "제가 보이시나요? 제 목소리가 들리시나요? 당신의 영혼이 산 자의 것임을 느낄 수 있어요. 아마 당신이 제 기도에 대한 답일지도 모르겠네요.\n\n저는 한때 쿠엘탈라스 소속이었던 세라핀입니다. 지금은 이 황폐한 땅에서 잊혀진 메아리일 뿐이죠. 끝나지 않은 임무에 사로잡혀 제 영혼은 이곳을 맴돌고 있어요. 저주받은 자들은 여전히 불안해하고… 살아있는 자들은 너무 빨리 잊어버리죠.\n\n제 사랑 —- 엘리드린 —- 은 스컬지의 첫 공격 때 쓰러졌어요. 그의 영혼은 저처럼 묶여 있지만, 그는 분노와 슬픔에 얽매여 있죠. 제게 평안을 주시려거든, 먼저 그를 해방시켜 주셔야 해요. 그는 우리의 마지막 전투가 벌어졌던 폐허 근처를 배회하며, 자신의 실패로 고통받고 있어요. 근처 역병숲에서 그를 찾을 수 있을 거예요.",
    },
    [26727] = {
        ["T"] = "헌신의 메아리",
        ["O"] = "곰팡이 계곡에 있는 사악한 힐두르(Hildur the Vile)에게서 세라핀의 로켓을 회수하십시오.",
        ["D"] =
        "엘리드린에 대한 제 유대감은 절 이 차원에 묶어두는 이유의 일부일 뿐이에요. 제 필멸자의 유해는 땅으로 돌아가기도 전에 약탈당했거든요.\n\n엘리드린은 우리가 맺어진 지 5주년이 되던 날 제게 로켓을 주었어요. 그 로켓은 저주받은 자들의 교단이 소유하고 있죠. 여기서 남쪽에 있는 곰팡이 계곡에서 그것의 기운을 느낄 수 있어요.\n\n제 시체를 약탈한 도굴꾼은 생전에 힐두르로 알려졌던 자예요 -- 우리 집을 지나가던 떠돌이 상인이었죠. 그가 지금은 어떤 존재가 되었는지 모르지만, 더 이상 상인이 아닌 것만은 확실해요.",
    },
    [26728] = {
        ["T"] = "현장 학습",
        ["O"] = "교수 라스무센을 처치하고 우등생(Honors Student)들에게서 연구 노트 4개를 모으십시오.",
        ["D"] =
        "제발, 스칼로맨스와의 관계로 인해 저를 오해하지 마십시오, $C. 제 마음은 은빛 여명회를 섬기고 있습니다. 저는 저주받은 자들의 교단에 잠입하여 그들의 계획을 좌절시킬 기회를 찾으며 많은 날을 보냈습니다. 당신의 도착은 제가 위장을 유지하면서도 그들의 일에 간섭할 수 있는 기회를 제공합니다.\n\n스칼로맨스의 우등생 그룹이 모종의 연구를 수행하기 위해 동부 역병지대로 현장 학습을 나왔습니다. 그들의 교사인 라스무센 교수는 저를 의심하여 그들이 여기서 무엇을 하고 있는지 말해주지 않습니다.\n\n그와 그의 사악한 학생들을 처치하고 그들의 노트를 회수해 주십시오. 어쩌면 그들이 이곳에 있는 목적을 알아낼 수 있을지도 모릅니다.",
    },
    [26729] = {
        ["T"] = "현장 학습",
        ["O"] = "코린 삼거리에서 명예교수 칠본을 찾아 처치하고 그의 일지를 회수하십시오.",
        ["D"] =
        "이 이름 모를 전직 교사는 이제 칠본이라고 불리는 것 같습니다. 그가 조사를 계속하기 위해 코린 삼거리로 향했다는 메모가 여기 있군요. 새로 부활한 리치에 대해 우리가 아는 바에 따르면, 칠본은 아직 자신의 힘을 제대로 키우지 못했을 것입니다. 즉, 군대 전체를 부르지 않고도 당신이 그를 처리할 수 있다는 뜻입니다.\n\n저는 그가 교단이 여기서 찾고 있는 것에 대해 더 많은 정보를 가지고 있기를 바라지만, 그가 더 강해지기 전에 지금 그를 제거할 기회를 잡아야 합니다.",
    },
    [26730] = {
        ["T"] = "수상한 편지",
        ["O"] = "수상한 편지를 동부 역병지대에 있는 스탈링 교수(Professor Starling)에게 가져가십시오.",
        ["D"] =
        "칠본의 소지품 안에서 라스 프로스트위스퍼에게 보내려다 만 편지를 발견합니다. 편지 내용은 다음과 같습니다:\n\n\"라스, 접선 장소에 대한 공지를 받았고 물건과 함께 전령을 보냈습니다. 신디케이트가 장악한 땅을 통과한 후에 로데론과 이렇게 가까운 곳에서 만나는 게 정말 현명한 일인지 모르겠습니다. 어둠의 장막은 포세이큰에게 아무런 의미가 없으니까요. 성물함이 잘못된 손에 들어가면 그 결과는...\"\n\n스탈링 교수라면 이 물건에 관심이 있을 것입니다.",
    },
    [26731] = {
        ["T"] = "현장 학습",
        ["O"] = "밤 동안 물건을 넘길 접선 장소를 찾고, 접선을 관찰할 장소를 찾으십시오.",
        ["D"] =
        "리치는 그 성물함을 얻어 정화하기 전까지는 결코 완전히 쓰러진 것이 아닙니다. 칠본의 성물함은 그가 가지고 있지 않았고, 이 편지는 그것이 어딘가로 옮겨졌음을 나타냅니다.\n\n보십시오 - 일지의 마지막 항목에는 로데론의 폐허 자체의 그림자 속에 있는 외딴 지역에서 왕실 연금술 학회의 일원과 곧 접선이 있을 거라고 적혀 있습니다! 편지의 지시 사항은 알터랙 산맥을 지나, 단드레드 장원을 거쳐, 로다미어 호수의 동쪽 가장자리를 따라 이동해야 한다고 나와 있습니다.\n\n이 접선은 반드시 중단시켜야 하며 - 밤에 이루어질 예정입니다. 저는 여기에 남아 일지의 나머지 내용에 쓰인 암호를 풀겠습니다.",
    },
    [26732] = {
        ["T"] = "현장 학습",
        ["O"] = "접선을 관찰하고 칠본의 성물함을 가로채십시오.",
        ["D"] =
        "당신은 상자 안에 자리를 잡고, 제시간에 도착했다면 이 만남이 너무 오래 걸리지 않기를 바랍니다.\n\n비축된 통 위로 횃불 불빛이 춤을 추고 어스름한 밤의 어둠 속에서 형체들이 시야에 들어오면 당신의 인내심은 보상을 받을 것입니다.",
    },
    [26733] = {
        ["T"] = "현장 학습",
        ["O"] = "칠본의 성물함을 검은바위 산으로 가져가 산 내부의 용암에 던져 파괴하십시오. 그 후 동부 역병지대의 버려진 예배당 근처에 있는 스탈링 교수에게 결과를 보고하십시오.",
        ["D"] =
        "리치의 성물함을 정화하는 것은 사소한 일이 아니지만, 쉬운 방법이 하나 있습니다 - 검은바위 산의 펄펄 끓는 용암 속에 던져넣는 것입니다. 산의 작열하는 열기로도 칠본의 영혼을 가두는 틀을 녹일 수 없다면, 그 어떤 것으로도 녹일 수 없을 것입니다.\n\n프랜클론 포지라이트의 무덤을 통과해 사슬을 따라가면 작열하는 교각 바닥에 있는 용암 웅덩이에 쉽게 도달할 수 있습니다.",
    },
    [26734] = {
        ["T"] = "현장 학습",
        ["O"] = "긴급 보고서를 동부 역병지대의 희망의 빛 예배당에 있는 니콜라스 제베렌호프 경에게 가져가십시오.",
        ["D"] =
        "당신이 여행하는 동안, 칠본의 일지를 해독할 시간이 있었습니다. 제가 알게 된 사실은 구역질이 날 정도였습니다. 지금 당신에게 얼마나 많은 것을 말해줄 수 있을지 모르겠으니, 그것은 제 상관들에게 맡기겠습니다. 제가 작성한 이 보고서를 희망의 빛 예배당에 있는 니콜라스 제베렌호프 공작에게 즉시 가져가 주십시오!",
    },
    [26735] = {
        ["T"] = "동부숲의 기억",
        ["O"] = "다로우샤이어에서 과거의 유물 1개를 찾아 동부 역병지대의 희망의 빛 예배당에 있는 아일라나 페더문에게 가져가십시오.",
        ["D"] =
        "당신도 느껴지시나요, $C? 자연스러운 존재의 조화가 파괴될 때 이 땅이 어떻게 고통에 울부짖는지요? 저는 그 부름에 응답하기 위해 멀리서 왔고, 이제 이곳에 도착하니 이 땅의 고통에 압도되는 기분입니다. 당신의 도움이 필요합니다.\n\n역병이 돌기 전, 이 땅은 동부숲이라 불리며 무성한 숲과 농장, 그리고 자라나는 것들로 가득 차 있었습니다. 치유의 희망이 있으려면 우리는 이 땅이 한때 어떤 모습이었는지 이 땅에 상기시켜야 합니다.\n\n이곳에 살았던 자들은 도망치거나 역병에 굴복했을 때 그들의 과거 삶에 대한 많은 유물을 남겼습니다. 어두운 기억을 떨쳐내기 위한 정화 의식을 치르려면 많은 유물을 모아야 합니다.\n\n남쪽, 다로우샤이어라는 마을에서 시작하십시오. 남겨진 물건이 있는지 찾아보십시오.",
    },
    [26736] = {
        ["T"] = "동부숲의 기억",
        ["O"] = "코린 삼거리에서 과거의 유물 2개를 찾아 동부 역병지대의 희망의 빛 예배당에 있는 아일라나 페더문에게 가져가십시오.",
        ["D"] =
        "다로우샤이어에서 길을 따라 올라오는 여행자는 다음으로 코린 삼거리에 도달했을 것입니다. 특히 수확기에는 마을의 즐거운 축제에 대해 들은 적이 있습니다. 붉은 수탉 여관은 우리 동족들 사이에서도 훌륭한 에일 맥주로 유명했죠. 우리는 그 풍요와 기쁨의 기억을 소환해야 합니다.\n\n코린 삼거리로 여행하여 그곳에서 유물 몇 개를 찾으십시오.",
    },
    [26737] = {
        ["T"] = "동부숲의 기억",
        ["O"] = "브라우만 제분소에서 과거의 유물 1개를 찾아 동부 역병지대의 희망의 빛 예배당에 있는 아일라나 문페더에게 가져가십시오.",
        ["D"] =
        "우리가 지금 서 있는 곳 바로 북쪽에는 브라우만 제분소가 있었습니다. 과거에는 줄아만과 영원노래에서 강을 따라 떠내려온 통나무들을 제재하던 곳이죠. 저는 개인적으로 이런 관행이 불쾌할지 모르지만, 그곳의 노동자들이 남긴 헌신의 메아리는 우리가 포착해야 할 가치가 있다고 확신합니다.\n\n제분소에서 유물을 찾아 제게 가져오십시오.",
    },
    [26738] = {
        ["T"] = "동부숲의 기억",
        ["O"] = "마른 푸른골짜기 강(Greenrush River) 근처의 농장에서 과거의 유물 2개를 찾아 동부 역병지대의 희망의 빛 예배당에 있는 아일라나 문페더에게 가져가십시오.",
        ["D"] =
        "푸른골짜기 강은 산에서 동부숲을 거쳐 흘러내리며 목재와 생명을 하류의 농장으로 실어 날랐습니다. 그 농장들의 폐허가 일부 남아있습니다.\n\n검은나무 농장은 이름이 같은 호수 근처에 있었고, 푸른골짜기 농장은 강 건너 북쪽에 있었습니다. 그 농장들을 수색하여 더 행복했던 시절의 유물을 찾을 수 있는지 확인해 보십시오.",
    },
    [26739] = {
        ["T"] = "동부숲의 기억",
        ["O"] = "잿불마을 폐허에서 과거의 유물 2개를 찾은 다음, 동부 역병지대의 희망의 빛 예배당에 있는 아일라나 문페더에게 돌아가십시오.",
        ["D"] =
        "스트라솔름에 가까워질수록 여행자들은 의식용 아치를 통과했습니다. 이것이 인간들에게 어떤 의미였는지는 모르지만, 그 아치에는 잿불마을이라는 마을이 있었습니다. 한때 성장하던 공동체의 흔적은 거의 남아 있지 않지만, 우리는 그들의 유산을 포착할 수 있습니다.\n\n북서쪽으로 스트라솔름을 향해 길을 따라가서 아치를 지나 지금은 역병숲이 된 곳의 폐허를 수색하십시오. 무엇이든 찾아서 가져오십시오.",
    },
    [26740] = {
        ["T"] = "동부숲의 기억",
        ["O"] = "테러데일에서 과거의 유물 1개를 찾아 동부 역병지대의 희망의 빛 예배당에 있는 아일라나 문페더에게 가져가십시오.",
        ["D"] =
        "역병숲 반대편에는 한때 웨스트데일로 알려졌지만, 지금은 테러데일이라고 불리는 것이 더 적절한 작은 마을이 있습니다. 스트라솔름 주민 중 상당수가 아서스가 도시를 공격할 때 이곳으로 피신했고 그들과 함께 역병을 가져왔습니다.\n\n저는 그곳이 순식간에 무너졌다고 이해하고 있습니다.\n\n우리는 거의 다 왔습니다, $C. 우리 수집품을 위해 웨스트데일 역사의 유물을 가져오십시오.",
    },
    [26741] = {
        ["T"] = "동부숲의 기억",
        ["O"] = "스트라솔름의 거주민들에게서 과거의 유물 10개를 모아, 동부 역병지대의 희망의 빛 예배당에 있는 아일라나 문페더에게 가져가십시오.",
        ["D"] =
        "단 한 곳만이 남았고 저를 대신하여 이 위험에 맞서달라고 부탁하기가 두렵지만, 당신이 우리가 필요한 마지막 유물을 회수하는 데 성공한다면 필수적인 의식을 준비해야 합니다.\n\n바로 스트라솔름 주민들의 물건입니다.\n\n한때 북부의 빛나는 보석이었던 곳은 이제 끊임없이 불타오르는 유령의 폐허가 되었습니다. 언데드와 저주받은 자들의 교단이 거리를 활보하고 있습니다.\n\n이 새로운 거주민들 중 상당수는 틀림없이 망자들에게서 물건을 약탈했을 것입니다. 그들에게서 부당하게 얻은 물건을 빼앗아 그 유물들을 제게 가져오십시오.\n\n우린 거의 다 왔습니다.",
    },
    [26742] = {
        ["T"] = "동부숲의 기억",
        ["O"] = "동부 내륙지의 세라데인에 있는 폐허가 된 사원으로 여행하여 의식용 제단을 찾으십시오. 안전을 위해 동료 몇 명을 데려가는 것이 좋을 것입니다.",
        ["D"] =
        "이곳에서 의식을 치르기에는 제가 이 땅의 고통에 너무 쇠약해진 것 같습니다. 자연의 힘이 더 강한 곳으로 이동해야 합니다.\n\n동부 내륙지의 세라데인은 그리 멀지 않습니다. 적대적인 녹색 용군단을 피한다면, 정화 의식을 치르기에 이상적인 폐허가 된 사원을 찾을 수 있을 것입니다. 유물 꾸러미를 제단으로 가져가 그 위에 놓으십시오. 이 땅의 파괴에 손을 댄 강력한 존재들의 기억이 빠져나올 것입니다. 당신은 그들을 물리쳐야 합니다.\n\n저는 당신에게 많은 것을 부탁했고, $N, 당신이 이것을 할 수 없더라도 저는 이해합니다. 당신을 도울 동맹을 모아야 할 것이며, 당신이 마주할 것은 제가 설명할 수 없는 악몽입니다. 이 땅의 영혼 자체를 정화하지 않고서는 이 땅이 치유를 시작할 수 없다는 점만 말씀드릴 수 있습니다.",
    },
    [26743] = {
        ["T"] = "동부숲의 기억",
        ["O"] = "세라데인의 제단에서 무거운 기억의 유물 꾸러미를 정화한 다음, 동부 역병지대의 희망의 빛 예배당에 있는 아일라나 문페더에게 돌아가십시오.",
        ["D"] =
        "저를 보고 놀라시는군요, $C. 네. 저도 동부숲의 기억입니다. 아시다시피, 저는 스컬지 역병이 시작되었을 때 그곳에 있었습니다. 그리고 제 영원한 수치로, 저는 그것을 막기 위해 아무것도 하지 않고 도망쳤습니다.\n\n이제 당신 앞의 임무는 위험한 것이지만, 당신은 기억의 짐으로부터 동부숲을 해방시킬 뿐만 아니라, 저 역시도 해방시키게 될 것입니다.\n\n우리의 대화가 끝나면, 저는 기억을 불러일으키고 의식을 시작하겠습니다. 당신과 당신의 파티가 준비되었는지 확인하십시오...",
    },
    [26744] = {
        ["T"] = "영업 시작",
        ["O"] = "마빈 캐쉬의 흔적이 있는지 역병숲에서 스트라솔름과 테러데일 사이의 교차로에 있는 여관 폐허를 수색하십시오.",
        ["D"] =
        "이제 사업 준비가 완료되었소! 무엇을 원하십니까?\n\n아 잠깐만요... 제게 물건이 별로 없는 것 같네요. 재고도 없이 어떻게 물건을 팔죠?\n\n마빈 캐쉬가 팔 물건을 가져다주곤 했소. 그가 여기 없다면, 아마 배달 경로를 돌고 있을 거요. 그는 스트라솔름과 이곳으로 이어지는 길이 만나는 교차로 바로 옆에 있는 여관에 들르곤 했소. 그가 제 재고를 여관에 남겨두었는지 확인해 보시오. 그것을 제게 가져오시면 제 가격이 얼마나 미친 듯이 싼지 보게 될 거요!",
    },
    [26745] = {
        ["T"] = "영업 시작",
        ["O"] = "동부 역병지대의 검은나무 호수 근처 농장으로 마빈의 흔적을 따라가십시오.",
        ["D"] =
        "편지를 열어 그 내용을 읽어봅니다:\n\n\"아가사에게,\n\n당신이 이 편지를 찾아서 나를 따라오길 기도할 뿐이오. 언데드 군대가 로데론을 가로질러 오고 있소. 굿맨 가문과 함께 검은나무 농장으로 피신할 생각이오. 당신이 무사하길 기도하오. 빛이 당신을 보호하시길.\n\n마빈\"\n\n어쩌면 이것이 아우구스투스가 언급한 그 사람일까요?",
    },
    [26746] = {
        ["T"] = "영업 시작",
        ["O"] = "동부 역병지대의 코린 삼거리 여관으로 마빈의 흔적을 따라가십시오.",
        ["D"] =
        "여기 있는 편지는 습기 때문에 곰팡이가 슬고 눅눅합니다. 조심스럽게 편지를 열어보니 간신히 알아볼 수 있습니다:\n\n\"사랑하는 아가...\n\n우리는...이틀...굶주린 구울들이...근처 언덕을 배회... 코린 삼거리로 여행...여관 방 하나와...그곳에 당신을 위한 말.\n\n마빈\"\n\n코린 삼거리 여관을 조사해 봐야 할까요?",
    },
    [26747] = {
        ["T"] = "영업 시작",
        ["O"] = "마빈 캐쉬의 흔적이 있는지 동부 역병지대의 메렐다르 호수 기슭을 수색하십시오.",
        ["D"] =
        "편지를 열어 그 내용을 읽어봅니다:\n\n\"아가사에게,\n\n다로우샤이어에서 전투가 벌어졌고 수도로 가는 길은 차단되었다는 소식을 들었소. 굿맨 가문이 메렐다르 호수를 가로질러 항해할 배가 있는 사람을 찾았고, 우리는 반대편 호숫가로 탈출을 시도할 거요. 이 어두운 시기에 빛이 우리 모두를 축복하시길.\n\n마빈\"\n\n호수 근처 부두를 확인해 봐야 할까요?",
    },
    [26748] = {
        ["T"] = "영업 시작",
        ["O"] = "인양된 화물이 든 상자를 동부 역병지대 테러데일에 있는 아우구스투스(Augustus the Touched)에게 반환하십시오.",
        ["D"] =
        "이 마차에 보관된 말린 약초 더미, 신성한 헌신 인장, 비전 양초 더미는 먼지가 쌓여 있지만 아직 쓸 만해 보입니다. 이것이 마빈 캐쉬가 아우구스투스에게 가져다주려던 상품들이었을까요?\n\n어느 쪽이든 상인과 그 친구들에게 무슨 일이 일어났는지에 대한 다른 단서는 없습니다. 운이 좋았다면 그들은 스컬지 군대의 진군을 벗어났을지도 모릅니다.",
    },
    [26749] = {
        ["T"] = "경쟁자 처치",
        ["O"] = "스컬지 병사 6명, 지하마귀 4마리, 찢어진 비명꾼 2마리, 그리고 역병 걸린 멧돼지 1마리를 처치하십시오.",
        ["D"] =
        "내 고객들은 최고의 쇼핑 경험을 원하는데, 가게 주변에 불쾌한 불량배 몇 명이 서성거리는 걸 도저히 모른 체 할 수 없군.\n\n제발 그들이 다른 곳에 존재하도록 설득해 주시겠소? 어떤 설득 방식이라도 좋소! 하! 두고 보시오! 이건 정말 굉장할 거요!\n\n아, 그리고 저 멧돼지 중 한 마리도 잡아 주시오. 내 마지막 도넛을 먹어 치웠으니까!",
    },
    [26750] = {
        ["T"] = "경쟁자 처치",
        ["O"] = "아우구스투스를 위해 가고일의 날개 8개와 공포의 꿰맨 자국 4개를 수집하십시오.",
        ["D"] =
        "오 안 돼, $N! 문제가 생겼소 - 내 고객들이 사고 싶어 할 물건을 담을 쇼핑백이 하나도 없소!\n\n스트라솔름에 들어가서 굿맨 가문의 잡화점에서 몇 개 더 가져다주면 안 되겠소?\n\n거기 불타고 있다고? 그럼 안 되겠군. 알겠소.\n\n내가 괴성을 지르며 날아다니는 박쥐 같은 생물들을 좀 봤지. 박쥐가 아니오! 박쥐 같은 녀석들 말이오. 놈들의 날개는 좋은 가방이 될 거요. 그리고 실도 좀 필요하지. 아마 역병숲을 어슬렁거리는 그 꿰매어진 괴물들에게서 구할 수 있을 거요. 그래! 바로 그거요!",
    },
    [26751] = {
        ["T"] = "방문 마케팅",
        ["O"] = "영혼 주민 6명에게 아우구스투스의 미친 듯이 싼 가격에 대해 알리십시오!",
        ["D"] =
        "이제 정말 영업할 준비가 되었소! 그러니 나가서 테러데일의 선량한 사람들에게 알리시오: 쇼핑할 시간이 왔다고! \n\n당신은 이것을 놓치고 싶지 않을 거요. 내 가격은 미쳤으니까!",
    },
    [26752] = {
        ["T"] = "목적을 갖기 위해",
        ["O"] = "동부 역병지대에 있는 아돈을 위해 유령 타란툴라 8마리를 처치하십시오.",
        ["D"] =
        "안녕하십니까 모험가여! 이 황폐한 땅에서 새로운 얼굴을 뵙는 것은 참으로 오랜만이군요.\n\n저는 쿠엘탈라스에 닥칠 위험을 감시하기 위해 이곳에 배치되었고, 이미 오래전에 죽거나 실종된 상관의 명령을 지키는 것이 아무리 우스꽝스러워 보일지라도 그 임무를 소홀히 하지 않을 것입니다. 하지만 감시를 서는 동안, 무기를 들고 이 문제를 해결할 의지가 있는 사람이라면 이 땅의 문제점들을 바로잡을 수 있음을 알게 되었습니다.\n\n당신이 바로 그런 $R이라면, 거미들로 들끓고 있는 역병숲 남쪽의 동굴에 주목해 주십시오. 놈들의 숫자를 줄여 당신의 전투력을 제게 보여주십시오.",
    },
    [26753] = {
        ["T"] = "숲 너머의 땅",
        ["O"] = "유령 타란툴라 알주머니에서 쿠엘도레이 비단가닥 6개를 모아 동부 역병지대에 있는 아돈에게 가져가십시오.",
        ["D"] =
        "쿠엘탈라스가 멸망한 후, 저는 동족들 사이에서 추방자가 되었습니다. 쿠엘리시엔 산장의 엘프들은 외부인과의 접촉을 피하고, 실버문으로 돌아가는 길은 막혀 있습니다. 저는 혼자입니다.\n\n저를 좀 도와주시겠습니까? 역병숲 남쪽에 사는 유령 타란툴라의 알주머니에는 실버문에서 멋진 망토를 만드는 데 쓰이는 섬세한 비단가닥이 들어있습니다. 그 실을 제게 좀 가져다주시면 제가 그곳에서 살던 느낌이 어땠는지 기억할 수 있을 것입니다.",
    },
    [26754] = {
        ["T"] = "숲 너머의 땅",
        ["O"] = "햇살 깃든 특등급 포도주 한 병을 동부 역병지대에 있는 아돈에게 가져가십시오.",
        ["D"] =
        "행복했던 시절이라면, 저는 햇빛으로 발효시킨 포도주인 햇살 깃든 특등급 포도주 한 병으로 당신의 승리를 축하했을 것입니다. 그것을 다시 맛볼 수 있다면 무엇이든 주겠습니다.\n\n쿠엘리시엔 산장에 있는 엘프들에게 그것이 있을지 모르지만, 그들은 옛 쿠엘탈라스에서 추방되었습니다. 마지막으로 그들과 대화를 시도했을 때 그들은 저를 쫓아내고 다시는 그들의 영토에 들어오지 말라고 경고했습니다. 그들의 노여움을 사고 싶지는 않군요. 당신이 대신 그곳에 가서 제게 줄 포도주를 구할 수 있는지 알아봐 주시겠습니까?",
    },
    [26755] = {
        ["T"] = "태양의 물",
        ["O"] =
        "운고로 분화구의 골락카 간헐천에 있는 살아있는 물과 찰박거리는 정령에게서 순수한 샘물 구슬 8개를 수집한 다음, 동부 역병지대의 쿠엘리시엔 산장에 있는 셀레스테 코레알리스에게 돌아가십시오.",
        ["D"] =
        "햇살 깃든 특등급 포도주를 찾고 계신가요? 입맛이 고급이시군요! 요새 구하기 힘든 음료죠.\n\n다행히도, 저는 지금 햇살 깃든 특등급 포도주를 여러 병 발효시키고 있으며, 더 만드는 데 필요한 핵심 재료가 다 떨어졌습니다. 재료를 가져다주시면 한 병은 당신 겁니다!\n\n영원노래 숲에서 흐르던 것과 같은 순수한 샘물이 필요합니다. 영원노래는 스컬지에 의해 황폐해졌으므로, 다른 곳에서 수원을 찾아야 합니다. 온천이 있는 원시적인 곳이라면 어떨까요? 그곳이 어디인지는 당신이 알아내시도록 맡기겠습니다.",
    },
    [26756] = {
        ["T"] = "숲 너머의 땅",
        ["O"] = "동부 역병지대의 맹독의 둥지 도살장에서 순찰자 라리야를 찾아 처치한 다음, 동부 역병지대에 있는 아돈에게 돌아가십시오.",
        ["D"] =
        "당신에게 부탁하고 싶은 마지막 임무가 하나 있습니다, $R.\n\n스컬지가 내 동족의 땅을 행군할 때 우리는 최고의 순찰자들을 많이 잃었습니다. 운이 좋은 자들은 죽었습니다. 다른 이들은 언데드의 저주를 통해 그들을 섬기기 위해 되살아났습니다. 그중 한 명은 제게 무척 가까운 사람이었습니다.\n\n맹독의 둥지는 이 땅에서 스컬지의 사악한 음모를 위한 작전 기지 중 하나입니다. 그 둥지의 사령관은 이전에 실버문 소속이었던 순찰자 라리야입니다. 이전에 그녀가 거부당했던 죽음을 그녀에게 선사해 주십시오. 그녀가 안식에 들었음을 알게 되면 제 마음이 크게 편안해질 것입니다.",
    },
    [26757] = {
        ["T"] = "그림자가 닿지 않는 곳",
        ["O"] = "라리야의 편지를 동부 역병지대의 아돈에게 가져가십시오.",
        ["D"] =
        "순찰자 라리야의 몸에서 발견된 이 편지는 낡고 서둘러 쓴 것처럼 보입니다 - 심지어 봉인조차 되지 않았습니다. 아돈이라면 틀림없이 이것에 관심을 가질 것입니다.",
    },
    [26758] = {
        ["T"] = "야수의 본성",
        ["O"] = "그늘날개로 알려진 사악한 생명체를 처치한 다음, 동부 역병지대의 산마루 경비탑 근처에 있는 파트리스 에를가딘 부인에게 돌아가십시오.",
        ["D"] =
        "모험가님 환영합니다! 이 황량한 땅에서 반가운 얼굴을 만나니 안심이 되는군요.\n\n제 남편은 가시덤불 골짜기에서 사냥꾼으로 이름을 떨쳤습니다. 전 역병지대의 괴물들을 사냥하여 그 명성에 힘을 더하고자 했지만, 제가 너무나 잘 알던 이 땅의 파괴를 목도하니 슬픔에 압도되어 버렸습니다. 예를 들어, 이 집은 한때 제 친한 친구의 소유였습니다.\n\n전리품을 찾는 대신, 우리는 스컬지가 만든 끔찍한 생명체들을 파괴하는 데 도움을 주어야 합니다. 매리스 농장 북쪽 시골에는 그늘날개라는 이름의 거대한 알비노 악마 박쥐가 출몰합니다. 이 사악한 생명체를 파괴하는 데 도움을 주신다면 감사하겠습니다.",
    },
    [26759] = {
        ["T"] = "야수의 본성",
        ["O"] = "피고름구더기로 알려진 사악한 생명체를 죽인 다음, 동부 역병지대의 산마루 경비탑 근처에 있는 파트리스 에를가딘 부인에게 돌아가십시오.",
        ["D"] =
        "그늘날개의 죽음으로 당신은 거친 짐승을 다룰 수 있음을 증명했습니다. 당신이 죽여주었으면 하는 또 다른 괴물이 있습니다.\n\n북쪽으로 스트라솔름으로 향하는 길을 따라가다 보면 피고름구더기라고 알려진 뚱뚱한 덩어리를 발견할 수 있습니다. 놈이 통제 불능의 끔찍한 벌레 떼를 번식시키기 전에 놈을 죽여주십시오.",
    },
    [26760] = {
        ["T"] = "역병숲의 가마솥",
        ["O"] = "역병숲에 있는 스컬지 가마솥에 다목적 중화제를 넣은 다음 연금술사 디더스에게 돌아가십시오.",
        ["D"] =
        "서부 역병지대의 가마솥에서 훌륭한 성과를 거두셨군요. 이제 동부 역병지대에서의 유사한 스컬지 활동에 눈을 돌릴 때입니다.\n\n우리의 정보에 따르면 역병숲에는 3개의 역병 가마솥이 작동 중이라고 합니다. 이 가마솥들에는 가마솥 군주가 없으며, 저는 모든 가마솥에 일반적인 중화제를 사용하여 그 내용물을 오염시키고 적어도 당분간은 사용할 수 없게 만들 수 있다고 믿습니다. 이 유리병을 가지고 가마솥을 처리하십시오. 하지만 조심하십시오. 역병숲은 역병지대 내 스컬지 세력의 심장부이며 온갖 종류의 병사들로 가득합니다.",
    },
    [26761] = {
        ["T"] = "마지막 가마솥",
        ["O"] = "곰팡이 계곡과 맹독의 둥지에 있는 스컬지 가마솥에 다목적 중화제를 넣은 다음 연금술사 디더스에게 돌아가십시오.",
        ["D"] =
        "마지막 가마솥 두 개가 남아 있다는 보고가 들어왔는데, 각각 동부 역병지대의 맹독의 둥지와 곰팡이 계곡에 있습니다. 이 두 가마솥에 중화제를 넣으면 역병의 확산을 적어도 당분간은 통제할 수 있을 것입니다.\n\n영웅이여, 이 일을 신속히 마무리할 수 있도록 서두르십시오.",
    },
    [26762] = {
        ["T"] = "역병숲의 가마솥",
        ["O"] = "역병숲에 있는 스컬지 가마솥에 다목적 중화제를 넣은 다음 연금술사 알빙턴에게 돌아가십시오.",
        ["D"] =
        "서부 역병지대의 가마솥에서 훌륭한 성과를 거두셨군요. 이제 동부 역병지대에서의 유사한 스컬지 활동에 눈을 돌릴 때입니다.\n\n우리의 정보에 따르면 역병숲에는 3개의 역병 가마솥이 작동 중이라고 합니다. 이 가마솥들에는 가마솥 군주가 없으며, 저는 모든 가마솥에 일반적인 중화제를 사용하여 그 내용물을 오염시키고 적어도 당분간은 사용할 수 없게 만들 수 있다고 믿습니다. 이 유리병을 가지고 가마솥을 처리하십시오. 하지만 조심하십시오. 역병숲은 역병지대 내 스컬지 세력의 심장부이며 온갖 종류의 병사들로 가득합니다.",
