        ["O"] = "곰팡이 계곡과 맹독의 둥지에 있는 스컬지 가마솥에 다목적 중화제를 넣은 다음 연금술사 알빙턴에게 돌아가십시오.",
        ["D"] =
        "마지막 가마솥 두 개가 남아 있다는 보고가 들어왔는데, 각각 동부 역병지대의 맹독의 둥지와 곰팡이 계곡에 있습니다. 이 두 가마솥에 중화제를 넣으면 역병의 확산을 적어도 당분간은 통제할 수 있을 것입니다.\n\n영웅이여, 이 일을 신속히 마무리할 수 있도록 서두르십시오.",
    },
    [26764] = {
        ["T"] = "우리에겐 기술이 있다",
        ["O"] = "스컬지 기계공학자 롯렌치를 쓰러뜨리고 투석기 설계도를 빼앗으십시오. 동부 역병지대의 티르의 손 수도원으로 향하는 도로 근처에서 그를 찾으십시오.",
        ["D"] =
        "안녕하세요, $C. 우호적인 - 그리고 살아있는 - 얼굴을 보니 반갑네요.\n\n언데드가 널려 있음에도 불구하고, 이곳에는 진취적인 젊은 $R... 당신 같은 분들을 위한 기회가 있습니다! 스컬지는 역병지대를 행군하며 많은 투석기를 뒤에 남겨두었고, 그중 일부를 인양하기 시작했습니다. 전 그게 어떻게 작동하는지 알고 싶어요!\n\n여기서 멀지 않은, 티르의 손 수도원으로 가는 길을 따라 스컬지 기계공들이 쓰러진 벌목기를 수리하고 있습니다. 그들의 우두머리를 죽이고 그들이 전차를 고치는 데 사용하는 설계도를 제게 가져다주시면 수고비는 톡톡히 쳐드리겠습니다.",
    },
    [26765] = {
        ["T"] = "우리에겐 기술이 있다",
        ["O"] = "티르의 손 수도원이나 쿠엘탈라스로 가는 길 근처의 스컬지 정비공들에게서 스컬지 렌치, 스컬지 스패너, 스컬지 망치를 수집하십시오.",
        ["D"] =
        "이것 좀 보세요 $N. 이 부품 중 일부는 노스렌드의 가열로에서 제조된 특수 냉기 철제 도구가 필요해요. 전 그런 게 없어요! 사실, 제가 아는 사람 중엔 아무도 그런 걸 안 가지고 있죠!\n\n하지만 이 전차들을 인양하는 작업을 하는 스컬지 기계공들은 가지고 있을 게 분명해요. 근처에 있는 기계공들이 도구를 가지고 있지 않다면 북쪽의 쿠엘탈라스로 가는 길을 따라 더 찾아볼 수 있습니다.",
    },
    [26766] = {
        ["T"] = "우리에겐 기술이 있다",
        ["O"] = "동부 역병지대의 노스데일 근처에 있는 역병 벌목기를 인양하여 스컬지 예비 부품 30개를 얻으십시오.",
        ["D"] =
        "이제 알맞은 도구가 생겼으니 알맞은 부품이 필요합니다.\n\n이 투석기들엔 기즈모플럭스 톱니바퀴벨트가 회전 너트 매트릭스와 만나는 부분에 설계 결함이 있는 것 같습니다. 제가 본 고장 난 전차들은 모두 그 부분이 박살나 있었죠. 하지만, 이제 약간의 고블린 창의력을 투입할 때입니다! 노스데일 주변의 기계 수확기에서 교체 부품을 얻을 수 있을 겁니다. 돌봐줄 사람이 없어서 광포해졌으니 조심하세요!",
    },
    [26767] = {
        ["T"] = "우리에겐 기술이 있다",
        ["O"] = "기계공학자 길킨에게 투석기를 위한 모든 부품이 모였다고 전하십시오.",
        ["D"] =
        "이 물건들을 조립하는 건 공이 많이 드는 작업입니다. 최종 작업은 제 조수인 기계공학자 길킨에게 맡기겠습니다. 여기, 그에게 우리가 준비되었다고 말해주시겠어요? 그는 저쪽 들판에 있습니다.",
    },
    [26768] = {
        ["T"] = "자업자득 (Just Desserts)",
        ["O"] = "사라 팀버레인에게 특별한 간식을 만드는 데 필요한 재료를 가져다주십시오.",
        ["D"] =
        "우리의 영광스러운 주인님께서 특별한 손님들을 저녁 식사에 초대하셨고, 전 식사 준비를 맡았죠. 손님들에게 기억에 남는 저녁 식사를 대접하기 위해 최고급 재료를 구하고 최고의 레시피를 연구하는 데 몇 주를 보냈어요.\n\n특별한 날 저는 주방에서 몇 시간 동안 모든 향신료와 소스의 균형을 완벽하게 맞췄죠. 음식이 손님들의 미각 위에서 춤을 출 것이라고 확신했을 때 비로소 식탁에 내보냈어요.\n\n모든 것이 순조롭게 시작됐어요. 손님들은 애피타이저 냄새를 맡으며 기대감에 침을 흘리고 있었죠. 모두에게 음식이 서빙된 후, 주인님께서 모두에게 \"마음껏 먹으라\"고 권하셨어요.\n\n그때 제 인생 최대의 모욕을 받았어요. 주인님께서는 음식은 맛보지도 않으시고 손가락을 튕기더니 직접 머핀을 창조해 내서 드셨죠! 파스트리에 중독되었다며 농담을 하시고는 제 요리에는 손도 대지 않으셨어요. 그러자 손님들도 주인님이 드시는 걸 원했죠! 이 모든 게 헛수고가 됐어요!\n\n전 그의 배은망덕함에 넌더리가 났고 복수할 계획이 있어요. 그저 부족한 재료 몇 개만 있으면 돼요.\n\n진저가 가꾸는 정원에서 마나 베리 몇 개와 골드샤이어의 타린 보우덴에게서 밀가루, 부드러운 양념, 소금을 좀 가져다주세요.",
    },
    [26769] = {
        ["T"] = "자업자득 (Just Desserts)",
        ["O"] = "아조라의 탑 바깥의 우물에서 마나로 오염된 진흙을 낚으십시오.",
        ["D"] =
        "좋아요, 재료를 가져오셨으니 아주 맛있는 케이크를 만들 거예요 -- 하지만 한 가지가 더 필요해요: 케이크의 다른 모든 맛을 압도할 강렬한 풍미를 가진 무언가 말이에요.\n\n근처에 있는 이 우물은 주인님의 실험으로 오염되어 아무도 쓰지 않아요. 우리가 필요한 것이 저 아래에 있을 거라고 확신해요. 이 낚싯대를 가져가서 마나로 오염된 진흙을 좀 낚아주세요.",
    },
    [26770] = {
        ["T"] = "자업자득 (Just Desserts)",
        ["O"] = "사라의 케이크를 테오크리투스에게 선물하십시오.",
        ["D"] =
        "자, 케이크가 완성됐어요. 겉보기엔 완벽하게 맛있어 보이지만... 안에는 한 입만 먹어도 심한 위경련을 일으킬 것이 확실하죠.\n\n케이크를 탑 꼭대기에 있는 테오크리투스에게 가져가세요. 이 케이크가 그의 파스트리 중독을 치료할 거라고 믿어 의심치 않아요. 그럼 제가 만든 건강하고 맛있는 음식을 군말 없이 먹게 되겠죠.",
