    [26771] = {
        ["T"] = "잃어버린 장비",
        ["O"] = "석영 광산에서 채광 장비 8개를 회수하여 골드샤이어의 로버트 미스턴에게 돌아가십시오.",
        ["D"] =
        "난 코볼트와 거미가 그곳을 점령하기 전까지 석영 광산에서 일했었네. 광석이 풍부했고 스톰윈드 대장장이들에게 보내는 주요 공급원이었지.\n\n괴물들이 그곳을 점령했을 때, 우리는 많은 동료 광부들을 잃었고 장비도 모두 잃었네. 광부들은 대체할 수 없지만, 우리가 그곳에 두고 온 장비 중 일부를 찾아서 내게 가져다줄 수 있겠나?",
    },
    [26772] = {
        ["T"] = "숙련 말 타기",
        ["O"] = "랜들 헌터에게서 숙련 타기를 배운 다음, 엘윈 숲에 있는 케이티 헌터와 대화하여 말을 얻으십시오.",
        ["D"] =
        "다시 오셨군요. 숙련 타기를 배우러 오신 거 맞죠? 이전과 마찬가지로 말의 가격은 지불되었지만, 훈련 비용은 직접 지불하셔야 합니다. 고급 훈련은 안타깝게도 결코 저렴하지 않습니다.\n\n훈련을 받으신 후 우리 반대편에 있는 케이티 헌터와 대화하십시오. 그녀는 우리 말의 판매를 관리합니다. 아직 자금이 없으시다면 언제든지 다시 오셔도 좋습니다.",
