    [26773] = {
        ["T"] = "말 타기",
        ["O"] = "랜들 헌터에게서 수습 타기를 배운 다음, 엘윈 숲에 있는 케이티 헌터와 대화하여 말을 얻으십시오.",
        ["D"] =
        "그래서 말을 구하러 오셨군요? 마침 당신을 기다리고 있었습니다! 어떤 신비한 후원자가 일반 군마 값을 지불하고 당신의 이름, $N(으)로 편지를 남겼습니다. 하지만 훈련 비용은 지불하지 않았기 때문에, 안타깝게도 그 비용은 청구해야 합니다.\n\n훈련을 받으신 후 우리 반대편에 있는 케이티 헌터와 대화하십시오. 그녀는 우리 말의 판매를 관리합니다. 아직 자금이 없으시다면 나중에 다시 오셔도 됩니다.",
    },
    [26774] = {
        ["T"] = "거미 비약",
        ["O"] = "거미 턱뼈 4개를 회수하고 엘윈 숲의 석영 광산에서 갇힌 광부 4명을 풀어주십시오.",
        ["D"] =
        "모험가님, 저를 좀 도와주시겠어요? 이 불쌍한 광부들은 석영 광산에서 도망치는 걸 발견했어요. 그들은 골드샤이어로 돌아오기 전에 지쳐 쓰러졌죠. 무언가가 그들의 정신을 흐리게 해서 상황을 설명 듣지 못했어요.\n\n광산 깊은 곳에 거미들이 둥지를 틀었다는 소문을 들은 적이 있어요. 광부들이 거미에게 중독된 거라면, 모든 게 설명이 돼요! 알맞은 해독제를 만들려면 광산 거미의 턱뼈 샘플이 필요해요.\n\n그리고 제발, 갇혀 있는 광부를 발견하면 그들이 탈출할 수 있도록 풀어주시겠어요?",
    },
    [26775] = {
        ["T"] = "부상자 돌보기",
        ["O"] = "거미 비약을 사용하여 수간호사 달시의 야전 치료소 텐트에서 중독된 광부들을 치료하십시오.",
        ["D"] =
        "이제 이 해독제가 생겼으니 남은 부상자들을 편안하게 치료할 수 있겠군요. 제 뒤에 있는 광부들에게 한 명씩 약을 투여해서, 그들이 무사하고 건강하게 가족들의 품으로 돌아갈 수 있게 해주세요.",
    },
    [26776] = {
        ["T"] = "날쌘발",
        ["O"] = "날쌘발의 주둥이를 노스샤이어 수도원 밖에 있는 메리사 스틸웰에게 가져가십시오.",
        ["D"] =
        "당신 -- $c -- 마침내 이곳 일을 도우러 온 사람을 보니 반갑군요. 최근의 비극에 대해 들으셨나요? 제 아들이 폭포 아래서 놀고 있었는데, 숲에서 거대한 늑대가 뛰쳐나와 아이를 물어 죽였어요! 제가 반응할 틈도 없이 불쌍한 제 아들은 이미 목숨을 잃고 말았죠.\n\n<메리사가 살짝 눈물을 글썽입니다.>\n\n경비병 몇 명과 이야기해 보니, 도망치는 속도가 너무 빨라서 그 늑대를 날쌘발이라고 부른다더군요! 그들은 도울 수 있는 게 아무것도 없다고 했어요! 당신이 이름을 날리고 싶다면, 어머니의 마음이 편안해지도록 그 끔찍한 짐승을 끝장내서 다른 사람들에게도 같은 비극이 일어나지 않게 해주세요.",
    },
    [26777] = {
        ["T"] = "흠뻑 젖은 통",
        ["O"] = "노스샤이어 수도원에서 이 통의 출처를 알 만한 사람을 찾으십시오.",
        ["D"] =
        "수정 호수로 향하는 강을 따라 걷던 중, 겨울 산 정상이 새겨진 에일이 가득 담긴 흠뻑 젖은 통을 우연히 발견합니다. 전에는 한 번도 맡아본 적 없는 놀라운 향기가 납니다. 노스샤이어 수도원 누군가는 이것이 어디서 왔는지 알고 있을지도 모릅니다.",
    },
    [26778] = {
        ["T"] = "수사 찾기",
        ["O"] = "흠뻑 젖은 통을 노스샤이어 수도원의 수사 닐스에게 가져가십시오.",
        ["D"] =
        "전 에일이나 와인의 전문가는 아니에요, 그냥 포도를 기를 뿐이죠. 하지만 전문가라고 할 만한 분이 여기 계십니다 -- 바로 수사 닐스님이시죠. 수도원 꼭대기 층에서 찾으실 수 있을 거예요.",
    },
    [26779] = {
        ["T"] = "수사의 혐오감",
        ["O"] = "이 통의 더미를 사자무리 여관에 있는 멜리카 아이센스트라이더에게 가져가십시오.",
        ["D"] =
        "<수사 닐스가 통을 보더니 찡그립니다.>\n\n역겨운 구정물이군! 여긴 와이너리네, $N! 오스워스 양은 동부 왕국 전역에서 가장 훌륭한 포도를 재배하고, 나와 다른 형제들이 와인을 만들지. 여기선 아무도 에일을 마시지 않는다네.\n\n이것이 어디서 왔는지 정말 알고 싶다면, 골드샤이어의 사자무리 여관으로 가서 멜리카 아이센스트라이더에게 자네가 찾은 걸 보여주게. 그녀는 동네 단골손님들과 양조업자들을 아주 잘 알지.\n\n아! 그리고 거기로 간다면, 우리 와인의 최신 선적품도 그녀에게 전해주게나.",
    },
    [26780] = {
        ["T"] = "마법사의 조언",
        ["O"] = "사자무리 여관 2층에 있는 잘디마르와 대화하십시오.",
        ["D"] =
        "그러고 보니... 일주일 전쯤 무룬이라는 드워프가 여기 왔었어요. 엄청나게 술을 마셔대면서, 수도원 한참 위에 있는 노스샤이어 폭포 근처에서 풍부한 광맥을 찾고 있다는 이야기로 손님들을 즐겁게 했죠.\n\n그는 당신이 제게 가져온 통과 똑같이 생기고 같은 냄새가 나는 에일도 가져왔었어요. 하지만, 젊은 $c께서 그 절벽을 오르는 건 무리라고 생각해요.\n\n무룬을 뒤쫓는 데 관심이 있다면, 위층에 있는 잘디마르에게 말해 보세요. 그는 교활한 마법사라서 당신을 도울 수 있을지도 몰라요.",
    },
    [26781] = {
        ["T"] = "리누스의 돌 팁",
        ["O"] = "고갈된 순간이동석(Depleted Translocation Stone)을 골드샤이어 사자무리 여관에 있는 잘디마르에게 가져가십시오.",
        ["D"] =
        "당신의 도움이 필요한 부분이 바로 이겁니다, $N. 최근에 제 전 조수가 이 지역 데피아즈단과 협력하고 있다는 걸 알게 됐죠. 리누스는 제 코앞에서 골드샤이어 경비병의 패턴과 수송품에 대한 정보를 놈들에게 넘겨주고 있었어요!\n\n불행히도 제가 그를 해고했을 때, 그는 제 유물 여러 개를 훔쳐 달아났습니다. 당신에게 가장 불행한 일은, 그가 동력을 잃은 순간이동석을 가져갔다는 거죠. 그 돌을 찾아주시면, 기꺼이 돕겠습니다.\n\n마지막으로 경비병에게 들은 바에 따르면, 그는 골드샤이어 바로 북쪽 언덕에서 마을을 정찰하는 모습이 목격되었습니다. 녀석에게 교훈을 주기 위해 덤으로 뭔가를 더 해줘도 전 상관없습니다.",
    },
    [26782] = {
        ["T"] = "양조의 형제들",
        ["O"] = "노스샤이어 계곡의 폭포를 찾아 순간이동석을 이용해 꼭대기에 오르십시오.",
        ["D"] =
        "이제 그 문제가 해결되었으니, 당신이 찾고 있는 에일의 출처를 알 수 있을 겁니다. 이것을 노스샤이어 계곡의 폭포 밑으로 가져가서 꼭대기로 올라가는 데 쓰십시오. 원하는 것을 찾을 수 있기를 빕니다.",
    },
    [26783] = {
        ["T"] = "후회는 없다! 뭐, 약간은 있을지도",
        ["O"] = "노스샤이어 폭포에서 드로물 오드링크를 찾으십시오.",
        ["D"] =
        "나와 내 파트너 드로물은 던 모로에서부터 여기까지 왔어. 이 고립된 계곡에서 부를 찾아 불타는 평원을 가로질러 맹렬히 싸우며 왔지.\n\n그래, 하지만 전리품을 차지하려고 도착했을 때, 우린 사이가 틀어졌지... 녀석이 내 도구를 가져갔고, 난 녀석의 양조 장비 대부분을 가져갔어... 그리고 지금 우리 둘 다 여기 갇혀 있지!\n\n그 에일은 내가 양조한 게 아니야 $N. 그런 기술을 가진 건 강 상류에 있는 드로물이야. 내가 한 말 때문에 그 녀석이 다시는 나한테 말도 안 걸겠지만... 제발 그 녀석이 무사한지 확인해 주겠나?",
    },
    [26784] = {
        ["T"] = "마운틴스타우트 에일(Mountainstout Ale)",
        ["O"] =
        "드로물 오드링크가 마운틴스타우트 에일의 새로운 양조를 만들 수 있도록 노스샤이어 갈대 6개와 반짝이는 폭포 물(Glistening Falls Water) 반 다스 핀트를 모으십시오.",
        ["D"] =
        "무룬이 나를 걱정한다고? 나를? 하! 그 고집불통 바보가 태도를 바꿀 줄은 꿈에도 몰랐군.\n\n며칠 전 녀석의 야영지로 노를 저어 내려가서 사과의 선물을 남겼지. 녀석의 가문 문양을 새겨 넣은, 내가 발명한 새로운 에일이었어. 마운틴스타우트 에일이라 불렀지.\n\n네가 그걸 찾았다면, 녀석이 보기도 전에 강물에 떠내려간 게 분명해. <드로물이 생각에 잠깁니다.>\n\n이제 우물쭈물할 시간 없어! 강 근처의 정령들에게서 마력 깃든 물을 좀 가져오고, 근처에서 자라는 갈대도 한 움큼 꺾어와. 그러면 새 에일을 양조해 주마.",
    },
    [26785] = {
        ["T"] = "참된 친구",
        ["O"] = "마운틴스타우트 에일을 노스샤이어 폭포에 있는 무룬 골드로어에게 가져가십시오.",
        ["D"] =
        "너랑 나, 그리고 무룬이 에일을 한잔하며 수다를 떨고 이 논쟁을 뒤로할 때가 왔어. 그 녀석과 나는 오랜 사이라, 녀석 없는 삶은 상상할 수 없거든. 우린 매부지간이라고! 그러니 녀석에게 가보자고.",
    },
    [26786] = {
        ["T"] = "스톰윈드의 기물 파손",
        ["O"] = "스톰윈드 항구의 말로우(Detective Marlowe) 형사와 대화하십시오.",
        ["D"] =
        "아, 다시 만나서 반갑소 $N. 자네가 들러줘서 다행이야 -- 과거에 우릴 위해 훌륭히 일해준 적도 있고, 지금 우리 고향에 문제가 생기고 있거든. 자네가 전에 조사했던 데피아즈단 활동과 관련이 있는 것 같진 않아 -- 스톰윈드에서 활동하는 새로운 부류의 사악한 요원들이지.\n\n항구의 부두에서 뻔뻔한 기물 파손 행위가 있었어. 아무도 다치진 않았지만, 몇몇 새로운 주민들의 마차가 총에 맞고 불탔지. 아내는 당연히 정신을 차리지 못하고 있지만, 남편은 이상하게도 입을 굳게 다물고 있어. 여기엔 눈에 보이는 것보다 훨씬 더 많은 이야기가 얽혀 있으니, 자네를 지원군으로 보내겠네. 말로우 형사를 만나 그가 지금까지 알아낸 것이 무엇인지, 그리고 자네가 어떻게 도울 수 있을지 알아보게. 행운을 비네!",
    },
    [26787] = {
        ["T"] = "스톰윈드의 기물 파손",
        ["O"] = "단서를 찾기 위해 스톰윈드 항구의 브래드포드 마차 근처에 있는 다른 사람들을 탐문한 다음, 말로우 형사에게 돌아가 보고하십시오.",
        ["D"] =
        "이것이 방화임을 확인했고 어젯밤 근무하던 경비병들이 도망치는 형체를 목격했지만 - 그들은 용의자를 쫓기보다는 불이 번지기 전에 불을 끄는 데 더 집중했습니다.\n\n비비안과 데릭 브래드포드를 심문했습니다. 비비안은 완전히 혼란스러워 보이지만, 데릭은 무언가를 숨기고 있는 것 같습니다. 구체적으로 말하자면, 전 이것이 표적 범죄였고 그가 이유를 알고 있다고 생각합니다. 하지만 그는 아직 우리에게 말하지 않을 것입니다.\n\n제가 여기서 잿더미를 뒤져 단서를 더 찾는 동안, 당신이 부두 주변의 다른 사람들에게 무언가를 본 적이 있는지 물어봐 주시겠습니까?",
    },
    [26788] = {
        ["T"] = "스톰윈드의 기물 파손",
        ["O"] = "스톰윈드의 여관과 술집들을 돌며 수상한 여인을 찾아 대적하십시오.",
        ["D"] =
        "스톰윈드에는 6개의 여관과 술집이 있으니, 이 신비한 인물에 대해 더 알아내려면 모두 다 찾아봐야 할지도 모릅니다.\n\n구 시가지에 있는 돼지와 휘파람 술집부터 시작하는 게 좋을 것 같군요 - 그 동네엔 거친 자들이 많거든요. 하지만 드워프 지구의 수염 달린 여관종업원, 상업 지구의 황금 장미 여관, 마법 지구의 고독한 은둔자 선술집과 어둠의 희생양 선술집, 스톰윈드 공원의 시트린 이글(Citrine Eagle) 여관도 있죠. 여관이나 술집 주인들에게 그 묘사가 익숙한지 확인해 보세요.\n\n어둠의 희생양 선술집을 방문해야 한다는 건 부럽지 않군요. 그곳은 항상 기분 나쁜 곳이니까요.",
    },
    [26789] = {
        ["T"] = "스톰윈드의 기물 파손",
        ["O"] = "남녘해안으로 여행하여 메이저 헴스워시(Major Helmsworthy)를 찾아 알터랙 군단(Alteraci Legion)에 대해 더 알아보십시오.",
        ["D"] =
        "50년 전 알터랙 군단은 전설적이었습니다. 불행히도 대부분은 알터랙 공성전이나 그 직후의 혼란 속에서 사망했습니다. 스컬지에 대항하는 데 그들의 힘이 필요했을 텐데요....\n\n데릭 브래드포드가 무언가를 숨기고 있을지도 모르니, 정보는 다른 곳에서 얻는 것이 상책입니다. 제가 아는 전직 알터랙 군단원 중 아직 살아있는 사람은 딱 한 명뿐입니다. 남녘해안으로 여행하여 헴스워시 소령과 대화하십시오. 어쩌면 그가 데릭 브래드포드와 비밀결사대 또는 군단 간의 관계에 대해 빛을 밝혀줄지도 모릅니다.",
    },
    [26790] = {
        ["T"] = "잃어버린 깃발들",
        ["O"] = "스톰윈드의 스톰윈드 항구에 있는 데릭 브래드포드와 대화하십시오.",
        ["D"] =
        "<헴스워시 소령은 당신이 상황을 설명하는 것을 듣습니다.>\n\n절 찾아와 주셔서 다행입니다, $C. 당신을 도울 수 있는 사람은 거의 없을 겁니다.\n\n데릭 브래드포드는 알터랙의 몰락에서 살아남은 몇 안 되는 전 군단원 중 하나입니다. 그는 몇 달 전, 군단이 참여했던 주요 전투의 세월 속에 잃어버린 우리 부대의 독수리 깃발 세 개를 되찾겠다는 의향을 담은 편지를 저에게 보냈습니다. 깃발들은 금전적 가치는 없지만 - 알터랙의 자부심을 나타내는 강력한 상징입니다. 제 생각에 비밀결사대는 이 계획의 낌새를 채고 자신들을 위해 같은 깃발을 회수하고 싶어 하는 것 같습니다. 그들이 이 깃발들을 손에 넣는다면, 신병들을 모아 알터랙 군단의 왜곡된 버전을 재건할 수 있을 겁니다.\n\n데릭은 자신의 목숨을 노린 이번 시도 이후 아무도 믿지 않으려 하겠지만, 당신이 아는 사실을 말하며 그를 설득한다면, 당신의 도움을 받아들일 것이라 믿습니다.",
    },
    [26791] = {
        ["T"] = "잃어버린 깃발들",
        ["O"] = "알터랙 폐허, 달라란 폐허, 스트롬가드 폐허에서 명예의 깃발을 회수하여 언덕마루 구릉지의 남녘해안에 있는 헴스워시 소령에게 가져가십시오.",
        ["D"] =
        "알터랙 군단의 깃발을 잃어버린 장소에 대해 조사를 좀 해봤습니다.\n\n군단은 알터랙 도시 방어전의 일원이었고, 그곳에서 그들의 주 깃발을 잃었죠. 하지만 군단의 잔존 세력은 스컬지의 진격으로부터 달라란을 방어하려 시도했고, 그곳 근처 어딘가에서 마지막 깃발을 잃었습니다.\n\n가장 찾기 힘든 것은 알터랙이 스트롬가드를 공격할 때 잃어버린 깃발입니다. 너무 오래전 일이라 회수할 깃발이 거의 남아있지 않을 수도 있지만, 저는 트롤베인 가문이 우리 오래된 원한의 전리품으로 그것을 어딘가에 보관하고 있을 것이라 믿습니다.\n\n당신이 이 깃발들을 찾을 수 있다면, 우리는 비밀결사대의 계획에 타격을 입힐 수 있습니다. 깃발들을 헴스워시 소령에게 안전하게 보관해달라고 가져다주십시오. 비밀결사대가 저를 감시하고 있는 게 분명하니까요.",
    },
    [26792] = {
        ["T"] = "잃어버린 깃발들",
        ["O"] = "헴스워시 소령의 보상금을 스톰윈드의 스톰윈드 항구에 있는 데릭 브래드포드에게 가져가십시오.",
        ["D"] =
        "마무리해야 할 일이 하나 더 남았소, $C. 데릭의 가족은 화재로 모든 것을 잃었소. 이 보상금을 그에게 전해주면 좋겠군. 그는 동정을 받고 싶어 하지 않겠지만, 깃발 회수에 도움을 준 데 대한 보수라고 강하게 말하시오. 그러면 기꺼이 받아들일 거요.\n\n남쪽에서 새 삶을 시작하는 그에게 행운이 있길 빈다고 전해주시오. 다음 휴가 때 찾아가겠다고도 전해주고.",
    },
    [26793] = {
        ["T"] = "잃어버린 깃발들",
        ["O"] = "스톰윈드의 스톰윈드 항구에 있는 말로우 형사와 대화하십시오.",
        ["D"] =
        "말로우 형사가 수사를 확인하러 여러 번 찾아왔었습니다. 그에게 이제 수사를 종결해도 된다고 전해주시겠습니까?\n\n깃발이 안전해졌으니, 비밀결사대가 절 계속 감시할 이유가 없죠. 따라서 SI:7은 다른 더 중요한 일에 매진할 수 있을 겁니다.\n\n그리고 만약 비밀결사대가 저를 노리더라도, 뭐, 이젠 만반의 준비가 되어 있습니다.",
    },
    [26794] = {
        ["T"] = "현상 수배: 빅 블루(Big Blue)",
        ["O"] = "빅 블루의 날개를 엘윈 숲 아조라의 탑에 있는 진저 맥거빈스(Ginger McGubbins)에게 가져가십시오. 빅 블루는 밤에만 나타납니다.",
        ["D"] =
        "아조라의 탑의 대마법사들은 뛰어날지 모르지만, 그들의 위험 관리는... 부족합니다.\n\n불행히도, 나비 한 마리가 주인의 실험 중 하나에 너무 가까이 다가갔다가 걷잡을 수 없는 괴물로 돌연변이를 일으켰습니다.\n\n거의 매일 밤 그놈이 우리 정원을 엉망으로 만들고 있고, 그 때문에 우리 음식의 질이 떨어지고 있어요!\n\n그 짐승을 처리하고 놈의 날개를 아조라의 탑에 있는 진저 맥거빈스에게 가져가십시오! 놈이 마지막으로 목격된 장소는 탑의 북동쪽, 돌무덤 호수의 호숫가입니다.",
    },
    [26795] = {
        ["T"] = "길 잃은 전사",
        ["O"] = "던홀드 요새에서 토그타르의 흔적을 찾으십시오. 크루스크가 그가 하수구에 있을지도 모른다고 말했던 것을 기억하십시오.",
        ["D"] =
        "나와 내 형제 토그타르는 던홀드 요새에서 물건을 되찾고 그곳을 지배하는 소위 \"비밀결사대\"를 조사하라는 대족장님의 명령을 받았소.\n\n우리는 주변을 둘러보러 던홀드에 갔지만, 대규모 인간 무리에게 기습을 당했소. 용감하게 싸웠지만, 놈들의 엄청난 숫자에 압도당하고 말았지.\n\n나는 가까스로 탈출했지만 내 형제는 운이 좋지 않았소. 나는 놈들이 형제를 요새 동쪽에 있는 감옥으로 쓰는 하수구로 끌고 가는 것을 보았소.\n\n그를 찾아봐 주겠소, $N? 내 형제를 다시 데려온다면 평생 은혜를 잊지 않겠소.",
    },
    [26796] = {
        ["T"] = "길 잃은 전사",
        ["O"] = "던홀드 하수구에 있는 간수 에스톤(Jailer Eston)에게서 에스톤의 열쇠를 빼앗아 토그타르에게 돌아가십시오.",
        ["D"] =
        "누군가 왔다니 믿을 수 없군! 내 동생이 자네를 보냈나?\n\n자네가 와줘서 다행이지만, 안타깝게도 이 족쇄를 차고는 어디로도 갈 수 없소. 이 족쇄의 열쇠는 간수 에스톤이 가지고 있소. 그가 하수구 반대편으로 가는 걸 방금 봤소.\n\n가서 그의 열쇠를 가져오시오... 어떤 수단을 써서라도. 난 여기서 죽고 싶지 않소!",
    },
    [26797] = {
        ["T"] = "길 잃은 전사",
        ["O"] = "토그타르와 함께 던홀드 요새를 탈출하십시오. 성공하면 타렌 제분소에 있는 크루스크에게 보고하십시오.",
        ["D"] =
        "여기서 나갈 시간이다, $N. 하지만 명심해라, 이 망할 비밀결사대 놈들이 가만있지 않을 거다!\n\n떨어지지 말고 함께 가자. 내가 돌아왔을 때 내 동생이 어떤 표정을 지을지 벌써 기대되는군.",
    },
    [26798] = {
        ["T"] = "위기에 처한 정찰병",
        ["O"] = "비밀결사대 방어구 조각 10개를 모아 남녘해안의 탈렌 대장에게 돌아가십시오.",
        ["D"] =
        "반갑네, $N! 도움이 절실히 필요하네. 내 정찰병 중 한 명에게 북동쪽에 있는 요새인 던홀드 요새를 정찰하라고 명령했네. 최근 비밀결사대 조직이 그곳을 점령했거든. 하지만 정찰병이 아직 보고하지 않고 있어. 최악의 사태가 우려되니, 무슨 일이 일어났는지 알아보는 것이 대장으로서 내 의무지.\n\n요새에 비밀결사대 단원들이 모여있으니, 정면으로 맞붙을 위험을 감수할 수는 없어. 이번 작전엔 은신이 필요해.\n\n요새 근처에 하급 비밀결사대 단원들이 기지로 사용하는 폐허가 된 탑이 하나 있네. 놈들의 방어구를 좀 모아오게나, 그걸로 변장할 옷을 만들 수 있을 거야. 탑을 찾으려면 남녘해안에서 북쪽 길을 따라가다가 갈림길에서 우회전하여 탑이 나올 때까지 계속 동쪽으로 가게나.",
    },
    [26799] = {
        ["T"] = "위기에 처한 정찰병",
        ["O"] = "비밀결사대 변장을 하고 던홀드 요새에서 정찰병 베르나도를 찾으십시오.",
        ["D"] =
        "좋네 $N, 이제 비밀 작전을 수행할 시간이야. 자네가 이 옷으로 변장하고 던홀드 요새로 바로 들어갔으면 하네. 비밀결사대가 하수도를 감옥으로 쓰고 있다는 소식을 들었는데, 요새 동쪽에 있다네. 분명 그곳에서 실종된 정찰병을 찾을 수 있을 거야.\n\n변장한 상태에서는 비밀결사대 놈들에게 너무 공격적으로 굴지 마. 그 변장이 압박감 속에서 얼마나 잘 버틸지 자신이 없으니까. 또 필요하다면 날 찾아오게. 수리해 줄 수 있을지도 모르니.\n\n던홀드 요새를 찾으려면 방어구 조각을 얻었던 탑을 지나 조금만 더 가면 되네. 행운을 비네!",
    },
    [26800] = {
        ["T"] = "위기에 처한 정찰병",
        ["O"] = "간수 에스톤을 설득하여 감방 열쇠를 건네받고 던홀드 요새에 있는 정찰병 베르나도에게 돌아가십시오.",
        ["D"] =
        "탈렌 대장님이 보내셨습니까? 당신이 와서 다행이지만, 안타깝게도 이 족쇄를 풀기 전엔 오도 가도 못합니다!\n\n열쇠는 간수 에스톤이 가지고 있습니다. 이 하수구를 감시하는 녀석이죠. 방금 떠났으니, 아마 하수구 반대편을 순찰하고 있을 겁니다.\n\n그에게 던홀드의 주인 베브 페레놀드가 신문을 위해 절 원한다고 말하세요. 요새로 절 이송하려면 열쇠가 필요할 테니까요.\n모두가 베브를 두려워하니 그가 당신에게 열쇠를 줄 거라 확신합니다. 열쇠를 구하면 서둘러 돌아오세요, 그럼 우린 이곳을 조용히 빠져나갈 수 있습니다!",
    },
    [26801] = {
        ["T"] = "위기에 처한 정찰병",
        ["O"] = "정찰병 베르나도와 함께 던홀드 요새를 탈출하십시오. 성공하면 남녘해안의 탈렌 대장에게 보고하십시오.",
        ["D"] =
        "이곳을 탈출할 준비가 되었습니다. 눈에 띄지 않게 조심합시다; 그냥 자연스럽게 행동하세요.\n\n비밀결사대가 아는 한, 당신은 그냥 일을 하는 것뿐이니, 우리가 걸어 나갈 때 의심하지 않을 겁니다.",
    },
    [26802] = {
        ["T"] = "맹독 치료제",
        ["O"] = "이끼거미 맹독 8개를 수집하여 남녘해안의 수습생 하니웰에게 돌아가십시오.",
        ["D"] =
        "반갑습니다, $N. 저는 연금술을 깊이 연구하기 위해 남녘해안으로 왔고, 다음으로 배우고 싶은 것은 독을 치료하는 방법입니다.\n\n몇몇 시민이 거미에 물려 앓아누웠습니다. 저를 위해 그들의 독을 모아주실 수 있나요? 언덕마루 전역에 흩어져 있는 거미들을 찾으실 수 있을 겁니다.",
    },
    [26803] = {
        ["T"] = "무기고 파괴",
        ["O"] = "던홀드 요새에서 던홀드 무장 10개를 전리품으로 획득하여 남녘해안의 쿤드릭 잔덴에게 돌아가십시오.",
        ["D"] =
        "던홀드 요새의 비밀결사대 놈들이 빠르게 골칫거리가 되고 있습니다. 여행객들을 공격하고 신병을 모으는 걸 보면, 얼라이언스가 아직도 그들에게 전쟁을 선포하지 않은 게 놀라울 지경입니다!\n\n우리 땅을 안전하게 지키는 것은 남녘해안의 책임이며, 전 당신이 요새에 가서 그들의 무기를 훔쳐주었으면 합니다. 무기가 사라지면 한동안 그들의 성장이 둔화될 것입니다. 요새는 여기서 북동쪽, 길을 따라가면 찾으실 수 있습니다.",
    },
    [26804] = {
        ["T"] = "바삭하게 구워진",
        ["O"] = "던홀드 요새의 병영에 있는 비밀결사대 식량 보급품에 불을 지르십시오. 임무를 마치면 탈로우에게 돌아가십시오.",
        ["D"] =
        "저는 평생을 타렌 제분소에서 살았습니다, $c. 이 땅이 폭력배 무리에게 파괴되는 걸 보고만 있진 않을 겁니다. 당연히 비밀결사대 이야기입니다. 그들은 최근 남동쪽의 던홀드 요새로 이주했고, 식량을 구하려 우리 들판을 약탈하고 있습니다.\n\n가만두지 않겠습니다! 이제 그들에게 자신들의 약, 아니 약이 없음을 맛보게 해줄 때입니다. 그들의 병영에 있는 식량 보급품을 태워버리십시오.\n\n전 한 친구에게서 꺼지지 않는 횃불을 받았습니다. 이걸 가져가서 그들의 식량을 바삭하게 태워버리십시오.",
    },
    [26805] = {
        ["T"] = "여관 장식",
        ["O"] = "남녘해안의 여관주인 앤더슨을 위해 곰 털가죽 10개를 수집하십시오.",
        ["D"] =
        "생각 좀 해봤는데, 이 여관을 다시 장식할 때가 된 것 같소. 입구에 깔개를 더하고 싶단 말이오!\n\n내게 빚을 진 재봉사를 알고 있으니, 당신은 털가죽만 구해주면 되오. 이 근처 땅의 곰들이면 충분할 거요.",
