        ["D"] =
        "반갑네, $c. 남녘해안 수비대장으로서, 이 땅의 안전을 지키는 것이 내 책임이지. 호드가 언제 우리 문앞에서 파티를 벌이기로 작정할지 모르는 일이야.\n\n언덕마루 전역에 주둔 중인 내 경비병들에게서 보고서를 가져다줄 사람이 필요하네. 남동쪽 던 가록의 경비병 에밀리, 여기서 정서쪽에 있는 청금석 광산 밖의 경비병 팩스턴, 북서쪽 농장의 시청 근처에 있는 경비병 트리스탄을 찾을 수 있을 거야.\n\n여기 마구간에 있는 다렌과 대화하고, 내가 보냈다고 전하게. 그가 자네가 임무를 수행할 말을 빌려줄 수 있을 거야. 자네만 믿네, $N! 그리고 서두르게, 난 기다리는 걸 싫어하니까.",
    },
    [26807] = {
        ["T"] = "남녘해안 방어",
        ["O"] = "탈렌의 보고서를 저습지 메네실 항구의 스타우트피스트 경비대장에게 가져가십시오.",
        ["D"] =
        "$N... 자네가 가져온 보고서엔 심각한 소식이 담겨 있네. 호드가 언덕마루 전역에서 공격 부대를 증강하고 있어. 타렌 제분소의 총전력에 맞서 방어할 병력이 없는 것 같네.\n\n남녘해안이 살아남으려면 신속히 행동해야 해. 메네실 항구로 가서 성채에 있는 경비대장 스타우트피스트와 대화하게. 내가 이곳 상황을 문서로 정리한 보고서를 쓰지. 그에게 다가올 전투에 대비할 병력, 무기 등 무엇이든 원조를 요청해 주게. 그리고 제발 서둘러주게, 남녘해안은 자네만 믿고 있네.",
    },
    [26808] = {
        ["T"] = "남녘해안 방어",
        ["O"] = "저습지의 은여울 동굴에서 유령이 깃든 광석 8개를 채광하여 경비대장 스타우트피스트에게 돌아가십시오.",
        ["D"] =
        "호드가 남녘해안을 공격할 준비를 하고 있다고? 이건... 골치 아픈 소식이군. 메네실도 최선을 다해 돕겠지만, 많은 걸 약속할 순 없어. 지금은 병력을 빼낼 여유가 없네만, 정 절실하다면 내게 생각이 하나 있지. 우린 아이언포지를 제외하고 최고의 대장장이들을 보유하고 있어. 그게 아무 소용이 없다면 내가 저주를 받겠지!\n\n던 알가즈의 남동쪽, 모단 호수의 폭포가 끝나는 곳에 은여울 동굴이 있네. 유령이 출몰해서 우리는 단 한 번도 원정대를 보내지 않았지만, 지금은 용기 있는 행동이 필요한 때지. 소문에 따르면 동굴 안에는 검을 거의 파괴 불가능하게 만들 만큼 강력한 광석이 있다고 해.\n\n동굴로 가게, $N. 내가 가진 가장 단단한 곡괭이를 주지; 용기 있는 마음으로 받길 바라네. 돌아오면 그 광석을 우리 무기 제작자 브라크 더나드에게 가져가게. 이곳 대장간 건물에서 그를 찾을 수 있을 거야.",
    },
    [26809] = {
        ["T"] = "남녘해안 방어",
        ["O"] = "",
        ["D"] = "",
    },
    [26810] = {
        ["T"] = "남녘해안 방어",
        ["O"] = "청동, 철, 강철, 그리고 유령이 깃든 무기 상자들을 언덕마루 구릉지 남녘해안의 탈렌 대장에게 가져가십시오.",
        ["D"] =
        "좋아, 여기 네가 가져온 유령이 깃든 광석으로 만든 다양한 무기 상자가 있다. 내가 기대했던 것과는 조금 다르네. 이 재료는 밀도가 부족해서 단순한 검을 만드는 데 예상보다 훨씬 많은 양을 써야 했어.\n\n이러고 싶진 않았지만, 저기 있는 상자들도 가져가. 저것들은 청동, 철, 강철 무기들로 꽉 차 있고, 원래는 스팀휘들 항구에 팔러 갈 예정이었지. 남녘해안이 더 중요하잖아. 자, 가봐!",
    },
    [26811] = {
        ["T"] = "남녘해안 방어",
        ["O"] = "남녘해안 북서쪽에 있는 언덕마루 농장의 경비병 트리스탄과 대화하십시오.",
        ["D"] =
        "이 무기들을 즉시 배분하기 시작하겠습니다. 그동안 당신은 언덕마루 농장에 필요합니다. 증원군 요청을 받았는데, 편지 내용을 보면 임박한 침략에 대한 것은 아닌 것 같았습니다. 우리는 남녘해안의 방어를 준비하느라 바쁠 테니, 당신이 저희를 대신해 가서 무엇이 필요한지 알아보셔야겠습니다.\n\n농장에 도착하면 시청 근처에 있는 경비병 트리스탄과 대화하십시오. 위치를 잊어버리셨다면, 남녘해안에서 길을 따라 정서쪽으로 향하기만 하면 농장에 도착할 수 있습니다. 신의 가호가 있기를, $N.",
    },
    [26812] = {
        ["T"] = "하루에 사과 한 개",
        ["O"] =
        "언덕마루 농장의 과수원에서 사과를 모은 다음, 언덕마루 농장 북쪽 끝에 있는 덩굴시렁 아래 사과 압착기로 가져가서 사과 사이다를 짜내십시오. 그 후, 사과 사이다를 사과 압착기 근처의 통에 부으십시오.",
        ["D"] =
        "증원군 요청을 감안하면 이 임무가 이상해 보일 수 있지만, 식량과 물은 무기와 방어구만큼이나 우리의 안전에 중요합니다. 언덕마루 농장은 사과와 사과 사이다의 주요 수출처인데, 호드의 공격으로 일정이 지연되고 있습니다.\n\n과수원으로 나가 사과를 좀 수집한 다음, 농장 북쪽 끝 덩굴 캐노피 아래에 있는 사과 압착기로 향하여 사이다를 좀 만드십시오. 다 끝나면 통에 보관하십시오. 걱정하지 마십시오, 수고비는 보상해 드리겠습니다.",
    },
    [26813] = {
        ["T"] = "호드 접근 금지",
        ["O"] = "언덕마루 농장 외곽에서 호드 정찰병 6명을 처치하십시오. 완료하면 언덕마루 구릉지의 언덕마루 농장에 있는 경비병 트리스탄에게 보고하십시오.",
        ["D"] =
        "호드 정찰병들이 우리 들판 외곽에서 여러 번 목격되었습니다. 놈들이 들키고 싶어 안달이 났는지, 아니면 그저 임무를 못 하는 건지 모르겠지만, 어쨌든 놈들을 처리해야 합니다. 정찰병 몇 명을 죽일 수 있다면 다른 놈들은 도망치거나 언덕마루 농장이 그렇게 쉬운 표적이 아니라고 보고할 마음이 생길 겁니다.\n\n행운을 빕니다.",
    },
    [26814] = {
        ["T"] = "갈등의 들판",
        ["O"] = "언덕마루 농장 내에서 호드 플레이어 1명을 처치하십시오.",
        ["D"] =
        "순찰을 도는 동안, 호드 모험가들을 주시하십시오. 그들은 때때로 이 지역에서 목격되며, 우리 병력과 농부들을 학살하고 있습니다. 그들과 교전하여 제거하는 것이 당신의 의무입니다. 이 임무를 완수하면 제게 보고하십시오.",
    },
    [26815] = {
        ["T"] = "남녘해안 방어",
        ["O"] = "언덕마루 구릉지 남녘해안의 탈렌 대장과 대화하십시오.",
        ["D"] =
        "당신을 이곳으로 보낸 것에 사과드립니다. 저는 경비병이 더 오기를 바라고 있었습니다. 당신 정도의 실력을 갖춘 분이 제게 오리라곤 생각지 못했고, 그 점을 남녘해안의 탈렌 대장님께 전달하는 것이 좋겠습니다.\n\n다음 보고서를 작성할 때 당신에 대해 좋은 말을 꼭 써두겠습니다. 앞으로의 모험에 행운을 빕니다, $N.",
    },
    [26816] = {
        ["T"] = "남녘해안 방어",
        ["O"] = "언덕마루 구릉지 남녘해안에 있는 사우스쇼어 포고꾼과 대화하고 호드의 공격으로부터 남녘해안을 방어하십시오.",
        ["D"] =
        "신뢰할 수 있는 보고에 따르면 호드가 곧 타격할 것이라고 합니다. 이제 우리의 준비가 시험받을 때입니다!\n\n당신에게 필요한 마법, 무기 연마, 마법 강화 등을 통해 대비하십시오. 준비가 되면 우리 그리핀 조련사 달라 근처에 있는 사우스쇼어 포고꾼에게 보고하십시오. 얼라이언스를 위하여!",
    },
    [26817] = {
        ["T"] = "완수되지 않은 정의",
        ["O"] = "알터랙 산맥의 로다미어 호숫가에 있는 그의 집에서 폴 \"할아버지\" 비샤스를 찾아 정의의 심판을 받게 하십시오.",
        ["D"] =
        "제가 집정관이 되었을 때 폴 비샤스에 대한 미집행 영장이 있다는 것을 발견했습니다. 비샤스는 거의 20년 전에 저지른 살인 사건으로 수배 중이더군요. 왜 이 영장이 집행되지 않았는지 모르겠습니다; 폴 비샤스는 수년 동안 이 지역에서 목격되었으니까요.\n\n그의 아들 시드니는 로다미어 호숫가에 집이 있습니다. 어쩌면 비샤스가 거기에 숨어 있는 건 아닐까요?\n\n제발 그를 체포해 주십시오 $C. 만약 그가 조용히 순응하지 않는다면, 당신이 정의를 집행하여 이 사건을 장부에서 지워버려도 좋습니다.",
    },
    [26818] = {
        ["T"] = "만을 가로지르는 노",
        ["O"] = "저습지의 메네실 항구 다리 동쪽에 있는 앤드류 포터(Andrew Porter)와 대화하십시오.",
        ["D"] =
        "남녘해안에 가본 적이 있소, $C? 대륙에 아직 남아 있는 얼라이언스의 최북단 도시 중 하나요. 남녘해안은 붐비는 항구였소, 무슨 일이 있었는지는 모르겠지만. 바위와 기타 말도 안 되는 것들 때문에 여기서 남녘해안까지 배가 지나가는 데 어려움이 있다는 소문을 들었소.\n\n어쨌든, 이 포터 형제들이 우리 두 도시 사이에 작은 배편을 마련했소. 언덕마루로 가는 여행을 찾고 있다면 다리 근처에 있는 앤드류 포터와 대화해 보시오.",
    },
    [26819] = {
        ["T"] = "이 땅에서 퓨마 몰아내기",
        ["O"] = "굶주린 퓨마 10마리를 처치하고 남녘해안의 치안대장 레드패스에게 돌아가십시오.",
        ["D"] =
        "자네가 와줘서 다행이군, $c. 최근 이 주변의 퓨마들이 안절부절못하며 우리 시민 여럿을 다치게 했지. 조치를 취해야 하네!\n\n남녘해안의 시민들이 다시 안전해질 수 있도록 자네가 이 지역의 퓨마 무리를 쓸어버려 주었으면 해. 놈들은 주로 이 북쪽을 배회하지.",
    },
    [26820] = {
        ["T"] = "언덕마루 강습",
        ["O"] = "중앙 경비탑이 얼라이언스 통제하에 있을 때 점령하십시오.",
        ["D"] =
        "언덕마루 중심에 있는 탑은 호드가 이 땅을 지배하는 데 핵심적이다. 밴시 여왕님께서 친히 명령하시길, 얼라이언스가 탑을 점령할 때마다 우리가 시급히 되찾아야 한다고 하셨다.\n\n병력을 집결하라 $n, 그리고 그녀가 명한 대로 행하라.",
    },
    [26821] = {
        ["T"] = "언덕마루 방어",
        ["O"] = "중앙 경비탑이 호드 통제하에 있을 때 방어하십시오.",
        ["D"] =
        "언덕마루 중심에 있는 탑은 호드가 이 땅을 지배하는 데 핵심적이다. 밴시 여왕님께서 친히 명령하시길, 얼라이언스가 탑을 점령하려고 시도할 때마다 무슨 수를 써서라도 지켜내야 한다고 하셨다.\n\n병력을 집결하라 $n, 그리고 그녀가 명한 대로 행하라.",
