    [26822] = {
        ["T"] = "언덕마루 강습",
        ["O"] = "중앙 경비탑이 호드 통제하에 있을 때 점령하십시오.",
        ["D"] =
        "언덕마루 중심에 있는 탑은 얼라이언스가 이 땅을 지배하는 데 핵심적입니다. 프레스톨 영주님께서 친히 명령하시길, 호드가 탑을 점령할 때마다 우리가 시급히 되찾아야 한다고 하셨습니다.\n\n병력을 집결하세요 $n, 그리고 그녀가 명한 대로 행하십시오.",
    },
    [26823] = {
        ["T"] = "언덕마루 방어",
        ["O"] = "중앙 경비탑이 얼라이언스 통제하에 있을 때 방어하십시오.",
        ["D"] =
        "언덕마루 중심에 있는 탑은 얼라이언스가 이 땅을 지배하는 데 핵심적입니다. 프레스톨 영주님께서 친히 명령하시길, 호드가 탑을 점령하려고 시도할 때마다 무슨 수를 써서라도 지켜내야 한다고 하셨습니다.\n\n병력을 집결하세요 $n, 그리고 그녀가 명한 대로 행하십시오.",
    },
    [26824] = {
        ["T"] = "현상 수배: 대마법사 자이고르(Archmage Zygor)",
        ["O"] = "던홀드 요새에 있는 대마법사 자이고르를 처치하십시오. 타렌 제분소의 고위집행관 다살리아에게 돌아가 보상을 받으십시오.",
        ["D"] =
        "실바나스 님의 권한으로, 자이고르라고 알려진 대마법사를 즉각 처형한다. 자이고르는 비밀결사대라는 위험한 조직에 흑마법을 훈련시키고 지시한 죄를 지었다.\n\n그는 던홀드 요새, 마법사 탑에 있을 가능성이 크다. 그들의 만행에 대한 증거를 고위집행관 다살리아에게 가져오는 자에게는 두둑한 보상을 내릴 것이다.",
    },
    [26825] = {
        ["T"] = "비밀결사대 마법",
        ["O"] = "비밀결사대 보주 5개를 수집하여 남녘해안의 핀 오델릭에게 돌아가십시오.",
        ["D"] =
        "나는 마법의 예술을 연구하고 항상 그것에 대해 더 많은 것을 배우고자 노력하지. 집정관은 비밀결사대가 사악한 계획의 연료로 흑마법을 사용하고 있다고 믿지만, 난 의심스럽다네.\n\n던홀드 요새로 가서 놈들의 마법사들이 사용하는 보주를 좀 가져다줄 텐가? 요새는 여기서 북동쪽에 있지만 조심하게... 경비가 아주 삼엄하다고 들었네.",
    },
    [26826] = {
        ["T"] = "비밀결사대 인원",
        ["O"] = "비밀결사대 도적 5명과 비밀결사대 감시원 5명을 처치하십시오. 임무를 마치면 타렌 제분소의 고위집행관 다살리아에게 돌아가십시오.",
        ["D"] =
        "어둠의 여왕님께서 비밀결사대의 모든 단원을 제거하라고 명령하셨다. 놈들은 약자를 먹잇감으로 삼고 모두의 것을 훔치는 위험한 폭력배 무리다.\n\n놈들 중 한 무리가 현재 이 남동쪽의 탑을 점거하고 있다. 길을 따라 남쪽으로 가다가 갈림길에서 왼쪽으로 돌면 탑을 찾을 수 있을 것이다. 최대한 많이 죽여라, $N - 놈들이 무슨 꿍꿍이인지 누가 알겠느냐.",
    },
    [26827] = {
        ["T"] = "던홀드 박멸",
        ["O"] = "비밀결사대 작업반장 10명과 비밀결사대 감독관 10명을 처치하십시오. 임무를 마치면 타렌 제분소의 고위집행관 다살리아에게 돌아가십시오.",
        ["D"] =
        "자네에게 맡길 임무가 하나 더 있다, $n. 비밀결사대가 이제 여기서 남동쪽에 있는 던홀드 요새를 장악했다. 이 땅을 깡패들로부터 안전하게 지키는 것이 호드의 최우선 과제이니, 이 땅에서 놈들의 쓰레기 같은 흔적을 깨끗이 씻어내야 한다.\n\n던홀드 요새를 찾으려면, 자네가 찾은 탑을 지나서 길을 계속 따라가면 된다. 같은 길에서 요새를 찾을 수 있을 것이다.",
    },
    [26828] = {
        ["T"] = "진흙주둥이 혼합물",
        ["O"] = "진흙주둥이 영액 8개를 수집하여 남녘해안의 난다르 브랜슨에게 돌아가십시오.",
        ["D"] =
        "던홀드 요새로 이주한 비밀결사대는 우리 들판을 약탈하는 것으로 악명이 높아 어떤 조치든 취해야 합니다. 남녘해안 경비대의 노력만으로는 역부족일까 우려되어, 포세이큰의 수법을 빌려 비밀결사대의 식량 공급원에 독을 타기로 결정했습니다!\n\n가혹하게 들릴지 모르지만, 절박한 상황에는 절박한 조치가 필요합니다. 절 돕고 싶다면 여기서 동쪽, 강 건너 네산더 농장에 있는 놀들에게서 영액이 필요합니다. 그걸 손에 넣으면 비밀결사대의 활동을 늦출 수 있는 효과적인 독을 만들 수 있습니다!",
    },
    [26829] = {
        ["T"] = "비밀결사대를 위한 맹독",
        ["O"] = "던홀드 요새에 있는 비밀결사대 식량 보급품에 독을 타고 남녘해안의 난다르 브랜슨에게 돌아가십시오.",
        ["D"] =
        "독이 준비되었습니다, $N. 투여해 줄 사람이 필요할 뿐입니다. 던홀드 요새는 북동쪽으로 길만 따라가면 찾을 수 있습니다. 하지만 주의하십시오. 비밀결사대는 자신들의 근거지를 철통같이 보호하니 친구들과 함께 가는 것이 좋습니다.\n\n안으로 들어가면 놈들의 병영을 찾으십시오. 분명 그 안에 놈들의 식량 보급품이 있을 것입니다. 보급품 주변에 맹독을 뿌리고 이리로 돌아오십시오.",
    },
    [26830] = {
        ["T"] = "현상 수배: 베브 페레놀드(Beve Perenolde)",
        ["O"] = "베브 페레놀드를 처치하고 그녀의 머리를 남녘해안의 탈렌 대장에게 가져가십시오.",
        ["D"] =
        "남녘해안 탈렌 대장의 명에 따라, 베브 페레놀드에게 사형이 선고되었습니다. 그녀는 위험한 범죄자이자 던홀드 요새의 감독관으로 이 땅에서 비밀결사대를 철권 통치하고 있습니다.\n\n그녀는 남녘해안 북동쪽에 있는 요새의 성채 깊은 곳에서 발견될 가능성이 큽니다. 그녀의 머리를 탈렌 대장에게 가져가면 보상을 받을 것입니다.",
    },
    [26831] = {
        ["T"] = "비밀결사대 계획",
        ["O"] = "비밀결사대 계획서를 남녘해안의 탈렌 대장에게 배달하십시오.",
        ["D"] =
        "당신은 베브 페레놀드의 주머니에서 떨어지는 편지를 발견합니다. 봉인되어 있으며 앨리덴 페레놀드 경에게 보내는 주소가 적혀 있어 중요한 편지인 것 같습니다.\n\n남녘해안의 탈렌 대장이라면 비밀결사대의 향후 계획이 상세히 적혀있을지도 모르는 이 편지에 큰 관심을 가질 것입니다.",
    },
    [26832] = {
        ["T"] = "비밀결사대 계획",
        ["O"] = "비밀결사대 계획서를 타렌 제분소의 고위집행관 다살리아에게 배달하십시오.",
        ["D"] =
        "당신은 베브 페레놀드의 주머니에서 떨어지는 편지를 발견합니다. 봉인되어 있으며 앨리덴 페레놀드 경에게 보내는 주소가 적혀 있어 중요한 편지인 것 같습니다.\n\n타렌 제분소의 고위집행관 다살리아라면 비밀결사대의 향후 계획이 상세히 적혀있을지도 모르는 이 편지에 큰 관심을 가질 것입니다.",
    },
    [26833] = {
        ["T"] = "야생가시 치료제(Wildthorn Cure)",
        ["O"] = "잿빛 골짜기에 있는 거미들에게서 야생가시 연고 8개를 수집하여 남녘해안의 제나 선더브루에게 돌아가십시오.",
        ["D"] =
        "내 남편이 많이 아파요, $N. 제가 아는 모든 치료법을 시도해 봤지만 아무 소용이 없네요.\n\n얼마 전 이곳을 지나가던 여행자가 머나먼 땅에 사는 거미에 대해 말해줬어요. 그 거미들은 아무리 심한 상처라도 치료할 수 있는 연고를 만들어낼 수 있대요.\n\n그의 말로는 이 거미들을 야생가시라고 불렀고, 칼림도어라는 먼 대륙의 잿빛 골짜기에 숨어 산다고 했어요. 당신에게 부탁하기에는 너무 과분한 일이지만, 만약 칼림도어로 여행을 가신다면 제 남편을 고칠 수 있도록 야생가시의 연고를 좀 가져다주시겠어요?",
    },
    [26834] = {
        ["T"] = "제나 지원하기",
        ["O"] = "언덕마루 구릉지에서 제나 선더브루를 찾으십시오.",
        ["D"] =
        "현지 치유사인 제나 선더브루로부터 긴급한 편지를 받았습니다. 남편이 병에 걸려 긴급한 도움이 필요하다고 합니다.\n\n남녘해안은 시민들을 도우므로 당신이 가서 그녀를 확인해 주어야겠습니다. 그녀는 바로 서쪽에 있는 공터에 있는 그녀의 오두막에 삽니다.",
    },
    [26835] = {
        ["T"] = "정기의 깨달음",
        ["O"] = "고를룬드 스노우비어드(Gorlund Snowbeard)를 위해 바람, 불, 대지, 물의 샘플을 각각 수집하십시오.",
        ["D"] =
        "와일드해머 부족의 고를룬드 화이트비어드(Gorlund Whitebeard)가 자네만 한 능력을 갖춘 주술사를 부르는 전갈을 보냈네. 자네가 준비가 되었음을 증명하기 위해 각각의 정령 샘플을 가져오라고 하더군.\n\n맹금의 봉우리에서 그를 찾을 수 있네.",
    },
    [26836] = {
        ["T"] = "수호 영혼",
        ["O"] = "고를룬드 스노우비어드를 위해 두꺼운 검은 발톱과 붉은눈 거미 눈알을 모으십시오.",
        ["D"] =
        "동부 내륙지의 사악한 트롤 놈들은 비열한 정령 마법으로 봉우리를 공격한다네. 놈들의 영혼을 쫓아낼 토템을 만드는 데 필요한 게 뭔지는 알지만, 난 더 이상 젊은 드워프가 아니거든.\n\n여기서 동쪽 길을 따라 신디거의 야영지로 올라간 다음 북쪽으로 가면 지금 서부 역병지대라고 불리는 곳에 도착할 수 있지. 거기서 수호 토템을 만들기 위해 흑곰 발톱과 거미 눈알 몇 개를 구해야 해. 생각해보니 청소부 동물을 잡아먹고 사는 놈들에게서도 구할 수 있을지 모르겠군.",
    },
    [26837] = {
        ["T"] = "트롤 마법",
        ["O"] = "가라앉은 사원에서 호박색, 푸른색, 녹색 부두 깃털을 모으십시오.",
        ["D"] =
        "가아! 이건 충분히 강하지 않아! 이래서는 안 될 거란 걸 알았어야 했는데. 트롤 놈들의 저주받은 부두교 자체로만 그들의 정령 마법에 대항할 수 있다네.\n\n남쪽 멀리, 슬픔의 늪에 가라앉은 사원이라는 곳이 있어. 마이잔, 졸로, 줄로, 로로, 게이셔, 후쿠로 알려진 트롤들은 그들의 끔찍한 부두 마법이 스며든 깃털을 지니고 다니지. 이 해충 놈들을 처치하고, 그 깃털을 가져다주게.",
    },
    [26838] = {
        ["T"] = "적절한 전송",
        ["O"] = "은여울 광산에서 본두르의 뼈를 회수하여 텔사마의 야니 스타우트하트에게 돌아가십시오.",
        ["D"] =
        "제 남편 본두르는 이곳 북쪽에 있는 은여울 광산에서 일하던 광부였습니다. 가족을 부양하기 위해 열심히 땀 흘리던 다정한 사람이었죠.\n\n그런데 트로그들이 나타나 광산에 있던 사람들에게 자비를 베풀지 않았습니다. 사랑하는 제 본두르는 갈기갈기 찢기고 말았죠.\n\n저는 남편의 죽음을 받아들였지만, 그의 뼈는 아직 광산에 남아 있습니다. 남편을 이곳 묘지에 제대로 묻어주고 싶어요.\n\n비탄에 빠진 미망인을 도와주시겠습니까, $N? 은여울 광산에 가셔서 본두르의 뼈를 수습해 텔사마 묘지에 묻어 주실 수 있나요?",
