    [26839] = {
        ["T"] = "호드 보고서",
        ["O"] = "호드 보고서를 텔사마로 가져가서 그 내용에 관심 있을 만한 사람을 찾으십시오.",
        ["D"] =
        "죽은 오크의 시체에서 공식적으로 보이는 보고서를 발견합니다. 누군가 이 보고서를 보는데 관심이 있을 거라 확신하지만, 누구일까요?\n\n텔사마에는 다수의 아이언포지 경비병들이 있습니다. 그들 중 누군가가 분명히 이 일을 처리할 적임자일 것입니다.",
