    [26840] = {
        ["T"] = "호드 사절",
        ["O"] = "모단 호수와 저습지 사이의 산길에 득실거리는 용아귀 오크들 사이에서 호드 사절을 찾아 제거하십시오.",
        ["D"] =
        "이 보고서는 제가 모르는 호드 사절에게 수신인이 되어 있지만, 이 자가 모단 호수와 저습지 사이의 언덕으로 이주한 용아귀 오크들과 협상을 시도하고 있는 것 같군요. 상상이나 됩니까?! 호드가 우리 턱밑에 있다니!\n\n이런 협상이 성사되게 내버려 둘 순 없습니다, $N. 저습지로 이어지는 길을 따라 남쪽으로 여행하여 용아귀 야영지에서 이 사절을 찾으십시오. 우리의 약점에 대해 보고할 수 없도록 그를 제거하십시오!",
