        ["O"] = "아이언밴드의 발굴현장에서 잃어버린 유물 5개를 회수하여 모단 호수의 알드렌 코든에게 돌아가십시오.",
        ["D"] =
        "망할 트로그 놈들, 항상 일을 망친다니까! 그놈들이 오기로 결정하기 전까지 우리는 완벽하고 훌륭하게 발굴을 진행 중이었소. 왜 항상 이런 일이 나한테만 일어나는 거람?\n\n대피를 서두르는 바람에, 발굴현장에 귀중한 유물 몇 개를 두고 왔지. 마그니 전하께서 친히 이 발굴을 명하셨는데, 그 유물들을 잃어버리면 우린 큰 곤경에 처할 거요! 우리를 위해 그것들을 좀 되찾아 주시지 않겠소?",
