    [26842] = {
        ["T"] = "의약품 보충",
        ["O"] = "대호수(The Loch)에서 호수풀(Loch Weed) 8개를 채집하여 텔사마의 칼리 힐터치에게 돌아가십시오.",
        ["D"] =
        "여기 와줘서 정말 기뻐요, $N! 의약품이 부족해서 도움이 필요하거든요.\n\n트레샤돈들이 더 공격적으로 변한 이후로, 물속에서 자라는 호수풀을 구하기가 점점 더 힘들어졌어요. 경비병들은 그것을 구하러 대호수까지 가는 것을 거부하고 있고요. 제 물약을 보충할 수 있도록 당신이 용기를 내어 좀 가져다주실 수 있나요?",
    },
    [26843] = {
