        ["D"] =
        "그래, 해야 할 일이 있지, $c. 경비병으로서 내 일은 땅뿐만 아니라 물도 감시하는 것이라네!\n\n대호수에 위험이 도사리고 있고, 그게 이 지역에 골칫거리를 만들고 있지. 대호수에 서식하는 트레샤돈들이 최근 공격적으로 변했는데, 마치 무언가가 놈들을 자극한 것 같아. 바로 얼마 전에 이곳 텔사마 주민 중 한 명이 낚시를 하다가 놈들 중 한 마리에게 죽을 뻔했어! 자네가 가서 놈들의 개체 수를 좀 줄여줘야겠네, 그래야 대호수가 우리 사람들에게 다시 안전해질 테니까.",
    },
    [26844] = {
        ["T"] = "기묘한 우상",
        ["O"] = "이 기묘한 우상을 아이언포지 내 탐험가의 전당에 있는 발굴조사단장 스톰파이크에게 가져가십시오.",
        ["D"] =
        "트로그들이 광분한 이유를 알아내려면 이 우상들을 연구해 봐야겠지만, 보세요... 이 우상은 다른 것들과 다릅니다.\n\n이건 뭔가 이상해요. 정확히 짚어 말할 수는 없지만요. 같은 양식임에도 다른 것들보다 새것처럼 보이는데, 마치 이 장소가 우리가 처음 추정한 것보다 더 오랫동안 사용된 것처럼 말이죠.\n\n이건 제 수준 밖의 일입니다. 이걸 아이언포지에 있는 발굴조사단장 스톰파이크에게 가져가 보는 건 어떨까요? 그에게 당신의 도움으로 우리가 약간의 진전을 이루었다는 것도 보여주고요.",
