        ["D"] =
        "텔사마 집정관의 명령에 따라:\n\n대호수를 배회하는 위험한 트레샤돈에게 붙여진 별명인 대모 테사에게 사형을 선고한다. 몇 차례의 끔찍한 사망 사고가 발생한 후, 시민들은 이 위협이 해결될 때까지 대호수에서 낚시하지 말 것을 경고받았다.\n\n대모 테사에 걸린 현상금을 청구하려는 모험가들은 그녀가 일반 트레샤돈보다 훨씬 크고 강하다는 점을 경고하는 바이다. 그녀의 죽음에 대한 증거를 텔사마에 있는 집정관 블런트노즈에게 제시하면 보상이 제공될 것이다.",
