        ["D"] =
        "거기, 안녕 친구!\n\n당신은 믿지 않겠지만, 난 바로 이곳 붉은마루에서 첫 살육을 경험했지. 사실 녀석은 지금 우리가 말하는 이 순간에도 바로 우리 위에 걸려 있다고! 아, 추억이여... 내가 때때로 여기 돌아오는 걸 좋아하는 이유가 바로 이거지. 물론 내 최근 승리에 비하면 아무것도 아니지만, 누구나 처음은 있는 법이니까!\n\n그건 그렇고, 자네가 자신을 증명하고 싶다면 꽤 흥미로운 도전거리를 주지. 이 지역에 있는 모든 종류의 멀록을 처치했는지 확인해 봐. 이 끈적끈적한 물고기 인간들은 다양한 종류가 있어서 상대하려면 각각 약간씩 다른 접근 방식이 필요할 거야. 네 다재다능함을 증명할 절호의 기회지!\n\n게다가 녀석들의 수가 늘어나고 있다는 보고가 있으니, 자네가 이 마을의 훌륭한 사람들에게 호의를 베푸는 일이기도 하고!\n그래서 어떻게 할 텐가, 도전을 받아들이겠나?",
