        ["D"] =
        "또 다른 도전을 위해 돌아왔군, 그렇지? 그럼 단단히 준비해 파트너. 왜냐하면 이 녀석은 대충 핥고 약속한다고 쓰러질 놈이 아니거든!\n\n놈의 이름은 진창발 아르도, 이 근방에서 아주 큰 소란을 일으킨 녀석이지. 녀석의 흔적을 레이크샤이어 뒤편 언덕 북쪽에 있는 동굴까지 추적했어. 네가 놈의 그 유명한 앞발을 내게 가져오면 도전에 성공한 것으로 간주하고, 내 유명한 사냥 용품 중 일부를 상으로 주지!\n행운을 비네!",
