        ["D"] =
        "저기, 부탁 하나 해도 될까요? 클라이드 랜덜이 파는 특별한 실타래를 구하고 싶은데, 그가 붉은마루 가장 동쪽 산에 가게를 차렸거든요. 오크와 놀 때문에 제가 직접 가기에는 길이 너무 위험해졌지만, 당신이라면 해낼 수 있을 것 같군요!\n\n그의 평소 판매 물품에선 찾을 수 없을 테니, 특별한 실에 대해 분명하게 물어봐야 해요. 실을 사는 데 든 비용은 제가 부담하고, 수고비도 넉넉히 얹어 드릴게요.",
