        ["D"] =
        "내 특별한 실? 이렇게 하지. 일갈라의 탑 근처를 순찰하는 저 악랄한 놀 놈들을 처리하는 걸 도와주면 공짜로 주지!\n\n우리는 여기서 성공적인 사업을 운영하려고 하는데, 저 망할 짐승들이 최근 들어 엄청난 골칫거리를 만들고 있어. 놈들은 상업에 대한 존중이 전혀 없는 것 같아!",
