        ["D"] =
        "끔찍한 소식입니다, $N! 우리 연대 중 하나가 검은바위 오크의 매복에 당했습니다. 살아서 돌아온 병사는 거의 없고 많은 이들이 실종되었습니다. 이 사악하고 잔혹한 행위를 처벌하지 않고 넘어갈 수는 없지만, 반격에 투입할 병력이 부족하고 사기도 떨어져 있습니다.\n\n당신의 도움이 필요합니다. 검은바위 부족은 자신들의 공격에 대가가 따른다는 것을 알아야 합니다. 가장 아픈 곳을 찔러 적에게 전술적 타격을 가해야 합니다, $N. 그들의 추적자와 소환사들을 제거하십시오. 그러면 또 다른 매복을 준비하기가 몹시 어려워질 것입니다.\n\n불타는 평원으로 향하는 길 바로 서쪽, 북쪽에 있는 그들의 야영지에서 놈들을 찾을 수 있을 겁니다.",
