        ["D"] =
        "이글거리는 협곡에 있는 검은무쇠 드워프들이 우리가 떨어뜨린 보급품을 훔쳐 달아났다는 보고를 받았소. 황야의 땅에 교두보를 유지하려면 그 보급품이 필요하오.\n\n카르가스 바로 남쪽 고개를 지나 서쪽으로 향하면 이글거리는 협곡 중심부에서 가마솥과 화산바위 구덩이에 있는 검은무쇠 광산을 찾을 수 있을 거요. 가능한 한 많은 보급품 상자를 회수하시오.",
