        ["O"] = "북서쪽 이글거리는 협곡의 황혼의 야영지에서 황혼의 불꽃경비병 8명과 황혼의 흙점쟁이 8명을 처치하십시오.",
        ["D"] =
        "토륨 대장합회는 황혼의 망치단이 검은바위 산 깊은 곳 어둠괴철로 도시에 있는 우리 형제들에게 사절을 보냈다는 소식을 들었쉬. 이 라그나로스의 하수쉿들은 오랫동안 잠들어 있던 옛 힘을 위한 동맹을 구하고 잇쉬며, 토륨 대장합회는 그들이 이글거리는 협곡에 발판을 마련하도록 내버려 두지 않을 것이야!\n\n이 이교도들을 죽이고 그들의 솨악한 의슈...*딸꾹*...의슈...*딸꾹*...의식을 끝내주쉬게.",
