    [26855] = {
        ["T"] = "황혼의 전술",
        ["O"] = "이글거리는 협곡 북서쪽에 있는 황혼의 이교도 동굴에서 의식용 제단을 수색하고 어둠괴철로 도시에서 도난당한 타우릿산 유물을 회수하십시오.",
        ["D"] =
        "오래전, 우리 황제 타우릿샨의 슈상들은 끔찍한 마법을 통해 라그나로스를 이고슈로 불러왔지. *딸꾹* 난 황혼의 망치단이 그를 다시 깨우려 할까 봐 두렵쉬.\n\n어둠괴철로 도시에 있던 그들의 사절들이 한때 마술사 영주 타우릿샨의 소유였던 유물을 밀반출했어. 그들이 그걸로 무얼 할 계획인지는 모르지만...*딸꾹*... 그게 동굴 안 의식 장소에 보관되어 있다고 믿쉬. 자네가 잠...*딸꾹*...조샤...*딸꾹*... 이 유물을 되찾아주게.",
    },
    [26856] = {
        ["T"] = "황혼의 전술",
        ["O"] = "황혼의 사절 모가리(Mo'gali)와 감독관 웨프트 간의 만남을 방해하고 그들이 가지고 있는 문서를 모두 회수하십시오.",
        ["D"] =
        "내 정봇망에 따르면 황혼의 망치단 솨절과 가마솥 감독관 중 한 명 사이에 이 근처에서 접선이 있을 거라고 하쉬. 우리는 그 접선을 방해하고 그 반역자놈들이 가진 문셔를 모두 회수해야 해.\n\n내 정보에 따르면 접선은 여기서 남동쪽, 검은바위 산 입구 근처의 검은재 동굴에서 이루어질 것이라네. 낭비할 시간이 없어, $C! *딸꾹*",
