    [26857] = {
        ["T"] = "문서를 아이언포지로!",
        ["O"] = "황혼의 동맹 문서를 아이언포지에 있는 메리다 스타우트포지에게 가져가십시오.",
        ["D"] =
        "이제 이 문서들을 확보했으니...<*딸꾹*>... 아이언포지의 메리다 슈타우트포지에게 가져가 주었으면 해. 그녀는 왕을 알현하기 위해 기다리고 있고 이 문서가 그녀의 주장에 도움을 줄 거쉬야.",
    },
    [26858] = {
        ["T"] = "토륨 대장합회",
        ["O"] = "이글거리는 협곡 토륨 거점에 있는 감시대장 롤로 롱스트라이커와 대화하십시오.",
        ["D"] =
        "$C! 그래, 당신이오! 제발 아이언포지의 수많은 사람들처럼 나를 무시하지 마시오.\n\n난 이글거리는 협곡의 토륨 대장합회 수비대에서 왔소. 검은무쇠 부족과 브론즈비어드 부족 간의 관계가 긴장 상태이긴 하지만, 어둠괴철로 도시에는 황혼의 망치단과 손을 잡기 시작한 자들이 있소. 마그니 국왕님께 경고해야 하는데, $C 내 알현 일정이 계속 미뤄지고 있소.\n\n지금 당장 토륨 거점에 도움이 필요하오! 당신이 모험가 타입이라면 감시대장 롤로 롱스트라이커를 찾아서 당신의 서비스를 제공하시오.",
