    [26859] = {
        ["T"] = "타락한 원소",
        ["O"] =
        "이글거리는 협곡의 그을린 오염물(Muck Splash)에서 타락한 물의 핵, 불지옥 정령에서 타락한 불의 핵, 용암 정령에서 타락한 대지의 핵, 연기 정령(Smoke Elemental)에서 타락한 바람의 핵을 수집하십시오.",
        ["D"] =
        "조심해, $R. 여긴 성난 땅이야. 이백 년 전 검은바위 산을 만들어낸 지각 변동이 이곳의 원소 세력들을 알아볼 수 없을 정도로 타락시켰을지도 몰라.\n\n라그나로스 출현의 트라우마가 이 협곡의 토착 정령들에게까지 스며든 것 같아 두렵다. 내가 정령들을 연구할 장비를 챙기는 동안, 누군가 각 종류의 정령들에게서 핵을 수집해 여기로 가져다줄 사람이 필요해. 네가 그 사람이 되어주겠나?",
