        ["D"] =
        "검은무쇠 드워프들은 검은바위 산 깊은 곳 어둠괴철로 도시의 본거지를 떠나는 일이 드문데, 어떤 이유에서인지 서쪽 국경 너머 이글거리는 협곡에 있는 검댕가루 작업현장에 지질학자 팀을 보냈어. 그곳에서 일하던 아이언포지의 발굴 팀도 쫓아냈지!\n\n이 드워프들의 흥미를 끈 것이 무엇인지 알아야겠어. 가서 이 작업을 방해하고 그들이 수집하고 있는 유물 상자를 하나 가져오도록 해.",
