        ["O"] = "검댕가루 발굴로 인해 방해받은 정령들을 찾고, 그들의 이글거리는 정수 6개를 가져오십시오.",
        ["D"] =
        "검댕가루 작업현장이 오래전 죽은 생물들의 영혼을 방해한 것 같군요. 그들의 영혼이 이제 작업현장 남쪽 언덕과 평원을 배회하고 있습니다. 내 연구를 위해 이 존재들의 정수를 모아 주셨으면 합니다.\n\n걱정 마세요, 당신이라면 살아남을 수 있을 겁니다.",
