        ["D"] =
        "드문 기회가 찾아왔다, $c, 이 기회를 활용할 누군가가 필요하다.\n\n어둠괴철로 사서 빈데롤은 뛰어난 작가이자 악명 높은 은둔자이다. 어떤 이유에서인지 그가 화산바위 구덩이로 여행을 와서 그곳에 있는 검은무쇠 병영에 머물고 있다. 이것이 그의 \"타우릿산의 역사\" 필사본 사본을 얻을 유일한 기회일지도 모른다.\n\n그 책이 필요하다. 무슨 수를 써서라도 얻어라!",
