    [26863] = {
        ["T"] = "어둠괴철로 사서",
        ["O"] = "어둠괴철로 사서 빈데롤을 처치하고 타우릿산의 역사를 회수하여 아이언포지 탐험가의 전당에 있는 사서 메이 페일더스트에게 가져가십시오.",
        ["D"] =
        "드문 기회가 찾아왔네, $c, 이 기회를 활용할 누군가가 필요해.\n\n어둠괴철로 사서 빈데롤은 뛰어난 작가이자 악명 높은 은둔자라네. 어떤 이유에서인지 그가 화산바위 구덩이로 여행을 와서 그곳에 있는 검은무쇠 병영에 머물고 있지. 이것이 그의 \"타우릿산의 역사\" 필사본 사본을 얻을 유일한 기회일지도 모르네.\n\n폭력을 옹호하는 건 싫지만, 그 책이 필요하다네. 제발 나를 위해 그걸 가져다줄 방법을 찾아봐 주겠나?",
