    [26864] = {
        ["T"] = "노예상인도 기록을 남길까?",
        ["O"] = "검은무쇠 노예상인에게서 노예상인 기록을 얻은 다음, 이글거리는 협곡에 있는 부린드 스타우트포지에게 돌아가십시오.",
        ["D"] =
        "노예상인들에게 우리 가족에게 아주 중요한 사람이 납치되었고, 우린 그 사람을 되찾으러 여기까지 내려왔어. 가마솥에 있는 그 노예상인들 알지? 장담컨대 그놈들 노예 중 일부를 어떻게 했는지 기록해 둔 문서 같은 걸 가지고 있을 거야.\n\n놈들의 시체에서 나를 위해 뭔가를 찾을 수 있는지 알아봐 줘.",
    },
    [26865] = {
        ["T"] = "그람피의 이론",
        ["O"] = "이글거리는 협곡 북서쪽의 접선 장소를 찾으십시오. 사절들을 처치하고 노예상인 기록을 그람피 스타우트포지에게 가져가십시오.",
        ["D"] =
        "<그람피가 찌푸린 숱 많은 눈썹 사이로 당신을 쳐다봅니다.>\n\n황혼의 망치단이야. 전에도 북서쪽에서 노예상인들을 만나는 걸 본 적이 있지. 장담하건대 그들이 조만간 다시 만날 거야. 놈들을 죽이고 우리를 위한 물건이 있는지 확인해.\n\n<늙은 드워프가 생각에 잠겨 수염을 쓰다듬습니다.>",
    },
    [26866] = {
        ["T"] = "라이사",
        ["O"] = "불망루 마루에서 라이사를 구출한 다음, 이글거리는 협곡에 있는 부린드 스타우트포지에게 돌아가십시오.",
        ["D"] =
        "북서쪽 불망루 마루에 동굴이 있는데, 황혼의 망치단이 득실거리지. 그 개자식들이 틀림없이 라이사를 거기에 가둬놓고 희생시킬 날만 기다리고 있을 거야! 아니면 더 끔찍한 짓을 저지르거나...!\n\n그곳 동굴로 가서 그녀를 구출해! 내가 자리를 비워도 노예상인들이 그람피를 낚아채지 않을 거란 확신이 서면 널 따라가마.",
    },
    [26867] = {
        ["T"] = "고위 심문관",
        ["O"] = "검은바위 나락에서 고위 심문관 게르스탄을 처치한 다음, 이글거리는 협곡에 있는 그람피 스타우트포지에게 돌아가십시오.",
        ["D"] =
        "<그람피가 만족스러운 표정이라 짐작되는 얼굴로 당신을 쳐다봅니다.>\n\n잘했다. 라이사는 회복 중이야. 마을로 돌아가기 전에 내 아들과 내게 책 한 권 분량의 이야기를 해줬지. 짧게 말하자면 검은바위 나락의 구류장에 괴물이 하나 있다더군. 라이사는 그녀를 없애버리고 싶어 했지만, 지금 상태로는 무리지. 라이사는 네가 해낼 거라 확신하더군. 놈의 이름은 거스탄, 인간이지.\n\n어떠냐? 라이사가 하려던 일을 끝내고 보상을 받아라.",
    },
    [26868] = {
        ["T"] = "그람피 스타우트포지",
        ["O"] = "이글거리는 협곡 남서쪽 야영지에 있는 그람피 스타우트포지를 찾으십시오.",
        ["D"] =
        "그람피 스타우트포지는 드워프 치고도 나이가 많소. 그는 대장장이 장인이고 우리가 기억하는 한 토륨 대장합회의 일원이었소.\n\n최근에 그는 아들 부린드와 함께 남쪽으로 떠났소. 이유를 말해주진 않았지만, 아주 이상하게 행동했지. 가서 그가 하는 일에 도움이 필요하지 않은지 확인해 보시오.",
    },
    [26869] = {
        ["T"] = "사후의 해부학",
        ["O"] = "공동묘지의 연금술사 렌퍼럴은 돌연변이 머리 1개, 기형의 가슴 1개, 씹다 남은 팔 2개, 흉측한 다리 2개를 모아오길 원합니다.",
        ["D"] =
        "공동묘지는 자네의 도움이 필요하다네, $N! 우리 경비병들을 죽이는 위험한 회색곰이 있어. 우리의 무기와 마법으로도 그 짐승을 죽이지 못해서, 언더시티에서는 내게 그 짐승을 처치할 수 있는 누더기골렘을 만들라는 임무를 맡겼다네.\n\n누더기골렘은 살점들을 꿰매어 만든 돌연변이지. 안타깝게도 나는 신체 부위가 다 떨어져서, 자네가 모아주었으면 하네. 근처에 있는 늑대인간 중 하나의 머리, 놀의 가슴, 동쪽에 있는 언데드에게서 두 팔, 그리고 호숫가에 있는 멀록의 다리를 원하네.\n\n이것들을 내게 가져오면 누더기골렘을 꿰매기 위한 주문을 시작할 수 있네. 회색곰이 우리 경비병들을 더 죽이기 전에 서둘러 주게.",
    },
    [26870] = {
        ["T"] = "사후의 해부학",
        ["O"] = "공동묘지의 연금술사 렌퍼럴은 당신이 호박색 농장의 인간들에게서 농축된 피 10개를 모아오길 원합니다.",
        ["D"] =
        "자네가 가져온 신체 부위는 누더기골렘에 완벽하게 맞을 테지만, 한 가지가 더 필요하네. 자네가 외출한 동안, 마을에서 일어난... 상황 때문에 내가 가진 마지막 인간의 피를 써버려야 했지. 누더기골렘에 필요한 마지막 재료는 신선한 인간의 피라네.\n\n이 근처에서 가장 좋은 피는 호박색 농장의 인간들에게서 나오지. 이곳에서 남쪽 길을 따라가다가 마을을 향해 동쪽으로 향하면 호박색 농장을 찾을 수 있을 거야. 하지만 조심하게, 그 인간들은 지난번에 꽤나 강렬하게 반항했거든!",
    },
    [26871] = {
        ["T"] = "사후의 해부학",
        ["O"] = "누더기골렘을 소환하여 조종하고, 공동묘지 남쪽에 있는 아카기를 죽이는 데 사용하십시오. 임무를 마치면 연금술사 렌퍼럴에게 돌아가십시오.",
        ["D"] =
        "원래 우리는 언더시티에서 누더기골렘을 제작하지만, 이런 긴급한 상황에서는 여기서 어떻게든 해내야 하네. 언더시티가 가진 모든 재료가 없기 때문에 안타깝게도 이 누더기골렘은 자의식이 없을 것이고, 자네가 직접 조종해야 하네. 주문에 사용할 주문서를 적어두었지. 내가 마치자마자 누더기골렘의 정신은 자네의 통제하에 놓일 걸세.\n\n조금 전 경비병들로부터 보고를 받았는데, 우리가 찾고 있던 회색곰이 여기서 바로 남쪽에서 목격되었다고 하네. 아카기라고 부르지.\n\n비행조련사 옆의 거친 샛길을 따라 첫 번째 공터에서 우회전하게. 그곳에서 짐승을 찾을 수 있을 거야. 그리고 서두르게, 주문은 몇 분밖에 지속되지 않을 테니!",
    },
    [26872] = {
        ["T"] = "검은 갈퀴발톱 영액",
        ["O"] = "까마귀발톱 영액 샘플을 공동묘지의 연금술사 렌퍼럴에게 가져가십시오.",
        ["D"] =
        "이 언데드의 몸에서 펜리스 섬의 썩은가죽일족의 영액과 유사한 탁한 잿빛 물질의 찌꺼기가 들어있는 샘플 병을 발견합니다. 공동묘지의 연금술사 렌퍼럴이 이 물건에 관심이 있을지도 모릅니다.",
    },
    [26873] = {
        ["T"] = "실종된 수습생",
        ["O"] = "호박색 농장에서 케빈 윈터를 찾으십시오.",
        ["D"] =
        "방해해서 미안하오만, $C, 자네의 도움이 필요하다네.\n\n난 은빛소나무 숲이 낯설고 이곳 공동묘지에서 현자 수련생을 만나기로 했지만 그가 도착하지 않았어. 그가 여관주인에게 남긴 메모에는 우리 만남 전에 호박색 농장을 잠시 둘러보러 간다고 적혀 있었지. 여관주인은 호박색 농장이 여기서 남쪽에 있다고 하지만, 내가 그를 찾으러 떠난 사이에 그가 도착해서 상황을 악화시키고 싶지는 않다네. 혹시 자네가 그를 찾아봐 줄 수 있겠나? 그의 이름은 케빈 윈터라네.",
    },
    [26874] = {
        ["T"] = "실종된 수습생",
        ["O"] = "마법사 다르노를 죽이고 호박색 우리 열쇠를 케빈 윈터에게 가져가십시오.",
        ["D"] =
        "책임자가 한 명 있어요 - 이름이 다르노였던 것 같아요. 그자가 이 우리 열쇠를 가지고 있죠. 당신이 그를 설득해 열쇠를 건네받을 수 있다면, 이 우리에서 나가고 싶어요.",
    },
    [26875] = {
        ["T"] = "실종된 수습생",
        ["O"] = "공동묘지로 돌아가 현자 그린혼과 대화하십시오.",
        ["D"] =
        "이 마법사들의 대화를 엿들으면서 몇 가지 흥미로운 사실을 알아냈습니다. 결과적으로, 공동묘지에 있는 현자 그린혼을 만나기 전에 처리하고 싶은 작은 심부름이 생겼어요. 하지만 친절하게도 먼저 돌아가서 제가 곧 그곳에 갈 거라고 그녀에게 알려주신다면 정말 감사하겠습니다.",
    },
    [26876] = {
        ["T"] = "흥미로운 고서",
        ["O"] = "북부 호박색 농장이나 베렌의 동굴 근처에서 달라란 마법사들에게서 오래된 고서 5권을 모으십시오.",
        ["D"] =
        "나의 새로운 수습생에게 맡기려던 임무가 있었지만 자네가 이 일에 더 적임자일지도 모르겠군.\n\n달라란의 지식 대부분은 도시와 함께 파괴되었지만, 그들의 마법사 중 일부가 호박색 농장으로 피신한 모양이네. 만약 그들이 그 도시에서 가져온 오래된 고서를 가지고 있다면, 내가 몇 권 수집하고 싶군.\n\n그러한 지식은 모두가 공유해야지, 얼라이언스 마법사들이 숨겨두어선 안 되네.",
    },
    [26877] = {
        ["T"] = "흥미로운 고서",
        ["O"] = "그레이메인 성벽에 있는 난민들 중 병든 난민 4명을 죽이고 길니아스 고서 5권을 수집하십시오.",
        ["D"] =
        "로데론을 관통한 스컬지의 진군에서 살아남은 길니아스 생존자들이 은빛소나무 숲 남쪽 경계에 있는 그레이메인 성벽에 모였다고 들었어. 그들은 역병을 가져올지도 모른다는 두려움 때문에 조국으로의 입국을 거부당하고 있지.\n\n마치 병든 암양을 대하는 양치기처럼, 전체를 구하기 위해 때로는 도태가 필요할 때가 있는 법이네. 만약 그들이 역병 보균자라면, 질병을 더 퍼뜨리기 전에 제거하는 것이 현명할 것이네.\n\n이 난민들은 또한 길니아스의 저술 중 일부를 가지고 다닐지도 모르고 만약 그렇다면, 내가 그것들을 수집하고 싶군.",
    },
    [26878] = {
        ["T"] = "흥미로운 고서",
        ["O"] = "은빛소나무 숲 남쪽의 버려진 집에서 \"역사의 이론\"을 회수하십시오.",
        ["D"] =
        "자네가 찾아주길 바라는 마지막 고서가 하나 있네, $C.\n\n이곳 경비병들은 유명한 로데론 역사가가 그레이메인 성벽 동쪽, 은빛소나무 숲 남쪽에 오두막을 가지고 있었다고 말해주었어. 그 오두막에 \"역사의 이론\" 사본이 있을지도 모르네. 이 저작은 역사의 방법론에 대해 논하고 있는데... 글쎄 자네가 그 세부 사항에 관심이 있을 거란 생각은 들지 않는군. 자네가 그곳으로 길을 찾아 그 책을 회수해 줄 수 있겠나?\n\n아, 경비병들이 주의를 당부했다는 점을 명심하게. 오두막 주변 지역에서 강력한 늑대인간이 목격되었다더군. 동행할 친구 몇 명을 구하는 것이 현명할 걸세.",
    },
    [26879] = {
        ["T"] = "스위프트후프의 전언",
        ["O"] = "사만다 스위프트후프의 전언을 가시덤불 골짜기의 그롬골에 있는 킨윌레이에게 가져가십시오.",
        ["D"] =
        "오래 전 우리 타우렌은 멀고어의 광활한 평원을 달리는 코도만큼이나 빠르게 달리는 평원주자의 고대 기술을 연마했습니다. 우리 부족이 짐승들을 길들이는 법을 배운 후에는 이 관습을 버렸지만, 저는 송아지 시절부터 이 오래된 기술에 매료되었습니다. 저는 단거리를 전력 질주하는 데 천부적인 재능이 있었고 많은 경주에서 우승했습니다.\n\n슬프게도 저는 부상을 당했고 다시는 달릴 수 없을까 두렵습니다. 이 정글 어딘가에 숨겨져 있다는 소문이 있는 치료법을 찾아 가시덤불 골짜기로 왔지만, 다리를 절고 있는 저는 길에서 멀리 벗어날 수가 없습니다.\n\n부탁 하나만 들어주시겠습니까? 이 쪽지를 그롬골의 킨윌레이에게 전해주십시오. 제 탐색은 실패했지만 그가 도와준 것에 감사드리고 싶습니다.",
    },
    [26880] = {
        ["T"] = "사만다를 위한 연고",
        ["O"] = "가시덤불 골짜기 북동쪽의 쿠르젠 주둔지에서 쿠르젠 맹수조련사들에게서 활력을 주는 정글 연고 4개를 수집하십시오.",
        ["D"] =
        "사만다는 고결한 영혼을 가졌지만, 자신을 위험으로부터 지켜줄 속도를 잃어버려서 자신감이 부족하지. 우리가 그녀의 자신감을 회복시켜 준다면, 아마 그녀는 치료법을 찾는 일을 계속할 거야.\n\n정글의 북동쪽 끝에, 일단의 인간들이 야영지를 세웠네. 그곳의 쿠르젠 맹수조련사들은 그들이 훈련시키는 전투 표범의 기운을 돋우는 데 사용하는 연고를 가지고 다니지. 이 침입자들을 죽이고 그 연고 몇 개를 회수해 오게.",
    },
    [26881] = {
        ["T"] = "사만다를 위한 연고",
        ["O"] = "가시덤불 골짜기 북쪽의 안개계곡 고릴라에게서 따뜻한 피가 든 유리병 6개를 수집하십시오.",
        ["D"] =
        "쿠르젠 주둔지로 북쪽 길을 따라가는 동안 안개계곡 고릴라들의 영토를 지나왔을 수도 있겠군. 이 공격적인 야수들의 피가 우리 연고의 나머지 부분을 구성할 거라네.\n\n놈들을 죽이고 따뜻한 피 반 다스 병을 내게 가져오게! 빨리 돌아올수록, 사만다를 더 빨리 도울 수 있네.",
    },
    [26882] = {
        ["T"] = "사만다를 위한 연고",
        ["O"] = "그롬골 북쪽의 진흙아가미 멀록 약탈자(Murkgill Forager)와 진흙아가미 사냥꾼에게서 질주엉겅퀴를 수집하십시오.",
        ["D"] =
        "잠깐, $N! 킨윌레이가 이 연고에 관해 당신에게 내린 지시를 엿듣고 말았어. 난 진짜 연금술사는 아니지만 내 시약들은 잘 알고 있지, 장담컨대 당신이 만든 그것은 모르는 사이에 사만다를 구할 게 아니라 독살할 거야!\n\n이 연고를 성공작으로 만들려면 또 다른 재료 하나가 필요해. 마을 바로 북쪽에서 진흙아가미 멀록들의 둥지를 찾을 수 있을 거야. 놈들의 약탈자들은 질주엉겅퀴라는 희귀한 약초에 이끌리지. 당신이 정말로 사만다를 돕고 싶다면 그들을 죽이고 질주엉겅퀴를 좀 구해줘.",
    },
    [26883] = {
        ["T"] = "사만다를 위한 연고",
        ["O"] = "가시덤불 골짜기의 주 도로를 배회하는 사만다 스위프트후프에게 완성된 연고를 가져가십시오.",
        ["D"] =
        "잠시만 기다리게, $N.\n\n<앵그런이 질주엉겅퀴를 아주 잘게 빻은 다음, 연고에 섞습니다.>\n\n이제 이 연고는 사만다가 사용하기에 안전할 거야. 제발 이걸 그녀에게 가져다줘, 그리고 두 사람 모두에게 행운을 비네.",
    },
    [26884] = {
        ["T"] = "약탈자 약탈하기",
        ["O"] = "붉은머리부족 납골당에서 달트리의 소지품 4개를 회수하십시오.",
        ["D"] =
        "우리 주위의 이 폐허가 보이십니까, $C? 제 할아버지가 이 정글에 집을 짓고자 했던 시도에서 남은 전부입니다. 저는 여기서 회수할 만한 것이 있는지 보러 내려왔습니다.\n\n수십 년 전, 붉은머리부족 트롤들이 농장을 습격하여 가족 대부분을 학살했습니다. 모든 귀중품도 약탈해 갔죠. 그런데 트롤들은 죽은 자를 묻을 때 전리품의 일부를 함께 묻는다는 이야기를 들었습니다. 붉은머리부족은 줄다이아 폐허 북쪽에 커다란 납골당을 가지고 있습니다. 전 가난한 농부에 불과하지만, 제 가족이 빼앗긴 소지품이 있는지 그 납골당을 조사해 주실 의향이 있으시다면 기꺼이 보답하겠습니다.",
    },
    [26885] = {
        ["T"] = "내 친구, 전투해골 부족원",
        ["O"] = "가시덤불 골짜기 북서쪽에 있는 붉은머리부족 트롤들 사이에서 전승지기 이츨리의 친구 투텍(Thu'tek)을 찾으십시오.",
        ["D"] =
        "이봐 형제, 아주 강력한 도움이 필요해.\n\n우리의 공유된 역사 일부를 기록하는 것을 돕기 위해 다른 정글 부족들에게 연락을 취하고 있었고, 마침내 전투해골 부족 트롤 한 명과 친구가 되었어. 그가 그롬골 밖의 길에서 날 만나기로 했는데 끝내 나타나지 않았어.\n\n그러던 중, 전투해골 부족 전투부대가 붉은머리부족을 습격했다가 패배했다는 보고가 들어왔지. 킨윌레이는 내 친구의 영혼이 영혼계에 없다고 하니, 그는 붉은머리부족의 포로임이 틀림없어.\n\n그를 찾아줘, $C, 그리고 그가 어떤 도움이 필요한지 알아봐. 그의 이름은 투텍이야.",
    },
    [26886] = {
        ["T"] = "내 친구, 전투해골 부족원",
        ["O"] = "그롬골에 있는 전승지기 이츨리에게 투텍의 영혼 부적을 가지고 돌아가십시오.",
        ["D"] =
        "내 부족, 전투해골 부족은 정정당당하게 패배했다. 전투에서 죽는 대신 포로로 잡혔지. 나는 혈신에게 제물로 바쳐질 것이다. 우리가 놈들을 패배시켰다 해도 똑같이 했을 것이니 다를 바 없다.\n\n나는 내 부족의 명예를 위해 죽을 것이다. 네 도움은 필요 없다, $R. 하지만 우정의 증표로 이 부적을 이츨리에게 가져가도 좋다.",
    },
    [26887] = {
        ["T"] = "내 친구, 전투해골 부족원",
        ["O"] = "가시덤불 골짜기의 그롬골에 있는 전승지기 이츨리를 위해 야생덩굴 6개, 큰 송곳니 4개, 붉은머리부족 주술사의 정수 1개를 수집하십시오.",
        ["D"] =
        "혈신은 죽었어, $C. 투텍은 헛되이 죽을 거야. 하지만 그가 부족의 명예를 지키도록 돕고 그가 계속 나를 돕게 할 수 있는 오래된 방법이 하나 있어.\n\n먼저 재료를 좀 모아야 해. 이 골짜기 전역에서 자생하는 야생덩굴이 필요해. 그리고 큰 송곳니 - 랩터나 호랑이를 잡아봐. 마지막으로 붉은머리부족 주술사의 정수. 여기서 북쪽 해변에 있는 발랄 폐허에서 몇 명을 찾을 수 있어.",
    },
    [26888] = {
        ["T"] = "내 친구, 전투해골 부족원",
        ["O"] = "발랄, 트카시, 줄다이아, 칼아이 폐허에서 피의 화로를 찾아 그롬골에 있는 전승지기 이츨리에게 가져가십시오.",
        ["D"] =
        "이제 이 재료들이 모였으니, 붉은머리부족 폐허에서 다른 무언가를 가져와 줘야겠어 - 피의 화로 말이야.\n\n우리 트롤들은 수만 년 동안 존재해 왔고 버려진 오래된 전통이 한두 가지가 아니지. 혈신 학카르가 패배하기 전에도, 정글 트롤들은 피의 화로 사용을 중단했었어. 하지만 그들이 그것들을 간직해 두었다는 건 알고 있지.\n\n북쪽 정글과 해변에 있는 발랄, 트카시, 줄다이아, 칼아이 같은 붉은머리부족의 폐허를 방문해서 피의 화로를 찾아. 그곳들 중 어디에든 있을 수 있어.",
    },
    [26889] = {
        ["T"] = "내 친구, 전투해골 부족원",
        ["O"] = "전승지기 이츨리의 물품들을 줄맘웨의 폐허에 있는 납골당으로 가져가십시오.",
        ["D"] =
        "북서쪽 해안에 있는 줄다이아 폐허 북쪽에 붉은머리부족이 명예로운 죽은 자들을 안치하는 납골당이 있어. 네가 가져온 재료들로 특별한 향을 만들었지. 이 화로, 투텍의 부적, 정수를 납골당으로 가져가야 해. 중앙 석실에서 정수에 불을 붙여.\n\n투텍의 몸은 붉은머리부족과 함께 남아 있겠지만 영혼은 나타날 거야.\n\n뭐? 아예 친구가 없는 것보단 영혼 친구가 있는 게 낫지 않아?",
    },
    [26890] = {
        ["T"] = "내 친구, 전투해골 부족원",
        ["O"] = "의식을 완료한 다음, 그롬골에 있는 전승지기 이츨리에게 돌아가십시오.",
        ["D"] =
        "다음에 무슨 일이 일어날지 모른 채 향에 불을 붙입니다. 붉은머리부족은 이 의식을 결코 반가워하지 않을 것입니다.",
    },
    [26891] = {
        ["T"] = "암초 도굴",
        ["O"] = "악랄한 암초(Vile Reef) 안의 침몰한 배에서 물에 젖어 망가진 무기 10개를 수집하십시오.",
        ["D"] =
        "그롬골 주변의 바다는 악랄한 암초로 알려져 있소. 꽤나 위험한 수역이지만, 한때 무법항에서 스톰윈드로 물건을 가져가서 빨리 한몫 챙기려는 밀수업자들이 지나는 경로가 그곳에 있었지. 하지만 바다는 잔인한 여주인과 같아서 모두가 살아남은 건 아니었소.\n\n여러 척의 난파선이 이곳 바다 밑바닥에 가라앉아 있고 그 안에는 내가 녹여서 호드를 위해 새롭게 제련할 수 있는 무기들이 있소. 우리 병사들을 무장시킬 수 있도록 그 무기 10개를 내게 가져오시오.",
    },
    [26892] = {
        ["T"] = "야수 동맹",
        ["O"] = "안개계곡 골짜기에서 안개계곡 밀렵꾼 8명을 찾아 처치하십시오.",
        ["D"] =
        "달숲에서 자라며 제 어머니는 안개계곡 고릴라들에 대한 이야기를 들려주시곤 했습니다. 어머니가 돌아가신 후, 저는 그들을 보러 가고 싶은 충동을 느꼈습니다. 그리고 제가 발견한 것은 말로 다 표현할 수 없을 정도로 충격적이었습니다.\n\n한때 풍부했던 이 야수들은 멸종 위기에 처할 정도로 밀렵당했습니다! 식량이나 보온 목적이 아니라, 단순한 오락을 위해서 말입니다!\n\n아래 계곡에 있는 밀렵꾼들을 사냥하고, 누가 그들의 배후에 있는지 밝혀낼 수 있게 저를 도와주십시오.\n\n이 위대한 유인원들에게는 당신이 필요합니다, $N.",
    },
    [26893] = {
        ["T"] = "야수 동맹",
        ["O"] =
        "가시덤불 골짜기 동쪽 해안에서 밀렵꾼 우두머리를 찾아내고 배후의 구매자에 대한 증거를 더 찾아보십시오.",
        ["D"] =
        "섬이라고요? 돈 많은 구매자? 우두머리요? 이건 너무 심하군요! 다시 당신의 도움이 필요합니다, $N. 동쪽 해안을 따라 이 야영지를 추적하고 직접 사냥을 좀 해보십시오. 이 W.P.라는 자들이 자신들에 대해 뭐라 말하는지 알아보고 구매자에 대해 더 알아보십시오. 우리는 이 나무의 뿌리째로 뽑아 태워버려야 합니다.",
    },
    [26894] = {
        ["T"] = "야수 동맹",
        ["O"] = "무법항에서 시디스 페인트스나이프를 기습하십시오.",
        ["D"] =
        "드디어 최고 책임자의 이름과 그가 어디 있는지 알게 되었습니다. 무법항입니다. 전혀 놀랍지 않군요. 자, 이 호루라기를 가지고 그를 찾으십시오. 그를 찾으면 호루라기를 부십시오. 그러면 제 친구들이 그 탐욕스러운 모피 상인에게 복수하러 올 것입니다.",
    },
    [26895] = {
        ["T"] = "힘의 투기장: 부러진뿔",
        ["O"] = "부러진뿔을 처치하십시오. 승리하면 트롤 하인 운자와 대화하여 보상을 받으십시오.",
        ["D"] =
        "첫 번째 전투를 치를 준비가 되었습니까? 준비가 되었다면 알려주십시오. 시작하겠습니다. 힘의 투기장에서 상대가 도착하기를 기다리기만 하면 됩니다.\n\n이번 상대는 흉포한 코도, 부러진뿔입니다.\n\n행운을 빕니다! 친구들을 데려오셨기를 바랍니다.\n\n그리고 기억하십시오. 전투는 당신이나 상대 중 한 명이 투기장 바닥에 엎어질 때 끝납니다.",
    },
    [26896] = {
        ["T"] = "힘의 투기장: 쌍둥이",
        ["O"] = "나가 쌍둥이를 처치하십시오. 승리하면 트롤 하인 운자와 대화하여 보상을 받으십시오.",
        ["D"] =
        "다음 전투는 이인조, 정확히는 쌍둥이 자매입니다.\n\n아직 꽁무니 뺄 늦은 시간은 아닙니다, $n. 충분히 이해합니다.\n\n하지만 준비가 되었다면 힘의 투기장으로 들어가 쌍둥이가 도착하기를 기다리십시오.\n\n최후의 생존자가 승자입니다!",
    },
    [26897] = {
        ["T"] = "힘의 투기장: 스톤게이즈",
        ["O"] = "스톤게이즈를 처치하십시오. 승리하면 트롤 하인 운자와 대화하여 보상을 받으십시오.",
        ["D"] =
        "정말 잘해주고 계십니다. 하지만 오우거들이 다음 경기 상대로 어마어마한 녀석을 데려왔군요. 바실리스크인지 뭔지라던데... 녀석들은 절대 자신들의 챔피언과 당신을 싸우게 하고 싶어 하지 않습니다. 베팅 금액이 천정부지로 치솟았거든요!\n\n투기장으로 들어가서 이번 녀석을 빨리 끝내버리십시오!",
    },
    [26898] = {
        ["T"] = "힘의 투기장: 윈스턴",
        ["O"] = "윈스턴을 처치하십시오. 승리하면 트롤 하인 운자와 대화하여 보상을 받으십시오.",
        ["D"] =
        "이번 전투는 꽤 고통스러울 겁니다, $n. 당신을 도와줄 용감한 친구들이 있습니까? 우리는 윈스턴이라는 거대한 유인원을 데려오는 데 성공했습니다! 제 말을 믿으세요. 친구들이 필요할 겁니다. 녀석은 이길 수 없을 것처럼 보입니다! 바위처럼 단단하다고요!\n\n그래도 그와 싸우고 싶다면 힘의 투기장으로 들어가십시오. 그가 올 것입니다.",
    },
    [26899] = {
        ["T"] = "힘의 투기장: 데케드",
        ["O"] = "투기장 챔피언을 처치하십시오. 승리하면 트롤 하인 운자와 대화하여 보상을 받으십시오.",
        ["D"] =
        "줄아만 검투사 투기장에서 챔피언을 데려와야 했습니다. 그는 한 번에 세 마리의 산악 거인을 상대로 훈련을 하고 있었죠.\n\n이번 경기에서 이기면 당신이 새로운 챔피언이 됩니다. 승산이 어느 정도라고 생각하십니까? 자신 있습니까? 말만 하면 제 전 재산을 당신에게 걸겠습니다.\n\n자, 들어가서 이기고 오십시오!",
    },
    [26900] = {
        ["T"] = "힘의 투기장: 최후의 도전",
        ["O"] = "전쟁군주 루르그를 처치하십시오. 승리하면 트롤 하인 운자와 대화하여 보상을 받으십시오.",
        ["D"] =
        "<수북이 쌓인 금화를 세고 있는 픽>\n\n당신 덕분에 돈을 많이 벌었소. 루르그를 물리친다면, 섭섭지 않게 보상해 주겠소. 힘의 투기장에서 겪은 모든 고통이 결국 보상으로 돌아올 것이오.\n\n자, 들어가서 당신의 본때를 보여주시오!",
    },
    [26901] = {
        ["T"] = "상어 지느러미 수프",
        ["O"] = "썩은내 암초에서 흉포한 상어로부터 온전한 상어 지느러미 8개를 수집하십시오.",
        ["D"] =
        "이 지역 주민들은 상어 지느러미 수프라는 것을 아주 좋아한다고 합니다. 만드는 과정은 까다롭지만 건강에 아주 좋다고 알려져 있죠.\n\n암초로 나가서 그 지역의 상어들에게서 지느러미를 모아 제게 가져다주시면 수프를 만들어 보겠습니다.",
    },
    [26902] = {
        ["T"] = "머리 축소 멈춰!",
        ["O"] = "줄쿤다 폐허에 있는 붉은머리부족 트롤들에게서 얼라이언스 모험가 8명을 구출하십시오.",
        ["D"] =
        "이곳의 남서쪽에는 축소된 머리를 만드는 기술로 가시덤불 골짜기 전체에 악명 높은 줄쿤다의 붉은머리부족 트롤들이 있습니다. 하지만 정작 축소되는 머리의 주인이 누구인지에 대해서는 아무도 말하지 않는 것 같습니다!\n\n그들은 의술사에게 데려가기 위해 가시덤불 골짜기 전역에서 모험가들을 붙잡아 왔습니다. 그들이 붉은머리부족의 목에 매달리기 전에 잡혀있는 곳에서 제발 그들을 구출해 주십시오.",
    },
    [26903] = {
        ["T"] = "머리 축소 멈춰!",
        ["O"] = "줄쿤다 폐허에 있는 붉은머리부족 트롤들에게서 호드 모험가 8명을 구출하십시오.",
        ["D"] =
        "이곳의 북서쪽에는 축소된 머리를 만드는 기술로 가시덤불 골짜기 전체에 악명 높은 줄쿤다의 붉은머리부족 트롤들이 있습니다. 하지만 정작 축소되는 머리의 주인이 누구인지에 대해서는 아무도 말하지 않는 것 같습니다!\n\n그들은 의술사에게 데려가기 위해 가시덤불 골짜기 전역에서 모험가들을 붙잡아 왔습니다. 그들이 붉은머리부족의 목에 매달리기 전에 잡혀있는 곳에서 제발 그들을 구출해 주십시오.",
    },
    [26904] = {
        ["T"] = "조잡한 투구",
        ["O"] = "이해할 수 있을 만한 무법항의 누군가에게 실험용 정신 지배 투구를 가져가십시오.",
        ["D"] =
        "투박하게 얽혀있는 전선, 안테나, 그리고 낡은 금속 투구에 웬 스프링까지 붙어있는 물건이 당신의 손에 있습니다.\n\n아마도 무법항의 재능 있는 기술자에게 이것을 가져가면 이것으로 무엇을 해야 할지 알 수 있지 않을까요?",
    },
    [26905] = {
        ["T"] = "조잡한 투구",
        ["O"] = "무법항 북쪽에 있는 늙은 안개계곡 고릴라 8마리에게 실험용 정신 지배 투구를 시험해 보십시오.",
        ["D"] =
        "이런... 참으로 독특한 물건이군요. 투자개발회사에서 정신 지배 투구를 만들려고 시도한 것이 분명합니다. 제가 본 최악의 시도인 동시에 놀랍도록 훌륭한 시도이기도 하네요.\n\n전 이거 안 써볼 거고, 당신도 저한테 이거 쏘게 안 놔둘 테니, 무법항 북쪽에 있는 늙은 고릴라들에게 가져가서 한 번 써보세요.\n\n성능이 어떤지 제게 보고해 주시길 바랍니다.",
    },
    [26906] = {
        ["T"] = "줄다이아 서판",
        ["O"] = "무법항의 크랭크 피즐버브에게 줄다이아 서판을 가져가십시오.",
        ["D"] =
        "무슨 이유에서인지 요새 트롤 역사에 대해 배우는 게 대세입니다. 그 말은 즉, 돈이 된다는 뜻이죠!\n\n줄다이아 폐허 북쪽에는 붉은머리부족 트롤의 지하 묘지가 있습니다. 그 안에 줄다이아의 역사를 말해주는 서판이 어딘가에 있죠. 관심 있어 하는 구매자가 있습니다 -- 서판을 획득해 주신다면 수익의 일부를 떼어 드리겠습니다.",
    },
    [26907] = {
        ["T"] = "야생의 튤립",
        ["O"] = "튤립의 일기장을 사용하여 그녀의 추억의 상자를 찾으십시오.",
        ["D"] =
        "제 가장 친한 친구인 튤립과는 다르게 전 해적이 아니에요. 그녀는 정말 대단하죠! 로프를 입으로 단번에 물어뜯는 것도 본 적이 있다니까요. 그녀는 너무 맹렬해요! 다니엘과 함께 있을 때만 빼고요....\n\n그는 이제 그녀의 약혼자입니다. 그녀는 두 사람이 어떻게 만나 사랑에 빠졌는지에 대한 아름다운 일기를 제게 보냈어요. 심지어 저보고 그들의 결혼식 주례를 부탁했답니다. 정말 큰 영광이죠.\n\n그런데... 아시다시피... 그들은 3일 전에 결혼할 예정이었지만, 오지 않았고 그 이후로 전 너무 걱정이 돼서 병이 날 지경이에요.\n\n튤립은 소중한 기념품들을 묻어두었다고 적었어요. 혹시 그들의 추억의 상자를 찾아, 그 안에 있는 기념품이 가리키는 곳에서 뭔가 가져와 주실 수 있나요?",
    },
    [26908] = {
        ["T"] = "야생의 튤립",
        ["O"] = "튤립의 일기장을 사용하여 묻혀 있는 추억의 기념품을 찾아 그녀가 있는 곳을 알아내십시오.",
        ["D"] =
        "뭔가 더 있을 줄 알았는데 두 사람이 소중하게 간직한 추억에 대한 설명만 있는 것 같군요.\n\n당신이 사용할 수 있도록 이것들을 그녀의 일기장에 첨부해 드리겠습니다. 제가 보기엔 두 사람이 다른 두 곳에 중요한 기념품을 남긴 것 같습니다. 아마도 그것들이 튤립을 찾는 데 도움이 되지 않을까요?",
