    [26909] = {
        ["T"] = "야생의 튤립",
        ["O"] = "마력 깃든 나침반을 사용하여 튤립과 다니엘을 찾으십시오.",
        ["D"] =
        "자... 이 나침반이 튤립과 다니엘이 있는 곳으로 길을 안내할 것입니다. 부디, 그들이 무사히 집으로 돌아와 마침내 결혼식을 올릴 수 있도록 무슨 짓이든 해주세요!\n\n튤립의 기억이 가장 강하므로 그녀에게 먼저 안내한 다음, 그곳에서부터 다니엘에게로 안내할 것입니다. 그들을 무사히 제게 데려와 주세요, $n님!",
    },
    [26910] = {
        ["T"] = "야생의 튤립",
        ["O"] = "마력 깃든 나침반을 사용하여 다니엘을 추적하십시오.",
        ["D"] =
        "다니엘, 언제나 당신이었어.\n\n그래서 튜타가 날 당신에게서 떼어놓으려고 우릴 쫓아왔던 거야. 난 너무 화가 났어! 당신에게 가는 것밖에 생각나지 않아서 자르고, 찌르고, 베었지. 조심했더라면 내 뒤에 있던 그녀의 소리를 들었을 텐데.\n\n손에서 펜던트가 빛나고 있어. 얼음처럼 차갑게 타오르고, 산보다 무거워. 죽음이 뭔지 아는데, 이건 죽음처럼 느껴지지 않아. 오늘이 우리 결혼식이 되어야 했어. 날 용서해 주겠어?\n\n다니엘, 부디 무사하길 바라. 당신이 도망치길 바라. 사랑해...",
    },
    [26911] = {
        ["T"] = "야생의 튤립",
        ["O"] = "첼 문우드의 의식을 목격하십시오.",
        ["D"] =
        "절 위해 해주신 모든 일에 감사드립니다만, 이제 무슨 일이 일어나든 방해해서는 안 됩니다.\n\n제가 시도할 수 있는 마지막 의식이 하나 남았지만, 엘룬이 금지한 것입니다. 왜냐하면... 그 고통을 견딜 수 있는 자가 거의 없기 때문이죠. 하지만 제가 살아남지 못하더라도... 튤립은요? 음... 그녀라도 저를 위해 똑같이 했을 테니까요.",
    },
    [26912] = {
        ["T"] = "죽음의 일격 치료제",
        ["O"] = "죽음의 일격 독액 8병을 모아 스토나드에 있는 툴타조르에게 돌아가십시오.",
        ["D"] =
        "내가 대장 녀석 비위를 거스른 게 분명해. 오크들이 스토나드라고 부르는 이 악취 나는 변두리로 나를 보냈으니 말이야! 이 지역의 저주받은 야생 동물들 문제를 해결할 연금술사가 필요했던 모양인데, 당신이 나서줄 차례군.\n\n최근 이곳 남동쪽에 거대한 거미 둥지가 부화했네. 심각한 독 중독 사건이 몇 건 있었고, 물린 상처를 치료할 해독제를 개발하기 위해 그 거미들의 독을 연구해 보고 싶어. 나는 싸움꾼이 아니야, $N. 내가 필요한 독을 가져다줄 텐가?",
    },
    [26913] = {
        ["T"] = "오크니르의 소중한 낚싯대",
        ["O"] = "피난처 남쪽의 어선에서 오크니르가 버리고 온 낚싯대들을 회수하십시오.",
        ["D"] =
        "얼마 전, 아주 친절한 인간이 이곳을 지나가다가 우리의 작은 카약보다 이론상으로 훨씬 안정적인 어선을 만드는 기술을 가르쳐 주었습니다. 며칠 동안 고생한 끝에 마침내 그 인간과 저는 배를 타고 나갔죠. 그런데 믿어지십니까 -- 크로콜리스크가 그 망할 배를 물어뜯어 배가 가라앉기 시작한 겁니다! 우린 간신히 살아 돌아왔어요!\n\n우리는 이곳 남쪽에 배를 버렸고, 제가 알기로 그 인간은 제가 특별히 광택을 낸 낚싯대들을 회수하도록 도와주러 오지도 않은 채 마을을 떠나버렸습니다. 저를 위해 그 배를 찾아 낚싯대를 회수해 주시겠습니까?",
    },
    [26914] = {
        ["T"] = "오크니르의 소중한 낚싯대",
        ["O"] = "피난처 동쪽에 있는 드레노어 난민 낚시꾼에게서 온전한 광택 나는 낚싯대를 회수하십시오.",
        ["D"] =
        "이보세요, 여긴 늪지대입니다. 이 근방에서 낚시하는 사람이 많지 않으니, 제 낚싯대를 가져갔을 만한 집단은 단 한 곳뿐입니다. 바로 동쪽의 드레노어 난민들이죠. 그들 중에는 낚시를 하는 조잡한 무리가 섞여 있고, 분명 그들 중 누군가가 그걸 가지고 있을 겁니다. 드레노어 난민들을 수색해 그걸 되찾아 주시지 않겠습니까?",
