    [26915] = {
        ["T"] = "늪지대의 공포",
        ["O"] = "뒤엉킨 공포 10마리와 늪지 장로 3마리를 처치하고 스토나드의 준다르타에게 돌아가십시오.",
        ["D"] =
        "북서쪽에는 안개 골짜기가 있습니다. 한때 숲의 생명력이 넘치는 무성하고 아름다운 지역이었죠. 그런데 최근 정령 공포의 역병이 그 계곡을 집어삼켰습니다.\n\n얼라이언스가 스토나드를 공격하기 위한 전진 기지로 그 계곡을 사용할 수도 있으니, 우리가 그곳을 장악하는 것이 가장 이익입니다. 안개 골짜기로 가서 정령들을 정화해 주십시오, $N. 스토나드를 위하여!",
