        ["D"] =
        "이곳엔 입이 너무 많아서 카라보르 스튜를 끓여 내기가 벅찹니다. 한 번에 아주 많이 끓일 수만 있다면, 며칠 동안 사람들이 배불리 먹을 수 있을 텐데요. 절 위해 재료를 좀 구해다 주시겠습니까? 동쪽 멀리 해안을 따라가면 갯벌 게를 찾을 수 있습니다. 그들에게서 가장 크고 즙이 많은 집게발을 가져다주세요.",
