        ["D"] =
        "끝내주는 스튜를 만들고 싶다면 가능한 한 많은 고기가 필요합니다. 최상급 품질의 고기만이 경비병들의 기력을 회복시킬 수 있습니다. 이곳 남동쪽에서 죽음의 일격 독거미들을 찾을 수 있을 겁니다. 그 거미들의 고기는 즙이 많고 맛있습니다. 크면 클수록 더 좋습니다! 절 위해 거미들을 박살 내고 살코기를 저며다 주시겠습니까.",
    },
    [26918] = {
        ["T"] = "화끈한 맛",
        ["O"] = "슬픔의 늪 주변에서 불꽃 매운 고추 8개를 모으십시오.",
        ["D"] =
        "이 스튜에 경비병들의 정신을 번쩍 들게 할 화끈한 맛을 더하려면 강력한 풍미가 필요합니다. 우리가 어둠의 문을 통과할 때 불꽃 고추 식물 씨앗 한 봉지를 가지고 왔었죠. 주머니에 구멍이 나 있어서 피난처로 오는 길에 씨앗이 좀 떨어졌습니다. 그 이후로 그 식물들이 싹을 틔우고 다 자랐을 겁니다. 그 식물에서 열리는 고추는 매운 걸 넘어서 화끈하죠. 절 위해 고추를 좀 가져다주시겠습니까?",
    },
    [26919] = {
        ["T"] = "카라보르 불꽃 스튜",
        ["O"] = "피난처의 시민들에게 카라보르 불꽃 스튜를 배달하십시오.",
        ["D"] =
        "얼마 만에 만들어 낸 최고의 스튜인지 모르겠습니다. 이 스튜의 풍미와 화끈함이 우리 동족에게 고향의 좋은 추억을 떠올리게 해 줄 것입니다.\n\n이것을 제 동료 드레나이들에게 나누어 주시겠습니까? 당신이 스튜를 준비하는 데 큰 도움을 주었으니 그들의 감사를 받는 것이 마땅합니다.",
    },
    [26920] = {
        ["T"] = "늪지대의 가죽",
        ["O"] = "두꺼운 크로콜리스크 가죽 8장과 질긴 표범 가죽 8장을 마사트 탄드르에게 모아 주십시오.",
        ["D"] =
        "가끔 고향의 야수들이 그립습니다... 그들의 가죽... 그들의 모피... 모두 훌륭했죠. 이 행성은 제 사업을 계속하기에 안성맞춤인 것 같습니다.\n\n하지만 재료가 아주 많이 부족합니다. 이 늪에 사는 야수들의 가죽을 좀 구해다 주실 수 있습니까? 무두질이 잘되는 늪지 표범이나 톱니이빨 새끼 악어 가죽이면 가장 좋습니다.",
    },
    [26921] = {
        ["T"] = "늪지대의 가죽",
        ["O"] =
        "슬픔의 늪에서 톱니이빨 무는악어에게서 튼튼한 크로콜리스크 가죽 8장을, 그림자 표범에게서 거친 흑표범 가죽 8장을 수집하십시오.",
        ["D"] =
        "이봐요, 거기. 네, 당신이요!\n\n아까 당신이 가죽 뭉치를 마사트에게 가져가는 걸 봤는데 조그만 프로젝트를 하나 도와주실 수 있나 해서요. 마사트가 이 마을에서 가장 가죽세공을 많이 하지만, 솜씨가 형편없거든요. 제가 품질이 훨씬 뛰어난 것을 만들어내면 경비병들에게 장비를 납품하는 일을 넘겨받을 수 있을 겁니다. 저를 위해서도 가죽을 좀 구해다 주시겠습니까? 마사트가 부탁한 쓰레기 같은 것들보다 품질이 훨씬 높아야 합니다.\n\n동쪽으로 멀리 가면 톱니이빨 무는악어와 그림자 표범을 찾을 수 있을 겁니다. 대신 그 녀석들의 가죽을 제게 가져다주세요.",
