        ["D"] =
        "이 늪은 이국적인 약초와 야생 동물의 본고장입니다. 스토나드에서 의학적인 목적으로 사용할 가능성이 있는지 조사하는 것이 제 임무입니다.\n\n특히, 북서쪽 안개 골짜기에서 자라는 늪지대 갈대라는 약초가 있습니다. 사용 가능성을 테스트해 볼 수 있도록 그곳에서 자라는 샘플을 제게 가져다주셨으면 합니다.",
