        ["D"] =
        "밤이 되면 우리 사람들이 소리도 없이 사라집니다. 남겨진 끈적끈적한 찌꺼기가 많은 것으로 보아, 이 늪에 사는 거대한 거미가 범인일 것으로 추측됩니다. 이 악몽 같은 괴물을 성공적으로 제거하는 모험가라면 누구에게든 보상하겠습니다!\n\n\n-- 감시자 마나르",
