    [26924] = {
        ["T"] = "현상 수배: 타무라",
        ["O"] = "타무라를 처치하고 스토나드에 있는 준다르타에게 그녀의 머리를 가져가십시오.",
        ["D"] =
        "북쪽 늪지대를 조심하십시오. 타무라로 알려진 치명적인 사자가 배회하고 있습니다. 스토나드는 이 무자비한 야수에 대해 어떤 수단을 써서라도 처치하라는 명령을 내렸습니다. 이 현상금 사냥에 나서는 모험가들은 절대 홀로 타무라를 상대하지 마십시오. 성공한다면 스토나드의 준다르타에게 타무라의 머리를 가져가 보상을 받으십시오.",
    },
    [26925] = {
        ["T"] = "역사학자에게 보내는 메시지",
        ["O"] = "브릴에 있는 역사학자 토드 페이지를 찾아 멀록들이 노스샤이어 광산을 점령했다고 알리십시오.",
        ["D"] =
        "안녕하시오 친구... 혹시 브릴로 가는 길이오? 그렇다면 브릴로 메시지를 전해줄 수 있겠소?\n\n내 이름은 재스퍼 그린이고 전승지기회 수습생이오. 내 상관인 역사학자 페이지 님이 노스샤이어 광산에서 유물을 수집해 내가 돌아오기를 브릴에서 기다리고 있다오. 하지만 그분이 지시한 임무를 수행할 수가 없소. 광산 주변이 멀록들에게 점령당했기 때문이지.\n\n그분은 임무를 완수하기 전까지는 돌아오지 말라고 하셨소. 이 문제를 설명해 주실 수 있소? 어쩌면 그분이 해결책을 알고 계실지도 모르오.",
    },
    [26926] = {
        ["T"] = "유물 상자",
        ["O"] = "노스샤이어 광산을 조사하여 브릴의 역사학자 토드 페이지를 위해 수집된 유물 상자를 회수하십시오.",
        ["D"] =
        "노스샤이어 광산은 로데론이 몰락하기 직전에 세워졌소. 솔리덴 농장 서쪽 길 끝을 지나 속삭임의 해안에서 조금 안쪽으로 들어간 곳에 있소.\n\n광산은 광석 채굴로 이익을 본 적이 없지만, 한때 광부들이 기이하고 오래된 유물을 발견했다는 보고가 수도로 전해진 적이 있소. 이 보고서는 최근 언더시티가 복구한 낡은 문서에서 발견되었소.\n\n내가 아는 한 이 상자는 아직 회수되지 않았고, 광산에서 먼지를 뒤집어쓰고 있을 거요.\n\n그러니 그곳으로 가서 상자를 찾으시오!",
    },
    [26927] = {
        ["T"] = "유물 상자",
        ["O"] = "수집된 유물 상자를 언더시티 마법 지구에 있는 역사학자 에바 트렐레인에게 가져가십시오.",
        ["D"] =
        "내 지시를 훌륭히 완수했군, 그렇다면 이 유물 상자를 다시 자네에게 맡기겠네.\n\n브릴을 나와 남쪽으로 향하는 길을 따라가게. 그 길은 언더시티로 바로 이어져 있지. 마법 지구에 전승지기회 역사학자 에바 트렐레인이 있을 걸세. 이 상자를 그녀에게 가져가 내 임무가 완료되었다고 전해주게.",
