    [26928] = {
        ["T"] = "아루갈의 매복",
        ["O"] =
        "공동묘지 북쪽 매복 지점 근처의 다리 아래에서 짐마차에 탔던 자들의 흔적을 찾아보십시오.",
        ["D"] =
        "이 짐마차 행렬은 언더시티를 향해 가고 있었는데, 늑대인간이라는 끔찍한 야수들의 공격을 받았습니다. 제가 이곳에 도착했을 무렵에는 호위병들과 인부들이 모두 숲으로 끌려갔거나 그보다 더 끔찍한 일을 당한 후였습니다.\n\n늑대인간들은 짐마차에서 무언가를 찾고 있었고, 저는 있는 힘을 다해 놈들을 쫓아냈습니다. 왜 그들이 공격했는지 이유를 찾을 수 있는지 주위를 살펴보십시오. 발톱 자국과 발자국이 분명 근처 다리 밑으로 이어져 있습니다.",
    },
    [26929] = {
        ["T"] = "아루갈의 매복",
        ["O"] =
        "죽음의경비병 키트사펠이 부상당한 말을 치료할 수 있도록 크로그 버섯 포자 8개와 검은늑대의 피 4쿼트를 구하십시오.",
        ["D"] =
        "로데론 맙소사, 이 불쌍한 죽음의경비병들이 도대체 뭘 찾은 걸까요? 어떻게 처리할지 결정할 수 있도록 최대한 빨리 공동묘지로 가져가야 합니다. 이 상자는 너무 무거워서 들고 갈 수가 없으니 말이 필요합니다.\n\n이 말들은 다쳐서 서 있지도 못할 정도지만, 상자를 옮기려면 말 한 마리는 필요합니다. 근처 물가에서 크로그 버섯 포자를 구하고, 이곳 북서쪽의 검은늑대들에게서 피를 좀 가져다주시면 말을 치료할 수 있는지 보겠습니다.",
