        ["D"] =
        "이 상자를 남서쪽에 있는 공동묘지로 급히 가져가 병참장교 코르에게 보관을 맡길 것입니다.\n\n이 호송대에서 제가 수습한 나머지 물자들을 챙겨서 그곳에서 만납시다. 길가에서 썩혀두는 것보다는 공동묘지에서 사용하는 것이 훨씬 더 유용할 것입니다.",
