        ["D"] =
        "상자가 너무 통통 튄다. 상자 안쪽은 푹신하다. 상자가 내 손을 핥았다. 코르가 훔쳐보자 상자가 겁에 질린 것 같았다. 상자는 나쁘지 않다. 경비병 키트에게 상자를 보여주자.",
