        ["D"] =
        "조금 전 누군가 나에게 다가와 이 두루마리를 건넸다. 우리 사냥꾼 전문가, 아폴로스 데스샷이 보낸 것이 분명하다. 당신에게 주려는 것이었던 것 같군. 읽어보라.",
