        ["D"] =
        "빌어먹을 인간 놈들! 우리 병사들을 죽이고, 우리 무덤에 침을 뱉고, 이제는 우리 광산까지 차지했소! 필시 광석을 이용해 갑옷과 무기를 만들고 있을 것이오... 이런 일을 용납할 수는 없소!\n\n$N, 이곳 남동쪽, 발니르 농장 근처에 있는 키트사펠 광산으로 가서 그들이 채굴하고 있는 광석을 좀 가져와 주시오. 우리가 나서지 않으면, 놈들은 그 광석으로 무기를 만들어 브릴을 공격할 것이오!",
