        ["D"] =
        "제페타는 당신이 고블린 회전초밥을 가져다준 것에 대한 감사의 표시로 이 열쇠를 주었습니다. 이 열쇠는 티리스팔 숲 비행선 탑 맨 아래층에 있는 금고를 여는 열쇠라고 하더군요.\n\n안에 무엇이 들어있을까요?",
