        ["D"] =
        "만약 광산에 멀록이 득실거린다면, 그린 그놈은 크고 흉측한 좀비 바지라도 입고 당장 그 문제를 해결해야 할 걸세! 간단한 임무를 완수하지 못한 게 벌써 두 번째야. 돌아가서 광산에 있는, 녀석의 앞길을 가로막는 게 무엇이든 해결하라고 전하게.\n\n현장 업무는 위험한 법이니 녀석이 감당할 수 없다면 지금 당장 알아야겠어.",
