    [26937] = {
        ["T"] = "노스샤이어 광산",
        ["O"] = "재스퍼 그린을 위해 노스샤이어 광산을 청소하십시오.",
        ["D"] =
        "이보시오, $N, 가진 돈이 많진 않지만, 자네가 광산에 가서 좀 쓸어준다면 내 가진 걸 전부 주겠소. 내 공으로 돌려주기만 한다면, 책이 있는 곳으로 돌아갈 수 있소. 그렇게 해준다면 Lorespeakers(전승지기회)에 영원한 친구를 두게 되는 거요.\n\n광산은 인적이 드문 곳에 있소. 길 끝을 지나 조그만 연못 근처에 있지. 사람들이 밟아 생긴 길을 따라 서쪽으로 쭉 가기만 하면 되오.",
    },
    [26938] = {
        ["T"] = "사냥꾼의 길",
        ["O"] = "Razor Hill(시험의 골짜기 앞마을)에 있는 소타르와 대화하십시오.",
        ["D"] =
        "안녕하신가, 젊은 사냥꾼이여. 자네는 야수를 다루고 동반자로 훈련시킬 수 있을 만큼 능숙해 보이는군.\n\n이 제안에 관심이 있다면, 듀로타의 Razor Hill에 있는 소타르를 찾아가 보게. 그가 자네만의 야수를 얻는 길로 인도해 줄 걸세.",
    },
    [26939] = {
        ["T"] = "죽음 속의 안식",
        ["O"] =
        "북서쪽의 나이트 웹 거미 동굴 광산에서 조셉 스트린브로우의 유품을 찾아 그의 영혼을 달래주십시오. 그런 다음 죽음의 종소리 마을 묘지에 있는 루나 스트린브로우에게 돌아가십시오.",
        ["D"] =
        "반갑습니다, $N. 제가 왜 이 무덤에 무릎을 꿇고 있는지 궁금하실 텐데요. 제 남편 조셉의 무덤입니다.\n\n조셉은 이곳 북서쪽 나이트 웹의 거미 동굴 광산에서 일하던 광부였습니다. 그는 거미에게 물려 죽었죠. 역병이 퍼지기 전이라 시신을 수습하지 못했습니다.\n\n이제 조셉의 영혼은 안식을 찾지 못하고 광산을 차지하려는 포세이큰들을 위협하고 있습니다. 시신은 오래전에 사라졌지만, 전 아직도 이 무덤을 그의 것이라고 생각합니다. 그가 남긴 물건을 가져다주시면 이곳에 묻고 영혼을 달랠 수 있을 겁니다. 광산을 뒤져서 그의 유품이 될 만한 것을 찾아주시겠습니까?",
    },
    [26940] = {
