        ["D"] =
        "키트사펠 광산에 대해 들어보셨소? 티리스팔에서 가장 풍부한 광산이지! 역병이 돌기 전에는 내가 소유하고 관리했지만, 역병이 돌자 붉은십자군 놈들이 우리에게서 광산을 \"해방\"시킨답시고 빼앗아갔소. 그놈들에게 교훈을 가르쳐 줄 때가 왔소.\n\n광산으로 가서 포세이큰을 위해 탈환해 주었으면 하오! 브릴에서 남쪽 길을 따라가다 갈림길에서 왼쪽으로 꺾어 발니르 농장이 나올 때까지 계속 가시오. 농장 바로 남쪽 언덕을 따라가면 광산이 있을 거요. 조심하시오, $N. 붉은십자군은 싸우지도 않고 광산을 포기하지는 않을 테니.",
    },
    [26941] = {
        ["T"] = "붉은십자군의 기밀",
