        ["D"] =
        "붉은십자군을 상대로 제법 성과를 거뒀다고 들었소, $N. 일자리를 찾고 있다면 내게 맡길 임무가 하나 있소만?\n\n동쪽 멀리 독그물 골짜기라는 곳이 있소. 붉은십자군이 그곳에 작은 전초기지를 세웠는데, 내가 믿을만한 정보통에 따르면 놈들이 뭔가 사악한 일을 꾸미고 있다고 하오. 놈들이 무슨 계획인지 알아야 하는데, 가장 좋은 방법은 놈들의 중위를 처치하고 놈들의 명령서를 가져오는 것이오.",
