        ["D"] =
        "죽어서도 우린 먹어야 하오 $N! 여태껏 얻어먹은 딱딱한 빵은 이제 지겹지 않소. 제대로 된 식사를 할 때요!\n\n재료만 가져다주면 내가 맛있는 요리를 만들어줄 수 있소. 서쪽에 있는 청정 연못에 가서 뱀장어를 낚아보는 건 어떻소? 가져오면 우리 둘 다 맛있게 먹을 수 있는 걸 만들어 주겠소.",
    },
    [26943] = {
        ["T"] = "야수 길들이기",
        ["O"] =
