        ["D"] =
        "반갑소, 젊은 사냥꾼. 이제 자네의 모험을 도울 야수를 길들이는 법을 배울 준비가 된 것 같군.\n\n우리는 죽었지만, 여전히 동물의 존경과 신뢰를 얻을 수 있소. 심지어 살아있는 자들의 존경과 신뢰를 얻는 것보다 더 말이지. 이 조련용 막대를 받게, 나가서 거대한 그늘박쥐를 길들이는 데 사용해보게. 이름 때문에 겁먹지 마시오. 나중에 보게 될 다른 박쥐들에 비하면 꽤 온순한 편이니까. 성공하면 돌아오시오.",
