    [26944] = {
        ["T"] = "야수 길들이기",
        ["O"] =
        "조련용 막대를 사용하여 굶주린 검은늑대를 길들이십시오. 기술을 연습한 후, 조련용 막대를 브릴에 있는 다르나 워드에게 돌려주십시오.",
        ["D"] =
        "자네의 다음 시험으로 굶주린 검은늑대를 길들여 오게나. 굶주린 짐승은 배부른 녀석들보다 다루기가 조금 더 쉬울 걸세. 종종 억지로 먹어야 했던 불결한 살점 때문인지, 늘 싸울 기력이 있는 건 아니니까 말이야. 놈들은 티리스팔과 은빛소나무 숲을 잇는 곳, 브릴의 남서쪽에서 찾을 수 있네.",
