    [26945] = {
        ["T"] = "야수 길들이기",
        ["O"] =
        "조련용 막대를 사용하여 흉포한 검은그물거미를 길들이십시오. 기술을 연습한 후, 조련용 막대를 브릴에 있는 다르나 워드에게 돌려주십시오.",
        ["D"] =
        "마침내 마지막 시험을 치를 때가 왔소. 장난은 그만하지: 난 자네를 거미 소굴 한가운데로 보낼 생각이네. 자네라면 무사할 거라 생각하네.\n\n동쪽 멀리 산 근처로 가서 흉포한 검은그물거미를 길들이시오. 등 뒤를 조심하고, 근처에 진을 치고 있는 붉은십자군을 경계하게나.\n\n행운을 비네, $N.",
    },
    [26946] = {
        ["T"] = "야수 훈련",
        ["O"] = "언더시티의 스티븐 캐롤과 대화하십시오.",
        ["D"] =
        "이제 자네는 펫을 길들이고 부르는 기술을 익혔지만, 그 녀석을 훈련하는 지식 또한 얻어야 하오.\n\n언더시티로 가시오. 군사 지구에 가면 포세이큰 군대에서 가장 훌륭한 사냥꾼 중 한 명인 스티븐 캐롤을 찾을 수 있을 거요. 그가 자네를 지도해 줄 것이오.\n\n앞으로 자네의 이름이 자주 들리기를 바라네, $C.",
    },
    [26947] = {
        ["T"] = "사냥꾼의 길",
        ["O"] = "티리스팔 숲의 브릴에 있는 다르나 워드와 대화하십시오.",
        ["D"] =
        "안녕하신가, 젊은 사냥꾼이여. 자네는 야수를 다루고 동반자로 훈련시킬 수 있을 만큼 능숙해 보이는군.\n\n브릴에 있는 다르나 워드를 찾아가 보게. 그녀가 자네만의 야수를 얻는 길로 인도해 줄 걸세.",
