    [26951] = {
        ["T"] = "시간의 흐름에 관한 문제",
        ["O"] = "아제로스의 가장 위험한 구석을 샅샅이 뒤져 다른 시간의 교란이 있는지 찾아보십시오.",
        ["D"] =
        "안돌할에서 일어난 시간 교란만이 내 감각을 찌르는 유일한 왜곡은 아닙니다. 더 큰 문제가 있을 것으로 의심됩니다. 그리고 시간의 흐름에 관한 한, 제 감각은 틀린 적이 없습니다.\n\n친구여, 저와 제 용군단은 당신의 도움이 다시 필요합니다. 저는 여기에 남아서 이 작은 문제를 수습해야 하지만, 세상의 다른 곳들도 시간의 기생충에 의해 영향을 받고 있을 가능성이 큽니다. 정확히 어디인지는 모르겠지만, 세상의 가장 위험한 구석을 수색하다 보면 찾을 수 있을 겁니다. 무언가 발견하면 알려주십시오. 행운을 빕니다!",
    },
    [26952] = {
        ["T"] = "시간의 흐름이 갈라진다?",
        ["O"] =
        "크로미의 시간 이동기를 여명의 설원에서 발견한 이상 현상으로 가져가 조사하여 무엇이 나타나는지 확인하십시오.",
        ["D"] =
        "이 이상 현상들이 군단이 아제로스에서 강력한 영향력을 유지했던 지역에서 나타나는 것이 우연일 리가 없습니다... 아니면 우연일까요? 그들이 힘을 행사하던 곳에 시간의 흐름을 조작한 증거를 남겼다는 건 너무 뻔한 것 같습니다.\n\n확신이 서지 않는군요, $N. 자, 이 시간 이동기를 가지고 여명의 설원 안돌할의 사일로를 조사했던 것처럼 그곳의 이상 현상도 조사해 보십시오. 무엇이 나오는지 확인해 보십시오. 그러면 누가 진짜 배후에 있는지, 혹은 진짜 군단의 짓인지 짐작할 수 있을 겁니다.",
    },
    [26953] = {
        ["T"] = "찢어진 합격 통지서",
        ["O"] =
        "찢어진 합격 통지서를 서부 역병지대의 다로우미어 호수 한가운데에 있는 카엘 다로우 섬으로 가져가십시오.",
        ["D"] =
        "편지가 든 찢어진 봉투를 발견했습니다.\n\n아주 정교한 양피지에 쓰인 것으로 보아 카엘 다로우 섬에 위치한 어떤 학술 기관의 초대장인 듯합니다. 편지에는 마법과 전투 병과에 대한 언급이 있지만, 구체적인 내용은 부족합니다. 수신자의 이름도 빠져 있고, 편지의 아랫부분도 없습니다.\n\n이 교육 기관에 대해 조사해 보는 것은 어떨까요?",
    },
    [26954] = {
        ["T"] = "활제조자의 부탁",
