        ["D"] =
        "$C 님, 대화해 주셔서 감사합니다. 저는 보잘것없는 사냥꾼이지만 당신의 도움을 간절히 바라고 있습니다. 유명한 순찰자 나타노스 매리스는 지금의 동부 역병지대에 농장을 가지고 있었습니다. 스컬지가 오기 전까지 그는 제 영웅이었고, 저는 그의 기록이 남아 있는지 확인하러 그곳에 가고 싶었습니다.\n\n유감스럽게도 역병지대의 짐승들은 제가 감당하기엔 벅찹니다. 제 대신 그의 영지 폐허를 수색해 주시겠습니까? 저는 그가 휘두르는 것과 같은 쇠뇌를 만드는 방법을 알고 싶습니다. 그의 기록을 하나라도 발견하면 저에게 가져다주십시오.",
    },
    [26955] = {
        ["T"] = "활제조자의 부탁",
        ["O"] = "히포그리프나 청소부 독수리에게서 화살 깃털 20개를 모은 후, 서리바람 야영지의 마리엘 듀폰트에게 돌아가십시오.",
        ["D"] =
        "이 기록에 따르면, 순찰자 매리스는 생애의 대부분을 보낸 쿠엘탈라스에서 찾은 재료로 자신만의 쇠뇌와 볼트를 만들었습니다. 쿠엘탈라스가 황폐해졌으니 우리는 다른 곳에서 비슷한 재료를 찾아야 합니다.\n\n가장 먼저 필요한 것은 화살 깃에 쓸 깃털입니다. 제 생각에는 여러 곳에서 비슷한 깃털을 구할 수 있을 것 같습니다. 여기 서부 역병지대나 아즈샤라, 심지어 더 먼 곳에 있는 튼튼한 히포그리프나 청소부 독수리 같은 종류 말입니다.",
    },
    [26956] = {
        ["T"] = "활제조자의 부탁",
        ["O"] = "역병지대의 장작더미에서 엘프 심장목 10개를 모으십시오.",
        ["D"] =
        "다음으로 쇠뇌의 몸체가 될 나무를 모아야 합니다. 기록에 따르면 나타노스는 하이 엘프들이 라오미어, 즉 공용어로 심장목이라고 부르는 나무의 목재를 사용했다고 합니다. 심장목은 훌륭한 무기를 만들 수 있을 뿐만 아니라 벽난로에서 아주 오래 탄다고 하네요.\n\n혹시 역병지대 전역의 폐허 근처 장작더미에 아직 심장목이 남아있지 않을까 싶습니다. 한 번 수색해 보시겠습니까?",
    },
    [26957] = {
        ["T"] = "활제조자의 부탁",
        ["O"] = "검은바위 첨탑의 트롤들에게서 팽팽하게 감긴 쇠뇌 시위를 모으십시오.",
        ["D"] =
        "이 마지막 작업은 매우 까다로울 겁니다, $N 님. 나타노스는 쇠뇌 시위로 쿠엘탈라스에서만 만들어지는 마력 깃든 엘프의 실을 사용했습니다.\n\n<마리엘이 한숨을 쉽니다.>\n\n더 이상 찾을 방법이 없지만, 검은바위 오크들과 동맹을 맺은 트롤들이 원거리 무기의 대가라는 소문을 들었습니다. 아마도 그들이 사용하는 활시위가 괜찮은 대체품이 될 수 있을 겁니다. 알아보려면 검은바위 첨탑의 심연으로 내려가 보셔야 할 것입니다.",
    },
    [26958] = {
        ["T"] = "영웅 숭배",
        ["O"] = "동부 역병지대의 매리스 농장에 있는 나타노스 블라이트콜러와 대화하십시오.",
        ["D"] =
        "$C 님, 대화해 주셔서 감사합니다. 저는 보잘것없는 사냥꾼이지만 당신의 도움을 간절히 바라고 있습니다. 유명한 순찰자, 나타노스 매리스가 이제 언데드가 되어 우리 동맹이 되었다는 소식을 들었습니다. 스컬지가 오기 전까지 그는 제 영웅이었고, 저는 직접 그와 이야기하기 위해 그의 농장으로 여행할 계획이었습니다.\n\n유감스럽게도 역병지대의 짐승들은 제가 감당하기엔 벅찹니다. 저를 대신해 순찰자 매리스와 대화해 주시겠습니까? 그가 휘두르는 것과 같은 쇠뇌를 만드는 방법을 알고 싶습니다.",
    },
    [26959] = {
        ["T"] = "영웅 숭배",
        ["O"] =
        "히포그리프나 청소부 독수리에게서 화살 깃털 20개를 모은 후, 동부 역병지대의 매리스 농장에 있는 나타노스 블라이트콜러에게 돌아가십시오.",
        ["D"] =
        "<나타노스가 한숨을 쉽니다.>\n\n언데드의 삶은 가끔 참 지루하단 말이야. 지금 당장은 딱히 할 일도 없는 것 같고. 네가 재료를 가져온다면, 기본적인 것들을 가르쳐 주마.\n\n가장 먼저 필요한 것은 화살 깃에 쓸 깃털이다. 여기 서부 역병지대나 더 먼 곳에서 튼튼한 히포그리프나 청소부 독수리에게서 구할 수 있을 거다.",
    },
    [26960] = {
        ["T"] = "영웅 숭배",
        ["O"] = "역병지대의 장작더미에서 엘프 심장목 10개를 모으십시오.",
        ["D"] =
        "간단한 일부터 시작했지. 다음 일은 훨씬 더 쉽다.\n\n쿠엘탈라스에서 발견되는 심장목이 최고의 활을 만든다. 쿠엘탈라스가 파괴되었으니 주위를 둘러보고 로데론의 폐허에 남겨진 장작더미에서 심장목을 찾을 수 있는지 살펴봐야 할 거다. 어서 움직여라!",
    },
    [26961] = {
        ["T"] = "영웅 숭배",
        ["O"] = "검은바위 첨탑의 트롤들에게서 팽팽하게 감긴 쇠뇌 시위를 모으십시오.",
        ["D"] =
        "잔일은 끝났다 $C. 이제 활시위만 있으면 된다. 과거에 나는 쿠엘탈라스에서만 만들어진 마력 깃든 엘프 실을 사용했지. 당연히, 너는 대체품이 필요할 거다.\n\n검은바위 오크와 동맹을 맺은 트롤들이 원거리 무기의 대가라는 소문을 들었다. 아마도 그들이 사용하는 활시위가 꽤 괜찮은 대체품이 될 거다. 알아내려면 검은바위 첨탑의 깊은 곳으로 내려가야 하지만... 네가 돌아올 때까지 기다리진 않겠다.",
    },
    [26962] = {
        ["T"] = "영웅 숭배",
        ["O"] = "순찰자 매리스의 기록을 보루에 있는 셸든 그림스비에게 가져가십시오.",
        ["D"] =
        "좋아, 필요한 건 다 모았다. 이걸로 뭘 해야 하는지 적어놓은 메모다.\n\n이제 네가 온 곳으로 돌아가라.",
    },
    [26963] = {
        ["T"] = "학교 첫날",
        ["O"] = "스칼로맨스 아카데미 교직원과 대화하여 이용 가능한 과정을 알아보고 필요한 서류에 서명하십시오.",
        ["D"] =
        "가장 먼저 말씀드릴 게 있습니다 -- 이곳은 평범한 교육 기관이 아닙니다. 우리는 직접 체험하는 실습 위주의 학습과, 느슨한 안내하에 스스로 주도하는 실용적인 접근 방식을 믿습니다. \"변호사\"라고 알려진 아주 고약한 구울에게 들었는데, 학교와 학생을 \"손해 배상\"과 \"너무 많은 사람들이 기웃거리는 것\"으로부터 보호하기 위해 특정한 서류에 당신의 서명을 받아야 한다는군요. 흥.\n\n특히 초보자가 다룰 때 마법과 무술 능력이 본질적으로 위험한 것은 사실입니다. 이 요구 사항을 활용하여 소개를 맡은 교직원인 닥터 애트우드, 닥터 한론, 셰프 픽맨, 감독관 필립스를 만나보실 수 있습니다.",
    },
    [26964] = {
        ["T"] = "복장 규정 준수",
        ["O"] = "부패한 거미줄 8개를 카엘 다로우에 있는 이자벨 픽맨에게 가져오십시오.",
        ["D"] =
        "당신의 첫 번째 과정은 가정 경제학입니다. 학교 예산이 부족하여 학생들은 자신의 교복을 위한 원자재를 직접 조달해야 합니다. 다행히도 이것은 쉬운 일입니다.\n\n역병지대에 사는 거미들은 특히 부패한 튼튼한 거미줄을 칩니다. 교복을 위한 원자재를 충분히 얻을 때까지 거미들을 처치한 다음, 거미줄을 우리의 가정 경제학 교사인 이자벨 픽맨에게 가져가십시오. 안돌할 폐허 북쪽, 가마솥 밭 근처나 벌목장 위에서도 이 거미들을 찾을 수 있습니다. 시작하세요!",
