    [26965] = {
        ["T"] = "복장 규정 준수",
        ["O"] = "샬롯을 죽이고 그녀의 실젓을 이자벨 픽맨에게 가져오십시오.",
        ["D"] =
        "당신이 교복 재료를 구하러 나간 사이에 내 베틀의 셔틀이 부러졌습니다. 노스렌드에서 새 것을 보내달라고 하면 너무 오래 걸리겠지만, 다행히 이 근처에서 해결할 방법이 있습니다.\n\n이 지역 거미 무리의 우두머리는 원주민들이 샬롯이라고 부르는 거대한 짐승입니다. 그녀의 실젓은 내가 베틀에 필요한 크기와 거의 일치할 것입니다. 펠스톤 농장 북서쪽의 분지에서 그녀를 찾을 수 있습니다. 이것을 첫 번째 추가 점수 획득 기회라고 생각하세요.",
