        ["D"] =
        "수업에 온 것을 환영합니다, $N. 스컬지가 역병지대를 지나가면서 이 지역의 모든 생물들에게 흔적을 남겼습니다. 진흙탕 동굴에 서식하는 진흙괴물의 진화를 연구해 보시기 바랍니다. 숙제는 그 생물들에게서 곰팡이 샘플 여섯 개를 채취하는 것입니다. 동쪽으로 역병지대를 관통하는 도로를 따라가다 다리를 건넌 후, 강을 따라 북쪽으로 올라가면 동굴을 찾을 수 있습니다.\n\n그리고 그들의 우두머리인 군주 클라크를 보게 되면, 가까이 가지 않는 게 좋을 겁니다.",
