        ["D"] =
        "흥미롭군요. 가져온 샘플은 스컬지 역병으로 인해 생겨난 것이라고 짐작했던 것보다 훨씬 연약합니다. 수업 계획을 변경해야겠습니다.\n\n달슨의 눈물 북쪽의 북마루 벌목지에 있는 붉은십자군 바보들이 이 지역에 건강한 나무를 다시 심으려는 시도로 엘윈 숲에서 거대한 흙무더기를 가져왔습니다. 내가 이 지역의 독성 토양에 곰팡이 샘플을 심어 만족스러운 결과를 얻겠지만, 엘윈에서 수입한 토양에 샘플을 심으면 어떻게 되는지 보고 싶습니다. 좀 가져다주세요!",
