    [26969] = {
        ["T"] = "스컬지 식물학",
        ["O"] = "준비된 토양에 곰팡이 샘플을 심고 결과를 관찰하십시오.",
        ["D"] =
        "진정한 식물학을 어떻게 다루는지 한 번 봅시다. 이 흙 샘플, 곰팡이, 그리고 물뿌리개를 가지고 광장 위쪽에 있는 빈 화분으로 가십시오. 화분에 흙을 채우고 곰팡이를 심으세요. 물뿌리개로 물을 약간 주고 결과를 관찰하십시오. 그런 다음 제게 보고하세요.",
