        ["D"] =
        "가정 경제학 강사로서 스칼로맨스 아카데미에서 학업을 하는 동안 스스로 건강을 챙길 수 있는지 확인하는 것이 내 임무입니다. 업무량이 많아 심장이 약한 사람에게는 적합하지 않습니다. 앞으로의 시련을 견딜 수 있도록 체력을 유지하는 데 도움이 될 혼합물을 만들었습니다. 먼저 안돌할 폐허 북쪽이나 호수 남쪽 가장자리에 서식하는 독수리에게서 엄청나게 큰 알을 구해 오세요. 둥지에 있는 알 말고요! 그건 전염병에 걸린 알입니다. 살아있는 새의 알이 필요합니다.",
