        ["D"] =
        "다로우미어 호수의 물에는 평범하고 오래된 물고기와 가끔 등장하는 호수 트레샤돈이 가득했습니다. 스컬지 역병으로 인해 물고기들은 죽었지만, 트레샤돈은 살아남았습니다. 게다가, 그들은 이전보다 훨씬 더 공격적이고 독성이 강한 모습으로 변했습니다. 그들의 타액선에는 이제 근육을 키우고 활력을 회복하는 데 도움이 되는 강력한 화합물이 들어 있습니다. 이것이 바로 우리의 비밀 재료입니다!\n\n온전한 타액선을 회수할 때까지 트레샤돈을 처치하십시오. 그런 다음 갈아버릴 준비를 합시다!",
