        ["O"] = "붉은십자군 벌목꾼에게서 암흑 저항 공책 4개를 수집하여 학장 블랙우드에게 가져오십시오.",
        ["D"] =
        "$N, 여기서 수업을 통과하는 것에 대해 분명 불안해하실 테니, 제가 특별한 제안을 하나 하죠. 붉은십자군은 벌목꾼들에게 암흑 마법으로 손상되기 어려운 특수한 공책을 지급합니다. 스컬지의 타락을 옮기지 않는 종이에 집으로 보내는 사랑하는 사람들에게 편지를 쓸 수 있다는 뭔가 그런 이유에서죠. 그건 완전히 헛소리지만 -- 그 공책은 우리의 부주의한 강령술 학생들에게 완벽합니다.\n\n당연히 벌목꾼들은 북쪽의 붉은십자군 제재소에서 찾을 수 있습니다. 공책 컬렉션을 다시 채워주시면 성적표에 보너스를 드리겠습니다.",
