    [26973] = {
        ["T"] = "고급 연금술",
        ["O"] = "채집 주사기를 사용하여 진흙탕 동굴에서 진흙괴물 샘플 세 개를 구하십시오.",
        ["D"] =
        "진흙탕 동굴은 돌연변이 진흙괴물을 자연 서식지에서 관찰하기에 아주 흥미로운 장소입니다. 난 진흙괴물을 애완동물로 키우려고 시도해 보았지만 올바른 기질을 가진 녀석을 찾는 데 너무 오래 걸렸습니다. 온순하고 점액질이지만 너무 끈적거리지 않고 역겨운... 오, 내가 무슨 말을 하고 있었죠? 오, 그렇군요, 연금술 수업 말입니다.\n\n가둬놓고 완벽한 애완 진흙괴물을 사육할 수 있는지 알아보기 위한 연구를 수행해야 합니다. 이 주사기를 가지고 죽은 진흙괴물에서 샘플을 추출하는 데 사용하십시오. 세 개 정도면 충분할 겁니다.",
