    [26974] = {
        ["T"] = "고급 연금술",
        ["O"] = "감독관 필립스와 대화하여 실험을 시작하십시오.",
        ["D"] =
        "이제 샘플을 확보했으니 조수인 감독관 필립스에게 이 다음 테스트를 관리하게 할 겁니다. 만약 물질이 내가 예상한 대로 반응한다면 그를 보호해 줄 사람이 필요합니다. 항구로 가는 길을 따라 동쪽, 안뜰 벽 밖에서 감독관 필립스를 찾으세요.\n\n그리고 $N, 이것이 이 과정의 테스트가 될 것이라는 점은 굳이 말하지 않아도 알 겁니다.",
