        ["O"] = "바로브 지하 묘지의 지하실에 있는 명판의 텍스트를 베끼십시오.",
        ["D"] =
        "역사 수업 시간입니다. 주위를 둘러보세요, $N. 만약 이 돌들이 말할 수 있다면, 아카데미를 위해 이 땅을 기증한 강력한 바로브 가문에 대한 어떤 이야기를 들려줄까요?\n\n나는 그들이 무덤에 묻힌 지 얼마 안 됐을 때 바로브 일가의 역사를 기록하고 싶습니다. 우리 교직원의 훌륭한 일원들이 학교 내에 묻혀 있는 동안 그들의 조상들은 다른 곳에 누워 있습니다. 서쪽 호수 건너편에는 슬픔의 언덕에 있는 무덤이 있습니다. 바로브 가문의 지하 묘지가 바로 거기에 있습니다. 깊은 곳으로 내려가 그 안에 묻힌 모든 사람의 이름을 가져오십시오.",
