        ["D"] =
        "당신이 서둘러 이름 목록을 적어 내려갈 때 뒤에서 이상한 소리가 들립니다.\n\n전에는 없었던 영묘한 형체가 나타납니다. 유령이 당신에게 가까이 오라고 손짓합니다. 대화를 나누는 것이 좋지 않을까요?",
