    [26978] = {
        ["T"] = "역사 101",
        ["O"] = "카엘 다로우에 있는 한론 교수에게 이 정보를 가지고 돌아가십시오.",
        ["D"] =
        "이제 제 이야기를 알게 되셨으니, 진실을 바로잡아 주십시오. 언젠가 암흑스승 간들링이 저를 가두고 있는 속박이 풀리고 제 영혼이 평안을 찾을지도 모릅니다. 그런 날이 올 때까지는 적어도 한 명이라도 진실을 안다는 사실에 위안을 삼겠습니다. 빛의 축복이 당신과 함께하길, $C님. 빛은 저를 버렸다는 것을 압니다.",
    },
    [26979] = {
        ["T"] = "졸업반의 장난",
        ["O"] = "하스글렌으로 가는 북쪽 도로에 있는 붉은십자군 간이화장실에서 배설물을 좀 구하십시오.",
        ["D"] =
        "이봐요! 신입생! 이리 와봐요!\n\n학기가 끝나가는데 그냥 넘길 순 없죠. 스칼로맨스 아카데미에 걸맞은 졸업반 장난을 치려고요. 하지만 진짜로 졸업하려면 공부를 해야 해요. 현자 폴켈트는 날짜에 정말 깐깐한 분이거든요.\n\n그래서 당신이 도와줬으면 해요. 최고의 졸업반 장난을 칠 수 있게 재료를 구해주면 그에 맞는 보상을 할게요! 먼저, 냄새나는 게 좀 필요해요. 달슨의 눈물 북동쪽, 하스글렌으로 가는 길에 붉은십자군의 방어 시설 근처에 간이화장실이 있어요. 거기서 배설물을 좀 가져다주세요!",
    },
    [26980] = {
