        ["O"] = "붉은십자군 기원사에게서 유황 조각을 수집하십시오.",
        ["D"] =
        "다음엔 불을 아주 빨리 낼 수 있는 게 필요해요. 붉은십자군 기원사들은 화염 마법의 시약으로 유황 조각을 들고 다니죠. 그거면 딱 좋을 거예요. 여기로 한 조각 가져다주세요. 정말 엄청날 거예요!",
    },
    [26981] = {
        ["T"] = "졸업반의 장난",
        ["O"] = "우서 경의 무덤, 보루, 그리고 서리바람 야영지에 있는 배설물 자루에 불을 지르십시오.",
        ["D"] =
        "라베니안과의 전투 시험에서 떨어질 뻔했는데, 머리카락이 다시 자란 덕분에 재시험을 보게 해주기로 했어요. 장난을 끝내려면 당신에게 의지할 수밖에 없네요.\n\n우서 경의 무덤, 서리바람 야영지, 그리고 보루에 배설물 자루를 놔뒀어요. 가서 거기에 불을 붙여 주세요, $N. 최고죠! 그리고 누가 했냐고 물어보면 꼭 제가 했다고 말해주세요.\n\n만약 선생님이라면 당신이 했다고 하고요.",
