        ["O"] = "동부 역병지대 경계의 강을 따라 있는 티리온 폴드링에게 닥터 한론의 초대장을 전해주십시오.",
        ["D"] =
        "잠깐만요, $N. 가기 전에 할 말이 있습니다. 역사 과목에서 당신을 합격시키지 못해 유감입니다. 하지만 운이 좋으시군요. 저를 위해 작은 심부름을 하나 해주신다면 다시 제 호의를 얻을 수 있습니다.\n\n당신이 사람들과 대화를 잘한다는 것을 보여주었으니, 최근에 스컬지에서 살아남았다는 악명 높은 사람과 대화해 보았으면 합니다. 그의 이름은 티리온 폴드링이고, 한때 로데론 사회의 저명한 인물이었습니다. 그를 인터뷰해서 자신의 교단을 배신한 기분이 어떤지 알아보고 싶습니다.\n\n이 인터뷰 요청서를 그에게 가져가 주십시오. 그는 동부 역병지대의 톤드로릴 강 북쪽 끝에 살고 있습니다.",
    },
    [26984] = {
        ["T"] = "현장 학습",
        ["O"] = "동부 역병지대 다로우미어 호수 기슭에 있는 스타링 교수를 찾으십시오.",
        ["D"] =
        "다로우미어 호수 북쪽 기슭에서 실습 강사인 스타링 교수를 찾을 수 있을 겁니다. 그녀가 보충 학습 과정에 대해 소개해 줄 겁니다. 입문 과정이 어렵다고 생각했다면, 글쎄요... 이 교육 과정은 정말 치명적입니다. 안녕히 가십시오, $N.",
    },
    [26985] = {
        ["T"] = "학술 등록",
        ["O"] = "서부 역병지대의 카엘 다로우 섬에 있는 학장 블랙우드와 대화하십시오.",
        ["D"] =
        "안녕하세요. 저는 무술과 마법을 가르치는 특별한 아카데미를 대표하며, 당신이 주문과 무기를 다루는 데 소질이 있어 보이는 것을 알게 되었습니다. 저희 입문 과정을 이수하고 학교에 잘 맞는지 확인해 보실 것을 공식적으로 초대합니다. 시작하려면 이 소개장을 서부 역병지대의 카엘 다로우 섬에 있는 학장 블랙우드에게 가져가십시오.\n\n이 편지를 수락함으로써 귀하는 방문 학생 정책 및 비공개 계약을 준수하는 데 동의하게 됩니다. 우리는 신원 조사, 이해 상충 평가 또는 소지품 평가를 수행할 수 있습니다.\n\n스칼로맨스 아카데미에서 만나 뵙기를 기대하겠습니다. 화이팅, 고스트!",
    },
    [26986] = {
        ["T"] = "학술 등록",
        ["O"] = "서부 역병지대의 카엘 다로우 섬에 있는 학장 블랙우드와 대화하십시오.",
        ["D"] =
        "안녕하세요. 저는 무술과 마법을 가르치는 특별한 아카데미를 대표하며, 당신이 주문과 무기를 다루는 데 소질이 있어 보이는 것을 알게 되었습니다. 저희 입문 과정을 이수하고 학교에 잘 맞는지 확인해 보실 것을 공식적으로 초대합니다. 시작하려면 이 소개장을 서부 역병지대의 카엘 다로우에 있는 학장 블랙우드에게 가져가십시오.\n\n이 편지를 수락함으로써 귀하는 방문 학생 정책 및 비공개 계약을 준수하는 데 동의하게 됩니다. 우리는 신원 조사, 이해 상충 평가 또는 소지품 평가를 수행할 수 있습니다.\n\n스칼로맨스 아카데미에서 만나 뵙기를 기대하겠습니다. 화이팅, 고스트!",
    },
    [26987] = {
        ["T"] = "귀향",
        ["O"] = "데피아즈단에게서 낸시의 머리카락을 되찾아 도널드 이스트워스에게 보여주십시오. 그가 가족에게 돌아오도록 설득해 보십시오.",
        ["D"] =
        "실례합니다! 잠시만 머물러 주시겠어요?\n\n사과드릴게요. 제 딸이 조금... 겁을 먹어서요. 데피아즈단이 나타난 이후로 제정신을 유지하기가 힘들었어요. 남편 도널드가 사랑하는 농장과 사랑하는 가족을 떠나 데피아즈단에 합류하기로 결정했다는 사실을 믿으시겠어요!? 어떻게 저와 어린 티나를 남겨두고 떠날 수 있죠?\n\n제가 남편을 설득하려고 노력한 뒤에 그의 새로운 친구들이 우릴 찾아왔어요. 우린 너무 무서웠죠! 그들은 우리 딸을 해치진 않았지만... 제 머리카락을 자르고 우릴 농장에서 내쫓았어요. 제게 경고하려고 그런 짓을 한 거예요. 절 모욕하던 그들의 포식자 같은 눈빛은 절대 잊지 못할 거예요. 그들은 제 땋은 머리를 전리품으로 가져갔고, 또다시 간섭하려고 하면 더 끔찍한 일을 당할 거라고 경고했어요.\n\n그 이후로 남편에 대한 소문만 들었어요. 어떤 사람들은 남편이 그늘숲에서 달빛시내 마을로 이동하는 불운한 상인들을 약탈한다고 하더군요. 제발, 그 늙은 멍청이가 우리에게 돌아오도록 설득해 주세요. 우린 돌아갈 집도 없고 도널드의 새로운 동료들은 독수리처럼 감시의 언덕 주위를 맴돌고 있어요! 데피아즈단 중 한 명에게서 제 땋은 머리를 찾아 남편에게 보여준다면, 그의 새 친구들이 무슨 짓을 저지를 수 있는지 경고가 될지도 몰라요.",
    },
    [26988] = {
        ["T"] = "고집 센 남자",
        ["O"] = "낸시 이스트워스와 대화하십시오.",
        ["D"] =
        "오래된 속담이 있지. 그들과 싸울 수 없다면 그들과 합류하라. 스톰윈드의 관리들이 서부 몰락지대의 사람들에게 신경 쓰지 않으니, 우리는 우리 스스로 문제를 해결해야 하네. 그래, 민병대가 있긴 하지만, 난 이곳의 진짜 권력자를 위해 일하지.\n\n이봐, 몇 주 후면 남방해안에 집을 빌릴... 아니, 집을 지을 수 있을 만큼 충분한 돈을 벌게 될 거야. 난 위험을 감수해야 했고 낸시는 그걸 받아들여야만 해. 그리고 데피아즈단을 좀 더 존중해야 할 거야.\n\n하지만 낸시에게 내가 그리워한다고 전해줘. 내가 그녀들을 사랑하고 곧 돌아갈 거라고, 그리고 돌아갈 땐 이 저주받은 붉은 복면과 함께 과거를 묻어버릴 거라고 말이야!\n\n자, 이제 날 내버려둬. 곧 고블린 상인이 다리를 지나갈 거라는 소식을 들었거든. 그 일이 일어날 때 이곳에 있고 싶진 않을 텐데.",
    },
    [26989] = {
        ["T"] = "엄지를 치켜들고, 남자는 쓰러지다",
        ["O"] = "도널드의 피투성이 엄지손가락을 낸시 이스트워스에게 가져가십시오.",
        ["D"] =
        "그 늙은 바보가 동전 몇 닢을 위해 우리 모두의 목숨을 걸 때까지 더 이상 기다리지 않을 거예요.\n\n처음엔 제 땋은 머리를 잃었고, 다음엔 제 목에 칼이 들어올지도 몰라요. 아니면 더 끔찍한 일이 생길지도요! 오, 빛이시여 우릴 인도하소서! 다가올 어두운 시기를 이겨내려면 빛이 필요해요.\n\n티나와 저는 강해져야 하고 독립해야 해요, 지금 당장요. 우린 떠날 거예요. 설령 제가 티나를 어깨에 업고 검은바위 산을 지나야 한다고 해도 -- 우린 꼭 떠나야만 해요. 하지만 우리의 미래를 지키기 위해 당신에게 마지막으로 한 가지 부탁을 하고 싶어요. 도널드에게 절대 잊지 못할 교훈을 가르쳐주세요.\n\n데피아즈단이 제게 위협했던 것처럼, 그를 아주 반쯤 죽여 놓으세요. 그가 그렇게 잃고 싶어 하는 것 같은 그의 엄지손가락을 제게 가져오세요. 굳이... 그를 죽일 필요까진 없어요. 뼈 몇 개 부러뜨리는 것만으로 충분할 거예요. 그가 우리를 쫓아오지 못하게만 해주세요 -- 그가 가는 곳엔 언제나 불행이 따르니까요.",
    },
    [26990] = {
        ["T"] = "강물발바닥부족의 난동",
        ["O"] = "강물발바닥부족 놀 8마리와 강물발바닥부족 정찰병 8마리를 처치한 후 감시의 언덕에 있는 민병대원 가리엘에게 돌아가십시오.",
        ["D"] =
        "민병대에 도움이 필요합니다! 강물발바닥부족 놀들이 서부 몰락지대 시민들을 공격하고 있습니다! 스톰윈드는 아무런 도움도 보내지 않고, 우리는 스스로 방어해야만 하는 처지입니다. 우리를 돕고 싶으시다면 놀들에 대한 공격을 이끌어 주십시오.\n\n북쪽의 장고로드 광산과 펄브라우 호박밭 근처에서 놈들의 야영지 몇 곳을 찾을 수 있을 것입니다. 서부 몰락지대는 당신의 도움을 매우 고맙게 생각할 것입니다. 자, 가서 이 괴물들을 끝장내 주십시오!",
    },
    [26991] = {
        ["T"] = "강물발바닥부족의 난동",
        ["O"] = "강물발바닥부족 똥개 8마리와 강물발바닥부족 채집꾼 8마리를 처치하고 감시의 언덕에 있는 민병대원 가리엘에게 돌아가십시오.",
        ["D"] =
        "일이 다 끝났다고 생각하셨습니까? 천만에요... 놀들은 서부 몰락지대 곳곳에 야영지를 흩어놓고 있습니다. 앞서 도와주신 건 감사하지만, 너무 자만하지는 마십시오. 혼쭐을 내줘야 할 놀들이 아직 더 남아있습니다.\n\n황금해안 채석장 남쪽으로 가서 서부 몰락지대에서 놀들을 좀 더 제거해 주십시오. 놈들의 부족 중 더 강한 놈들이 경비를 서고 있는 야영지를 발견하게 될 것입니다. 당신이 이 임무를 맡아주시기를 바랍니다 -- 당신이 죽는 건 보고 싶지 않으니까요.",
    },
    [26992] = {
        ["T"] = "강물발바닥부족의 난동",
        ["O"] = "강물발바닥부족 도적 8마리와 강물발바닥부족 감독관 8마리를 처치하고 감시의 언덕에 있는 민병대원 가리엘에게 돌아가십시오.",
        ["D"] =
        "아직 살아계시다니 놀랍군요. 전 당신이 그 놀들에게 죽을 줄 알았습니다! 어쨌든, 정찰병들에게서 가장 강력한 강물발바닥부족 놀 몇 마리가 이곳 남쪽의 먼지 언덕에 진을 쳤다는 보고를 받았습니다. 당신과 함께 보낼 병사를 몇 명 지원해 드리고 싶지만, 우리 병력은 분산되어 있습니다. 당신 혼자 가야 할 것 같습니다.\n\n민병대의 이름으로, 가서 놀들에게 정의의 심판을 내리십시오! 서부 몰락지대는 더 이상 놈들을 용납하지 않을 것입니다!",
    },
    [26993] = {
        ["T"] = "죽음의 들판",
        ["O"] = "녹슨 허수아비 골렘 10마리를 처치하고 얀센 농장의 농부 펄브로우에게 돌아가십시오.",
        ["D"] =
        "이 땅의 꼴을 보십시오! 기계 공포물들을 만들어 이 들판으로 내보내는 고블린들을 둔 데피아즈단에게 저주를! 우리 농부들은 이런 걸 원한 적이 없습니다. 이 골렘들이 계속 여기 있다면 저와 늙은말 블랑쉬는 어떻게 가족을 먹여 살려야 한단 말입니까?\n\n근처에 있는 골렘들을 처치하는 걸 좀 도와주시겠습니까? 바로 이 근처나 서쪽의 제 호박밭 주변에서 찾을 수 있을 겁니다. 제발 우릴 도와주십시오! 스톰윈드는 우리를 포기했습니다.",
    },
    [26994] = {
        ["T"] = "죽음의 들판",
        ["O"] = "살딘 농장의 농부 살딘과 대화하십시오.",
        ["D"] =
        "이 근처의 골렘들을 훌륭하게 처리해주셨군요. 하지만 이 문제로 골머리를 앓고 있는 건 저뿐만이 아닙니다. 제 좋은 친구인 살딘 역시 골렘들이 그의 농장을 파괴하고 있다고 말했습니다. 그를 도와주실 수 있겠습니까? 그의 농장은 이쪽에서 남쪽으로 가다 보면 나올 겁니다.",
    },
    [26995] = {
        ["T"] = "죽음의 들판",
        ["O"] = "허수아비 골렘 10마리를 처치하고 살딘 농장의 농부 살딘에게 돌아가십시오.",
        ["D"] =
        "이곳을 도와주는 분이 계시다니 정말 기쁩니다. 이 골렘들은 우리 주민들에게 겁을 주고 있으며, 이 문제를 빨리 해결하지 않으면 서부 몰락지대가 데피아즈단에게 점령당할까 봐 두렵습니다. 어쨌든, 밖으로 나가 골렘들을 처치해 주십시오! 이 농장이나 서쪽에 있는 몰센 농장에서 놈들을 찾으실 수 있을 겁니다.",
    },
    [26996] = {
        ["T"] = "죽음의 들판",
        ["O"] = "허수아비 암살자 10마리를 처치하고 살딘 농장의 농부 살딘에게 돌아가십시오.",
        ["D"] =
        "당신이 아까 처치한 골렘들만이 우리 땅을 훼손하고 있는 건 아닙니다! 우리 농부 중 한 명이 황금해안 채석장 근처에 있는 알렉스턴 농장에서 골렘 무리를 더 봤다고 하더군요. 골렘들을 좀 더 처치해 주신다면 정말 감사하겠습니다.",
    },
    [26997] = {
        ["T"] = "죽음의 들판",
        ["O"] = "허수아비 수확기 10마리를 처치하고 살딘 농장의 농부 살딘에게 돌아가십시오.",
        ["D"] =
        "우리 농장의 대부분은 되찾았지만, 아직 싸워야 할 농장이 하나 남아 있습니다. 여기서 감시의 언덕을 지나 남쪽으로 멀리 가면 메마른 논밭이 나오는데, 그곳에는 가장 강력한 골렘들이 돌아다니며 땅을 태우고 있습니다. 그곳에 일꾼 몇 명을 데려가려 했지만, 골렘들이 우릴 쫓아냈습니다! 이 임무를 맡아주셨으면 합니다, $n 님. 그 골렘들은 장난이 아니거든요!",
    },
    [26998] = {
        ["T"] = "현상 수배: 약탈자 그나르팡",
        ["O"] = "약탈자 그나르팡을 처치하고 감시의 언덕에 있는 정찰대장 다누빈에게 그의 발바닥을 가져가십시오.",
        ["D"] =
        "서부 몰락지대 시민 여러분, 주의하십시오! 약탈자 그나르팡이라고 알려진 위험한 놀이 흩어져 있던 강물발바닥부족을 통합하여 우리 땅을 공포에 떨게 하고, 농장을 약탈하며 주민들을 공격하고 있습니다!\n\n우리는 그의 난동에 종지부를 찍을 당신과 같은 용감한 모험가들이 필요합니다. 그나르팡은 감시의 언덕 남쪽 언덕을 배회하는 것으로 알려져 있습니다. 당신의 용기의 증표로 감시의 언덕에 있는 정찰대장 다누빈에게 그의 발바닥을 가져가면 넉넉한 보상을 받을 것입니다.",
    },
    [26999] = {
        ["T"] = "네크로쉬는 죽어야 한다",
        ["O"] = "족장 네크로쉬를 처치하고 그의 머리를 시장 오크마스터에게 가져가십시오.",
        ["D"] =
        "자, 이제 못된 녀석, 네크로쉬 차례군. 엄청난 덩치에 아주 잔인한 녀석이지. 줄루마르에 있는 그 거대한 요새에서 좀처럼 나오지 않아.\n\n자네가 처치한 세 명의 지도자는 하루에 두 번 그에게 보고를 하니, 그들이 나타나지 않으면 의심을 할 거야. 자네가 그의 목을 치러 가는 데 누구의 허락을 받을 필요는 없지.\n\n요새 안의 방어가 어떤지는 모르니 조심하게나.\n\n행운을 비네, $n.",
    },
    [27000] = {
        ["T"] = "일시적인 승리",
        ["O"] = "번두랄의 승리 소식을 경비대장 스타우트피스트에게 전하십시오.",
        ["D"] =
        "자네는 스타우트피스트 대장님이 보냈으니, 여기서 일어난 일을 그에게 말하는 것이 옳을 걸세. 메네실에 있는 그에게 돌아가 우리가 추가 지원이 필요 없다는 것을 알리게나.",
    },
    [27001] = {
        ["T"] = "굴다르 도박",
        ["O"] = "상부 늪지대에 있는 던 굴다르에 도착하여 시장에게 도움을 제안하십시오.",
        ["D"] =
        "우리가 용아귀 부족에게 싸움을 걸 때가 왔소. 그들의 야영지를 밀어붙여 던 굴다르 고갯길까지 가주시오.\n\n전령을 찾았던 동쪽을 향해 메네실을 나선 다음, 남쪽으로 향하시오.\n\n그곳에 도착하면 서쪽으로 돌아 던 굴다르를 만나게 될 것이오.\n\n그곳에 도착하면 번두랄 시장을 찾아 대화하고 그를 돕기 위해 왔다고 말하시오.",
    },
    [27002] = {
        ["T"] = "최전선에 보고하라",
        ["O"] = "번두랄 최전선에 있는 사령관 스트롱본에게 보고하십시오.",
        ["D"] =
        "전 예전에 번두랄의 시장이었습니다. 사람들이 던 굴다르 고갯길을 통해 실종되기 시작했을 땐 대수롭지 않게 여겼죠... 딸꾹.\n\n다음 순간 그들은 한밤중에 공격했고, 적절한 대응이 이루어지기도 전에 마을의 절반을 점령했습니다... 딸꾹!\n\n우리의 사령관인 스트롱본이라는 분은 아직 최전선에 있습니다. 용아귀가 우리의 좋은 에일을 빼앗아 가지 못하게 제가 계속 지키고 있을 테니 부디 그에게 가서 도움을 제안하십시오... 딸꾹. 마을을 벗어나 동쪽으로 향하면 바로 앞에 번두랄이 보일 겁니다... 딸꾹.",
    },
    [27003] = {
        ["T"] = "침착하고 냉정하게",
        ["O"] = "광란에 빠진 피난민 5명을 진정시키십시오.",
        ["D"] =
        "도대체 시민들은 왜 힘든 상황에서 이성을 잃는 걸까?\n\n머리 잘린 닭처럼 뛰어다니며 우리의 방어를 방해하고 있어. 그들과 대화하고 제정신을 차리게 해서 던 굴다르의 안전한 곳으로 향하게 해 주게.",
    },
    [27004] = {
        ["T"] = "그들을 밀어내라",
        ["O"] = "번두랄에 있는 용아귀부족 마술사 6명과 용아귀부족 교도관 6명을 처치하십시오.",
        ["D"] =
        "우리는 이곳에서 목숨을 걸고 싸우고 있지만, 약간의 지원만 있다면 용아귀를 밀어낼 수 있습니다.\n\n적의 최전선은 우리의 마지막 방어선에 있으며, 우리는 이곳에서 용아귀를 무찌르지 않으면 죽게 됩니다.\n\n최전선에 있는 적의 마술사와 교도관들을 처치하면 전세를 진정으로 바꿀 방법을 계획할 수 있을 것입니다.",
    },
    [27005] = {
        ["T"] = "전쟁의 전리품",
        ["O"] = "최전선에서 용아귀부족 무기 8개를 훔치십시오.",
        ["D"] =
        "이 공세를 늦추고 싶다면 보급선의 가장 중요한 부분인 무기를 없애야 해.\n\n저 오크들은 아주 고통스러워 보이는 도끼, 단검, 검 등이 가득 담긴 큰 선반을 가져왔지.\n\n최전선에서 무기를 없애고 우리가 사용할 수 있게 탈취한다면 용아귀들을 쫓아낼 수 있을 거야.",
    },
    [27006] = {
        ["T"] = "줄루마르의 눈",
        ["O"] = "줄루마르 근처 상부 늪지대에서 정찰병 발리브루를 찾으십시오.",
        ["D"] =
        "우리는 용아귀 요새인 줄루마르로 싸움을 가져가야 하네. 우리에게는 발리브루라는 이름의 정찰병이 길을 감시하고 있어서 용아귀가 병력을 보낼 때를 알 수 있지.\n\n그는 줄루마르 내부에서 무슨 일이 일어나고 있는지 속속들이 알고 있어. 그를 찾게, 그러면 그가 우리가 공격해야 할 정밀한 목표물을 안내해 줄 걸세.\n\n우리가 마지막으로 받은 보고서에 따르면, 그는 용아귀가 던 굴다르에서 도망치면서 파괴한 짐마차 뒤에 숨어 있다고 하더군. 이렇게 많은 파괴라니... 어쩌다 이 지경이 된 걸까?",
    },
    [27007] = {
        ["T"] = "고통스러운 곳을 노려라",
        ["O"] = "줄루마르 밖에서 정찰병 발리브루를 위해 용아귀부족 검귀 6명과 그들의 우두머리인 조루크를 처치하십시오.",
        ["D"] =
        "네크로쉬가 마음대로 부릴 수 있는 가장 사나운 전사들은 검귀라네. 그들은 줄루마르 입구의 임시 감시탑에서 음흉하게 노려보는 잔인한 감시자 조루크에게 훈련을 받지.\n\n근원부터 그들의 훈련을 끊어버린다면, 머지않아 용아귀는 가장 강한 투사들을 잃게 될 걸세. 그러면 그들 중 강한 자들이 권력을 다투면서 내부 분열이 일어나겠지.\n\n강력한 지도력이 없으면 그들은 항상 옛 방식으로 돌아가게 마련이야.",
    },
    [27008] = {
        ["T"] = "번두랄의 도살자들",
        ["O"] = "저습지에서 정찰병 발리브루를 위해 용아귀부족 도살자 6명과 야수조련사 모르를 처치하십시오.",
        ["D"] =
        "숫자로 판단해 볼 때 용아귀 도살자들이 처치한 수가 가장 많습니다.\n\n그들의 우두머리인 야수조련사 모르와 함께 동이 틀 무렵이면 길을 나서는 여행자들을 공격하고 저습지의 야생 동물을 사냥하기 위해 나섭니다.\n\n용아귀들이 자신들의 병사조차 먹여 살릴 수 없다는 것을 깨닫게 된다면, 그들을 쓰러뜨리는 것은 골칫거리를 없애는 것 이상의 의미가 있을 겁니다.\n\n용아귀 도살자들에게 그들 자신의 약맛을 보여주고, 야수조련사도 그들과 함께 제거하십시오.",
    },
    [27009] = {
        ["T"] = "대피 보고",
        ["O"] = "시장 오크마스터에게 최종 대피 보고서를 전달하십시오.",
        ["D"] =
        "대피자들이 마지막이길 바랍니다. 당신은 저와 이 마을 사람들에게 큰 봉사를 해주셨습니다. 이제 마침내 그 보고서를 시장에게 다시 가져다줄 수 있게 되었습니다.\n\n이것을 그에게 가져다주시면 제 등에서 내려올 겁니다.",
    },
    [27010] = {
        ["T"] = "대피 보고",
        ["O"] = "롱뷰 전초기지에 있는 마운틴뷰 상병에게서 최신 대피 보고서를 받으십시오.",
        ["D"] =
        "용아귀가 아직 번두랄 끝까지 쳐들어온 것은 아닙니다... 딸꾹. 구할 수 있었던 사람들도 있을 겁니다... 딸꾹. 마을 바로 외곽에 있는 롱뷰 전초기지에서 마운틴뷰 상병을 찾아보세요 -- 이미 지나오셨을 겁니다.\n\n그에게 아직 떠나지 않은 사람이 누구인지 전체 보고를 요청하세요. 지금쯤이면 남은 사람이 아주 적을 겁니다... 딸꾹.",
    },
    [27011] = {
        ["T"] = "골렘 자이로스코프",
        ["O"] = "상부 늪지대의 던 굴다르에 있는 안구스 씩바텀을 찾으십시오.",
        ["D"] =
        "우리 골렘이 부서진 후 아버지가 저를 이곳으로 보냈고, 저는 몇 주째 부품을 기다리고 있습니다.\n\n불행히도 그 이후로 빌어먹을 용아귀들이 고갯길을 완전히 점령해서 이젠 제가 안전하게 돌아갈 방법이 전혀 없습니다.\n\n부디 아버지께 제가 살아있고 무사하지만, 그 부품들을 아버지께 가져갈 수는 없다고 전해주십시오.\n\n그에게 가려면 메네실에서 용아귀가 보일 때까지 동쪽으로 향한 다음, 던 굴다르 고갯길 너머 상부 늪지대로 남쪽으로 향한 후, 정서쪽으로 향해 던 굴다르에 도달해야 합니다.",
    },
    [27012] = {
        ["T"] = "골렘 자이로스코프",
        ["O"] = "번두랄의 대장간에서 자이로스코프 2개를 구하십시오.",
        ["D"] =
        "절박한 시기에는 절박한 조치가 필요합니다. 골렘을 수리할 때까지 피난민을 돕는 데 우리 골렘을 기여할 수 없거든요.\n\n당신은 여기까지 올 정도로 용감하게 용아귀에 맞섰으니, 번두랄 마을로 가주실 수 있을 겁니다. 던 굴다르 바로 외곽이 포위되어 있죠. 대장장이와 대다수의 마을 사람들은 도망쳤지만, 남겨둔 부품이 있을지도 모릅니다.\n\n가서 자이로스코프 2개를 찾을 수 있는지 확인해 보십시오. 그러면 제가 이 골렘을 작동시킬 수 있을지도 모릅니다.",
    },
    [27013] = {
        ["T"] = "골렘 자이로스코프",
        ["O"] = "안구스의 농장에서 골렘 수리를 시도하십시오.",
        ["D"] =
        "시작합시다! 저 골렘을 작동시킬 수 있다면 우리 난민들을 쉽게 먹여 살릴 수 있지만, 골렘이 없으면 우린 도와줄 힘이 없습니다.\n\n이 자이로스코프를 가져가서 장착하세요. 골렘이 움직이는지 한번 보자고요!",
    },
    [27014] = {
        ["T"] = "산양 목장 구출",
        ["O"] = "글로리 크램버를 설득하여 상부 늪지대에 있는 집에서 대피하도록 하십시오.",
        ["D"] =
        "번두랄 북쪽에 있는 산양 목장의 크램버 일가는 대대로 이곳에 살아왔고, 고집불통인 늙은 글로리는 떠나려 하지 않을 겁니다.\n\n망할 산처럼 지어진 데다 고집도 산만큼 셉니다. 꿈쩍도 하지 않을 거예요!\n\n떠나라고 설득해 봤지만 소용이 없었습니다. 당신이 한번 설득해 보시겠습니까?",
    },
    [27015] = {
        ["T"] = "과감한 조치",
        ["O"] = "번두랄의 교도관과 마술사들로부터 조잡한 용아귀부족 의상을 만들 부품을 구하십시오.",
        ["D"] =
        "저희 아버지는 까다롭고, 오만하고, 고집 센 늙은 바보입니다. 우리는 지평선에서 피어오르는 연기를 볼 수 있습니다. 저는 용아귀가 농장 주변을 몰래 돌아다니는 것을 잡은 적이 있고 당신도 번두랄에서 들려오는 비명소리를 들었을 겁니다.\n\n하지만 아니요, 아버지는 자신의 눈으로 직접 보기 전까지는 공격이 있다는 것을 인정하려 하지 않습니다. 아버지는 이 모든 게 사기이고, 앰버스틸 가문이 차지하려 드는 것일 뿐이라고 계속 중얼거립니다.\n\n과감한 조치가 필요합니다. 번두랄로 가서 조각난 장비를 이용해 용아귀 변장용으로 쓸 부품을 충분히 수집해 오세요. 저에게 아이디어가 있습니다...",
    },
    [27016] = {
        ["T"] = "과감한 조치",
        ["O"] = "용아귀로 변장하고 두 개의 산양 방목장과 마구간에 불을 지르십시오.",
        ["D"] =
        "이제 당신에게 극단적인 부탁을 하나 해야겠습니다, $c. 구해온 의상으로 변장하고 방목장을 돌아다니며 불을 질러 산양들을 겁줘서 쫓아내세요.\n\n네... 압니다... 극단적이라는 걸요. 하지만 아버지는 우리가 진짜 위험에 처하기 전까진 믿지 않으실 겁니다. 용아귀보단 당신이 낫죠.",
    },
    [27017] = {
        ["T"] = "고원 달아나기",
        ["O"] = "라우시 가족이 대피하도록 설득하십시오.",
        ["D"] =
        "번두랄 남쪽에는 라우시 가족이 있습니다. 이곳에 사는 유일한 인간이죠.\n\n서부 몰락지대를 떠난 후 땅과 연못이 있는 멋진 작은 곳을 샀어요. 주변에서 가장 훌륭한 작물을 생산합니다.\n\n그들이 지나가는 걸 못 봤는데, 대피의 시급함을 일깨워줘야 할 것 같습니다.\n\n제발, $n, 용아귀가 밀고 들어오기 전에 가서 그들과 대화하고 대피시키세요.",
    },
    [27018] = {
        ["T"] = "작업이 끝날 때까지",
        ["O"] = "가린의 옥수수 작물 10개를 모으십시오.",
        ["D"] =
        "길을 떠나 이곳을 벗어나려면 식량이 필요할 겁니다. 다행히 마지막 작물 수확이 거의 끝났지만, 제 가족이 떠날 준비를 하면서 작물을 돌볼 수는 없어요.\n\n근처 밭에서 내 곡물을 수확하고 우리가 가져갈 수 있도록 준비해 준다면 순식간에 당신 눈앞에서 사라져 드릴게요.",
    },
    [27019] = {
        ["T"] = "영웅이 찾기",
        ["O"] = "고원 구석의 연못에서 사라의 인형 '영웅이'를 찾으십시오.",
        ["D"] =
        "나는 아무 데도 안 가! 연못 근처에서 내 인형 영웅이랑 놀고 있었는데, 얄미운 올드 그린이 안 돌려준다고.\n\n아빠는 우리가 떠날 거라고 하지만 난 영웅이를 두고 가지 않을 거야!\n\n내 인형을 찾아줘!",
    },
    [27020] = {
        ["T"] = "여기서 나가자",
        ["O"] = "사디라 아이언비트를 번두랄 마을 밖으로 안전하게 호위하십시오.",
        ["D"] =
        "쾅! 저는 폭발물 관련 열성 팬이죠. 여기 있는 게 제 컬렉션이에요.\n\n용아귀들이 너무 빨리 진격해서 저는 지금 적진 뒤에 갇혀버렸어요. 절 상병에게 데려가 주신다면 이 물건들을 유용하게 쓸 수 있을 거라고 확신해요.\n\n남겨진 물건들은 용아귀들이 우리를 상대로 쓰지 못하게 도망가면서 부숴야 해요.\n\n제가 안전해지면 던 굴다르에 있는 닉시 이모에게 말해주세요. 이모가 걱정하시겠지만, 저는 날려버려야 할 오크들이 있거든요!",
    },
    [27021] = {
        ["T"] = "메네실로 보내는 메시지",
        ["O"] = "번두랄 공고를 발스탁 아이언조에게 배달하십시오.",
        ["D"] =
        "당신 앞의 전령은 간신히 손을 뻗어 피에 젖은 쪽지를 당신의 손에 꼭 쥐여준 뒤, 발스탁이라는 이름을 중얼거리고 의식을 잃습니다.\n\n메네실 항구에서 그 쪽지의 수신자를 찾으십시오.",
    },
    [27022] = {
        ["T"] = "전령을 죽이지 마라",
        ["O"] = "부상당한 번두랄 전령을 치료하십시오.",
        ["D"] =
        "이 쪽지를 저에게 가져오려던 전령은 목숨을 걸었습니다. 당신의 말에 따르면 그에게는 아직 숨이 붙어 있습니다.\n\n우리는 그가 늪지에서 죽도록 내버려 둘 수 없습니다. 자, 이걸로 정찰병의 생명력을 조금 회복시켜 그들이 이곳에 안전하게 도착할 수 있도록 해주십시오.",
    },
    [27023] = {
        ["T"] = "새끼용 조련사들",
        ["O"] = "용아귀부족 어둠의손 6명과 그들의 우두머리인 정복자 샤로그를 처치하십시오.",
        ["D"] =
        "용아귀부족은 모든 용을 혐오한다고 주장하지만, 그것이 용을 자신의 의지대로 굴복시키는 것을 막지는 못합니다.\n\n줄루마르 안의 어둠의손들은 그들 중에서도 가장 유능한 용 조련사들입니다. 이 지식은 가장 숙련된 조련사 정복자 샤로그의 직접적인 가르침을 통해 그들에게 전수되었습니다.\n\n그와 그의 제자들은 줄루마르 북쪽, 저습지를 내려다보는 거대한 마법사 탑에서 찾을 수 있습니다.",
    },
    [27024] = {
        ["T"] = "하지리의 연대기",
        ["O"] = "아메스아란에서 떠돌이 학자를 찾으십시오.",
        ["D"] =
        "만나서 반갑습니다, 여행자여. 저는 엘룬의 자매회 여사제, 티라이스라고 합니다. 중요한 연구를 완료하기 위해 이곳에 파견되었지만 임무가 교착 상태에 빠진 것 같습니다.\n\n고대의 전쟁 이전 칼도레이 제국의 전성기 시절, 지금의 조람 해안과 어둠해안 남부에 하지리라는 도시가 있었습니다. 최근 아스트라나르를 지나던 떠돌이 학자가 나가가 제국 몰락 이전의 기록을 복구하기 위해 폐허에서 작업 중이라고 하더군요. 저는 그 기록을 복구하고 싶습니다.\n\n여사제로서 제 의무 때문에 아스트라나르를 떠날 수는 없지만, 당신에게는 이동의 자유가 있습니다. 저를 도와주신다면 떠돌이 학자를 찾아주십시오. 그녀는 어둠해안의 아메스아란 방향으로 향한다고 했습니다.",
    },
    [27025] = {
        ["T"] = "하지리의 연대기",
        ["O"] = "아메스아란에서 아샬렌이 수호물을 뚫을 때까지 그녀를 방어하십시오.",
        ["D"] =
        "제 이름은 아샬렌이고 잃어버린 예술의 학자입니다. 저는 티라이스가 찾고 있는 것이 어디 있는지 알 것 같지만, 저만의 연구를 마쳐야 합니다. 저는 교환을 제안하고 싶습니다.\n\n아메스아란 폐허 내에는 고대 마법사들이 사용했던 초점이 있습니다. 그것은 수호물로 보호받고 있는데, 오랜 세월이 지났음에도 여전히 강력한 방어력을 자랑합니다.\n\n제가 수호물을 뚫는 동안 저를 보호해 주신다면 티라이스가 찾고 있는 것을 얻도록 돕겠습니다.",
    },
    [27026] = {
        ["T"] = "하지리의 연대기",
        ["O"] = "잿빛 골짜기의 조람 해안에 있는 아샬렌과 대화하여 리알라스와의 대결을 시작하십시오.",
        ["D"] =
        "도와주셨으니 제가 왜 이 초점이 필요한지 설명할 때가 되었군요.\n\n사악한 바다 마녀, 리알라스는 티라이스가 찾고 있는 역사적 텍스트를 찾기 위해 고대 폐허를 꼼꼼하게 수색해 왔습니다. 리알라스에 대한 제 원한은 약탈자에 맞서는 역사가의 원한 그 이상입니다.\n\n고대의 전쟁 동안, 제 가족은 칼도레이 저항군과 함께 섰고, 이는 리알라스의 주의를 끌었습니다. 그녀가 우릴 잡으러 왔을 때, 그녀는 거의 뚫을 수 없는 수호물로 자신을 방어했습니다. 우리는 그녀를 막을 수 없었고, 영원의 샘 폭발만이 그녀가 우릴 몰살시키는 것을 막았습니다.\n\n저는 수년 동안 그녀의 마법을 뚫을 방법을 찾고 있었습니다. 이 초점을 손에 넣었으니, 이번엔 그녀가 사악한 마법 뒤에 숨을 수 없을 겁니다.\n\n조람 해안에서 저를 찾으세요. 함께 리알라스를 분쇄하고 티라이스가 그토록 원하던 텍스트를 손에 넣읍시다.",
    },
    [27027] = {
        ["T"] = "하지리의 연대기",
        ["O"] = "아스트라나르의 티라이스에게 하지리의 연대기를 돌려주십시오.",
        ["D"] =
        "짐작하셨겠지만, 제가 털어놓은 제 이야기에는 뭔가 더 있습니다. 당신과 함께 마을로 돌아갈 수 없어요.\n\n당신은 기록을 얻었고, 저는 제 유배지로 돌아가겠다는 약속을 지키겠습니다. 여기서 일어난 일은 우리만의 비밀로 간주해 주셨으면 합니다. 제가 가장 원치 않는 것은 신성한 법을 어겨 여사제에게 쫓기는 일이니까요.",
    },
    [27028] = {
        ["T"] = "하지리의 연대기",
        ["O"] = "별가루 폐허의 성물함에서 샘플을 회수하여 아스트라나르의 티라이스에게 돌아가십시오.",
        ["D"] =
        "이 책의 현재 상태로는 왜 나가가 애초에 이 책을 찾았는지 알아낼 수 없을 겁니다. 그렇다고 제게 방법이 없는 것은 아닙니다.\n\n아스트라나르 남쪽에는 한때 별가루라고 불리던 곳이 있습니다. 비록 폐허가 되었지만, 그곳에는 여전히 가장 순수한 물의 근원이 남아 있습니다.\n\n그곳으로 가서 이 유리병을 별가루의 물로 채우세요. 조심하십시오, 폐허에는 위험한 생물들이 살고 있으니까요.",
    },
    [27029] = {
        ["T"] = "하지리의 연대기",
        ["O"] =
        "아스트라나르 서쪽에 있는 아에시나의 제단으로 가서 아에시나의 은총을 구하십시오. 완료되면 아스트라나르로 돌아가 티라이스와 만나십시오.",
        ["D"] =
        "제 계획의 마지막 부분은 물과 연대기를 모두 아에시나의 제단으로 가져가는 것입니다. 물을 제물로 바쳐 그녀가 우리에게 축복을 내리고 연대기를 복구해 주기를 바라는 것입니다. 그곳에서 만나겠습니다.\n\n저보다 먼저 도착하신다면, 아에시나의 축복을 받는 가장 좋은 방법을 다른 방문객들에게 물어보는 것도 좋을 겁니다.",
    },
    [27030] = {
        ["T"] = "때려 눕혀!",
        ["O"] =
        "롬굴이 잿빛 골짜기 정찰병을 유인하여 자신을 공격하도록 하는 동안 그를 보호하십시오. 임무가 완료되면 작업반장 바란에게 돌아가십시오.",
        ["D"] =
        "비겁한 나이트 엘프들은 그림자 속에 숨어서 자기 영토에 들어오는 사람들을 매복 공격합니다. 이제 일꾼들에게서 그들의 주의를 돌릴 무언가를 해야 할 때입니다.\n\n이 임무에 롬굴을 배정하겠습니다. 그는 보통의 일꾼처럼 둔하게 비틀거리며 최대한 많은 소음을 낼 것입니다. 매복꾼들이 이 멍청한 바보를 보면 약점을 포착하고 달려들 것입니다. 당신의 역할은 롬굴은 살리되 엘프 매복꾼들은 한 명도 살려두지 않는 것입니다.\n\n이 일을 해낸다면 보수를 지급하겠습니다.",
    },
    [27031] = {
        ["T"] = "군단 파괴",
        ["O"] =
        "만노로크 덩굴정령 6마리, 지옥수호병 6마리, 그리고 불타는 지옥불정령 6마리를 처치하고 잿빛 골짜기 토막나무 주둔지의 시리스에게 돌아가십시오.",
        ["D"] =
        "불타는 군단의 악마 잔당들이 우리 전쟁노래 벌목 기지를 공격하고 있다!\n\n더 이상은 안 돼!\n\n악마들은 남동쪽 악령불 언덕, 악마벼락 협곡, 악마벼락 마루라 불리는 지역에서 공격해 오고 있다.\n\n가서 가능한 한 많은 악마를 파괴하여 너 자신과 호드에 영광을 가져오도록 해라!",
    },
    [27032] = {
        ["T"] = "군단 파괴",
        ["O"] =
        "만노로크 덩굴정령 6마리, 지옥수호병 6마리, 그리고 불타는 지옥불정령 6마리를 처치하고 잿빛 골짜기 숲의 노래에 있는 파수꾼 마이드린에게 돌아가십시오.",
        ["D"] =
        "불타는 군단의 악마 잔당들이 전쟁노래 벌목 기지를 공격하고 있습니다. 제가 벌목꾼들을 싫어하는 만큼이나, 악마들이 제지받지 않는다면 그들은 벌목 기지를 넘어와 도로의 여행자들을 잡아먹기 시작할 것입니다.\n\n악마들은 남쪽의 악령불 언덕, 악마벼락 협곡, 악마벼락 마루라 불리는 지역에서 공격해 오고 있습니다.\n\n가서 가능한 한 많은 악마를 파괴하여 숲과 얼라이언스에 안전을 가져다주십시오!",
    },
    [27033] = {
        ["T"] = "악마의 계획",
        ["O"] = "잿빛 골짜기 토막나무 주둔지에 있는 시리스에게 악마의 계획서를 전달하십시오.",
        ["D"] =
        "악마가 이 양피지를 떨어뜨렸는데, 놀랍게도 오크어로 적혀 있습니다! 양피지에 언급된 디아스로스와 고르간논은 이 지역의 악마들을 조종하는 악명 높은 두 명의 공포의 군주입니다.\n\n계획서에는 북서쪽의 토막나무 주둔지를 향한 악마의 공격 준비가 자세히 적혀 있습니다.\n\n토막나무 주둔지에 있는 시리스가 이 계획서에 관심을 보일 것이 틀림없습니다.",
    },
    [27034] = {
        ["T"] = "두 번 다시는!",
        ["O"] = "악마벼락 협곡으로 들어가 고르간논과 추적자 디아스로스를 처치하십시오.",
        ["D"] =
        "$N, 이 불타는 군단의 공격이 결코 일어나지 않도록 해야 한다! 가서 이 공포의 군주들을 처치해라! 놈들이 없으면 나머지 악마들은 사실상 이성을 잃는다.\n\n고르간논은 악령불 언덕을 지나 남쪽의 악마벼락 협곡, 공중에 떠 있는 만노로스의 부러진 창 근처에서 찾을 수 있을 것이다.\n\n추적자 디아스로스는 악마벼락 마루 꼭대기 어딘가에 산다. 마루를 찾으려면 그롬 헬스크림의 기념비 근처에 있는 악마벼락 협곡에서 올라가는 경사로를 찾아봐라.",
    },
    [27035] = {
        ["T"] = "악마의 계획",
        ["O"] = "잿빛 골짜기 숲의 노래에 있는 파수꾼 마이드린에게 악마의 계획서를 전달하십시오.",
        ["D"] =
        "악마가 이 양피지를 떨어뜨렸는데, 놀랍게도 공용어로 적혀 있습니다! 양피지에 언급된 디아스로스와 고르간논은 이 지역의 악마들을 조종하는 악명 높은 두 명의 공포의 군주입니다.\n\n이 계획서에는 북쪽의 숲의 노래에 대한 악마의 공격 준비가 상세히 적혀 있습니다.\n\n숲의 노래에 있는 파수꾼 마이드린이 이 계획서에 관심을 가질 것이 분명합니다.",
    },
    [27036] = {
        ["T"] = "두 번 다시는!",
        ["O"] = "악마벼락 협곡으로 들어가 고르간논과 추적자 디아스로스를 처치하십시오.",
        ["D"] =
        "$N, 불타는 군단의 공격이 결코 일어나지 않도록 확실히 해라! 가서 공포의 군주들을 처치해라! 놈들이 없으면 나머지 악마들은 사실상 이성을 잃는다.\n\n고르간논은 악령불 언덕을 지나 남쪽의 악마벼락 협곡, 공중에 떠 있는 만노로스의 부러진 창 근처에서 찾을 수 있을 것이다.\n\n추적자 디아스로스는 악마벼락 마루 꼭대기 어딘가에 산다. 마루를 찾으려면 그롬 헬스크림의 기념비 근처에 있는 악마벼락 협곡에서 올라가는 경사로를 찾아봐라.",
    },
    [27037] = {
        ["T"] = "직접적인 보복",
        ["O"] = "검은심연 나락에서 여왕 사레베스를 처치하고 아스트라나르의 티라이스에게 돌아가십시오.",
        ["D"] =
        "복구된 연대기를 훑어볼 기회가 있었는데, 나가가 무엇을 찾고 있었는지 알 것 같습니다.\n\n앞서 말씀드렸듯이 하지리는 고대의 전쟁 이전부터 존재했지만, 이후 많은 칼도레이 도시들과 마찬가지로 잃어버린 도시가 되었습니다. 이 책에는 하지리의 사원에서 별로 승천했다고 알려진 대여사제의 이야기가 담겨 있습니다. 아마도 나가의 목표는 비슷한 의식을 통해 엘룬의 힘을 얻는 것일지도 모릅니다. 우리가 나가에게서 이 텍스트를 빼앗았지만, 놈들이 비슷한 다른 텍스트를 계속 쫓을 것은 명백합니다.\n\n우리를 공격했던 나가는 여왕 사레베스의 하수인들이었습니다. 서쪽으로 조람 해안을 따라가면 폐허가 된 사원의 입구가 있습니다. 여왕 사레베스가 하수인들과 음모를 꾸미는 곳이 바로 이 나락 내부입니다. 그녀를 찾아 그녀의 음모에 영원한 종지부를 찍으세요. 이 일을 완료하고 제게 오시면, 보상해 드리겠습니다.",
    },
    [27038] = {
        ["T"] = "포세이큰 약탈자",
        ["O"] =
        "배스랜 서식지에서 포세이큰 탐구자 5명, 포세이큰 약초사 5명, 포세이큰 폭력배 10명을 처치하십시오. 임무를 마치면 마에스트라 주둔지에 있는 정화자 델그렌에게 돌아가십시오.",
        ["D"] =
        "포세이큰이 잿빛 골짜기에 침입했습니다. 이들은 한때 제 동족이었을지 모르지만, 저는 그들이 밟는 곳마다 죽음만 가져오는 것을 직접 보았습니다. 저는 그들이 이곳에 머무는 것을 용납하지 않을 것입니다.\n\n북쪽 배스랜 서식지에 있는 그들의 전초기지를 찾아 놈들이 그 위에서 대체 무슨 짓을 하고 있든 막아내십시오.",
    },
    [27039] = {
        ["T"] = "실용적인 과학",
        ["O"] = "토막나무 주둔지 남쪽, 도르다닐 고분 근처에 있는 연금술사 야영지를 찾으십시오.",
        ["D"] =
        "저는 이곳을 지나는 모험가 중 돈 되는 일을 찾는 사람이라면 연금술사들을 찾아가 보라고 전하라는 부탁을 받았습니다. 역겨운 목적을 가진 냄새나는 시체들도 상관없다면 관심이 있으실 겁니다.\n\n연금술사 야영지는 토막나무 주둔지 남쪽, 도르다닐 지하굴 근처에 있습니다.",
    },
    [27040] = {
        ["T"] = "실용적인 과학",
        ["O"] = "잿빛 골짜기 정찰병에게 불쾌한 혼합물을 5회 사용하고, 연금술사 빅터에게 돌아가십시오.",
        ["D"] =
        "거기 당신! 돈 버는 데 관심이 있으십니까? 호드를 돕는 건 어떻습니까?\n\n마침 이곳 작업에 연구 조교가 필요하던 참이었습니다. 임무는 정말 간단합니다. 내 훌륭한 혼합물을 가져가 이 지역을 배회하는 정찰병들에게 던지기만 하면 됩니다.\n제가 말한 혼합물은 대 나이트 엘프 기술의 최신이자 최고의 기술이며, 전쟁노래 동맹이 이 지역을 방어하는 데 도움이 될 것입니다.\n\n완료하시면 그 결과를 제게 보고해 주십시오.",
    },
    [27041] = {
        ["T"] = "실용적인 과학",
        ["O"] = "은빛날개 매복병에게 불쾌한 혼합물을 5회 사용하고, 연금술사 빅터에게 돌아가십시오.",
        ["D"] =
        "거기 당신! 돈 버는 데 관심이 있으십니까? 호드를 돕는 건 어떻습니까?\n\n잠깐만요, 이미 이야기한 거군요. 죄송합니다, $n. 이번 일은 저번과 매우 비슷하지만, 이번에는 남쪽에 있는 매복병들에게 사용하는 것을 보고 싶습니다. 그 녀석들은 전쟁노래 부족의 눈엣가시이므로, 적병 몇 명을 무력화시켜 그들을 돕는 셈이 되겠죠.\n\n엘프들에게 혼합물을 아낌없이 발라주고, 무슨 일이 일어나는지 봅시다!",
    },
    [27042] = {
        ["T"] = "향상된 신속의 물약",
        ["O"] = "호드 정찰병 5명에게 향상된 신속의 물약을 주고, 연금술사 리디야에게 돌아가십시오.",
        ["D"] =
        "당신은 정말 훌륭한 연구 조교군요, $n. 제 이름은 리디야고, 왕립 연금술 학회 소속입니다. 저는 빅터와 독립적으로 프로젝트를 진행하고 있는데, 혹시 저를 도와주실 수 있나요?\n\n남쪽에는 나이트 엘프 매복병들을 끊임없이 감시하는 여러 전쟁노래 정찰병이 있습니다. 그들은 전투에서 제 몫을 할 수 있지만, 우리가 줄 수 있는 모든 지원을 제공해야 합니다.\n\n저는 특별한 변종 신속의 물약을 연구해 왔습니다. 그 물약은 정찰병들에게 뛰어난 반사 신경과 일반적인 민첩성을 부여하여, 어떤 매복병이 다가와도 물리칠 수 있게 해줄 것입니다. 절 위해 전쟁노래 정찰병들에게 이 물약을 좀 나누어 주시겠습니까? 수고비는 두둑하게 쳐드리겠습니다.",
    },
    [27043] = {
        ["T"] = "윤리적 딜레마",
        ["O"] = "작업반장 바란에게 연금술사 빅터와 리디야의 활동을 보고하십시오.",
        ["D"] =
        "$n, 맞죠? 리디야가 당신에게 자신의 프로젝트에 대해 말한 것을 우연히 들었습니다. 우리 모두 같은 프로젝트에 임하고 있고 정찰병에게 나눠주라는 \"향상된 신속의 물약\" 같은 건 존재하지 않는다는 점을 고려하면, 그녀의 설명이 흥미롭군요.\n\n단도직입적으로 말하죠. 그녀는 당신에게 거짓말을 했습니다. 그녀가 당신에게 준 것은 나이트 엘프에게 사용했던 것과 동일한 혼합물입니다. 리디야는 우리 프로젝트의 실험 대상 풀을 확대하려고 안달이 났지만, 당신이 오기 전까지는 실험할 수 있는 대상이 나이트 엘프뿐이었습니다.\n\n누군가 리디야와 빅터를 막아야 합니다. 왕립 연금술 학회에서 결과만 나온다면 그들은 누구를 실험 대상으로 삼든 신경 쓰지 않는 것 같습니다. 저로서는 그들을 어떻게 할 힘이 없지만, 당신이 작업반장 바란을 찾아가신다면... 왕립 연금술 학회와 전쟁노래 부족 모두를 달랠 수 있는 이 문제의 해결책이 그녀에게 있을지도 모릅니다.",
    },
    [27044] = {
        ["T"] = "실험의 결론",
        ["O"] = "빅터와 리디야를 처치하여 머리를 취하는 것으로 그들의 프로젝트를 종료하고, 작업반장 바란에게 돌아가십시오.",
        ["D"] =
        "도넬리가 자기 연금술 사이비 집단의 체면을 세워줄 해결책을 원한다고? 해결책을 얻게 될 것이다!\n\n빅터와 리디야에게 가라. 그들의 머리를 내게 가져옴으로써 그들의 프로젝트를 \"종료\"시켜라! 만약 도넬리가 그들을 돕는다면, 그의 머리도 가져와! 호드는 우리 \"동맹\"들의 그런 행동을 용납하지 않는다.\n\n해산!",
    },
    [27045] = {
        ["T"] = "땅의 울림",
        ["O"] = "토막나무 광산 내의 일꾼들을 심문하십시오.",
        ["D"] =
        "보통 이 광산의 생산량은 호드의 전쟁 노력에 결정적입니다. 그런데 최근 망할 일꾼 놈들이 게으름을 피우고 있습니다. 도구를 내려놓고 횡설수설하며 이곳을 뛰쳐나간 녀석들도 있죠!\n\n아제로스에 무슨 일이 일어나고 있는지 그들에게 물어봐 주시겠습니까?",
    },
    [27046] = {
        ["T"] = "땅의 울림",
        ["O"] = "토막나무 광산에서 일꾼들을 겁주는 괴물을 찾아 제거하십시오.",
        ["D"] =
        "그래서 그들은 광산 깊은 곳에 괴물이 있다고 하는 겁니까? 최근에 이곳에서 계속 발생하는 지진의 원인도 그 괴물인지 궁금하군요.\n\n문제가 생기지 않도록 이 작업을 다시 정상 궤도에 올려놓아야 합니다. 다시 광산으로 깊이 들어가서 그 괴물을 처리해 주시겠습니까?",
    },
    [27047] = {
        ["T"] = "대지의 울림",
        ["O"] = "물가에서 튼튼한 갈대 6개를 수집하고, 썩어가는 점액괴물에게서 깨진 유리 조각 4개를 수집하십시오.",
        ["D"] =
        "이제 당신에게 확실한 관심이 생겼습니다. 이 울림은 아직 계속되고 일꾼들의 생산성은 별로 나아지지 않았습니다. 우리는 이 혼란의 진짜 원인을 찾기 위해 노력해야 합니다.\n\n좋은 생각이 하나 있지만 당신이 제게 몇 가지 물건을 구해 주셔야 합니다. 잿빛 골짜기 전역의 물가 주변에서 속을 비워 임시 조준경으로 쓸 수 있는 튼튼한 갈대를 찾을 수 있습니다.\n\n렌즈를 만들 유리도 필요합니다. 하지만 유리는 자연적으로 생성되는 게 아니니까... 흠... 알겠네요! 근처에 있는 썩어가는 점액괴물들은 여행자가 땅에 떨어뜨린 물건을 모두 주워 먹습니다. 유리 제품들도 이리저리 흡수했을 겁니다.",
    },
    [27048] = {
        ["T"] = "땅의 울림",
        ["O"] = "토막나무 광산 밖에서 진동계측기 1형을 시험해 보십시오.",
        ["D"] =
        "가져온 재료로 내 최신 발명품, 진동계측기 1형을 만들겠습니다! 이것을 광산 밖으로 가져가 시험해 보십시오. 올바른 방향을 알려줄 것이라고 확신합니다.",
    },
    [27049] = {
        ["T"] = "땅의 울림",
        ["O"] = "오그리마 내에서 이지 패스트로켓을 찾아 작업반장 스프링소켓의 보급품을 수집하십시오.",
        ["D"] =
        "글쎄요, 그것이 바로 비용을 아끼려고 문자 그대로 식물과 슬라임으로 뒤덮인 유리를 사용해서 문제를 해결하려고 한 내 잘못이죠. 아, 뭐, 시도해 볼 만한 가치는 있었습니다.\n\n이 문제를 해결할 유일한 방법은 내 금고에 손을 대는 것뿐인 것 같군요. 자, 지불금으로 톱니바퀴 한 자루를 가져가서 오그리마의 비행선 지역 안에 있는 내 옛 동료 이지 패스트로켓을 찾으세요. 내가 필요로 하는 고품질 부품을 공급해 달라고 부탁하십시오.",
    },
    [27050] = {
        ["T"] = "땅의 울림",
        ["O"] = "토막나무 광산의 작업반장 스프링소켓에게 돌아가십시오.",
        ["D"] =
        "<가방 안을 들여다보는 이지>\n\n나랑 마음이 통하는 고블린이군요.\n\n여기요, 작업반장이 원하는 모든 게 들어있어요. 솔직히 말해서 제 호기심을 자극하네요. 여기에 돌아와서 결과가 어떻게 됐는지 말해줘야 해요. 그 친구가 마침내 제게 도움을 청하게 만든 원인이 무엇이든, 엄청난 발견임에 틀림없어요.\n\n이 상자를 가지고 토막나무 주둔지로 돌아가 그에게 전해주세요.",
    },
    [27051] = {
        ["T"] = "땅의 울림",
        ["O"] = "진동계측기 2형을 사용하여 잿빛 골짜기 내에서 지진의 진원지를 찾으십시오.",
        ["D"] =
        "이것이 바로 진동계측기 2형입니다. 아름답지 않나요? 땅에 내려놓으면 잿빛 골짜기에 있는 지진의 근원지를 가리킬 것입니다.\n\n제가 도울 수 있는 건 여기까지입니다. 제발 망할 일꾼들의 정신 건강을 위해서라도 진원지를 추적하고 막아주십시오.",
    },
    [27052] = {
        ["T"] = "땅의 울림",
        ["O"] = "해바위 야영지의 딧시 스프링소켓에게 진동계측기 2형을 가져가십시오.",
        ["D"] =
        "내 여동생 딧시가 해바위 야영지에 머물고 있습니다. 여동생이 당신의 다음 단계를 도울 수 있을 겁니다. 진동계측기를 가져가면 여동생이 자기만의 기술을 더할 수 있을 겁니다. 이 지진을 일으키는 원인은 아제로스 깊은 곳에 있는 강력한 무언가일 겁니다.\n\n딧시에게 가려면 토막나무 주둔지 남서쪽에 있는 돌발톱 오솔길을 타면 됩니다. 불모의 땅 지형에 익숙하다면 먼지 구덩이 서쪽에 있는 명예의 감시탑으로 가는 길을 통해 해바위로 갈 수 있습니다.",
    },
    [27053] = {
        ["T"] = "솔라살 보고서",
        ["O"] = "아스트라나르의 누군가에게 보고서를 가져가십시오.",
        ["D"] =
        "<보고서에는 솔라살이라는 폐허에 대한 나가의 관심이 자세히 적혀 있습니다. 내용 자체는 모호하며 나가의 병력 규모나 공격 계획에 대한 표시는 없습니다. 이 정보는 아스트라나르의 누군가에게 유용할 수 있습니다.>",
    },
    [27054] = {
        ["T"] = "고대 정령의 심장",
        ["O"] = "심장에 대해 알려줄 수 있는 사람을 아스트라나르에서 찾으십시오.",
        ["D"] =
        "당신은 고대 정령의 심장을 집어 들었고, 그것에서 기묘한 박동이 방출되는 것을 느낍니다. 아마 아스트라나르에 있는 누군가가 이것에 대해 더 많이 알려줄 수 있을 것입니다.",
    },
    [27055] = {
        ["T"] = "고대 정령의 심장",
        ["O"] = "심장에 대해 알려줄 수 있는 사람을 토막나무 주둔지에서 찾으십시오.",
        ["D"] =
        "당신은 고대 정령의 심장을 집어 들었고, 그것에서 기묘한 박동이 방출되는 것을 느낍니다. 아마 토막나무 주둔지에 있는 누군가가 이것에 대해 더 많이 알려줄 수 있을 것입니다.",
    },
    [27056] = {
        ["T"] = "스랄에게로 돌아가기",
        ["O"] = "오그리마 지혜의 골짜기에 있는 스랄과 대화하십시오.",
        ["D"] =
        "아, $C 님. 당신에게 전할 메시지가 있습니다.\n\n우리의 대족장인 스랄 님이 오그리마에서 대화하기 위해 당신이 돌아오기를 명하셨습니다. 그는 불타는 칼날단에 대한 소식을 가지고 있습니다.",
    },
    [27057] = {
        ["T"] = "창공의 파동",
        ["O"] = "잿빛 골짜기 토막나무 주둔지에서 시리스를 찾으십시오.",
        ["D"] =
        "공포안개 봉우리 꼭대기에 있는 악마의 씨앗을 파괴하려는 귀하의 최근 노력에 대해 들었소. 이 행동은 칭찬할 만하며 불타는 칼날단의 하수인들에게 맞설 수 있다는 것을 보여주었소.\n\n그러나 씨앗의 파괴는 흑마법사와 악마들이 특히 민감하게 반응하는 어두운 에테르를 통한 신호음처럼 퍼졌소. 새로운 위험이 도래했소.\n\n닐루 파이어블레이드는 불타는 칼날단이 불모의 땅과 잿빛 골짜기에서 작전을 펼쳤다고 언급했소. 귀하가 불모의 땅에 있는 그들의 요새를 공격했으니, 이 위험이 잿빛 골짜기에 닥칠 것이라고 믿소. 잿빛 골짜기의 토막나무 주둔지에 보고하고 내 요원인 시리스와 이야기하시오. 그녀가 이 위험을 찾는 데 도움을 줄 것이오.",
    },
    [27058] = {
        ["T"] = "창공의 파동",
        ["O"] =
        "돌발톱 산맥에서 불타는 칼날단을 찾으십시오. 찾으면 잿빛 골짜기 토막나무 주둔지에 있는 시리스를 위해 불타는 칼날단 목걸이 4개를 회수하십시오.",
        ["D"] =
        "스랄 님이 당신이 올 거라고 알려주셨습니다. 또 다른 여정을 보내게 되어 유감이지만, 불타는 칼날단의 마법 표본이 없으면 잿빛 골짜기에서 그들을 찾을 수 없고, 이곳에는 아무런 단서가 없습니다.\n\n불타는 칼날단이 돌발톱 산맥의 그림토템 타우렌 부족과 안전한 피난처를 찾았다는 소문을 들었습니다. 공포안개 봉우리가 더 이상 안전하지 않으니 그곳으로 옮겨갔을 겁니다.\n\n돌발톱에서 그림토템의 존재를 수색하고 그들이 불타는 칼날단과 동맹을 맺었는지 확인하십시오. 그들의 마법에 관한 것, 아마도 그들이 사용하는 마법 목걸이 같은 것을 가져올 수 있는지 확인해 보십시오.",
    },
    [27059] = {
        ["T"] = "창공의 파동",
        ["O"] = "썬더 블러프 장로의 봉우리에 있는 마가타 그림토템과 대결하십시오.",
        ["D"] =
        "잿빛 골짜기에서 불타는 칼날단을 찾으려면 이 목걸이를 연구해야 합니다. 시간이 좀 걸릴 것입니다.\n\n제가 연구하는 동안, 당신은 대족장님의 대리인으로서 그림토템 부족의 지도자와 대화할 것을 명합니다.\n\n마가타 그림토템은 썬더 블러프 장로의 봉우리에 살고 있습니다. 불타는 군단은 호드의 끔찍한 적이며, 그녀의 부족이 그들과 협력하는 것은 참을 수 없는 일입니다. 즉시 중단되어야 합니다.\n\n그녀가 이 문제에 대한 대족장의 뜻을 이해하는지 확인하십시오.",
    },
    [27060] = {
        ["T"] = "창공의 파동",
        ["O"] = "불모의 땅에 있는 푸른 오아시스로 이동하여 폭풍몰이 레제스와 길잡이 미신을 처치하십시오.",
        ["D"] =
        "대족장님께서 우리 부족이 떠돌이 흑마법사 몇 명과 일하는 것을 반대하신다고? 왜 우리가 그렇게 하는지 묻지는 않았지만, 말해주지.\n\n타우렌이 한때 켄타우로스에게 사냥당했다는 것은 당연히 알겠지. 그들의 약탈로 대대로 이어온 지식이 사라졌다. 난 그들이 이 땅을 공유하는 것을 용납하지 않을 것이다. 왜 내가 포세이큰과의 동맹을 지지했다고 생각하나? 그들의 역병은 가장 흥미로운 무기이기 때문이다....\n\n우리 부족이 불타는 칼날단과 협력하는 것을 그만두기를 원한다면 그에 상응하는 도구를 나에게 다오. 불모의 땅으로 가서 폭풍몰이 레제스와 길잡이 미신을 죽여라. 그들은 오랫동안 내 눈엣가시였다.",
    },
    [27061] = {
        ["T"] = "창공의 파동",
        ["O"] = "잿빛 골짜기 토막나무 주둔지에 있는 시리스에게 돌아가십시오.",
        ["D"] =
        "네가 진짜 찾고 있는 게 뭔지 안다, $C. 어둠에 익숙한 모든 피조물은 악마의 씨앗이 파괴되면서 흩어지는 에너지 파동을 느꼈다. 그 에너지의 일부가 여전히 네 주변에 공명하고 있다.\n\n잿빛 골짜기 어딘가에서 자라는 또 다른 씨앗이 있다. 내 부족의 목적과는 무관한 것이라 자세한 내용은 알지 못한다. 하지만 대족장님께 선의를 보여주는 의미로 이 정보를 공유하지... 이제 잠시 너의 주인에게로 돌아가도 좋다. 나중에 돌아와 내 임무를 이어가기를 기대하마.",
    },
    [27062] = {
        ["T"] = "창공의 파동",
        ["O"] = "오그리마의 스랄에게 돌아가십시오.",
        ["D"] =
        "당신이 없는 동안 당신이 가져온 목걸이의 비밀 중 일부를 풀어냈습니다. 안타깝게도 우리가 잿빛 골짜기에서 다루고 있는 것은 더 많은 정보 없이 도전하기에는 너무 강력하다고 생각합니다.\n\n이 보고서를 스랄 님께 전해주십시오. 그가 어떻게 진행할지 결정하는 동안 마가타의 심부름을 할 여유가 있을 것 같습니다.",
    },
    [27063] = {
        ["T"] = "새로운 악마의 씨앗",
        ["O"] = "잿빛 골짜기 토막나무 주둔지에 있는 시리스와 대화하십시오.",
        ["D"] =
        "$N, 이제 다시 불타는 칼날단에 맞서 무기를 들어야 할 때다. 시리스는 이전처럼 에테르 교란을 일으키지 않고 이 새로운 악마의 씨앗을 소멸시킬 계획을 세웠다.\n\n즉시 토막나무 주둔지에 있는 그녀에게 보고해라.",
    },
    [27064] = {
        ["T"] = "새로운 악마의 씨앗",
        ["O"] =
        "사티르나르를 거쳐 잿빛 골짜기의 사비안으로 가서 니조리스를 처치하십시오. 저주송곳니 금고를 회수하여 토막나무 주둔지에 있는 시리스에게 가져가십시오.",
        ["D"] =
        "불모의 땅에서 했던 것처럼 이 새로운 악마의 씨앗을 단순히 파괴할 수는 없습니다. 계속 자라지 못하도록 어딘가에 가둬야 합니다. 다행히 그런 곳이 손닿는 곳에 있습니다.\n\n사티로스 무리가 동쪽에 진을 치고 있습니다. 사비안의 위층에는 희귀 유물 수집가인 니조리스가 있습니다. 그는 저주송곳니 금고라는 물건을 소유하고 있습니다. 이 마법 상자는 어둠의 강력한 물건을 보관하기 위해 특별히 고안되었습니다. 니조리스를 처치하고 그 금고를 내게 가져다주십시오. 악마의 씨앗을 봉인하는 데 사용할 수 있습니다.",
    },
    [27065] = {
        ["T"] = "새로운 악마의 씨앗",
        ["O"] = "악마벼락 협곡에 침투하여 저주송곳니 금고를 사용해 새로운 악마의 씨앗을 봉인하십시오.",
        ["D"] =
        "이제 우리 임무 중 가장 위험한 부분입니다, $N.\n\n당신이 전쟁노래 벌목 기지와 악령불 언덕 남쪽에 있는 악마벼락 협곡으로 가 주셨으면 합니다. 그곳은 그롬 헬스크림이 만노로스를 물리친 장소입니다. 불타는 칼날단은 만노로스의 피의 잔재를 이용해 그곳에서 새로운 악마의 씨앗을 기르고 있습니다.\n\n씨앗을 찾아 금고에 넣으십시오. 그런 다음 금고를 내게 가져오십시오.\n\n유감스럽게도 나는 당신과 동행할 수 없습니다. 악마들이 내 존재를 감지할 것이고 당신은 훨씬 더 힘든 저항에 부딪힐 것입니다.",
    },
    [27066] = {
        ["T"] = "새로운 악마의 씨앗",
        ["O"] = "봉인된 저주송곳니 금고를 오그리마에 있는 스랄에게 가져가십시오.",
        ["D"] =
        "이제 저주송곳니 금고는 마법으로 봉인되었습니다, $N. 와이번을 타고 오그리마로 가져가 스랄 님께 전해 주십시오. 그분께서 금고를 안전한 곳에 보관하고 감시하실 겁니다.\n\n잘해 주셨습니다, 젊은 $C. 다시 만날 날을 기대하겠습니다.",
    },
    [27067] = {
        ["T"] = "그늘수렵으로의 여행",
        ["O"] = "잊혀진 땅의 그늘수렵 마을에서 핍조트와 자카라를 찾으십시오.",
        ["D"] =
        "시리스는 악마의 씨앗의 파괴로 소환된 강력한 악마의 위치를 잿빛 골짜기에서 배제했소. 내 다른 요원이 잊혀진 땅으로 가서 불타는 칼날단이 그 지역에 존재한다는 보고를 해왔소.\n\n남서쪽 해안에 있는 그늘수렵 마을로 가서 자카라와 그녀의 임프 핍조트를 찾으시오.\n\n자카라는 유능한 흑마법사지만 말을 할 수 없소. 그녀의 임프가 대화를 대신할 것이오.",
    },
    [27068] = {
        ["T"] = "일감 한 점",
        ["O"] = "발로르모크의 렐코를 위해 아즈샤라의 산호껍질거북에게서 거북 목살 6개를 수집하십시오.",
        ["D"] =
        "아즈샤라는 마음만 먹으면 가져갈 수 있는 보물로 가득한 고대적이고 경이로운 땅이라네. 발로르모크에 한몫 잡으려고 온 건가? 최고의 가죽 세공 재료를 찾고 있나?\n\n최근에 나도 물건을 좀 처분했는데, 이 지역은 숲에서 해안까지 깨끗한 짐승 가죽으로 가득 찬 최고의 장소라네. 일에 끼어들고 싶다면 팁을 하나 주지. 여기 거북이들은 목 주위에 가장 부드러운 가죽을 가지고 있다네. 이런 건 본 적이 없어. 그러니 나가서 산호껍질거북을 죽이고 -- 맞다네 -- 거북 목살을 좀 가져오게나.",
    },
    [27069] = {
        ["T"] = "일감 한 점",
        ["O"] = "아즈샤라의 히드라에게서 폭풍히드라 비늘 6개를 수집한 다음 발로르모크의 렐코에게 돌아가십시오.",
        ["D"] =
        "여기 끝없는 해안의 바닷바람은 해변 전체를 순찰하는 폭풍히드라의 비늘을 보존하고 빛나게 한다네 -- 적어도 나가가 패권을 쥐고 있지 않은 곳에서는 말이지.\n\n동전을 더 벌고 싶다면 여기서 어떤 종류의 히드라든 죽이고 최고급 비늘을 모으게나. 내가 염두에 두고 있는 구매자에게는 최고급만이 통한다네.",
    },
    [27070] = {
        ["T"] = "일감 한 점",
        ["O"] = "아즈샤라 발로르모크의 렐코에게 멀클럭을 처치하고 질긴 바닷가재 힘줄을 가져가십시오.",
        ["D"] =
        "가죽세공인들은 자신의 작품을 고정하기 위해 실을 사용하지. 대부분의 경우엔 그걸로 충분하고 괜찮아. 하지만 나에겐 좀 더 큰 물건을 위한 구매자가 있다네. 우리는 좀 더 튼튼한 것이 필요하지. 그리고 어디서 얻을 수 있는지도 안다네.\n\n폭풍의 만 한가운데에는 모래톱 위로 크고 구부러진 바위가 있는 섬이 있다네. 그곳에서 종종 햇볕을 쬐고 있는 덩치 큰 바닷가재 한 마리를 볼 수 있지. 이 멀클럭을 찾아 죽이고 크고 두꺼운 힘줄을 얻어오게나. 두껍고 탄력이 있어서 이 주문을 이행하는 데 딱 필요한 것이라네.\n\n걱정 말게나. 자네가 이걸 해낸다면 특별한 걸 준비해 뒀으니까.",
    },
    [27071] = {
        ["T"] = "계약: 발로르모크 광산",
        ["O"] = "아즈샤라의 발로르모크 광산에서 광맥 5개를 채굴한 후 광산 앞의 현장감독 레오폴드에게 보고하십시오.",
        ["D"] =
        "이봐 광부! 내가 자네에게 줄 제안이 하나 있네!\n\n그 부풀어 오른 이두박근을 보아하니 곡괭이질 꽤나 해본 솜씨군. 우리 일꾼들을 쉬게 해줄 겸 광산에서 단기로 일해보는 건 어떤가? 우리는 장미 수정이라는, 이전에 본 적 없는 사랑스럽고 희귀한 작은 기묘한 광물을 캐고 있다네.\n\n물론 계약직 유급 노동이고 단기이며 복리후생은 없네. 위험은 본인이 감수해야 하고 저 아래서 무슨 일이 일어나든 우리는 책임지지 않아. 하지만 호드를 위해 채워야 할 할당량이 있고 자네가 도울 수 있지!",
    },
    [27072] = {
        ["T"] = "계약: 발로르모크 광산",
        ["O"] = "장미 수정 샘플을 발로르모크의 레안더 사부에게 가져가 조사하십시오.",
        ["D"] =
        "장미 수정을 여러 번 잘 캤군. 이것들 대부분은 아주 평범한 거야. 하지만 봐! 이 장미 수정 조각은 다른 것들과 달라. 이상하게 빛나는 게 보이나? 저건 좋지 않은 징조거나 아주 좋은 징조지.\n\n남서쪽에 있는 연금술 건물의 레안더 사부에게 가져가서 한 번 살펴봐 달라고 하는 게 어떤가?\n\n기억하게, 그게 저주받은 거라도 난 책임 안 져!",
    },
    [27073] = {
        ["T"] = "계약: 발로르모크 광산",
        ["O"] = "레안더 사부의 보고서를 아즈샤라 발로르모크 광산의 현장감독 레오폴드에게 가져가십시오.",
        ["D"] =
        "엄청난 발견이군요, $N. 장미 수정 파편에 일종의 마법 정수가 있다는 것을 한눈에 알 수 있습니다. 당신에게 이것을 가져오게 한 현장감독 레오폴드의 통찰력이 놀랍군요.\n\n추가 연구를 위해 이 샘플을 보관하겠습니다. 레오폴드에게 돌아가서 더 파내는 모든 표본에 관심이 있다고 전하십시오. 그리고 당신은 보너스를 받았다고도 말하십시오.",
    },
    [27074] = {
        ["T"] = "악마 침입자",
        ["O"] = "아즈샤라 검은아귀 마을의 대족장 운갈을 위해 레가쉬 사티로스 10마리, 레가쉬 도적 10마리, 레가쉬 지옥술사 8마리를 처치하십시오.",
        ["D"] =
        "오래 전, 거대한 악마가 이 땅에 왔었다. 우리 부족은 얼라이언스가 악마를 쫓아내는 것을 도왔다. 위대한 족장 운그 악은 평화를 찾기 위해 다른 이들과 멀리 떨어진 이곳에 정착하기로 결정했다.\n\n그런데 악마들이 다시 돌아왔다. 타락이 많은 친구들을 앗아갔다.\n\n평화의 시간은 끝났다. 고립의 시간도 끝났다. 검은아귀와 친구가 되고 싶은가? 남쪽 근처의 많은 악마를 처치하여 친구임을 증명하라. 그런 다음 대화하자.",
    },
    [27075] = {
        ["T"] = "악마 침입자",
        ["O"] = "박스잘란을 처치하고 그의 머리를 아즈샤라 검은아귀 마을의 대족장 운갈에게 가져가십시오.",
        ["D"] =
        "너는 검은아귀에게 우정을 보여주었지만, 검은아귀는 네가 힘 또한 보여주기를 요구한다.\n\n남쪽의 악마들 중 박스잘란이라는 자가 있다. 그가 이끌면 악마들이 따른다.\n\n힘을 증명하려면 박스잘란을 처치해야 한다. 증거로 머리를 가져와라. 그러면 우리는 진정한 친구가 될 것이다.",
    },
    [27076] = {
        ["T"] = "추방자들의 후손",
        ["O"] = "탈렌디스 초소의 아쉴라 대장이 아즈샤라의 탈라시안 기지에 있는 블러드 엘프 수복자 10명과 블러드 엘프 측량사 10명을 처치해 달라고 부탁했습니다.",
        ["D"] =
        "아즈샤라 관광을 오셨나요, $C? 역사에서 교훈을 얻지 못하는 자들에겐 볼거리가 없는 곳이랍니다. 마법이 지닌 위험성을 증명하는 곳이자 그 이름 자체인 땅이죠.\n\n신도레이는 무모한 마법 사용으로 칼림도어에서 추방된 쿠엘도레이의 일부였습니다. 하지만 고블린 용병 보호자들을 대동하고 최근 아즈샤라로 돌아왔죠. 더욱 우려되는 것은 그들이 오크들을 죽이고 자신들의 목적을 위해 이곳 북동쪽 지역을 조사하고 있다는 보고입니다.\n\n나쁜 꿍꿍이를 품고 있는 그들을 막고 싶습니다. 저를 위해 침입자들을 제거해 주시면 보상해 드리겠습니다.",
    },
    [27077] = {
        ["T"] = "점액 증류하기",
        ["O"] = "아즈샤라의 숲수액괴물에게서 숲 점액 4개를 수집하여 발로르모크의 레안더 사부에게 돌아가십시오.",
        ["D"] =
        "내 탑 곳곳에 있는 수습생들이 보이나, $C? 쓸모없는 녀석들 같으니라고!\n\n그런데 이건 뭐지 -- 당신 몸에서 트롤의 피 냄새가 나는군? 돌비늘 오일의 정수라니? 당신도 연금술사라면 마침 딱 맞는 일이 있네.\n\n원래 수습생이 5명이었는데, 한 녀석에게 숲수액괴물 점액을 모아오라는 간단한 심부름을 보낸 뒤로는 4명밖에 남지 않았지. 점액은 아직도 필요한데 심부름 보낼 수습생이 더 없으니 노련한 연금술사의 도움이 필요하네. 멘나르 호수 북쪽이나 아즈샤라 북서쪽 외곽에서 숲수액괴물을 찾을 수 있을 거야.\n\n그리고 내 멍청한 수습생의 흔적을 발견하거든 주저 말고 침을 뱉어 주게!",
    },
    [27078] = {
        ["T"] = "점액 증류하기",
        ["O"] =
        "아즈샤라 남쪽 해안을 따라 폭풍해안멀록 점쟁이에게서 순수한 멀록의 정수를 얻어 발로르모크의 레안더 사부에게 가져가십시오.",
        ["D"] =
        "수액괴물의 점액은 물약과 비약을 위한 강력한 베이스지만, 우리 혼합물을 촉발시킬 수 있는 에너지가 있는 것이 필요하네. 다행히도 그 답은 남동쪽 해안에 서식하는 수중 생물에게 있지.\n\n폭풍해안멀록 점쟁이는 번개가 주입된 정수를 분비하여 마법 능력을 촉진하네. 온전한 상태로 회수되는 경우는 드물지만, 충분히 처치하다 보면 결국 얻게 될 거야. 레이븐크레스트 기념비 반도 주변의 해안과 연안에서 순찰 중인 그들을 찾을 수 있을 걸세. 서둘러!",
    },
    [27079] = {
        ["T"] = "점액 증류하기",
        ["O"] = "레안더의 유리병을 멘나르 호수의 물로 채운 후, 아즈샤라 발로르모크의 레안더 사부에게 돌아가십시오.",
        ["D"] =
        "<레안더 사부가 구터스피크(언데드어)로 수습생들에게 명령을 내리자, 그들은 재빨리 주의를 기울이고 미친 듯한 속도로 재료를 섞기 시작합니다. 레안더 사부는 한 수습생이 용액에 물을 넣기 시작할 때까지 묵묵히 감독합니다.>\n\n안 돼! 이 바보야! 이걸 만드는 데 원액 그대로의 오그리마 수돗물을 쓰면 어떡해! 너희들의 전문가 스승이 누구였지, 트롤이었나?\n\n<레안더 사부가 수습생에게서 유리병을 낚아채어 당신에게 내밉니다.>\n\n$C, 착한 $g소년:소녀;처럼 이걸 멘나르 호수의 순수한 마법의 물로 채워다 주게나. 남쪽, 푸른 용혈족이 사는 곳 근처에서 찾을 수 있을 거야.\n\n제발 그놈들에게 잡아먹히진 말게, 여기 여분 유리병이 그리 많지 않거든.",
    },
    [27080] = {
        ["T"] = "악취 나는 형상",
        ["O"] = "아즈샤라 검은아귀 마을의 대족장 운갈을 위해 레가쉬 사티로스 야영지에서 악취 나는 형상 토템 3개를 훔치십시오.",
        ["D"] =
        "남쪽의 악마들이 어둠의 마법을 위한 악취 나는 형상 -- 불타는 해골 기둥을 만들었다. 검은 연기와 나쁜 마법, 그리고 더 많은 악마가 그 형상에서 나온다.\n\n우리는 그들의 악취 나는 토템을 가져와 정화해야 한다. 세 곳의 악마 야영지에서 토템을 훔쳐 검은아귀의 친구임을 보여다오. 그들의 마법을 방해해라. 그런 다음 대화하자.",
    },
    [27081] = {
        ["T"] = "펄볼그와 친구 되는 법",
        ["O"] = "아즈샤라 검은아귀 마을의 놀그를 위해 천둥뿔 히포그리프 깃털 10개를 모으십시오.",
        ["D"] =
        "반갑다 이방인. 펄볼그의 방식을 배우고 싶은가? 내가 돕겠다.\n\n의식에 깃털이 필요하다. 검은아귀 마을 밖의 큰 히포그리프에게서 구할 수 있다. 하지만 죽이지는 마라. 그들이 땅에 떨어뜨린 것을 감사의 뜻을 담아 제물로 주워오는 것이다. 친구가 필요한 것을 친구가 돕는다. 놀그가 깃털 모으는 걸 도와주겠는가? 그럼 우린 친구다.",
    },
    [27082] = {
        ["T"] = "펄볼그와 친구 되는 법",
        ["O"] = "/인사부터 시작하여 놀그의 지시에 따라 펄볼그 우정 의식에 참여하십시오.",
        ["D"] =
        "춤은 의식이기에 펄볼그의 동작을 뜻하는 말이다. 내가 하는 대로 따라 해라. 내 말을 잘 들어라. 내가 하는 대로 따라 하면 우린 친구다.\n\n너도 친구들과 함께 이런 걸 할지도 모른다. 펄볼그처럼 친구가 되는 법을 그들에게 가르쳐주어라. 나, 놀그에게 /인사를 하는 것으로 시작해라.",
    },
    [27083] = {
        ["T"] = "워블 할로우의 위협",
        ["O"] = "아즈샤라 워블 할로우의 웬디 워블스미스를 위해 원한의 꼬리 비명술사 10마리와 원한의 꼬리 전사 10마리를 처치하십시오.",
        ["D"] =
        "우리 가족은 아즈샤라에 아주 험난하게 왔어요. 비행기에 연료가 떨어져 바다에 불시착했거든요. 아주 순조로운 입항은 아니었지만 우린 아래 해변에 밀려왔고, 이 절벽 위로 힘겹게 기어 올라온 후엔 가게를 차리기로 했죠. 우리가 원했던 건 아닐지 몰라도, 이제 워블 할로우는 우리 집이고 아즈샤라 황야의 위협으로부터 이곳을 지킬 생각이에요.\n\n도와주실 의향이 있다면 수고비는 기꺼이 지불할게요. 원한의 꼬리 나가 부족이 멘나르 호수 북쪽 엘프 폐허에 살고 있어요. 특히 전사와 비명술사들을 없애주세요. 녀석들은 나가의 총알받이 같으니 큰 문제는 없을 거예요.",
    },
    [27084] = {
        ["T"] = "워블 할로우의 위협",
        ["O"] = "아즈샤라 워블 할로우의 웬디 워블스미스를 위해 원한의 꼬리 바다마녀 10마리와 원한의 꼬리 미르미돈 10마리를 처치하십시오.",
        ["D"] =
        "그 낮은 레벨의 나가를 처치해달라는 제 부탁 때문에 부서진 해변에 더 노련한 나가 무리가 모여든 것 같네요. 해변 곳곳을 순찰하고 있는 원한의 꼬리 미르미돈과 바다마녀들을 말하는 거예요. 녀석들의 순찰이 늘어나면 해안가에 있는 우릴 발견할 수도 있고, 그런 일이 일어나게 내버려 둘 순 없어요.\n\n다시 한번 우리를 도와주실 수 있나요?",
    },
    [27085] = {
        ["T"] = "워블 할로우의 위협",
        ["O"] = "아즈샤라 남쪽 해안을 따라 폭풍해안멀록 점쟁이 8마리를 아즈샤라 워블 할로우의 웬디 워블스미스를 위해 처치하십시오.",
        ["D"] =
        "당신이 나가를 물리치는 동안 반드시 해결해야 할 또 다른 위협을 발견했어요. 이곳 동쪽 해안에 있는 폭풍해안멀록 점쟁이들은 어둠의 의식을 통해 강력한 폭풍을 일으키겠다고 위협하고 있어요. 방치하면 아즈샤라로 들어오는 해상 및 항공 경로가 모두 위태로워질 수 있어요!\n\n해안을 따라 내려가 그들의 음모에 종지부를 찍어주셨으면 해요. 이 멀록들은 강력한 자연 마법을 구사하고 그들의 원소 마스터리 솜씨는 어마어마하니 조심하세요. 성공하신다면 이번에도 기꺼이 보답해 드릴게요.",
    },
    [27086] = {
        ["T"] = "원한의 꼬리일족 우두머리",
        ["O"] =
        "워블 할로우의 웬디 워블스미스를 위해 아즈샤라의 레이븐크레스트 기념비 근처에 있는 마술사 얄리나라는 원한의 꼬리일족 우두머리를 처치하십시오.",
        ["D"] =
        "안녕 $N, 관심 있으시면 보호 관련 일거리가 하나 더 있어요.\n\n원한의 꼬리 나가는 이곳 아즈샤라의 적이고, 바다에서 새 우두머리가 도착해서 지휘를 맡았어요. 저희 원격 센서에 그녀의 도착이 기록됐거든요.\n\n새로운 현지 우두머리가 자리 잡은 이상, 나가가 맘만 먹으면 대규모로 모여 워블 할로우를 침략하는 걸 막을 방법이 없어요. 우두머리가 없다면 그들이 혼란에 빠진 틈을 타서 우리가 방어를 준비할 시간을 벌 수 있을 거예요.\n\n동쪽으로 멀리 떨어진 절벽 위, 레이븐크레스트 기념비 주변에서 마술사 얄리나를 찾을 수 있을 거예요. 그녀를 없애고 시간을 좀 벌어주세요!",
    },
    [27087] = {
        ["T"] = "아크코란의 신전 약탈",
        ["O"] = "아즈샤라 북서쪽 아크코란의 신전에서 우리에게 가치 있을 만한 유물을 수집하십시오.",
        ["D"] =
        "아즈샤라 북서쪽 외곽에 있는 아크코란의 신전을 조사할 의향이 있다면, 혹시나 우리에게 가치 있을 만한 특이한 것이 있는지 눈여겨봐 주십시오.\n\n두루마리, 책, 물약... 뭐 정확히 어떤 게 있을지는 모르겠지만, 나가는 왠지 서판이나 조각상 같은 걸 꽤 좋아하는 것 같더군요...?\n\n어쨌든 들고 다닐 수 있을 만큼 작은 것 중에 흥미로운 걸 발견하면 제가 좀 보고 싶습니다.",
    },
    [27088] = {
        ["T"] = "아크코란의 신전 약탈",
        ["O"] = "이상한 나가 서판을 발로르모크의 연금술 탑에 있는 레안더 사부에게 가져가십시오.",
        ["D"] =
        "아즈샤라의 명가 폐허에는 많은 서판이 있지만, 이건 전혀 다른 것 같군요. 더 크고, 어... 더 화려하달까? 더... 룬 문자 같기도 하고요?\n\n모르겠습니다. 전 평범한 병사일 뿐이니까요. 제가 말해 줄 수 있는 건 이 물건이 위험해 보인다는 것뿐입니다. 추가 조사를 위해 레안더 사부에게 가져가 보시는 게 좋겠군요. 발로르모크 반대편에 있는 연금술 탑에서 수습생들과 함께 있는 그를 찾을 수 있을 겁니다.",
    },
    [27089] = {
        ["T"] = "아크코란의 신전 약탈",
        ["O"] =
        "이상한 나가 서판을 아즈샤라 북쪽 마법사 탑에 있는 대마법사 실렘에게 가져가십시오. 발로르모크 근처 야영지에서 사나스 림요를 찾아 그곳으로 순간이동하십시오.",
        ["D"] =
        "<당신에게 서판을 되돌려주는 레안더 사부>\n\n그걸 아주 조심스럽게 다루게나, $R. 지금 손에 든 것은 온전한 명가 성물함 서판으로 보이네 -- 한때 여왕 아즈샤라가 소유했던 명가 도서관의 유물이지.\n\n과거 이곳에 있던 엘프 도시를 파괴한 세계의 분리 이후, 도서관과 그 안의 모든 것은 파괴된 것으로 추정되었어. 이게 진짜 성물함 서판인지 증명할 순 없지만, 할 수 있는 사람을 알지.\n\n이 서판을 근처 절벽 탑에 사는 대마법사 실렘에게 가져가게. 탑으로 올라가려면 그의 조수 사나스 림요와 협상해야 할 거야.",
    },
    [27090] = {
        ["T"] = "아즈샤라의 유산",
        ["O"] = "폭풍의 만에 있는 엘프 폐허에서 젖은 명가 유물 8개를 수집하십시오.",
        ["D"] =
        "자네와 자네 스승이 내게 이걸 가져온 건 잘한 일이야, $C. 하지만 이 서판은 한때 아즈샤라의 명가 성물함에 존재했던 지식의 극히 일부에 불과해.\n\n아마도 이 온전한 서판을 해독기로 사용하여 폭풍의 만에 널려 있는 부서지고 쓸모없는 유물들을 해독할 수 있을지도 몰라. 내가 비교해 볼 수 있게 바닷속으로 잠수해서 유물들을 좀 건져다 주게.",
    },
    [27091] = {
        ["T"] = "아즈샤라의 유산",
        ["O"] = "아즈샤라의 발로르모크에 있는 레안더 사부에게 돌아가십시오.",
        ["D"] =
        "자네가 가져온 유물들을 해독하려면 시간이 좀 걸릴 거야. 당분간 스승에게 돌아가 있는 건 어떤가? 자네의 도움이 다시 필요하면 사람을 보내겠네.",
    },
    [27092] = {
        ["T"] = "아즈샤라의 유산",
        ["O"] = "발로르모크의 레안더 사부를 위해 마크린니 바닷가재의 눈 12개를 수집하십시오.",
        ["D"] =
        "그의 관심사와 우리의 관심사가 겹칠 수만 있다면 대마법사는 강력한 동맹이 될 수 있을 거야. 잘했네, $N.\n\n자네에게 맡길 다른 일이 있네. 마크린니 종의 바닷가재는 아즈샤라 북부와 남부 해안에서 찾을 수 있어. 그 녀석들의 눈알이 필요해. 정확히 열두 개 말이야.\n\n그리고 아크코란 녀석들과 헷갈리지 마. 그 녀석들은 마법에 변형되어 내겐 쓸모가 없거든.",
    },
    [27093] = {
        ["T"] = "아즈샤라의 유산",
        ["O"] = "아즈샤라 북쪽 마법사 탑에 있는 대마법사 실렘과 대화하십시오. 발로르모크 근처 야영지에서 사나스 림요를 찾아 그곳으로 순간이동하십시오.",
        ["D"] =
        "자네가 내 심부름을 나간 사이에 대마법사 실렘에게서 메시지가 왔네. 다시 서판과 관련된 일로 자네의 도움이 필요하다더군.\n\n오래 기다리게 하지 않는 편이 좋을 거야. 지금은 그가 자네에게 호의를 가지고 있으니 그르치지 말게.",
    },
    [27094] = {
        ["T"] = "아즈샤라의 유산",
        ["O"] = "아즈샤라 남동쪽 구석에 있는 웅덩이를 수색하여 나가 추방자의 위치를 알아내십시오.",
        ["D"] =
        "자네가 폭풍의 만에서 회수한 유물들은 성물함 서판의 룬문자와 부분적으로만 일치하네. 이 퍼즐엔 아직 빠진 조각이 있고 난 그걸 어디서 얻어야 할지 알 것 같군.\n\n내가 점술로 확인한 바에 따르면, 아즈샤라의 남동쪽 끝 레이븐크레스트 기념비 아래 웅덩이에 숨겨진 동굴에 은둔하며 살아가는 나가 마술사가 있다네. 그녀를 찾아내서 서판 해독에 도움을 요청해 주게.\n\n그녀가 기꺼이 우리를 도와줄 이유가 있다고 생각하네.",
    },
    [27095] = {
        ["T"] = "아즈샤라의 유산",
        ["O"] = "아크코로크의 후예를 처치하고 그 심연의 인장을 획득하여 아즈샤라의 대마법사 실렘에게 가져가십시오.",
        ["D"] =
        "당신의 \"대마법사\" 친구는 날 훔쳐보고 자신이 똑똑하다고 생각하겠지만, 그건 내가 발견되길 원했기 때문이라는 사실은 모르고 있군요. 난 당신이 아크코란의 신전에서 서판을 가져갔을 때부터 지켜봤습니다. 당신은 이제 아즈샤라에 사는 모든 이를 위협하는 길을 가고 있고 제가 가만히 서서 아무것도 하지 않는다면 무책임한 일이 될 겁니다.\n\n그러니 당신에게 딱 한 번만 말하죠: 이 거대한 규모의 마법에 간섭하는 건 필멸자들의 어리석은 짓입니다. 이 마법은 깊은 바다의 힘에서 온 것이며 당신들을 위한 것이 아닙니다. 통제할 수도 없고요.\n\n내 말을 귀담아듣지 않을 거라는 건 알지만 딱 한 가지만 더 말해 주겠습니다. 아크코로크의 후예들은 깊은 바다를 가로지를 때 특수한 보호 인장을 지니고 다니기 때문에 서판을 찾을 수 있었습니다. 하나를 죽여 그 인장을 빼앗으십시오. 그것이 당신의 실수에서 살아남을 수 있을 만큼의 보호를 제공할지도 모릅니다.",
    },
    [27096] = {
        ["T"] = "아즈샤라의 유산",
        ["O"] = "아즈샤라의 발로르모크에 있는 레안더 사부에게 돌아가십시오.",
        ["D"] =
        "지금 우리의 사업은 끝났네, $C. 자네 스승에게 돌아가 자네의 수고에 합당하다고 생각하는 보상을 받게나.\n\n필요하면 자네 스승에게 다시 연락하겠네. 자네에게 감사의 빚을... 졌군.",
    },
    [27097] = {
        ["T"] = "워블 할로우로 보내는 메시지",
        ["O"] = "아즈샤라 남쪽 해안 멘나르 호수 남쪽 절벽에서 워블 할로우를 찾으십시오.",
        ["D"] =
        "주목, $R! 아즈샤라로 여행할 계획입니까? 그렇다면 임무를 하나 드리겠습니다.\n\n저희 초소에서 웬디 워블스미스라는 사람을 수신인으로 한 메시지를 아이언포지에서 받았습니다. 전 그 이름은 모르지만, 메시지에 따르면 노움 무리가 아즈샤라의 남쪽 가장자리 절벽 어딘가에 작전 기지를 세웠을 수 있다고 합니다. 이 메시지를 가지고 멘나르 호수 남쪽에서 수신인을 찾아주시겠습니까? 전 배달하러 자리를 뜰 수가 없어서요.",
    },
    [27098] = {
        ["T"] = "정찰병 두라에게 보고",
        ["O"] = "아즈샤라 발로르모크에 있는 정찰병 두라를 찾으십시오.",
        ["D"] =
        "여기서 너무 많은 시간을 보낸다면 악령숲의 타락이 살갗에 스며들 겁니다, $R. 당신을 위해서라도 아즈샤라에 있는 발로르모크의 새 전초기지를 방문해 보는 게 좋겠습니다. 악령이 깃든 강에서 잠시 벗어나 짠 바닷바람을 마시세요.\n\n그곳에 있는 동안 제 친구 두라를 만나보세요. 이 지역의 지형을 알려줄 겁니다.",
    },
    [27099] = {
        ["T"] = "흑요석 강철",
        ["O"] = "아즈샤라 발로르모크에 있는 그룰 다크블레이드를 위해 수호병 방패 6개를 수집하십시오.",
        ["D"] =
        "아, 동료 대장장이군. 당신의 혈관에서 흐르는 대장간 특유의 냄새를 맡을 수 있다오.\n\n근처 엘다라스 폐허를 보호하는 원한의 꼬리일족 수호병이 흑요석 강철을 완벽하게 다루어 인상적인 방패를 제작한다는 사실에 흥미가 생길 거요.\n\n흑요석 강철이 뭐냐고? 나도 그게 알고 싶다오.\n\n주인에게서 수호병 방패 6개를 회수하여 내게 가져오시오. 어쩌면 우리가 함께 알아낼 수도 있을 거요.",
    },
    [27100] = {
        ["T"] = "흑요석 강철",
        ["O"] = "오그리마 명예의 골짜기에 있는 크라토크 몰튼피스트에게 수호병 방패를 가져가십시오.",
        ["D"] =
        "이거 보셨소, $N? 이 물질은 우리 대장간의 열기에 사실상 영향을 받지 않소!\n\n하지만 여기 발로르모크엔 기본적인 설비밖에 없다오. 오그리마의 대장간으로 가져가서 크라토크 몰튼피스트가 이걸 녹이는 걸 도와줄 수 있는지 확인해 보겠소? 그는 명예의 골짜기 뒤편에 있을 거요.",
    },
    [27101] = {
        ["T"] = "흑요석 강철",
        ["O"] = "녹인 흑요석 용재를 아즈샤라 발로르모크의 그룰 다크블레이드에게 다시 가져가십시오.",
        ["D"] =
        "그룰이 이걸 녹여달라고 한다면, 그렇게 해주지. 내 숯은 아이언포지의 숯만큼이나 뜨겁다고.\n\n<크라토크가 서서히 방패를 녹여 두껍고 기름진 액체 용재로 만듭니다.>\n\n잘 녹지 않는 건 확실하군. 내가 자네라면 조심해서 다룰 거야. 하지만 그룰은 최고 중 한 명이지. 그가 이 재료로 뭘 만들어낼지 흥미롭군.",
    },
    [27102] = {
        ["T"] = "고위집행관 데링턴에게 보고",
        ["O"] = "티리스팔 숲의 보루에 있는 고위집행관 델링턴에게 보고하십시오.",
        ["D"] =
        "호드의 용사여! 우리 병력이 아제로스 전역의 다른 호드 전초기지로 전해야 할 긴급 문서가 있소. 이 임무를 맡겠소?\n\n이 보고서를 티리스팔 숲 보루에 있는 고위집행관 델링턴에게 전달하시오. 동부 왕국으로 이동해 언더시티에서 동쪽으로 향하는 도로를 따라 그의 야영지에 도착해야 하오.\n\n신속하게, 그리고 명예롭게 가시오!",
    },
    [27103] = {
        ["T"] = "파견사령관 루아그에게 보고",
        ["O"] = "슬픔의 늪의 스토나드에 있는 파견사령관 루아그에게 보고하십시오.",
        ["D"] =
        "호드의 용사여! 슬픔의 늪의 스토나드에 주둔하고 있는 파견사령관 루아그가 보낸 메시지에 응답해야 하오.\n\n동부 왕국으로 이동하여 그롬골에서 북쪽으로 난 길을 따라 그늘숲과 저승바람 고개를 지나 슬픔의 늪에 도착해야 하오. 멀지만 중요한 여정이오. 이걸 안전하게 전달해 주겠소?",
    },
    [27104] = {
        ["T"] = "정찰병 두라에게 보고",
        ["O"] = "아즈샤라 발로르모크에 있는 정찰병 두라를 찾으십시오.",
        ["D"] =
        "여기 페랄라스에서 오우거들과 함께해 준 일은 아주 가치 있었소, $C. 그래서 훨씬 더 위험한 땅에서 새로운 임무를 추천하는 거라오.\n\n페랄라스의 엘프 폐허가 인상적이라고 생각했다면 아즈샤라에 있는 폐허를 볼 때까지 기다려 보시오. 호드는 발로르모크에 최전방 작전 기지를 세웠고 황야를 탐험하고 우리의 위치를 지킬 당신 같은 전사가 필요하오.\n\n내 명성을 걸고 당신을 추천하는 거니 날 실망하게 하지 마시오!",
    },
    [27105] = {
        ["T"] = "워블 할로우의 보급품",
        ["O"] = "아즈샤라 워블 할로우의 윌버 워블스미스와 대화하고 남는 기계공학 부품에 대한 지원을 요청하십시오.",
        ["D"] =
        "이런 황무지에서 동료 기계공학자를 만나다니 반갑네요. 전 이 전초기지에서 모든 걸 정상 작동시키려고 노력해 왔는데 제 말씀 좀 들어보세요. 이거 정말 쉽지 않다고요!\n\n저기 기계공학자 동료로서 부탁 하나만 들어주시겠어요? 원자재가 떨어져 가거든요. 기어 같은 거 말이에요. 멘나르 호수 남쪽 절벽 가장자리에 노움 무리가 야영지를 차렸죠. 거기로 가서 우리가 싼값에 구할 수 있는 남는 부품이 굴러다니는지 알아봐 주시면 수고비는 섭섭지 않게 쳐 드릴게요.\n\n네, 그들이 얼라이언스 소속인 건 알지만 꽤나 우호적이잖아요.",
    },
    [27106] = {
        ["T"] = "워블 할로우의 보급품",
        ["O"] =
        "아즈샤라 남쪽 바다와 해안에서 난파된 부품 10개를 수집한 다음 제한적 순간이동 촉진기를 사용하여 아즈샤라의 워블 할로우로 돌아가십시오.",
        ["D"] =
        "기계공학자에게 많이 필요한 게 있다면 그건 여분의 부품이죠. 안타깝게도 저희 주변엔 여분의 부품이 많지 않아요. 저희도 부품을 구하려고 찾아다녔거든요. 하지만 좋은 소식은 저희의 정보통이 당신의 정보통도 될 수 있다는 거죠.\n\n<윌버가 남쪽 탁 트인 바다를 가리킵니다.>\n\n저 밖에 잠수를 조금만 할 의향이 있다면 건져낼 부품이 많은 난파선이 꽤 있어요. 자, 여기 이 순간이동 신호기를 드릴 테니 저희 순간이동기로 돌아오시면 돼요. 효율적으로 하셔야 할 거예요 -- 배터리 수명이 한정되어 있거든요. 행운을 빌어요!",
    },
    [27107] = {
        ["T"] = "워블 할로우의 보급품",
        ["O"] = "아즈샤라 발로르모크의 피짓에게 물에 젖은 부품 상자를 가져가십시오.",
        ["D"] =
        "자, 이것들을 상자에 담아드릴게요. 당신이 이걸 필요로 한 목적에 도움이 되었으면 좋겠네요. 잠깐, 이걸 어디에 쓸지 말씀하셨던가요?\n\n<윌버의 안색이 창백해집니다.>\n\n오, 호드 전초기지라고요? 음, 어, 기계공학자들 사이의 협력 정신에 따라 우리가 제공한 도움이 이곳 아즈샤라에서 우리 사이의 평화를 유지하는 데 큰 도움이 되기를 바랍니다.\n\n이제 출발하세요!",
    },
    [27108] = {
        ["T"] = "원한의 꼬리일족의 마술",
        ["O"] =
        "아즈샤라 북쪽 마법사 탑에 있는 조이 아나레스와 대화하십시오. 발로르모크 근처 야영지에서 통행을 위해 사나스 림요와 대화해야 할 수도 있습니다.",
        ["D"] =
        "이 땅에 흐르는 에너지가 느껴지나, $C? 자네가 마법부여 막대를 다루는 솜씨가 꽤 있다는 걸 알 수 있지 -- 에너지가 자네 몸에서 뿜어져 나오는 것 같거든.\n\n그것에 대비하고 싶은가? 어쩌면 마법부여 기술을 시험해 볼 텐가? 얼마 전 조수를 구하던 하이 엘프가 근처 대마법사의 탑에 있다네. 사나스 림요와 협상해서 그곳에 올라가야 하지만 한번 확인해 볼 가치는 있을 거야.",
    },
    [27109] = {
        ["T"] = "원한의 꼬리일족의 마술",
        ["O"] =
        "원한의 꼬리 바다마녀나 마술사에게서 암호화된 바다 두루마리 10개를 얻어 아즈샤라 마법사 탑의 조이 아나레스에게 돌아가십시오.",
        ["D"] =
        "자네가 어느 정도 솜씨가 있는 마법부여사라는 건 알겠지만, 나를 위해 사소한 일 몇 가지만 기꺼이 해준다면 가르쳐 줄 것이 많네.\n\n영원의 샘이 폭발하며 땅이 갈라졌을 때 강력한 명가 마법사들은 나가가 되었지. 그들은 아직도 옛 비밀의 대부분을 지니고 있고 나는 그것들을 수집하는 게 목표야.\n\n나가 바다마녀나 마술사를 처치하고 그들이 지니고 다니는 두루마리 열 개를 얻게. 그들은 부서진 해변 남쪽이나 아즈샤라 남동쪽 끝에 있는 레이븐크레스트 기념비 주변 언덕에서 찾을 수 있을 걸세.\n\n자, 가보게!",
    },
    [27110] = {
        ["T"] = "원한의 꼬리일족의 마술",
        ["O"] =
        "아즈샤라 남동쪽의 레이븐크레스트 기념비에서 마술사 얄리나에게 원한의 꼬리 주문껍질을 구한 후 아즈샤라 마법사 탑의 조이 아나레스에게 돌아가십시오.",
        ["D"] =
        "이 두루마리들은 암호를 풀 올바른 열쇠를 가진 자가 아니면 사용할 수 없도록 마법 암호로 부호화되어 있는 것 같군. 다행히 이번 주 초 대마법사 실렘이 점술을 통해 이 문제를 해결할 방법을 찾아냈지.\n\n그가 이 지역을 평소처럼 점술로 관찰하던 중 아즈샤라 남동쪽 끝 레이븐크레스트 기념비에 새로운 사령관이 자리를 잡았다는 것을 알게 되었어. 이 마술사 얄리나는 두루마리를 해독하는 데 사용되는 어떤 열쇠나 증표를 가지고 있을 게 틀림없어. 그녀를 죽이고 이 증표를 나에게 가져오게!",
    },
    [27111] = {
        ["T"] = "엮어 만든 방어구",
        ["O"] = "발로르모크의 줄자를 위해 아즈샤라의 나무그물거미 은둔자에게서 거미줄 10개를 수집하십시오.",
        ["D"] =
        "이 땅에 흐르는 에너지가 느껴지나, $C? 이곳 생물들에게 암울했던 과거와 암울한 미래가 다가온다는 징조지. 명가는 이 땅에 흐르는 마법 그 자체에 큰 죄를 저질렀어. 그런 악에 비하면 내 부두교는 연약하고 무력하지.\n\n그것에 대비하고 싶은가? 우리 재봉사들이 그럴 기술을 가지고 있지만, 여기 원주민들에게서 얻어야 할 게 몇 가지 있다네.\n\n도와주고 싶다면 이곳 아즈샤라에 있는 은둔자 거미들의 거미줄을 좀 가져다주게나. 그걸로 우리가 뭘 짤 수 있는지 보자고.",
    },
    [27112] = {
        ["T"] = "엮어 만든 방어구",
        ["O"] = "발로르모크의 줄자를 위해 아즈샤라의 블러드 엘프에게서 엘프 옷감 12개를 수집하십시오.",
        ["D"] =
        "실 얘기가 나와서 말인데, 우리 동쪽에 있는 블러드 엘프들은 태양빛으로 짠 고급 비단을 가지고 있다네. 그들의 옷감은 조상들의 마법을 자연적으로 튕겨내지. 그걸 좀 구할 수 있다면 우리 일이 훨씬 수월해질 텐데.\n\n동쪽, 그리고 남쪽으로 부서진 해변 위 절벽을 따라 블러드 엘프 야영지를 찾을 수 있을 거야. 그곳의 비단 12장을 구해서 돌아오게나.",
    },
    [27113] = {
        ["T"] = "엮어 만든 방어구",
        ["O"] = "아즈샤라 검은아귀 마을의 상인 말루와 룬문자 실타래를 가을 염료로 교환한 후 발로르모크의 줄자에게 돌아가십시오.",
        ["D"] =
        "마지막으로 현지 재료로 만든 염료가 좀 필요해. 레안더 사부님을 이렇게 사소한 부탁으로 귀찮게 할 순 없고, 수습생들도 너무 바빠서 우리를 도와줄 수 없다네.\n\n저기 북쪽 해안에 이방인들에게 호의적인 펄볼그 마을 상인이 있다고 들었어. 거기에 상인이 있다면 혹시 교환할 염료가 있는지 알아봐 줄 수 있겠나?\n\n가서 교환할 물건이 필요할 거야. 룬문자 실타래가 어떨까? 아마 그들이 작업하는 것보다 훨씬 질이 좋을 거야.",
    },
    [27114] = {
        ["T"] = "바다 건지기",
        ["O"] =
        "워블 할로우 인근 바다에서 윌버, 웬디, 윌슨, 빌헬미나가 잃어버린 보급품을 모은 다음 제한적 순간이동 촉진기를 사용하여 아즈샤라의 워블 할로우에 있는 윌버 워블스미스에게 돌아가십시오.",
        ["D"] =
        "안녕 $C! 워블 할로우가 지금은 촌스럽다는 거 알지만 시간만 조금 내어주시면 아제로스 외딴 구석에 기계공학의 경이로움을 만들어낼 거예요.\n\n그러기 위해 저희 가족이 챙겨온 보급품을 회수하는 데 도움이 필요해요.\n\n저희는 비행기 세 대로 출발했는데 이곳 남쪽 바다에 추락했어요. 그런 다음 은닉품을 회수하려 했지만 배가 침몰해서 간신히 해안으로 살아 돌아왔죠.\n\n저희는 아무도 수영을 못 해서 당신이 물에 뛰어들어 난파선에서 찾은 걸 가져와 주시면 좋겠어요.\n\n걱정 마세요! 기술이 우릴 구해줄 테니까요! 일이 다 끝나면 이 제한적 순간이동 촉진기를 써서 이리로 바로 텔레포트하세요! 효율적으로 하셔야 할 거예요 -- 배터리 수명이 한정되어 있거든요.",
    },
    [27115] = {
        ["T"] = "해안 건지기",
        ["O"] = "아즈샤라 워블 할로우의 윌버 워블스미스를 위해 아즈샤라 해변에서 난파선 보급품 10개를 수집하십시오.",
        ["D"] =
        "괜찮으시다면 일을 하나 더 맡기고 싶어요, $C. 폭풍의 만 남쪽을 따라 이어지는 조수 웅덩이와 해안은 남녘마루 해변으로 알려져 있어요. 우리 비행기가 이곳에 추락하기 전 저는 이 지역을 여러 차례 항공 조사했어요. 잔해가 떠밀려온 곳이 많은 걸 봤거든요. 남녘마루로 내려가서 이 상자들을 조사해 보셨으면 좋겠어요. 워블 할로우에서의 우리 작전에 도움이 될 만한 걸 찾으시면 수고비를 드릴게요. 어때요?",
    },
    [27116] = {
        ["T"] = "인양가 인양하기",
        ["O"] = "아즈샤라 워블 할로우의 윌버 워블스미스를 위해 아크코란 멀록을 처치하고 반짝이는 인양 상자를 회수하십시오.",
        ["D"] =
        "항공 조사 중에 흥미로운 곳을 한 군데 더 발견했어요. 폭풍의 만 반대편 북서쪽에 있는 아크코란의 신전이었죠. 만을 순찰하는 바다 거인들은 온갖 잡동사니를 주워 멀록들이 조사하도록 그곳에 놔둡니다. 멀록들이 온갖 물건을 벗겨내서 쌓아둔다고 생각해요. 멀록은 반짝이는 걸 좋아하는 것 같거든요.\n\n아무튼, 그 말은 멀록의 둥지가 우리가 수집하기에 딱 좋다는 뜻이죠. 멀록은 끔찍한 생물이고 그들을 소탕하는 건 공익을 위한 일입니다. 게다가 워블 할로우에 매우 귀중한 재료를 얻을 수 있다는 보너스까지 있죠! 일하실 생각 있으세요?",
    },
    [27117] = {
        ["T"] = "원한의 꼬리일족 건지기",
        ["O"] =
        "아즈샤라 워블 할로우의 윌슨 워블스미스를 위해 원한의 꼬리 전투대장과 원한의 꼬리 마술사를 처치하여 회수한 두루마리를 수집하십시오.",
        ["D"] =
        "마지막으로 조사할 수 있었던 곳은 아즈샤라의 남동쪽 끝자락인 레이븐크레스트 기념비 근처였어요. 원한의 꼬리 나가가 살고 있는 것을 봤는데, 그중엔 마술사 -- 즉, 강력한 주문 시전자도 있었죠. 우리 노움은 기술 전문가지만 가끔은 기술이 쉽게 할 수 없는 걸 보완하기 위해 마법이 유용할 때가 있어요.\n\n이 나가들은 종종 평범한 주문이 걸려 있는 두루마리를 가지고 다녀요. 우리 집 근처에 있는 나가의 위협을 없애는 보너스와 함께 워블 언덕의 기술을 녀석들의 마법으로 보완할 수 있도록 그들의 두루마리를 좀 가져와 주셨으면 해요!",
    },
    [27118] = {
        ["T"] = "아크코란의 신전 정찰",
        ["O"] = "아즈샤라 북서쪽 아크코란의 신전으로 가서 아크코란 진흙괴물 8마리와 아크코란 점쟁이 8마리를 처치하십시오.",
        ["D"] =
        "개척지에 온 걸 환영한다, $C. 자네도 나처럼 이 땅의 거친 기운이 느껴지나?\n\n하그룸과 악토르는 우리 주변에 보이는 위협에 신경 쓰고 있고 그게 당연해. 하지만 난 그 너머를 보는데, 그들이 아크코란이라 부르는 거대한 사원과... <오싹함> ...지평선 위에 어렴풋이 나타나는, 그 안에서 숨어있는 멀록들이 보여.\n\n난 여기 남아서 문제를 감시하라는 명령을 받았지만, 자네가 나를 위해 놈들을 싹 쓸어버리고 나중에 일어날 멀록 침공의 악몽으로부터 우리를 구해주지 않겠나?",
    },
    [27119] = {
        ["T"] = "지평선의 난파선",
        ["O"] = "아즈샤라 남쪽 해안 어딘가에서 난파선 생존자들을 찾으십시오.",
        ["D"] =
        "안녕 $C! 여기 워블 할로우에선 아즈샤라 해안 위아래는 물론이고 듀로타까지 아주 잘 보이지.\n\n얼마 전에 지평선에서 조난당한 배를 봤어. 꽤 멀리 가라앉았는데 생존자 몇 명이 해안으로 올라온 것 같아. 자네가 해안으로 내려가서 생존자들을 확인해 보는 게 좋겠어. 만약 그들에게 우리가 줄 수 있는 도움이 필요하다면 기꺼이 돕겠네.",
    },
    [27120] = {
        ["T"] = "고대 땅의 전리품",
        ["O"] = "아즈샤라의 발로르모크에 있는 렐코를 위해 이끼발굽 수사슴을 무두질하여 이끼발굽 모피 10개를 수집하십시오.",
        ["D"] =
        "이곳 아즈샤라의 무두질 게임은 고블린 무역왕의 금고만큼이나 풍부하다네, $N. 자네 이 전리품들 중 일부를 손에 넣고 싶은가?\n\n전초기지를 세우려면 엄청난 재료가 필요하고, 발로르모크는 호드가 건설할 수 있는 가장 훌륭한 기지라네. 이 지역 전역에 사는 사슴 가죽으로 좋은 값을 받을 수 있게 해줄게. 놈들을 죽이고 가죽을 벗겨서 끌고 오면 자네 몫의 부를 챙길 수 있을 거야.",
    },
    [27121] = {
        ["T"] = "고대 땅의 전리품",
        ["O"] = "안개날개 키메라를 무두질하여 안개날개 모피 10개를 수집한 다음 아즈샤라의 발로르모크에 있는 렐코에게 돌아가십시오.",
        ["D"] =
        "사슴은 아즈샤라 어디에나 있지만 키메라는 찾기가 훨씬 어렵다네. 그 가죽은 얻기가 훨씬 위험하고 그만큼 훨씬 비싸지.\n\n수집할 전리품을 더 찾고 있다면 멘나르 호수 근처에서 특이한 키메라를 찾을 수 있네 -- 하지만 대부분은 북동쪽 외곽에 있지. 녀석들을 처치하고 가죽을 벗겨 이곳으로 가져오면 보상해 주겠네!",
    },
    [27122] = {
        ["T"] = "고대 땅의 전리품",
        ["O"] = "모피 묶음을 오그리마의 카마리에게 가져가십시오.",
        ["D"] =
        "마지막으로 부탁 하나만 하지, 이보게. 내게 오그리마에 연락책이 하나 있는데 이 가죽들을 아주 기쁘게 사용할 거야. 하지만... 이유가 있어서... 당분간 도시 밖에서 머물려고 해. 이 가죽 묶음을 골짜기에 있는 가죽 세공 상점의 카마리에게 가져가면 수고비로 섭섭지 않게 챙겨줄 거야.\n\n하지만 그녀가 묻는다면 날 못 봤고, 내가 어디 있는지도 모르며, 수표는 우편으로 갈 거라고 하게.",
    },
    [27123] = {
        ["T"] = "학생들에게 물품 공급하기",
        ["O"] = "태양풀 20개를 아즈샤라의 발로르모크에 있는 수습생 사리나에게 가져가십시오.",
        ["D"] =
        "안녕하세요, $C. 뭐 필요한 거라도 있으신가요? 전 레안더 사부님이 내주신 과제들 때문에 너무 바빠요.\n\n참, 혹시 약초학자는 아니신가요? 만약 그렇다면 당신의 도움이 정말 필요해요. 태양풀이 거의 다 떨어졌는데, 아즈샤라에는 태양풀이 흔하게 자라지만 더 채집하러 나갈 시간이 없거든요. 여행 중에 태양풀을 보게 되면 우리 재고 좀 다시 채워주시겠어요?\n\n수습생 사리나에게 전해주세요. 그녀가 태양풀 기름의 새로운 공식을 연구 중이거든요.",
    },
    [27124] = {
        ["T"] = "학생들에게 물품 공급하기",
        ["O"] =
        "거대한 폭풍히드라 5마리를 처치하고 그들의 소화 주머니를 모으십시오. 그런 다음 아즈샤라의 발로르모크에 있는 수습생 자비스에게 가져가십시오.",
        ["D"] =
        "코린은 우리 연구실을 차린 이후로 계속 꽃과 함께 전령을 보내 제게 시간을 낭비하고 있어요. 그는 아즈샤라 식물 분류 작업에 전념해야 하는데 말이죠!\n\n저희를 정말 돕고 싶으시다면 수습생들끼리는 도저히 할 수 없는 일이 있어요. 아즈샤라 남동쪽 해안에 서식하는 거대한 폭풍히드라들이 레이븐크레스트 기념비 아래의 연약한 조수 웅덩이를 배회하며 그곳에서 자라는 희귀하고 연약한 식물들을 밟고 지나다닙니다. 히드라들이 너무 위험해서 우린 아직 그 웅덩이에서 자라는 모든 종의 목록조차 확보하지 못했어요.\n\n히드라 몇 마리를 죽이고 소화 주머니를 수집해 주신다면 그 지역에서 무엇이 자라는지 더 잘 이해할 수 있을 거예요. 수집할 수 있다면 2층에 있는 생물학 전문가 수습생 자비스에게 가져가 주세요.",
    },
    [27125] = {
        ["T"] = "학생들에게 물품 공급하기",
        ["O"] =
        "남녘마루 해변을 따라 있는 조수 웅덩이에서 하얀조수 연꽃 8개를 수집하여 아즈샤라의 발로르모크에 있는 수습생 윈터에게 가져가십시오.",
        ["D"] =
        "놀랍군요, $C! 이 폭풍히드라의 위에는 하얀조수 연꽃 잔해물이 남아있어요.\n\n하얀조수 연꽃은 매우 희귀해서 노련한 약초학자가 채집해야 해요. 유감스럽게도 여기 수습생 중에는 그럴 기술을 가진 사람이 없어요. 하지만 어쩌면 당신은 할 수 있지 않을까요?\n\n이 약초를 채집하고 싶으시다면 아즈샤라 남동쪽 계곡과 바위 지대에 있는 조수 웅덩이를 수색하세요. 찾은 연꽃은 모두 최상층에 있는 수습생 윈터에게 가져가세요.",
    },
    [27126] = {
        ["T"] = "펄볼그 - 고블린 무역 연결망",
        ["O"] = "스팀휘들 무역회사와 검은아귀 마을 사이에 무역로를 개척하는 것에 관해 아즈샤라의 킴자엘과 대화하십시오.",
        ["D"] =
        "안녕 새 친구. 나 말루. 검은아귀 상인.\n\n우리가 마을을 이방인들에게 개방한 후로 나는 무역에서 새 장신구를 많이 얻었다. 내 새 친구는 작은 녹색 인간인 킴자엘이다. 녹색 인간은 검은아귀 마을에서 멀리 떨어진 많은 녹색 인간과 거래하는 걸 도울 수 있다고 했다.\n\n말루는 외부인과 거래하기 위해 마을에 머물러야 하지만, 네가 녹색 인간을 찾아가서 말루가 이제 거래를 원한다고 전해주어라. 그는 여기서 멀지 않은, 엘프 야영지 위의 언덕에 산다.",
    },
    [27127] = {
        ["T"] = "펄볼그 - 고블린 무역 연결망",
        ["O"] = "톱니항에 있는 M. 스펜서 쿠퍼핀치와 굴뚝나무 목장조합 및 검은아귀 마을 간의 무역로 개척에 관해 대화하십시오.",
        ["D"] =
        "솔직히, $N... $N라고 불러도 될까요? 솔직히 저는 그 친구에게 예의를 갖췄을 뿐이에요. 검은아귀가 수집하는 물건들은 보통 제가 취급하는 상품이 아니거든요.\n\n하지만 당신이 여기 있고 의향이 있으니, 제안을 하나 하죠. 제 사촌이 남쪽에서 굴뚝나무 목장조합을 위해 일하며 괜찮은 일거리를 구했어요. 그들은 온갖 특이한 장난감과 장신구로 유명하죠. 어쩌면 검은아귀가 만드는 조각된 토템들이 율 축제에 잘 팔릴지도 모르죠? 아니면 신선한 생선 시장이 있을 수도 있고요? 저도 잘 모르겠네요.\n\n톱니항에 있는 그들 사무실 밖에서 굴뚝나무의 물건을 팔고 있는 제 사촌을 찾을 수 있을 겁니다. 이름은 M. 스펜서 쿠퍼핀치입니다.",
    },
    [27128] = {
        ["T"] = "펄볼그 - 고블린 무역 연결망",
        ["O"] = "스팀휘들 항구의 재비와 스팀휘들 무역회사 및 검은아귀 마을 간의 무역로 개척에 관해 대화하십시오.",
        ["D"] =
        "보세요 $N... $N라고 불러도 될까요? 굴뚝나무 목장조합은 최고급 품질의 상품을 취급합니다. 이건 장인 정신의 정의 그 자체네요. 아즈샤라의 숲에서 곰들이 만든 수공예품이라뇨? 하! 까다로운 나이트 엘프 시장에 진출할 수 있을지도 모르겠지만... 흠....\n\n<M. 스펜서 쿠퍼핀치가 잠시 생각에 잠깁니다.>\n\n아니요, 아니요, 절대 안 될 겁니다. 죄송합니다 $N, 당신이 제안하는 물건은 저한테 필요 없고 킴자엘이 당신을 떼어내려고 저에게 보낸 것 같군요. 하지만 제가 꽤 괜찮은 사업가이니 펄볼그가 파는 물건에 관심이 있을 만한 사람을 연결해 드리죠. 옛 룸메이트인 재비가 타나리스의 스팀휘들 항구에서 물건을 팔고 있어요. 어쩌면 아주 먼 북쪽에서 온 물건이 그의 고객들에게 신기하게 느껴질지도 모르죠?",
    },
    [27129] = {
        ["T"] = "펄볼그 - 고블린 무역 연결망",
        ["O"] = "행상 러즈고트와 스팀휘들 무역회사 및 검은아귀 마을 간의 무역로 개척에 관해 대화하십시오.",
        ["D"] =
        "있잖아요 $N... $N라고 불러도 되죠? 있잖아요, 곰이 숲에서 장난감을 만든다는 지어낸 이야기를 들고 당신처럼 순진한 얼간이가 제 상점에 들어오는 건 매일 있는 일이 아니에요. 꽤 괜찮은 농담이네요!\n\n잠깐, 진심이에요?\n\n음. 뭐, 원유가 흐르고 물이 펌프질되기 시작한 이후로 이곳 스팀휘들 항구가 활기를 띠고 있어요. 그 말인즉슨 관광객이 많다는 거죠! 무법항에 있는 아이들에게 가져다줄 물건을 찾는 해적이든, 즐길 거리가 필요한 목마른 행상이든 제가 팔아넘기겠습니다. 그러니 좋아요, 한번 해보죠!\n\n가장 먼저 필요한 것은 기반 시설입니다. 아즈샤라에 정박해서 물건을 싣고 이곳으로 항해할 수 있는 사람이 필요하죠. 무법항에 있는 행상 러즈고트와 얘기해 보는 게 어때요? 그가 북쪽 바다에 연락책을 이미 마련해 뒀는지 알아보세요.",
    },
    [27130] = {
        ["T"] = "펄볼그 - 고블린 무역 연결망",
        ["O"] = "스프링소켓의 요아킴 스파크루트와 스팀휘들 무역회사 및 검은아귀 마을 간의 무역로 개척에 관해 대화하십시오.",
        ["D"] =
        "제가 데리고 있던 덩치 중 한 명이 스팀휘들 무역회사가 황야의 땅 스프링소켓으로 이전했을 때 자기만의 상단 회사를 차렸어요. 그곳이 황무지인 점을 감안하면 일자리가 더 필요할 것 같네요. 이름은 요아킴 스파크루트이고 휴일에는 마을에서 어슬렁거리는 그를 찾을 수 있을 겁니다.\n\n러즈고트가 보냈다고 전하면 서비스 요금을 깎아줄지도 몰라요!",
    },
    [27131] = {
        ["T"] = "펄볼그 - 고블린 무역 연결망",
        ["O"] = "눈망루 마을에 있는 우마론 스트래가렐름과 스팀휘들 무역회사 및 검은아귀 마을 간의 무역로 개척에 관해 대화하십시오.",
        ["D"] =
        "러즈고트의 판단은 옳았지만 제가 이 일을 맡을 고블린은 아닙니다. 황야의 땅을 떠날 생각은 전혀 없습니다. 이곳에는 할 수 있는 사업이 많이 있고 아무리 솔깃하게 들리더라도 곰들 때문에 그런 기회를 놓치지는 않을 것입니다.\n\n하지만 이봐요, 헛걸음하신 건 아닙니다. 제 전 직원 중 한 명이 더위를 몹시 싫어해서 사막에서 최대한 먼 곳인 여명의 설원으로 갔거든요. 눈망루 마을에 있는 우마론 스트래가렐름에게 이야기해 보세요. 그는 일자리가 필요하고 이 일을 할 만한 경험도 있습니다.\n\n행운을 빕니다, $N... $N라고 불러도 되겠죠?",
    },
    [27132] = {
        ["T"] = "펄볼그 - 고블린 무역 연결망",
        ["O"] = "검은아귀 마을에 있는 상인 말루와 개척한 무역망에 대해 대화하십시오.",
        ["D"] =
        "이 검은아귀 마을이 해안가에 있다고요? 그리고 물건을 타나리스의 스팀휘들 항구로 옮겨야 한다고요? 꽤 쉬운 일 같네요. 제 여동생의 증기선을 빌리겠습니다. 여동생이 어쩌다 보니 노움이랑 결혼했거든요.\n\n다음 달에 운항을 시작할 수 있습니다. 마을 연락책에게 배송에 맞게 포장해두라고 하세요. 바구니든 상자든 상관없습니다. 다만 낱개 물건은 안 됩니다. 안 그러면 제가 파손에 대한 책임을 지지 않을 거니까요.\n\n계약서 보내주셨나요? 아니라고요? 곰이잖아요. 그들이 서류 작업에 신경 쓸 거라곤 생각 안 해요.\n\n어쨌든 그에게 약속은 약속이라고 전해주세요. 일 줘서 고맙습니다.",
    },
    [27133] = {
        ["T"] = "도둑들!",
        ["O"] = "레스리스 성소에서 알렉산드라의 서적을 되찾은 다음 아즈샤라 폐허가 된 해변에 있는 그녀에게 돌려주십시오.",
        ["D"] =
        "나가들의 공격을 -- 발톱이나 지느러미 등 무엇이든 간에 -- 받은 건 이번이 처음이 아니에요! 저희가 처음 도착했을 때 우리는 바로 해변에 자리를 잡았습니다. 하지만 우리가 알아차리기도 전에 멀록과 나가가 우리를 기습해 이곳으로 후퇴할 수밖에 없었습니다.\n\n단 한 번 뒤돌아보았지만 멀록 중 한 마리가 수년간 작업해 온 제 서적을 물갈퀴 달린 손가락으로 만지작거리고 있는 것을 보았습니다. 제발 그걸 되찾아 주신다면 기꺼이 돈을 지불하겠습니다. 동쪽에 있는 레스리스 성소 방향에서 온 것 같았어요.",
    },
    [27134] = {
        ["T"] = "안전을 위해",
        ["O"] =
        "레스리스 성소에서 원한의 꼬리 약탈자 10마리와 원한의 꼬리 마녀 5마리를 처치하고 아즈샤라의 폐허가 된 해변에 있는 패트릭 밀스에게 돌아가십시오.",
        ["D"] =
        "나가가 우리를 이곳으로 밀어낸 이후로, 우린 수비에 전념하고 있습니다. 지금 당장 한숨 돌릴 수는 있지만 의사가 부상자들을 돌보는 동안 그들이 우리에게 접근하지 못하게 할 무언가 조치를 취해야 합니다.\n\n알렉산드라는 나가가 레스리스 성소에서 접근하는 것을 보았다고 했습니다. 우리를 도울 생각이 있으시다면 그곳이 나가를 공격할 적기입니다. 운이 좋다면 추가 공격을 감행할지 다시 생각하게 될 겁니다.",
    },
    [27135] = {
        ["T"] = "벼랑 끝에서",
        ["O"] = "아즈샤라 폐허가 된 해변에 있는 닥터 텔틴을 위해 의료 물품 상자 3개를 모으십시오.",
        ["D"] =
        "이건 악몽이에요. 배는 가라앉고 포위된 데다 이제 보급품까지 떨어져 가고 있어요.\n\n부탁 하나만 들어주시겠어요? 우리 의료 물품 중 일부가 남쪽에 있는 지평선 정찰호 난파선에서 떠내려왔을지도 몰라요. 그리고 서쪽에서 노움의 집처럼 보이는 것도 봤어요. 거기서 보급품을 팔지도 몰라요.\n\n어디서든 제게 의료 물품을 가져다주신다면 아즈샤라가 우리에게 어떤 시련을 주든 살아남게 해 주실 거예요.",
    },
    [27136] = {
        ["T"] = "지평선 정찰호",
        ["O"] = "아즈샤라에 있는 지평선 정찰호 근처에서 이등항해사 샨드릴을 찾으십시오.",
        ["D"] =
        "저와 제 승무원들은 당신이 와주어서 운이 좋았습니다. 상황이 나아지기 시작했군요.\n\n벌써 많은 것을 부탁드렸지만, 우리가 처음 이곳에 발이 묶였을 때 제 이등항해사 샨드릴이 지평선 정찰호 근처에 다른 생존자가 있는지 확인하러 나섰습니다. 제가 이곳을 지키는 동안 그녀의 상태를 확인해 주시겠습니까? 그녀는 우리 위치에서 남쪽으로 내려가면 있을 겁니다.",
    },
    [27137] = {
        ["T"] = "지평선 정찰호",
        ["O"] = "지평선 정찰호 난파선 근처에서 실종된 승무원을 찾아본 뒤 이등항해사 샨드릴에게 돌아가십시오.",
        ["D"] =
        "배가 가라앉았을 때 우리 대부분은 목숨을 건졌지만, 승무원 중 세 명이 아직 행방불명이라는 사실을 깨달았습니다. 그들을 찾을 수 있을까 싶어 난파선으로 헤엄쳐 갔지만 부상 때문에 계속 찾을 수가 없었죠.\n\n저는 아직도 부상에서 회복 중입니다. 저희 일등항해사, 요리사, 기계공학자를 찾을 수 있는지 확인해 주십시오. 운이 좋았다면 그들은 빠져나왔겠지만 왠지 불길한 예감이 듭니다.",
    },
    [27138] = {
        ["T"] = "열심히, 하지만 너무 열심히는 말고",
        ["O"] = "지평선 정찰호 난파선에 있는 롤랜드 기어대블러를 구하기 위해 \"최선을 다하십시오\".",
        ["D"] =
        "그 망할 노움 녀석! 지평선 정찰호에는 승객이 몇 명 타고 있었고 그중 하나가 롤랜드라는 이 비열한 작은 노움이었죠. 실종된 우리 승무원을 찾을 수 있을까 살펴보고 있었는데 그 노움이 절 공격했어요.\n\n발작을 일으킨 것 같아요. 최선을 다해서 그를 정신 차리게 하고 안전한 곳으로 데려가지 않으면 제 할 일을 다하지 못하는 것이겠지만, 지금은 그를 상대할 여력이 없어요. 아마 당신이라면 저보다 더 운이 좋을지도요?\n\n자기방어를 위해 그를 죽여야만 한다면, 이해합니다.",
    },
    [27139] = {
        ["T"] = "지평선 정찰호",
        ["O"] = "아즈샤라의 폐허가 된 해변에 있는 선장 바네사 벨티스에게 돌아가십시오.",
        ["D"] =
        "당신이 할 수 있는 일은 다 한 것 같군요. 저는 이곳에 남아서 돌아가기 전에 쓸만한 물건을 찾아볼게요.\n\n선장님께 확인해 보세요.",
    },
    [27140] = {
        ["T"] = "지맥 나침반",
        ["O"] = "아즈샤라 발로르모크의 레안더 사부에게 이상한 나침반을 가져가십시오.",
        ["D"] =
        "당신이 처치한 마술군주는 이상한 마법 장치를 지니고 있었습니다. 나침반 모양이지만 그 정교한 은빛 도구는 북쪽을 가리키지 않습니다. 대신 유리 케이스 아래에서 빠르게 회전하며 다이얼처럼 보이는 곳에 낯선 표시를 띄엄띄엄 가리킵니다.\n\n아마도 발로르모크의 레안더 사부가 이 물건을 조사하는 데 관심이 있지 않을까요?",
    },
    [27141] = {
        ["T"] = "부서진 해변 사령관",
        ["O"] = "부서진 해변에서 파도여사제 아킬라를 찾아 처치한 후 아즈샤라 워블 할로우의 웬디 워블스미스에게 승리 소식을 보고하십시오.",
        ["D"] =
        "이 나가는 해초에 싸여 있는 명령서 같은 것을 지니고 있었습니다. 불가해한 나가의 문자를 자세히 이해할 수는 없지만 명령서에 파도여사제 아킬라라는 사령관의 이름이 있다는 것은 알아볼 수 있습니다.\n\n부서진 해변에서 원한의 꼬리일족 사령관을 제거하면 웬디 워블스미스를 기쁘게 할 것이고 워블 할로우의 안전을 확보하는 데 도움이 될 것입니다. 근처에 있는 대형 텐트들을 확인해 보는 게 좋지 않을까요?",
    },
    [27142] = {
        ["T"] = "부서진 해변 사령관",
        ["O"] = "부서진 해변에서 파도여사제 아킬라를 찾아 처치한 후 아즈샤라 발로르모크의 하그룸 블러드피스트에게 승리 소식을 보고하십시오.",
        ["D"] =
        "이 나가는 해초에 싸여 있는 명령서 같은 것을 지니고 있었습니다. 불가해한 나가의 문자를 자세히 이해할 수는 없지만 명령서에 파도여사제 아킬라라는 사령관의 이름이 있다는 것은 알아볼 수 있습니다.\n\n부서진 해변에서 원한의 꼬리일족 사령관을 제거하면 하그룸 블러드피스트를 기쁘게 할 것이고 발로르모크의 안전을 확보하는 데 도움이 될 것입니다. 근처에 있는 대형 텐트들을 확인해 보는 게 좋지 않을까요?",
    },
    [27143] = {
        ["T"] = "나무구렁 동맹",
        ["O"] =
        "문지기 레이지로어와 대화하여 검은아귀 펄볼그는 타락하지 않았다고 설명하십시오. 이 대화를 진행하려면 나무구렁 펄볼그와 최소한 약간 적대적 이상의 평판이 필요합니다.",
        ["D"] =
        "이제 검은아귀의 친구가 되었으니 검은아귀가 할 수 없는 일을 해주면 좋겠다.\n\n나무구렁 펄볼그는 우리 형제지만 다른 펄볼그를 믿지 않는다. 충분히 그럴 만하다. 다수가 타락했기 때문이다. 하지만 나무구렁은 검은아귀와 같다. 너는 나무구렁의 친구가 될 수 있다. 만약 네가 나무구렁과 검은아귀 모두의 친구라면, 문지기 레이지로어에게 검은아귀를 위한 메시지를 가져다줄 수 있을 것이다.\n\n레이지로어는 나무구렁 요새 입구를 감시한다. 하지만 그에게 다가가려면 나무구렁의 친구여야 한다. 그들에게 검은아귀는 타락하지 않았다고 전해라. 우리가 모두 친구라고 전해라.",
    },
    [27144] = {
        ["T"] = "나무구렁 동맹",
        ["O"] = "아즈샤라 나무구렁 요새의 정찰병 갈레스와 대화하십시오.",
        ["D"] =
        "너는 나무구렁의 친구이고 검은아귀의 친구라고 말했으니 널 믿는다 $C.\n\n<생각에 잠기는 문지기 레이지로어>\n\n너와 함께 정찰병 갈레스를 검은아귀에게 보내겠다. 넌 그를 지켜라. 그가 진실을 보고 보고할 것이다. 그를 데리고 무사히 다녀와라.",
    },
    [27145] = {
        ["T"] = "나무구렁 동맹",
        ["O"] = "정찰병 갈레스를 검은아귀 마을로 호위하여 검은아귀가 타락하지 않았음을 증명하십시오.",
        ["D"] =
        "난 검은아귀와 얘기해 본 적이 없다. 그들은 악마들이 오기 전부터 멀리 떨어져 살았다. 족장에 대해 무서운 이야기들을 들었다. 그가 늑대로 변한다고 말하는 사람도 있었다. 본 적 있나? 없나? 그럼 사실이 아닐지도.\n\n난 언제든 준비돼 있다. 악마들을 보게 되면 내가 검은아귀를 만날 수 있게 날 보호해 줘.",
    },
    [27146] = {
        ["T"] = "나무구렁 동맹",
        ["O"] = "문지기 레이지로어의 우정의 제안을 아즈샤라 검은아귀 마을의 대족장 운갈에게 가져가십시오.",
        ["D"] =
        "나무구렁의 친구로서 이 메시지를 검은아귀에게 가져가라. 우리가 너희를 본다. 우리가 너희 냄새를 맡는다. 우린 함께 악마와 싸운다.\n\n우리는 검은아귀를 감시하고, 검은아귀는 나무구렁을 감시한다. 타락이 온다면 우린 해야 할 일을 할 것이다.\n\n이제 우정 안에서 가라 $N.",
    },
    [27147] = {
        ["T"] = "다가올 겨울",
        ["O"] = "돼지치기 구눅을 위해 아즈샤라 이끼발굽 엘크를 무두질하여 사슴고기 스테이크 10개를 수집하십시오.",
        ["D"] =
        "돼지는 내 열정의 대상이야, $N. 하지만 겨울이 오면 돼지만으로는 우리 배를 채울 수 없어 -- 게다가 돼지 녀석들도 먹어야 하거든!\n\n거대한 뿔을 단 크고 살집이 두둑한 짐승들이 숲을 누비는 걸 봤지. 타우렌 중 한 명이 그걸 '엘크'나 '사슴' 비슷한 이름으로 부르는 걸 들었어. 먹음직스러워 보이던데, 우린 다가올 겨울을 준비해야 해. 그 고기를 좀 가져와서 비축해 줄 수 있겠어?",
    },
    [27148] = {
        ["T"] = "다가올 겨울",
        ["O"] = "아즈샤라 발로르모크의 돼지치기 구눅을 위해 발로르모크 동쪽의 나가에게서 원한의 꼬리일족 해초 10개를 수집하십시오.",
        ["D"] =
        "제디가는 아즈샤라에 온 최초의 오크 중 한 명이고 그녀는 특이하게도 해초에 맛을 들였다네!\n\n제디가의 주장에 따르면 해초는 고기처럼 아주 다양한 방법으로 요리할 수 있다고 해. 말리거나, 양념을 치거나, 살짝 튀기거나, 굽거나, 끓이거나, 종류가 셀 수 없이 많지.\n\n해변의 나가가 해초를 많이 가지고 있다고 들었어. 해초가 나가를 저렇게 크고 강하게 만든다면, 어쩌면 우리도 크고 강하게 만들어줄지 모르지. 우리를 위해 나가에게서 해초를 좀 넉넉히 구해와 줄 수 있겠어?",
    },
    [27149] = {
        ["T"] = "다가올 겨울",
        ["O"] = "아즈샤라 발로르모크의 돼지치기 구눅을 위해 아크코란 바닷가재를 처치하고 거대한 바닷가재 집게 10개를 수집하십시오.",
        ["D"] =
        "트롤들은 여기서 바닷가재를 잡는 것에 대해 이야기하곤 해. 우리 고향 드레노어에도 바닷가재가 있었지. 난 바닷가재를 아주 좋아해.\n\n하지만 아즈샤라에는 바닷가재 인간들이 있더군! 녀석들의 집게는 더 커. 더 맛있을 게 분명해. 고기도 확실히 더 많을 테고 말이야.\n\n내가 요리해 볼 수 있게 그 크고 살 많은 집게를 좀 가져다줄 수 있겠어? 해변을 따라 북서쪽으로 아크코란의 신전 쪽에 녀석들이 무리 지어 있어.",
    },
    [27150] = {
        ["T"] = "다가올 겨울",
        ["O"] = "검은아귀 마을의 상인 말루에게서 검은아귀 버터를 얻어 아즈샤라 발로르모크의 돼지치기 구눅에게 가져오십시오.",
        ["D"] =
        "당신은 이 보잘것없는 돼지 농부에게 큰 도움이 되었습니다. 한 가지 더 부탁하기 미안하지만, 이 바닷가재 집게와 곁들일 버터가 정말 먹고 싶군요.\n\n북쪽 해안에는 나무구렁보다 이방인을 더 환영하는 펄볼그 야영지가 있습니다. 검은아귀라고 불리는데 우리와 보급품을 거래할 의향이 있습니다. 이 베이컨 한 조각을 그곳 상인에게 가져가서 버터와 바꿔줄 수 있는지 알아봐 주시겠습니까?",
    },
    [27151] = {
        ["T"] = "배고픈 노움",
        ["O"] = "아즈샤라의 이끼발굽 엘크에게서 사슴고기 스테이크 10개를 모아 워블 할로우에 있는 빌헬미나 워블스미스에게 가져오십시오.",
        ["D"] =
        "안녕 $R! 워블 할로우에 온 걸 환영해요.\n\n먹을 걸 좀 주고 싶은데 솔직히 말하자면 우린 생선 빼고는 먹을 게 아무것도 없거든요. 매일 생선만 먹어요.\n\n바다 덕분에 굶어 죽진 않겠지만 육즙이 가득한 스테이크가 너무 먹고 싶어요. 숲에 멋진 수사슴이 있는 걸 봤는데 전 사냥꾼이 아니잖아요. 관심 있으시면, 사슴고기 한 무더기를 제게 가져다주시면 수고비를 넉넉히 드릴게요.",
    },
    [27152] = {
        ["T"] = "배고픈 노움",
        ["O"] =
        "엘다라스 폐허와 부서진 해변의 원한의 꼬리 나가에게서 긁어모은 보급품 10개를 수집한 다음 아즈샤라의 워블 할로우에 있는 빌헬미나 워블스미스에게 돌아가십시오.",
        ["D"] =
        "당장 요리하고 싶지만 향신료를 구할 수 있다면 뭐든 하겠어요. 약간의 양념, 약간의 소금... 잠깐, 아이디어가 떠올랐어요!\n\n폭풍의 만은 위험한 곳이라 정기적으로 배가 난파되어 그곳으로 떠밀려 옵니다. 이 난파선들은 부서진 해변 아래로 내려온 원한의 꼬리 나가들에 의해 약탈당합니다. 그들 아래에는 보급품이 산더미처럼 쌓여 있을 테니 장담컨대 그 안에는 향신료도 있을 거예요!\n\n향신료가 그냥 널려 있을지 아니면 나가에게서 무력으로 보급품을 뺏어야 할지는 모르겠지만, 제가 찾는 걸 긁어모아 주시면 수고비를 넉넉히 드릴게요.",
    },
    [27153] = {
        ["T"] = "배고픈 노움",
        ["O"] = "아즈샤라 워블 할로우에 있는 빌헬미나 워블스미스를 위해 아크코란 바닷가재를 처치하고 거대한 바닷가재 집게 10개를 수집하십시오.",
        ["D"] =
        "좋아요! 성공이에요 $N! 이 상자에는 진정 효과가 있는 매운 향신료가 가득하네요. 하지만 이제 더 좋은 아이디어가 생겼어요....\n\n스테이크보다 좋은 게 뭘까요? 바닷가재와 함께 먹는 거요!\n\n바다는 이제 지긋지긋하다고 말한 건 알지만 해산물과 고기가 먹고 싶다는 생각이 든 이상 그 생각을 떨칠 수가 없어요.\n\n이제 바닷가재를 구할 곳만 남았네요. 거대한 고깃덩어리 같은 집게를 달고 아즈샤라를 돌아다니는 바닷가재 인간들 본 적 있어요? 아즈샤라 북서쪽 끝의 아크코란의 신전에 그놈들이 엄청나게 모여 있어요. 바닷가재 인간들을 처치하고 제게 그 고기를 가져오세요! 그게 어떤 맛일지 상상이 가나요?",
    },
    [27154] = {
        ["T"] = "배고픈 노움",
        ["O"] = "검은아귀 마을 상인 말루에게서 검은아귀 버터를 얻어 아즈샤라 워블 할로우의 빌헬미나 워블스미스에게 가져오십시오.",
        ["D"] =
        "좋아요 $N! 바닷가재도 구했고! 스테이크도 구했어요! 향신료도 있고! 그리고... 오, 안 돼... 이런! 버터가 없어요. 버터 없이 어떻게 육즙이 풍부하고 버터 향이 나는 스테이크와 바닷가재를 먹을 수 있죠?\n\n이 꿈을 포기할 순 없어요 $N. 아즈샤라 어딘가에서 버터를 구할 수 있는 약간의 희망이 있어요.\n\n북쪽 해안을 따라 이방인에게 우호적인 펄볼그 야영지가 있어요. 온갖 물건을 파는 상인들이 있다고 들었어요. 어쩌면 이 베이컨 한 조각과 교환하면 버터를 줄지도 모르잖아요?",
    },
    [27155] = {
        ["T"] = "발로르모크의 위협",
        ["O"] = "발로르모크에 있는 하그룸 블러드피스트를 위해 원한의 꼬리 전사 10마리와 원한의 꼬리 비명술사 10마리를 처치하십시오.",
        ["D"] =
        "환영하오, 호드의 병사여!\n\n발로르모크는 호드의 칼림도어 전진 기지 중 가장 멀리 떨어진 곳이고, 우리의 입지를 안전하게 하려면 당신의 도움이 필요하오.\n\n근처 폐허에 있는 나가 무리를 소탕하는 것부터 시작하면 되오. 무기가 그들의 피로 붉게 물들 때까지 전사와 비명술사들을 처치하시오!\n\n잠깐... 나가의 피도 붉은색이던가?\n\n알아보시오!",
    },
    [27156] = {
        ["T"] = "발로르모크의 위협",
        ["O"] = "발로르모크에 있는 하그룸 블러드피스트를 위해 원한의 꼬리 미르미돈 10마리와 원한의 꼬리 바다마녀 10마리를 처치하십시오.",
        ["D"] =
        "발로르모크 근처의 나가는 약하고 쉽게 무너진다오. 그런 하찮은 적에게 당신을 보내 미안하지만 더 적합한 도전을 제안하기 전에 당신의 용기를 시험해야만 했소. 동쪽 부서진 해변에 가면 더 까다로운 상대들을 찾을 수 있을 거요.\n\n원한의 꼬리 미르미돈과 바다마녀를 처치하시오. 우리가 오늘 밤 푹 잘 수 있도록 해변의 적들을 모두 소탕하시오!",
    },
    [27157] = {
        ["T"] = "발로르모크의 위협",
        ["O"] = "하그룸 블러드피스트를 위해 폭풍해안멀록 전사 15마리를 처치하십시오.",
        ["D"] =
        "제 상관인 혈투사 글러쉬는 특히 멀록을 싫어합니다. 저는 멀록에게 딱히 반감은 없지만, 어쨌든 녀석들이 위협적인 건 사실이죠.\n\n멀록 전사들이 아즈샤라 북쪽 해안을 대거 순찰하고 있습니다. 놈들이 규합하여 우리에게 대항하지 못하도록 그 수를 줄이십시오.\n\n그러면 글러쉬도 그 기괴한 소음에 대해 조용히 있을 겁니다.",
    },
    [27158] = {
        ["T"] = "발로르모크의 위협",
        ["O"] = "발로르모크에 있는 하그룸 블러드피스트를 위해 푸른용혈족 5마리, 푸른 비늘파멸자 5마리, 용족 마술사 5마리를 처치하십시오.",
        ["D"] =
        "당신은 다양한 무예의 적을 상대로 자신의 능력을 증명했지만 마법을 사용하는 적은 어떻소?\n\n푸른 용혈족 무리가 남쪽 멘나르 호수 주변에 거주하고 있소. 그들이 있다는 것은 그 지역에 지맥이나 다른 마법의 결절이 있다는 의미지. 앞으로 우리가 그 자원을 이용해야 할지도 모른다오.\n\n그들의 군대를 처치하는 선발 임무를 수행해 푸른 용혈족에게 호드의 공포를 심어주시오. 그러면 우리가 무력으로 진입할 때 그들은 달아날 거요.\n\n푸른 용혈족은 평범한 적이 아니니 이 임무를 위해 분대를 구성하는 게 좋을 거요.",
    },
    [27159] = {
        ["T"] = "발로르모크의 위협",
        ["O"] = "발로르모크에 있는 하그룸 블러드피스트를 위해 바다 거인 5마리를 처치하십시오.",
        ["D"] =
        "당신에게 많은 것을 부탁했고, $N, 지금까지 실망하게 한 적이 없군. 안전을 확보하기 위한 마지막 임무가 하나 남았소.\n\n아즈샤라의 바다 거인은 침략할 만큼 조직적이지는 않지만 발소리만으로도 대지가 진동하여, 이곳, 특히 광산에서 벌어지는 모든 새로운 건설 작업이 위태로워지고 있소. 그들의 수를 줄여줬으면 하오.\n\n만약 그 분대가 근처에 있다면, 이번에도 다시 투입하고 싶을 거요. 행운을 비오.",
    },
    [27160] = {
        ["T"] = "발로르모크 광산 보고서",
        ["O"] = "아즈샤라 발로르모크 광산의 현장감독 레오폴드, 감독관 갈드, 현장감독 레오나드와 대화하여 채굴 상황에 대한 보고를 받으십시오.",
        ["D"] =
        "발로르모크에 오신 것을 환영합니다, $C. 우리는 대족장님의 의지에 따라 이 땅을 길들이고 그 자원을 이용해 호드에게 장비와 물자를 조달하기 위해 이곳에 왔습니다.\n\n전 전초기지의 문제를 처리하느라 바빴으니 -- 혹시 당신이 마을 북쪽에 있는 광산에 들러 관리자들에게 상황을 확인해 주실 수 있겠습니까? 상태 보고서를 제출할 때가 지났거든요.",
    },
    [27161] = {
        ["T"] = "휘파람 불며 일하기",
        ["O"] = "발로르모크 광부 5명과 함께 /휘파람을 불고, 아즈샤라 발로르모크의 악토르 블러드피스트에게 돌아가십시오.",
        ["D"] =
        "저를 급진주의자라고 부르겠지만 저는 음악이 어두운 날을 바꿀 수 있다고 믿습니다. 자, 입술을 모으고 광산으로 내려가 광부들과 함께 휘파람을 불어보십시오. 즐겁게 우린 이곳에서 광석을 추출할 수 있습니다. 노래가 페이스를 맞추는 데 도움이 되면 그리 오래 걸리지 않을 겁니다.\n\n사기가 높아지면 시간은 훌쩍 지나갈 겁니다. 그러니, 일하는 동안 휘파람을 불게 하십시오.\n\n<악토르가 당신을 향해 기분 나쁠 정도로 크게 웃어 보입니다.>",
    },
    [27162] = {
        ["T"] = "발로르모크의 오그리마 보고서",
        ["O"] = "오그리마의 지혜의 골짜기에 있는 스랄에게 발로르모크 보고서를 전달하십시오.",
        ["D"] =
        "<악토르 블러드피스트가 한숨을 내쉽니다.>\n\n제가 누구를 속이겠습니까? 약간의 음악이 모든 것을 고쳐주지는 못할 겁니다.\n\n얼라이언스나 불타는 군단과 싸울 때가 훨씬 쉬웠습니다. 이제는 '사기', '약혼', '이제 켄타우로스는 무두질할 수 없다' 같은 이야기뿐이니까요.\n\n광부들에게 영향을 미치는 무언가가 있다면 어쩌면 스랄 님은 어떻게 해야 할지 아실지도 모릅니다. 어쨌든 저는 그분께 광산이 가동되고 있지만 아직 목표 생산량에 도달하지 못했다고 알려야 합니다. 오그리마의 지혜의 골짜기에 계신 그분께 이 메시지를 전해 주시겠습니까?",
    },
    [27163] = {
        ["T"] = "현상 수배: 푸른용혈족",
        ["O"] = "워블 할로우의 웬디 워블스미스를 위해 푸른용혈족 5마리, 푸른 비늘파멸자 5마리, 용족 마술사 5마리를 처치하십시오.",
        ["D"] =
        "모험가 여러분 주목: 워블 할로우 북쪽 멘나르 호수 근처에 푸른용혈족 무리가 살고 있습니다. 이들은 우리 작업에 위협이 됩니다. 이들의 수를 줄여주는 사람에게는 누구든 보상하겠습니다. \n\n경고: 이들은 강력한 적입니다.\n\n이 임무를 완수하고 워블 할로우에 있는 웬디 워블스미스에게 말씀하십시오.",
    },
    [27164] = {
        ["T"] = "현상 수배: 바다 거인",
        ["O"] = "바다 거인 5마리를 처치하고 아즈샤라 워블 할로우의 웬디 워블스미스와 대화하십시오.",
        ["D"] =
        "모험가 여러분 주목: 바다 거인이 아즈샤라의 외딴곳을 배회하고 있습니다. 이 무시무시한 생명체들의 발걸음은 워블 할로우에서 사용하는 정밀한 장비에 영향을 미치고 있습니다. 거인들을 제거하고 평화를 되찾아 주는 파티에게는 보상이 지급됩니다.\n\n경고: 이들은 강력한 적입니다.",
    },
    [27165] = {
        ["T"] = "불타는 칼날단 징표",
        ["O"] = "불타는 칼날단 단원들에게서 불타는 칼날단 징표 반지 10개를 모아 크로스로드의 쏜에게 돌아가십시오.",
        ["D"] =
        "불타는 칼날단에 대해 들어본 적 있소? 군단이 침공한 이래로 아제로스에 전염병처럼 퍼진 잔인한 악마 숭배 집단이지. 놈들이 불모의 땅을 침략했고, 이미 작은 마을 하나를 약탈했소.\n\n나의 최우선 순위는 이 땅의 안전이니, 나가서 그놈들을 몰아내시오! 놈들을 처치했다는 증거로 징표 반지를 몇 개 가져오시오. 정찰병의 보고에 따르면 불타는 칼날단이 여기서 꽤 북서쪽에 있는 산맥, 공포안개 봉우리에 진을 쳤다고 하오.",
    },
    [27166] = {
        ["T"] = "증오의 끝",
        ["O"] = "십자로에 있는 만크릭에게 켄타우로스 머리 10개를 가져오십시오.",
        ["D"] =
        "항상 불확실한 상태로 있는 것이 어떤 기분인지 아십니까? 나디아의 운명을 알지 못하는 기분을? 당신이 알지 못할 수도 있지만, 제가 확신하는 한 가지는... 저는 복수를 원한다는 겁니다. 저는 피를 원합니다. 켄타우로스는 죽어야 합니다!\n\n제가 직접 가고 싶지만, 탈출 과정에서 다리를 다쳤습니다. 저를 위해 $r, 가서 놈들의 머리를 가져오세요. 그러면 임무를 완수한 줄 알겠습니다.",
    },
    [27167] = {
        ["T"] = "외국 기술",
        ["O"] = "죽음의 폐광에 침투하여 지식 구조 재건기를 십자로의 트라우그에게 가져오십시오.",
        ["D"] =
        "우리의 기술은... 여기 불모의 땅에서는 제한적입니다. 저는 자동화된 방식으로 더 복잡한 도구와 무기를 만들 수 있는 능력을 원합니다. 저는 이런 지식이 없지만, 알고 있는 자들이 있습니다.\n\n죽음의 폐광에 대해 들어보셨습니까? 그곳은 데피아즈단의 거점으로, 동부 왕국의 서부 몰락지대에 위치해 있습니다. 그 안에는 형제단을 위해 장치를 만드는 악랄한 고블린 길니드가 있습니다.\n\n그가 원자재를 무기로 찍어낼 수 있는 새로운 장치를 발명했다는 소문이 있습니다! 호드가 더 강해질 수 있도록 그 장치를 제게 가져오십시오! 하지만 조심하십시오. 형제단은 자신들의 기계를 쉽게 내어주지 않을 테니, 친구들을 함께 데려가십시오.",
    },
    [27168] = {
        ["T"] = "전투 중 실종",
        ["O"] = "나디아에게 무슨 일이 일어났는지 알아내고 결과를 십자로에 있는 만크릭에게 보고하십시오.",
        ["D"] =
        "그들은 한밤중에 무리 지어 몰려왔습니다. 켄타우로스는 사악하고 끔찍한 생물입니다. 저는 마을에서 도망쳐 성소를 찾아 이곳에 왔습니다. 제 아내 나디아는 그렇게 운이 좋지 않았습니다.\n\n그들은 죽은 오아시스 근처 남쪽에 있는 그들의 진영으로 그녀를 데려갔습니다. 최악의 상황이 두렵지만, $N, 저는 알아야 합니다. 제발 그들의 텐트에서 단서를 찾을 수 있는지 확인해 보시고, 가능하면 그녀를 다시 데려와 주십시오. 가는 길을 막는 켄타우로스는 모두 학살하십시오.",
    },
    [27169] = {
        ["T"] = "잔해 수색",
        ["O"] = "만크릭의 마을에서 나디아의 흔적을 찾고 십자로에 있는 만크릭에게 돌아오십시오.",
        ["D"] =
        "그래서 그녀가 켄타우로스에게서 탈출했다고요! 왜 나디아가 이곳으로 오지 않았을까요? 아마 제가 어디에 있는지 몰랐을 겁니다. 그렇다면 우리가 그녀를 찾아야 합니다. 그녀는 분명 제가 있을 거라고 생각하고 우리 마을로 돌아갔을 것입니다.\n\n$N, 내 마을로 가서 그녀를 찾으십시오. 북쪽으로 길을 따라가다가 갈림길에서 우회전하십시오. 이 땅과 듀로타가 만나는 해안선을 따라 남쪽으로 가십시오. 그곳에서 우리 마을을 찾고, 부디 나디아를 찾으시길 바랍니다.",
    },
    [27170] = {
        ["T"] = "내 손을 떠난 일",
        ["O"] = "불모의 땅에서 신질을 추적하십시오.",
        ["D"] =
        "그녀를 찾기 위해 우리가 더 이상 할 수 있는 일은 없습니다, $n. 외부의 도움을 구해야 합니다. 당신이 심문한 포로들이 그녀가 탈출했다고 했으니, 저는 그녀가 아직 살아있다고 굳게 믿고 있습니다.\n\n이 지역 사람들에게 도움을 준 신질이라는 주술사의 이야기를 들은 적이 있습니다. 그는 이 마을에서 조금 북쪽, 갈림길 근처에 살고 있습니다. 가보십시오. 그와 대화하여 그가 나디아를 찾는 데 도움을 줄 수 있는지 알아보십시오.",
    },
    [27171] = {
        ["T"] = "보주 회수",
        ["O"] = "대마법사 코르가르를 처치하고 그의 보주를 불모의 땅에 있는 신질에게 가져가십시오.",
        ["D"] =
        "그래, 내가 도와주지, 하지만 나디아의 위치에 집중하기 위한 의식을 시작하려면 몇 가지 물건이 필요해. 그녀를 찾을 만큼 강력한 유일한 물건은 북부감시 요새에 있다네.\n\n그곳엔 대마법사 코르가르라는 이름의 강력한 마법사가 있지. 그의 힘의 원천인 그의 보주는 끊임없는 보호를 받고 있어. 우리가 나디아를 찾으려면 그 보주가 필요할 거야.\n\n북부감시 요새는 톱니항에서 정남쪽으로 가면 찾을 수 있어. 하지만 조심하는 게 좋을 거야, 경비병들이 낯선 이를 친절하게 대하지는 않거든.",
    },
    [27172] = {
        ["T"] = "보주 주입",
        ["O"] = "번개의 정수 5개를 코르가르의 보주에 흡수시키고 불모의 땅에 있는 신질에게 돌아가십시오.",
        ["D"] =
        "이게 우리가 찾던 구슬이군. 하지만 이제 보주를 손에 넣었으니 자연의 힘을 주입해야 해. 남쪽 멀리, 십자로를 지나면 코도와 비슷하게 생긴 천둥 도마뱀 무리가 살고 있지.\n\n우리는 그들의 정수를 이용해 이 보주에 주입해야 해... 가장 강력한 힘을 얻으려면 그들이 살아있는 동안에 해야 해. 그걸 마치면 의식을 끝낼 수 있도록 나에게 돌아오게.",
    },
    [27173] = {
        ["T"] = "보고",
        ["O"] = "십자로에 있는 만크릭에게 나디아의 위치에 대한 소식을 전하십시오.",
        ["D"] =
        "우리가 그녀를 찾았어! 푸른 오아시스 남서쪽에 가시멧돼지 마을이 있다는 걸 기억해. 그곳에서 그녀를 찾을 수 있을 거야.\n\n시간 낭비할 틈이 없네, 가서 만크릭에게 소식을 전해주게! 혹시 십자로에 도움이 필요한 사람이 있다면 나에게 보내주게나.",
    },
    [27174] = {
        ["T"] = "나디아 찾기",
        ["O"] = "불모의 땅에 있는 가시멧돼지 마을에서 나디아를 찾으십시오.",
        ["D"] =
        "그녀를 찾기 일보 직전입니다, $n. 신질 님이 말씀하신 지역은 저도 잘 압니다. 아가마고르라고 불리며 많은 가시멧돼지가 그곳에 살고 있죠.\n\n푸른 오아시스 남서쪽에서 찾을 수 있을 겁니다. 당신을 믿겠습니다. 제발, 제 사랑하는 나디아를 데려와 주십시오.",
    },
    [27175] = {
        ["T"] = "우리 열기",
        ["O"] = "고르탁의 열쇠를 수집하고 불모의 땅에 있는 나디아를 우리에서 풀어주십시오.",
        ["D"] =
        "당신이 이곳에 와주셔서 정말 기쁩니다! 저는 이곳에 갇혀... 길을 잃고... 여러 날을 기다렸습니다. 하지만 나갈 방법을 알 것 같아요!\n\n가끔 그들의 우두머리를 관찰했는데, 그들은 그를 고르탁이라고 부르더군요. 그는 항상 북서쪽의 가시멧돼지 마을에서 옵니다. 제 우리를 열 수 있는 열쇠를 그가 가지고 있을 거라고 확신해요! 하지만 조심하세요, 그는 다른 녀석들보다 훨씬 강해 보이니까요... 그를 상대하려면 친구들이 필요할지도 모릅니다.",
    },
    [27176] = {
        ["T"] = "좋은 소식",
        ["O"] = "십자로에 있는 만크릭에게 나디아의 탈출을 알리십시오.",
        ["D"] =
        "모든 도움에 감사드립니다, $N. 당신 덕분에 목숨을 건졌어요. 여기서부터 집으로 가는 길은 알지만, 당신 말로는 그곳이 파괴되었다고 하더군요. 새로운 집을 지을 수 있을 때까지 십자로에서 피난처를 찾아야 할 것 같습니다.\n\n먼저 가서 만크릭에게 일어난 모든 일을 전해주세요. 그는 내 생사를 몰라 불확실함 속에 죽어가고 있을 테니까요. 저도 바로 뒤따라가겠습니다!",
    },
    [27177] = {
        ["T"] = "작전: 북부감시 요새",
        ["O"] = "북부감시 요새에서 다양한 방어구가 든 상자를 훔쳐 십자로에 있는 톨크에게 가져가십시오.",
        ["D"] =
        "쉿! 당신, 그래 당신! 우리 앞에 있는 저 요새가 보이나요? 저 테라모어 경비병들은 저곳을 보급품 전초기지로 사용하고 있습니다. 며칠 동안 그들을 지켜봤는데, 십자로를 공격할 만큼 충분한 보급품을 갖추고 있는 것 같아 걱정입니다!\n\n당신이 저 안에 들어가서 그들의 방어구를 훔쳐 왔으면 합니다. 대장간 건물에서 찾을 수 있을 겁니다. 우리 병사들이 사용할 수 있도록 십자로에 있는 톨크에게 가져다주십시오.",
    },
    [27178] = {
        ["T"] = "계약 #1001: 심장부 사냥개 거름",
        ["O"] = "검은바위 첨탑에 있는 괴수의 방에서 심장부 사냥개 거름으로 상자를 채우십시오.",
        ["D"] =
        "팀을 구성할 의향이 있는 계약자들을 위한 일거리가 있습니다. 우리 모두 음식을 좋아하죠? 자, 농산물 부서에 도움이 되는 계약이 있습니다.\n\n계약 #1001: 검은바위 첨탑 내에서 심장부 사냥개 거름 확보\n\n수량: 1상자",
    },
    [27179] = {
        ["T"] = "계약 #1024: 검은무쇠 조각",
        ["O"] = "검은바위 나락 내의 저명한 드워프들로부터 검은무쇠 조각 4줌을 수집하십시오.",
        ["D"] =
        "팀을 구성할 의향이 있는 계약자들을 위한 일거리가 있습니다. 장난감 부서에 도움이 되는 계약입니다.\n\n계약 #1024: 검은바위 나락 내에서 검은무쇠 조각 확보\n\n수량: 4줌",
    },
    [27180] = {
        ["T"] = "계약 #1031: 괴사성 염료",
        ["O"] = "스트라솔름의 저주받은 자들의 교단 일원들로부터 괴사성 염료 4개를 수집하십시오.",
        ["D"] =
        "팀을 구성할 의향이 있는 계약자들을 위한 일거리가 있습니다. 선물 좋아하시나요? 싫어할 사람이 어딨겠어요!? 선물 포장 부서에서 온 계약입니다.\n\n계약 #1031: 스트라솔름 내에서 괴사성 염료 확보\n\n수량: 4병",
    },
    [27181] = {
        ["T"] = "계약 #1063: 오우거 사향",
