        ["D"] =
        "팀을 구성할 의향이 있는 계약자들을 위한 일거리가 있습니다. 향수, 코롱, 향초 부서에서 온 계약입니다.\n\n계약 #1063: 검은바위 첨탑 하층에서 오우거 사향 확보\n\n수량: 4파인트",
