        ["O"] = "스칼로맨스의 되살아난 피조물로부터 특대형 대퇴골을 수집하십시오.",
        ["D"] =
        "팀을 구성할 의향이 있는 계약자들을 위한 일거리가 있습니다. 음악 좋아하시나요? 싫어할 사람이 어딨겠어요!? 음악 부서에서 온 계약입니다.\n\n계약 #1088: 스칼로맨스 내에서 대퇴골 확보\n\n수량: 1개 (특대형)",
