        ["D"] =
        "굴뚝나무 목장조합은 가장 위험한 곳을 포함하여 아제로스 전역에서 사업을 합니다. 전투에 참전 용사를 기여하면 보급품 보관함을 받기로 일부 전장 진영과 계약도 맺었죠.\n\n알터랙 산맥의 보급품이 필요합니다. 알터랙 계곡에서 승리하면 원더볼트 기계에 사용되는 순수한 눈과 겨울서리풀이 들어 있는 알터랙 보관함을 얻을 수 있을 겁니다. 전투에 참여할 의향이 있으신가요?",
