        ["D"] =
        "고블린 무역 연합은 호드와 얼라이언스 간의 긴장에 대해 중립을 지키고 있지만, 여러분이 서로 싸울 때 가끔 얻을 수 있는 피투성이 징표에는 흥미가 동합니다. 이 피투성이 징표와 교환하여 희귀한 재료를 기꺼이 공급하려는 장부 외의 \"기업가\"들이 있거든요.\n\n내 가죽을 위험에 빠뜨리면서까지 그걸 구하고 싶진 않지만, 당신이 기꺼이 해준다면 깊은 인상을 받을 겁니다.",
