        ["D"] =
        "우리는 동부 역병지대에서 변화한 동식물을 어떻게 가장 잘 활용할 수 있을지 이제 막 탐구하기 시작했습니다. 그곳은 위험한 지역이라, 아제로스의 다른 어떤 곳보다 요원 사상자가 많이 발생했죠.\n\n은빛 여명회가 그곳에 세운 탑 중 하나를 통제하여 그곳을 더 안전한 장소로 만드는 데 도움을 주실 수 있나요? 그러면 내 요원들에게 필요할 때 피난처로 사용할 수 있다고 알릴 수 있을 겁니다.",
