        ["O"] = "길리짐의 섬 전투에서 승리하여 길리짐 보급품 보관함을 획득하십시오.",
        ["D"] =
        "굴뚝나무 목장조합은 가장 위험한 곳을 포함하여 아제로스 전역에서 사업을 합니다. 전투에 참전 용사를 기여하면 보급품 보관함을 받기로 일부 전장 진영과 계약도 맺었죠.\n\n길리짐의 섬 보급품이 필요합니다. 길리짐의 섬에서 승리하면 우리의 비밀 물약에 사용되는 야생덩굴과 바나나몽치가 들어 있는 길리짐 보급품 보관함을 얻을 수 있을 겁니다. 전투에 참여할 의향이 있으신가요?",
