        ["D"] =
        "굴뚝나무 목장조합은 가장 위험한 곳을 포함하여 아제로스 전역에서 사업을 합니다. 전투에 참전 용사를 기여하면 보급품 보관함을 받기로 일부 전장 진영과 계약도 맺었죠.\n\n잿빛 골짜기의 보급품이 필요합니다. 전쟁노래 협곡에서 승리하면 명절 장식에 사용되는 기름과 나가 비늘이 들어 있는 전쟁노래 보관함을 얻을 수 있을 겁니다. 전투에 참여할 의향이 있으신가요?",
