        ["D"] =
        "편안한 밤의 수면을 위해 얼마를 지불하시겠습니까? 대답하지 않으셔도 됩니다. 그 가치가 아주 크다는 건 알고 있으니까요. 바로 그래서 굴뚝나무 목장조합이 최고급 냉각 기술로 만든 실험용 베개를 개발 중인 겁니다.\n\n시제품을 위해 깃털이 더 필요한데, 구할 수 있는 곳은 단 한 곳뿐입니다. 바로 여명의 설원에 있는 올빼미죠. 그들의 깃털은 본래 차가워서 검은바위 산 옆에 잠자리를 펴더라도 편안하게 잘 수 있게 해줍니다. 이 일을 맡아주시겠습니까?",
    },
    [27190] = {
        ["T"] = "공포의 원소",
