        ["D"] =
        "우리 커피 드셔보신 적 있나요? 그 깊은 이탄 향은 자연 서식지에서 추출한 정령의 장인의 물로 목욕시킨 콩을 특별 로스팅해서 얻은 결과입니다.\n\n하나의 물 핵은 우리 공정에서 오랫동안 지속되지만, 페랄라스의 특별한 출처에서 다시 보충할 때가 왔습니다. 이 일을 맡아주시겠습니까?",
