        ["D"] =
        "우리 고기 과일 케이크나 고기 파이 드셔보셨나요? 고기는 구하기 쉽지만, 양념... 바로 거기서 맛이 나오는 겁니다!\n\n우리 파이에는 다양한 버섯을 사용하지만, 꼭 시도해 보고 싶은 희귀한 종류가 있습니다. 닉티아 콜라브루스라고 불리는데, 동부 역병지대의 곰팡이 계곡에서만 자라죠. 저를 위해 그 버섯을 좀 채집해 주실 수 있나요?",
