        ["D"] =
        "저주받은 땅의 어둠의 문을 아십니까? 대부분의 사람들은 불타는 군단과의 전쟁 때문에 그곳을 피하지만, 굴뚝나무 목장조합은 악마의 침공 따위가 사업에 방해되도록 내버려 두지 않죠!\n\n우리에게는 문에서 뿜어져 나오는 에너지를 정기적으로 빼내는 요원이 있는데, 그 지역을 순찰하는 지옥수호병 파수병들 때문에 문제가 좀 생겼습니다. 요원들이 임무를 계속할 수 있도록 그들의 수를 좀 줄여주시면 감사하겠습니다!",
