        ["D"] =
        "굴뚝나무 목장조합이 만든 상품에는 그들을 특별하게 만드는 아주 작은 *무언가*가 있다는 걸 눈치채셨길 바랍니다. 속임수가 아닙니다... 우리가 만드는 모든 것에는 별빛이 아주 조금 주입되어 있죠.\n\n별빛 공급량이 바닥나고 있지만, 여명의 설원에 있는 올빼미야수처럼 별빛과 특히 조화를 이루는 생물로부터 별빛을 뽑아낼 수 있는 새로운 도구를 최근에 얻었습니다. 약화시킨 다음 빼내기만 하면 됩니다, 아주 쉽죠. 이 일에 관심 있으신가요?",
