    [27194] = {
        ["T"] = "공포의 거미굴 시험",
        ["O"] = "동부 역병지대의 공포의 거미굴에서 굴뚝나무 목장조합 투하함을 회수하십시오.",
        ["D"] =
        "굴뚝나무 목장조합 요원들이 동부 역병지대에서 다양한 거미줄을 수집하여 공포의 거미굴에 위치한 안전한 보관함에 투하하도록 일정을 잡았습니다. 하지만 문제가 생겼어요... 벤처 투자회사가 우리 요원의 뒤를 밟았고, 그들이 투하함의 위치를 알고 있다고 생각합니다. 무슨 수를 써서라도 그 화물을 확보해 주셔야 합니다!",
