    [27195] = {
        ["T"] = "이빨로 곧장",
        ["O"] = "헥클팡 하이에나 이빨 10개를 모아 타우라조 야영지에 있는 칼리야 스톰슈에게 가져가십시오.",
        ["D"] =
        "반갑습니다, $c. 이제 아제로스가 치명적인 곳이라는 건 아시겠죠. 두려움 없이 모험을 떠나려면 튼튼하고 강한 무기가 필요합니다.\n\n부족의 무기를 만들기 위해 근처의 헥클팡 하이에나 이빨이 필요합니다. 저 스스로 그들과 싸우러 갈 만큼 강하지는 않지만, 당신과 거래를 하고 싶습니다. 그들의 이빨을 가져다주시면 당신을 위한 무기도 만들어 드리겠습니다.",
