    [27197] = {
        ["T"] = "상인의 딸",
        ["O"] = "보물 상자를 톱니항에 있는 비참한 자 레닉스에게 가져가십시오.",
        ["D"] =
        "이봐 친구, 돈 좀 벌고 싶나? 요즘 경기가 어렵지만, 이 마을 해안가 바다 밑바닥에 '상인의 딸'이라는 배가 가라앉아 있다는 소문을 들었지.\n\n그 잔해 안에는 보물이 있어. 그 배의 선원들이 그 안에 뭘 가지고 있었는지 누가 알겠어! 난 모르지만, 요전 밤에 술 취한 선원에게서 그 보물 상자의 열쇠를 땄다는 건 알지. 그 보물을 가져오면 내 몫을 조금 떼어주겠네.",
