    [27198] = {
        ["T"] = "실종된 전승지기들",
        ["O"] = "남부 황금길에서 실종된 캐러밴의 흔적을 찾으십시오.",
        ["D"] =
        "반갑네, 모험가여. 혹시 남부 황금길을 여행할 예정인가?\n\n이곳에 도착할 캐러밴을 기다리고 있는데, 예정보다 며칠이나 지연되었네. 그들에게 무슨 일이 생겼는지 걱정이군.\n\n남쪽으로 모험을 떠나게 된다면, 코도가 끄는 마차를 타고 여행하는 타우렌과 트롤을 유심히 살펴봐 주게.",
    },
    [27199] = {
        ["T"] = "실종된 전승지기들",
        ["O"] = "타우라조 야영지에 있는 현자 엘크후프에게 돌아가 나쁜 소식을 전하십시오.",
        ["D"] =
        "잔해 주변을 둘러봅니다. 뼈는 살점이 갓 발라져 깨끗합니다. 상자들은 부서져 열려 있고 내용물은 약탈당했습니다.\n\n부러진 가시멧돼지 엄니가 흙 속에 떨어져 있습니다. 가시멧돼지가 만든 것으로 보이는 화살과 버려진 단검도 있습니다. 이 나쁜 소식을 전할 때 현자 엘크후프에게 가져갈 증거로 단검을 줍습니다.",
    },
    [27200] = {
        ["T"] = "실종된 전승지기들",
        ["O"] = "검은가시 능선에 있는 가시멧돼지 야영지에서 타우렌 전승 두루마리 8개를 회수하십시오.",
        ["D"] =
        "불쌍한 미나와 셀림. 그들은 전사가 아니라 평화로운 연구자들이었어. 가시멧돼지들과는 아무런 다툼도 없었는데... 이젠 내가 다툼을 벌일 차례군!\n\n그 마차에는 높새바람 봉우리에서 온 타우렌 전승 두루마리 상자들이 실려 있었지. 가시멧돼지들이 그것들을 손에 넣었을 거라고 짐작할 수밖에. 그들이 캐러밴을 공격했던 검은가시 능선의 야영지로 내려가서, 그 두루마리들을 되찾아 주게. 방해하는 가시멧돼지는 모두 처치해. 그것이 쓰러진 형제들을 위한 내 복수라네.",
    },
    [27201] = {
        ["T"] = "삼인방 두루마리",
        ["O"] = "가시덩굴 우리에 침투하여 가시멧돼지들로부터 삼인방 두루마리를 회수하십시오.",
        ["D"] =
        "삼인방 두루마리는 썬더 블러프, 해바위 야영지, 모자케 야영지의 건립에 대해 묘사한 세 개의 두루마리 세트라네. 구전되던 역사가 처음으로 글로 기록된 것이지. 우린 그것들을 반드시 회수해야 해.\n\n이 두루마리들이 가시덩굴 우리의 가시멧돼지 요새로 전리품으로 보내졌다는 끔찍한 의심이 드는군. 그곳으로 들어가서 그것들을 되찾아 주게!",
    },
    [27202] = {
        ["T"] = "흑요석 유물",
        ["O"] = "흑요석 유물을 불모의 땅에 있는 갠 스톤스파이어에게 가져가십시오.",
        ["D"] =
        "발굴조사단장의 소지품 중에는 바엘 모단 발굴 현장의 폐허 양식과 어울리지 않는 기이한 유물이 있습니다. 주변의 빛을 빨아들이는 듯한 검은 물질로 만들어졌습니다.\n\n아마도 갠 스톤스파이어라면 이 불길한 발견물을 어떻게 해야 할지 알지도 모릅니다.",
    },
    [27203] = {
        ["T"] = "흑요석 유물",
        ["O"] = "흑요석 유물을 썬더 블러프에 있는 포위 미스트러너에게 가져가십시오.",
        ["D"] =
        "드워프들이 이런 것에 관심이 있었다면, 심히 우려스럽군. 이것이 무기와 조금이라도 관련이 있다면, 우리 동맹들에게 반드시 알려야 해.\n\n이 유물을 썬더 블러프의 정기의 봉우리에 있는 포위 미스트러너에게 가져가게. 그녀는 오래된 물건에 관심이 많으니 도움을 줄 수 있을 거네.",
    },
    [27204] = {
        ["T"] = "현상 수배: 딥스킨",
        ["O"] = "딥스킨을 처치하고 십자로에 있는 톨크에게 그의 이빨을 가져가십시오.",
        ["D"] =
        "수많은 모험가들이 유독 공격적인 이 악어의 희생양이 되었습니다. 녀석은 불모의 땅과 듀로타가 만나는 강을 배회합니다.\n\n그가 죽었다는 증거로 십자로에 있는 톨크에게 녀석의 송곳니 중 하나를 가져가십시오.",
    },
    [27205] = {
        ["T"] = "내 동생 이사베타",
        ["O"] = "아우버다인 바로 남쪽에 있는 어둠해안 연안 섬의 집에 있는 이사베타 휠랜드와 대화하십시오.",
        ["D"] =
        "이 마을에서 멀록 문제를 해결해 줄 사람을 찾느라 하도 오랫동안 머물렀더니, 내 여동생 이사베타는 내가 어디에 있는지 궁금해할 겁니다.\n\n당신이 나가서 멀록들을 처리하는 동안, 집에 들러 동생에게 내가 곧 돌아갈 거라고 전해주시겠어요?\n\n우린 마을 남쪽의 작은 섬에 집을 지었거든요.",
    },
    [27206] = {
        ["T"] = "내 동생 이사베타",
        ["O"] = "이사베타 휠랜드 집의 화재를 조사하십시오.",
        ["D"] =
        "한 여자의 시신이 이곳에 누워 있습니다. 이사베타 휠랜드가 틀림없습니다. 비록 머리카락이 그을리고 손에 화상을 입었지만, 사망 원인은 가슴에 찔린 여러 개의 흉기 자국인 것 같습니다.\n\n주머니가 뒤집혀 있는 걸로 보아 시신을 뒤진 흔적이 있습니다.\n\n근처의 집은 아직 최근에 난 불로 연기가 피어오르고 있습니다. 빌 휠랜드에게 무슨 일이 있었는지 알리기 전에 사건 현장을 조사해 보는 것이 좋지 않을까요?",
    },
    [27207] = {
        ["T"] = "내 동생 이사베타",
        ["O"] = "서부 몰락지대로 이동하여 에반젤린 휠랜드에게 화재와 이사베타 휠랜드의 죽음에 대해 알리십시오.",
        ["D"] =
        "이... 이건 데피아즈단 복면의 조각입니다. 내 목숨을 걸 수도 있어요. 이건 데피아즈단의 소행이 확실합니다. 스톰윈드 땅의 일반인들을 공포에 떨게 하는 폭력배와 악당들의 무리죠. 그들이 우릴 미행했어요... 그들은 메시지를 전하고 싶었던 겁니다.\n\n나도 나만의 메시지를 보내야겠어요. 기꺼이 도와주시겠다면, 이 메시지를 우리 다른 여동생 에반젤린에게 전해주세요. 그녀는 서부 몰락지대 민병대의 일원입니다. 그녀는 데피아즈단이 다른 사람들과 공유하고 싶어하지 않는 정보를 가지고 있어요. 그들이 이사베타를 쫓아 어둠해안까지 왔다면, 에반젤린의 목숨도 위험합니다.\n\n먼 길이지만, $C, 여기서 배를 타고 메네실 항구로 가는 것부터 시작해야 합니다.",
    },
    [27208] = {
        ["T"] = "내 동생 이사베타",
        ["O"] = "황금해안 채석장의 오마르 도른을 처치하고 서부 몰락지대에 있는 에반젤린 휠랜드에게 데피아즈단 열쇠를 가져가십시오.",
        ["D"] =
        "데피아즈단이 이사베타를 쫓아 어둠해안까지 가서, 그녀의 집을 불태우고 그녀를 죽였다고요? 오, 맙소사!\n\n<에반젤린은 멍한 표정을 짓더니, 결의에 찬 표정이 얼굴에 스쳐 지나갑니다.>\n\n미안해요, $C. 당신은 당신이 알 수 있는 것보다 훨씬 더 큰 상황 한가운데에 발을 들여놓았어요. 그리고, 도움이 필요해요. 하지만 내가 아직 당신을 믿어도 될지 모르겠네요.\n\n돕고 싶으시다면, 임무를 하나 맡아 주시겠어요? 이 길을 따라 서쪽으로 더 가면 있는 황금해안 채석장에 자리 잡은 데피아즈단 부관이 있어요. 그의 이름은 오마르 도른입니다. 녀석을 처치하고 그가 가진 열쇠를 가져다주세요.",
    },
    [27209] = {
        ["T"] = "내 동생 이사베타",
        ["O"] =
        "데피아즈단 열쇠를 사용하여 달빛시내 마을에 숨겨진 데피아즈단 금고를 여십시오. 그 안에서 찾은 것을 서부 몰락지대에 있는 에반젤린 휠랜드에게 가져가십시오.",
        ["D"] =
        "달빛시내 마을은 한때 번창했던 곳이었죠. 지금은 도둑들의 소굴이자, 데피아즈단 동조자들의 근거지가 되었습니다.\n\n달빛시내 마을 어딘가에 특정 문서가 보관되어 있는 금고가 있어요. 오마르 도른에게서 찾은 이 열쇠로 그걸 열 수 있을 겁니다. 그 안에서 문서가 나오면 제게 가져다주세요. 하지만 그 안에 있는 다른 것들은 당신이 가져도 좋습니다.",
    },
    [27210] = {
        ["T"] = "숨겨진 기록",
        ["O"] = "스톰윈드의 대성당 광장에 있는 바로스 알렉스턴에게 에반젤린의 쪽지를 가져가십시오.",
        ["D"] =
        "이거 보이시나요, $N? 이건 데피아즈단이 필사적으로 숨기려 하는 비밀이에요. 내 동생과 관련된 비밀이죠.\n\n이사베타는 데피아즈단에 동조했던 수많은 사람들 중 하나였어요. 결국, 그들은 스톰윈드 귀족들에게 타당한 불만을 가지고 있으니까요. 하지만 데피아즈단이 우리 뒷마당인 이 서부 몰락지대에서 평범한 사람들을 공포에 떨게 하기 시작했을 때, 그녀는 조직을 떠났죠.\n\n그녀가 조직을 떠난 후에야 자신이 임신했다는 사실을 알게 되었어요.\n\n이것은 그녀 딸의 유일한 출생 증명서 사본입니다. 안전하게 보관하기 위해 스톰윈드에 있는 제 옛 친구에게 가져다주셨으면 해요. 그의 이름은 바로스 알렉스턴이고 도시 건축가 직책을 맡고 있어요. 대성당 근처에서 그를 찾을 수 있을 거예요.",
    },
    [27211] = {
        ["T"] = "숨겨진 기록",
        ["O"] = "스톰윈드에 있는 왕실조사원 바스릴로에게 출생 증명서를 가져가십시오.",
        ["D"] =
        "<바로스 알렉스턴이 쪽지와 증명서를 빠르게 훑어봅니다.>\n\n그러니까 내 옛 친구 에드윈 밴클리프가 이사베타 휠랜드와의 사이에서 딸을 얻었단 말이군. 스톰윈드 귀족들이 이 사실을 알게 되면 그녀를 붙잡아 인질로 삼으려 할 거요. 하지만 이사베타 역시 에드윈이 딸을 돌보는 것을 원치 않았음이 분명하오. 에반젤린은 양측 사이의 아슬아슬한 줄타기를 도와달라고 내게 부탁하는구려.\n\n다음에 무엇을 해야 할지는 모르겠지만, 일단 공식 등록관에게 이 기록을 제출하는 것이 좋겠소. 그는 이 건물 위층에 있소. 당신이 친절하게도 그에게 이 기록을 가져다준다면, 당신이 돌아올 때쯤에는 내게 어떤 계획이 생길지도 모르겠소.",
    },
    [27212] = {
        ["T"] = "밴클리프 숙모",
        ["O"] = "서부 몰락지대에 있는 민병대원 에반젤린에게 돌아가십시오.",
        ["D"] =
        "에반젤린의 쪽지에 따르면 그녀는 바네사가 지금 어디에 있는지 모른다고 했소. 돌아가서 바네사를 찾기 위해 내가 할 수 있는 모든 지원을 하겠다고 그녀에게 전해주시오.\n\n출생 증명서에 증인으로 등재된 사람은 에드나 몰슨 -- 밴클리프의 이모요. 수년 동안 그녀를 보지 못했소. 그들은 한때 가까운 사이였지. 어쩌면 그녀가 더 많은 정보를 가지고 있을지도 모르오 -- 아직 살아있다면 말이오.",
    },
    [27213] = {
        ["T"] = "밴클리프 숙모",
        ["O"] = "메마른 논밭으로 여행하여 에드나 몰슨의 행방에 대한 단서를 찾으십시오.",
        ["D"] =
        "에드나 몰슨을 찾아보자는 바로스의 생각은 좋지만, 그가 말했듯이 나도 몇 년 동안 그녀를 보지 못했어요.\n\n남편이 죽었을 때, 그녀는 그늘숲과 맞닿아 있는 강가 가장자리의 작은 농장으로 이사했죠. 데피아즈단이 들어오기 전부터 농장은 번창하지 못했고, 그녀는 그곳을 떠났어요. 지금은 메마른 논밭으로 알려져 있죠.\n\n가서 둘러볼 가치는 있어요. 어쩌면 그녀가 어디로 갔는지에 대한 단서가 있을지도 모르죠. 찾은 것이 있으면 알려주세요.",
    },
    [27214] = {
        ["T"] = "밴클리프 숙모",
        ["O"] = "서부 몰락지대에 있는 민병대원 에반젤린에게 돌아가십시오.",
        ["D"] =
        "\"샤이어\"는 스톰윈드 왕국의 여러 다른 마을을 지칭할 수 있습니다. 희미한 단서이긴 하지만, 폐허가 된 농장에 남은 유일한 실마리인 것 같습니다.\n\n에반젤린 휠랜드가 이에 대해 알고 싶어 할 것입니다.",
    },
    [27215] = {
        ["T"] = "밴클리프 숙모",
        ["O"] =
        "골드샤이어, 레이크샤이어, 다크샤이어에 있는 여관들을 조사하여 에드나 몰슨의 행방에 대한 단서를 찾을 수 있는지 확인하십시오.",
        ["D"] =
        "\"샤이어\"라는 단어요? 그게 다예요? 뭐, 그것도 단서라고 할 수 있겠죠.\n\n튼튼한 걷기용 부츠를 가지고 계시길 바라요, $N. 인근 마을인 골드샤이어, 레이크샤이어, 다크샤이어로 나가서 마을에서 에드나 몰슨을 본 사람이 있는지 알아봐야 할 겁니다.",
    },
    [27216] = {
        ["T"] = "밴클리프 숙모",
        ["O"] = "스톰윈드의 대성당 광장에 있는 왕실조사원 바스릴로와 대화하십시오.",
        ["D"] =
        "나는 2년 전에 에드나 몰슨을 처음 만났어. 그녀는 그늘숲에 부동산을 좀 샀지만, 이사 온 적은 없었고 그 후로 농장은 황폐해졌지.\n\n내 생각엔 그녀가 1년도 더 전에 스톰윈드로 돌아간 것 같아. 손녀와 관련된 긴급한 소환을 받았거든 -- 가족 분쟁과 관련된 일이었지, 불쌍한 사람.\n\n하지만 스톰윈드에 가족이 있는 것 같아. 그곳 등록관이라면 알지도 모르지.",
    },
    [27217] = {
        ["T"] = "밴클리프 숙모",
        ["O"] = "스톰윈드에서 스티븐 몰슨을 찾으십시오.",
        ["D"] =
        "도시 기록에서 에드나 몰슨을 찾으신다고요? 흠, 그 이름은 낯설군요. 하지만 스티븐 몰슨은 마을에 있습니다. 적어도, 가끔은 마을에 있죠. 그는 약간... 떠돌이 일꾼 같은 사람이라. 지금 어디 있는지 확실치 않네요.\n\n당신이 스티븐을 찾는 동안 제가 기록을 더 자세히 살펴보겠습니다. 나중에 다시 오시면 에드나에 대해 찾은 것이 있는지 알려드리죠.",
    },
    [27218] = {
        ["T"] = "밴클리프 숙모",
        ["O"] = "그늘숲의 까마귀 언덕에 있는 여관에서 까마귀 암흑 에일 한 병을 구하십시오.",
        ["D"] =
        "에드나? 그래, 에드나 알아. 그녀는 내... *딸꾹*... 누나야.\n\n당신 데피아즈단 소속인가?\n\n<스티븐이 트림을 합니다.>\n\n아니, 그런 모습은 아니군. 그녀가 어디 있는지 알고 싶나 보지? 뭐, 먼저 내게 작은 부탁을 들어주면 말해주지.\n\n서부 몰락지대에서 그늘숲으로 넘어가는 다리 바로 건너편, 까마귀 언덕에 북적이던 여관이 하나 있었어. 아주 훌륭한 에일을 만들었지. 더 마시고 싶은데. 그곳 잔해로 가서 나를 위해 한 병만 구해다 줄 텐가? 그럼 당신이 알고 싶은 걸 말해주지.",
    },
    [27219] = {
        ["T"] = "밴클리프 숙모",
        ["O"] = "그늘숲의 애들 농장에서 에드나 몰슨을 찾으십시오.",
        ["D"] =
        "에드나는 그늘숲에 있는 땅, 오래된 애들 농장을 샀어... *딸꾹*. 그녀는 비통한 조카 에드윈에게 그곳을 쓰게 해줬지. 그녀는 에드윈이 자신의 것이라 부를 수 있는 장소를 가지게 되면, 그가 걷고 있던 길에서 벗어나기를 바랐어.\n\n<스티븐이 술에서 깨어난 듯 진지해집니다.>\n\n소용없었지.\n\n몇 주 전에 에드윈이 에드나에게 농장에서 만나자는 메시지를 보냈어. 그 후로 그녀를 보지 못했네. 가지 말라고 했는데. 아마 죽었을 거야. 당신도 데피아즈단 일에 코를 들이밀다간 똑같은 신세가 될 걸.",
    },
    [27220] = {
        ["T"] = "밴클리프 숙모",
        ["O"] = "패트릭 페인을 처치하고 사슬 열쇠를 그늘숲의 애들 농장에 있는 에드나 몰슨에게 가져가십시오.",
        ["D"] =
        "바네사에게 무슨 일이 있었는지 말씀드리겠지만, 먼저 제가 이 사슬에서 벗어날 수 있게 도와주세요.\n\n애들 농장에 있는 데피아즈단의 우두머리는 패트릭 페인이에요. 상상해 보세요 -- 그가 어렸을 때 그와 친구들에게 비스킷을 구워주곤 했는데, 그는 제 머리를 때리는 걸 두 번 생각하지 않더군요.\n\n그는 이곳의 다른 데피아즈단 일원들만큼이나 은밀하지만, 그를 찾을 수만 있다면 저를 결박하고 있는 열쇠를 가진 건 바로 그 사람입니다.",
    },
    [27221] = {
        ["T"] = "밴클리프 숙모",
        ["O"] = "서부 몰락지대에 있는 민병대원 에반젤린에게 돌아가십시오.",
        ["D"] =
        "몇 달 전, 에드윈의 폭력배들이 이사베타를 위협하기 시작했어요. 그는 이전에 딸에게 별로 관심이 없었지만 갑자기 \"유산\"에 대해 떠들어댔죠.\n\n이사베타는 바네사를 저에게 맡기고 칼림도어로 떠났어요. 저는 계속 이동했고요. 우리는 메네실 항구에서 테라모어로 가는 길이었는데, 불행이 닥쳤어요. 무슨 이유에서인지, 에드윈의 부하들 중 일부가 우연히 여관에서 우리를 보았어요. 왜 그들이 거기 있었는지 모르겠지만, 그들은 나에게서 바네사를 앗아갔어요. 바네사를 되찾을 수 있을까 희망을 품고 애들 농장에 왔죠.\n\n<에드나가 고개를 숙입니다.>\n\n바네사를 지키지 못했어요. 그녀의 아버지가 그녀를 잘 대해주기를 기도할 수밖에요. 하지만 이제 우리는 여길 떠나야 해요. 저는 다른 길로 가겠습니다. 행운을 빌어요, $C, 그리고 감사합니다.",
    },
    [27222] = {
        ["T"] = "잃어버렸지만 잊혀지지 않은",
        ["O"] = "스톰윈드의 대성당 광장에 있는 바로스 알렉스턴과 대화하십시오.",
        ["D"] =
        "당신이 에드나를 추적하는 동안, 에드윈이 몇몇 용감한 모험가들에게 패배했다는 소문이 퍼졌소. 혹시 그것에 대해 아는 게 있소...?\n\n바네사는 그와 함께 있지 않았소. 데피아즈단 잔당이 바네사를 어디에 붙잡아두고 있을지 알 방법이 없구려. 새로운 정보가 나타나길 기다리는 것 외에 다른 방법이 없소.\n\n마지막으로 부탁하고 싶은 건, 스톰윈드로 돌아가 바로스 알렉스턴에게 지금까지 있었던 모든 일을 전해달라는 것이오.",
    },
    [27223] = {
        ["T"] = "개인 소지품",
        ["O"] = "렘트래블의 발굴현장 주변에서 고고학자 에버릿의 개인 소지품을 수집하십시오.",
        ["D"] =
        "있잖아 $C, 저 골렘들 때문에 지금 당장 구덩이로 다시 돌아가는 게 좀 겁이나. 저 짐승들을 피해서 여기 위쪽에 새 텐트를 쳐야겠어.\n\n하지만 그러려면 내가 발굴지에 두고 온 소중한 소지품 몇 개가 필요해. 어차피 저 아래로 내려갈 거면, 내 물건들을 좀 주워다 줄 수 있겠나?",
    },
    [27224] = {
        ["T"] = "날뛰는 골렘",
        ["O"] = "렘트래블의 발굴현장에서 고고학자 에버릿을 위해 부서진 골렘이나 바위 거대괴수 6마리를 처치하십시오.",
        ["D"] =
        "렘트래블의 발굴현장에 온 걸 환영하네, $glad:lass;. 자네가 와서 다행이야. 이 발굴현장에 큰 문제가 생겼거든.\n\n발굴조사단장 렘트래블은 연구에 너무 집중한 나머지 우리 주변의 위험에는 눈을 감고 있지 뭔가. 그 위험 중 하나는 우리가 파기 시작한 이후로 깨어난 골렘들이야. 난 일개 고고학자에 불과하지만 자네는 투사 같아 보이는데. 녀석들의 수를 줄여서 우리를 좀 도와주겠나?",
    },
    [27225] = {
        ["T"] = "에르소타 돌",
        ["O"] = "이 기이한 돌을 아이언포지의 탐험가의 전당으로 가져가십시오.",
        ["D"] =
        "이 상자 안에는 예전에 한 번도 본 적 없는 기이한 문양으로 덮인 서판이 있습니다. 이 돌은 고고학자에게 가치가 있을 것으로 짐작됩니다. 아이언포지의 탐험가 연맹에서 이 물건에 관심을 가질지도 모릅니다. 어쩌면 이 배의 목적지가 바로 그곳이었을지도 모릅니다.\n\n스톰윈드의 드워프 지구에서 깊은굴 지하철을 타면 아이언포지에 도착할 수 있습니다.",
    },
    [27226] = {
        ["T"] = "에르소타 돌",
        ["O"] =
        "어둠해안의 아우버다인에 있는 고고학자 호올리에게 에르소타 돌을 가져가십시오.\n\n어둠해안으로 가려면, 모단 호수와 저습지를 거쳐 테라모어 항구로 가야 합니다.",
        ["D"] =
        "이 돌은 오래전 아제로스를 지배했던 무시무시한 존재인 고대 신 연구에 있어 매우 중요한 유물입니다. 아우버다인에 있는 우리 연구자 중 한 명에게 이 조각이 정말 필요할 텐데, 그곳은 아주 멀어요. 칼림도어에 있거든요.\n\n그곳으로 여행하는 건 위험한 여정이겠지만, $N, 기꺼이 맡아주신다면 넉넉히 보상해 드리죠.\n\n길을 따라 동쪽으로 모단 호수까지 간 다음, 북쪽으로 저습지까지 가야 합니다. 메네실까지 그 길을 계속 따라가시고, 뒤를 조심하세요. 먼 길이 될 겁니다.",
    },
    [27227] = {
        ["T"] = "스토레타 돌",
        ["O"] = "마시스트라 폐허에 있는 나가로부터 스토레타 파편 10개를 수집하십시오.",
        ["D"] =
        "이 돌이 이 지역에서 발견되는 다른 오래된 서판들을 해독하는 핵심이라고 확신해요. 불행히도 폐허에 있는 적대적인 나가들 때문에 그 서판들을 수집하는 데 진전이 없었어요. 나가들이 내가 찾고 있는 서판 중 하나를 조각내버렸거든요!\n\n당신은 지금까지 유능함을 증명해 보였죠. 계속해서 제 연구를 도와주고 싶다면 북쪽의 마시스트라 폐허로 가서 현재 그 지역에 들끓는 나가들에게서 서판 파편을 수집해 주세요. 어쩌면 제가 다시 조립할 수 있을지도 몰라요.",
    },
    [27228] = {
        ["T"] = "트로에스타 돌",
        ["O"] = "검은심연 나락의 황혼의 군주 켈리스로부터 트로에스타 돌 서판을 수집하십시오.",
        ["D"] =
        "내 연구의 핵심이 되는 서판이 하나 더 있지만, 그것을 얻는 것은 당신이 지금까지 한 그 어떤 일보다 훨씬 더 위험할 거예요, $C.\n\n해안을 따라 남쪽으로 가면 검은심연 나락이라고 알려진 사원이 있어요. 이 사원 내부에 에르소타 돌의 자매 서판이 있다는 소문이 있죠. 이 트로에스타 돌은 고대 신의 고대 문자를 번역하기 위해 마지막으로 필요한 조각이에요.\n\n불행히도 사원은 적대적인 나가와 정체불명의 파멸의 교단으로 가득 차 있어요. 혹시라도 이 사원을 약탈하는 데 관심이 있는 무리를 찾게 된다면, 돌을 찾아 제게 가져다주시길 부탁드려요.",
    },
    [27229] = {
        ["T"] = "기이한 유물",
        ["O"] = "다르나서스에 있는 수석고고학자 그레이위스커에게 기이한 유물을 가져가십시오.",
        ["D"] =
        "이 유물들을 보게나, 젊은이. 내가 보는 것이 자네에게도 보이나?\n\n그중 하나가 다르다네. 필멸자의 손에는 존재하는 것처럼 느껴지지만 내 눈에는... 일렁이는군. 이것은... 이 시대의 것이 아니야. $R에게 달리 어떻게 설명해야 할지 모르겠군.\n\n이 기이한 유물의 존재는 황혼의 망치단이 그들의 오래전 죽은 신의 무덤인 이곳에서 무엇을 하고 있는지 설명해 줄 수 있을 거야. 다르나서스에는 고대 신과 그들의 적인 티탄과 관련된 고대 유물을 연구하러 온 드워프가 있네. 이것을 그에게 가져가게. 그의 연구를 돕고 황혼의 망치단의 계획을 밝혀내는 데 도움이 되도록 말이네.",
    },
    [27230] = {
        ["T"] = "위기에 처한 노움",
        ["O"] = "불타는 칼날단 전령을 추적하여 그의 편지를 잊혀진 땅의 디비 스퀴글코드에게 가져가십시오.",
        ["D"] =
        "보잘것없어 보일지 몰라도, 이 마을은 내가 밑바닥부터 세웠습니다! 내 시민들을 돌보는 건 내 의무이고, 지금 당신의 도움이 필요합니다!\n\n내 기술자 중 한 명인 윙클 스크류버킷이 보급품을 구하러 나갔다가 그 이후로 보이지 않아요. 불타는 칼날단이 그를 붙잡았을까 봐 걱정입니다.\n\n내 정보에 따르면 그들의 전령 중 한 명이 천둥도끼 요새의 족장에게 편지를 전달할 예정이라고 합니다. 그 편지에 윙클이 어디 있는지에 대한 정보가 있을지도 모릅니다. 전령은 아마 요새 근처에 있을 테니, 빨리 가서 그 편지를 가져다주세요!",
    },
    [27231] = {
        ["T"] = "위기에 처한 노움",
        ["O"] = "스퀴글코드 전초기지의 에코크 니프티패치와 대화하십시오.",
        ["D"] =
        "불타는 칼날단이 윙클을 잡아간 이상, 그를 되찾으려면 특별한 도구가 필요할 겁니다! 내 수석 기술자인 에코크 니프티패치가 우리를 도울 수 있는 뭔가를 연결해 줄 수 있을 겁니다. 바로 내 뒤에 있는 건물에서 그를 찾을 수 있습니다.",
    },
    [27232] = {
        ["T"] = "위기에 처한 노움",
        ["O"] =
        "살데리스 해안의 잔해에서 무아지경 강화 고글을 회수하여 스퀴글코드 전초기지의 에코크 니프티패치에게 돌아가십시오.",
        ["D"] =
        "불타는 칼날단이 윙클의 위치를 불게 할 방법이 있을지도 모릅니다! 유일한 문제는... 우리에게 적절한 도구가 없다는 겁니다. 몇 년 전, 수많은 기술자들을 태운 배가 이 북서쪽에 있는 살데리스 해안 연안에 정박했습니다. 나가가 공격했고 배는 침몰했죠.\n\n선원들이 가지고 있던 도구 중 일부가 꽤 진보된 것이었다는 소문을 들었습니다. 적에게 최면을 거는 고글도 있다더군요! 잔해에서 그 고글을 회수하면, 그걸로 윙클을 찾을 수 있을지도 모릅니다.",
    },
    [27233] = {
        ["T"] = "위기에 처한 노움",
        ["O"] = "무아지경 강화기에 암흑의 정수 5개를 주입하고 스퀴글코드 전초기지의 에코크 니프티패치에게 돌아가십시오.",
        ["D"] =
        "좋은 소식은 고글이 있다는 것이고, 나쁜 소식은 충전되지 않았다는 겁니다! 몇 년 동안 바닷속에 있으면 배터리가 정말 닳아버리거든요. 다행히 이 고글들을 재충전할 수 있는 곳을 알고 있습니다.\n\n북동쪽에 있는 살게론으로 가져가세요. 그곳에서 에너지가 풍부한 어둠의 정령들을 찾을 수 있을 겁니다. 그들의 에너지를 고글에 주입한 다음 내게 가져오세요.",
    },
    [27234] = {
        ["T"] = "위기에 처한 노움",
        ["O"] =
        "충전된 무아지경 강화기를 사용하여 불타는 칼날단의 일원에게 윙클 스크류버킷의 위치를 말하도록 최면을 거십시오. 성공하면 스퀴글코드 전초기지의 디비 스퀴글코드에게 돌아가십시오.",
        ["D"] =
        "무아지경 강화기가 충전되어 사용할 준비가 되었습니다! 천둥도끼 요새로 가져가서 그곳에 있는 불타는 칼날단 일원 중 한 명에게 사용하십시오. 무아지경 상태가 얼마나 오래갈지 장장할 수 없으니, 질문은 빠르게 하십시오.\n\n그의 위치를 알아내면, 우리가 구출 작전을 조율할 수 있도록 디비에게 즉시 알리십시오. 행운을 빕니다, $N, 그리고 윙클을 집으로 데려와 주십시오!",
    },
    [27235] = {
        ["T"] = "위기에 처한 노움",
        ["O"] = "잊혀진 땅의 천둥도끼 요새에서 윙클 스크류버킷을 찾으십시오.",
        ["D"] =
        "최면을 건 불타는 칼날단 녀석이 윙클이 천둥도끼 요새 남쪽 동굴에 갇혀 있다고 했단 말이죠? 그게 사실이라면, 놈들이 그를 중앙 수용소로 이송하기 전에 서둘러야 합니다.\n\n하지만 조심하십시오. 불타는 칼날단은 그를 쉽게 내주지 않을 것입니다. 경비병을 좀 보내줄 수 있으면 좋겠지만, 이 일은 당신 손에 맡기겠습니다 $N. 윙클을 무사히 우리 집으로 데려와 주십시오.",
    },
    [27236] = {
        ["T"] = "위기에 처한 노움",
        ["O"] = "윙클 스크류버킷을 천둥도끼 요새 밖으로 호위하십시오. 성공하면 디비 스퀴글코드에게 보고하십시오.",
        ["D"] =
        "디비가 당신을 보냈나요? 저는 며칠 동안 이 동굴에 갇혀 있었습니다. 도망칠까도 생각했지만, 저는 그저 겁 많은 노움일 뿐이니까요. 이제 당신이 왔으니 여기서 나갈 기회가 생겼군요! 앞장서십시오, $R!",
    },
    [27237] = {
        ["T"] = "공포의 종식",
        ["O"] = "잊혀진 땅 내의 스크래블스크류의 야영지에 있는 스트렉을 위해 공포의 괴조 8마리를 처치하십시오.",
        ["D"] =
        "우리 캐러밴이 잊혀진 땅을 가로지를 때면, 켄타우로스나 현지 야생동물의 매복 공격을 받을 위험이 자주 있습니다. 무슨 이유에서인지 잊혀진 땅 전역의 공포의 괴조들이 우리가 운반하는 날고기를 훔치는 데 특히 재미를 붙였습니다. 몇 번 성공하더니 녀석들의 공격이 점점 더 대담해지고 있습니다. 캐러밴이 안전할 수 있도록 녀석들의 수를 좀 줄여주시겠습니까?",
    },
    [27238] = {
        ["T"] = "임프의 분부",
        ["O"] =
        "북서쪽 잊혀진 땅에 있는 살게론으로 이동하여 니조리스를 다시 찾으십시오. 악마의 육분의를 되찾아 그늘수렵 마을에 있는 핍조트에게 가져가십시오.",
        ["D"] =
        "악마가 되는 게 득인지 실인지 모르겠지만, 우리가 태어난 세계가 아닌 다른 세계로 소환될 때 일반적으로 진짜 죽을 수 없다는 조항이 우리 계약서에 있습니다.\n\n그러니까, 죽긴 하지만, 다시 돌아온다는 거죠. 어떤 때는 오랜 시간이 걸리고, 어떤 때는 시간이 전혀 걸리지 않습니다.\n\n잿빛 골짜기에서 지리스가 당신에게 죽이라고 했던 그 악마, 니조리스 말입니다. 녀석은 짧은 타이머를 달고 있어요. 지금 살게론이라고 불리는 사티로스 비밀 회합 장소에 있는데, 이번에는 악마의 육분의라는 유물을 가지고 있습니다. 원래는... 다른 일에 쓰이겠지만... 우리는 당신의 악마 씨앗 악마를 찾는 데 그것을 사용할 수 있습니다. 그러니 나가서 그 육분의를 가져오세요.\n\n아니면 육분의를 찾으러 보냈던 지난번 두 명처럼 잿더미로 변해버리든가요.",
    },
    [27239] = {
        ["T"] = "임프의 분부",
        ["O"] = "잊혀진 땅의 만노로크 소굴에 있는 쉬리나로부터 불지옥 연감을 회수하십시오.",
        ["D"] =
        "이 다음 임무는 지난번보다 훨씬 더 어렵습니다. 어쩌면 잿더미로 변할 시간은 아직 남아있을지도 모르죠!\n\n불타는 칼날단은 그늘수렵 마을에서 동쪽으로 이어지는 길을 따라 만노로크 소굴 폐허에 눈에 띄게 진을 치고 있습니다. 주변 사람들이 당신에게 그곳에 있는 악마들을 처리하라는 잡다한 임무를 줄 거라 확신하지만, 우리는 그들 중 오직 하나에만 관심이 있습니다.\n\n서큐버스 쉬리나는 이 차원에 존재하는 불지옥 연감의 유일한 사본을 소유하고 있습니다. 우리에게 그것이 필요해요. 가서 가져오세요!",
    },
    [27240] = {
        ["T"] = "임프의 분부",
        ["O"] = "남동쪽 잊혀진 땅에 있는 동트는 협곡에서 강력한 악마를 찾으십시오.",
        ["D"] =
        "내가 당신에게 무엇을 해야 할지 어떻게 아는지 궁금할 겁니다. 자카라가 무슨 생각을 하는지 알기 때문이죠. 그게 어떻게 작동하냐고요? 말해 주죠... 바로 마법입니다.\n\n자카라는 당신의 나약한 $C 두뇌로는 이해할 수 없는 마법 기술을 사용하여 당신이 찾고 있는 악마가 잊혀진 땅 남동쪽의 비밀 협곡에 있다는 것을 알아냈습니다. 전에 주인의 명령으로 그곳에 한 번 간 적이 있죠. 그곳은 동트는 협곡이라고 불립니다.\n\n자, 가서 크고 나쁜 악마를 찾으세요!",
    },
    [27241] = {
        ["T"] = "동트는 협곡",
        ["O"] = "잊혀진 땅의 그늘수렵 마을에 있는 자카라와 핍조트에게 돌아가십시오.",
        ["D"] =
        "강력한 악마 대신 불타는 칼날단이 건설한 요새를 발견했습니다. 입구는 단단히 봉인되어 있고 현재로서는 들어갈 방법이 보이지 않습니다.\n\n악마가 이곳에 있다면, 요새 안쪽에 있을 것이 틀림없습니다. 자카라와 핍조트에게 돌아가 이 상황을 알려야 합니다.",
    },
    [27242] = {
        ["T"] = "동트는 협곡",
        ["O"] = "오그리마의 스랄에게 돌아가십시오.",
        ["D"] =
        "아아, 자카라는 다음에 무엇을 해야 할지 모릅니다. 어떻게든 그 요새의 문을 뚫을 방법을 찾아야겠지만, 안에 무엇이 있는지 모른 채 무작정 돌진하는 것은 어리석은 짓이겠죠. 적어도 그녀는 그렇게 말합니다. 난 당신이 한 번 시도해 보는 걸 보고 싶지만요.\n\n<핍조트가 당신에게 이빨을 드러내며 웃습니다.>\n\n가서 스랄에게 전하세요. 이제 그의 골칫거리니까요.",
    },
    [27243] = {
        ["T"] = "미쳐버린 청소부",
        ["O"] = "코도 무덤 내에서 썩은고기괴물 8마리를 처치하십시오.",
        ["D"] =
        "흙 속의 벌레가 되든 당신 뼈를 쪼아먹는 청소부가 되든, 당신 뒤에 오는 것들을 위한 먹이가 되는 것은 자연스러운 삶의 주기의 일부입니다.\n\n마음속 깊이 코도도 이 사실을 알고 있기 때문에 이곳 무덤으로 온다고 믿습니다.\n\n하지만 코도 시체를 파먹는 청소부 독수리의 수가 너무 많아졌고, 너무 공격적으로 변했습니다. 녀석들은 아직 살아있는 코도를 쪼고 할퀴어, 녀석들의 마지막 날들을 고통스럽게 만듭니다.\n\n독수리들의 수를 줄여, $N, 이 신성한 땅에 균형을 되찾아 주십시오.",
    },
    [27244] = {
        ["T"] = "마크루라 별미",
        ["O"] =
        "잊혀진 땅 해안에 있는 마크루라로부터 특대형 집게발을 수집하여 침묵의 초소에 있는 하노르에게 돌아가십시오.",
        ["D"] =
        "아래 무덤의 특성 때문에 침묵의 초소 분위기는 종종 암울합니다. 타우렌에게 코도의 생명이 끝나는 것을 지켜보는 것은 고통스럽지만, 일어나야만 하는 일임을 알고 있죠.\n\n어떤 영혼이든 따뜻하게 해 줄 수 있는 유일한 것은 몸에 좋은 따뜻한 해산물 스튜입니다. 특대형 집게발을 좀 구할 수 있다면, 모두를 위한 맛있는 식사를 만들 수 있습니다.\n\n해안으로 가서 마크루라들에게서 집게발을 좀 모아 주시겠습니까? 크면 클수록 좋습니다!",
    },
    [27245] = {
        ["T"] = "그림토템의 배신",
        ["O"] = "에토크 야영지 또는 갈래발굽 바윗골에서 갈라크 폭풍술사 8명, 갈라크 약탈자 8명, 갈라크 싸움꾼 8명을 처치하십시오.",
        ["D"] =
        "날 볼 때 당신이 무엇을 보는지 알고 있소, $C. 내가 스랄의 적들과 기꺼이 일하려 하기 때문에 호드를 배신했다고 생각하겠지. 당신의 세상은 흑백이지만, 내 세상은 다양한 잿빛이라오.\n\n자신의 동족을 속여 타락시키고 노예로 만든 자들에 대한 스랄의 복수심을 생각해 보시오. 글쎄, 켄타우로스는 나의 불타는 군단이라오. 내 평생의 과업은 우리가 다시는 그 흉물들에게 사냥당하지 않도록 하는 것이지.\n\n그 목적을 위해 당신이 버섯구름 봉우리로 여행하여 많은 켄타우로스를 처치해 주었으면 하오. 에토크 야영지와 갈래발굽 바윗골에서 그들을 찾을 수 있을 거요.\n\n불모의 땅에서 버섯구름 봉우리로 가는 남쪽 길을 타시오. 켄타우로스 야영지는 협곡의 북쪽 사면에 붙어 있다오.",
    },
    [27246] = {
        ["T"] = "폭풍술사 지신스",
        ["O"] = "갈래발굽 소굴로 여행하십시오. 폭풍술사 지신스를 처치하고 그녀에게서 대지모신의 서판을 회수하십시오.",
        ["D"] =
        "켄타우로스들은 타우렌이 끊임없이 노력하여 세운 것들을 약탈하고 파괴한다오. 그들은 발굽으로 대지를 더럽히는 도둑이자 잡종들이지.\n\n타혼다 야영지가 버려졌을 때, 켄타우로스들이 와서 가져갈 수 없었던 귀중품 몇 가지를 약탈해 갔소. 그 중 하나가 땅을 신성하게 하기 위해 그곳에 묻혀 있던 신성한 대지모신의 서판이라오.\n\n서판은 현재 버섯구름 봉우리의 갈래발굽 바윗골에 사는 폭풍술사 지신스가 가지고 있소. 이 신성한 서판을 되찾고 지신스는 흙 속에 파묻히기를 바라오.",
    },
    [27247] = {
        ["T"] = "어둠파괴 고원",
        ["O"] = "잊혀진 땅의 어둠파괴 고원에 있는 카일리 그림토템에게 대지의 서판을 가져가십시오.",
        ["D"] =
        "타혼다 야영지에서 당신이 구해낸 대지모신의 서판이 새 보금자리로 갈 준비가 되었소.\n\n우리 부족이 잊혀진 땅에 어둠파괴 고원이라는 새로운 정착지를 세웠소. 정기의 봉우리 북서쪽 언덕에서 그곳으로 올라가는 길을 찾을 수 있을 거요. 푸른 토템 근처에서 시작되지.\n\n서판을 카일리 그림토템에게 가져가시오. 그녀는 서판으로 대지를 축복할 그곳의 주술사요.",
    },
    [27248] = {
        ["T"] = "침묵의 초소를 위한 메시지",
        ["O"] = "잊혀진 땅 중앙에 있는 침묵의 초소로 이동하여 펠굴 투커츠와 대화하십시오.",
        ["D"] =
        "콜카르 켄타우로스들은 타우렌이 예전에 그랬던 것처럼 유목 생활을 합니다. 우리가 이곳 어둠파괴 고원에 정착하자마자 콜카르 무리가 마을 아래 언덕 기슭에 텐트를 쳤습니다. 우리는 그들에게 저항할 만큼 충분한 전사가 없었고, 카일리는 이 상황에 대한 메시지를 썬더 블러프에 다시 보냈습니다. 왜 도착하지 않았는지 궁금하군요....\n\n대지모신의 서판은 더 이상 필요 없습니다. 마가타에게 다시 가져갈 수 있습니다. 계속해서 침묵의 초소로 가주시겠습니까? 제 친구 펠굴 투커츠는 이곳에 무슨 일이 일어났는지 알고 있을 것입니다.",
    },
    [27249] = {
        ["T"] = "침입자를 죽여라!",
        ["O"] = "제반 그림토템을 위해 어둠파괴 고원에서 콜카르 약탈자 10마리를 처치하십시오.",
        ["D"] =
        "호드가 멀고어에서 켄타우로스를 물리쳤으니 그들과의 거래 방식에 변화가 생기길 바랐건만. 내가 어리석었지. 어떤 것들은 절대 변하지 않는군.\n\n자네는 꽤 유능한 전사 같아. 어둠파괴 고원 주변을 어슬렁거리는 콜카르 약탈자들을 처치하는 데 자네의 힘을 빌리고 싶네.",
    },
    [27250] = {
        ["T"] = "약탈자들 약탈하기",
        ["O"] = "어둠파괴 고원에 있는 제반 그림토템을 위해 타우렌의 소중한 소지품 8개를 수집하십시오.",
        ["D"] =
        "콜카르는 어둠파괴 고원에 있는 사람들을 죽였을 뿐만 아니라, 마을을 약탈하고 타우렌의 소중한 소지품들을 자기들 야영지로 가져갔지. 난 그 물건들을 돌려받고 싶네!\n\n어둠파괴 고원을 지나 콜카르 마을로 가는 길을 따라 내려가 보게. 그들의 오두막과 야영지에서 도난당한 타우렌의 소지품을 찾을 수 있을 거야. 가능한 한 많이 모아서 내게 돌려주게.",
    },
    [27251] = {
        ["T"] = "마가타에게 돌아가기",
        ["O"] = "마가타 그림토템에게 어둠파괴 고원에서 무슨 일이 일어났는지 알리십시오.",
        ["D"] =
        "이곳에 잠시 머물며 쓰러진 부족원들의 영혼과 작별 인사를 나누고 싶네. 자네가 도착하기 전에 쓰러진 자들의 뼈를 수습할 수 있었지. 적절한 장례 의식을 위해 이 꾸러미를 마가타에게 다시 가져가 주게. 그녀에게 무슨 일이 일어났는지, 그리고 내가 곧 마을로 돌아갈 것이라고 전해주게.",
    },
    [27252] = {
        ["T"] = "합당한 장례",
        ["O"] = "북동쪽 멀고어에 있는 붉은 바위 언덕의 의식용 모닥불에 그림토템 뼈 꾸러미를 가져가십시오.",
        ["D"] =
        "장로회는 내가 알아서 처리하겠소. 당신은 말한 대로 날 섬겼지. 약속을 지켰소.\n\n마지막으로 한 가지 부탁하겠소 -- 북동쪽 멀고어에 있는 신성한 매장지, 붉은 바위 언덕으로 이 뼈들을 가져가시오. 우리 부족의 영혼이 안식을 찾을 수 있도록 의식용 불에 던져 넣으시오. 그러면 당신은 나를 섬기는 임무에서 해방될 거요, $N.",
    },
    [27253] = {
        ["T"] = "엄청난 이익",
        ["O"] =
        "잊혀진 땅 내에서 가장 큰 코도 뼈에서 화석화된 담낭 3개를 수집한 다음, 잊혀진 땅 내 코르메크의 오두막에 있는 비블리 퍼츠버클에게 돌아가십시오.",
        ["D"] =
        "남서쪽의 코도 무덤 주변에는 잊혀진 땅이... 이렇게 되기 전, 아주 오래전에 이곳에 살았을 법한 진정 거대한 코도들의 뼈가 널려 있습니다. 그 크기의 비밀은 그들이 소비한 것에 있다고 생각하며, 내 이론을 증명하려면 화석화된 담낭 샘플이 필요합니다.\n\n내 말이 맞다면, 그리고 내가 그런 거대한 짐승을 번식시킬 수 있다면, 사람들이 이 짐승들을 보려고 얼마나 많은 돈을 지불할지 누가 알겠습니까!? 어쩌면 일종의 공원에서... 어쨌든 담낭은 찾기 힘들 테니 눈을 크게 뜨고 찾아보십시오.",
    },
    [27254] = {
        ["T"] = "언더시티를 위한 시약",
        ["O"] = "잊혀진 땅에 있는 애니 그림에게 붉은피의 창 발톱 10개와 붉은피의 창 뿔 10개를 가져가십시오.",
        ["D"] =
        "이곳에서 내 임무 중 하나는 언더시티의 강력한 연금술사인 시어도어 그리프스를 위한 시약을 구하는 거야. 마윈은 우리가 어차피 여기 있으니까 그냥 은행에 돈을 저축하는 것처럼 쉽다고 생각하지. 지금도 일손이 부족하다는 건 신경 안 쓴다니까.\n\n그의 목록에 있는 처음 몇 가지 아이템은 꽤 구하기 쉬울 거고, 나를 도와주는 사람에겐 꽤 짭짤한 돈벌이가 될 거야.\n\n잊혀진 땅의 멀리 북동쪽에 있는 증오의분노 사티로스에게서 뿔과 발톱이 좀 필요해. 그것들을 가져오면 목록의 나머지 부분도 시작해보자고.",
    },
    [27255] = {
        ["T"] = "언더시티를 위한 시약",
        ["O"] = "잊혀진 땅에 있는 애니 그림에게 스콜파시 독 7병과 오래된 코도 통가죽 3장을 가져가십시오.",
        ["D"] =
        "시어도어의 목록 다음은... 어디 보자... 흠. 아, 여기 있군.\n\n간단하지만 꽤 명확한 지시사항이야. 스콜파시의 독과 코도의 가죽이 필요하대. 세부 사항을 보면 특정한 생물이 필요하다고 적혀있어. 독은 어떤 스콜파시에게서든 얻을 수 있지만, 가죽은 죽어가거나 고대의 코도가 아닌 오래된 코도에게서 구해야 한대.\n\n연금술사들 말이야, 그들이 원하는 건 정말... 이상해.",
    },
    [27256] = {
        ["T"] = "언더시티를 위한 시약",
        ["O"] = "잊혀진 땅에 있는 애니 그림에게 지옥사냥개 뇌 10개, 황천의 날개 10개, 그리고 파멸의경비대 혈액 10병을 가져가십시오.",
        ["D"] =
        "이게 마지막 물건인데, 솔직히 말해서 별로 좋은 일은 아닐 거야. 다른 것보다 시간도 좀 더 걸릴 거고.\n\n자, 나쁜 소식부터. 시어도어의 말에 따르면 다음과 같아. 마나 탐식자, 마법사 사냥꾼, 또는 지맥 사냥꾼의 뇌 10개. 그리고, 황천 처녀, 자매 또는 여마법사의 황천의 날개 10개. 마지막으로... 파멸의경비대 부대장 또는 군주의 파멸의경비대 혈액 10병.\n\n간단하지? 젠장... 이번 건 포기하고 싶어도 이해할게.",
    },
    [27257] = {
        ["T"] = "언더시티를 위한 시약",
        ["O"] = "언더시티 내 연금술사 지구에 있는 시어도어 그리프스에게 시어도어의 꾸러미를 배달하십시오.",
        ["D"] =
        "보수를 받으려면 언더시티로 돌아가서 시어도어 본인과 이야기해야 해. 이 보급품 꾸러미를 그에게 주면, 충분한 보상을 받을 수 있을 거야.\n\n걱정 마, 돌아가면 너에 대해 좋게 얘기해 줄 테니까. 나도 잊혀진 땅에 오래 있지는 않을 거거든.",
    },
    [27258] = {
        ["T"] = "황천의 잔재",
        ["O"] = "만노로크 소굴 내 악마들에게서 황천의 잔재 10개를 수집하십시오.",
        ["D"] =
        "이곳 남서쪽에서 불타는 칼날단이 악마들을 소환하고 있는 위험하고 지옥불에 오염된 만노로크 소굴을 찾을 수 있을 거요.\n\n악마들이 고향 차원에서 아제로스로 넘어오면서 내가 연구하고 있는 기이한 황천의 잔재를 가져오고 있소. 샘플을 좀 수집해 주시겠소?",
    },
    [27259] = {
        ["T"] = "스퀴글코드를 위한 보급품",
        ["O"] = "천둥도끼 요새 남서쪽에 있는 스퀴글코드 전초기지로 스퀴글코드 보급품 상자를 가져가십시오.",
        ["D"] =
        "이 위험한 땅에서 우리 얼라이언스 일원들은 동맹들에게 도움의 손길을 내밀 준비가 되어 있어야 해요. 그런 의미에서, 스퀴글코드 전초기지라는 새로운 노움 정착지에 소포를 하나 가져다주셨으면 해요. 그곳 여관주인, 티니퓨즈에게 음식과 음료 보급품이 바닥나고 있다는 연락을 받았거든요.\n\n스퀴글코드는 그리 멀지 않아요. 여기서 남서쪽, 천둥도끼 요새 너머에서 찾을 수 있을 거예요.",
    },
    [27260] = {
        ["T"] = "돌아가기 위한 간청",
        ["O"] = "그늘수렵 마을 북동쪽의 돌개바람 폭풍술사들에게서 폭풍의 정수 4개를 수집하십시오.",
        ["D"] =
        "내 고향과 내 마음은 동부내륙지의 깨진엄니 부족과 함께 있지만, 메마른나무껍질 사촌들에게 주술의 어두운 면을 가르친 죄로 추방당했어. 나는 그 행동을 깊이 후회하고 내가 원하는 건 오직 발밑의 풀을 다시 느끼고, 나무가 흔들리는 것을 보며, 가족과 밤을 보내는 것뿐이야.\n\n그럴 수 있도록 깨진엄니 원시술사에게 강력한 번개 토템을 바치려 하는데, 이 임무를 도와줄 수 있길 바라.\n\n이곳 북동쪽에는 이 땅을 배회하는 강력한 바람의 정령인 돌개바람 폭풍술사들이 있어. 그들 안에는 내가 토템에 집중시킬 수 있는 분노가 있지. 그것을 모아 내게 가져다줘, 부탁할게.",
    },
    [27261] = {
        ["T"] = "돌아가기 위한 간청",
        ["O"] = "잊혀진 땅 전역의 우두머리 천둥뿔도마뱀으로부터 축전의 뿔 10개를 수집하십시오.",
        ["D"] =
        "토템을 만들기 위해 마지막으로 하나가 더 필요해. 잊혀진 땅 주변에서 가장 나이가 많고, 가장 강하며, 가장 큰 뿔을 가진 우두머리 천둥뿔도마뱀을 찾을 수 있을 거야. 수년 동안 그들을 통해 흐른 에너지로 원시술사에게 바칠 강력한 번개 토템을 만들 수 있어. 나를 위해 뿔을 좀 모아줄 수 있겠어?",
    },
    [27262] = {
        ["T"] = "가장 신선한 기름",
        ["O"] = "그늘수렵 마을 해안을 따라 마윈 슈릴윌을 위해 범고래 지방 덩어리 7개를 수집하십시오.",
        ["D"] =
        "랜턴과 폭발물에 쓰이는 최고의 기름 중 일부는 잊혀진 땅 기슭의 범고래에게서 나옵니다. 타우렌과 트롤 모두 녀석들의 지방을 구하는 걸 돕지 않으려 해요, 무슨 의식적인 동물 존중 같은 거라나. 그래서 저 대신 손을 더럽힐 당신 같은 용감한 모험가가 필요합니다! 만에 들어가서 저를 위해 지방을 좀 모아 주시겠습니까?",
    },
    [27263] = {
        ["T"] = "가장 친절한 행동",
        ["O"] = "코도 무덤 내에서 임종의 코도 8마리를 처치하십시오.",
        ["D"] =
        "칼림도어의 코도들이 기나긴 삶이 끝나간다고 느낄 때 왜 필사적으로 이곳 무덤에 오려고 하는지 완전히 이해되지는 않지만, 그들의 여정은 떠오르는 태양처럼 예측 가능합니다.\n\n하지만 어떤 코도들은 심하게 병들어 대지모신의 품으로 건너가지 못한 채 고통 속에서 땅을 배회합니다.\n\n우리가 할 수 있는 가장 친절한 일은 그들을 그녀에게 인도하는 것입니다. 나를 위해 이 일을 해주시겠습니까?",
    },
    [27264] = {
        ["T"] = "현상 수배: 케이코",
        ["O"] = "잊혀진 땅 내의 그늘수렵 마을 외곽 만에서 케이코를 찾아 처치하십시오.",
        ["D"] =
        "낚시는 이 마을을 먹여 살리는 중요한 일이지만, 만 밖에서는 케이코라고 이름 붙인 거대한 범고래가 낚싯배를 전복시키고 트롤과 타우렌 모두에게 부상을 입히고 있습니다. 가능한 한 많은 사람들을 계속 먹여 살리려면 이 잔인한 범고래를 처치해야 합니다.\n\n케이코의 죽음에 대한 증거를 그늘수렵 마을 내의 지나르질렌에게 가져가십시오.",
    },
    [27265] = {
        ["T"] = "현상 수배: 윌피즈 실버빗",
        ["O"] = "잊혀진 땅 내 만노로크 소굴 북쪽에서 윌피즈 실버빗을 찾아 처치하십시오.",
        ["D"] =
        "나의 이전 수습생이 이곳에서의 우리 계획에 대한 귀중한 지식을 가지고 불타는 군단을 도우러 도망쳤습니다. 이 오만함을 용납할 수 없습니다! 그의 머리를 가져오기를 원합니다 -- 필요하다면 창에 꽂아서라도! 만노로크 소굴 바로 북쪽에서 버섯을 따고 있는 것이 마지막으로 목격되었습니다.\n\n-- 이무 코퍼스펠",
    },
    [27266] = {
        ["T"] = "번개의 손길",
        ["O"] = "번개의 정수 5개를 조곤의 마법막대에 주입하고 Razor Hill에 있는 조곤에게 돌아가십시오.",
        ["D"] =
        "반갑네. 시간 있으면 좀 도와주겠나. 주술사의 능력을 연습 중인데, 물체를 조종하는 법을 배우고 싶어. 그러려면 번개의 정수가 좀 필요하다네.\n\n그걸 찾기 가장 좋은 곳은 천둥 마루야. 내 마법막대를 가져가서 짐승들에게 사용하게. 그 도마뱀들의 가죽에는 번개가 풍부해서, 이 마법막대가 그것을 흡수할 거라네.",
    },
    [27267] = {
        ["T"] = "위기에 처한 마을",
        ["O"] = "시험의 골짜기에 있는 가로키를 위해 엉겅퀴풀 5개, 지옥사냥개 피 3병, 피발톱 랩터 발톱 3개를 수집하십시오.",
        ["D"] =
        "반갑네, 친구. 보급품이 필요한 현지 마을에서 보고를 받았어. 일자리를 찾고 있다면 도움을 주면 고맙겠군.\n\n보고서에 따르면 엉겅퀴풀이 좀 필요하다는데, 이 계곡 주변에 흩어져 있는 걸 찾을 수 있을 거야. 다음은 여기 북쪽 동굴에 있는 지옥사냥개의 피야. 마지막으로 여기 남쪽에 있는 랩터 서식지에서 랩터의 발톱이 필요해.",
    },
    [27268] = {
        ["T"] = "보르날에게 배달",
        ["O"] = "시약 상자를 센진 마을에 있는 장로 보르날에게 배달하십시오.",
        ["D"] =
        "도와줘서 정말 고맙네, 친구. 계곡을 나가는 길에 이 시약들을 배달해 줄 수 있겠나?\n\n이것들은 센진 마을에 있는 장로 보르날에게 가는 거야. 계곡을 빠져나간 후 남동쪽으로 가면 찾을 수 있어. 이걸 어디에 쓸지는 모르겠지만, 배달해주면 자네에게 줄 일거리가 더 있을지도 모르지.",
    },
    [27269] = {
        ["T"] = "수습 랩터 타기",
        ["O"] = "자르티로부터 수습 타기를 배운 후, 듀로타에 있는 졸니르와 대화하여 랩터를 받으십시오.",
        ["D"] =
        "돌아온 걸 환영해. 수습 타기를 배우러 왔지, 맞나? 이전과 마찬가지로 랩터 가격은 지불되었지만 훈련 비용은 직접 내야 해. 유감스럽지만 신속하게 타는 건 싸지 않다네.\n\n훈련을 받은 후 바로 옆에 있는 졸니르와 얘기하게. 그가 우리 랩터 판매를 관리하니까. 아직 자금이 없다면 나중에 다시 와도 좋아.",
    },
    [27270] = {
        ["T"] = "랩터 타기",
        ["O"] = "자르티로부터 초급 타기를 배운 후, 듀로타에 있는 졸니르와 대화하여 랩터를 받으십시오.",
        ["D"] =
        "그래서 랩터를 구하러 왔나 보군? 마침 자네를 기다리고 있었지! 수수께끼의 후원자가 일반 랩터에 대한 대금을 남겼는데 당신 이름인 $N 앞으로 되어 있더군. 하지만 훈련 비용까지 내주진 않았으니 그건 자네가 지불해야 할 거야.\n\n훈련을 받은 후 바로 옆에 있는 졸니르와 얘기하게. 그가 우리 랩터 판매를 관리하니까. 아직 자금이 없다면 나중에 다시 와도 좋아.",
    },
    [27271] = {
        ["T"] = "수습 늑대 타기",
        ["O"] = "킬다르로부터 수습 타기를 배운 후, 오그리마에 있는 오구나로 울프러너와 대화하여 타기용 늑대를 받으십시오.",
        ["D"] =
        "돌아온 걸 환영하오. 수습 타기를 배우러 왔군, 맞소? 이전과 마찬가지로 늑대 가격은 지불되었지만 훈련 비용은 직접 내야 하오. 유감스럽지만 신속하게 타는 건 비싸다오.\n\n훈련을 받은 후 바로 옆에 있는 오구나로 울프러너와 얘기하시오. 그가 우리 늑대 판매를 관리하오. 아직 자금이 없다면 언제든지 다시 와도 좋소.",
    },
    [27272] = {
        ["T"] = "늑대 타기",
        ["O"] = "킬다르로부터 초급 타기를 배운 후, 오그리마에 있는 오구나로 울프러너와 대화하여 타기용 늑대를 받으십시오.",
        ["D"] =
        "그래서 늑대를 구하러 왔나 보군? 마침 당신을 기다리고 있었소! 수수께끼의 후원자가 타기용 늑대에 대한 대금을 남겼는데 당신 이름인 $N 앞으로 되어 있더군. 하지만 훈련 비용까지 내주진 않았으니 그건 당신이 지불해야 할 거요.\n\n훈련을 받은 후 바로 옆에 있는 오구나로 울프러너와 얘기하시오. 그가 우리 늑대 판매를 관리하오. 아직 자금이 없다면 나중에 다시 와도 좋소.",
    },
    [27273] = {
        ["T"] = "샤그리",
        ["O"] = "샤그리의 영혼을 처치하고 센진 마을에 있는 봄베이에게 돌아가십시오.",
        ["D"] =
        "이보게 친구. 오래전에 메아리 섬의 지도자였던 샤그리라는 트롤이 있었지. 그는 자네와 다르지 않은 모험가에게 살해당했어.\n\n이제 그의 영혼이 분노하여 섬 전역에 분노를 퍼뜨리고 있다네. 그걸 막아야 해! 가장 북쪽에 있는 섬 꼭대기에서 트롤들이 그를 위해 지은 성소를 찾을 수 있을 거야. 그걸 파괴해서 그의 존재를 없애버려.",
    },
    [27274] = {
        ["T"] = "저주받은 함대",
        ["O"] = "쿨 티라스 갑판원 8명과 쿨 티라스 제독 3명을 처치하고 Razor Hill에 있는 가르톡에게 돌아가십시오.",
        ["D"] =
        "요새를 잘 처리해 주었군 $N. 하지만 아직 해야 할 일이 남아있어. 몇 년 전 쿨 티라스인들이 바다에서 듀로타를 공격했지. 대포와 폭발 때문에 내 부하들이 죽을 뻔했어. 오그리마에서 증원군이 도착했을 때 비로소 그들을 밀어내고 많은 수를 학살했지.\n\n죽은 쿨 티라스 선원들이 바다에서 불안해하며, 임무를 끝내지 못해 제대로 떠나지 못하고 있다고 하더군.\n\n그들 함대의 잔해로 가서 여전히 문제를 일으키고 있는 쿨 티라스인들을 모두 처치해 줬으면 하네. 이곳 동쪽, 가라앉은 해안에서 침몰한 배들을 찾을 수 있을 거야.",
    },
    [27275] = {
        ["T"] = "현상 수배: 더스트포우",
        ["O"] = "시험의 골짜기에 있는 현장감독 타즈릴에게 더스트포우의 주둥이를 가져가십시오.",
        ["D"] =
        "경비병의 명령에 따라, 더스트포우라는 위험한 늑대에게 사형을 선고한다! 시험의 골짜기에서 수십 명의 시민을 죽인 더스트포우는 이 현상금을 노리는 모험가들에게 어려운 도전이 될 것이다.\n\n더스트포우는 골짜기의 동쪽 능선을 순찰하는 모습이 목격되었다. 성공한다면 현장감독 타즈릴에게 녀석의 주둥이를 가져와라.",
    },
    [27276] = {
        ["T"] = "감독관 힌크",
        ["O"] = "듀로타에 있는 비행선 탑의 감독관 힌크에게 보고하십시오.",
        ["D"] =
        "정찰병 중 한 명이 방금 편지를 배달했네. 우리의 새 비행선 탑을 짓고 있는 고블린들에게 무슨 문제가 생긴 것 같더군. 그게 무슨 의미인지는 확실치 않지만... 현장감독이 도움을 요청했으니 Razor Hill이 응답해야지.\n\n대족장님께서 비행선 탑을 짓는 것이 최우선 과제라고 하셨으니, 고블린들이 겪고 있는 문제를 돕는 것이 중요해! 가서 감독관 힌크에게 보고하게. 그가 공사를 감독하고 있지. 새 비행선 탑은 오그리마 성문 바로 남동쪽에서 찾을 수 있을 거야.",
    },
    [27277] = {
        ["T"] = "낫송곳니 정지",
        ["O"] = "피발톱 낫송곳니랩터 10마리를 처치하고 듀로타의 비행선 탑에 있는 감독관 힌크에게 돌아가십시오.",
        ["D"] =
        "듀로타에서 일을 맡았을 때 내가 실수했다는 걸 알았지! 아제로스의 그 많은 장소 중에서, 랩터와 전갈이 일상적으로 돌아다니는 곳을 선택하다니. 내가 여기 있는 유일한 이유는 대족장이 이 탑을 짓는 대가로 엄청난 돈을 지불하기 때문이야.\n\n공사가 시작된 이후로 우린 계속 이 망할 랩터들 때문에 골머리를 앓고 있어! 녀석들은 밤마다 우리 야영지를 습격하고 낮에는 우리 일꾼들을 잡아먹는다고. 자네가 가서 녀석들의 수를 좀 \"치워\" 주면, 개발이 다시 일정대로 진행될 수 있을 거야!",
    },
    [27278] = {
        ["T"] = "먼지바람 탈출",
        ["O"] = "기즐 스크류스닙이 먼지바람 동굴을 탈출하도록 도우십시오. 성공하면 듀로타의 비행선 탑에 있는 감독관 힌크에게 보고하십시오.",
        ["D"] =
        "다른 $R을(를) 다시는 못 볼 줄 알았어요! 절 여기서 내보내 주세요. 이 이교도들은 미쳤어요! 아까 저한테 의식을 치르려 했는데, 재료가 다 없었던 것 같아요.\n\n그들이 돌아오면 틀림없이 다시 시도할 거예요. 이번에는 성공할지도 몰라요! 서둘러서 여길 빠져나가요.",
    },
    [27279] = {
        ["T"] = "기즐 찾기",
        ["O"] = "기즐 스크류스닙을 찾으십시오. 감독관 힌크가 그가 먼지바람 동굴에 붙잡혀 있을지도 모른다고 했던 것을 기억하십시오.",
        ["D"] =
        "나의 최고 기술자인 기즐 스크류스닙이 며칠 전에 보급품을 구하러 나갔다가 불가사의하게 사라졌어. 난 그가 몹시 걱정되고, 그의 설계도는 비행선 탑 개발에 필수적이야.\n\n추측건대, 불타는 칼날단이 그를 잡아갔을 거야. 그들이 Razor Hill 바로 북쪽, 먼지바람 동굴이라는 곳을 점령하고 있다는 소문을 들었어. 그들은 납치한 사람들에게 악마의 의식과 기타 끔찍한 짓을 저지르지.\n\n먼지바람 동굴로 가면 기즐을 찾을 가능성이 높다고 생각해. 그를 찾으면 자네의 수고에 대해 넉넉히 보상하겠네.",
    },
    [27280] = {
        ["T"] = "에어하트는 가야 한다",
        ["O"] = "먼지진흙 습지대와 불모의 땅 경계에 있는 에어하트 요새를 찾아내어 그 안에 있는 사령관 에어하트를 처치하십시오.",
        ["D"] =
        "타우라조 야영지에서 골치 아픈 소식이 도착했습니다. 얼라이언스 탈영병 무리가 먼지진흙 습지대와 불모의 땅 경계에 있는 요새를 점령하고 우리의 보급품을 훔치고 있다는군요. 얼라이언스 내의 내... 연락책들도 상황이 혼란스러워지기 전에 우리가 그들을 소탕해야 한다는 데 동의했습니다. 이 탈영병들이 호드와의 전면전을 촉발하게 둘 순 없습니다.\n\n하지만 그들은 무장을 잘 갖추고 요새 안에 단단히 참호를 파고 있습니다. 그들의 우두머리는 에어하트라는 겁 없는 사령관입니다. 요새 깊숙한 곳에서 그를 찾아내 처치하여 이 끔찍한 상황을 끝내주십시오.",
    },
    [27281] = {
        ["T"] = "에어하트는 가야 한다",
        ["O"] = "먼지진흙 습지대와 불모의 땅 경계에 있는 에어하트 요새를 찾아내어 그 안에 있는 사령관 에어하트를 처치하십시오.",
        ["D"] =
        "정찰병들로부터 새로운 탈영병 무리가 먼지진흙 습지대와 불모의 땅 경계에 있는 요새를 점령했다는 골치 아픈 소식을 받았습니다. 누군가 상황을 오해하여 우리가 호드와의 전면전을 위해 무장하고 있다고 믿기 전에 그들을 소탕해야 합니다.\n\n탈영병들은 무장을 잘 갖추고 요새 안에 단단히 참호를 파고 있습니다. 그들의 우두머리는 에어하트라는 겁 없는 사령관입니다. 요새 깊숙한 곳에서 그를 찾아내 처치하여 이 끔찍한 상황을 끝내주십시오.",
    },
    [27282] = {
        ["T"] = "현상 수배: 용 사냥꾼",
        ["O"] = "먼지진흙 습지대의 브록의 웅덩이에서 브록을 추적하십시오.",
        ["D"] =
        "브록은 돌망치 폐허를 되찾는 걸 도울 강한 전사와 강력한 마법을 쓰는 사람이 필요해. 뚱뚱하고 게으른 대군주는 아무것도 안 할 거지만, 브록은 할 수 있어. 습지대의 남서쪽 구석에 있는 웅덩이에서 브록을 찾아봐.",
    },
    [27283] = {
        ["T"] = "표류자",
        ["O"] = "아가일 윌크스를 테라모어까지 무사히 호위하십시오.",
        ["D"] =
        "사소한 의견 차이 때문에 내 선원들에게 쫓겨나서, 이 낡은 구명정 하나만 달랑 가지고 폭풍우 속으로 내던져진 것도 모자라. 깨어나 보니 빛도 저버린 이 늪지대라니!\n\n그냥 혼자 있을 수 있는 해변의 내 오두막으로 돌아가고 싶어. 징징대는 건 이제 그만! 술이 필요해! 가장 가까운 술집이 어딘가?",
    },
    [27284] = {
        ["T"] = "에어하트 탈출",
        ["O"] = "애나 카스피안을 에어하트 요새 밖으로 호위한 다음 테라모어 여관에 있는 그녀의 친구 자닌에게 그녀가 탈출했음을 알리십시오.",
        ["D"] =
        "남편 제럴드와 저는 신선한 보급품을 가지고 톱니항에서 테라모어로 가는 길에 이 불한당들의 매복 공격을 받았어요. 가슴의 문장을 보고 그들이 테라모어의 친구가 아니라는 걸 알 수 있었죠.\n\n불쌍한 제 남편은 프라우드무어의 명예를 지키려 했지만 글쎄요... 내 뒤를 보면 어떻게 됐는지 알 수 있을 거예요....\n\n발목을 심하게 삐어서 여길 빠져나가려면 도움이 필요해요. 절 도와주시겠어요, $n?",
    },
    [27285] = {
        ["T"] = "에어하트 탈출",
        ["O"] = "카야 레이지토템을 에어하트 요새 밖으로 호위한 다음 타우라조 야영지 여관에 있는 그녀의 친구 칼리야에게 카야가 탈출했음을 알리십시오.",
        ["D"] =
        "남편 통가와 저는 높새바람 봉우리에서 타우라조 야영지로 가는 길에 이 불한당들의 매복 공격을 받았어요.\n\n가슴의 문장을 보고 그들이 호드의 친구가 아니라는 걸 알 수 있었죠.\n\n불쌍한 제 남편은 우리를 지키려 했지만 글쎄요... 그들이 남편을 저 정원에 거름으로 뿌려버렸어요...!\n\n발목을 심하게 삐어서 여길 빠져나가려면 도움이 필요해요. 절 도와주시겠어요, $n?",
    },
    [27286] = {
        ["T"] = "불로 태워버려라",
        ["O"] = "어둠안개 동굴에 들어가 8개의 어둠안개 알주머니에 불을 지르십시오.",
        ["D"] =
        "우리가 여기로 이사 온 후로 오우거들이 실종되고 있어. 너무 멀리 가면 거미들이 널 잡을 거야. 우리가 살아남으려면 못된 벌레들이 사라져야 해. 내 횃불을 가져가서 그들의 알을 태워버려.",
    },
    [27287] = {
        ["T"] = "그들을 쓰러뜨려라",
        ["O"] = "에어하트 요새를 습격하여 탈영병 근위병 8명과 탈영병 의무병 8명을 처치하십시오.",
        ["D"] =
        "먼지진흙과 불모의 땅 경계에 있는 오래된 요새가 에어하트라는 사람의 지휘하에 얼라이언스 탈영병들에게 점령당했소. 우리가 그를 쓰러뜨리더라도 계급 내에서 새로운 지도자가 나타날 뿐일 거요.\n\n우리는 총력을 다해 이 탈영병들을 습격해야 하오. 머리만 치는 것이 아니라 팔다리도 잘라내야지. 그들이 이 타격에서 회복하지 못하도록 무시무시한 근위병과 그들의 의무병을 쓰러뜨리시오.",
    },
    [27288] = {
        ["T"] = "그들을 쓰러뜨려라",
        ["O"] = "에어하트 요새를 습격하여 탈영병 근위병 8명과 탈영병 의무병 8명을 처치하십시오.",
        ["D"] =
        "먼지진흙과 불모의 땅 경계에 있는 오래된 요새가 에어하트라는 사람의 지휘하에 얼라이언스 탈영병들에게 점령당했소. 우리가 그를 쓰러뜨리더라도 계급 내에서 새로운 지도자가 나타날 뿐일 거요.\n\n우리는 총력을 다해 이 탈영병들을 습격해야 하오. 머리만 치는 것이 아니라 팔다리도 잘라내야지. 그들이 이 타격에서 회복하지 못하도록 무시무시한 근위병과 그들의 의무병을 쓰러뜨리시오.",
    },
    [27289] = {
        ["T"] = "멀리서 온 증원군",
        ["O"] = "화려한 편지를 담쟁이 마을에 있는 나지르 블러드파이크에게 가져가 검사를 받으십시오.",
        ["D"] =
        "보급품과 증원군에 대한 귀하의 요청은 잘 들었으며, 우리 밀수업자들이 스팀휘들과 테라모어 자체를 통해 귀하에게 지원을 전달하기 위해 최선을 다하고 있습니다.\n\n요새가 함락되지 않는 것이 대의에 중요합니다. 호드의 개들과 얼라이언스 내부의 애송이들은 자신들이 저지른 일에 대한 대가를 치를 것입니다.\n\n우리 섬의 소유주와 새롭게 맺은 중립 관계 덕분에 우리는 우리의 열망에 충성하는 자들을 위한 진정한 마을을 건설하기 시작할 수 있었습니다.\n\n머지않아 타우라조 야영지를 전면 공격하라는 지시를 받게 되겠지만, 다음 보고를 기다리십시오. 제독을 위하여!\n\n-- R.D.",
    },
    [27290] = {
        ["T"] = "멀리서 온 증원군",
        ["O"] = "화려한 편지를 테라모어에 있는 여군주 제이나 프라우드무어에게 가져가 검사를 받으십시오.",
        ["D"] =
        "보급품과 증원군에 대한 귀하의 요청은 잘 들었으며, 우리 밀수업자들이 스팀휘들과 테라모어 자체를 통해 귀하에게 지원을 전달하기 위해 최선을 다하고 있습니다.\n\n요새가 함락되지 않는 것이 대의에 중요합니다. 호드의 개들과 얼라이언스 내부의 애송이들은 자신들이 저지른 일에 대한 대가를 치를 것입니다.\n\n우리 섬의 소유주와 새롭게 맺은 중립 관계 덕분에 우리는 우리의 열망에 충성하는 자들을 위한 진정한 마을을 건설하기 시작할 수 있었습니다.\n\n머지않아 타우라조 야영지를 전면 공격하라는 지시를 받게 되겠지만, 다음 보고를 기다리십시오. 제독을 위하여!\n\n-- R.D.",
    },
    [27291] = {
        ["T"] = "현상 수배: 킹 크룰",
        ["O"] = "돌망치 폐허 남쪽에서 킹 크룰을 찾아 물리치십시오.",
        ["D"] =
        "큰 악어가 오우거를 먹는다! 가족들이 실종되고 있어. 돌망치 폐허 남쪽으로 돌아다니지 마, 킹 크룰이 널 잡을 거야. 악어를 죽이면 빛나는 걸 줄게.",
    },
    [27292] = {
        ["T"] = "현상 수배: 킹 크룰",
        ["O"] = "돌망치 폐허 남쪽에서 킹 크룰을 찾아 물리치십시오.",
        ["D"] =
        "거대한 악어가 먼지진흙의 지류에서 발견되어 병사들과 여행자들을 마구 낚아채고 있습니다. 오우거들은 녀석에게 창의력 없게도 \"킹 크룰\"이라는 이름을 붙였습니다.\n\n그 괴물을 사냥하십시오. 녀석은 돌망치 폐허 남쪽에서 마지막으로 목격되었습니다.",
    },
    [27293] = {
        ["T"] = "추락한 비행선",
        ["O"] = "담쟁이 마을 남동쪽 지역을 정찰하여 정찰병 가크가 발견한 추락한 비행선을 찾으십시오.",
        ["D"] =
        "보셨습니까 $c? 화염이 치솟더니 다음 순간, 여기 정남동쪽 지평선에서 비행선이 공중에서 곤두박질치고 있었습니다!\n\n무슨 일이 일어나고 있는지 조사하기 위해 정찰대를 파견해 달라고 요청했지만, 그 놈의 복잡한 절차 때문에 발목이 묶여 있습니다.\n\n가서 추락 현장을 조사하고 생존자가 있는지 확인해 주시겠습니까?",
    },
    [27294] = {
        ["T"] = "추락한 비행선",
        ["O"] = "테라모어 부두 서쪽 지역을 정찰하여 순찰대원 윌리스가 발견한 추락한 비행선을 찾으십시오.",
        ["D"] =
        "보셨습니까 $c? 화염이 치솟더니 다음 순간, 여기 정서쪽 지평선에서 비행선이 공중에서 곤두박질치고 있었습니다!\n\n무슨 일이 일어나고 있는지 조사하기 위해 정찰대를 파견해 달라고 요청했지만, 그 놈의 복잡한 절차 때문에 발목이 묶여 있습니다.\n\n가서 추락 현장을 조사하고 생존자가 있는지 확인해 주시겠습니까?",
    },
    [27295] = {
        ["T"] = "도대체 비질 링크스패너는 어디 있는 거야?",
        ["O"] =
        "먼지진흙 습지대의 비질의 추락지 근처에 있는 점액들로부터 비질 링크스패너에게 무슨 일이 일어났는지 짐작할 수 있는 단서를 수집하십시오.",
        ["D"] =
        "비행선에서 제 임무는 간단합니다. 늪지대 위를 날아갈 때 용을 주시하는 거죠. 막 근무를 서기 시작했는데, 다음 순간 엄청난 굉음이 들리더니 상자가 내 머리를 강타했어요! 순식간에 기절했죠.\n\n선원 중 나만 의식을 되찾았을지도 모르겠어요. 그리고 비질 링크스패너 선장님은 어디서도 찾을 수 없고요! 근처의 점액들이 자신들을 감쌀 수 있는 것은 뭐든 집어삼키고 있으니 선장님에게로 향하는 단서를 가지고 있을지도 모릅니다. 녀석들을 잡아서 찾은 것을 내게 가져다주세요.",
    },
    [27296] = {
        ["T"] = "물품 챙기기",
        ["O"] = "비질의 추락지 주변 지역에서 비행선 화물 8상자를 수집하십시오.",
        ["D"] =
        "선장을 찾은 다음 회사의 가장 높은 우선순위는 자산을 회수하는 겁니다! 추락에서 살아남고 빌어먹을 점액에게 흡수되지 않은 모든 것은 우리 것이고, 우린 그걸 되찾아야 해요.\n\n이 재난에서 적어도 약간의 이익이라도 건져야 합니다. 흩어져 있는 살아남은 화물들을 모아주세요, $n.",
    },
    [27297] = {
        ["T"] = "제세동기 작동",
        ["O"] = "선원 6명에게 전기 충격을 가해 비행선에서 무슨 일이 일어났을지 모를 상황에 대해 더 많은 정보를 알아내십시오.",
        ["D"] =
        "이제 나머지 선원들을 도와야 해요. 보아하니, 그들의 의료비가 유족에게 지급될 사망 보험금보다 더 나올 것 같네요. 하지만... 이 상자들을 늪 밖으로 운반하려면 그들의 도움이 필요해요.\n\n이 제세동기를 가져가서 그들을 깨워주세요. 하는 김에 비질이 어디로 갔는지에 대한 정보가 있는지도 알아보고요. 심장에 바로 한 번 강하게 펄스를 가하면 될 겁니다.",
    },
    [27298] = {
        ["T"] = "마크 4 냄새탐지기",
        ["O"] = "톱니항에 있는 가즈로에게 가서 키스의 마크 4 냄새탐지기에 대해 문의하십시오.",
        ["D"] =
        "이 작전은 점점 더 비용이 많이 들고 있어요. 우리 상사는 이걸 좋아하지 않을 테고, 난 비질의 실수에 대해 뒤집어쓸 생각 없어요!\n\n당신이 찾은 망토를 사용해 그를 추적할 순 있지만, 기술적인 도움이 좀 필요할 겁니다. 톱니항에 있는 가즈로에게 가서 내가 맡겨둔 마크 4 냄새탐지기 키트가 있는지 물어보세요.\n\n훌륭한 고블린 기술을 사용해서 비질을 찾을 겁니다.",
    },
    [27299] = {
        ["T"] = "그를 찾아내라",
        ["O"] = "마크 4 냄새탐지기 컨트롤러를 사용하여 냄새탐지기를 소환하십시오. 그것이 당신을 비질에게 안내할 것입니다.",
        ["D"] =
        "이 냄새탐지기와 당신이 찾은 망토로 비질을 찾을 수 있어요. 냄새탐지기를 꺼내면 망토 냄새를 맡고 당신을 이끌고 출발할 겁니다. 목숨을 걸고 이 장치를 지키세요. 당장 교체할 장치가 없으니까요!\n\n선장을 찾아서 내게 무사히 데려와 주세요.",
    },
    [27300] = {
        ["T"] = "비질과 불타는 칼날단",
        ["O"] = "키스 크래프트차지에게 돌아가 비질 링크스패너에 대한 정보를 전하십시오.",
        ["D"] =
        "네가 방금 저 불지옥 정령으로부터 내 목숨을 구해주지 않았다면, 아무 말도 안 했을 거야. 하지만 그만큼 빚을 졌고, 내 안의 어떤 부분은 내가 이 상황을 수습할 수 있을 거라고 생각하거든.\n\n그래, 불타는 칼날단이 나를 고용해서 거대한 불지옥 정령을 스팀휘들 항구로 수송하게 했어. 그곳에서 뭘 하려는진 모르겠지만, 좋은 일은 아닐 게 뻔하지. 다행히 그들이 선불로 돈을 줬어. 무슨 일이 있었는지 그들에게 알려야겠지만, 걱정 마. 내 소매에 작은 보험을 숨겨뒀으니까.\n\n나중에 보자, 얼간이!",
    },
    [27301] = {
        ["T"] = "불타는 칼날단 서류",
        ["O"] = "키스 크래프트차지의 보고서를 담쟁이 마을에 있는 정찰병 가크에게 가져가십시오.",
        ["D"] =
        "그러니까 비질이 회사 몰래 불타는 칼날단과 일하고 있었다고요? 이런 쥐새끼 같은 놈!\n\n이 문제는 이제 회사의 자원 관리 소홀보다 더 커졌습니다. 내 보고서의 사본을 당신의 상관에게 가져가는 것이 현명할 것 같습니다. 칼날단이 어느 정도까지 손을 뻗쳤는지 그들도 알고 싶어 할 겁니다.",
    },
    [27302] = {
        ["T"] = "불타는 칼날단 서류",
        ["O"] = "키스 크래프트차지의 보고서를 테라모어에 있는 순찰대원 윌리스에게 가져가십시오.",
        ["D"] =
        "그러니까 비질이 회사 몰래 불타는 칼날단과 일하고 있었다고요? 이런 쥐새끼 같은 놈! 내 보고서의 사본을 당신의 상관에게 가져가는 것이 현명할 것 같습니다. 칼날단이 어느 정도까지 손을 뻗쳤는지 그들도 알고 싶어 할 겁니다.",
    },
    [27303] = {
        ["T"] = "오염 억제",
        ["O"] =
        "지옥물 정화기를 피멍울 폭포에 있는 호수로 가져가 설치하십시오. 그런 다음 악령숲의 에메랄드 성소에 있는 아이비 리프러너에게 돌아가십시오.",
        ["D"] =
        "반갑습니다, $C. 악령숲을 뒤틀어 놓은 사악한 악마의 타락으로 인한 피해를 복구할 수 있을지는 아직 불확실하지만, 퍼지는 것을 막기 위한 조치를 취할 수는 있습니다.\n\n오염된 점액들이 어둠해안으로 흘러드는 피멍울 강기슭에서 번식하고 있습니다. 오염 물질이 강 하류로 퍼져 타락시킬까 봐 걱정입니다. 다행히 우리의 고블린 친구 중 한 명이 강의 수원을 정화하는 데 도움이 될 정화기를 만들어 주었습니다.\n\n이 정화기를 피멍울 폭포 호수의 부두로 가져가서 던져 넣으십시오. 효과가 있는 것 같으면 내게 알려주십시오.",
    },
    [27304] = {
        ["T"] = "오염 억제",
        ["O"] =
        "악령숲의 불벼락 골짜기 근처를 배회하는 지옥의 호위병에게서 불타는 정령 핵을 획득하여 에메랄드 성소에 있는 아이비 리프러너에게 가져가십시오.",
        ["D"] =
        "$N, 좋은 생각이 있습니다. 우리가 호수에서 거대한 점액을 유인해 내 파괴하려면 녀석을 유혹할 무언가를 찾아야 합니다.\n\n점액들은 악마의 타락에서 태어났고 그것을 먹고 더 크게 자랍니다. 강력한 악마 에너지원을 수확한다면, 그것을 사용하여 호수에서 점액을 유인해 낼 수 있을 거라고 생각합니다.\n\n이것은 위험한 임무입니다. 그런 강력한 에너지원을 구할 수 있는 곳으로 제가 떠올릴 수 있는 유일한 곳은 불벼락 골짜기 근처를 배회하는 지옥의 호위병의 핵뿐입니다. 혼자 시도하고 싶진 않을 겁니다.\n\n행운을 빕니다, 엘룬이 당신과 함께하시길.",
    },
    [27305] = {
        ["T"] = "오염 억제",
        ["O"] = "흉측한 어미점액괴물을 피멍울 폭포 밖으로 유인하여 파괴하십시오.",
        ["D"] =
        "여기, $N. 핵을 가져다가 당신이 사용할 미끼로 만들었습니다. 주의하십시오, 이것을 활성화하자마자 어미점액괴물이 당신에게 곧장 다가올 것이 확실합니다!\n\n그것이 파괴되면 피멍울 강의 타락이 줄어들기 시작할 거라고 장담합니다. 만약을 대비해 정화기를 수리하는 작업은 계속하겠지만, 당신의 노력이 성공한다면 어쩌면 정화기가 필요 없을지도 모릅니다!",
    },
    [27306] = {
        ["T"] = "비취불꽃 숲의 정원",
        ["O"] =
        "비취불꽃 사티로스와 지옥의 추종자들을 처치하여 켈레크 스카이키퍼의 정원 도구를 회수하고, 악령숲의 에메랄드 성소에 있는 그에게 돌려주십시오.",
        ["D"] =
        "군단이 오기 전, 나는 비취불꽃 숲에서 많은 시간을 보내며 빛나는 정원을 가꾸었소. 슬프게도 그 평화로운 안식처를 짓기 위해 쏟았던 수년간의 경작과 노력의 흔적은 아무것도 남지 않았지.\n\n지금 내 옛 정원에 살고 있는 비취불꽃 악마들은 자신들의 더러운 손에 닿는 조각은 무엇이든 모아두는 짐꾼으로 알려져 있소. 그게 그들이 내 도구를 가지고 있다는 뜻이길 바라며, 그걸 되찾을 수 있다면 무엇이든 주겠소.\n난 전사는 아니지만, 내 도구를 되찾아 준다면 넉넉히 보상하겠소. 특히 그곳에 있는 모든 악마를 처치하는 것이라면 더더욱!",
    },
    [27307] = {
        ["T"] = "기만자의 성소",
        ["O"] =
        "기만자의 성소에 보관되어 있는 살게라스, 티콘드리우스, 킬제덴, 아키몬드의 기념품을 회수하여 악령숲의 에메랄드 성소에 있는 파수꾼 스틸송에게 가져가십시오.",
        ["D"] =
        "반갑습니다 $C. 내 이름은 벨라 스틸송이고 파수꾼입니다. 아니, 적어도 그렇게 되기를 희망합니다. 사실 저는 아직 훈련 중입니다.\n\n제데나르를 점령한 악마 세력을 조사하기 위해 이곳에 파견되었습니다. 이 이교도들이 불타는 군단이 악령숲을 지나갈 때 남긴 기념품들을 수집하여 제데나르 내의 기만자의 성소에 보관하고 있다는 것을 알아냈습니다.\n\n그들에게서 이 기념품들을 빼앗는 것은 그들이 군단에 헌신한다는 강력한 상징을 제거하는 것이 될 것입니다.\n\n저는 그들과 직접 교전해서는 안 되고, 첫 번째 임무에서 명령에 불복종하고 싶지 않습니다. 하지만 당신이 제 대리인으로서 이 유물들을 회수해 주신다면 정말 감사하겠습니다.",
    },
    [27308] = {
        ["T"] = "3차 대전쟁의 기념품",
        ["O"] = "소름 끼치는 기념품 상자를 다르나서스의 달의 신전에 있는 티란데 위스퍼윈드에게 가져가십시오.",
        ["D"] =
        "이곳에 와주셔서 기뻐요 $N. 이 아이템들을 살펴보니 예상했던 것보다 훨씬 더 소름 끼치네요. 이것들은 군단이 하이잘로 향하며 앗아간 희생자 일부의 두개골이에요.\n\n이교도들은 두개골에 그들의 이름을 표시해 두었어요. 비록 그들의 희생자에 대해서는 아는 바가 없지만, 세계수를 지킨 영웅들로서 최고의 예우를 갖춰 적절히 매장되어야 마땅해요.\n\n이 전리품들을 다르나서스에 있는 엘룬의 대여사제 티란데 위스퍼윈드에게 가져가 주세요. 다음에 어떻게 해야 할지 결정하는 데 그녀의 판단을 믿습니다.",
    },
    [27309] = {
        ["T"] = "3차 대전쟁의 기념품",
        ["O"] = "소름 끼치는 기념품 상자를 오그리마의 지혜의 골짜기에 있는 스랄에게 가져가십시오.",
        ["D"] =
        "이곳에 와주셔서 기뻐요 $N. 이 아이템들을 살펴보니 예상했던 것보다 훨씬 더 소름 끼치네요. 이것들은 군단이 하이잘로 향하며 앗아간 희생자 일부의 두개골이에요.\n\n이교도들은 두개골에 그들의 이름을 표시해 두었어요. 비록 그들의 희생자에 대해서는 아는 바가 없지만, 세계수를 지킨 영웅들로서 최고의 예우를 갖춰 적절히 매장되어야 마땅해요.\n\n이 전리품들을 호드의 대족장이자 전쟁의 승리자 중 한 명인 스랄에게 가져가 주세요. 다음에 어떻게 해야 할지 결정하는 데 그의 판단을 믿습니다.",
    },
    [27310] = {
        ["T"] = "현상 수배: 칼알라쉬",
        ["O"] = "강철나무 숲에서 칼알라쉬를 찾아 그의 고통을 끝내십시오.",
        ["D"] =
        "이 숲은 3차 대전쟁 이후 우리가 잃은 것에 대한 고통스러운 알림이라네, $N. 군단이 학살하지 않은 야생동물은 악령숲의 악마 타락으로 인해 미쳐버렸지.\n\n거대한 키메라 칼알라쉬와 그의 자식들은 군단이 공격했을 때 가장 먼저 악령숲을 보호했어. 슬프게도 그의 무리 전체가 악마들과의 전투에서 쓰러졌고, 그는 홀로 남아 끔찍한 지옥 마법에 오염되고 말았지. 이제 그 거대한 키메라에게 남은 것이라곤 대전투로 상처 입고 슬픔에 휩싸인 채 강철나무 숲을 배회하는 것뿐이야.\n\n저주받은 숲에 혼자 발을 들여놓는 것은 권하지 않네만, 혹시라도 칼알라쉬를 직접 마주치게 된다면... 부디 그의 고통을 끝내주게. 내가 부탁하는 건 그것뿐이네.",
    },
    [27311] = {
        ["T"] = "현상 수배: 칼알라쉬",
        ["O"] = "강철나무 숲으로 모험을 떠나 사악한 키메라 칼알라쉬를 처치하십시오.",
        ["D"] =
        "3차 대전쟁 이후 이 숲에서 키메라가 멸종되었다고 생각했을지도 모르지만 $C, 아직 한 마리가 강철나무 숲을 배회하고 있소. 엘프들은 그것을 \"칼알라쉬\"라고 부르지.\n\n나와 내 사냥 파트너가 그것을 생포하려 했지만, 지옥불에 미친 듯 날뛰는 날개 달린 공포, 지옥불과 맹독을 뿜어내는 쌍둥이 아가리와 마주쳤을 뿐이오. 나는 간신히 목숨을 건져 도망쳤지만, 내 파트너는... 그는 그렇게 운이 좋지 않았소.\n\n다시는 그 짐승과 엮일 엄두가 나지 않지만, 녀석을 쓰러뜨릴 수 있는 자에게는 보상하겠소.",
    },
    [27312] = {
        ["T"] = "고르두니 도둑들",
        ["O"] = "페랄라스에 있는 고르두니 오우거들로부터 모자케 야영지 보급품 10개를 수집하십시오.",
        ["D"] =
        "불모의 땅 도로에 문제가 생겨 이곳 모자케 야영지로 보급품이 전달되는 것도 충분히 힘든데, 페랄라스로 무사히 들어온 제한된 상자들마저 고르두니 오우거들이 훔쳐가고 있습니다.\n\n우리가 최저 수준으로 운영되지 않도록 저 도둑들에게서 상자 몇 개를 되찾아 주실 수 있습니까? 강을 따라 북쪽으로 가면 그들의 전초기지를 찾을 수 있을 겁니다.",
    },
    [27313] = {
        ["T"] = "고기!",
        ["O"] = "글루크의 영지(Gluk's Compound)에 있는 멕넬을 위해 무쇠가죽 고기와 유인원 고기를 수집하십시오.",
        ["D"] =
        "보급품이 바닥나고 있어! 글루크의 집행자들을 먹여 살리려면 많이 필요하다고! 우리가 더 필요해! 도와줄래?\n\n어린 무쇠가죽곰의 고기가 가장 맛있으니까, 녀석들을 잡아와! 그리고 그로독도 단맛이 나, 난 그게 아주 좋아! 가서 잡아와, 녀석들은 근처에 있어.",
    },
    [27314] = {
        ["T"] = "모든 생물에게 자유를",
        ["O"] =
        "대나무 우리 열쇠를 사용하여 그림토템 야영지의 우리에서 화살요정용을 풀어주십시오. 최소 6마리의 화살요정용과 루유아 어스문이 생존해야 합니다.\n\n루유아가 후퇴할 시간이라고 결정하기 전까지 6분의 시간이 주어지며, 실패 시 퀘스트에 실패합니다.",
        ["D"] =
        "더러운 그림토템 부족이 요정용을 잡아가고 있습니다, $N. 오르도와 저는 그들이 용을 가지고 무슨 짓을 할 계획인지 전혀 모르지만, 분명히 좋은 일은 아닐 겁니다.\n\n우리는 야영지에 쳐들어가 포획된 용들을 풀어줄 만큼 강하지 않지만, 아마도 당신의 도움이 있다면... 우리가 무언가를 할 수 있을 겁니다.\n\n기꺼이 도와주실 의향이 있고 강한 친구들이 있다면, 이 열쇠로 우리에서 생물들을 풀어주고 그들이 목숨을 건져 탈출할 수 있도록 해주세요. 저는 내내 당신 곁에 있을 겁니다. 오르도는 여기에 남을 거고요.",
    },
    [27315] = {
        ["T"] = "정의의 분배",
        ["O"] =
        "그림토템 자연주의자 12명, 그림토템 약탈자 10명, 그림토템 주술사 6명을 처치한 후 페랄라스에 있는 오르도 어스문에게 돌아가십시오.",
        ["D"] =
        "그녀가 이미 말했듯이, 루유아와 나는 이제 그림토템과 싸울 것입니다. 우리가 함께라면 여전히 큰 위협 없이 그림토템 중 일부를 처치할 수 있겠지만, 당신이 기꺼이 할 수 있다면 약간의 도움을 받고 싶습니다.\n\n우리 아래에 있는 야영지를 보셨겠지만, 동쪽으로 가면 더 있습니다. 당신만의 전술을 사용하여 타우렌에게 가능한 한 많은 피해를 주십시오. 그들이 루유아의 화살과 당신의 무기의 매운맛을 본 후에 우리는 모두 여기로 다시 모일 수 있습니다.",
    },
    [27316] = {
        ["T"] = "정의의 분배",
        ["O"] = "썬더 블러프에 있는 대드루이드 하뮬 룬토템에게 오르도의 인장 반지를 가져가십시오.",
        ["D"] =
        "이 황야에서 루유아와 저는 당신의 도움에 보답할 수단이 변변치 않지만, 당신이 인정받지 못한다고 느끼게 하고 싶지는 않습니다. 내 인장 반지를 가져가십시오. 썬더 블러프의 봉우리에 가게 된다면, 장로의 봉우리로 가십시오. 그곳에서 대드루이드 하뮬 룬토템을 찾을 수 있을 것입니다. 이 반지는 우리가 잘 있다는 것을 알리고 당신의 이야기에 신빙성을 더해 줄 것입니다.\n\n우리 두 사람 모두 당신에게 감사드립니다, $N.",
    },
    [27317] = {
        ["T"] = "집을 찾는 고아",
        ["O"] = "버섯구름 봉우리의 신기루 경주장에 있는 하산 헤비우드와 대화하십시오.",
        ["D"] =
        "오, 안녕하세요, $N. 다시 뵙게 되어 정말 기쁩니다. 썬더 블러프에서의 여행은 어땠나요?\n\n글쎄요, 당신이 떠난 사이에 우리가 꽤 많은 진전을 이뤘다는 걸 알면 기뻐하실 겁니다. 심지어 알이 가득 찬 둥지를 구하기도 했어요. 불행히도, 우리가 도착하기 전에 어미가 죽어버렸지만요.\n\n있잖아요, 애완용으로 하나 키워보실 생각 없나요? 곧 부화할 것 같으니 좋은 $g아빠:엄마;가 필요할 거예요. 어때요?\n\n정말 관심이 있다면, 알 하나를 소금 평원의 경주장에 있는 하산 헤비우드에게 가져가 보세요. 그가 더 자세히 알려줄 겁니다.",
    },
    [27318] = {
        ["T"] = "짧은 부화기",
        ["O"] = "버섯구름 봉우리에 있는 하산 헤비우드에게 인내의 비약 2개를 가져가십시오.",
        ["D"] =
        "어스문 가, 맞죠? 아주 흥미롭군요. 화살요정용들이 그 두 사람이 그들을 돌본다는 게 어떤 의미인지 진정으로 이해할 수 있었으면 좋겠어요. 둘 다 아주 유능한 사람들이죠.\n\n그래서, 그들이 알을 선물로 줬다고요. 그렇다면 알이 필요한 만큼 당신이 책임져야겠네요. 거의 부화할 준비가 된 것 같지만, 건강하고 손상이 가지 않도록 확실히 해야 합니다.\n\n알을 보호할 작은 주문을 위해 인내의 비약 두 개만 있으면 됩니다. 나머지 재료는 제가 여기에 가지고 있습니다.",
    },
    [27319] = {
        ["T"] = "가족의 새로운 구성원",
        ["O"] =
        "깨지기 쉬운 화살요정용 알을 동부내륙지로 가져가 사냥꾼 마코르와 대화하십시오. 하지만 서두르십시오. 알 안의 새끼가 죽기 전에 그를 찾을 수 있는 시간은 1시간뿐입니다.",
        ["D"] =
        "놀라운 표본이군요, $N. 이 생물이 잉태 기간을 살아남는다면 참으로 건강한 애완동물이 될 것입니다!\n\n이 일을 끝까지 해낼 생각이라면 제가 제안하고 싶은 마지막 한 가지가 있습니다. 동부내륙지의 깨진엄니 마을로 가십시오. 그곳에서 사냥꾼 마코르라는 트롤과 대화하십시오. 그는 마스터 동물 조련사이며 부화의 마지막 단계에서 당신을 안내할 수 있을 것입니다.\n\n하지만 서두르십시오, $N. 이 알은 깨지기 쉽고 적절한 보살핌 없이는 오래 버티지 못할 것입니다.",
    },
    [27320] = {
        ["T"] = "아기를 위한 식량",
        ["O"] = "동부내륙지에 있는 사냥꾼 마코르에게 긴발톱 은빛갈기늑대 옆구리살 5개를 가져가십시오.",
        ["D"] =
        "화살요정용은 잡식성이야 -- 즉 고기와 식물을 모두 먹는다는 거지. 알이 부화하려면 미리 준비하는 게 좋을 거야. 이 꼬마 녀석들에게 좋은 먹이는 날것의 즙이 많은 옆구리 고기지, 믿기지 않겠지만. 이유는 한 번도 알아내지 못했지만, 엘프를 향한 엘룬의 계획과 관련이 있을 거야... 어쩌면 수호자나 뭐 그런 존재가 될 예정이었는지도 모르지.\n\n일단 알은 내가 돌볼 테니, 부화하면 먹일 수 있게 맛있는 긴발톱 은빛갈기늑대 옆구리살을 좀 구해다 주는 게 어때.",
    },
    [27321] = {
        ["T"] = "부모가 되기",
        ["O"] = "동부내륙지에 있는 사냥꾼 마코르와 대화하십시오.",
        ["D"] = "이런, 생각했던 것보다 훨씬 더 준비가 되어 있었군...!",
    },
    [27322] = {
        ["T"] = "부정하는 자 설득하기",
        ["O"] =
        "글루크의 영지(Gluk's Compound) 북서쪽의 까마귀바람 폐허 근처에서 발견되는 하피들로부터 깨진 거울 조각을 수집하십시오.",
        ["D"] =
        "나 즈랄. 나 도움 필요해. 내 친구 트로그, 걔 죽었는데 자기가 죽은 거 몰라. 살아있는 것처럼 걸어 다녀. 난 걔가 평화 찾았으면 좋겠어. 까마귀바람 폐허 하피들 거울 조각 좋아한다고 들었어. 걔들 허영심 많아서 맨날 자기 모습만 봐. 가서 좀 구해다 줄래? 내가 돈 많이 줄게. 나 좀 도와줘, 친구.",
    },
    [27323] = {
        ["T"] = "죽음의 반영",
        ["O"] = "트로그에게 그가 죽었다는 것을 증명하기 위해 그의 모습이 비친 거울을 보여주십시오.",
        ["D"] =
        "전에 나 도와줬지, 고마워. 이제 도움 더 필요해. 네가 가져온 조각으로 나 거울 만들어. 네가 그거 트로그한테 가져가서 비춰 보여주면 좋겠어. 자기가 죽은 거 보면 평화 찾을 거야. 나 위해 이 일 해줄래, 친구?",
    },
    [27324] = {
        ["T"] = "죽어서 사라진",
        ["O"] = "트로그가 죽은 장소에 대한 정보를 얻기 위해 글루크의 영지 주변을 탐문하십시오.",
        ["D"] =
        "트로그 자기 죽은 거 안 믿어, 자기 몸 봐야 해. 네가 걔 어디서 죽었는지 알아내는 거 도와줘. 집행자들, 멕넬, 가크한테 가서 물어봐. 걔들은 아는 거 있어. 정보 가져오면 내가 돈 줄게.",
    },
    [27325] = {
        ["T"] = "치과 기록",
        ["O"] = "글루크의 영지 북쪽 지역에서 우두머리 무쇠가죽곰의 이빨을 수집하십시오.",
        ["D"] =
        "네가 가서 우두머리 무쇠가죽곰 이빨 좀 찾아왔으면 해. 내 생각엔 트로그가 이빨 보면 자기가 어떻게 죽었는지 기억할지도 몰라. 네가 가서 이빨 찾아서 나한테 가져와. 우리 트로그한테 보여주자, 그럼 걔가 기억하고 자기가 죽은 거 알지도 몰라. 지금 가. 서둘러!",
    },
    [27326] = {
        ["T"] = "치과 기록",
        ["O"] = "수집한 이빨을 트로그에게 보여주어 그가 살해당했던 것을 기억하는지 확인하십시오.",
        ["D"] =
        "이빨 가져왔네, 잘했어. 이제, 네가 가서 트로그한테 보여줬으면 해. 내 생각엔 걔가 이빨 보면 어떻게 죽었는지 기억할지도 몰라. 트로그한테 가서 이빨 보여주고, 걔가 기억하는지 봐봐. 서둘러, 트로그가 편히 쉴 수 있게 빨리 알아야 해.",
    },
    [27327] = {
        ["T"] = "치과 기록",
        ["O"] = "쌍둥이 바위산 근처의 글루크의 영지 북쪽에서 발견되는 덩치 큰 무쇠설인에게서 이빨을 수집하십시오.",
        ["D"] =
        "내 생각엔 야영지 북쪽 동굴에 있는 덩치 큰 무쇠설인들, 걔네들 크고 세. 네가 가서 걔네들 이빨 좀 가져오면 좋겠어, 트로그가 알아보고 드디어 이해하길 바라. 지금 가서 이빨 가져와, 트로그가 편히 쉴 수 있게 도와줘.",
    },
    [27328] = {
        ["T"] = "치과 기록",
        ["O"] = "수집한 이빨을 트로그에게 보여주어 그가 살해당했던 것을 기억하는지 확인하십시오.",
        ["D"] = "네가 가서 큰 이빨 트로그한테 보여주길 원해. 걔가 이빨 기억하길 바라, 지금 가!",
    },
    [27329] = {
        ["T"] = "치과 기록",
        ["O"] = "쌍둥이 바위산 근처의 글루크의 영지 북쪽에서 발견되는 그로독 천둥발구르개에게서 이빨을 수집하십시오.",
        ["D"] =
        "나, 즈랄, 그리고 트로그, 우리 오래전에 사냥 갔어. 우린 크고 못된 그로독 만났어. 걔들 이빨 컸어, 크고 못된 이빨. 우리 빨리 도망쳤는데, 즈랄은 그 이빨 기억해. 이제, 난 그 이빨이 트로그 죽였다고 생각해. 네가 가서 그로독한테서 그 이빨 좀 가져오면 좋겠어. 가져오면, 우리 트로그한테 보여주자, 그럼 걔가 기억할지도 몰라.",
