    [27330] = {
        ["T"] = "치과 기록",
        ["O"] = "수집한 이빨을 트로그에게 보여주어 그가 살해당했던 것을 기억하는지 확인하십시오.",
        ["D"] = "어쩌면 이거일지도 몰라? 가서 트로그한테 그로독 이빨 보여줘. 내 돌 다 걸고 걔가 이제 기억할 거야.",
    },
    [27331] = {
        ["T"] = "호기심 많은 그로독",
        ["O"] = "텔아빔 바나나 한 상자를 수집하십시오.",
        ["D"] =
        "그로독! 그로독은 가만두면 보통 착해. 트로그를 다 먹진 않았을 거야. 그로독 바나나 좋아해. 우리가 바나나 주면 걔네가 착해져서 길 알려줄지도 몰라?\n\n비고는 우리랑 안 나누는 비싼 과일 많이 먹어. 걔한테 바나나 달라고 해볼까?",
    },
    [27332] = {
        ["T"] = "호기심 많은 그로독",
        ["O"] = "쌍둥이 바위산의 그로독 천둥발구르개에게 텔아빔 바나나를 던져 트로그의 시체를 찾으십시오.",
        ["D"] =
        "우리 아까 이빨 구하려고 그로독 죽였지... 이 바나나로 걔네 마음 달래서, 평소에 먹이 먹는 곳을 알려줬으면 좋겠어. 가서 해봐!",
    },
    [27333] = {
        ["T"] = "자신을 직면하다",
        ["O"] = "트로그의 머리를 글루크의 영지에 있는 즈랄에게 가져가십시오.",
        ["D"] =
        "몸통은 거의 남아 있지 않지만, 근처에 굴러다니는 머리는 멀쩡합니다. 근처의 짐승들이 먹기에는 너무 징그러웠던 걸까요?\n\n이 머리를 글루크의 영지에 있는 즈랄에게 가져가야 합니다.",
    },
    [27334] = {
        ["T"] = "자신을 직면하다",
        ["O"] = "트로그에게 그가 죽었다는 것을 증명하십시오.",
        ["D"] = "이걸 보고도 트로그가 자기가 죽었다는 걸 안 믿을 리가 없어. 네가 나 대신 걔한테 보여줄래?",
    },
    [27335] = {
        ["T"] = "현상 수배: 길 잃은 고대정령",
        ["O"] = "길 잃은 고대정령을 찾아내 처치하고, 그 증거로 무거운 고대 통나무를 수집하십시오.",
        ["D"] =
        "곧 왕이 될 글루크의, 군대를 강화할 무기에 대한 요구는 끝이 없으며, 우리는 매우 튼튼한 나무가 많이 필요할 거다.\n\n길 잃은 고대정령이 야영지 남쪽을 배회하며 모험가와 오우거들을 마구잡이로 해치우는 것이 목격되었다. 내 대신 녀석을 처치하면 두둑이 보상하겠다.\n\n-- 비고",
    },
    [27336] = {
        ["T"] = "악몽의 정수",
        ["O"] = "스톰레이지 지하굴에 있는 선조의 악몽으로부터 악몽의 정수 샘플 10개를 수집하여 달숲에 있는 시라 문워든에게 가져가십시오.",
        ["D"] =
        "달숲은 평화로워 보일지 모르지만, $c, 나는 그 고요한 겉모습 아래 숨어 있는 무언가를 느낍니다.\n\n사령관 스톰러너는 당신이 지하굴에 있는 잠들지 못하는 영혼들을 진정시켜 주기를 원하지만, 저는 무엇이 그들을 괴롭히고 있는지에 더 관심이 있습니다. 첫 번째 영혼을 처치하고 나면 제가 무슨 뜻인지 알게 될 것입니다... 악몽이 구체화된 것을 말이죠.\n\n이 악몽들의 정수를 모아 제게 가져오십시오. 그러면 제가 더 조사할 수 있을 것입니다.",
    },
    [27337] = {
        ["T"] = "엘룬의 빛 안에서",
        ["O"] =
        "스톰레이지 지하굴의 가운데 차원문으로 들어가 칼도레이 영혼 10명의 영혼을 안식에 들게 하십시오. 영혼은 밤에만 보입니다. 이 임무를 완료하면 달숲의 스톰레이지 지하굴 밖으로 나가 사령관 세이나 스톰러너에게 돌아가십시오.",
        ["D"] =
        "$C, 명심하시오! 스톰레이지 지하굴은 고요함과 평화의 장소이며, 우리는 바보들이 우리의 신성한 땅을 모독하는 것을 용납하지 않을 것이오.\n\n보통은 외부인의 출입을 금하지만, 당신의 도움이 필요하오. 엘룬의 빛이 달숲을 비출 때, 우리 조상들의 영혼이 나타나기 시작했소. 비록 평온해 보이지만, 그들은 내면에서 억눌린 분노로 들끓고 있소.\n\n나는 매일 밤 내 동족을 거듭해서 처치하는 것을 견딜 수 없소. 당신이 이 영혼들을 대지로 돌려보내는 것을 도와준다면 감사하겠소.",
    },
    [27338] = {
        ["T"] = "스톰레이지 지하굴",
        ["O"] = "달숲의 스톰레이지 지하굴에 있는 사령관 세이나 스톰러너와 대화하십시오.",
        ["D"] =
        "유능한 $c인 것 같군. 우리 지하굴 감시자의 지도자인 사령관 세이나 스톰러너가 현재 엘룬아라 호수 남동쪽에 있는 스톰레이지 지하굴에 주둔하고 있네. 그녀는 긴급한 문제로 도움을 찾고 있지.\n\n밤의 안식처에서 나와 호수를 둘러싼 길을 따라가면 그녀를 찾을 수 있을 거야.",
    },
    [27339] = {
        ["T"] = "그림토템의 침략",
        ["O"] = "그림토템단 헥터 4명과 그림토템단 척후병 4명을 처치한 후 나라체 야영지의 그룰 호크윈드에게 보고하십시오.",
        ["D"] =
        "발밑을 조심하시오, 붉은구름 고원의 평화로운 거주민이여. 그림토템 부족원들이 우리 야영지를 떠나 동쪽에 자신들만의 정착지를 세웠소. 그들은 모든 타우렌의 필요를 고려하지 않고 오직 자신들만을 위해 대지에서 가져가고 있지. 우리가 모두 같은 태양 아래 있는 자녀일지라도, 그들이 이 신성한 고원을 모독하는 것을 막지는 못하오.\n\n우리의 외교적 노력은 거절당했고, 우리의 마지막 사절은 돌아오지 않았소. 선택의 여지가 없소: 그림토템을 붉은구름 고원에서 제거해야만 하오.",
    },
    [27340] = {
        ["T"] = "모네 찾기",
        ["O"] = "동쪽의 붉은구름 고원에 있는 그림토템 정착지로 향하는 모습이 마지막으로 목격된 모네 선메인을 찾으십시오.",
        ["D"] =
        "내 남편 모네가 너무 걱정돼요. 그는 고원에서의 남획을 멈춰달라고 그림토템 정착지에 있는 그들과 이야기하러 이틀 전에 떠났는데, 아직 돌아오지 않았어요.\n\n제발 가서 조사해 보고 그를 무사히 데려와 주세요. 뿔 끝의 황금색으로 그를 알아볼 수 있을 거예요.",
    },
    [27341] = {
        ["T"] = "모네 찾기",
        ["O"] = "단순한 녹색 펜던트를 붉은구름 고원의 카야 선메인에게 가져가십시오.",
        ["D"] =
        "쓰러진 타우렌의 목에 단순한 녹색 펜던트가 달린 목걸이가 걸려 있습니다. 이 자가 카야 선메인의 남편이라고 짐작하며, 이 펜던트를 붉은구름 고원으로 가져가기로 결정합니다.",
    },
    [27342] = {
        ["T"] = "놀 절도범",
        ["O"] = "블러드후프 마을 서쪽의 놀 동굴에서 납치된 타우렌 8명을 찾아내어 풀어주십시오.",
        ["D"] =
        "도움이 필요해, $c. 식량을 구하거나 아이들과 사냥을 나간 사람들이 실종되고 있어. 처음에는 몇 명뿐이었지만, 지금은 수십 명이 사라졌어.\n\n마을 서쪽 동굴에 있는 놀들이 그들을 잡아갔다는 소문이 퍼지고 있어.\n\n제발, 이 동굴을 조사해 줘! 우리 이웃들이 그곳에 갇혀 있다면, 우리에게 돌려보내 주길 바라.",
    },
    [27343] = {
        ["T"] = "수습 코도 타기",
        ["O"] = "카르 스톰싱어로부터 수습 타기를 배운 후, 멀고어에 있는 할브 클로후프와 대화하여 코도를 받으십시오.",
        ["D"] =
        "돌아온 걸 환영하오. 수습 타기를 배우러 왔군, 맞소? 이전과 마찬가지로 코도 가격은 지불되었지만 훈련 비용은 직접 내야 하오. 유감스럽지만 신속하게 타는 건 비싸다오.\n\n훈련을 받은 후 바로 옆에 있는 할브 클로후프와 얘기하시오. 그가 우리 짐승 판매를 관리하오. 아직 자금이 없다면 언제든지 다시 와도 좋소.",
    },
    [27344] = {
        ["T"] = "코도 타기",
        ["O"] = "카르 스톰싱어로부터 초급 타기를 배운 후, 멀고어에 있는 할브 클로후프와 대화하여 코도를 받으십시오.",
        ["D"] =
        "그래서 코도를 구하러 왔나 보군? 마침 당신을 기다리고 있었소! 수수께끼의 후원자가 기본 코도에 대한 대금을 남겼는데 당신 이름인 $N 앞으로 되어 있더군. 하지만 훈련 비용까지 내주진 않았으니 그건 당신이 지불해야 할 거요.\n\n훈련을 받은 후 바로 옆에 있는 할브 클로후프와 얘기하시오. 그가 우리 짐승 판매를 관리하오. 아직 자금이 없다면 나중에 다시 와도 좋소.",
    },
    [27345] = {
        ["T"] = "현자 레인토템",
        ["O"] = "멀고어 북동쪽의 붉은 바위 언덕 근처에서 현자 레인토템을 찾으십시오.",
        ["D"] =
        "내 부탁 하나 들어주겠소, $C?\n\n현자 레인토템이 어제 붉은 바위 언덕에 있는 신성한 매장지를 방문하러 떠났는데, 아직 돌아오지 않았다오. 그가 무사한지 확인해 주시겠소?\n\n썬더 블러프의 북쪽 승강기를 타고 동쪽으로 가면 붉은 바위 언덕을 찾을 수 있을 거요.",
    },
    [27346] = {
        ["T"] = "황소바위 오염",
        ["O"] = "벤처 투자회사 파편 10개를 블러드후프 마을에 있는 아가사 롱캐스트에게 가져가십시오.",
        ["D"] =
        "황소바위 호수의 신성한 샘은 수 세기 동안 우리에게 영양을 공급해 주었죠. 그것은 말 그대로 멀고어의 생명의 원천이자 대지모신의 축복받은 성배입니다.\n\n$C, 지금 이 호수를 보세요! 정제된 금속 조각, 파편, 심지어 제 남편조차 만지기 두려워하는 어떤 기름진 물질까지... 그는 금속 볼트가 뱃속에 있는 메기를 잡기도 했어요!\n\n벤처 투자회사는 이익을 위해 멀고어를 파괴하고, 우리 민족에게 매우 신성한 선물을 더럽혀 그 무덤 속에 우리를 묻으려 하고 있어요.\n\n제발, 호수를 조금이라도 청소해서 저를 도와주실 수 있나요? 쓰레기의 대부분은 북동쪽 해안에 가장 가깝게 모여 있습니다.",
    },
    [27347] = {
        ["T"] = "절대 응고-늦은 게 아닙니다.",
        ["O"] = "노움식 혈액응고기를 회수하여 황소바위 호수를 정화하는 데 사용하십시오. 완료 후 아가사 롱캐스트에게 돌아가십시오.",
        ["D"] =
        "잠깐, 얼굴에 묻은 게 뭐죠? 아, 그 더러운 기름이군요. 독성이 없다고 생각하고 싶지만, 물과 토양을 모두 오염시킬까 두렵네요.\n\n블러드후프 마을의 한 사냥꾼이 벤처 투자회사의 일꾼과 감독관 중 일부가 북동쪽에 있는 광산의 기름 오염을 정화하는 데 사용하는 이상한 장치에 대해 언급했어요.\n\n그것을 회수해 보세요. 그들이 그곳의 오염을 중화시킬 수 있다면, 황소바위 호수에도 똑같이 할 수 있을 거예요.",
    },
    [27348] = {
        ["T"] = "약탈자들을 저지하라",
        ["O"] = "바엘 모단 감정사를 처치하고 그들이 지닌 고대 타우렌 유물을 수집하십시오. 6개를 모아 썬더 블러프의 정기의 봉우리에 있는 포위 미스트러너에게 가져가십시오.",
        ["D"] =
        "반갑소, $C. 마을 아래에 있는 블레인 블러드후프와 대화해 보았소? 그는 멀고어 서쪽에 있는 바엘 모단이라는 드워프 발굴 현장으로 가서 그들의 채굴을 막아줄 사람을 찾고 있다오.\n\n블레인의 목적은 이해할 만하지만, 때로는 역사를 발굴하기 위해 파헤쳐야 할 때도 있는 법이지. 이미 피해가 발생한 이상, 난 당신이 그 상황을 최대한 활용해 주기를 바라오. 발굴 현장의 감정사들은 그곳에서 발견된 유물들을 지니고 다니지. 우리가 연구할 수 있도록 그 유물들을 수집해 주었으면 하오.",
    },
    [27349] = {
        ["T"] = "약탈자들을 저지하라",
        ["O"] = "멀고어 남동쪽에 있는 벤처 투자회사 광산의 직원들로부터 고대 유물 8개를 회수하십시오.",
        ["D"] =
        "멀고어에서 우리의 역사를 침해하는 자들은 드워프만이 아닙니다. 벤처 투자회사가 멀고어 남동쪽에 광산을 열었어요. 그들은 오직 약탈할 수 있는 자원만을 위해 이곳에 왔고, 그들의 무모한 행동으로 파괴하고 있는 역사에 대해서는 전혀 신경 쓰지 않죠!\n\n광산 일꾼들이 발견한 고대 물건들을 개인적으로 챙기고 있다는 걸 알아요. 그런 유물들은 탐욕스러운 고블린의 주머니를 채우기보다는 타우렌과 함께 여기에 남아있는 것이 더 낫습니다. 제발, 광산으로 가서 그것들을 회수해 주세요!",
    },
    [27350] = {
        ["T"] = "길 잃은 송아지",
        ["O"] = "블러드후프 마을에서 길 잃은 코도 송아지의 주인을 찾으십시오.",
        ["D"] =
        "미친 듯이 날뛰는 코도 송아지의 목에 손상된 목걸이가 걸려 있는 것을 발견합니다. 목걸이에는 주인의 신원이 닳아서 지워져 있습니다.\n\n갑자기 코도 송아지가 도망쳐버리고, 당신 손에는 목걸이만 남습니다. 블러드후프 마을의 누군가가 주인일지도 모릅니다. 당신이 발견한 것을 알리기 위해 그들을 찾으십시오.",
    },
    [27351] = {
        ["T"] = "길 잃은 송아지",
        ["O"] = "멀고어 평야의 타조와 독수리들로부터 물고지 딸기 8개를 수집하십시오.",
        ["D"] =
        "그 작은 말썽꾸러기! 정말 아끼지만 불순종이 점점 골칫거리가 되고 있어요.\n\n당신이 찾은 송아지는 오독입니다. 어미가 죽은 후부터 제가 돌보고 있는데, 아직 스스로를 돌볼 만큼 크지 않았거든요. 평원에 혼자 있다니 정말 걱정돼요! 무사히 데려와야 해요.\n\n녀석을 유인할 수 있는 특별히 좋아하는 간식이 있는데, 그걸 만들려면 당신이 재료를 좀 모아주셔야 해요.\n\n마을 북쪽의 독수리와 타조들은 위장에서 현지 물고지 딸기를 발효시키는데, 왠지 오독은 그 맛을 아주 좋아해요. 이 딸기를 좀 가져다주시면 유인할 먹이를 만들어 볼게요.",
    },
    [27352] = {
        ["T"] = "길 잃은 송아지",
        ["O"] = "황소바위 호수의 호수 농어로부터 농어 퓌레를 수집하십시오.",
        ["D"] =
        "그게 역겹다고 생각하셨다면, 슬프게도 조금 더 끔찍해질 거라고밖에 말씀드릴 수 없네요. 다음으로 필요한 건 마을을 둘러싼 호수에서 구한 농어 퓌레입니다.\n\n이틀에 한 번씩 저는 오독을 데리고 나가서 농어를 잡고, 오독은 찌꺼기를 먹습니다. 그 톡 쏘는 냄새가 나면 오독이 우리에게 바로 달려올 거라고 확신해요.",
    },
    [27353] = {
        ["T"] = "길 잃은 송아지",
        ["O"] = "블러드후프 마을 여관 밖 송아지 미끼를 놓아 오독을 주인에게 유인하십시오.",
        ["D"] =
        "이 딸기와 퓌레를 섞어서 오독을 위한 \"맛있는\" 간식을 만들었습니다. 하지만 다른 여관 손님들을 위해 부디 여관 **밖**에 놓아주세요.",
    },
    [27354] = {
        ["T"] = "현상 수배: 제이슨",
        ["O"] = "썬더 블러프 아래를 배회하는 켄타우로스 제이슨을 사냥하십시오.",
        ["D"] =
        "추방당한 갈라크 켄타우로스가 썬더 블러프 도시 아래를 배회하며 남녀노소 가리지 않고 공격하고 있다. 이대로 둘 수는 없다! 친구들을 모아 그 켄타우로스를 사냥해라.\n\n이 짐승에 대한 승리의 증거를 썬더 블러프 꼭대기에 있는 잔겐 스톤후프에게 가져가면 보상할 것이다.",
    },
    [27355] = {
        ["T"] = "저주받은 자의 무장",
        ["O"] = "마파람 마을 내의 고문받는 파수꾼들로부터 영체의 무장 8개를 수집하십시오.",
        ["D"] =
        "마파람 마을은 한때 칼도레이와 실리시드 간의 큰 전투가 벌어졌던 장소입니다. 왜 마파람 마을의 영혼들이 남아있는지는 확실하지 않지만, 우리가 아는 것은 그들이 살았을 때 사용했던 무기를 지니고 다닌다는 것입니다. 이 무기들은 실리시드와 싸우기 위해 특별히 벼려진 것이며 우리가 몇 개라도 회수할 수 있다면 병력에 큰 축복이 될 것입니다. 마파람 마을로 가서 영혼들을 안식에 들게 하고 그들의 무기를 이곳으로 가져오십시오.",
    },
    [27356] = {
        ["T"] = "고뇌에서 해방되다",
        ["O"] = "마파람 마을 폐허 내의 고문받는 드루이드 6명을 처치하십시오.",
        ["D"] =
        "수년 전, 흐르는 모래의 전쟁 동안 나와 내 형제들은 운고로 분화구 동쪽 경계인 이곳 남쪽의 작은 마을에 주둔했소.\n\n우리의 방어선은 무너졌고... 마을은 함락되었으며, 나와 함께 싸웠던 많은 이들이 지금 고통과 고뇌 속을 헤매고 있다오. 그들이 이 고문에서 벗어날 수 있도록 그들의 영혼을 해방시켜 주시오.",
    },
    [27357] = {
        ["T"] = "과거의 보고서",
        ["O"] = "마파람 마을에서 고대 보고서 3개를 수집하십시오.",
        ["D"] =
        "억겁의 세월 전 실리시드가 마파람 마을을 유린했을 때, 도망치지 못한 많은 이들이 전투에서 목숨을 잃었습니다. 하지만 칼도레이 병력은 우리가 실리시드와 어떻게 싸울 수 있는지 자세히 설명된 보고서 형태의 핵심 정보를 남겼습니다.\n\n저를 위해 마파람 마을로 가서 가능한 한 많은 보고서를 모아 주시겠습니까? 정보가 승리의 열쇠이며, 우리 나이트 엘프조차 잊어버린 비밀이 있을까 우려됩니다.",
    },
    [27358] = {
        ["T"] = "망령 학살",
        ["O"] = "셀란디르의 망령을 처치하고 그의 정수를 실리더스의 용사의 안식처에 있는 폴리언 세이지블로워에게 가져가십시오.",
        ["D"] =
        "마파람 마을에 큰 불안이 감돌고 있소, $n. 한때 강력했던 드루이드 셀란디르의 망령이 그곳에서 목격되었는데, 알아들을 수 없는 말을 중얼거리며 자신을 향해 비명을 지르고 있다고 하오. 그들은 그가 \"눈이 온다\"고 계속해서 외친다고 하더군.\n\n내 아버지는 한때 셀란디르와 함께 복무하셨고, 아버지를 기리기 위해 내가 이 드루이드를 이 고뇌에서 해방시켜야만 하오. 나를 위해 이 일을 해주시겠소?",
    },
    [27359] = {
        ["T"] = "속삭임을 잠재우다",
        ["O"] = "앰버문의 유령을 처치하고 광기에서 그녀를 해방하여 실리더스의 용사의 안식처에 있는 사시아 포레스트크레스트에게 가져가십시오.",
        ["D"] =
        "얼마 전, 브란이라는 떠돌이 드워프가 이곳을 지나갔소. 그 이유를 밝히지는 않았지만 타나리스와 실리더스 사이를 여행하고 있었지. 그가 용사의 안식처를 마지막으로 지났을 때, 마파람 마을의 지휘관 중 한 명인 여군주 앰버문의 망령을 보았다고 보고했소. 그는 그녀만이 들을 수 있는 속삭임과 대화하는 것을 엿들었다고 주장했소.\n\n나는 그녀의 고문받는 마음이 완전히 부서졌거나, 더 나쁜 것은 죽음 속에서 어떤 사악한 것이 그녀에게 영향을 미치고 있을까 두렵소. 부디 어떤 어둠의 세력이 지배하고 있든 그녀의 영혼을 해방시켜 주시겠소?",
    },
    [27360] = {
        ["T"] = "수정 조사",
        ["O"] = "페타 윈드스카는 당신이 정수 초점 조절기를 실리더스 북동쪽 끝에 있는 수정 더미 5개에 사용하기를 원합니다.",
        ["D"] =
        "여기서 바로 남서쪽에 수정 더미가 있는데, 더 서쪽에 있는 것들과 확연히 다릅니다. 이 수정들의 목적을 이해하고, 이곳에서 우리의 목적에 사용할 수 있는 것이 있는지 알아봐야 합니다.\n\n이 초점 조절기를 가져가서 북동쪽의 수정 더미에 조율해 보고 내게 다시 가져오십시오.",
    },
    [27361] = {
        ["T"] = "야생동물 도태",
        ["O"] = "잔노크 하이드피어서는 당신이 모래거미 8마리를 처치하기를 원합니다.",
        ["D"] =
        "실리더스를 이동하다 보면 이 땅을 고향이라 부르는 잔인한 거미들의 공격을 분명히 받았을 것입니다. 용사의 안식처 또한 예외는 아닙니다.\n\n경비병들은 우리를 안전하게 지키기 위해 최선을 다하고 있지만, 녀석들에게 타격을 입히고 원정대에게 유예를 제공할 수 있는 누군가가 필요합니다. 이 친절을 베풀어 주시겠습니까?",
    },
    [27362] = {
        ["T"] = "전갈 독 수집",
        ["O"] = "나타 호크송은 당신이 실리더스의 모든 전갈로부터 전갈 독 8병을 수집하기를 원합니다.",
        ["D"] =
        "우리 원정대가 실리더스에서 직면하는 도전 중 하나는 전갈의 침입니다. 녀석들의 독은 강하고 치명적이며, 해독제를 만들기 위한 독 샘플이 충분하지 않습니다.\n\n우리는 얇게 퍼져 있습니다. 현지 전갈에게서 독이 든 병을 수집하여 우리를 돕는다면 우리에게 엄청난 도움이 될 것입니다.",
    },
    [27363] = {
        ["T"] = "무리",
        ["O"] = "실리더스의 용사의 안식처에 있는 암라스 문스워드를 위해 실리시드 말벌 무리 6마리를 포획하십시오.",
        ["D"] =
        "세나리온 의회가 실리더스에서 수행하는 연구 덕분에 아키르를 가까이서 연구할 수 있는 특별한 기회를 얻었습니다.\n\n실리시드에는 어린 말벌 무리가 있는데 여기서 바로 서쪽에서 찾을 수 있습니다. 제가 직접 수집하겠지만 당분간은 연구 때문에 이곳에 머물러야 합니다. 저 대신 수집해 주시겠습니까?",
    },
    [27364] = {
        ["T"] = "그것들....",
        ["O"] = "잔노크 하이드피어서는 당신이 굴착벌레 10마리를 처치하기를 원합니다.",
        ["D"] =
        "미늘벌레는 실리더스를 고향이라 부르며, 이곳에서 발견할 수 있는 무시무시한 생물들의 또 다른 예입니다. 녀석들은 예외적으로 폭력적이며 주저 없이 공격할 것입니다.\n\n아직 용사의 안식처를 침범하지는 않았지만, 그런 위험을 감수하고 싶지 않습니다. 녀석들의 수를 줄여주도록 당신을 설득할 수 있을까요?",
