        ["D"] =
        "바람의 왕자, 썬더란에 대해 들어보셨습니까? 그의 백성 중 다수가 북서쪽의 수정 골짜기를 배회하고 있기 때문에 실리더스에서 그의 중요성은 과소평가될 수 없습니다. 모래바람 정령으로 알려진 정령들은 그의 정수를 지니고 있으며 주인을 섬기도록 결속되어 있습니다. 누군가 실리더스에 대한 왕자의 지배력을 약화시키고자 한다면 그의 백성을 처치하고 이 정수들을 모아야 합니다. 충분히 모으면 정수들을 사용하여 썬더란의 용사를 소환하고 처치하십시오.",
