    [27366] = {
        ["T"] = "금지된 것인가, 아니면 그냥 잃어버린 것인가?",
        ["O"] = "실리더스의 용사의 안식처에 있는 암라스 문스워드를 위해 황혼의 서판을 수집하십시오.",
        ["D"] =
        "황혼의 망치단은 실리더스의 북서쪽 끝에 야영지를 두고 있었는데 얼마 전에 파괴되었습니다. 언제 왜 파괴되었는지는 나중에 던질 질문이지만, 지금 가장 흥미로운 것은 그들의 야영지에 있었던 정보를 수집할 수 있는 가능성입니다. 아키르, 퀴라지, 실리시드에 대해 그들이 더 깊은 지식을 가지고 있기를 희망합니다.\n\n약탈당한 야영지 지역에 가게 된다면, 주변을 둘러보고 무엇을 찾을 수 있는지 확인해 주시겠습니까? 어둠 속에 숨어 기다리고 있을지도 모를 이교도들을 조심하십시오.",
