        ["D"] =
        "이 땅 전역에는 모래바람 정령으로 알려진 바람의 정령들이 존재하지만, 가장 많이 존재하는 곳은 수정 골짜기 바로 남쪽, 먼 서쪽입니다. 녀석들은 실리더스 전체에 영향을 미치는 위험한 모래 폭풍을 일으키는 맹렬한 정령입니다.\n\n녀석들의 수를 줄이는 것은 매우 중요합니다. 우리를 대신해 그들에 맞서고자 한다면, 조심하고 동료들을 데려오십시오.",
