        ["D"] =
        "황혼의 망치단 이교도들이 자신들의 어두운 목적을 위해 대지의 정령들을 하수인으로 소환한다는 것은 잘 알려져 있습니다. 수정 골짜기 안에는 소환된 정령들이 여러 마리 남아 이 땅을 쑥대밭으로 만들고 있습니다.\n\n용사의 원정대는 얇게 펴져 있으므로 맹렬한 정령들의 위협을 처리하는 것은 당신과 같은 영웅들의 몫입니다. 제발, $n, 동료 모험가들을 모아 녀석들의 수를 줄여주십시오.",
