        ["D"] =
        "이곳에서 멀리 떨어진 북서쪽 실리더스에 수정 골짜기라는 곳이 있습니다. 그곳에 있는 수정은 다른 곳에서 발견되는 수정보다 더 많습니다. 정찰병의 보고에 따르면 수정이 자라고 있으며, 그곳에 있는 훨씬 더 큰 수정에서 멀지 않은 곳에서 \"새끼\" 수정들을 찾을 수 있다고 합니다.\n\n절 위해 그 새끼 수정 샘플을 좀 수집해 주시겠습니까?",
