    [27370] = {
        ["T"] = "정확히 무엇을 복수하는가?",
        ["O"] = "실리더스의 용사의 안식처에 있는 사시아 포레스트크레스트를 위해 황혼의 복수자 8명을 처치하십시오.",
        ["D"] =
        "이 땅에 존재하는 위험은 실리시드만이 아닙니다. 우리의 임무는 황혼의 망치단과 그들의 \"복수자\"들에 의해 방해받고 있습니다. 비록 그들이 무엇을 복수하고 있는지는 저로선 알 수 없지만요.\n\n당신이 동료들을 모아 그들을 공격하여 그들의 수를 줄여주기를 요청합니다. 하지만 조심하십시오. 그들은 가볍게 볼 상대가 아닙니다.",
