    [27371] = {
        ["T"] = "이교도 계획서",
        ["O"] = "실리더스에 있는 황혼의 망치단 야영지에서 이교도 계획서 3세트를 회수하십시오.",
        ["D"] =
        "적의 작전을 주시하는 것은 원정대를 위한 제 임무 중 하나일 뿐이지만, 최근에 입은 상처에서 회복하는 동안에는 임무를 수행할 수 없습니다. 내 임무는 황혼의 망치단 야영지에 잠입하여 그들의 계획에 대해 뭐든 알아내는 것이었습니다.\n\n나 대신 이 임무를 맡아주겠습니까? 그들의 야영지를 찾아 계획서를 내게 가져와 주십시오.",
