        ["D"] =
        "황혼의 망치단은 끊임없이 움직이며 정령을 소환하고 그들을 이 차원에 속박합니다. 우리 정찰병의 보고에 따르면 그 이교도들은 동쪽과 남동쪽에 가장 많이 집중되어 있으며, 그들의 결속 작업 대부분이 이루어지는 곳이 바로 그곳입니다.\n\n용사의 원정대를 돕기 위해 이곳에 오셨다면 녀석들을 찾아서 방해해 주기를 부탁합니다. 녀석들이 정령을 결속하는 팔보호구를 내게 가져오십시오.",
