    [27373] = {
        ["T"] = "좋은 읽을거리",
        ["O"] = "실리더스에 있는 황혼의 망치단 이교도로부터 황혼의 망치단 문서 5개를 획득하십시오.",
        ["D"] =
        "요즘 모두가 황혼의 망치단 이교도에 대해 생각하느라 바쁜 것 같지만, 그들의 저주받은 행동의 동기가 무엇인지 아무도 모릅니다. 이교도를 이해하려면 그들의 지루한 문헌을 읽어보기만 하면 됩니다. 이교도의 일원들이 조직의 구조와 대처 방법을 더 잘 이해하는 데 도움이 될 만한 정보를 가지고 있을 거라고 확신합니다.\n\n조만간 이교도들과 싸우게 된다면, 그들이 우리가 이해하는 데 도움이 될 만한 기록된 무언가를 가지고 있는지 시간을 내어 확인해 보십시오. 사시아가 그것에서 유용한 무언가를 얻어낼 수 있을지도 모릅니다.",
