        ["D"] =
        "실리더스에서는 쓰러진 자들의 영혼을 고문할 뿐만 아니라 우리처럼 살아있는 자들을 적대시하는 어둠의 의식이 행해지고 있습니다. 이 모독적인 행위에 책임이 있는 자들은 바로 황혼의 망치단의 \"지배자들\"입니다.\n\n예전 같았으면 내가 직접 그들을 쫓아가 처치할 책임을 졌겠지만, 지금은 방어를 유지하기 위해 이곳에 남아야 합니다. 나를 대신해 황혼의 망치단의 지배자라 자칭하는 자들을 공격해 주시겠습니까?",
