        ["D"] =
        "조라 하이브에 \"여왕 무리\"로 알려진 실리시드 생물이 있습니다. 이 변종이 특별한 이유는 무엇일까요? 그들은 다른 유형보다 능력이 더 뛰어날까요, 아니면 떨어질까요? 질문이 너무 많습니다! 이 문제를 원정대의 다른 사람들에게 제기했지만, 사시아는 우리가 심각한 위험에 노출되지 않고 샘플을 확보하기 위해 병력을 보낼 수 없다는 인상을 받은 것 같습니다.\n\n부탁하기 미안하지만, 연구를 위해 그들의 뇌 샘플을 수집해서 내게 가져다주시겠습니까?",
    },
    [27376] = {
        ["T"] = "그들을 굶겨라",
        ["O"] = "조라 하이브에 있는 고기 더미 10개를 태우고 실리더스의 용사의 안식처에 있는 잔노크 하이드피어서에게 돌아가십시오.",
        ["D"] =
        "실리시드들은 그들이 죽인 야생동물의 거대한 고기 더미를 먹고 생존합니다. 사시아에게 경비병을 보내 무리의 식량 보급품을 찾아내어 태워버리자고 제안했지만, 그녀는 위험이 너무 크다고 생각했습니다. 저도 동의하지 않는 것은 아니지만, 무리가 끝없이 자라나도록 내버려 둘 수는 없습니다.\n\n내 횃불을 드릴 테니 조라 하이브에 있는 그들의 식량 보급품에 불을 질러주시겠습니까?",
