        ["D"] =
        "불안할 정도로 많은 수의 실리시드 말벌이 조라 하이브에서 목격되었습니다. 녀석들은 평범한 말벌이 아니며, 이런 엄청난 수로 보인다는 것은 우리가 곧 공격받을 것으로 예상해야 한다는 징후입니다.\n\n실리시드는 자신들의 세력을 집결하는 동안 선제 반격이 있을 거라고는 예상하지 못할 것이라고 생각합니다. 우리가 여기서 방어 태세를 취하고 있는 동안, 당신과 당신의 동료들이 조라 하이브에 있는 말벌들을 공격하여 녀석들의 수를 줄일 수 있을 것입니다.",
    },
    [27378] = {
        ["T"] = "길의 감시자",
        ["O"] = "조라 하이브에 있는 조라 길잡이벌레 6마리를 처치한 다음, 실리더스의 용사의 안식처에 있는 사시아 포레스트크레스트에게 돌아가십시오.",
        ["D"] =
        "원정대는 삼엄한 경계 태세에 돌입했으며, 그럴 만한 이유가 있습니다. 실리시드는 너무나 위험해서 우리는 녀석들에게 조금도 양보할 수 없습니다. 따라서 우리를 도울 의향이 있다면 조라 하이브에 있는 길잡이벌레들을 상대로 전투를 벌일 수 있습니다. 녀석들의 수가 줄어들면 무리의 조정 능력이 손상되어, 우리가 실리더스로 들어가는 도로에 대한 지배력을 강화할 수 있을 것입니다.\n\n그러면 어쩌면 사시아도 한숨 돌리고, 우리 모두 업무로 돌아갈 수 있을 것입니다.",
    },
    [27379] = {
        ["T"] = "다라이의 보고서",
        ["O"] = "조라 하이브에서 다라이 문보우를 찾아 그녀의 보고서를 실리더스의 용사의 안식처에 있는 사시아 포레스트크레스트에게 가져가십시오.",
        ["D"] =
        "다라이가 조라 하이브를 정찰하러 나갔습니다. 이곳의 상황은 위태롭고, 실리시드의 위협에 앞서 나가기 위해서는 그녀로부터 초기 보고서를 입수해야 합니다. 우리가 모르는 사이에 군락이 동원될 위험이 있으므로 원정대 경비병들을 가까이 두어야 합니다.\n\n군락 내에서 다라이를 찾아 그녀에게서 보고서를 받아 주시겠습니까?",
    },
    [27380] = {
        ["T"] = "오, 군주여!",
