        ["D"] =
        "레갈 하이브는 하이브 군주로 알려진 실리시드가 통제합니다. 녀석들은 계층 구조의 최상위에 있지만, 여전히 그들의 퀴라지 주인에게 복종합니다. 실리시드가 어떻게 작동하는지 더 잘 이해하기 위해 여러 다른 실리시드의 뇌를 조사하여 비교하고 있습니다.\n\n원정대 감시관들은 하이브 군주의 뇌 샘플을 회수하는 데 실패했습니다. 나를 위해 뇌를 좀 구해다 내 연구를 도와주시겠습니까?",
