    [27381] = {
        ["T"] = "벌레 으깨기",
        ["O"] = "레갈 하이브의 레갈 굴착벌레 6마리를 제거하고 실리더스의 용사의 안식처에 있는 사시아 포레스트크레스트에게 돌아가십시오.",
        ["D"] =
        "레갈 하이브의 실리시드 유형 중 하나는 대지를 파고 터널을 뚫어 다른 녀석들을 위한 길을 만드는 것으로 알려져 있습니다. 우리가 이곳에서 준비하는 방어는 무엇이든 이 생물들에 의해 무너질 수 있습니다!\n\n우리 감시관들은 여전히 용사의 안식처를 면밀히 감시하고 있습니다. 그렇지 않았다면 녀석들을 처리하러 나갔을 것입니다. 제가 이 임무를 당신에게 대신 맡겨도 되겠습니까?",
    },
    [27382] = {
        ["T"] = "임박한 해방",
        ["O"] = "레갈 하이브의 레갈 노예제조기 5마리를 처치하고 실리더스의 용사의 안식처에 있는 마스카 엠버벤더에게 돌아가십시오.",
        ["D"] =
        "실리시드에게 고용된 노예를 본 적이 있습니까, $n? 저는 없습니다. 하지만 레갈 하이브의 실리시드 중 일부는 부주의한 병사의 마음을 통제할 수 있다는 보고가 있었습니다. 이 생물들은 \"노예제조기\"라고 불립니다. 이 노예제조기들이 자신들이 \"만든\" 노예를 어디로 데려가는지 저는 결코 알지 못할 것입니다. 제가 아는 것은 우리 자신의 이익을 위해 이 실리시드들을 제거해야 한다는 것입니다. 우리를 돕기 위해 이곳에 오셨다면, 보이는 노예제조기는 모두 죽이고 자신도 노예가 되지 않도록 조심하십시오.",
    },
    [27383] = {
        ["T"] = "그건 오히려 산성에 가깝다",
        ["O"] = "레갈 하이브의 레갈 맹독벌레로부터 산성 침 샘플 5개를 획득하고 실리더스의 용사의 안식처에 있는 나타 호크송에게 돌아가십시오.",
        ["D"] =
        "이번에는 제 초점이 해독제를 만드는 데 있지 않습니다. 제가 무엇을 하든 레갈 하이브의 일부 실리시드가 적의 방어구를 녹이는 데 사용하는 산성 침에 대한 효과적인 대응책을 만들 수 없는 것 같습니다. 레갈 하이브 인근에 계신다면, 그곳에 있는 \"맹독벌레\"들에게서 침 샘플을 수집해 주시겠습니까?",
    },
    [27384] = {
        ["T"] = "심장부를 치다",
        ["O"] = "빛나는 씨앗을 레갈 하이브의 심장부에 심고 실리더스의 용사의 안식처에 있는 라요 스타스트라이크에게 돌아가십시오.",
        ["D"] =
        "지금이 바로 행동할 때입니다, $n. 실리시드가 재집결하려 시도하는 동안, 우리는 그들의 군락 중 한 곳으로 이동하여 그곳을 교란해야 합니다. 제가 변동성이 큰 힘의 씨앗을 하나 가지고 있는데, 심으면 통제할 수 없을 정도로 빠르게 자랄 것입니다. 레갈 하이브의 심장부를 찾아 그 심장에 씨앗을 심어 우리를 도와주시겠습니까?",
    },
    [27385] = {
        ["T"] = "일벌레 억압",
        ["O"] = "아쉬 하이브의 아쉬 일벌레 6마리를 제거하고 실리더스의 용사의 안식처에 있는 사시아 포레스트크레스트에게 돌아가십시오.",
        ["D"] =
        "아쉬 하이브는 수벌, 즉 일벌레들이 운영하며 군락 주변의 평범한 일들을 처리합니다. 다른 녀석들만큼 호전적이지는 않지만 군락이 더 위험한 실리시드를 계속해서 생산할 수 있도록 보장합니다. 내가 보낸 원정대 감시관들은 가능한 한 많은 수벌을 제거하려고 시도했지만 유감스럽게도 여러 명이 군락에서 죽었습니다. 그들의 임무를 완수하기 위해 더 많은 병력을 보낼 수 없습니다.\n\n아쉬 하이브에 맞서 그들 일벌레 중 상당수를 처치하여 쓰러진 감시관들이 끝내지 못한 임무를 완수해 주시겠습니까?",
    },
    [27386] = {
        ["T"] = "알 으깨기!",
        ["O"] = "아쉬 하이브에서 실리시드 알 10개를 으깨고 실리더스의 용사의 안식처에 있는 자룬드 스타우트라이더에게 돌아가십시오.",
        ["D"] =
        "무리의 성장을 막으려면 근원을 조사해야 합니다. 단일 번식어미를 찾을 가능성은 낮지만 아쉬 하이브 전역에 알이 있다는 것은 알고 있습니다. 가설이긴 하지만, 한 무리의 모험가가 그곳으로 가서 알을 으깨어 죽으로 만든다면 앞으로 병력을 보충할 실리시드의 수가 줄어들 것입니다.",
    },
    [27387] = {
        ["T"] = "독침벌레에게서 독침을",
        ["O"] = "아쉬 하이브의 아쉬 독침벌레로부터 아쉬 독침벌레의 침 5개를 획득하고 실리더스의 용사의 안식처에 있는 나타 호크송에게 돌아가십시오.",
        ["D"] =
        "아쉬 하이브의 독침벌레들은 실리시드가 주입하는 다른 독과 비교했을 때 특히 치명적인 강력한 독을 가지고 있습니다. 우리 감시관들이 실패한 이후, 저는 우리가 해독제를 고안하지 않고 그들을 상대할 준비가 되어 있지 않다는 점을 우려하고 있습니다.\n\n그 아래로 내려가게 된다면... 독침벌레들에게서 독침을 좀 수집해 주시겠습니까? 아쉬 독침벌레의 아쉬 독침벌레의 침 말입니다. 무슨 말인지 이해가 되시나요?",
    },
    [27388] = {
        ["T"] = "잃어버린 것을 회수하다",
        ["O"] = "아쉬 하이브에서 용사의 안식처 보급품 3개를 회수하고 실리더스의 용사의 안식처에 있는 밀라이스 미스트블레이드에게 돌아가십시오.",
        ["D"] =
        "용사의 안식처를 공격하는 무리의 위협이 많이 줄어들자, 사시아는 이 기회를 틈타 아쉬 하이브를 공격하여 그들에게 치명타를 입히고 원정대의 시간을 벌려고 시도했습니다. 많은 감시관이 군락에서 전투를 벌였지만 이곳으로 후퇴할 수밖에 없었습니다. 우리는 전투에서 많은 보급품과 무장을 잃었습니다. 군락으로 가서 무엇을 회수할 수 있는지 확인해 주시겠습니까?",
    },
    [27389] = {
        ["T"] = "단 한 마리?",
        ["O"] = "아쉬 하이브의 아쉬 대군주를 처치하고 실리더스의 용사의 안식처에 있는 다라이 문보우에게 돌아가십시오.",
        ["D"] =
        "실리시드 하이브는 각각 작동 방식이 독특합니다. 아쉬 하이브의 경우, 그들의 지도부는 군락 자체에서 직접 통치하는 단일 대군주를 중심으로 집중되어 있습니다. 사시아가 녀석을 제거하기 위해 원정대 감시관들을 보냈지만 성공하지 못한 것 같습니다.\n\n군락이 동원될 위협은 여전히 매우 현실적이며, 또 다른 원정대가 파견될 가능성은 낮습니다. 제발, $n, 다른 모험가들을 모아 아쉬 하이브의 대군주를 제거해 주십시오.",
    },
