        ["O"] = "원정대 상자를 수집하십시오.",
        ["D"] = "",
    },
    [27397] = {
        ["T"] = "계곡으로의 여행",
        ["O"] = "잿더미 계곡에서 검게 탄 나무 1개와 바실리스크 꼬리 1개를 수집하여 돌발톱 산맥의 해바위 야영지에 있는 쿨위아에게 돌아가십시오.",
        ["D"] =
        "잿더미 계곡에서만 찾을 수 있는 이국적인 무역 재료가 좀 필요해요. 가장 용감한 모험가만이 가는 위험한 곳이죠. 여기서 북쪽으로 향하면 찾을 수 있어요. 땅거미 호수에 도달하면 동쪽으로 가세요, 그럼 길을 찾을 수 있을 거예요.\n\n내게 필요한 재료는 바실리스크 꼬리 하나와 계곡을 배회하는 고대정령들에게서 구한 검게 탄 나무 한 조각이에요. 이 재료들을 가져다주시면 수고에 대한 보답을 할게요.",
    },
    [27398] = {
        ["T"] = "광산 공격",
        ["O"] =
        "칼바람 광산에 있는 칼바람 점쟁이 5명, 칼바람 흙점쟁이 5명, 칼바람 광부 10명을 처치한 후 돌발톱 산맥의 해바위 야영지에 있는 그라우날에게 돌아가십시오.",
        ["D"] =
        "칼바람 바위산에 가게 된다면 벤처 투자회사가 건설한 광산을 주시하게. 그들이 작업을 시작했다는 말을 들었는데, 코볼트들이 광산을 점령하고 벤처 투자회사를 몰아냈다는군!\n\n벤처 투자회사는 결과는 생각하지 않고 대지의 자원을 약탈하지만, 코볼트는 내버려두면 상당한 힘을 가진 정령들을 소환하는 해충이라네. 광산의 작업은 멈춰야만 해! 수단과 방법을 가리지 말게, $N, 그리고 임무가 완료될 때까지 내게 돌아오지 말게.",
    },
    [27399] = {
        ["T"] = "평온 속의 사냥",
        ["O"] = "돌발톱 숲 주변의 사슴으로부터 순록 모피 10개를 수집하여 돌발톱 산맥에 있는 사냥꾼 키라니아에게 돌아가십시오.",
        ["D"] =
        "반가워요, $C. 사냥 기술에 대해 잘 아시나요? 이곳 숲에 있는 사슴들은 아주 포착하기 어려워서, 녀석들을 사냥하려는 사람에게 엄청난 도전이 될 거예요. 녀석들의 빠른 발과 예리한 감각은 좋은 스포츠를 만들어주죠.\n\n이렇게 하죠, 녀석들의 털을 좀 가져다주시면, 그걸로 멋진 망토를 하나 만들어 드릴게요! 물론 저도 좀 가질 거예요, 여기 겨울은 추우니까요! 행운을 빌어요, 그리고 여기 위에서 찾을 수 없다면, 사슴들이 숲으로 올라가는 길 근처, 약간 더 남쪽으로 모험을 떠나기도 한답니다.",
    },
    [27400] = {
        ["T"] = "땅거미 팔보호구",
        ["O"] = "땅거미 호수의 물의 정령으로부터 땅거미 팔보호구 8개를 수집하여 돌발톱 산맥의 해바위 야영지에 있는 탐라 윈드필드에게 돌아가십시오.",
        ["D"] =
        "반갑습니다, $N. 이곳에서 $C을(를) 보게 되어 반갑군요, 해야 할 일이 많거든요. 저는 여러 해 동안 해바위 야영지에 살았는데, 이 산맥은 저를 항상 놀라게 합니다. 최근 근처 땅거미 호수에서 마법의 샘이 깨어났고, 그것을 처리하기 위해 당신의 도움이 필요합니다.\n\n호수는 숲의 생물들을 위한 오래되고 고대의 피난처입니다. 샘 덕분에 물의 정령들이 호수 깊은 곳에서 솟아올라 호수 주변의 생물들을 해치고 있습니다. 물의 정령들을 제거해 주시고, 그 증거로 녀석들의 팔보호구를 가져다주셨으면 합니다.",
    },
    [27401] = {
        ["T"] = "땅거미 호수",
        ["O"] = "땅거미 호수에 있는 물의 정령으로부터 땅거미 정수 8개를 수집하여 돌발톱 산맥의 돌발톱 숲에 있는 센트리카 나이트송에게 돌아가십시오.",
        ["D"] =
        "돌발톱 산맥은 엘룬의 소중한 수많은 생물들의 고향이에요, $N. 저는 녀석들을 연구하고 평화롭게 연금술을 연습하기 위해 이곳에 모험을 왔죠.\n\n이곳 남쪽 땅거미 호수에서 물의 정령들을 좀 관찰했어요. 그들 정수의 효과를 꼭 시험해 보고 싶어요. 제게 좀 가져다주실 수 있나요?\n\n숲 밖으로 난 길을 따라 남쪽으로 가면 아무 문제 없이 땅거미 호수에 도착할 수 있을 거예요. 쓸만한 샘플을 좀 가져다주시면, 제 물약 몇 개를 기꺼이 드릴게요!",
    },
    [27402] = {
        ["T"] = "해바위를 위한 광석",
        ["O"] = "칼바람 광산에서 팔라듐 광석 8개를 채광하여 해바위 야영지의 그라우날에게 돌아가십시오.",
        ["D"] =
        "그렇게 보이지 않는다는 건 알지만, 경비병들을 위한 무기로 제련할 금속이 바닥나가고 있소. 자신을 방어할 수 없다면 얼라이언스의 공격에 무방비로 노출될 거요!\n\n벤처 투자회사가 이곳 돌발톱 산맥에서 새로운 광석을 발견했다는 소문을 들었소, 우리가 사용하던 철보다 더 강하다더군. 내 곡괭이를 가지고 칼바람 광산으로 가주길 원하오. 칼바람 바위산에 들어가서 산 가장자리를 따라 오른쪽으로 향하면 광산을 찾을 수 있을 거요. 특별한 광석을 발견하면 내 곡괭이를 사용하여 채집하고 조사를 위해 내게 다시 가져오시오.",
    },
    [27403] = {
        ["T"] = "대지의 땅울림",
        ["O"] = "자부심날개 하늘사냥꾼, 자부심날개 갈퀴발톱, 자부심날개 우두머리로부터 금속성 꼬리 가시 3개를 수집하십시오.",
        ["D"] =
        "음, 내 형제가 이 장치를 만드는 데 내 시간을 덜어줬다는 건 부인할 수 없지만, 이 장치에 필요한 게 하나 있어: 바로 더 많은 힘이지! 임시 배터리로 이것을 과충전시킬 수 있지만, 몇 가지 물건이 필요할 거야. 첫 번째는 여기서 북서쪽에 있는, 네가 찾을 수 있는 가장 강한 자부심날개의 금속 꼬리야.\n\n가장 크고, 비열하고, 가장 질긴 놈들만 원해! 하늘사냥꾼, 갈퀴발톱, 우두머리에게서 좋은 성체 꼬리를 얻을 수 있을 거야.",
    },
    [27404] = {
        ["T"] = "대지의 땅울림",
        ["O"] = "돌발톱 산맥의 잿더미 계곡 내에 있는 붉은분노 마녀하피로부터 번개 토템 4개를 수집하십시오.",
        ["D"] =
        "알아! 잿더미 계곡 안에서 붉은분노 마녀하피들을 찾을 수 있을 거야. 녀석들이 집중시키는 번개에는 분명 근원이 있을 테지. 녀석들을 죽이고 그게 뭐든 내게 가져와! 네가 가져온 꼬리로 녀석들의 번개를 집중시켜서 이 땅울림기계를 과충전시킬 수 있어.\n\n하피 근원 4개면 충분할 것 같아. 잿더미 계곡은 해바위 야영지 서쪽에서 찾을 수 있어.",
    },
    [27405] = {
        ["T"] = "대지의 땅울림",
        ["O"] = "땅울림기계 마크 III를 사용하여 돌발톱 내의 진동의 근원지를 찾으십시오.",
        ["D"] =
        "자 간다. 땅울림기계 마크 III를 소개하지. 난 항상 형제보다 무언가를 땜질해서 엮어내는 데 더 뛰어났어. 말 안 해도 점수 알지!\n\n이제 땅울림기계를 땅에 내리치면 이 진동의 근원지를 찾아낼 거야. 어서 해봐!",
    },
    [27406] = {
        ["T"] = "대지의 땅울림",
        ["O"] = "해바위 야영지에 있는 딧시 스프링소켓에게 광석 샘플을 가져가십시오.",
        ["D"] =
        "당신 앞의 광석은 이전에 보았던 그 어떤 것과도 다릅니다. 엄청난 노력 끝에 조각 하나를 떼어내어 딧시 스프링소켓에게 가져갑니다.",
    },
    [27407] = {
        ["T"] = "대지의 땅울림",
        ["O"] = "분석물 샘플을 오그리마에 있는 스랄에게 가져가십시오.",
        ["D"] =
        "몇 년 전 대족장님 이후로 돌발톱 동굴에 감히 들어가는 사람은 아무도 없고, 살아서 돌아온 사람은 내가 아는 한 대족장님뿐이야. 자네가 수집한 샘플을 그에게 가져가서 자네의 여행에 대해 얘기해 줘.\n\n그분보다 이 금속에 대해 더 나은 통찰력을 가질 사람은 없을 거야.",
    },
    [27408] = {
        ["T"] = "계곡에서의 땜질",
        ["O"] = "잿더미 계곡에서 그을린 비늘 10개와 성난 핵 1개를 수집하여 돌발톱 산맥의 돌발톱 숲에 있는 바퍼 투크윙클에게 돌아가십시오.",
        ["D"] =
        "좋은 하루입니다, $gsir:madam;! 여기 숲은 꽤 근사하죠, 그렇지 않나요? 사실 전 잿더미 계곡의 생물 중 일부를 탐구하고 제 다음 창작물에 유용하게 쓰일 수 있는지 알아보기 위해 이곳에 왔습니다.\n\n불행히도, 전 겁이 나서 실제로 거기로 모험을 갈 수가 없어요. 당신은 강한 모험가 같아 보이는데, 대신 가주실 수 있나요? 바실리스크의 비늘과 대지의 정령의 핵이 필요합니다. 땅거미 호수 서쪽의 길을 지나 남쪽으로 가면 잿더미 계곡을 찾을 수 있을 거예요.",
    },
    [27409] = {
        ["T"] = "황혼의 송곳니",
        ["O"] = "황혼의 송곳니 10개를 수집하여 돌발톱 산맥의 해바위 야영지에 있는 크론드에게 돌아가십시오.",
        ["D"] =
        "여기서 멀리 북쪽에 있는 돌발톱 숲에 가게 된다면, 그곳에 숨어 있는 황혼의추적자 퓨마를 예리한 눈으로 살펴보게. 녀석들의 송곳니는 최고 품질이라고 알려져 있지만, 그 고양잇과 동물들은 찾기 힘들고 재빨라서 희귀하다네.\n\n녀석들의 송곳니를 좀 가져다주면, 기꺼이 그것들로 자네에게 뭔가를 만들어 주지. 어떤 사람들은 황혼의 송곳니가 마법적인 특성마저 가지고 있다고 말하더군...!",
    },
    [27410] = {
        ["T"] = "호수의 덩굴",
        ["O"] = "땅거미 호수에서 물덩굴 8개를 수집하여 돌발톱 숲의 발루레크 나이트송에게 돌아가십시오.",
        ["D"] =
        "이곳에서 $c을(를) 보게 되어 반갑군요, 모험심이 있는 사람을 찾고 있었거든요! 제 자매 센트리카 나이트송의 연금술 연구를 위해 새로운 재료가 좀 필요해요. 제가 자매를 도우려고 따라오긴 했지만, 유감스럽게도 별로 도움이 되지 못했어요! 그녀에게 필요한 약초는 위험한 곳에서만 자라는데, 저는 검술에 소질이 없거든요.\n\n저를 대신해서 가주실 의향이 있나요, $N? 그녀에게는 땅거미 호수에서만 자라는 물덩굴이 필요해요. 길을 따라 남쪽으로 가면 호수는 쉽게 찾을 수 있지만, 그곳의 생물들을 조심하세요!",
    },
    [27411] = {
        ["T"] = "호수의 덩굴",
        ["O"] = "돌발톱 숲의 센트리카 나이트송에게 물덩굴 상자를 배달하십시오.",
        ["D"] =
        "도와주셔서 정말 감사합니다, $N. 물덩굴을 상자 안에 넣어두었으니, 제 자매에게 배달해 주시면 감사하겠습니다! 그녀는 바로 여기 위 여관에서 찾을 수 있을 거예요. 그녀는 오랫동안 이 약초를 구하려고 애써왔기 때문에 드디어 갖게 되어 아주 기뻐할 겁니다.",
    },
    [27412] = {
        ["T"] = "썩은나무 공격",
        ["O"] = "썩은나무 아뮬렛 15개를 수집하여 아스트라나르에 있는 파수꾼 테니실에게 돌아가십시오.",
        ["D"] =
        "가만히 귀 기울여 보면 썩은나무 펄볼그 부족의 억눌린 비명 소리를 들을 수 있습니다. 이 저주받은 펄볼그들은 이 땅에 전염병처럼 퍼져, 마을을 공포에 떨게 하고 민간인을 사냥합니다. 이제 그들과 싸워야 할 때이며, 우리는 맹렬하게 공격할 것입니다!\n\n그들은 레인나무 은신처에 도착하기 직전, 동쪽으로 향하는 도로 남쪽에 야영지를 세웠습니다. 자비를 베풀어선 안 됩니다, $N. 그들을 모두 죽이고, 그들의 최후를 증명하기 위해 부족을 표시하는 아뮬렛을 제게 가져오십시오. 행운을 빕니다, 아스트라나르는 당신에게 기대하고 있습니다.",
    },
    [27413] = {
        ["T"] = "캘라에게 보고",
        ["O"] = "돌발톱 산맥의 칼바람 바위산으로 들어가는 골짜기를 내려다보고 있는 캘라 섀도스피어에게 보고하십시오.",
        ["D"] =
        "우리는 오늘 썩은나무 펄볼그들에게 결정적인 타격을 입혔지만, 돌발톱 산맥의 위협에 우리가 주의를 기울여야 한다는 정보를 받았습니다. 분명 벤처 투자회사가 칼바람 바위산에서 작업을 시작한 것 같습니다. 이 일은 반드시 중단되어야 합니다.\n\n당신이 썩은나무 펄볼그들을 상대로 유능함을 증명했으므로, 벤처 투자회사에 대한 우리의 공격을 감독하고 있는 캘라 섀도스피어에게 보고해주었으면 합니다. 이곳 남쪽의 갈퀴발톱오솔길을 따라 돌발톱 산맥으로 여행한 후, 칼바람 바위산 입구가 내려다보이는 절벽에서 그녀를 찾을 수 있습니다.",
    },
    [27414] = {
        ["T"] = "비축물 태우기",
        ["O"] = "칼바람 바위산에 있는 벤처 투자회사 보급품 8개에 불을 지른 후, 돌발톱 산맥의 캘라 섀도스피어에게 돌아가십시오.",
        ["D"] =
        "이 유리한 지점 아래에는 한때 푸르고 아름다운 숲이었던 칼바람 바위산이 있습니다. 하지만 그 평온함은 이익에 이끌리는 무자비한 고블린 무리인 벤처 투자회사에 의해 위협받고 있습니다. 그들은 천연자원을 위해 아제로스의 장엄한 공간을 파괴하는 것으로 유명합니다.\n\n우리는 숲을 보호하기 위해 벤처 투자회사에 대한 공격을 개시해야 합니다. 이 횃불을 가져가 제 뒤에 있는 모닥불에서 불을 붙인 다음, 그들의 보급품 상자에 불을 지르십시오. 횃불의 불이 꺼지면 제게 다시 와서 새 횃불을 가져가십시오. 숲은 당신에게 기대고 있습니다, $N.",
    },
    [27415] = {
        ["T"] = "칼바람 광산",
        ["O"] = "칼바람 광산에서 칼바람 광부 15마리를 처치하고 돌발톱 산맥의 캘라 섀도스피어에게 돌아가십시오.",
        ["D"] =
        "벤처 투자회사는 보급품이 완전히 불타버려 이곳에서 작업을 계속하기 어려울 것으로 예상합니다. 칼바람 바위산에 대한 다음 위협은 코볼트입니다. 녀석들은 광산에서 광석을 파내기 시작했고, 이 지역 주민들을 공포에 떨게 하고 있습니다.\n\n칼바람 바위산 입구에서 정동쪽에 있는 광산을 찾을 수 있을 겁니다. 그곳의 코볼트들을 모조리 없애고 제게 돌아오십시오. 이 땅의 안전을 위해 그 끔찍한 생물들이 이곳에서 계속 채굴하도록 내버려 두지 않는 것이 중요합니다.",
    },
    [27416] = {
        ["T"] = "돌발톱 숲",
        ["O"] = "돌발톱 산맥의 돌발톱 숲에 있는 사령관 마이네라에게 캘라의 보고서를 배달하십시오.",
        ["D"] =
        "$N, 칼바람 바위산의 문제를 처리하는 데 주신 모든 도움에 감사드립니다. 돌발톱 숲에 계신 제 상관 사령관 마이네라님께서 칼바람 바위산의 상황에 대한 보고서를 요청하셨습니다. 그녀에게 가져다주실 수 있나요? 돌발톱 숲에 가려면 길을 따라 북쪽 끝까지 가십시오.",
    },
    [27417] = {
        ["T"] = "로아의 존중",
        ["O"] = "바다의 로아 그랄에게 바칠 제물로 타나리스 남서부 지역의 이글거리는 로크와 유리껍질 바실리스크로부터 고기를 수집하십시오.",
        ["D"] =
        "어이, 친구. 나는 아키하야, 강력한 주술사이자 바다의 로아 그랄의 시종이지. 자네에게 아주 중요한 임무를 주러 왔네.\n\n안제와사 서쪽에 이글거리는 로크와 유리껍질 바실리스크가 있어. 이 짐승들은 아주 즙이 많은 고기를 제공하는 걸로 알려져 있고, 그랄의 환심을 사려면 아주 많은 양의 고기가 필요해.\n\n사막에서 우리에게 물을 공급하는 정령들이 계속 일하게 하려면 그랄의 축복이 필요하네. 그의 축복이 없으면 정령들은 말라죽고 사라져버릴 거야.\n\n자네가 할 수 있는 한 최대한 많은 고기를 내게 가져오게.",
    },
    [27418] = {
        ["T"] = "로아의 존중",
        ["O"] = "그랄의 환심을 사기 위해 끝자락 해안의 제단에서 그랄에게 제물을 바치십시오.",
        ["D"] =
        "자, 이제 자네에게 또 다른 임무를 주겠네. 이 고기를 끝자락 해안에 있는 제단으로 가져가서 그랄에게 제물로 바쳐줬으면 해. 바라건대 그가 제물에 기뻐하며 우리에게 모습을 드러냈으면 좋겠군.\n\n끝자락 해안의 제단을 찾으려면 안제와사에서 모래 해안에 도달할 때까지 동쪽으로 여행하면 되네. 제단은 물가 근처에서 찾을 수 있어.\n\n제물을 바친 후 안제와사로 돌아오면 자네의 노력에 보상하겠네. 자네의 여정에 그랄의 인도가 함께 하기를.",
    },
    [27419] = {
        ["T"] = "쾅! 쾅! 쾅!",
        ["O"] = "타나리스의 모래폭풍 수렁에 있는 불로크로부터 화염 주머니 8개를 수집하십시오. 녀석들은 주로 뼈 주변에서 발견됩니다.",
        ["D"] =
        "쾅! 쾅! 쾅! 엄청나게 큰 수류탄을 만들고 있어! 왜냐고? 왜 안 되겠어!? 쾅! 쾅! 쾅!\n\n단 한 가지, 불로크에서만 얻을 수 있는 추가적인 추진력이 필요해. 가서 녀석들의 화염 주머니를 좀 모아줄 수 있어?",
    },
    [27420] = {
        ["T"] = "두 발 달린 독수리",
        ["O"] = "추락한 비행선의 약탈자들에게서 마본의 회중시계, 챙 달린 모자, 햄 라디오를 수집하십시오.",
        ["D"] =
        "저는 2주 전에 이곳에 추락했고 이미 제 비행선은 약탈자들에게 점령당했어요.\n\n녀석들은 독수리보다 나을 게 없어요, 어디선가 불쑥 나타나 자기들 것도 아닌 걸 마구 뒤져가죠.\n\n하지만 여기엔 저 혼자뿐이고 제 연구에 집중해야 합니다. 친절하게 약탈자들에게서 제 물건들을 되찾아 주실 수 있나요? 보시다시피 전 지금 가진 게 넝마 조각 하나뿐이거든요.",
    },
    [27421] = {
        ["T"] = "라이트풋 구출",
        ["O"] = "정찰병 라이트풋을 맹독의 둥지 밖으로 호위하고 가는 길에 있는 모든 위협으로부터 그를 방어하십시오.",
        ["D"] =
        "절 찾아주셔서 감사합니다. 맹독의 둥지에서 정찰 임무를 수행하던 중 매복 공격을 받아 기절하고 말았습니다. 여기서 빠져나가 안제와사로 돌아가려면 당신의 도움이 필요합니다. 절 도와주시겠습니까?",
    },
    [27422] = {
        ["T"] = "누구도 공짜로 마실 수 없다",
        ["O"] =
        "수도 요금을 내지 않은 스팀휘들 항구 주민들과 엄하게 대화하십시오. 이 임무를 완료하면 타나리스의 스팀휘들 항구에 있는 보안과장 빌지위즐에게 돌아가십시오.",
        ["D"] =
        "음, 걸어 다니고 말하는 몹시 비열한 녀석처럼 생겼군... 부업 좀 해볼 생각 있나? 이 주변에서 가장 깨끗한 물을 원한다면 우리를 거쳐야 하지. 수수료를 받고 마을의 모든 집에 직접 파이프로 연결해 주고 있어.\n\n어떤 사람들은 우리가 얼마나 관대했는지 이해하지 못하고 요금 내는 걸 \"잊어버린\" 모양이야. 그들을 설득해 줄 누군가가 필요해. 당신이 해줄 수 있겠지?\n\n첫 번째는 미키 스프링소켓 양이야. 그녀는 여관 뒤에서 음식과 음료를 팔고 있지. 두 번째는 우리 마을의 폭발물 중독자인 이나빗 웨지피트야. 마을의 유일한 노움이라 쉽게 찾을 수 있을 거야. 세 번째로 스텔스를 찾아야 해. 그녀는 최근 방어구를 팔고 수리하는 상점을 차렸지. 마지막으로, 생선 냄새가 나는 바보 기킥스야.",
    },
    [27423] = {
        ["T"] = "정찰병의 명예",
        ["O"] = "북서쪽의 맹독의 둥지로 향하여 그곳 상황을 감시하고 있는 섀도댄서라는 이름의 정찰병을 찾으십시오.",
        ["D"] =
        "잘 들으시오, 모험가. 북서쪽 맹독의 둥지 상황을 감시하기 위해 섀도댄서라는 강인한 트롤과 그녀의 정찰대를 파견했소. 그들이 몇 주째 보고가 없어 안전이 우려되오. 맹독의 둥지로 향해 그들을 찾아줄 누군가가 필요하오.\n\n난 무능함을 용납하지 않소. 섀도댄서와 그녀의 일행이 위험에 처해 있다면, 그들을 찾아서 안전을 확보하는 것이 당신의 의무요. 맹독의 둥지로 향하고 그들을 찾을 때까지 돌아오지 마시오. 그리고 경고하건대 -- 이 임무에 실패한다면, 내 분노를 온전히 마주하게 될 것이오. 내 말 뜻 명확히 알겠소?",
    },
    [27424] = {
        ["T"] = "부서진 파티",
        ["O"] = "맹독의 둥지 지상에 있는 센티파르 말벌로부터 센티파르 말벌 독침 8개를 수집하십시오.",
        ["D"] =
        "나머지 정찰대원들은 곤충 실리시드와의 전투 중 마비 독에 쏘여 의식을 잃었고, 전 그들의 안전이 걱정됩니다. 맹독의 둥지 지상에서 볼 수 있는 센티파르 말벌의 독침으로 연고를 만들어 독을 정화하고 그들의 회복을 도와야 합니다.",
    },
    [27425] = {
        ["T"] = "일꾼의 반란",
        ["O"] = "타나리스에 있는 정찰병 섀도댄서를 위해 맹독의 둥지에서 센티파르 일꾼 10마리를 처치하십시오.",
        ["D"] =
        "잘 들으세요, $n. 당신이 센티파르 말벌에게서 독침을 수집하는 동안, 저는 센티파르 일꾼들이 알 수 없는 이유로 의식을 잃은 정찰대원들을 군락 안으로 끌고 가는 것을 보았습니다. 그들이 내 정찰병들을 군락 안으로 더 데려가지 못하도록 일꾼들을 죽여주셔야 합니다.",
    },
    [27426] = {
        ["T"] = "자리에서 일어나",
        ["O"] = "맹독의 둥지 지표면에서 기절한 정찰병 8명을 찾아 부활시키십시오.",
        ["D"] =
        "정찰대의 안전이 위태로우며, 가능한 한 빨리 그들을 부활시켜야 합니다. 맹독의 둥지로 향하여 제가 만든 이 연고를 사용해 기절한 정찰병들을 부활시키세요. 정찰병 전원을 성공적으로 부활시킬 때까지 돌아오지 마세요. 내 말 뜻 명확히 알겠어요, $n?",
    },
    [27427] = {
        ["T"] = "실리시드 쟁탈전",
        ["O"] = "군락 안으로 더 깊이 정찰하여 센티파르 땅굴벌레 6마리와 센티파르 모래약탈자 6마리를 근절하십시오.",
        ["D"] =
        "정찰병들을 부활시키는 데 도움을 주셔서 감사합니다, $n. 이제 센티파르가 내 정찰대에게 한 짓에 대해 복수할 때입니다. 군락 깊숙이 정찰하여 타나리스 모래 아래 터널을 파는 원흉인 센티파르 땅굴벌레와 센티파르 모래약탈자를 근절해 주십시오.\n\n군락은 모든 종류의 치명적인 곤충들로 가득한 위험한 장소입니다. 조심해야 합니다, $n, 그리고 어렵고 위험한 싸움에 대비하십시오. 땅굴벌레와 모래약탈자를 죽이고 저에게 돌아오십시오.",
    },
    [27428] = {
        ["T"] = "벌레 소진",
        ["O"] = "맹독의 둥지 가장 깊은 곳에서 독침 센티파르 또는 우두머리 센티파르의 시체 6구를 불태우십시오.",
        ["D"] =
        "당신을 위한 특별한 임무가 있습니다, $n. 맹독의 둥지 가장 깊은 곳은 독침 센티파르와 우두머리 센티파르를 포함하여 가장 거친 센티파르로 가득 차 있습니다. 그들에게 다가가 이 곤충들을 죽여주셔야 합니다.\n\n하지만 명심할 게 있습니다. 독침 센티파르와 우두머리 센티파르를 죽이면 제가 으깬 독침 반죽을 코팅한 횃불을 사용해 녀석들에게 불을 질러야 합니다. 독침 반죽은 가연성이 매우 높습니다.\n\n보시다시피, $n, 독침 센티파르와 우두머리 센티파르는 센티파르 중에서 가장 강력한 번식력을 지녔습니다. 그들을 죽이고 불을 지름으로써 우리는 그들의 개체수를 격감시키고 그들이 군락을 재건하는 것을 막을 수 있습니다. 위험한 계획이지만, 타나리스 주민들의 안전을 보장하는 유일한 방법입니다. 당신이 이 일을 할 거라고 믿어도 될까요, $n?",
    },
    [27429] = {
        ["T"] = "우룰그의 보고서",
        ["O"] = "정찰 보고서를 안제와사에 있는 우룰그에게 돌려주십시오.",
        ["D"] =
        "우리는 둥지에서 모든 적대적인 생물을 성공적으로 제거했고, 실리시드 독침이 잠재적인 무기가 될 수 있다는 것을 발견했습니다. 이 보고서를 제 상관인 우룰그에게 전달하고 우리의 성공을 알려주시면 감사하겠습니다.",
    },
    [27430] = {
        ["T"] = "안제와사 보급",
        ["O"] = "보급품을 타나리스 남동쪽 구석의 안제와사에 있는 우룰그에게 가져가십시오.",
        ["D"] =
        "반갑소, 모험가. 도전에 응할 생각이 있다면 임무가 있소. 여기서 남동쪽에 있는 우리의 안제와사 전초기지의 보급품이 바닥나가고 있다는 소식을 들었소. 보급품 수송품을 그들에게 가져갈 누군가가 필요하오. 모래지옥 협곡 근처에서 전초기지를 찾을 수 있을 거요 -- 가젯잔에서 남동쪽으로 향하면 찾을 수 있을 거요. 관심 있소?",
    },
    [27431] = {
        ["T"] = "우티 찾기",
        ["O"] = "타나리스의 끝자락 해안에서 우티 선점퍼를 찾아 그녀가 안전한지 확인하십시오.",
        ["D"] =
        "반가워요, 모험가. 당신의 도움이 필요해요. 제 친한 친구인 우티 선점퍼가 며칠째 실종되었어요. 그녀는 숙련된 어부이자 우리 커뮤니티의 귀중한 일원이죠. 그녀에게 무슨 끔찍한 일이 생겼을까 봐 두렵습니다.\n\n끝자락 해안에서 우티를 찾아 주시겠어요? 그녀의 집은 그곳에 있고, 그녀가 마지막으로 목격된 장소이기도 해요. 영원히 빚을 지겠습니다.",
    },
    [27432] = {
        ["T"] = "차가운 낯선 이",
        ["O"] = "우티 선점퍼를 위해 모래해안 해초 8개와 파도글라이더 물 6병을 수집하십시오.",
        ["D"] =
        "투스카르는 사막의 더위 때문에 큰 위험에 처해 있어요. 그를 보호할 냉각 토템 없이는 그가 오래 버티지 못할까 봐 두려워요.\n\n토템을 만들려면 사막 해안에서만 발견되는 모래해안 해초라는 특정한 종류의 해초와 거북이 등껍질의 물이 필요해요. 네, 제 말 맞아요. 거북이 등껍질이요.\n\n어려운 임무가 될 거라는 걸 알지만, 부디 이 재료들을 모아 저를 도와주시기를 간청합니다. 투스카르의 목숨이 달려 있어요.",
    },
    [27433] = {
        ["T"] = "차가운 낯선 이",
        ["O"] =
        "달샘의 물로 수정 유리병을 채우고 끝자락 해안에 있는 우티 선점퍼를 위해 덤불나무 골짜기에서 덤불나무 가시수색꾼으로부터 튼튼한 뿌리 8개를 수집하십시오.",
        ["D"] =
        "냉각 토템이 투스카르를 도울 만큼 강력하지 않을까 봐 걱정입니다. 사막의 열기는 너무 강렬하고, 그는 회복을 위해 더 강력한 재료가 필요해요.\n\n북서쪽 덤불나무 골짜기에 달샘이 있다는 이야기를 들었습니다. 달샘의 물은 강력한 치유력을 가지고 있다고 하더군요. 그 물을 좀 얻을 수 있다면, 토템을 크게 강화할 수 있을 겁니다.\n\n게다가 골짜기에 서식하는 가장 강력한 덤불나무 괴물들은 약초의 효능을 높일 수 있는 튼튼한 뿌리를 가지고 있다고 합니다. 우리를 위해 그 뿌리를 좀 수집해 주신다면 큰 도움이 될 것입니다.\n\n위험한 여정이란 건 알지만, 제발 이 재료들을 구하는 걸 도와주시기를 간청합니다. 투스카르의 목숨이 달려 있습니다.",
    },
    [27434] = {
        ["T"] = "차가운 낯선 이",
        ["O"] = "우티 선점퍼의 집에 있는 투스카르 록나르 옆에 물의 토템을 놓으십시오.",
        ["D"] =
        "토템이 거의 준비되었어요, 모험가. 토템을 투스카르 옆에 두기 위해 당신의 도움이 필요합니다. 그의 상태는 여전히 위독하고 토템은 그에게 필요한 치유를 제공할 거예요.\n\n투스카르 옆에 토템을 놓는 걸 도와주시겠어요? 도와주시면 정말 감사하겠습니다.",
    },
    [27435] = {
        ["T"] = "기술적 진보",
        ["O"] = "스팀휘들 항구로 여행하여 여관주인 피즈마인드에게 투스카르를 위한 냉각기를 요청하십시오.",
        ["D"] =
        "아직 스팀휘들 항구에 연락하지는 않았지만, 그곳에 우리가 투스카르를 구하는 데 사용할 수 있는 기계식 냉각기가 있다는 이야기를 들었습니다. 하지만 정당한 이유 없이는 우리에게 빌려주려 하지 않을까 봐 걱정입니다.\n\n스팀휘들 항구로 가서 여관주인 피즈마인드를 설득해 냉각기를 빌려주시겠어요? 어려운 일이라는 건 이해하지만 당신의 기술과 능력을 믿습니다.\n\n투스카르의 목숨이 달려 있습니다.",
    },
    [27436] = {
        ["T"] = "계속 차갑게",
        ["O"] = "냉각기를 안제와사에 있는 아키하에게 가져가서 그것을 강화하는 방법에 대한 지침을 요청하십시오.",
        ["D"] =
        "고백하자면 우티 선점퍼에게 애정이 있고 그녀를 돕고 싶어요. 냉각기를 빌려드리겠지만, 이 냉각기만으로는 노스렌드의 추위를 재현할 만큼 강력하지 않다는 걸 경고해야겠네요.\n\n냉각기에 힘을 불어넣고 투스카르를 구할 수 있을 만큼 강력하게 만들려면 물의 정령의 도움이 필요할 겁니다. 가장 가까운 물의 정령은 남쪽에 있는 전초기지 안제와사에서 찾을 수 있는데, 당신에게도 익숙한 곳이 틀림없겠죠. 가서 아키하라는 강력한 주술사에게 조언을 구하세요.",
    },
    [27437] = {
        ["T"] = "아쿠아의 축복",
        ["O"] = "안제와사에 있는 두 물의 정령에게 냉각기에 대한 축복을 요청하십시오.",
        ["D"] =
        "자네 눈에서 결단력과 열정이 보이네, 모험가. 자네는 투스카르를 구하는 것의 중요성을 진정으로 믿고 있군. 자네의 결의에 깊은 인상을 받았고 자네를 돕기 위해 내 힘이 닿는 한 모든 것을 하겠네.\n\n하지만 조심하게, 친구. 물의 정령들은 억지로 내게 묶여 있는 게 아니야. 그들은 스스로의 선택으로 나와 유대를 맺었고, 나는 그들의 뜻에 반하는 어떤 일도 하라고 명령할 수 없네.\n\n물의 정령들에게 도움을 요청하고 냉각기의 필요성과 투스카르를 구하는 것의 중요성을 그들에게 납득시켜야 하네. 그렇게 할 수 있다면, 그들은 기꺼이 냉각기에 힘을 불어넣어 투스카르의 목숨을 구할 만큼 강력하게 만들어 줄 걸세.",
    },
    [27438] = {
        ["T"] = "차가운 친구",
        ["O"] = "강화된 냉각기를 투스카르 옆에 두어 일사병을 치료하십시오.",
        ["D"] =
        "모험가님, 투스카르를 구하는 우리의 임무에 당신은 정말 중요한 역할을 하셨습니다. 당신의 도움이 없었다면 우리는 틀림없이 실패했을 것입니다.\n\n당신에게 마지막 부탁을 하나 드리고 싶습니다. 냉각기를 투스카르 옆에 두어 그의 생명을 구해 주시는 영광을 누려주시겠습니까? 제게도 큰 영광이 될 것이고, 투스카르 역시 감사해할 것임을 압니다.",
    },
    [27439] = {
        ["T"] = "위대한 뇌 절도",
        ["O"] = "타나리스의 두 하이브에 있는 실리시드로부터 뇌를 수집하십시오.",
        ["D"] =
        "아, 그래서 자네가 내 연구를 도와줄 영웅인가? 음, 말해두지만 쉬운 일이 아니야. 타나리스의 두 군락에 있는 실리시드의 뇌가 필요하네. 해낼 수 있겠어, 아니면 내가 다른 사람을 찾아야 하나?\n\n세부 사항을 설명할 시간이 없지만, 그냥 내가 실리시드에 대한 연구를 진행 중이고 그 짐승들의 뇌가 필요하다고 해두지. 타나리스의 군락들은 그들로 들끓고 있으니, 거기로 가서 뇌를 최대한 많이 수집해 오게. 돌아오면 기다리고 있겠네.",
    },
    [27440] = {
        ["T"] = "군락의 마음",
        ["O"] = "타나리스의 스팀휘들 항구에 있는 이나빗 웨지피트로부터 듀몬트의 비밀 보급품을 수집하십시오.",
        ["D"] =
        "우리는 실리시드 뇌에서 무언가를 알아냈습니다. 일종의... 심령적 연결고리죠. 그들은 단지 본능에 의해서만 움직이는 것이 아닙니다 -- 모래 언덕 어딘가에 이곳과 맹독의 둥지의 실리시드를 통제하는 위대한 하잘리 지도자가 있습니다.\n\n실리시드 뇌는 매우 단순해서 우리는 폭발물이 장착된 특별한 정신 제어 모자를 만들 겁니다. 여기 데니스에게 아주 잘 어울릴 것 같네요....\n\n스팀휘들의 기괴한 노움 이나빗 웨지피트에게 몇 가지 다른 물건과 함께 모자 제작을 의뢰해 두었습니다. 나를 위해 가져다주실 수 있나요?",
    },
    [27441] = {
        ["T"] = "정신 붕괴",
        ["O"] = "폭발성 정신 제어 모자를 사용하여 데니스를 모래지옥 협곡 하이브 북쪽으로 보내 그 안에 있는 하잘리 뇌군주를 파괴하십시오.",
        ["D"] =
        "실리시드는 뇌가 반쯤 없어도 \"기능\"할 수 있는 단순한 짐승입니다. 저기 저 작은 데니스가 대표적인 예죠. 슬프게도, 이 모자는 그 녀석을 위한 겁니다.\n\n실리시드는 그를 공격하지 않을 테니, 이를 통해 우리는 모래지옥 협곡 하이브 깊숙이 들어가 그들을 조종하는 뇌군주를 처치할 수 있습니다. 릴린은 자신의 애완동물을 희생하는 것을 전혀 개의치 않을 거라고 확신합니다.",
    },
    [27442] = {
        ["T"] = "소탕된 군락",
        ["O"] = "우룰그에게 모래지옥 협곡 하이브에서 가장 강력한 실리시드를 성공적으로 제거했다고 알리십시오.",
        ["D"] =
        "제가 예상했던 것보다 훨씬 더 성공적이었네요. 머지않아 여길 정리하고 언더시티의 진짜 연구실로 돌아갈 수 있을 것 같습니다. 가서 그 퉁명스러운 멍청이 우룰그에게 좋은 소식을 전하세요.",
    },
    [27443] = {
        ["T"] = "아제로스 우주 협회(A.S.S.)",
        ["O"] = "스팀휘들 항구에서 아제로스 우주 협회의 고다드를 찾으십시오.",
        ["D"] =
        "우리의 수석 로켓 과학자 고다드가 스팀휘들 항구에 자신의 실험용 로켓 개발 플랫폼을 설치했네. 바다 위로 발사하는 게 더 안전하다나 뭐라나 -- 하지만 언제부터 안전을 따졌다고 그래?\n\n최근 그가 핵심 재료를 추적하는 데 도움이 필요하다고 불평하더군.\n\n가서 그를 찾아 그가 원하는 게 뭔지 알아봐 줄 수 있나?",
    },
    [27444] = {
        ["T"] = "완벽한 연료",
        ["O"] = "해그늘 폐허에서 고대 배터리 8개와 전갈 사냥꾼으로부터 추출된 전갈 독 주머니 6개를 수집하십시오.",
        ["D"] =
        "지금 내 바로 뒤에 있는 소중한 구조물을 위한 완벽한 로켓 연료를 개발하고 있소. 연료는 모든 것의 핵심이고, 그것이 없다면 이것은 단지 지나치게 큰 어... 상징물에 불과할 거요. 그럴 순 없지!\n\n이곳 서쪽 해그늘 폐허의 고대 트롤들은 초보적인 형태의 태양열 배터리를 만들곤 했지. 수십 년 동안 사막의 태양 아래 구워지면서 배터리 동력은 증가하기만 했소. 가서 좀 모아 주시겠소, $n?\n\n하는 김에 근처의 전갈들에게서 얻을 수 있는 가장 큰 독 주머니도 필요하오.",
    },
    [27445] = {
        ["T"] = "완벽한 연료",
        ["O"] = "스팀휘들 항구 북동쪽에 있는 석유 굴착 장치 바닥에서 원유를 수집하십시오.",
        ["D"] =
        "이곳 북동쪽 석유 플랫폼 바닥에 석유를 정제하기 전후에 순도를 테스트하는 데 사용하는 밸브가 있소. 정제되지 않은 가장 거친 원유가 필요하니, 물속에서 훔쳐 와야 한다는 뜻이지. 그 플랫폼으로 가서 이 용기를 가져가시오. 밸브에서 용기를 채우고 다시 내게 가져와서 계속할 수 있게 하시오.",
    },
    [27446] = {
        ["T"] = "완벽한 용기",
        ["O"] = "가젯잔 서쪽의 추락한 노움 경주용 차에서 노움 자동차 부품 6개를 획득하십시오.",
        ["D"] =
        "완벽한 연료를 로켓에 안전하게 저장할 방법이 없다면 아무 소용이 없소. 이 부근 최고의 야금술은 버섯구름 봉우리의 신기루 경주장에 있는 노움 경주팀이 다루지만, 슬프게도 녀석들은 공유하려 들지 않아! 무슨 \"영업 비밀\"이나 \"우리 걸 훔치려 들지 마라\" 같은 변명을 대더군.\n\n그들의 실험용 차 중 하나가 타나리스 밖까지 와서 추락했다는 소문이 퍼졌지. 난 그 차의 금속을 원하오! 가젯잔 외곽에서 추락 현장을 찾아 무슨 수를 써서라도 그 부품을 가져오시오!",
    },
    [27447] = {
        ["T"] = "더 좋은 연료",
        ["O"] = "스팀휘들 항구의 풀을 위해 돌연변이 바실리스크 분비선 하나와 유리껍질 분비선 6개를 수집하십시오.",
        ["D"] =
        "쉿... 이리 와... 목소리 낮춰.\n\n이봐, 우리끼리 얘기인데 난 여기 고다드가 얼간이라고 생각해. 끊임없이 날 닦달하고 자기가 얼마나 똑똑한지 허풍이나 떨고. 이젠 지쳤어! 수석 로켓 과학자는 단 한 명뿐일 수 있어. 예산이 더 이상 허락하지 않거든. 그러니... 녀석을 없애는 걸 도와주면 녀석보다 널 더 잘 대우해 주지. 어때?\n\n점화될 때 재앙적인 결과를 초래할 몇 가지 추가 재료를 혼합물에 넣을 생각이야. 도와줄 의향이 있다면 모래 언덕의 유리껍질 바실리스크들의 분비선이 필요해. 그건 연료에 들어가는 비교적 정상적인 성분이지. 진짜 불꽃은 근처에서 순찰하는 걸 본 돌연변이에게서 나올 거야. 내 생각엔 기름 때문에 녀석이 이상해진 것 같아! 녀석은 여기서 남쪽 해변을 순찰하는 게 목격됐어. 가서 혼합물에 추가할 녀석의 분비선을 내게 가져와.\n\n그리고 이건 우리끼리 비밀로 해. 안 그러면 우리 둘 다 가젯잔 밖에서 목이 졸리게 될 테니까.",
    },
    [27448] = {
        ["T"] = "위험한 혼합물",
        ["O"] = "나라인의 집에서 로켓 연료 재료를 조합하여 스팀휘들 항구의 고다드에게 실험용 로켓 연료를 가져가십시오.",
        ["D"] =
        "자, 이제 드디어 모든 걸 섞어볼 시간이오. 귀찮은 내 조수가 당신을 위해 모든 걸 한데 묶어 두었소. 자, 받으시오.\n\n유일한 문제는 과정의 이 부분이... 잘못하면 폭발할 수도 있다는 거요. 나는 항구 벽 안에서 시도하는 것조차 명시적으로 금지당했소. 그러니 가장 가까운 적당한 후보지에서 이것을 섞어보는 게 어떻소? 생각 좀 해보지... 알겠소! 마을 북쪽에 있는 저 바보 나라인의 집이 좋겠군. 녀석은 우리가 여기서 하는 일에 대해 끊임없이 불평하고 있으니, 이것으로 두 가지 가능한 결과가 생기지.\n\n제대로 섞이면 아무 일도 일어나지 않소. 만약 아니라면, 글쎄, 폭발하는 건 당신과 녀석뿐이겠지. 윈-윈 아니겠소.",
    },
    [27449] = {
        ["T"] = "마지막 카운트다운",
        ["O"] = "고다드 옆에 있는 기폭 장치를 눌러 로켓의 이륙 절차를 시작하십시오.",
        ["D"] =
        "이제 때가 됐소 $n! 드디어 이 로켓을 테스트하고 고블린이 얼마나 높이 날 수 있는지 볼 거요. 물론 처음엔 무인으로. 당신이 아주 큰 도움이 되었으니, 내 바로 옆에 있는 저 기폭 장치를 눌러서 영광을 누려보지 않겠소? 그러면 테스트가 시작될 거요.",
    },
    [27450] = {
        ["T"] = "A.S.S. 정비",
        ["O"] = "풀의 보고서를 가젯잔의 A.S.S. 창립자 크란츠에게 가져가십시오.",
        ["D"] =
        "히, 히, 히, 완벽했어! 운고로까지 로켓 연기를 볼 수 있었을 거라고 장담해. 이제 사장에게 약간의 의심만 심어주면 눈 깜짝할 사이에 고다드의 일자리는 내 차지가 될 거야.\n\n여기서 일어난 일에 대해 내가 작성한 보고서야. 이걸 우리 단체의 창립자인 크란츠에게 가져가면 여기서 네 일은 끝이야.",
    },
    [27451] = {
        ["T"] = "전승지기 반자",
        ["O"] = "타나리스의 안제와사에서 전승지기 반자를 찾으십시오.",
        ["D"] =
        "관심이 있다면 사막으로 갈 메신저가 필요하네.\n\n타나리스 남쪽에 트롤 정착지인 안제와사가 있지. 전승지기 반자가 몇 주 전에 그곳에 갔는데 아직 진행 상황 보고서를 보내오지 않았네. 그 지역에 있다면 내게 소식을 전해줄 수 있겠나, 고맙겠네.",
    },
    [27452] = {
        ["T"] = "죽음의 메시지",
        ["O"] = "타나리스 해안을 수색하여 전승지기 반자의 실종된 메신저를 찾으십시오.",
        ["D"] =
        "전승지기 자니가 내 보고서를 받지 못했다면 메신저들에게 무슨 일이 생긴 게 틀림없네. 그들의 목숨이 걱정되는군, 친구.\n\n둘 다 해안 경로를 이용하라고 했지 -- 실리시드와 모래 폭풍을 피할 수 있으니까. 해안을 수색해서 그들의 흔적을 찾을 수 있는지 확인해 줄 수 있나? 그리고 조심하게, $C.",
    },
    [27453] = {
        ["T"] = "죽음의 메시지",
        ["O"] = "전승지기 반자에게 돌아가 나쁜 소식을 전하십시오.",
        ["D"] =
        "죽은 트롤의 무기에는 인간형 생물의 피가 엉겨 붙어 있습니다. 녀석들은 죽기 전에 꽤 격렬하게 싸웠습니다. 시체에서 부패로 인한 것이 아닌 이상하게 검게 변한 피부를 발견합니다.\n\n시신을 검사해 보니 그들의 전령 주머니가 비어 있는 것을 발견합니다. 그들이 가지고 있던 메시지가 무엇이든 약탈당한 반면, 다른 귀중품들은 남겨져 있었습니다.\n\n전승지기 반자가 이 사실을 알아야 합니다.",
    },
    [27454] = {
        ["T"] = "무덤 수색",
        ["O"] = "줄파락 근처의 모래망치 트롤에게서 툴마리의 징표 6개를 수집하십시오.",
        ["D"] =
        "난 세계의 분리 이전 시대의 고대 트롤 영웅인 툴마리의 무덤을 찾아 타나리스에 왔지. 무덤이 타나리스에 있다고 믿지만 모래망치 부족도 툴마리를 자신들의 조상이라고 주장하고 있네. 그들은 무덤이 어디 있는지 알고 있고, 내가 그걸 찾는 걸 원치 않지. 협상해 보려 했지만 실패했다네.\n\n시체에서 자네가 본 검은 피부는 모래망치 독이야. 녀석들이 내 메신저들을 죽이고 있다면 녀석들을 죽여 달라고 자네에게 부탁하겠네! 모래망치 부족은 툴마리의 말이 적힌 작은 징표를 가지고 다니지. 녀석들이 내가 원하는 걸 평화롭게 주지 않겠다면, 무력을 써서라도 녀석들에게서 그것을 빼앗겠어.",
    },
    [27455] = {
        ["T"] = "무덤 수색",
        ["O"] = "오그리마의 전승지기 기힌에게 툴마리의 징표 번역을 부탁하십시오.",
        ["D"] =
        "<전승지기 반자가 한숨을 쉽니다.>\n\n알았어야 했는데. 이 징표들은 고대 모래 트롤 언어로 쓰여 있어서 난 읽을 수가 없네.\n\n하지만 오그리마의 전승지기 기힌은 이것을 읽을 수 있지. 이 징표들을 그에게 가져가서 뭐라고 적혀 있는지 물어봐 주게.\n\n정기의 골짜기에서 다른 전승지기들과 함께 있는 그를 찾을 수 있을 거야.",
    },
    [27456] = {
        ["T"] = "무덤 수색",
        ["O"] = "줄파락의 의술사 줌라를 처치하고 오그리마의 전승지기 기힌을 위해 그의 부적의 고서를 획득하십시오.",
        ["D"] =
        "내가 번역 작업을 하는 동안 자네가 나를 위해 작은 부탁을 하나 들어준다면 이 번역을 반자를 위해 해주지. 어차피 타나리스에서 일하고 있으니, 줄파락에 있는 내 오랜 친구 의술사 줌라를 찾아가 보게.\n\n오래전 그는 내가 되찾고 싶은 부적에 대한 오래된 비법을 훔쳐 갔어. 그가 순순히 내놓지 않을 테니, 그를 죽이고 부적의 고서를 내게 가져오게.\n\n그러면 번역본을 주지.",
    },
    [27457] = {
        ["T"] = "무덤 수색",
        ["O"] = "번역본을 타나리스의 안제와사에 있는 전승지기 반자에게 가져가십시오.",
        ["D"] =
        "전승지기 반자가 요청한 번역본이 여기 있네. 내 생각엔 자네가 해야 할 일이 더 많아진 것 같군. 보아하니, 그가 찾는 무덤이 세계의 분리 때 파도 아래 묻혔다고 하네. 그리고 반자, 그는 바다를 무서워하지.\n\n<전승지기 기힌이 킬킬거립니다.>\n\n다행히도 마법의 장벽이 무덤을 보호하여 물이 들어오는 것을 막아준다고 하니, 그걸 찾으면 그 아래에서도 숨을 쉴 수 있을 거야. 행운을 비네, $C.",
    },
    [27458] = {
        ["T"] = "무덤 수색",
        ["O"] = "툴마리의 무덤을 찾고 드렉의 망치를 회수하십시오.",
        ["D"] =
        "툴마리는 드렉의 용사였고 그가 죽었을 때 그의 망치를 물려받았지. 전설에 따르면 망치는 그녀와 함께 묻혔다고 하네. 그게 내가 찾고 있는 거야.\n\n하지만 이 번역본에 따르면 무덤은 타나리스 남쪽 해안 앞바다의 파도 아래 묻혔다고 하네. 난 수영을 못해, $C, 그리고 바다는 질색이야.\n\n나를 위해 남쪽 연안 해역을 수색해서 무덤을 찾아줘, 간청하네.",
    },
    [27459] = {
        ["T"] = "무덤 수색",
        ["O"] = "썬더 블러프에 있는 전승지기 자니에게 소식을 전달하십시오.",
        ["D"] =
        "자, 이제 썬더 블러프에 있는 전승지기 자니에게 돌아가서 제대로 보고하게.\n\n그는 내가 무덤을 찾지 못할 거라고 내기를 걸었지. 그래서 이제 그는 내게 엄청난 양의 밀림덩굴 포도주를 빚지게 되었네.\n\n그럼 어서 가게, 부두교 주술을 조심하고.",
    },
    [27460] = {
        ["T"] = "그들은 주로 밤에 온다... 주로",
        ["O"] = "밤에 타나리스의 흑호들에게서 흑호 턱뼈 10개를 수집하십시오.",
        ["D"] =
        "저주받을 실리시드들이 또 말썽을 부리고 있어요. 녀석들이 타나리스에 있는 자신들의 영역을 지키기 위해 흑호를 보낸 것이 목격되었죠. 이 짐승들은 밤에만 나오기 때문에 녀석들을 추적하려면 조심해야 할 겁니다.\n\n맹독의 둥지와 모래지옥 협곡에서 흑호들을 찾을 수 있어요. 맹독의 둥지는 북서쪽 멀리 떨어져 있고, 모래지옥 협곡은 안제와사 바로 외곽에 있죠.\n\n힘과 교활함을 사용하여 녀석들을 물리치고 승리의 증거로 턱뼈를 수집하세요.",
    },
    [27461] = {
        ["T"] = "동물들을 생각하세요",
        ["O"] = "타나리스 해안을 따라 기름으로 덮인 동물 8마리를 닦아주십시오.",
        ["D"] =
        "고블린들이 그 굴착 장치를 건설한 이후로 저는 해안을 따라 오르내리며 그들이 흘린 기름으로 덮인 동물들을 발견하고 있습니다. 야생동물들이 고통받고 있으며, 그들이 이런 모습을 보면 제 마음이 찢어집니다.\n\n어떻게 좀 해주실 수 없나요? 제가 그들을 다 구할 수는 없어요. 여기, 이 청소용품을 가져가서 기름을 뒤집어쓴 짐승들을 발견하면 도와주세요.",
    },
    [27462] = {
        ["T"] = "폐기물 제거",
        ["O"] = "타나리스 해안을 따라 바다에 있는 기름 유출 6곳을 청소하십시오.",
        ["D"] =
        "이 기름이 새고 있는 바다 속 통들을 제거하지 않으면 동물을 몇 마리나 닦아주는지는 아무 소용이 없을 거예요.\n\n이 기름 흡수제를 가지고 해안을 따라 가보세요. 기름 유출을 발견하면 모두 제거해 주세요. 많으면 많을수록 좋아요.\n\n해주실 수 있나요?",
    },
    [27463] = {
        ["T"] = "필사적인 조치",
        ["O"] = "가젯잔의 버젝 브래킷스윙에게서 마라이의 \"보급품\"을 수집하십시오.",
        ["D"] =
        "진저리가 나네요! 새로운 동물들이 고통받고 바다에 버려지는 새 통들을 이미 볼 수 있어요. 수도 회사는 화려한 필터 헛소리를 늘어놓으며 저를 돕지 않을 거예요. 이 오염을 막으려면 진짜 근원지로 가야 해요...! 저 석유 굴착 장치는 사라져야 해요... 영구적으로요.\n\n버젝이라는 이름의 가젯잔에 있는 마스터 기술자에게 연락했고 그가 저를 위해 몇 가지 \"보급품\"을 준비했어요. 가서 가져와 주시겠어요? 앞으로 일어날 일에 중요하게 쓰일 거예요.",
    },
    [27464] = {
        ["T"] = "석유 재벌 때려잡기",
        ["O"] = "스팀휘들 항구 북쪽 석유 굴착 장치에서 굴착 장치 일꾼 8명과 그들의 우두머리인 감독관 루니를 처치하십시오.",
        ["D"] =
        "석유 굴착 장치를 무너뜨리기 위한 첫 번째 단계는 굴착 장치 일꾼들을 제거하는 것입니다. 그들의 우두머리는 감독관 루니라는 이름으로 굴착 장치 꼭대기 통제실에 있습니다.\n\n나머지 일꾼들은 그냥 하수인이지만, 그들은 자신의 금전적 이득을 위해 동물들이 고통받는 것을 신경 쓰지 않으니 그것만으로도 충분합니다. 도대체 어떤 괴물이 그런 짓을 한답니까?",
    },
    [27465] = {
        ["T"] = "굴착 장치를 가라앉혀라",
        ["O"] = "스팀휘들 항구 북쪽의 석유 굴착 장치에서 약간 열린 기름통 주변에 폭발물 4개를 설치하십시오.",
        ["D"] =
        "그리고 이제 이 작은 문제에 대한 최종 해결책입니다. 일꾼들이 죽으면 열려 있는 통 근처에 이 폭발물을 설치하기만 하면 됩니다. 그에 따른 연쇄 반응은 재앙적일 것입니다. 굴착 장치를 다시는 사용할 수 없도록 가능한 한 많은 곳에 설치하십시오.",
    },
    [27466] = {
        ["T"] = "불의 팁",
        ["O"] = "타나리스의 안제와사에서 멜코르 블러드러너를 찾으십시오.",
        ["D"] =
        "최근 실리시드 독침을 으깨어 반죽으로 만들어 가연성 무기로 사용할 수 있다는 사실을 발견하셨다고 들었습니다. 이 정보는 얼라이언스와 실리시드 모두에 맞서는 계속되는 전쟁에서 우리의 대의에 가치가 있을 것입니다. 멜코르 블러드러너라는 포세이큰에게 이 정보를 전달하는 데 도움을 주십사 요청합니다. 그는 안제와사 내의 근처 동굴에서 찾을 수 있습니다.",
    },
    [27467] = {
        ["T"] = "불의 팁",
        ["O"] = "타나리스의 모래지옥 협곡에 있는 하잘리 말벌로부터 하잘리 말벌 독침 8개를 수집하십시오.",
        ["D"] =
        "실리시드 독침의 잠재력을 알았으니 이 기회를 빌려 더 자세히 탐구하고 싶습니다. 새로운 퀘스트가 있습니다, $n. 이 독침들을 더 모아 주셨으면 하는데, 이번에는 훨씬 더 강한 하잘리 말벌에게서 얻으십시오. 이 반죽을 대량으로 공급받으면 타나리스에 있는 우리 호드 부대를 위한 특제 불화살을 만들 수 있습니다. 우리를 도와줄 거라 믿어도 되겠습니까?",
    },
    [27468] = {
        ["T"] = "불의 팁",
        ["O"] =
        "멜코르 블러드러너가 제공한 아이템을 사용하여 운고로 분화구의 타르 괴물로부터 타르를 흡수하십시오. 타르 괴물은 쇠약해진 상태여야 합니다.",
        ["D"] =
        "이제 독침을 얻었으니 불화살을 가능한 한 강력하게 만드는 데 집중해야 합니다. 타르 괴물의 핵에서 직접 타르를 흡수할 수 있는 특별한 용기를 고안했지만, 그러려면 녀석들이 약해져 있고 살아있어야 합니다. 고통스러운 과정이지만, 때때로 과학은 희생을 요구합니다. 타르 괴물은 근처 운고로 분화구의 락카리 잿구덩이에서 찾을 수 있습니다.",
    },
    [27469] = {
        ["T"] = "불의 팁",
        ["O"] = "안제와사의 레미 콜드아이에게 불화살을 가져가십시오.",
        ["D"] =
        "불화살이 완성되었습니다, $n. 이제 사용할 때입니다. 이것을 레미 콜드아이에게 전달해 주시면 실리시드와의 전투에 사용할 신병들에게 배포할 것입니다.",
    },
    [27470] = {
        ["T"] = "수도 회사 구원자",
        ["O"] = "스팀휘들 항구 주변 해저에서 여과기 부품 8개를 수집하십시오.",
        ["D"] =
        "스팀휘들 항구는 수도 회사 제국의 심장부이지만, 여과 시스템에 심각한 손상이 생겨서 지금은 전적으로 예비 물량에만 의존하고 있습니다.\n\n부품 화물을 기다리고 있었는데, 기중기를 조작하는 멍청한 녀석들이 배가 정박할 때 상자 대부분을 바다로 떨어뜨리고 말았습니다! 요즘엔 좋은 인재를 구할 수가 없다니까요!\n\n그 부품들이 녹슬어서 못 쓰게 되기 전에 해안을 따라 잠수해서 가져다주실 수 있나요?",
    },
    [27471] = {
        ["T"] = "여성 일꾼의 도구",
        ["O"] = "버섯구름 봉우리의 소금 평원에 있는 신기루 경주장의 래저릭으로부터 킥스의 배터리 강화 용접기를 수집하십시오.",
        ["D"] =
        "화물에서 기대했던 것 중 하나가 제가 여기서 사용할 수 있는 새롭고 강력한 아크 용접기였습니다. 그것이 물에 닿자마자 망가졌기 때문에 굳이 당신에게 낚시해 오라고 부탁하지는 않았죠.\n\n신기루 경주장에서 고블린 경주팀을 위해 일하는 제 좋은 친구에게 빌려준 여분이 하나 있습니다. 가서 좀 부탁해 보시겠어요? 그가 기꺼이 내주지는 않겠지만 우리의 요구가 어떤 경주용 자동차보다 더 중요하니까요.",
    },
    [27472] = {
        ["T"] = "여성 일꾼의 도구",
        ["O"] = "타나리스의 모래 언덕을 가로지르는 약해진 맹렬한 폭풍우를 사용하여 킥스의 배터리를 충전하십시오.",
        ["D"] =
        "이 용접기의 유일한 문제는 래저릭이 충전해 두지 않았다는 것입니다. 전형적인 그의 방식이죠.\n\n타나리스 모래 언덕 바깥쪽에 우리가 맹렬한 폭풍우라고 부르기 시작한 희귀한 정령이 있습니다. 녀석들은 엄청나게 강력한 전기로 가득 차 있습니다! 녀석들에게서 에너지를 빼내면 용접기 배터리를 빠르게 충전할 수 있을 겁니다.\n\n먼저 폭풍우를 약화시킨 다음 충전기로 녀석을 쏘아야 합니다. 당신이 알기도 전에 고품질 H2O가 다시 이곳으로 흐르는 길에 서게 될 것입니다.",
    },
    [27473] = {
        ["T"] = "물 분사",
        ["O"] = "모래 언덕 중앙에 있는 무너진 기둥 폐허 근처의 추락한 비행선에서 연료 분사기 8개를 수집하십시오.",
        ["D"] =
        "잠깐, 잠깐, 잠깐. 뭔가 단단히 잘못됐어요. 수압이 우리가 필요로 하는 것 근처에도 못 미치네요. 생각해 봅시다....\n\n알겠어요! 이곳 남서쪽, 무너진 기둥 폐허에 한때 우리가 고용했던 미치광이 과학자가 있어요. 그의 비행선이 근처에 추락했고 연료 분사기를 몇 개 싣고 있었어요. 약간만 손보면 물 분사기가 되도록 개조할 수 있어요. 꽤 먼 길이지만 가서 가져다주시겠어요? 모래 언덕 한가운데로 들어가면 추락 현장은 쉽게 찾을 수 있을 거예요.",
    },
    [27474] = {
        ["T"] = "우리 중의 사보추어",
        ["O"] = "스팀휘들 항구의 폭력배들을 심문하여 어두운 인물이 누구이고 어디로 갔는지 알아내십시오.",
        ["D"] =
        "사보추어! 이제 모든 게 이해가 되네요... 녀석들이 우리 부품을 고의로 바다에 빠뜨렸음이 틀림없어요! 그들은 애초에 여과기를 파괴한 녀석들이었어요! 하지만 누구일까요?\n\n녀석들이 어디로 도망쳤는지 정확히 보지는 못했지만 그건 폭력배들이 돈값을 해야 할 일이죠. 가서 그들이 무엇을 보았는지 물어보세요.",
    },
    [27475] = {
        ["T"] = "분명한 비난",
        ["O"] = "스팀휘들 항구의 보안과장 빌지위즐에게 수자원 여과 시스템을 파괴한 것으로 의심되는 자가 누구인지 알리십시오.",
        ["D"] =
        "다들 도즈저드라는 동일 인물을 언급했다고요. 왜 그 이름이 그렇게 귀에 익을까요? 폭력배! 그는 경비병 중 한 명이에요. 내부 소행이군요! 보안과장에게 이 사실을 알려야 합니다. 지금 당장 그에게 가세요!",
    },
    [27476] = {
        ["T"] = "현상 수배: 도스주르드",
        ["O"] = "이전 폭력배였던 도스주르드를 찾아 처치하십시오. 가젯잔 바로 외곽에서 목격되었다고 합니다.",
        ["D"] =
        "배신자 도스주르드가 가젯잔에서 보급품을 구하고 성문을 나서는 것이 목격되었다고 요원들이 알려왔습니다. 그가 어디에 있든 조금만 걸어가면 될 겁니다. 수도 회사를 대신하여 녀석을 찾아 처치하십시오. 임무를 마치면 보안과장에게 보고하십시오.",
    },
    [27477] = {
        ["T"] = "마른가지 공격",
        ["O"] = "마른가지 주술사 4명, 마른가지 수호병 4명, 마른가지 복병 4명, 마른가지 전사 4명을 처치한 후 텔드랏실의 돌라나르에 있는 멜라리스에게 돌아가십시오.",
        ["D"] =
        "마른가지 부족의 동족에 대한 공격이 점점 잦아지고 있어 걱정이 되기 시작했습니다. 그들에 맞선 전투에서 우리를 도와주시겠습니까?\n\n텔드랏실 곳곳에 흩어져 있는 그들의 부족원을 찾을 수 있지만, 정찰병의 보고에 따르면 그들은 이 서쪽의 길 바로 옆과 바네실 지하굴 근처에 모여 있다고 합니다. 나가서 그들을 처치해, 동족이 안전하다는 것을 내게 알려주십시오.",
    },
    [27478] = {
        ["T"] = "마른가지 공격",
        ["O"] = "아갈, 나르글, 그린포우를 처치하고 돌라나르에 있는 멜라리스에게 돌아가십시오.",
        ["D"] =
        "그들의 지도부를 치지 않는다면 마른가지의 수는 계속 늘어날 것입니다. 족장이 없으면 따를 곰도 없어집니다. 그들의 부족은 무너지고 뿔뿔이 흩어질 것입니다.\n\n첫 번째 족장은 아갈입니다. 그는 바네실 지하굴 바로 북쪽 동굴에 살고 있습니다. 두 번째와 세 번째 족장인 나르글과 그린포우는 지하굴 깊은 곳에 살고 있습니다. 내가 당신이라면 혼자 가지 않을 것입니다. 요새는 매우 깊고 길을 잃기 쉽습니다.\n\n이 임무에 행운을 빕니다, $n. 무사히 돌아와서, 마른가지 부족을 끝내주십시오.",
    },
    [27479] = {
        ["T"] = "붉은깃털 알",
        ["O"] = "붉은깃털 알 6개를 수집하여 텔드랏실의 신탁의 숲에 있는 알란나 레이븐아이에게 돌아가십시오.",
        ["D"] =
        "근처에 있는 붉은깃털 하피들을 본 적 있나요? 이 땅을 침범했지만 신비롭고 아름다운 생물들이죠.\n\n저는 마법을 연구하는데, 그들이 낳는 알에 마법적 특성이 있을 수 있다고 생각해요. 알을 좀 가져다주시면 조사해 볼 수 있을 텐데, 가능할까요?",
    },
    [27480] = {
        ["T"] = "그늘 협곡의 타락",
        ["O"] = "나투크와 광란의 달빛야수 8마리를 처치한 후, 그늘 협곡의 알드랏실에 있는 알라네아 미스트스트라이커에게 돌아가십시오.",
        ["D"] =
        "달빛야수 무리가 그늘 협곡에 자리를 잡았습니다! 우리는 달빛야수에게 어떤 원한도 없으며 사실 많은 달빛야수가 우리의 동맹입니다. 하지만 이 무리는 엘룬과의 연락을 끊고 숲 전역에서 혼란을 일으키고 있습니다.\n\n무언가가 이 달빛야수들을 타락시켜 통제 불능에 혼란스럽게 만든 것이 제 생각입니다.\n\n이 무리는 이 동쪽에 있는 펄볼그 야영지를 점령했습니다. 녀석들의 지도자를 처치하고 나머지 무리를 해산시켜 그늘 협곡 생태계의 균형에 심각한 피해를 주기 전에 막아주십시오!",
    },
    [27481] = {
        ["T"] = "수습 호랑이 타기",
        ["O"] = "잘트삼으로부터 수습 타기를 배운 후, 다르나서스에 있는 렐라나이와 대화하여 호랑이를 받으십시오.",
        ["D"] =
        "돌아온 걸 환영하오. 수습 타기를 배우러 왔군, 맞소? 이전과 마찬가지로 호랑이 가격은 지불되었지만 훈련 비용은 직접 내야 하오. 유감스럽지만 신속하게 타는 건 비싸다오.\n\n훈련을 받은 후 바로 옆에 있는 렐라나이와 얘기하시오. 그녀가 우리 호랑이 판매를 관리하오. 아직 자금이 없다면 언제든지 다시 와도 좋소.",
    },
    [27482] = {
        ["T"] = "호랑이 타기",
        ["O"] = "잘트삼으로부터 초급 타기를 배운 후, 다르나서스에 있는 렐라나이와 대화하여 호랑이를 받으십시오.",
        ["D"] =
        "그래서 호랑이를 구하러 왔나 보군? 마침 당신을 기다리고 있었소! 수수께끼의 후원자가 일반 호랑이에 대한 대금을 남겼는데 당신 이름인 $N 앞으로 되어 있더군. 하지만 훈련 비용까지 내주진 않았으니 그건 당신이 지불해야 할 거요.\n\n훈련을 받은 후 바로 옆에 있는 렐라나이와 얘기하시오. 그녀가 우리 호랑이 판매를 관리하오. 아직 자금이 없다면 나중에 다시 와도 좋소.",
    },
    [27483] = {
        ["T"] = "악마 바위굴의 악마들",
        ["O"] = "악마 바위굴에서 악마의 정수 10개를 수집하여 돌라나르에 있는 지나 피더보우에게 돌아가십시오.",
        ["D"] =
        "반갑습니다, 돌라나르에서 새로운 $c을(를) 보게 되어 반갑군요. 최근 텔드랏실에서 발생한 타락에 대해 들어보셨겠죠?\n\n악마들이 이 땅을 침략했고, 우리 정찰병의 보고에 따르면 이곳 바로 북쪽에 있는 악마 바위굴이라는 동굴에 엄청난 수의 악마가 집중되어 있다고 합니다.\n\n그들을 처치하고 악마의 정수를 제게 가져다주시면 우리가 정화할 수 있을 것입니다.",
    },
    [27484] = {
        ["T"] = "정수 정화",
        ["O"] = "돌라나르에 있는 달샘에서 악마의 정수를 정화하고 지나 피더보우에게 돌아가십시오.",
        ["D"] =
        "악마의 정수는 악마가 소환된 차원에 그들을 속박하므로, 그들의 영혼을 이 세계에서 제거하려면 그것을 정화해야 합니다.\n\n나이트 엘프 영토 전역에 많은 달샘이 있지만, 가장 가까운 곳은 바로 여기 돌라나르에 있습니다. 달샘으로 가서 이 정수를 정화하십시오. 그러면 그들의 영혼이 아제로스에서 영원히 추방될 것입니다.",
    },
    [27485] = {
        ["T"] = "약초 의학",
        ["O"] = "아리스리엔 연못에서 백합 채찍 8개를 수집하여 텔드랏실의 돌라나르에 있는 말로른 블레이드리프에게 돌아가십시오.",
        ["D"] =
        "많은 사람들이 약초는 해를 끼치는 물약을 만드는 데만 사용된다고 생각하지만, 약초는 가장 먼저 의학에 사용되었습니다. 언제 올빼미가 광견병에 걸려 동맹을 공격할지 모르니, 항상 약을 준비해 두는 것이 좋습니다.\n\n서쪽 멀리 떨어진 아리스리엔 연못에서 백합 채찍 몇 개를 가져다주시면 당신을 위한 약을 만들어 드릴 수 있습니다. 당신이 가져온 샘플이 마음에 든다면 당신을 위해 직접 만들 수 있는 방법을 알려드릴지도 모르고요.",
    },
    [27486] = {
        ["T"] = "호박색 유물",
        ["O"] = "호박색 유물의 미스터리를 푸십시오.",
        ["D"] =
        "족장 더스트후프의 방황하는 영혼으로부터 빼앗은 부적은 겉보기에 특별해 보이지 않습니다. 금속은 변색되었고 세팅에 호박 조각이 아무렇게나 박혀 있는 낡은 청동 펜던트입니다.\n\n이 장신구가 얼마나 오래되었는지 또는 그 가치가 얼마인지 확실하지 않습니다. 이 아이템을 조사하자 차가운 돌풍이 불어와 당신을 소금 평원 북쪽 가장자리 방향으로 부릅니다.\n\n조사해 보시겠습니까?",
    },
    [27487] = {
        ["T"] = "영혼의 모임",
        ["O"] = "잊혀진 땅의 해안에서 위브리프 8다발을 수집하십시오.",
        ["D"] =
        "우리 부족의 먼 과거에 우리는 마샨쉬의 초원을 누볐지만, 이 지역에 재앙이 닥쳐 생명체가 살 수 없는 황무지가 되었습니다. 우리 부족은 족장 더스트후프의 인도 아래 지금은 잊혀진 땅이라 불리는 그 황무지를 떠났습니다. 그는 켄타우로스와 엘프의 땅을 넘어 남쪽 사막 너머에 푸르고 길들여지지 않은 땅이 있다는 희망을 품고 있었습니다.\n\n우리는 여행 준비가 부족했고 족장 더스트후프는 소금 평원을 건너다 목숨을 잃었습니다. 족장의 죽음으로 남은 부족원들은 뿔뿔이 흩어졌습니다. 많은 이들이 사막의 더위와 짐승들의 먹이가 되었습니다. 이 지역을 떠도는 그들의 영혼을 보셨을지도 모르겠습니다.\n\n저는 비록 영혼의 형태로나마 부족으로서 다시 한 번 그 땅을 걷기 위해 이 여행을 계속할 수 있다고 믿습니다. 하지만 $c, 당신의 도움이 필요합니다.\n\n당신은 산 자들의 세계로 돌아가 잊혀진 땅으로 가야 합니다. 해안을 따라 위브리프를 수집하십시오. 충분히 모았다면, 이곳으로 돌아와 이 토템에 불을 붙이는 데 사용하십시오. 과거에 우리는 의식 모임에서 위브리프를 향으로 사용했습니다. 더스트후프와 우리 형제들의 영혼이 그 향기를 알아볼 것입니다.\n\n대지모신께서 당신의 길을 인도하시기를, 친구여.",
    },
    [27488] = {
        ["T"] = "나쁜 소식에는 뿔이 있다",
        ["O"] = "먹구름 봉우리에서 세 개의 비밀 쪽지를 찾아 회수하십시오.",
        ["D"] =
        "켄타우로스, 타우렌, 그리고 가끔 지나가는 고블린 대상단을 제외하면, 버섯구름 봉우리에서 여행자를 보는 일은 드뭅니다. 특히 제 걱정을 자아내는 무리가 하나 있습니다.\n\n그림토템 부족과 접촉하는 수상한 자들이 목격되었습니다. 그들은 두건을 쓰고 있어서 정체를 파악할 수 없었지만, 그들이 호드의 일원인지 의심스럽습니다.\n\n그림토템이 무슨 계획을 꾸미고 있는지 모르겠지만, 결코 좋은 일일 리가 없습니다. 엄청난 위험이 따른다는 건 알지만, 먹구름 봉우리에 있는 그 부족의 마을로 잠입해 주셔야겠습니다. 그 요원들과 그림토템 사이의 협력을 설명해 줄 수 있는 문서나 메시지 등 뭐라도 찾을 수 있는지 확인해 주십시오.",
    },
    [27489] = {
        ["T"] = "협곡 순찰",
        ["O"] = "모테가 파이어메인은 당신이 버섯구름 봉우리에서 뾰루지가죽 하이에나 8마리를 처치하기를 원합니다.",
        ["D"] =
        "사악한 청소부라는 악명에도 불구하고, 이 땅의 하이에나들은 유능한 사냥꾼들입니다. 그들은 불모의 땅의 사자나 멀고어의 거대한 코도 야수 못지않게 대지모신의 생명 순환의 일부로서 중요합니다.\n\n안타깝게도 이 때문에 버섯구름 봉우리를 지나는 여행자들에게 위협이 되기도 합니다. 부탁 하나 해도 되겠습니까? 그들의 수를 좀 줄여 주십시오.",
    },
    [27490] = {
        ["T"] = "바윗골 추적",
        ["O"] = "모테가 파이어메인은 당신이 버섯구름 봉우리에서 바위 추적자 6마리를 처치하기를 원합니다.",
        ["D"] =
        "버섯구름 봉우리에 도사리고 있는 위험은 하이에나뿐만이 아닙니다, $n. 눈에 보이는 위협과 보이지 않는 위협 모두에 대처할 준비가 항상 되어 있어야 합니다.\n\n바위 추적자들은 위장의 달인이라 일반 퓨마보다 훨씬 더 위협적입니다. 표시된 길을 벗어나는 어리석은 자들은 곧 그 사실을 몸소 깨닫게 되죠.\n\n당신은 어리석은 자가 아닌 것 같으니, 그들을 상대하려면 협곡 더 깊은 곳으로 들어가야 할 겁니다. 정신 바짝 차리십시오, $c. 당신만 믿겠습니다.",
    },
    [27491] = {
        ["T"] = "운전 면허 승인",
        ["O"] = "경주로관리인 제린, 경주진행자 크론크라이더, 래저릭, 위즐 브라스볼츠에게 간청하고 매달려 신기루 경주장 면허를 받으십시오.",
        ["D"] =
        "신기루 경주장에 참가하려면 이 지역 주요 인물들의 공식적인 승인이 필요합니다. 경주진행자 크론크라이더가 최고 책임자이긴 하지만 그 사람 혼자 승인할 순 없습니다. 각 팀의 책임자들의 승인이 필요하죠. 노움 팀의 위즐 브라스볼츠와 고블린 팀의 래저릭 말입니다. 마지막으로 경주로관리인 제린이 큰 영향력을 쥐고 있습니다.\n\n이곳 레이서들의 자존심만큼 큰 건 없으니, 그들에게 가서 간청하고 매달리면 공식 청원서가 나올 테고 그럼 트랙에 나설 수 있을 겁니다.",
    },
    [27492] = {
        ["T"] = "신선한 물 배달",
        ["O"] = "신기루 경주장 주변 경비탑에 있는 경주 감독관들에게 시원하고 톡 쏘는 신선한 물 10개를 배달하십시오.",
        ["D"] =
        "경주장 주변에는 감독관이라고 불리는 경주 심판들이 있는 네 개의 탑이 있습니다. 감독관들은 뜨거운 태양 아래 그곳에 앉아 부정행위와 외부 개입이 적정 수준을 유지하도록 경주를 감시합니다. 경주를 중단시킬 만한 충돌이 발생하면 이곳으로 알려주죠.\n\n그들에게 시원하고 톡 쏘는 신선한 물을 좀 제공해 주면 뭔가 잘못되었을 때 조금 더... 상냥하게 대해줄지도 모릅니다. 어때요?",
    },
    [27493] = {
        ["T"] = "시상대 마무리",
        ["O"] = "신기루 경주장 이벤트에서 1, 2, 3위 안에 드십시오.",
        ["D"] =
        "경주에 나가면 당신은 우리 고블린 경주 팀을 대표하게 됩니다. 당신에게 최고를 기대하고 있으니 이렇게 하죠. 경주가 끝날 때 3위 시상대 안에 들면, 아주 특별한 선물을 드리겠습니다. 어때요? 자, 나가서 타이어를 좀 태워보시죠!",
    },
    [27494] = {
        ["T"] = "시상대 마무리",
        ["O"] = "신기루 경주장 이벤트에서 1, 2, 3위 안에 드십시오.",
        ["D"] =
        "경주에 나가면 당신은 우리 노움 경주 팀을 대표하게 됩니다. 당신에게 최고를 기대하고 있으니 이렇게 하죠. 경주가 끝날 때 3위 시상대 안에 들면, 아주 특별한 선물을 드리겠습니다. 어때요? 자, 나가서 타이어를 좀 태워보시죠!",
    },
    [27495] = {
        ["T"] = "비룡의 이빨",
        ["O"] = "모테가 파이어메인에게 맹독 샘 10개를 가져가십시오.",
        ["D"] =
        "버섯구름 봉우리에는 위험이 넘쳐납니다, 친구. 켄타우로스뿐만 아니라 토착 야생동물들 때문에도요. 제 경고를 무시한 여행자들이 다쳐서 치료해 준 적이 한두 번이 아닙니다.\n\n구름 뱀에게 물린 상처는 특별한 치료가 필요한데, 특히 그 맹독이 문제입니다. 뱀의 독으로 만든 해독제만이 그 효과를 완전히 중화할 수 있는데, 지금 제게 물자가 부족합니다.\n\n이 일로 당신이 목숨을 거는 건 원치 않지만, 구름 뱀의 맹독 샘을 구해다 주시면 두둑이 보상해 드리겠습니다.",
    },
    [27496] = {
        ["T"] = "재봉 물자",
        ["O"] = "버섯구름 봉우리의 탈라나르에 있는 렌도우에게 먼지 묻은 가죽 10개를 가져가십시오.",
        ["D"] =
        "실례지만 시간 좀 있으십니까? 방어구 수리 재료가 떨어져 가는데, 켄타우로스의 최근 공격 이후로는 상단이 여길 지나갈 것 같지 않군요. 버섯구름 봉우리를 배회하는 야수들의 신선한 가죽이 좀 필요합니다.\n\n어떤 동물에서 구하든 가죽의 품질이 어떻든 크게 신경 쓰지 않으니, 10장만 구해다 주시면 넉넉히 값을 쳐드리겠습니다.",
    },
    [27497] = {
        ["T"] = "갈라크를 향한 반격",
        ["O"] = "장군 블리즈를 찾아 처치하고 높새바람 봉우리의 절벽파수꾼 롱혼에게 그의 머리를 가져가십시오.",
        ["D"] =
        "그 겁쟁이 녀석...! 제 목을 그토록 원한다면... 직접 여길 찾아와야만 기회를 얻을 겁니다.\n\n장군 블리즈가 이 북쪽에 야영지를 세우고 부하들을 보내 우리 야영지와 상단을 기습하고 있습니다. 절 직접 죽이러 오지 않고 거기 숨어있는 것도 놀랍지 않군요.\n\n있잖아요, 당신이 그 녀석의 죽음을 증명해 준다면 높새바람 봉우리 사람들도 마다하지 않을 겁니다.",
    },
    [27498] = {
        ["T"] = "칸 아블린",
        ["O"] = "칸 아블린을 찾아 처치하고 높새바람 봉우리의 절벽파수꾼 롱혼에게 그의 머리를 가져가십시오.",
        ["D"] =
        "야영지 에톡의 장군은 죽었지만, 그들의 우두머리 칸 아블린이 새 장군을 임명하는 건 시간문제입니다. 지금이 바로 칠 때입니다!\n\n칸은 이 북쪽의 켄타우로스 야영지에 머물며 다음 행동을 꾸미고 있습니다. 그를 사냥하십시오, $c. 그를 베어버리고 야영지를 혼란에 빠뜨리십시오.",
    },
    [27499] = {
        ["T"] = "소금 평원의 유령",
        ["O"] = "족장 더스트후프의 영혼을 처치하십시오.",
        ["D"] =
        "이봐요, 영웅 같은 부류로 보이는데. 시간 좀 있습니까?\n\n우리 차들이 갑자기 트랙을 벗어나 오프로드로 추돌하는 일들을 겪고 있습니다. 무슨 생각 하시는지 알지만, 절 믿으세요. 이번엔 고블린 기술이 폭발한 게 아닙니다. 이 엔진을 만지작거리는 노움들 짓인 줄 알았는데, 알고 보니 걔네 레이서들도 같은 일을 겪고 있다더군요.\n\n\"이 일\"이 뭐냐고 물으시겠죠? 글쎄, 충돌 생존자 중 한 명이 트랙 동쪽을 배회하는 먼지투성이 털코트의 타우렌 족장 유령을 봤다고 보고했습니다. 노움들은 신기루라고 하지만, 난 신기루가 트랙을 배회하며 사람을 너무 겁줘서 차량 통제력을 잃게 만들진 않는다고 생각합니다!\n\n저 대신 이 일을 좀 알아봐 주셨으면 합니다. 필요하면 친구들을 데려와도 좋으니, 그 유령 영감을 도로에서 쫓아내 주쇼!",
    },
    [27500] = {
        ["T"] = "성스러운 불꽃",
        ["O"] = "버섯구름 봉우리의 갈래발굽 바윗골을 시작으로 켄타우로스 유물의 위치를 정찰하십시오. 유물을 찾으면 탈라나르의 팔핀델 웨이워더에게 돌아가십시오.",
        ["D"] =
        "이 지역의 켄타우로스들에 대한 소문을 들었습니다. 갈라크 부족이 켄타우로스의 탄생 시기부터 전해져 온 유물을 보호하고 있다는군요.\n\n정확히 뭔지는 모르겠지만, 켄타우로스의 기원을 밝히는 데 도움이 될 거라 믿습니다. 안타깝게도 우린 유물의 위치를 전혀 모르고, 갈라크가 그 위치를 그리 쉽게 발설할 것 같지도 않군요.\n\n협곡 더 아래쪽에 가장 큰 갈라크 정착지인 갈래발굽 바윗골이 있습니다. 거기서 단서를 찾아보시길 권하지만, 켄타우로스라도 그렇게 귀중한 걸 탁 트인 곳에 두진 않았을 겁니다.",
    },
    [27501] = {
        ["T"] = "성스러운 불꽃",
        ["O"] = "팔핀델 웨이워더를 위해 갈래 발굽을 회수하십시오.",
        ["D"] =
        "이 유리병을 가져가서 여기 달샘에서 채우십시오. 제 추측이 맞다면, 달샘의 물을 이용해 불을 끄고 발굽을 회수할 수 있을 겁니다. 불이 영원히 꺼지는 건 아니니 서두르셔야 할 겁니다.\n\n갈래발굽 소굴로 돌아가서 제게 갈래 발굽을 회수해 주십시오. 켄타우로스와 드리아드는 비슷한 혈통을 공유하는 것 같고, 전 이 발굽이 그것과 연관되어 있다고 확신합니다.",
    },
    [27502] = {
        ["T"] = "타혼다 야영지의 비극",
        ["O"] = "풍화된 토템을 높새바람 봉우리의 누군가에게 가져가십시오. 폐허가 된 야영지에 대해 더 알고 있을지도 모릅니다.",
        ["D"] =
        "당신 손에 있는 타우렌이 만든 토템은 마모된 흔적이 역력합니다. 바실리스크 이빨 자국이 토템을 덮고 있고, 벗겨지지 않은 페인트도 심하게 바랬습니다. 이 모든 것에도 불구하고, 이것은 폐허가 된 야영지에 남은 몇 안 되는 물건 중 하나이며, 타우렌에게 가치 있는 것일지도 모릅니다.\n\n높새바람 봉우리에 타혼다 폐허와 그 운명에 대해 더 잘 아는 사람이 있을지도 모릅니다. 어쩌면 토템을 팔아 금화를 좀 챙길 수 있을지도 모르죠.",
    },
    [27503] = {
        ["T"] = "아아 와이번",
        ["O"] = "버섯구름 봉우리의 마루둥지에서 크리스티의 고양이 코디를 구출하십시오.",
        ["D"] =
        "$C, 절 좀 도와주세요!\n\n코디, 내 사랑스러운 말썽꾸러기 고양이... 누가 납치해 갔어요! 내가 잠시 이동장 문을 열어둔 사이에 사막으로 뛰쳐나가 버렸죠! 내가 잡기도 전에 와이번 중 한 마리가 휙 날아와서 내 소중한 코디를 낚아채 갔어요! 분명 자기 새끼 중 하나로 착각했을 거예요!\n\n코디의 이동장을 가지고 마루둥지에 있는 와이번 둥지로 올라가 주세요. 하지만 부디 조심하세요! 거기 와이번들은 사납기로 소문났고, 내 작은 아기가 다치는 건 원치 않아요!\n\n제발 $c, 서둘러 주세요!",
    },
    [27504] = {
        ["T"] = "크리스티의 배달 서비스",
        ["O"] = "코디를 잊혀진 땅의 스퀴글코드 전초기지에 있는 넬라에 스카이문에게 데려가십시오.",
        ["D"] =
        "음, 코디는 짧은 모험을 마친 후에도 괜찮은 것 같네요. 조금 놀라긴 했지만 다른 곳은 다치지 않았어요. 코디가 계속 말썽을 피우고 있어서 탈라나르 주변에 이 녀석을 더 이상 둘 수 있을지 모르겠어요.\n\n괜찮으시다면, 코디를 조금 더 지켜봐 주시고 제 친구에게 데려다주실 수 있나요? 넬라에 스카이문은 잊혀진 땅의 스퀴글코드 전초기지에 살고 있어요. 모든 고양이에게 정말 다정다감한 분이라, 내 작은 코디를 기꺼이 돌봐주실 거라고 확신해요.\n\n잊혀진 땅은 여기서 조금 걸어가야 하지만, 당신이 겪은 일에 비하면 문제도 아닐 거예요!",
    },
    [27505] = {
        ["T"] = "고단백 식단",
        ["O"] = "서부 역병지대의 청소부 독수리 둥지에서 썩은 계란 12개를 모아 운고로 분화구의 늪지대에 있는 모르베크에게 가져가십시오.",
        ["D"] =
        "보통 새끼 라바사우루스는 부모가 둥지로 가져온 시체에서 먹이를 찾아 먹으며 스스로 사냥하는 법을 빨리 배우거나--아니면 굶어 죽습니다. 이 공룡들을 탈것으로 훈련시키고 있기 때문에, 녀석들에겐 더 균형 잡힌 아침 식사를 제공하고 있죠.\n\n알은 훌륭한 단백질 공급원이지만, 현지에서 조달한 먹이를 주고 싶진 않습니다. 운고로의 공룡 개체 수는 추가로 알을 채집하기엔 너무 취약하거든요. 스컬지가 휩쓸고 간 이후 서부 역병지대의 독수리 개체 수가 걷잡을 수 없이 급증했다는 소식을 들었습니다. 그 알은 크다고 소문나서--게걸스러운 식욕에 완벽하죠.\n\n서부 역병지대로 가서 알 한 다스만 모아다 주시겠습니까? 청소부 독수리가 배회하는 곳 근처에서 찾을 수 있을 겁니다.",
    },
    [27506] = {
        ["T"] = "배고픈 새끼들",
        ["O"] = "운고로 분화구의 공포의 터 근처에서 발견되는 스테고돈에게서 신선한 공룡 고기 10개를 모으십시오.",
        ["D"] =
        "제가 돌보는 새끼 맹독가죽 라바사우루스들에게 균형 잡힌 식단을 제공하고 있긴 하지만, 녀석들을 튼튼하게 유지하는 데 신선한 고기만 한 게 없죠.\n\n분화구 남서쪽 구석에서 스테고돈이라는 강력한 공룡들을 찾을 수 있을 겁니다. 녀석들의 고기는 특히 두껍고 즙이 많아 어린 라바사우루스의 식욕을 채우는 데 안성맞춤입니다!\n\n저를 위해 녀석들에게서 고기 10덩이만 구해다 주시겠습니까?",
    },
    [27507] = {
        ["T"] = "힘을 위한 힘",
        ["O"] =
        "빨간색 파워 수정 5개, 노란색 파워 수정 5개, 파란색 파워 수정 5개, 녹색 파워 수정 5개를 아즈샤라 북부의 검은아귀 마을에 있는 상인 말루에게 검은아귀 의식 토템과 교환하십시오. 운고로 분화구의 모르베크에게 토템을 가져가십시오.",
        ["D"] =
        "토르와 패스파인더에게 들은 새로운 훈련 기술을 시도해 보고 싶군요. 그가 아즈샤라 북부에 있는 검은아귀 펄볼그라는 부족에 대해 말해줬습니다. 그들은 야수가 조련사를 신뢰하도록 돕는 진정 토템을 만든다더군요. 당신이 제게 그걸 하나 가져다주셨으면 합니다.\n\n토르와의 말에 따르면, 단순한 동전만으로는 그런 물건을 얻을 수 없습니다. 거래가 필요하죠. 토템은 힘을 상징하니, 동등한 힘의 교환이 효과가 있지 않을까요?\n\n운고로 전역에 돋아나는 파워 수정을 색깔별로 다섯 개씩 모아 아즈샤라 북부의 마을로 가져가서 거래에 응하는지 확인해 보십시오.",
    },
    [27508] = {
        ["T"] = "연구 구원",
        ["O"] = "아무 랩터에게서나 연구 일지 10장을 모아 운고로 분화구의 마샬의 야영지에 있는 윌리덴 마샬에게 가져가십시오.",
        ["D"] =
        "오 안돼, $N! 장비와 함께 있던 우리 연구 일지가 모두 사라졌어요.\n\n보관함이 입은 손상을 보아하니, 당신이 오기 전에 운고로의 랩터들이 손을 댄 것 같군요. 그 일지들은 이제 어디에나 있을 수 있어요.\n\n랩터 근처 분화구를 탐험하다 우연히 우리 일지를 발견한다면, 친절하게 돌려주시겠어요? 모르겠네요--일지를 가지고 있는지 확인하려면 몇 마리 죽여야 할지도 몰라요.",
    },
    [27509] = {
        ["T"] = "운고로 사냥",
        ["O"] = "스파인스케일을 처치하고 그의 머리를 운고로 분화구의 마샬의 야영지에 있는 S.J. 얼가딘 주니어에게 가져가십시오.",
        ["D"] =
        "마샬 원정대를 얻어 타고 운고로 분화구에 왔지만, 아무래도 내가 감당할 수 없는 일인 것 같아. 날 좀 도와줄래?\n\n우리 부모님은 대단한 사냥꾼이셔. 그래서 운고로에 와서 나도 사냥할 준비가 되었다는 걸 보여주기로 결심했지.\n\n솔직히, 여긴 너무 무서워서 집에 가고 싶어. 하지만 빈손으로 떠나면 평생 잔소리를 들어야 할 거야. 내가 전설로 남을 수 있도록 트로피가 될 만한 야수를 사냥해 줄 수 있어?\n\n분화구 북쪽 가장자리의 거대한 바위 근처에 스파인스케일이라는 거대한 디메트로돈이 산다고 들었어. 트로피로 쓸 수 있게 녀석의 머리를 가져다줘. 돈은 지불할게!",
    },
    [27510] = {
        ["T"] = "운고로 사냥",
        ["O"] = "그늘날개를 처치하고 그의 머리를 운고로 분화구의 마샬의 야영지에 있는 S.J. 얼가딘 주니어에게 가져가십시오.",
        ["D"] =
        "마샬 원정대가 처음 분화구에 들어왔을 때, 우리는 홀아니가 강철바위 고원이라고 부르는 지역을 지나갔어. 그곳에는 수많은 비행 야수들이 있었고 그중 한 마리는 다른 녀석들보다 더 크고 사나워 보였지. 우린 녀석을 그늘날개라고 불렀어.\n\n그늘날개를 찾아서 내게 머리를 가져다줄 수 있어? 내 생각엔 이게 저것보다 더 인상적인 트로피가 될 것 같아.",
    },
    [27511] = {
        ["T"] = "운고로 사냥",
        ["O"] = "스테고돈을 처치하고 그의 머리를 운고로 분화구의 마샬의 야영지에 있는 S.J. 얼가딘 주니어에게 가져가십시오.",
        ["D"] =
        "페트라 그로센이 전에 운고로를 여행한 적이 있는데, 분화구 남서쪽 어딘가에 등에 거대한 융기된 판을 가진 거대한 야수들이 있다고 말해줬어. 무척 위험하다고 들었는데, 그 녀석들 중 하나를 죽일 수 있다면 훨씬 더 인상적일 거야.\n\n바로 이거야 $N! 이 \"스테고돈\"의 머리를 가져오면 보수를 두 배로 줄게.",
    },
    [27512] = {
        ["T"] = "운고로 사냥",
        ["O"] = "데빌사우루스를 처치하고 그의 머리를 운고로 분화구의 마샬의 야영지에 있는 S.J. 얼가딘 주니어에게 가져가십시오.",
        ["D"] =
        "이 근처 능선 위로 올라갔는데, 정상에 도착했을 때 땅이 흔들리는 걸 느꼈어. 거대한 괴물이 걸어 지나갔지--마치 랩터 같았는데 10배는 더 컸어! 페트라가 걔네들은 데빌사우루스라고 불리며 여기 운고로 분화구에서만 볼 수 있다고 했지.\n\n내 컬렉션을 위해 녀석들 중 하나의 머리를 꼭 가져야겠어. 부모님이 가져오셨던 그 어떤 것보다 훌륭해. 제발, $N, 날 위해 데빌사우루스를 죽이고 녀석의 머리를 가져다줘!",
