    [27513] = {
        ["T"] = "쉬즐의 비행기 업그레이드",
        ["O"] = "운고로 분화구의 마샬의 야영지에 있는 쉬즐을 위해 스테고돈 판 3개를 수집하십시오.",
        ["D"] =
        "얼가딘 꼬맹이와 당신이 나누는 얘기를 안 들을 수가 없더군요. 계속 생각해 봤는데, 이 비행선에 약간의 매력을 더해 줄 게 딱 하나 있습니다--바로 비행선 중앙에 쓸 튼튼한 판이죠. 당신이 독한 럼주를 쏟았을 때 훌륭한 받침대 역할을 해줄 겁니다.\n\n스테고돈을 잡으러 나가는 김에 제가 실험할 수 있게 몇 개 가져다주시겠습니까? 세 개면 충분합니다!",
