    [27514] = {
        ["T"] = "쉬즐의 딜럭스 비행선",
        ["O"] = "운고로 분화구의 마샬의 야영지에 있는 쉬즐을 위해 데빌사우루스 가죽 1개를 수집하십시오.",
        ["D"] =
        "그래서 꼬맹이가 데빌사우루스를 잡아달라고 하던가요? 글쎄, 녀석들 중 하나를 잡으러 간다면, 제 비행선의 멋진 가죽 인테리어로 쓸 수 있겠군요. 고품질의 통가죽을 얻으려면 진짜 가죽세공인이 필요하겠지만, 아무 모험가나 저를 위해 겉가죽을 벗겨다 줄 순 있잖아요.\n\n오, 생각해 보세요. 내후성도 뛰어나고 스타일리시하죠!\n\n어떻습니까?",
    },
    [27515] = {
        ["T"] = "실리더스 간식",
        ["O"] = "실리더스의 미늘벌레에게서 미늘벌레 고기 5개를 운고로 분화구의 늪지대에 있는 모르베크에게 가져가십시오.",
        ["D"] =
        "제가 훈련시키는 라바사우루스들은 결국 주인을 따라 전 세계를 여행하게 될 겁니다. 적응을 돕기 위해, 저는 녀석들에게 다양한 종류의 고기를 노출시킵니다.\n\n서쪽에는 실리더스라고 알려진 위험한 땅이 있습니다. 이 불모의 황무지에 서식하는 거대한 모래벌레들은 맹독가죽 라바사우루스 새끼들이 먹던 것과는 꽤 다른 맵고 건조한 종류의 살점을 가지고 있죠. 녀석들이 자라는 동안 식단에 이것을 좀 포함시키고 싶군요.\n\n이 모래벌레들에게서 고기 다섯 덩이를 모아주세요. 하지만 조심하세요. 녀석들은 강력한 적이라 쓰러뜨리려면 파티가 필요할 수도 있습니다.",
    },
    [27516] = {
        ["T"] = "뽀드득 깨끗하게",
        ["O"] = "모르베크의 청소 양동이를 이용해 골락카 간헐천에서 물을 모은 다음, 물이 식기 전에 근처에 있는 새끼 맹독가죽 라바사우루스를 닦아 주십시오.",
        ["D"] =
        "제 곁에 있는 어린 맹독가죽 라바사우루스가 보이십니까?\n\n이 녀석은 운고로의 진흙투성이 강을 쿵쾅거리며 걷는 걸 아주 좋아하는데, 사냥 후 발톱에서 피를 씻어내는 법은 아직 배우지 못했죠. 이제 이 꼬마 아가씨를 목욕시켜야 할 때입니다!\n\n이 양동이를 분화구 반대편에 있는 골락카 간헐천으로 가져가 뜨거운 물을 채우십시오. 물이 식기 전에 여기로 돌아와 녀석을 박박 문질러 씻겨 주십시오.",
    },
    [27517] = {
        ["T"] = "폭풍, 대지, 바람, 그리고 불",
        ["O"] = "타르 정령 여섯 마리를 약화시킨 다음 대지의 힘을 얄루니 플레임워처의 토템에 흡수시키십시오.",
        ["D"] =
        "대지 고리회를 대표하여 인사드립니다, $R. 저는 원시 정령을 연구하고 있는데 혹시 절 도와주실 수 있나 해서요.\n\n운고로 원소의 각 힘의 정수를 이 토템에 담고 싶었지만, 악령숲에서 수년을 보낸 후 남은 지옥 마력으로 정수를 오염시킬까 두렵습니다. 저를 위해 정수를 모아줄 사람이 필요합니다. 그저 정령들을 약화시킨 다음, 토템을 이용해 원시 정수를 포획하면 됩니다.\n\n락카리 잿구덩이 주변의 타르 정령들--대지의 원시적인 힘부터 시작할 수 있습니다.",
    },
    [27518] = {
        ["T"] = "폭풍, 대지, 바람, 그리고 불",
        ["O"] = "바람 정령 여섯 마리를 약화시켜 바람의 힘을 얄루니 플레임워처의 토템에 흡수시키십시오.",
        ["D"] =
        "대지는 무겁고 끈적끈적하고 조밀하죠. 우리는 그 반대인--바람으로 넘어갈 겁니다.\n\n바람의 정수는 운고로 주변 산맥에 숨어 있습니다. 분화구 가장자리 주변을 찾아보고 북동쪽과 남서쪽의 언덕과 골짜기로 올라가야 할 겁니다.\n\n동일한 과정을 반복하십시오: 녀석들을 약화시킨 다음 토템으로 정수를 흡수하십시오.",
    },
    [27519] = {
        ["T"] = "폭풍, 대지, 바람, 그리고 불",
        ["O"] = "불의 정령 여섯 마리를 약화시켜 불의 힘을 얄루니 플레임워처의 토템에 흡수시키십시오.",
        ["D"] =
        "바람은 산들바람처럼 가볍고 더 밝은 에너지--즉 불에 의해 쉽게 밀려납니다.\n\n불은 운고로에서 쉽게 눈에 띕니다. 분화구 중앙의 불기둥 마루에 이글거리는 정령들이 득실거리죠.\n\n탁 트인 용암 웅덩이와 그들의 우두머리, 불바람 주변에서는 주의하십시오. 그는 우리 연구 대상이 아닙니다.\n\n나머지 정령들은 약화시켜 토템에 흡수시킬 수 있습니다.",
    },
    [27520] = {
        ["T"] = "폭풍, 대지, 바람, 그리고 불",
        ["O"] = "물 정령 여섯 마리를 약화시켜 물의 힘을 얄루니 플레임워처의 토템에 흡수시키십시오.",
        ["D"] =
        "마지막으로, 당신이 서쪽으로 가주셨으면 합니다. 골락카 간헐천에는 강인하고 탄력적인 존재인 물 정령들이 살고 있죠.\n\n<얄루니 플레임워처가 당신을 위아래로 훑어봅니다.>\n\n당신이라면 녀석들을 감당할 수 있을 거라 확신합니다.\n\n과정은 동일합니다. 녀석들을 약화시킨 후 토템을 이용해 정수를 포획하십시오. 우린 거의 다 왔습니다.",
    },
    [27521] = {
        ["T"] = "폭풍, 대지, 바람, 그리고 불",
        ["O"] = "바위 수호자에게 얄루니의 정령 강화 토템을 사용한 다음, 수호자를 처치하십시오.",
        ["D"] =
        "운고로에는 타르 군주보다 더 강력한 대지의 힘이 존재하고, 그게 바로 제가 이곳에 끌린 이유입니다.\n\n거대한 바위 수호자들이 강이나 분화구 벽과 같은 외딴 경로를 배회합니다. 평소 같으면 그들은 엄청난 상대라 우리 둘이서 상대하기엔 벅찰 겁니다. 하지만 우리가 수집한 원시적인 힘을 사용하면 그 건장한 적을 쓰러뜨릴 수 있다고 믿습니다.\n\n이 토템을 받으십시오. 당신이 모은 모든 정령의 힘이 충전되어 있습니다. 토템의 힘을 바위 수호자에게 해방하고 처치하십시오.\n\n수호자들은 지금은 평화롭지만, 언젠가 악령숲의 정령들처럼 타락할 경우를 대비하여 방어 수단을 마련해야 합니다.",
    },
    [27522] = {
        ["T"] = "아루탈리스의 전설",
        ["O"] = "운고로 분화구 가장자리를 따라 아루탈리스 폐허를 수색하고 무엇이든 발견하면 자일사 스톤송에게 돌아가십시오.",
        ["D"] =
        "안녕하세요, $R. 제가 쇠약해진 상태인 걸 양해해 주세요. 저는 엘룬의 자매 자일사 스톤송입니다. 전 전설의 엘프 도시, 아루탈리스를 찾기 위해 운고로 분화구에 왔습니다.\n\n전해지는 바에 따르면 우리 조상들은 트롤 전투 부대의 광란을 피해 이 분화구에 숨었다고 합니다. 그들은 아즈샤라의 어느 곳 못지않은 도시를 세우고 아루탈리스라 불렀죠. 그러다 아제로스가 세계의 분리로 찢어지기 몇 년 전에 폐허가 되고 말았습니다.\n\n분화구는 위험한 곳이라 저는 이 지역의 생물들에게 큰 부상을 입었습니다. 저는 회복될 테지만, 계속 수색해 주시겠어요? 분화구 중심부를 지나왔지만 가장자리는 수색하지 못했어요. 제발 주변 언덕과 고원 지대에서 조상들의 흔적을 찾아봐 주세요.",
