        ["D"] =
        "아루탈리스에 무슨 일이 일어났는지 더 잘 이해해야 합니다. 여기서 본격적인 고고학 발굴을 진행하려면 몇 달, 아니 몇 년이 걸릴 겁니다. 하지만 표면에 유물이 있는 경우가 종종 있고, 심지어 지역 생물들이 줍기도 하죠.\n\n당신이 묘사한 바람 정령들이 유물을 삼켰을지도 모르니 녀석들을 처치하면 쉽게 회수할 수 있을 겁니다. 비교를 위해 몇 개만 수집해 주시겠어요?",
