        ["D"] =
        "자일사가 전설에서 거대한 비전 폭발이 아루탈리스를 파괴했다고 말했나요? 당신이 찾은 유물들이 이 이론을 뒷받침할지도 모릅니다. 만약 사실이라면, 분화구에 오랜 시간에 걸쳐 쌓인 퇴적물 샘플에서 비전 찌꺼기 층을 발견할 수 있을 겁니다.\n\n저는 자일사를 돌봐야 하지만 도와주실 수 있다면, 이 노심 추출기를 가져가 운고로의 다양한 장소에서 퇴적물 노심을 좀 추출해 주세요. 목록을 드릴게요.",
    },
    [27525] = {
        ["T"] = "아루탈리스의 전설",
        ["O"] = "네 곳의 아루탈리스 폐허를 방문하여 서판을 찾으십시오. 발견한 서판의 탁본을 떠 운고로 분화구의 자일사 스톤송에게 가져가십시오.",
        ["D"] =
        "다시 뵙네요, $N. 가져오신 유물들을 살펴봤는데 \"쐐기돌 서판\"이라는 것을 언급하고 있더군요. 대략적인 번역이라 정확히 무슨 의미인지는 모르겠지만, 전체의 여러 부분이 아루탈리스 전역으로 흩어졌다는 걸 암시하는 것 같아요.\n\n전체가 온전하진 않겠지만 충분한 부분을 모은다면 문맥을 통해 나머지를 이해할 수 있을지도 몰라요.\n\n전에 발견하신 여러 폐허 유적지로 이동하여 글씨가 적힌 서판, 아마도 원형 글씨가 적힌 서판을 찾아주시겠어요? 이 탁본 재료를 가져가서 서판의 탁본을 떠주세요.",
    },
    [27526] = {
        ["T"] = "아루탈리스의 전설",
