        ["D"] =
        "지금으로선 당신이 할 수 있는 모든 도움을 주신 것 같네요. 제가 회복되면 스스로 이 일을 계속할 수 있을 거예요.\n\n부탁이 하나 더 있어요. 노심 샘플, 서판 탁본, 그리고 제 보고서를 다르나서스의 상급자들에게 가져다주세요. 그들은 우리가 찾은 것을 듣고 싶어 안달일 거예요.",
