    [27527] = {
        ["T"] = "아루탈리스의 전설",
        ["O"] = "아루탈리스 연구 자료 상자를 썬더 블러프 장로의 봉우리에 있는 하뮬 룬토템에게 가져가십시오.",
        ["D"] =
        "지금으로선 당신이 할 수 있는 모든 도움을 주신 것 같네요. 제가 회복되면 스스로 이 일을 계속할 수 있을 거예요.\n\n부탁이 하나 더 있어요. 노심 샘플, 서판 탁본, 그리고 제 보고서를 썬더 블러프의 하뮬 룬토템에게 가져다주세요. 그는 전설이 사실인지 확인하는 데 관심을 보였고, 호드 소속인 당신이 절 도와주셨으니 그 정도는 제가 할 수 있는 최소한의 보답이죠.",
