        ["D"] =
        "운고로 분화구의 수정탑들은 무척 오래되었다는 소문이 있지만, 어디서 왔는지 아는 사람은 아무도 없습니다. 저 수정탑은 얼마나 오랫동안 망가져 있었을까요?\n\n오래된 물건의 연대를 측정하는 데 전문가인 친구가 있습니다--리키 카트스파크라고 하죠. 그녀와 그녀의 파트너는 분화구 남서쪽 구석에 있는 공포의 터 근처에서 고고학 연구를 하고 있습니다. 그녀에게 가서 수정탑이 언제 손상되었는지 알아낼 방법이 있는지 물어봐 주시겠어요?",
    },
    [27530] = {
        ["T"] = "다른 것들과 다른 한 가지",
        ["O"] = "운고로 강둑에서 고운 강모래 4개를, 운고로 분화구의 수액괴물에게서 수액 화합물을 수집하십시오.",
        ["D"] =
        "내 파트너 자일사와 나는 여기 운고로에서 나이트 엘프의 역사를 연구하고 있습니다. 이 수정탑 중 하나를 가까이서 살펴보는 데 많은 시간을 보내진 않았지만, 나이트 엘프보다 훨씬 더 이전의 것이라고 생각합니다.\n\n수정탑이 언제 손상되었는지 확인하기 위해 의존할 수 있는 특정한 연구 원칙이 있습니다.\n\n당신이 조사에 사용할 키트를 만들 재료가 좀 필요합니다. 저는 자일사를 돌봐야 하니, 당신이 강둑에서 고운 모래를 좀 구하고 근처 수액괴물들에게서 끈적한 화합물을 구해준다면 도움이 될 겁니다.",
    },
    [27531] = {
        ["T"] = "다른 것들과 다른 한 가지",
        ["O"] = "리키의 연대 측정 화합물을 사용하여 남부 수정탑을 조사하고 결과를 관찰하십시오.",
        ["D"] =
        "좋아요, 계획은 이렇습니다. 남부 수정탑으로 돌아가서 이 화학 추출물을 발라야 합니다. 수정탑 파편이 바닥에 1년 이상 방치되었다면, 울창한 정글 환경에 쌓인 흙과 이끼가 화합물을 흡수해서 아무 일도 일어나지 않을 겁니다. 하지만 최근에 부서진 거라면 추출물을 모두 흡수할 만큼 퇴적물이 충분하지 않아 반응이 일어날 거예요.\n\n정확히 어떤 반응일지 말씀드릴 순 없지만, 절대 놓칠 리 없을 거라 확신합니다!",
    },
    [27532] = {
        ["T"] = "다른 것들과 다른 한 가지",
        ["O"] = "운고로 분화구의 마샬의 야영지에 있는 J.D. 콜리에게 남부 수정탑에 대한 정보를 가져가십시오.",
        ["D"] =
        "정말 흥미로운 전개군요! 당신이 목격한 반응은 지난 1년 내에 수정탑에 어떤 종류의 폭발물이 사용되었음을 의미합니다. 그게 무슨 뜻인지 이해하시겠어요?\n\n수정탑이 노후화나 날씨 때문에 손상되었을 가능성은 희박합니다. 누군가 고의로 파괴한 거예요. 하지만 왜죠?\n\n당신이 찾은 것이 궁금하긴 하지만, 저는 자일사와 함께 이곳에 머물러야 합니다. 하지만 J.D.는 이 사실을 알아야 해요. 그녀에게 당장 알려야 합니다.",
    },
    [27533] = {
