        ["D"] =
        "그래서 누군가 의도적으로 저 수정탑 중 하나를 파괴했다는 거군요--하지만 왜일까요? 걱정스러운 가설이 하나 있습니다. 수정탑들이 저 벌레 생물들과 그들의 둥지 확장을 막는 것과 연관되어 있을지도 모릅니다.\n\n이 가설을 확인해 볼 방법이 있습니다. 홀아니가 실리시드 둥지를 조사하는 데 관심이 있었다고 생각합니다. 아마도 그녀의 연구가 둥지가 그 자리에 얼마나 오래 있었는지 말해줄 수 있을 겁니다. 만약 불과 1년 전의 일이라면, 우리는 매우 우려해야 합니다.",
