        ["O"] = "알게 된 내용을 마샬의 야영지에 있는 J.D. 콜리에게 보고하십시오.",
        ["D"] =
        "당신이 가져온 둥지 벽 샘플을 근거로 보면, 이 터널들은 꽤 최근에 만들어진 것 같습니다. 사실, 우리가 본 모든 실리시드 둥지들은 비교적 최근에 생긴 것들입니다. 이 생물들은 매우 빠르게 성장하고 급속도로 팽창하죠.\n\n이 둥지가 여기 있은 지 1년 또는 그 이하로 추정됩니다. 도움이 되길 바랍니다!",
