        ["D"] =
        "수정탑이 실리시드의 확산을 막고 있었다는 것이 사실이라면, 애초에 왜 그것들이 만들어졌는지에 대한 다른 단서가 있을지도 모릅니다.\n\n남동쪽과 북서쪽 모두 운고로 분화구 입구에 짙은 보라색 수정탑이 있습니다. 그 수정탑들을 조사해 보고 분화구 자체의 수정탑들과 어떤 관계가 있는지 확인해 주시겠어요?\n\n이 일에 안 좋은 예감이 드네요....",
