        ["D"] =
        "마샬 원정대가 가젯잔에서 준비하는 동안, 용맹 원정대라고 불리는 무리가 실리더스로 여행을 떠났습니다. 그들과 함께 한 연구자들 중 일부는 자칭 실리시드 전문가들이죠. 검은 수정탑들이 그들에 의해 만들어졌다면, 당신이 본 조각들이 그들에게 어떤 의미가 있을지도 모릅니다.\n\n그들이 지금 어디 있는지 모르지만, 실리더스로 향하는 길을 따라가다 보면 그들의 야영지를 찾을 수 있지 않을까요?",
