        ["D"] =
        "우리 일행이 가던 길을 멈추고 운고로 입구에 있는 수정탑을 유심히 보았기 때문에 당신이 묻는 것이 무엇인지 잘 알고 있습니다. 그 수정탑은 실리시드와 사촌 격인 인간형 종족 퀴라지가 세운 것입니다. 그것은 일종의 경고문으로, 분화구는 출입 금지 구역이거나 위험하다는 뜻이지만 이는 대략적인 번역일 뿐입니다. 그들의 언어와 개념은 당신이나 내가 의사소통하는 방식과는 꽤 다릅니다.\n\n우리는 이곳의 역사에 대해 잘 알지 못하며, 단지 아주 오래전 이곳에서 큰 전쟁이 벌어졌고 실리시드와 퀴라지가 패배했다는 것만 알고 있습니다. 아직 더 많은 걸 말씀드리지 못해 죄송합니다만--나중에 다시 오시면 우리 연구를 돕는 걸 환영합니다. 어쩌면 그때 당신이 찾는 해답을 발견할 수도 있겠죠.",
