        ["D"] =
        "이런 진행 상황을 우리끼리만 알고 있을 수는 없네 $N! 딱 맞는 사람이 있지 -- 연금술사 페슬저그 [cite: 1]가 오그리마 [cite: 21]의 의원인 질지빈 드럼로어 [cite: 35]를 위해 실리시드에 대한 연구를 하고 있다고 했네. 이 보고서를 가져가서 직접 전해주게! 그가 어떻게 해야 할지 알 걸세!",
