    [27539] = {
        ["T"] = "폭풍이 모인다",
        ["O"] = "다르나서스 [cite: 7]에 있는 그라시나 스피릿마이트 [cite: 12]에게 J.D. 콜리의 보고서를 가져가야 합니다.",
        ["D"] =
        "이런 진행 상황을 우리끼리만 알고 있을 수는 없네 $N! 딱 맞는 사람이 있지 -- 연금술사 페슬저그 [cite: 1]가 다르나서스 [cite: 7]의 의원인 그라시나 스피릿마이트 [cite: 12]를 위해 실리시드에 대한 연구를 하고 있다고 했네. 이 보고서를 가져가서 직접 전해주게! 그녀가 어떻게 해야 할지 알 걸세!",
    },
    [27540] = {
        ["T"] = "도난당한 교본",
        ["O"] = "하스글렌 [cite: 14]에서 \"공룡을 훈련시키는 방법\"을 회수하여 운고로 분화구의 모르베크에게 가져가야 합니다.",
        ["D"] =
        "얼마 전에 내 라바사우루스 [cite: 22] 보급품을 뒤지는 인간을 발견했어. 겁을 줘서 쫓아내긴 했지만, 나중에 알고 보니 그 녀석이 맹독가죽 라바사우루스 [cite: 31] 훈련 팁이 적힌 내 수첩을 훔쳐 갔더라고. 좀 조사해 보니 그 도둑은 붉은십자군 [cite: 6]이라는 조직의 일원이었어.\n\n이 광신도들은 북부 역병지대 [cite: 21]의 하스글렌 [cite: 14]이라는 곳에 강력한 요새를 두고 있지. 그곳에 사는 붉은십자군 [cite: 24] 마법사들은 책을 엄청나게 탐독한다고 하더군 -- 어쩌면 내 책이 그들의 도서관 어딘가에 있지 않을까?\n\n내가 이 라바사우루스 [cite: 22] 새끼들을 계속 훈련시킬 수 있도록 그걸 좀 되찾아 줘!",
    },
    [27541] = {
        ["T"] = "독성 내성",
        ["O"] = "운고로 분화구에서 맹독가죽 라바사우루스 [cite: 31]를 공격하여 맹독가죽의 피를 20번 뒤집어써야 합니다.",
        ["D"] =
        "맹독가죽 라바사우루스 [cite: 31]를 타고 싶다고? 그럼 나쁜 소식이 하나 있어.\n\n맹독가죽 라바사우루스 [cite: 31]는 온통 독투성이야: 독 피, 독침[cite: 31], 독 피부까지. 녀석의 등에 올라타면 몇 시간 안에 죽어서 떨어지고 말걸.\n\n내가 녀석을 네게 팔기 전에 독에 대한 내성을 길러야 할 거야. 그건 아주, 아주 오랜 시간이 걸리는 일이지.... 정말 관심이 있다면, 맹독가죽 녀석들은 여기서 북서쪽으로 저습지 [cite: 34] 북부 지역을 좋아해. 그곳에서 녀석들과 싸우며 피를 여러 번 뒤집어써 봐.",
    },
    [27542] = {
        ["T"] = "아루탈리스의 장난감",
        ["O"] = "운고로 분화구의 아루탈리스 폐허에 사는 대기의 정령에게서 \"장난감\" 8개를 수집해야 합니다.",
        ["D"] =
        "맹독가죽 라바사우루스 [cite: 31]는 애완동물이 아니지만, 키우고 훈련시키는 동안 녀석들의 장난기를 자극해 주는 건 좋은 일이지.\n\n라바사우루스 [cite: 22]의 장난감으로 썼을 때 며칠씩 견뎌내는 건 많지 않은데, 돌멩이 [cite: 23]로 만든 물건이 그나마 하루 이상 버틸 가능성이 커. 분화구 주변 언덕에서 엘프 폐허를 본 적이 있어. 지금 그곳에 사는 대기의 정령들이 가끔 맹독가죽 새끼들에게 꽤 괜찮은 장난감이 될 만한 오래된 엘프 석재 유물을 삼키곤 하거든.\n\n나를 위해 몇 개만 모아다 줄 수 있겠어? 운고로의 북동쪽과 남서쪽 가장자리에서 찾을 수 있을 거야.",
    },
    [27543] = {
        ["T"] = "맹독가죽 안장",
        ["O"] =
        "무법항 [cite: 3]으로 이동하여 드리즐릭 [cite: 8]에게서 맹독가죽 안장 배송품을 받은 후, 운고로 분화구의 모르베크에게 가져가야 합니다.",
        ["D"] =
        "내가 훈련시키는 맹독가죽 라바사우루스 [cite: 31]의 안장을 드리즐릭 [cite: 8]에게 제작해 달라고 부탁해 뒀어. 다음 안장이 완성되어 가져갈 수 있을 텐데, 가서 좀 찾아다 줄 수 있겠어? 무법항 [cite: 3] 위층에서 그의 상점을 찾을 수 있을 거야.\n\n한 가지 주의할 점이 있어, $N -- 내가 안장값을 치렀는지 기억이 안 나네. 안 냈다면, 내 대신 좀 지불해 주겠어? 돌아오면 보상해 줄게.",
    },
    [27544] = {
        ["T"] = "영혼의 예언자를 위한 선물",
        ["O"] = "기이하게 깎인 수정을 켈테릴 호수 근처의 영혼의 예언자 니셸에게 가져가야 합니다.",
        ["D"] =
        "모험이 널 부르고 있어 -- 마우아리가 알지! 네게 딱 맞는 모험이 준비되어 있다네, 젊은 $C여.\n\n내 친한 친구 니셸은 특히 영혼들과 교감하는 데 능해. 이 수정 초점을 켈테릴 호수 근처의 그녀에게 가져가면 분명 흥미로운 모험이 뒤따를 거야. 하지만 조심해 -- 이 땅의 유령 [cite: 11]들은 분노하고 불안해하고 있거든. 그들을 달래지 못하면, 영원히 널 괴롭힐지도 몰라!",
    },
    [27545] = {
        ["T"] = "과거로 향하는 문",
        ["O"] =
        "눈망루 마을 [cite: 9] 북쪽의 야수들에게서 온전한 곰 대퇴골, 온전한 달빛야수 [cite: 20] 눈알, 온전한 키메라 독주머니를 구해 영혼의 예언자 니셸에게 가져가야 합니다.",
        ["D"] =
        "켈테릴 호수에 온 걸 환영해, $N. 나처럼 이곳에 이끌려 왔나? 난 이 폐허를 연구하며 깨어 있는 모든 시간을 보냈지.\n\n오래전, 세계의 분리 [cite: 6]로 대지가 쪼개지기 전 이 사원에 끔찍한 비극이 일어났어. 이 비극의 원인은 아직 수수께끼지만, 우리가 그들과 대화할 수만 있다면 영혼들이 직접 진실을 밝혀줄지도 몰라. 마우아리가 네게 준 수정은, 우리가 대화할 수 있는 영혼 [cite: 11]을 소환 [cite: 27]할 수 있게 내가 고안한 특별한 의식의 핵심 재료야.\n\n지역의 야생동물에게서 의식에 필요한 재료를 모으는 걸 도와줘. 내게 곰 대퇴골, 달빛야수 [cite: 20] 눈알, 키메라 독주머니를 가져다줘. 이 모든 생물은 눈망루 마을 [cite: 9] 북쪽에서 찾을 수 있어 -- 하지만 명심해, 의식이 성공하려면 온전한 부위가 필요해.",
    },
    [27546] = {
        ["T"] = "과거로 향하는 문",
        ["O"] =
        "켈테릴 호수 주변의 명가 영혼에게 조율되지 않은 수정을 사용하여 조율한 후, 켈테릴 호수 근처의 영혼의 예언자 니셸에게 돌아가야 합니다.",
        ["D"] =
        "의식을 시작하려면 먼저 수정을 우리가 소환 [cite: 27]하려는 영혼 에너지 유형에 조율해야 해. 켈테릴 호수의 폐허에는 이 비극을 목격한 엘프들의 고통받고 번민하는 영혼 [cite: 11]들이 살고 있어. 이 수정으로 그 영혼들에게 사용해서 내 동족이 사는 영혼의 세계에 조율해야 해. 내 말은, 그들의 동족 말이야. 용서해 줘, 이곳에서 너무 많은 시간을 보내다 보니 내가 이곳의 일부가 된 것만 같아.\n\n이 영혼들을 파괴 [cite: 7]하는 건 마음이 아프지만, 나머지 영혼들을 구하려면 희생 [cite: 24]이 따르는 법이지. 임무를 마치면 내게 돌아와 줘. 네가 없는 동안 난 네가 가져온 의식 재료들을 준비하고 있을게.",
    },
    [27547] = {
        ["T"] = "과거로 향하는 문",
        ["O"] = "영혼의 예언자 니셸이 의식을 마칠 수 있도록 도와야 합니다.",
        ["D"] =
        "내 피부에 희미한 영혼의 기운이 느껴져, $C. 거의 다 됐어! 이제 네가 가져온 재료들과 마우아리의 조율된 수정, 그리고 내가 만든 영혼 가루 [cite: 27]를 혼합할 거야. 시간이 조금 걸리겠지만, 이 작업이 끝나면 영혼이 나타날 거야.\n\n이제 돌이킬 수 없어, $N. 한 번 필멸의 차원을 넘어선 세계에 손을 뻗으면, 저 너머의 영혼들이 영원히 널 찾아낼 수 있게 되거든. 지금 당장 떠나기로 선택해도 널 탓하지는 않을게. 만약 남기로 한다면, 긴장을 늦추지 마. 이 영혼이 어떤 형태를 취할지 나도 모르니까.",
    },
    [27548] = {
        ["T"] = "과거로 향하는 문",
        ["O"] = "여명의 설원 [cite: 34] 동쪽에 있는 영혼의 대화자 움브란스를 찾아, 고대 일지를 번역해 달라고 부탁해야 합니다.",
        ["D"] =
        "아아, 이 일지의 내용은 도무지 이해할 수가 없네. 아마 장막을 통과하면서 내용이 뒤틀려버린 것 같아. 게다가 의식용 수정도 손상 [cite: 6]됐어. 정말 끔찍한 재앙이야! 하지만 우리를 도와줄 만한 사람이 근처에 있을지 몰라.\n\n영혼의 대화자 움브란스는 한때 니셸의... 그러니까... 내 스승이었어. 그는 눈망루 마을 [cite: 9] 북동쪽의 외딴 오두막에 살고 있지. 이 책 [cite: 3]과 수정을 그에게 가져가서 우리를 위해 번역해 줄 수 있는지 물어봐 줘. 내가 직접 가고 싶지만 우리는... 사이가 틀어졌거든. 너 같은 중립적인 제3자가 부탁하는 편이 나을 것 같아.",
    },
    [27549] = {
        ["T"] = "과거로 향하는 문",
        ["O"] = "수리된 수정을 사용하여 영혼의 예언자 니셸의 몸에 깃든 악의적인 영혼을 몰아내고 파괴해야 합니다.",
        ["D"] =
        "일지는 번역할 수 있지만, 우리 앞에 더 시급한 문제가 생겼군. 니셸의 연구로 인해 그녀가 악의적인 영혼에게 빙의되고 말았어. 설명해 주지.\n\n켈테릴 호수의 명가는 진말로르의 수정이라는 강력한 마법 유물을 남용했네. 이 수정은 다시 고쳐서 사용하기엔 너무 위험해. 자네도 사원 거주자들에게 닥친 재앙을 두 눈으로 직접 확인하지 않았나. 나는 니셸에게 어떤 비밀은 묻어두는 편이 낫다고 경고했었네.\n\n니셸은 영혼들이 어떻게 수정을 사용했는지 이해할 수 있다면, 자신이 그것을 통제할 수 있다고 믿었지. 그녀의 연구는 결국 호수의 영혼들에게 빙의될 틈을 열어주고 말았고, 이제 악의적인 힘이 그녀의 행동을 조종하고 있네. 자네가 시도했던 의식은 더 많은 영혼이 우리 세계로 들어올 수 있도록 문을 여는 것이 목적이었지. 다행히도 자네가 그 문을 무너뜨렸군.\n\n이 존재가 널 신뢰하고 있으니, 내가 이 수정을 고쳐서 네가 그녀의 몸에서 영혼을 몰아내고 파괴 [cite: 7]하는 데 사용할 수 있도록 해주지. 어쩌면 그제야 그녀가 제정신을 차리고 이 어리석은 임무를 포기할지도 모르지.",
    },
    [27550] = {
        ["T"] = "과거로 향하는 문",
        ["O"] = "여명의 설원 [cite: 34] 동쪽에 있는 영혼의 대화자 움브란스에게 돌아가야 합니다.",
        ["D"] =
        "움브란스의 말이 맞았어, 진말로르의 수정은 찾아내서 다시 사용하기엔 너무 위험해. 내 안에 깃든 그 영혼을 견뎌내야 했던 며칠은, 그 수정이 일으킬 수 있는 최악의 재앙에 비하면 약과였지.\n\n부탁이야, $N, 움브란스에게 돌아가서 내가 다시 나 자신으로 돌아왔다고 전해줄래? 난 이제 일지 번역엔 관심 없어. 그 책 [cite: 3]을 어쩌든 그가 알아서 하라지. 난 이 끔찍한 경험을 좀 되돌아본 뒤에 곧 마을로 돌아갈 생각이야. 영혼들의 축복이 함께하길, $C.",
    },
    [27551] = {
        ["T"] = "살점 덩어리",
        ["O"] =
        "앨런 호손이 여명의 설원 [cite: 34]의 펄볼그 [cite: 11]들에게서 주름진 펄볼그 [cite: 11] 뇌 4개, 펄볼그 [cite: 11] 고기 덩어리 20개, 큰 펄볼그 [cite: 11] 뼈 15개를 모아달라고 부탁했습니다.",
        ["D"] =
        "반갑군, $C.\n\n도살자가 한 명 필요하네... 안목이 높으면서도 도덕적 나침반은 좀 무딘 자로 말이야. 관심 있나?\n\n이곳의 펄볼그 [cite: 11]들은 아주 튼튼한 생물이지 -- 말하자면 근육의 산이랄까. 녀석들은 \'불물\'이라는 걸 마시는데, 나도 내 나름의 목적을 위해 그 힘을 이용하고 있지. 하지만 이건 내 알 바가 아니군.\n\n내게는 계획이 있다네. 위대한 예술 작품을 위한 계획이지. 나는 펄볼그 [cite: 11]의 뇌, 살점, 그리고 뼈가 필요해.",
    },
    [27552] = {
        ["T"] = "불길한 보급품",
        ["O"] =
        "눈망루 마을 [cite: 9]의 상인들에게서 납 유리병 20개, 석탄 [cite: 5] 10개, 빈 양피지 5개를 구매한 후 여명의 설원 [cite: 34]의 앨런 호손에게 돌아가야 합니다.",
        ["D"] =
        "이제 우리 앞의 피투성이 작품을 위한 도안을 그려야겠군. 시간이 좀 걸릴 거야.\n\n자네, 이 지역을 여행하고 있겠지? 악당들과 쓰레기들이 모여드는 눈망루 마을 [cite: 9]이라는 곳에 들르거든, 이 보급품들을 좀 사다 주게. 물론 보상은 두둑이 섭섭지 않게 해 주지...!",
    },
    [27553] = {
        ["T"] = "일생의 과업",
        ["O"] = "앨런 호손의 동굴에 있는 살점 덩어리에 호손의 불안정한 용액을 사용해야 합니다.",
        ["D"] =
        "내 작품을 널리 공유할 생각이네. 바로 자네부터 시작해서 말이야. 자네가 없는 동안, 나는 흉물에 관한 스승님의 가르침을 정독했지. 모든 것이 제자리에 있네 -- 직접 확인해 보게.\n\n<고기 더미는 당신이 떠났을 때와 똑같아 보입니다.>\n\n이 유리병을 들고 그 내용물을 더미 위에 부어 보게.",
    },
    [27554] = {
        ["T"] = "고통받는 자들의 고통",
        ["O"] = "켈테릴 호수의 유령 [cite: 11]들에게서 불안정한 심령체를 10개 모아 여명의 설원 [cite: 34]의 앨런 호손에게 돌아가야 합니다.",
        ["D"] =
        "아니, 그건 확실히 내가 의도한 게 아니야. 적어도 자네가... 음, 훌륭하게 처리해 줬군.\n\n흠... 불행은 동반자를 좋아하는 법이지. 괴물이 깨어났을 때 그리 기뻐할 것 같진 않지만, 동쪽 호수를 떠도는 끔찍하게 불행한 유령 [cite: 11]들을 봤네.\n\n저 유령 [cite: 11]들을 한번 찾아가 보지 않겠나, $C? 심령체가 산더미처럼 필요하거든.",
    },
    [27555] = {
        ["T"] = "끝나지 않는 임무",
        ["O"] = "앨런 호손의 동굴에 있는 살점 덩어리에 호손의 안정화된 용액을 사용해야 합니다.",
        ["D"] =
        "다시 시도해 보지, 안 그런가?\n\n자네가 떠난 사이, 내가 그 뇌들을 \'강화 [cite: 9]\'시켰네. 그리고 심령체 덕분에 이 피조물의 정신은 분노에서 훨씬 더 벗어나 집중할 수 있을 거야. 게다가 추론 능력이 뛰어날수록 통제 [cite: 6]하기도 쉬워지지.\n\n용액은 이미 정제해 뒀어. 이제 붓기만 하면 되는데, 그 일은 다시 한번 자네 몫이네.",
    },
    [27556] = {
        ["T"] = "도난당한 고서",
        ["O"] =
        "하스글렌 [cite: 14]에서 \"눈호랑이 [cite: 11] 훈련에 관한 논문\"을 되찾아 여명의 설원 [cite: 34]의 리베른 프로스트윈드 [cite: 23]에게 가져가야 합니다.",
        ["D"] =
        "얼마 전에 은빛 여명회 [cite: 2]에서 계곡 반대편에 은둔해 사는 인간, 영혼의 대화자 움브란스에게 사절을 보냈어. 그 은빛 여명회 [cite: 2] 사절은 떠나기 전에 여명의 설원 [cite: 34]을 둘러보며 호랑이 훈련 과정에 아주 깊은 관심을 보였지.\n\n너무 지나친 관심이었어.\n\n그 자는 도둑이었네. 내가 반쯤 완성한 \"눈호랑이 [cite: 11] 훈련에 관한 논문\"을 훔쳐서 사라져버렸지. 움브란스에게 물어보니, 그 역시 도둑맞은 물건이 있더군. 우리는 그 도둑이 붉은십자군 [cite: 6] 소속이며, 지금은 그들의 요새인 하스글렌 [cite: 14]에 숨어 있을 거라고 확신하네. 그곳에 사는 붉은십자군 [cite: 24] 마법사들은 지독한 독서광이라고 하니 -- 어쩌면 내 책 [cite: 3]도 그들의 도서관 어딘가에 있지 않을까?",
    },
    [27557] = {
        ["T"] = "따뜻한 목욕",
        ["O"] =
        "얼음불꽃 온천 [cite: 11]의 따뜻한 물을 리베른 프로스트윈드 [cite: 23]의 목욕통에 채운 다음, 그의 눈호랑이 [cite: 11] 동반자인 글레이시어[Glacier]를 목욕시켜야 합니다.",
        ["D"] =
        "내 동반자 글레이시어는 아주 장난꾸러기 녀석이지. 가끔 사냥하고 뛰어놀다 보면 털이 너무 더러워져서 스스로 청결을 유지하기도 힘들 정도야. 녀석을 씻기는 것 좀 도와주겠어?\n\n이 양동이를 들고 얼음불꽃 온천 [cite: 11]으로 내려가서 뜨거운 물을 채워오게. 물이 식기 전에 빨리 돌아와서 글레이시어에게 가벼운 목욕을 시켜주렴. 으르렁거리며 널 할퀼지도 모르지만, 내 장담컨대 녀석도 고마워할 거야.",
    },
    [27558] = {
        ["T"] = "비즈 위드 더 피즈",
        ["O"] = "눈망루 마을 [cite: 9]에서 이어지는 남쪽 길가에 있는 야영지의 타눔과 대화해야 합니다.",
        ["D"] =
        "이봐, 잘나가는 친구! 일자리 찾고 있어? 난 연금술 [cite: 1]계에서 최고급 맥주를 만드는 사업을 하고 있지.\n\n적어도 그럴 거라고 생각했어! 내 파트너인 타눔이 행방불명된 지 일주일이 넘어서 슬슬 걱정되기 시작하네. 내 제품이 필요한데, 칼림도어 [cite: 15]에서 그걸 만들 줄 아는 믿을 만한 연금술사는 그 녀석뿐이거든! 거액을 들여서 여기까지 데려왔는데 말이야!\n\n사업이 미쳐 돌아가고 있으니, 뭐가 문제인지 좀 확인해 줄래? 눈망루 마을 [cite: 9] 남쪽으로 가봐. 대로를 따라 조금만 내려가면 있어. 제발 내가 생각하는 그런 짓거리는 안 하고 있어야 할 텐데!",
    },
    [27559] = {
        ["T"] = "고품질 재료",
        ["O"] = "타눔의 쇠톱을 사용하여 타눔의 야영지 동쪽에 있는 얼음엉겅퀴설인 [cite: 14] 시체에서 설인 손가락 80개를 채집해야 합니다.",
        ["D"] =
        "그러니까, 그 여자가 물약을 원한다 이거지? 참을성이라곤 요만큼도 없는 작은 고블린 같으니라고! 보낸 지 하루밖에 안 지났는데...!\n\n<타눔이 물약 얼룩이 묻은 수염을 긁적거리자, 털이 한 움큼씩 빠져나옵니다.>\n\n이름이 뭐라고 했지... $N...? $N, 여기까지 온 김에 피곤한 늙은 드워프 좀 도와주지 않겠나. 이 물약을 만들려면 동쪽 언덕을 배회하는 거대한 야수들의 설인 손가락이 필요해. 그래, 손가락 -- 온전한 게 필요해, 특히 그 발톱 말이야! 저 위쪽 동굴을 돌아다니는 녀석들도 찾을 수 있을 거야.\n\n비위 약한 척하지 마! 이 쇠톱을 가져가서 아주 즐거운 시간을 보내보라고.",
    },
    [27560] = {
        ["T"] = "원령의 포효",
        ["O"] = "타눔의 야영지 동쪽에 있는 절벽 동굴에서 레이스로어[Wraithroar]를 처치해야 합니다.",
        ["D"] =
        "잘 들어, $N. 저 소리 들리나?\n\n<타눔이 잠시 말을 멈추자, 동쪽에서 희미한 포효 소리가 들려옵니다.>\n\n내가 여기 온 내내 이 소음 때문에 시달려 왔어! 그리고 누가 그런 짓을 하는지도 알고 있지... 저기 동굴 저 안쪽에 있는 뚱뚱한 털 뭉치 녀석! 지금, 내 초라한 실력으론 상대하기 벅차지만, 자네라면...?\n\n<타눔이 자네의 장비를 매의 눈으로 스캔하며 손가락을 비벼댑니다. 자네와 눈이 마주치자 그의 얼굴에 사악한 미소가 번집니다.>\n\n난 일할 조용한 환경이 필요해! 수고비를 두둑이 챙겨줄 테니 한 번 해보겠나, $C...?",
    },
    [27561] = {
        ["T"] = "그 피즈",
        ["O"] =
        "타눔은 전기 B.T.L.R. 장치에 서리바람 키메라의 번개 숨결 [cite: 17]을 8번 충전 [cite: 5]해 오기를 원합니다.",
        ["D"] =
        "좋아, $C. 손가락도 구했고, 평화와 고요도 얻었으니, 이제 피즈가 필요해... 대체 피즈가 뭐냐고 묻고 싶지?\n\n<타눔이 말을 멈추고 공허한 눈빛으로 당신을 바라봅니다.>\n\n당연히 번개 숨결 [cite: 17]이지! 저 키메라들한테서 말이야... 하지만 널 찌릿하게 해 줄 녀석들만 골라서! 자, 여기 그 일을 위한 도구가 있네.\n\n<타눔이 버튼, 스위치, 조명으로 가득 찬 위험해 보이는 장치를 건네줍니다.>\n\n조금 따끔거려도 너무 걱정하지 마... 아, 그리고 안 죽게 조심하고!",
    },
    [27562] = {
        ["T"] = "훌륭한... 제품?",
        ["O"] = "여명의 설원 [cite: 34]의 눈망루 마을 [cite: 9]에 있는 록시 피즈휘슬에게 물약 상자 [cite: 3]를 전달해야 합니다.",
        ["D"] =
        "알았네, $N... 으윽...!\n\n<타눔은 큰 소리로 한숨을 쉬며 색깔과 농도가 다른 다양한 물약에 손을 뻗은 다음 그것들을 모두 상자 [cite: 3]에 던져 넣습니다.>\n\n이걸 그 작은 폭죽 아가씨한테 가져다줘! 아으, 그 여자가 날 망치고 있어! 이런 짓거리 할 시간이 없드아구...!\n\n<타눔은 방금 끓인 연금술 작업대의 물약으로 굶주린 눈을 돌리며 혼잣말을 중얼거리고 혀가 꼬이기 시작합니다.>",
    },
    [27563] = {
        ["T"] = "만국 공통어",
        ["O"] = "타눔에게 교훈을 주고 여명의 설원 [cite: 34]의 눈망루 마을 [cite: 9]에 있는 록시 피즈휘슬에게 돌아가야 합니다.",
        ["D"] =
        "<록시가 엉망진창인 물약 상자 [cite: 3]를 살펴봅니다. 당신의 이야기를 듣고 그녀의 얼굴이 혐오감으로 일그러집니다.>\n\n안 돼, 안 돼! 안 돼!! 그 녀석이 또 내 물건을 퍼마시고 있잖아! 내게 이런 쓰레기를 보내다니... 이 병 [cite: 3] 안에 뭐가 들어있는지 알고 싶지도 않아 -- 이게 내 물건이 아니라는 건 알겠어!\n\n그 멍청이는 꽤 괜찮은 맥주를 만들 줄 안다는 걸 다행으로 여겨야 할 거야! 오... 우두머리가 이 사실을 알면 어떻게 나올까!?\n\n결정했어, $N! 그 꼬맹이한테 교훈을 좀 가르쳐 줘! 죽이지는 말고, 그냥... 좀 거칠게 다뤄 줘. \"무역회사가 안부를 전한다\"고 말해. 그럼 정신을 좀 차릴 테니까!",
    },
    [27564] = {
        ["T"] = "델레반을 돕기 위해",
        ["O"] = "눈망루 마을 [cite: 9] 북동쪽이자 숨겨진 숲 [cite: 29] 남쪽에 있는 야영지에서 델레반 프로스트게이즈와 대화해야 합니다.",
        ["D"] =
        "아주 잘했어, 꼬맹이. 그 털복숭이 수염 녀석에게 공포 [cite: 8]를 다시 심어줬구나! 다른 일 하나 더 해볼래?\n\n여명의 설원 [cite: 34]에 내 친구가 있어 -- 좋은 녀석이고, 동물들도 잘 다루고, 악령숲 [cite: 10]이나 잿빛 골짜기 [cite: 2]에서 나를 많이 도와줬지... 아무튼, 이름은 델레반이고 북쪽의 달빛야수 [cite: 20]들과 무언가를 하려고 하고 있어.\n\n<록시가 손바닥을 들어 올립니다.>\n\n그게 뭔지는 묻지 마! 그 녀석이 하는 말은 도통 알아들을 수가 없거든. 그 녀석이 너 같은 사람을 눈여겨보고 자기한테 보내 달라고 하더군. 위험하다고 언급했던 것 같은데, 너한테 딱 맞는 일 같아.",
    },
    [27565] = {
        ["T"] = "재료 막대",
        ["O"] =
        "델레반 프로스트게이즈는 당신이 숨겨진 숲 [cite: 29] 근처의 뿌리에서 얼음수액 8개, 바위에서 얼음 수정 6개, 공중의 부엉이에게서 피 깃털 5개를 모아오길 원합니다.",
        ["D"] =
        "록시가 내 목적을 설명해 줬으리라 믿네. 아니라고?\n\n무언가가 이 북쪽 부엉이 야수들의 마음을 뒤흔들고 있네. 원인을 설명하긴 어렵지만, 우리가 그들의 혼란을 덜어줄 수 있다고 믿어.\n\n첫 번째 단계는 이 지역의 재료로 막대를 처리하고 마법을 부여하여 효과를 높이는 것이지. 내가 직접 모두 모으고 싶지만... 돌아와 보면 야영지가 파괴 [cite: 7]되어 있을 테니까. 내 대신 다녀와 줄 수 있겠나?\n\n근처 뿌리에서 채취한 얼음수액은 봉인제 역할을 하여 마음을 차분하게 해줄 걸세. 바위 꼭대기의 얼음 수정은 추위 속에서 윙윙거리며 정신을 달래주지. 마지막으로, 여명의 설원 [cite: 34]을 날아다니는 늘 지혜로운 올빼미들은 결단력이 있으니, 그 피 깃털이 덩치가 더 큰 친척들에게 같은 특성을 불어넣어 줄지도 모르네. 그들에게 위엄 있는 최후를 안겨주길 바라네.\n\n이 재료들을 모아다 준다면, 네게 빚을 지는 셈이지. 여명의 설원 [cite: 34]은 혹독할 수 있으니 부디 조심하게나.",
    },
    [27566] = {
        ["T"] = "달빛 아래의 애도",
        ["O"] = "밤에 델레반 프로스트게이즈를 도와 숨겨진 숲 [cite: 29] 안의 달에 미친 부엉이 야수를 처치해야 합니다.",
        ["D"] =
        "꿈속에서, 숲을 맴돌며 증오로 들끓는 외로운 부엉이 야수를 만났어. 그 녀석은... 뚜렷한 위험이 없는데도 절박해 보였어. 이 피조물이 내 의도를 알고는 있지만, 분노 [cite: 22]에 사로잡혀 있는 것 같아.\n\n막대는 완성되었지만, 다시 한번 자네의 힘을 빌려야겠네. 밤이 되면 숲의 동식물들이 동화되지: 이것이 우리의 행동로가 될 거야. 막대는 그 동화에 접속할 것이고, 나는 그 분노 [cite: 22]와 마주할 것이네. 짐작건대, 이 외로운 부엉이 야수가 그 분노 [cite: 22]를 구현하게 되겠지.\n\n앞에 놓인 위험에 맞설 준비가 되면 내게 말하게. 자네와 함께 가겠지만, 반드시 밤에 가야만 해.",
    },
    [27567] = {
        ["T"] = "텔레스아란으로 가는 길",
        ["O"] =
        "눈망루 마을 [cite: 9] 북쪽 길을 따라가다가 별똥별 마을 [cite: 27]을 지나 나오는 갈림길에서 우회전하여 여명의 설원 [cite: 34]에 있는 트자카자의 고용주를 찾으십시오.",
        ["D"] =
        "거기 자네. 트자카자의 고용주는 강하고 용감한 전사가 필요해... 트자카자 생각엔 자네가 딱인 것 같군.\n\n눈망루 마을 [cite: 9] 북쪽 길로 나가서 별똥별 마을 [cite: 27]을 지난 갈림길에서 오른쪽으로 돌게. 그녀가 자네를 기다리고 있을 거야.",
    },
    [27568] = {
        ["T"] = "돌에 새겨진 말",
        ["O"] = "여군주 라이린은 당신이 여명의 설원 [cite: 34]의 텔레스아란을 수색하여 쿠엘도레이 서판 8개를 모아오길 원합니다.",
        ["D"] =
        "준비를 단단히 하고 왔군. 자네 주머니를 두둑하게 채워보는 건 어떤가, $C?\n\n나는 고대 쿠엘도레이 -- 칼림도어 [cite: 15]의 추방자가 아닌 명가 -- 와 관련된 모든 것을 수집하고 있으며, 북쪽의 폐허에서 무언가를 찾고 있지. 자네가 찾을 수 있는 모든 문헌이 필요하지만, 아마 서판만 찾게 될 가능성이 커.\n\n읽을 필요는 없네. 거래에 동의하나?",
    },
    [27569] = {
        ["T"] = "필경사의 일",
        ["O"] = "여명의 설원 [cite: 34]의 눈망루 마을 [cite: 9] 여관에 있는 마리우스 헤드린에게 쿠엘도레이 서판을 가져가야 합니다.",
        ["D"] =
        "내 호위병들이 눈망루 마을 [cite: 9]에서 빈둥거리고 있군. 그 두 녀석은 나와 같은 열정을 공유하지는 않지만, 뭐 그게 그들이 여기 있는 이유는 아니니까.\n\n필경사, 마리우스 헤드린을 찾게. 그에게 이 서판의 일부를 마법 주문서에 새겨달라고 부탁하게.\n\n<여군주 라이린이 손가락으로 서판의 문자 일부를 가리킵니다.>\n\n그에게 주문서가 아주 강력해야 한다고 전해 -- 그가 가진 최고의 노력만이 이 작업을 해낼 수 있을 거야.",
    },
    [27570] = {
        ["T"] = "환영의 열쇠",
        ["O"] =
        "여명의 설원 [cite: 34] 눈망루 마을 [cite: 9]의 마리우스 헤드린은 쿠엘도레이 마법 주문서를 만들기 위해 환영 가루 [cite: 14] 7개가 필요합니다. 환영 가루 [cite: 14]는 마법부여 [cite: 9] 전문 기술의 산물입니다.",
        ["D"] =
        "와, 정말 아름다운 서예군요! 읽을 수는 없지만, 여군주님께서 이것을 필사하길 원하시는 거겠죠?\n\n마법 주문서요? 음, 가장 강력한 주문서는 환영 가루 [cite: 14]로 잉크를 만들어 쓰는데... 아, 지난주에 다 떨어졌어요!\n\n어... 재료 좀 구해 주실 수 있나요? 환영 가루 [cite: 14]는 마법부여 [cite: 9]사의 영역이니, 다른 곳에서 찾을 수 없다면 눈망루 마을 [cite: 9] 천문대의 경매장에서 구할 수 있을지도 몰라요.",
    },
    [27571] = {
        ["T"] = "알 수 없는 마법",
        ["O"] = "텔레스아란 밖의 여군주 라이린에게 튼튼한 두루마리 보관함을 가지고 돌아가야 합니다.",
        ["D"] =
        "좋습니다, $C. 이 정도면 될 겁니다! 서판은 제가 보관하겠지만, 이건 가져가셔야 합니다.\n\n<마리우스가 단단히 밀봉된 튼튼한 두루마리 보관함을 건넵니다.>\n\n주문서는 안에 있습니다. 여군주 라이린께 전달해 주세요. 안전한 여행 되시고 행운을 빕니다!",
    },
    [27572] = {
        ["T"] = "아르카나움",
        ["O"] = "텔레스아란 마법 주문서를 사용하여 아르카나움 문을 열고 아르카나움 금고를 찾아야 합니다.",
        ["D"] =
        "좋아, 내 계획은 이러네...:\n\n텔레스아란은 도시 [cite: 5] 북쪽 끝에 아르카나움이라 불리는 거대한 쿠엘도레이 저장소를 보유하고 있지. 이곳은 수많은 보물을 지키기 위해 산속에 지어졌으며, 그 안의 마법은 오랜 세월이 지난 지금도 유물들을 보존할 만큼 강력해. 네가 찾은 서판에 적힌 것은 문을 여는 주문이라네. 내가 무슨 말을 하려는 건지 알겠나?\n\n유령 [cite: 11]들은 우릴 돕지 않을 테고, 살아있는 자 중엔 그 말을 발음할 수 있는 자가 없을 테니 자네가 대신 두루마리를 사용해야 하네. 내 연구에 따르면, 아르카나움의 가장 웅장한 금고는 철통같은 경비 속에 위층에 자리 잡고 있지. 그 안의 내용물을 내게 가져오게, $C.",
    },
    [27573] = {
        ["T"] = "퇴폐적인 욕망",
        ["O"] = "쿠엘도레이 유물을 가지고 텔레스아란 밖의 여군주 라이린에게 돌아가야 합니다.",
        ["D"] = "<여군주 라이린이 당신이 찾은 유물을 보고 싶어 할 것입니다.>",
    },
    [27574] = {
        ["T"] = "길 잃은 영혼",
        ["O"] = "이스미르 던폴은 여명의 설원 [cite: 34] 텔레스아란의 유령 [cite: 11] 거주민 20명의 안식을 찾아주길 원합니다.",
        ["D"] =
        "내게 말을 걸어주다니? 얼마나 오랜만인지...? 대부분의 여행자들은 나를 본 체 만 체 하거나... 그게 아니면 반대 방향으로 도망치지.\n\n<이스미르가 당신이 떠날 것을 예상한 듯 말을 멈춥니다. 꿰뚫어 보는 듯한 그의 눈빛에는 깊은 슬픔이 묻어납니다.>\n\n난 임무에 실패했네, $C... 텔레스아란은 내 아버지의 조상 대대로 물려받은 고향이었고, 고통받는 동족들을 안식에 들게 하려고 몇 년 전 이곳에 왔네. 나는 살아서 순찰자 [cite: 22]였고 내 능력을 조금도 의심치 않았어. 하지만 자네도 보다시피...!\n\n<이스미르가 자신의 가슴을 통과해 형체 없는 손을 흔들자, 그의 유령 오라가 반응하여 일그러집니다.>\n\n자네는 폐허로 향하는 것 같군. 자네에게 줄 것은 없지만, 부디 -- 이 지역의 영혼들에게 자네의 친절을 베풀어주게. 그들을 고통에서 해방시켜 줘. 비극적이게도 그들은 자신들이 어떤 상태인지조차 깨닫지 못하고 있다네.",
    },
    [27575] = {
        ["T"] = "악몽의 씨앗",
        ["O"] = "텔레스아란 내부의 사티로스 야영지에서 악몽의 씨앗 8개를 수집해야 합니다. 사티로스 야영지에서 냄새의 근원을 찾아야 합니다.",
        ["D"] =
        "<씨앗 껍질은 죽어 있고, 이전 소유자가 반쯤 먹은 상태입니다. 이전에 본 적 없는 독특한 물건입니다... 그리고 썩은내 [cite: 32]가 납니다.>\n\n<이 폐허의 무언가에서 이와 비슷한 불쾌한 냄새가 나고 있으며, 사티로스 야영지에 가까워질수록 냄새가 더 심해집니다.>",
    },
    [27576] = {
        ["T"] = "말보르의 인도",
        ["O"] = "뿌리예언자 아하루가 달숲 [cite: 20]에 있는 말보르에게 악몽의 씨앗 주머니를 전달해 달라고 부탁했습니다.",
        ["D"] =
        "이것들을 내게 가져온 건 현명한 선택이었네, $N. 이제 알겠어. 나무의 뿌리와 마법이 땅으로 휘감겨 들어가고 있으니, 나무를 벤다고 해서 퍼지는 걸 막을 순 없겠어.\n\n내 마법으로 상처 [cite: 34]를 치료하고 식물 [cite: 21]을 재배할 순 있지만... 이런 일은 내 능력만으로는 역부족이네. 하지만 비슷한 상황을 다뤄본 자를 하나 알고 있지.\n\n$N, 달숲 [cite: 20]의 학식 있는 약초학자 말보르를 찾아주게. 그는 밤의 안식처 [cite: 21] 남서쪽 구역의 비행 조련사 근처에 거주하고 있어.\n\n이 씨앗들을 전해주고 우리의 궁지를 설명하면, 그가 어찌해야 할지 알 걸세. 나는 여명의 설원 [cite: 34]에 남아 동료에게 조언을 구하겠네.",
    },
    [27577] = {
        ["T"] = "달처럼 순수한",
        ["O"] = "달숲 [cite: 20]의 말보르 집 밖에 있는 달샘 [cite: 20] 물을 수정 유리병 [cite: 6]에 채워야 합니다.",
        ["D"] =
        "정말 골치 아픈 일이군, $C. 주머니가 무사히 버텨줘서 다행이야 -- 만약 이 씨앗 중 하나라도 흙과 만났다면, 자네가 다시 회수할 수 있었을지 장담할 수 없네.\n\n씨앗은 끔찍하지만, 달빛의 축복을 받은 물은 어떤 것이든 정화 [cite: 5]할 수 있지. 내 짐작이 맞다면, 이 씨앗들이 그들의 사악한 목적을 거스르게 만들 수 있을 거야. 밖의 달샘 [cite: 20]에서 내 물약병에 물을 채워 내게로 돌아오게.",
    },
    [27578] = {
        ["T"] = "아하루에게 돌아가기",
        ["O"] = "여명의 설원 [cite: 34]의 텔레스아란 근처에 있는 뿌리예언자 아하루에게 꿈의 씨앗 물약을 전달해야 합니다.",
        ["D"] =
        "자, 보게. 씨앗들이 꿈틀거림을 멈춘 게 보이나? 머지않아 이 씨앗들은 분명 긍정적인 변화를 일으키는 매개체가 될 걸세.\n\n달의 물이 강력한 대항 마법을 부여했어. 만약 저주받은 나무 근처에 이것들을 심는다면, 그 나무의 성장과 악의를 멈출 수 있을지도 몰라.\n\n추가 연구를 위해 씨앗을 몇 개 남겨두었으니 이 상황을 세나리온 의회에 보고하겠네. 서둘러 아하루에게 가보게. 그가 자네의 수고를 보상해 줄 거야. 고맙네, $C.",
    },
    [27579] = {
        ["T"] = "꿈 심기",
        ["O"] = "여명의 설원 [cite: 34]의 텔레스아란 내부의 악몽 종양 5개 근처에 꿈의 씨앗을 심어야 합니다.",
        ["D"] =
        "말보르가 우릴 구했어! 당장 이 사악한 나무를 끝장낼 수 없는 건 아쉽지만, 그 영향을 줄일 수만 있다면 그것만으로도 승리 [cite: 32]라 할 수 있지. 내 동료 델레반은 야생 동물들이 동요하고 있다고 의심하니, 한시가 급하네!\n\n부디 효과가 있기를 바라자고. 자네에게 이 씨앗을 심는 영광을 주겠네, $N. 일을 마치면 내게 돌아오게.",
    },
    [27580] = {
        ["T"] = "사악한 뿔의 그림자",
        ["O"] = "뿌리예언자 아하루는 당신이 북쪽 텔레스아란 내부에 있는 악의 뿔 사티로스 15마리를 처치하길 원합니다.",
        ["D"] =
        "반갑네 $C. 비록 좀 더 나은 상황에서 만났다면 좋았겠지만 말이야.\n\n달숲 [cite: 20]에서조차 여명의 설원 [cite: 34]에 무언가 잘못되었다는 것을 느낄 수 있었지. 나무들과 교감을 나눴더니, 끔찍한 마법에 휩쓸려 점점 더 크고 악랄하게 자라나는 대지의 오염된 상처 [cite: 34]를 내게 보여주더군.\n\n<뿌리예언자 아하루가 낙담한 듯 고개를 가로젓습니다.>\n\n공기 중의 불쾌한 냄새가 느껴지나? 여기까지 바람을 타고 불어오는 유황 냄새는 단 한 가지를 의미하지: 바로 사티로스일세. 그 냄새를 따라 북쪽으로 가서 녀석들을 처치하게 -- 그들의 사악한 소행에 종지부를 찍어 주게!",
    },
    [27581] = {
        ["T"] = "눈버찌 간식",
        ["O"] = "여명의 설원 [cite: 34]에 있는 리베른 프로스트윈드 [cite: 23]를 위해 눈버찌 12개를 모아야 합니다.",
        ["D"] =
        "눈호랑이 [cite: 11]를 훈련시키는 건 시간이 아주 많이 드는 일이야, $N. 내가 가장 좋아하는 간식이 주변에 지천으로 널려 있는데도 밥 챙겨 먹는 걸 깜빡할 정도라니까.\n\n부탁 하나만 들어줄래? 눈버찌는 여명의 설원 [cite: 34] 전역에서 자라는데, 이 지역 곳곳에 있는 큰 나무나 바위 [cite: 23] 그늘에서 흔히 볼 수 있지. 내가 훈련을 계속하는 동안 몇 움큼만 모아다 주면 정말 고맙겠어.",
    },
    [27582] = {
        ["T"] = "부드러운 박쥐 가죽",
        ["O"] =
        "여명의 설원 [cite: 34]에 있는 리베른 프로스트윈드 [cite: 23]를 위해 동부 역병지대 [cite: 8]의 역병박쥐에게서 부드러운 박쥐 [cite: 2] 가죽 10개를 모아야 합니다.",
        ["D"] =
        "눈호랑이 [cite: 11]를 탈 때 꼭 필요한 게 적절한 안장이야. 여명의 설원 [cite: 34]에 가죽 [cite: 16]이 부족한 건 아니지만, 이런 장치를 만들 때 가장 좋은 가죽 [cite: 16]은 좀 더 이국적인 곳에서 구할 수 있다는 걸 알게 됐지.\n\n바다 [cite: 25] 건너 동부 역병지대 [cite: 8]로 여행을 떠나 그곳을 배회하는 역병박쥐들을 사냥해 줘. 질기면서도 부드러운 박쥐 [cite: 2] 가죽 [cite: 16]은 다른 가죽 [cite: 16]들처럼 살을 쓸리게 하지 않거든. 안장 제작에 쓸 부드러운 가죽 [cite: 16] 10개를 모아서 여기 여명의 설원 [cite: 34]에 있는 내게 가져와 줘.",
    },
    [27583] = {
        ["T"] = "마즈소릴의 새끼용",
        ["O"] = "여명의 설원 [cite: 34] 마즈소릴 [cite: 19]로 여행을 떠나 푸른 새끼용 12마리를 처치해야 합니다.",
        ["D"] =
        "눈호랑이는 아주 위험한 포식자지만 아주 특정한 강력한 생물 -- 마즈소릴 [cite: 19]에 서식하는 푸른용들의 먹잇감이기도 하지.\n\n다 자란 눈호랑이는 약한 용혈족과의 싸움에서 버틸 수 있지만, 이 사악한 생물들은 가끔 눈호랑이 새끼를 포획해서 자기 새끼용들에게 먹이로 주기도 해. 그것이 생명의 순환이지. 하지만 최근 이 지역의 새끼용 수가 급격히 늘어난 것을 발견했어. 녀석들이 너무 많아지면 눈호랑이 개체 수에 어떤 악영향을 미칠지 걱정돼. 조치를 취해야 해!\n\n마즈소릴 [cite: 19]에 들끓는 푸른 새끼용들을 좀 처리해 줬으면 해. 녀석들 개개인은 약하지만 다 자란 수호자들이 지키고 있을 수도 있어. 자네의 안전을 위해 파티를 꾸려가는 것을 추천하네.",
    },
    [27584] = {
        ["T"] = "에코 교환",
        ["O"] =
        "아즈샤라 [cite: 2] 검은아귀 [cite: 3] 마을의 상인 말루에게 달빛야수 [cite: 20] 에코 5개와 얼음엉겅퀴설인 에코 5개를 주고 검은아귀 [cite: 3] 의식 토템 [cite: 30]으로 교환하세요. 여명의 설원 [cite: 34]에 있는 리베른 프로스트윈드 [cite: 23]에게 토템 [cite: 30]을 가져가야 합니다.",
        ["D"] =
        "타락하기 전 눈망루 펄볼그 [cite: 11]들은 눈호랑이 [cite: 11] 훈련에 큰 도움을 주었지. 녀석들은 짐승이 나를 믿게 하는 진정 토템 [cite: 30]을 만들어 주었어. 아즈샤라 [cite: 2]의 검은아귀 [cite: 3] 펄볼그 [cite: 11] 부족이 비슷한 토템 [cite: 30]을 만든다고 들었는데, 나를 위해 하나 구해다 줄 수 있겠어?\n\n그들이 눈망루 부족과 같다면 단순한 동전만으로는 그런 물건을 얻을 수 없을 거야. 거래가 필요하지. 눈망루 마을 [cite: 9]의 의술사 마우아리가 여명의 설원 [cite: 34] 거주민들에게서 마법을 끌어내는 방법을 알아냈어. 이 \"에코\"가 검은아귀 [cite: 3] 부족의 관심을 끌 수 있지 않을까?\n\n에코를 얻는 방법을 모른다면 눈망루 마을 [cite: 9]의 의술사에게 말을 걸어봐. 아니면 펄볼그 [cite: 11]와 비슷하지만 냉기 [cite: 11]와 비전 [cite: 1]이 주입된 부엉이 야수와 설인의 정수를 시도해 보는 건 어때?",
    },
    [27585] = {
        ["T"] = "눈호랑이 안장",
        ["O"] =
        "무법항 [cite: 3]으로 이동하여 드리즐릭 [cite: 8]에게서 눈호랑이 [cite: 11] 안장 배송품을 받은 후, 여명의 설원 [cite: 34]의 리베른 프로스트윈드 [cite: 23]에게 가져가야 합니다.",
        ["D"] =
        "내가 훈련시키는 눈호랑이 [cite: 11]들을 위한 안장 제작을 피혁 세공소 [Tan-Your-Hide Leatherworks]의 드리즐릭 [cite: 8]에게 의뢰했어. 다음 안장이 준비되어 있을 테니 가지러 가주겠나? 무법항 [cite: 3] 위층에서 그의 상점을 찾을 수 있을 거야.\n\n한 가지 주의할 점이 있어, $N -- 내가 안장값을 치렀는지 기억이 안 나. 만약 내가 돈을 내지 않았다면 대신 지불해 주겠나? 돌아오면 갚아주지.",
    },
    [27586] = {
        ["T"] = "보모 달시의 의뢰",
        ["O"] =
        "연금술사 말로리 [cite: 1]는 당신이 연금술 [cite: 1] 기술을 사용하여 최하급 치유 물약 [cite: 19] 5개를 제작하고, 엘윈 숲 [cite: 9] 골드샤이어 [cite: 12]의 보모 달시에게 배달해 주길 원합니다.",
        ["D"] =
        "초보 연금술사로군! 혹시 나 좀 도와줄 수 있겠나? 지금 일손이 너무 달려서 그러는데, 골드샤이어 [cite: 12]에 있는 보모 달시가 부상당한 광부들을 위해 최하급 치유 물약 [cite: 19]을 좀 구해달라고 하더군. 난 스톰윈드 경비병 [cite: 28]들을 위한 아주 중요한 작업을 마무리해야 해서, 자네가 괜찮다면 그 물약을 5개 만들어서 보모 달시에게 좀 배달해 주게.",
    },
    [27587] = {
        ["T"] = "경비병 토마스의 의뢰",
        ["O"] =
        "연금술사 말로리 [cite: 1]는 당신이 연금술 [cite: 1] 기술을 사용하여 최하급 방어의 비약 [cite: 9] 5개를 제작하고, 엘윈 숲 [cite: 9] 동쪽계곡 벌목지 [cite: 8]의 경비병 토마스 [cite: 13]에게 배달해 주길 원합니다.",
        ["D"] =
        "내게 도와줄 의뢰가 하나 더 있네 -- 아주 간단하고 기초적인 기술만 있으면 되지.\n\n동쪽 길을 따라가다 보면 동쪽계곡 벌목지 [cite: 8] 근처에 배치된 경비병들을 볼 수 있을 거야. 그중 한 명인 경비병 토마스 [cite: 13]가 숲에서 경비병들이 자꾸 실종된다며 연금술적인 도움을 요청했어. 그들이 길을 잃는 걸 막을 순 없겠지만, 최하급 방어의 비약 [cite: 9]이라면 필요한 만큼의 이점을 줄 수 있을 거야. 이 의뢰를 맡아 주겠나?",
    },
    [27588] = {
        ["T"] = "의무병 마일리의 의뢰",
        ["O"] =
        "의무병 마일리는 당신이 연금술 [cite: 1] 기술을 사용하여 최하급 마나 물약 [cite: 19] 5개를 제작하고 던 모로 [cite: 8] 카라노스 [cite: 15]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "오 안녕! 네 갑옷에 묻은 평온초 꽃잎 [cite: 21] 얼룩만 봐도 네가 연금술사라는 걸 알 수 있어! 혹시 날 도와줄 수 있을까?\n\n난 이 노움들이 연구실에서 겪는 수많은 사고를 수습하려고 여기 있지만, 가끔 마나 [cite: 18]가 모자랄 때가 있어. 네가 최하급 마나 물약 [cite: 19]을 좀 만들어준다면 기꺼이 돈을 지불하고 거기에 보급품도 몇 개 끼워줄게!",
    },
    [27589] = {
        ["T"] = "앙구스의 의뢰",
        ["O"] =
        "의무병 마일리는 당신이 연금술 [cite: 1] 기술을 사용하여 약한 트롤의 피 비약 [cite: 33] 5개를 제작하고 던 모로 [cite: 8] 카라노스 [cite: 15] 남쪽 야영지의 앙구스 [cite: 1]에게 배달해 주길 원합니다.",
        ["D"] =
        "있잖아, 이 주변엔 연금술사가 할 일이 아주 많아. 네가 원한다면 더 할 수 있을 거야.\n\n카라노스 [cite: 15] 남쪽의 드워프 박격포 부대원들도... 자잘한 사고를 아주 많이 일으키지. 치유 물약 [cite: 13]을 쓸 정도는 아니지만, 만약 네가 의뢰를 맡을 생각이 있다면 약한 트롤의 피 비약 [cite: 33]에는 아주 관심이 많을걸.",
    },
    [27590] = {
        ["T"] = "달의여사제 아마라의 의뢰",
        ["O"] =
        "말로른 블레이드리프 [cite: 18]는 당신이 연금술 [cite: 1] 기술을 사용하여 사자의 힘 비약 [cite: 9] 5개를 제작하고 텔드랏실 [cite: 29]의 다르나서스 [cite: 7]로 향하는 서쪽 길에 있는 달의여사제 아마라 [cite: 20]에게 배달해 주길 원합니다.",
        ["D"] =
        "실례합니다만, 당신이 연금술사라는 걸 우연히 알아봤습니다. 신드라 님은 너무 많은 요청에 시달리고 계시는데 마음씨가 너무 고우셔서 누구 하나 거절하지 못하고 계십니다. 혹시 그녀의 주문을 몇 개 맡아주시지 않겠습니까?\n\n달의여사제 아마라 [cite: 20]님께서 선발대를 위해 사자의 힘 비약 [cite: 9] 5개를 요청하셨습니다. 비약을 만드신 후 다르나서스 [cite: 7]로 향하는 서쪽 길에서 그녀를 찾으실 수 있을 겁니다.",
    },
    [27591] = {
        ["T"] = "파수꾼 아리니아 클라우드브레이크의 의뢰",
        ["O"] =
        "말로른 블레이드리프 [cite: 18]는 당신이 연금술 [cite: 1] 기술을 사용하여 최하급 회복 물약 [cite: 19] 5개를 제작하고 텔드랏실 [cite: 29] 오라클 글레이드에 있는 파수꾼 아리니아 클라우드브레이크 [cite: 25]에게 배달해 주길 원합니다.",
        ["D"] =
        "신드라 님이 너무 바쁘다는 걸 누군가에게 알리고 싶지만, 도움을 청하는 모든 이를 외면하지 못하는 그녀의 마음도 이해합니다. 오라클 글레이드에 홀로 있는 클라우드브레이크 파수꾼 [cite: 25]의 시급한 요청이 있습니다. 최하급 회복 물약 [cite: 19]을 만들어 그녀에게 전달해 주신다면 신드라 님께 큰 도움이 될 것입니다.",
    },
    [27592] = {
        ["T"] = "농부 살딘의 의뢰",
        ["O"] =
        "지나 맥그리거는 당신이 연금술 [cite: 1] 기술을 사용하여 하급 치유 물약 [cite: 16] 5개를 제작하고 서부 몰락지대 [cite: 34] 살딘 농장 [cite: 24]의 농부 살딘 [cite: 10]에게 배달해 주길 원합니다.",
        ["D"] =
        "저는 그저 평범한 상인이라 비약이나 물약을 만드는 재주는 없지만 서부 몰락지대 [cite: 34]의 주민들을 돕고 싶어요. 농부 살딘 [cite: 10]이 자신의 농장 [cite: 10]에서 날뛰는 기계들을 처리하다가 가벼운 상처 [cite: 34]를 입었답니다. 하급 치유 물약 [cite: 16]을 좀 만들어서 살딘 농장 [cite: 24]에 배달해 주시면, 제가 그분을 더 많이 돕지 못한 죄책감을 덜 수 있을 것 같아요.",
    },
    [27593] = {
