        ["O"] =
        "지나 맥그리거는 당신이 연금술 [cite: 1] 기술을 사용하여 아귀 기름 [cite: 3] 5개를 제작하고 서부 몰락지대 [cite: 34] 단검 언덕의 그림부즈 썬더브루 [cite: 12]에게 배달해 주길 원합니다.",
        ["D"] =
        "도와주는 김에 말인데... 연금술사의 도움을 절실히 필요로 하는 사람이 한 명 더 있어요. 단검 언덕에 있는 야영지에서 그림부즈 썬더브루 [cite: 12]를 찾을 수 있을 텐데. 그가 아귀 기름 [cite: 3]을 여러 병 만들어 줄 사람을 찾고 있다더군요. 만약 당신이 이 의뢰에 관심이 있다면, 그가 분명 후하게 보상할 거예요.",
    },
    [27594] = {
