        ["O"] =
        "울란나 [cite: 31]는 당신이 연금술 [cite: 1] 기술을 사용하여 지혜의 비약 [cite: 9] 5개를 제작하고 어둠해안 [cite: 7] 고대정령의 숲에 있는 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "몇 달마다 오누 [cite: 21]님과 대화하기 위해 고대정령의 숲을 찾는 순례자들이 있어요. 하지만 그분의 지혜 [cite: 34]를 헤아리는 게 결코 쉽지 않죠. 그래서 순례자들이 오누 [cite: 21]님의 말씀을 조금이라도 더 잘 이해할 수 있도록 지혜의 비약 [cite: 9]을 좀 준비해 두고 싶어요. 절 위해 비약을 만들어서 배달해 주신다면, 유용한 물건으로 기꺼이 보답해 드릴게요.",
    },
    [27595] = {
        ["T"] = "고고학자 에버릿의 의뢰",
        ["O"] =
        "울란나 [cite: 31]는 당신이 연금술 [cite: 1] 기술을 사용하여 최하급 인내의 비약 [cite: 9] 5개를 제작하고 어둠해안 [cite: 7] 렘트래블의 발굴현장 [cite: 23]에 있는 고고학자 에버릿에게 배달해 주길 원합니다.",
        ["D"] =
        "최근 드워프 무리가 이곳을 지나갔어요. 렘트래블의 발굴현장 [cite: 23]이라는 곳으로 가고 있었죠. 그들이 골렘들 때문에 꽤 골머리를 앓고 있다던데 최하급 인내의 비약 [cite: 9]이 있으면 문제를 해결하는 데 도움이 되지 않을까 싶어요. 한 번 가보는 것도 괜찮지 않을까요?",
    },
    [27596] = {
        ["T"] = "워그 딥워터의 의뢰",
        ["O"] =
        "가크 힐터치 [cite: 11]는 당신이 연금술 [cite: 1] 기술을 사용하여 수중 호흡의 비약 [cite: 9] 5개를 제작하고 모단 호수 [cite: 17] 대호수 [cite: 29] 기슭의 워그 딥워터 [cite: 33]에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑네 $C... 아니 연금술사 $N이라고 불러야 하나?\n\n이곳저곳에서 들어오는 의뢰 때문에 정신이 하나도 없네. 혹시 자네가 물약 몇 개만 좀 만들어서 내 짐을 좀 덜어줄 수 있겠나?\n\n호숫가의 워그 딥워터 [cite: 33]가 수중 호흡의 비약 [cite: 9] 한 묶음을 구해 달라고 하더군. 글쎄, 호수 안에서 낚시 [cite: 10]를 하겠다지 뭔가. 정말 기가 막힐 노릇이야... 어쨌든 조금이라도 도와준다면 정말 고맙겠네.",
    },
    [27597] = {
        ["T"] = "마렉 아이언하트의 의뢰",
        ["O"] =
        "가크 힐터치 [cite: 11]는 당신이 연금술 [cite: 1] 기술을 사용하여 신속한 수영 물약 [cite: 28] 5개를 제작하고 모단 호수 [cite: 17] 원정순찰대 오두막 [cite: 10]의 마렉 아이언하트 [cite: 18]에게 배달해 주길 원합니다.",
        ["D"] =
        "원정순찰대 오두막 [cite: 10]에 있는 마렉 아이언하트 [cite: 18]가 신속한 수영 물약 [cite: 28]을 좀 구해 달라고 부탁했어. 그 친구, 자기가 대단한 악어 사냥꾼이라고 착각하는 모양인데 물속에서 짐승 녀석들을 쫓아가려면 물약이 필요할 거로 생각한 모양이야. 혹시 자네가 이 일을 좀 맡아주지 않겠나?",
    },
    [27598] = {
        ["T"] = "순찰대원 도즈의 의뢰",
        ["O"] =
        "사령관 알시아 이본로크 [cite: 5]는 당신이 연금술 [cite: 1] 기술을 사용하여 치유 물약 [cite: 13] 5개를 제작하고 그늘숲 [cite: 8] 중심부 야경대 야영지의 순찰대원 도즈 [cite: 33]에게 배달해 주길 원합니다.",
        ["D"] =
        "$C, 당신도 연금술사라는 이야기를 들었습니다. 야경대를 위해 치유 물약 [cite: 13]을 몇 개 주문하고 싶은데, 괜찮겠습니까? 그늘숲 [cite: 8] 중앙에 있는 우리 야영지의 순찰대원 도즈 [cite: 33]에게 배달해 주십시오.",
    },
    [27599] = {
        ["T"] = "제랄드 크롤리의 의뢰",
        ["O"] =
        "제랄드 크롤리 [cite: 11]는 당신이 연금술 [cite: 1] 기술을 사용하여 화염 기름 [cite: 10] 5개를 제작하고 붉은마루 산맥 [cite: 23] 레이크샤이어 [cite: 16]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "오... 연금술사로군. 독에 대한 내 관심에 흥미를 느낄 것 같은데. 결국 연금술 [cite: 1]이나 독이나 기술의 뿌리는 다르지 않으니까.\n\n사실 자네의 솜씨가 좀 필요해. 화끈한 향을 지닌 독을 하나 만들고 싶거든... 불타는 듯한 느낌을 줄 수 있는 것으로 말이야. 자네가 내게 화염 기름 [cite: 10]을 좀 만들어준다면, 나도 자네의 향후 제작에 도움이 될 만한 유용한 재료들을 제공해 주지.",
    },
    [27600] = {
        ["T"] = "파수꾼 파송의 의뢰",
        ["O"] =
        "킬란나 [cite: 16]는 당신이 연금술 [cite: 1] 기술을 사용하여 강인한 트롤의 피 비약 [cite: 28] 5개를 제작하고 잿빛 골짜기 [cite: 2] 은빛날개 숲 [cite: 26]의 파수꾼 파송 [cite: 25]에게 배달해 주길 원합니다.",
        ["D"] =
        "이곳에서 동료 연금술사를 만나다니 정말 반갑네요. 은빛날개 파수꾼들의 주문이 잔뜩 밀려 있어서, 일손이 하나라도 더 절실한 상황이거든요.\n\n강인한 트롤의 피 비약 [cite: 28] 5개를 만들어서 은빛날개 숲 [cite: 26]의 파수꾼 파송 [cite: 25]에게 전달해 주실 수 있나요? 전쟁노래 협곡 [cite: 33]의 전투를 앞두고 파수꾼들에게 보급품이 부족하지 않도록 만전을 기해야 합니다.",
    },
    [27601] = {
        ["T"] = "케이티 그라스만의 의뢰",
        ["O"] =
        "케이티 그라스만은 당신이 연금술 [cite: 1] 기술을 사용하여 하급 마나 물약 [cite: 16] 5개를 제작하고 저습지 [cite: 34] 메네실 항구 [cite: 19]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "저는 연금술사가 아니에요... 음, 진짜 연금술사는 아니죠. 하지만 뒤에 부글부글 끓고 있는 유리병들을 보시면 알겠지만, 전 물약이나 비약을 섞어보는 걸 꽤 좋아한답니다.\n\n제가 만드는 혼합물의 대부분은 하급 마나 물약 [cite: 16]을 기본 재료로 쓰는데, 지금 다 떨어져 버렸어요! 저를 위해 조금만 더 만들어 주신다면, 기꺼이 제 물건 중 일부를 나눠드릴게요.",
    },
    [27602] = {
        ["T"] = "하사관 요화의 의뢰",
        ["O"] =
        "하사관 요화 [cite: 25]는 당신이 연금술 [cite: 1] 기술을 사용하여 적중의 비약 [cite: 8] 5개를 제작하고 가시덤불 골짜기 [cite: 28] 반란군 야영지 [cite: 23]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "대령 쿠르젠 [cite: 5]이 주술사들이 만든 비약과 물약을 가지고 있는 한 우리는 계속해서 밀릴 수밖에 없어. 보급을 끊어버릴 계획도 세워뒀지만, 우리에게도 이점이 필요해.\n\n자네가 적중의 비약 [cite: 8]을 좀 만들어서 내게 배달해 줬으면 하네. 그게 있으면 우리도 쿠르젠의 정글 투사들을 상대로 우위를 점할 수 있을 테니까.",
    },
    [27603] = {
        ["T"] = "타베사의 의뢰",
        ["O"] =
        "우마 발툼 [cite: 31]은 당신이 연금술 [cite: 1] 기술을 사용하여 하급 투명 물약 [cite: 16] 5개를 제작하고 먼지진흙 습지대 [cite: 8] Tabetha's Farm [cite: 28]의 타베사 [cite: 28]에게 배달해 주길 원합니다.",
        ["D"] =
        "아 -- 훌륭한 연금술사이시군요! 당신의 도움이 필요합니다!\n\n늪지대에 타베사 [cite: 28]라는 은둔자가 한 분 살고 계시죠. 그녀가 제게 전령을 보내 하급 투명 물약 [cite: 16]이 아주 시급하다고 전해왔는데, 안타깝게도 전 지금 재고가 하나도 없고 만드는 방법조차 모른답니다! 혹시 물약을 만들어서 그녀에게 배달해 주실 수 있으신가요?",
    },
    [27604] = {
        ["T"] = "수호자 마란디스의 의뢰",
        ["O"] =
        "수호자 마란디스 [cite: 15]는 당신이 연금술 [cite: 1] 기술을 사용하여 인내의 비약 [cite: 8] 5개를 제작하고 잊혀진 땅 [cite: 7] 나이젤의 야영지 [cite: 21]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "세나리온 의회의 명을 받아 중요한 임무를 수행하러 이곳에 왔지만, 이 땅은 도무지 적응하기 힘들군요. 관절은 쑤시고, 근처 악마들의 타락한 기운 때문에 피부가 스멀거립니다.\n\n당신이 꽤 실력 있는 연금술사라는 건 잘 알고 있습니다. 제 임무를 마칠 때까지 이 땅의 끔찍한 기운을 견뎌낼 수 있도록 인내의 비약 [cite: 8]을 좀 만들어 주시겠습니까? 부탁합니다.",
    },
    [27605] = {
        ["T"] = "치안대장 레드패스의 의뢰",
        ["O"] =
        "수습생 하니웰 [cite: 1]은 당신이 연금술 [cite: 1] 기술을 사용하여 고양이눈 비약 [cite: 5] 5개를 제작하고 언덕마루 구릉지 [cite: 14] 남녘해안 [cite: 27]의 치안대장 레드패스 [cite: 19]에게 배달해 주길 원합니다.",
        ["D"] =
        "비밀결사대의 행동이 몹시 대담해졌어요, $N. 심지어 전 남녘해안 [cite: 27] 행정관을 암살하기까지 했죠!\n\n우리 경비병들이 그 은밀한 도적들을 꿰뚫어 볼 수 있도록 고양이눈 비약 [cite: 5]을 만들 수 있다면 좋을 텐데, 저에겐 아직 그런 기술이 부족하네요.\n\n하지만 당신이라면 가능할 것 같은데요! 이 마을의 치안대장 레드패스 [cite: 19]에게 고양이눈 비약 [cite: 5]을 배달하는 이 좋은 일에 기꺼이 동참해 주시겠어요?",
    },
    [27606] = {
        ["T"] = "키넬로리의 의뢰",
        ["O"] =
        "드로브나르 스트롱브루 [cite: 8]는 당신이 연금술 [cite: 1] 기술을 사용하여 상급 치유 물약 [cite: 12] 5개를 제작하고 아라시 고원 [cite: 1] 고셰크 농장 [cite: 11]의 키넬로리 [cite: 16]에게 배달해 주길 원합니다.",
        ["D"] =
        "얼마 전, 두 명의 얼라이언스 정찰병이 고셰크 농장 [cite: 11]에 호드의 동태를 살피러 나갔었소. 아직까지 돌아오지 않아서 무슨 변이라도 당한 건 아닌지 걱정이 되는군.\n\n지금 내게 여분의 상급 치유 물약 [cite: 12]이 없지만 자네라면 연금술 [cite: 1] 실험실을 잘 다룰 것 같군. 상급 치유 물약 [cite: 12]을 좀 만들어서 키넬로리 [cite: 16]에게 배달해 준다면 내 마음이 훨씬 가벼워질 텐데 말이야.",
    },
    [27607] = {
        ["T"] = "조브린 팬대즐의 의뢰",
        ["O"] =
        "로간나스 [cite: 17]는 당신이 연금술 [cite: 1] 기술을 사용하여 상급 수중 호흡의 비약 [cite: 9] 5개를 제작하고 페랄라스 [cite: 10] 잊혀진 해안에 있는 야영지의 조브린 팬대즐 [cite: 35]에게 배달해 주길 원합니다.",
        ["D"] =
        "본토 해안가에 진을 치고 있는 한 고블린이 상급 수중 호흡의 비약 [cite: 9]을 요청했을 때 단칼에 무시해 버렸소. 난 고블린을 도무지 믿을 수가 없으니까.\n\n하지만 좀 찜찜한 기분이 드는군, $C. 그 비약이 딱히 해를 끼칠 것 같진 않은데도, 내 손으로 직접 배달하고 싶진 않아. 자네가 괜찮은 보상을 원한다면, 그 녀석의 요청을 들어주는 건 어때?",
    },
    [27608] = {
        ["T"] = "연금술사 알빙턴의 의뢰",
        ["O"] =
        "연금술사 알빙턴 [cite: 1]은 당신이 연금술 [cite: 1] 기술을 사용하여 언데드 감지의 비약 [cite: 8] 5개를 제작하고 서부 역병지대 [cite: 34] 서리바람 야영지 [cite: 5]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "아, 동료 연금술사로군. 나는 이곳에서 스컬지 역병의 영향을 연구하며 많은 시간을 보내왔는데, 어느 지역에 언데드가 서성거리는지 알 수만 있다면 연구가 훨씬 더 효율적일 것 같소. 유감스럽게도 언데드 감지의 비약 [cite: 8] 제조법을 적어둔 노트를 잃어버린 모양이야. 자네가 친절하게 비약 5개를 제조해 준다면, 수고비와 함께 내 연구로 얻은 유용한 물건들도 좀 나눠주도록 하지.",
    },
    [27609] = {
        ["T"] = "윌버 워블스미스의 의뢰",
        ["O"] =
        "윌버 워블스미스는 당신이 연금술 [cite: 1] 기술을 사용하여 상급 민첩의 비약 [cite: 9] 5개를 제작하고 아즈샤라 [cite: 2] 워블 할로우의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "오, 연금술사로군요. 전 그 과학의 한 분야를 잘 이해하진 못하지만 정말 존경한답니다!\n\n혹시 부탁 하나 드려도 될까요? 가끔 이 절벽 아래로 도구를 한두 개 떨어뜨릴 때가 있어요. 제 순간이동 [cite: 31]기로 내려갔다 올 수는 있지만, 작동시키는 데 드는 에너지가 너무 귀하거든요. 상급 민첩의 비약 [cite: 9]이 있다면 절벽을 기어오를 수 있고, 배터리는 정말 필요할 때를 위해 아껴둘 수 있을 거예요. 절 도와주실 수 있나요?",
    },
    [27610] = {
        ["T"] = "에리단 블루윈드의 의뢰",
        ["O"] =
        "에리단 블루윈드 [cite: 9]는 당신이 연금술 [cite: 1] 기술을 사용하여 숙면의 물약 [cite: 8] 5개를 제작하고 악령숲 [cite: 10] 에메랄드 성소 [cite: 9]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "오래 있다 보면 이 숲의 타락한 기운이 정신 속으로 스며들게 되지, $C. 내게 지금 가장 필요한 건 하루 이틀 방해받지 않고 푹 자는 거야.\n\n하지만, 오... 넌 연금술사잖아? 나를 위해 숙면의 물약 [cite: 8]을 좀 만들어주지 않겠어? 조만간 푹 자지 못하면 지옥불 광기의 유혹에 굴복하고 말지도 몰라!",
    },
    [27611] = {
        ["T"] = "감독관 힝크의 의뢰",
        ["O"] =
        "마이아잔은 당신이 연금술 [cite: 1] 기술을 사용하여 최하급 치유 물약 [cite: 19] 5개를 제작하고 듀로타 [cite: 8] 오그리마 [cite: 21] 외곽의 비행선 탑에 있는 감독관 힝크에게 배달해 주길 원합니다.",
        ["D"] =
        "신출내기 연금술사로군! 혹시 날 좀 도와줄 수 있겠나? 지금 일이 너무 밀려 있는데, 오그리마 [cite: 21] 밖 비행선 탑의 감독관 힝크가 다친 일꾼들을 위해 최하급 치유 물약 [cite: 19]을 구해달라고 하더군. 난 그런트들을 위한 중요한 일을 해야 해서 말이야. 네가 도와준다면, 물약 5개를 만들어서 힝크에게 좀 전해주게.",
    },
    [27612] = {
        ["T"] = "가르톡의 의뢰",
        ["O"] =
        "마이아잔은 당신이 연금술 [cite: 1] 기술을 사용하여 최하급 방어의 비약 [cite: 9] 5개를 제작하고 듀로타 [cite: 8] Razor Hill [cite: 23]의 가르톡에게 배달해 주길 원합니다.",
        ["D"] =
        "내가 도움을 받을 만한 또 다른 의뢰가 있지 -- 아주 간단해서 기본 기술만 있으면 돼.\n\n동쪽 길을 따라 내려가면 Razor Hill [cite: 23]이 나올 거야. 그 지역 그런트들을 지휘하는 가르톡이 그곳에 주둔하고 있지. 그가 부하들을 위해 최하급 방어의 비약 [cite: 9]을 필요로 해. 이 의뢰를 맡아 주겠나?",
    },
    [27613] = {
        ["T"] = "현자 레인토템의 의뢰",
        ["O"] =
        "크레이 [cite: 12]는 당신이 연금술 [cite: 1] 기술을 사용하여 최하급 마나 물약 [cite: 19] 5개를 제작하고 멀고어 [cite: 20] 붉은 바위 언덕 [cite: 23]의 현자 레인토템 [cite: 18]에게 배달해 주길 원합니다.",
        ["D"] =
        "네 갑옷에 묻은 평온초 꽃잎 [cite: 21] 얼룩만 봐도 네가 연금술사라는 걸 단번에 알 수 있어! 혹시 나 좀 도와줄 수 있니?\n\n공부가 뒤처지는 데다 처리하지 못한 의뢰가 산더미처럼 쌓여 있거든. 네가 도와주면, 연구실에서 내가 더 쓸모 있는 존재가 될 수 있도록 학업에 매진할 수 있을 텐데. 도울 생각이 있다면, 최하급 마나 물약 [cite: 19]을 좀 만들어서 동쪽 붉은 바위 언덕 [cite: 23]의 레인토템 현자님께 전해줘.",
    },
    [27614] = {
        ["T"] = "모린 클라우드스토커의 의뢰",
        ["O"] =
        "크레이 [cite: 12]는 당신이 연금술 [cite: 1] 기술을 사용하여 약한 트롤의 피 비약 [cite: 33] 5개를 제작하고 멀고어 [cite: 20] 블러드후프 마을 [cite: 3] 남쪽 길의 모린 클라우드스토커 [cite: 20]에게 배달해 주길 원합니다.",
        ["D"] =
        "있잖아, 이 주변엔 연금술사가 할 일이 널렸어. 네가 원한다면 더 할 수 있을 거야.\n\n불모의 땅 [cite: 29]으로 이어지는 남쪽 길을 순찰하는 모린 클라우드스토커 [cite: 20]도 자주... 자잘한 사고를 겪거든. 치유 물약 [cite: 13]을 쓸 정도는 아니지만 -- 약한 트롤의 피 비약 [cite: 33]이라면 아주 반가워할 거야. 만약 네가 의뢰를 맡을 생각이 있다면, 약한 트롤의 피 비약 [cite: 33] 5개를 만들어서 그에게 전해줘.",
