    [27615] = {
        ["T"] = "고르도의 의뢰",
        ["O"] =
        "연금술사 요한 [cite: 1]은 당신이 연금술 [cite: 1] 기술을 사용하여 사자의 힘 비약 [cite: 9] 5개를 제작하고 티리스팔 숲 [cite: 30] 브릴 [cite: 4] 서쪽 길의 고르도 [cite: 12]에게 배달해 주길 원합니다.",
        ["D"] =
        "당신이 연금술사라는 사실을 눈치채지 못할 수가 없군요. 지금 제게 쏟아지는 요청들이 너무 많아서, 중요하지 않은 것들에 제 시간을 뺏기고 싶지 않습니다. 연습 삼아 이 의뢰들을 좀 맡아주시겠습니까?\n\n죽음의경비병들이 저 미련한 덩치 고르도 [cite: 12]를 위해 사자의 힘 비약 [cite: 9] 5개를 주문했습니다. 이 비약을 만들어 주신다면 브릴 [cite: 4] 서쪽 길 어딘가에 있는 그 녀석에게 전달해 주시면 됩니다.",
    },
    [27616] = {
        ["T"] = "메릴 웬딜의 의뢰",
        ["O"] =
        "연금술사 요한 [cite: 1]은 당신이 연금술 [cite: 1] 기술을 사용하여 최하급 회복 물약 [cite: 19] 5개를 제작하고 티리스팔 숲 [cite: 30] 브릴 묘지의 메릴 웬딜에게 배달해 주길 원합니다.",
        ["D"] =
        "제가 받는 시시한 요청 중에서도 이것만큼은 꽤 중요합니다. 메릴 웬딜은 스컬지석을 다루는 일이 잦은데, 그 돌은 그녀의 몸과 마음을 좀먹는 것 같더군요. 최하급 회복 물약 [cite: 19]을 만들어서 전해주신다면 메릴에게 큰 도움이 될 겁니다. 그녀는 근처 묘지에 있습니다.",
    },
    [27617] = {
        ["T"] = "죽음의경비병 키트사펠의 의뢰",
        ["O"] =
        "연금술사 렌퍼럴 [cite: 1]은 당신이 연금술 [cite: 1] 기술을 사용하여 하급 치유 물약 [cite: 16] 5개를 제작하고 은빛소나무 숲 [cite: 26] 공동묘지 [cite: 29] 북쪽 길의 죽음의경비병 키트사펠에게 배달해 주길 원합니다.",
        ["D"] =
        "전 무척 바쁜 사람입니다. 비약이나 물약 따위를 만드는 것보다 훨씬 더 중요한 일에 시간을 써야 하거든요. 하지만 내 동포 포세이큰을 외면할 수는 없죠. 공동묘지 [cite: 29] 북쪽 도로에서 사고가 있었다는 소식을 들었습니다. 하급 치유 물약 [cite: 16]을 좀 만들어서 사고 현장에 있는 죽음의경비병 키트사펠에게 전해주세요. 그를 돕지 못한 제 죄책감을 조금이나마 덜 수 있도록 말입니다.",
    },
    [27618] = {
        ["T"] = "킬리안 사나타의 의뢰",
        ["O"] =
        "연금술사 렌퍼럴 [cite: 1]은 당신이 연금술 [cite: 1] 기술을 사용하여 아귀 기름 [cite: 3] 5개를 제작하고 은빛소나무 숲 [cite: 26] 북부 해안가 [cite: 21]의 킬리안 사나타 [cite: 16]에게 배달해 주길 원합니다.",
        ["D"] =
        "도와주는 김에 말인데... 연금술사의 도움이 필요한 자가 한 명 더 있습니다. 부패의 마굴을 지나 해안을 따라 북부 해안가 [cite: 21]에 있는 야영지에서 킬리안 사나타 [cite: 16]를 찾을 수 있을 겁니다. 그가 아귀 기름 [cite: 3]을 여러 병 만들어 줄 사람을 찾고 있더군요. 어... 그가 준 물고기 [cite: 10]는 제가 다른 데 좀 써버렸거든요. 관심이 있다면, 그가 분명 당신에게 돈을 지불할 겁니다.",
