        ["O"] =
        "연금술사 헬브림 [cite: 1]은 당신이 연금술 [cite: 1] 기술을 사용하여 지혜의 비약 [cite: 9] 5개를 제작하고 불모의 땅 [cite: 29] 통곡의 동굴 [cite: 32] 꼭대기에 사는 팔라 세이지윈드 [cite: 10]에게 배달해 주길 원합니다.",
        ["D"] =
        "통곡의 동굴 [cite: 32] 꼭대기에 은둔해 사는 타우렌을 만나기 위해 몇 달마다 순례자들이 찾아오고 있습니다. 그녀의 지혜 [cite: 34]를 이해하는 게 결코 쉽지 않기 때문에, 지혜의 비약 [cite: 9]을 넉넉히 비축해 그녀에게 전해주고 싶군요. 비약을 만들어서 배달해 주신다면, 그녀도 기꺼이 유용한 물건으로 보답할 것입니다.",
    },
    [27620] = {
        ["T"] = "신질의 의뢰",
        ["O"] =
        "연금술사 헬브림 [cite: 1]은 당신이 연금술 [cite: 1] 기술을 사용하여 최하급 인내의 비약 [cite: 9] 5개를 제작하고 불모의 땅 [cite: 29] 십자로 [cite: 6] 북쪽의 자기 집에 사는 신질에게 배달해 주길 원합니다.",
        ["D"] =
        "이 대륙에 사는 모든 기이한 생명체 중에서도 저는 트롤이 가장 불쾌합니다. 냄새나는 데다 수준 높은 문학은 즐기지도 못하니까요... 아무튼, 신질이라는 트롤에게서 최하급 인내의 비약 [cite: 9] 주문이 들어왔습니다. 당신이 이 일을 맡아 주신다면 불만은 없을 겁니다.",
