    [27621] = {
        ["T"] = "양조업자 드론의 의뢰",
        ["O"] =
        "양조업자 드론 [cite: 3]은 당신이 연금술 [cite: 1] 기술을 사용하여 수중 호흡의 비약 [cite: 9] 5개를 제작하고 불모의 땅 [cite: 29] 톱니항 [cite: 22]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑네 $C... 연금술사 $N이라고 불러야 하나? 사실 에일 맥주 양조나 연금술이나 별반 다를 게 없지.\n\n여행하면서 마주친 생물들 덕분에 에일 양조에 대해 많은 걸 배웠지만, 아직 파헤치지 못한 재료의 보고가 하나 있다네: 바로 바다 [cite: 25]지. 그걸 위해 수중 호흡의 비약 [cite: 9]이 필요해. 좀 도와줄 수 있겠나?",
