        ["O"] =
        "양조업자 드론 [cite: 3]은 당신이 연금술 [cite: 1] 기술을 사용하여 신속한 수영 물약 [cite: 28] 5개를 제작하고 불모의 땅 [cite: 29] 톱니항 [cite: 22]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "양조에 쓸 재료를 찾기 위해 바다를 탐험하고 싶긴 하지만 내가 바보도 아니고 바다 [cite: 25] 밑에 상어 떼나 위험한 게 득실댄다는 건 잘 알지. 그러니까 필요할 때 목숨 걸고 헤엄쳐서 도망칠 수 있도록 신속한 수영 물약 [cite: 28]도 몇 개 구해다 주면 정말 고맙겠어!",
    },
    [27623] = {
