        ["O"] =
        "시리스는 당신이 연금술 [cite: 1] 기술을 사용하여 치유 물약 [cite: 13] 5개를 제작하고 잿빛 골짜기 [cite: 2] 토막나무 주둔지 [cite: 27]의 록케 오카르 [cite: 17]에게 배달해 주길 원합니다.",
        ["D"] =
        "$C, 당신도 연금술사라는 이야기를 들었습니다. 대족장님께서 이 주둔지의 기강을 바로잡기 위해 저를 보내셨지만 상황은 생각보다 더 끔찍합니다. 매일 얼라이언스에게 점점 더 많은 그런트들을 잃고 있습니다. 병사들에게 나누어줄 치유 물약 [cite: 13]을 몇 개 주문하고 싶은데, 괜찮겠습니까?",
    },
    [27624] = {
        ["T"] = "연금술사 라이던의 의뢰",
        ["O"] =
        "연금술사 라이던 [cite: 1]은 당신이 연금술 [cite: 1] 기술을 사용하여 화염 기름 [cite: 10] 5개를 제작하고 언덕마루 구릉지 [cite: 14] 타렌 제분소 [cite: 29]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "오... 연금술사로군. 독에 대한 내 관심에 흥미를 느낄 것 같은데. 결국 연금술 [cite: 1]이나 독이나 기술의 뿌리는 다르지 않으니까.\n\n사실 당신의 솜씨가 좀 필요합니다. 언덕마루 [cite: 14]를 위한 특별한 혼합물을 만들고 싶거든요... 화끈한 향을 지닌 독... 불타는 듯한 느낌을 줄 수 있는 것으로 말이죠. 당신이 내게 화염 기름 [cite: 10]을 좀 만들어준다면, 나도 당신의 향후 제작에 도움이 될 만한 유용한 재료들을 제공하겠습니다.",
    },
    [27625] = {
        ["T"] = "엘루의 의뢰",
        ["O"] =
        "엘루 [cite: 9]는 당신이 연금술 [cite: 1] 기술을 사용하여 강인한 트롤의 피 비약 [cite: 28] 5개를 제작하고 버섯구름 봉우리 [cite: 30] 높새바람 봉우리 [cite: 11]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "이곳에서 연금술사를 만나다니 정말 반갑군요. 다친 와이번 새끼들을 돌보고 있는데, 상처 [cite: 34]를 살살 씻어내고 치유 [cite: 13]해 줄 강인한 트롤의 피 물약이 한 묶음 정도 필요합니다. 혹시 이 일을 도와주실 수 있나요?",
    },
    [27626] = {
        ["T"] = "의술사 진질의 의뢰",
        ["O"] =
        "지다 [cite: 15]는 당신이 연금술 [cite: 1] 기술을 사용하여 하급 마나 물약 [cite: 16] 5개를 제작하고 돌발톱 산맥 [cite: 28] 말라카진의 의술사 진질에게 배달해 주길 원합니다.",
        ["D"] =
        "전 연금술사가 아니에요... 음, 진짜 연금술사는 아니죠. 하지만 저희 주인님이신 진질 의술사님은 제가 허공에서 물약을 뚝딱 만들어낼 수 있다고 믿으시는 것 같아요.\n\n의술사님께 드릴 하급 마나 물약 [cite: 16]이 필요해요. 혹시 도와주실 수 있나요? 그냥 몇 개 만들어서 말라카진의 진질님께 가져다주세요. 그러면 저를 제버려 두시고 제 공부에 집중할 수 있게 해 주실지도 몰라요.",
    },
    [27627] = {
        ["T"] = "님보야의 의뢰",
        ["O"] =
        "님보야 [cite: 21]는 당신이 연금술 [cite: 1] 기술을 사용하여 적중의 비약 [cite: 8] 5개를 제작하고 가시덤불 골짜기 [cite: 28] 그롬골의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "다른 숲과 정글 트롤 녀석들이 의술사들의 버프를 받고 있는 한 우리는 계속해서 밀릴 수밖에 없네. 우리에게도 이점이 필요해.\n\n자네가 적중의 비약 [cite: 8]을 좀 만들어서 내게 배달해 줬으면 하네. 그게 있으면 우리도 다른 트롤 녀석들을 상대로 우위를 점할 수 있을 테니까.",
    },
    [27628] = {
        ["T"] = "타베사의 의뢰",
        ["O"] =
        "드라즈질브는 당신이 연금술 [cite: 1] 기술을 사용하여 하급 투명 물약 [cite: 16] 5개를 제작하고 먼지진흙 습지대 [cite: 8] Tabetha's Farm [cite: 28]의 타베사 [cite: 28]에게 배달해 주길 원합니다.",
        ["D"] =
        "아 -- 훌륭한 연금술사이시군요! 당신의 도움이 필요합니다!\n\n늪지대에 타베사 [cite: 28]라는 은둔자가 한 분 살고 계시죠. 그녀가 저희에게 전령을 보내 하급 투명 물약 [cite: 16]이 아주 시급하다고 전해왔는데, 안타깝게도 여기엔 그런 걸 만들 줄 아는 사람이 하나도 없습니다! 혹시 물약을 만들어서 그녀에게 배달해 주실 수 있으신가요? 전 그녀의 분노를 사고 싶지 않습니다. 이미 고통받을 만큼 받았으니까요.",
    },
    [27629] = {
        ["T"] = "타카타 스틸블레이드의 의뢰",
        ["O"] =
        "마윈 슈릴윌은 당신이 연금술 [cite: 1] 기술을 사용하여 인내의 비약 [cite: 8] 5개를 제작하고 잊혀진 땅 [cite: 7] 침묵의 초소 [cite: 11]의 타카타 스틸블레이드 [cite: 28]에게 배달해 주길 원합니다.",
        ["D"] =
        "왕립 연금술 학회의 명을 받아 중요한 임무를 띠고 이곳에 왔습니다만, 호드와 함께 몰려온 이 쓰레기 같은 녀석들은 제가 온갖 자질구레한 부탁이나 들어주러 온 줄 착각하는 모양입니다.\n\n타카타 스틸블레이드 [cite: 28]라는 오크 전사가 근처 악마들의 지옥 마력 때문에 관절이 쑤시고 피부가 스멀거린다고 투덜대더군요. 당신도 연금술에 꽤 소질이 있어 보이니, 그를 위해 인내의 비약 [cite: 8]을 좀 만들어서 제 일감을 좀 덜어 주시죠.",
    },
    [27630] = {
        ["T"] = "썬더하트의 의뢰",
        ["O"] =
        "자칼 모스멜드 [cite: 15]는 당신이 연금술 [cite: 1] 기술을 사용하여 고양이눈 비약 [cite: 5] 5개를 제작하고 황야의 땅 [cite: 2] 카르가스의 썬더하트 [cite: 30]에게 배달해 주길 원합니다.",
        ["D"] =
        "황야의 땅 [cite: 2] 큰 고양이 녀석들은 몹시 대담해, $C. 우리 정찰병들이 녀석들에게 한두 명 당한 게 아니야. 가장 큰 문제는 녀석들의 은신 기술이지. 녀석들이 다가오는 걸 볼 수 있게 해 줄 무언가가 필요해.\n\n나도 연금술사이긴 하지만 독학으로 배운 터라 고양이눈 비약 [cite: 5] 제조법은 모르네. 하지만 자네가 알고 있다면, 이 비약 몇 개만 만들어 주어도 이곳의 그런트들에게 엄청난 도움이 될 걸세.",
    },
    [27631] = {
        ["T"] = "드럼 펠의 의뢰",
        ["O"] =
        "토르간은 당신이 연금술 [cite: 1] 기술을 사용하여 상급 치유 물약 [cite: 12] 5개를 제작하고 아라시 고원 [cite: 1] 망치 주둔지 [cite: 13]의 드럼 펠 [cite: 8]에게 배달해 주길 원합니다.",
        ["D"] =
        "이 야영지의 오크들은 이곳에서 우리 형제자매들에게 벌어진 끔찍한 일들에 대한 기억 때문에 몹시 낙담해 있소. 나는 정령들의 힘을 빌려 그들의 사기를 조금이나마 끌어올려 줄 수 있지만, 다른 이들에겐 예부터 전해 내려오는 전통 연금술 [cite: 1]이 더 효과적일지도 모르오.\n\n예를 들면 드럼 펠 [cite: 8]이 그렇소. 그는 인간들에게 입은 상처를 숨기고 있지. 그를 위해 상급 치유 물약 [cite: 12]을 만들어 주시오. 그럼 새로운 리더십이 깨어나는 걸 볼 수 있을 테니.",
    },
    [27632] = {
        ["T"] = "아키하의 의뢰",
        ["O"] =
        "뒤몽 할로크라이는 당신이 연금술 [cite: 1] 기술을 사용하여 상급 수중 호흡의 비약 [cite: 9] 5개를 제작하고 타나리스 [cite: 28] 안제와타의 아키하에게 배달해 주길 원합니다.",
        ["D"] =
        "전 트롤과 녀석들의 유치한 로아 정령 따위가 정말 터무니없다고 생각해요! 아키하를 한 번 보세요. \"상어의 신\"이라뇨? 그게 말이 되나요!\n\n이 그랄이라는 존재가 진짜 있다면, 상급 수중 호흡의 비약 [cite: 9]을 만들어서 직접 인사라도 하러 가지 그래요? 아니, 당신은 연금술사니까, 직접 가보는 게 어때요?",
    },
    [27633] = {
        ["T"] = "즈랄의 의뢰",
        ["O"] =
        "즈랄은 당신이 연금술 [cite: 1] 기술을 사용하여 언데드 감지의 비약 [cite: 8] 5개를 제작하고 페랄라스 [cite: 10] 글룩의 요새에 있는 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "아, 연금술사. 내 친구 토그는 자기가 아직 살아있다고 생각한다네. 혹시 여기 근처에 자기가 안 죽은 줄 아는 놈들이 더 있는 건 아닌지 궁금하군. 그래서 토그 녀석도 죽은 주제에 태연하게 어슬렁거리는지도 몰라. 자네, 내가 죽은 자들을 볼 수 있게 해주는 마실 것을 만들어 줄 수 있나?",
    },
    [27634] = {
        ["T"] = "트룰 페일베인의 의뢰",
        ["O"] =
        "트룰 페일베인 [cite: 31]은 당신이 연금술 [cite: 1] 기술을 사용하여 상급 민첩의 비약 [cite: 9] 5개를 제작하고 악령숲 [cite: 10] 피멍울 초소 [cite: 3]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "아, 연금술사로군. 전 그 과학의 한 분야를 잘 이해하진 못하지만 정말 존경한답니다.\n\n사실, 상급 민첩의 비약 [cite: 9]이 좀 필요합니다. 이 숲에 스며든 지옥 마력이 제 뼈속까지 파고들어 온몸이 뻣뻣해졌거든요. 그 비약이 제 관절을 다시 움직이게 해 줄 겁니다. 도와주실 수 있나요?",
    },
    [27635] = {
        ["T"] = "수습생 사리나의 의뢰",
        ["O"] =
        "수습생 사리나는 당신이 연금술 [cite: 1] 기술을 사용하여 숙면의 물약 [cite: 8] 5개를 제작하고 아즈샤라 [cite: 2] 발로르모크 [cite: 31]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "레안더 스승님은 연금술 [cite: 1]의 천재이시지만 우릴 뼛골 빠지게 부려 먹으시죠 -- 언데드 농담은 아니에요. 수 개월 동안 제대로 잠 한숨 자본 적 없는 것 같아요.\n\n제 개인 프로젝트 때문에 하던 일을 멈출 순 없지만, 당신이 제게 숙면의 물약 [cite: 8]을 몇 개 만들어주신다면 서서 자면서도 생산성을 높일 수 있을 거예요. 도와주실 수 있나요?",
    },
    [27636] = {
        ["T"] = "치안대장 해거드의 의뢰",
        ["O"] =
        "대장장이 아르거스 [cite: 26]는 당신이 대장기술 [cite: 3]을 사용하여 구리 룬문자 바지 [cite: 24] 1개와 구리 룬문자 건틀릿 [cite: 24] 1개를 제작하고 엘윈 숲 [cite: 9] 동쪽계곡 벌목지 [cite: 8]의 치안대장 해거드 [cite: 19]에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑네, $C. 동료 대장장이를 여기서 다 보는군. 혹시 내가 받은 의뢰 하나를 맡아보는 건 어떤가?\n\n동쪽계곡 벌목지 [cite: 8]의 치안대장 해거드 [cite: 19]가 구리 룬문자 바지 [cite: 24] 한 벌과 구리 룬문자 건틀릿 [cite: 24] 한 켤레를 주문했네. 자네만 괜찮다면 물건을 직접 만들어서 전해주면 되네.\n\n골드샤이어 [cite: 12] 동쪽에 벌목지가 있네.",
    },
    [27637] = {
        ["T"] = "부관 레이너의 의뢰",
        ["O"] =
        "대장장이 아르거스 [cite: 26]는 당신이 대장기술 [cite: 3]을 사용하여 구리 전투 도끼 [cite: 6] 2개를 제작하고 엘윈 숲 [cite: 9] 서쪽시내 주둔지 [cite: 34]의 부관 레이너 [cite: 7]에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑네, $C. 자네가 내 밀린 의뢰를 좀 처리해 줬으면 좋겠군. 부관 레이너 [cite: 7]가 자신의 부하들을 무장시킬 구리 전투 도끼 [cite: 6]를 좀 주문했어.\n\n관심이 있다면 도끼를 만들어서 서쪽시내 주둔지 [cite: 34]에 있는 부관에게 배달해 주게.",
    },
    [27638] = {
        ["T"] = "레욜트 발리브루의 의뢰",
        ["O"] =
        "코간 포지스톤 [cite: 16]은 당신이 대장기술 [cite: 3]을 사용하여 조잡한 연마석 [cite: 24] 10개를 제작하고 던 모로 [cite: 8] 브루날 마을 [cite: 4]의 레욜트 발리브루 [cite: 23]에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑네, $C. 동료 대장장이가 틀림없군. 산더미처럼 쌓인 내 주문을 처리하는 데 자네 망치 [cite: 13] 좀 빌려주지 않겠나?\n\n서쪽 브루날 마을 [cite: 4]의 레욜트 발리브루 [cite: 23]에게 조잡한 연마석 [cite: 24] 한 무더기를 만들어 가져다줄 사람이 필요해. 그의 새로운 맥주 양조와 관련된 일에 쓰일 모양이더군. 생각 있나?",
    },
    [27639] = {
        ["T"] = "채석장주임 테스텐의 의뢰",
        ["O"] =
        "코간 포지스톤 [cite: 16]은 당신이 대장기술 [cite: 3]을 사용하여 구리 철퇴 [cite: 6] 3개를 제작하고 던 모로 [cite: 8] 골볼라 채석장에 있는 채석장주임 테스텐 [cite: 22]에게 배달해 주길 원합니다.",
        ["D"] =
        "같은 대장장이끼리 털어놓자면, 항상 일이 밀려서 처리하지 못할 정도야. 날 좀 도와주고 싶다면, 동쪽 골볼라 채석장에 있는 채석장주임 테스텐 [cite: 22]이 의뢰한 구리 철퇴 [cite: 6] 주문을 하나 주지. 나 대신 이 물건을 좀 만들어 줄 수 있겠나?",
    },
    [27640] = {
        ["T"] = "메리 아이언위브의 의뢰",
        ["O"] =
        "레이니 오크스멜터는 당신이 대장기술 [cite: 3]을 사용하여 무거운 구리 방패와 구리 사슬 조끼 [cite: 6]를 1개씩 제작하고 텔드랏실 [cite: 29] 돌라나르 [cite: 7]의 메리 아이언위브 [cite: 18]에게 배달해 주길 원합니다.",
        ["D"] =
        "이슈누아도어, $C. 긴 이야기를 나눌 시간이 없군요 -- 이 작업장 [cite: 34]을 연 이후로 밀려드는 주문들을 다 처리하지 못하고 있습니다.\n\n이런 -- 당신도 모루 [cite: 1]를 꽤 잘 다루시는 것 같군요. 절 도와주실 의향이 있으시다면, 무거운 구리 방패 한 개와 구리 사슬 조끼 [cite: 6] 한 벌을 제작해서 돌라나르 [cite: 7]의 방어구 상인인 메리 아이언위브 [cite: 18]에게 전달해 주시면 됩니다.",
    },
    [27641] = {
        ["T"] = "에렐라스 앰버스카이의 의뢰",
        ["O"] =
        "레이니 오크스멜터는 당신이 대장기술 [cite: 3]을 사용하여 구리 룬문자 반지 2개를 제작하고 텔드랏실 [cite: 29] 루테란 마을의 에렐라스 앰버스카이 [cite: 9]에게 배달해 주길 원합니다.",
        ["D"] =
        "여기 에렐라스 앰버스카이 [cite: 9]에게서 들어온 주문이 있는데 제 대신 처리해 보시는 건 어떨까요? 그는 구리 룬문자 반지 두 개를 원합니다. 다 만들고 나면 텔드랏실 [cite: 29] 기슭의 루테란 마을에 있는 그를 찾을 수 있을 겁니다. 은행 뒤쪽의 차원문을 통과하면 갈 수 있습니다.",
    },
    [27642] = {
        ["T"] = "병참장교 루이스의 의뢰",
        ["O"] =
        "병참장교 루이스 [cite: 22]는 당신이 대장기술 [cite: 3]을 사용하여 일반 연마석 [cite: 5] 5개를 제작하고 서부 몰락지대 [cite: 34] 감시의 언덕 [cite: 25]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑네, $C. 대장장이를 여기서 다 보는군. 무기와 갑옷의 녹과 때를 벗겨낼 일반 연마석 [cite: 5]이 새로 좀 필요해. 5개만 만들어서 내게 가져다주면 고맙겠네.",
    },
    [27643] = {
        ["T"] = "민병대원 에반젤린의 의뢰",
        ["O"] =
        "병참장교 루이스 [cite: 22]는 당신이 대장기술 [cite: 3]을 사용하여 구리 룬문자 흉갑 [cite: 24] 1개와 구리 룬문자 팔보호구 [cite: 24] 1개를 제작하고 서부 몰락지대 [cite: 34] 남쪽 길의 민병대원 에반젤린에게 배달해 주길 원합니다.",
        ["D"] =
        "일거리를 더 찾고 있다면 하나 더 있지. 서부 몰락지대 [cite: 34] 민병대에 새로 들어온 신병이 갑옷을 완성할 구리 룬문자 흉갑 [cite: 24]과 구리 룬문자 팔보호구 [cite: 24]를 필요로 한다더군. 이것들을 만들어서 민병대원 에반젤린에게 가져다주게. 그녀는 감시의 언덕 [cite: 25] 남쪽 길을 순찰하고 있다네.",
    },
    [27644] = {
        ["T"] = "울란나의 의뢰",
        ["O"] =
        "델프룸 플린트비어드 [cite: 7]는 당신이 대장기술 [cite: 3]을 사용하여 일반 숫돌 [cite: 5] 3개와 일반 무게추 [cite: 5] 3개를 제작하고 어둠해안 [cite: 7] 남쪽 고대정령의 숲에 있는 울란나 [cite: 31]에게 배달해 주길 원합니다.",
        ["D"] =
        "아하, 멀리서도 동료 대장장이는 단번에 알아볼 수 있지! 멀리서 온 손님이라 하니, 고대정령의 숲에 있는 울란나 [cite: 31]가 숫돌과 무게추를 더 보내달라며 쪽지를 보내왔네. 내가 아직 주문을 처리할 여유가 없었는데, 자네가 우리 마을에 있는 동안 자네 기술을 좀 부려본다면 내가 이 의뢰를 넘겨주지.",
    },
    [27645] = {
        ["T"] = "로르난 골드리프의 의뢰",
        ["O"] =
        "델프룸 플린트비어드 [cite: 7]는 당신이 대장기술 [cite: 3]을 사용하여 음영석 [cite: 25] 펜던트 1개와 조율된 구리 다리보호구를 1개 제작하고 잿빛 골짜기 [cite: 2] 국경에 위치한 골드리프 은신처의 로르난 골드리프에게 배달해 주길 원합니다.",
        ["D"] =
        "어둠해안 [cite: 7]이나 그 밖의 지역에 자네처럼 진취적인 젊은 대장장이가 할 일은 널려 있네. 왜냐하면 내가 아직 미처리 상태인 주문서를 가지고 있거든. 아득히 먼 남쪽, 잿빛 골짜기 [cite: 2]와의 국경 도로에 떨어져 사는 로르난 골드리프라는 은둔자에게서 온 주문이지. 자네가 음영석 [cite: 25] 펜던트와 조율된 구리 다리보호구를 만들어서 이 주문을 처리해 준다면 내 짐을 하나 덜게 되는 셈이지.",
    },
    [27646] = {
        ["T"] = "토르발트 딥포지의 의뢰",
        ["O"] =
        "모한 카퍼텅 [cite: 20]은 당신이 대장기술 [cite: 3]을 사용하여 은 해골 열쇠 [cite: 26] 4개를 제작하고 모단 호수 [cite: 17] 남동쪽 왕의 계곡 [cite: 31]에 있는 토르발트 딥포지 [cite: 30]에게 배달해 주길 원합니다.",
        ["D"] =
        "만나서 반갑소, 모험가... 게다가 대장장이이기도 하군! 자네 도움이 필요하네.\n\n왕의 계곡 [cite: 31] 초소에 있는 토르발트 딥포지 [cite: 30]가 최근에 오래된 금고 더미를 찾아냈는데, 억지로 부숴서 열고 싶진 않다는군. 자네가 그를 위해 은 해골 열쇠 [cite: 26]를 좀 만들어준다면, 자네의 수고에 확실히 보답할 걸세.",
    },
    [27647] = {
        ["T"] = "산악경비대 스톰파이크의 의뢰",
        ["O"] =
