        ["O"] =
        "가빈 나알트리 [cite: 11]는 당신이 대장기술 [cite: 3]을 사용하여 무거운 청동 철퇴 [cite: 13] 1개와 무거운 무게추 [cite: 14] 2개를 제작하고 그늘숲 [cite: 8] 서쪽 까마귀 언덕 [cite: 22]의 지터스 [cite: 15]에게 배달해 주길 원합니다.",
        ["D"] =
        "어이, 마을에 새로 온 대장장인가? 야경대 주문이 잔뜩 밀려 있어서 한 민간인이 맡긴 이 주문을 처리하지 못했어. 혹시 날 도와주고 싶다면 무거운 청동 철퇴 [cite: 13] 하나랑 무거운 무게추 [cite: 14] 두어 개를 만들어서 까마귀 언덕 [cite: 22]으로 가져다주게. 주문을 맡긴 자가 그곳에서 어슬렁거리고 있을 거야.",
