    [27649] = {
        ["T"] = "경비병 파커의 의뢰",
        ["O"] =
        "베르너 오스구드 [cite: 32]는 당신이 대장기술 [cite: 3]을 사용하여 순은 방패를 1개 제작하고 붉은마루 산맥 [cite: 23] 동쪽 붉은마루 삼거리 [cite: 30]의 경비병 파커 [cite: 13]에게 배달해 주길 원합니다.",
        ["D"] =
        "대장장이는 아니겠지? 오, 대장장이로군! 당신의 도움이 필요해.\n\n오크들이 쳐들어왔을 때 우리 마을의 마지막 대장장이가 도망가버려서 우리 경비병들은 남은 찌끄러기 장비들로 버티고 있어. 경비병 파커 [cite: 13]를 위해 순은 방패를 하나 주문하고 싶은데, 골드샤이어 [cite: 12]에 방어구를 요청하면 오기까지 너무 오래 걸려. 당신이 직접 만들어서 전해준다면, 파커가 그에 대한 대가로 당신에게 보급품을 줄 수 있도록 조치해 두지.",
    },
    [27650] = {
        ["T"] = "울샨의 의뢰",
        ["O"] =
        "자이앤더는 당신이 대장기술 [cite: 3]을 사용하여 빠른 청동 단검 2개를 제작하고 잿빛 골짜기 [cite: 2] 중앙 실바람 산장 [cite: 26]의 울샨 [cite: 31]에게 배달해 주길 원합니다.",
        ["D"] =
        "아, 대장장이! 당신이 절 도와줄 수 있을지도 모르겠군요 -- 실바람 산장 [cite: 26]의 울샨 [cite: 31]이 새로 들어온 칼이 없냐며 저를 성가시게 하고 있습니다. 세이버 스테이크를 썰기에 적당한 걸 원한다더군요. 제가 만든 것 중에는 그에게 맞는 게 없지만, 숙련된 대장장이라면 울샨 [cite: 31]의 목적에 맞는 빠른 청동 단검을 만들 수 있다고 들었습니다. 단검 두 자루를 만들어 배달해 주신다면, 그가 마침내 절 내버려 둘 겁니다!",
