    [27651] = {
        ["T"] = "잔혹한 롱브레이드의 의뢰",
        ["O"] =
        "브란마르 [cite: 4]는 당신이 대장기술 [cite: 3]을 사용하여 은도금한 청동 건틀릿 [cite: 26] 3개를 제작하고 저습지 [cite: 34] 북쪽 던 모드르 [cite: 8]의 잔혹한 롱브레이드에게 배달해 주길 원합니다.",
        ["D"] =
        "내 사촌 롱브레이드는 던 모드르 [cite: 8] 위쪽에서 검은무쇠 [cite: 6] 일족에 맞서 싸우는 민병대의 일원이네. 자신의 부하들을 위해 은도금한 청동 건틀릿 [cite: 26] 3개를 요청했지만, 테라모어 섬 [cite: 30]에서 밀려드는 주문 때문에 도저히 시간이 나질 않는군. 자네는 솜씨 좋은 대장장이 같으니 -- 이 주문을 처리해 주고 배달까지 해준다면 정말 진심으로 고맙겠네.",
