    [27652] = {
        ["T"] = "부관 도렌의 의뢰",
        ["O"] =
        "부관 도렌 [cite: 17]은 당신이 대장기술 [cite: 3]을 사용하여 청동 전투도끼 [cite: 4] 1개와 청동 대검 [cite: 4] 1개, 그리고 청동 전투해머 [cite: 4] 1개를 제작하고 가시덤불 북쪽 반란군 야영지 [cite: 23]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "이곳에서 대장장이를 만나다니 정말 반갑군. 보시다시피 우리는 보급로조차 제대로 마련하지 못했소. 물론 직접 무기를 찍어낼 대장간조차 없지. 자네에게 청동 전투도끼 [cite: 4], 청동 대검 [cite: 4], 청동 전투해머 [cite: 4]를 하나씩 만들어 달라고 의뢰하고 싶소만. 대가로 자네의 다음 대장 작업에 쓸 보급품을 넉넉히 주겠소.",
