        ["D"] =
        "안녕하신가, 모험가 -- 아니, 대장장이 동료라고 불러야 하나?\n\n테라모어 경비병들을 위한 작업만으로도 산더미 같은데, 저 북쪽의 북부 경비탑 [cite: 21]에 있는 대장 다릴 [cite: 4]에게서 특별 주문이 들어왔소. 이 의뢰 하나를 처리하자고 다른 주문들을 지체할 순 없는 노릇이지. 혹시 자네가 이 일을 좀 맡아주지 않겠나? 그는 녹색 철제 투구 [cite: 12], 녹색 철제 다리보호구 [cite: 12], 녹색 철제 팔보호구 [cite: 12]가 필요하다오.",
    },
    [27654] = {
        ["T"] = "모틀리 헤비브라스의 의뢰",
        ["O"] =
        "맥스턴 스트랑 [cite: 19]은 당신이 대장기술 [cite: 3]을 사용하여 반짝이는 강철 단검 [cite: 11] 2개를 제작하고 잊혀진 땅 [cite: 7] 스퀴글코드 전초기지의 모틀리 헤비브라스에게 배달해 주길 원합니다.",
        ["D"] =
        "이 불모지에 온 걸 환영하네, 대장장이. 코앞까지 들이닥친 악마 놈들로부터 이 작은 전초기지가 든든하게 무장할 수 있도록 내 손가락이 닳아 없어질 정도로 일해왔지!\n\n스퀴글코드 전초기지의 노움 녀석들도 이것저것 주문하기 시작했는데 내가 도무지 처리할 시간이 나질 않네. 날 좀 도와주고 싶다면, 반짝이는 강철 단검 [cite: 11]을 두 자루 만들어서 그곳에 있는 모틀리 헤비브라스에게 전해주게나.",
    },
    [27655] = {
