        ["O"] =
        "다렌 말뷰 [cite: 7]는 당신이 대장기술 [cite: 3]을 사용하여 녹색 철제 갑옷 [cite: 12]을 1개 제작하고 언덕마루 구릉지 [cite: 14] 남녘해안 [cite: 27] 근처 탑에 있는 메이저 헬름스워시에게 배달해 주길 원합니다.",
        ["D"] =
        "이곳엔 대장장이가 없어서 새 편자를 구하는 것조차 힘들지만, 남녘해안 [cite: 27]의 경비대 상황을 생각하면 내 처지는 차라리 나은 편이야. 그들은 몇 년이나 된 낡은 방어구와 무기로 버티고 있지.\n\n자네 대장장이인가? 도와줄 생각이라면, 메이저 헬름스워시에게 새 녹색 철제 갑옷 [cite: 12]이 하나 필요해. 그가 직접 요구하진 않겠지만, 그를 제대로 무장시켜야 해. 만약 우리가 그를 잃는다면, 다음 호드의 공격을 어떻게 막아낼지 상상조차 할 수 없어!",
    },
    [27656] = {
