        ["D"] =
        "눈치챘겠지만 여긴 가열로 [cite: 11]는 있는데 일할 대장장이가 없어. 자네가 이 문제를 해결해 준다면, 관리인 알라리크 [cite: 5]가 주문한 기민한 황수정 [cite: 5] 아뮬렛을 맡기지. 물건을 다 만들면 스트롬가드의 납골당 [cite: 6]에 있는 알라리크에게 배달해 주게. 근처에 어슬렁거리는 호드 녀석들을 조심하고!",
