    [27657] = {
        ["T"] = "샨드리스 페더문의 의뢰",
        ["O"] =
        "샨드리스 페더문 [cite: 26]은 당신이 대장기술 [cite: 3]을 사용하여 강철 흉갑 [cite: 27] 6개를 제작하고 페랄라스 [cite: 10] 페더문 요새 [cite: 10]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "우리 파수꾼 중에는 무기를 만드는 자가 거의 없네. 대장장이, 자네 솜씨를 좀 빌려야겠어. 새로 모집한 파수꾼들을 위해 강철 흉갑 [cite: 27] 여섯 개를 만들어 주었으면 하네. 다 만들거든 내게로 가져와 주게.",
