        ["O"] =
        "사령관 아쉬람 발러피스트 [cite: 6]는 당신이 대장기술 [cite: 3]을 사용하여 검은 대형 철퇴 [cite: 3] 2개를 제작하고 서부 역병지대 [cite: 34] 서리바람 야영지 [cite: 5]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "아, 대장장이로군. 자네 기술이 좀 필요하네.\n\n스컬지를 뒤로 밀어내긴 했지만, 전투를 이어가려면 새 무기가 필요해. 언데드를 상대로 아주 효과적이라는 검은 대형 철퇴 [cite: 3]에 대해 들었네. 두 자루를 만들어서 내게 가져와 보게. 그 소문이 사실인지 시험해 보지.",
    },
    [27659] = {
        ["T"] = "대족장 운갈의 의뢰",
        ["O"] =
        "웬디 워블스미스는 당신이 대장기술 [cite: 3]을 사용하여 진은 해골 열쇠 [cite: 31] 4개를 제작하고 아즈샤라 [cite: 2] 북부 검은아귀 [cite: 3] 마을의 대족장 운갈에게 배달해 주길 원합니다.",
        ["D"] =
        "어이! 대장장이 맞지?\n\n검은아귀 [cite: 3] 펄볼그 [cite: 11]들에게 우리가 위협적인 존재가 아니라는 걸 보여줄, 상징적이고 멋진 선물이 없을까 고민하고 있었거든. 딱 좋은 생각이 났어: 진은 해골 열쇠 [cite: 31]야. 우정의 열쇠 같은 그런 의미 말이야! 우리 대신 이 열쇠를 만들어서 배달해 줄 대장장이가 필요해. 관심 있어?",
    },
    [27660] = {
        ["T"] = "말리니 프로스트문의 의뢰",
        ["O"] =
        "말리니 프로스트문 [cite: 20]은 당신이 대장기술 [cite: 3]을 사용하여 미스릴 코이프 [cite: 20] 1개와 미스릴 미늘 바지 [cite: 20] 1개를 제작하고 악령숲 [cite: 10] 갈퀴가지 숲 [cite: 28]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "반가워요, $C. 당신도 꽤 노련한 대장장이라는 게 느껴지는군요. 악령숲 [cite: 10]의 지독한 지옥 가스 때문에 제 갑옷이 완전히 녹아버렸지 뭐예요. 새 미스릴 미늘 바지 [cite: 20]와 미스릴 코이프 [cite: 20]가 필요해요. 만들어 주신다면, 제 물건들과 교환해 드리죠.",
    },
    [27661] = {
        ["T"] = "라르 프라울터스크의 의뢰",
        ["O"] =
        "우아크 [cite: 34]는 당신이 대장기술 [cite: 3]을 사용하여 구리 룬문자 바지 [cite: 24] 1개와 구리 룬문자 건틀릿 [cite: 24] 1개를 제작하고 듀로타 [cite: 8] 센진 마을의 라르 프라울터스크 [cite: 16]에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑군, $C. 동료 대장장이의 손길이 느껴지네. 내가 받은 의뢰 하나를 맡아보는 건 어떤가?\n\n센진 마을의 라르 프라울터스크 [cite: 16]가 구리 룬문자 바지 [cite: 24] 한 벌과 구리 룬문자 건틀릿 [cite: 24] 한 켤레를 주문했네. 자네만 괜찮다면 직접 물건을 만들어서 배달해 주게.\n\n센진 마을은 Razor Hill [cite: 23] 남쪽에 있네 -- 여길 오면서 지나쳤을 거야.",
    },
    [27662] = {
