        ["O"] =
        "우아크 [cite: 34]는 당신이 대장기술 [cite: 3]을 사용하여 구리 전투 도끼 [cite: 6] 2개를 제작하고 듀로타 [cite: 8] 오그리마 [cite: 21] 외곽의 비행선 탑에 있는 감독관 힝크에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑군, $C. 이 밀려드는 의뢰들을 처리하는 데 네 도움이 필요해. 감독관 힝크가 일꾼들이 비행선 탑에서 전갈 떼를 쫓아내는 데 쓸 구리 전투 도끼 [cite: 6]를 좀 주문했어.\n\n이 의뢰에 관심이 있다면, 도끼를 만들어서 여기서 북쪽에 있는 오그리마 [cite: 21] 외곽 비행선 탑의 감독관에게 배달해 주면 되네.",
