    [27663] = {
        ["T"] = "현자 레인토템의 의뢰",
        ["O"] =
        "마흐노트 러프운드 [cite: 18]는 당신이 대장기술 [cite: 3]을 사용하여 조잡한 연마석 [cite: 24] 10개를 제작하고 멀고어 [cite: 20] 북동쪽 붉은 바위 언덕 [cite: 23]의 현자 레인토템 [cite: 18]에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑네, $C. 대장장이로군. 혹시 현자님께서 주신 의뢰 하나를 좀 도와줄 수 있겠나?\n\n북동쪽 붉은 바위 언덕 [cite: 23]에 계신 현자 레인토템 [cite: 18]님께 조잡한 연마석 [cite: 24]을 만들어 배달해 줄 사람이 필요하네. 망자들을 위한 신성한 의식에 쓰일 텐데, 내가 가진 재고가 몽땅 떨어져서 말이야. 좀 도와주겠나?",
    },
    [27664] = {
        ["T"] = "이얀 이글탈론의 의뢰",
        ["O"] =
        "마흐노트 러프운드 [cite: 18]는 당신이 대장기술 [cite: 3]을 사용하여 구리 철퇴 [cite: 6] 3개를 제작하고 멀고어 [cite: 20] 썬더 블러프 [cite: 30]의 이얀 이글탈론 [cite: 9]에게 배달해 주길 원합니다.",
        ["D"] =
        "이얀 이글탈론 [cite: 9]이 형제의 곧 다가올 의식에 선물로 쓸 구리 철퇴 [cite: 6]를 찾으러 조금 전에 다녀갔소. 철퇴 세 자루를 의뢰하고 싶어 했지만 내게는 재고가 없었고, 썬더 블러프 [cite: 30]의 대장장이들은 제시간에 만들기엔 너무 바빴지. 당신이 이 주문을 서둘러 처리해 준다면, 그도 몹시 고마워할 거요.",
    },
    [27665] = {
        ["T"] = "죽음의경비병 시머의 의뢰",
        ["O"] =
        "아베 윈터스 [cite: 1]는 당신이 대장기술 [cite: 3]을 사용하여 무거운 구리 방패와 구리 사슬 조끼 [cite: 6]를 1개씩 제작하고 티리스팔 숲 [cite: 30] 죽음의 종소리 마을 [cite: 7] 입구의 죽음의경비병 시머 [cite: 7]에게 배달해 주길 원합니다.",
        ["D"] =
        "이런, 긴 이야기를 나눌 시간이 없군 -- 붉은십자군 [cite: 6] 녀석들이 나대기 시작한 이후로 주문이 쏟아져서 한참이나 밀려 있거든.\n\n이런 -- 당신도 모루 [cite: 1]를 꽤 잘 다루시는 것 같군요. 절 도와주실 의향이 있으시다면, 무거운 구리 방패 한 개와 구리 사슬 조끼 [cite: 6] 한 벌을 제작해서 죽음의 종소리 마을 [cite: 7] 입구 초소를 지키고 있는 죽음의경비병 시머 [cite: 7]에게 배달해 주십시오.",
    },
    [27666] = {
        ["T"] = "죽음의경비병 리니아의 의뢰",
        ["O"] =
        "아베 윈터스 [cite: 1]는 당신이 대장기술 [cite: 3]을 사용하여 구리 룬문자 반지 2개를 제작하고 티리스팔 숲 [cite: 30] 브릴 [cite: 4] 동쪽 도로의 야영지에 있는 죽음의경비병 리니아 [cite: 7]에게 배달해 주길 원합니다.",
        ["D"] =
        "여기 죽음의경비병 리니아 [cite: 7]가 의뢰한 주문이 있는데 제 대신 처리해 보는 건 어떻소? 구리 룬문자 반지 두 개를 원하더군. 물건을 완성하면 동쪽 브릴 [cite: 4]에서 나오는 길을 따라 내려가다 보면 그녀를 찾을 수 있을 거요. 키트사펠 광산에 도착했다면, 너무 멀리 간 거니까 참고하시오.",
    },
    [27667] = {
        ["T"] = "세바스티안 멜로체의 의뢰",
        ["O"] =
        "세바스티안 멜로체 [cite: 25]는 당신이 대장기술 [cite: 3]을 사용하여 일반 연마석 [cite: 5] 5개를 제작하고 은빛소나무 숲 [cite: 26] 공동묘지 [cite: 29]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑네, $C. 마을에서 대장장이를 보니 반갑군. 무기와 갑옷의 녹과 찌든 때를 제거할 새 일반 연마석 [cite: 5]이 좀 필요하네. 자네가 5개만 만들어서 내게 가져다주면 정말 고맙겠네.",
    },
    [27668] = {
        ["T"] = "레인 요릭의 의뢰",
        ["O"] =
        "세바스티안 멜로체 [cite: 25]는 당신이 대장기술 [cite: 3]을 사용하여 구리 룬문자 흉갑 [cite: 24] 1개와 구리 룬문자 팔보호구 [cite: 24] 1개를 제작하고 은빛소나무 숲 [cite: 26] 이바르 호박밭 [cite: 29]의 레인 요릭 [cite: 22]에게 배달해 주길 원합니다.",
        ["D"] =
        "일거리를 더 찾고 있다면, 이바르 호박밭 [cite: 29]에 있는 레인 요릭 [cite: 22]이 형의 망가진 갑옷을 대신할 구리 룬문자 흉갑 [cite: 24]과 구리 룬문자 팔보호구 [cite: 24]를 필요로 하네. 자네가 이걸 만들어서 그곳에 있는 레인에게 가져다주게. 이바르 호박밭 [cite: 29]은 공동묘지 [cite: 29] 북쪽에 있네.",
    },
    [27669] = {
        ["T"] = "우제크의 의뢰",
        ["O"] =
        "트라우그 [cite: 31]는 당신이 대장기술 [cite: 3]을 사용하여 일반 숫돌 [cite: 5] 3개와 일반 무게추 [cite: 5] 3개를 제작하고 불모의 땅 [cite: 29] 북동쪽 천리길 경비초소 [cite: 10]의 우제크 [cite: 31]에게 배달해 주길 원합니다.",
        ["D"] =
        "아하, 멀리서도 동료 대장장이는 단번에 알아볼 수 있지! 멀리서 온 손님이라 하니, 천리길 경비초소 [cite: 10]에 있는 우제크 [cite: 31]가 숫돌과 무게추를 더 보내달라며 쪽지를 보내왔네. 내가 아직 주문을 처리할 여유가 없었는데, 자네가 우리 마을에 있는 동안 자네 기술을 좀 부려본다면 내가 이 의뢰를 넘겨주지.",
    },
    [27670] = {
        ["T"] = "크라날 피스의 의뢰",
        ["O"] =
        "트라우그 [cite: 31]는 당신이 대장기술 [cite: 3]을 사용하여 음영석 [cite: 25] 펜던트 1개와 조율된 구리 다리보호구를 1개 제작하고 불모의 땅 [cite: 29] 그롤돔 농장의 크라날 피스 [cite: 16]에게 배달해 주길 원합니다.",
        ["D"] =
        "십자로 [cite: 6]나 그 밖의 지역에 자네처럼 진취적인 젊은 대장장이가 할 일은 널려 있네. 왜냐하면 내가 아직 미처리 상태인 주문서를 가지고 있거든. 북쪽 도로에 떨어져 사는, 잿빛 골짜기 [cite: 2] 경계와 멀지 않은 곳에 사는 크라날 피스 [cite: 16]라는 은둔자에게서 온 주문이지. 자네가 음영석 [cite: 25] 펜던트와 조율된 구리 다리보호구를 만들어서 이 주문을 처리해 준다면 내 짐을 하나 덜게 되는 셈이지.",
    },
    [27671] = {
        ["T"] = "브린의 의뢰",
        ["O"] =
        "테터낵 스틸포지 [cite: 29]는 당신이 대장기술 [cite: 3]을 사용하여 은 해골 열쇠 [cite: 26] 4개를 제작하고 남부 불모의 땅 [cite: 27] 검은가시 능선 꼭대기의 브린 [cite: 4]에게 배달해 주길 원합니다.",
        ["D"] =
        "만나서 반갑소, 모험가... 게다가 대장장이이기도 하군! 당신의 도움이 필요하오.\n\n브린 [cite: 4]이라는 은둔형 주술사가 은 해골 열쇠 [cite: 26]를 좀 만들어달라고 부탁했는데, 지금 은이 하나도 남지 않았소. 자네가 은을 구해서 그녀의 주문을 처리해 준다면, 대족장님이 지시하신 새로운 무기를 만드는 일에 더 집중할 수 있을 거요.",
    },
    [27672] = {
        ["T"] = "갠 스톤스파이어의 의뢰",
        ["O"] =
        "테터낵 스틸포지 [cite: 29]는 당신이 대장기술 [cite: 3]을 사용하여 두꺼운날 전투 도끼 [cite: 30] 2개를 제작하고 불모의 땅 [cite: 29] 남부 황금길 [cite: 27]의 갠 스톤스파이어 [cite: 11]에게 배달해 주길 원합니다.",
        ["D"] =
        "가시멧돼지가 대상 행렬을 공격한 이후, 타우렌 한 명이 남부 황금길 [cite: 27]을 계속해서 여행하고 있네. 그의 끈기는 대단하지만, 무장이 좀 더 든든하다면 훨씬 오래 버틸 수 있겠지.\n\n아직 그를 위해 두꺼운날 전투 도끼 [cite: 30] 두어 개를 만들어주지 못했는데, 자네가 그 일을 좀 맡아주면 좋겠군. 다 만들고 나면, 남쪽 도로를 순찰하는 그를 만날 수 있을 거야.",
    },
    [27673] = {
        ["T"] = "토렉의 의뢰",
        ["O"] =
        "작업반장 바란은 당신이 대장기술 [cite: 3]을 사용하여 무거운 청동 철퇴 [cite: 13] 1개와 무거운 무게추 [cite: 14] 2개를 제작하고 잿빛 골짜기 [cite: 2] 은빛날개 전초기지 [cite: 26] 동쪽 언덕에 있는 토렉 [cite: 30]에게 배달해 주길 원합니다.",
        ["D"] =
        "어이, 마을에 새로 온 대장장인가? 전쟁노래 부족 주문이 잔뜩 밀려 있는데, 급하게 처리해야 할 게 하나 있어. 혹시 날 좀 도와주고 싶다면, 무거운 청동 철퇴 [cite: 13] 하나랑 무거운 무게추 [cite: 14] 두어 개를 만들어서 은빛날개 전초기지 [cite: 26] 근처 언덕에 있는 토렉 [cite: 30]에게 가져다주게. 그 녀석 지금 거기서 자기 부대랑 습격 준비를 하고 있거든.",
    },
    [27674] = {
        ["T"] = "죽음의추적자 레시의 의뢰",
        ["O"] =
        "오트 [cite: 21]는 당신이 대장기술 [cite: 3]을 사용하여 순은 방패를 1개 제작하고 언덕마루 구릉지 [cite: 14] 남서쪽 남부경비 탑 [cite: 27]의 죽음의추적자 레시 [cite: 7]에게 배달해 주길 원합니다.",
        ["D"] =
        "대장장이는 아니겠지? 오, 대장장이로군! 네 도움이 필요해.\n\n제3차 대전쟁 때 타렌 제분소 [cite: 29]의 마지막 대장장이가 죽고 나서, 우리 경비병 몇 명은 남은 찌끄러기 장비들로 버티고 있어. 죽음의추적자 레시 [cite: 7]를 위해 순은 방패를 하나 주문하고 싶은데, 언더시티 [cite: 31]에 방어구를 요청하면 오기까지 너무 오래 걸려. 네가 직접 만들어서 전해준다면, 레시가 그에 대한 대가로 네게 보급품을 줄 수 있도록 조치해 두지.",
    },
    [27675] = {
        ["T"] = "위즐로 베어링샤이너의 의뢰",
        ["O"] =
        "위즐로 베어링샤이너 [cite: 34]는 당신이 대장기술 [cite: 3]을 사용하여 빠른 청동 단검 2개를 제작하고 버섯구름 봉우리 [cite: 30] 백사장 야영지 [cite: 34]의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "아, 대장장이! 당신이 절 좀 도와줄 수 있겠군요 -- 상단이 또 습격을 당할 때를 대비해야 하는데, 그걸 위해 끝내주는 단검 두 자루가 필요해요. 아주 날렵한 거, 뭔지 알죠. 반짝이고, 빠른 거. 가능하겠죠?",
    },
    [27676] = {
        ["T"] = "다른 탈론그립의 의뢰",
        ["O"] =
        "디시 스프링소켓은 당신이 대장기술 [cite: 3]을 사용하여 은도금한 청동 건틀릿 [cite: 26] 3개를 제작하고 돌발톱 산맥 [cite: 28] 남쪽 말라카진의 다른 탈론그립 [cite: 7]에게 배달해 주길 원합니다.",
        ["D"] =
        "어이, 대장장이? 이 오크 녀석이 대장간을 들르는 아무 대장장이한테나 은도금한 청동 건틀릿 [cite: 26] 세 켤레를 구한다는 메모를 남겨놨어. 혹시 관심 있으면, 만들어서 말라카진의 다른 탈론그립 [cite: 7]에게 가져다줘.",
    },
    [27677] = {
        ["T"] = "헤멧 네싱워리의 의뢰",
        ["O"] =
        "바르 [cite: 32]는 당신이 대장기술 [cite: 3]을 사용하여 청동 전투도끼 [cite: 4] 1개와 청동 대검 [cite: 4] 1개, 그리고 청동 전투해머 [cite: 4] 1개를 제작하고 가시덤불 북쪽 네싱워리 원정대 [cite: 20]의 헤멧 네싱워리 [cite: 14]에게 배달해 주길 원합니다.",
        ["D"] =
        "이곳에서 대장장이를 또 만나니 정말 반갑군. 저기 드워프 사냥꾼, 헤멧 네싱워리 [cite: 14]가 제작 요청을 하나 해왔네. 아마 얼라이언스 녀석들이 아직 제대로 된 보급로를 못 뚫어서 무기를 제때 조달하지 못하는 모양이야.\n\n개인적으론 얼라이언스 영토 근처에 얼씬도 하고 싶지 않으니, 자네에게 청동 전투도끼 [cite: 4], 청동 대검 [cite: 4], 청동 전투해머 [cite: 4]를 내 몫까지 만들어서 그의 야영지에 배달해 주길 의뢰하고 싶네만. 도와주면 정말 고맙겠어.",
    },
    [27678] = {
        ["T"] = "늪지눈알 자알의 의뢰",
        ["O"] =
        "줄르그 [cite: 35]는 당신이 대장기술 [cite: 3]을 사용하여 녹색 철제 투구 [cite: 12] 1개, 녹색 철제 팔보호구 [cite: 12] 1개, 녹색 철제 다리보호구 [cite: 12] 1개를 제작하고 먼지진흙 습지대 [cite: 8] 늪빛 장원의 늪지눈알 자알에게 배달해 주길 원합니다.",
        ["D"] =
        "너 쇠 치는 애?\n\n인간이 갑옷 원한다. 근데 나 인간 몸에 맞게 만드는 거 모른다. 무기만 안다. 걔 녹색 철제 투구 [cite: 12], 녹색 철제 다리보호구 [cite: 12], 녹색 철제 팔보호구 [cite: 12] 필요하다. 너 쇠 치면 마녀 언덕 [cite: 34]의 늪지눈알에게 가져가라.",
    },
    [27679] = {
        ["T"] = "애니 그림의 의뢰",
        ["O"] =
