        ["D"] =
        "포세이큰은 가장 교활한 적이라는 걸 증명해 냈네, $C. 녀석들은 음흉하고 기만적이며 믿을 수 없는 존재일 뿐만 아니라, 자연의 섭리와 빛 자체를 거스르는 범죄이지.\n\n하지만 리치 [cite: 17] 왕의 지배 [cite: 6]에서 벗어나려는 녀석들의 의지 하나만큼은 가히 놀라울 정도야. 스컬지의 공격에서 또다시 살아남으려면, 포세이큰이 어떻게 그런 엄청난 일을 해냈는지 최대한 많이 이해하는 것이 우리에게도 큰 도움이 될 걸세. 동부 역병지대 [cite: 8]에 있는 녀석들의 사촌 격인 구울과 누더기골렘들을 도살하는 것부터 시작하게나. 녀석들의 썩은 내장을 조심스레 모아 연금술사인 리다 크리스탈팝에게 가져가게. 아이언포지 [cite: 15] 연금술 [cite: 1] 연구소에서 그녀를 찾을 수 있을 거야.",
