        ["D"] =
        "포세이큰은 리치 [cite: 17] 왕의 정신 지배 [cite: 6]에서 벗어났다고 말하지. 만약 그게 사실이라면, 우리도 정신 침투로부터 대상의 마음을 차단시켜 강제로 지배 [cite: 6]를 끊어버릴 수 있어야 해. 이론상으로는 그 언데드가 비적대적으로, 심지어 우호적으로 변해야 맞지.\n\n내가 직접 고안한 이 보석을 가져가서 동부 역병지대 [cite: 8]의 밴시 [cite: 2]들에게 시험해 보게. 확실한 대조군을 위해 여러 밴시 [cite: 2]에게 시험해 봐야 할 거야. 내가 목록을 준비해 뒀으니 거기에 적힌 녀석들에게 써보고 결과를 가져와 주게.",
