    [27889] = {
        ["T"] = "생존 의지",
        ["O"] = "스톰윈드 [cite: 28]에 있는 기록관 로이와 대화해야 합니다.",
        ["D"] =
        "이번 실험이 완전히 헛수고는 아니었다고 생각하네. 대주교님께서 알아야 할 정보는 내가 책임지고 모두 보고하겠네.\n\n여기서 알게 된 사실을 토대로 연구를 계속 이어가고 싶다면, 스톰윈드 [cite: 28]의 기록관 로이와 이야기해 보는 게 좋을 거야.\n\n이것으로 우린 빚을 갚은 걸로 하지.",
    },
    [27890] = {
        ["T"] = "삶과 죽음 [cite: 7]의 문제",
        ["O"] = "썬더 블러프 [cite: 30] 장로의 봉우리 [cite: 8]에 있는 마가타 그림토템 [cite: 18]을 찾아야 합니다.",
        ["D"] =
        "반갑군, $N. 마가타 그림토템 [cite: 18] 님의 전갈을 가져왔네. 은밀하게 처리해야 할 일이 있다며 적임자를 찾고 계시더군. 포세이큰과 관련된 일인 것 같아.\n\n자네가 믿을 만한 $C라는 걸 알고 있으니, 이 일에 아주 적격일 거라 생각하네. 썬더 블러프 [cite: 30] 장로의 봉우리 [cite: 8]에서 그녀를 찾을 수 있을 거야. 명심해, $N. 누군가 묻는다면 나는 이 일에 대해 일언반구도 하지 않은 걸로 하는 거야.",
    },
    [27891] = {
        ["T"] = "삶과 죽음 [cite: 7]의 문제",
        ["O"] =
        "동부 역병지대 [cite: 8]의 구울과 누더기골렘에게서 썩은 내장 30개를 모아 언더시티 [cite: 31] 연금술 [cite: 1] 실험실에 있는 홀카 그레이혼에게 가져가야 합니다.",
        ["D"] =
        "우리의 동맹인 포세이큰은 우리 모두에게 여전히 수수께끼 같은 존재지. 난 그들이 의심스러우면서도 한편으론 꽤 흥미로워, 그들을 좀 더 깊이 이해하고 싶은데. 자네도 그렇지 않나?\n\n동부 역병지대 [cite: 8]에 있는 그들의 사촌 격인 구울과 누더기골렘들을 도살하는 것부터 시작하게. 녀석들의 썩은 내장을 조심스레 거두어 내 사절인 홀카 그레이혼에게 가져가 주게나. 언더시티 [cite: 31]의 연금술 [cite: 1] 실험실에서 그녀를 찾을 수 있을 거야.",
    },
    [27892] = {
        ["T"] = "삶과 죽음 [cite: 7]의 문제",
        ["O"] = "동부 역병지대 [cite: 8]의 찢겨진 비명소리, 증오의 비명소리, 죽음의 노래꾼들에게 홀카의 정신 절연 수정을 시험해 봐야 합니다.",
        ["D"] =
        "포세이큰은 리치 [cite: 17] 왕의 정신 지배 [cite: 6]에서 벗어났다고 주장하죠. 그 말이 사실이라면, 목표물의 정신을 외부 침투로부터 차단하여 지배 [cite: 6]를 강제로 끊어버릴 수 있어야 해요. 이론적으로는 언데드가 비적대적으로, 심지어 우호적으로 변해야 정상이죠.\n\n제가 직접 고안한 이 보석을 가져가서 동부 역병지대 [cite: 8]의 밴시 [cite: 2]들에게 시험해 보세요. 대조군을 위해 꽤 많은 밴시 [cite: 2]에게 시험해 봐야 할 거예요. 결과를 제게 가져와 주세요.",
    },
    [27893] = {
        ["T"] = "삶과 죽음 [cite: 7]의 문제",
        ["O"] = "언더시티 [cite: 31] 연금술 [cite: 1] 실험실에 있는 수석 연금술사 파라넬 [cite: 19]과 홀카의 연구에 대해 이야기해야 합니다.",
        ["D"] =
        "포세이큰이라는 존재, 즉 삶과 죽음 [cite: 7] 사이에 머무는 상태가 과학의 이해 범위를 넘어서는 현상이 아니라면, 지금 눈앞에 벌어지는 이 상황을 도저히 이해할 수 없어요. 뭔가 중요한 조각이 빠져 있는 느낌이고, 이 연구에 포세이큰을 직접 참여시키는 것 외에는 선택의 여지가 없는 것 같군요. 수석 연금술사 파라넬 [cite: 19] 님께 이 데이터를 보여드리고 그분의 의견을 들어보세요.",
    },
    [27894] = {
        ["T"] = "삶과 죽음 [cite: 7]의 문제",
        ["O"] = "포세이큰에 대해 배운 것을 가지고 썬더 블러프 [cite: 30] 장로의 봉우리 [cite: 8]에 있는 마가타 그림토템 [cite: 18]에게 돌아가야 합니다.",
        ["D"] =
        "그렇군요. 그래서 홀카가 포세이큰 그 자체를 연구하고 있었던 거군요.\n\n제가 이 정보에 화가 났을 거라 생각할 수도 있겠지만, 그렇지 않습니다. 우리가 삶을 살아가는 동안에도, 우리가 존재하는 이유의 상당 부분은 우리에게 수수께끼로 남아 있으니까요. 적어도 저는 그렇게 느낍니다. 전 대부분의 사람들보다 스컬지의 본질을 연구하는 데 훨씬 더 많은 시간을 보냈으니까요.\n\n당신에게 내려줄 수 있는 결론은 하나입니다. 어둠의 여왕님께서 말씀하셨듯, 이런 삶은 저주입니다. 누군가는 이를 어둠의 축복 [cite: 3]이라 부르고 확실히 이점도 존재하지만, 그럼에도 여전히 저주일 뿐입니다. 가장 어리석은 자만이 우리 대열에 자발적으로 합류하려 하겠지요.\n\n즉, 언데드로 되살아난 모든 존재가 삶을 이어가는 데 성공하는 것은 아닙니다. 포세이큰이 된다는 것은 삶 그 자체가 당신을 버렸을 때조차도 살아남으려는 강인한 의지 [cite: 32]를 갖는 것입니다. 이 메시지를 당신의 주인에게 전하십시오.",
    },
    [27895] = {
        ["T"] = "삶과 죽음 [cite: 7]의 문제",
        ["O"] = "썬더 블러프 [cite: 30]에서 용사 사이크를 찾으십시오.",
        ["D"] =
        "포세이큰에 대해서는 더 알아야 할 것이 많다고 생각하네. 자네가 그들에게 더욱 가까워지길 원한다면, 썬더 블러프 [cite: 30]의 용사 사이크와 대화하며 지금까지 갈고닦은 기술을 유용하게 활용할 수 있을 거라고 믿네.\n\n자, 이제 내 앞에서 물러가게!",
    },
    [27896] = {
        ["T"] = "별에 새겨진 징조",
        ["O"] = "동부 내륙지 [cite: 29]의 맹금의 봉우리 [cite: 1]에 있는 폴스타트 와일드해머 [cite: 10]와 대화해야 합니다.",
        ["D"] =
        "반갑네 $N! 자네 혹시 천문학에 관심 있나? 듣자 하니 조만간 아주 특별한 천문 현상이 일어난다고 하더군 -- 그리고 맹금의 봉우리 [cite: 1]의 와일드해머 드워프들이 그와 관련된 중요한 의식을 도와줄 용감한 모험가를 찾고 있다지 뭔가.\n\n하지만 명심하게 -- 와일드해머 드워프들은 저 거친 타우렌 녀석들처럼 대지모신을 숭배하거든. 이 일을 맡으려면 그 소 녀석들과도 어울려야 할지도 몰라.\n\n자넨 어떨지 모르겠지만 난 말대꾸하는 스테이크는 질색이라서 말이야.\n\n그래도 여전히 관심이 있다면, 맹금의 봉우리 [cite: 1]의 폴스타트를 찾아가 보게나.",
    },
    [27897] = {
        ["T"] = "별에 새겨진 징조",
        ["O"] = "멀고어 [cite: 20]와 불모의 땅 [cite: 29] 사이의 언덕에 있는 대지모신의 안식처에서 별의 예언자 나로와 대화해야 합니다.",
        ["D"] =
        "오 위대한 그리핀이시여, 자네 저거 봤나? 하늘에서 유성이 떨어지고 있어! 저게 바로 우리가 기다리던 징조야 -- 대지모신의 안식처 동굴이 마침내 열렸다는 뜻이지. 별의 예언자 나로가 멀고어 [cite: 20]와 불모의 땅 [cite: 29] 경계에 있는 썬더 블러프 [cite: 30] 북동쪽 언덕에서 그곳을 지키고 있다네. 거긴 호드 구역이라서 자네처럼 용감한 모험가가 그곳으로 가, 별의 예언자가 쌍둥이 심장을 되찾는 걸 도와주길 바랐던 거야.\n\n내가 왜 우리 부족 사람을 보내지 않는지 궁금할 테지? 글쎄, 모든 걸 예견한 예언에 따르면 오직 이방인만이 대지모신의 보물을 안전하게 꺼낼 수 있다고 하더군. 자네가 할 의향이 있다면, 칼림도어 [cite: 15]로 향하는 다음 배에 당장 자네 이름을 올리지.",
    },
    [27898] = {
        ["T"] = "별에 새겨진 징조",
        ["O"] = "썬더 블러프 [cite: 30]에 있는 잔겐 스톤후프 [cite: 35]와 대화해야 합니다.",
        ["D"] =
        "반갑네 $N! 자네 혹시 천문학에 관심 있나? 듣자 하니 조만간 아주 특별한 천문 현상이 일어난다고 하더군 -- 그리고 주술사 잔겐 스톤후프 [cite: 35]가 그와 관련된 중요한 의식을 도와줄 용감한 모험가를 찾고 있다지 뭔가.\n\n썬더 블러프 [cite: 30] 중심 봉우리의 케른 블러드후프 [cite: 5] 근처에서 그를 찾을 수 있을 거야.",
    },
    [27899] = {
        ["T"] = "별에 새겨진 징조",
        ["O"] = "멀고어 [cite: 20]와 불모의 땅 [cite: 29] 사이의 언덕에 있는 대지모신의 안식처에서 별의 예언자 나로와 대화해야 합니다.",
        ["D"] =
        "하늘의 저 빛을 보았는가? 저것이 징조라네 -- 대지모신의 안식처 동굴이 마침내 열린 것이지. 별의 예언자 나로가 멀고어 [cite: 20]와 불모의 땅 [cite: 29] 경계에 있는 썬더 블러프 [cite: 30] 북동쪽 언덕에서 그곳을 지키고 있다네. 예언에 따르면 오직 이방인만이 별의 예언자가 대지모신 자녀들의 쌍둥이 심장을 되찾는 것을 도울 수 있다고 하더군. 우리를 돕고 싶다면 지금이 바로 그 때야. 붉은 바위 언덕 [cite: 23] 북쪽 절벽을 따라 올라가면 별의 예언자에게 닿는 길을 찾을 수 있을 걸세.",
    },
    [27900] = {
        ["T"] = "대지모신의 은혜",
        ["O"] = "대지모신의 안식처 동굴에서 안쉬의 심장과 무샤의 심장을 되찾아 별의 예언자 나로에게 가져가야 합니다.",
        ["D"] =
        "타우렌과 드워프, 성과 마을이 생기기도 수겁 년 전, 대지모신이 이 땅을 거닐었소. 그녀의 숨결이 바람을 일으키고, 그녀의 웃음이 꽃을 피웠지. 그리고 그녀가 자신의 창조물들을 지키기 위해 기꺼이 희생 [cite: 24]했을 때, 우리는 그녀가 언젠가 수많은 형태로, 수차례에 걸쳐 우리 곁으로 돌아올 것임을 알았지. 그녀의 메시지는 별에 새겨져 있고, 바람에 실려 오며, 대지 깊은 곳에 묻혀 있다오.\n\n불타는 두 개의 달이 하늘을 가로지를 때 한 이방인이 우리를 찾아올 것이라는 예언이 있었고, 그렇게 당신이 온 거요. 당신의 임무는 아주 간단해. 언덕을 조금 내려가면 동굴이 하나 보일 거요. 그 안은 어둠의 정령들이 우글거리고 있지. 녀석들을 물리치고 대지모신이 남긴 두 가지 보물 -- 그녀 아이들의 쌍둥이 심장을 되찾아오시오. 내게 가져오면 그것들을 어떻게 사용해야 할지 알려주겠소.",
    },
    [27901] = {
        ["T"] = "대지모신의 은혜",
        ["O"] =
        "불모의 땅 [cite: 29]에 있는 대지모신의 제단에서 태양 빛으로 안쉬의 심장을 충전 [cite: 5]하고, 돌발톱 산맥 [cite: 28]에 있는 대지모신의 제단에서 달빛으로 무샤의 심장을 충전 [cite: 5]해야 합니다.",
        ["D"] =
        "대지모신은 어둠의 속삭임 [cite: 7]에 타락한 창조물들을 보고 눈물을 흘렸고, 그 눈물은 푸른 아이 -- 로쇼가 되었지. 대지모신이 세상을 창조하기 위해 자신의 몸을 바쳤을 때, 그녀는 두 방울의 눈물을 더 흘렸는데 -- 그것이 바로 당신이 지금 쥐고 있는 돌이라오.\n\n그것을 제대로 사용하려면, 어머니에게 신성한 장소에서 그녀의 아이들의 빛으로 심장을 충전 [cite: 5]해야 해.\n\n진흙수렁 바로 남동쪽 산꼭대기에 있는 제단으로 안쉬의 심장을 가져가시오. 화창한 한낮에 제단 위에 그것을 올려두어 안쉬의 힘을 흡수 [cite: 1]하게 하시오.\n\n마찬가지로 무샤의 심장도 해바위 야영지 [cite: 28] 북쪽 언덕에 있는 돌발톱 굴 근처의 제단으로 가져가야 하오. 밤이 되면 그곳에 그것을 두어 무샤의 힘을 흡수 [cite: 1]하게 하시오.\n\n이 모든 일이 끝나야만 내게 돌아올 수 있소.",
    },
    [27902] = {
        ["T"] = "대지모신의 은혜",
        ["O"] = "쌍둥이 심장의 힘을 사용하여 대지모신의 뼈를 정화 [cite: 5]해야 합니다.",
        ["D"] =
        "이제 당신은 대지모신의 쌍둥이 자녀인 안쉬와 무샤의 강화 [cite: 9]된 심장을 손에 넣었소. 이 힘으로 당신은 오랫동안 남아있던 악의 기운을 무찌를 수 있을 거요.\n\n내 천막에서 남쪽 절벽을 따라 땅에서 솟아오른 커다란 바위 [cite: 23] 쪽으로 가보시오. 그것들은 대지모신의 뼈이며, 어둠의 정령이 그곳에 숨어 타격할 시기를 기다리고 있다오. 녀석은 힘을 완전히 되찾기 전까진 모습을 드러낼 수 없었지만 -- 이제 그 시기가 임박했소. 하지만 쌍둥이 심장을 사용하면 녀석을 물리칠 수 있을 거요.\n\n안쉬의 심장은 아이들에게 베풀었던 대지모신의 사랑으로 당신을 강화 [cite: 9]시켜 체력 [cite: 27]을 증가시켜 줄 거요. 무샤의 심장은 적을 약화시켜 당신의 공격에 더 취약하게 만들어 줄 테고.\n\n당신이 이 임무를 완수한다면 대지모신의 모든 자녀들에게서 영원한 존경을 받게 될 거요.",
    },
    [27903] = {
        ["T"] = "대지모신의 은혜",
        ["O"] = "다르나서스 [cite: 7] 달의 신전에 있는 역사학자 디미트레스쿠와 대화해야 합니다.",
        ["D"] =
        "당신의 노력으로 대지모신의 축복을 청할 수 있는 권리를 얻었소. 당신의 종족 중에도 그녀의 힘을 끌어내는 방법을 아는 자가 몇몇 있다고 믿소. 더 자세히 알고 싶다면 다르나서스 [cite: 7]에 있는 역사학자 디미트레스쿠와 대화해보시오.\n\n안녕히 가시오, $N. 평화로운 모험가를 만나게 되어 기뻤소.",
    },
    [27904] = {
        ["T"] = "대지모신의 은혜",
        ["O"] = "썬더 블러프 [cite: 30] 수렵의 봉우리 [cite: 14]에 있는 용사 사이크와 대화해야 합니다.",
        ["D"] =
        "당신의 노력으로 대지모신의 축복을 청할 수 있는 권리를 얻었소. 더 자세히 알고 싶다면 썬더 블러프 [cite: 30] 수렵의 봉우리 [cite: 14]에 있는 용사 사이크와 대화해보시오.\n\n안녕히 가시오, $N. 평화롭게 가시길.",
    },
    [27905] = {
        ["T"] = "피와 명예 [cite: 20]로 맺어진",
        ["O"] = "먼지진흙 습지대 [cite: 8] 테라모어 섬 [cite: 30]에 있는 여군주 제이나 프라우드무어 [cite: 16]에게 오크에 대한 정보를 물어봐야 합니다.",
        ["D"] =
        "당신이 오크에 대해 좀 더 알고 싶어 한다는 소문을 들었습니다. 그런 바람을 누구에게 털어놓을지는 조심하는 게 좋을 겁니다 -- 전쟁에서 있었던 일을 모두가 용서 [cite: 11]한 건 아니니까요.\n\n편견 없이 오크를 대하고 싶다면, 제가 믿을 수 있는 분은 딱 한 명뿐입니다 -- 여군주 제이나 프라우드무어 [cite: 16] 님이죠.\n\n그분은 먼지진흙 습지대 [cite: 8] 테라모어 섬 [cite: 30]의 지배자이시며, 얼라이언스 내에서 오크들의 가장 친한 친구라고 할 수 있는 유일한 분입니다.",
    },
    [27906] = {
        ["T"] = "피와 명예 [cite: 20]로 맺어진",
        ["O"] = "오그리마 [cite: 21] 스랄의 방에 있는 나즈그렐 [cite: 20]과 대화하여 오크에 대해 배우고 싶다는 관심을 표해야 합니다.",
        ["D"] =
        "자네가 우리의 동맹인 오크에 대해 더 알고 싶어 한다는 소문을 들었네. 그게 사실이라면 나즈그렐 [cite: 20]과 대화해 보게. 오그리마 [cite: 21] 스랄의 방에서 그를 찾을 수 있을 거야.",
    },
    [27907] = {
        ["T"] = "피와 명예 [cite: 20]로 맺어진",
        ["O"] = "슬픔의 늪 [cite: 28]으로 이동하여 당신과 대화해 줄 오크를 찾아보세요.",
        ["D"] =
        "얼라이언스와 호드 간의 적대감을 식히는 것이 저의 오랜 소원 중 하나였습니다. 당신이 자발적으로 오크를 이해하려 노력한다는 것은 시대가 변하고 있다는 긍정적인 신호군요.\n\n불행히도 진짜 오크에 비하면 저는 형편없는 스승일 수밖에 없습니다. 상황이 이렇게 된 것에 대한 제 씁쓸함이 아직 너무 생생하거든요. 하지만 네더가드 요새 [cite: 20] 근처 슬픔의 늪 [cite: 28]에 얼라이언스에게 다소 우호적이라는 오크 야영지가 있다는 소문을 들었습니다. 그곳으로 가서 오크의 명예 [cite: 28] 개념에 대해 말해줄 사람이 있는지 찾아보세요. 그곳이 시작하기엔 가장 좋은 장소일 겁니다.",
    },
    [27908] = {
        ["T"] = "피와 명예 [cite: 20]로 맺어진",
        ["O"] = "슬픔의 늪 [cite: 28]으로 이동하여 저주받은 땅 [cite: 3]으로 가는 길에 있는 호드의 넋을 찾아야 합니다.",
        ["D"] =
        "우리 동족처럼 생각하고 싸우는 것은 단순히 도끼를 이리저리 휘두르는 문제가 아니네. 자네는 모든 것에서 명예 [cite: 28]를 받아들여야 해. 이 개념을 가르쳐 줄 최고의 스승을 알고 있지.\n\n슬픔의 늪 [cite: 28]에서 명예 [cite: 28]롭게 살다가 죽은 자의 영혼을 찾을 수 있을 거야. 저주받은 땅 [cite: 3]으로 가는 길에서 그를 찾아 당신의 교육을 시작하게나.",
    },
    [27909] = {
        ["T"] = "피와 명예 [cite: 20]로 맺어진",
        ["O"] = "깊은굴 지하철 [cite: 7]의 일꾼 기념비로 이동하여 의식용 향을 사용하여 조상에게 예를 표해야 합니다.",
        ["D"] =
        "우리 동족에 대해 더 알고 싶다? 뭐, 내가 훌륭한 스승이기도 하고, 다른 누구보다 기꺼이 가르쳐 줄 마음이 있긴 하지. 어차피 난 어디 도망갈 데도 없으니까.\n\n진정 우리 동족을 이해하고 싶다면, 명예 [cite: 28]가 모든 말과 행동, 행위의 근간이라는 사실을 아는 것부터 시작해야 하네. 우리 부족들은 명예로운 행동의 긴 역사로 묶여 있지. 우리는 우리의 행동이 단지 우리 자신만의 것이 아님을 이해한다네.\n\n자네가 타인을 어떻게 존중하는지 내게 보여주게. 자네 조상들의 안식처에서 이 의식용 향을 피운 후 내게 돌아오게나.",
    },
