        ["O"] = "멀고어 [cite: 20] 붉은 바위 언덕 [cite: 23]에 있는 묘지로 이동하여 의식용 향을 사용하여 조상에게 예를 표해야 합니다.",
        ["D"] =
        "우리 동족에 대해 더 알고 싶다? 뭐, 내가 훌륭한 스승이기도 하고, 다른 누구보다 기꺼이 가르쳐 줄 마음이 있긴 하지. 어차피 난 어디 도망갈 데도 없으니까.\n\n진정 우리 동족을 이해하고 싶다면, 명예 [cite: 28]가 모든 말과 행동, 행위의 근간이라는 사실을 아는 것부터 시작해야 하네. 우리 부족들은 명예로운 행동의 긴 역사로 묶여 있지. 우리는 우리의 행동이 단지 우리 자신만의 것이 아님을 이해한다네.\n\n자네가 타인을 어떻게 존중하는지 내게 보여주게. 자네 조상들의 안식처에서 이 의식용 향을 피운 후 내게 돌아오게나.",
    },
    [27915] = {
        ["T"] = "피와 명예 [cite: 20]로 맺어진",
        ["O"] = "브릴 [cite: 4] 근처 묘지에 있는 분수로 이동하여 의식용 향을 사용하여 조상에게 예를 표해야 합니다.",
        ["D"] =
        "우리 동족에 대해 더 알고 싶다? 뭐, 내가 훌륭한 스승이기도 하고, 다른 누구보다 기꺼이 가르쳐 줄 마음이 있긴 하지. 어차피 난 어디 도망갈 데도 없으니까.\n\n진정 우리 동족을 이해하고 싶다면, 명예 [cite: 28]가 모든 말과 행동, 행위의 근간이라는 사실을 아는 것부터 시작해야 하네. 우리 부족들은 명예로운 행동의 긴 역사로 묶여 있지. 우리는 우리의 행동이 단지 우리 자신만의 것이 아님을 이해한다네.\n\n자네가 타인을 어떻게 존중하는지 내게 보여주게. 자네 조상들의 안식처에서 이 의식용 향을 피운 후 내게 돌아오게나.",
    },
    [27916] = {
        ["T"] = "피와 명예 [cite: 20]로 맺어진",
        ["O"] =
        "/결투를 사용하여 저주받은 땅 [cite: 3]에 있는 마즈로어[Mazroar]에게 막고라를 선포하고, 명예로운 결투에서 그를 쓰러뜨려야 합니다. 이 도전 [cite: 2]에서 반드시 살아남아야 합니다.",
        ["D"] =
        "명예로운 결투에 대해 평생 얘기할 수도 있지만, 자네의 기본적인 이해를 돕기 위해 간단히 설명하지.\n\n우리 동족은 명예 [cite: 28]를 버리고 군단에 합류하여 그 힘의 노예가 되었었지. 타락하기 전, 우리는 막고라라는 명예로운 결투를 통해 지도권 분쟁을 해결하거나 다른 이의 권위에 도전 [cite: 2]하곤 했네. 저주받은 땅 [cite: 3], 어둠의 문 [cite: 29]이 내려다보이는 언덕에 마즈로어라는 악마가 있네. 녀석은 아제로스 [cite: 2]에 있는 군단 하수인들을 지배하는 하급 군주지만, 도전 [cite: 2]을 받아 쓰러져야 마땅한 자지.\n\n마즈로어에게 막고라를 선포하고 속임수 없이 명예 [cite: 28]롭게 그 녀석과 맞서게. 만약 지게 되더라도, 정당하게 패배를 받아들이게나. 이기게 된다면, 오롯이 자네의 힘만으로 이룩한 승리 [cite: 32]가 될 걸세. 행운을 비네, 모험가.",
    },
    [27917] = {
        ["T"] = "피와 명예 [cite: 20]로 맺어진",
        ["O"] = "테라모어 섬 [cite: 30]의 여군주 제이나 프라우드무어 [cite: 16]에게 돌아가 그동안 배운 것을 이야기해야 합니다.",
        ["D"] =
        "이제 우리 동족에 대해 더 깊이 이해하게 되었을 거라 믿네, $R. 아직 자네를 친구라 부를 순 없겠지만, 전투에서 오크와 맞서게 된다면 그것이 명예로운 도전 [cite: 2]이 될 것임을 명심하게. 자네가 최선을 다해 임할 가치가 있는 도전 [cite: 2] 말일세.\n\n자네를 내게 보낸 자에게 돌아가 이곳에서 배운 것을 전해주게. 잘 가시게!",
