        ["O"] = "아이언포지 [cite: 15]에서 기록관 던김을 찾아야 합니다.",
        ["D"] =
        "이제 오크의 명예 [cite: 28]에 대해 더 잘 이해하게 되었으니, 그 원칙들을 전투의 지침으로 삼을 수 있을 것이네. 그 원칙들을 더 깊이 수용하고 싶다면, 아이언포지 [cite: 15]의 기록관 던김을 찾아가 보게. 행운을 비네, $C.",
    },
    [27919] = {
        ["T"] = "피와 명예 [cite: 20]로 맺어진",
        ["O"] = "오그리마 [cite: 21] 스랄의 방에 있는 나즈그렐 [cite: 20]에게 돌아가야 합니다.",
        ["D"] =
        "이제 우리 동족에 대해 더 깊이 이해하게 되었을 거라 믿네, $R. 우린 이미 동맹이지만, 전투에서 오크와 함께 싸운다면 그것이 명예로운 싸움이 될 것임을 이제 알게 되었을 거네. 자네가 최선을 다할 가치가 있는 싸움 말일세.\n\n자네를 내게 보낸 자에게 돌아가 이곳에서 배운 것을 전해주게. 잘 가시게!",
