        ["D"] =
        "이제 오크의 명예 [cite: 28]에 대해 더 잘 이해하게 되었으니, 그 원칙들을 전투의 지침으로 삼을 수 있을 것이네. 그 원칙들을 더 깊이 수용하고 싶다면, 오그리마 [cite: 21]의 제왕 조크를 찾아가 보게. 행운을 비네, $C.",
    },
    [27921] = {
        ["T"] = "아포니의 부탁",
        ["O"] = "썬더 블러프 [cite: 30] 장로의 봉우리 [cite: 8]에 있는 아포니 브라이트메인 [cite: 1]과 대화해야 합니다.",
        ["D"] =
        "$N, 아포니 브라이트메인 [cite: 1]이 자네에게 부탁을 해왔네.\n\n그녀가 썬더 블러프 [cite: 30]의 원로 드루이드들을 대신하여 도움을 요청했네. 나도 이 문제에 대해선 더 할 말이 별로 없지만, 다른 무엇보다도 나이트 엘프들이 언급되었어.\n\n이 일엔 보안 유지가 아주 중요하다고 전해 달라는군. 썬더 블러프 [cite: 30]의 장로의 봉우리 [cite: 8]에서 그녀를 찾아보게.",
    },
    [27922] = {
        ["T"] = "불길한 소문",
        ["O"] = "돌발톱 산맥 [cite: 28] 땅거미 호수 [cite: 20] 주변 지역을 조사해야 합니다.",
        ["D"] =
        "제 부름에 응해 주셔서 감사합니다, $N. 돌발톱 산맥 [cite: 28]에서 공격이 있었다는 소식이 전해졌는데, 최악의 상황이 우려됩니다. 당신의 실력이 아주 뛰어나다고 들었습니다.\n\n우리 역사의 신성한 일부가 도난당했을지도 모릅니다 -- 이렇게 말하지만 나이트 엘프를 포함한 모든 드루이드의 역사이기도 하죠. 달의 은혜, 즉 무샤의 축복을 받은 생명의 분수가 공격받았습니다. 그곳은 호수 근처 아헵와 야영지 끝자락의 동굴 안에 있습니다. 이 봉우리의 장로들은 그곳이 우리 최고 용사 [cite: 4]들의 호위를 받아 안전하다고 믿었었죠.\n\n<아포니가 산장 입구를 매섭게 노려보며 밖의 그림토템 무리를 경계하듯 쳐다보곤 말을 멈춥니다.>\n\n전... 아니, 소문에 생명력을 불어넣지는 않겠습니다. 제발, 돌발톱 산맥 [cite: 28] 심장부에 있는 땅거미 호수 [cite: 20] 북동쪽 지역으로 가주세요. 무슨 일이 일어났는지, 왜 일어났는지 알아내야만 합니다!",
    },
    [27923] = {
        ["T"] = "그림토템의 배신",
        ["O"] = "그림토템 약탈자 8마리를 처치하고 사나 [cite: 24] 다크클라우드를 처치해야 합니다.",
        ["D"] =
        "<소문이 사실이었던 것 같습니다. 정착지가 그림토템 부족의 손에 넘어가고 있습니다.>\n\n<이 배신자 녀석들은 그들의 범죄에 대한 대가를 치러야 합니다. 아마도 생존자를 찾을 수 있고 왜 그들이 이곳을 약탈했는지 이유를 알 수 있을지도 모릅니다.>",
    },
    [27924] = {
        ["T"] = "소생과 휴식",
        ["O"] = "치유의 물 단지를 찾아 로라스린 파보우에게 가져가야 합니다.",
        ["D"] =
        "안 돼, 무기를 거두시오! 난 비-비무장 상태요, $R.\n\n<나이트 엘프가 겁에 질린 표정을 짓습니다. 머리의 심각한 상처에서 동굴 바닥으로 피가 스며 나옵니다.>\n\n왜... 내가 왜 여기에..? 분수가... 나... 제발...!\n\n<이 엘프는 곧 기절할 것 같습니다. 아포니가 이곳의 물에 치유 효과가 있다고 말했으니 근처에 물 단지가 있을지도 모릅니다. 엘프가 혼미한 상태에서 벗어나면 아마 더 많은 이야기를 들을 수 있을 것입니다.>",
    },
    [27925] = {
        ["T"] = "아포니에게 돌아가기",
        ["O"] = "썬더 블러프 [cite: 30] 장로의 봉우리 [cite: 8]에 있는 아포니 브라이트메인 [cite: 1]에게 돌아가 알아낸 사실을 알려야 합니다.",
        ["D"] =
        "<나이트 엘프가 눈을 천천히 깜빡이며 주변을 살핍니다. 그의 시선은 여기저기 맴돌다가 늘 당신에게로 돌아옵니다.>\n\n우리... 우린 타우렌과 함께 이 분수를 연구하려고 이곳에 초대받았소. 처음엔 주저했지만... 세나리우스의 가르침을 공유하는 자로서 큰 호기심을 품고 오게 되었지. 놀랍진 않지만, 이렇게 화해의 손길이 피로 물든 걸 보니 안타깝군.\n\n내 말이 별로 설득력은 없겠지만 자네 호드에 대한 어떤 음모도 없었어. 자네들의 정치 문제에 개입하진 않겠어; 난 그저 북쪽으로 돌아가고 싶을 뿐이오.\n\n<그는 당신의 무기를 잠시 쳐다보더니 잠시 눈을 감습니다.>\n\n내 목숨을 구해줘서 고맙군. 우리 평화롭게 갈 길 가는 게 어떻겠소?",
    },
    [27926] = {
        ["T"] = "달의 은총 [cite: 12]",
        ["O"] = "썬더 블러프 [cite: 30]에서 용사 사이크와 대화해야 합니다.",
        ["D"] =
        "<엘프가 당신의 얼굴을 살피더니 부드럽게 헛기침을 합니다.>\n\n그 물. 당신... 당신은 선물을 받았소, $R...!\n\n<엘프는 불안함과 당혹감이 뒤섞인 표정으로 잠시 말을 멈춥니다.>\n\n...그리고 당신이 처음 받은 게 아니지. 또 다른 이가 이 분수에서 치유되었소, 한 타우렌이 당신과 같은 기운에 둘러싸여 있었지. 우리는 그걸 여신의 은총 [cite: 12]이라 부르게 되었소... 그리고 그녀의 뜻을 따르는 자로서 우린 그 타우렌에게 우리의 가르침을 전수했지.\n\n그건 통달하기 아주 어려운 길임에는 틀림없소. 하지만 여신께서 당신에게 어떤 믿음을 가지고 계신 것 같군. 내가 더 이상 함부로 해석할 문제는 아니오.\n\n썬더 블러프 [cite: 30]의 용사 사이크를 찾아가 보시오. 어쩌면 그 힘을 이용하는 방법을 배울 수 있을지도 모르지.",
    },
    [27927] = {
        ["T"] = "명예 [cite: 28]와 피의 기억",
        ["O"] = "아이트리그 [cite: 9]에게 인간에 대해 더 알고 싶다고 말해야 합니다.",
        ["D"] =
        "자네가 우리 호드의 주적인 인간에 대해 더 알아보고 싶어 한다는 소문을 들었네. 우리 종족과 놈들 사이의 긴장감이 여전히 고조된 상황에서, 적을 아는 것은 지혜 [cite: 34]로운 선택인 듯하군.\n\n호드의 많은 구성원들이 전쟁에서 인간들과 싸웠지만, 아무도 스랄과 아이트리그 [cite: 9]만큼 그들의 속내를 잘 알지는 못할 거네. 스랄은 요즘 매우 바쁘지만 아이트리그 [cite: 9]라면 면담을 허락해 줄지도 몰라. 오그리마 [cite: 21] 스랄의 방에서 그를 찾아보게.",
    },
    [27928] = {
        ["T"] = "명예 [cite: 28]와 피의 기억",
        ["O"] =
        "불타는 평원 [cite: 4]으로 여행을 떠나 로서를 기리며 주변 검은바위 소속의 보병, 학살자, 마술사를 처치해야 합니다.",
        ["D"] =
        "나는 1, 2차 대전쟁에서 인간들과 맞서 싸웠지, $C. 그들은 만만치 않은 적이었어. 오그림 둠해머 [cite: 21]가 안두인 로서를 쓰러뜨렸을 때 얼라이언스가 자신들의 지도자가 죽었음에도 다시 뭉쳐 싸우는 걸 보았네. 놀랍게도 그 모습엔 묘한 명예로움이 깃들어 있었지.\n\n얼라이언스는 불타는 평원 [cite: 4]에 로서의 동상을 세웠지만, 아직도 군단에 충성하는 검은바위 오크들이 그 지역을 더럽히고 있네. 로서의 용기에 경의를 표하고 우리의 방어를 굳건히 할 겸, 그들의 수를 좀 줄여 주게나.",
    },
    [27929] = {
        ["T"] = "명예 [cite: 28]와 피의 기억",
        ["O"] = "던홀드 요새 [cite: 8]로 가서 교수대를 찾아야 합니다. 도전의 뿔피리를 불어 에델라스 블랙무어의 유령을 소환하고 처치해야 합니다.",
        ["D"] =
        "호드가 얼라이언스에게 패배한 후, 나는 포로로 잡힐 때까지 황야를 떠돌았네. 나는 인간들에게 잠시 동안만 붙잡혀 있었지만 스랄과 많은 오크들은 수년간 던홀드 요새 [cite: 8]에 수감되어 있었지.\n\n에델라스 블랙무어가 운영하던 수용소의 오크 학대는 끔찍했네. 그것은 인간 본성의 가장 추악한 면과 자신들의 타락을 보지 못하는 맹목을 보여주었어. 죽는 순간까지 스랄을 포획한 자는 자신의 잘못을 깨닫지 못했지.\n\n블랙무어는 오래전에 죽었고 그의 시체는 요새의 잔해 속에 묻혔네. 그 위에 새로운 수용소가 세워졌지. 이 도전의 뿔피리를 가져가서 복원된 교수대 근처에서 부르게나. 그러면 블랙무어의 유령이 나타날 테니 정의 [cite: 16]의 심판을 나눠 주게나.",
    },
    [27930] = {
        ["T"] = "명예 [cite: 28]와 피의 기억",
        ["O"] = "오그리마 [cite: 21] 투기장의 제왕 조크를 찾아야 합니다.",
        ["D"] =
        "자네의 여행이 인간의 선한 면과 악한 면 모두를 비춰주었기를 바라네. 인간들에게 한 걸음 더 다가가고 싶다면 오그리마 [cite: 21]에 있는 제왕 조크와 이야기해 보게.",
    },
    [27931] = {
        ["T"] = "파이어브루의 맥주",
        ["O"] = "아이언포지 [cite: 15] 구 시가지 [cite: 21]에 있는 록파이어 여관의 여관주인 파이어브루 [cite: 14]와 대화해야 합니다.",
        ["D"] =
        "$C, 아이언포지 [cite: 15] 록파이어 여관에 있는 여관주인 파이어브루 [cite: 14]가 아주 특별한 맥주를 만드는 데 자네의 도움이 필요하대!\n\n평범한 드워프들처럼 가슴에 털이 나고 훨씬 튼튼하게 만들어줄 거라고 하더군.\n\n관심이 있다면, 아이언포지 [cite: 15] 평민 구역에 있는 록파이어 여관으로 가보게.",
    },
    [27932] = {
        ["T"] = "최고급 시음",
        ["O"] =
        "그웨나 파이어브루 [cite: 13], 트루크 와일드비어드 [cite: 31], 그리고 감시대장 롤로 롱스트라이커 [cite: 17]와 대화하여 그들의 맥주를 시음해야 합니다.",
        ["D"] =
        "좋아, $C. 내가 좀 건방지게 들리더라도 용서하게나. 자네 아직 진짜 드워프 명품 맥주 맛은 제대로 못 본 것 같군그래. 내가 구상 중인 맥주 맛을 제대로 음미하려면 목부터 좀 축여야지!\n\n우리 드워프들이 꼬맹이 때부터 끝내주는 흑맥주로 젖을 뗀다는 건 세상이 다 아는 사실 아니겠나! 다른 종족들이 쌓아 올린 내성 따위는 우리한테 명함도 못 내밀지. 내 맥주로 자넬 골로 보내긴 싫으니, 이건 필수 과정이라 생각하게!\n\n최고의 맛을 보여줄 친구들 목록을 적어뒀어. 우선 여기 여관에 있는 내 예쁜 산골 아가씨 그웨나와 이야기해 보게... 내가 만든 라거를 내어줄 테니.\n\n그다음에 어디로 갈지는 자네 마음이지만, 동부 내륙지 [cite: 29] 맹금의 봉우리 [cite: 1]에 있는 트루크 와일드비어드 [cite: 31]와 이글거리는 협곡 [cite: 25] 토륨 거점 [cite: 30]에 있는 감시대장 롤로 롱스트라이커 [cite: 17]를 찾아가게. 그 두 사람이라면 끝내주는 맥주를 만들어 줄 테니 말이야!\n\n건배, $N!",
    },
    [27933] = {
        ["T"] = "지하 도시의 연금술",
        ["O"] =
        "서부 역병지대 [cite: 34]의 농장 밭에서 역병초 [cite: 21] 30개를 채집해야 합니다. 역병지대 [cite: 21]에 있는 스컬지 가마솥 아무 곳에서 파이어브루의 유리병을 채워야 합니다.",
        ["D"] =
        "자, 우리가 만들려는 이 맥주는 그냥 마시고 즐기기 위한 게 아니야. 얼라이언스의 동맹들에게 아주 실용적인 용도로 쓰일 거거든. 알다시피 내가 애국심이 좀 투철해서 말이야.\n\n독이나 질병 [cite: 1] 같은 것들로부터 친구들을 안전하게 지켜주고 싶어... 사실 양조 기술이나 연금술 [cite: 1]이나 별반 다를 게 없지.\n\n이건 우리끼리 비밀인데. 아제로스 [cite: 2]에서 가장 역겨운 재료가 좀 필요한데 역병지대 [cite: 21]보다 그걸 구하기 좋은 곳이 어디 있겠어? 그래 맞아. 제발 우리가 새로운 역병이라도 만들어내는 일이 없기만 바래야지!\n\n맛은 내가 책임질 테니! 자넨 저 위에 있는 밭에서 자라는 식물들을 좀 캐다 주면 돼. 아, 그리고 이 수정 유리병 [cite: 6]도 가져가 -- 온 땅에 흩어져 있는 무언가로 가득 찬 가마솥에 대해 들었거든... 오, 그 안에 끔찍한 게 들어있을 게 틀림없겠지?!\n\n그 식물들을 구하고 스컬지가 만든 용액으로 유리병을 채워오게. 그러면 우리 음료를 만들 수 있을 거야.",
    },
    [27934] = {
        ["T"] = "오싹하게 유지하기",
        ["O"] = "여명의 설원 [cite: 34] 북쪽에서 얼음 수정 5개를 수집해야 합니다.",
        ["D"] =
        "바다 [cite: 25] 건너 여명의 설원 [cite: 34]에 가본 적 있나, $N? 카즈 모단과는 비교도 안 되게 춥다더군...\n\n북쪽으로 갈수록 추위는 더 심해진다고 해. 북쪽 여명의 설원 [cite: 34] 바위 [cite: 23] 틈에서 피어나는 얼음 수정이 우리 음료에 들어가면 어떤 맛을 낼지 궁금하지 않나?\n\n내 생각엔 말이야: 차가운 음료는 출혈을 늦추는 데 도움이 될 테고, 가장 차가운 음료라면 완전히 멈추게 할 수도 있을 거라는 거지! 아니, 그곳에 방문하는 것만으로도 자네의 냉기 저항력이 올라갈지도 모를 일이고.\n\n어떤가, $N? 그 수정을 좀 캐다 주면 우리 음료가 톡 쏘게 될 때 슬쩍 넣어보자고.",
    },
    [27935] = {
        ["T"] = "미식가의 미각",
        ["O"] = "록파이어 여관에 있는 여관주인 파이어브루 [cite: 14] 옆의 통에서 효과가 느껴질 때까지 맥주를 마셔야 합니다.",
        ["D"] =
        "자네 완전 보물 사냥꾼이 다 됐군그래? 여기저기 뛰어다니며 이것저것 모아오고... 꼭 전에도 해본 사람처럼 말이야!\n\n맥주 준비는 이제 거의 다 끝났어. 이거 보이나? 이건 내 노움 친구한테 받은 '초고속 발효 촉매제'야... 효과가 있는지 한 번 보자고.\n\n<여관주인 파이어브루가 거품이 이는 액체를 맥주통에 붓고 격렬하게 흔듭니다. 통이 삐걱거리고 꾸르륵거리더니 이내 잠잠해집니다.>\n\n자, 이제 남은 건 한 번 맛보는 일뿐이군! 쭉 들이켜, $C! 널 위해 준비한 거니까.",
    },
    [27936] = {
        ["T"] = "항상 재고 있음",
        ["O"] = "아이언포지 [cite: 15]의 기록관 던김과 대화해야 합니다.",
        ["D"] =
        "우리의 여정이 벌써 끝났다니 믿기지 않는군, $N... 자네와 일해서 정말 즐거웠네!\n\n이제 이 맥주를 최대한 많이 만들어내기 시작해야겠지만, 자네가 필요할 때마다 언제든 마실 수 있게 준비해 두겠네. 더 필요하면 언제든 기록관 던김을 찾아가게나!\n\n내가 이 말을 좀 늦게 하긴 했지만, 축하하네 $N -- 내 기준엔 자네도 명예로운 드워프야! 내 난롯가엔 언제든 환영이니 낯설어하지 말고 언제든 찾아오게나.",
    },
    [27937] = {
        ["T"] = "보안의 슬픔",
        ["O"] = "슬픔의 늪 [cite: 28] 북동쪽 끝에 있는 외딴 연구실 근처의 위기 매글리저와 대화해야 합니다.",
        ["D"] =
        "유명한 고블린 과학자가 당신의 도움을 필요로 합니다, $C. 그녀는 슬픔의 늪 [cite: 28]에 있는 자신의 연구실을 털어가는 도둑들을 막아내느라 고군분투하고 있으며, 몇 가지 새로운 방어 수단을 시험해 줄 사람을 찾고 있습니다.\n\n조금 과장되게 들리겠지만, 당신이 이 일에 참여한다면 마음을 갈고닦아 어떤 상황에서도 탈출 [cite: 9]할 수 있는 능력을 얻게 될 것입니다 –- 노움처럼 말이죠.\n\n진지하게 임할 모험가만 모집한다고 하네요. 관심 있으신가요?",
    },
    [27938] = {
        ["T"] = "고행의 길",
        ["O"] = "북쪽 절벽 길에 있는 위기 매글리저의 장애물을 통과한 후, 그녀의 연구실에서 그녀와 대화해야 합니다.",
        ["D"] =
        "도둑들이 날 찾지 못하게 이쪽으로 이사 왔지. \"이 우중충한 진흙탕 쓰레기통까지 올 사람은 없을 거야!\"라고 생각했는데. 정착한 지 몇 달밖에 안 됐는데 벌써 메뚜기 떼처럼 몰려들고 있잖아!\n\n일단 연구실을 지킬 방법부터 생각하느라 하던 연구를 몽땅 중단했어! 내 새로운 방어벽들을 시험해 보고 싶군.\n\n해볼 텐가? 네가 하는 걸 지켜보면서 메모해 둘 테니… 감시받는다고 긴장해서 실수나 하지 말라고, 친구.\n\n보수는 섭섭지 않게 주지, 게다가 덤으로 새로운 걸 배울 수도 있을 거야. 준비가 되면 북쪽 길로 올라가 -- 하지만 서둘러야 할걸! 시간 재고 있을 테니까. 행운을 빌어, 행여나 죽더라도 귀신이 되어 날 찾아오진 마.",
    },
    [27939] = {
        ["T"] = "지능 [cite: 15]의 척도",
        ["O"] = "언더시티 [cite: 31] 왕실 [cite: 24]에 있는 롤랜드 스티프스트라이크와 대화해야 합니다.",
        ["D"] =
        "끝났군! 넌 정말 착하고 도움도 많이 됐어. 너무 아프진 않았길 바라.\n\n언제든 다시 시도하러 와, $N. 하지만 내 물건을 훔치진 마, 알았지?\n\n내 동료인 언더시티 [cite: 31]의 롤랜드 스티프스트라이크에게 내가 쓴 노트를 정리해서 보낼게. 넌 언제든 그걸 볼 수 있어... 마음을 수련하라는 둥 뭐 그런 헛소리들.\n\n이제 가봐. 난 일해야 해!",
    },
    [27940] = {
        ["T"] = "지능 [cite: 15]의 척도",
        ["O"] = "스톰윈드 [cite: 28] 왕립 도서관에 있는 기록관 로이와 대화해야 합니다.",
        ["D"] =
        "끝났군! 넌 정말 착하고 도움도 많이 됐어. 너무 아프진 않았길 바라.\n\n언제든 다시 시도하러 와, $N. 하지만 내 물건을 훔치진 마, 알았지?\n\n내 동료인 스톰윈드 [cite: 28]의 기록관 로이에게 내가 쓴 노트를 정리해서 보낼게. 넌 언제든 그걸 볼 수 있어... 마음을 수련하라는 둥 뭐 그런 헛소리들.\n\n이제 가봐. 난 일해야 해!",
    },
    [27941] = {
        ["T"] = "게로 만든",
        ["O"] = "타나리스 [cite: 28] 안제와타 남서쪽 끝자락 해안 [cite: 16]의 트준코와 대화해야 합니다.",
        ["D"] =
        "반갑습니다, $C. 트준코라는 트롤 주술사가 당신처럼 노련한 모험가를 찾고 있습니다. 드워프의 능력을 모방할 방법을 고안하는 데 도움을 줄 사람을 말이죠.\n\n그들이 스스로 질병을 씻어내는 능력에 관한 일입니다. 이 주술사는 안제와타 남서쪽 끝자락 해안 [cite: 16]에 있는 타나리스 [cite: 28] 남부의 독특한 바실리스크 종을 연구 중입니다.\n\n평소 같으면 이런 기이한 요청은 피하겠지만... 트준코는 호드에서 꽤 평판이 좋은 자입니다.",
    },
    [27942] = {
        ["T"] = "보는 돌",
        ["O"] = "북쪽 동굴의 쿠자즈라 크롤러들에게서 쿠자즈라의 눈 20개를 수집해야 합니다.",
        ["D"] =
        "이곳 바실리스크가 드워프랑 능력이 닮았다는 게 놀랍구먼. 반짝이는 걸 감지 [cite: 7]하는 예리한 눈, 비슷한 내성...\n\n트준코는 눈을 원해, 반짝반짝 빛나는 걸로. 너무 오래 쳐다보지 않게 조심해라, 형제... 눈을 떼지 못하게 될 테니까!\n\n반짝이는 눈이 우리가 찾는 물건이지. 괜찮다면 좀 가져다주게.",
    },
    [27943] = {
        ["T"] = "식혀라",
        ["O"] = "북쪽 동굴의 쿠자즈라 크롤러들 근처에 있는 얼어붙은 사냥감에게서 얼어붙은 조각 15개를 수집해야 합니다.",
        ["D"] =
        "타나리스 [cite: 28]는 덥다, 형제! 트준코에게는 너무 덥지... 하지만 넌 바실리스크가 널 도와주길 원치 않을 거다.\n\n바실리스크의 숨결에 당한 불쌍한 영혼들이 동굴에 널려 있지... 곧 보게 될 거야. 이런 곳에서 꽁꽁 얼어붙다니!\n\n네가 찾은 자들의 잔해가 필요하다. 놈들을 산산조각 내서 그 얼어붙은 조각들을 모아와 -- 경건하게 말이지.",
    },
    [27944] = {
        ["T"] = "저주 반사는 안 돼!",
        ["O"] = "교반기를 사용하여 북쪽 동굴의 쿠자즈라 크롤러들에게서 쿠자즈라 비늘 80개를 수집해야 합니다.",
        ["D"] =
        "트준코는 육체의 저주를 안다, 그리고 반대로 저주받는 일은 원치 않는다, 알겠지?\n\n바실리스크 비늘... 그게 우리 부적에 필요한 재료다. 정령들도 그리 말했고, 우린 복종해야 해. 트준코에게 막대가 하나 있는데, 비늘을 아주 쉽게 떼어낼 수 있는 거다...\n\n조심해라, 형제. 쿠자즈라는 네가 얕볼 상대가 아니야!",
    },
    [27945] = {
        ["T"] = "불굴의 신앙 [cite: 8]",
        ["O"] = "트준코에게 준비되었다고 말한 후, 트준코의 부적을 사용하여 트준코의 칼날을 버텨내야 합니다.",
        ["D"] =
        "좋아 형제, 마지막 시험이다...!\n\n드워프에 대해 아나? 서리, 출혈, 독, 질병 [cite: 1]에 내성이 있지... 게다가 피부도 아주 두꺼운데, 돌로 변했을 때만 그렇지.\n\n트준코가 칼을 하나 가지고 있는데... 톱니 모양 칼날에, 타나리스 [cite: 28] 전역의 시체에서 뽑아낸 병든 피로 만든 가장 치명적인 독이 발라져 있다.\n\n형제, 부적을 안 쓰면 넌 죽을 거다. 마지막에는 효과가 있을 거라고 정령들이 말했다. 베일 준비가 되면 트준코에게 말해라.",
    },
    [27946] = {
        ["T"] = "너 부두교에 빠졌구나",
        ["O"] = "오그리마 [cite: 21] 투기장의 제왕 조크와 대화해야 합니다.",
        ["D"] =
        "너랑 일해서 좋았다, $N.\n\n그 눈이 네게 보물을 보여주고 있구나…\n\n오그리마 [cite: 21]에 있는 제왕 조크를 찾아가라, 트준코는 이제 볼일 끝났다.",
    },
    [27947] = {
        ["T"] = "인간의 정신력 [cite: 29]",
        ["O"] = "스톰윈드 [cite: 28] 구 시가지 [cite: 21] 구역에 있는 SI:7 [cite: 32]의 단장 마티아스 쇼 [cite: 19]와 대화해야 합니다.",
        ["D"] =
        "다시 만났군요, $N. 당신이 치즈를 아주 좋아한다고 들었는데 -- 인간들처럼 말이죠.\n\n단장 마티아스 쇼 [cite: 19]가 특별한 임무를 맡아줄 인재를 찾고 있습니다. 치즈가 관련된 일이죠. 어쩌면 당신이 적임자 아닐까요?\n\n스톰윈드 [cite: 28]의 구 시가지 [cite: 21], SI:7 [cite: 32]에서 쇼 단장님을 찾을 수 있을 겁니다.",
    },
    [27948] = {
        ["T"] = "인간의 정신력 [cite: 29]",
        ["O"] =
        "스톰윈드 [cite: 28] 상업 지구 [cite: 31]에 있는 트리아스 치즈 상점의 엘링 트리아스 [cite: 9]에게 룬무늬 옷감 [cite: 24] 20장, 큰 비단 실타래 [cite: 14] 1개, 그리고 황금색 염료 1개를 가져가야 합니다.",
        ["D"] =
        "임무를 수락할 의향이 있다면 위장에 쓸 재료가 필요합니다. 룬무늬 옷감 [cite: 24], 실, 그리고 스톰윈드 [cite: 28] 귀족 특유의 금빛 염료 말이죠. 처음 두 개는 쉽게 구할 수 있겠지만, 염료는 아델버트 페리에게서 구해야 합니다. 페리는 스톰윈드 공원 [cite: 29]에 있는 재단사 상점을 은신처로 삼고 있는 데피아즈단 끄나풀이죠. 페리를 제거하고 염료를 차지하십시오... 절대 남의 눈에 띄어서는 안 됩니다.\n\n일이 끝나면 상업 지구 [cite: 31]에 있는 엘링 트리아스 [cite: 9]에게 재료를 가져가십시오.",
    },
    [27949] = {
        ["T"] = "인간의 정신력 [cite: 29]",
        ["O"] =
        "스톰윈디코 비토 치즈, 성난여울 강 블루 치즈, 그리고 치즈 오르코를 맛보십시오. 맛있는 테라모어 섬 [cite: 30] 레드 와인 한 병으로 입가심을 하세요. 그런 다음 스톰윈드 왕궁 [cite: 28]의 테사 엘레리안과 대화해야 합니다.",
        ["D"] =
        "귀족들의 신임을 얻으려면, 현재 인간들의 유행과 패션에 대해 자연스럽게 대화할 수 있어야 합니다.\n\n음식부터 시작하죠. 자네가 어떤 것을 좋아하는지 파악할 수 있도록 최고급 인간 치즈 목록을 준비했습니다. 치즈를 맛본 김에, 우리 최고의 와인도 곁들이는 게 좋겠군요. 마을 주변 상점들에서 이것들을 맛볼 수 있을 겁니다. 맛을 본 후엔, 테사 엘레리안과 이야기를 나눠보세요.\n\n그녀도 아주 오래전 궁정 예절을 배워야만 했으니까요.",
    },
    [27950] = {
        ["T"] = "인간의 정신력 [cite: 29]",
        ["O"] = "테사 엘레리안의 이야기를 들은 후, 상업 지구 [cite: 31]의 엘링 트리아스 [cite: 9]에게 돌아가야 합니다.",
        ["D"] =
        "엘링 트리아스 [cite: 9] 님이 절 찾아보라고 하셨나요? 그리고 데피아즈단 사건과 관련이 있다고요? 이게 정말 예절에 관한 일일지 의문이 드네요. 아마 당신이 왜 이 일을 하는지 제대로 이해하길 바라셨던 거겠죠.\n\n용서해 주세요. 길고 아직도 고통 [cite: 28]스러운 이야기입니다. 하지만 원하신다면 들려드리죠.",
    },
    [27951] = {
        ["T"] = "인간의 정신력 [cite: 29]",
        ["O"] =
        "화려한 스톰윈드 [cite: 28] 귀족 로브 [cite: 23]를 입고, 스톰윈드 왕궁 [cite: 28]의 왕실 갤러리에 있는 파딘 레스코바와 대화해야 합니다. 수단과 방법을 가리지 말고 그녀에게서 데피아즈단 명부를 확보해야 합니다.",
        ["D"] =
        "이제 파딘 레스코바 여군주와 만나야 합니다. 그녀의 아버지는 데피아즈단 동조자였고, 그녀는 데피아즈단 전 조직원 명부를 가지고 있죠. 그녀는 지금 데피아즈단의 목적을 돕는 데 관심이 있는 대표자와 만난다고 믿고 있습니다.\n\n당신의 정치적 식견과 세련된 취향으로 그녀를 감동시킨다면 평화롭게 명부를 넘겨줄 겁니다. 하지만 일이 틀어진다면, 수단과 방법을 가리지 말고 빼앗아야 합니다.",
    },
    [27952] = {
        ["T"] = "인간의 정신력 [cite: 29]",
        ["O"] = "스톰윈드 [cite: 28]의 기록관 로이를 찾아가야 합니다.",
        ["D"] =
        "이 정보는 왕국에 남은 마지막 데피아즈단 잔당들을 소탕하는 우리 작전에 귀중한 자산이 될 겁니다. 당신은 스톰윈드 [cite: 28]를 위해 큰 공을 세웠습니다, $N. 정말 감사합니다.\n\n언젠가 다시 인간의 정신을 되새기고 싶다면, 스톰윈드 [cite: 28]의 기록관 로이와 대화하십시오.",
    },
    [27953] = {
        ["T"] = "기술의 마법",
        ["O"] = "저습지 [cite: 34]의 연구실에 있는 웨일린 틴커스프링과 대화해야 합니다.",
        ["D"] =
        "반갑습니다, $C. 모단 호수 [cite: 17]에서 저습지 [cite: 34]로 향하는 길에 있는 던 알가즈 [cite: 8] 작업장 [cite: 34]에서, 한 노움 발명가가 장치 제작을 도와줄 분을 찾고 있습니다.\n\n그는 당신처럼 뛰어난 모험가를 필요로 하며, 보상으로 그 시제품 장치를 기꺼이 드리겠다고 합니다.\n\n제가 여기 적힌 바로는 나이트 엘프와 비슷한 능력 -- 은신, 민첩한 반사 신경, 그리고... 어, 지오스- 지오사인… 음, 흠. 이런 걸 얻게 될 거라고 하네요.\n\n정말 흥미로운 제안 같은데요. 이 임무를 수락하시겠습니까?",
    },
    [27954] = {
        ["T"] = "보이지 않는 자",
        ["O"] = "밤이 되면 아즈샤라 [cite: 2] 멘나르 호수 [cite: 16]에서 호수의 영혼으로부터 영혼의 찌꺼기를 수집해야 합니다.",
        ["D"] =
        "'투명화 [cite: 15]' 하면 뭐가 떠오르나? 도적? 아니면 뭔가... 터무니없는 마법사 주문?!\n\n내가 뭘 생각하는지 말해주지. 유령 [cite: 11]이야! 유령 [cite: 11]은 자기가 원할 때만 모습을 드러낸다는 사실, 알고 있었어? 어, 뭐 대부분은 말이지.\n\n아즈샤라 [cite: 2]에 있는 그런 유령 [cite: 11]에 대해 읽은 적이 있어 -- 슬픈 이야기지... 나중에 기회 되면 해줄게! 멘나르 호수 [cite: 16] 위를 맴돌고 있는 걸 볼 수 있는데, 햇빛이 없을 때만 나타나! 아주 중요해 -- 밤에만 찾을 수 있다고!\n\n그 유령 [cite: 11]을 물리치고 남은 영혼의 찌꺼기를 가져다줘. 분명 우리가 찾는 바로 그것일 테니까!",
    },
    [27955] = {
        ["T"] = "빠른 반사신경!",
        ["O"] = "운고로 분화구의 습지대에 서식하는 공포의 집게발 [cite: 22] 랩터에게서 두꺼운 심줄 12개를 가져와야 합니다.",
        ["D"] =
        "신체의 여러 관절에 장착해 착용자의 반사 신경을 강화하는 기계 소매를 만들었어. 네가 무슨 생각 하는지 알아... 이게 안전하긴 한 거냐고?\n\n아직은 모르지만, 곧 알게 되겠지! 걱정 마, 부러진 뼈나 관절쯤은 내가 다 고쳐줄 수 있으니까.\n\n<웨일린이 구부러진 손가락을 눈앞에서 흔들어 보입니다. 모양이 기형적임에도 불구하고 놀랍도록 민첩해 보입니다.>\n\n이제 필요한 건 공포의 집게발 [cite: 22] 랩터의 심줄이야. 운고로 분화구 습지대의 어느 동굴에서만 발견되는 희귀한 랩터 [cite: 22] 종이지. 이 짐승들은 찰나의 반응 속도로 유명하니까, 그런 생물이라면 튼튼하고 반사 신경이 뛰어난 심장을 가지고 있을 게 뻔하잖아!",
    },
    [27956] = {
        ["T"] = "정령 모방",
        ["O"] = "나후벤과 일라그나의 정령 핵을 회수해야 합니다.",
        ["D"] =
        "내 연구에 따르면, 나이트 엘프는 태양과 달의 주기에 따라 축복을 받는다고 해.\n\n불과 물의 정령도 서로 대립하며 비슷한 주기를 따른다는 글을 읽은 적이 있어! 그들의 핵은 강력하고 재생 가능한 부품이 될 뿐만 아니라, 장치의 효과를 조절하는 데도 큰 도움이 될 거야.\n\n불타는 평원 [cite: 4]에 강력한 불의 정령이 있다는 걸 알아... 아주 사나운 녀석이지. 검은바위 산 [cite: 3] 기슭의 용암 [cite: 16] 웅덩이에서 찾을 수 있을 거야. 그리고 또 보자... 가시덤불 골짜기 [cite: 28] 가라앉은 해안 [cite: 25] 앞바다 섬 주변을 맴도는 강력한 물의 정령도 하나 있었던 것 같아. 그 섬엔 물의 정령이 바글거리니까 놓칠 일은 없을 거야! 내가 이런 존재들을 어떻게 아느냐고? 책에서 읽었지!\n\n그 녀석들의 핵을 가져오면, 본격적인 조립을 시작할 수 있어.",
    },
    [27957] = {
        ["T"] = "조립의 시간",
        ["O"] = "저습지 [cite: 34]의 웨일린 틴커스프링 연구실 주변에서 노움 부품 5개를 회수해야 합니다.",
        ["D"] =
        "믿을 수가 없어, 거의 다 됐어 $N! 드디어 내 꿈이 실현되는구나...!\n\n너도 빨리 쓸만한 물건을 손에 쥐고 싶을 테니, 마무리 작업을 시작하자고! 내가 부품들을 늘어놓기 시작할 테니, 네가 조립에 쓸 도구와 재료들을 내 작업장 [cite: 34] 주변에서 좀 가져다줄래.\n\n도와줄 거지? 이 장치에 쓸 수 있는 예비 부품은 모조리 필요하니까, 내 보물들을 샅샅이 뒤질 때 가리지 말고 다 주워 와. 조심해서 다뤄야 해!",
    },
    [27958] = {
        ["T"] = "첫 번째 시험",
        ["O"] = "웨일린의 발명품을 자신에게 사용해 보고 어떤 일이 일어나는지 확인해야 합니다.",
        ["D"] =
        "좋아, $N. 다 조립했으니 이제 네가 써 볼 차례야!\n\n<웨일린이 상자 가득 담긴 장비들을 당신의 손에 안겨줍니다.>\n\n네 갑옷 안쪽에 쏙 들어갈 테니 겉모습 걱정은 안 해도 돼!",
    },
    [27959] = {
        ["T"] = "수리 [cite: 23] 필요하십니까?",
        ["O"] = "아이언포지 [cite: 15]의 기록관 던김과 대화해야 합니다.",
        ["D"] =
        "다음 모험을 떠날 준비가 다 된 것 같네, $N.\n\n나는 이곳의 내 연구실이 좋아. 그 번잡한 소음에서 뚝 떨어져 있으니까! 장비가 부서질 때마다 여기까지 오는 건 귀찮을 테니, 혹시라도 수리 키트가 필요하면 아이언포지 [cite: 15]에 있는 기록관 던김에게 보내둘게.\n\n너와 함께 일해서 정말 즐거웠어. 그냥 얼굴 보러 오고 싶으면 언제든 찾아오라고!",
    },
    [27960] = {
        ["T"] = "어둠의 창 축제",
        ["O"] = "다르나서스 [cite: 7] 달의 신전에 있는 사절 크랄본과 대화해야 합니다.",
        ["D"] =
        "정말 신나는 소식입니다! 어둠해안 [cite: 7]에 은둔해 사는 어둠의 창 트롤들이 축제를 여는데, 처음으로 외부인들을 초대하여 그들의 관습을 지켜보고 참여할 기회를 준다고 합니다. 트롤들의 문화를 도끼에 머리통이 날아갈 걱정 없이 관찰할 수 있는 아주 귀한 기회죠.\n\n관심이 있으시다면 다르나서스 [cite: 7] 달의 신전에 있는 그들의 사절을 찾아가 보십시오.",
    },
    [27961] = {
        ["T"] = "어둠의 창 축제",
        ["O"] = "오그리마 [cite: 21] 정기의 골짜기 [cite: 31]에 있는 사절 발크론과 대화해야 합니다.",
        ["D"] =
        "정말 신나는 소식입니다! 어둠해안 [cite: 7]에 은둔해 사는 어둠의 창 트롤들이 축제를 여는데, 처음으로 외부인들을 초대하여 그들의 관습을 지켜보고 참여할 기회를 준다고 합니다. 트롤들의 문화를 도끼에 머리통이 날아갈 걱정 없이 관찰할 수 있는 아주 귀한 기회죠.\n\n관심이 있으시다면 오그리마 [cite: 21] 정기의 골짜기 [cite: 31]에 있는 그들의 사절을 찾아가 보십시오.",
    },
    [27962] = {
        ["T"] = "어둠의 창 축제",
        ["O"] = "어둠의 창 축제에서 도끼 던지기 대회에 참여한 후 어둠의 창 마을의 우나 지로에게 돌아가야 합니다.",
        ["D"] =
        "어둠의 창 축제에 온 걸 환영한다, $R! 우리 외딴 고향에 이방인이 오는 건 드문 일이니 영광으로 생각하라고. 언제든 집으로 돌아가고 싶으면 내게 말해.\n\n하지만 가기 전에 축제를 즐겨야지. 음식 [cite: 10]과 마실 걸 맛보고 -- 용기가 있다면 불빛 아래서 춤을 추거나, 도끼 던지기 표적에서 어둠의 창 챔피언 브루 주닐과 실력을 겨뤄보라고. 마을 안쪽으로 들어가면 다 찾을 수 있을 거다.",
    },
    [27963] = {
        ["T"] = "초보자를 위한 광폭화",
        ["O"] = "부두 [cite: 32] 재료를 모아 어둠의 창 축제에 있는 의술사 할데에게 가져가야 합니다.",
        ["D"] =
        "아, 꼬맹이. 너도 브루 녀석한테 깨진 도전자 중 하나로구나. 할데가 브루를 꺾을 비법을 알려주마 -- 그 녀석은 콧대 좀 꺾여야 해.\n\n브루가 챔피언이 될 수 있었던 비밀은 우리 내면에 있는 분노 -- 모든 영웅의 힘의 원천 -- 에 깊이 교감했기 때문이지. 트롤들은 태어날 때부터 이걸 배우지만 이방인인 너도 제대로 연습만 하면 그 힘을 끌어낼 수 있어.\n\n그 과정을 돕기 위해 네가 좀 모아와야 할 물건이 있어 -- 정글 트롤들에게서 모조 [cite: 20] 한 병 [cite: 3], 서리트롤을 상징할 여명의 설원 [cite: 34] 곰의 이빨, 그리고 우리 숲 트롤 적들의 뼈다. 동부 역병지대 [cite: 8] 폐허에 있는 이끼가죽 트롤들의 뼈면 충분할 거야.\n\n너희 대도시 [cite: 5]의 사절과 우나 지로에게 말을 걸면 우리 마을과 네 고향 사이를 자유롭게 오갈 수 있을 거다.",
    },
    [27964] = {
        ["T"] = "초보자를 위한 광폭화",
        ["O"] = "광폭화 강화 효과를 받은 상태로 어둠의 창 마을 동굴에 있는 어둠의 창 부적을 처치하고 의술사 할데에게 돌아가야 합니다.",
        ["D"] =
        "솔직히 말해서 네가 살아서 돌아올 줄 몰랐다, $R. 보기보다 꽤 끈질기구나.\n\n아주 좋아. 이제 우리 부족의 방식으로 널 시험해 볼 차례야. 길을 따라 조금만 올라가면 동굴이 하나 나올 거다. 네가 가져온 재료로 만든 이 목걸이 [cite: 25]를 걸면 광전사의 속도로 널 축복해 줄 거야. 그 힘에 저항하지 말고 온전히 내맡겨. 그리고 그 힘으로 그곳의 궤짝에 있는 녀석을 물리쳐봐 -- 궤짝을 열 용기가 있다면 말이지.",
    },
    [27965] = {
        ["T"] = "초보자를 위한 광폭화",
        ["O"] = "어둠의 창 마을의 도끼 던지기 대회에서 브루 자닐을 이기고 의술사 할데에게 돌아가야 합니다.",
        ["D"] =
        "넌 아직 광폭화의 초보자에 불과하지만, 브루 자닐을 상대로 경쟁에 사용할 만큼은 알아. 그 녀석은 게을러터져서 전혀 예상하지 못할 테니 -- 네가 그 기회를 놓치지 않는다면 승산이 있을 거야.\n\n네게 기대가 크다, $N. 도끼 던지기 사로에 있는 브루에게 돌아가서 다시 한번 도전해 봐. 네가 그를 꺾는다면 널 명예로운 어둠의 창 챔피언으로 인정해 주마.",
    },
    [27966] = {
        ["T"] = "다르나서스 [cite: 7]로 돌아가기",
        ["O"] = "다르나서스 [cite: 7] 달의 신전에 있는 역사학자 디미트레스쿠와 대화해야 합니다.",
        ["D"] =
        "이봐, 트롤이 된다는 건 단순히 분노를 끌어내는 것 이상이야. 하지만 그거에 대해 더 알고 싶다면, 다르나서스 [cite: 7]에 도움을 청할 만한 사람들이 있을 거라고 확신해.\n\n사절 크랄본이 말하길 디미트레스쿠라는 매력적인 나이트 엘프가 우리 역사에 대해 유난히 관심을 보였다더군. 우리도 한때는 같은 민족이었단 사실, 알고 있지?\n\n하지만 그건 아주 오래전 이야기야, 살아있는 자들의 기억을 훌쩍 넘어서는.\n\n<의술사 할데가 당신에게 윙크를 합니다.>\n\n행운을 빈다, 모험가여.",
    },
    [27967] = {
        ["T"] = "오그리마 [cite: 21]로 돌아가기",
        ["O"] = "오그리마 [cite: 21] 투기장의 제왕 조크와 대화해야 합니다.",
        ["D"] =
        "이봐, 트롤이 된다는 건 단순히 분노를 끌어내는 것 이상이야. 하지만 그거에 대해 더 알고 싶다면, 오그리마 [cite: 21]에 도움을 청할 만한 사람들이 있을 거라고 확신해.\n$사절 발크론이 말하길 조크라는 타우렌이 우리 역사에 대해 유난히 관심을 보였다더군. 오래전 전 세계 사람들이 트롤에게서 지혜를 배우러 왔었지. 하지만 그건 아주 오래전 이야기야, 대부분 존재의 기억을 훌쩍 넘어서는.\n\n<의술사 할데가 당신에게 윙크를 합니다.>\n\n행운을 빈다, 모험가여.",
    },
    [27968] = {
        ["T"] = "용서 [cite: 11]",
        ["O"] = "",
        ["D"] = "",
    },
    [27969] = {
        ["T"] = "작업장 [cite: 34]의 의식",
        ["O"] = "황야의 땅 [cite: 2] 스프링소켓에 있는 하위 카트스프로켓과 대화해야 합니다.",
        ["D"] =
        "구리관 [cite: 6]과 만능 스패너 [cite: 2]를 처음 만들던 그 시절에 비하면 자넨 정말 놀랍게 발전했어. 자네 기계공학 [cite: 9] 실력을 시험해 볼 준비가 된 것 같군.\n\n땜장이 조합 모임에서 만난 지인에게서 연락을 받았네. 취미 삼아 일하는 친구이긴 한데 -- 그 친구가 진짜 사랑하는 건 역사야. 아무튼, 엄청나게 노련한 기술자의 도움이 간절히 필요하다더군. 호드든, 얼라이언스든, 소속이 아예 없든 상관없다면서 말이야! 정말 절박한 모양이야.\n\n그 친구 성격상 보수는 쥐꼬리만 하겠지만, 꽤 흥미로운 일일 거야. 어떻게, 한 번 해볼 텐가?",
    },
    [27970] = {
        ["T"] = "작업장 [cite: 34]의 의식",
        ["O"] =
        "하위 카트스프로켓은 톨 바라드 [cite: 30] 섬에 있는 바라딘 요새 [cite: 2]로 이동하여 바라딘 요새 [cite: 2] 경비병에게서 자신의 이중 안전장치 공책을 받아 황야의 땅 [cite: 2] 스프링소켓에 있는 그에게 가져다주기를 원합니다. 아라시 고원 [cite: 1]의 팔디르의 만 [cite: 10]에서 톨 바라드 [cite: 30]로 향하는 비행편을 이용할 수 있습니다.",
        ["D"] =
        "탐험가 연맹은 티탄의 역사를 연구하기 위해 설립됐지만, 난 그들의 기술에 대해 더 알고 싶어! 특히 내부 연결형 지맥-안정화 비전 플럭스 엔진의 기초 조립체, 줄여서 F.A.I.L.S.A.F.E(안전장치)로 알려진 장치에 대한 소문 말이야. 이 장치는 행성의 대재앙을 막기 위해 고안되었지만, 제대로 관리되지 않으면 오히려 엄청난 문제를 일으킬 수 있거든.\n\n이 장치에 대한 내 모든 연구 기록이 담긴 공책을 아는 지인에게 도둑맞았는데, 그 녀석이 지금 바라딘 요새 [cite: 2] 감옥에 수감되어 있어. 그곳 경비병에게 편지를 보냈더니, 공책을 가지러 와도 좋다는 답장을 받았어. 아직 갈 시간을 못 냈지만, 조수가 있다면 나도 두 곳에 동시에 있을 수 있지 않겠어? 자, 톨 바라드 [cite: 30]로 가서 내 공책을 좀 가져다줘!",
    },
    [27971] = {
        ["T"] = "작업장 [cite: 34]의 의식",
        ["O"] =
        "바라딘 요새 [cite: 2]의 죄수 중 한 명에게서 하위 카트스프로켓의 공책을 회수하여 황야의 땅 [cite: 2] 스프링소켓에 있는 그에게 돌려주어야 합니다.",
        ["D"] =
        "하위의 공책을 되찾는 걸 도와줄 바라딘 감시자가 없으니, 이 문제는 자네가 직접 해결해야 해.\n\n죄수 중 한 명이 틀림없이 공책을 훔친 자일 거야. 그들을 심문하거나 감방을 조사하면 자네가 찾는 걸 알아낼 수 있지 않을까?",
    },
    [27972] = {
        ["T"] = "작업장 [cite: 34]의 의식",
        ["O"] = "운고로 분화구의 마샬의 야영지 [cite: 19]에 있는 J.D. 콜리와 대화해야 합니다.",
        ["D"] =
        "이제 내 공책을 되찾았으니 내가 발견했던 내용을 다시 떠올릴 수 있겠어. 아, 맞아! 운고로 분화구라는 미지의 땅으로 탐험을 떠난 동료에게서 낡은 편지를 받았었지. 그녀는 분화구에 안전장치와 연관될지도 모르는 티탄 기술의 흔적이 남아 있을 거라고 생각했어.\n\n있잖아, 내 노트를 전부 다시 읽으려면 시간이 좀 걸릴 것 같아. 네가 그 친구를 직접 찾아가 보는 건 어때? 말하자면 노움의 입에서 직접 최신 정보를 들어보라는 거지. 아주 먼 곳이니, 네가 돌아올 때쯤이면 나도 멈췄던 연구를 다시 시작할 준비가 끝날 거야.",
    },
    [27973] = {
        ["T"] = "작업장 [cite: 34]의 의식",
        ["O"] =
        "운고로 분화구에 있는 타르 [cite: 29] 정령을 처치하여 티탄 기술의 파편 [cite: 7]을 회수하고, 운고로 분화구의 마샬의 야영지 [cite: 19]에 있는 J.D. 콜리에게 가져가야 합니다.",
        ["D"] =
        "하위가 티탄 기술에 대해 물어보라고 직접 너를 이 먼 곳까지 보냈단 말이야? 글쎄, 하위에게 들려줄 만한 이야기가 별로 없는데! 분화구 곳곳에 흩어져 있는 수정 수정탑들을 연구해 오긴 했지만, 그것들이 정말 티탄의 것인지는 나도 확실히 몰라.\n\n굳이 추측해보자면, 이곳의 원소들은 아주 오래전부터 존재했어. 그리고 이 타르 [cite: 29] 웅덩이들 말인데... 어쩌면 타르 [cite: 29] 정령들이 티탄 기술의 일부를 삼켰을지도 모르지? 타르 [cite: 29] 정령들을 충분히 해부해보면 고대 티탄의 유물을 발견할 수 있을지도 몰라!",
    },
    [27974] = {
        ["T"] = "작업장 [cite: 34]의 의식",
        ["O"] =
        "운고로 분화구의 마샬의 야영지 [cite: 19]에 있는 J.D. 콜리는 당신이 정교한 아케이나이트 변환기 [cite: 7]를 제작하여 그녀에게 가져오길 원합니다.",
        ["D"] =
        "이건 확실히 열릴 거야! 그저 기계적으로 꽉 닫혀 있을 뿐이지. 정교한 아케이나이트 변환기 [cite: 7]만 있다면 좋을 텐데.\n\n잠깐! 아까 기술자라고 했지? 만들 수 있어? 하나 만들어서 내게 가져다주면 이 장치를 열 수 있을 것 같아!",
    },
    [27975] = {
        ["T"] = "작업장 [cite: 34]의 의식",
        ["O"] =
        "기이한 고대 유물을 찾을 때까지 실리더스 [cite: 26] 지역의 아무 벌레집에서 잠복꾼, 일벌레, 땅무지, 일꾼들을 처치한 후, 황야의 땅 [cite: 2] 스프링소켓에 있는 하위 카트스프로켓에게 가져가야 합니다.",
        ["D"] =
        "이 구체 안의 장치....\n\n<J.D.는 기침을 하며 물건에서 모래를 더 털어냅니다.>\n\n내 눈엔 확실히 티탄 기술로 보여. 근데 이 모래 좀 봐! 운고로 모래가 아니잖아! 타나리스 [cite: 28]의 모래 같은 느낌도 전혀 안 나고.\n\n근데... 얼마 전에 실리더스 [cite: 26] 사막으로 향하던 탐험대가 이곳을 지나갔었지. 그들 보고에 따르면 사막에서 땅을 파는 벌레들이 잔뜩 있다고 했어. 어쩌면 땅을 파는 곤충들이라면 이 물건이 그곳에서 온 것일 경우 이런 유물을 더 많이 가지고 있지 않을까?\n\n탐험대가 북서쪽 언덕으로 올라가는 길을 찾아냈어. 한번 시도해 볼 만한 가치는 있을 거야. 무언가 발견하면 하위에게 가져다주렴. 난 이걸로 뭘 해야 할지 전혀 모르겠거든.\n\n행운을 빌어!",
    },
    [27976] = {
        ["T"] = "작업장 [cite: 34]의 의식",
        ["O"] =
        "하위 카트스프로켓은 당신이 기계공학 [cite: 9] 기술을 사용하여 야전수리로봇 1개, 고급 표적 허수아비 [cite: 1] 3개, 강력한 시포리움 폭약 [cite: 22] 1개, 토륨 수류탄 20개를 제작해 주길 원합니다. 황야의 땅 [cite: 2] 스프링소켓에 있는 그에게 가져가십시오.",
        ["D"] =
        "울둠 [cite: 31]은 고대 티탄의 연구 시설이야. 이 노드들은 일종의 참고 문헌 같은 거고, 그걸 읽을 수 있는 장치가 시설 내부에 존재할 텐데. 굳게 닫혀 있어서 문제지.\n\n어쩌면 이 노드가 울둠 [cite: 31]의 문을 여는 연구에 도움이 될지도 몰라. 스프링소켓에서의 일을 마치는 대로 바로 출발해야겠어.\n\n떠나기 전에 진짜 사막 야영 준비를 철저히 해야 해 -- 타나리스 [cite: 28]는 황야의 땅 [cite: 2]보다 훨씬 오지라고 들었으니까! 그래서 조수 네가 필요한 거야! 보급품이 필요해: 발굴 작업에 쓸 야전수리로봇과 강력한 시포리움 폭약 [cite: 22], 덫으로 쓸 고급 표적 허수아비[cite: 1], 그리고 성가신 야생 동물을 쫓아낼 토륨 수류탄 잔뜩!",
    },
    [27977] = {
        ["T"] = "상품권 교환",
        ["O"] = "탈것 상품권을 사용하여 기계타조를 선택하십시오.",
