        ["D"] = "",
    },
    [27985] = {
        ["T"] = "실험실의 의식",
        ["O"] = "저승바람 고개의 야영지에 있는 아리덴 엘리스와 대화하십시오.",
        ["D"] =
        "당신이 이곳에 여러 번 방문하는 것을 보았습니다. 당신의 연금술 숙련도에 칭찬을 보내고 싶군요. 사실 너무 감명받은 나머지, 당신에게 일자리 하나를 추천하고 싶습니다.\n\n한 옛 지인이 수수께끼를 푸는 데 도움이 필요하다며 전갈을 보내왔는데, 그 일에는 대가급 연금술사의 기술이 필요합니다. 모험심과 필요한 기술을 모두 갖춘 사람으로 가장 먼저 당신이 떠올랐죠.\n\n관심이 있다면 저승바람 고개로 향하십시오. 그 황량한 협곡 어딘가에 야영하고 있는 아리덴을 찾을 수 있을 겁니다.",
    },
    [27986] = {
        ["T"] = "실험실의 의식",
        ["O"] =
        "저승바람 고개에 있는 아리덴 엘리스는 당신이 연금술 기술을 사용해 일급 치유 물약 5개, 일급 마나 물약 5개, 돌비늘 기름 5개, 생명력 활성 물약 5개를 만들어 자신에게 가져오기를 원합니다.",
        ["D"] =
        "저는 오랜 세월 카라잔의 관리인으로 지냈습니다. 제 자신이 뛰어난 연금술사는 아닐지 몰라도, 물약과 비약에 대해서는 잘 알고 있죠. 카라잔의 연금술사들이 소유했던 지식을 되찾는 것이 제 임무입니다만, 저를 도와줄 고급 기술을 가진 누군가가 필요합니다.\n\n그러니 먼저, 당신이 그런 기술을 가지고 있다는 것을 증명해 주십시오. 여기 만들기 꽤 까다로운 물약 목록이 있습니다. 당신의 기술을 증명할 수 있도록 이 물약들을 제조해 주신다면, 우리가 여기서 무엇을 하고 있는지 설명해 드리겠습니다.",
    },
    [27987] = {
        ["T"] = "실험실의 의식",
        ["O"] =
        "남쪽의 카라잔 폐허를 수색하여 연금술 책을 찾은 다음, 저승바람 고개에 있는 아리덴 엘리스에게 가져가십시오.",
        ["D"] =
        "카라잔의 연금술 실험실이 완벽하게 가동되던 시절을 당신이 보지 못한 것은 정말 안타까운 일입니다. 저는 종종 도서관에서 책을 빌려 연금술의 경이로움에 대해 읽곤 했죠. 제가 자리를 비웠을 때 그 비극이 일어났고, 제게는 귀중한 고서 한 권만이 남아 있었습니다. 그 고서는 제게 더 많은 것을 찾기 위해 돌아오도록 영감을 주었죠.\n\n폐허 어딘가에 다른 고서들이 있을지도 모릅니다. 아마 그곳을 떠도는 갇힌 영혼들이 소유하고 있을지도 모르죠. 부디 폐허를 뒤져 연금술 고서를 발견하면 모두 가져와 주십시오.",
    },
    [27988] = {
        ["T"] = "실험실의 의식",
        ["O"] =
        "서부 역병지대 카엘 다로우 섬에 있는 스칼로맨스 실험실의 환영 강사들에게서 봉인 해제 연고를 모아 저승바람 고개의 아리덴 엘리스에게 가져가십시오.",
        ["D"] =
        "당신이 도안의 개인 연금술 일지를 되찾아오다니 믿을 수 없군요! 그가 전쟁 후 미쳐서 붉은십자군에 가담했다는 소식은 들었지만, 한때 그는 카라잔에서 복무하던 키린 토 수습생이었습니다. 도안은 연금술에 꽤 재능이 있고 창의적이었죠. 비록 그의 진짜 관심사는 순수한 비전 마법이었지만요.\n\n이 고서에는 제가 재현하고자 하는 정확한 실험 내용이 담겨 있습니다만, 눈치채셨겠지만 보호 마법이 걸려 있습니다. 키린 토의 수호물은 강력하지만 올바른 재료만 있다면 깰 수 있죠. 어디 보자....\n\n스칼로맨스에 서식하는 그 끔찍한 강령술사들이 우리가 필요한 것을 가지고 있을 겁니다. 그들도 자체 연금술 실험실을 가지고 있다고 들었는데, 카라잔에 필적할 정도는 아닐 겁니다. 저주받은 자들의 교단은 우리 모두에게 재앙이죠. 그곳으로 가서 그들에게서 봉인 해제 연고를 가져오십시오.",
    },
    [27989] = {
        ["T"] = "실험실의 의식",
        ["O"] =
        "저승바람 고개의 야영지에 있는 아리덴 엘리스는 당신이 연금술 기술을 사용해 눈부신 빛의 비약 5개, 현자의 비약 5개, 우수한 방어의 비약 5개, 살쾡이의 비약 5개를 만들어 자신에게 가져오기를 원합니다.",
        ["D"] =
        "예, 이제 이 고서를 읽을 수 있군요. 아주 훌륭한 진전입니다, $N.\n\n제가 아는 도안의 연구에 따르면, 그는 다양한 비약을 결합하여 일종의 강력한 궁극의 비약을 만들려 했습니다. 그 시도는 매우 위험한 것으로 판명되어 중단하라는 지시를 받았고, 그때 그는 연금술에 대한 흥미를 잃었죠. 이제 우리를 막을 사람은 없으니, 그가 중단했던 곳부터 다시 시작할 수 있습니다.\n\n도안이 추천하는 비약 목록이 여기 있습니다: 눈부신 빛, 현자, 우수한 방어, 그리고 살쾡이. 각각 5개씩 만들어서 한번 시도해 보는 게 어떨까요?\n\n이게 성공한다면, 우리는 카라잔 내부에 접근할 수 있고 어쩌면 그 안에 남아있는 악마의 타락을 정화할 수 있는 비약을 만들어낼 수도 있을 겁니다.",
    },
    [27990] = {
        ["T"] = "실험실의 의식",
        ["O"] =
        "실리더스의 바람의 정령에게서 정제된 유리 조각 10개를 구하십시오. 저승바람 고개의 아리덴 엘리스에게 그 유리와 아케이나이트 주괴를 가져가십시오.",
        ["D"] =
        "도안의 주된 난제는 이 비약들을 결합했을 때 생성되는 강력한 혼합물을 담을 적절한 용기를 찾는 것이었습니다. 일반적인 수정 유리병은 금이 가거나 심지어 폭발해 버렸죠! 놀랍지 않습니까!\n\n하지만 제게 좋은 생각이 있습니다. 실리더스라는 먼 땅에 대해 읽은 적이 있죠. 그 땅을 배회하는 바람의 정령들은 고대의 미세한 모래를 빨아들입니다. 고대 나이트 엘프의 기록에 따르면 정령들은 그 소용돌이치는 내부에서 모래를 회전시켜 엄청나게 단단한 유리 조각으로 만들어낸다고 하더군요.\n\n왜 그러냐고요? 책을 많이 읽어서 그렇습니다.\n\n칼림도어의 먼 끝자락까지 가는 긴 여정이 되겠지만, 이것이 우리가 가진 최선의 선택입니다. 궁극의 유리병을 만들기에 충분한 유리를 얻을 때까지 이 정령들을 처치하십시오. 아, 유리를 보강하기 위해 아케이나이트 주괴도 하나 필요할 겁니다. 당신 정도의 실력자라면 그리 어려운 일은 아니겠죠.",
    },
    [27991] = {
        ["T"] = "실험실의 의식",
        ["O"] = "저승바람 고개에서 아리덴 엘리스와 함께 실험 결과를 확인하십시오.",
        ["D"] =
        "이야기가 딴 데로 샜군요. 향수에 젖은 노인의 횡설수설을 용서하십시오.\n\n이 실험을 진행하는 데 필요한 모든 것을 갖추었습니다. 이제 도안의 기록대로 재료를 결합할 것입니다. 부디 이 수수께끼가 풀리는 순간을 함께해 주십시오.",
    },
    [27992] = {
        ["T"] = "대장간의 의식",
        ["O"] = "가시덤불 골짜기의 무법항에 있는 맥가반과 대화하십시오.",
        ["D"] =
        "낯이 익군요. 가열로 주변에서 시간을 많이 보내시죠? 네, 당신은 우리에게 필요한 기술을 가지고 있군요.\n\n무법항에 맥가반이라는 제 친구가 있습니다. 이전에 마주친 적이 있을지도 모르겠지만, 그렇지 않다 하더라도 그와 토륨 대장합의 모든 구성원은 금속과 마법의 비밀을 푸는 데 관심이 있다는 것만 알아두십시오. 당신도 관심이 있다면 맥가반의 대장간으로 가보십시오. 그는 이 세상의 것이 아닌 무언가를 연구하고 있답니다....",
    },
    [27993] = {
        ["T"] = "대장간의 의식",
        ["O"] =
        "가시덤불 골짜기 무법항의 맥가반은 당신이 대장기술을 사용하여 흑요석 단검 2개를 제작해 오기를 원합니다.",
        ["D"] =
        "내 친구가 당신에게 금속의 비밀을 풀 기술이 있다고 생각한단 말이지? 그럼 시험해 보지.\n\n흑요석 단검 두 자루를 만들어 와. 도면이 없다면, 글쎄, 죽을 고비를 넘겨야 배울 수 있을 텐데. 그게 바로 우리가 연구할 대상이니 완벽한 시험이 되겠군.\n\n아직도 헷갈린다면 서부 역병지대의 스칼로맨스를 뒤져봐. 도면을 사려면 거기서 잔심부름을 좀 해야 할지도 모르지만, 앞으로 다가올 일에 비하면 널 더 강하게 만들어 줄 거야.",
    },
    [27994] = {
        ["T"] = "대장간의 의식",
        ["O"] =
        "동부 역병지대의 스트라솔름으로 들어가 검은호위대 검제작자를 처치하십시오. 괴저의 칼날을 회수하여 가시덤불 골짜기 무법항의 맥가반에게 가져가십시오.",
        ["D"] =
        "괴저 금속을 다뤄본 적 있나? 아니, 괴저 금속이라는 걸 들어보기라도 했어? 없겠지? 뭐, 그런 게 존재하고 난 그게 어떻게 작동하는지 알아내려 해.\n\n금속은 살아있는 게 아니니 애초에 죽을 수도 없고, 언데드가 될 수는 더더욱 없지. 스컬지가 그런 걸로 만든 칼날을 사용한다는 소문을 들었으니, 첫 번째 단계는 그 칼날 중 하나를 얻는 거야.\n\n스트라솔름에는 한때 훌륭한 대장간 구역이 있었고, 스컬지가 그들의 생각 없는 전사들을 위해 어떻게든 칼날을 만들고 있으니 틀림없이 그곳에 있을 거야. 동부 역병지대로 가서 폐허에서 뭘 찾을 수 있는지 봐. 친구들을 데려가는 게 좋을 거야.",
    },
    [27995] = {
        ["T"] = "대장간의 의식",
        ["O"] = "실리더스의 브론즈비어드 야영지에 있는 브란 브론즈비어드와 대화하십시오.",
        ["D"] =
        "난 브란 브론즈비어드라는 탐험가를 우연히 만나 이 물질에 대해 처음 알게 되었지. 그가 내 몇 가지 질문을 조사해 보겠다고 약속했는데, 마지막 편지에 답장이 없더군.\n\n당신은 위험한 상황에서도 제 몫을 할 수 있을 것 같아. 내가 괴저의 칼날을 연구하는 동안, 칼림도어 반대편에 있는 실리더스로 가줘. 브론즈비어드는 편지에서 드워프의 역사적 발견을 연구하기 위해 그곳에 야영할 것이라고 했지. 내 질문에 대한 답을 얻어 여기로 돌아와 줘.",
    },
    [27996] = {
        ["T"] = "대장간의 의식",
        ["O"] =
        "브란의 잠긴 궤짝을 찾을 때까지 실리더스의 긴다리 바위거미를 처치하십시오. 궤짝과 아케이나이트 해골 열쇠를 가시덤불 골짜기 무법항의 맥가반에게 가져가십시오.",
        ["D"] =
        "야영지를 세운 후 한동안 우리는 거미들이 물건을 훔쳐 가는 진짜 골칫거리를 겪었소. 우리가 쫓아냈지만, 그중 몇 마리가 끈적한 거미줄을 이용해 우리 개인 물품을 가져가 버렸지 뭐요!\n\n브란은 그 금속에 대한 모든 기록을 잠긴 궤짝에 보관하고 있었소. 그 상자는 마지막으로 야영지에서 달아나는 긴다리 바위거미의 등에서 목격되었소. 그놈들을 충분히 처치하다 보면 상자와 기록을 찾을 수 있을 거요.\n\n물론 여기엔 상자를 열어줄 브란이 없으니, 그 일을 하려면 아케이나이트 해골 열쇠가 필요할 거요. 하지만 당신이 대장장이이니 그 정도는 문제없을 거라 믿소.",
    },
    [27997] = {
        ["T"] = "대장간의 의식",
        ["O"] =
        "가시덤불 골짜기 무법항의 맥가반은 당신이 대장기술을 사용하여 검은무쇠 어깨보호구 한 쌍과 화산 망치를 제작해 오기를 원합니다.",
        ["D"] =
        "당신이 없는 동안 괴저의 칼날을 구성 요소로 분해할 수 있었어. 하지만 브란의 기록에 따르면 그럴 필요가 없을지도 몰라. 그는 일반 금속에 괴저 에너지를 가하면 괴저 금속으로 변형된다고 이론을 세웠더군!\n\n우린 이 이론을 시험해 봐야 해. 브란은 기본 재료로 좋을 만한 몇 가지 아이템을 추천했지. 이 목록 중에서... 검은무쇠 어깨보호구와 화산 망치를 만들어 주겠나.\n\n도면을 모른다면, 검은무쇠 어깨보호구는 검은바위 산의 깊은 곳에서 구할 수 있고, 화산 망치 도면은 토륨 대장합과 관련된 누군가에게서 살 수 있을 거야.",
    },
    [27998] = {
        ["T"] = "대장간의 의식",
        ["O"] =
        "동부 역병지대나 여명의 설원의 밴시에게서 유령의 혈장 6개를 모아 가시덤불 골짜기 무법항의 맥가반에게 가져가십시오.",
        ["D"] =
        "난 우리가 필요한 이 유령의 혈장에 대해서는 아무것도 모르지만, 일단 손에 넣으면 금속에 불어넣는 방법은 이해하고 있지. 그러니 난 가열로를 준비할 테니, 당신은 혈장을 구해와.\n\n브란의 기록에 따르면 밴시 유령이 가장 효과적일 거라고 하더군. 여명의 설원에 있는 오래된 나이트 엘프 폐허에 밴시가 있는 것 같아. 아니면 하이 엘프들이 살았던 동부 역병지대일까? 어디서 구하든 구해오기만 하면 돼!",
    },
    [27999] = {
        ["T"] = "대장간의 의식",
        ["O"] = "맥가반이 괴저 금속을 만들어내는 실험 결과를 관찰하십시오.",
        ["D"] =
        "좋아. 일반 무기와 방어구도 있고. 유령의 혈장도 있고. 뜨거운 가열로도 있지. 우린 도구도 있고, 재능도 있다고!\n\n물러서 있는 게 좋을 거야, $N. 이게 얼마나 뜨거워지거나 차가워질지 전혀 모르니까.",
    },
    [28000] = {
        ["T"] = "불의 의식",
        ["O"] = "타나리스의 스팀휘들 항구에 있는 카렘과 대화하십시오.",
        ["D"] =
        "내 친구 카렘은 아제로스 최고의 요리사로 알려져 있지... 하지만 다음 요리 평론가가 그녀의 메뉴를 시식할 때 미슐룬 별을 지켜내지 못한다면 그 타이틀을 이자벨 픽맨에게 빼앗길 위기에 처해 있어. 그녀는 재능 있는 부주방장을 찾기 위해 내게 연락했고, 당신은 내 주방을 거쳐 간 최고 중 한 명이지. 즉, 전설적인 카렘과 함께 요리할 기회를 얻었다는 뜻이야!\n\n스팀휘들 항구에 있는 그녀의 새 식당에서 그녀를 찾을 수 있을 거야. 모른다면 타나리스에 있어.",
    },
    [28001] = {
        ["T"] = "불의 의식",
        ["O"] =
        "타나리스 스팀휘들 항구의 카렘은 당신이 요리 기술을 사용하여 단백질 쉐이크 10개를 만들어 자신에게 가져오기를 원합니다.",
        ["D"] =
        "부주방장? 오! 내 메시지가 잘 전달되어 다행이군요.\n\n네, 맞아요, 위대한 카렘은 부주방장이 필요하죠. 하지만 내 오랜 친구 이자벨 픽맨과 경쟁할 수 있도록 날 도울 만큼 실력이 뛰어나야 해요.\n\n이자벨은 요리의 어두운 면에 타락했지만, 재능과... 창의성이라고 부르죠, 그것만큼은 부정할 수 없어요. 그녀의 대표 메뉴인 단백질 쉐이크를 요리해서 내 주방에서 쓸모가 있다는 걸 증명해 보이세요.\n\n아직 만드는 법을 모른다면 먼저 그녀 밑에 가서 배워야 할지도 몰라요. 요즘 그녀는 서부 역병지대의 카엘 다로우 섬에 있거든요.",
    },
    [28002] = {
        ["T"] = "불의 의식",
        ["O"] =
        "서부 역병지대의 스칼로맨스에 들어가 이자벨 픽맨의 요리책을 찾으십시오. 타나리스 스팀휘들 항구의 카렘에게 그것을 가져가십시오.",
        ["D"] =
        "이자벨 픽맨은 이제 역병 지대에 있는 그 스칼로맨스라는 기괴한 학교의 수석 주방장이 되었어요. 그녀가 그 명망 있는 자리를 얻은 건 내 실험적인 레시피 몇 개를 훔쳐서 자기 것인 양 행세했기 때문이죠!\n\n글쎄요, 요리 세계에선 역지사지가 공평하죠. 당신이 우리만의 첩보 활동을 해줬으면 해요. 그 학교에 그녀의 요리책이 분명 있을 거예요. 가서 훔쳐 오세요! 내가 그 계획을 뛰어넘으려면 그녀가 무슨 연구를 하고 있는지 알아야 해요.",
    },
    [28003] = {
        ["T"] = "불의 의식",
        ["O"] =
        "타나리스 스팀휘들 항구의 카렘을 위해 실리더스의 아시 하이브 생물에게서 부드러운 살코기 10개를 구하십시오.",
        ["D"] =
        "신성한 나무 맙소사! 이 책에 있는 레시피들은 끔찍해요! 대부분의 요리에 인간의 고기가 들어가다니... 역겨워요. 인간은 맛도 없고 질긴데다... 어쨌든 제철도 아니잖아요.\n\n하지만 봐요, 육지와 바다 고기를 섞는 것에 대한 그녀의 메모가 있어요. 우리도 그렇게 할 수 있죠. 바다는 바로 여기 있지만, 인간과 비슷하면서도 그렇게 나쁘지는 않은 육지 고기를 어디서 구하죠?\n\n알겠어요! 저 멀리 실리더스라는 곳에 타나리스에 있는 곤충형 생물들보다 훨씬 거대한 놈들이 있대요. 여기서 나는 놈들을 요리해 본 적 있는데, 인간과 그리 다르지 않거든요. 더 큰 놈들이라면 우리에게 진짜 스테이크를 줄 수 있을 거예요. 실리더스로 가서 시세가 어떻든 간에 좀 구해다 줘요.",
    },
    [28004] = {
        ["T"] = "불의 의식",
        ["O"] =
        "타나리스 스팀휘들 항구의 카렘은 당신이 요리 기술을 사용해 랍스터 롤 10개, 스트라솔름 블랑 10개, 뱃사람의 술 10개를 준비해 자신에게 가져오기를 원합니다.",
        ["D"] =
        "이 실리시드 스테이크가 육지 쪽을 해결해 줄 테니, 이제 파도를 탈 차례네요. 고전적인 메뉴로 가보죠 - 랍스터 롤. 만들어 본 적 있어요? 레시피가 필요하다면 해적들에게 엄청 인기 있죠.\n\n그리고 마실 것도 빼놓을 수 없죠. 장난스러운 곁들임으로 뱃사람의 술을 추가하고, 세련된 미각을 위해 스트라솔름 블랑을 메뉴에 올려보죠.\n\n이 레시피들도 모른다고요? 뱃사람의 술은 랍스터 롤과 같은 곳에서 나오고 스트라솔름 블랑은 당연히... 스트라솔름에서 나오겠죠!",
    },
    [28005] = {
        ["T"] = "불의 의식",
        ["O"] = "타나리스의 동굴에 있는 잘라쉬지와 대화하십시오.",
        ["D"] =
        "바다를 떠올리고 그곳에 누가 사는지 생각해보면, 결국 나가에 도달하게 되죠. 나가는 나의 고대 친족이니, 나처럼 세련된 만찬 파티를 열 것이 틀림없어요.\n\n여기서 멀지 않은 해안가에 추방된 나가가 살고 있어요. 그에게 나가가 식탁 세팅을 어떻게 하는지 물어보세요. 어쩌면 그들의 아이디어를 좀 빌릴 수 있지 않을까요?",
    },
    [28006] = {
        ["T"] = "불의 의식",
        ["O"] =
        "아즈샤라의 레이븐크레스트 기념비 근처에 있는 나가에게서 촛대, 냅킨, 식탁보, 은식기를 모아 타나리스 스팀휘들 항구의 카렘에게 가져가십시오.",
        ["D"] =
        "만 년이 넘는 세월 동안 그렇게 이상한 요청은 들어본 적 없지만, 인정하지, 꽤 재미있군. 문명화된 종족으로서 우리는 당연히 네가 찾는 물건들을 가지고 있다.\n\n어떤 나가도 힘들게 얻은 식탁보를 쉽게 내어주진 않을 테니, 무력이 필요할 것이다. 아즈샤라의 레이븐크레스트 기념비로 가는 게 좋을 거다. 그들은 내 종족이 아니며 너무 오랫동안 고립되어 살았지. 네가 나타나면 그들은 동요하고 피가 끓어오를 것이다. 말 그대로 말이야.",
    },
    [28007] = {
        ["T"] = "불의 의식",
        ["O"] = "오그리마 용골 산책로에 있는 잠자와 대화하여 성공을 알리십시오.",
        ["D"] =
        "이제 준비가 되었어요. 요리 평론가들이 와도 좋아요. 내 미슐룬 별을 지켜낼 거고 이자벨은 계속 무명 속에서 뒹굴겠죠.\n\n이제 가봐요. 당신이 내 성공의 비결이라고 평론가들이 생각하게 놔둘 순 없으니까요! 당신을 내게 보낸 친구 잠자는 어떻게 되었는지 알고 싶어 할 거예요.\n\n당신이 내 보증을 받았다고 그녀에게 말해도 좋아요.",
    },
    [28008] = {
        ["T"] = "불의 의식",
        ["O"] = "아이언포지에 있는 엠룰 루크누선과 대화하여 성공을 알리십시오.",
        ["D"] =
        "이제 준비가 되었어요. 요리 평론가들이 와도 좋아요. 내 미슐룬 별을 지켜낼 거고 이자벨은 계속 무명 속에서 뒹굴겠죠.\n\n이제 가봐요. 당신이 내 성공의 비결이라고 평론가들이 생각하게 놔둘 순 없으니까요! 당신을 내게 보낸 친구 엠룰 루크누선은 어떻게 되었는지 알고 싶어 할 거예요.\n\n당신이 내 보증을 받았다고 그에게 말해도 좋아요.",
    },
    [28009] = {
        ["T"] = "비전의 의식",
        ["O"] = "언덕마루 구릉지의 타렌 제분소에 있는 마법사장 보이드글레어와 대화하십시오.",
        ["D"] =
        "아, $N! 처음 기술을 시작했을 때부터 당신의 마법부여 숙련도가 얼마나 성장했는지. 정말 감명 깊군요! 사실 너무 감명받은 나머지 일자리 하나를 추천하고 싶습니다.\n\n마법사장 보이드글레어가 대가급 마법부여사를 구하기 위해 언더시티에 전갈을 보냈습니다. 저는 도시를 떠나고 싶지 않지만, 당신은 더... 모험심이 넘치니까요. 절대 무모하다는 뜻은 아닙니다!\n\n박쥐를 타고 타렌 제분소로 가면 마법사장에게 바로 데려다줄 것입니다. 그가 무엇을 원하는지 저도 궁금하군요. 마법사장이 도움을 요청하는 일은 드무니까요.",
    },
    [28010] = {
        ["T"] = "비전의 의식",
        ["O"] =
        "던홀드 요새 뒤편 알터랙 산맥의 구릉지에 있는 라벤홀트 장원을 찾아, 도착하면 펠리시티와 대화하십시오.",
        ["D"] =
        "거짓된 구실로 당신을 이곳에 불렀소, $N. 도움이 필요한 건 내가 아니라 라벤홀트 장원이오. 라벤홀트 영주는 비록 인간이지만 호드의 친구로 자리 잡았소.\n\n라벤홀트 영주의 애완 마법사가 장원 위쪽에서 스스로 감당할 수 없는 문제에 부딪혀 마법부여사의 도움을 요청했소. 나는 포세이큰의 비밀을 너무 많이 알고 있어서 직접 가는 위험을 감수할 수 없소. 만약 이것이 함정이라면 재앙이 될 수 있으니까. 하지만 당신! 당신은 그저 일개 보병, 그저 그런 가치의 $C일 뿐이오. 당신이 사라진다고 그리워할 사람은 많지 않을 거요.\n\n그러니 호드를 대표해서 가보시오, $N. 장원에서 만나는 누구도 믿지 마시오. 그곳은 비밀과 스파이, 그리고 고수로 가득하오. 고수는 비누 맛이 난단 말이오. 역겹군!",
    },
    [28011] = {
        ["T"] = "비전의 의식",
        ["O"] =
        "알터랙 산맥 라벤홀트 장원의 펠리시티를 위해 검은바위 첨탑 하층의 검은방패 수행사제, 주문술사, 흑마법사에게서 공명하는 재 8개를 모으십시오.",
        ["D"] =
        "단도직입적으로 말하죠. 문제가 생겼어요, $N. 20년 전 키린 토의 마법사들이 스파이와 도적을 양성하는 로데론 얼라이언스의 훈련소를 숨기기 위해 라벤홀트 장원에 예지 방지 문양을 걸어두었습니다. 오랫동안 효력을 상실했던 이 서약의 유물이 이제 불안정해지고 있어요. 폭발하거나 황천으로 향하는 차원문을 열거나 다른 끔찍한 비전 마법 사고를 일으키기 전에 이것을 제거해야 합니다.\n\n남아있는 키린 토와 상의한 결과, 검은바위 산의 검은방패 오크들이 사용하는 물질인 공명하는 재를 사용해 문양을 약화시킬 수 있다고 판단했습니다. 오직 마법부여사만이 이 재를 안전하게 다룰 수 있죠. 다른 사람의 손에 들어가면 그저 빛을 내며 허무하게 사라져버립니다.\n\n그래서... 당신의 도움을 기대해도 될까요?",
    },
    [28012] = {
        ["T"] = "비전의 의식",
        ["O"] =
        "알터랙 산맥 라벤홀트 장원의 펠리시티는 당신이 마법부여 기술을 사용하여 눈부신 큰 결정 4개, 상급 영원의 정수 6개, 환영 가루 20개를 가져오기를 원합니다.",
        ["D"] =
        "공명하는 재는 예지 방지 문양의 힘을 흡수하는 스펀지 역할을 하겠지만, 적절한 용어가 생각나지 않네요... 문양 비누...를 만들기 위해 수집해야 할 다른 재료들이 있습니다. 특히, 재를 문양에 사용된 마법의 종류와 동기화시키기 위해 여러 마법부여 재료가 필요합니다.\n\n당신은 대가급 마법부여사이니 이 재료들을 구하는 게 그리 어렵지 않으리라 확신합니다. 눈부신 큰 결정, 상급 영원의 정수, 그리고 엄청난 양의 환영 가루 말이죠.",
    },
    [28013] = {
        ["T"] = "비전의 의식",
        ["O"] =
        "알터랙 산맥 라벤홀트 장원의 펠리시티를 위해 악령숲 강철나무 숲의 나무정령에게서 강철나무 껍질 4개를, 저주받은 땅 펠스톤 요새의 흑마법사에게서 암흑문양을 구하십시오.",
        ["D"] =
        "이런 종류의 문양을 안전하게 해제하려면 마법 물질 그 이상이 필요해요. 문양이 조율된 극성을 나타내는 마법 구성 요소를 사용하여 문양을 정렬해야 합니다.\n\n이 문양은 장원이 알터랙의 자연 지형처럼 보이게 하고 어둠의 의회의 마법을 튕겨내도록 설계되었어요. 악령숲에서 구한 강철나무 껍질을 흙의 구성 요소로 사용할 수 있죠. 어둠의 의회 마법이 닿은 것이라, 군단을 상징하기 위해 필요한 암흑문양과 더 조화롭게 작용할 거예요. 군단의 잔당들이 저주받은 땅에 요새를 재건하고 있다는 소식을 들었어요. 그곳의 흑마법사에게서 암흑문양을 구할 수 있을 거예요.",
    },
    [28014] = {
        ["T"] = "비전의 의식",
        ["O"] =
        "알터랙 산맥 라벤홀트 장원의 펠리시티를 위해 실리더스의 황혼의 망치단 이교도에게서 황혼의 이교도 장갑 한 쌍을 구하십시오.",
        ["D"] =
        "당신이 마법부여에 있어 대가의 기술을 가지고 있다고 하더라도, 맨손으로 이 문양을 비활성화할 수는 없어요. 아니, 특별한 장갑 한 쌍이 필요할 거예요. 그렇지 않으면 당신의... 음, 굳이 구체적으로 설명할 필요는 없겠네요. 피부를 몽땅 잃을 위험이 있거든요.\n\n하지만 걱정 마세요. 이 임무에 딱 맞는 장갑을 찾았으니까요. 그냥 가서 장갑 한 쌍을 구하기만 하면 돼요. 황혼의 망치단 이교도들에게서요. 실리더스에서요. 요즘 그곳 날씨가 참 좋다던데! 그리고 이 일을 마치고 나면, 문양을 제거할 준비가 거의 다 되었다고 93% 확신해요.",
    },
    [28015] = {
        ["T"] = "비전의 의식",
        ["O"] =
        "알터랙 산맥 라벤홀트 장원의 펠리시티는 당신이 마법부여 기술을 사용하여 황혼의 이교도 장갑에 장갑 마법부여 - 최하급 가속을 부여한 후 자신과 대화하기를 원합니다.",
        ["D"] =
        "마지막이에요! 약속해요!\n\n이 장갑에 가속 마법부여를 조금 하는 게 좋을 것 같아요. 문양을 제거하려면 손가락이 빨라야 하고, 당신이 그 임무를 해낼 수 있다고 확신하지만 모든 이점을 다 갖추는 게 나쁠 건 없잖아요.",
    },
    [28016] = {
        ["T"] = "비전의 의식",
        ["O"] =
        "마법이 부여된 황혼의 이교도 장갑을 착용한 채 라벤홀트 장원의 지하실로 들어가 예지 방지 문양을 제거하십시오.",
        ["D"] =
        "준비는 끝났어요. 이제 시간이 되었습니다. 그 마법이 부여된 황혼의 이교도 장갑을 끼고 내 오른쪽 계단으로 내려가세요. 바닥 한가운데에 문양이 보일 겁니다. 이제 문제없이 제거할 수 있을 거예요!\n\n어서 가세요! 장원을 불태우지 않을 거라고 믿어요!",
    },
    [28017] = {
        ["T"] = "비전의 의식",
        ["O"] = "알터랙 산맥의 라벤홀트 장원에 있는 펠리시티에게 돌아가 성공을 알리십시오.",
        ["D"] =
        "문양이 사라짐으로써, 라벤홀트 장원은 더 이상 비전 사고의 현장이 될 위험에서 벗어났습니다.\n\n펠리시티는 당신의 성공에 매우 기뻐할 것입니다.",
    },
    [28018] = {
        ["T"] = "비전의 의식",
        ["O"] = "엘윈 숲의 아조라의 탑에 있는 키타 파이어윈드와 대화하십시오.",
        ["D"] =
        "아, $N! 처음 기술을 시작했을 때부터 당신의 마법부여 숙련도가 얼마나 성장했는지. 정말 감명 깊군요! 사실 너무 감명받은 나머지 일자리 하나를 추천하고 싶습니다.\n\n키타 파이어윈드 양이 대가급 마법부여사를 구하기 위해 언더시티에 전갈을 보냈습니다. 저는 도시를 떠나고 싶지 않지만, 당신은 더... 모험심이 넘치니까요. 절대 무모하다는 뜻은 아닙니다!\n\n레이크샤이어로 가는 수레를 타면 키타가 일하고 있는 아조라의 탑을 바로 지나가게 됩니다. 그녀가 무엇을 원하는지 저도 궁금하군요. 탑에서 도움을 요청하는 일은 드무니까요.",
    },
    [28019] = {
        ["T"] = "비전의 의식",
        ["O"] =
        "던홀드 요새 뒤편 알터랙 산맥의 구릉지에 있는 라벤홀트 장원을 찾아, 도착하면 펠리시티와 대화하십시오.",
        ["D"] =
        "중요한 임무를 위해 당신을 이곳에 불렀습니다, $N. 도움이 필요한 건 제가 아니라 라벤홀트 장원입니다. 라벤홀트 영주는 얼라이언스의 일원은 아니지만, 여전히 친구입니다.\n\n라벤홀트 영주의 피후견인은 재능 있는 마법사지만, 마법부여사의 기술이 필요한 문제에 부딪혔습니다. 저는 이미 테오크리투스를 위한 일에 매여 있어서 당신을 떠올렸죠! 부디 시간을 내어 주시길 바랍니다.\n\n부디 라벤홀트에서 얼라이언스를 대표해 주십시오, $N. 하지만 그곳에서 발견할 것들을 조심하십시오. 그곳은 비밀과 스파이, 그리고 고수로 가득합니다. 고수는 비누 맛이 납니다. 역겹군요!",
    },
    [28020] = {
        ["T"] = "심연의 의식",
        ["O"] = "먼지진흙 습지대에 있는 내트 페이글과 대화하십시오.",
        ["D"] =
        "손에 낚싯대를 쥐고 물가에서 쉬는 것보다 더 좋은 일은 없죠, 안 그런가요 $N? 당신이 내가 아는 가장 헌신적인 $g어부:어부; 중 한 명이니 당신도 동의할 거라 믿습니다!\n\n아, 그러고 보니 생각나네요 -- 최근 먼지진흙 습지대에서 함께 낚시를 하자는 내트 페이글의 초대를 받았습니다. 솜씨를 겨룰 재능 있는 낚시꾼들을 원하고 있는 것 같더군요. 당신은 어떤 낚시 대회에든 꼭 끼어야 할 사람입니다. 먼지진흙 습지대로 가서 한번 확인해 보는 게 어때요?",
    },
    [28021] = {
        ["T"] = "심연의 의식",
        ["O"] =
        "먼지진흙 습지대의 내트 페이글은 당신이 낚시 기술을 사용하여 돌비늘장어 20마리와 무쇠비늘 철갑어 10마리를 낚기를 원합니다.",
        ["D"] =
        "최근에 몸이 좀 쑤시더군요, $N. 당신이 와줘서 다행입니다. 제 실력을 조금 더 키우고 싶었거든요. 정확히 어떻게 해야 할진 모르겠지만, 가벼운 친선 경쟁으로 시작해 볼 수 있지 않을까요?\n\n돌비늘장어와 무쇠비늘 철갑어를 낚은 제 기록을 깰 수 있는 사람이 있을지 항상 궁금했습니다. 당신이 직접 한번 시도해 보시겠소?",
    },
    [28022] = {
        ["T"] = "심연의 의식",
        ["O"] = "아즈샤라 검은아귀 마을에 있는 위플라와 대화하십시오.",
        ["D"] =
        "열렬한 낚시꾼이라면 아즈샤라의 검은아귀 마을에 가보신 적이 있을 겁니다. 안 가보셨다면 정말 큰 손해를 보고 계신 거예요! 아즈샤라 북쪽 해안에 있는 펄볼그 마을인데, 그들은 낚시에 아주 미쳐있죠.\n\n어쨌든, 분위기를 좀 띄워줄 새 미끼가 필요할 것 같네요. 전 항상 검은아귀 부족의 솜씨에 감탄해 왔거든요. 그곳으로 가서 그들의 미끼 하나를 구해다 주시겠어요?",
    },
    [28023] = {
        ["T"] = "심연의 의식",
        ["O"] =
        "검은아귀 마을의 위플라는 스내피쿠스 렉스라는 랍스트로크에게서 검은아귀 미끼를 되찾기를 원합니다. 미끼를 구한 후, 먼지진흙 습지대의 내트 페이글에게 전달하십시오.",
        ["D"] =
        "검은아귀 미끼 원한다? 그래, 우리 미끼 낚시에 아주 좋다. 하지만 손으로 만든 미끼는 검은아귀에게 아주 개인적인 것. 거저 주기 쉽지 않다.\n\n위플라 생각에 너 자격 증명하면 검은아귀 미끼 가져갈 수 있다. 위플라 가장 좋아하는 미끼 크고 나쁜 랍스트로크가 가져갔다. 고블린들 랍스트로크를 스내피쿠스 렉스라 부른다. 그놈 아즈샤라 온통 헤엄친다. 스내피쿠스 찾으면, 그놈한테 미끼 빼앗아라, 그럼 네가 가져도 좋다.",
    },
    [28024] = {
        ["T"] = "심연의 의식",
        ["O"] =
        "동부 역병지대 스트라솔름 안에 있는 베이베리 여관을 뒤져 존 킨케이드의 태클 상자를 찾은 후 먼지진흙 습지대의 내트 페이글에게 가져가십시오.",
        ["D"] =
        "스트라솔름의 비극에서 죽은 친구가 한 명 있었소. 존은 좋은 친구였고, 당신이 본 것 중 가장 놀라운 미끼 수집품을 가지고 있었지. 가능성은 희박하지만, 그 미끼들이 아직 그곳에 있을지 궁금하군.\n\n존은 마을 북쪽에 있는 베이베리 여관을 소유하고 있었소. 마을의 상당 부분이 불탔다고 들었지만, 존은 튼튼한 태클 상자에 미끼를 보관했으니 어떤 불길에도 살아남았을 거요.\n\n물론 이게 너무 무리한 부탁이라면 이해하오. 그 폐허는 아마 여전히 위험할 테니까.",
    },
    [28025] = {
        ["T"] = "심연의 의식",
        ["O"] =
        "내트 페이글은 당신이 낚시 기술을 사용하여 날 용암해골어 10마리를 낚아 먼지진흙 습지대에 있는 자신에게 가져오기를 원합니다.",
        ["D"] =
        "이 태클 상자가 불러일으킨 모든 추억을 떠올릴 시간이 조금 필요할 것 같소. 하지만 그러는 동안 당신에게 부탁할 게 하나 있소.\n\n이 태클 상자를 구해온 걸 보니 당신은 불을 두려워하지 않는 것 같군. 음, 불은 바로 용암해골어를 잡는 곳이지. 그렇소 -- 용암 낚시 말이오.\n\n뜨거운 열기를 견딜 수 있는 낚싯대가 없다면, 검은무쇠 드워프들과 시간을 좀 보내며 낚싯대를 업그레이드해야 할 거요.",
    },
    [28026] = {
        ["T"] = "심연의 의식",
        ["O"] = "실리더스의 생물들에게서 이국적인 실리시드 미끼 10개를 모은 후, 먼지진흙 습지대의 내트 페이글에게 가져가십시오.",
        ["D"] =
        "아, 그래요. 미끼!\n\n세상에서 가장 좋은 낚시용 가짜 미끼라도 그에 걸맞은 진짜 미끼가 없다면 소용이 없지. 큰지렁이나 반딧벌레부터 미친 기계공학 장치까지 다 써봤소. 어느 정도 효과는 있었지만, 좀 더... 이국적인 게 필요한 것 같소. 머나먼 땅에서 온, 독특한 향신료가 가미된 무언가 말이오. 진정으로 특이한 미끼로 무엇을 낚을 수 있을지 누가 알겠소? 좋은 생각 있소?",
    },
    [28027] = {
        ["T"] = "심연의 의식",
        ["O"] = "이국적인 실리시드 미끼를 사용하여 내트 페이글과 함께 낚시를 하고 무엇을 낚는지 확인하십시오!",
        ["D"] =
        "음, 이 미끼를 빨리 써보고 싶군. 미끼를 바늘에 꽂아둘 테니 준비되면 말해주시오. 우리가 뭘 낚을지 누가 알겠소?",
    },
    [28028] = {
        ["T"] = "들판의 의식",
        ["O"] = "달숲의 밤의 안식처에 있는 덴드리트 스타블레이즈와 대화하십시오.",
        ["D"] =
        "음, 약초채집 기술을 정말 잘 연마하셨군요, 그렇지 않나요? 당신처럼 재능 있는 분이 들르는 일은 흔치 않습니다.\n\n사실 부탁드리고 싶은 게 하나 있습니다. 달숲에 식물의 타락 영향을 연구하는 친구가 한 명 있습니다. 그는 악령숲과 역병지대를 오가는 일에 지쳐 조수가 필요하다고 하더군요. 관심이 있으시다면 밤의 안식처로 가서 덴드리트 스타블레이즈와 대화해 보십시오.\n\n달숲에 가본 적이 없으시다면, 악령숲에 있는 나무구렁 펄볼그의 영역을 지나야만 도착할 수 있습니다. 펄볼그들은 낯선 이에게 친절하지 않지만, 통과할 방법을 찾으실 수 있을 거라 믿습니다.",
    },
    [28029] = {
        ["T"] = "들판의 의식",
        ["O"] =
        "덴드리트 스타블레이즈는 당신이 약초채집 기술을 사용하여 은초롱이 20개와 얼음송이 20개를 모아 달숲 밤의 안식처에 있는 자신에게 가져오기를 원합니다.",
        ["D"] =
        "제 연구를 돕는 데 관심이 있으시다고요? 아주 훌륭합니다. 해야 할 일은 많은데 세상 모든 시간을 가질 순 없게 되었거든요.\n\n도와주시려는 마음은 감사하지만, 먼저 당신의 기술을 평가해 봐야겠습니다. 은초롱이와 얼음송이를 채집하여 약초채집 능력을 보여주십시오. 그러면 앞으로 있을 임무에 필요한 재능을 갖추고 있는지 알 수 있을 것입니다.",
    },
    [28030] = {
        ["T"] = "들판의 의식",
        ["O"] =
        "동부 내륙지의 진타알로로 여행하여 썩은가지부족 약초채집사에게서 썩은 낫을 구하십시오. 달숲 밤의 안식처에 있는 덴드리트 스타블레이즈에게 가져가십시오.",
        ["D"] =
        "제가 연구하려는 표본을 수확하려면 위험한 식물을 채집하기 위한 특별한 도구가 필요합니다. 줄구룹의 구루바시 트롤들이 위험한 식물을 수확하기 위한 특별한 낫을 가지고 있다고 들었습니다만, 줄구룹은 현재 폐쇄되었으니 다음으로 좋은 것을 찾아야겠죠.\n\n진타알로의 썩은가지부족 트롤 중 뛰어난 약초채집사가 있다고 합니다. 구루바시의 사촌격이니, 아마 이 약초채집사도 비슷한 도구를 가지고 있지 않을까요?",
    },
    [28031] = {
        ["T"] = "들판의 의식",
        ["O"] =
        "달숲 밤의 안식처에 있는 덴드리트 스타블레이즈를 위해 실리더스의 하이브와 동굴에서 균사초 10개를 채집하여 썩은 낫을 시험해 보십시오.",
        ["D"] =
        "이제 썩은 낫을 얻었으니 타락한 식물에 시험해 봐야 합니다. 당신을 최종 목표지로 보내기 전에 이것이 효과적인지 확인하고 싶습니다.\n\n남쪽 멀리 실리더스라는 땅에 세나리온 의회의 지원을 받는 연구 원정대가 있습니다. 그들은 그곳의 동굴과 하이브에서 자라나는 이상하게 변형된 버섯을 보고했습니다. 이 썩은 낫을 가져가서 그 진균을 채집해 오십시오. 원정대는 그것을 균사초라 이름 붙였습니다. 낫이 타락을 퍼뜨리지 않고 안전하게 그것들을 수집할 수 있는지 확인하십시오.",
    },
    [28032] = {
        ["T"] = "들판의 의식",
        ["O"] =
        "덴드리트 스타블레이즈는 당신이 약초채집 기술을 사용하여 야생덩굴 20개, 실명초 20개, 검은 연꽃 1개를 모아 달숲 밤의 안식처에 있는 자신에게 가져오기를 원합니다.",
        ["D"] =
        "당신을 아무런 준비 없이 위험에 빠뜨릴 수는 없습니다. 따라서 우리가 해야 할 마지막 일이 있습니다 -- 만약의 사태를 대비해 당신을 위한 확실한 해독제를 준비하는 것입니다.\n\n여기 밤의 안식처에 필요한 대부분의 재료가 있고 조제하는 데 시간이 좀 걸립니다. 혼합물을 완성하려면 야생덩굴, 실명초, 그리고 검은 연꽃 약간만 있으면 됩니다. 당신은 숙련된 약초채집사이니 그 재료들을 구하는 건 문제없으시겠죠?",
    },
    [28033] = {
        ["T"] = "들판의 의식",
        ["O"] =
        "서부 역병지대의 스칼로맨스로 여행하여 달숲 밤의 안식처에 있는 덴드리트 스타블레이즈를 위해 역병지대 파리매초 표본을 수집하십시오.",
        ["D"] =
        "이제 해독제가 끓고 있으니 우리의 최종 목표를 밝힐 수 있겠군요.\n\n저주받은 자들의 교단이 서부 역병지대에서 끔찍한 짓을 저지르고 있습니다. 저는 그곳의 땅을 연구하며 시간을 보냈죠. 치유할 수는 있지만, 교단이 스칼로맨스 시설에서 타락한 식물을 계속 퍼뜨리는 한 불가능합니다.\n\n그 식물들이 뿌리내리고 퍼지는 것을 막으려면 그들의 타락한 식물 표본이 필요합니다. 스칼로맨스로 들어가 이 표본을 가져오시고, 교단의 식물을 한 번에 제거해 주십시오!",
    },
    [28034] = {
        ["T"] = "사냥의 의식",
        ["O"] = "불모의 땅 통곡의 동굴 서쪽 야영지에 있는 피즈너클과 대화하십시오.",
        ["D"] =
        "반갑습니다, $N. 당신처럼 고급 기술을 가진 가죽세공사에게 전할 메시지가 있습니다.\n\n피즈너클이라는 고블린이 불모의 땅 통곡의 동굴 서쪽에 있는 외딴 야영지에서 상점을 운영하고 있습니다. 그는 수수료를 받고 일할 의향이 있는 재능 있는 가죽세공사를 찾고 있습니다. 관심이 있으실지 모르겠지만, 일단 메시지는 전해드리는 게 좋겠군요.",
    },
    [28035] = {
        ["T"] = "사냥의 의식",
        ["O"] =
        "피즈너클은 당신이 가죽세공 기술을 사용하여 정제된 깊은바위 소금 5개와 튼튼한 방어구 키트 20개를 만든 다음, 불모의 땅 통곡의 동굴 서쪽에 있는 그의 야영지로 가져오기를 원합니다.",
        ["D"] =
        "고급 가죽 제품의 공급자로서, 전 항상 특별한 기술을 가진 공급업체를 찾고 있습니다. 특히 제 상점이 이 멀리까지 와 있으니까요... 마을에서 더 이상 환영받지 못하거든요... 이유는 묻지 마시고요.\n\n당신이 와줘서 기쁩니다, $N. 유망한 제작자로서 당신 이름을 들은 적이 있죠. 제가 찾고 있는 기술이 있는지 확인해 보고 싶은데, 정제된 깊은바위 소금 몇 개와 튼튼한 방어구 키트 한 묶음을 만들어 주시겠어요?\n\n소금을 정제하는 법을 모른다면 기계공학자의 도움이 필요할 겁니다.",
    },
    [28036] = {
        ["T"] = "사냥의 의식",
        ["O"] =
        "피즈너클은 당신이 가죽세공 기술을 사용하여 야생 가죽 망토 4개를 제작하고 악령숲 에메랄드 성소에 있는 아이비 리프러너에게 배달하기를 원합니다.",
        ["D"] =
        "이제 당신이 일을 감당할 수 있다는 걸 알았으니, 첫 번째 계약을 드리죠.\n\n야생 가죽 망토를 만드는 방법은 아시겠죠? 악령숲에 있는 괴짜 고객이 망토를 4개나 원하고 있습니다. 왜 4개나 필요한지는 모르겠고, 묻지도 않았습니다! 하지만 당신에게 그 망토를 만들어 에메랄드 성소에 배달하라고 말씀드리는 겁니다.\n\n망토를 만드는 법을 모른다면, 페더문 요새의 프랫 맥그루벤이나 모자케 야영지의 장도르 스위프트스트라이더를 찾아가 보세요. 둘 다 페랄라스에 있습니다. 가본 적이 없다면 말이죠.",
    },
    [28037] = {
        ["T"] = "사냥의 의식",
        ["O"] =
        "악령숲 에메랄드 성소에 있는 아이비 리프러너를 위해 여명의 설원의 눈망루 펄볼그에게서 눈망루 가죽 제품 6개를 모으십시오.",
        ["D"] =
        "저는 독특한 가죽 제품을 수집하는 사람입니다, $N. 특히 역사나 우리 민족에게 어떤 의미가 있는 물건이라면 더욱 그렇죠.\n\n칼도레이는 한때 여명의 설원의 펄볼그 부족과 우호적인 관계를 유지했지만, 전쟁 이후 펄볼그들은 타락의 구렁텅이에 빠졌습니다. 그들은 과거에 유명했던 아름다운 가죽 공예품을 더 이상 만들지 않으며, 여전히 가지고 있는 많은 물건들도 쓸모없이 방치되어 있습니다.\n\n저는 언젠가 이 땅을 타락에서 정화했을 때, 펄볼그들이 본받을 수 있는 모범이 될 수 있도록 그 가죽 제품 중 일부를 보존하고 싶습니다. 경험 많은 가죽세공사로서 당신은 무엇을 찾아야 할지 알 것입니다. 저를 위해 대여섯 개 정도 구해 주시겠습니까?",
    },
    [28038] = {
        ["T"] = "사냥의 의식",
        ["O"] =
        "악령숲 에메랄드 성소에 있는 아이비 리프러너를 위해 검은바위 첨탑 상층의 성난발톱용혈족에게서 용가죽 북 4개를 모으십시오.",
        ["D"] =
        "수천 년 전, 검은용군단의 일원들은 그들의 지도자 넬타리온과 함께 타락하기 전에는 건축가, 장인, 재봉사들이었습니다. 그 시절과 그 후에 이어진 고통에 대해 생각하지 않은 지 꽤 오래되었군요.\n\n동부 왕국에서 온 보고에 따르면 검은용군단이 검은바위 산 근처의 구 호드 잔당들과 동맹을 맺었다고 합니다. 그들이 여전히 가죽세공 기술을 연마하고 있는지 알고 싶습니다. 만약 그렇다면 샘플도 몇 개 얻고 싶군요. 그곳으로 가서 저를 위해 조사해 주실 수 있겠습니까?",
    },
    [28039] = {
        ["T"] = "사냥의 의식",
        ["O"] = "불모의 땅 통곡의 동굴 서쪽에 있는 피즈너클의 야영지에서 그와 대화하십시오.",
        ["D"] =
        "아... 하마터면 잊을 뻔했군요! 잠시 추억에 잠겨 있었네요. 당신이 일하는 그 고블린이 메시지를 보냈어요. 가능한 한 빨리 그의 야영지로 돌아오길 바라더군요. \"오래전 잃어버린 가죽세공 도면\"에 관한 이야기라는데, 꽤 흥미롭네요. 무엇을 찾았는지 꼭 알려주세요!",
