    [28040] = {
        ["T"] = "사냥의 의식",
        ["O"] =
        "불모의 땅의 피즈너클을 위해 실리더스 마파람 마을의 고문당한 드루이드들에게서 고대 도면의 조각 5개를 모으십시오.",
        ["D"] =
        "이건 아주 뜨거운 정보야. 저 멀리 남쪽 사막을 탐험하는 바보들의 보고서에서 막 입수한 거지. 듣자 하니 나이트 엘프 유령으로 가득한 마을을 발견했는데, 그중 일부가 고대 가죽세공 도면 조각을 가지고 다닌대! 빈티지 제품의 마진이 얼마나 될지 상상해 보라고!\n\n그러니 다른 사람이 이 정보를 채가기 전에 직접 실리더스라는 곳으로 가. 그래, 넌 가죽세공사지만 동시에 $C이기도 하지 -- 그 기술을 활용할 때야.",
