    [28041] = {
        ["T"] = "비늘 제작자",
        ["O"] =
        "카라나는 당신이 전 세계에서 다양한 비늘을 수집하기를 원합니다. 전문가인 당신은 올바른 비늘이 검은용 비늘 5개, 두꺼운 전갈 딱지 5개, 두꺼운 바실리스크 비늘 5개, 거북 등딱지 5개일 것이라 생각합니다. 이것들을 모아 슬픔의 늪의 은신처에 있는 카라나에게 돌아가십시오.",
        ["D"] =
        "아칼 헥타, 방랑자여. 당신은 가죽세공사가 맞습니까? 그렇다면 서로 유익한 합의에 이를 수 있을 것 같군요. 지금은 아웃랜드로 알려진... 드레노어에서, 저는 대부분 멸종했을 법한 무수한 생물들로 아름다운 비늘 갑옷을 만들곤 했습니다. 하지만 이 세상에는 제가 세공할 수 있는 새로운 비늘이 많이 있군요.\n\n이 세상 곳곳에서 다양한 비늘을 가져다주셨으면 합니다. 제 요구가 크다는 것은 알지만, 그에 대한 보답으로 제 소중한 도면 중 하나를 드리겠습니다.",
    },
    [28042] = {
        ["T"] = "산맥의 의식",
        ["O"] = "저주받은 땅에 있는 카에르나 시버스톤과 대화하십시오.",
        ["D"] =
        "$N! 방금 제 친구에게서 긴급한 메시지를 받았습니다. 대지의 부름에 각별한 관심을 가진 주술사죠. 당신은 경험 많은 광부이시죠? 그녀가 상담하고 싶어 하는 사람이 바로 당신 같은 사람입니다.\n\n도울 의향이 있으시다면 저주받은 땅의 네더가드 요새에 있는 카에르나 시버스톤을 찾아가 보십시오.",
    },
    [28043] = {
        ["T"] = "산맥의 의식",
        ["O"] =
        "저주받은 땅 네더가드 요새의 카에르나 시버스톤을 위해 저주받은 땅의 단층선에서 끓어오르는 광석을 채광하십시오.",
        ["D"] =
        "대지의 고통을 달래기 위해 광부의 도움을 구한다는 것이 이상하게 들릴 거라는 걸 압니다. 우리 주술사들은 광업을 고통의 원인으로 여길 때가 많으니까요. 하지만 이번에는 당신의 광물 채광 기술이 꼭 필요하다는 걸 느낍니다.\n\n저주받은 땅의 돌들이 울부짖는 소리가 들립니다. 뭔가 고대의 것이 깊은 곳에서 꿈틀거리고 있어요. 대지의 갈라진 틈에서 무언가 스며 나오고 있습니다. 저주받은 땅으로 가서 땅속에서 무엇이 부글거리며 올라오는지 확인해 주십시오.",
    },
    [28044] = {
        ["T"] = "산맥의 의식",
        ["O"] =
        "신비한 수정 하나, 아제로스 다이아몬드 하나, 거대한 오팔 하나, 그리고 검은무쇠 주괴 10개를 저주받은 땅 네더가드 요새의 카에르나 시버스톤에게 가져가십시오.",
        ["D"] =
        "말씀드렸다시피, 이 광석은 제가 전에 본 어떤 것과도 다르지만, 검은바위 산 깊은 곳에서 발견되는 검은무쇠와 일부 유사한 점이 있습니다. 더 관련이 깊은 것은 산을 관통해 흐르는 용암이죠. 용암 역시 어두운 영혼을 가지고 있습니다. 표본을 비교해보고 싶지만, 먼저 그것을 담을 수 있는 도가니를 만들어야 합니다.\n\n그러기 위해선 당신이 얻기에 가장 적합한 몇 가지 재료가 필요합니다. 초점 역할을 할 신비한 수정, 내부를 코팅할 아제로스 다이아몬드와 거대한 오팔, 그리고 틀을 잡을 검은무쇠 주괴입니다.",
    },
    [28045] = {
        ["T"] = "산맥의 의식",
        ["O"] =
        "검은바위 산의 검은바위 나락으로 들어가 검은무쇠 도가니를 사용해 검은 가열로 근처의 용암에서 표본을 채취한 후, 저주받은 땅 네더가드 요새의 카에르나 시버스톤에게 가져가십시오.",
        ["D"] =
        "이제 검은바위 산에서 용암 표본을 수집할 장비를 갖추셨군요. 검은무쇠 드워프들이 산의 심장부 근처에 자신들만의 가열로, 즉 Black Forge를 가지고 있다고 들었습니다. 그 가열로에 가까이 가서 표본을 얻을수록 더 좋습니다.\n\n조심하십시오, $N. 요즘 어둠괴철로 도시는 배신, 폭력배, 도둑, 이교도들로 가득하다고 들었습니다.",
    },
    [28046] = {
        ["T"] = "산맥의 의식",
        ["O"] = "운고로 분화구에서 야루니 파이어워처를 찾으십시오.",
        ["D"] =
        "이 표본을 수집해주신 노력에는 감사드리지만, 대지가 겪는 고통의 근원에 대해서는 여전히 알 수가 없군요. 다른 의견을 구해봐야겠습니다.\n\n제 동료 중 한 명이 운고로 분화구 연구 원정대와 동행했습니다. 야루니가 지금 정확히 어디 있는지 모르겠지만, 그는 이 표본을 평가해줄 수 있는 최고의 전문가입니다.\n\n부디 이 끓어오르는 광석을 가지고 그를 찾아주십시오.",
    },
    [28047] = {
        ["T"] = "산맥의 의식",
        ["O"] =
        "운고로 분화구 마샬의 야영지에 있는 야루니 파이어워처를 위해 실리더스에서 웅웅거리는 광석 10개를 채광하십시오.",
        ["D"] =
        "칼림도어의 이 지역으로 모험을 떠난 탐험대는 마샬 원정대뿐만이 아니었습니다. 이곳에서 실리더스라는 사막으로 계속 나아간 세나리온 의회의 무리가 있었습니다. 그들로부터 들려오는 소식은 드물고 산발적이었지만, 한 메시지에서 분노한 망자들의 영혼과 웅웅거리는 하이브로 가득 찬 땅에 대한 언급이 있었습니다.\n\n저주받은 땅에서 그토록 멀리 떨어진 그곳의 대지도 같은 분노를 보여주고 있는지 궁금합니다. 그 방향에서 무언가 뿜어져 나오는 것을 느낄 수 있지만, 저의 불에 대한 연결이 대지에 대한 연결보다 훨씬 강합니다. 실리더스에서 표본을 좀 가져다주시면 더 많은 것을 알아낼 수 있을지도 모릅니다.",
