    [28048] = {
        ["T"] = "산맥의 의식",
        ["O"] =
        "운고로 분화구 마샬의 야영지에 있는 야루니 파이어워처는 당신이 웅웅거리는 광석 표본을 저주받은 땅 네더가드 요새의 카에르나 시버스톤에게 가져가기를 원합니다.",
        ["D"] =
        "카에르나가 직접 비교해 볼 수 있도록 이 표본을 그녀에게 가져가야 합니다. 대지와의 유대감은 그녀가 저보다 훨씬 깊으니까요.\n\n이 수수께끼를 가져다주셔서 감사합니다, $N. 대지 고리회는 이제 어떤 조치를 취해야 할지 논의할 것입니다.",
