        ["D"] =
        "소식 들었습니까, $N? 전설적인 사냥꾼 헤멧 네싱워리가 트로피 제작을 도울 정예 무두장이를 찾고 있다고 합니다!\n\n경력에 넣기엔 이보다 완벽한 일자리가 없죠! 관심 있으시면 가시덤불 골짜기에 있는 네싱워리의 야영지로 직접 찾아가 지원해 보세요.",
