        ["O"] =
        "검은용 비늘 하나, 푸른용 비늘 하나, 녹색용 비늘 하나, 붉은용 비늘 하나를 가시덤불 골짜기 네싱워리 원정대의 헤멧 네싱워리에게 가져가십시오.",
        ["D"] =
        "아무 무두장이한테나 이 일을 맡길 순 없지, $N. 그러니 자네 실력을 증명해 보게.\n\n난 아제로스에서 가장 위험한 짐승들을 사냥해 왔고, 그중 가장 교활한 것은 용이라네. 자네가 용을 직접 사냥할 필요는 없지만, 용가죽을 몇 장 벗겨서 무두질용 칼을 다룰 줄 안다는 증거로 내게 용비늘을 가져오게나. 검은용, 푸른용, 녹색용, 붉은용의 비늘을 각각 하나씩 원하네.",
