    [28051] = {
        ["T"] = "야생의 의식",
        ["O"] =
        "헤멧 네싱워리는 당신이 무두질 기술을 사용해 여명의 설원 눈호랑이에게서 극도로 두꺼운 눈호랑이 가죽 6개를 모아 가시덤불 골짜기의 야영지로 가져오기를 원합니다.",
        ["D"] =
        "최고급 야수 가죽 몇 개를 구입하는 동안 자신의 익명성을 유지하고 싶어 하는 고객이 있네. 경쟁이 공론화될까 봐 걱정하는 모양이야.\n\n가장 먼저 구해달라고 요청받은 건 여명의 설원의 최고급 눈호랑이 가죽이라네. 아무 가죽이나 가져오면 안 돼. 고객은 가장 두껍고 따뜻한 가죽만을 원하네. 자네 이 일을 할 수 있겠나? 여러 임무 중 제일 쉬운 일이야.",
    },
    [28052] = {
        ["T"] = "야생의 의식",
        ["O"] =
        "헤멧 네싱워리는 당신이 무두질 기술을 사용해 실리더스의 시추벌레에게서 시추벌레 가죽 6개를 모아 가시덤불 골짜기의 야영지로 가져오기를 원합니다.",
        ["D"] =
        "다음 임무는 자네가 좀 부럽군. 저 멀리 서쪽에 실리더스라는 새로운 땅이 발견되었다지. 우리 고객이 그곳 생물들로부터 독특한 가죽을 얻을 수 있다는 정보를 입수한 모양이야. 고객은 그것들을 \"벌레 같은\" 것이라 설명하더군.\n\n직접 가보고 싶을 정도로 흥미가 동하지만, 어딜 가기 전에 이 골짜기에서 끝내야 할 일들이 남아 있어서 말이야. 게다가 이 실리더스라는 곳은 극도로 위험하다더군. 하지만 때때로 자신을 시험하지 않는 사냥꾼이 무슨 소용이겠나?",
