    [28053] = {
        ["T"] = "야생의 의식",
        ["O"] =
        "헤멧 네싱워리는 당신이 무두질 기술을 사용하여 검은바위 첨탑 하층에서 할리콘의 가죽을 모아 가시덤불 골짜기의 야영지로 가져오기를 원합니다.",
        ["D"] =
        "고객이 이 정보를 어디서 얻었는지는 모르겠지만, 검은바위 첨탑의 오크들이 늑대 기수들의 탈것을 제공하기 위해 거대한 늑대 한 쌍을 번식시키고 있다는군. 그리고 우리 고객은 그놈들의 가죽을 원하네. 더 구체적으로 말하자면, 할리콘이라는 이름의 늑대 가죽이지.\n\n자네가 어떻게 검은바위 첨탑에 들어가 이 늑대를 찾아 가죽을 벗길지 모르겠지만, 성공만 한다면 우리 둘 다에게 아주 두둑한 보상이 떨어질 걸세.",
    },
    [28054] = {
        ["T"] = "야생의 의식",
        ["O"] = "가죽 꾸러미를 가시덤불 골짜기 무법항의 남작 레빌가즈에게 전달하십시오.",
        ["D"] =
        "자네가 떠난 사이 고객에게 자네의 훌륭한 솜씨에 대한 메시지를 보냈지. 글쎄, 고객이 자네를 직접 만나 감사를 표하고 싶다더군.\n\n짐작했겠지만, 고블린이라네. 바로 남쪽의 무법항에 있지. 남작 레빌가즈라는 자일세. 보아하니 스팀휘들 무역회사의 꽤 높은 사람인 것 같군. 거기로 가는 김에 자네가 모은 가죽들도 그에게 배달해 주게나.",
