        ["D"] =
        "오, $N! 들러주셔서 기뻐요. 아제로스 최고의 디자이너 중 한 명인 거만한 의류상이 숙련된 재봉술 조수를 찾고 있다는 소식을 최근에 들었거든요. 당신의 작품을 본 적이 있어서 이 기회에 대해 들으면 관심이 있을 거라 생각했어요.\n\n관심이 있다면, 현재 그녀는 타나리스 남쪽에 있는 스팀휘들 항구에 자리를 잡고 있습니다.",
    },
    [28056] = {
        ["T"] = "베틀의 의식",
        ["O"] =
