        ["D"] =
        "당신이 조수인가요? 뭐, 찬밥 더운밥 가릴 처지는 아니죠.\n\n도움이 필요하다는 걸 인정하긴 싫지만, 사실이에요. 상점을 차리기 위해 붉은해적단에게 자금을 좀 빌렸는데, 여윳돈을 버는 속도보다 빚 갚을 날짜가 더 빨리 다가오고 있거든요. 패션의 최첨단을 유지하려면 수익을 투자해야 하는데 -- 바로 여기서 당신이 필요해요.\n\n내 일을 무료로 조금만 도와주면, 이력서에 그 전설적인 거만한 의류상과 함께 일했다고 적을 수 있게 해줄게요! 이 룬무늬 가방 주문을 채우는 것부터 시작하시죠.",
    },
    [28057] = {
        ["T"] = "베틀의 의식",
        ["O"] =
        "타나리스의 스팀휘들 항구에 있는 거만한 의류상을 위해 역병지대에서 발견되는 거미들에게서 강철그물 거미줄 5개와 괴저 거미줄 5개를 구하십시오.",
        ["D"] =
        "그건 식은 죽 먹기였네요! 다음 주문은 거미에 집착하는 트롤들을 위한 거예요. 디자인에 거미줄을 원하는데, 다 떨어졌지 뭐예요. 그러니 역병지대로 가서 거미줄 좀 더 구해오는 게 어때요? 거기 거미들은 엄청 크고 거미줄도 훌륭하다고 들었거든요. 튼튼한 거미줄과 이국적인 거미줄이 좀 필요해요. 해낼 수 있죠?",
