    [28058] = {
        ["T"] = "베틀의 의식",
        ["O"] =
        "톨 바라드 섬의 바라딘 요새로 들어가 글라구트를 처치한 다음, 타나리스 스팀휘들 항구의 거만한 의류상에게 돌아가십시오.",
        ["D"] =
        "자, 이 거래는... 당신의 도움과 $C로서의 기술이 필요해요.\n\n내가 그들을 위해 문제를 하나 처리해 주면 붉은해적단이 내 빚의 절반을 탕감해 주겠다고 했어요. 그 문제란? 한때 붉은해적단이었지만 배신하고 다른 함대에 합류한 글라구트라는 오우거 배신자죠. 해적들은 배신자를 곱게 보지 않는 것 같죠?\n\n어쨌든, 글라구트의 새 함대는 아마 아라시 고원 앞바다의 톨 바라드 섬을 항해하고 있을 거예요. 이런 모험 같은 건 제 특기가 아니니, 당신에게 위임할게요.",
    },
    [28059] = {
        ["T"] = "베틀의 의식",
        ["O"] =
        "거만한 의류상은 당신이 재봉술을 사용하여 영혼 주머니 2개와 달빛 옷감 2개를 제작하여 타나리스의 스팀휘들 항구에 있는 자신에게 가져오기를 원합니다.",
        ["D"] =
        "이 다음 주문을 넣은 커플은 정말 귀여웠어요! 정반대의 매력이랄까요... 그 나이트 엘프는 확실히 사제였고 달빛 옷감을 원했어요. 하지만 그녀의 여자친구는? 완전 흑마법사 느낌이었죠. 영혼 주머니 두 개를 주문했거든요.\n\n이 일은 당신을 믿고 맡길게요. 이제 제 빚을 청산할 날이 머지않았어요. 끝까지 버텨준다면, 당신이 저를 도왔다는 걸 확실히 말해줄게요.",
    },
    [28060] = {
        ["T"] = "베틀의 의식",
        ["O"] =
        "타나리스의 스팀휘들 항구에 있는 거만한 의류상을 위해 실리더스의 황혼의 망치단 이교도에게서 희미하게 빛나는 황혼의 옷감 8개를 구하십시오.",
        ["D"] =
        "실리더스 사막이 정확히 어디 있는지 몰라요. 붉은해적단 말로는 타나리스에서 서쪽, 한참 서쪽이라고 하더군요. 해적들이 그곳에 사는 이교도들과 원한 관계인 것 같아요. 장막의 바다에서 배를 집어삼키기 위해 심해의 야생 정령들을 소환한다는 둥 뭐라는 둥... 패션에 관한 얘기가 아니면 대화 흐름을 놓칠 때가 있거든요.\n\n제 관심을 끈 건 그 이교도들이 자신들만의 천을 짠다는 거예요. 붉은해적단은 그걸 희미하게 빛나는 황혼의 옷감이라고 불렀어요. 그들은 원한을 갚기 위해 이교도들을 죽이길 원하고, 전 이 천을 원해요. 그러니 8개의 희미하게 빛나는 황혼의 옷감을 모을 때까지 이교도들을 처치하세요. 그럼 제 빚을 모두 청산할 수 있을 거예요!",
    },
    [28061] = {
        ["T"] = "베틀의 의식",
        ["O"] =
        "거만한 의류상은 당신이 재봉술을 사용하여 함장 모자를 제작하여 타나리스의 스팀휘들 항구에 있는 자신에게 가져오기를 원합니다.",
        ["D"] =
        "자... 아주 작고 사소한 일 하나만 더 해주면 붉은해적단이 제 빚을 완전히 갚은 것으로 쳐주겠대요. 그건 바로 그들의 우두머리를 위해 함장 모자를 만들어 주는 거예요.\n\n불행히도 이 모자가 어떻게 생겼는지 전혀 몰라요! 아마 가시덤불 골짜기에 있는 해적 재봉사가 패턴을 팔 테지만, 전 동부 왕국에 가본 적도 없고 정령들이 배를 통째로 삼킨다는 얘기를 듣고 나선 절대 배에 오르지 않을 거예요.\n\n그러니 당신에게 달렸어요, $N. 함장 모자를 만들어 줘요. 그럼 전 자유로워질 테고, 당신은 쬐금 더 유명해지겠죠.",
    },
    [28062] = {
        ["T"] = "그렘록 필스노르의 주문",
        ["O"] =
        "그렘록 필스노르는 당신이 요리 기술을 사용하여 늑대 양념 구이 10개를 제작한 다음, 던 모로의 카라노스에 있는 그렘록 필스노르에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "여보게, $N! 든든한 식사와 맥주 한잔하러 여관에 왔나? 음, 나쁜 소식이 있네 -- 오늘의 특선 요리인 늑대 양념 구이가 다 떨어졌어.\n\n자네도 요리를 좀 할 줄 알지 않나? 자네가 오늘의 특선 요리 만드는 걸 도와준다면, 생고기를 자네 몸무게만큼이라도 기꺼이 주겠네! 어떤가, 거래할 텐가?",
