        ["D"] =
        "어이 거기. 너 요리사야? 튜닉에 묻은 기름때를 보고 짐작했지.\n\n저 동쪽에는 용들이 우글거리는데 가끔 불을 뿜어대지. 부러워죽겠어! 하지만 그걸 흉내 낼 방법이 있지.\n\n용숨결 칠리. 들어본 적 있어? 나도 용처럼 불을 뿜을 수 있게 좀 만들어 줘, 그럼 아주 행복한 고블린이 될 테니.",
