        "게르날 버치는 당신이 요리 기술을 사용하여 비단잉어 구이 10개를 제작한 다음, 티리스팔 숲의 브릴에 있는 여관의 게르날 버치에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "휴! 정말 바쁜 하루였소. 불앞에 너무 오래 있어서 나 자신은 한 입도 먹지 못했지 뭐요.\n\n혹시 좀 도와줄 수 있소? 프라이팬 다루는 솜씨가 제법이던데, 비단잉어 구이 한 접시를 부탁하고 싶소. 그걸 해주면 내 특별한 요리 재료와 교환해 주겠소. 거래하겠소?",
    },
    [28080] = {
        ["T"] = "라르카의 주문",
        ["O"] =
        "라르카는 당신이 요리 기술을 사용하여 삶은 조개 10개를 제작한 다음, 불모의 땅의 십자로에 있는 라르카에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "바를 보는 것만큼 배고파지는 일이 또 있을까? 저 맛있는 음료들을 보니 배에서 꼬르륵 소리가 나네.\n\n근처 바다에는 내가 다 알지 못하는 별미들이 있지. 삶은 조개 먹어본 적 있어, $N? 지금 당장 삶은 조개를 좀 먹었으면 좋겠군. 날 위해 좀 만들어주면 섭섭지 않게 보답할게.",
    },
    [28081] = {
        ["T"] = "마그그랜 어스바인더의 주문",
        ["O"] =
        "마그그랜 어스바인더는 당신이 요리 기술을 사용하여 무지개날개다랑어 구이 10개를 제작한 다음, 돌발톱 산맥의 해바위 야영지에 있는 마그그랜 어스바인더에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "반갑소, $C. 이 전초기지는 외딴곳에 있어서 투자개발회사나... 대지모신이여 굽어살피소서, 얼라이언스의 공격에 대비해 병력을 유지하는 수많은 업무를 도울 일손이 부족하오.\n\n요리사의 도움이 필요하오. 이곳에 주둔한 그런트들을 위해 무지개날개다랑어 구이를 준비해 주겠소? 건강한 생선으로 만든 든든하고 따뜻한 식사는 사슴 고기나 와이번 알을 대신할 좋은 기분 전환이 될 것이오.",
    },
    [28082] = {
        ["T"] = "카랑 아마카르의 주문",
        ["O"] =
        "카랑 아마카르는 당신이 요리 기술을 사용하여 게살 케이크 10개를 제작한 다음, 잿빛 골짜기의 조람가르 전초기지에 있는 카랑 아마카르에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "조람 해안에 온 것을 환영하오, $C. 바다의 풍요로움은 이토록 가까운데도 너무 멀리 있군. 나는 이 작은 전초기지의 지휘를 맡아 우리를 둘러싼 여러 위협에 대처하느라 모든 시간을 쏟고 있다오. 하지만 맛있는 게살 케이크가 너무 먹고 싶군!\n\n날 위해 게살 케이크를 만들어 준다면 참 고맙겠지만, 바쁘다면 이해하겠소. 난 그냥 여기 있겠소. 기다리며....",
