    [28083] = {
        ["T"] = "키르제 스턴혼의 주문",
        ["O"] =
        "키르제 스턴혼은 당신이 요리 기술을 사용하여 말린 돼지 갈비 10개를 제작한 다음, 불모의 땅의 타우라조 야영지에 있는 키르제 스턴혼에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "아, $N! 아름다운 날 아닌가? 해는 빛나고, 구름은 높고, 그리고 난 말린 돼지 갈비를 먹을 수 있겠지!\n\n뭐, 내가 스테이크를 더 원할 줄 알았나? 그건 역겹잖아!\n\n남쪽의 가시멧돼지들이 수풀 속에 멧돼지를 잔뜩 기르고 있지. 이 늙은 타우렌을 도와줄 수 있겠나?",
    },
    [28084] = {
        ["T"] = "도른 플레인스토커의 주문",
        ["O"] =
        "도른 플레인스토커는 당신이 요리 기술을 사용하여 표범메기 구이 10개를 제작한 다음, 버섯구름 봉우리의 갈기바람 협곡 침식된 동굴에 있는 도른 플레인스토커에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "반갑소, $N. 바다는 이토록 멀고 난 생선이 너무 먹고 싶소. 하지만 내 임무 때문에 여길 떠날 시간도 없고, 내 빈약한 실력으로 요리할 시간은 더더욱 없지.\n\n부탁 하나만 들어주겠소? 따끈한 표범메기 구이가 먹고 싶소. 화로 다루는 솜씨가 있는 것 같으니. 사례는 섭섭지 않게 하겠소.",
    },
    [28085] = {
        ["T"] = "마윈 슈릴윌의 주문",
        ["O"] =
        "마윈 슈릴윌은 당신이 요리 기술을 사용하여 큰 곰 스테이크 10개를 제작한 다음, 잊혀진 땅의 그늘수렵 마을에 있는 마윈 슈릴윌에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "난 왕립 연금술 학회에서 중요한 연구를 맡아 잊혀진 땅에 왔지만, 고향이 그립소. 특히나 뜨겁고 육즙이 가득한 큰 곰 스테이크처럼 고향 최고의 음식들이 그립군.\n\n잊혀진 땅에 곰이 없다는 건 알지만, 곰 고기를 구해와 내게 스테이크를 요리해 준다면 이 지옥 같은 황무지를 견디는 데 조금이나마 도움이 될 거요.",
    },
    [28086] = {
        ["T"] = "죽음의추적자 레시의 주문",
        ["O"] =
        "죽음의추적자 레시는 당신이 요리 기술을 사용하여 고블린식 매운 조개 요리 10개를 제작한 다음, 언덕마루 구릉지의 남부경비 탑에 있는 죽음의추적자 레시에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "호드 최악의 부대에 온 걸 환영해, $C: 남부경비 탑 말이야. 볼품없긴 하지만 내 임지지.\n\n살아생전에 난 바다 근처에서 많은 시간을 보냈고, 그곳 요리가 그리운 모양이야. 언더시티 배급 식량은 전혀 매력적이지 않고, 고블린식 매운 조개 요리 한 접시라면 무엇과도 바꿀 수 있을 것 같아. 요리할 줄 안다면, 좀 가져다주는 대가로 사례는 넉넉히 할게!",
    },
    [28087] = {
        ["T"] = "키타 파이어윈드의 주문",
        ["O"] =
        "키타 파이어윈드는 당신이 마법부여 기술을 사용하여 룬문자 구리마법막대 1개를 제작한 다음, 엘윈 숲의 아조라의 탑에 있는 키타 파이어윈드에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "흠, 수습 마법부여사인가요? 발전이 어느 정도인지 보죠. 나를 위해 룬문자 구리마법막대를 만들어 내가 볼 수 있도록 가져오세요. 잘 해낸다면, 당신의 기술이 더 발전한 후 다시 만날 수도 있을 겁니다.",
    },
    [28366] = {
        ["T"] = "치유사의 의식",
        ["O"] = "오그리마의 지혜의 골짜기에 있는 아이트리그와 대화하십시오.",
        ["D"] =
        "응급치료 공부를 마쳤군. 잘했다, $N.\n\n때마침 잘 찾아왔다. 호드를 위해 봉사할 경험 많은 치유사가 필요하다. 대족장께서 직접 최고의 부관 아이트리그에게 적임자를 찾으라고 명령하셨고, 너보다 나은 사람은 생각나지 않는구나.\n\n부름에 응할 의향이 있다면 지혜의 골짜기에서 아이트리그를 찾을 수 있을 것이다.",
    },
    [28367] = {
        ["T"] = "치유사의 의식",
        ["O"] = "불타는 평원에서 요원 메리건과 하사관 그루말을 수색하십시오.",
        ["D"] =
        "신생 호드 합류를 거부한 검은바위 오크들이 어둠의 세력과 동맹을 맺었다. 얼라이언스가 검은바위 산에 있는 그들의 본거지에 잠입하자고 제안했고, 우리는 동의했다. 하지만 이 임무에 파견된 요원들이 아직 보고하지 않고 있다.\n\n뛰어난 의료 기술을 가진 누군가가 불타는 평원으로 가서 그들에게 무슨 일이 일어났는지 확인해야 한다. 전쟁노래 부족 출신의 그런트인 하사관 그루말이나 위장한 인간인 요원 메리건을 찾아야 한다. 그들이 죽었다면 즉시 보고해라. 그렇지 않다면 그들이 임무를 완수하도록 네가 도울 수 있는지 확인해라.",
    },
    [28368] = {
        ["T"] = "치유사의 의식",
        ["O"] =
        "요원 메리건은 당신이 응급치료 기술을 사용하여 강력한 해독제를 만든 다음, 불타는 평원에 있는 그의 동굴로 가져오기를 원합니다.",
        ["D"] =
        "임무에 대해선 잠시 후에 알려드리겠지만, 먼저 시급한 상황부터 처리해야 합니다.\n\n제 위장은 꽤 통했지만 홀든에 대한 제 애정은 숨기기 어려웠습니다. 그는 아마 제 결의를 시험하려는 검은바위 오크에게 중독되었을 겁니다. 독의 효과를 늦추는 데는 성공했지만 강력한 해독제가 없으면 그는 죽고 말 겁니다.\n\n홀든을 돕는다면 알고 싶은 모든 것을 말해드리겠습니다.",
    },
    [28369] = {
        ["T"] = "치유사의 의식",
        ["O"] =
        "검은바위 요새에서 우스모그 스파인브레이커를 처치하고 그가 가진 문서를 불타는 평원의 요원 메리건에게 가져가십시오.",
        ["D"] =
        "전 약속을 지키는 사람입니다, $C. 이제 홀든이 회복하고 있으니 무슨 일이 있었는지 말씀드리죠.\n\n검은바위 오크들은 우리의 존재를 의심하지 않았습니다. 우리는 쉽게 그들의 근무 명단에 들어갔지만, 하사관 그루말과 제가 서로 다른 순찰대에 배정되면서 흩어졌다는 단점이 있었죠. 그로 인해 제 위장을 유지하기가 더 힘들어졌습니다. 겉모습은 오크와 완벽히 똑같을지 몰라도 세세한 부분까지는 다 알지 못하니까요. 그래서 물러날 수밖에 없었습니다.\n\n그루말은 적응하는 데 아무 문제 없었지만 며칠째 그를 보지 못했습니다. 그가 어디에 배정되었는지 모릅니다. 그 정보를 가진 유일한 자는 검은바위 요새의 사령관 우스모그 스파인브레이커뿐입니다. 그가 병력 배치에 관한 유일한 문서를 보관하고 있습니다. 무리한 부탁이겠지만, 우리가 필요한 정보를 얻으려면 그를 처치해야만 합니다.",
    },
    [28370] = {
        ["T"] = "치유사의 의식",
        ["O"] =
        "요원 메리건은 당신이 응급치료 기술을 사용하여 두꺼운 룬매듭 붕대 20개를 제작한 후, 검은바위 산의 검은바위 첨탑 하층에 잠입하여 하사관 그루말을 찾기를 원합니다.",
        ["D"] =
        "음, 적어도 그루말이 병력 배치표에 이름이 있군요. 죽지 않았다는 뜻이겠죠.\n\n나쁜 소식은 그가 검은바위 첨탑의 병참장교 호위대로 배정되었다는 것입니다. 거긴 엄청나게 큰 곳입니다! 그가 그 안 어디에 있을지 모릅니다.\n\n홀든은 분명 우리와 동행할 수 없습니다. 어쨌든 저도 스톰윈드에 돌아가 보고하고 이 환영을 지워야 합니다. 그를 구출할 팀을 구성하는 건 당신에게 맡길 수밖에 없겠군요. 두꺼운 룬매듭 붕대를 좀 챙겨 가십시오. 그가 다쳤을지도 모릅니다.",
    },
    [28371] = {
        ["T"] = "치유사의 의식",
        ["O"] =
        "검은바위 첨탑 하층의 하사관 그루말은 당신이 해독제 표본을 오그리마의 아이트리그나 스톰윈드의 렌직 \"더 시브\"에게 가져가기를 원합니다.",
        ["D"] =
        "이제 좀 낫군. 시간이 지나면 회복될 거요.\n\n검은바위 오크들이 새로운 해독제를 개발했고 날 시험 대상으로 삼았지. 한밤중의 전갈 독침에 진절머리가 났나 보군.\n\n다른 건 몰라도, 의학적 돌파구가 될지도 모르는 이 해독제에 대해서는 알게 되었소. 이 해독제 표본을 당신의 지도자에게 가져가시오. 난 좀 쉬면 검은바위 첨탑을 빠져나갈 수 있을 거요.",
    },
    [28372] = {
        ["T"] = "치유사의 의식",
        ["O"] =
        "실리더스의 돌비늘전갈에게서 독침을 얻어 검은바위 해독제를 시험한 후, 오그리마의 아이트리그나 스톰윈드의 렌직 \"더 시브\"에게 돌아가십시오.",
        ["D"] =
        "듣자 하니 이 해독제는 가장 강력한 전갈 독에 사용된다고 하니 한번 시험해 보시오.\n\n칼림도어 동남쪽 끝에 있는 잃어버린 땅 실리더스로 떠난 원정대에서 초기 보고서를 받았소. 그들은 지금까지 본 적 없는 강력한 독을 가진 전갈을 포함해 공격적인 야수들을 보고했소.\n\n이 해독제의 효능을 시험하기에 그보다 더 좋은 장소는 생각나지 않는군. 그곳으로 가서 이 해독제로 전갈의 독을 치료해 보시오. 그리고 어떻게 작동하는지 보고하시오.",
    },
    [28373] = {
        ["T"] = "치유사의 의식",
        ["O"] = "스톰윈드 구 시가지의 SI:7에 있는 렌직 \"더 시브\"와 대화하십시오.",
        ["D"] =
        "응급치료 공부를 마쳤군. 잘했다, $N.\n\n때마침 잘 찾아왔다. 얼라이언스를 위해 봉사할 경험 많은 치유사가 필요하다. 볼바르께서 직접 SI:7에 적임자를 찾으라고 명령하셨고, 너보다 나은 사람은 생각나지 않는구나.\n\n부름에 응할 의향이 있다면 구 시가지의 SI:7에서 렌직 \"더 시브\"를 찾을 수 있을 것이다.",
