        "이보시오, 마을에 있는 동안 남부 불모의 땅의 선량한 사람들을 좀 도와주면 안 되겠소? 갠 스톤스파이어는 남부 황금길을 혼자 순찰하는데 그의 안전이 걱정되오. 그가 안전하도록 이 사냥꾼의 도끼에 최하급 공격력을 부여해서 가져다주시오.",
