        ["D"] =
        "오 착한 마법부여사. 저기, 날 도와 룬문자 금마법막대를 하나 만들어 줄 수 있어? 어디에 쓸 건진 묻지 마, 고블린의 일이니까! 아, 물론 돈은 지불할게.",
