        ["D"] =
        "난 마법부여사를 보면 한눈에 알지. 난 헬쿨라만큼 강력하진 않지만 헬쿨라가 그랬던 것처럼 호드를 더 잘 모시기 위해 마법 연구를 향상시킬 희미하게 빛나는 큰 결정이 필요해. 하나 구해줄 수 있어? 돈은 지불할게.",
