        ["D"] =
        "반갑소, 당신은 마법부여사이오? 높새바람 봉우리의 하가르 라이트닝후프가 친화의 지팡이를 찾고 있었는데 마을에는 마법부여사가 없소. 당신이 기꺼이 도와준다면 그도 섭섭지 않게 보답할 거요.",
