        ["D"] =
        "마법부여 실력이 꽤 늘었군. 연습할 게 좀 필요한가? 의술사 진질이 이 몽상가의 로브에 마나 마법부여를 원한다네. 작업이 끝나면 말라카진에 두고 오게. 여기서 길을 따라 남쪽으로 가면 바로 나올 테니.",
