        "맥가반은 당신이 마법부여 기술을 사용하여 제공된 강한 타격의 철퇴 1개에 양손 무기 마법부여 - 하급 충돌을 부여한 다음, 가시덤불 골짜기의 그롬골 주둔지에 있는 사령관 아그로고쉬에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "그롬골 주둔지의 사령관 아그로고쉬가 이 강한 타격의 철퇴를 주문했는데 마법을 부여해달라고 하더군. 그런데 원래 거래하던 녀석이 마을에 없지 뭐야. 도와줄 만한 사람 아는가? 사례는 두둑하게 하겠네.",
