    [28416] = {
        ["T"] = "타베사의 주문",
        ["O"] =
        "발라이 로크웨인은 당신이 마법부여 기술을 사용하여 신비한 하급 마술봉 1개를 제작한 다음, 먼지진흙 습지대 수렁 어딘가에 있는 타베사의 집으로 주문품을 가져가기를 원합니다.",
        ["D"] =
        "어느 정도 가까이 있는 마법사가 새 마술봉을 필요로 하오. 늪에 있는 타베사의 농장으로 신비한 하급 마술봉을 만들어 보내주시오. 뜻밖의 요청이긴 하지만 거절하진 않겠소. 어쩌면 다른 사람을 위한 선물일 수도 있고 그녀가 어떤 식으로든 강화할 수도 있겠지.",
