        "애니 그림은 당신이 마법부여 기술을 사용하여 신비한 상급 마술봉 1개를 제작한 다음, 잊혀진 땅의 그늘수렵 마을에 있는 애니 그림에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이런 부주의할 데가, 이곳으로 떠나려고 짐을 쌀 때 언더시티에 마술봉을 깜빡 잊고 왔어요. 아니면 고블린 짐마차에 두고 내렸을지도 모르죠. 어쨌든, 당신이 마법부여사가 맞다면 신비한 상급 마술봉을 하나 만들어주세요.",
