        "자칼 모스멜드는 당신이 마법부여 기술을 사용하여 제공된 소령의 검 1개에 무기 마법부여 - 공격력을 부여한 다음, 황야의 땅의 카르가스에 있는 장군 고어투스에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "오 마법부여사님 안녕하세요, 잠시 시간 좀 내주시겠어요. 사람들은 제가 마법부여가 아니라 연금술 수습생이라는 걸 모른다니까요. 니카 블러드스카는 고어투스 장군을 위해 이 소령의 검에 마법을 부여해 달라고 하셨지만, 전 할 수 없어요. 도와주실 수 있나요? 근처 탑에 있는 그에게 배달해 주세요.",
    },
    [28419] = {
        ["T"] = "고르물의 주문",
        ["O"] =
        "토르간은 당신이 마법부여 기술을 사용하여 제공된 주술사의 방패 1개에 방패 마법부여 - 정신력을 부여한 다음, 아라시 고원의 망치 주둔지에 있는 고르물에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "반갑소, 마법부여사. 고르물이 요즘 꽤 우울해해서 기운(spirit)을 북돋아 주고 싶소. 그러니 말 그대로 한번 해봅시다. 훌륭한 전사라면 누구나 방패를 가지고 다니니, 내가 구한 이 주술사의 방패에 정신력(Spirit)을 부여해서 그의 기운을 돋우어 주었으면 하오. 방패가 그런 역할을 하는 것 아니겠소?",
