    [28420] = {
        ["T"] = "멜코르 블러드러너의 주문",
        ["O"] =
        "멜코르 블러드러너는 당신이 마법부여 기술을 사용하여 찬란하게 빛나는 큰 결정 1개를 제작한 다음, 타나리스의 안제와타에 있는 멜코르 블러드러너에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "해적이며 모래망치 부족이며 오우거... 벌레... 좋아, 여긴 위험한 곳이야. 어쨌든 요즘엔 보급 마차가 다니는 일이 드물지. 찬란하게 빛나는 큰 결정이 다 떨어졌는데 내 연구에 필요해. 날 위해 하나 구해다 줄 수 있어? 수고비는 줄게.",
