        ["D"] =
        "당신은 마법부여사죠? 저 좀 도와주실 수 있나요? 가죽세공 공급업자로서 제게 물건을 대줄 의향이 있는 사람을 찾고 있습니다. 마법부여사는 구하기 어려운데, 마침 마력 깃든 가죽이 떨어졌네요. 하나 구해다 주실 의향이 있으신가요?",
    },
    [28422] = {
        ["T"] = "알트소바 레이지토템의 주문",
