        ["D"] =
        "잠깐만 기다려 보시오, 마법부여사님. 피멍울 초소를 가동하려면 아직 많은 보급품이 필요하오. 특별히 무기를 계속 제작하기 위해 마력 깃든 토륨 주괴가 좀 필요하오. 하나 만들어 주시겠소? 물론 보상은 할 것이오.",
    },
    [28423] = {
        ["T"] = "수습생 사리나의 주문",
        ["O"] =
        "수습생 사리나는 당신이 마법부여 기술을 사용하여 하급 황천의 마술봉 1개를 제작한 다음, 아즈샤라의 발로르모크에 있는 수습생 사리나에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "잠깐만요, 조용히요, 저 좀 도와주실 수 있어요? 제가 마법에 너무 많이 의존하고 연금술 기술에는 충분한 시간을 쏟지 않는다고 수석 연금술사 리앤더님이 제 마술봉을 가져가 버리셨어요. 하지만 전 마술봉이 필요한걸요! 그러니 몰래 대체품 하나 만들어 주실 수 있나요? 돈은 드릴게요!",
    },
    [28424] = {
        ["T"] = "감독관 랠렌의 주문",
        ["O"] =
        "감독관 랠렌은 당신이 기계공학 기술을 사용하여 구리 나사 한 줌 24개를 제작한 다음, 엘윈 숲의 동쪽계곡 벌목지에 있는 감독관 랠렌에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이봐요, $N -- 귀 뒤에 기름때가 조금 남았군요! 그걸 보니 당신 직업이 기계공학자인 것 같은데, 당신의 도움이 필요한 일이 하나 있습니다.\n\n제재소를 계속 가동하는 것은 시간 단위로 해야 하는 귀찮은 일입니다. 조금만 잘못 쳐다봐도 망가질 것 같은 기분이죠. 칼날을 계속 돌리려면 구리 나사 한 줌이 24개쯤 필요합니다. 도와주실 수 있겠습니까?",
    },
    [28425] = {
        ["T"] = "치안대장 해거드의 주문",
        ["O"] =
        "감독관 랠렌은 당신이 기계공학 기술을 사용하여 천연 구리 폭탄 20개를 제작한 다음, 엘윈 숲의 동쪽계곡 벌목지에 있는 치안대장 해거드에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이봐요, 당신이 기계공학자이니 여기서 도와줄 수 있는 일이 하나 더 있습니다.\n\n저 너머에 있는 치안대장 해거드는 스톰윈드 경비병으로 수십 년간 복무해 왔습니다. 가끔 그는 2차, 3차 대전쟁의 기억을 떠올리며 한밤중에 깨어납니다... 더 이상 안전하다고 느끼지 못하죠. 그에게 필요한 건 화력이라고 생각합니다. 위안 삼아 곁에 둘 만한 거 말입니다. 제 말은 폭발물입니다, $N. 천연 구리 폭탄 한 묶음이라면 그에게 개인 무기고가 있는 듯한 느낌을 줄 수 있을 겁니다.",
    },
    [28426] = {
        ["T"] = "조종사 해머풋의 주문",
        ["O"] =
        "라즐 스프리스프로켓은 당신이 기계공학 기술을 사용하여 만능 스패너 2개를 제작한 다음, 던 모로의 북부 관문 전초기지에 있는 조종사 해머풋에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "놈리건의 대재앙으로 수많은 노움 기계공학자들을 잃은 탓에, 우리의 서비스는 수요가 아주 높습니다. 조종사 해머풋을 보세요 -- 그는 심지어 자기 공성 전차를 고칠 수 있게 제 개인 공구를 내놓으라고 요구했다니까요!\n\n뭐, 내 눈에 흙이 들어가기 전엔 내 공구를 가져갈 수 없지만, 좋은 일을 하고 싶다면 만능 스패너 몇 개를 만들어서 북부 관문 전초기지에 있는 그에게 가져다주세요. 어쨌든 우리도 작동하는 공성 전차가 필요하니까요.",
    },
    [28427] = {
        ["T"] = "레욜트 발리브루의 주문",
        ["O"] =
        "라즐 스프리스프로켓은 당신이 기계공학 기술을 사용하여 구리관 5개를 제작한 다음, 던 모로의 브루날 마을에 있는 레욜트 발리브루에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "기계공학자라면 여느 드워프 못지않게 좋은 맥주를 감상할 줄 아니, 시간이 되신다면 레욜트 발리브루의 이 요청을 처리해 달라고 부탁드리고 싶습니다. 그는 브루날 마을의 증류기를 개선하기 위해 구리관 한 묶음이 필요하다고 합니다. 레욜트가 이미 빚고 있는 에일 맥주도 아주 훌륭해서, 새 증류기가 가동되면 어떤 맥주가 나올지 기대가 됩니다.",
    },
    [28428] = {
        ["T"] = "다잘라의 주문",
        ["O"] =
        "샌더는 당신이 기계공학 기술을 사용하여 조잡한 붐스틱 1개를 제작한 다음, 텔드랏실의 돌라나르에 있는 다잘라에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이슈누달디엡, $C. 아이언포지에서 돌아온 이후로 내 기계공학 서비스의 수요가 아주 높다는 걸 깨달았습니다. 혼자 감당할 수 없을 정도로 주문이 밀려들더군요.\n\n당신에게도 기계공학적 소질이 있다면 주문을 하나 처리해 줄 수 있겠습니까? 돌라나르의 사냥꾼 상급자인 다잘라가 총을 한 번 써보고 싶다고 하더군요. 상상이나 됩니까? 정말 진취적인 생각이죠!\n\n어쨌든 그에게 조잡한 붐스틱을 하나 만들어 배달해 주신다면 정말 감사하겠습니다.",
    },
    [28429] = {
        ["T"] = "데날란의 주문",
        ["O"] =
        "샌더는 당신이 기계공학 기술을 사용하여 천연 다이너마이트 20개를 제작한 다음, 텔드랏실의 알라메스 호수에 있는 데날란에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "좀 이해하기 힘든 주문이 하나 들어왔습니다. 혹시 한번 보시겠습니까?\n\n데날란이 알라메스 호수 근처에서 식물 실험을 하고 있습니다. 며칠 전 그가 \"통제 불능의 관목\"을 처리할 \"폭발적인\" 무언가를 보내 달라는 메모를 보냈더군요. 글쎄요, 이걸 어떻게 해석해야 할지 모르겠지만, 천연 다이너마이트를 좀 만들 의향이 있으시다면 돌라나르 뒤편 호숫가에 있는 데날란에게 배달해 주십시오.",
    },
    [28430] = {
        ["T"] = "정찰병 리엘의 주문",
        ["O"] =
        "민병대원 가리엘은 당신이 기계공학 기술을 사용하여 조잡한 조준경 2개를 제작한 다음, 서부 몰락지대의 감시의 언덕에 있는 정찰병 리엘에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "전 민병대가 필요로 하는 물품을 징발할 권한을 부여받았습니다. 당신 기계공학자 맞죠? 탑 꼭대기에 있는 정찰병 리엘에게 줄 조잡한 조준경이 필요합니다. 감시의 언덕을 공격하는 모든 것을 저격할 수 있는 좋은 이점을 줄 겁니다. 만약 몇 개를 만들어서 그녀에게 배달해 주신다면 보상해 드리겠습니다.",
