    [28431] = {
        ["T"] = "민병대원 도라나의 주문",
        ["O"] =
        "민병대원 가리엘은 당신이 기계공학 기술을 사용하여 날렵한 호랑이 고글 1개를 제작한 다음, 서부 몰락지대를 통과해 북쪽으로 향하는 도로의 순찰 경로에 있는 민병대원 도라나에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "민병대의 징발관으로서 민병대원 도라나에게 날렵한 호랑이 고글을 한 쌍 만들어 주실 것도 요청하고 싶습니다. 그녀는 감시의 언덕에서 북쪽으로 뻗은 길을 홀로 걷고 있는데, 그 고글이 흙먼지와 모래 폭풍, 그리고 따가운 햇볕으로부터 그녀의 눈을 보호해 줄 겁니다. 친절하게도 그걸 그녀에게 배달해 주신다면 정말 감사하겠습니다.",
