        "골볼트 스틸핸드는 당신이 기계공학 기술을 사용하여 표적 허수아비 5개를 제작한 다음, 어둠해안의 렘트래블의 발굴현장에 있는 고고학자 에버릿에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이 동네 엘프 친구들 대부분은 훌륭한 기계공학을 별로 믿지 않지만, 전 최근 남쪽에 있는 렘트래블의 발굴현장 소속 드워프인 고고학자 에버릿과 얘기를 나눴습니다. 골렘과 관련된 어떤 문제가 있다며 표적 허수아비를 좀 찾고 있다고 하더군요. 전 재고가 없었죠 -- 평소에 취급하는 물건이 아니니까요 -- 하지만 당신이 그걸 만들 생각이 있다면, 그가 그에 걸맞은 대가를 치를 거라 확신합니다.",
    },
    [28433] = {
        ["T"] = "셀렐리안 화이트클로의 주문",
        ["O"] =
        "골볼트 스틸핸드는 당신이 기계공학 기술을 사용하여 은 접지 20개를 제작한 다음, 어둠해안의 아우버다인에 있는 셀렐리안 화이트클로에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "제가 재고로 가지고 있지 않은 또 다른 물건은 은 접지인데, 이 마을의 한 나이트 엘프가 그걸 좀 사고 싶어 하더군요. 아내의 스케치를 위한 '적절한 매개체'라나 뭐라나. 전 예술에 대해선 아무것도 모르지만... 당신이 아우버다인의 셀렐리안 화이트클로를 위해 은 접지를 좀 구해올 수 있다면 동전 좀 만질 수 있다는 건 알고 있죠.",
    },
    [28434] = {
        ["T"] = "브록 스톤시커의 주문",
        ["O"] =
        "브록 스톤시커는 당신이 기계공학 기술을 사용하여 구리 변조기 5개를 제작한 다음, 모단 호수의 텔사마에 있는 브록 스톤시커에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "반갑소, $C. 광부가 기계공학자에게 도움을 요청하는 게 좀 이상하다는 건 알지만, 새로운 자동 채굴기에 대한 아이디어가 있소. 내 첫 번째 시제품을 만들려면 구리 변조기 5개가 필요하오. 날 도와준다면 기꺼이 수수료에 팁을 얹어 주겠소.",
    },
    [28435] = {
        ["T"] = "수습생 다릴의 주문",
        ["O"] =
        "브록 스톤시커는 당신이 기계공학 기술을 사용하여 연습용 자물쇠 5개를 제작한 다음, 모단 호수의 원정순찰대 오두막에 있는 수습생 다릴에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "도움 얘기가 나와서 말인데, 얼마 전 원정순찰대 오두막으로 향하던 한 젊은 인간이 여길 지나갔소. 사냥에 조금 지루함을 느끼는 것 같더군. 마을에 연습용 자물쇠를 만들 수 있는 사람이 있냐고 물었지만, 여기엔 그런 기술을 가진 사람이 아무도 없소. 동전을 좀 더 벌고 싶다면 그가 오두막에 한동안 머물 거라고 하더군. 이름은 다릴이었소.",
    },
    [28436] = {
        ["T"] = "빅토리 프리즘안트라스의 주문",
        ["O"] =
        "코그 글리츠스피너는 당신이 기계공학 기술을 사용하여 화려한 망원경 1개를 제작한 다음, 그늘숲의 다크샤이어에 있는 빅토리 프리즘안트라스에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "옆집에 사는 인간이 별을 관측하려고 무슨 거창한 망원경 같은 걸 만들려고 해요. 우리 노움들은 이미 별을 볼 방법이 있다고 계속 말하고 있죠 -- 바로 화려한 망원경을 통해서요!\n\n전 기계공학자가 아니지만 당신은 그런 것 같군요. 당신이 망원경을 만들어서 빅토리에게 배달해 준다면 정말 좋겠어요. 그러면 그 바보 같은 발명품에 대해 더 이상 안 들어도 될 테니까요!\n\n<코그가 노움의 산업을 침해하는 인간들에 대해 중얼거립니다.>",
    },
    [28437] = {
        ["T"] = "젬 리워드의 주문",
