        ["D"] =
        "이봐요, $C. 영원고요 호수에서의 낚시는 이보다 더 좋을 수 없을 정도예요. 이 부두에서 크고 빛나는 해바라기 붕어를 수없이 낚았죠 -- 하지만 그 신기한 액체역학 물고기 유인기만 있다면 더 잘할 수 있을 것 같아요. 혹시 그거 만들 줄 아는 사람 아나요?",
    },
    [28438] = {
        ["T"] = "오렌딜 브로드리프의 주문",
        ["O"] =
        "정화자 델그렌은 당신이 기계공학 기술을 사용하여 강한 다이너마이트 20개를 제작한 다음, 잿빛 골짜기의 마에스트라 주둔지에 있는 오렌딜 브로드리프에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "반갑습니다, $C. 저는 근처에 있는 포세이큰의 활동을 조사하기 위해 이곳에 왔습니다. 제 이웃인 오렌딜 브로드리프에게 기계공학 기술의 실습에 대한 많은 질문을 받았죠. 그는 다른 많은 나이트 엘프들처럼 기술에 반대하지는 않는 것 같습니다.\n\n오렌딜에게 기계공학을 이용해 발휘할 수 있는 힘을 보여주고 싶습니다. 강한 다이너마이트를 좀 만들어서 그에게 가져다주실 수 있겠습니까?",
    },
    [28439] = {
        ["T"] = "사령관 스트롱본의 주문",
        ["O"] =
        "프래드 스위프트기어는 당신이 기계공학 기술을 사용하여 일반 조준경 2개를 제작한 다음, 저습지 북부 늪지대의 번듀럴에 있는 사령관 스트롱본에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "나의 누추한 작업장에 온 걸 환영하오, $C. 북부 늪지대에서 심상치 않은 일이 벌어지고 있다는 불길한 보고를 받았소. 용아귀 오크들이 그곳에 병력을 집결시키고 있어서, 번듀럴이 공격받을까 봐 걱정이라오.\n\n사령관 스트롱본이 그곳 방어의 책임자인데, 소총수들을 위해 일반 조준경 몇 개를 요청하는 주문서가 여기 있소. 아아, 아직 손도 못 대고 있다오. 날 좀 도와서 당장 이 일을 맡아줄 수 있겠소?",
