    [28440] = {
        ["T"] = "하사관 요화의 주문",
        ["O"] =
        "하사관 요화는 당신이 기계공학 기술을 사용하여 대형 청동 폭탄 20개를 제작한 다음, 가시덤불 골짜기의 반란군 야영지에 있는 하사관 요화에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "대령 쿠르젠의 군대가 가시덤불 골짜기의 멀리 떨어진 언덕에 있는 동굴에 틀어박혀 있습니다. 전술적 타격으로 그와 그의 부하들을 소탕할 수 있다면 더 좋겠지만, 우리의 공세가 실패할 경우에 대비해야만 합니다.\n\n그 준비에는 당신 같은 재능 있는 기계공학자가 포함됩니다.\n\n폭탄이 필요합니다, $N. 큰 놈으로요. 구체적으로 말하자면 대형 청동 폭탄 한 묶음입니다. 최악의 상황이 오면 그 동굴 입구를 폭파해 쿠르젠을 안에 가둬버릴 수 있습니다.",
    },
    [28441] = {
        ["T"] = "현장감독 티온의 주문",
        ["O"] =
        "경비병 바이론은 당신이 기계공학 기술을 사용하여 태엽장치 5개를 제작한 다음, 먼지진흙 습지대의 테라모어 섬에 있는 현장감독 티온에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이봐요 -- 거기 당신! 동부 왕국에 주둔했을 때 아이언포지에 있는 기계공학 전문가 옆에서 당신을 본 것 같은데요. 기계공학자 맞죠?\n\n현장감독 티온이 우리 제재소를 가동하려고 애쓰고 있는데 벨트의 타이밍을 맞추는 데 문제를 겪고 있습니다. 가동하려면 태엽장치가 몇 개 필요하다고 하더군요. 혹시 도와주실 수 있나요?",
    },
    [28442] = {
        ["T"] = "호르니즈 브림버즐의 주문",
        ["O"] =
        "디비 스퀴글코드는 당신이 기계공학 기술을 사용하여 조밀한 다이너마이트 20개를 제작한 다음, 잊혀진 땅의 코도 무덤에 있는 호르니즈 브림버즐에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "스퀴글코드에 온 걸 환영해요. 제가 이 구역을 맨바닥부터 다 세웠고 할 일도 꽤 많죠.\n\n이봐요, 당신 기계공학자 맞죠? 당신 손가락에 박힌 만능 스패너 굳은살을 보면 알 수 있어요. 들어온 주문 하나 처리해 볼래요?\n\n코도 무덤 밑에 사는 한 고블린이 조밀한 다이너마이트를 좀 사고 싶다고 주문을 넣었어요. 저도 고블린 기계공학자들에 대해선 건강한 직업적 존경심을 가지고 있지만, 이 자는 연금술사라고요.... 대체 다이너마이트를 어디다 쓰려는 건지 모르겠어서 아직 주문을 처리하지 않았어요. 원하신다면 전부 맡길게요!",
    },
    [28443] = {
        ["T"] = "시몬 캔트렐의 주문",
        ["O"] =
        "시몬 캔트렐은 당신이 기계공학 기술을 사용하여 초정밀 고글 1개를 제작한 다음, 언덕마루 구릉지의 라벤홀트 장원에 있는 시몬 캔트렐에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "라벤홀트 영주 같은 인간이 조경에 안목이 있다는 사실에 꽤 놀랐지만, 이곳의 정원은 정말로 훌륭해질 기초를 갖추고 있습니다. 나뭇잎의 세세한 부분까지 파악할 수 있는 초정밀 고글이 한 쌍 있다면 정말 큰 도움이 될 겁니다. 혹시 어디서 그 고글을 구할 수 있는지 아시나요?",
    },
    [28444] = {
        ["T"] = "호윈 카인드페더의 주문",
        ["O"] =
        "호윈 카인드페더는 당신이 기계공학 기술을 사용하여 미스릴관 5개를 제작한 다음, 동부 내륙지의 맹금의 봉우리에 있는 호윈 카인드페더에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "낚시해 본 적 있소, $N? 난 낚시를 아주 좋아하지만, 썩은가지부족 트롤들이 내가 제일 좋아하는 낚시터에서 날 쫓아냈을 때 제일 아끼던 낚싯대를 잃어버렸다오.\n\n마을에 기계공학자가 없어서 언제 새 낚싯대를 장만할지 모르겠소. 혹시 미스릴관을 몇 개 구하게 된다면, 당신 친구 호윈을 떠올려주지 않겠소? 그걸로 새 낚싯대를 만들 수 있을 거요.",
    },
    [28445] = {
        ["T"] = "샨드리스 페더문의 주문",
        ["O"] =
        "샨드리스 페더문은 당신이 기계공학 기술을 사용하여 고급 표적 허수아비 2개를 제작한 다음, 페랄라스의 페더문 요새에 있는 샨드리스 페더문에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "훈련시켜야 할 파수꾼은 많은데 모두에게 나눠줄 방어구가 부족하군요, $N. 대장간에서 방어구가 만들어지기를 기다리는 자들은 부상을 피하기 위해 조심해서 대련해야 합니다. 그래서 당신이 필요한 겁니다 -- 당신의 기계공학 기술에 대한 소문이 당신보다 먼저 이곳에 도착했죠. 제 파수꾼들을 위해 고급 표적 허수아비 몇 개가 필요합니다. 도와주실 수 있나요?",
    },
    [28446] = {
        ["T"] = "닥터 앳우드의 주문",
        ["O"] =
        "마리엘 듀몬트는 당신이 기계공학 기술을 사용하여 유동성 제동장치 5개를 제작한 다음, 서부 역병지대의 카엘 다로우에 있는 닥터 앳우드에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "당신 기계공학자인가요? 아, 죄송해요... 그저 그렇게 보여서요. 제 오빠가 기계공학자거든요.\n\n어쨌든, 얼마 전 서리바람 야영지에 닥터 앳우드라는 사람이 유동성 제동장치를 좀 찾고 있었다는 사실을 알려드리고 싶었어요. 은빛 여명회가 그를 좀 내쫓았는데... 이유는 잘 모르겠어요. 하지만 기계공학자가 오면 자긴 카엘 다로우에 있을 거라고 했어요. 언데드들을 뚫고 그곳에 갈 수 있다면 동전을 좀 벌 수 있는 좋은 기회가 될 거예요!",
    },
    [28447] = {
        ["T"] = "킴자엘의 주문",
        ["O"] =
        "윌슨 워블스미스는 당신이 기계공학 기술을 사용하여 초정밀 조준경 2개를 제작한 다음, 아즈샤라의 레가쉬 야영지에 있는 킴자엘에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "오! 동료 기계공학자로군요! 당신 손톱 밑의 기름때를 보니 한눈에 알겠습니다!\n\n저기, 고용할 수 있나요? 워블 할로우 주변에 처리해야 할 일이 산더미라 다른 사람을 도울 짬이 안 나거든요. 북쪽의 악마들 곁에 사는 어떤 고블린이 초정밀 조준경 두어 개를 만들어줄 사람을 찾고 있었어요. 돈 버는 데 관심이 있다면, 당신의 서비스에 두둑이 값을 치를 겁니다!",
    },
    [28448] = {
        ["T"] = "소로스 다크크레센트의 주문",
        ["O"] =
        "소로스 다크크레센트는 당신이 기계공학 기술을 사용하여 고폭탄 20개를 제작한 다음, 악령숲의 갈퀴가지 숲에 있는 소로스 다크크레센트에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "<소로스는 쇠약해 보이지만 의식은 뚜렷합니다.>\n\n악마들이... 이렇게 만들었어. 반드시... 복수할 테다! 폭탄이... 필요해. 고폭탄... 나를 도와줘... 복수할 수 있게!",
    },
    [28449] = {
        ["T"] = "작업반장 힝크의 주문",
        ["O"] =
        "머크드락은 당신이 기계공학 기술을 사용하여 구리 나사 한 줌 24개를 제작한 다음, 듀로타의 오그리마 외곽 비행선 탑에 있는 작업반장 힝크에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이봐, $N -- 귀 뒤에 기름때가 조금 남았군! 그걸 보니 넌 직업이 기계공학자인 것 같은데, 네 도움이 필요한 일이 하나 있어.\n\n오그리마 외곽에 새로운 비행선 탑을 짓고 있는 고블린 무리가 있는데, 구리 나사 한 줌이 한 24개쯤 필요하대. 난 저 수레 부품 주문을 처리하느라 바빠서 손도 못 대고 있었어. 네가 좀 도와줄래?",
    },
    [28450] = {
        ["T"] = "라르 프라울터스크의 주문",
        ["O"] =
        "머크드락은 당신이 기계공학 기술을 사용하여 천연 구리 폭탄 20개를 제작한 다음, 듀로타의 센진 마을에 있는 라르 프라울터스크에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이봐, 네가 기계공학자이니 여기서 도와줄 수 있는 일이 하나 더 있어.\n\n센진 마을에 있는 라르 프라울터스크가 골치 아픈 켄타우로스 무리를 처치하는 데 도움이 필요하대. 나한테 뭐라도 보태줄 수 있냐고 묻길래, 내가 뻥 터지는 걸(BOOM) 만들어줄 수 있다고 했지. 헤헤.\n\n폭발물 얘기야, $N.\n\n천연 구리 폭탄 한 묶음이라면 그 녀석에게 자기만의 개인 무기고가 생긴 것 같은 든든함을 줄 수 있을 거야.",
