        ["O"] =
        "트위직 스프로켓그라인드는 당신이 기계공학 기술을 사용하여 조잡한 붐스틱 1개를 제작한 다음, 멀고어의 썬더 블러프에 있는 멜로르 스톤후프에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "칼림도어에는 기계공학자가 너무 적어서 우리 서비스는 수요가 높아요. 멜로르 스톤후프를 예로 들어보죠 -- 그는 새 총을 찾고 있다며 전갈을 보냈지만, 제가 너무 바빠서 답장을 못 했어요. 수수료를 포기하긴 싫지만 당신이 좋은 일을 하고 싶다면 조잡한 붐스틱을 만들어 썬더 블러프의 수렵의 봉우리에 있는 그에게 배달해 주세요.",
