        ["O"] =
        "트위직 스프로켓그라인드는 당신이 기계공학 기술을 사용하여 구리관 5개를 제작한 다음, 멀고어의 블러드후프 마을에 있는 바인 블러드후프에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "바인 블러드후프가 족장의 아들이고 기술을 싫어한다는 건 알아요. 그리고 투자개발회사와 탐험가 연맹이 멀고어에서 벌이는 짓을 타우렌들이 달갑게 여기지 않는다면, 저도 그들의 방식이 옳다고는 못 하겠네요. 잠재 고객을 화나게 해서는 안 되니까요!\n\n투자개발회사가 호수에 폐기물을 버리고 있어서 바인이 기름과 오염물을 퍼내는 데 쓸 구리관이 좀 필요하대요. 어쩌면 당신이 기계공학(그리고 고블린)이 물건을 폭파하는 것뿐만 아니라 도울 수도 있다는 걸 그에게 보여줄 수 있지 않을까요?",
