    [28453] = {
        ["T"] = "토마스 알렌도의 주문",
        ["O"] =
        "그레이엄 반 탈렌은 당신이 기계공학 기술을 사용하여 만능 스패너 2개를 제작한 다음, 티리스팔 숲의 브릴에 있는 토마스 알렌도에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "죽음의 경비병들이 죽음의 종소리 마을에서 잠든 자들을 깨우기 시작한 이후로 내 기계공학 서비스의 수요가 아주 높다는 걸 깨달았소. 혼자 감당할 수 없을 정도로 주문이 밀려들더군.\n\n당신에게도 기계공학적 소질이 있다면 주문을 하나 처리해 줄 수 있겠소? 토마스 알렌도는 티리스팔과 은빛소나무 숲을 오가는 마차들을 관리하는데, 마모된 것을 교체할 만능 스패너 두어 개를 요청했소.\n\n그에게 만들어 배달해 준다면 정말 고맙겠소.",
    },
    [28454] = {
