        ["O"] =
        "그레이엄 반 탈렌은 당신이 기계공학 기술을 사용하여 천연 다이너마이트 20개를 제작한 다음, 티리스팔 숲 언더시티 동쪽의 야영지에 있는 죽음의경비병 리니아에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "언더시티 바로 외곽 도로에 야영 중인 죽음의경비병 리니아의 주문이오. 마을에서 더 동쪽에 있는 농장들에 스컬지가 침입한 적이 있어서 천연 다이너마이트를 좀... 뭔가에 쓰려나 보오. 난 몰라, 난 그냥 만들어서 배달할 뿐이지. 이 일 처리해 줄 수 있겠소?",
