        ["O"] =
        "기욤 소로이는 당신이 기계공학 기술을 사용하여 조잡한 조준경 2개를 제작한 다음, 은빛소나무 숲의 올슨 농장에 있는 샘 요릭에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "전 죽음의추적자가 필요로 하는 물품을 징발할 권한을 부여받았습니다. 당신 기계공학자 맞죠? 올슨 농장에서 정찰 중인 샘 요릭에게 줄 조잡한 조준경이 필요합니다. 그 위치라면 남쪽에서 공동묘지를 공격하는 모든 것을 저격할 수 있는 좋은 이점을 줄 겁니다. 만약 몇 개를 만들어서 그에게 배달해 주신다면 보상해 드리겠습니다.",
