        ["D"] =
        "죽음의추적자 징발관으로서 레인 요릭에게 날렵한 호랑이 고글을 한 쌍 만들어 주실 것도 요청하고 싶습니다. 그녀는 공동묘지에서 북쪽으로 뻗은 길을 홀로 걷고 있는데, 그 고글이 진흙과 따가운 햇볕으로부터 그녀의 눈을 보호해 줄 겁니다. 친절하게도 그걸 그녀에게 배달해 주신다면 정말 감사하겠습니다.",
