        ["D"] =
        "이 칼림도어 녀석들 대부분은 기계공학의 진정한 힘을 잘 모르지만, 우리가 만드는 걸 원한다는 건 확실히 알고 있지. 그 덕분에 우리가 이 시장을 꽉 잡고 있어서 감당 못 할 정도로 일거리가 넘쳐난다고. 십자로의 대장인 셀그라 다크쏜을 예로 들어보지. 그녀가 표적 허수아비를 찾고 있어. 난 지금 당장 가진 게 없는데, 만약 네가 만들 생각이 있다면 그 녀석이 섭섭지 않게 보답할 거다.",
