        ["D"] =
        "내가 재고로 갖고 있지 않은 또 다른 물건은 은 접지인데, 북부 황금길에 사는 어떤 고블린이 좀 사고 싶어 했어. 배달 올 때까지 기다릴 수 있다더군. 그 녀석이 뭘 만들고 있는지는 모르지만, 네가 은 접지를 구해 웨니키 볼트버킷에게 갖다주면 돈 좀 만질 수 있다는 건 확실해.",
