        "테터낵 스틸포지는 당신이 기계공학 기술을 사용하여 연습용 자물쇠 5개를 제작한 다음, 불모의 땅 남부 황금길 외곽의 불타버린 감시탑에 있는 블러시트에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "도움 얘기가 나와서 말인데, 연습용 자물쇠를 요청하는 익명의 쪽지를 받았소. 누가 그런 걸 필요로 하는진 모르겠지만, 여기엔 그걸 만들 기술을 가진 사람이 아무도 없소. 동전을 좀 더 벌고 싶다면, 남부 황금길 외곽 호드의 불타버린 감시탑 근처에 그걸 두고 오라고 쪽지에 적혀있더군.",
    },
    [28461] = {
        ["T"] = "시리스의 주문",
        ["O"] =
        "시리스는 당신이 기계공학 기술을 사용하여 화려한 망원경 1개를 제작한 다음, 잿빛 골짜기의 토막나무 주둔지에 있는 시리스에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "대족장께서 이 초소를 정비하라고 날 여기로 보내셨는데, 해야 할 일이 산더미군. 우리에겐 선발대가 있지만 정작 여기 토막나무 주둔지 자체엔 정찰 장비가 턱없이 부족해.\n\n너 기계공학자 맞지? 길을 감시하고 일꾼들을 지켜볼 화려한 망원경이 하나 필요해. 돈은 지불하지.",
    },
    [28462] = {
        ["T"] = "톡카르의 주문",
        ["O"] =
        "가라쉬는 당신이 기계공학 기술을 사용하여 액체역학 물고기 유인기 10개를 제작한 다음, 슬픔의 늪의 안개갈대 주둔지에 있는 톡카르에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이보시오, $C. 동쪽 바다로 선발대를 보냈는데, 식량 확보가 그들의 임무라오. 바다에서 물고기를 잡는 데 도움이 되는 액체역학 물고기 유인기라는 게 있다고 들었소. 갓 잡은 생선이 너무 먹고 싶군! 혹시 그거 만들 줄 아는 사람 아시오?",
    },
    [28463] = {
        ["T"] = "위즐로 베어링샤이너의 주문",
        ["O"] =
        "위즐로 베어링샤이너는 당신이 기계공학 기술을 사용하여 일반 조준경 2개를 제작한 다음, 버섯구름 봉우리의 백사장 야영지에 있는 위즐로 베어링샤이너에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "어이, 댁 기계공학자야? 맙소사! 짐마차를 끌고 다시 길을 나설 준비를 하고 있는데, 이번엔 켄타우로스 놈들이 보일 때마다 바로 쏴버리게 일반 조준경 두어 개가 필요해. 나 좀 도와줄 수 있어?",
    },
    [28464] = {
        ["T"] = "지즈 피직스의 주문",
        ["O"] =
        "디시 스프링소켓은 당신이 기계공학 기술을 사용하여 강한 다이너마이트 20개를 제작한 다음, 돌발톱 산맥의 칼바람 바위산에 있는 지즈 피직스에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "나도 기계공학자이긴 하지만 지금은 의뢰를 받을 수 없어. 내 프로젝트에 집중해야 하거든. 하지만 그렇다고 사람들이 내게 도움을 청하지 않는 건 아니지!\n\n일손이 좀 필요해, 좀 더 정확히 말하자면 지즈 피직스에게 네 손길이 필요할 거야.\n\n강한 다이너마이트를 만들 수 있다면, 칼바람 바위산 아래에 있는 피직스의 작업장에 두고 와.",
    },
    [28465] = {
        ["T"] = "사령관 아그로고쉬의 주문",
        ["O"] =
        "오글소프 오브노티쿠스는 당신이 기계공학 기술을 사용하여 대형 청동 폭탄 20개를 제작한 다음, 가시덤불 골짜기의 그롬골에 있는 사령관 아그로고쉬에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "반갑습니다, $N! 동료 기계공학자를 만나는 건 언제나 기쁜 일이죠. 비록 당신이 호드 소속이라 하더라도 말입니다.\n\n말이 나와서 말인데... 그롬골의 아그로고쉬 사령관이 대형 청동 폭탄을 몇 개 요청하는 전갈을 보냈습니다. 저는 표면적으로는 진영 분쟁에서 중립을 지키고 있지만, 이 주문만큼은 호드 기계공학자가 채워주었으면 합니다. 그게 바로 당신이란 뜻이죠!",
    },
    [28466] = {
        ["T"] = "타르그의 주문",
        ["O"] =
        "타르그는 당신이 기계공학 기술을 사용하여 태엽장치 5개를 제작한 다음, 먼지진흙 습지대의 담쟁이 마을에 있는 타르그에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "타르그 가장 똑똑한 오우거 아니지만 타르그 많은 거 눈치챈다. 그림자와 빛, 밝음과 어둠. 타르그 시간에 대해 궁금하다. 타르그 시간 보는 법 모르지만 태엽장치 시간에 유용하다는 거 안다. 타르그에게 태엽장치 많이 가져와라. 그럼 타르그 시간 많아질 거다!",
    },
    [28467] = {
        ["T"] = "호르니즈 브림버즐의 주문",
        ["O"] =
        "투크는 당신이 기계공학 기술을 사용하여 조밀한 다이너마이트 20개를 제작한 다음, 잊혀진 땅의 코도 무덤에 있는 호르니즈 브림버즐에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "그늘수렵 마을에 온 걸 환영해. 이봐, 당신 기계공학자 맞지? 당신 손가락에 박힌 만능 스패너 굳은살을 보면 알 수 있어. 들어온 주문 하나 처리해 볼래?\n\n코도 무덤 밑에 사는 한 고블린이 조밀한 다이너마이트를 좀 사고 싶다고 주문을 넣었어. 저도 고블린 기계공학자들에 대해선 건강한 직업적 존경심을 가지고 있지만, 이 자는 연금술사라고.... 대체 다이너마이트를 어디다 쓰려는 건지 모르겠어. 네가 원한다면 이 주문 전부 가져가!",
    },
    [28468] = {
        ["T"] = "명사수 갈라마브의 주문",
        ["O"] =
        "니카 블러드스카는 당신이 기계공학 기술을 사용하여 초정밀 고글 1개를 제작한 다음, 황야의 땅의 카르가스에 있는 명사수 갈라마브에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "갈라마브가 조준하는 데 어떤 장비의 도움도 받지 않는다는 사실에 꽤 놀랐다. 초정밀 고글같이 기계공학이 그를 도울 수 있다는 걸 그저 몰라서 안 쓴다고 생각한다! 혹시 어디서 그 고글을 구할 수 있는지 아나?",
    },
    [28469] = {
        ["T"] = "낚시꾼 카툼의 주문",
        ["O"] =
        "낚시꾼 카툼은 당신이 기계공학 기술을 사용하여 미스릴관 5개를 제작한 다음, 동부 내륙지의 깨진엄니 마을에 있는 낚시꾼 카툼에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "낚시해 본 적 있소, $N? 난 낚시를 아주 좋아하지만, 썩은가지부족 트롤들이 내가 제일 좋아하는 낚시터에서 날 쫓아냈을 때 제일 아끼던 낚싯대를 잃어버렸다오.\n\n마을에 기계공학자가 없어서 언제 새 낚싯대를 장만할지 모르겠소. 혹시 미스릴관을 몇 개 구하게 된다면, 당신 친구 카툼을 떠올려주지 않겠소? 그걸로 새 낚싯대를 만들 수 있을 거요.",
    },
    [28470] = {
        ["T"] = "레미 콜드아이의 주문",
        ["O"] =
        "레미 콜드아이는 당신이 기계공학 기술을 사용하여 고급 표적 허수아비 2개를 제작한 다음, 타나리스의 안제와타에 있는 레미 콜드아이에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "훈련시켜야 할 그런트는 많은데 모두에게 나눠줄 방어구가 부족하군, $N. 대장간에서 방어구가 만들어지기를 기다리는 자들은 부상을 피하기 위해 조심해서 대련해야만 해. 그래서 네가 필요한 거다 -- 네 기계공학 기술에 대한 소문이 너보다 먼저 이곳에 도착했지. 내 신병들을 위해 고급 표적 허수아비 몇 개가 필요하다. 도와줄 텐가?",
    },
    [28471] = {
        ["T"] = "비고의 주문",
        ["O"] =
        "신드라 톨그래스는 당신이 기계공학 기술을 사용하여 유동성 제동장치 5개를 제작한 다음, 페랄라스의 글룩의 요새에 있는 비고에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "당신 기계공학자인가요? 아, 죄송해요... 그저 그렇게 보여서요.\n\n얼마 전 고블린 한 명이 유동성 제동장치를 좀 찾고 있었어요. 전 그런 종류의 물건은 취급하지 않지만, 기계공학자가 온다면 자긴 글룩의 요새에 있을 거라고 했어요. 숲을 뚫고 그곳에 갈 수 있다면 동전을 좀 벌 수 있는 좋은 기회가 될 거예요!",
    },
    [28472] = {
        ["T"] = "제시 문보우의 주문",
        ["O"] =
        "알트소바 레이지토템은 당신이 기계공학 기술을 사용하여 초정밀 조준경 2개를 제작한 다음, 악령숲의 에메랄드 성소에 있는 제시 문보우에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "오! 기계공학자로군! 자네 손톱 밑의 기름때를 보니 한눈에 알겠어!\n\n저기, 고용할 수 있나? 내가 에메랄드 성소에 내려갔을 때 한 나이트 엘프가 초정밀 조준경을 좀 사고 싶다고 하더군. 내 양심상 나이트 엘프에겐 팔 수 없지만 그녀는 세나리온 의회 소속이야. 이 일에 관심이 있다면 길을 따라 남쪽으로 가봐.",
    },
    [28473] = {
        ["T"] = "피의경비병 글루시의 주문",
        ["O"] =
        "그룰 다크블레이드는 당신이 기계공학 기술을 사용하여 고폭탄 20개를 제작한 다음, 아즈샤라의 발로르모크에 있는 피의경비병 글루시에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "매일 밥 먹을 때마다 듣는 소리라곤 멀록의 위협뿐이야. 므르르르글, 롸아아아글 등등. 피의경비병 글루시는 그것들에게 완전히 집착하고 있지.\n\n이 마을에는 기계공학 작업을 할 수 있는 가열로가 없지만, 네가 다른 곳에서 고폭탄을 몇 개 만들어 글루시에게 가져다준다면, 아마 그가 \"멀록의 위협\"으로부터 안전하다고 느끼고 입을 닥칠지도 몰라!",
    },
    [28474] = {
        ["T"] = "탐네르 폴의 주문",
        ["O"] =
        "탐네르 폴은 당신이 응급치료 기술을 사용하여 리넨 붕대 20개를 제작한 다음, 던 모로의 카라노스에 있는 탐네르 폴에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "카라노스는 자신을 증명하고 싶어 안달 난 젊고 풋내기 신병들로 빠르게 채워지고 있지. 그리고 훈련에는 멍과 찰과상, 그리고 상식보다 앞서는 자존심이 뒤따르기 마련이고.\n\n붕대 재고가 바닥나고 있네. 리넨 붕대 20개만 가져다주면, 이런 가벼운 상처들이 악화되기 전에 계속 치료할 수 있을 걸세.",
    },
    [28475] = {
        ["T"] = "고고학자 에버릿의 주문",
        ["O"] =
        "고고학자 호올리는 당신이 응급치료 기술을 사용하여 두꺼운 리넨 붕대 20개를 제작한 다음, 어둠해안의 렘트래블의 발굴현장에 있는 고고학자 에버릿에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "렘트래블의 발굴현장에 있는 고고학자 에버릿에게서, 그들이 발굴한 골렘들과 약간의 자잘한 사고가 있었다는 소식을 받았습니다.\n\n응급치료로 상처를 싸매는 기술을 아시나요? 만약 그렇다면, 두꺼운 리넨 붕대를 좀 넉넉히 준비해서 발굴현장에 있는 에버릿에게 전해주실 수 있을까요? 여기서 길을 따라 남쪽으로 꽤 멀리 떨어져 있습니다.",
    },
    [28476] = {
        ["T"] = "순찰대원 도즈의 주문",
        ["O"] =
        "브링크 스패너크랭크는 당신이 응급치료 기술을 사용하여 해독제 3개를 제작한 다음, 그늘숲 중심부의 야간 경비대 야영지에 있는 순찰대원 도즈에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "독에 대해선 내가 잘 알지, $C. 연구도 했고, 제조도 해봤고, 치료도 해봤어. 그리고 이 숲에서는 말이야? 거미에 한두 번 물리는 것쯤은 대처할 준비를 단단히 하는 게 좋을 거야.\n\n야간 경비대는 거미에게 물렸을 때 실질적으로 도움이 될 만한 물건을 좀 필요로 해. 순찰대원 도즈에게 해독제 3개를 가져다줘. 거창한 건 아니지만, 그와 순찰대가 도랑에 처박혀 죽는 대신 계속 발로 뛰게 해줄 거야.",
    },
    [28477] = {
        ["T"] = "에이미 데이븐포트의 주문",
        ["O"] =
        "에이미 데이븐포트는 당신이 응급치료 기술을 사용하여 양모 붕대 20개를 제작한 다음, 붉은마루 산맥의 레이크샤이어에 있는 에이미 데이븐포트에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "저기요, 가방에 든 그거 붕대인가요? 당신의 도움이 필요해요. 몇몇 경비병들이 산등성이 근처에서 너무 대담하게 굴다가 오크 순찰대와 정면으로 맞닥뜨렸어요. 지금 레이크샤이어로 돌아오긴 했지만, 음... 그중 몇 명은 한동안 경계 근무를 서지 못할 것 같네요.\n\n의료 용품이 부족해요. 양모 붕대 20개를 가져다주시면, 경비병들에게 꼭 전달할게요. 살아 돌아온 것만도 다행인 사람들이죠 -- 계속 살 수 있게 해주자고요.",
    },
    [28478] = {
        ["T"] = "센트리카 나이트송의 주문",
        ["O"] =
        "센트리카 나이트송은 당신이 응급치료 기술을 사용하여 두꺼운 양모 붕대 20개를 제작한 다음, 돌발톱 산맥의 돌발톱 숲에 있는 센트리카 나이트송에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "연금술은 경이롭습니다. 화상에 바르는 물약, 고통을 줄여주는 비약, 힘을 솟게 하는 영약 등 여러 가지가 있죠... 하지만 어떤 상처에는 그저 깨끗한 천 조각과 흔들림 없는 손길만 있으면 될 때도 있습니다.\n\n이 초소에는 치유사가 배치되어 있지 않습니다, $C. 그러니 두꺼운 양모 붕대 20개를 가져다주십시오. 보급품만 충분하다면 가벼운 상처는 직접 치료하고, 연금술 보급품은 심각한 사태를 위해 아껴둘 수 있을 겁니다.",
    },
    [28479] = {
        ["T"] = "렌도우의 주문",
        ["O"] =
        "렌도우는 당신이 응급치료 기술을 사용하여 강력한 해독제 3개를 제작한 다음, 버섯구름 봉우리의 탈라나르에 있는 렌도우에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "숲 가장자리인 이곳의 높은 하늘에는 와이번들이 배회하고 있습니다. 놈들의 독침은 빠르고, 잔인하며, 즉각 대처하지 않으면 치명적입니다. 우린 이미 짐말 두 마리를 잃었고 하마터면 정찰병 한 명마저 잃을 뻔했습니다.\n\n당신은 응급치료에 능숙하시군요, 딱 보면 알 수 있죠. 강력한 해독제 3개가 필요합니다. 다음에 독침에 쏘인 생물은 독이 퍼지기 전에 제 발로 돌아오지 못할 수도 있으니, 우린 대비해야만 합니다.",
    },
    [28480] = {
        ["T"] = "여관주인 핀미르의 주문",
        ["O"] =
        "여관주인 핀미르는 당신이 응급치료 기술을 사용하여 두꺼운 비단 붕대 20개를 제작한 다음, 슬픔의 늪의 은신처에 있는 여관주인 핀미르에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이곳 은신처의 추방자들은 너무 많은 것을 겪었습니다. 질병과 상처, 그리고 산산이 부서진 세계로부터의 긴 여정을 거치며 치유의 여력조차 남지 않았습니다.\n\n두꺼운 비단 붕대 20개를 내어주실 수 있다면, 가장 도움이 필요한 드레나이에게 전달하겠습니다. 보잘것없어 보일지라도, 단순하고 부드러운 천 조각 하나가 희망을 가져다줄 수 있습니다.",
    },
    [28481] = {
        ["T"] = "베단 블루워터의 주문",
        ["O"] =
        "베단 블루워터는 당신이 응급치료 기술을 사용하여 마법 붕대 20개를 제작한 다음, 페랄라스의 페더문 요새에 있는 베단 블루워터에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "저는 티란데 위스퍼윈드 님의 명을 받고 이곳에 터를 잡았던 고대 나이트 엘프들을 연구하러 왔습니다. 하지만 페랄라스의 폐허는 고대부터 존재해 온 위험한 곳이라는 걸 깨달았죠. 떨어지는 돌, 날카로운 뿌리, 이끼 아래 숨겨진 것들 말입니다. 이곳을 제대로 연구하려면 자잘한 부상에 대비해야만 합니다.\n\n조사를 시작하기 전에 검토할 것이 많으니 당신의 도움을 받고 싶습니다. 마법 붕대 20개를 제게 가져다주십시오. 찰과상이나 삔 것 때문에 원정을 중단하진 않겠지만, 그렇다고 치료하지 않고 방치하지도 않을 겁니다.",
    },
    [28482] = {
        ["T"] = "가빅 그라임세일의 주문",
        ["O"] =
        "가빅 그라임세일은 당신이 응급치료 기술을 사용하여 비단 붕대 20개를 제작한 다음, 가시덤불 골짜기의 무법항에 있는 가빅 그라임세일에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "난 예전만큼 빠르지 않은데, $N, 바다는 그런 걸 봐주지 않지. 저 밖에선 작은 긁힘 하나가 순식간에 악화될 수 있어. 선장님은 항구에서 볼일이 끝나자마자 바로 출항할 준비를 하라고 하셨지. 나? 난 밧줄에 다시 매달려야 하기 전에 좀 쉬고 싶어.\n\n알았어! 비단 붕대 20개만 좀 가져다주겠어? 아직 커틀라스는 휘두를 수 있지만, 요즘은 몸뚱이를 온전히 유지하는 데 도움이 조금 더 필요하거든.",
    },
    [28483] = {
        ["T"] = "대족장 운갈의 주문",
        ["O"] =
        "대족장 운갈은 당신이 응급치료 기술을 사용하여 두꺼운 마법 붕대 20개를 제작한 다음, 아즈샤라의 검은아귀 마을에 있는 대족장 운갈에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "악마들이 불과 어둠으로 일격을 가한다. 우리는 맞서 싸우지만 부상자가 너무 많다.\n\n약초나 마법 없이도 낫게 하는 당신의 치료술과 천 조각에 대해 들은 바 있다. 나도 한번 써보고 싶군. 두꺼운 마법 붕대 20개를 가져와라. 당신네 방식이 우리 부족에게 도움이 되는지 보겠다.",
    },
    [28484] = {
        ["T"] = "리키 카트스파크의 주문",
        ["O"] =
        "리키 카트스파크는 당신이 응급치료 기술을 사용하여 룬매듭 붕대 20개를 제작한 다음, 운고로 분화구의 공포의 터에 있는 리키 카트스파크에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "당신같이 솜씨 좋은 분을 여기서 뵙게 되어 다행이군요, $C. 제일리사는 아직도 일어나지 못하고 있어요. 그 바깥에서 그녀를 덮친 건 그저 이빨과 발톱만이 아니었어요. 엄청난 분노가 서려 있었고, 회복하기까지 아주 오랜 시간이 걸릴 거예요.\n\n그녀를 안정시키느라 붕대 재고를 대부분 써버렸어요. 더 필요합니다. 룬매듭 붕대 20개를 가져다주신다면, 그녀가 회복하는 데 정말 큰 도움이 될 겁니다.",
    },
    [28485] = {
        ["T"] = "멀그리스 딥리버의 주문",
        ["O"] =
        "멀그리스 딥리버는 당신이 응급치료 기술을 사용하여 두꺼운 룬매듭 붕대 20개를 제작한 다음, 서부 역병지대의 저술가의 은신처에 있는 멀그리스 딥리버에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "나를 동정하지 마시오, $C. 내 삶은 이미 끝을 향해 가고 있으니... 상처는 너무 많고 빛은 너무나 희미하오. 하지만 아주 희미하게나마 희망의 끈은 아직 남아 있소.\n\n당신이 내게 두꺼운 룬매듭 붕대 20개를 가져다준다면, 어쩌면 조금만 더 버틸 수 있을지도 모르겠소... 숲 위로 떠오르는 일출을 한 번만 더 볼 수 있을 때까지 말이오.",
    },
    [28486] = {
        ["T"] = "비라 영후프의 주문",
        ["O"] =
        "비라 영후프는 당신이 응급치료 기술을 사용하여 리넨 붕대 20개를 제작한 다음, 멀고어의 블러드후프 마을에 있는 비라 영후프에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "야영지는 자신을 증명하고 싶어 안달 난 젊은 전사들, 풋내기들로 빠르게 채워지고 있지. 그리고 훈련에는 멍과 찰과상, 그리고 상식보다 앞서는 자존심이 뒤따르기 마련이고.\n\n붕대 재고가 바닥나고 있네. 리넨 붕대 20개만 가져다주면, 이런 가벼운 상처들이 악화되기 전에 계속 치료할 수 있을 거야.",
    },
    [28487] = {
        ["T"] = "레인 요릭의 주문",
        ["O"] =
        "고위집행관 하드렉은 당신이 응급치료 기술을 사용하여 두꺼운 리넨 붕대 20개를 제작한 다음, 은빛소나무 숲 북쪽의 농장에 있는 레인 요릭에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "실종된 죽음의추적자들을 찾아 나설 생각이라면, 그들에게 필요할 만한 것을 준비해 두는 게 좋을 거다.\n\n난 두꺼운 리넨 붕대를 말하고 있는 거다, $C. 넉넉히 준비해서 요릭 일행을 찾을 때 꼭 가져가도록 해라.",
    },
    [28488] = {
        ["T"] = "마그그랜 어스바인더의 주문",
        ["O"] =
        "탐라 윈드필드는 당신이 응급치료 기술을 사용하여 해독제 3개를 제작한 다음, 돌발톱 산맥의 해바위 야영지에 있는 마그그랜 어스바인더에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "독에 대해선 내가 잘 알지, $C. 독은 이 땅의 방어 수단 중 하나이며, 이 산맥에서는 말이야? 거미에 물리거나 와이번 독침에 쏘이는 것에 대비를 단단히 하는 게 좋을 거야... 둘 다일 수도 있고!\n\n이곳에 주둔한 그런트들은 독에 대처할 실질적인 자원이 필요해. 해독제 3개를 마그그랜 어스바인더에게 가져다줘. 우리는 치유하기 위해 독의 근원을 사용할 것이다.",
    },
    [28489] = {
        ["T"] = "칼리야 스톰슈의 주문",
        ["O"] =
        "칼리야 스톰슈는 당신이 응급치료 기술을 사용하여 양모 붕대 20개를 제작한 다음, 불모의 땅의 타우라조 야영지에 있는 칼리야 스톰슈에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "저기, 가방에 든 그거 붕대야? 네 도움이 필요해. 나도 거친 황야로 모험을 떠나고 싶은데, 그전에 꼭 필요한 물품들이 좀 있거든. 무기, 식량, 그리고 네가 도와줄 수 있는 것!\n\n의료 용품이 부족해. 양모 붕대 20개를 가져다주면 요긴하게 쓸게. 여기 무사히 있는 것만도 행운이니까 -- 이 상태를 유지해야지.",
    },
    [28490] = {
        ["T"] = "연금술사 라이던의 주문",
        ["O"] =
        "연금술사 라이던은 당신이 응급치료 기술을 사용하여 두꺼운 양모 붕대 20개를 제작한 다음, 언덕마루 구릉지의 타렌 제분소에 있는 연금술사 라이던에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "연금술은 경이롭지, $N. 화상에 바르는 물약, 고통을 줄여주는 비약, 힘을 솟게 하는 영약 등 여러 가지가 있지만... 어떤 상처에는 그저 깨끗한 천 조각과 흔들림 없는 손길만 있으면 될 때도 있거든.\n\n내 귀중한 보급품을 치유 물약에 낭비할 순 없어. 그러니 두꺼운 양모 붕대 20개를 가져다줘. 보급품만 충분하다면 경비병들의 가벼운 상처는 직접 치료하고, 연금술 보급품은 심각한 사태를 위해 아껴둘 수 있을 테니까.",
    },
    [28491] = {
        ["T"] = "엘루의 주문",
        ["O"] =
        "엘루는 당신이 응급치료 기술을 사용하여 강력한 해독제 3개를 제작한 다음, 버섯구름 봉우리의 높새바람 봉우리에 있는 엘루에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이곳 봉우리의 높은 하늘에는 와이번들이 배회하고 있어. 난 그 애들을 정말 아끼지만, 그 독침은 빠르고 잔인하며 즉각 대처하지 않으면 치명적이라는 건 인정할 수밖에 없어. 우린 최근 짐코도 두 마리를 잃었고 하마터면 정찰병 한 명마저 잃을 뻔했어.\n\n넌 응급치료에 능숙하구나, 딱 보면 알 수 있지. 강력한 해독제 3개가 필요해. 다음에 독침에 쏘인 생물은 독이 퍼지기 전에 제 발로 돌아오지 못할 수도 있으니, 우린 대비해야만 해.",
    },
    [28492] = {
        ["T"] = "벤고르의 주문",
        ["O"] =
        "벤고르는 당신이 응급치료 기술을 사용하여 두꺼운 비단 붕대 20개를 제작한 다음, 슬픔의 늪의 스토나드에 있는 벤고르에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "온몸이 쑤시는군, $C. 하지만 빌어먹을 치유 마법으로 내 몸에 손댈 생각은 마. 난 그놈의 \"빛\" 따위엔 요만큼도 관심 없으니까.\n\n내 상처엔 평범한 약으로도 충분해, 아니면 차라리 죽음을 택하겠다. 두꺼운 비단 붕대를 20개만 내어준다면, 다시 일어설 수 있을지도 모르겠군.",
    },
    [28493] = {
        ["T"] = "블라이즈 몽고메리의 주문",
        ["O"] =
        "블라이즈 몽고메리는 당신이 응급치료 기술을 사용하여 마법 붕대 20개를 제작한 다음, 페랄라스의 모자케 야영지에 있는 블라이즈 몽고메리에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "지식의 전달자들의 명을 받아 이곳에 터를 잡았던 고대 나이트 엘프들을 연구하러 왔지만, 페랄라스의 폐허는 고대부터 존재해 온 위험한 곳이라는 걸 깨달았소. 이곳을 제대로 연구하려면 자잘한 부상에 대비해야만 하오. 여기서 추가 보급품이 오기를 기다리고 있는데, 무슨 이유에서인지 아직 도착하지 않았소.\n\n조사를 시작하기 전에 검토할 것이 많으니 당신의 도움을 받아 속도를 좀 내고 싶소. 마법 붕대 20개를 내게 가져다주시오. 찰과상이나 삔 것 때문에 원정을 중단하진 않겠지만, 그렇다고 치료하지 않고 방치하지도 않을 것이오.",
    },
    [28494] = {
        ["T"] = "제이슨 마더스의 주문",
        ["O"] =
        "제이슨 마더스는 당신이 낚시 기술을 사용하여 날 비단잉어 20마리를 모은 다음, 엘윈 숲의 수정 호수에 있는 제이슨 마더스에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "작은 물고기가 다 떨어졌어. 오늘 아침에, 그것 때문에 주먹다짐이라도 벌일 기세였던 요리사에게 마지막 남은 걸 다 팔아버렸거든.\n\n낚싯대와 안정된 손길만 있다면 신선한 생선이 잔뜩 필요해. 날 비단잉어 20마리를 가져다줘. 이 근방 사람들은 내 물건이 항상 채워져 있을 거라 기대하니, 그들을 그냥 돌려보내는 일은 없었으면 좋겠군.",
    },
    [28495] = {
        ["T"] = "민병대원 가리엘의 주문",
        ["O"] =
        "민병대원 가리엘은 당신이 낚시 기술을 사용하여 날 줄무늬고등어 20마리를 모은 다음, 서부 몰락지대의 감시의 언덕에 있는 민병대원 가리엘에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "스톰윈드에 우리 사람들을 위한 식량을 더 요청했지만, 돌아오는 건 관료주의적인 허튼소리뿐이었소. 민병대에게 필요한 건 단백질이지 약속이 아니오.\n\n보급품이 또 부족해졌고, 지금은 소금에 절인 고기보다 신선한 생선을 구하는 게 더 쉽소. 낚싯대가 있군. 이 굶주린 입들을 채우는 걸 도와주겠소? 할 수 있다면, 날 줄무늬고등어 20마리를 잡아 여기 감시의 언덕에 있는 내게 가져다주시오.",
    },
    [28496] = {
        ["T"] = "할 맥알리스터의 주문",
        ["O"] =
        "할 맥알리스터는 당신이 낚시 기술을 사용하여 날 긴주둥이진흙퉁돔 20마리를 모은 다음, 언덕마루 구릉지의 남녘해안에 있는 할 맥알리스터에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "오늘 아침에 진흙퉁돔을 마지막으로 다 요리해 버렸지 뭐야. 정오도 되기 전에 다 팔렸다고! 뜨거운 팬에 구워 약간의 향신료를 곁들인 그 맛에 사람들은 환장하거든.\n\n낚시할 시간 있으면, 날 긴주둥이진흙퉁돔 20마리만 갖다줘. 요리는 내가 할 테니 -- 넌 계속 잡아 오기만 해.",
    },
    [28497] = {
        ["T"] = "워그 딥워터의 주문",
        ["O"] =
        "워그 딥워터는 당신이 낚시 기술을 사용하여 날 호수프렌지 20마리를 모은 다음, 모단 호수에 있는 워그 딥워터에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "이 근방에 새로 온 $g어부:어부;인가? 어디 솜씨 좀 겨뤄볼 텐가? 난 자네가 미끼 끼우는 법을 알기도 전부터 호수프렌지를 낚아 올렸어. 내 수확량을 이길 수 있을 것 같나?\n\n호수프렌지 20마리를 가져와서 자네 솜씨가 어느 정도인지 보여주게나. 오늘 제일 큰 놈을 낚는 게 나라고 해도 너무 상심하진 말라고.",
    },
    [28498] = {
        ["T"] = "파수꾼 오나에야의 주문",
        ["O"] =
        "파수꾼 오나에야는 당신이 낚시 기술을 사용하여 날 총명어 20마리를 모은 다음, 잿빛 골짜기의 마에스트라 주둔지에 있는 파수꾼 오나에야에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "마에스트라 주둔지의 파수꾼들은 보급품이 바닥나고 있는데, 특히 신선한 음식이 절실합니다. 밤낮으로 정찰을 하다 보면 말린 고기만으로는 한계가 있거든요.\n\n날 총명어 20마리가 필요합니다. 가볍고, 영양가 높으며, 작은 불꽃으로도 쉽게 요리할 수 있죠. 가져다만 주신다면, 하나도 낭비하지 않고 다 먹어 치우겠습니다.",
    },
    [28499] = {
        ["T"] = "킬륵스의 주문",
        ["O"] =
        "킬륵스는 당신이 낚시 기술을 사용하여 날 무지개날개다랑어 20마리를 모은 다음, 불모의 땅의 톱니항에 있는 킬륵스에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "무법항부터 검은심연 나락까지 온갖 물고기는 다 잡아봤지만, 무지개날개다랑어는 한 번도 낚아본 적 없어. 소문에 의하면 일출처럼 반짝이고 맛은 두 배나 좋다고 하더군.\n\n날 무지개날개다랑어 20마리만 가져다줘. 내 두 눈으로 직접 확인해 보고 싶거든. 그리고 남은 건 튀겨 먹을지도 모르지. 거기에 무슨 양념을 쳐서 먹을까?",
    },
    [28500] = {
        ["T"] = "노인 헤밍의 주문",
        ["O"] =
        "노인 헤밍은 당신이 낚시 기술을 사용하여 날 돌비늘대구 20마리를 모은 다음, 가시덤불 골짜기의 무법항에 있는 노인 헤밍에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "물가에 그저 가만히 앉아 귀 기울여 본 적 있나? 거기에 기쁨이 있는 거라네. 금화도 아니고, 물고기도 아니지. 그저 고요함과 낚싯대를 던지는 행위 자체 말이야.\n\n그래도... 혹시 날 돌비늘대구를 낚게 된다면, 거절하진 않겠네. 그걸 보면 내가 애초에 낚시를 시작했던 이유가 떠오르거든.",
    },
    [28501] = {
        ["T"] = "스미드 스크래블스크류의 주문",
        ["O"] =
        "스미드 스크래블스크류는 당신이 낚시 기술을 사용하여 기름기 많은 아귀 20마리를 모은 다음, 잊혀진 땅의 스크래블스크류의 야영지에 있는 스미드 스크래블스크류에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "다른 고블린들은 이익을 내겠다고 땅을 파거나, 베어내거나, 무언가를 폭파하느라 혈안이 되어 있지. 아마추어들 같으니.\n\n육지가 끝나고 바다가 시작된다는 걸 무시해선 안 돼. 이익도 마찬가지로 바다에서 시작된다고! 뭘 잡아야 할지만 안다면 바다에는 금이 넘쳐나지. 기름기 많은 아귀 같은 거 말이야. 연금술사들이 아주 비싼 값을 쳐준다고.\n\n기름기 많은 아귀 20마리만 가져와 봐. 땅이나 파대는 멍청이들에게 진짜 돈은 파도에서 나온다는 걸 보여주지.",
    },
    [28502] = {
        ["T"] = "시몬 캔트렐의 주문",
        ["O"] =
        "시몬 캔트렐은 당신이 낚시 기술을 사용하여 날 대형 총명어 20마리를 모은 다음, 알터랙 산맥의 라벤홀트 장원에 있는 시몬 캔트렐에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "고향인 아스트라나르에서 우린 총명어의 담백하고 섬세하며 미묘한 맛을 최고로 쳤어요. 이곳 알터랙에서 총명어를 찾을 거라곤 전혀 예상치 못했는데, 훨씬 더 큰 놈들이 있을 줄이야!\n\n이 대형 총명어는 추억과 놀라움의 선물입니다. 날 대형 총명어 20마리를 가져다주시겠어요? 내가 기억하는 그 맛이 여전한지 꼭 확인해 보고 싶거든요.",
    },
    [28503] = {
        ["T"] = "\"늪지눈깔\" 자를의 주문",
        ["O"] =
        "\"늪지눈깔\" 자를은 당신이 낚시 기술을 사용하여 날 표범메기 20마리를 모은 다음, 먼지진흙 습지대의 수렁진흙 장원에 있는 \"늪지눈깔\" 자를에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "내가 늪에 산다고 사람들은 내가 물을 좋아할 거로 생각하지. 확실히 짚고 넘어갈게. 난 싫어. 춥고, 축축하고, 어디에나 들러붙는다고.\n\n하지만 생선? 생선은 좋아. 특히 메기.\n\n날 표범메기 20마리만 가져다줘, 그럼 축축한 장화 따윈 잊어버릴 수 있을지도 모르니까.",
    },
    [28504] = {
        ["T"] = "모렌 리버벤드의 주문",
        ["O"] =
        "모렌 리버벤드는 당신이 낚시 기술을 사용하여 날 미스릴송어 20마리를 모은 다음, 달숲의 밤의 안식처에 있는 모렌 리버벤드에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "엘루네아라 호수에는 미스릴송어가 우글거립니다. 다른 물고기 떼를 몰아내고, 갈대를 훼손하며, 호수의 균형을 깨뜨리고 있죠.\n\n그 개체 수를 줄여야 합니다. 낚시를 할 줄 아신다면 날 미스릴송어 20마리만 가져다주십시오. 생태계와 우리 저녁 식탁 양쪽 모두에 큰 도움이 될 겁니다.",
    },
    [28505] = {
        ["T"] = "멕넬의 주문",
        ["O"] =
        "멕넬은 당신이 낚시 기술을 사용하여 날 점박이놀래기 20마리를 모은 다음, 페랄라스의 글룩의 요새에 있는 멕넬에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "글룩의 집행자들 고기 좋아한다! 생선도 좋아한다! 낚싯대 있네, 낚시 잘하겠다. 글룩의 친구들을 위해 날 점박이놀래기 잔뜩 가져와라. 그럼 우리도 널 친구로 생각하겠다.",
    },
    [28506] = {
        ["T"] = "아탈아이 추방자의 주문",
        ["O"] =
        "아탈아이 추방자는 당신이 낚시 기술을 사용하여 날 해비늘연어 20마리를 모은 다음, 동부 내륙지의 샤드라알로에 있는 아탈아이 추방자에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "추방은 쓰디쓴 법. 차가운 돌, 오래된 유령, 그리고 솥에는 온기조차 없다.\n\n하지만 난 해비늘연어의 맛을 기억한다. 풍부하고, 황금빛이며, 오랫동안 잊힌 강물에서 온 온기로 가득한 그 맛. 날 해비늘연어 20마리만 가져와다오. 그러면... 단 한 끼 식사일지라도 그림자보다 더 나은 무언가를 떠올릴 수 있을 테니까.",
    },
    [28507] = {
        ["T"] = "리키 카트스파크의 주문",
        ["O"] =
        "리키 카트스파크는 당신이 낚시 기술을 사용하여 날 붉은퉁돔 20마리를 모은 다음, 운고로 분화구의 공포의 터에 있는 리키 카트스파크에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "저기, 가방에 묶어놓은 거 낚싯대인가요? 혹시 저희 부탁 좀 들어주실 수 있나요?\n\n제일리사가 다치는 바람에 계획보다 더 오래 황야에 머물게 되어서 신선한 식량이 다 떨어졌어요. 굶어 죽진 않겠지만, 매일 똑같은 배급 식량만 먹는 건 좀... 뭐랄까, 너무 지루하잖아요!\n\n뭔가 신선한 게 필요해요. 너무 거창한 거 말고요! 낚시해 주실 수 있다면 날 붉은퉁돔 정도면 충분해요.",
    },
    [28508] = {
        ["T"] = "요르바 스크류스피곳의 주문",
        ["O"] =
        "요르바 스크류스피곳은 당신이 낚시 기술을 사용하여 날 빛깔좋은 망둥어 20마리를 모은 다음, 타나리스의 스팀휘들 항구에 있는 요르바 스크류스피곳에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "케잔에 있는 무역회사 간부들이 말하길, \"배가 들어오기만을 가만히 앉아 기다리진 마라.\"라더군.\n\n뭐, 내 배는 늦고 있고 난 확실히 여기 가만히 앉아만 있어. 그래서 생각했지 -- 기왕 이럴 거면 뭐라도 먹는 게 낫겠다고.\n\n날 빛깔좋은 망둥어 20마리만 가져다줘. 크고, 맛있고, 내 초조함 대신 씹을 거리가 되어줄 테니까.",
    },
    [28509] = {
        ["T"] = "아리덴 엘리스의 주문",
        ["O"] =
        "아리덴 엘리스는 당신이 낚시 기술을 사용하여 날 유리비늘연어 20마리를 모은 다음, 저승바람 고개의 아리덴의 야영지에 있는 아리덴 엘리스에게 주문품을 가져가기를 원합니다.",
        ["D"] =
        "솔직히 말해서, 카라잔으로 돌아가기로 마음먹었을 때 내가 필요할 \"야영 식량\"의 규모를 제대로 생각하지 못했어요. 보존 식량은 잔뜩 챙겨왔지만... 장원에서 먹었던 음식은 고사하고, 마을에서 먹던 음식에 비하면 형편없죠.\n\n전 낚시에 소질이 없어요 -- 너무 축축하고 벌레도 많으니까요. 하지만 당신이 날 유리비늘연어 20마리만 가져다준다면, 병조림이 아닌 제대로 된 식사를 할 수 있어서 정말 고마울 거예요.",
    },
    [28510] = {
        ["T"] = "킴자엘의 의뢰",
        ["O"] =
        "킴자엘은 당신이 낚시[cite: 10] 기술을 사용해 검은발톱 바닷가재[cite: 6, 7] 20마리를 모아 아즈샤라[cite: 2]의 레가쉬 야영지[cite: 16]에 있는 자신에게 가져오기를 원합니다.",
        ["D"] =
        "그 저주받은 블러드 엘프들을 피해 도망치느라 노트, 도구, 간식 등 모든 것을 잃어버렸소. 아직 내가 제일 좋아하는 포크도 찾지 못했다오.\n\n지금 내게 정말 필요한 건 제대로 된 식사요. 검은발톱 바닷가재[cite: 6, 7] 20마리를 가져다준다면, 다음에 뭘 할지 생각하는 동안 최소한 배를 따뜻하게 채울 수 있을 거요.",
