        ["D"] =
        "학생들이... 불안해하고 있습니다. 그들의 식욕은 야망만큼이나 끝이 없죠. 의식의 방에서 또 기절하는 학생을 처리해야 한다면, 그들 중 한 명을 희생시켜야 할지도 모릅니다. 게다가 아직 충분히 살이 찌지도 않았어요.\n\n밤비늘퉁돔[cite: 23] 20마리를 가져다주세요. 영양가도 높고 준비하기도 쉬우며, 한 번에 너무 많은 포를 뜨지 않아도 될 만큼 그들의 정신을 예리하게 유지해 줄 겁니다.",
    },
