        ["O"] =
        "우탄 스틸워터[cite: 31]는 당신이 낚시[cite: 10] 기술을 사용해 비단잉어[cite: 22] 20마리를 모아 멀고어[cite: 20]의 블러드후프 마을[cite: 3]에 있는 자신에게 가져오기를 원합니다.",
        ["D"] =
        "물의 고요함, 낚싯줄이 팽팽해지는 느낌, 찌를 던진 후의 정적만큼 좋은 건 없습니다. 그것은 대지모신과 그녀의 모든 창조물과 교감하는 방법이지요.\n\n당신도 나만큼 낚시[cite: 10]를 즐긴다면, 비단잉어[cite: 22] 20마리를 가져다주십시오. 거래를 위한 것도, 동전을 위한 것도 아닙니다. 그저 낚시의 기쁨을 나누기 위해서입니다.",
