        ["D"] =
        "많은 사람들이 낚시할 줄 안다고 떠들어대지만, 그건 허풍에 불과합니다. 파도 앞에서 말은 아무 의미가 없죠. 중요한 건 잡은 물고기입니다.\n\n당신에게 그럴 능력이 있다고 생각하십니까? 줄무늬고등어[cite: 23] 20마리를 가져와서 당신이 미끼와 허세 그 이상이라는 것을 증명해 보십시오.",
