        ["D"] =
        "멧돼지[cite: 3], 코도[cite: 16] 등 고기는 넘쳐나. 하지만 기름진 고기와 뼈를 씹는 데 지쳤어.\n\n물고기[cite: 10]가 필요해. 불지느러미퉁돔[cite: 10] 20마리를 가져와. 맵고 신선한 걸로 말이야. 좋은 고기를 가져오면 제대로 거래해 주지.",
