        ["O"] =
        "약초상 포메로이[cite: 14]는 당신이 약초채집[cite: 14] 기술을 사용해 평온초 꽃잎[cite: 21] 20개를 모아 엘윈 숲[cite: 9]의 아조라의 탑[cite: 30]에 있는 사라 템플워스에게 가져가기를 원합니다.",
        ["D"] =
        "수습 약초상 맞으시죠? 성공할 기술이 있다는 것을 증명하고 싶나요? 기본부터 시작해 봅시다. 평온초 꽃잎[cite: 21] 20개를 꺾어 아조라의 탑[cite: 30]에 있는 사라 템플워스에게 가져가세요. 탑의 마법사 탑[cite: 18]을 위해 요리[cite: 6] 중인 무언가에 필요할 겁니다. 당신이 요령을 피우는지 그녀가 알아볼 거예요.",
