        ["D"] =
        "제가 카라노스[cite: 15]에 온 지 얼마 되지 않았지만, 제 약초 기술에 대한 소문은 이미 퍼졌습니다. 밀린 주문이 몇 개 있어서 도와줄 조수가 필요합니다.\n\n여기 앰버스틸 목장[cite: 1]에서 온 주문이 있습니다. 산양 타기[cite: 22] 훈련을 위해 은엽수잎[cite: 26] 한 다발을 간식으로 원하는 것 같군요. 이 일을 처리할 수 있습니까?",
