        ["D"] =
        "환영합니다, 동료 약초상. 기술을 연마할 과제를 원하십니까?\n\n알란나 레이븐아이[cite: 1]는 오라클 숲에서 마법부여[cite: 9] 기술을 연습하고 있는 동료 장인입니다. 그녀가 뱀뿌리[cite: 8] 한 꾸러미를 요청했습니다. 이것은 당신이 채우기에 훌륭한 주문이 될 것입니다.",
