        ["D"] =
        "무릎에 묻은 풀물 자국을 보니 약초채집[cite: 14]가시군요. 다행입니다! 방금 원정순찰대 오두막[cite: 10]에서 전갈 딱지[cite: 25]에 물린 감염을 치료하기 위해 마법초 꽃잎[cite: 18]이 절실히 필요하다는 전갈을 받았습니다. 다행히 당신에게 이 요청을 처리할 능력이 있어 보입니다.\n\n최대한 빨리 마법초 꽃잎[cite: 18] 20개를 바이린 스위프트윈드[cite: 32]에게 가져가세요. 하이 엘프를 실망시키고 싶지 않습니다. 그들은 이미 많은 고통을 겪었으니까요.",
