    [28521] = {
        ["T"] = "로난 골드리프의 의뢰",
        ["O"] =
        "얄다[cite: 34]는 당신이 약초채집[cite: 14] 기술을 사용해 찔레가시[cite: 4] 20개를 모아 어둠해안[cite: 7]의 골드리프 산장에 있는 로난 골드리프에게 가져가기를 원합니다.",
        ["D"] =
        "제가 보이나요? 약초상임에 틀림없군요... 엘룬[cite: 9]께 감사합니다. 드디어 제가 대화할 수 있는 분이 생겼네요!\n\n저는 3차 대전쟁 때 죽었지만 이 세계에 묶여 있습니다. 갚을 수 없는 빚이 있지만, 제가 할 수 있는 일은 여전히 해야 합니다. 아니, 당신에게 대신 해달라고 부탁해야겠군요. 찔레가시[cite: 4]를 모아 잿빛 골짜기[cite: 2]로 가는 길 서쪽에 있는 산장의 로난 골드리프에게 배달해 주시겠어요? 그는 누구에게서 온 것인지 알 겁니다.",
