        ["O"] =
        "마티 제인로즈[cite: 19]는 당신이 약초채집[cite: 14] 기술을 사용해 토끼엉겅퀴풀[cite: 28] 20개를 모아 붉은마루 산맥[cite: 23]의 레이크샤이어[cite: 16]에 있는 마티 제인로즈[cite: 19]에게 가져가기를 원합니다.",
        ["D"] =
        "저 빌어먹을 멧돼지[cite: 3], 서리먹보[cite: 3]가 또 내 약초 정원에 들어왔어요. 이번엔 내 토끼엉겅퀴풀[cite: 28]을 다 먹어치웠다고요!\n\n정원을 다시 가꾸려면 토끼엉겅퀴풀[cite: 28] 꺾꽂이 순이 더 필요하지만, 오우거[cite: 21]들이 돌아다녀서 마을 밖으로 멀리 나가는 건 너무 위험해요. 모험가처럼 보이는데, 절 도와주시겠어요?",
