        ["D"] =
        "동쪽 숲을 공격하는 호드[cite: 1]와 맞서 기꺼이 여행하려는 약초상을 만나게 되어 기쁩니다. 저는 은빛날개 전초기지[cite: 26] 파수꾼[cite: 25]들의 부상당함[cite: 34]을 돕는 데 시간을 보냈지만, 아스트라나르[cite: 2]에 생채기풀[cite: 4]이 필요한 아픈 아이가 있다는 소식을 들었습니다. 생채기풀[cite: 4] 20개를 모아 펠투러스 화이트문[cite: 21]에게 배달해 주시겠습니까?",
