        ["D"] =
        "좋은 아침입니다, $C. 저는 숙련 연금술[cite: 1] 시험을 시작할 준비가 되었지만, 문제가 하나 있습니다. 생명의 뿌리[cite: 17]를 연구하고 싶은데, 생명의 뿌리[cite: 17]가 가장 많이 나는 곳은 굶주린 퓨마[cite: 21]들로 가득하거나 호드[cite: 1]와 너무 가까워서 위험합니다.\n\n저를 위해 생명의 뿌리[cite: 17]를 모아주시겠습니까? 제가 만든 보급품과 물약[cite: 8]을 기꺼이 드리겠습니다.",
