        ["D"] =
        "여기 있는 다단가[cite: 6]는 가젯잔[cite: 11]에서부터 우리 보급품을 싣고 왔고, 굶주린 랩터[cite: 22]들을 쫓아내기도 한 정말 부지런한 일꾼 코도[cite: 16]랍니다. 그녀의 노력에 보답하고 싶어요.\n\n다단가[cite: 6]는 태양풀[cite: 28]을 좋아하지만, 전 약초상이 아니에요. 저를 좀 도와주시겠어요?",
