        ["D"] =
        "제 조카 크레이[cite: 13]는 썬더 블러프[cite: 30]에 있는 수습 연금술사[cite: 1]입니다. 아내에게 은엽수잎[cite: 26]이 또 부족하다는 전갈을 보냈더군요.\n\n그 애가 학업을 진지하게 생각하지 않는 것 같아 걱정이지만, 낙제하는 것은 보고 싶지 않습니다. 은엽수잎[cite: 26] 20개를 모아 그에게 가져다주시겠습니까? 당신이 약초를 가져가면, 그런 친절이 공짜가 아니라는 걸 그 애도 이해할 겁니다.",
