        ["D"] =
        "버려진 장원[cite: 5]에 사는 저 잘난 \"의류상\" 콘스턴스 브리스부아즈[cite: 6]가 무슨 \"자연주의 패션\"이라는 헛소리를 늘어놓으며 작업 중이라더군. 그게 뭔 소리인지 원.\n\n뱀뿌리[cite: 8] 20개가 필요하다고 하니 가져다줘. 그녀가 이끼를 짜서 숄을 만들기 전에 말이야.\n\n\"패셔너블하게 부패한\"이라는 말이 유행하지 않기를 바랄 뿐이야.",
