        ["D"] =
        "무릎에 묻은 풀물 자국을 보니 약초채집[cite: 14]가시군요. 도대체 사람들은 왜 연금술사[cite: 1]와 약초상을 헷갈려 하는지 모르겠습니다. 아니면 제가 왜 사람들의 사소한 약초 심부름이나 해줄 시간이 있다고 생각하는 걸까요. 다행히 당신에게는 이 요청을 처리할 기술과 시간이 있어 보이는군요.\n\n마법초 꽃잎[cite: 18] 20개를 그 마법부여[cite: 9]사에게 가져다주십시오. 이름이 아마 레오 사른[cite: 16]이었던 것 같은데, 언덕마루[cite: 14]로 가는 길 바로 남쪽에 야영지[cite: 2]를 세웠습니다.",
