        ["D"] =
        "오, 약초상이군요! 메보크 미지릭스[cite: 19]라는 이상한 고블린[cite: 11]이 제게 찔레가시[cite: 4]를 요청했습니다. 전 지금 가진 게 하나도 없고 그의 그 \"긴급한\" 어투를 또 상대하고 싶지 않습니다.\n\n부탁이니 찔레가시[cite: 4] 20개를 톱니항[cite: 22]에 있는 그에게 가져다주어 제 골칫거리를 해결해 주십시오.",
