        ["O"] =
        "제누 산크레아는 당신이 약초채집[cite: 14] 기술을 사용해 생채기풀[cite: 4] 20개를 모아 잿빛 골짜기[cite: 2]의 조람가르 전초기지에 있는 자신에게 가져오기를 원합니다.",
