        ["D"] =
        "돌발톱 산맥[cite: 28]의 거미[cite: 27]들은 깊게 물고, 그 독극물 취급점[cite: 21]은 오래 남는 찌꺼기를 남깁니다.\n\n야생 철쭉[cite: 34]으로 끓인 진정제만이 독을 빼낼 수 있지만, 보급품이 바닥나가고 있습니다. 당신이 도울 수 있습니다! 더 많은 이가 병들기 전에 야생 철쭉[cite: 34] 20개를 말라카진으로 가져다주십시오.",
