        ["D"] =
        "연금술사 라이던[cite: 1]이 죽음에 집착하는 동안, 저는 생명이 훨씬... 흥미롭더군요. 특히 이 형태 덕분에 가능해질지도 모르는 다른 종류의 생명 말이죠.\n\n섬세한 실험을 위해 생명의 뿌리[cite: 17] 20개가 필요합니다. 거미[cite: 27]로서의... 환생에 관한 실험이죠! 타렌 제분소[cite: 29]에 있는 저에게 가져다주십시오.",
