        ["D"] =
        "반갑네, $N. 자네 약초학자인 것 같군. 부탁 하나만 하겠네.\n\n높새바람 봉우리에 있는 내 친구 하가르가 왕꽃잎풀을 필요로 하네. 왜 필요한지는 묻지 않았지만, 꽤 급해 보이더군.\n\n왕꽃잎풀 20개를 채집해서 그에게 가져다주게. 그가 알아서 잘 쓸 걸세.",
