        ["D"] =
        "우리 정찰병들이 몸소 겪었듯이, 늪지대엔 온갖 위험이 도사리고 있지. 이곳의 재규어들처럼 늪의 안개 속으로 모습을 감출 수 있는 비약을 만들고 싶네.\n\n자네 약초를 좀 다룰 줄 아는 것 같군. 미명초잎 20개를 가져다주면, 내가 비약을 완성하겠네.",
