        "발라이 로크웨인은 당신이 약초채집 기술을 사용하여 카드가의 수염 20개를 채집한 다음, 먼지진흙 습지대 Tabetha's Farm의 타베사에게 전달해 주길 원합니다.",
        ["D"] =
        "어이, 늪지대 마녀 -- 타베사 -- 그녀가 자기가 만들 비약에 넣을 카드가의 수염을 원하고 있어. 빨리 가져다주지 않으면 나한테 무슨 짓을 할지 몰라. 날 두꺼비로 만들어버릴지도 모른다고!\n\n내가 개구리 신세가 되기 전에 카드가의 수염 20개를 Tabetha's Farm의 그녀에게 가져다줄 수 있겠어?",
