        ["O"] =
        "토르간은 당신이 약초채집 기술을 사용하여 황금가시 20개를 채집한 다음, 아라시 고원의 망치 주둔지에 있는 토르간에게 전달해 주길 원합니다.",
        ["D"] =
        "이 오래된 감옥에 머무는 이들의 사기를 높이기 위해 해야 할 일이 많소. 내 주술 의식에는 수많은 것들이 필요하지 -- 때로는 피와 이빨이, 때로는 향으로 태울 적절한 약초가 말이오.\n\n다음 의식을 위해 황금가시 20개가 필요하오. 그것만 있으면 이 지역에 머무는 불안한 대지와 불의 정령들의 관심을 끌 수 있지.",
    },
    [28556] = {
        ["T"] = "루우의 의뢰",
        ["O"] =
        "루우는 당신이 약초채집 기술을 사용하여 아서스의 눈물 20개를 채집한 다음, 페랄라스의 모자케 야영지에 있는 루우에게 전달해 주길 원합니다.",
        ["D"] =
        "아서스의 눈물... 그토록 아름다운 꽃에 참으로 슬픈 이름이지. 예전엔 스트라솔름 백합이라고 불렸다는군. 한때 로데론이었던 땅에서는 더 이상 흔하게 자라지 않는다고 들었네.\n\n이 약초를 연구해 보고 싶네. 아서스의 눈물 20개를 내게 가져다주면 그에 대한 보상을 하겠네.",
