    [28557] = {
        ["T"] = "수습생 윈터의 의뢰",
        ["O"] =
        "수습생 윈터는 당신이 약초채집 기술을 사용하여 꿈풀 20개를 채집한 다음, 아즈샤라의 발로르모크에 있는 수습생 윈터에게 전달해 주길 원합니다.",
        ["D"] =
        "꿈풀... 누군가에겐 그저 무해한 약초일 뿐이겠지만, 난 여기서 잠재력을 봤어 -- 훨씬 더 거대한 무언가가 될 잠재력 말이야.\n\n이 약초가 정신에 미치는 영향은... 꽤 유망해. 꿈풀 20개를 내게 가져다줘, 그럼 우리가 새로운 역벼... 내 말은, 물약의 배합을 시작할 수 있을 거야.",
    },
    [28558] = {
        ["T"] = "랠릭 핀의 의뢰",
        ["O"] =
        "아델레 필더는 당신이 가죽세공 기술을 사용하여 얇은 가죽 화살통 1개를 제작한 다음, 엘윈 숲의 동쪽계곡 벌목지에 있는 랠릭 핀에게 전달해 주길 원합니다.",
        ["D"] =
        "수습 가죽세공인이시군요? 밀린 주문을 조금 도와주시겠어요?\n\n동쪽계곡 벌목지에 있는 랠릭 핀이 새 화살통을 주문했어요. 예전 화살통은 다 해져서 화살이 이음새 밖으로 튀어나올 정도라네요. 아주 위험한 상황이죠.\n\n초보자가 맡기에 딱 좋은 일이에요. 얇은 가죽 화살통을 하나 만들어서 벌목지에 있는 그에게 전달해 주세요. 연습도 하고 남도 돕는 일이라고 생각해 보세요.",
    },
    [28559] = {
        ["T"] = "토미 조 스톤필드의 의뢰",
        ["O"] =
