        ["D"] =
        "괜찮으시다면 하나 더 부탁드릴게요: 토미 조가 요즘 어떤 신비로운 아가씨에게 푹 빠져서는, 자기를 \"말끔하게\" 보이게 해줄 무언가를 찾고 있거든요.\n\n가죽세공 솜씨를 기르고 싶으시다면 손바느질한 가죽 바지 몇 벌을 만들어보는 것도 좋은 핑계가 될 거예요. 스톤필드 농장에 있는 그에게 바지를 가져다주세요. 멀끔한 모습을 갖추면 그가 용기를 내는 데 도움이 될지도 모르잖아요.",
    },
    [28560] = {
