        "그레타 파인스핀들은 당신이 가죽세공 기술을 사용하여 새김무늬 가죽 조끼 2개를 제작한 다음, 던 모로의 남부 관문 전초기지에 있는 오르고른 스트롱브로우에게 전달해 주길 원합니다.",
        ["D"] =
        "동료 수습생인가? 밀린 주문을 몇 개만 좀 도와주지 않겠나?\n\n오르고른이 웃통을 벗고 남부 관문 전초기지를 순찰하고 있다네. \"바람과 레슬링을 하다가 잃어버렸다\"고 하던데. 참 나.\n\n자네가 가죽세공을 연마 중이라면, 그에게 새김무늬 가죽 조끼 두어 벌을 만들어주게. 녀석이 인정하진 않겠지만, 산 공기가 그리 따뜻하진 않거든.",
    },
    [28561] = {
