        "그레타 파인스핀들은 당신이 가죽세공 기술을 사용하여 작은 가죽 탄약주머니 2개를 제작한 다음, 던 모로의 카라노스에 있는 그리프 와일드하트에게 전달해 주길 원합니다.",
        ["D"] =
        "이건 자네가 처리해 줬으면 좋겠군. 그리프 와일드하트가 사격 훈련을 하다가 인내심도, 탄약주머니 공간도 바닥이 났다고 하더군. 탄약주머니가 너무 낡아서 눈밭에 총알을 줄줄 흘리고 다닌다나 뭐라나.\n\n자네가 가죽세공 기술을 올리고 싶다면, 작은 가죽 탄약주머니 두 개를 만들어서 카라노스에 있는 그에게 가져다주게. 그가 아주 요긴하게 쓸 거야. 그리고 아마 수습 사냥꾼들에게 으르렁거리는 것도 좀 멈추겠지.",
    },
    [28562] = {
        ["T"] = "지나 피더보우의 의뢰",
        ["O"] =
        "나디야 메인위버는 당신이 가죽세공 기술을 사용하여 튼튼한 가죽 바지 2개를 제작한 다음, 텔드랏실 돌라나르의 지나 피더보우에게 전달해 주길 원합니다.",
        ["D"] =
        "아, 수습 가죽세공인이시군요. 제 작업실에 오신 걸 환영합니다. 기술을 연습하러 오신 거라면, 제가 도와드릴 수 있어요.\n\n초보자에게 딱 맞는 아주 간단한 일이 몇 가지 있거든요. 돌라나르의 지나 피더보우가 텔드랏실 깊은 숲속에서 훈련을 하고 있는데. 너무 무리한 나머지 바지에 구멍이 여러 개 났고, 새 바지가 필요하답니다. 튼튼한 가죽 바지 두 벌을 만들어서 그녀에게 배달해 주시면 큰 도움이 될 거예요.",
    },
    [28563] = {
        ["T"] = "수석고고학자 그레이위스커의 의뢰",
        ["O"] =
        "나디야 메인위버는 당신이 가죽세공 기술을 사용하여 손바느질한 가죽 허리띠 1개를 제작한 다음, 텔드랏실 다르나서스 달의 신전에 있는 수석고고학자 그레이위스커에게 전달해 주길 원합니다.",
        ["D"] =
        "제가 다르나서스에 가는 일은 드뭅니다만, 만약 당신이 그 도시로 가실 의향이 있다면, 딱 맡기기 좋은 주문이 하나 더 있어요.\n\n이곳을 방문 중인 한 드워프가 메네실 항구에서 오던 중 허리띠가 망가졌다는 쪽지를 보냈거든요. 손바느질한 가죽 허리띠를 만들어서 수석고고학자 그레이위스커에게 전달해 주세요. 달의 신전에 가시면 그를 찾을 수 있을 겁니다.",
    },
    [28564] = {
        ["T"] = "정찰병 갈리안의 의뢰",
        ["O"] =
        "민병대원 가리엘은 당신이 가죽세공 기술을 사용하여 암색 가죽 장화 2개를 제작한 다음, 서부 몰락지대 감시의 언덕에 있는 정찰병 갈리안에게 전달해 주길 원합니다.",
        ["D"] =
        "나는 민병대의 보급 장교요. 가죽세공인이 한 명 필요한데. 당신 맞소?\n\n정찰병 갈리안이 밤낮으로 감시의 언덕 주변을 정찰하느라 장화 이음새가 다 뜯어져 버렸소. 교체품을 요청받았소만 -- 튼튼하고, 발소리가 나지 않으며, 장시간 이동에도 끄떡없는 놈으로 말이오.\n\n가죽세공 기술을 좀 다룬다면, 암색 가죽 장화 두 켤레를 만들어서 그에게 배달해 주시오.",
    },
    [28565] = {
        ["T"] = "민병대원 에반젤린의 의뢰",
        ["O"] =
        "민병대원 가리엘은 당신이 가죽세공 기술을 사용하여 고급 가죽 망토 1개를 제작한 다음, 서부 몰락지대 남쪽 길 정찰 경로에 있는 민병대원 에반젤린에게 전달해 주길 원합니다.",
        ["D"] =
        "민병대원 에반젤린은 밤낮으로 남쪽 길을 순찰하고 있는데, 단검 언덕에서 불어오는 바람은 데피아즈단의 칼날처럼 매섭소. 그녀를 위해 제대로 된 망토를 하나 요청받았소. 튼튼하고, 비바람을 막아주며, 위엄 있는 것으로 말이오.\n\n가죽세공을 연마하고 있다면 고급 가죽 망토를 만들어서 그녀에게 전해주시오. 그녀가 대놓고 편한 걸 찾진 않겠지만, 그래도 그럴 자격이 충분한 사람이니까 말이오.",
    },
    [28566] = {
        ["T"] = "케를로니안 에버셰이드의 의뢰",
        ["O"] =
        "마브라린은 당신이 가죽세공 기술을 사용하여 일반 방어구 키트 5개를 제작한 다음, 어둠해안 고대정령의 숲에 있는 케를로니안 에버셰이드에게 전달해 주길 원합니다.",
        ["D"] =
        "가죽세공인이라고요? 오, 엘룬이시여 감사합니다! 숲이 이렇게 위험한데 밀려드는 주문을 다 처리하지 못해서 쩔쩔매고 있었거든요.\n\n케를로니안 에버셰이드님은 깨어남과 잠듦의 경계를 떠돌고 계시지만, 무아지경 속에서도 숲을 지키셔야 한답니다. 그분의 가죽 갑옷은 너무 오래 써서 낡아버렸어요. 꿈속에서는 눈치채지 못하실지 몰라도, 깨어나시면 신경 쓰이실 거예요.\n\n일반 방어구 키트 5개를 만들어서 그분께 전해주시겠어요? 도착하셨을 때 아직 깨어나지 않으셨을 수도 있지만, 조용히 돕는 것도 도움이 되니까요.",
    },
    [28567] = {
        ["T"] = "그웨니스 블라이레곤드의 의뢰",
        ["O"] =
        "마브라린은 당신이 가죽세공 기술을 사용하여 고급 가죽 튜닉 1개를 제작한 다음, 어둠해안 아우버다인에 있는 그웨니스 블라이레곤드에게 전달해 주길 원합니다.",
        ["D"] =
        "이게 가장 급한 주문은 아닐지 몰라도, 가장 따뜻한 일 중 하나일 거예요.\n\n그웨니스 님은 아우버다인에서 보급품 기록과 드루이드 배송품을 조율하는 일을 돕고 계시는데, 지난 계절부터 계속 똑같은 낡은 튜닉만 입고 계신답니다. 이제 좀 더 튼튼하고 편안한 옷이 필요할 때가 된 것 같아요.\n\n고급 가죽 튜닉을 만들어서 그녀에게 배달해 주시겠어요? 마을 비행장에 가시면 그녀를 찾으실 수 있을 거예요.",
    },
    [28568] = {
        ["T"] = "산악경비대 오즈모크의 의뢰",
        ["O"] =
        "카트 샘프슨은 당신이 가죽세공 기술을 사용하여 얇은 가죽 바지 2개를 제작한 다음, 모단 호수 텔사마의 산악경비대 오즈모크에게 전달해 주길 원합니다.",
        ["D"] =
        "오, 숙련된 가죽세공인이시군요. 마을에 계시는 동안 좋은 일 좀 해보시겠어요? 산악경비대 오즈모크가 강풍에도 버티지 못할 바지를 입고 바위와 눈밭 위를 기어 다니고 있거든요. 순찰이 끝날 때마다 그를 꿰매주는 것도 이젠 지긋지긋하네요.\n\n가죽세공 기술을 기르고 싶으시다면, 얇은 가죽 바지 두어 벌을 만들어서 텔사마에 있는 그에게 전달해 주세요. 툴툴거리긴 하겠지만, 거절하진 않을 거예요.",
    },
    [28569] = {
        ["T"] = "수석 기술자 힌더위어 7세의 의뢰",
        ["O"] =
        "카트 샘프슨은 당신이 가죽세공 기술을 사용하여 고급 가죽 허리띠 1개를 제작한 다음, 모단 호수 돌다지 댐의 수석 기술자 힌더위어 7세에게 전달해 주길 원합니다.",
        ["D"] =
        "수석 기술자 힌더위어가 계속 공구를 잃어버리고 있어요. 과장하는 게 아니에요. 진짜로요. 지난주에 허리띠가 끊어지면서 렌치들이 댐 위로 떨어졌는데 그 소리가 계곡 절반에 다 울렸다니까요. 전 댐이 무너지는 줄 알았어요!\n\n그가 고급 가죽 허리띠를 만들어 돌다지 댐의 자신에게 가져다 달라고 하더군요. 당신이 가죽세공 기술을 뽐내고 싶다면, 이건 충분히 시간 투자할 가치가 있는 일일 거예요. 우리 모두의 안전을 위해서라도요.",
    },
    [28570] = {
        ["T"] = "캘라 섀도스피어의 의뢰",
        ["O"] =
        "사냥꾼 키아나는 당신이 가죽세공 기술을 사용하여 고급 방어구 키트 5개를 제작한 다음, 돌발톱 산맥 그물누비 고개에 있는 캘라 섀도스피어 야영지로 전달해 주길 원합니다.",
        ["D"] =
        "당신의 도움이 필요해요, 가죽세공인. 제 가장 친한 친구인 캘라 섀도스피어가 그물누비 고개에 주둔하고 있는데, 그곳은 매일 매복과 독, 그리고 더 끔찍한 일들이 벌어지는 곳이죠. 장비를 셀 수 없이 기워 입었지만, 이젠 더 버티기 힘들 거예요.\n\n고급 방어구 키트를 몇 개 만들어서 그녀에게 전해 주시겠어요? 시간을 뺏고 싶진 않지만, 그녀에겐 정말 간절한 물건이랍니다.",
    },
    [28571] = {
        ["T"] = "라스의 의뢰",
        ["O"] =
        "라스는 당신이 가죽세공 기술을 사용하여 두꺼운 가죽 화살통 1개를 제작한 다음, 그늘숲 고요한 강둑에 있는 자신의 야영지로 전달해 주길 원합니다.",
        ["D"] =
        "고요한 강둑을 따라 늑대 무리를 추적하고 있었는데, 까마귀 언덕 어딘가에서 화살통을 잃어버렸소. 지금쯤이면 갈기갈기 찢겨 있겠죠. 새 화살통이 필요하오.\n\n가죽세공을 배웠소? 그럼 제대로 된 두꺼운 가죽 화살통을 하나 만들어 주시오. 긴 사냥을 마치고 돌아올 때까지 화살을 넉넉히 담을 수 있는 튼튼한 놈이어야 하오.",
    },
    [28572] = {
        ["T"] = "파수꾼 마이스린의 의뢰",
        ["O"] =
        "하론 다크위브는 당신이 가죽세공 기술을 사용하여 암색 가죽 허리띠 2개를 제작한 다음, 잿빛 골짜기 숲의 노래에 있는 파수꾼 마이스린에게 전달해 주길 원합니다.",
        ["D"] =
        "최근 아주 영광스러운 무용담을 들었네, $C. 악령불 언덕에서 남쪽으로부터 쏟아지는 악마들에 맞서 파수꾼 마이스린이 자리를 지켜냈다는군. 물론 대가가 없진 않았지. 그녀의 갑옷은 불에 그을렸고, 허리띠는 완전히 찢어졌다고 하더군. 그녀는 무기와... 음... 위신을 잃었지. 무슨 말인지 알겠나.\n\n다음 전투를 치르기 전에 다시 장비를 갖춰야 하네. 자네의 가죽세공 기술이 충분하다면 암색 가죽 허리띠 두 개를 만들어서 숲의 노래에 있는 마이스린에게 전해주게. 지체할 시간이 없어. 악마들이 계속 몰려오고 있다더군.",
    },
    [28573] = {
        ["T"] = "베르너 오스구드의 의뢰",
        ["O"] =
        "클라이드 랜덜은 당신이 가죽세공 기술을 사용하여 경화 가죽 장갑 1개를 제작한 다음, 붉은마루 산맥 레이크샤이어의 베르너 오스구드에게 전달해 주길 원합니다.",
        ["D"] =
        "베르너 오스구드는 수년 동안 레이크샤이어 마구간에서 일하며, 스톰윈드의 왕실이 우릴 신경 쓰지 않을 때도 마을 사람들을 보살펴 왔소. 우리 가족이 여기까지 온 것도 다 그 때문이지 -- 오크들이 공격할 때를 대비해서... 아, 지역 정치 이야기로 자네를 지루하게 만들 필요는 없겠지. 자네 도움이 필요하네.\n\n베르너를 위해 아주 특별한 경화 가죽 장갑을 만들어 주었으면 하네. 녀석이 고삐를 잡아당기는 걸 몹시 좋아하는 새 암망아지를 들였는데, 쓰던 장갑 때문에 물집이 잡힌다더군. 베르너가 계속 일할 수 있게 돕는 건 붉은마루 사람 모두를 위한 봉사라고 생각해 주게.",
    },
    [28574] = {
        ["T"] = "아이나르 스톤그립의 의뢰",
        ["O"] =
        "제임스 할로란은 당신이 가죽세공 기술을 사용하여 활장이 장갑 1개를 제작한 다음, 저습지 녹색지대 남쪽의 교차로에 있는 아이나르 스톤그립에게 전달해 주길 원합니다.",
        ["D"] =
        "자네가 생가죽을 다루는 솜씨를 봤네. 가죽세공인인가? 자네한테 맡길 일이 하나 있네.\n\n아이나르 스톤그립은 내 최고의 사냥꾼이지 -- 하지만 그의 장갑이 너덜너덜해져서, 천을 덧댄 손가락과 쓸데없는 자존심으로 화살을 매기려 낑낑대는 꼴은 이젠 더 못 보겠군. 녀석이 새 활장이 장갑을 달라고 부탁할 위인도 못 되니, 내가 대신 부탁하겠네.",
    },
    [28575] = {
        ["T"] = "감시자 마나르의 의뢰",
        ["O"] =
        "여관주인 핀미르는 당신이 가죽세공 기술을 사용하여 녹색 가죽 팔보호구 6개를 제작한 다음, 슬픔의 늪 피난처에 있는 감시자 마나르에게 전달해 주길 원합니다.",
        ["D"] =
        "우리의 감시자들은 재규어, 악어, 정령, 미쳐 날뛰는 물고기들로부터 우릴 지키고 있습니다. 이런 짐승들과 싸울 때 손목을 보호해 줄 팔보호구가 필요해요. 당신은 가죽과 바늘을 잘 다루는 것 같군요. 그들을 도와줄 수 있나요?",
    },
    [28576] = {
        ["T"] = "비블리 풋츠버클의 의뢰",
        ["O"] =
        "자넷 호머스는 당신이 가죽세공 기술을 사용하여 야만전사의 어깨보호구 2개를 제작한 다음, 잊혀진 땅 코르메크의 오두막에 있는 비블리 풋츠버클에게 전달해 주길 원합니다.",
        ["D"] =
        "나이젤의 야영지 같은 작은 전초기지에서는 우리 모두가 두 가지 이상의 일을 맡고 있죠. 예를 들어, 전 메시지를 받고 배달하는 일을 한답니다. 당신이 흥미를 느낄 만한 메시지가 하나 있어요.\n\n코르메크의 오두막이라 불리는 판잣집에 사는 고블린이 가죽세공인을 찾고 있더라고요. \"비즈니스 상의 이유\"로 새 어깨보호구가 필요하다나 뭐라나. 그게 무슨 뜻인진 모르겠지만요.\n\n돈을 좀 벌 수 있는 좋은 기회 아닐까요? 고블린들은 주머니가 두둑하잖아요... 듣기로는 그렇다던데요.",
    },
    [28577] = {
        ["T"] = "조라크 라벤홀트 경의 의뢰",
        ["O"] =
        "조라크 라벤홀트 경은 당신이 가죽세공 기술을 사용하여 서리 가죽 망토 1개를 제작한 다음, 알터랙 산맥 라벤홀트 장원의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "나는 사람을 꿰뚫어 보는 안목이 좀 있지, $C. 내 짐작에 자네는... 솜씨가 꽤 훌륭한 가죽세공인인 것 같군.\n\n펠리시티의 생일이 다가오고 있어. 그녀는 전혀 기대하지 않겠지만 선물을 좀 주고 싶네. 실용적이면서도 우아하고, 그러면서도 약간 예상치 못한 선물이면 좋겠어.\n\n서리 가죽 망토라면 딱 맞을 것 같군. 자, 한 번 만들어 보겠나?",
    },
    [28578] = {
        ["T"] = "수석 기술자 우룰의 의뢰",
        ["O"] =
        "수석 기술자 우룰은 당신이 가죽세공 기술을 사용하여 거무스름한 허리띠 2개를 제작한 다음, 동부 내륙지 맹금의 봉우리의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "내 주머니에도 공구가 가득하고 소매에도 공구가 가득하지. 어제는 하마터면 스패너가 하수구로 굴러떨어질 뻔했다니까. 조카 니오마가 제대로 된 허리띠가 필요하다고 하더군 -- 정확히는 거무스름한 허리띠 두 개 말이야.\n\n자네가 가죽세공 기술을 익혔다면 두어 개 만들어서 이리 가져오게. 내 공구를 잘 지탱해 주고 압력을 견디며 터지지만 않는다면 어떻게 생겨 먹었든 상관없어. 터트리는 건 내 몫이니까.",
    },
    [28579] = {
        ["T"] = "보안과장 빌지위즐의 의뢰",
        ["O"] =
        "보안과장 빌지위즐은 당신이 가죽세공 기술을 사용하여 거북 껍질 다리보호구 2개를 제작한 다음, Tanaris 스팀휘들 항구의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "가죽세공인이슈? 굳은살을 보아하니 딱이구만.\n\n이봐, 잠깐 내 불평 좀 들어봐. 평범한 바지로는 여기서 못 버텨. 해적 놈들 주먹은 맵고, 햇살은 더 맵거든. 거북이 껍질로 만든 바지를 원해. 거북이 등딱지야말로 오우거 이마만큼이나 튼튼하니까 말이야.\n\n가죽세공 기술이 충분하다면 거북 껍질 다리보호구를 좀 만들어 줘. 튼튼하고, 활동하기 편하고, 해적의 공격도 막아줄 그런 놈으로 부탁해. 내 우선순위가 그렇단 말이지.",
    },
    [28580] = {
        ["T"] = "그레간 브루스퓨의 의뢰",
        ["O"] =
        "프랫 맥그루벤은 당신이 가죽세공 기술을 사용하여 속사 화살통 1개를 제작한 다음, 페랄라스 쌍둥이 바위산 근처 야영지의 그레간 브루스퓨에게 배달해 주길 원합니다.",
        ["D"] =
        "그 드워프 그레간은 이곳을 거쳐 간 대부분의 드루이드들보다 더 오래 페랄라스 야생에 머물렀지. 내게 속사 화살통을 새로 만들어 달라는 부탁을 해 왔어. 숲의 습기에도 망가지지 않는 게 필요하다고 하더군.\n\n날 페랄라스 밖으로 끌어낼 순 없을걸, $g형제님:자매님;! 하지만 당신에겐 그걸 만들 실력이 있지, 안 그런가?",
    },
    [28581] = {
        ["T"] = "크로미의 의뢰",
        ["O"] =
        "레오나드 포터는 당신이 가죽세공 기술을 사용하여 거친 경화 가죽 1개를 제작한 다음, 서부 역병지대 안돌할의 크로미에게 배달해 주길 원합니다.",
        ["D"] =
        "이봐 -- 진짜 가죽세공인이군! 가죽과 깊은바위 소금의 냄새는 어디서든 알아볼 수 있지.\n\n말이 나온 김에... 내가 아주 난처한 상황에 처했어. 크로미라는 꼬마 노움에게 거친 경화 가죽을 만들어 주기로 약속했는데, 내 소금통이 없어졌지 뭔가. 게다가 반경 수 마일 내에 가죽세공인이라곤 눈을 씻고 찾아봐도 없어.\n\n자네가 좀 해줄 수 있겠나? 아, 또 다른 문제는 그녀가 저쪽... 안돌할 폐허에 있다는 거야. 난 싸움꾼 체질이 아니거든. 하지만 자넨 그런 것 같군그래.",
    },
    [28582] = {
        ["T"] = "리키 카트스파크의 의뢰",
        ["O"] =
        "윌리덴 마샬은 당신이 가죽세공 기술을 사용하여 밤하늘 장화 2개를 제작한 다음, 운고로 분화구 공포의 터에 있는 리키 카트스파크에게 배달해 주길 원합니다.",
        ["D"] =
        "오! 당신 가죽세공인은 아니시죠... 그쵸?\n\n무슨 행운인지! 실은 운고로에서 오래된 엘프 폐허를 연구 중인 리키 카트스파크라는 노움에게서 방금 연락을 받았어요. 파트너인 제일사가 다치는 바람에 장화가 엉망이 됐다더군요. 타르나 독 때문이었나 봐요. 아무튼, 밤하늘 장화가 몇 켤레 필요하대요. 혹시 이거 도와주실 수 있나요?",
    },
    [28583] = {
        ["T"] = "소타르의 의뢰",
        ["O"] =
        "카마리는 당신이 가죽세공 기술을 사용하여 얇은 가죽 화살통 1개를 제작한 다음, 듀로타 Razor Hill의 소타르에게 배달해 주길 원합니다.",
        ["D"] =
        "수습 가죽세공인인가? 밀린 주문을 몇 개만 도와주겠어?\n\nRazor Hill의 소타르가 새 화살통을 주문했어. 이전 화살통은 다 해져서 화살이 이음새 밖으로 튀어나올 정도라더군. 아주 위험한 상황이지.\n\n초보자가 맡기에 딱 좋은 일이야. 얇은 가죽 화살통을 하나 만들어서 마구간에 있는 그에게 배달해 줘. 연습도 하고 호드를 돕는 일이라고 생각해 보라고.",
    },
    [28584] = {
        ["T"] = "로카르 블레이드섀도의 의뢰",
        ["O"] =
        "카마리는 당신이 가죽세공 기술을 사용하여 손바느질한 가죽 바지 2개를 제작한 다음, 듀로타 모래바람 협곡 위쪽, Razor Hill 북동쪽 농장의 로카르 블레이드섀도에게 배달해 주길 원합니다.",
        ["D"] =
        "괜찮다면 하나 더 부탁할게: 로카르가 Razor Hill 북동쪽에서 \"농사\"를 짓고 있다더군. 내가 듣기론 수확이라기보단 헛손질에 가까운 것 같지만 말이야. 아무튼, 모래바람 협곡을 기어오르다 바지가 찢어졌다고 하더라고.\n\n가죽세공을 연마 중이라면 손바느질한 가죽 바지 두어 벌을 만들어서 그에게 가져다줘. 그의 농장은 협곡 위쪽, Razor Hill 외곽에 있어.",
    },
    [28585] = {
        ["T"] = "잔겐 스톤후프의 의뢰",
        ["O"] =
        "초우 스트롱하이드는 당신이 가죽세공 기술을 사용하여 새김무늬 가죽 조끼 2개를 제작한 다음, 멀고어 썬더 블러프 상층에 있는 잔겐 스톤후프에게 배달해 주길 원합니다.",
        ["D"] =
        "다른 수습 가죽세공인인가? 밀린 주문을 몇 개만 좀 도와주지 않겠나?\n\n잔겐 스톤후프가 의식용 불꽃에 지난번 조끼를 그슬리는 바람에 새 새김무늬 가죽 조끼가 필요하다네. 자네가 맡아 준다면 아주 간단한 일일 거야.",
