    [28586] = {
        ["T"] = "멜로르 스톤후프의 의뢰",
        ["O"] =
        "초우 스트롱하이드는 당신이 가죽세공 기술을 사용하여 작은 가죽 탄약주머니 2개를 제작한 다음, 멀고어 썬더 블러프 수렵의 봉우리의 멜로르 스톤후프에게 배달해 주길 원합니다.",
        ["D"] =
        "잔겐의 동생 멜로르는 훌륭한 사냥꾼이지. 녀석도 주문을 넣었는데, 이 일은 자네가 맡아 줬으면 좋겠군.\n\n작은 가죽 탄약주머니 두 개를 만들어서 썬더 블러프 수렵의 봉우리에 있는 멜로르에게 가져다주게. 기술자에게 새 총을 막 주문했는데, 새 탄약을 시험해 보고 싶다는군.",
    },
    [28587] = {
        ["T"] = "쉘든 그림스비의 의뢰",
        ["O"] =
        "죽음의경비병 리니아는 당신이 가죽세공 기술을 사용하여 튼튼한 가죽 바지 2개를 제작한 다음, 티리스팔 숲 보루의 쉘든 그림스비에게 배달해 주길 원합니다.",
        ["D"] =
        "저기 쉘린을 보시오. 요즘 새로 깨어난 포세이큰들 주문 처리하느라 정신이 없다오. 하지만 내가 당신이 그녀와 이야기하는 걸 봤고, 당신이라면 이 주문들을 맡을 수 있을 거란 걸 알지. 그래서 당신에게 임무를 하나 맡기겠소.\n\n쉘든 그림스비가 위대한 순찰자 나타노스 매리스를 찾겠다며 보루로 떠났소. 하지만 난 그가 실패할 거라 확신하오. 왜냐고? 그 여행을 견뎌내지 못할 너덜너덜한 바지를 입고 있거든. 그러니 튼튼한 가죽 바지 두어 벌을 만들어 주시오. 은빛 여명회 앞에서 그가 망신당하는 걸 막을 수 있을지 어디 한번 두고 봅시다.",
    },
    [28588] = {
        ["T"] = "올리버 드워의 의뢰",
        ["O"] =
        "죽음의경비병 리니아는 당신이 가죽세공 기술을 사용하여 손바느질한 가죽 허리띠 1개를 제작한 다음, 티리스팔 숲 브릴의 올리버 드워에게 배달해 주길 원합니다.",
        ["D"] =
        "올리버 드워를 만나본 적 있소? 브릴의 무기 제작자인데, 내가 장담하건대 아주 훌륭한 솜씨를 지녔소. 무기에는 뛰어나지만, 옷에는 형편없지. 한마디로 허리띠가 필요하다는 거요.\n\n우리가 언데드이긴 하지만, 불은 여전히 뜨겁소. 난 바지가 흘러내려서 대장간 불에 바지가 타는 꼴을 보고 싶지 않소. 그러니 손바느질한 가죽 허리띠를 만들어 주시오. 사고는 미연에 방지해야 하니까.",
    },
    [28589] = {
        ["T"] = "세이지 그린혼의 의뢰",
        ["O"] =
        "세이지 그린혼은 당신이 가죽세공 기술을 사용하여 암색 가죽 장화 2개를 제작한 다음, 은빛소나무 숲 공동묘지의 세이지 그린혼에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑소, $R. 내 친구 무라와 나는 이 지역 출신이 아니오. 뭐 척 보면 알겠지만.\n\n우린 은빛소나무 숲이 이렇게... 추울 줄은 몰랐소. 특히 밤에는 말이오. 자네에게 기술이 있다면 암색 가죽 장화 두어 켤레를 만들어 주었으면 좋겠군. 이곳에서 수습생을 기다리는 동안 내 발굽이 어는 걸 막아줄 테니.",
    },
    [28590] = {
        ["T"] = "무라 룬토템의 의뢰",
