        ["D"] =
        "내가 여기서 발굽이 얼어붙는 동안, 무라는 바다에서 불어와 언덕진 계곡을 밴시의 비명처럼 휘감는 차가운 바람 때문에 몸서리치고 있다오.\n\n그녀를 위해 바람과 비를 모두 막아줄 고급 가죽 망토를 하나 만들어 주겠소?",
    },
    [28591] = {
        ["T"] = "팔라 세이지윈드의 의뢰",
