        "날팍은 당신이 가죽세공 기술을 사용하여 일반 방어구 키트 5개를 제작한 다음, 불모의 땅 통곡의 동굴 꼭대기에 있는 팔라 세이지윈드 자택으로 배달해 주길 원합니다.",
        ["D"] =
        "가죽세공인? 그래, 환영에서 본 바로 그 사람이군. 꿈속에서 당신이 기술을 발휘해 팔라를 돕는 걸 보았소. 팔라는 바로 이 산꼭대기에 살고 있지. 그녀는 일반 방어구 키트가 몇 개 필요하다오.\n\n그녀를 도와줄 수 있겠소?",
    },
    [28592] = {
        ["T"] = "가즈록의 의뢰",
        ["O"] =
        "날팍은 당신이 가죽세공 기술을 사용하여 고급 가죽 튜닉 1개를 제작한 다음, 불모의 땅 십자로의 가즈록에게 배달해 주길 원합니다.",
        ["D"] =
        "환영 속에서 당신이 고급 가죽 튜닉을 들고 있는 것도 보았소. 십자로에 있는 가즈록에게 필요한 물건인 것 같군. 랩터 여러 마리와 싸우다가 셔츠가 찢어졌는데, 동료들에게 그 사실을 숨기고 싶어 하더군. 당신이 새 옷을 가져다주면 아주 안도할 거요.",
    },
    [28593] = {
        ["T"] = "마렌 스카이시어의 의뢰",
        ["O"] =
        "루가 레이지토템은 당신이 가죽세공 기술을 사용하여 얇은 가죽 바지 2개를 제작한 다음, 불모의 땅 티더스의 계단의 마렌 스카이시어에게 배달해 주길 원합니다.",
        ["D"] =
        "오, 숙련된 가죽세공인이시군요. 당신 도움이 좀 필요해요. 크룰무가 일이 산더미처럼 밀렸는데도 인정하려 들질 않아요. 전문 기술 훈련을 막 끝낸 터라 긴장하고 있으면서도 겉으론 태연한 척하고 있죠.\n\n그를 좀 도와주실 수 있나요? 제가 주문서를 몇 개 빼돌려 왔거든요. 마렌 스카이시어가 얇은 가죽 바지를 몇 벌 주문했어요. 바지를 만들어서 톱니항 너머 해안가에 있는 그녀의 집으로 배달해 주세요.",
    },
    [28594] = {
        ["T"] = "크룰무 풀문의 의뢰",
        ["O"] =
        "루가 레이지토템은 당신이 가죽세공 기술을 사용하여 고급 가죽 허리띠 1개를 제작한 다음, 불모의 땅 타우라조 야영지의 크룰무 풀문에게 배달해 주길 원합니다.",
        ["D"] =
        "부탁 하나 더 들어주실래요? 흠... 이 쪽지엔 이름이 없네요. 그저 \"고급 가죽 허리띠 하나\"라고 휘갈겨 쓰여 있을 뿐이에요. 뭐 어때요. 그냥 허리띠를 만들어서 크룰무에게 가져다주세요. 배달은 그가 알아서 할 거예요.",
    },
    [28595] = {
        ["T"] = "카드라크의 의뢰",
        ["O"] =
        "시리스는 당신이 가죽세공 기술을 사용하여 고급 방어구 키트 5개를 제작한 다음, 잿빛 골짜기 몰샨 주둔지의 카드라크에게 배달해 주길 원합니다.",
        ["D"] =
        "가죽세공인, 당신 도움이 필요하오. 대족장님의 명으로 이곳의 군기반을 다잡으려 하는데, 보급품이 너무 부족하오. 토막나무 주둔지의 수요를 맞추다 보면 우리 정찰병과 선발대에 쓸 보급품이 모자랄 수밖에 없지.\n\n고급 방어구 키트를 몇 개 만들어서 불모의 땅 입구인 몰샨 주둔지에 배치된 우리 병력에게 전달해 주시오. 은빛날개 진영의 전진에 몰샨 주둔지가 무너지게 내버려 둘 순 없소. 그렇게 되면 남쪽의 병력과 완전히 단절될 테니까.",
    },
    [28596] = {
        ["T"] = "탈로우의 의뢰",
        ["O"] =
        "조지 칸다테는 당신이 가죽세공 기술을 사용하여 두꺼운 가죽 화살통 1개를 제작한 다음, 언덕마루 구릉지 타렌 제분소의 탈로우에게 배달해 주길 원합니다.",
        ["D"] =
        "탈로우라는 사냥꾼이 타렌 제분소 외곽을 따라 퓨마를 추적하다가, 교수대 교차로 근처 어딘가에서 화살통을 잃어버렸소. 지금쯤이면 오우거 녀석들이 갈기갈기 찢어놨을 테니 새 화살통이 필요할 거요.\n\n가죽세공을 할 줄 아시오? 그럼 녀석에게 제대로 된 두꺼운 가죽 화살통을 하나 만들어 주시오. 긴 사냥을 마치고 돌아올 때까지 화살을 넉넉히 담을 수 있는 튼튼한 놈으로 말이오. 녀석의 펫은 걱정하지 마시오. 마을에 있을 땐 그 흉포한 놈을 마구간에 가둬두니까.",
    },
    [28597] = {
        ["T"] = "스타른의 의뢰",
        ["O"] =
        "스타른은 당신이 가죽세공 기술을 사용하여 암색 가죽 허리띠 2개를 제작한 다음, 버섯구름 봉우리 높새바람 봉우리의 스타른에게 배달해 주길 원합니다.",
        ["D"] =
        "반갑네, $N. 혹시 바늘과 가죽을 좀 다룰 줄 아나? 조만간 부모님께서 높새바람 봉우리를 방문하실 텐데, 집에 돌아가실 때 선물로 드릴 암색 가죽 허리띠를 두어 개 구하고 싶네만 이곳엔 가죽세공인이 없어서 말이야.\n\n자네가 이 일을 맡아준다면 기꺼이 보상을 지불하고 내 마지막 사냥에서 얻은 가죽들도 몇 장 얹어주지.",
    },
    [28598] = {
        ["T"] = "다른 탈론그립의 의뢰",
        ["O"] =
        "마그그랜 어스바인더는 당신이 가죽세공 기술을 사용하여 경화 가죽 장갑 1개를 제작한 다음, 돌발톱 산맥 말라카진의 다른 탈론그립에게 배달해 주길 원합니다.",
        ["D"] =
        "다른 탈론그립은 전쟁이 끝난 후부터 말라카진에 주둔하고 있소. 그는 힘든 상황에서도 훌륭한 지휘관이지. 난 대부분의 오크보다 그를 더 존경하오.\n\n당신에게 다른을 위한 아주 특별한 경화 가죽 장갑 제작을 의뢰하고 싶소. 최근 겪은 좌절로 인해 그가 자신의 지도력에 의구심을 품고 있거든. 그가 여전히 존경받고 가치 있는 존재라는 걸 상기시켜 주고 싶소. 다른이 계속 임무를 수행할 수 있게 돕는 건 호드를 위한 봉사라고 생각해 주시오.",
    },
    [28599] = {
        ["T"] = "사만다 스위프트후프의 의뢰",
        ["O"] =
        "브로운은 당신이 가죽세공 기술을 사용하여 활장이 장갑 1개를 제작한 다음, 가시덤불 골짜기 주요 도로를 순찰하는 사만다 스위프트후프에게 배달해 주길 원합니다.",
        ["D"] =
        "자네가 생가죽을 다루는 솜씨를 봤네. 가죽세공인인가? 자네한테 맡길 일이 하나 있네.\n\n사만다 스위프트후프는 절름발이가 된 발을 치료할 방법을 찾아 가시덤불 골짜기로 왔지. 하지만 이젠 은신과 저격이라는 사냥꾼의 삶을 받아들이고 있는 것 같더군. 그녀를 위해 활장이 장갑을 하나 만들어 주지 않겠나? 내가 직접 해주고 싶지만 꼬치꼬치 캐물은 것도 많고, 내가 자기한테 관심 있다고 생각하게 만들고 싶진 않거든. 그런 건 절대 아니야.\n\n<브로운이 헛기침을 합니다.>",
    },
    [28600] = {
        ["T"] = "토크카르의 의뢰",
        ["O"] =
        "준다르타는 당신이 가죽세공 기술을 사용하여 녹색 가죽 팔보호구 6개를 제작한 다음, 슬픔의 늪 안개갈대 주둔지의 토크카르에게 배달해 주길 원합니다.",
        ["D"] =
        "우리의 정찰병들은 재규어, 악어, 정령, 미쳐 날뛰는 물고기들로부터 우릴 방어하고 있습니다. 이런 짐승들과 싸울 때 손목을 보호해 줄 팔보호구가 필요해요. 당신은 가죽과 바늘을 잘 다루는 것 같군요. 그들을 도와줄 수 있나요?",
    },
    [28601] = {
        ["T"] = "비블리 풋츠버클의 의뢰",
        ["O"] =
        "나르브 하이드크래프터는 당신이 가죽세공 기술을 사용하여 야만전사의 어깨보호구 2개를 제작한 다음, 잊혀진 땅 코르메크의 오두막에 있는 비블리 풋츠버클에게 전달해 주길 원합니다.",
        ["D"] =
        "침묵의 초소 같은 작은 전초기지에서는 우리 모두가 잊혀진 땅의 다른 이들을 돕기 위해 힘을 보태고 있소. 덕분에 내 처리 능력을 넘어서는 주문이 밀려들었고, 자네의 도움이 필요하네.\n\n코르메크의 오두막이라 불리는 판잣집에 사는 고블린이 가죽세공인을 찾고 있더군. \"비즈니스 상의 이유\"로 새 어깨보호구가 필요하다나 뭐라나. 그게 무슨 뜻인진 모르겠지만.\n\n돈을 좀 벌 수 있는 좋은 기회 아닐까? 고블린들은 주머니가 두둑하니까... 듣기로는 그렇다는 거네.",
    },
    [28602] = {
        ["T"] = "조라크 라벤홀트 경의 의뢰",
        ["O"] =
        "조라크 라벤홀트 경은 당신이 가죽세공 기술을 사용하여 서리 가죽 망토 1개를 제작한 다음, 알터랙 산맥 라벤홀트 장원의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "나는 사람을 꿰뚫어 보는 안목이 좀 있지, $C. 내 짐작에 자네는... 솜씨가 꽤 훌륭한 가죽세공인인 것 같군.\n\n펠리시티의 생일이 다가오고 있어. 그녀는 전혀 기대하지 않겠지만 선물을 좀 주고 싶네. 실용적이면서도 우아하고, 그러면서도 약간 예상치 못한 선물이면 좋겠어.\n\n서리 가죽 망토라면 딱 맞을 것 같군. 자, 한 번 만들어 보겠나?",
    },
    [28603] = {
        ["T"] = "감시원 롤로의 의뢰",
        ["O"] =
        "텅크는 당신이 가죽세공 기술을 사용하여 거무스름한 허리띠 2개를 제작한 다음, 아라시 고원 팔디르의 만에 있는 감시원 롤로에게 배달해 주길 원합니다.",
        ["D"] =
        "가죽세공 재료는 잔뜩 있지만, 나한테는 그 기술이 없다네. 주사위를 몇 번 잘못 굴리는 바람에 팔디르의 만에 있는 롤로에게 새 허리띠를 몇 개 빚지게 된 게 문제지.\n\n왜 그런 빚을 졌는지는 묻지 마... 그냥 녀석이 그렇게 갚으라고 한 거니까.\n\n어쨌든 허리띠 없이는 그쪽에 얼굴을 내밀 수가 없으니 좀 도와줄 수 있겠나?",
    },
    [28604] = {
        ["T"] = "보안과장 빌지위즐의 의뢰",
        ["O"] =
        "보안과장 빌지위즐은 당신이 가죽세공 기술을 사용하여 거북 껍질 다리보호구 2개를 제작한 다음, Tanaris 스팀휘들 항구의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "가죽세공인이슈? 굳은살을 보아하니 딱이구만.\n\n이봐, 잠깐 내 불평 좀 들어봐. 평범한 바지로는 여기서 못 버텨. 해적 놈들 주먹은 맵고, 햇살은 더 맵거든. 거북이 껍질로 만든 바지를 원해. 거북이 등딱지야말로 오우거 이마만큼이나 튼튼하니까 말이야.\n\n가죽세공 기술이 충분하다면 거북 껍질 다리보호구를 좀 만들어 줘. 튼튼하고, 활동하기 편하고, 해적의 공격도 막아줄 그런 놈으로 부탁해. 내 우선순위가 그렇단 말이지.",
    },
    [28605] = {
        ["T"] = "그레간 브루스퓨의 의뢰",
        ["O"] =
        "장도르 스위프트스트라이더는 당신이 가죽세공 기술을 사용하여 속사 화살통 1개를 제작한 다음, 페랄라스 쌍둥이 바위산 근처 야영지의 그레간 브루스퓨에게 배달해 주길 원합니다.",
        ["D"] =
        "그 드워프 그레간은 이곳을 거쳐 간 대부분의 드루이드들보다 더 오래 페랄라스 야생에 머물렀지. 내게 속사 화살통을 새로 만들어 달라는 부탁을 해 왔어. 숲의 습기에도 망가지지 않는 게 필요하다고 하더군.\n\n모자케 야영지 밖으로 나갈 순 없어! 하지만 자네에겐 그걸 만들 실력이 있지 않나?",
    },
    [28606] = {
        ["T"] = "타론 레드페더의 의뢰",
        ["O"] =
        "타론 레드페더는 당신이 가죽세공 기술을 사용하여 거친 경화 가죽 1개를 제작한 다음, 악령숲 에메랄드 성소의 자신에게 배달해 주길 원합니다.",
        ["D"] =
        "뛰어난 가죽세공인이군! 가죽과 깊은바위 소금의 냄새는 어디서든 알아볼 수 있지.\n\n말이 나온 김에... 자네의 기술이 좀 필요하네. 이 숲의 지옥 타락이 내 텐트의 구조용 가죽에 구멍을 내기 시작해서, 덧댈 거친 경화 가죽이 필요해. 안 그러면 우리 머리 위로 텐트가 통째로 무너져 내릴지도 몰라!\n\n그 가죽을 조달해 준다면 정말 고맙겠네.",
    },
    [28607] = {
        ["T"] = "카마리의 의뢰",
        ["O"] =
        "렐코는 당신이 가죽세공 기술을 사용하여 밤하늘 장화 2개를 제작한 다음, 듀로타 오그리마의 카마리에게 배달해 주길 원합니다.",
        ["D"] =
        "오! 자네가 가죽세공인이니 부탁 하나만 더 해도 될까?\n\n나는 카마리에게 평생 갚지 못할 빚을 졌어. 그녀는 내 아이들의 어머니이고, 내가 밖으로 나도는 걸 대부분 참아주었거든. 거의 다.\n\n아무튼, 지금 당장 가죽이 없어서 그런데 밤하늘 장화 두어 켤레를 만들어서 오그리마 골목길에 있는 그녀의 상점으로 배달해 주면 정말 고맙겠네, $g형제님:자매님;.",
    },
    [28608] = {
        ["T"] = "거트 레더선더의 의뢰",
        ["O"] =
        "거트 레더선더는 당신이 무두질 기술을 사용하여 얇은 통가죽 5개를 구한 다음, 던 모로 카라노스의 자신에게 가져오길 원합니다.",
        ["D"] =
        "무두장이가 되고 싶어? 그럼 쪼가리 말고 진짜를 구해올 수 있다는 걸 증명해 봐.\n\n얇은 통가죽을 가져와 -- 그냥 가죽 말고 껍질 전체를 말이야. 모양도, 형태도 잡혀 있고... 가공할 만한 가치가 있는 걸로. 네가 뭘 하고 있는지 안다는 걸 증명하면, 이 기술을 계속 배울 수 있도록 보증해 주지.",
    },
    [28609] = {
        ["T"] = "래드날 메인위버의 의뢰",
        ["O"] =
        "래드날 메인위버는 당신이 무두질 기술을 사용하여 얇은 가죽 20개를 구한 다음, 텔드랏실에 있는 그의 집으로 가져오길 원합니다.",
        ["D"] =
        "칼을 휘둘러 껍질을 벗기는 건 누구나 할 수 있지만, 깔끔하게 할 수 있겠소? 항상 일정하게? 짐승에 대한 적절한 예의를 갖춰서 말이오.\n\n잘 손질된 얇은 가죽 20장을 가져오시오. 가죽을 망치지 않고 그걸 모아온다면, 제대로 된 기술을 배울 준비가 된 것으로 간주하겠소.",
    },
    [28610] = {
        ["T"] = "라드란의 의뢰",
        ["O"] =
        "라드란은 당신이 무두질 기술을 사용하여 일반 가죽 20개를 구한 다음, 잿빛 골짜기 아스트라나르의 자신에게 가져오길 원합니다.",
        ["D"] =
        "반갑소, $N. 무두장이 칼을 다룰 줄 아시오? 파수꾼들과 아스트라나르를 지나가는 모험가들의 수요를 맞추기 위해 밤낮으로 일하고 있는데 원자재가 턱없이 부족하오.\n\n일반 가죽 20장을 가져다준다면, 기꺼이 그 수고비를 치르겠소.",
    },
    [28611] = {
        ["T"] = "렌도우의 의뢰",
        ["O"] =
        "렌도우는 당신이 무두질 기술을 사용하여 일반 통가죽 5개를 구한 다음, 버섯구름 봉우리 탈라나르의 자신에게 가져오길 원합니다.",
        ["D"] =
        "반갑습니다, $N. 실례지만 가방에 조심스럽게 묶여 있는 당신의 무두장이 칼을 안 볼 수가 없었군요. 저는 항상 이 야생으로 모험을 떠나는 이들을 보호할 갑옷을 만들 원자재에 관심이 많습니다. 절 위해 일반 통가죽 5장을 구해다 주시겠습니까?",
    },
    [28612] = {
        ["T"] = "모루울의 의뢰",
        ["O"] =
        "모루울은 당신이 무두질 기술을 사용하여 새끼 녹색용 비늘 5개를 구한 다음, 슬픔의 늪 피난처의 자신에게 가져오길 원합니다.",
        ["D"] =
        "아. 이계의 존재여. 무두질 도구를 지닌 자로군.\n\n이 세계는 낯설어 -- 짐승들도, 하늘도, 냄새도. 하지만 가죽은 여전히 가죽이고, 난 여전히 내 기술을 알고 있지.\n\n남쪽에 산다는 작은 용들에게 흥미가 생겼어. 새끼 녹색용 비늘 5개를 내게 가져다줘. 그걸로 이곳에 어울리는 갑옷을 만들어 볼 테니.",
    },
    [28613] = {
        ["T"] = "전투교관 스지게티의 의뢰",
        ["O"] =
        "전투교관 스지게티는 당신이 무두질 기술을 사용하여 두꺼운 가죽 20개를 구한 다음, 먼지진흙 습지대 테라모어 섬의 전투교관 스지게티에게 가져오길 원합니다.",
        ["D"] =
        "훈련병들을 보러 왔나? 신병이 들어온다는 건 멍과 피, 그리고 박살 난 장비들이 늘어난다는 뜻이지. 녀석들의 갑옷이 버텨주지 못하면 녀석들도 버티지 못할 거야.\n\n우리 군대를 돕고 싶다면 두꺼운 가죽 20장을 가져와. 훈련 장비를 보강하는 데 써야 하거든. 타격을 견뎌낼 만큼 튼튼해야 하면서도, 금방 망가져도 아깝지 않을 만큼 저렴해야 해.",
    },
    [28614] = {
        ["T"] = "스쿼토의 의뢰",
        ["O"] =
        "스쿼토는 당신이 무두질 기술을 사용하여 랩터 통가죽 5개를 구한 다음, 아라시 고원 임시 주둔지의 스쿼토에게 가져오길 원합니다.",
        ["D"] =
        "고원에는 랩터들이 득실거려. 녀석들은 발톱과 비늘로 무장한 아주 사나운 놈들이지. 우리가 녀석들과 꽤 자주 싸우는데... 기왕 싸우는 거 녀석들을 활용하는 게 낫지 않겠어?\n\n랩터 통가죽 5장을 가져오라고. 튼튼한 놈이라 장비 만들기엔 딱이니까. 그 좋은 가죽을 풀밭에서 썩히게 둘 필요는 없잖아.",
    },
    [28615] = {
        ["T"] = "니오마의 의뢰",
        ["O"] =
        "니오마는 당신이 무두질 기술을 사용하여 거북 등딱지 10개를 구한 다음, 동부 내륙지 맹금의 봉우리의 자신에게 가져오길 원합니다.",
        ["D"] =
        "저 멀리 동쪽 바닷가에 사는 거북이들은 비록 느리지만 그 껍질은 아주 특별해. 내구성도 좋고, 유연하면서도 놀라울 만큼 다루기 쉽거든.\n\n요즘 순찰하는 트롤들 때문에 재고를 채우러 나갈 수가 없었어. 만약 그쪽으로 갈 일이 있다면 거북 등딱지 10개를 가져다줘. 제대로 손질만 하면 평생 입을 수 있는 훌륭한 방어구로 만들 수 있거든.",
    },
    [28616] = {
        ["T"] = "피즈너클의 의뢰",
        ["O"] =
        "피즈너클은 당신이 무두질 기술을 사용하여 돌연변이 비늘 5개와 완전한 돌연변이 비늘 1개를 구한 다음, 불모의 땅 통곡의 동굴 서쪽에 있는 자신의 상점으로 가져오길 원합니다.",
        ["D"] =
        "오호라, 무두장이신가? 돌연변이 가죽에 대해 잘 알아? 아주 기이한 물건이지. 반짝거리고 튼튼해서 불티나게 팔린다고.\n\n이봐 거래 하나 하지. 내게 돌연변이 비늘 5개와 완전한 돌연변이 비늘 1개를 가져다주면, 내 수익의 일부를 떼어주지.\n\n그걸 구하려면 통곡의 동굴로 들어가야 할 거야. 감당할 수 있겠어?",
    },
    [28617] = {
        ["T"] = "비블리 풋츠버클의 의뢰",
        ["O"] =
        "비블리 풋츠버클은 당신이 무두질 기술을 사용하여 질긴 통가죽 5개를 구한 다음, 잊혀진 땅 코르메크의 오두막에 있는 자신에게 가져오길 원합니다.",
        ["D"] =
        "이봐, 무두장이. 일거리가 하나 있어. 어디에 쓸 건지는 묻지 마. 아니 진짜로. 묻지 마.\n\n네가 알 건 딱 하나, 질긴 통가죽이 필요하다는 거야. 크고, 두껍고, 구하기 힘든 거... 어떤 진행 중인 프로젝트에 완벽하게 어울리거든.\n\n전혀 무해한 일이야, 장담하지. 아마도.",
    },
    [28618] = {
        ["T"] = "조아킴 스파크루트의 의뢰",
        ["O"] =
        "조아킴 스파크루트는 당신이 무두질 기술을 사용하여 닳아해진 용비늘 5개를 구한 다음, 황야의 땅 스프링소켓에 있는 자신에게 가져오길 원합니다.",
        ["D"] =
        "용. 거대하고 분노에 찬 위험한 생물. 여기서 동쪽으로 조금만 가면 녀석들이 잔뜩 있는데, 내가 장담하건대 녀석들은 아주 값진 존재야. 어디에 팔아야 할지만 안다면 비늘 하나하나가 동전 무더기로 바뀐다고. 물론 넌 그 정보를 감당할 여유가 없겠지만.\n\n그러니까, 거래를 좀 하자고. 닳아해진 용비늘 5개를 내게 가져와. 지금은 별 볼 일 없어 보여도, 약간의 광택과 다듬기를 거치면 이 짐승의 껍데기가 엄청난 현상금으로 변할 테니까.",
    },
    [28619] = {
        ["T"] = "쿠인의 의뢰",
        ["O"] =
        "쿠인은 당신이 무두질 기술을 사용하여 전갈 딱지 10개를 구한 다음, Tanaris 가젯잔의 쿠인에게 가져오길 원합니다.",
        ["D"] =
        "사막은 자신의 보물을 쉽게 내어주지 않아. 피 흘리고, 불타고, 바싹 구워져야만 찾을 수 있지.\n\n하지만 전갈 딱지는? 전혀 숨겨져 있지 않은 보물이지. 전갈 딱지 10개를 가져와, 그럼 이 사막의 골칫거리들을 어떻게 돈으로 바꾸는지 보여줄 테니.",
    },
    [28620] = {
        ["T"] = "비고의 의뢰",
        ["O"] =
        "비고는 당신이 무두질 기술을 사용하여 두꺼운 가죽 20개를 구한 다음, 페랄라스 글룩의 요새에 있는 자신에게 가져오길 원합니다.",
        ["D"] =
        "이봐, 자네 무두장이인가? 내가 개인적으로 진행하는 일이 몇 개 있어서 말이야. 아주 은밀하고, 공식적인 건 아무것도 없는 일이지. 하지만 질 좋은 재료가 필요해.\n\n두꺼운 가죽 20장을 가져오면 이곳을 모험할 때 유용한 보급품과 교환해 주지. 깨끗하게 잘린 튼튼한 가죽이 필요해. 묻지도 따지지도 않고 말이야.",
    },
    [28621] = {
        ["T"] = "타론 레드페더의 의뢰",
        ["O"] =
        "타론 레드페더는 당신이 무두질 기술을 사용하여 두꺼운 통가죽 5개를 구한 다음, 악령숲 에메랄드 성소에 있는 자신에게 가져오길 원합니다.",
        ["D"] =
        "이 숲에 타락이 얼마나 깊이 스며들었는지 확인할 수 있는 또 다른 방법은 바로 이곳의 짐승들을 연구하는 걸세. 녀석들은 뒤틀려버렸지만, 과연 녀석들의 가죽도 그럴까? 타락은 깊이 뿌리박혔지만, 과연 얼마나 깊을까?\n\n악령숲의 생물들에게서 두꺼운 통가죽 5장을 구해와 주게. 그걸 시험하고, 오염을 연구해 보고 싶네. 만약 피부가 그 독을 기억하고 있다면, 우린 그걸 이겨낼 방법을 배울 수 있을지도 몰라.",
    },
    [28622] = {
        ["T"] = "델레이지의 의뢰",
        ["O"] =
        "델레이지는 당신이 무두질 기술을 사용하여 거친 통가죽 5개를 구한 다음, 아즈샤라 검은아귀 마을의 델레이지에게 가져오길 원합니다.",
        ["D"] =
        "겨울이 살며시 다가오는데, 모든 이가 쉴 곳을 가진 건 아니야. 아즈샤라의 바람은 특히 밤이면 뼈를 깎는 듯이 매섭지.\n\n따뜻한 담요를 만들 거친 통가죽 5장이 필요해. 우리 새끼들을 보호해야 하거든. 단순한 일이지만, 많은 이들의 생존이 걸린 일이야.",
    },
    [28623] = {
        ["T"] = "수석대장장이 버니네이트의 의뢰",
        ["O"] =
        "수석대장장이 버니네이트는 당신이 무두질 기술을 사용하여 튼튼한 가죽 20개를 구한 다음, 이글거리는 협곡 토륨 거점의 자신에게 가져오길 원합니다.",
        ["D"] =
        "우리가 어둠괴철로 도시에서 빠져나올 때, 도구, 장비, 그리고 질 좋은 가죽까지 보급품의 절반을 그곳에 두고 와야 했어. 추억만으로는 물건을 만들 수 없더군.\n\n여기서 우릴 돕고 싶다면 튼튼한 가죽 20장을 가져와. 잃어버린 것들은 내가 어떻게든 채워 넣을 테니. 징징대봤자 소용없어. 그냥 일이나 시작하라고.",
    },
    [28624] = {
        ["T"] = "트자카자의 의뢰",
        ["O"] =
        "트자카자는 당신이 무두질 기술을 사용하여 전투곰 가죽 5개를 구한 다음, 여명의 설원 눈망루 마을의 트자카자에게 가져오길 원합니다.",
        ["D"] =
        "여긴 너무 추워. 트자카자는 밀림이 그리워. 따뜻함이 그립다고. 하지만 트자카자는 추위를 견딜 수 있게 도와줄 무언가에 대해 들었지.\n\n이곳의 곰들은 겨울을 나기 위해 아주 두껍고 질긴 가죽을 가지고 있어. 전투곰 가죽 5장을 가져와, 그럼 트자카자의 고용주가 원할 때까지 트자카자도 이 추위를 버틸 수 있을 테니까.",
    },
    [28625] = {
        ["T"] = "욘 디프컷의 의뢰",
        ["O"] =
        "욘 디프컷은 당신이 무두질 기술을 사용하여 얇은 통가죽 5개를 구한 다음, 멀고어 블러드후프 마을의 욘 디프컷에게 가져오길 원합니다.",
        ["D"] =
        "반갑네, $N. 무두장이가 되고 싶나? 그럼 쪼가리 말고 진짜를 구해올 수 있다는 걸 증명해 봐.\n\n얇은 통가죽을 가져와 -- 그냥 가죽 말고 껍질 전체를 말이야. 모양도, 형태도 잡혀 있고... 가공할 만한 가치가 있는 걸로. 네가 뭘 하고 있는지 안다는 걸 증명하면, 이 기술을 계속 배울 수 있도록 보증해 주지.",
    },
    [28626] = {
        ["T"] = "죽음의경비병 리니아의 의뢰",
        ["O"] =
        "죽음의경비병 리니아는 당신이 무두질 기술을 사용하여 얇은 가죽 20개를 구한 다음, 티리스팔 숲 브릴 남쪽 야영지의 죽음의경비병 리니아에게 가져오길 원합니다.",
        ["D"] =
        "거기. 네가 무두질 전문가와 대화하는 걸 봤다! 네 기술이 필요해.\n\n칼을 휘둘러 가죽을 벗기는 건 아무나 할 수 있지만, 깔끔하게 할 수 있겠나? 변함없이? 짐승에 대한 적절한 예의를 갖춰서 말이야.\n\n깔끔하게 재단된 얇은 가죽 20장을 가져와라. 가죽을 엉망으로 만들지 않고 그것들을 모아온다면, 이 기술을 제대로 배울 준비가 된 것으로 간주하겠다.",
