        ["D"] =
        "반갑소, $N. 무두장이 칼을 다룰 줄 아시오? 토막나무 주둔지를 지나가는 전쟁노래 부족과 모험가들의 수요를 맞추기 위해 밤낮으로 일하고 있는데 원자재가 턱없이 부족하오.\n\n일반 가죽 20장을 가져다준다면, 기꺼이 그 수고비를 치르겠소.",
