        "그런트 줄은 당신이 무두질 기술을 사용하여 새끼 녹색용 비늘 5개를 구한 다음, 슬픔의 늪 스토나드의 그런트 줄에게 가져오길 원합니다.",
        ["D"] =
        "거기 무두질용 칼 든 녀석. 네 도움이 필요하다!\n\n이 인간 녀석이 늪지대 때문에 자꾸 악몽을 꾼다며 징징대고 있어. 잠 좀 제대로 자려면 새끼 녹색용 비늘로 만든 담요가 필요하다나 뭐라나.\n\n우린 이 녀석을 살려두라는 명령을 받았고, 난 녀석의 불평을 더 이상 듣고 싶지 않다. 그러니 녀석이 원하는 비늘을 좀 구해다 줄 수 있겠나?",
