        ["D"] =
        "도와주러 왔어? 크라크 새로운 물건 만들 가죽 필요해. 용들이 공격했을 때 많이 잃었어. 새로운 팔보호구 필요해. 새로운 허리띠. 이거 만들려면 두꺼운 가죽 필요해.\n\n너 늪에 가서 가죽 구해올래? 그럼 크라크 아주 기쁠 거야!",
