    [28631] = {
        ["T"] = "텅크의 의뢰",
        ["O"] =
        "텅크는 당신이 무두질 기술을 사용하여 랩터 통가죽 5개를 구한 다음, 아라시 고원 망치 주둔지의 텅크에게 가져오길 원합니다.",
        ["D"] =
        "고원에는 랩터들이 득실거려. 녀석들은 발톱과 비늘로 무장한 아주 사나운 놈들이지. 우리가 녀석들과 꽤 자주 싸우는데... 기왕 싸우는 거 녀석들을 활용하는 게 낫지 않겠어?\n\n랩터 통가죽 5장을 가져오라고. 튼튼한 놈이라 장비 만들기엔 딱이니까. 그 좋은 가죽을 풀밭에서 썩히게 둘 필요는 없잖아.",
    },
    [28632] = {
        ["T"] = "대장장이 슬래그트리의 의뢰",
        ["O"] =
        "대장장이 슬래그트리는 당신이 무두질 기술을 사용하여 거북 등딱지 10개를 구한 다음, 동부 내륙지 깨진엄니 마을의 대장장이 슬래그트리에게 가져오길 원합니다.",
        ["D"] =
        "여기 해안가에 사는 거북이들은 비록 느리지만 그 껍질은 아주 특별해. 내구성도 좋고, 유연하면서도 놀라울 만큼 다루기 쉽거든.\n\n요즘 순찰하는 와일드해머와 트롤들 때문에 재고를 채우러 나갈 수가 없었어. 만약 나갈 일이 있다면 거북 등딱지 10개를 가져다줘. 제대로 손질만 하면 평생 입을 수 있는 훌륭한 방어구로 만들 수 있거든.",
