        ["O"] =
        "대장장이 아르거스는 당신이 채광 기술을 사용하여 구리 광석 20개를 수집한 다음, 엘윈 숲 서쪽시내 주둔지의 병참장교 허드슨에게 전달해 주길 원합니다.",
        ["D"] =
        "자네 광부인가? 자네 도움이 좀 필요하네.\n\n서쪽시내 주둔지의 병참장교 허드슨이 구리 광석을 대량으로 요청했는데, 지금 당장은 여분이 없군. 자네 기술을 발휘해서 골드샤이어를 대신해 이 주문을 좀 처리해 주지 않겠나?",
