        ["D"] =
        "자네 가방에 있는 그 곡괭이 보이는데! 마침 난처한 참인데 자네가 날 좀 도와주게!\n\n채석장에 트로그들이 들어차는 바람에 민간인들의 석재 주문을 채우는 데 큰 차질을 빚고 있어. 우리 재고는 모조리 군대로 보내야 하거든.\n\n작은 암석 20개를 캐서 스틸그릴의 정비소에 있는 얄 해머스톤에게 가져다주면, 내 마음의 무거운 짐을 덜어줄 수 있을 거야.",
