        ["D"] =
        "지금 다르나서스의 가열로가 타오르고 있다 해도, 모든 우아함에는 토대가 필요한 법이지. 이제 텔드랏실에서 채광이 가능해지면서 수요가 엄청나게 몰리고 있어.\n\n내게 구리 주괴 10개를 가져다줘. 밀린 주문이 많아... 섬세한 장식, 조용한 강인함 같은 것들이지. 그리고 구리는... 구리는 장인의 손길에 잘 순응하거든.",
