        ["D"] =
        "아, 광부로군. 자네에게 맡길 일이 있어.\n\n가끔은 흔해 빠진 광석과 침만으로는 안 되는 특별한 작업이 필요할 때가 있지. 엘프들이 열광하는 달빛 같은 특별한 광채를 지닌 그런 거 말이야.\n\n아무튼, 은괴 5개를 가져와. 여기 아우버다인에서 딱 알맞은 빛깔을 필요로 하는 주문이 들어왔는데, 은이 아주 제격이거든.",
