        ["D"] =
        "아, 광부로군. 자네에게 맡길 일이 있어.\n\n아이언밴드가 또 은 광석이 필요하다며 징징대고 있어. 발굴현장에 있는 룬이 새겨진 이상한 기계를 만지작거리는 데 필요하다나 뭐라나. 티탄의 일이 아니라 은 기질의 미신이겠지!\n\n아무튼, 은여울 광산이 마른 이후로 난 은이 뚝 떨어졌네. 자네가 좀 찾아다 배달해 주겠나? 그리고 시간이 넉넉지 않다면 녀석이 떠들어대는 드워프 역사 얘기엔 귀 기울이지 마!",
