        ["D"] =
        "구리는 어떻게 써야 할지 모를 정도로 차고 넘치는데, 주석이 없으니 청동을 녹여낼 수가 없군. 문제는, 숲속에 도사리고 있는 짐승들 때문에 마을 밖으로 나가는 게 너무 위험하다는 거야.\n\n내가 저 어둠 속에 사는 것들에게 잡아먹히지 않고 계속 가열로를 돌릴 수 있도록 주석 광석 20개를 가져다줄 수 있겠어?",
