        ["D"] =
        "이봐 거기! 곡괭이 든 친구. 얼라이언스엔 당신의 도움이 필요해.\n\n방금 지시가 내려왔어: 남녘해안의 메이저 헬름스워시가 장비 수리와 부품 제작을 위해 주석 주괴 20개가 필요하대. 문제는, 우리가 이 광산에서 더 이상 주석을 캐내지 않는다는 거지.\n\n주괴를 찾아서 남녘해안에 있는 그에게 가져다줘. 기다리는 걸 좋아하는 사람이 아니니까.",
