        ["D"] =
        "워, 어이 거기. 이 경주장 보여? 손봐야 할 엔진은 산더미인데 시간이 모자라! 용접할 부품도 널렸고 갈아내야 할 톱니바퀴도 쌨는데, 청동 재고가 하나도 없어.\n\n당장 청동 주괴 20개를 가져다줘, 빨리! 내가 직접 가고 싶지만, 여기서 한 발짝이라도 떨어졌다간 무언가가 폭발하고 말 거라고. 아마도...!",
    },
    [28641] = {
