        "바퍼 툭윙클은 당신이 채광 기술을 사용하여 큰 암석 20개를 수집한 다음, 돌발톱 산맥 돌발톱 숲의 바퍼 툭윙클에게 가져오길 원합니다.",
        ["D"] =
        "어라, 이 돌발톱에 광부가 나타났네? 아주 제격인 장소지. 혹시 일자리를 찾고 있다면 마침 자네에게 딱 맞는 일이 여기 있는데?\n\n난 돌이 필요해! 정확히 말하자면 철 광석 주변에서 흔히 볼 수 있는 크고 단단한 돌멩이 말이야. 돌발톱 내에는 철이 조금밖에 없지만, 인접한 지역엔 그런 재료가 아주 풍부하거든. 기꺼이 도와준다면 돌아왔을 때 두둑이 보상해 주지!",
