    [28642] = {
        ["T"] = "모루울의 의뢰",
        ["O"] =
        "모루울은 당신이 채광 기술을 사용하여 금괴 5개를 수집한 다음, 슬픔의 늪 피난처의 자신에게 가져오길 원합니다.",
        ["D"] =
        "내 세계에서 방어구는 섬유와 갈대, 수정과 빛으로 엮어 만들지. 하지만 이곳에선 금속으로 모양을 잡더군.\n\n금은 무르다고 들었어. 쉽게 구부러지고 모양을 낼 수 있지. 금괴 10개를 가져와, 그럼 내가 당신들의 방식을 배워서 뭔가 아름다운 걸 만들어 볼 테니.",
    },
    [28643] = {
        ["T"] = "카즈 투스프로켓의 의뢰",
        ["O"] =
        "카즈 투스프로켓은 당신이 채광 기술을 사용하여 철 광석 20개를 수집한 다음, 먼지진흙 습지대 테라모어 섬의 카즈 투스프로켓에게 가져오길 원합니다.",
        ["D"] =
        "여기서 쿨티라스인들을 위해 일하는 건 정말 고역이야, 안 그래! 이따금 사령관이 불쑥 나타나선 내 철 광석을 몽땅 징발해 가버린다고. 방금도 또 그랬어!\n\n오, 등에 곡괭이를 메고 있군! 혹시 내 개인 비축량을 다시 채워줄 생각 없어? 네가 수고해 준다면 모험가라면 누구나 탐낼 만한 내 물건들과 기꺼이 교환해 주지!",
    },
    [28644] = {
        ["T"] = "디비 스퀴글코드의 의뢰",
        ["O"] =
        "디비 스퀴글코드는 당신이 채광 기술을 사용하여 철 주괴 20개를 수집한 다음, 잊혀진 땅 스퀴글코드 전초기지의 자신에게 가져오길 원합니다.",
        ["D"] =
        "내 전초기지는 아주 순조롭게 지어지고 있어... 아, 우리가 비축해 둔 철 주괴가 엄청나게 부족하다는 것만 빼면 말이지.\n\n철 주괴를 좀 가져다줄 수 있을까? 엄청나게 많은 양은 아니어도 돼, 그저 문손잡이가 떨어지지 않고 누군가 기대어도 벽이 무너지지 않을 정도면 충분해.",
    },
    [28645] = {
        ["T"] = "사령관 스트롱본의 의뢰",
        ["O"] =
        "사령관 스트롱본은 당신이 채광 기술을 사용하여 강철 주괴 10개를 수집한 다음, 저습지 번듀랄의 사령관 스트롱본에게 가져오길 원합니다.",
        ["D"] =
        "저 이두박근 좀 보게! 자넨 광부 아니면 대장장이에게 최악의 악몽이 될 존재가 분명해. 어찌 됐든 자네의 힘이 필요하네.\n\n이 바리케이드가 보이나? 우린 이걸 유지하기 위해 모든 걸 쏟아부었지만 오크 녀석들은 끊임없이 몰려들고 있어. 바리케이드를 보강할 강철 주괴 10개가 필요해. 빠르면 빠를수록 좋고!",
    },
    [28646] = {
        ["T"] = "알렉시아 아이언나이프의 의뢰",
        ["O"] =
        "알렉시아 아이언나이프는 당신이 채광 기술을 사용하여 진은 광석 10개를 수집한 다음, 서부 역병지대 서리바람 야영지의 알렉시아 아이언나이프에게 가져오길 원합니다.",
        ["D"] =
        "진은이 언데드 근처에서 이상한 공명을 일으킨다는 걸 눈치챈 적 있소? 난 진은이 강령술 에너지와 반응할지도 모른다는 가설을 세웠는데, 그걸 증명할 표본이 필요하오.\n\n난 광부가 아니오... 하지만 당신은 광부지! 진은 광석 10개를 가져다주겠소? 만약 내 가설이 맞다면, 우린 우아하면서도 치명적인 무기를 발견하게 될 거요.",
    },
    [28647] = {
        ["T"] = "스트럼너 플린트힐의 의뢰",
        ["O"] =
        "스트럼너 플린트힐은 당신이 채광 기술을 사용하여 진은 주괴 5개를 수집한 다음, 저주받은 땅 네더가드 요새의 자신에게 가져오길 원합니다.",
        ["D"] =
        "악마들은 진은을 싫어한다고 하더군. 그들을 탓할 순 없지. 반짝거리고, 날카롭게 잘 연마되는 데다 다방면으로 축복받은 금속이니까.\n\n어둠의 문 잔해 근처를 배회하는 악마들 때문에 우린 진은 무기를 넉넉히 비축해 둘 필요가 있어. 진은 주괴 5개를 가져오면, 얼라이언스를 위해 큰 공을 세우는 셈이지.",
    },
    [28648] = {
        ["T"] = "윌슨 워블스미스의 의뢰",
        ["O"] =
        "윌슨 워블스미스는 당신이 채광 기술을 사용하여 토륨 주괴 20개를 수집한 다음, 아즈샤라 워블 할로우의 윌슨 워블스미스에게 가져오길 원합니다.",
        ["D"] =
        "이건 정말 재앙이에요, $N! 우리가 타고 출발한 비행기 네 대 중 겨우 한 대만 건져냈는데, 이걸 다시 고치려면 기적이 필요할 지경이죠.\n\n하지만 토륨 주괴 20개를 긁어모아 주시면 큰 도움이 될 거예요. 저기 위쪽 야생 지대에 광석이 널려 있다고 들었거든요. 제가 직접 가서 확인할 시간만 있었더라도요.",
    },
    [28649] = {
        ["T"] = "웨니키 볼트버킷의 의뢰",
        ["O"] =
        "스퍼터밸브는 당신이 채광 기술을 사용하여 일반 암석 20개를 수집한 다음, 북부 불모의 땅 황금길에 있는 웨니키 볼트버킷의 집으로 가져가길 원합니다.",
        ["D"] =
        "일거리를 찾는 광부야? 마침 좋은 정보가 있지.\n\n웨니키가 뭔가 시끄럽고, 불안정하며, 절대 합법적이지 않은 물건을 만들고 있어. \"구조적 완충\"인지 뭔지 하는 헛소리 때문에 일반 암석 20개가 필요하다더군. 더 빨리 달릴 수만 있다면 구조 따위 알 게 뭐야?\n\n네가 좀 캐다 줄 수 있다면 그녀에게 가져다줘 -- 황금길을 따라 북쪽으로 가면 그녀가 자리 잡고 있을 거야.",
    },
    [28650] = {
        ["T"] = "맥가반의 의뢰",
        ["O"] =
        "맥가반은 당신이 채광 기술을 사용하여 금 광석 10개를 수집한 다음, 가시덤불 골짜기 무법항의 자신에게 가져오길 원합니다.",
        ["D"] =
        "금은 많은 걸 말해주지, $C. 이 무법항에서는 아주 고래고래 소리를 지른다네.\n\n미스릴 대장조합은 품질로 유명해서 구매자들이 줄을 섰지만, 보여줄 물건이 없어. 요새는 다들 번쩍이는 금장식을 원하는데 내겐 금 광석이 다 떨어졌거든.\n\n한몫 챙겨볼 텐가? 금 광석 10개를 가져와. 구하기 힘든 귀한 물건이지만 누가 돈을 내는지 안다면 곡괭이질할 가치는 충분할 테니.",
    },
    [28651] = {
        ["T"] = "가플의 의뢰",
        ["O"] =
        "가플은 당신이 채광 기술을 사용하여 견고한 암석 20개를 수집한 다음, 황야의 땅 스프링소켓의 자신에게 가져오길 원합니다.",
        ["D"] =
        "이 황야의 땅에선 다들 광석 때문에 싸워대지. 인듀리움? 토륨? 집어치우라지, 난 돌이 필요해. 단단하고 다듬어지지 않은 돌 말이야.\n\n이봐, 넌 기술이 있고 난 연줄이 있으니, 거래 한 번 해볼 텐가? 견고한 암석 20개를 가져오면, 내가 이 척박한 황무지에서 네가 하루 더 버틸 수 있게 해 주지.",
    },
    [28652] = {
        ["T"] = "트렌튼 라이트해머의 의뢰",
        ["O"] =
        "트렌튼 라이트해머는 당신이 채광 기술을 사용하여 미스릴 광석 20개를 수집한 다음, Tanaris 가젯잔의 자신에게 가져오길 원합니다.",
        ["D"] =
        "엘프가 대장장이의 망치를 쥐는 것도 흔치 않은 일이지만, 그 실력으로 존경받는 엘프는 더더욱 드물지. 하지만 난 술스라즈를 본 순간부터, 그 비밀을 알아내기 전까진 결코 쉬지 않겠노라 다짐했어.\n\n연구를 계속하려면 미스릴 광석이 필요해. 사막에 자원이 풍부하긴 하지만 이곳에서만 구할 수 있는 건 아니지. 어서 가서 내가 원하는 걸 가져오게나.",
    },
    [28653] = {
        ["T"] = "비고의 의뢰",
        ["O"] =
        "비고는 당신이 채광 기술을 사용하여 미스릴 주괴 20개를 수집한 다음, 페랄라스 글룩의 요새에 있는 자신에게 가져오길 원합니다.",
        ["D"] =
        "저기 멍청한 녀석 두 명 보여? 바보랑 멍청이는 며칠 내로 가열로를 준비하겠다는데, 도무지 믿을 수가 있어야지.\n\n미스릴 주괴가 좀 있다면 작업 속도를 앞당길 수 있을 거야. 20개 정도면 충분하겠군. 그래. 물론 가열로를 위해서지. 날 위해 개인적으로 쓰려는 게 절대 아니야. 어쨌든 가져오라고.",
    },
    [28654] = {
        ["T"] = "켈레크 스카이키퍼의 의뢰",
        ["O"] =
        "켈레크 스카이키퍼는 당신이 채광 기술을 사용하여 토륨 광석 20개를 수집한 다음, 악령숲 에메랄드 성소에 있는 자신에게 가져오길 원합니다.",
        ["D"] =
        "예전에 쓰던 정원 도구들을 되찾는다 해도, 그게 과연 쓸모가 있을지 모르겠군요. 이곳의 타락은 너무 깊어서 이 땅을 가꾸려면 훨씬 더 단단한 모종삽이 필요할지도 몰라요.\n\n토륨 광석 20개를 가져다주시면 새로운 도구를 만들 수 있을 거예요. 토륨은 아주 단단하다고 들었어요. 악령숲의 타락을 견뎌낼 수 있는 재료가 있다면 틀림없이 그것일 겁니다.",
    },
    [28655] = {
        ["T"] = "수석대장장이 버니네이트의 의뢰",
        ["O"] =
        "수석대장장이 버니네이트는 당신이 채광 기술을 사용하여 검은무쇠 광석 10개를 수집한 다음, 이글거리는 협곡 토륨 거점의 자신에게 가져오길 원합니다.",
        ["D"] =
        "어둠괴철로 도시를 버리고 떠날 때, 우린 가열로와 도구들... 그리고 모든 보급품을 남겨둬야 했지.\n\n이제 이곳을 재건해야 하니, 숙련된 광부의 도움이 필요해. 검은무쇠 광석 10개를 가져다줘. 우리가 예전의 힘을 되찾기 위한 첫걸음은 불과 금속에서 시작될 테니까.",
    },
    [28656] = {
        ["T"] = "비엘의 의뢰",
        ["O"] =
        "비엘은 당신이 채광 기술을 사용하여 강도 높은 암석 20개를 수집한 다음, 여명의 설원 검은속삭임 협곡의 비엘에게 가져오길 원합니다.",
        ["D"] =
        "난 누군가에게 무언가를 요구하는 일이 드물다, 필멸자여. 그리고 설명하지도 않지. 하지만 네가 도와줄 수 있는 나만의 목적이 있다.\n\n강도 높은 암석 20개를 가져와라. 질문은 협곡 입구에나 두고 와라, 대답은 나중에 해 줄 테니.",
    },
    [28657] = {
        ["T"] = "감독관 힝크의 의뢰",
        ["O"] =
        "크룬은 당신이 채광 기술을 사용하여 구리 광석 20개를 수집한 다음, 듀로타 오그리마 외곽 비행선 탑의 감독관 힝크에게 전달해 주길 원합니다.",
        ["D"] =
        "수습 광부, 자네 도움이 좀 필요하군.\n\n오그리마 외곽 비행선 탑의 감독관 힝크가 구리 광석을 대량으로 요청했는데, 지금 당장은 여분이 없어. 자네 기술을 발휘해서 Razor Hill을 대신해 이 주문을 좀 처리해 주지 않겠나?",
    },
    [28658] = {
        ["T"] = "하란트 아이언브레이스의 의뢰",
        ["O"] =
        "아착 엠버드림은 당신이 채광 기술을 사용하여 작은 암석 20개를 수집한 다음, 멀고어 블러드후프 마을의 하란트 아이언브레이스에게 전달해 주길 원합니다.",
        ["D"] =
        "가방에 든 그 곡괭이를 봤습니다! 아주 부지런한 분이시군요, 그렇죠? 혹시 당신만의 이름을 걸고 직접 처리할 수 있는 의뢰를 하나 맡아보시겠습니까?\n\n마을의 큰 천막에 있는 하란트가 작은 암석을 대량으로 요청했습니다. 그러니 직접 가서 그를 위해 주문을 처리해 보는 건 어떨까요? 이웃을 돕는 것은 축복입니다... 게다가 당신에겐 훌륭한 연습 기회가 될 테니까요.",
    },
    [28659] = {
        ["T"] = "죽음의경비병 리니아의 의뢰",
        ["O"] =
        "퍼거스 키트사펠은 당신이 채광 기술을 사용하여 구리 주괴 20개를 수집한 다음, 티리스팔 숲 브릴 남쪽에 있는 죽음의경비병 리니아의 야영지로 전달해 주길 원합니다.",
        ["D"] =
        "죽음의경비병 리니아가 눈에 보이는 건 모조리 징발하고 있어요. 이제는 죽음의경비병들이 무슨 꿍꿍이인지 제 구리 주괴까지 달라고 하네요. 그걸 넘겨주면 전 쓸 재료가 하나도 없게 된다고요!\n\n그러니 이렇게 하죠 -- 당신이 가서 구리 주괴 20개를 캐서 그녀에게 전해주고 제가 보냈다고 말해주세요. 그럼 그녀가 내건 쥐꼬리만 한 보상은 당신이 챙기시면 됩니다. 아니, 두둑한 보상이요. 저보다 당신에게 훨씬 더 유용할 겁니다.",
    },
    [28660] = {
        ["T"] = "세바스티안 멜로체의 의뢰",
        ["O"] =
        "요한 폭히트는 당신이 채광 기술을 사용하여 은괴 5개를 수집한 다음, 은빛소나무 숲 공동묘지의 세바스티안 멜로체에게 전달해 주길 원합니다.",
        ["D"] =
        "아, 광부로군. 자네에게 맡길 일이 있어.\n\n저기 있는 세바스티안과 난, 뭐, 사이가 썩 좋지 않아. 지난번 벼룩과 진드기 사건 이후로 이 무덤은 우리 둘이 함께 쓰기엔 너무 좁아졌지. 하지만 죽음의추적자를 지원하려면 어쩔 수 없이 여기 있어야 해.\n\n아무튼, 세바스티안에게 은괴 5개를 가져다주게. 공동묘지에서 녀석이 처리해 줬으면 하는 주문이 있는데, 딱 알맞은 광채가 필요하거든. 은이 제격이지. 내 입을 통하는 것보단 자네가 전해주는 게 녀석도 더 잘 받아들일 거야.",
    },
    [28661] = {
        ["T"] = "트라우그의 의뢰",
        ["O"] =
        "자안 호크윙은 당신이 채광 기술을 사용하여 은 광석 10개를 수집한 다음, 불모의 땅 십자로의 트라우그에게 전달해 주길 원합니다.",
        ["D"] =
        "아, 광부로군. 자네에게 맡길 일이 있어.\n\n가열로에 있는 트라우그에게 맞춤형 작업을 하나 주문하고 싶은데, 은 장식이 필요하거든. 그런데 녀석은 지금 은이 다 떨어져서 언제 다시 들어올지 모른다고 하더군. 자네가 좀 도와줄 수 있겠나?",
    },
    [28662] = {
        ["T"] = "작업반장 스프링소켓의 의뢰",
