        "민병대원 가리엘은 당신이 재봉술을 사용하여 회색 양모 셔츠 4벌을 제작한 다음, 단검 언덕 남서쪽에 있는 그녀의 농장에 있는 대프니 스틸웰에게 전달해 주길 원합니다.",
        ["D"] =
        "민병대의 보급 장교로서, 민병대원뿐만 아니라 서부 몰락지대에 남아있는 민간인들을 보살피는 것도 내 책임이오.\n\n대프니 스틸웰은 광산을 지나 단검 언덕 남서쪽 물가에 혼자 살고 있소. 그곳은 꽤 쌀쌀한데, 마지막으로 지나갈 때 보니 촛불 하나 데우지 못할 얇은 옷을 입고 있더군. 재봉술을 할 줄 안다면, 제대로 된 회색 양모 셔츠 몇 벌을 지어주는 게 큰 도움이 될 거요.",
    },
    [28680] = {
        ["T"] = "살마 살딘의 의뢰",
        ["O"] =
        "민병대원 가리엘은 당신이 재봉술을 사용하여 양모 장화 2켤레를 제작한 다음, 서부 몰락지대 살딘 농장의 살마 살딘에게 전달해 주길 원합니다.",
        ["D"] =
        "서부 몰락지대 사람들은 너무 오랫동안 굶주리고 헐벗어 왔소 -- 하지만 당신이 도울 방법이 있지. 살마 살딘은 동틀 녘부터 해 질 녘까지 농장에서 일하며 항상 민병대를 위한 따뜻한 식사를 준비해 주오. 그런데 그 불쌍한 여인네는 샌들 외엔 맨발이나 다름없다오! 그녀를 대신해 양모 장화 두 켤레를 징발할 권한을 승인받았소. 이제 필요한 건 재봉사뿐인데. 당신이 그 사람이오?",
    },
    [28681] = {
        ["T"] = "발툴 섀도스트라이크의 의뢰",
        ["O"] =
        "샬딘은 당신이 재봉술을 사용하여 진주 장식 망토 1개를 제작한 다음, 어둠해안 알살락스의 탑에 있는 발툴 섀도스트라이크에게 전달해 주길 원합니다.",
        ["D"] =
        "발툴은 수주째 알살락스의 탑에 주둔하며, 바다에서 불어오는 차가운 바람과 안에서 스며 나오는 어둠에 노출되어 있습니다. 망토 하나 가지러 초소를 비울 사람이 아니죠.\n\n그래서 당신 같은 재봉사가 필요한 겁니다. 약간의 따뜻함과 위안을 줄 진주 장식 망토를 만들어 주셨으면 해요. 어둠해안 북부의 그에게 그걸 전해주며, 임무의 부름 속에서도 그가 잊혀지지 않았음을 상기시켜 주세요.",
    },
    [28682] = {
        ["T"] = "고고학자 에버릿의 의뢰",
        ["O"] =
        "샬딘은 당신이 재봉술을 사용하여 두꺼운 양모 장갑 2켤레를 제작한 다음, 어둠해안 렘트래블의 발굴현장에 있는 고고학자 에버릿에게 전달해 주길 원합니다.",
        ["D"] =
        "튼튼하고 두꺼운 장갑을 만들어 달라는 요청을 받았는데, 그걸 부탁한 드워프에게 당장 내어줄 만한 물건이 없군요. 도와줄 수 있다면, 두꺼운 양모 장갑 두어 켤레를 만들어서 렘트래블의 발굴현장에 있는 고고학자 에버릿에게 배달해 주세요.",
    },
    [28683] = {
        ["T"] = "산악경비대 코블플린트의 의뢰",
        ["O"] =
        "알드렌 코든은 당신이 재봉술을 사용하여 양모 자루 2개를 제작한 다음, 모단 호수 왕의 계곡에 있는 산악경비대 코블플린트에게 전달해 주길 원합니다.",
        ["D"] =
        "모단 호수 사람들에게서 밀려든 주문을 처리하려면 숙련된 재봉사의 도움이 절실하네. 관심 있나?\n\n산악경비대 코블플린트는 반짝이는 돌멩이를 보는 눈이 예리하고, 그걸 모조리 주머니에 쑤셔 넣는 성향은 그보다 더 날카롭다네. 문제는, 돌멩이를 너무 많이 주워 담아서 낡은 가방 이음새가 다 터져버렸다는 거지.\n\n그에게 배달할 새 양모 자루 두 개의 주문이 있네. 내가 마지막으로 들은 바로는 그는 왕의 계곡 아래에 주둔하고 있다네.",
    },
    [28684] = {
        ["T"] = "산악경비대 하길의 의뢰",
        ["O"] =
        "알드렌 코든은 당신이 재봉술을 사용하여 손바느질한 리넨 바지 1벌을 제작한 다음, 모단 호수 돌다지 댐의 산악경비대 하길에게 전달해 주길 원합니다.",
        ["D"] =
        "댐에서 들려온 소식에 따르면 산악경비대 하길이 조금 구르다가 지지대를 타고 내려오면서 바지가 쫙 찢어졌다는군. 그 이후로 녀석은 노끈과 억지로 바지를 기워 입고 있다고 해.\n\n이 주문도 같이 맡아주겠다면, 손바느질한 리넨 바지 한 벌을 만들어서 돌다지 댐으로 달려가 주게나.",
    },
    [28685] = {
        ["T"] = "순찰대원 캘러한의 의뢰",
        ["O"] =
        "다니엘 집스티치는 당신이 재봉술을 사용하여 작은 비단 배낭 2개를 제작한 다음, 그늘숲 어두운 강둑에 있는 순찰대원 캘러한에게 전달해 주길 원합니다.",
        ["D"] =
        "언니는 그깟 눈웃음치고 빵 좀 구워주면 캘러한 순찰대원님의 마음을 얻을 수 있다고 생각해요. 제발. 순찰대원님께 필요한 건 저처럼 현실적인 사람이라고요!\n\n우리 선물을 공정하게 평가해 줄 심판이 필요해요. 작은 비단 배낭 두어 개를 만들어서 붉은마루 다리 바로 남쪽, 어두운 강둑에 계신 순찰대원 캘러한님께 전해주시면, 성실한 남자가 뭘 좋아하는지 제가 증명해 보일게요!",
    },
    [28686] = {
        ["T"] = "크직스의 의뢰",
        ["O"] =
        "셰리 집스티치는 당신이 재봉술을 사용하여 감청색 비단 조끼 1벌을 제작한 다음, 그늘숲 어두운 강둑에 있는 크직스에게 전달해 주길 원합니다.",
        ["D"] =
        "그래, 다니엘은 내가 그 지루한 늙은 순찰대원에게 아양이나 떨고 있다고 생각하는 거지? 천만에! 내 연인은 스타일이 있어. 야망도 있고. 인맥도 빵빵하지. 그는... 음, 그는 고블린이야. 하지만 그냥 고블린이 아니라고 -- 안목 있는 상인, 크직스란 말이야.\n\n다니엘이 이걸 시합으로 만들고 싶다면, 기꺼이 응해주지. 크직스를 위해 감청색 비단 조끼를 하나 만들어 줘. 아주 감동해서 레이크샤이어에서 온 그 계집애 따윈 까맣게 잊어버릴 거라 장담해!",
    },
    [28687] = {
        ["T"] = "파수꾼 마이스린의 의뢰",
        ["O"] =
        "애올린은 당신이 재봉술을 사용하여 흰색 양모 드레스 1벌을 제작한 다음, 잿빛 골짜기 숲의 노래에 있는 파수꾼 마이스린에게 전달해 주길 원합니다.",
        ["D"] =
        "재봉사가 정말 절실히 필요했는데, 손가락의 굳은살을 보아하니 바늘을 좀 잡을 줄 아는 분 같군요. 그날이 다가오고 있습니다 -- 마이스린과 셀림 드림송이 숲의 노래 나뭇가지 아래에서 부부의 연을 맺게 될 거예요. 축하연은 조촐하겠지만, 그녀는 여전히 의미가 담긴 수제 옷을 입고 싶어 한답니다.\n\n기술이 있으시다면 흰색 양모 드레스를 한 벌 지어 잿빛 골짜기 반대편에 있는 그녀에게 전해 주세요.",
    },
    [28688] = {
        ["T"] = "그레첸 보겔의 의뢰",
        ["O"] =
        "그레첸 보겔은 당신이 재봉술을 사용하여 수습마술사 로브 2벌을 제작한 다음, 붉은마루 산맥 레이크샤이어의 그레첸 보겔에게 전달해 주길 원합니다.",
        ["D"] =
        "결심했어요! 전 두루마리를 공부하고 싶은데, 고마워할 줄도 모르는 마을 사람들에게 술 따르는 짓은 이제 그만둘 거예요. 아조라의 탑에서 수습생 자리를 제안받았고, 전 그걸 받아들일 작정이에요.\n\n하지만 탑에 가려면 그에 걸맞은 차림새를 갖춰야 해요. 절 위해 수습마술사 로브 두어 벌을 만들어 주신다면 정말 큰 의미가 될 거예요. 그들이 절 단순한 학생이 아니라, 마법사가 될 준비가 된 사람으로 봐줬으면 좋겠거든요.",
    },
    [28689] = {
        ["T"] = "항해사 크롤리의 의뢰",
        ["O"] =
        "항해사 크롤리는 당신이 재봉술을 사용하여 명상의 장갑 2켤레를 제작한 다음, 저습지 메네실 항구의 자신에게 전달해 주길 원합니다.",
        ["D"] =
        "바다는 집중력을 요구하지. 단 한 번의 방심으로 암초에 부딪히거나 더 끔찍한 일을 겪을 수 있거든. 내가 처녀의 미덕호 조타기를 잡을 때면 맑은 정신과 흔들림 없는 두 손이 필요해.\n\n명상의 장갑에 대해 들은 적이 있어: 가볍고 편안하며, 마음을 진정시키는 마법이 부여되어 있다더군. 자네가 만들 수 있다면 두어 켤레 부탁하고 싶네. 화려한 건 필요 없어. 그저 내가 우리를 집으로 이끄는 동안 머릿속을 맴도는 세상의 잡음을 막아줄 수 있으면 그만이야.",
    },
    [28690] = {
        ["T"] = "수사 안톤의 의뢰",
        ["O"] =
        "수사 안톤은 당신이 재봉술을 사용하여 마력의 로브 1벌을 제작한 다음, 잊혀진 땅 나이젤의 야영지에 있는 수사 안톤에게 전달해 주길 원합니다.",
        ["D"] =
        "$C... 자네 재봉사 아닌가? 비밀리에 묻겠네, 친구. 수도원 내에서는 특정 로브의 착용이... 금지되어 있지. 그들은 그걸 \"허영\"이라 부르네. \"너무 세속적\"이라고도 하고. 하지만 이곳, 탁 트인 하늘과 그림자 진 태양 아래서, 나는 원장들이 결코 가르쳐주지 않았던 방식으로 빛을 느끼고 있다네.\n\n자네의 솜씨가 뛰어나다면, 내게 마력의 로브를 하나 지어주게. 자만심 때문이 아니라, 경외와 힘이 반드시 적일 필요는 없다는 것을 증명하기 위해서지. 이 일은 자네와 나, 둘만 알면 되네!",
    },
    [28691] = {
        ["T"] = "헤미트 암스트롱의 의뢰",
        ["O"] =
        "타마라 암스트롱은 당신이 재봉술을 사용하여 긴 비단 망토 1개를 제작한 다음, 언덕마루 구릉지 남녘해안의 헤미트 암스트롱에게 전달해 주길 원합니다.",
        ["D"] =
        "바르톨로가 제게 설인 털로 만든 망토를 팔려고 했어요 -- 믿어지세요? 말도 안 되죠. 헤미트에겐 레슬링 할 때나 입을 무거운 옷이 아니라 가볍고 통풍이 잘되는 옷이 필요하다고요.\n\n바느질을 할 줄 아신다면, 긴 비단 망토를 하나 만들어서 이곳으로 가져와 주세요. 헤미트가 입을 따뜻한 옷이 생기기 전까진 우린 계속 여행할 수 없어요.",
    },
    [28692] = {
        ["T"] = "머더그 드렁크벨리의 의뢰",
        ["O"] =
        "트루크 와일드비어드는 당신이 재봉술을 사용하여 감청색 비단 허리띠 2개를 제작한 다음, 동부 내륙지 맹금의 봉우리의 머더그 드렁크벨리에게 전달해 주길 원합니다.",
        ["D"] =
        "자네 재봉사인가? 신이시여 감사합니다! 자네 도움이 필요해.\n\n보통은 대장 뒤에서 호박씨 까는 짓은 안 하지만... 상황이 심각해. 머더그의 바지가 하루가 다르게 흘러내리고 있어서, 식당에서 한 번만 더 허리를 숙였다간 우리 모두 밥맛 떨어져서 나갈 판이야.\n\n자네 실력이 된다면 그에게 경고의 의미로 감청색 비단 허리띠 두어 개만 만들어 주게. 내가 보냈다고는 하지 말고 -- 그냥 \"눈썰미 좋은 부하 직원의 선물\"이라고만 전해달라고.",
    },
    [28693] = {
        ["T"] = "거만한 의류상의 의뢰",
        ["O"] =
        "거만한 의류상은 당신이 재봉술을 사용하여 룬무늬 두루마리 10개를 제작한 다음, Tanaris 스팀휘들 항구의 자신에게 전달해 주길 원합니다.",
        ["D"] =
        "어머, 재봉사로군요! 당신은 내 마음을 알 거예요, 이런 끔찍한 환경에선 도저히 작업을 할 수가 없답니다. 비단은 유행이 지났고, 양모는 비극 그 자체이며, 마법옷감이요? 웃기지도 마세요.\n\n이 태양빛에 바랜 황무지에서 조금이라도 패셔너블한 옷을 만들어내려면, 제대로 된 옷감이 필요해요. 내게 룬무늬 두루마리 열 개를 가져오세요. 쪼가리도, 실오라기도 아닌, 오염되지 않은 온전한 두루마리여야만 해요. 스타일은 희생을 요구하고, 전 룬무늬 옷감을 요구하니까요.",
    },
    [28694] = {
        ["T"] = "병참장교 룬겔츠의 의뢰",
        ["O"] =
        "감시자 마할 바는 당신이 재봉술을 사용하여 불매듭 장화 2켤레를 제작한 다음, 저주받은 땅 네더가드 요새의 병참장교 룬겔츠에게 전달해 주길 원합니다.",
        ["D"] =
        "이곳의 대지는 불타고 있소. 지옥의 오염은 돌, 모래, 심지어 강철에까지 들러붙지. 룬겔츠는 몇 주도 안 돼 장화를 세 켤레나 버려야 했소 -- 버텨내는 게 없으니까. 듣자 하니 불매듭 옷감은 열기, 불꽃, 그리고 타락에 저항성이 있다고 하더군. 그래서 네더가드는 우리 병참장교를 위해 불매듭 장화 몇 켤레의 값을 지불할 거요.\n\n부디 그 말이 사실이길 바라야겠지, 안 그러면 월말쯤엔 녀석이 맨발로 다녀야 할 테니까.",
    },
    [28695] = {
        ["T"] = "대여사제 맥도넬의 의뢰",
        ["O"] =
        "대여사제 맥도넬은 당신이 재봉술을 사용하여 그림자매듭 어깨보호구 1개를 제작한 다음, 서부 역병지대 서리바람 야영지의 자신에게 전달해 주길 원합니다.",
        ["D"] =
        "서리바람 야영지에 주둔한 이후, 전 어둠이 어떻게 움직이고 속삭이는지 직접 두 눈으로 보았습니다. 물론 파괴적이기도 하죠... 하지만 보호할 수도 있어요. 게다가 어둠은 빛이 결코 하지 않는 방식으로 우리의 말에 귀를 기울인답니다.\n\n전 어둠을 더 깊이 이해해야만 해요. 그림자매듭 어깨보호구를 만들 수 있다면, 서리바람 야영지에 있는 제게 가져다주세요. 전 이것들이 단순한 의복 이상의 역할을 할 거라 믿습니다 -- 오랫동안 금지되었던 힘을 여는 열쇠가 될지도 모르죠.",
    },
    [28696] = {
        ["T"] = "빌헬미나 워블스미스의 의뢰",
        ["O"] =
        "경비대장 아실라는 당신이 재봉술을 사용하여 수수한 검은색 드레스 2벌을 제작한 다음, 아즈샤라 워블 할로우의 빌헬미나 워블스미스에게 전달해 주길 원합니다.",
        ["D"] =
        "재봉사 맞지? 잘됐군.\n\n워블 할로우의 노움들은 이곳에 추락하면서 전 재산을 잃었어. 우린 녀석들에게 음식을 조달해 주었고 녀석들 스스로 피난처도 짓고 있지만, 입을 옷이라곤 지금 걸치고 있는 게 전부야.\n\n수수한 검은색 드레스 두 벌을 지을 수 있다면, 빌헬미나 워블스미스에게 가져다주게. 작은 온정이지만, 지금 그들에겐 절실히 필요한 거니까.",
    },
    [28697] = {
        ["T"] = "레즐락의 의뢰",
        ["O"] =
        "스낭은 당신이 재봉술을 사용하여 리넨 가방 2개를 제작한 다음, 듀로타 칼끝바람 협곡의 레즐락에게 전달해 주길 원합니다.",
        ["D"] =
        "레즐락은 칼끝바람 협곡 북쪽에 야영지를 차려놓고 빈주머니와 쓰레기 같은 아이디어만으로 사업을 꾸려나가려 하고 있어. 뭐 당연하게도, 가방이 필요하다고 하더군.\n\n난 정상적인 주문 처리하느라 바빠서 도와줄 틈이 없지만, 자네가 연습 삼아 이 일을 맡아준다면 그 녀석이 후하게 쳐주겠다고 약속했어.",
    },
    [28698] = {
        ["T"] = "타이타시의 의뢰",
        ["O"] =
        "스낭은 당신이 재봉술을 사용하여 수수한 드레스 1벌을 제작한 다음, 듀로타 센진 마을의 타이타시에게 전달해 주길 원합니다.",
        ["D"] =
        "너무 요란 떨진 말고... 내가 널 대신해서 하나 만들어 줬으면 하는 게 있어.\n\n센진 마을에 있는 타이타시는 자기만 빼고 항상 다른 사람들을 돕느라 바빠. 그녀에게 예쁜 옷이 생기면 기뻐하지 않을까 생각했지. 하지만 내가 직접 만들어 주면 좀 이상할 것 같아서 말이야. 그러니까... 네가 대신 좀 해줄래?",
    },
    [28699] = {
        ["T"] = "마그린 리버메인의 의뢰",
        ["O"] =
        "반은 당신이 재봉술을 사용하여 파란색 리넨 셔츠 2벌을 제작한 다음, 멀고어 블러드후프 마을의 마그린 리버메인에게 전달해 주길 원합니다.",
        ["D"] =
        "블러드후프 마을의 마그린은 몇 계절째 똑같은 낡은 연보라색 조끼만 입고 있는데, 이젠 셔츠보다 기워낸 천이 더 많을 지경이야. 그는 새것을 달라고 부탁하지도 않아 -- \"아직 입을 만하다\"고 하더군.\n\n선행도 베풀고 그를 돕고 싶지만, 주문과 훈련 때문에 눈코 뜰 새 없이 바빠서 말이야. 시간 좀 있으면 파란색 리넨 셔츠 두 벌만 지어서 배달해 줄 수 있겠어? 정성이 담긴 선물을 받으면 그도 고마워할 거야.",
    },
    [28700] = {
        ["T"] = "포위 미스트러너의 의뢰",
        ["O"] =
        "반은 당신이 재봉술을 사용하여 질긴 리넨 장갑 1켤레를 제작한 다음, 멀고어 썬더 블러프 정기의 봉우리에 있는 포위 미스트러너에게 전달해 주길 원합니다.",
        ["D"] =
        "포위 미스트러너는 정기의 봉우리에서 섬세한 조각, 깃털 부적, 심지어 금이 간 룬석 같은 고대 유물들을 다루는 지식인들을 돕고 있어. 그녀는 맨발굽으로 유물들을 만지지 않도록 장갑을 한 켤레 부탁했지.\n\n네가 이 주문을 맡아 제때 배달해 주면 좋겠어. 포위가 그러는데 우리는 과거를 존중하는 마음으로 대해야 하고, 그건 얼룩을 남기지 않는 것에서부터 시작한대.",
    },
    [28701] = {
        ["T"] = "메릴 웬딜의 의뢰",
        ["O"] =
        "콘스턴스 브리스부아즈는 당신이 재봉술을 사용하여 흰색 리넨 로브 3벌을 제작한 다음, 티리스팔 숲 브릴 공동묘지의 메릴 웬딜에게 전달해 주길 원합니다.",
        ["D"] =
        "메릴 웬딜은 우리 성기사들을 대신해 스컬지석을 다루고 있는데, 그 돌의 오물이 그녀의 로브를 형체를 알아볼 수 없을 정도로 더럽히고 있소. 형체를 알아볼 수 없다는 게 말이 되나?\n\n아무튼 그녀에게 새 흰색 리넨 로브가 필요한데 내가 통 시간을 낼 수가 없군. 연습도 할 겸, 자네가 만들어 보는 건 어떻소?",
    },
    [28702] = {
        ["T"] = "재스퍼 그린의 의뢰",
        ["O"] =
        "콘스턴스 브리스부아즈는 당신이 재봉술을 사용하여 수수한 리넨 장화 1켤레를 제작한 다음, 티리스팔 숲 솔리덴 농장의 재스퍼 그린에게 전달해 주길 원합니다.",
        ["D"] =
        "재스퍼 그린은 지식인 수습생인데, 북쪽 해안 광산을 조사하라는 임무를 받았지. 한 가지 문제가 있다면 -- 그에겐 장화가 없소. 아니, 아예 신발이 한 짝도 없지.\n\n재스퍼가 다른 이유로 지식인 훈련을 통과하지 못할 순 있어도, 옷을 제대로 못 차려입어서 낙제하는 꼴은 보고 싶지 않소. 난 그를 위해 무언가 만들 시간이 전혀 없는데, 당신은 그리 바빠 보이지 않는군. 당신이 한 번 해보는 게 어떻소?",
    },
    [28703] = {
        ["T"] = "킬리안 사나타의 의뢰",
        ["O"] =
        "안드리아 보인톤은 당신이 재봉술을 사용하여 회색 양모 셔츠 4벌을 제작한 다음, 은빛소나무 숲 북부 해안가의 킬리안 사나타에게 전달해 주길 원합니다.",
        ["D"] =
        "킬리안은 몇 주째 북부 해안가에서 낚시를 하고 있는데, 돌아올 때마다 뼛속까지 흠뻑 젖어 있어요. 그가 인정하진 않겠지만, 그 낡은 셔츠는 옷감보다 구멍이 더 많을 지경이죠.\n\n회색 양모 셔츠를 몇 벌 지을 수 있다면 그에게 가져다주세요. 제가 직접 하고 싶지만 그가 제 호의를 달가워할 것 같진 않거든요. 긴 이야기가 있답니다.",
    },
    [28704] = {
        ["T"] = "릴리의 의뢰",
        ["O"] =
        "안드리아 보인톤은 당신이 재봉술을 사용하여 양모 장화 2켤레를 제작한 다음, 은빛소나무 숲 공동묘지 남쪽에 있는 릴리의 야영지로 전달해 주길 원합니다.",
        ["D"] =
        "릴리는 포세이큰치고도 좀 별난 애예요. 마법부여에 취미가 있긴 한데 신발도 없이 숲속을 뛰어다니거든요.\n\n저에게 많은 재주가 있긴 하지만 신발을 만드는 건 그중 하나가 아니에요. 만약 당신에게 그럴 재주가 있다면, 양모 장화 한 켤레를 그녀에게 선물해 보는 건 어떨까요. 우리 포세이큰은 서로를 돌봐야 하잖아요.",
    },
    [28705] = {
        ["T"] = "선장 탈로타스 브라이트선의 의뢰",
        ["O"] =
        "할리자 화이트스트라이더는 당신이 재봉술을 사용하여 진주 장식 망토 1개를 제작한 다음, 은빛소나무 숲 톱니항의 선장 탈로타스 브라이트선에게 전달해 주길 원합니다.",
        ["D"] =
        "호드가 십자로를 세운 이후로, 한 달 만에 처리할 수 없을 만큼 많은 주문이 쏟아져 들어오고 있어. 자네가 재봉 기술을 가지고 있다면 밀린 주문을 처리하는 데 큰 도움이 될 텐데.\n\n선장 탈로타스 브라이트선이 톱니항에 정박해서 새 진주 장식 망토를 요청했어. 실력을 뽐내기 딱 좋은 간단한 주문일 거야, 안 그래 $N?",
    },
    [28706] = {
        ["T"] = "웨니키 볼트버킷의 의뢰",
        ["O"] =
        "할리자 화이트스트라이더는 당신이 재봉술을 사용하여 두꺼운 양모 장갑 2켤레를 제작한 다음, 불모의 땅 북쪽 황금길에 있는 웨니키 볼트버킷의 집으로 전달해 주길 원합니다.",
        ["D"] =
        "튼튼하고 두꺼운 장갑을 만들어 달라는 요청을 받았는데, 그걸 부탁한 고블린에게 당장 내어줄 만한 물건이 없군. 도와줄 수 있다면 두꺼운 양모 장갑 두어 켤레를 만들어서 북쪽 황금길에 있는 웨니키 볼트버킷의 집으로 배달해 주게.",
    },
    [28707] = {
        ["T"] = "테터낵 스틸포지의 의뢰",
        ["O"] =
        "마하니는 당신이 재봉술을 사용하여 양모 자루 2개를 제작한 다음, 불모의 땅 타우라조 야영지의 테터낵 스틸포지에게 전달해 주길 원합니다.",
        ["D"] =
        "불모의 땅 사람들에게서 밀려든 주문을 처리하려면 숙련된 재봉사의 도움이 절실하네. 관심 있나?\n\n테터낵 스틸포지는 기이한 광석을 알아보는 예리한 눈과, 그걸 모조리 주머니에 쑤셔 넣으려는 더 예리한 본능을 가졌지. 문제는 너무 많이 주워 담아서 낡은 가방 이음새가 다 터져버렸다는 거야.\n\n그에게 새 양모 자루 두 개를 만들어 주라는 주문이 있네. 길 건너편 대장간에서 그를 찾을 수 있을 거야.",
    },
    [28708] = {
        ["T"] = "브린의 의뢰",
        ["O"] =
        "마하니는 당신이 재봉술을 사용하여 손바느질한 리넨 바지 1벌을 제작한 다음, 남부 불모의 땅 검은가시 능선의 브린에게 전달해 주길 원합니다.",
        ["D"] =
        "내 친구 브린은 검은가시 능선 아래에 사는데, 근처 퀼보아 야영지 주변에 자라난 거대한 가시덤불에 바지가 찢어졌다는 전갈을 보내왔소. 날 돕는 셈 치고 연습 삼아 이 주문을 처리해 보는 것도 괜찮을 텐데, 어떻소?",
    },
    [28709] = {
        ["T"] = "세나니 썬더하트의 의뢰",
        ["O"] =
        "세나니 썬더하트는 당신이 재봉술을 사용하여 작은 비단 배낭 2개를 제작한 다음, 잿빛 골짜기 토막나무 주둔지의 자신에게 전달해 주길 원합니다.",
        ["D"] =
        "잿빛 골짜기의 사냥꾼들이 전리품을 가져오는데, 박제될 때까지 보관해 둘 공간이 바닥나고 있어요. 작은 비단 배낭을 몇 개 만들어 주신다면 이 소중한 전리품들을 더 조심스럽게 옮길 수 있을 거예요. 사냥꾼의 긍지를 거친 삼베 자루에 쑤셔 넣을 순 없으니까요.",
    },
    [28710] = {
        ["T"] = "죽음의추적자 레시의 의뢰",
        ["O"] =
        "말렌 스웨인은 당신이 재봉술을 사용하여 감청색 비단 조끼 1벌을 제작한 다음, 언덕마루 구릉지 남부경비 탑의 죽음의추적자 레시에게 전달해 주길 원합니다.",
        ["D"] =
        "죽음의추적자 레시는 아주 꺼려지는 임무를 맡고 있다네. 홀로 남부경비 탑에 주둔하고 있지. 누군가 그녀에게 보급품을 전해준 게 언제인지 기억조차 나지 않는군.\n\n난 이제 바늘귀에 실을 꿰기엔 너무 늙었어, $N. 혹시 자네가 이 늙은이 대신 레시에게 감청색 비단 조끼를 지어줄 수 있겠나. 그녀 덕에 삼촌이 자랑스러워한다고 전해주게나.",
    },
    [28711] = {
        ["T"] = "티라에스 모닝셰이드의 의뢰",
        ["O"] =
        "티라에스 모닝셰이드는 당신이 재봉술을 사용하여 흰색 양모 드레스 1벌을 제작한 다음, 버섯구름 봉우리 신기루 경주장의 자신에게 전달해 주길 원합니다.",
        ["D"] =
        "재봉사가 정말 절실히 필요했는데, 손가락의 굳은살을 보아하니 바늘을 좀 잡을 줄 아는 분 같군요.\n\n여긴 해가 지면 아주 춥답니다. 모래는 돌처럼 열을 머금지 못하고, 제 평상복은 거센 바람보다는 경주장에 더 어울리게 맞춰져 있거든요. 제게 따뜻한 양모 드레스를 한 벌 지어 주시겠어요? 돈은 지불할게요! 약속해요!",
    },
    [28712] = {
        ["T"] = "학자 틸스의 의뢰",
        ["O"] =
        "학자 틸스는 당신이 재봉술을 사용하여 수습마술사 로브 2벌을 제작한 다음, 버섯구름 봉우리 신기루 경주장의 자신에게 전달해 주길 원합니다.",
        ["D"] =
        "당신이 재봉사라는 소리를 엿듣게 되었소. 내 짐이 신기루 경주장으로 바로 순간이동 되어야 했는데, 지금쯤 차원 사이에 끼어 있거나 아니면 거대한 바다 밑바닥에 가라앉아 있을 것 같소.\n\n어쨌든, 수습마술사 로브 한 벌이 필요하오. 누군가 날 싸구려 마술이나 부리는 마법사로 착각하기 전에 부디 이 주문을 서둘러 주길 바라오!",
    },
    [28713] = {
        ["T"] = "선견자 목타르딘의 의뢰",
        ["O"] =
        "라그란은 당신이 재봉술을 사용하여 명상의 장갑 2켤레를 제작한 다음, 가시덤불 골짜기 그롬골 주둔지의 선견자 목타르딘에게 전달해 주길 원합니다.",
        ["D"] =
        "선견자 목타르딘 님은 우릴 인도하기 위해 깊은 무아지경에 빠지곤 하시지. 그분은 밀림, 바다, 때로는 영혼 세계의 장막 너머까지 들여다보신다네. 하지만 최근 들어 그 부담이 점점 커지고 있어. 그분의 환영은 희미해지고, 두 손은 떨리고 있지.\n\n명상의 장갑을 만들 수 있다면, 그롬골 주둔지에 있는 그분께 가져다드리게. 그게 그분의 집중력을 붙잡아주고... 보이지 않는 곳으로 뻗는 손길을 안정시키는 데 도움이 될지도 모르니까.",
    },
    [28714] = {
        ["T"] = "펠제룰의 의뢰",
        ["O"] =
        "펠제룰은 당신이 재봉술을 사용하여 심홍색 비단 바지 4벌을 제작한 다음, 슬픔의 늪 스토나드의 자신에게 전달해 주길 원합니다.",
        ["D"] =
        "$C... 당신 재봉사지? 당신만 믿고 조용히 묻겠소. 내가 밖에서, 음... 볼일을 보고 있었는데, 늪에서 악어 한 마리가 갑자기 튀어나오지 뭐요. 내가... 옷을 벗은 상태라, 그놈 입에는 내 바지만 한가득 들어갔지. 그래서 바지가 몇 벌 더 필요하게 되었소.\n\n수고비는 치르겠소. 걱정 마시오, 당분간은 로브로 가려지니까.",
    },
    [28715] = {
        ["T"] = "어둠마법사 비비안 라그레이브의 의뢰",
        ["O"] =
        "어둠마법사 비비안 라그레이브는 당신이 재봉술을 사용하여 긴 비단 망토 1개를 제작한 다음, 황야의 땅 카르가스의 자신에게 전달해 주길 원합니다.",
        ["D"] =
        "여기 이 녀석은 아무 짝에도 쓸모가 없어!\n\n<비비안이 앙상한 엄지손가락으로 스란다를 가리킵니다.>\n\n긴 망토가 필요하다고 했잖아. 숄도, 덮개도 아닌. 제대로 된. 긴. 망토 말이야.\n\n네가 완전한 구제 불능이 아니라면 긴 비단 망토를 가져와. 사막의 매서운 바람을 막아줄 만큼 길고, 지금 내가 처한 이 끔찍한 상황을 잠시나마 잊게 해줄 만큼 우아한 놈으로.",
    },
    [28716] = {
        ["T"] = "라드의 의뢰",
        ["O"] =
        "주술사 쏜터스크는 당신이 재봉술을 사용하여 감청색 비단 허리띠 2개를 제작한 다음, 동부 내륙지 깨진엄니 마을의 라드에게 전달해 주길 원합니다.",
        ["D"] =
        "너 재봉사야? 로아께 감사해야겠군! 네 도움이 필요해.\n\n보통은 다른 이의 일에 내 엄니를 들이밀진 않지만... 지금은 아주 끔찍한 상황이야. 라드의 바지가 하루가 다르게 점점 흘러내리고 있어서, 저 녀석이 허리를 한 번만 더 굽혔다간 내 손으로 폭동을 진압해야 할지도 몰라.\n\n네가 감청색 비단 허리띠를 몇 개 만들어서 그에게 따끔한 충고를 대신 전해주면 좋겠군.... 내가 보냈다는 말은 하지 말고 -- 그냥 \"걱정스러운 여관 손님\"의 선물이라고 전해줘.",
    },
    [28717] = {
        ["T"] = "자카라의 의뢰",
        ["O"] =
        "핍조트는 당신이 재봉술을 사용하여 마력의 로브 1벌을 제작한 다음, 잊혀진 땅 그늘수렵 마을의 자카라에게 전달해 주길 원합니다.",
        ["D"] =
        "$C... 당신 재봉사지? 드디어 내 주인님이 마땅히 입으셔야 할 옷을 지어줄 사람이 나타났군! 맞아, 자카라님께는 새 로브가 필요해. 그냥 로브 말고, 마력의 로브 말이야! 감당할 수 있겠어, $R? 당장 시작하라고!\n\n아, 걱정 마, 돈은 두둑이 쳐줄 테니까.",
    },
    [28718] = {
        ["T"] = "거만한 의류상의 의뢰",
        ["O"] =
        "거만한 의류상은 당신이 재봉술을 사용하여 룬무늬 두루마리 10개를 제작한 다음, Tanaris 스팀휘들 항구의 자신에게 전달해 주길 원합니다.",
        ["D"] =
        "어머, 재봉사로군요! 당신은 내 마음을 알 거예요, 이런 끔찍한 환경에선 도저히 작업을 할 수가 없답니다. 비단은 유행이 지났고, 양모는 비극 그 자체이며, 마법옷감이요? 웃기지도 마세요.\n\n이 태양빛에 바랜 황무지에서 조금이라도 패셔너블한 옷을 만들어내려면, 제대로 된 옷감이 필요해요. 내게 룬무늬 두루마리 열 개를 가져오세요. 쪼가리도, 실오라기도 아닌, 오염되지 않은 온전한 두루마리여야만 해요. 스타일은 희생을 요구하고, 전 룬무늬 옷감을 요구하니까요.",
    },
    [28719] = {
        ["T"] = "오리칸도의 의뢰",
        ["O"] =
        "오리칸도는 당신이 재봉술을 사용하여 불매듭 장화 2켤레를 제작한 다음, 페랄라스 모자케 야영지의 오리칸도에게 전달해 주길 원합니다.",
        ["D"] =
        "난 숲 트롤이 아니야, $C. 이 땅은 너무 습해. 나무들도 너무 빽빽하고 키도 너무 크지. 여기서 떠날 생각이지만, 내 목적지에 맞게 준비를 좀 해야 해: 바로 불타는 평원이지.\n\n자네 실력이 된다면 불매듭 장화가 두어 켤레 필요해. 평원의 그 끔찍한 열기도 견뎌낼 수 있게 말이야.",
    },
    [28720] = {
        ["T"] = "펠제룰의 의뢰",
        ["O"] =
        "펠제룰은 당신이 재봉술을 사용하여 그림자매듭 어깨보호구 1개를 제작한 다음, 슬픔의 늪 스토나드의 자신에게 전달해 주길 원합니다.",
        ["D"] =
        "내 바지를 아주 훌륭하게 만들어 주었으니, 이번에도 자네에게 맡길 일이 있소! 이번엔 그림자매듭 세트에 어울리는 새 어깨보호구가 필요하오. 날 위해 만들어 줄 수 있겠소?",
    },
    [28721] = {
        ["T"] = "제디가의 의뢰",
        ["O"] =
        "제디가는 당신이 재봉술을 사용하여 수수한 검은색 드레스 2벌을 제작한 다음, 아즈샤라 발로르모크의 제디가에게 전달해 주길 원합니다.",
        ["D"] =
        "재봉사 맞지? 잘됐네.\n\n벨그롬이 날 여기로 쫓아냈을 때 짐을 챙길 시간조차 없었어. 내 목이 어깨에 제대로 붙어있길 원했다면 말이야. 하지만 여자라면 매일 똑같은 제복만 입는 것에 질리기 마련이지. 이곳 일을 마침내 끝내고 오그리마로 돌아가 시원한 에일 한잔 들이켤 때 입을 수수한 검은색 드레스 두어 벌이 필요해. 도와줄 수 있어?",
    },
    [28722] = {
        ["T"] = "검은창 부족",
        ["O"] = "듀로타 검은창 섬에 있는 조즈자즈와 대화해야 합니다.",
        ["D"] =
        "아, $N. 마침내 나를 찾아왔군. 부족을 위해 봉사할 준비가 되었나?\n\n우리는 오랫동안 정착할 고향을 찾았고, 이제 드디어 찾은 것 같군. 볼진과 호드의 동맹이 우리가 오랫동안 원했던 안정을 가져다주었지.\n\n그렇다고 해결해야 할 골칫거리가 없다는 뜻은 아니야. 네가 자원해서 나서 주겠나? 너처럼 풋내기에게 딱 맞는 일이 있지.",
    },
    [28723] = {
        ["T"] = "도둑 게",
        ["O"] = "자수정 게 10마리를 처치한 후 검은창 섬 다리 건너편에 있는 다즈티로에게 보고해야 합니다.",
        ["D"] =
        "우린 검은창 섬에 꽤 안락한 집을 마련했지만, 이 게 녀석들을 쫓아내지 않으면 오래가지 못할 거야. 녀석들이 우리 식량 창고를 털어가고 있거든!\n\n그러니 네 첫 임무는 아주 쉬워 -- 그 게 녀석들을 싹 쓸어버려. 집게발에 물리지 않게 조심하고!\n\n다 끝나면 다리 건너편에 있는 다즈티로에게 보고해. 그녀가 네게 할 일을 더 줄 테니.",
    },
    [28725] = {
        ["T"] = "G.E.A.R.로 향하라",
        ["O"] = "던 모로 G.E.A.R.에 있는 땜장이 대장 휘슬스크류를 위해 굶주린 트로그 10마리를 처치해야 합니다.",
        ["D"] =
        "아, 격리에서 풀려난 또 다른 건강한 노움이군요! 지하철 충돌 사고로 얼마나 끔찍하셨을지 알지만, 지금은 과거에 얽매여 있을 시간이 없습니다. 우리는 지금 아주 위급한 상황에 처해 있고, 당신의 도움이 절실합니다!\n\n노움 비상 집결 경로 -- 줄여서 G.E.A.R. -- 가 지하에서 기어 올라오는 트로그들의 위협을 받고 있어요. 그 오랜 시간 지하에 갇혀 계셨던 것 치고는 상태가 아주 좋아 보이시는데요. 우릴 도와주실 수 있나요?",
    },
    [28726] = {
        ["T"] = "동정할 여지는 없다",
        ["O"] =
        "던 모로 G.E.A.R.에 있는 땜장이 대장 휘슬스크류를 위해 방사능 수액괴물 8마리를 처치하고 감염된 노움 4명의 고통을 끝내줘야 합니다.",
        ["D"] =
        "세상에, $N. 방금 그 트로그들을 상대하는 솜씨가 마치 숙련된 $C 같았어요. 계속 저희를 돕고 싶으시다면, 반드시 해야 할 일이 하나 더 있습니다.\n\n놈리건의 대재앙에서 기어 올라온 건 트로그들만이 아닙니다. 방사능 수액괴물들이 생존자 중 일부를 기이한 질병에 감염시켰고, 그들은 정신을 잃고 광기에 사로잡혔어요! 아직 치료법은 없고, 우리가 손을 쓰지 않으면 더 많은 노움이 감염되고 말 겁니다. 제발, 부디 해야 할 일을 해주세요: 수액괴물들을 파괴하고, 감염된 노움들의 고통을 끝내주세요.\n\nG.E.A.R. 전면의 동굴을 정처 없이 헤매고 있는 녀석들을 찾으실 수 있을 겁니다.",
    },
    [28727] = {
        ["T"] = "상형 문자로 된 쪽지",
        ["O"] = "상형 문자로 된 쪽지를 읽은 후 던 모로 G.E.A.R. 내부에 있는 마릭 너리빗과 대화해야 합니다.",
        ["D"] =
        "당신이 저를 돕고 있는 동안, 이 쪽지를 당신에게 전해달라며 누군가 제게 주더군요. 시간 나실 때 한 번 읽어보세요. 아마 마법사 전문가 마릭이 보낸 것 같습니다. 시간이 나시면 G.E.A.R. 내부에서 그녀를 찾아보세요.",
    },
    [28728] = {
        ["T"] = "상형 문자로 된 서판",
        ["O"] = "상형 문자로 된 서판을 읽은 후 검은창 섬 마을에 있는 마이아와 대화해야 합니다.",
        ["D"] =
        "네가 날 돕는 동안, 이걸 네게 전해달라며 누군가 주고 가더군. 나중에 시간 날 때 한 번 읽어봐. 마법사 전문가, 마이아가 보낸 것 같아. 내 뒤쪽 언덕 위 마을에서 그녀를 찾아보라고.",
    },
    [28729] = {
        ["T"] = "성스러운 쪽지",
        ["O"] = "성스러운 쪽지를 읽고 던 모로 G.E.A.R.에 있는 누르세이 기어스피너와 대화해야 합니다.",
        ["D"] =
        "당신이 저를 돕고 있는 동안, 이 쪽지를 당신에게 전해달라며 누군가 제게 주더군요. 시간 나실 때 한 번 읽어보세요. 아마 사제 전문가 누르세이 기어스피너가 보낸 것 같습니다. 시간이 나시면 G.E.A.R. 내부에서 그를 찾아보세요.",
    },
    [28730] = {
        ["T"] = "성스러운 서판",
        ["O"] = "성스러운 서판을 읽은 후 검은창 섬 마을에 있는 켄자이와 대화해야 합니다.",
        ["D"] =
        "네가 날 돕는 동안, 이걸 네게 전해달라며 누군가 주고 가더군. 나중에 시간 날 때 한 번 읽어봐. 사제 전문가, 켄자이가 보낸 것 같아. 내 뒤쪽 언덕 위 마을에서 그를 찾아보라고.",
    },
    [28731] = {
        ["T"] = "암호화된 쪽지",
        ["O"] = "암호화된 쪽지를 읽은 후 던 모로 G.E.A.R.에 있는 윈들 퓨즈스프링과 대화해야 합니다.",
        ["D"] =
        "당신이 저를 돕고 있는 동안, 이 쪽지를 당신에게 전해달라며 누군가 제게 주더군요. 시간 나실 때 한 번 읽어보세요. 아마 도적 전문가 윈들 퓨즈스프링이 보낸 것 같습니다. 시간이 나시면 G.E.A.R. 내부에서 그를 찾아보세요.",
