    [28732] = {
        ["T"] = "암호화된 서판",
        ["O"] = "암호화된 서판을 읽은 후 검은창 섬 마을에 있는 타르카이와 대화해야 합니다.",
        ["D"] =
        "네가 날 돕는 동안, 이걸 네게 전해달라며 누군가 주고 가더군. 나중에 시간 날 때 한 번 읽어봐. 도적 전문가, 타르카이가 보낸 것 같아. 내 뒤쪽 언덕 위 마을에서 그를 찾아보라고.",
    },
    [28733] = {
        ["T"] = "대지의 부름",
        ["O"] = "앙금의 유리병 2개를 듀로타 검은창 섬에 있는 카나가 어스콜러에게 가져가야 합니다.",
        ["D"] =
        "때가 왔네, 젊은 $C여. 자네는 강해졌고 자네의 영혼은 대지처럼 인내하고 있어. 주술사의 길을 걷는다는 것은 자네 스스로를 증명하기 전부터 이미 지혜를 갖추었음을 의미하지.\n\n대지의 정령이 자네의 운명을 인도할 것이며, 자네가 준비되었다면 자네의 일부가 될 걸세. 하지만 그전에 자네는 대지 그 자체와 마주해야만 해. 자네가 준비되었다면 오직 주술사만이 볼 수 있는 것을 보게 될 거야.\n\n남쪽 동굴에 있는 살아있는 진흙을 찾아 앙금의 유리병 두 개를 구해 오게. 그런 다음 내게 돌아오면, 자네의 미래에 대해 좀 더 깊은 이야기를 나누지.",
    },
    [28734] = {
        ["T"] = "대지의 부름",
        ["O"] = "검은창 섬에서 솟아오르는 대지의 성소를 찾고, 도착하면 대지의 정기를 마셔야 합니다.",
        ["D"] =
        "정기란 우리의 영혼을 정령과 결속시키기 위해 만들어진 음료라네. 마법이 깃든 이 물약은 강인한 의지를 지닌 자만이 다른 누구도 볼 수 없는 정령의 모습을 보게 해 주지. 자네의 영혼은 정기가 상징하는 원소와 연결될 것이며, 이 제조법은 오직 선택받은 소수의 주술사만이 알고 있다네.\n\n정기는 항상 신성한 장소에서만 마셔야 하며, 다른 곳에선 절대 안 된다는 걸 명심하게.\n\n이곳 북쪽에 있는 솟아오르는 대지의 성소를 찾게 -- 서쪽 언덕 뒤편의 숨겨진 길 끝에서 찾을 수 있을 거야. 그곳에서 정기를 마시면... 글쎄, 직접 보게 될 걸세.",
    },
    [28735] = {
        ["T"] = "대지의 부름",
        ["O"] = "천연 석영을 듀로타 검은창 섬 마을에 있는 카나가 어스콜러에게 가져가야 합니다.",
        ["D"] =
        "내가 주는 이 천연 석영을 받아 카나가 어스콜러에게 우리가 만났다는 증표로 가져가라. 그가 너를 위해 토템을 만들어 줄 것이고, 이 작은 돌멩이가 그 중심이 될 것이다. 아무리 작아 보여도 크기가 다가 아니며, 아주 작은 것조차 다른 많은 것들보다 오래 살아남을 수 있다는 걸 곧 깨닫게 될 것이다.\n\n인내심을 가져라, $N. 굳건히 버텨라. 그리고 지혜를 구하라. 이것이 대지가 네게 요구하는 것이다. 결국, 넌 대지와 하나가 될 것이다--대지가 널 존중하듯, 너도 대지를 존중하라.",
    },
    [28736] = {
        ["T"] = "룬이 새겨진 서판",
        ["O"] = "룬이 새겨진 서판을 읽은 후 검은창 섬 마을에 있는 이시요와 대화해야 합니다.",
        ["D"] =
        "네가 날 돕는 동안, 이걸 네게 전해달라며 누군가 주고 가더군. 나중에 시간 날 때 한 번 읽어봐. 주술사 전문가, 이시요가 보낸 것 같아. 내 뒤쪽 언덕 위 마을에서 그를 찾아보라고.",
    },
    [28737] = {
        ["T"] = "오래된 쪽지",
        ["O"] = "오래된 쪽지를 읽고 던 모로 G.E.A.R. 내부에 있는 알라마 그림과 대화해야 합니다.",
        ["D"] =
        "당신이 저를 돕고 있는 동안, 이 쪽지를 당신에게 전해달라며 누군가 제게 주더군요. 시간 나실 때 한 번 읽어보세요. 아마 흑마법사 전문가 알라마 그림이 보낸 것 같습니다. 시간이 나시면 G.E.A.R. 내부에서 그를 찾아보세요... 하지만 제가 당신을 지켜보고 있다는 걸 명심하세요. 당신이 행하는 흑마법은 이곳에서 그리 환영받지 못하니까요.",
    },
    [28738] = {
        ["T"] = "시작",
        ["O"] = "깃털 부적 3개를 던 모로 G.E.A.R. 내부에 있는 알라마 그림에게 가져가야 합니다.",
        ["D"] =
        "자네를 가르쳐 주겠노라 약속했으니 이제 시작할 때가 되었군. 자네가 빨리 성공할수록 -- 아니면 죽든가 -- 나도 내 연구로 더 빨리 돌아갈 수 있을 테니까.\n\n자네가 배울 소환 주문 중 가장 기초적인 건 임프 소환이야. 이 지식을 자네에게 온전히 맡기기 전에, 마법을 통제할 필수적인 능력이 있다는 걸 먼저 증명해야 해.\n\n북쪽 서리갈기 동굴에 거주하는 서리갈기트롤 수습생들에게서 깃털 부적 3개를 가져오게.",
    },
    [28739] = {
        ["T"] = "아즈샤라 우상",
        ["O"] = "아즈샤라 우상 3개를 듀로타 검은창 섬 마을에 있는 우와에게 가져가야 합니다.",
        ["D"] =
        "어둠의 길은 호드 내에서도 불신의 대상이지. 우리 흑마법사들은 그저... 묵인되고 있을 뿐이야. 아주 간신히.\n\n아마추어가 부두 주술을 다루는 건 아주 위험한 짓이야. 난 네 길을 간섭할 생각은 없지만, 작은 쓰레기들을 치우는 데 네 도움을 좀 받아야겠어. 물론, 네 일에 대한 대가로 힘을 주지.\n\n남쪽 나가 동굴에서 아즈샤라 우상 세 개를 가져와. 그들의 수행사제들이 가지고 다니는데, 내 연구에 아주 유용하게 쓰일 거야.",
    },
    [28740] = {
        ["T"] = "오래된 서판",
        ["O"] = "오래된 서판을 읽은 후 검은창 섬 마을에 있는 우와와 대화해야 합니다.",
        ["D"] =
        "네가 날 돕는 동안, 이걸 네게 전해달라며 누군가 주고 가더군. 나중에 시간 날 때 한 번 읽어봐. 흑마법사 전문가, 우와가 보낸 것 같아. 내 뒤쪽 언덕 위 마을에서 그녀를 찾아보라고.",
    },
    [28741] = {
        ["T"] = "간결한 쪽지",
        ["O"] = "간결한 쪽지를 읽고 던 모로 G.E.A.R.에 있는 파즈바르 자이로노브와 대화해야 합니다.",
        ["D"] =
        "당신이 저를 돕고 있는 동안, 이 쪽지를 당신에게 전해달라며 누군가 제게 주더군요. 시간 나실 때 한 번 읽어보세요. 아마 전사 전문가 파즈바르 자이로노브가 보낸 것 같습니다. 시간이 나시면 G.E.A.R. 내부에서 그를 찾아보세요.",
    },
    [28742] = {
        ["T"] = "간결한 서판",
        ["O"] = "간결한 서판을 읽은 후 검은창 섬 마을에 있는 타르세르와 대화해야 합니다.",
        ["D"] =
        "네가 날 돕는 동안, 이걸 네게 전해달라며 누군가 주고 가더군. 나중에 시간 날 때 한 번 읽어봐. 전사 전문가, 타르세르가 보낸 것 같아. 내 뒤쪽 언덕 위 마을에서 그녀를 찾아보라고.",
    },
    [28743] = {
        ["T"] = "장인의 도구",
        ["O"] =
        "눈마루 골짜기 남서쪽 야영지에서 앤빌마의 그룬델 하킨에게 가져다줄 그룬델의 팔보호구, 그룬델의 흉갑, 그룬델의 망치를 수집해야 합니다.",
        ["D"] =
        "예전엔 눈마루 골짜기 남서쪽에 있는 아주 좋은 야영지에서 물건을 만들곤 했지. 트롤들이 근처에 나타나기 전까진 말이야. 정령들이 날뛰기 시작했을 때, 일거리와 도구들을 모두 내버려 두고 앤빌마로 냅다 도망쳐버렸지. 지금쯤이면 여기저기 흩어져 있을 텐데.\n\n난 모험가가 아니지만, 자넨 꽤 용감해 보이는군. 내 물건들을 찾아서 이곳으로 가져다줄 수 있겠나?",
    },
    [28744] = {
        ["T"] = "요동치는 정령",
        ["O"] = "그렐린 화이트비어드는 당신이 눈마루 골짜기에서 서리 정령 14마리를 처치해 주길 원합니다.",
        ["D"] =
        "내 동생 세니르와 나는 서리갈기트롤의 위협을 조사하기 위해 던 모로의 각기 다른 지역으로 파견되었네. 원로원은 트로그들 문제로 골머리를 앓고 있어서 더 이상 다른 골칫거리에 신경 쓸 여력이 없거든.\n\n내가 본 바로는 이 눈마루 골짜기엔 트롤이 없어 -- 그저 날뛰는 정령 무리가 있을 뿐이지. 그래도 우린 이 문제를 해결해야 해. 굳이 군대까지 동원할 필요는 없을 것 같고. 힘 좋은 몇 명만 있으면 충분할 테니까.\n\n혹시 이 일을 좀 돕지 않겠나? 자네의 노고에 합당한 보상을 지급할 권한이 내게 있다네.",
    },
    [28745] = {
        ["T"] = "서리술사",
        ["O"] = "그렐린 화이트비어드는 당신이 남서쪽 동굴을 탐험하여 서리 정령들을 자극하는 무언가를 찾아내 처치하길 원합니다.",
        ["D"] =
        "생각하면 할수록, 누군가 고의로 이 정령들을 선동하고 있다는 확신이 들어. 어쩌면 이게 바로 내 동생이 찾아다니던 트롤의 위협 아닐까?\n\n정령들을 훌륭하게 상대해 줬으니, 저기 저 동굴로 들어가서 그들을 지휘하는 우두머리를 찾아주게. 만약 그런 자를 발견한다면, 어떻게 해야 할지 잘 알겠지.",
    },
    [28746] = {
        ["T"] = "피난민의 난관",
        ["O"] = "던 모로 G.E.A.R.에 있는 펠릭스 윈들볼트에게 펠릭스의 궤짝, 펠릭스의 상자, 펠릭스의 나사통을 가져가야 합니다.",
        ["D"] =
        "놈리건에서 트로그들을 몰아냈지만, 일이 끔찍하게 꼬여버렸죠! 이제 우리의 고향은 방사능으로 완전히 뒤덮였고, 우리 노움들은 던 모로 전역으로 뿔뿔이 흩어졌습니다.\n\n방사능을 피해 허겁지겁 도망치느라 제 개인 소지품과 도구들을 몽땅 잃어버리고 말았어요. 트로그 놈들이 훔쳐 간 게 분명해요. 내 상자, 내 궤짝, 그리고 내 나사통까지 몽땅! 놈들은 서리갈기 봉우리의 찬 바람 부는 절벽, G.E.A.R. 외곽에 있는 자기들 야영지로 그걸 가져갔어요.\n\n전 모험가가 아니랍니다 -- 혹시 제 물건들을 찾아서 이곳으로 가져다주실 수 있나요, 제발?",
    },
    [28747] = {
        ["T"] = "비상 보급품",
        ["O"] = "비상 보급품 가방을 던 모로 서리갈기 봉우리에 있는 안톤 스파크샤인에게 전달해야 합니다.",
        ["D"] =
        "부탁 하나만 들어주시겠어요? 당신이 땜장이 대장 휘슬스크류를 돕는 걸 봤는데, 아주 믿음직해 보이더군요. 안톤 스파크샤인에게 이 비상 보급품을 전해줄 사람이 필요합니다.\n\nG.E.A.R. 밖, 서리갈기 봉우리를 가로지르는 야영지에서 그를 찾으실 수 있을 거예요. 어때요? 도와주실 수 있나요?",
    },
    [28748] = {
        ["T"] = "비상 보급품",
        ["O"] = "비상 담요를 던 모로 서리갈기 봉우리에 있는 디즈리 윌리카드에게 전달해야 합니다.",
        ["D"] =
        "이 비상 담요는 디즈리 윌리카드에게 더 유용할 거예요. 당신이 그에게 가져다주는 건 어떨까요?\n\n제가 마지막으로 알기론, 그는 남동쪽 봉우리로 올라가는 길목 근처에 주둔하고 있었어요.",
    },
    [28749] = {
        ["T"] = "서리갈기 동굴",
        ["O"] = "던 모로 서리갈기 봉우리에 있는 라일라 스프로켓스파크를 위해 서리갈기트롤 새끼 14마리를 처치해야 합니다.",
        ["D"] =
        "안톤 스파크샤인이 트로그들 때문에 걱정하는 건 당연하지만... 지평선 너머엔 훨씬 더 오래되고 위험한 적이 도사리고 있는 것 같아 두렵습니다.\n\n서리갈기트롤들은 오랫동안 재미 삼아 노움들을 사냥해 왔죠. 놈리건이 세워졌을 때 그 트롤들은 자취를 감췄지만, 도시가 무너지자 다시 북쪽 동굴, 그들의 옛 보금자리로 돌아왔어요.\n\n우리 비상구 근처에 놈들이 발을 들이게 내버려 둘 순 없어요. 혹시 이 위협을 처리하는 걸 도와주시겠어요? 놈리건을 위해 싸울 의향이 있는 분이라면 누구에게든 보상을 지급할 권한이 제게 있답니다.",
    },
    [28750] = {
        ["T"] = "도난당한 안경",
        ["O"] = "서리갈기 봉우리에 있는 라일라 스프로켓스파크는 당신이 서리갈기 동굴로 들어가 프라지르를 처치하고 자신의 광학 확대기를 되찾아오길 원합니다.",
        ["D"] =
        "내 안경! 분명 트롤 녀석들이 북쪽 동굴 -- 서리갈기 동굴로 가져갔을 거예요. 놈들은 자기네 족장인 프라지르에게 바칠 공물로 우리 물건들을 훔치고 있거든요.\n\n이 트롤들을 상대로 솜씨를 좀 보여주셨으니, 제 광학 확대기도 좀 되찾아 주시겠어요?",
    },
    [28751] = {
        ["T"] = "서리갈기 보고서",
        ["O"] = "라일라 스프로켓스파크의 보고서를 던 모로 눈마루 통로로 가는 길목에 있는 디즈리 윌리카드에게 가져가야 합니다.",
        ["D"] =
        "서리갈기트롤을 상대로 거둔 이런 중대한 승리는 마땅히 관계 당국에 보고되어야 합니다... 다만 그게 누구이고 어디에 있는지를 모를 뿐이죠.\n\n이건 다 당신의 공로를 기리는 일이니, 이 보고서는 당신이 직접 전달해야 해요. 디즈리 윌리카드와 대화해 보세요. 그라면 이 보고서를 누구에게 가져가야 할지 알 거예요. 여기서 남동쪽으로 눈마루 통로로 향하는 길목에 있는 야영지에서 그를 찾을 수 있습니다.",
    },
    [28752] = {
        ["T"] = "서리갈기 보고서",
        ["O"] = "라일라 스프로켓스파크의 보고서를 던 모로 카라노스에 있는 세니르 화이트비어드에게 가져가야 합니다.",
        ["D"] =
        "여기 서리갈기 봉우리 꼭대기에 있는 짐승들은 아주 사납습니다. 눈마루 통로를 따라 내려가다 보면 십중팔구 녀석들의 공격을 받게 될 거예요. 하지만 서리갈기 동굴의 트롤들을 상대하셨을 정도면 꽤 강하신 것 같군요.\n\n어디로 가야 하냐고요, 음, 동굴을 통과해 카라노스로 가는 길을 따라가세요. 마을에 가면 세니르 화이트비어드를 찾을 수 있을 겁니다. 그가 이 지역의 책임자이니 이 보고서를 어떻게 처리해야 할지 알 거예요.",
    },
    [28753] = {
        ["T"] = "얼어붙은 비단",
        ["O"] = "디즈리 윌리카드는 당신이 서리 거미줄 4개를 수집하여 던 모로 카라노스의 거트 레더선더에게 전달해 주길 원합니다.",
        ["D"] =
        "눈마루 통로를 지나가실 거라면, 가는 길에 동전도 좀 버는 게 좋지 않겠어요?\n\n카라노스에 있는 제 친구는 온갖 짐승의 부위를 다루는 전문가인데, 그중에서도 거미줄 다루는 걸 가장 좋아한답니다. 산을 내려가다 보면 서리 거미를 많이 보실 수 있을 거예요. 녀석들의 거미줄을 모아가면, 거트가 값을 두둑하게 쳐줄 겁니다.",
    },
    [28754] = {
        ["T"] = "티디 스크랩볼트에게 보내는 편지",
        ["O"] = "라즐 스크랩볼트의 편지를 카라노스 썬더브루 양조장에 있는 티디 스크랩볼트에게 전달해야 합니다.",
        ["D"] =
        "G.E.A.R.를 떠나시나요? 혹시 그쪽으로 가신다면 제 형제인 카라노스에게 이 편지를 전해주시겠어요? 눈마루 통로를 무사히 빠져나갔다면, 썬더브루 양조장에서 푹 쉬고 싶어지실 거예요.\n\n도착하면 티디 스크랩볼트를 찾아주세요. 그리고, 정말 감사합니다!",
    },
    [28755] = {
        ["T"] = "거미 전차 부품",
        ["O"] = "눈마루 통로에서 거미 전차 부품 화물을 수집하여 던 모로의 지르피즈 크랭크블래스트에게 가져가야 합니다.",
        ["D"] =
        "$C! 잠시만 제 말 좀 들어보세요. 카라노스로 가느라 바쁘시겠지만, 도움이 필요합니다.\n\n제가 놈리건에서 간신히 빼내 온 이 거미 전차의 교체 부품 화물을 기다리고 있는데, 배달부가 아직 도착하지 않았어요. 서리 거미들의 습격을 받은 건 아닌지 걱정됩니다.\n\n혹시 눈마루 통로에서 그 부품들의 흔적을 찾아봐 주실 수 있나요? 찾으신다면 잠시만 짬을 내어 제게 가져다주시면 정말 감사하겠습니다.",
    },
    [28756] = {
        ["T"] = "트로그 도시",
        ["O"] =
        "던 모로 서리갈기 봉우리에 있는 안톤 스파크샤인을 위해 앙상한 바위턱 트로그 6마리와 잔인한 바위턱 트로그 6마리를 처치해야 합니다.",
        ["D"] =
        "G.E.A.R. 당국은 놈리건 하층에 격리된 시민들을 계속 대피시키는 동안 우리의 비상 집결 경로를 안전하게 지키기 위해 최선을 다하고 있지만, 문제는 주변에 트로그들이 너무 많다는 겁니다! 마치 자기들 안방인 양 봉우리를 어슬렁거리는 꼴 좀 보세요! 안쪽뿐만 아니라 이 밖에도 트로그 세상이나 다름없습니다!\n\n놈들을 쓰러뜨린다고 잃어버린 이들이 돌아오진 않겠지만, 장기적으로 도시를 되찾기 위한 우리의 노력은 훨씬 수월해질 겁니다. 도와주시겠습니까?",
    },
    [28757] = {
        ["T"] = "바나나 대박",
        ["O"] = "다즈티로는 듀로타 검은창 섬에 있는 아지사리를 위해 당신이 햇살에 익은 바나나 10개를 수집하길 원합니다.",
        ["D"] =
        "네가 게 녀석들이 식량 창고를 공격하는 걸 막아주긴 했지만, 녀석들이 망쳐놓은 식량을 다시 채워 넣으려면 여전히 네 도움이 필요해.\n\n섬 밖으로 나가 야자수 주변을 샅샅이 뒤져서 잘 익은 맛있는 바나나를 찾아봐. 널리고 널렸을 거야. 다 모으면 마을의 아지사리에게 가져가. 녀석이 창고에 있는 맛있는 음식들과 교환해 줄 거야.",
    },
    [28758] = {
        ["T"] = "조개껍질 수집",
        ["O"] = "아지사리를 위해 검은창 섬 주변의 갯벌과 얕은 물에서 열대 바다 조개껍질 8개를 수집해야 합니다.",
        ["D"] =
        "지금까지 우릴 잘 도와줬으니 아지사리에게 네가 관심 있어 할 만한 일이 하나 더 있어.\n\n이곳의 조개껍질은 정말 아름다워. 훌륭한 소형 도구와 장신구의 재료가 되지. 좀 더 있으면 좋겠어. 검은창 섬 주변 얕은 물가에서 모을 수 있을 거야.",
    },
    [28759] = {
        ["T"] = "살쾡이의 발톱",
        ["O"] = "새끼 호랑이에게서 날카로운 호랑이 발톱 10개를 수집하여 듀로타 검은창 섬에 있는 사냥꾼 본주루에게 가져가야 합니다.",
        ["D"] =
        "우리 검은창 부족은 나가들을 몰아내고 이 섬을 차지했지만, 아직 위험 요소는 남아있어. 호랑이 수가 역대 최고로 늘어났고 녀석들은 마을 밖으로 나가는 모든 이들을 위협하고 있지.\n\n검은창을 위해 싸우겠다고? 호랑이들을 해치우고 그 증거로 발톱을 가져와!",
    },
    [28760] = {
        ["T"] = "저주받은 트롤",
        ["O"] = "듀로타 검은창 섬에 있는 의술사 리리아를 위해 저주받은 트롤 8마리를 혼내줘야 합니다.",
        ["D"] =
        "풋내기 $C인가? 네가 이 일에 딱 맞을 것 같군.\n\n최근에 우리 부족 몇몇이 남쪽의 오래된 폐허를 들락거리기 시작했어. 녀석들은 뭔가 이상한 행동을 하는데 이곳 장로들도 그 이유를 모르고 있지.\n\n거기 가서 확인 좀 해봐. 녀석들이 입을 열게 만들려면 먼저 정신이 번쩍 들게 혼쭐을 내줘야 할지도 몰라!",
    },
    [28761] = {
        ["T"] = "저주의 근원",
        ["O"] = "의술사 리리아를 위해 검은창 섬 어딘가에서 저주의 근원을 찾아야 합니다.",
        ["D"] =
        "그러니까 저주받은 트롤들이 두루마리를 읽고 부두 주술에 걸렸단 말이지? 그걸 찾아서 이 저주를 끝내야만 해.\n\n넌 지금까지 아주 믿을 만한 $C였어. 섬을 샅샅이 뒤져서 그 두루마리를 찾아내!\n\n짐작건대 아마 섬 반대편의 폐허 근처에 있을 거야. 선착장이 있는 남쪽 해안 끝까지 가봐. 거기가 바로 저주받은 트롤들이 자주 모이는 곳이니까.",
    },
    [28762] = {
        ["T"] = "장로 가드린에게 보고",
        ["O"] = "듀로타 센진 마을에 있는 장로 가드린과 대화해야 합니다.",
        ["D"] =
        "이 두루마리의 출처에 대해 짐작 가는 바가 있지만, 센진 마을에 계신 장로 가드린님께서 직접 살펴보셔야 할 것 같아.\n\n이 두루마리를 그분께 가져가. 센진 마을은 남서쪽 바다 건너편에 있어. 해안을 따라 선착장과 모래톱을 따라가다 보면 찾을 수 있을 거야.",
    },
    [28763] = {
        ["T"] = "Razor Hill에 보고",
        ["O"] = "쿨티라스인들이 라즈피리의 오탁을 공격했다는 사실을 Razor Hill의 책임자에게 보고해야 합니다.",
        ["D"] =
        "센진 마을의 축제에 참석하느라 밤에 집을 비웠는데, 오늘 아침에 돌아와 보니 내 오두막이 이렇게... 바싹 타버렸어!\n\n난 누가 이런 짓을 했는지 알아, $N. 물 건너 타이라가드 요새에 있는 쿨티라스 인간 녀석들이라고.\n\n호드는 우릴 인간들로부터 보호해 줘야 할 의무가 있잖아! Razor Hill에 가서 누군가에게 이 개자식들을 밟아줄 조치를 취해야 한다고 전해.\n\n거기 가겠다고 타이라가드를 가로지르는 멍청한 짓은 하지 마. 그냥 해안을 따라 센진 마을로 내려간 다음 내륙 쪽 길을 따라 Razor Hill로 가라고. 마차를 타면 더 빨리 갈 수 있을 거야.",
    },
    [28764] = {
        ["T"] = "죽음의 로아",
        ["O"] =
        "동굴 안과 샘 근처에 있는 브원삼디의 서판을 읽은 후 듀로타 검은창 섬의 마카스갈에게 돌아가야 합니다.",
        ["D"] =
        "네가 어렸을 때 로아에 대해 들어봤을 거라고 확신해. 이 강력한 영혼들은 우리가 구루바시 제국에서 떨어져 나온 이후로 검은창 부족을 무시해 왔지.\n\n하지만 브원삼디는 아니야.\n\n입 밖으로 꺼낼 수 없는 것을 공유하기 위해 장로들이 마을 밖 동굴과 마을 남쪽 샘에 서판을 세워두셨어. 네가 세상으로 나가기 전에 브원삼디와 맺은 우리의 계약을 반드시 숙지하도록 해 -- 안 그러면 나중에 그를 만났을 때 그의 속임수에 넘어갈지도 모르니까!",
    },
    [28765] = {
        ["T"] = "파도의 위협",
        ["O"] = "듀로타 검은창 섬에 있는 사냥꾼 본주루를 위해 멀록 바다전사 12마리를 처치해야 합니다.",
        ["D"] =
        "적들에 대해 말하자면... 나가들은 패배했을지 몰라도 그들의 하수인들은 여전히 남아 있어. 섬 남쪽 해안의 멀록들을 말하는 거야. 그쪽 갯벌로 내려가서 일이 더 커지기 전에 이 문제를 해결해. 이 짐승들은 단순한 짐승보다 훨씬 위험하거든. 또 볼 수 있길 바란다....",
    },
    [28766] = {
        ["T"] = "이상한 조개껍질 주머니",
        ["O"] = "이상한 조개껍질 주머니를 듀로타 검은창 섬에 있는 사냥꾼 본주루에게 가져가야 합니다.",
        ["D"] =
        "이 멀록은 이상한 조개껍질이 가득 든 주머니를 지니고 있었습니다. 이 조개껍질의 용도는 잘 모르겠지만, 사냥꾼 본주루라면 흥미로워할지도 모릅니다.",
    },
    [28767] = {
        ["T"] = "나가의 위협",
        ["O"] = "파도여왕 리아나를 처치해야 합니다. 그녀의 삼지창을 듀로타 검은창 섬에 있는 사냥꾼 본주루에게 가져가야 합니다.",
        ["D"] =
        "이건 단순한 조개껍질이 아니야, $N. 나가들이 수중 동맹들에게 지불할 때 쓰는 주화지. 이 멀록들이 제 발로 여기까지 왔다고 보기엔 너무 조직적이다 싶었어. 분명 배후에 어떤 나가 우두머리가 있을 거야.\n\n이 나가를 처치해야만 해, 그렇지 않으면 녀석들이 무리를 이끌고 섬을 되찾으러 다시 올지도 몰라. 남동쪽 갯벌 근처의 동굴을 수색해 봐. 그 우두머리가 숨어있기에 가장 그럴듯한 장소니까.",
    },
    [28768] = {
        ["T"] = "글이 새겨진 양피지",
        ["O"] = "글이 새겨진 서판을 읽은 후 검은창 섬 마을에 있는 젠샨과 대화해야 합니다.",
        ["D"] =
        "네가 날 돕는 동안, 이걸 네게 전해달라며 누군가 주고 가더군. 나중에 시간 날 때 한 번 읽어봐. 사냥꾼 전문가, 젠샨이 보낸 것 같아. 내 뒤쪽 언덕 위 마을에서 그녀를 찾아보라고.",
    },
    [28769] = {
        ["T"] = "글이 새겨진 서판",
        ["O"] = "글이 새겨진 서판을 읽은 후 검은창 섬 마을에 있는 젠샨과 대화해야 합니다.",
        ["D"] =
        "네가 날 돕는 동안, 이걸 네게 전해달라며 누군가 주고 가더군. 나중에 시간 날 때 한 번 읽어봐. 사냥꾼 전문가, 젠샨이 보낸 것 같아. 내 뒤쪽 언덕 위 마을에서 그녀를 찾아보라고.",
    },
    [30000] = {
        ["T"] = "검은무쇠 곡괭이",
        ["O"] = "상자를 찾아 산의 피를 건네고 잠금을 해제하세요, 무엇이 나올지 누가 알겠습니까?.",
        ["D"] =
        "<구입한 곡괭이를 자세히 살펴보니 자루 안에 빈 공간이 있는 것이 보입니다. 곡괭이 끝을 비틀자 빈 공간에서 종이 조각 하나가 떨어집니다.>\n\n\"자랑스럽고 숙련된 광부가 이 편지가 들어 있는 공간을 발견하기를 바라는 마음으로 이 편지를 남긴다, 아니면 네가 너무 세게 쳐서 자루를 부러뜨렸을지도 모르지! 이 곡괭이는 튼튼하고 믿음직하지만, 네가 아직 보지 못한 가장 단단한 광물에는 역부족일 거다. 그래서 난 전설적인 곡괭이 제작법을 연구하는 데 수년을 바쳤다. 완전히 완성하진 못했고, 이젠 내가 직접 만들기에 너무 늙어버렸지만, 이 지식을 아무렇게나 넘겨주고 싶진 않구나.\"\n\n\"산의 피를 찾아라. 검은무쇠 광맥을 지치지 않고 파내다 보면 찾을 수 있을 거다. 정 힘들면 남한테 돈 주고 사도 무덤에 있는 내가 탓하진 않으마. 그 피를 들고 내가 불의 군주를 소환하기 전에 살았던 옛집에 있는 궤짝으로 가라. 이 말이 너무 막연하게 들린다면, 넌 검은무쇠 일족이 아닐 테지!\"",
    },
