    [31003] = {
        ["T"] = "영혼의 안식",
        ["O"] = "요리 전문가에게 조언을 구하십시오. 어쩌면 가젯잔의 더지 퀵클리브가 도울 수 있을지도 모릅니다.",
        ["D"] = "",
    },
    [31004] = {
        ["T"] = "영혼의 안식",
        ["O"] =
        "가젯잔의 더지 퀵클리브는 당신이 꿀 버터 빵의 재료를 모두 구할 수 있을지 반신반의하고 있습니다.\n\n-아제로스의 수많은 상인이 갓 구운 빵을 판매하므로, 구입하는 것이 가장 쉬운 방법입니다.\n\n-꿀은 운고로 분화구의 몇몇 말벌에게서 얻을 수 있습니다.\n\n-버터는 언덕마루 구릉지의 타렌 제분소 또는 남녘해안에서 구매할 수 있습니다.",
