    },
    [31005] = {
        ["T"] = "영혼의 안식",
        ["O"] = "더지와 대화한 후 그가 꿀 버터 빵 요리를 마칠 때까지 기다려야 합니다.",
        ["D"] = "재료는 다 모였으니 어떻게 하는 건지 한 번 알아볼까, $N. 잘 보고 배우라고!",
    },
    [31006] = {
        ["T"] = "대족장과의 접견",
        ["O"] = "오그리마에 있는 스랄과 여명의 설원에서 들려오는 불길한 소문에 대해 대화해야 합니다.",
        ["D"] =
        "반갑네, 모험가여. 최근 대족장님을 접견할 기회가 있었네. 군주 발타라크와 맞서 싸운 자네의 무용담이 대족장님께 깊은 인상을 남기신 모양이야.\n\n지금 호드에 자네 같은 실력자가 필요하다는 말씀을 들었네. 여명의 설원에서 기이한 일들이 벌어지고 있다는군. 어서 가보게. 스랄님과 대화해 보게나, 대족장님을 기다리게 해선 안 되니.",
    },
    [31007] = {
        ["T"] = "국왕과의 접견",
        ["O"] = "아이언포지에 있는 마그니 브론즈비어드와 여명의 설원에서 들려오는 불길한 소문에 대해 대화해야 합니다.",
        ["D"] = "",
    },
    [31008] = {
        ["T"] = "불길한 소문",
        ["O"] = "대족장님의 명령을 경청하십시오.",
        ["D"] =
        "대족장의 부름에 응하겠는가? 앉아서 들어보게.\n\n<경비병이 두툼한 보고서 묶음을 가져옵니다.>\n\n영혼들이 동요하고 있네, $N. 얼어붙은 땅 여명의 설원에서 무언가 끔찍한 일이 벌어지고 있어. 호드 마법사들이 그곳 동부 지역에서 거대한 비전 에너지가 동요하는 것을 감지했고, 검은바위 산을 벗어난 적이 없는 첨탑돌일족 오우거들이 목격되었다는 정찰병들의 보고도 들어왔네.\n\n사방에서 이런 소란이 일어나는 걸 보니 분명 심상치 않은 일인 것 같군. 자네가 이 일을 조사해 줄 수 있겠나, 모험가여?",
    },
    [31009] = {
        ["T"] = "불길한 소문",
        ["O"] = "국왕의 요청을 경청하십시오.",
        ["D"] = "",
    },
    [31010] = {
        ["T"] = "여명의 설원으로 향하는 여정",
        ["O"] = "여명의 설원 동부 지역에서 호드 정찰병의 보고를 조사해야 합니다.",
        ["D"] =
        "<정찰병의 보고서 묶음을 건네받았습니다. 훑어보니, 동부 여명의 설원 지역에서 오우거의 활동과 비전 이상 현상이 목격된 것 같습니다. 좁은 산길과 거대한 용의 뼈에 대한 언급이 눈에 띕니다. 그곳으로 향해 무엇이 있는지 직접 확인하는 것이 좋겠습니다.>",
    },
    [31011] = {
        ["T"] = "여명의 설원으로 향하는 여정",
        ["O"] = "여명의 설원 동부 지역에서 얼라이언스 정찰병의 보고를 조사해야 합니다.",
        ["D"] = "",
    },
    [31012] = {
        ["T"] = "당면한 과제",
        ["O"] =
        "푸른 안식처에 있는 펄볼그가 첨탑돌일족 투사와 첨탑돌일족 흑마술사를 처리해 이 지역의 위협을 조금이나마 줄여 달라고 요청했습니다.",
        ["D"] =
        "<펄볼그가 수정을 뚫어지게 응시합니다.>\n\n보이나? 오우거 놈들이 엉망으로 만들었어, 마법을 엉망으로 만들었다고, 아주 위험해. 저 멍청한 짓이 우릴 다 죽이기 전에 막아야 해. 마법사들을 보호하는 투사들을 쓰러뜨린 다음, 흑마술사들을 처리해. 그런 다음 이야기하자.",
    },
    [31013] = {
        ["T"] = "잠시의 휴식",
        ["O"] = "푸른 안식처의 펄볼그와 대화하여 그의 이야기를 들어야 합니다.",
        ["D"] =
        "물어봐, 그럼 대답할 테니.\n\n<그의 시선이 다시 재빠르게 수정으로 향합니다. 당신도 그것을 바라봅니다. 수정에서 끊임없이 증폭되어 뿜어져 나오는 불안감이 느껴지며, 마치 주변의 모든 에너지를 빨아들이는 것 같습니다.>",
    },
    [31014] = {
        ["T"] = "불길한 조언",
        ["O"] =
        "푸른용군단의 조언을 구하십시오. 마즈소릴 동굴은 칼림도어에 있는 그들의 보금자리입니다. 수호자들은 침입자를 보면 즉시 공격하겠지만, 은둔 중인 수호대모라면 기꺼이 우릴 돕지 않을까요?",
        ["D"] =
        "난 저 용이 푸른용군단 소속이라는 걸 알고 있어. 뼈에 손을 대보는 것만으로도 그 사실을 확신할 수 있지. 난 마법을 모르고, 당신도 이 오염을 억누를 만한 힘은 없는 것 같군, $c.\n\n<탈루크가 잠시 생각에 잠깁니다.>\n\n여명의 설원에는 푸른용군단의 둥지가 있어. 녀석들은 보는 즉시 공격하려 들겠지만, 어쩌면, 아주 어쩌면 우리가 대화할 수 있는 누군가가 있지 않을까? 우두머리라든가, 수호자라든가? 확실하진 않지만 시도해 볼 가치는 있어.",
    },
    [31015] = {
        ["T"] = "필연적인 어둠의 대가",
        ["O"] =
        "마즈소릴의 헬레는 당신이 강령술 학교의 벡투스를 처치하고 그의 홀을 되찾아 오길 원합니다.",
        ["D"] =
        "내가 어떻게 이걸 놓쳤을까? 어떻게 느끼지 못했지? 내 혈육이, 나와... 수정에 이렇게 가까이 잠들어 있었는데?\n\n네게 줄 대답은 없다, $r. 그리고 난 마즈소릴에서의 내 임무를 버릴 수 없어. 하지만 무언가 조치를 취해야 해.\n\n<그녀가 다시 안식처 쪽을 깊고 길게 바라봅니다.>\n\n너도 느껴지지 않나? 커지고 있어, 포식하고 있다고. 저 오우거 바보 녀석들이 무슨 짓을 저지른 건지... 내게 찾아온 건 현명한 선택이었다. 이 마법의 근원을 통제하지 못한다면 무슨 일이 벌어질지 상상조차 할 수 없어.\n\n우리에게 필요한 건 해답이야, 그것도 아주 빨리. 서부 역병지대에 있는 강령술 학교로 가라. 그곳의 끔찍한 강령술사가 역병 걸린 용을 만드는 실험을 하고 있지. 녀석에게 가장 잔혹한 죽음을 안겨주고 녀석의 홀을 가져와.",
    },
    [31016] = {
        ["T"] = "빛의 임무",
        ["O"] =
        "우리의 임무는 강력한 성기사를 찾는 것입니다. 희망의 빛 예배당이 가장 좋은 선택이 될 것입니다. 아마도 은빛 여명회의 지도자인 맥스웰 티로서스 경에게 도움을 요청할 수 있지 않을까요?",
        ["D"] =
        "확실히 해두지 - 나는 네가 이 더러운 마법으로 유해를 모독하는 걸 용납하지 않겠다. 우리가 하려는 짓은 이미 충분히 혐오스러운 짓이니까.\n\n강력한 성기사의 도움을 구해라. 영혼에 가해질 피해를 줄이기 위해, 그들이 홀을 정화하고 신성한 마법을 불어넣도록 설득해.\n\n모든 준비가 끝난 후에야 푸른 안식처로 돌아가 그것을 사용할 수 있다, 타우렌. 알겠나? 제발 다른 방법이 있었더라면 좋았을 것을... 용서해 다오, 형제여.",
    },
    [31017] = {
        ["T"] = "의식의 필요조건",
        ["O"] =
        "희망의 빛 예배당의 맥스웰 티로서스 경은 홀을 정화하기 위해 몇 가지 재료가 필요합니다:\n- 스트라솔름의 성수 한 병.\n- 노련한 연금술사나 광부에게서 얻은 아케이나이트 주괴 한 개.\n- 재료 상인에게서 구매할 수 있는 신성한 양초 세 개.\n- 마법부여사에게서 얻은 영혼 가루 세 뭉치.\n- 역시 재료 상인에게서 구매할 수 있는 신앙의 징표 한 개.",
        ["D"] =
        "당신의 위기가 짐작 가는군, $r. 강령술사의 마법으로 용의 영혼을 더럽히는 것은 아주 사악한 행위요. 내가 도울 수 있는 한 최선을 다해 돕겠소.\n\n<맥스웰이 잠시 의식의 계획을 짭니다.>\n\n몇 가지 재료와 준비물이 필요하오:\n\n먼저 홀을 안치할 기반이 필요하오. 아케이나이트가 가장 적합한 재료이니 주괴가 최소 하나는 필요할 거요. 의식의 원 바깥쪽에는 영혼 가루 세 뭉치 위에 신성한 양초 세 개를 올려둬야 하오. 가장 중요한 건 마법 증폭기 역할을 할 신앙의 징표와 홀을 씻어낼 스트라솔름의 성수 한 병이오.\n\n모든 걸 구한 뒤 내게 돌아오시오. 우리 예배당에 재료 상인이 없다는 게 참 안타깝군... 여기서 기다리겠소.",
    },
    [31018] = {
        ["T"] = "신성한 정신집중",
        ["O"] = "정화 의식이 끝날 때까지 기다리십시오.",
        ["D"] = "",
    },
    [31019] = {
        ["T"] = "귀환길",
        ["O"] = "홀이 정화되었으니 여명의 설원으로 돌아갈 수 있습니다. 푸른 안식처에 있는 탈루크가 우릴 기다리고 있을 것입니다.",
        ["D"] =
        "<맥스웰 티로서스 경이 가쁜 숨을 몰아쉽니다.>\n\n예상했던 것보다 의식의 소모가 훨씬 크군.\n\n최선을 다했소... 하지만 당신의 계획이 성공할지는 장담할 수 없소. 푸른 안식처에 있는 용의 유해로 돌아가시오. 이제 그 해골에 홀을 집중시키면 쓰러진 용의 영혼이 끌려 나와 서로 대화를 나눌 수 있을 거요.\n\n평안하시길, $c, 그리고 행운을 비오. 모든 일이 끝나면 그 홀을 파괴하시오. 이 마법은 존재해선 안 되는 것이오.",
    },
    [31020] = {
        ["T"] = "비전의 역병",
        ["O"] = "푸른 안식처에 있는 해골에 홀을 사용하고 용의 영혼과 대화해야 합니다.",
        ["D"] =
        "맥스웰 경은 용의 해골에 홀의 마법을 집중시켜야 한다고 했습니다. 계획대로라면 쓰러진 푸른용의 영혼을 끌어낼 수 있을 겁니다. 부디 그 영혼이 우리가 그토록 간절히 바라는 해답과 해결책을 쥐고 있기를.",
    },
    [31021] = {
        ["T"] = "비전의 역병",
        ["O"] = "푸른 안식처에 있는 벨리고스와 대화하십시오. 그의 이야기를 듣고 다음 단계를 논의하십시오.",
        ["D"] =
        "<영혼이 서서히 안정되며 의식을 차리는 것 같습니다.>\n\n나는 벨리고스, 비전의 대가이자 마법의 수호자다.\n\n<벨리고스가 수정에 시선을 집중합니다.>\n\n왜 이 저주받은 물건이 활성화된 거지? 대체 어떤 어리석은 자가 내 주문을 풀었단 말인가?\n\n말해봐라, $r, 네가 이 임박한 재앙의 원흉이냐?",
    },
    [31022] = {
        ["T"] = "비전의 역병",
        ["O"] =
        "벨리고스는 우리에게 푸른 안식처 동굴 깊숙한 곳으로 쳐들어가 수정을 강화하고 있는 오우거들을 처치해 달라고 부탁했습니다.",
        ["D"] =
        "그 검은바위의 멍청이들이 내 보주를 찾아 다시 합쳐놓았거나... 아니면 어떤 식으로든 그 마법을 모방한 게 틀림없어. 수정을 흡수할 속셈이었겠지.\n\n이 짓을 벌인 자는 아주 강력하고도 가장 교활한 마법을 다루는 자일 거다. 그런 존재감은 근처에 느껴지지 않지만, 무언가 있긴 해.\n\n저 산자락 근처의 동굴에서 의식이 진행 중이다. 그 주문을 연결하고 있는 자들을 처치하면, 수정의 속도를 늦추고 우리가 시간을 조금 벌 수 있을 거다.",
    },
    [31023] = {
        ["T"] = "비전의 역병",
        ["O"] =
        "소환을 시작할 준비가 되면 벨리고스와 대화하십시오. 그는 우리가 푸른 안식처의 수정에 있는 첨탑돌일족 마술사 군주를 처치하길 원합니다.",
        ["D"] =
        "이런 상태라 능력이 현저히 떨어지긴 했지만, 수정 내부의 마법 흐름을 들여다보려고 애썼다. 그곳에서 내 보주의 에너지 흔적은 물론, 그걸 다뤘을 법한 자의 흔적을 찾아냈지.\n\n<벨리고스 주변의 에너지가 요동치는 것이 느껴집니다.>\n\n차원문을 통해 녀석을 이곳으로 끌고 올 수 있을 거다. 준비가 되면 알려다오, $N.",
