    [31024] = {
        ["T"] = "비전의 역병",
        ["O"] =
        "푸른 안식처의 벨리고스는 우리가 검은바위 첨탑 하층 깊숙한 곳으로 가서 첨탑돌일족의 진정한 지도자인 우로크 둠하울을 소환하여 처치하고, 그의 지배 보주의 두 번째 조각을 되찾아오길 원합니다.",
        ["D"] =
        "보주의 한 조각을 되찾았으니 이제 나머지 한 조각을 추적해야 해.\n\n<벨리고스가 조각에 마법을 집중하자 무언가와 공명하기 시작합니다.>\n\n동료들을 모아라, $r. 검은바위 산으로 가서 우로크 둠하울을 처치해. 녀석이 마법의 장막 뒤에 숨어있는 게 느껴지는군. 녀석의 하수인들을 박살 내고, 녀석을 어둠 속에서 끌어내 그 권위에 도전하여 세상에서 녀석의 사악한 영향력을 완전히 지워버려.\n\n내 지배 보주의 마지막 조각을 내게 가져와라. 난 이제 다가올 일에 대비해 힘을 비축하는 데 집중하겠다.",
    },
    [31025] = {
        ["T"] = "비전의 역병",
        ["O"] =
        "푸른 안식처의 벨리고스는 오염을 억누를 마법 보호막을 구현하기 위해 몇 가지 재료가 필요합니다:\n\n- 반마법 금속인 루멘스톤은 카라잔 탑 근처의 저승바람 고개에서 찾을 수 있습니다.\n- 운고로 분화구의 바위 수호자에게서 얻을 수 있는 수호자의 돌 4개.\n- 숙련된 가죽세공인에게서 얻을 수 있는 거친 통가죽 2장.\n- 재봉사에게서 얻을 수 있는 달빛 옷감 2장.\n- 연금술사에게서 얻을 수 있는 대마법 물약 2병.",
        ["D"] =
        "<수정에서 웅웅거리는 소리가 들려오며 끔찍한 열기가 뿜어져 나옵니다. 마치 당신의 정수가 그 안으로 빨려 들어가는 것 같은 느낌이 듭니다.>\n\n시간이 얼마 남지 않았다, $n. 수많은 해결책을 고심해 본 끝에, 한 가지 방법이 있을지도 몰라... 보주는 수리할 수 없을 정도로 망가졌고, 아제로스의 어떤 장인도 그걸 고쳐낼 순 없을 거다. 하지만 그렇다고 완전히 쓸모가 없어진 건 아니지. 오우거들이 어떻게 수정을 깨웠는지 알 것 같아. 우아한 방법은 아니지만 효과는 있을 거다.\n\n내가 준비하는 동안, 넌 다시 한 번 밖으로 나가야 해. 수정으로 인해 발생한 이 비전 역병의 확산을 막을 대마법 보호막을 만들어야 한다. 일단 안정되고 나면, 이 보호막이 봉인을 영구적으로 유지시켜 줄 거야.\n\n저승바람 고개로 가라. 메디브의 탑 지하실에서 마법을 무효화시키는 희귀 금속, 루멘스톤을 찾을 수 있을 거다. 하지만 명심해라. 그곳의 터널과 동굴은 아주 위험하며 고통받는 유령과 언데드들로 우글거리니까.\n\n다음으로, 운고로 분화구로 향해라. 그곳을 배회하는 엄청난 힘을 지닌 대지의 수호자, 룬이 새겨진 골렘들의 수호자의 돌을 모아라. 그것들이 보호막의 핵이 될 것이다.\n\n그리고 보호막을 외부 환경으로부터 지켜내기 위해 숙련된 장인들의 도움이 필요하다. 거친 통가죽 두 장과 달샘의 에너지가 깃든 옷감 두 장을 구해라. 그것들을 대마법 혼합물에 푹 담가야 해.",
    },
