        ["D"] =
        "당분간은 보주를 융합하기 위해 최선을 다했지만, 내가 그걸 다루기엔 지금 힘이 너무 미약하다.\n\n수정 근처에서 보주를 들고 있어라, 내 남은 힘을 두 조각에 모두 쏟아부어 조화를 이끌어내 보겠다.\n\n이 과정에서 수정의 그 엄청난 에너지 자체가 억제의 핵심적인 역할을 할 것이다. 마법의 흐름을 붕괴시켜 스스로 무너지게 만들고, 아제로스에서 이 재앙을 몰아낼 것이다.\n\n<벨리고스가 잠시 말을 멈춥니다.>\n\n그것을 연구할 수 있었더라면 얼마나 좋았을까. 그 옛날에 내가 성공했었더라면... 어쩌면 다음 생에선 가능할지도 모르지...",
