        ["D"] =
        "수정이 안정되면서 내가 지금까지 연명해 오던 에너지가 줄어들고 있다.\n\n$N, 그 옛날 모두를 실망시켰던 내 실패가 정말 미안하구나. 내 호기심이 수많은 죽음을 부를 뻔했지. 부디 이 유품을 내 혈육에게 전해주고 내 이야기를 알려다오. 새끼 용들에게 경각심을 심어줄 수 있도록.\n\n이제 강령술사의 홀을 부러뜨리는 일만 남았다.\n\n<벨리고스가 잠시 위로 떠 올라, 저 아래 바다를 길게 응시합니다.>\n\n내 임무는 끝났다. 이제 가야 할 시간이군. 난 준비되었다.",
    },
    [31030] = {
