        ["D"] =
        "정말 잘해주었소, $N. 용의 부탁을 받아들여 마즈소릴의 대모에게 이 유품을 전해주시오. 이 비극적인 이야기는 반드시 널리 알려져야 하오.\n\n길을 잃은 기분이 들 땐, 언제든 이곳으로 돌아오시오. 큰 슬픔의 원인이었던 곳이지만, 머지않아 평온이 찾아올 테니.\n\n잘 가시오, $r.",
