    [31033] = {
        ["T"] = "불운한 장애물",
        ["O"] = "저승바람 고개에서 악마에 대해 아는 사람을 수색해야 합니다.",
        ["D"] =
        "루멘스톤은 어디에도 보이지 않지만, 악마 중 하나가 지니고 있던 서판을 발견했습니다. 자세히 살펴보니 해석할 수 없는 악마의 언어로 쓰여 있는 것 같습니다:\n\nRikk alar il xi zennrakkan lok Kirasath Raka ruk asj xi veni parn kar lok revola rukadare il Karazhan. Lok kamil buras naztheros arakalada xi daz veni. Rikk lok parn il asj xi Z gular maladath lok buras kanrethad il lok kamil. Kiel ashjrethul ante buras gul revos.\nIl kirasath Vorakem Zekulrakkas Archim il Aman Veni Kazzak.\n\n이 메시지의 의미를 해독하려면 도움이 필요할 것 같습니다. 주변 환경을 살펴보니 최근 탑의 지하실을 방문한 사람이 우리가 처음은 아니었던 모양입니다. 운이 좋다면 그들이 아직 저승바람 고개 어딘가에 있을지도 모릅니다.\n\n유령, 오우거, 그리고 이제 악마들까지 탑 주변을 포위한 상황에서, 그들은 과연 어디에 숨어있을까요?",
