        ["D"] =
        "널 도울 수는 있어, 사실이야. 하지만 세상일이 다 그렇잖아... 나도 네게서 필요한 게 있어.\n\n보면 알겠지만, 내 상태가 지금 말이 아니거든. 지하실에서 도망쳐 나오느라 내 몸의 한계를 훨씬 넘어설 정도로 무리해야만 했어.\n\n내 마력을 회복하는 걸 도와주면 널 돕도록 하지. 지속적인 마나 회복 효과가 있는 것과 그걸 씻어내릴 만한 마실 것이면 내게 기적 같은 효과를 발휘할 텐데 말이야. 네가 없는 동안 난 서판 번역을 시작할게.",
