        ["D"] =
        "악마들은 교만해. 그리고 그게 바로 녀석들의 가장 큰 약점이니 그 점을 파고들어야 해. 놈들을 기습하는 게 최선의 방법이지. 정면으로 부딪쳐서 혼란스러운 틈을 타 최대한 많은 놈을 죽여버려.\n\n놈들이 네가 찾는 그 금속도 야영지로 가져갔을 테니 분명 거기서 찾을 수 있을 거야.\n\n나도 너와 함께 가고 싶지만 몸이 아직 덜 회복되었어. 녀석들이 그 금속에 무슨 짓을 했고, 그게 내 몸이 이렇게 된 원인이라고 생각하거든. 조심해, 내가 묘사했던 것과 조금이라도 비슷한 느낌이 든다면 - 도망쳐.",
